m_config_LedgerConfig.signature:
type LedgerConfig struct {
	// Enabled 已退休（B229 §2.6）：账本变必需品，恒开。键与字段仅为
	// KnownFields 严格解析不炸存量 config 而保留，值被忽略；加载到该键时
