m_executor_Adapter.signature:
type Adapter interface {
	// Start 异步启动任务执行并立即返回。
	//
	// 参数：
	//   - ctx: 控制启动阶段的超时/取消；不代表执行生命周期（执行延续到 Stop）
	//   - req: 任务快照、计划原文与任务工作目录
	//
	// 返回：
	//   - 启动失败（如 executor 不可达）时返回错误，此时任务应标记 failed
	//
	// 注意：
	//   - 启动后 executor 侧产生的事件经 Events 通道持续送达，与返回时机无关
	Start(ctx context.Context, req StartReq) error

	// Events 返回该任务的事件流通道（Start 后可用）。
	//
	// 注意：
	//   - 通道关闭表示执行终结（Stop 或内部异常退出），manager 据此结束中介循环
	Events(taskID string) <-chan AdapterEvent

	// Send 回答提问 / 回发修改指令，对同一会话续接执行。
	//
	// 参数：
	//   - taskID: 目标任务
	//   - text: 回答原文或续接指令，必须原样透传，不得加工
	Send(ctx context.Context, taskID, text string) error

	// RespondPermission 应答 executor 的权限请求。
	//
	// 参数：
	//   - taskID: 目标任务
	//   - permID: 权限请求 id（与事件中的 PermissionID 一致；manager 的 ticket id
	//     经 taskID:permID 命名空间化，此处传裸 permID，不得传命名空间化 id）
	//   - decision: "once"（批准本次）或 "reject"（拒绝）
	//   - reason: decision 为 "reject" 时协调者给出的原因；批准时忽略，可为空。
	//     原生协议带得了消息的 adapter 应把它与裁决同帧送达模型，并实现
	//     manager 侧的 DenyReasonInBand 可选接口；带不了的忽略即可，
	//     manager 会退回带外注入（B50）
	RespondPermission(ctx context.Context, taskID, permID, decision, reason string) error

	// Stop 终止任务执行并回收 executor 侧资源，事件通道随即关闭。
	Stop(taskID string) error
}

m_executor_AdapterEvent.signature:
type AdapterEvent struct {
	Type		string	// "permission" | "question" | "progress" | "result" | "usage"
	PermissionID	string	// Type=permission 时有效（manager 按其派生 ticket id，天然幂等）
	// QuestionID 是 Type=question 时 executor 侧提问请求的**原生**稳定 id
	// （如 opencode 的 que_xxx）。manager 按其派生 ticket id 使其幂等——
	// 没有它，agentd 重启后 executor 重放同一个提问会产出第二张工单，
	// 而旧工单永远答不掉（B58）。
	//
	// 留空表示该 executor 没有原生 id（claudecode/codex/grok 的 trailer ask
	// 就是这种），manager 退回 uuid，行为与今天一致。
	QuestionID	string
	SessionID	string	// 可选：executor 会话标识，manager 落 task.ExecutorSession；空则忽略
	Text		string	// permission 描述 / question 原文 / progress 文本
	// Perm 是 Type=permission 时的结构化载荷；nil 表示 adapter 提取不出结构，
	// manager 据此 fail-closed 升级人工（看不懂的请求交给人）。
	Perm	*PermRequest
	Result	*Result	// Type=result 时有效
	// ActualModel 是 executor 报回的**实际**模型名；空=本帧没带模型信息。
	// 与 Task.Model（dispatch 的入参）是两件事，manager 落 task.ActualModel。
	ActualModel	string
	// Usage 是当前 context 占用快照；nil=本帧没带用量。
	// 语义见 proto.Usage：只描述占用不描述消耗，且绝不用 0 冒充「没有」。
	Usage	*proto.Usage
	// Spend 是这一次调用/回合**新增**的消耗；nil = 本帧不带消耗信息。
	//
	// 与 Usage 的区别：Usage 是「当前占用」的快照（后到的覆盖先到的），
	// Spend 是「新增消耗」的账目（按 Key 覆盖后**求和**）。数量级完全不同，
	// 一个帧可以两者都带，但**绝不能互相赋值**。
	Spend	*proto.SpendEntry
	// Timing 是这一段的耗时账目；nil = 本帧不带耗时信息。
	//
	// 与 Spend 并列走 Type="usage" 事件（**不新增事件类型**）：Usage/Spend/Timing
	// 是同一次模型调用结束时的三样产物，拆成两个事件之间就能插进一次 agentd
	// 重启。三者语义互不交叉，**绝不能互相赋值**。
	Timing	*proto.TimingEntry
}

