	// Await 等该 task 跑到回合终态并取回最终报文。只在 Node.Verdict 时调用。
	Await	func(ctx context.Context, target, taskID string) (message string, err error)
	// OutputPath 返回本次派发已经渲染的单一路径；只有 Node.Produces 非 nil 时读取。
