m_proto_StatusResp.signature:
type StatusResp struct {
	Version	BuildInfo	`json:"version"`
	Listen	string		`json:"listen"`

	// ListenAux 是 loopback 辅助监听地址（B85）：Listen 为单网卡 IP 时 agentd
	// 额外监听 "127.0.0.1:<同端口>"，本机 CLI 的确定性改写拨的就是它。
	// 空 = 无辅助监听（Listen 为 loopback/通配，或对端是老 agentd）。
	ListenAux	string	`json:"listen_aux,omitempty"`

	DataDir	string	`json:"data_dir"`
	// ScratchRoot 是草稿区的绝对路径（<DataDir>/scratch），控制台浮窗的临时文件
	// 落在这里。**缺席 = 这台机器不支持临时文件**（老 agentd，或目录建不出来）。
	//
	// 与 PtySupported 那种能力位的三态纪律不同：那里 nil 要按「不知道，放行」处理，
	// 而这里缺的是一个**路径**——没有路径就没法发请求，放行只会换来一次必然 400。
	ScratchRoot	string		`json:"scratch_root,omitempty"`
	StartedAt	time.Time	`json:"started_at"`
	Executors	[]string	`json:"executors"`
	DefaultExecutor	string		`json:"default_executor"`
	TaskCounts	map[string]int	`json:"task_counts"`
	Active		[]ActiveTask	`json:"active"`

	// StallTimeout 是 agentd 看门狗判定「卡住」的空闲阈值，形如 "2h0m0s"
	//（time.Duration.String()）。空串 = 对端未提供。
	//
	// 为什么要外露：wait --follow 的 --timeout 若不大于它，两个计时器同时到点时
	// 客户端的 124 会抢在 agentd 的 stalled 前面退出进程，把一次带 last_seq 和
	// idle 时长的**诊断**降级成一句「我没收到东西」——协调者拿到的信息严格更少。
	StallTimeout	string	`json:"stall_timeout,omitempty"`

	// Update 是自动更新状态。**指针 + omitempty**：老版本 agentd 不发这个字段，
	// 消费方拿到 nil 就该什么都不显示，而不是显示一个「未托管、无待命」的假状态
	Update	*UpdateStatus	`json:"update,omitempty"`

	// Proc 是本机 uid 级的进程占用与上限。指针 + omitempty：老 agentd 不发这个
	// 字段，消费方拿到 nil 应当什么都不显示，而不是显示一个「0/0」的假状态。
	Proc	*ProcUsage	`json:"proc,omitempty"`

	// PtySupported 报告本机 agentd 是否支持 PTY 终端。
	//
	// 三态，与 Update / Proc 同一纪律：
	//   缺席(nil) = 对端 agentd 太老，没上报这个字段——**不许当成 false**
	//   false     = 平台不支持（Windows：ConPTY 是另一套 API，本轮不假装支持）
	//   true      = 支持
	// 前端据此决定画真终端、画「这台机器不支持」还是画「对端版本过旧，未上报」。
	PtySupported	*bool	`json:"pty_supported,omitempty"`

	// LaunchersSupported 报告本机 agentd 是否认识启动项（CreatePtySessionReq
	// 的 env_file / init_command 两个字段）。
	//
	// **三态的处置与 PtySupported / RevealSupported 刻意相反，别照抄邻居**：
	//   缺席(nil) = 对端 agentd 太老 → **按不支持处置**（不送这两个字段、
	//               界面不展示该机的启动项）
	//   false     = 不支持
	//   true      = 支持
	//
	// 为什么反着来：那两个能力位缺席时「放行」的代价只是一次必然失败的请求，
	// 用户当场看得见；而这里放行的代价是**静默起一个没有环境变量的终端**
	// （请求 200、终端正常出现、变量悄悄不在）。未知时的保守方向由「失败可不
	// 可见」决定，不由邻居的写法决定。
	//
	// 能力位与实现同生同死：上报 true 就必须真的实现这两个字段，不允许
	// 「先上报、下一版补实现」。
	LaunchersSupported	*bool	`json:"launchers_supported,omitempty"`

	// DisciplinesSupported 报告本机 agentd 是否认识「接收下发的纪律正文」
	// （/api/tasks 的 discipline_text / discipline_version，B229）。
	//
	// 三态的处置与 PtySupported / RevealSupported 刻意相反、与 LaunchersSupported
	// 同向：缺席(nil) = 对端太老 → 按不支持处置（协调者侧拒发）；false = 不支持；
	// true = 支持。放行的代价是静默降级——请求 200、任务正常创建、纪律块悄悄
	// 变成执行机本地残留（B229 缺陷三的原样复活），所以未知时按不支持拒发。
	//
	// 能力位与实现同生同死：收文即用、正文落盘、continue/resume 消费落盘正文
	// 三件齐了才许上报 true。
	DisciplinesSupported	*bool	`json:"disciplines_supported,omitempty"`

	// RevealSupported 报告本机 agentd 是否支持「在访达中显示」（B108）。
	//
	// 三态与 PtySupported 逐字相同：
	//   缺席(nil) = 对端 agentd 太老，没上报这个字段——**不许当成 false**
	//   false     = 平台不支持（只有 macOS 有 `open -R` 这个语义）
	//   true      = 支持
	//
	// 注意：这只是**平台**支持度。真能不能揭示还要看调用方是不是从回环来的
	//（远程浏览器点了会在 agentd 那台机器的桌面上弹窗，没人看得见），那一层
	// 由端点自己判，不进能力位——它是每请求的属性，不是机器的属性。
	RevealSupported	*bool	`json:"reveal_supported,omitempty"`

	// PtySessions 是当前活着的终端会话数。指针 + omitempty，与 Proc 同一纪律：
	// nil = 对端没上报，渲染时整行不打印；0 = 确实一个都没有。
	//
	// 为什么 status 只给个数、不给每个会话占多少进程：数进程要枚举全机进程，
	// 而 status 有「不能变成慢命令」的硬纪律。进程数在 /api/footprint 里给。
	PtySessions	*int	`json:"pty_sessions,omitempty"`

	// WebEmbedded 报告本机是否编译进 Web 控制台。
	//
	// nil = 对端未上报，false = 当前二进制是 stub，true = 已嵌入。
	// 使用指针保证非 nil 的 false 不被 omitempty 省略。
	WebEmbedded	*bool	`json:"web_embedded,omitempty"`
}

m_proto_Task.signature:
type Task struct {
	ID		string	`json:"id"`
	Target		string	`json:"target"`
	RepoPath	string	`json:"repo_path"`
	HomeDir		string	`json:"home_dir,omitempty"`	// 载体派发的隔离 HOME；空串表示旧任务或普通派发。
	// Carrier 是派发时绑定的载体名（B233.5）。空=旧任务或尚未接线的派发。
	// 落盘列归实现节点；本字段先冻结 JSON 键。
	Carrier	string	`json:"carrier,omitempty"`
	// Squad 是派发时解析出的小队名快照；空=载体直派或旧任务。只在创建时写入，
	// 终态释放据此与 Carrier 一起归还小队成员政策位。
	Squad		string		`json:"squad,omitempty"`
	Branch		string		`json:"branch"`
	PlanPath	string		`json:"plan_path"`
	PlanSummary	string		`json:"plan_summary"`
	ExecutorSession	string		`json:"executor_session"`
	State		TaskState	`json:"state"`
	CreatedAt	time.Time	`json:"created_at"`
	UpdatedAt	time.Time	`json:"updated_at"`
	// Name 是任务的展示名（dispatch --name 或从 plan/prompt 派生）。
	Name	string	`json:"name"`
	// Executor 是任务选择的执行者（dispatch --executor）；空=缺省执行者（老任务兼容）。
	Executor	string	`json:"executor"`
	// Model 是任务级模型覆盖（dispatch --model）；空=executor 自身默认。
	Model	string	`json:"model"`
	// Discipline 是本任务实际注入的纪律块来源标注（如「内置:single-context」）。
	// **不落盘**：它只在派发响应里回显给协调者，agentd 重启后为空。
	//
	// 为什么要回显：配置化把纪律块从 plan 文件里拿走后，写 plan 的人再也看不见它，
	// dispatch 必须当场把「这次注入的是哪块」说出来；CLI 拿到的就是这个对象。
	Discipline	string	`json:"discipline,omitempty"`
	// DisciplineName 是派发时点名的纪律块角色名（如 review）；空=按 executor 兜底。
	// 该列后加，老任务为空——空是有意义的取值（走兜底），不回填、不编造。
	//
	// 为什么必须落盘：resumeForContinue 与 ResumeTask 只拿得到 executor 名，
	// 不落盘的话一次 continue 或一次 agentd 重启就会让点名的任务静默退回兜底块，
	// 而且首回合是对的，事后极难查。
	DisciplineName	string	`json:"discipline_name,omitempty"`
	// DisciplineVersion 是派发时命中的纪律块账本版本（B229）；未点名/临时正文为 0。
	// 老任务为空。落盘理由与 DisciplineName 同一条：不落盘，「那次用的哪一版
	// 正文」在 agentd 重启后就再也答不上来。
	DisciplineVersion	int	`json:"discipline_version,omitempty"`
	// WorkDir 是任务工作区目录。空=原地模式（工作区即 RepoPath，由 Workdir() 统一回退）。
	// 审阅命令（diff/fetch/run）与 executor 的 cwd 都从这里取值，不得直接读 RepoPath。
	WorkDir	string	`json:"work_dir"`
	// WorktreeManaged 表示 WorkDir 是 agentd 创建的 worktree，任务完成（done）时由
	// agentd 负责删除；用户自带 worktree（Worktree=false）或原地模式均不受管理。
	WorktreeManaged	bool	`json:"worktree_managed"`
	// BaseCommit 是本任务新分支的**实际起点**（40 位 sha）；空=切已存在分支
	// （没有起点这回事）或老任务（该列后加，不回填、不编造）。
	// 它回答的是「这个任务建在哪个提交上」——B35 之前这个问题无处可问。
	BaseCommit	string	`json:"base_commit"`
	// BaseAhead 是派发当时任务仓库 HEAD 领先 BaseCommit 的提交数：这些提交
	// 不在任务分支里。0 表示起点就是仓库 HEAD，或该数字当时没能算出来。
	BaseAhead	int	`json:"base_ahead"`
	// RepoDirtyCount 是派发当时任务仓库未提交改动的**总数**（含未跟踪文件）；
	// 0=干净，或本次不是 managed（--new-worktree）模式。这些改动不在新工作树
	// 里，executor 看不到它们。
	RepoDirtyCount	int	`json:"repo_dirty_count"`
	// RepoDirtyFiles 是上述改动的文件名展示串（逗号分隔，封顶 5 个，超出补
	// 「等 N 处」）；服务端截断后的展示用字段，与 PlanSummary 同形，不供程序消费
	//（要精确条数请读 RepoDirtyCount）。
	RepoDirtyFiles	string	`json:"repo_dirty_files"`
	// DoneNote 是归档时协调者留下的完成说明（handoff done --note）；空串=未留说明
	// 或该任务归档于本功能上线之前。它回答的是「这次到底做完了什么、为什么放行」——
	// 归档之后除了一个 completed 状态位，此前没有任何地方记录这件事。
	DoneNote	string	`json:"done_note"`
	// ActualModel 是 executor 报回的**实际**模型名；空=执行者还没报（回合未
	// 开始）或该任务跑在不报模型名的旧版执行者上。
	//
	// 它与 Model 是两件事：Model 是 dispatch --model 发下去的**入参**（常为空，
	// 意思是「用执行者自己的默认」），ActualModel 是执行者实际在用的那个。
	// 二者不一致时以 ActualModel 为准，界面不并列显示。
	ActualModel	string	`json:"actual_model,omitempty"`
	// Usage 是当前 context 占用；nil=还没有任何一次模型调用完成。
	Usage	*Usage	`json:"usage,omitempty"`
	// Cumulative 是任务的累计消耗；nil = 没有任何账目（或本次是列表读取，
	// 列表不填充——见 Store.ListTasks）。与 Usage 是两个口径，别混。
	Cumulative	*Cumulative	`json:"cumulative,omitempty"`
	// Timing 是任务的耗时聚合；nil = 没有任何耗时账目（或本次是列表读取，
	// 列表不填充——与 Cumulative 同一条纪律，见 Store.ListTasks）。
	Timing	*TaskTiming	`json:"timing,omitempty"`
	// Machine 是这条任务所在的机器：""=本机；否则为**本机** cfg.Targets 的键。
	//
	// 线注解，不入库（存储层不读不写这一列）：它由汇总方在响应时盖章，
	// 语义是「我从哪个 target 拉来的」。
	//
	// 为什么不复用 Target：`target` 存的是「当年派发它的那个 CLI 管这台机器叫
	// 什么」——换一台笔记本、换一份配置派发，同一台机器可以叫不同名字，它是
	// 历史记录不是路由键。透明路由与 UI 的机器筛选必须锚在本机配置上。
	Machine	string	`json:"machine"`
	// ProjectID 是任务的项目归属：读时按 repo_path 与 project_locations.path
	// 等值 join 得到（W3a §1.3），未归属为 ""。
	//
	// 线注解，不入库：tasks 表不加这一列——历史任务或已注销项目的任务应当
	// 诚实显示「未归属」，而不是一列陈旧数据说谎。
	ProjectID	string	`json:"project_id"`
}

