n_agentd_NewPreviewOpenService.signature:
// NewPreviewOpenService constructs the local open boundary. A nil launcher
// selects the platform launcher; tests should inject a fake launcher.
func NewPreviewOpenService(owner *workspace.PreviewOwner, mirror *PreviewMirror, pool *targetclient.Pool,
	launcher PreviewLauncher, log *slog.Logger) *PreviewOpenService {
	if log == nil {
		log = slog.Default()
	}
	if launcher == nil {
		launcher = newPreviewOSLauncher(log)
	}
	service := &PreviewOpenService{
		owner:	owner, mirror: mirror, pool: pool, launcher: launcher, log: log,
		processes:	make(map[string]*previewProcess),
	}
	hubs := make([]*workspace.PreviewHub, 0, 2)
	if owner != nil && owner.Hub() != nil {
		hubs = append(hubs, owner.Hub())
	}
	if mirror != nil && mirror.hub != nil && (owner == nil || mirror.hub != owner.Hub()) {

		hubs = append(hubs, mirror.hub)
	}
	for _, hub := range hubs {
		var events <-chan proto.PreviewEvent
		var cancel func()
		events, cancel = hub.Subscribe()
		service.eventCancels = append(service.eventCancels, cancel)
		service.eventWG.Add(1)
		go service.watchOwnerEvents(events)
	}
	return service
}

n_agentd_NewPreviewProxy.signature:
// NewPreviewProxy binds a random loopback port and creates a private capability nonce.
// The nonce is used as the SOCKS RFC1929 password and is kept for the launcher boundary;
// it is never logged.
func NewPreviewProxy(ctx context.Context, sessionID string, via []string, dial PreviewRawDial, log *slog.Logger) (*PreviewProxy, error) {
	if sessionID == "" {
		return nil, errors.New("preview session ID 不能为空")
	}
	if dial == nil {
		return nil, errors.New("preview raw dial 未配置")
	}
	allow, err := ParsePreviewAllowlist(via)
	if err != nil {
		return nil, fmt.Errorf("解析 preview allowlist: %w", err)
	}
	listener, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return nil, fmt.Errorf("绑定 preview SOCKS 回环端口: %w", err)
	}
	nonce := make([]byte, 32)
	if _, err := rand.Read(nonce); err != nil {
		_ = listener.Close()
		return nil, fmt.Errorf("生成 preview proxy nonce: %w", err)
	}
	if log == nil {
		log = slog.Default()
	}
	proxy := &PreviewProxy{sessionID: sessionID, listener: listener, allowlist: allow, dial: dial, nonce: nonce, log: log}
	_ = ctx
	proxy.log.Info("preview SOCKS 代理创建成功", "operation", "proxy_create", "session", sessionID, "addr", listener.Addr().String())
	return proxy, nil
}

