n_agentd_ParsePreviewAllowlist.signature:
// ParsePreviewAllowlist accepts only IP, CIDR, or normalized domain entries.
// Empty input still permits the three loopback spellings and localhost.
func ParsePreviewAllowlist(via []string) (PreviewAllowlist, error) {
	if err := workspace.ValidatePreviewViaSyntax(via); err != nil {
		return PreviewAllowlist{}, err
	}
	allow := PreviewAllowlist{loopback: true, domains: make(map[string]struct{})}
	for _, raw := range via {
		value := strings.ToLower(strings.TrimSuffix(strings.TrimSpace(raw), "."))
		if ip := net.ParseIP(value); ip != nil {
			bits := 128
			if ip.To4() != nil {
				bits = 32
				ip = ip.To4()
			}
			allow.networks = append(allow.networks, &net.IPNet{IP: ip, Mask: net.CIDRMask(bits, bits)})
			continue
		}
		if _, network, err := net.ParseCIDR(value); err == nil {
			allow.networks = append(allow.networks, network)
			continue
		}
		allow.domains[value] = struct{}{}
	}
	return allow, nil
}

n_agentd_PreviewAllowlist_Allows.signature:
// Allows reports whether a hostname or IP may be connected by this session.
// Hostnames are matched exactly; no wildcard or implicit subdomain expansion is allowed.
func (a PreviewAllowlist) Allows(host string) bool {
	host = strings.ToLower(strings.TrimSuffix(strings.TrimSpace(host), "."))
	if host == "localhost" {
		return a.loopback
	}
	if ip := net.ParseIP(host); ip != nil {
		if a.loopback && ip.IsLoopback() {
			return true
		}
		for _, network := range a.networks {
			if network.Contains(ip) {
				return true
			}
		}
		return false
	}
	_, ok := a.domains[host]
	return ok
}

n_agentd_PreviewMirror_ListAll.signature:
// ListAll refreshes list-before-WS data and returns the current owner projection.
// Individual target failures are encoded in Machines and do not erase successful data.
func (m *PreviewMirror) ListAll(ctx context.Context) (*proto.PreviewListResp, error) {
	m.refreshAll(ctx)
	m.mu.RLock()
	defer m.mu.RUnlock()
	sessions := make([]proto.PreviewSession, 0, len(m.sessions))
	for _, session := range m.sessions {
		sessions = append(sessions, session)
	}
	sort.Slice(sessions, func(i, j int) bool {
		if sessions[i].Machine != sessions[j].Machine {
			return sessions[i].Machine < sessions[j].Machine
		}
		return sessions[i].ID < sessions[j].ID
	})
	machines := make([]proto.MachineStatus, 0, len(m.machines))
	for _, status := range m.machines {
		machines = append(machines, status)
	}
	sort.Slice(machines, func(i, j int) bool { return machines[i].Name < machines[j].Name })
	return &proto.PreviewListResp{Sessions: sessions, Machines: machines}, nil
}

