func (m *PreviewMirror) Resolve(id, machine string) (proto.PreviewSession, bool) {
	m.mu.RLock()
	defer m.mu.RUnlock()
	session, ok := m.sessions[previewSessionKey(machine, id)]
	return session, ok
}

n_agentd_PreviewMirror_Run.signature:
// Run performs an initial list-before-WS projection and supervises target streams.
func (m *PreviewMirror) Run(ctx context.Context) {
	m.mu.Lock()
	if m.started || m.stopped {
		m.mu.Unlock()
		return
	}
	m.started = true
	runCtx, runCancel := context.WithCancel(ctx)
	m.runCancel = runCancel
	m.mu.Unlock()
	m.refreshAll(runCtx)
	m.ensureLoops(runCtx)
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-runCtx.Done():
			m.Stop()
			return
		case <-m.stopDone:
			return
		case <-ticker.C:
			m.refreshAll(runCtx)
			m.ensureLoops(runCtx)
		}
	}
}

n_agentd_PreviewMirror_Stop.signature:
// Stop cancels every remote supervisor and waits for all network goroutines.
func (m *PreviewMirror) Stop() {
	m.stopOnce.Do(func() {
		m.mu.Lock()
		m.stopped = true
		if m.runCancel != nil {
			m.runCancel()
		}
		for name, cancel := range m.cancels {
			cancel()
			delete(m.cancels, name)
		}
		m.mu.Unlock()
		m.wg.Wait()
		close(m.stopDone)
		m.log.Info("preview mirror 已停止", "operation", "preview_mirror_stop")
	})
}

n_agentd_PreviewMirror_applyRemoteEvent.signature:
func (m *PreviewMirror) applyRemoteEvent(name string, event proto.PreviewEvent) {
	if event.Type != proto.PreviewEventCreated && event.Type != proto.PreviewEventClosed {
		m.log.Warn("preview mirror 忽略未知事件", "machine", name, "event", event.Type, "session", event.Session.ID)
		return
	}
	event.Machine = name
	event.Session.Machine = name
	key := previewSessionKey(name, event.Session.ID)
	m.mu.Lock()
	if event.Type == proto.PreviewEventClosed {
		delete(m.sessions, key)
	} else {
		m.sessions[key] = event.Session
	}
	m.mu.Unlock()
	m.hub.Publish(event)
	m.log.Info("preview mirror 事件投影成功", "machine", name, "event", event.Type, "session", event.Session.ID)
}

n_agentd_PreviewMirror_ensureLoops.signature:
func (m *PreviewMirror) ensureLoops(parent context.Context) {
	if m.pool == nil {
		return
	}
	m.mu.RLock()
	stopped := m.stopped
	m.mu.RUnlock()
	if stopped {
		return
	}
	for _, name := range m.pool.Names() {
		if m.isSelfTarget != nil && m.isSelfTarget(name) {
			continue
		}
		m.mu.Lock()
		if m.stopped {
			m.mu.Unlock()
			return
		}
		if _, exists := m.cancels[name]; exists {
			m.mu.Unlock()
			continue
		}
		ctx, cancel := context.WithCancel(parent)
		m.cancels[name] = cancel
		m.wg.Add(1)
		m.mu.Unlock()
		go m.runTarget(ctx, name)
	}
}

n_agentd_PreviewMirror_publishClosedEven.signature:
func (m *PreviewMirror) publishClosedEvents(events []proto.PreviewEvent, reason string) {
	for _, event := range events {
		m.hub.Publish(event)
		m.log.Info(reason, "operation", "preview_closed", "machine", event.Machine, "session", event.Session.ID)
	}
}

n_agentd_PreviewMirror_refreshAll.signature:
func (m *PreviewMirror) refreshAll(ctx context.Context) {
	m.mu.RLock()
	stopped := m.stopped
	m.mu.RUnlock()
	if stopped {
		return
	}
	now := time.Now().UTC()
	nextSessions := make(map[string]proto.PreviewSession)
	nextMachines := make(map[string]proto.MachineStatus)
	listedMachines := make(map[string]bool)
	if m.owner != nil {
		resp, err := m.owner.List(ctx)
		status := proto.MachineStatus{Name: "", FetchedAt: now, Ok: err == nil}
		if err != nil {
			status.Error = err.Error()
			m.log.Warn("preview 本机列表失败", "machine", "", "cause", err)
		} else {
			listedMachines[""] = true
			for _, session := range resp.Sessions {
				session.Machine = ""
				nextSessions[previewSessionKey("", session.ID)] = session
			}
		}
		nextMachines[""] = status
	}
	if m.pool != nil {
		for _, name := range m.pool.Names() {
			if m.isSelfTarget != nil && m.isSelfTarget(name) {
				continue
			}
			status := proto.MachineStatus{Name: name, FetchedAt: now}
			c, err := m.pool.For(name)
			if err == nil {
				resp, callErr := c.ListPreviews(ctx)
				err = callErr
				if err == nil {
					status.Ok = true
					listedMachines[name] = true
					for _, session := range resp.Sessions {
						session.Machine = name
						nextSessions[previewSessionKey(name, session.ID)] = session
					}
				}
			}
			if err != nil {
				status.Error = err.Error()
				m.log.Warn("preview 远端列表失败", "machine", name, "cause", err)
			}
			nextMachines[name] = status
		}
	}
	m.mu.Lock()
	for key, session := range m.sessions {
		if !listedMachines[session.Machine] {
			nextSessions[key] = session
		}
	}
	closed := previewClosedEvents(m.sessions, nextSessions)
	m.sessions, m.machines = nextSessions, nextMachines
	m.mu.Unlock()
	m.publishClosedEvents(closed, "preview mirror 列表收敛关闭事件")
	m.log.Info("preview mirror 列表刷新成功", "sessions", len(nextSessions), "machines", len(nextMachines))
}

n_agentd_PreviewMirror_refreshTarget.signature:
func (m *PreviewMirror) refreshTarget(ctx context.Context, name string, c interface {
	ListPreviews(context.Context) (*proto.PreviewListResp, error)
}) error {
	resp, err := c.ListPreviews(ctx)
	if err != nil {
		m.setMachineFailure(name, err)
		return err
	}
	listed := make(map[string]struct{}, len(resp.Sessions))
	for _, session := range resp.Sessions {
		listed[session.ID] = struct{}{}
	}
	m.mu.Lock()
	closed := make([]proto.PreviewEvent, 0)
	for key, session := range m.sessions {
		if session.Machine == name {
			if _, ok := listed[session.ID]; !ok {
				closed = append(closed, proto.PreviewEvent{Type: proto.PreviewEventClosed, Session: session, Machine: name})
			}
			delete(m.sessions, key)
		}
	}
	for _, session := range resp.Sessions {
		session.Machine = name
		m.sessions[previewSessionKey(name, session.ID)] = session
	}
	m.machines[name] = proto.MachineStatus{Name: name, Ok: true, FetchedAt: time.Now().UTC()}
	m.mu.Unlock()
	m.publishClosedEvents(closed, "preview mirror 目标列表收敛关闭事件")
	return nil
}

n_agentd_PreviewMirror_runTarget.signature:
func (m *PreviewMirror) runTarget(ctx context.Context, name string) {
	defer m.wg.Done()
	backoff := 300 * time.Millisecond
	for {
		if ctx.Err() != nil {
			return
		}
		c, err := m.pool.For(name)
		if err == nil {

			err = m.refreshTarget(ctx, name, c)
			if err == nil {
				err = c.StreamPreviewEventsOnce(ctx, func(event proto.PreviewEvent) error {
					m.applyRemoteEvent(name, event)
					return nil
				})
			}
		}
		if err != nil && ctx.Err() == nil {
			m.log.Warn("preview mirror 远端流失败", "machine", name, "cause", err)
		}
		if !waitPreviewBackoff(ctx, backoff) {
			return
		}
		if backoff < previewMirrorBackoffMax {
			backoff *= 2
			if backoff > previewMirrorBackoffMax {
				backoff = previewMirrorBackoffMax
			}
		}
	}
}

n_agentd_PreviewMirror_setMachineFailure.signature:
func (m *PreviewMirror) setMachineFailure(name string, err error) {
	m.mu.Lock()
	m.machines[name] = proto.MachineStatus{Name: name, FetchedAt: time.Now().UTC(), Error: err.Error()}
	m.mu.Unlock()
}

n_agentd_PreviewOpenService_OpenPreview.signature:
// OpenPreview opens or focuses one session on this desktop. machine selects a
// mirrored owner; an empty machine selects the local owner. A successful call
// returns Opened=true only after the browser process has started or was focused.
func (o *PreviewOpenService) OpenPreview(ctx context.Context, id, machine string) (*proto.PreviewOpenResp, error) {
	resp := &proto.PreviewOpenResp{Opened: false}
	if strings.TrimSpace(id) == "" {
		return resp, errors.New("preview open: session id 不能为空")
	}
	key := previewSessionKey(machine, id)

	o.mu.Lock()
	defer o.mu.Unlock()
	if o.stopped {
		return resp, errors.New("preview open service 已停止")
	}
	if process := o.processes[key]; process != nil {
		if err := o.launcher.Focus(ctx, process.browser.PID); err != nil {
			o.log.Warn("聚焦已有 preview 浏览器失败", "operation", "preview_focus", "session", id, "machine", machine, "pid", process.browser.PID, "cause", err)
			return resp, fmt.Errorf("聚焦 preview 浏览器: %w", err)
		}
		if machine == "" {
			if err := o.owner.Touch(ctx, id, o.owner.Now()); err != nil {
				o.log.Warn("聚焦后续命本机 preview 失败", "operation", "preview_touch", "session", id, "machine", machine, "cause", err)
				return resp, fmt.Errorf("续命 preview 会话: %w", err)
			}
		}
		o.log.Info("已有 preview 浏览器聚焦成功", "operation", "preview_focus", "session", id, "machine", machine, "pid", process.browser.PID)
		resp.Opened = true
		return resp, nil
	}

	session, err := o.resolveSession(ctx, id, machine)
	if err != nil {
		o.log.Warn("解析待打开 preview 会话失败", "operation", "preview_open", "session", id, "machine", machine, "cause", err)
		return resp, err
	}

	profile, err := os.MkdirTemp("", "handoff-preview-"+previewSafeName(id)+"-")
	if err != nil {
		o.log.Error("创建 preview 独立 profile 失败", "operation", "preview_open", "session", id, "machine", machine, "cause", err)
		return resp, fmt.Errorf("创建 preview profile: %w", err)
	}
	cleanupProfile := func() { _ = os.RemoveAll(profile) }
	proxy, err := NewPreviewProxy(ctx, id, session.Via, o.rawDial(machine, session), o.log)
	if err != nil {
		cleanupProfile()
		o.log.Warn("创建 preview SOCKS 失败", "operation", "preview_open", "session", id, "machine", machine, "cause", err)
		return resp, err
	}
	cleanupProxy := func() {
		if err := proxy.Close(); err != nil {
			o.log.Warn("清理 preview SOCKS 失败", "operation", "preview_cleanup", "session", id, "machine", machine, "cause", err)
		}
	}
	pacPath := filepath.Join(profile, "preview.pac")
	proxyNonce := hex.EncodeToString(proxy.Nonce())
	proxyURL := previewProxyURL(proxy.Addr().String(), proxyNonce)
	pac, err := RenderPreviewPAC(proxyURL, proxy.allowlist)
	if err == nil {
		err = os.WriteFile(pacPath, pac, 0o600)
	}
	if err != nil {
		cleanupProxy()
		cleanupProfile()
		o.log.Warn("写入 preview PAC 失败", "operation", "preview_open", "session", id, "machine", machine, "cause", err)
		return resp, fmt.Errorf("写入 preview PAC: %w", err)
	}
	go func() {
		if err := proxy.Serve(context.Background()); err != nil {
			o.log.Warn("preview SOCKS 服务结束并带错误", "operation", "preview_proxy", "session", id, "machine", machine, "cause", err)
		}
	}()

	executable, err := o.launcher.FindExecutable(ctx)
	if err != nil {
		cleanupProxy()
		cleanupProfile()
		o.log.Warn("未找到 preview 浏览器可执行文件", "operation", "preview_open", "session", id, "machine", machine, "cause", err)
		return resp, fmt.Errorf("查找 preview 浏览器: %w", err)
	}
	spec := PreviewLaunchSpec{
		SessionID:		id,
		EntryURL:		session.EntryURL,
		PACPath:		pacPath,
		ProxyServer:		proxy.Addr().String(),
		ProxyNonce:		proxyNonce,
		ProxyBypassList:	"<-loopback>",
		UserDataDir:		profile,
	}
	o.log.Info("preview 浏览器启动开始", "operation", "preview_open", "session", id, "machine", machine, "executable", executable, "entry_url", session.EntryURL, "proxy", spec.ProxyServer)
	browser, err := o.launcher.Start(ctx, executable, spec)
	if err != nil {
		cleanupProxy()
		cleanupProfile()
		o.log.Warn("preview 浏览器启动失败", "operation", "preview_open", "session", id, "machine", machine, "cause", err)
		return resp, fmt.Errorf("启动 preview 浏览器: %w", err)
	}
	process := &previewProcess{proxy: proxy, pacPath: pacPath, userDataDir: profile, browser: browser, exitDone: make(chan struct{})}
	o.processes[key] = process
	go o.watchProcess(key, process)
	if machine == "" {
		if err := o.owner.Touch(ctx, id, o.owner.Now()); err != nil {
			delete(o.processes, key)
			if cleanupErr := o.stopAndCleanupProcess(ctx, id, machine, process); cleanupErr != nil {
				o.log.Warn("preview 浏览器启动后续命失败且本地回收不完整", "operation", "preview_touch_cleanup", "session", id, "machine", machine, "pid", browser.PID, "cause", cleanupErr)
			}
			o.log.Warn("preview 浏览器启动后续命失败", "operation", "preview_touch", "session", id, "machine", machine, "pid", browser.PID, "cause", err)
			return resp, fmt.Errorf("续命 preview 会话: %w", err)
		}
	}
	o.log.Info("preview 浏览器启动成功", "operation", "preview_open", "session", id, "machine", machine, "pid", browser.PID)
	resp.Opened = true
	return resp, nil
}

n_agentd_PreviewOpenService_Stop.signature:
// Stop stops all local browser/proxy resources. It does not close owner
// sessions, because closing the desktop window must leave the session listed
// until explicit owner close or idle TTL expiry.
func (o *PreviewOpenService) Stop(ctx context.Context) error {
	o.mu.Lock()
	if o.stopped {
		o.mu.Unlock()
		return nil
	}
	o.stopped = true
	processes := make([]*previewProcess, 0, len(o.processes))
	for _, process := range o.processes {
		processes = append(processes, process)
	}
	o.processes = make(map[string]*previewProcess)
	o.mu.Unlock()

	stopErr := o.launcher.Stop(ctx)
	if stopErr != nil {
		o.log.Warn("停止 preview 浏览器失败", "operation", "preview_stop", "cause", stopErr)
	}
	for _, cancel := range o.eventCancels {
		cancel()
	}
	for _, process := range processes {
		if err := waitPreviewProcess(ctx, process); err != nil {
			stopErr = errors.Join(stopErr, err)
			o.log.Warn("等待 preview 浏览器收尾失败", "operation", "preview_stop", "cause", err)
		}
	}
	o.eventWG.Wait()
	o.cleanupWG.Wait()
	for _, process := range processes {
		o.cleanupProcess("", "", process)
	}
	o.log.Info("preview 本地资源已停止", "operation", "preview_stop", "processes", len(processes))
	return stopErr
}

n_agentd_PreviewOpenService_cleanupProce.signature:
func (o *PreviewOpenService) cleanupProcess(sessionID, machine string, process *previewProcess) {
	process.cleanupOnce.Do(func() {
		if err := process.proxy.Close(); err != nil {
			o.log.Warn("回收 preview SOCKS 失败", "operation", "preview_cleanup", "session", sessionID, "machine", machine, "cause", err)
		}
		if err := os.RemoveAll(process.userDataDir); err != nil {
			o.log.Warn("回收 preview profile 失败", "operation", "preview_cleanup", "session", sessionID, "machine", machine, "cause", err)
		}
	})
}

n_agentd_PreviewOpenService_rawDial.signature:
func (o *PreviewOpenService) rawDial(machine string, session proto.PreviewSession) PreviewRawDial {
	parsed, err := url.Parse(session.EntryURL)
	addr := ""
	if err == nil && parsed.Hostname() != "" && parsed.Port() != "" {
		addr = net.JoinHostPort(parsed.Hostname(), parsed.Port())
	}
	return func(ctx context.Context, network, destination string) (net.Conn, error) {
		if addr == "" {
			return nil, fmt.Errorf("preview entry_url 无有效端口: %q", session.EntryURL)
		}
		if machine != "" {
			if o.pool == nil {
				return nil, errors.New("preview target pool 未配置")
			}
			return o.pool.DialContext(ctx, machine, network, destination)
		}
		return (&net.Dialer{}).DialContext(ctx, network, destination)
	}
}

n_agentd_PreviewOpenService_resolveSessi.signature:
func (o *PreviewOpenService) resolveSession(ctx context.Context, id, machine string) (proto.PreviewSession, error) {
	if machine != "" {
		if o.mirror == nil {
			return proto.PreviewSession{}, errors.New("preview mirror 未配置")
		}
		session, ok := o.mirror.Resolve(id, machine)
		if !ok {
			return proto.PreviewSession{}, fmt.Errorf("preview 会话 %s machine=%s: %w", id, machine, store.ErrNotFound)
		}
		return session, nil
	}
	if o.owner == nil {
		return proto.PreviewSession{}, errors.New("preview owner 未配置")
	}
	row, err := o.owner.Get(id)
	if err != nil {
		return proto.PreviewSession{}, err
	}
	if row.ClosedAt != nil || !row.LastActiveAt.Add(time.Duration(row.Session.TTLSeconds)*time.Second).After(o.owner.Now().UTC()) {
		return proto.PreviewSession{}, fmt.Errorf("preview 会话 %s: %w", id, store.ErrNotFound)
	}
	return row.Session, nil
}

n_agentd_PreviewOpenService_stopAndClean.signature:
func (o *PreviewOpenService) stopAndCleanupProcess(ctx context.Context, sessionID, machine string, process *previewProcess) error {
	if ctx == nil {
		ctx = context.TODO()
	}
	stopCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), previewProcessStopTimeout)
	defer cancel()
	var stopErr error
	if err := o.launcher.StopPID(stopCtx, process.browser.PID); err != nil {
		stopErr = fmt.Errorf("停止 preview 浏览器进程组: %w", err)
		o.log.Warn("停止 preview 浏览器进程组失败", "operation", "preview_stop_pid", "session", sessionID, "machine", machine, "pid", process.browser.PID, "cause", err)
	}
	if err := waitPreviewProcess(stopCtx, process); err != nil {
		o.log.Warn("等待 preview 浏览器退出失败，保留本地资源", "operation", "preview_stop_pid", "session", sessionID, "machine", machine, "pid", process.browser.PID, "cause", err)
		return errors.Join(stopErr, err)
	}
	o.cleanupProcess(sessionID, machine, process)
	return stopErr
}

n_agentd_PreviewOpenService_watchOwnerEv.signature:
func (o *PreviewOpenService) watchOwnerEvents(events <-chan proto.PreviewEvent) {
	defer o.eventWG.Done()
	for event := range events {
		if event.Type != proto.PreviewEventClosed {
			continue
		}
		machine := event.Machine
		key := previewSessionKey(machine, event.Session.ID)
		o.mu.Lock()
		process := o.processes[key]
		if process != nil {
			delete(o.processes, key)
		}
		o.mu.Unlock()
		if process != nil {
			o.cleanupWG.Add(1)
			go func(event proto.PreviewEvent, machine string, process *previewProcess) {
				defer o.cleanupWG.Done()
				if err := o.stopAndCleanupProcess(context.TODO(), event.Session.ID, machine, process); err != nil {
					o.log.Warn("owner 关闭后回收本地 preview 资源不完整", "operation", "preview_owner_close", "session", event.Session.ID, "machine", machine, "pid", process.browser.PID, "cause", err)
					return
				}
				o.log.Info("owner 关闭后回收本地 preview 资源", "operation", "preview_owner_close", "session", event.Session.ID, "machine", machine, "pid", process.browser.PID)
			}(event, machine, process)
		}
	}
}

n_agentd_PreviewOpenService_watchProcess.signature:
func (o *PreviewOpenService) watchProcess(key string, process *previewProcess) {
	if process.browser.Done == nil {
		close(process.exitDone)
		return
	}
	err := <-process.browser.Done
	close(process.exitDone)
	o.mu.Lock()
	if o.processes[key] == process {
		delete(o.processes, key)
	}
	o.mu.Unlock()
	o.cleanupProcess("", "", process)
	if err != nil {
		o.log.Warn("preview 浏览器退出并带错误", "operation", "preview_process_exit", "pid", process.browser.PID, "cause", err)
		return
	}
	o.log.Info("preview 浏览器退出，已回收本地资源", "operation", "preview_process_exit", "pid", process.browser.PID)
}

n_agentd_PreviewProxy_Close.signature:
// Close closes the listener; active connections finish through their request context.
func (p *PreviewProxy) Close() error {
	var err error
	p.closeOnce.Do(func() {
		err = p.listener.Close()
		p.log.Info("preview SOCKS 代理已关闭", "operation", "proxy_close", "session", p.sessionID)
	})
	return err
}

n_agentd_PreviewProxy_Serve.signature:
// Serve accepts SOCKS5 requests until ctx cancellation or Close.
func (p *PreviewProxy) Serve(ctx context.Context) error {
	closed := make(chan struct{})
	go func() {
		select {
		case <-ctx.Done():
			_ = p.Close()
		case <-closed:
		}
	}()
	defer close(closed)
	for {
		conn, err := p.listener.Accept()
		if err != nil {
			if ctx.Err() != nil || errors.Is(err, net.ErrClosed) {
				return nil
			}
			return fmt.Errorf("接受 preview SOCKS 连接: %w", err)
		}
		go p.handle(ctx, conn)
	}
}

n_agentd_PreviewProxy_handle.signature:
func (p *PreviewProxy) handle(ctx context.Context, conn net.Conn) {
	defer conn.Close()
	if err := p.socksHandshake(conn); err != nil {
		p.log.Warn("preview SOCKS 握手失败", "operation", "socks_handshake", "session", p.sessionID, "cause", err)
		return
	}
	host, port, err := readSOCKSRequest(conn)
	if err != nil {
		p.log.Warn("preview SOCKS 请求解析失败", "operation", "socks_request", "session", p.sessionID, "cause", err)
		return
	}
	addr := net.JoinHostPort(host, fmt.Sprint(port))
	if !p.allowlist.Allows(host) {
		_ = writeSOCKSReply(conn, 0x02)
		p.log.Warn("preview SOCKS 目标被 allowlist 拒绝", "operation", "socks_connect", "session", p.sessionID, "addr", addr)
		return
	}
	p.log.Info("preview raw upstream 拨号开始", "operation", "socks_connect", "session", p.sessionID, "addr", addr)
	dialCtx, cancel := context.WithTimeout(ctx, 10*time.Second)
	upstream, err := p.dial(dialCtx, "tcp", addr)
	cancel()
	if err != nil {
		_ = writeSOCKSReply(conn, 0x05)
		p.log.Warn("preview raw upstream 拨号失败", "operation", "socks_connect", "session", p.sessionID, "addr", addr, "cause", err)
		return
	}
	defer upstream.Close()
	if err := writeSOCKSReply(conn, 0x00); err != nil {
		p.log.Warn("preview SOCKS 成功响应失败", "operation", "socks_connect", "session", p.sessionID, "addr", addr, "cause", err)
		return
	}
	p.log.Info("preview raw upstream 拨号成功", "operation", "socks_connect", "session", p.sessionID, "addr", addr)
	pipeSOCKS(conn, upstream)
}

n_agentd_PreviewProxy_socksHandshake.signature:
func (p *PreviewProxy) socksHandshake(conn net.Conn) error {
	var header [2]byte
	if _, err := io.ReadFull(conn, header[:]); err != nil {
		return err
	}
	if header[0] != 5 {
		return fmt.Errorf("SOCKS version=%d", header[0])
	}
	methods := make([]byte, int(header[1]))
	if _, err := io.ReadFull(conn, methods); err != nil {
		return err
	}
	for _, method := range methods {
		if method == 2 {
			if _, err := conn.Write([]byte{5, 2}); err != nil {
				return err
			}
			return p.socksUserPass(conn)
		}
	}
	_, err := conn.Write([]byte{5, 0xff})
	if err != nil {
		return err
	}
	return errors.New("不支持 SOCKS 认证方法：preview 必须使用 nonce 认证")
}

n_agentd_PreviewProxy_socksUserPass.signature:
func (p *PreviewProxy) socksUserPass(conn net.Conn) error {
	var header [2]byte
	if _, err := io.ReadFull(conn, header[:]); err != nil {
		return err
	}
	if header[0] != 1 {
		return fmt.Errorf("SOCKS 用户名密码版本=%d", header[0])
	}
	username := make([]byte, int(header[1]))
	if _, err := io.ReadFull(conn, username); err != nil {
		return err
	}
	var passwordLength [1]byte
	if _, err := io.ReadFull(conn, passwordLength[:]); err != nil {
		return err
	}
	password := make([]byte, int(passwordLength[0]))
	if _, err := io.ReadFull(conn, password); err != nil {
		return err
	}
	expectedUser := []byte(previewProxyUsername)
	expectedPassword := []byte(hex.EncodeToString(p.nonce))
	valid := len(username) == len(expectedUser) && subtle.ConstantTimeCompare(username, expectedUser) == 1 &&
		len(password) == len(expectedPassword) && subtle.ConstantTimeCompare(password, expectedPassword) == 1
	if !valid {
		_, _ = conn.Write([]byte{1, 1})
		return errors.New("preview SOCKS nonce 认证失败")
	}
	_, err := conn.Write([]byte{1, 0})
	return err
}

