// 注意：该入口由显式停止路径调用，不挂在信号关停或进程内 Trigger（包括升级换版）上；
// 崩溃、OOM 与升级重启都必须让 ptyhost 留存。
func (s *Server) ShutdownPtySessions(ctx context.Context)	{ s.shutdownPtySessions(ctx) }

n_agentd_Server_StartAutomation.signature:
// StartAutomation 启动 agentd 生命周期内唯一的自动化循环；依赖未装配时只记录可行动告警。
func (s *Server) StartAutomation(ctx context.Context) {
	if s.scheduling == nil || s.keystone == nil || s.autoLedger == nil {
		s.log.Warn("自动化循环未启动：依赖尚未装配",
			"has_scheduling", s.scheduling != nil,
			"has_keystone", s.keystone != nil, "has_ledger", s.autoLedger != nil)
		return
	}
	s.automationStartOnce.Do(func() {
		s.log.Info("自动化清队与事件唤醒循环启动",
			"poll", automationPollInterval, "queue_kinds", scheduling.QueueKinds)
		go s.automationLoop(ctx)
	})
}

n_agentd_Server_StartPreviewServices.signature:
// StartPreviewServices restores persisted path previews and starts owner lifecycle work.
func (s *Server) StartPreviewServices(ctx context.Context) error {
	if s.previewOwner != nil {
		if err := s.previewOwner.Restore(ctx); err != nil {
			return err
		}
	}
	if s.previewMirror != nil {
		go s.previewMirror.Run(ctx)
	}
	if s.previewOwner == nil && s.previewMirror == nil {
		s.log.Info("preview owner 未配置，跳过启动", "operation", "preview_start")
	}
	return nil
}

n_agentd_Server_StopPreviewServices.signature:
// StopPreviewServices stops the local opener before owner persistence closes.
func (s *Server) StopPreviewServices(ctx context.Context) error {
	var stopErr error
	if s.previewOpener != nil {
		if err := s.previewOpener.Stop(ctx); err != nil {
			stopErr = errors.Join(stopErr, err)
			s.log.Warn("preview opener 收口失败，继续关闭其余服务", "operation", "preview_stop", "cause", err)
		}
	}
	if s.previewMirror != nil {
		s.previewMirror.Stop()
	}
	if s.previewOwner != nil {
		if err := s.previewOwner.Stop(ctx); err != nil {
			stopErr = errors.Join(stopErr, err)
		}
	}
	return stopErr
}

n_agentd_Server_abortMachineUpgrade.signature:
// abortMachineUpgrade 放弃一个刚抢到、但还没真正开跑的槽位（前置校验没过）。
// 恢复成「本进程没发起过」，不留一条没有内容的终态。
func (s *Server) abortMachineUpgrade(name string) {
	s.upgradeMu.Lock()
	defer s.upgradeMu.Unlock()
	delete(s.machineUpgrades, name)
}

n_agentd_Server_acceptsCurrentWorkflowAt.signature:
// acceptsCurrentWorkflowAttempt 是 task_mirrored 唤醒前的身份闸。
// 不匹配的事件仍会进入 automationSeen，保留审计但不会唤醒新尝试；
// 缺失与空值使用指针区分，避免旧 envelope 被零值误判为有效身份。source
// task/target 来自账本列，必须和事件所属卡的当前派发快照一致；source_seq
// 不参与身份比较。
func (s *Server) acceptsCurrentWorkflowAttempt(ev proto.LedgerEvent) (bool, error) {
	envelope, err := decodeMirroredTaskEnvelope(ev)
	if err != nil {
		s.log.Error("task_mirrored envelope 无法进入当前 attempt 闸", "card", ev.CardID,
			"seq", ev.Seq, "type", ev.Type, "cause", err)
		return false, fmt.Errorf("卡 %s task_mirrored seq=%d type=%s: %w", ev.CardID, ev.Seq, ev.Type, err)
	}
	if envelope.Node == nil || *envelope.Node == "" || envelope.Attempt == nil || *envelope.Attempt == "" {
		s.log.Info("task_mirrored 因缺失或空 workflow 身份跳过", "card", ev.CardID,
			"seq", ev.Seq, "type", ev.Type, "node_present", envelope.Node != nil,
			"attempt_present", envelope.Attempt != nil, "task_type", envelope.TaskType)
		return false, nil
	}
	current, found, err := s.currentWorkflowAttempt(ev.CardID, *envelope.Node)
	if err != nil {
		return false, err
	}
	if !found || current.TaskID != current.Attempt || current.Attempt != *envelope.Attempt ||
		ev.SourceTask != current.Attempt || ev.SourceTarget != current.Target {
		s.log.Info("task_mirrored 因 source identity 不匹配跳过", "card", ev.CardID,
			"seq", ev.Seq, "type", ev.Type, "node", *envelope.Node,
			"attempt", *envelope.Attempt, "current_attempt", current.Attempt,
			"source_task", ev.SourceTask, "source_target", ev.SourceTarget,
			"current_target", current.Target, "source_seq", ev.SourceSeq,
			"task_type", envelope.TaskType, "reason", "source_identity_mismatch")
		return false, nil
	}
	s.log.Debug("task_mirrored 通过 source identity 闸", "card", ev.CardID,
		"seq", ev.Seq, "type", ev.Type, "node", *envelope.Node, "attempt", *envelope.Attempt,
		"source_task", ev.SourceTask, "source_target", ev.SourceTarget,
		"current_target", current.Target, "source_seq", ev.SourceSeq, "task_type", envelope.TaskType)
	return true, nil
}

n_agentd_Server_activeCount.signature:
// activeCount 返回活跃任务数（running + waiting_answer）。
//
// waiting_review 不计入：它在等协调者裁决，挂几天都正常，计入等于让升级
// 被无限期阻塞（沿用 B54.3 的 D12）。
func (s *Server) activeCount() (int, error) {
	tasks, err := s.st.ListTasks()
	if err != nil {
		return 0, fmt.Errorf("列任务: %w", err)
	}
	n := 0
	for _, t := range tasks {
		if t.State == proto.TaskStateRunning || t.State == proto.TaskStateWaitingAnswer {
			n++
		}
	}
	return n, nil
}

n_agentd_Server_addMachine.signature:
// addMachine 校验并把一台开发机写入配置、落盘。
//
// 参数：
//   - req: 已由 handler 反序列化的请求体（Force 在本层无意义，探测在 handler）
//
// 返回：
//   - 校验错误（可能包装 ErrMachineExists）或落盘错误；成功时 nil
//
// 注意：重名判定在 swapConf 的临界区内再做一次。校验时的那次是为了尽早
// 返回清晰的错误，但两次请求并发到达时只有临界区内的判定作数。
func (s *Server) addMachine(req proto.AddMachineReq) error {
	if err := validateAddMachine(req, s.conf().Targets); err != nil {
		return err
	}

	s.log.Info("新增开发机", "name", req.Name, "addr", req.Addr, "user", req.User)
	return s.swapConf(func(c *config.Config) error {
		if _, ok := c.Targets[req.Name]; ok {
			return fmt.Errorf("%w: %s", ErrMachineExists, req.Name)
		}
		c.Targets[req.Name] = config.Target{Addr: req.Addr, Token: req.Token, User: req.User}
		return nil
	})
}

n_agentd_Server_admitSquadStep.signature:
// admitSquadStep 对绑了小队的节点做冻结身份选择或入队。
//
// 参数：cardID 卡号；req 规范环节请求；node 已解出的节点定义（Override.Squad 非空，
// 由调用方保证）。返回：admitted 时 binding 为有效三级组；queued 时 binding 为零值、
// 请求已在 ignition_queue 持久排队；error 为受理失败，调用方应释放卡槽位并上浮。
//
// 注意：Select 只读 Registry，执行容量只在目标 agentd 的 AdmitFrozen 中取得。
// ErrNoHealthy/ErrNotFound/ErrRoleMismatch 都经 %w 包装上浮，调用方继续用
// errors.Is 分流；本函数自己消化 ErrNoSlot 与 ErrRetryExhausted（都转排队，收敛
// 在同一个 Enqueue 调用点；预算耗尽先落 WARN 标记词）。Ready 快照恒 true 的
// 取值决策见 plan §D4。
func (s *Server) admitSquadStep(cardID string, req proto.CardStepReq, node ledger.NodeDef) (scheduling.Binding, squadDispatchOutcome, error) {
	if s.scheduling == nil {
		return scheduling.Binding{}, 0, fmt.Errorf(
			"节点 %s 绑定了小队 %q，但编制域服务未装配（SetupAutomation 未执行或 SetScheduling 未注入）",
			node.Name, node.Override.Squad)
	}
	card, err := s.ledger.GetCard(cardID)
	if err != nil {
		return scheduling.Binding{}, 0, fmt.Errorf("读卡取优先级快照: %w", err)
	}
	resolved, err := s.resolveReceiver(node.Override.Squad)
	if err != nil {
		return scheduling.Binding{}, 0, fmt.Errorf("节点 %s 解析小队 %q: %w", node.Name, node.Override.Squad, err)
	}
	if resolved.Kind != scheduling.ReceiverSquad {
		err := fmt.Errorf("%w: 节点 %s 绑定的接收者 %q 不是小队", scheduling.ErrInvalid, node.Name, resolved.Name)
		s.log.Error("小队节点接收者类型错误", "card", cardID, "node", node.Name,
			"receiver", resolved.Name, "kind", string(resolved.Kind), "cause", err)
		return scheduling.Binding{}, 0, err
	}
	target, executor, model := effectiveCovers(req, node)
	ireq := scheduling.IgnitionRequest{
		Card:	cardID, Squad: node.Override.Squad, Node: req.Step,
		Target:	target, Executor: executor, Model: model,
		Priority:	card.Priority,
		Ready:		true,
		Actor:		req.Actor,
	}
	s.log.Info("小队节点冻结身份选择开始", "card", cardID, "node", node.Name,
		"squad", node.Override.Squad, "cover_target", target,
		"cover_executor", executor, "cover_model", model, "priority", card.Priority)
	binding, err := s.scheduling.Select(ireq)
	if err == nil {
		id := scheduling.PhysicalIdentity{Machine: binding.Target, CLI: binding.Executor, HomeDir: binding.HomeDir}
		bound, bindErr := scheduling.BindPhysical(id, scheduling.PhysicalOverlay{})
		if bindErr != nil {
			s.log.Error("小队节点绑定物理身份失败", "card", cardID, "node", node.Name,
				"squad", binding.Squad, "carrier", binding.Carrier, "error_kind", "physical_bind", "cause", bindErr)
			return scheduling.Binding{}, 0, bindErr
		}
		binding.Target = bound.Machine
		binding.Executor = bound.CLI
		binding.HomeDir = bound.HomeDir
		binding.Model = scheduling.EffectiveModel(binding.Model, model)
		s.log.Info("小队节点冻结身份选择成功", "card", cardID, "node", node.Name,
			"squad", binding.Squad, "carrier", binding.Carrier, "target", binding.Target,
			"executor", binding.Executor, "model", binding.Model, "error_kind", "select_success")
		return binding, squadDispatchAdmitted, nil
	}
	if errors.Is(err, scheduling.ErrNoSlot) || errors.Is(err, scheduling.ErrRetryExhausted) {
		if errors.Is(err, scheduling.ErrRetryExhausted) {

			s.log.Warn("准入重试预算耗尽，按满员转排队", "card", cardID,
				"node", node.Name, "squad", node.Override.Squad, "actor", req.Actor,
				"cause", err)
		}
		position, enqErr := s.scheduling.Enqueue(ireq, scheduling.KindIgnitionQueue)
		if enqErr != nil {
			s.log.Error("小队满员后写入点火队列失败", "card", cardID, "node", node.Name,
				"squad", node.Override.Squad, "queue_position", position, "error_kind", "enqueue", "cause", enqErr)
			return scheduling.Binding{}, 0, fmt.Errorf("满员转排队失败: %w", enqErr)
		}
		s.log.Info("小队满员，点火请求已持久排队", "card", cardID, "node", node.Name,
			"squad", node.Override.Squad, "queue_position", position, "actor", req.Actor)
		return scheduling.Binding{}, squadDispatchQueued, nil
	}
	s.log.Error("小队节点冻结身份选择被拒", "card", cardID, "node", node.Name,
		"squad", node.Override.Squad, "error_kind", "select_rejected", "cause", err)
	return scheduling.Binding{}, 0, fmt.Errorf("小队 %q 冻结身份选择被拒: %w", node.Override.Squad, err)
}

n_agentd_Server_advanceAutomationCursor.signature:
// advanceAutomationCursor 先更新内存再保存文件；保存失败不回滚内存，允许至少一次重放。
func (s *Server) advanceAutomationCursor(seq int64) error {
	s.automationMu.Lock()
	defer s.automationMu.Unlock()
	if seq <= s.automationCursor {
		return nil
	}
	s.automationCursor = seq
	if s.automationCursorStore == nil {
		err := fmt.Errorf("自动化 cursor 持久化未装配：seq=%d", seq)
		s.log.Error("自动化 cursor 保存失败", "seq", seq, "cause", err)
		return err
	}
	if err := s.automationCursorStore.Save(seq); err != nil {
		s.log.Error("自动化 cursor 保存失败", "seq", seq,
			"path", s.automationCursorStore.path, "cause", err)
		return fmt.Errorf("保存自动化 cursor seq=%d: %w", seq, err)
	}
	s.log.Info("自动化 cursor 已保存", "seq", seq, "path", s.automationCursorStore.path)
	return nil
}

n_agentd_Server_allowedHosts.signature:
// allowedHosts 计算白名单集合（小写归一）。
//
// 安全论证（为什么把本机网卡 IP 放进来不削弱 DNS rebinding 防线）：rebinding
// 的机制是让**攻击者的域名**解析到目标地址，浏览器随后发出的请求里 Host 头是
// **那个域名**（`evil.com`），不是 IP——这正是本中间件挡得住它的原因。要让浏览器
// 发出 `Host: 100.73.238.21`，页面必须直接请求 `http://100.73.238.21:port/`，
// 那是一个普通的跨源请求：同源策略不让攻击者读响应，而写操作仍要过后面的鉴权层。
// 换句话说，本机自己的 IP 出现在名单里，既不给攻击者读通道，也不给它免鉴权的
// 写通道。**能任意伪造 Host 的非浏览器客户端本来就不受 rebinding 约束**，那一层
// 从来是由凭据兜底的（见本文件头「边界」第二条）。
func (s *Server) allowedHosts() map[string]struct{} {
	out := make(map[string]struct{}, len(loopbackHosts)+len(s.conf().Web.AllowedHosts)+1)
	for _, h := range loopbackHosts {
		out[h] = struct{}{}
	}

	if h := strings.ToLower(hostOnly(s.conf().Listen)); h != "" && !isWildcardListen(s.conf().Listen) {
		out[h] = struct{}{}
	}

	if isWildcardListen(s.conf().Listen) {
		for _, ip := range localIPsFn() {
			out[ip] = struct{}{}
		}
	}
	for _, h := range s.conf().Web.AllowedHosts {
		if h = strings.ToLower(strings.TrimSpace(h)); h != "" {
			out[h] = struct{}{}
		}
	}
	return out
}

n_agentd_Server_attachCardBaseBranches.signature:
// attachCardBaseBranches 在 Git 工作树已经成功后，按请求顺序逐张设置卡基线。
// 单张失败只进入该项结果，不删除已经存在的工作树，也不回滚此前成功的卡。
func (s *Server) attachCardBaseBranches(ws proto.Workspace, ids []string, actor string) proto.Workspace {
	results := make([]proto.CardBaseBranchResult, 0, len(ids))
	s.log.Info("建树后开始逐卡挂基线", "branch", ws.Branch, "card_count", len(ids), "actor", actor)
	for _, id := range ids {
		result := proto.CardBaseBranchResult{ID: id}
		if err := s.ledger.SetCardBaseBranch(id, ws.Branch, actor); err != nil {
			result.Error = err.Error()
			s.log.Warn("建树后挂卡失败：工作树保留", "card", id, "branch", ws.Branch, "cause", err)
		} else {
			result.OK = true
			s.log.Info("建树后挂卡完成", "card", id, "branch", ws.Branch, "actor", actor)
		}
		results = append(results, result)
	}
	ws.CardResults = results
	s.log.Info("建树后逐卡挂基线完成", "branch", ws.Branch, "card_count", len(results))
	return ws
}

n_agentd_Server_auth.signature:
// auth 是 Bearer token 或 cookie 会话鉴权中间件，包住全部路由。
//
// 鉴权失败（无 token / token 不匹配 / cookie 会话无效）统一返回 401，并打 Warn
// 记录来源地址——这是排查「谁在扫本地端口」与「配对端 token 未同步」的第一线索。
//
// 为什么这里做空 token 拒绝（L-2）：subtle.ConstantTimeCompare("","")==1，
// 配置 token 为空时空 token 请求会通过鉴权——今天只因 net/http 的
// textproto 行解析会掐掉 "Bearer " 后的空格才 401，属于「碰巧被别的层拦住」
// 的隐性 fail-open。config.Load 正常都会生成 token，但手写配置可能漏掉；
// 在鉴权边界 fail-closed：cfg.Token 为空 → 拒绝一切请求并打 Error，提示
// 配置问题。选在这里而非 NewServer/启动时：这是 fail-open 真正发生的边界，
// 一个位置同时覆盖 HTTP 与 WS 全路由，任何嵌入方（含测试）都逃不掉。
//
// 为什么在 Bearer 之外加 cookie 分支：浏览器里 `new WebSocket()` 只能继承
// 页面已有的 cookie，设不了 Authorization 请求头——CLI 的主令牌路径在浏览器
// 里走不通，必须允许 cookie 会话鉴权。
func (s *Server) auth(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if s.conf().Token == "" {
			s.log.Error("token 未配置，拒绝一切请求（fail-closed）：请在配置中设置 token 后重启 agentd",
				"remote_addr", r.RemoteAddr, "method", r.Method, "path", r.URL.Path)
			writeUnauthorized(w, r)
			return
		}

		if token, ok := bearerToken(r); ok &&
			subtle.ConstantTimeCompare([]byte(token), []byte(s.conf().Token)) == 1 {
			next.ServeHTTP(w, r.WithContext(withIdentity(r.Context(), identity{})))
			return
		}

		sess, reason := s.sessionFromRequest(r)
		if sess == nil {
			s.log.Warn("鉴权失败", "remote_addr", r.RemoteAddr, "method", r.Method,
				"path", r.URL.Path, "reason", reason)
			writeUnauthorized(w, r)
			return
		}
		s.refreshSession(sess)
		next.ServeHTTP(w, r.WithContext(withIdentity(r.Context(), identity{session: sess.ID})))
	})
}

n_agentd_Server_automationLoop.signature:
func (s *Server) automationLoop(ctx context.Context) {
	s.runAutomationPass(ctx)
	ticker := time.NewTicker(automationPollInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			s.log.Info("自动化循环停止", "cause", ctx.Err())
			return
		case <-ticker.C:
			s.runAutomationPass(ctx)
		case <-s.automationKick:
			s.runAutomationPass(ctx)
		}
	}
}

n_agentd_Server_beginDesktopDownload.signature:
// beginDesktopDownload 抢占一个下载槽并设置 downloading 状态。
func (s *Server) beginDesktopDownload(tag string) bool {
	s.downloadMu.Lock()
	defer s.downloadMu.Unlock()
	if s.downloadState != nil && (s.downloadState.Stage == "downloading" || s.downloadState.Stage == "verifying") {
		return false
	}
	s.downloadState = &proto.DownloadState{Stage: "downloading", Tag: tag, Percent: -1}
	return true
}

n_agentd_Server_beginMachineUpgrade.signature:
// beginMachineUpgrade 抢占单台机器的后台升级槽位。
//
// 抢到时把状态置为 Running 并**清掉上一轮的终态**：留着会让控制台把旧结果
// 当成这一轮的结论。
func (s *Server) beginMachineUpgrade(name string) bool {
	s.upgradeMu.Lock()
	defer s.upgradeMu.Unlock()
	if s.machineUpgrades == nil {
		s.machineUpgrades = make(map[string]*proto.MachineUpgrade)
	}
	if st := s.machineUpgrades[name]; st != nil && st.Running {
		return false
	}
	s.machineUpgrades[name] = &proto.MachineUpgrade{Running: true}
	return true
}

