n_agentd_Server_clientForTarget.signature:
// clientForTarget 按规范目标取得 agentd client。
//
// 空串或配置中指向本机的登记名返回本机直连 client；该 client 不由调用方关闭。
// 远端和未知名称交给 target client 池，池保留既有的配置校验与 relay 生命周期。
func (s *Server) clientForTarget(target string) (*client.Client, error) {
	canonical := s.CanonicalTarget(target)
	if canonical == "" {
		cfg := s.conf()
		if cfg == nil || cfg.Token == "" {
			err := fmt.Errorf("本机客户端缺少配置或 token")
			s.log.Error("取得本机客户端失败", "target", target,
				"canonical_target", canonical, "cause", err)
			return nil, err
		}
		s.log.Info("采用本机节点客户端", "target", target,
			"canonical_target", canonical)
		return targetclient.NewLocal(config.LocalDialAddr(cfg.Listen), cfg.Token), nil
	}
	s.log.Info("采用远端节点客户端", "target", target,
		"canonical_target", canonical)
	return s.pool.For(canonical)
}

n_agentd_Server_closeCoordinatorTab.signature:
func (s *Server) closeCoordinatorTab(card string) {
	s.coordTabsMu.Lock()
	tab, ok := s.coordTabs[card]
	if ok {
		delete(s.coordTabs, card)
	}
	s.coordTabsMu.Unlock()
	if !ok {
		return
	}
	if tab.PtyID != "" {
		remote := !scheduling.IsLocalMachine(tab.Machine) && !s.IsSelfTarget(tab.Machine)
		if remote {
			if err := s.closeRemoteCoordinatorPty(tab.Machine, tab.PtyID); err != nil {
				s.log.Warn("关闭远端协调者 TUI 失败", "card", card, "machine", tab.Machine, "pty", tab.PtyID, "cause", err)
			} else {
				s.log.Info("远端协调者 TUI 已关闭", "card", card, "machine", tab.Machine, "pty", tab.PtyID)
			}
		} else if s.pty != nil {
			if err := s.pty.Close(tab.PtyID); err != nil {
				s.log.Warn("关闭协调者 TUI 失败", "card", card, "pty", tab.PtyID, "cause", err)
			} else {
				s.log.Info("协调者 TUI 已关闭", "card", card, "pty", tab.PtyID)
			}
		}
	}
	s.releaseSchedulingBinding(card, tab.Binding)
}

n_agentd_Server_closeCoordinatorTabIfTer.signature:
func (s *Server) closeCoordinatorTabIfTerminal(card, status string) {
	if status != ledger.StatusDone && status != ledger.StatusClosed {
		return
	}
	s.log.Info("卡终态，关闭协调者 TUI", "card", card, "status", status)
	s.closeCoordinatorTab(card)
}

n_agentd_Server_closeRemoteCoordinatorPt.signature:
func (s *Server) closeRemoteCoordinatorPty(machine, ptyID string) error {
	if s.closeRemoteCoordPty != nil {
		return s.closeRemoteCoordPty(machine, ptyID)
	}
	c, err := s.clientForPtySessions(machine)
	if err != nil {
		return fmt.Errorf("取机器 %s 客户端: %w", machine, err)
	}
	return c.DeletePtySession(context.Background(), ptyID)
}

n_agentd_Server_compensateStep.signature:
// compensateStep 回收一次已取得 task id 的失败派发。具名入口（原为内联闭包），
// 依赖声明收窄到 stopReclaimClient；只回收，不改原始错误。
func (s *Server) compensateStep(ctx context.Context, cl stopReclaimClient, cardID, target, taskID string) error {
	s.log.Info("agentd 派发失败补偿开始", "card", cardID, "target", target, "task", taskID)
	if err := cl.StopAndReclaim(ctx, taskID); err != nil {
		s.log.Error("agentd 派发失败补偿失败", "card", cardID, "target", target, "task", taskID, "cause", err)
		return err
	}
	s.log.Info("agentd 派发失败补偿完成", "card", cardID, "target", target, "task", taskID)
	return nil
}

