n_agentd_Server_disciplineBindings.signature:
// disciplineBindings 把「已注册的 executor ∪ 配置里已出现的键」折成档位列表，按名字升序。
//
// 三档映射：键不存在 → default；值为空串 → off；否则 → file。
// DefaultTier 恒空串：内置档位表已随 B229 删除，「改回默认」不再对应任何正文，
// 字段保留只为 TS 类型不断裂。
func (s *Server) disciplineBindings() []proto.DisciplineBinding {
	m := s.conf().Discipline
	seen := map[string]bool{}
	names := []string{}
	for _, n := range s.mgr.ExecutorNames() {
		if !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	for n := range m {
		if !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	sort.Strings(names)

	out := make([]proto.DisciplineBinding, 0, len(names))
	for _, n := range names {
		b := proto.DisciplineBinding{Executor: n}
		v, configured := m[n]
		switch {
		case !configured:
			b.Mode = proto.DisciplineModeDefault
		case strings.TrimSpace(v) == "":
			b.Mode = proto.DisciplineModeOff
		default:
			b.Mode, b.File = proto.DisciplineModeFile, strings.TrimSpace(v)
		}
		out = append(out, b)
	}
	return out
}

n_agentd_Server_disciplineTargetCap.signature:
// disciplineTargetCap 读目标机的 DisciplinesSupported。
//
// 本机（local / 本机 / 本机 hostname）就是当前进程：能力位与 Status 上报同源
// （当前二进制恒 true）。"local" 不是 config.Targets 里的远程机，pool.For 会
// 稳定报未登记；把 nil 当不支持会让本机点火被 B229 拒发闸误杀（B299 真机）。
// 远程机仍走探活；失败保持 nil，按不支持处置。生产派发走 resolveStepDiscipline
// 的探活失败硬红路径；本函数只服务本机短路单测。
func (s *Server) disciplineTargetCap(target string) *bool {
	if isLocalMachine(target) {
		yes := true
		return &yes
	}
	cl, err := s.pool.For(target)
	if err != nil {
		s.log.Warn("环节派发前取得目标机客户端失败", "target", target, "cause", err)
		return nil
	}
	status, serr := probeStatus(context.Background(), cl)
	if serr != nil {
		s.log.Warn("环节派发前能力位探活失败", "target", target, "cause", serr)
		return nil
	}
	return status.DisciplinesSupported
}

n_agentd_Server_drainIgnitionRequest.signature:
func (s *Server) drainIgnitionRequest(ctx context.Context, req scheduling.IgnitionRequest) error {
	backlog := 0
	if rows, err := s.scheduling.QueueSnapshot(); err != nil {
		s.log.Warn("生成出队简报失败，仍继续唤醒",
			"card", req.Card, "node", req.Node, "cause", err)
	} else {
		backlog = len(rows)
	}
	summary := fmt.Sprintf("queue_release kind=%s card=%s node=%s backlog=%d",
		scheduling.KindIgnitionQueue, req.Card, req.Node, backlog)
	decision := s.keystone.Decide(keystone.WakeEvent{
		Kind:	keystone.WakeQueueRelease, Card: req.Card, Summary: summary,
	})
	if !decision.Wake {
		s.log.Info("队列出队被人工接管暂缓", "card", req.Card,
			"node", req.Node, "reason", decision.Reason)
		return fmt.Errorf("队列出队暂缓：%s", decision.Reason)
	}
	result, err := s.wakeCoordinatorRound(ctx, req.Card, []keystone.WakeEvent{{
		Kind:	keystone.WakeQueueRelease, Card: req.Card, Summary: summary,
	}})
	if err != nil {
		return fmt.Errorf("队列出队唤醒失败: %w", err)
	}
	if result.Woke {
		s.log.Info("队列出队唤醒完成，进入节点再入口", "card", req.Card, "node", req.Node)
	} else {
		s.log.Info("队列出队无协调者席位，直接进入节点再入口", "card", req.Card, "node", req.Node)
	}

	return s.startCardStep(req.Card, proto.CardStepReq{
		Step:	req.Node, Target: req.Target, Executor: req.Executor,
		Model:	req.Model, Actor: req.Actor,
	})
}

n_agentd_Server_drainQueuesOnce.signature:
// drainQueuesOnce 按 QueueKinds 法定顺序最多处理 100 行。局部 deferred 只在本次
// 清队轮次存活，且只延后协调者 ErrNoSlot 请求；轮末统一回填这些请求后才返回，
// 因而一个载体暂时无位不会阻断其它载体的执行者请求。
func (s *Server) drainQueuesOnce(ctx context.Context) (processed int, err error) {
	if s.scheduling == nil {
		s.log.Error("自动化队列清队失败：编制域未装配")
		return 0, errors.New("自动化队列清队：编制域未装配")
	}
	type deferredLaunch struct {
		req	scheduling.IgnitionRequest
		cause	error
	}
	deferred := make([]deferredLaunch, 0)
	flushDeferred := func() int {
		count := len(deferred)
		for _, item := range deferred {
			s.requeueAutomation(item.req, scheduling.KindLaunchQueue, item.cause)
		}
		deferred = nil
		if count > 0 {
			s.log.Info("协调者无位请求已回填", "kind", scheduling.KindLaunchQueue,
				"deferred_count", count)
		}
		return count
	}
	for _, kind := range scheduling.QueueKinds {
		for processed < automationBatchLimit {
			req, ok, popErr := s.scheduling.PopReady(kind)
			if popErr != nil {
				requeued := flushDeferred()
				s.log.Error("自动化队列出队失败", "kind", kind, "cause", popErr)
				s.log.Warn("自动化队列清队提前结束", "kind", kind,
					"deferred_count", requeued, "cause", popErr)
				return processed, fmt.Errorf("出队 %s 失败: %w", kind, popErr)
			}
			if !ok {
				break
			}
			processed++
			s.log.Info("自动化队列出队", "kind", kind, "card", req.Card,
				"node", req.Node, "squad", req.Squad, "priority", req.Priority)
			switch kind {
			case scheduling.KindLaunchQueue:
				if _, launchErr := s.launchCoordinatorRound(ctx, req.Card, "coordinate"); launchErr != nil {
					if errors.Is(launchErr, scheduling.ErrNoSlot) {
						deferred = append(deferred, deferredLaunch{req: req, cause: launchErr})
						s.log.Warn("协调者准入无位，延后到本轮末回填", "kind", kind,
							"card", req.Card, "node", req.Node,
							"deferred_count", len(deferred), "cause", launchErr)
						continue
					}
					s.requeueAutomation(req, kind, launchErr)
					flushDeferred()
					s.log.Warn("协调者清队因非无位错误停止", "kind", kind,
						"card", req.Card, "node", req.Node, "cause", launchErr)
					return processed, nil
				}
			case scheduling.KindIgnitionQueue:
				if drainErr := s.drainIgnitionRequest(ctx, req); drainErr != nil {
					s.requeueAutomation(req, kind, drainErr)
					flushDeferred()
					s.log.Warn("执行者清队因错误停止", "kind", kind,
						"card", req.Card, "node", req.Node, "cause", drainErr)
					return processed, nil
				}
			default:
				s.log.Error("自动化清队遇到未声明 kind", "kind", kind, "card", req.Card)
				flushDeferred()
				return processed, fmt.Errorf("清队遇到未声明 kind %q", kind)
			}
		}
		if processed >= automationBatchLimit {
			break
		}
	}
	flushDeferred()
	return processed, nil
}

n_agentd_Server_enrichRoomAttachments.signature:
// enrichRoomAttachments 给 card 房间补最新可解析的挂账 task；群房间没有 task，
// 保持 Attach=nil。远端 attach 是非承重字段：请求只读取本地挂账与缓存，缺失项
// 交给后台刷新，避免一个 relay 延迟拖住整个房间列表。
func (s *Server) enrichRoomAttachments(_ context.Context, rooms []proto.RoomSummary) {
	if s.ledger == nil {
		return
	}
	links, err := s.ledger.AllTaskLinks()
	if err != nil {
		s.log.Warn("读取房间挂账失败", "cause", err)
		return
	}
	linksByRoom := make(map[string][]ledger.TaskLink)
	for _, link := range links {
		linksByRoom[link.CardID] = append(linksByRoom[link.CardID], link)
	}
	for roomID := range linksByRoom {
		sort.SliceStable(linksByRoom[roomID], func(i, j int) bool {
			return linksByRoom[roomID][i].CreatedAt.Before(linksByRoom[roomID][j].CreatedAt)
		})
	}

	localTasks := make(map[string]proto.Task)
	for _, link := range links {
		if link.Target != "" || s.st == nil {
			continue
		}
		tasks, listErr := s.st.ListTasks()
		if listErr != nil {
			s.log.Warn("读取本机任务列表失败，attach 降级禁用", "cause", listErr)
			break
		}
		for _, task := range tasks {
			localTasks[task.ID] = task
		}
		s.log.Debug("本机 attach 任务索引已就绪", "tasks", len(localTasks))
		break
	}

	for i := range rooms {
		if rooms[i].Kind != room.KindCard {
			continue
		}
		roomLinks := linksByRoom[rooms[i].ID]
		if len(roomLinks) == 0 {
			continue
		}
		for linkIndex := len(roomLinks) - 1; linkIndex >= 0; linkIndex-- {
			link := roomLinks[linkIndex]
			if link.Target == "" {
				attach, lookupErr := s.lookupRoomAttach(context.Background(), link, localTasks)
				if lookupErr != nil {
					s.log.Warn("房间 attach 本机任务不可解析", "room", rooms[i].ID,
						"task", link.TaskID, "cause", lookupErr)
					continue
				}
				rooms[i].Attach = attach
				s.log.Info("房间 attach 投影成功", "room", rooms[i].ID,
					"target", link.Target, "task", link.TaskID, "workdir", attach.WorkDir)
				break
			}
			if attach := s.cachedRoomAttach(link); attach != nil {
				rooms[i].Attach = attach
				s.log.Info("房间 attach 从缓存投影成功", "room", rooms[i].ID,
					"target", link.Target, "task", link.TaskID, "workdir", attach.WorkDir)
				break
			}
		}
	}
	s.startRoomAttachRefresh(links)
	s.log.Info("房间 attach 投影完成", "rooms", len(rooms), "links", len(links))
}

n_agentd_Server_envBindings.signature:
// envBindings 把「已注册的 executor ∪ 配置里已出现的键」折成档位列表，按名字升序。
//
// **两档映射**：键不存在（或值 trim 后为空）→ off；否则 → file。
//
// 为什么空串也归到 off：历史配置里可能已经写着空串（手改 yaml 留下的），把它
// 显示成「指向一个名字为空的文件」只会让人困惑。**但保存时绝不写回空串**——
// 读宽写严，脏数据经过一次保存就被洗掉。
func (s *Server) envBindings() []proto.EnvBinding {
	m := s.conf().Env
	seen := map[string]bool{}
	names := []string{}
	for _, n := range s.mgr.ExecutorNames() {
		if !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	for n := range m {
		if !seen[n] {
			seen[n] = true
			names = append(names, n)
		}
	}
	sort.Strings(names)

	out := make([]proto.EnvBinding, 0, len(names))
	for _, n := range names {
		b := proto.EnvBinding{Executor: n}
		if v := strings.TrimSpace(m[n]); v == "" {
			b.Mode = proto.EnvModeOff
		} else {
			b.Mode, b.File = proto.EnvModeFile, v
		}
		out = append(out, b)
	}
	return out
}

n_agentd_Server_executeMachineUpgrade.signature:
// executeMachineUpgrade 是 machineUpgradeRunner 的生产实现。
func (s *Server) executeMachineUpgrade(ctx context.Context, m upgrade.Machine, target config.Target,
	rel release.Release, force bool, progress func(string)) upgrade.Result {
	if s.machineUpgradeInstaller == nil {
		return upgrade.Result{Verdict: upgrade.VerdictNeedsUpgrade, Status: upgrade.StatusFail,
			Reason:	"远端升级下载器未就绪"}
	}

	peer, err := s.pool.For(m.Name)
	if err != nil {
		s.log.Error("执行机升级：取客户端失败", "name", m.Name, "cause", err)
		return upgrade.Result{Verdict: upgrade.VerdictUnreachable, Status: upgrade.StatusFail,
			Reason:	err.Error()}
	}
	return upgrade.RemoteOne(ctx, s.log, m, peer,
		s.machineUpgradeInstaller, rel, upgrade.Options{Force: force}, progress)
}

n_agentd_Server_executorDefaultResp.signature:
// executorDefaultResp 组装当前状态（GET 与 PUT 的成功响应共用，保证两处一致）。
func (s *Server) executorDefaultResp() proto.ExecutorDefaultResp {
	c := s.conf()
	return proto.ExecutorDefaultResp{
		Default:	c.Executor.Default,
		Model:		c.Executor.Model,
		Available:	s.mgr.ExecutorNames(),
	}
}

n_agentd_Server_finishDesktopDownloadErr.signature:
// finishDesktopDownloadError 将内部错误转成 502，并保留 failed 状态。
func (s *Server) finishDesktopDownloadError(w http.ResponseWriter, tag, action string, err error) {
	s.log.Error("桌面安装包下载失败", "tag", tag, "action", action, "cause", err)
	s.setDesktopDownloadFailed(tag, action+": "+err.Error())
	writeJSON(w, http.StatusBadGateway, map[string]string{"error": action + ": " + err.Error()})
}

n_agentd_Server_finishDesktopDownloadSta.signature:
// finishDesktopDownloadStatus 写指定状态码的失败结果。
func (s *Server) finishDesktopDownloadStatus(w http.ResponseWriter, tag string, status int, message string) {
	s.setDesktopDownloadFailed(tag, message)
	writeJSON(w, status, map[string]string{"error": message})
}

n_agentd_Server_finishMachineUpgrade.signature:
// finishMachineUpgrade 落终态并释放槽位。
//
// 承重：这是控制台知道「升级结束了」的唯一途径——升级没有进度流，成功可以靠
// 版本变化推断，失败**只有这条**。
func (s *Server) finishMachineUpgrade(name string, result upgrade.Result) {
	s.upgradeMu.Lock()
	defer s.upgradeMu.Unlock()
	s.machineUpgrades[name] = &proto.MachineUpgrade{
		Running:	false,
		Status:		result.Status.String(),
		Verdict:	result.Verdict.String(),
		Reason:		result.Reason,
		Remedy:		result.Remedy,
		From:		result.From,
		To:		result.To,
	}
}

n_agentd_Server_forwardIfRequested.signature:
// forwardIfRequested 处理显式 ?machine= 路由。
//
// 返回：
//   - true 表示请求已被处理（已转发或已拒绝），调用方必须直接 return
//   - false 表示这是本机的活，继续原来的处理
//
// 注意：
//   - machine 省略或为空串 = 本机（与 Task.Machine 的空串语义一致）
//   - 带转发头时一律返回 false（防环优先于路由）
func (s *Server) forwardIfRequested(w http.ResponseWriter, r *http.Request) bool {
	name := r.URL.Query().Get("machine")
	if name == "" || isForwarded(r) {
		return false
	}
	t, ok := s.conf().Targets[name]
	if !ok {
		s.log.Warn("转发被拒：机器名未在配置中定义", "machine", name, "path", r.URL.Path)
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": "机器 " + name + " 未在本机配置的 targets 中定义"})
		return true
	}
	c, err := s.pool.For(name)
	if err != nil {
		s.log.Error("转发失败：取目标客户端失败", "machine", name, "relay", t.IsRelay(), "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "转发到 " + name + " 失败: " + err.Error()})
		return true
	}
	s.forwardTo(w, r, name, c, t.Token)
	return true
}

n_agentd_Server_forwardJSON.signature:
// forwardJSON 经目标机客户端发一次有大小上限的 JSON 请求，把完整响应交回调用方。
//
// 为什么状态码的处置留给调用方而不在这里收口：建树这条路的成功与失败去向不同——
// 成功/失败分叉留给调用方：失败原样透传；成功由 handler 挂卡再写响应。本函数不写账本。
func (s *Server) forwardJSON(r *http.Request, name string, c *client.Client, token string, body []byte) (status int, headers http.Header, payload []byte, err error) {
	target, err := forwardURL(c.BaseURL(), r.URL)
	if err != nil {
		s.log.Error("建树 JSON 转发失败：目标地址不合法", "machine", name, "cause", err)
		return 0, nil, nil, err
	}
	req, err := http.NewRequestWithContext(r.Context(), r.Method, target, bytes.NewReader(body))
	if err != nil {
		s.log.Error("建树 JSON 转发失败：构造请求", "machine", name, "cause", err)
		return 0, nil, nil, err
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if contentType := r.Header.Get("Content-Type"); contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	req.Header.Set(forwardedHeader, "1")
	resp, err := c.HTTPClient().Do(req)
	if err != nil {
		s.log.Error("建树 JSON 转发失败：上游不可达", "machine", name, "cause", err)
		return 0, nil, nil, err
	}
	defer resp.Body.Close()
	payload, err = io.ReadAll(io.LimitReader(resp.Body, forwardBodyLimit+1))
	if err != nil {
		s.log.Error("建树 JSON 转发失败：读取响应", "machine", name, "status", resp.StatusCode, "cause", err)
		return 0, nil, nil, err
	}
	if len(payload) > forwardBodyLimit {
		err := fmt.Errorf("目标响应超过 %d 字节上限", forwardBodyLimit)
		s.log.Error("建树 JSON 转发失败：目标响应过大", "machine", name,
			"status", resp.StatusCode, "bytes", len(payload), "cause", err)
		return 0, nil, nil, err
	}
	headers = resp.Header.Clone()
	s.log.Info("建树 JSON 转发完成", "machine", name, "status", resp.StatusCode, "bytes", len(payload))
	return resp.StatusCode, headers, payload, nil
}

n_agentd_Server_forwardTo.signature:
// forwardTo 把请求原样搬到目标机器，并把响应原样回送。
//
// 参数：
//   - name: 目标机器名，只用于日志与错误文案
//   - c: 池选路好的目标客户端——基址与传输都取自它（relay 走隧道、直连走 addr）
//   - token: 目标机器的 Bearer 令牌（只进请求头；与池构造 c 时用的是同一份配置）
//
// 注意：
//   - **不设独立超时**：跟随 r.Context()。项目登记可能触发目标机 clone，耗时
//     以分钟计；§5.2 的 3s 预算约束的是**汇总扇出**，不是这条显式路由。
//     浏览器/CLI 断开时 r.Context() 取消，上游连接随之断开
//   - 转发失败回 502 带原文：这是本机与目标机之间的问题，不能伪装成目标机
//     的业务错误
func (s *Server) forwardTo(w http.ResponseWriter, r *http.Request, name string, c *client.Client, token string) {
	target, err := forwardURL(c.BaseURL(), r.URL)
	if err != nil {
		s.log.Error("转发失败：目标地址不合法", "machine", name, "base_url", c.BaseURL(), "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "转发到 " + name + " 失败: " + err.Error()})
		return
	}
	start := time.Now()
	s.log.Info("转发请求", "machine", name, "method", r.Method, "path", r.URL.Path)

	req, err := http.NewRequestWithContext(r.Context(), r.Method, target,
		io.LimitReader(r.Body, forwardBodyLimit))
	if err != nil {
		s.log.Error("转发失败：构造请求", "machine", name, "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "转发到 " + name + " 失败: " + err.Error()})
		return
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if ct := r.Header.Get("Content-Type"); ct != "" {
		req.Header.Set("Content-Type", ct)
	}
	req.Header.Set(forwardedHeader, "1")

	resp, err := c.HTTPClient().Do(req)
	if err != nil {
		s.log.Error("转发失败：上游不可达", "machine", name, "path", r.URL.Path,
			"elapsed_ms", time.Since(start).Milliseconds(), "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "转发到 " + name + " 失败: " + err.Error()})
		return
	}
	defer resp.Body.Close()

	if ct := resp.Header.Get("Content-Type"); ct != "" {
		w.Header().Set("Content-Type", ct)
	}

	for key, values := range resp.Header {
		if !strings.HasPrefix(http.CanonicalHeaderKey(key), "X-Handoff-") {
			continue
		}
		for _, value := range values {
			w.Header().Add(key, value)
		}
	}
	w.WriteHeader(resp.StatusCode)
	flusher, _ := w.(http.Flusher)
	if flusher != nil {

		flusher.Flush()
	}

	var n int64
	var cerr error
	if flusher == nil {

		n, cerr = io.Copy(w, resp.Body)
	} else {
		buf := make([]byte, 32*1024)
		for {
			nr, rerr := resp.Body.Read(buf)
			if nr > 0 {
				nw, werr := w.Write(buf[:nr])
				n += int64(nw)
				if werr != nil {
					cerr = werr
					break
				}
				if nw != nr {
					cerr = io.ErrShortWrite
					break
				}

				flusher.Flush()
			}
			if rerr != nil {
				if rerr != io.EOF {
					cerr = rerr
				}
				break
			}
		}
	}
	if cerr != nil {

		s.log.Warn("转发响应回送中断", "machine", name, "written", n, "cause", cerr)
	}
	if resp.StatusCode >= 400 {
		s.log.Warn("转发上游返回非 2xx（原样透传，不改写）", "machine", name,
			"path", r.URL.Path, "status", resp.StatusCode,
			"elapsed_ms", time.Since(start).Milliseconds())
		return
	}
	s.log.Info("转发完成", "machine", name, "path", r.URL.Path,
		"status", resp.StatusCode, "elapsed_ms", time.Since(start).Milliseconds())
}

n_agentd_Server_forwardWS.signature:
// forwardWS 把一条 WS 请求反代到 machine 指定的机器。
//
// 关键顺序：**先拨上游，成功了再 Accept 本地**。反过来的话，上游不可达时
// 本地已经升级成 101，只能发一个 close——前端看到的是「连上了又断了」，
// 会一直重连；而 502 才让它知道是本机与目标机之间的问题（与 forwardTo 一致）。
func (s *Server) forwardWS(w http.ResponseWriter, r *http.Request, machine string) {
	t, ok := s.conf().Targets[machine]
	if !ok {
		s.log.Warn("WS 转发被拒：机器名未在配置中定义", "machine", machine, "path", r.URL.Path)
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": "机器 " + machine + " 未在本机配置的 targets 中定义"})
		return
	}

	c, err := s.pool.For(machine)
	if err != nil {
		s.log.Error("WS 转发失败：取目标客户端失败", "machine", machine, "relay", t.IsRelay(), "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{
			"error": "转发到 " + machine + " 失败: " + err.Error()})
		return
	}
	target, err := forwardURL(c.BaseURL(), r.URL)
	if err != nil {
		s.log.Error("WS 转发失败：目标地址不合法", "machine", machine, "base_url", c.BaseURL(), "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{
			"error": "转发到 " + machine + " 失败: " + err.Error()})
		return
	}
	target = toWSScheme(target)

	dialCtx, cancelDial := context.WithTimeout(r.Context(), wsDialBudget)
	defer cancelDial()
	hdr := http.Header{forwardedHeader: {"1"}}
	if t.Token != "" {
		hdr.Set("Authorization", "Bearer "+t.Token)
	}
	start := time.Now()
	up, _, err := websocket.Dial(dialCtx, target, &websocket.DialOptions{
		HTTPHeader:	hdr,

		HTTPClient:	c.HTTPClient(),
	})
	if err != nil {
		s.log.Error("WS 转发失败：上游不可达", "machine", machine, "path", r.URL.Path,
			"elapsed_ms", time.Since(start).Milliseconds(), "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{
			"error": "转发到 " + machine + " 失败: " + err.Error()})
		return
	}
	defer up.Close(websocket.StatusNormalClosure, "")

	down, err := websocket.Accept(w, r, nil)
	if err != nil {
		s.log.Warn("WS 转发：本地升级失败", "machine", machine, "cause", err)
		return
	}
	defer down.Close(websocket.StatusNormalClosure, "")

	up.SetReadLimit(wsForwardReadLimit)
	down.SetReadLimit(wsForwardReadLimit)

	s.log.Info("WS 转发已建立", "machine", machine, "path", r.URL.Path,
		"elapsed_ms", time.Since(start).Milliseconds())

	ctx, cancel := context.WithCancel(r.Context())
	defer cancel()
	errCh := make(chan error, 2)
	go func() { errCh <- pipeWS(ctx, down, up) }()
	go func() { errCh <- pipeWS(ctx, up, down) }()

	first := <-errCh

	status, reason := websocket.CloseStatus(first), ""
	var ce websocket.CloseError
	if errors.As(first, &ce) {
		reason = ce.Reason
	}
	if status == -1 {
		status = websocket.StatusNormalClosure
	}

	_ = down.Close(status, reason)
	_ = up.Close(status, reason)
	cancel()
	s.log.Info("WS 转发结束", "machine", machine, "path", r.URL.Path,
		"close_status", int(status), "elapsed_ms", time.Since(start).Milliseconds())
}

n_agentd_Server_forwardWorktreeIfRequest.signature:
// forwardWorktreeIfRequested 是建树请求专用的 ?machine 转发路径。
//
// 返回：
//   - handled=false：不是跨机请求，调用方走本机建树
//   - handled=true 且 ws==nil：已向 w 写入拒绝或目标错误，调用方必须直接 return
//   - handled=true 且 ws!=nil：目标建树成功。本函数不写账本、不写成功响应；
//     copyForwardHeaders 已落到 w。调用方用 cardIDs 挂卡后再 writeJSON。
//
// 为什么建树不能走通用的 forwardIfRequested：card_ids 指的是协调者本机账本里的卡。
func (s *Server) forwardWorktreeIfRequested(w http.ResponseWriter, r *http.Request) (handled bool, ws *proto.Workspace, cardIDs []string) {
	name := r.URL.Query().Get("machine")
	if name == "" || isForwarded(r) {
		return false, nil, nil
	}
	s.log.Info("建树请求开始专用转发", "machine", name, "path", r.URL.Path)
	target, ok := s.conf().Targets[name]
	if !ok {
		s.log.Warn("建树专用转发被拒：机器未定义", "machine", name)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "机器 " + name + " 未定义"})
		return true, nil, nil
	}
	c, err := s.pool.For(name)
	if err != nil {
		s.log.Error("建树专用转发失败：取目标客户端", "machine", name, "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "转发到 " + name + " 失败: " + err.Error()})
		return true, nil, nil
	}
	raw, err := io.ReadAll(io.LimitReader(r.Body, forwardBodyLimit+1))
	if err != nil {
		s.log.Error("建树专用转发失败：读取请求", "machine", name, "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "读取转发请求失败: " + err.Error()})
		return true, nil, nil
	}
	if len(raw) > forwardBodyLimit {
		s.log.Warn("建树专用转发被拒：请求体过大", "machine", name, "bytes", len(raw),
			"limit", forwardBodyLimit)
		writeJSON(w, http.StatusRequestEntityTooLarge, map[string]string{"error": "请求体超过 1 MiB 上限"})
		return true, nil, nil
	}
	var original proto.CreateWorktreeReq
	if err := json.Unmarshal(raw, &original); err != nil {
		s.log.Warn("建树专用转发失败：请求 JSON 无法解析", "machine", name, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {mode, branch, base}"})
		return true, nil, nil
	}
	body, stripErr := stripWorktreeCardIDs(raw)
	if stripErr != nil {
		s.log.Warn("建树专用转发失败：请求对象无法裁剪", "machine", name, "cause", stripErr)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON object"})
		return true, nil, nil
	}
	status, headers, payload, err := s.forwardJSON(r, name, c, target.Token, body)
	if err != nil {
		s.log.Error("建树专用转发失败：目标请求", "machine", name, "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "转发到 " + name + " 失败: " + err.Error()})
		return true, nil, nil
	}
	if status < http.StatusOK || status >= http.StatusMultipleChoices {
		s.log.Warn("建树专用转发原样回送目标错误", "machine", name, "status", status)
		copyForwardHeaders(w, headers)
		w.WriteHeader(status)
		if _, err := w.Write(payload); err != nil {
			s.log.Warn("建树专用转发回送目标错误失败", "machine", name, "status", status, "cause", err)
		}
		return true, nil, nil
	}
	var out proto.Workspace
	if err := json.Unmarshal(payload, &out); err != nil {
		s.log.Error("建树专用转发失败：目标响应不是 Workspace", "machine", name, "status", status, "cause", err)
		writeJSON(w, http.StatusBadGateway, map[string]string{"error": "目标建树响应无法解析: " + err.Error()})
		return true, nil, nil
	}
	out.CardResults = nil
	copyForwardHeaders(w, headers)
	s.log.Info("建树专用转发成功，交应用挂卡", "machine", name, "branch", out.Branch,
		"card_count", len(original.CardIDs))
	return true, &out, original.CardIDs
}

n_agentd_Server_handleAddMachine.signature:
// handleAddMachine 处理 POST /api/machines。
//
// 流程：反序列化 → 校验 → （非 force 时）可达性探测 → 落库 → 返回新列表。
//
// 状态码：
//   - 400 请求体不合法，或探测不通（体内带探测失败原文，供前端原样展示）
//   - 409 同名开发机已存在
//   - 500 落盘失败
//
// 注意：响应体是 proto.MachinesResp，其中的 proto.Machine 没有 Token 字段
// ——令牌只进不出，这条由类型本身保证。
func (s *Server) handleAddMachine(w http.ResponseWriter, r *http.Request) {
	var req proto.AddMachineReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("新增开发机：请求体无法解析", "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体不是合法 JSON"})
		return
	}

	if err := validateAddMachine(req, s.conf().Targets); err != nil {
		code := http.StatusBadRequest
		if errors.Is(err, ErrMachineExists) {
			code = http.StatusConflict
		}
		s.log.Warn("新增开发机：校验未通过", "name", req.Name, "addr", req.Addr, "cause", err)
		writeJSON(w, code, map[string]string{"error": err.Error()})
		return
	}
	if !req.Force {
		ctx, cancel := context.WithTimeout(r.Context(), addMachineProbeBudget)
		defer cancel()
		s.log.Info("新增开发机：开始可达性探测", "name", req.Name, "addr", req.Addr)

		probeClient, cleanup, newErr := targetclient.New(req.Name,
			config.Target{Addr: req.Addr, Token: req.Token}, s.log)
		if newErr != nil {
			s.log.Warn("新增开发机：无法构造探测客户端", "name", req.Name, "cause", newErr)
			writeJSON(w, http.StatusBadRequest, map[string]string{
				"error": fmt.Sprintf("探测 %s 失败：%v", req.Addr, newErr),
			})
			return
		}
		defer cleanup()
		if _, err := probeClient.NoRedirect().Status(ctx); err != nil {

			s.log.Warn("新增开发机：探测不通", "name", req.Name, "addr", req.Addr, "cause", err)
			writeJSON(w, http.StatusBadRequest, map[string]string{
				"error": fmt.Sprintf("探测 %s 失败：%v", req.Addr, err),
			})
			return
		}
		s.log.Info("新增开发机：探测通过", "name", req.Name, "addr", req.Addr)
	}
	if err := s.addMachine(req); err != nil {
		code := http.StatusInternalServerError
		if errors.Is(err, ErrMachineExists) {
			code = http.StatusConflict
		}
		s.log.Error("新增开发机失败", "name", req.Name, "cause", err)
		writeJSON(w, code, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("新增开发机成功", "name", req.Name, "addr", req.Addr, "force", req.Force)
	writeJSON(w, http.StatusOK, s.probeMachines(r.Context()))
}

n_agentd_Server_handleCardAccept.signature:
// handleCardAccept 记一条「已真机验」验收，body 只收证据。
//
// 为什么不收 verified 字段：标记未验是补记动作而不是日常，留 CLI 的
// `card accept --unverified`。界面上只提供「标记已验」这一个方向，语义更窄也更难误点。
//
// 为什么空证据必须在这里拦：RecordAcceptance 自己不校验，「已验必须带证据」
// 这条规则今天只由 CLI 守着。只靠前端不让空提交的话，curl 一下就能落一条
// 没有证据的「已验」——而验收记录正是事后唯一能复查的东西。
func (s *Server) handleCardAccept(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Evidence string `json:"evidence"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "bad json"})
		return
	}
	id := r.PathValue("id")
	evidence := strings.TrimSpace(req.Evidence)
	if evidence == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": "标记已验必须带证据（与 CLI card accept 同规则）",
		})
		return
	}
	actor := "web:" + r.RemoteAddr
	if err := s.ledger.RecordAcceptance(id, true, evidence, actor); err != nil {
		s.log.Error("记验收失败", "card", id, "actor", actor, "cause", err)
		ledgerErr(w, err)
		return
	}
	s.log.Info("已记验收", "card", id, "actor", actor, "evidence_bytes", len(evidence))
	writeJSON(w, http.StatusOK, map[string]bool{"ok": true})
}

