n_agentd_Server_handleCardPatch.signature:
// handleCardPatch 改卡的标题 / 优先级 / 验收判据 / 显式基线。
//
// **缺字段 = 不动该字段，不是置空。** 四个字段都用 *string 收，靠指针区分
// 「没给」与「给了空串」——用值类型收会让「只改优先级」把标题和判据一起清掉。
func (s *Server) handleCardPatch(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	var body struct {
		Title			*string	`json:"title"`
		Priority		*string	`json:"priority"`
		AcceptanceCriteria	*string	`json:"acceptance_criteria"`
		BaseBranch		*string	`json:"base_branch"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		s.log.Warn("卡 patch 请求体解析失败", "card", id, "cause", err)
		writeErr(w, http.StatusBadRequest, fmt.Errorf("解析请求体: %w", err))
		return
	}
	s.log.Info("卡 patch 请求", "card", id, "has_title", body.Title != nil,
		"has_priority", body.Priority != nil, "has_acceptance", body.AcceptanceCriteria != nil,
		"has_base_branch", body.BaseBranch != nil)
	card, err := s.ledger.GetCard(id)
	if err != nil {
		s.log.Warn("卡 patch 读取卡失败", "card", id, "cause", err)
		ledgerErr(w, err)
		return
	}
	actor := s.ledgerActor(r)
	if body.Title != nil || body.Priority != nil {

		title, priority := card.Title, card.Priority
		if body.Title != nil {
			if strings.TrimSpace(*body.Title) == "" {
				writeErr(w, http.StatusBadRequest, fmt.Errorf("标题不能改成空"))
				return
			}
			title = strings.TrimSpace(*body.Title)
		}
		if body.Priority != nil {
			priority = *body.Priority
		}
		if err := s.ledger.UpdateCardMeta(id, title, priority, actor); err != nil {
			s.log.Warn("改卡元信息失败", "card", id, "cause", err)
			writeErr(w, http.StatusBadRequest, err)
			return
		}
		s.log.Info("已改卡元信息", "card", id, "title", title, "priority", priority, "actor", actor)
	}
	if body.AcceptanceCriteria != nil {
		if err := s.ledger.SetAcceptance(id, *body.AcceptanceCriteria, actor); err != nil {
			s.log.Warn("写验收判据失败", "card", id, "cause", err)
			writeErr(w, http.StatusBadRequest, err)
			return
		}
		s.log.Info("已写验收判据", "card", id, "bytes", len(*body.AcceptanceCriteria), "actor", actor)
	}
	if body.BaseBranch != nil {
		if err := s.ledger.SetCardBaseBranch(id, *body.BaseBranch, actor); err != nil {
			s.log.Warn("写卡基线失败", "card", id, "branch", *body.BaseBranch, "cause", err)
			ledgerErr(w, err)
			return
		}
		s.log.Info("已写卡基线", "card", id, "branch", *body.BaseBranch, "actor", actor)
	}
	writeJSON(w, http.StatusOK, map[string]any{"ok": true})
}

n_agentd_Server_handleCardStep.signature:
// handleCardStep 受理一个卡节点，受理即 202；202 不代表回合已完成。
//
// 规范 CLI 请求必须带非空 actor；旧看板只发送 {"step":...}，仅在原始 JSON
// 缺少 actor 键时补 web:<r.RemoteAddr>。显式 actor:"" 不能借 fallback 进入驱动锁。
// JSON 对**未知字段**宽松（忽略，避免版本错配把新可选字段变成 400），但对**尾随
// 内容**严格：整段读进来用 json.Unmarshal 解，多出的字节一律 400。Decoder.Decode
// 只吃第一个 JSON 值，被截断又重发的请求体会被它当成合法请求受理——而受理是有
// 副作用的（取得运行锁、派任务），不能建立在只看了前半句上。
//
// 受理前只做四件事：解出规范请求、校验 step/actor 非空、拒掉要求内联本地文件的
// 请求、确认卡与节点都解得开（卡不存在 404，节点名不对 400）。其余一切——门是否
// 放行、目标机是否够得着、回合是否超轮——都在后台 goroutine 里由 StepRunner 判定，
// 结果落卡的事件流。
func (s *Server) handleCardStep(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")

	payload, err := io.ReadAll(io.LimitReader(r.Body, maxCardStepBody+1))
	if err != nil {
		s.log.Warn("卡节点请求读取失败", "card", id, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "bad json"})
		return
	}
	if len(payload) > maxCardStepBody {
		s.log.Warn("卡节点请求被拒：请求体超限", "card", id, "limit", maxCardStepBody)
		writeJSON(w, http.StatusRequestEntityTooLarge, map[string]string{
			"error": fmt.Sprintf("card step 请求体超过 %d 字节", maxCardStepBody),
		})
		return
	}
	// 两次解同一段字节：raw 只用来区分「actor 键缺席」与「显式空串」，req 是规范请求。
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(payload, &raw); err != nil {
		s.log.Warn("卡节点请求解码失败", "card", id, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "bad json"})
		return
	}
	var req proto.CardStepReq
	if err := json.Unmarshal(payload, &req); err != nil {
		s.log.Warn("卡节点请求字段解码失败", "card", id, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "bad json"})
		return
	}
	if _, ok := raw["actor"]; !ok {
		req.Actor = "web:" + hostOnly(r.RemoteAddr)
		s.log.Info("legacy 卡节点请求补 actor", "card", id, "node", req.Step,
			"actor", req.Actor, "remote_addr", r.RemoteAddr)
	}
	if req.Step == "" {
		s.log.Warn("卡节点请求被拒：step 为空", "card", id)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "step 不能为空"})
		return
	}
	if req.Actor == "" {
		s.log.Warn("卡节点请求被拒：actor 为空", "card", id, "node", req.Step)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "actor 不能为空"})
		return
	}
	card, err := s.ledger.GetCard(id)
	if err != nil {
		s.log.Warn("卡节点请求读取席位失败", "card", id, "node", req.Step, "actor", req.Actor, "cause", err)
		ledgerErr(w, err)
		return
	}
	if card.DriverSession != "" || card.DriverSource != "" {
		if req.Actor != card.DriverSession {
			err := fmt.Errorf("卡 %s 当前席位要求出示 %q", id, card.DriverSession)
			s.log.Warn("卡节点请求被拒：席位 actor 不匹配", "card", id, "node", req.Step,
				"actor", req.Actor, "has_seat", true, "cause", err)
			writeJSON(w, http.StatusForbidden, map[string]string{"error": err.Error()})
			return
		}
		s.log.Info("卡节点席位出示通过", "card", id, "node", req.Step, "actor", req.Actor)
	}
	if requiresInlineLocalFile(req) {
		s.log.Warn("卡节点请求被拒：要求内联本地文件", "card", id, "node", req.Step,
			"actor", req.Actor)
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": "card step 不接受调用方本地文件",
		})
		return
	}
	if _, err := ledgerstep.ResolveNode(s.ledger, id, req.Step); err != nil {
		s.log.Warn("卡节点请求被拒：卡或节点解不开", "card", id, "node", req.Step,
			"actor", req.Actor, "cause", err)
		if errors.Is(err, ledger.ErrNotFound) {
			ledgerErr(w, err)
			return
		}
		writeErr(w, http.StatusBadRequest, err)
		return
	}
	s.log.Info("开始装配卡节点", "card", id, "node", req.Step, "actor", req.Actor,
		"target", req.Target, "executor", req.Executor, "model", req.Model,
		"has_extra", strings.TrimSpace(req.Extra) != "")
	err = s.startCardStep(id, req)
	switch {
	case err == nil:
		writeJSON(w, http.StatusAccepted, map[string]bool{"ok": true})
	case errors.Is(err, errStepInFlight):
		s.log.Warn("节点被拒：已有在飞", "card", id, "node", req.Step,
			"actor", req.Actor, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, ledger.ErrNotFound):
		s.log.Warn("卡节点所属卡不存在", "card", id, "node", req.Step, "cause", err)
		ledgerErr(w, err)
	default:
		s.log.Warn("节点被拒", "card", id, "node", req.Step, "actor", req.Actor, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	}
}

n_agentd_Server_handleCardsList.signature:
func (s *Server) handleCardsList(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	views, err := s.ledger.ListCards(ledger.CardFilter{
		Project:		q.Get("project"),
		Status:			q.Get("status"),
		BaseBranch:		q.Get("base_branch"),
		Needs:			q.Get("needs") == "1",
		Blocked:		q.Get("blocked") == "1",
		IncludeTerminal:	q.Get("all") == "1",
	})
	if err != nil {
		ledgerErr(w, err)
		return
	}
	tickets, err := s.ledger.OpenTicketCounts()
	if err != nil {
		s.log.Warn("未决工单推导失败（徽标退化为不显示，不阻塞列表）", "err", err)
		tickets = nil
	}
	runLocks, lockErr := s.ledger.AllRunLocks()
	if lockErr != nil {
		s.log.Warn("运行锁批量读取失败（冲突徽标退化为不显示，不阻塞列表）", "err", lockErr)
		runLocks = nil
	}
	activeLock := make(map[string]struct{}, len(runLocks))
	now := time.Now()
	for _, lock := range runLocks {
		if lock.ExpiresAt.After(now) {
			activeLock[lock.CardID] = struct{}{}
		}
	}
	out := make([]proto.CardView, 0, len(views))
	for _, view := range views {
		conflict := false
		if _, locked := activeLock[view.ID]; locked {
			states, stateErr := s.ledger.LatestTaskStates(view.ID)
			if stateErr == nil {
				for _, state := range states {
					if state.LastType == "failed" {
						conflict = true
						break
					}
				}
			}
		}
		out = append(out, ledgerCardViewWire(view, conflict, tickets[view.ID]))
	}
	writeJSON(w, http.StatusOK, map[string]any{
		"cards":	out,
		"unlinked":	s.unlinkedSummary(),
	})
}

n_agentd_Server_handleCarrierDelete.signature:
// handleCarrierDelete DELETE /api/squads/carriers/{name}?expect=N：以 CAS 删除未入队载体。
// expect 必填，缺席一律 400。仍在小队中的载体拒绝删除（400），不存在返回 404，版本冲突返回 409。
func (s *Server) handleCarrierDelete(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	expect, ok, err := expectVersion(r)
	if !ok {
		s.log.Warn("删除载体 expect 校验未过", "name", name, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("删除载体", "name", name, "expect", expect)
	if err := s.scheduling.DeleteCarrier(name, expect); err != nil {
		s.schedDeleteErr(w, name, err)
		return
	}
	s.log.Info("删除载体成功", "name", name, "expect", expect)
	writeJSON(w, http.StatusOK, proto.SquadPutResp{Name: name, Version: expect})
}

n_agentd_Server_handleCarrierDetect.signature:
// handleCarrierDetect POST /api/squads/carriers/{name}/detect：检测写状态。
// 协调机持有 registry，本端点不整段 forwardIfRequested；本机或目标机只负责
// WakeHome，ApplyDetect 始终回到协调机写状态。
func (s *Server) handleCarrierDetect(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	carrier, err := s.scheduling.Carrier(name)
	if err != nil {
		if errors.Is(err, scheduling.ErrNotFound) {
			writeErr(w, http.StatusNotFound, err)
			return
		}
		s.log.Error("读载体失败", "name", name, "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	if s.hostAPI == nil {
		err := fmt.Errorf("载体 %s 的 hostapi 未装配", name)
		s.log.Error("载体检测失败", "name", name, "machine", carrier.Machine, "cause", err)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("检测载体开始", "name", name, "machine", carrier.Machine, "path", r.URL.Path)
	var wake proto.HomeWakeResp
	if isLocalMachine(carrier.Machine) {
		reply, wakeErr := s.hostAPI.WakeHome(r.Context(), hostapi.WakeRequest{
			CLI:	carrier.CLI, HomeDir: carrier.HomeDir, Credential: string(carrier.Credential), Model: carrier.Model,
		})
		if wakeErr != nil {
			s.log.Error("本机载体唤起失败", "name", name, "machine", carrier.Machine, "cause", wakeErr)
			s.hostProbeErr(w, wakeErr)
			return
		}
		wake = proto.HomeWakeResp{Outcome: string(reply.Outcome), Detail: reply.Detail}
	} else {
		target, ok := s.conf().Targets[carrier.Machine]
		if !ok {
			err := fmt.Errorf("载体 %s 的机器 %q 未在 targets 中定义", name, carrier.Machine)
			s.log.Error("远程载体检测失败：目标未定义", "name", name, "machine", carrier.Machine, "cause", err)
			writeErr(w, http.StatusBadGateway, err)
			return
		}
		targetClient, poolErr := s.pool.For(carrier.Machine)
		if poolErr != nil {
			s.log.Error("远程载体检测失败：目标客户端不可用", "name", name, "machine", carrier.Machine, "cause", poolErr)
			writeErr(w, http.StatusBadGateway, poolErr)
			return
		}
		body, marshalErr := json.Marshal(proto.HomeWakeReq{
			CLI:	carrier.CLI, HomeDir: carrier.HomeDir, Credential: string(carrier.Credential), Model: carrier.Model,
		})
		if marshalErr != nil {
			s.log.Error("远程载体检测失败：编码唤起请求", "name", name, "machine", carrier.Machine, "cause", marshalErr)
			writeErr(w, http.StatusInternalServerError, marshalErr)
			return
		}
		forwardReq := r.Clone(r.Context())
		u := *r.URL
		u.Path, u.RawPath, u.RawQuery = "/api/host/wake", "", ""
		forwardReq.URL = &u
		status, headers, payload, forwardErr := s.forwardJSON(forwardReq, carrier.Machine,
			targetClient, target.Token, body)
		if forwardErr != nil {
			s.log.Error("远程载体检测失败：转发唤起", "name", name, "machine", carrier.Machine, "cause", forwardErr)
			writeErr(w, http.StatusBadGateway, forwardErr)
			return
		}
		if status < http.StatusOK || status >= http.StatusMultipleChoices {
			s.log.Warn("远程载体检测收到唤起错误", "name", name, "machine", carrier.Machine, "status", status)
			copyForwardHeaders(w, headers)
			w.WriteHeader(status)
			if _, err := w.Write(payload); err != nil {
				s.log.Warn("回送远程检测错误失败", "name", name, "machine", carrier.Machine, "status", status, "cause", err)
			}
			return
		}
		if err := json.Unmarshal(payload, &wake); err != nil {
			s.log.Error("远程载体检测失败：唤起响应解码", "name", name, "machine", carrier.Machine, "cause", err)
			writeErr(w, http.StatusBadGateway, fmt.Errorf("目标唤起响应无法解析: %w", err))
			return
		}
	}
	ev, ok := detectEvidence(wake.Outcome)
	if !ok {
		err := fmt.Errorf("载体 %s 的 wake outcome %q 未知", name, wake.Outcome)
		s.log.Error("载体检测失败：未知唤起结果", "name", name, "machine", carrier.Machine,
			"outcome", wake.Outcome, "cause", err)
		writeErr(w, http.StatusBadGateway, err)
		return
	}
	c, err := s.scheduling.ApplyDetect(name, ev, wake.Detail)
	if err != nil {
		if errors.Is(err, scheduling.ErrDetectUnwired) {
			s.log.Warn("载体检测尚未接线", "name", name, "machine", carrier.Machine, "outcome", wake.Outcome)
			writeErr(w, http.StatusServiceUnavailable, err)
			return
		}
		s.log.Error("载体检测写状态失败", "name", name, "machine", carrier.Machine,
			"outcome", wake.Outcome, "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	rows, rowsErr := s.scheduling.CarrierRows()
	if rowsErr != nil {
		s.log.Error("载体检测读取新版本失败", "name", name, "machine", carrier.Machine, "cause", rowsErr)
		writeErr(w, http.StatusInternalServerError, rowsErr)
		return
	}
	version := 0
	for _, row := range rows {
		if row.Carrier.Name == name {
			version = row.Version
			break
		}
	}
	if version == 0 {
		err := fmt.Errorf("载体 %s 检测写入后无法读取版本", name)
		s.log.Error("载体检测版本缺失", "name", name, "machine", carrier.Machine, "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	s.log.Info("载体检测完成", "name", name, "machine", carrier.Machine,
		"outcome", wake.Outcome, "status", c.Status, "version", version)
	writeJSON(w, http.StatusOK, proto.CarrierDetectResp{
		Name:	c.Name, Status: string(c.Status), LastError: c.LastError,
		Version:	version,
	})
}

n_agentd_Server_handleCarrierPut.signature:
// handleCarrierPut PUT /api/squads/carriers/{name}?expect=N：以 CAS 写载体。
// expect 必填（0=新建），缺席一律 400——「没带就当 0」会把更新静默变新建。
func (s *Server) handleCarrierPut(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	expect, ok, err := expectVersion(r)
	if !ok {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	var in proto.CarrierInput
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("解析请求体: %v", err)})
		return
	}
	if in.Name != "" && in.Name != name {
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("请求体 name %q 与路径 %q 不一致", in.Name, name)})
		return
	}
	carrier := scheduling.Carrier{
		Name:	name, Machine: in.Machine, CLI: in.CLI, HomeDir: in.HomeDir,
		Model:	in.Model, Credential: scheduling.CredentialSource(in.Credential),
		MaxConcurrency:	in.MaxConcurrency,
	}
	s.log.Info("登记载体", "name", name, "expect", expect,
		"machine", in.Machine, "cli", in.CLI)
	if err := s.scheduling.PutCarrier(carrier, expect); err != nil {
		s.schedPutErr(w, "载体", name, err)
		return
	}
	writeJSON(w, http.StatusOK, proto.SquadPutResp{Name: name, Version: expect + 1})
}

n_agentd_Server_handleCarrierRunCommand.signature:
