// handleDeleteMachine 处理 DELETE /api/machines/{name}。
//
// 状态码：
//   - 404 该名字不存在
//   - 500 落盘失败
//
// 注意：删除只改本机配置里的 targets，**不去动对端**——对端 agentd 与其
// 上正在跑的任务与本操作无关，删的只是「本机记得这台机器」这件事。
func (s *Server) handleDeleteMachine(w http.ResponseWriter, r *http.Request) {
