n_agentd_Server_handleDisciplineGet.signature:
// handleDisciplineGet 处理 GET /api/discipline[?machine=]。
//
// 响应：
//   - 200 proto.DisciplineResp：Builtins/Files 恒为空数组（类型保留防 TS 断裂）；
//     Bindings 照常反映机器级映射（③层语义本轮不动）
//   - 503：manager 未就绪（与 dispatch 等路由同款：executor 名单来自 manager）
func (s *Server) handleDisciplineGet(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	s.log.Info("纪律配置查询请求", "method", r.Method, "path", r.URL.Path)
	if s.mgr == nil {
		s.log.Warn("纪律配置查询：manager 未就绪")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	resp := proto.DisciplineResp{

		Dir:		"",
		Builtins:	[]proto.DisciplineBuiltin{},
		Files:		[]proto.DisciplineFile{},
		Bindings:	s.disciplineBindings(),
	}
	s.log.Info("纪律配置查询完成", "bindings", len(resp.Bindings))
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleDisciplineMapping.signature:
// handleDisciplineMapping 处理 PUT /api/discipline/mapping[?machine=]。
//
// 请求体 proto.DisciplineMappingReq：**整段替换**该机的 discipline 配置段。
//
// 响应：200 proto.DisciplineResp（保存后的最新状态，界面直接拿它刷新）
//
//	400 mode 非法 / executor 为空 / file 档指向不存在的文件
//	503 manager 未就绪
//
// 为什么仍要校验「file 档的文件必须存在」（B229 后）：映射的派发消费方已随
// Resolver 一起退役，但保存语义不动意味着既有承诺原样保留——存进去的东西必须
// 当下真实存在，不许借机放宽。注意这只是保存时的一次性校验。
func (s *Server) handleDisciplineMapping(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	if s.mgr == nil {
		s.log.Warn("纪律映射保存：manager 未就绪")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req proto.DisciplineMappingReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("纪律映射保存：请求体无法解析", "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体不是合法 JSON"})
		return
	}
	dir := legacyDisciplineFilePath(s.conf().DataDir, "")
	s.log.Info("纪律映射保存请求", "bindings", len(req.Bindings), "dir", dir)

	next := map[string]string{}
	for _, b := range req.Bindings {
		name := strings.TrimSpace(b.Executor)
		if name == "" {
			s.log.Warn("纪律映射保存被拒：executor 名为空", "cause", "executor 名不能为空")
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "executor 名不能为空"})
			return
		}
		switch b.Mode {
		case proto.DisciplineModeDefault:

		case proto.DisciplineModeOff:
			next[name] = ""
		case proto.DisciplineModeFile:
			file := strings.TrimSpace(b.File)
			if verr := validateLegacyDisciplineFileName(file); verr != nil {
				s.log.Warn("纪律映射保存被拒：文件名非法", "executor", name, "file", file, "cause", verr)
				writeJSON(w, http.StatusBadRequest, map[string]string{
					"error": fmt.Sprintf("%s 指定的纪律块文件不可用：%v", name, verr)})
				return
			}
			path := legacyDisciplineFilePath(s.conf().DataDir, file)

			if _, err := os.Stat(path); err != nil {
				werr := err
				if errors.Is(err, os.ErrNotExist) {
					werr = fmt.Errorf("纪律块文件 %s 不存在", path)
				}
				s.log.Warn("纪律映射保存被拒：文件不可用", "executor", name, "file", file, "cause", werr)
				writeJSON(w, http.StatusBadRequest, map[string]string{
					"error": fmt.Sprintf("%s 指定的纪律块文件不可用：%v", name, werr)})
				return
			}
			next[name] = file
		default:
			s.log.Warn("纪律映射保存被拒：档位非法", "executor", name, "mode", b.Mode,
				"cause", "只支持 default/file/off")
			writeJSON(w, http.StatusBadRequest, map[string]string{
				"error": fmt.Sprintf("%s 的档位 %q 非法：只支持 default/file/off", name, b.Mode)})
			return
		}
	}
	if err := s.swapConf(func(c *config.Config) error {
		c.Discipline = next
		return nil
	}); err != nil {
		s.log.Error("纪律映射落盘失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("纪律映射已保存", "configured", len(next))
	s.handleDisciplineGet(w, r)
}

n_agentd_Server_handleDisciplineNames.signature:
// handleDisciplineNames 列出可选的纪律块名：账本 disciplines 聚合的全部名字。
//
// 给节点配置的下拉用。返回去重升序的名字列表，不带正文——正文有专门的
// 读写接口，列表接口没必要驮着几十 KB。
//
// B229 起权威副本在账本：内置角色清单与 <DataDir>/discipline 磁盘文件都已退役，
// 下拉只反映账本现状（ListDisciplineNames）。账本读不了就如实 500——
// 它是纪律块的必需品，静默空清单会让用户以为没有可选项。
func (s *Server) handleDisciplineNames(w http.ResponseWriter, r *http.Request) {
	names, err := s.ledger.ListDisciplineNames()
	if err != nil {
		s.log.Error("列纪律块名失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("列出纪律块名", "count", len(names))
	writeJSON(w, http.StatusOK, map[string]any{"names": names})
}

n_agentd_Server_handleDispatch.signature:
// handleDispatch 派发一个新任务，返回创建后的任务（state=running）。
//
// 流程：解析请求体 → 冻结身份准入或普通接收者准备链 → manager.Dispatch
// （建任务/写 plan/启动 executor/进 running）。带 Carrier 的请求必须使用已冻结的
// 物理身份；Receiver 只作为审计字段，不能再次选择载体。
func (s *Server) handleDispatch(w http.ResponseWriter, r *http.Request) {
	s.log.Info("dispatch 请求", "method", r.Method, "path", r.URL.Path,
		"remote_addr", r.RemoteAddr)
	if s.mgr == nil {
		s.log.Warn("dispatch 请求到达但 manager 未注入", "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req dispatchRequest
	if err := json.NewDecoder(io.LimitReader(r.Body, 4<<20)).Decode(&req); err != nil {
		s.log.Warn("dispatch 请求体解析失败", "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {project_id, plan_b64, ...}"})
		return
	}
	s.log.Info("dispatch 请求身份", "project", req.ProjectID, "receiver", req.Receiver,
		"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
		"executor", req.Executor, "model", req.Model, "home_dir_set", req.HomeDir != nil)
	var binding scheduling.Binding
	var resolved scheduling.ResolvedReceiver
	var err error
	if req.Carrier != "" {
		if s.scheduling == nil {
			err = errors.New("编制域服务未装配（SetupAutomation 未执行）")
		} else if req.HomeDir == nil {
			err = fmt.Errorf("%w: 冻结请求必须明确携带 home_dir（空串表示目标机主 HOME）", scheduling.ErrInvalid)
			s.log.Warn("dispatch 冻结身份缺少 home_dir", "project", req.ProjectID,
				"receiver", req.Receiver, "carrier", req.Carrier, "squad", req.Squad,
				"target", req.Target, "error_kind", "frozen_home_dir_missing", "cause", err)
		} else {
			homeDir := *req.HomeDir
			binding, err = s.scheduling.AdmitFrozen(scheduling.Binding{
				Squad:	req.Squad, Carrier: req.Carrier, Target: req.Target,
				Executor:	req.Executor, Model: req.Model, HomeDir: homeDir,
			})
			s.log.Info("dispatch 冻结身份准入", "project", req.ProjectID, "receiver", req.Receiver,
				"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
				"executor", req.Executor, "model", req.Model, "error_kind", "frozen_admit")
		}
	} else if req.Squad != "" {
		err = fmt.Errorf("%w: 冻结小队请求缺少 carrier", scheduling.ErrInvalid)
	} else {
		overlay := scheduling.PhysicalOverlay{Machine: req.Target, CLI: req.Executor, HomeDir: req.HomeDir}
		binding, resolved, err = s.prepareReceiverBinding(req.Receiver, overlay, req.Model)
		s.log.Info("dispatch 普通身份准入", "project", req.ProjectID, "receiver", req.Receiver,
			"resolved_name", resolved.Name, "resolved_kind", string(resolved.Kind),
			"carrier", binding.Carrier, "squad", binding.Squad, "target", binding.Target,
			"executor", binding.Executor, "model", binding.Model, "error_kind", "ordinary_admit")
	}
	if err != nil {
		s.log.Warn("dispatch 身份准入失败", "project", req.ProjectID, "receiver", req.Receiver,
			"carrier", req.Carrier, "squad", req.Squad, "target", req.Target,
			"error_kind", "admit", "cause", err)
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	released := false
	defer func() {
		if !released && binding.Carrier != "" && s.scheduling != nil {
			if relErr := s.scheduling.Release(binding.Squad, binding.Carrier); relErr != nil {
				s.log.Error("dispatch 失败释放占用失败", "project", req.ProjectID,
					"squad", binding.Squad, "carrier", binding.Carrier, "cause", relErr)
			}
		}
	}()
	home := binding.HomeDir
	var homePtr *string
	if req.Carrier != "" || home != "" {
		homePtr = &home
	}
	s.log.Info("dispatch 任务身份快照已组装", "project", req.ProjectID,
		"carrier", binding.Carrier, "squad", binding.Squad, "target", binding.Target,
		"executor", binding.Executor, "home_dir_set", homePtr != nil)
	task, err := s.mgr.Dispatch(r.Context(), DispatchReq{
		ProjectID:	req.ProjectID, ProjectName: req.ProjectName,
		PlanB64:	req.PlanB64, PlanName: req.PlanName, Target: binding.Target,
		Prompt:	req.Prompt, Name: req.Name, Receiver: req.Receiver, Squad: binding.Squad, Carrier: binding.Carrier,
		Executor:	binding.Executor, Discipline: req.Discipline, Model: binding.Model,
		HomeDir:		homePtr,
		DisciplineText:		req.DisciplineText,
		DisciplineVersion:	req.DisciplineVersion,
		Branch:			req.Branch, NewBranch: req.NewBranch, Base: req.Base,
		ResolveDefaultBase:	req.ResolveDefaultBase,
		LocalBaseBranch:	req.LocalBaseBranch,
		Worktree:		req.Worktree, NewWorktree: req.NewWorktree, BaseCommit: req.BaseCommit,
	})
	if err != nil {
		s.writeDispatchError(w, req.ProjectID, err)
		return
	}
	released = true
	s.log.Info("dispatch 完成", "task", task.ID, "state", task.State, "carrier", task.Carrier,
		"squad", binding.Squad, "target", binding.Target, "executor", binding.Executor)
	writeJSON(w, http.StatusOK, task)
}

n_agentd_Server_handleDone.signature:
// handleDone 归档任务（要求任务处于 waiting_review）：置 completed 并回收 executor。
func (s *Server) handleDone(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("done 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	if s.mgr == nil {
		s.log.Warn("done 请求到达但 manager 未注入", "task", taskID)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	// body 缺失或非法一律按「无说明」处理，不报错（见 doneRequest 注释）
	var req doneRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil && !errors.Is(err, io.EOF) {
		s.log.Debug("done 请求体解析失败，按无说明处理", "task", taskID, "cause", err)
		req.Note = ""
	}
	if len(req.Note) > proto.MaxDoneNoteBytes {
		s.log.Warn("归档说明超长被拒", "task", taskID,
			"note_bytes", len(req.Note), "limit", proto.MaxDoneNoteBytes)
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("归档说明超长（%d 字节，上限 %d）", len(req.Note), proto.MaxDoneNoteBytes)})
		return
	}

	if cur, err := s.st.GetTask(taskID); err == nil && cur.State == proto.TaskStateCompleted {
		s.log.Info("done 已幂等完成，跳过重复释放", "task", taskID, "state", cur.State,
			"carrier", cur.Carrier, "squad", cur.Squad, "error_kind", "already_completed")
		writeJSON(w, http.StatusOK, doneResult{OK: true, NoteSaved: req.Note != ""})
		return
	}
	cur, taskErr := s.st.GetTask(taskID)
	if taskErr != nil {
		s.log.Error("done 读取任务快照失败，未执行终态迁移", "task", taskID, "cause", taskErr)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "读取任务快照失败"})
		return
	}
	outcome, err := s.mgr.Done(r.Context(), taskID, req.Note)
	if err != nil {
		s.writeManagerError(w, taskID, "归档任务", err)
		return
	}
	if !outcome.Claimed {

		s.log.Info("done 幂等成功，跳过占用释放", "task", taskID)
		writeJSON(w, http.StatusOK, doneResult{OK: true, NoteSaved: req.Note != ""})
		return
	}
	terminal, snapshotErr := s.st.GetTask(taskID)
	if snapshotErr != nil {

		s.log.Error("done 成功后读取终态任务快照失败，使用迁移前身份快照释放占用",
			"task", taskID, "cause", snapshotErr)
		s.releaseTaskCarrierOccupancy(cur)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "任务已归档但读取终态快照失败"})
		return
	}
	s.releaseTaskCarrierOccupancy(terminal)

	s.log.Info("done 请求完成", "task", taskID, "note_saved", req.Note != "")
	writeJSON(w, http.StatusOK, doneResult{OK: true, NoteSaved: req.Note != ""})
}

n_agentd_Server_handleEnvFileRead.signature:
// handleEnvFileRead 处理 GET /api/env/file?name=[&machine=]。
//
// 响应：200 proto.FileRead / 400 名字非法 / 404 文件不存在。
//
// **这条会把含值的全文交给浏览器**，且这是刻意的——不然没法编辑。默认视图
// 走 keys 端点；界面只在用户点「编辑正文」时调这条。spec §7 已写明这条边界：
// 掩码防的是肩窥、截图、录屏、整页粘贴，不是防浏览器本身，更不是加密。
func (s *Server) handleEnvFileRead(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	name := r.URL.Query().Get("name")
	dir := envfile.Dir(s.conf().DataDir)
	s.log.Info("env 读文件请求（含值全文）", "dir", dir, "name", name)

	content, sha, size, err := envfile.Read(dir, name)
	if err != nil {
		s.writeEnvReadError(w, dir, name, err)
		return
	}
	s.log.Info("env 读文件完成", "dir", dir, "name", name, "bytes", size, "sha256", shortHash(sha))
	writeJSON(w, http.StatusOK, proto.FileRead{Content: content, Size: size, SHA256: sha})
}

n_agentd_Server_handleEnvFileWrite.signature:
// handleEnvFileWrite 处理 PUT /api/env/file?name=[&machine=]。
//
// 请求体 proto.FileWriteReq：base_sha256 为空串 = 新建（目标必须不存在）。
//
// 响应：200 FileWriteResp / 400 名字非法、超限或**语法错误** / 409 撞名或冲突
// （带磁盘现状）/ 404 目标在编辑期间被删。
//
// **写前必须解析**（与纪律块的唯一实质差异）：纪律块写错了模型顶多读到一段
// 怪话；env 写错了，症状是「代理配了但连不上」「go test 突然全红」，离根因
// 十万八千里。Parse 已经能产出带行号的错误，白不用。
//
// 重复键**不拦**：Resolver 的既有行为是 WARN + 后者覆盖，界面照此标注即可。
func (s *Server) handleEnvFileWrite(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	name := r.URL.Query().Get("name")
	dir := envfile.Dir(s.conf().DataDir)

	var req proto.FileWriteReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("env 写文件请求体解析失败", "name", name)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体不是合法 JSON"})
		return
	}

	s.log.Info("env 写文件请求", "dir", dir, "name", name,
		"bytes", len(req.Content), "base", shortHash(req.BaseSHA256))

	if _, _, perr := envfile.Parse(bytes.NewReader([]byte(req.Content)), nil); perr != nil {
		s.log.Warn("env 写文件被拒：语法错误", "dir", dir, "name", name, "bytes", len(req.Content))
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": perr.Error()})
		return
	}

	sha, size, err := envfile.Write(dir, name, req.Content, req.BaseSHA256)
	if err != nil {
		switch {
		case errors.Is(err, envfile.ErrBadName), errors.Is(err, envfile.ErrTooLarge):
			s.log.Warn("env 写文件被拒", "name", name, "bytes", len(req.Content))
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		case errors.Is(err, envfile.ErrExists):
			s.log.Warn("env 写文件被拒：撞名", "dir", dir, "name", name)
			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
		case errors.Is(err, envfile.ErrBaseMismatch):

			cur, curSHA, curSize, rerr := envfile.Read(dir, name)
			if rerr != nil {
				s.log.Error("env 写文件冲突后读现状失败", "name", name)
				writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
				return
			}
			s.log.Warn("env 写文件冲突", "dir", dir, "name", name,
				"base", shortHash(req.BaseSHA256), "current", shortHash(curSHA))
			writeJSON(w, http.StatusConflict, proto.FileConflictResp{
				Error:		"env 文件已被改动",
				Current:	proto.FileRead{Content: cur, Size: curSize, SHA256: curSHA},
			})
		case errors.Is(err, fs.ErrNotExist):
			s.log.Warn("env 写文件：目标在编辑期间被删", "dir", dir, "name", name)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "env 文件不存在"})
		default:
			s.log.Error("env 写文件失败", "dir", dir, "name", name)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "写入 env 文件失败"})
		}
		return
	}
	s.log.Info("env 写文件完成", "dir", dir, "name", name, "bytes", size, "sha256", shortHash(sha))
	writeJSON(w, http.StatusOK, proto.FileWriteResp{SHA256: sha, Size: size})
}

n_agentd_Server_handleEnvGet.signature:
// handleEnvGet 处理 GET /api/env[?machine=]。
//
// 响应：
//   - 200 proto.EnvResp
//   - 503：manager 未就绪（与 dispatch 等路由同款：executor 名单来自 manager）
func (s *Server) handleEnvGet(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	s.log.Info("env 配置查询请求", "method", r.Method, "path", r.URL.Path)
	if s.mgr == nil {
		s.log.Warn("env 配置查询：manager 未就绪")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	dir := envfile.Dir(s.conf().DataDir)
	files, err := envfile.List(dir)
	if err != nil {
		s.log.Error("env 配置查询：列举文件失败", "dir", dir, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	resp := proto.EnvResp{
		Dir:		dir,
		Files:		make([]proto.EnvFile, 0, len(files)),
		Bindings:	s.envBindings(),
	}
	for _, f := range files {
		resp.Files = append(resp.Files, proto.EnvFile{Name: f.Name, Size: f.Size, SHA256: f.SHA256})
	}
	s.log.Info("env 配置查询完成", "dir", dir, "files", len(resp.Files), "bindings", len(resp.Bindings))
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleEnvKeys.signature:
// handleEnvKeys 处理 GET /api/env/file/keys?name=[&machine=]。
//
// 响应：200 proto.EnvKeysResp / 400 名字非法或**语法错误** / 404 文件不存在。
//
// 这是 Env 分区的默认视图，也是 spec §7 凭据边界的落点：**响应结构里没有
// 任何字段承载值**，只有 key 名、值的字节长度与重复标记。日常最高频的问题
// 是「这台机给某个 executor 注了哪些变量」，回答它不需要看见任何一个值。
//
// 注意：Parse 的 lookup 传 **nil**。展开时不查 agentd 自己的环境变量——否则
// 同一个文件在不同机器上会显示出不同的值长度，既误导又多泄露一层信息。
// 引用了外部变量的值因此会显示为 0，这是刻意的，不是 bug。
func (s *Server) handleEnvKeys(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	name := r.URL.Query().Get("name")
	dir := envfile.Dir(s.conf().DataDir)
	s.log.Info("env 变量清单请求", "dir", dir, "name", name)

	content, _, size, err := envfile.Read(dir, name)
	if err != nil {
		s.writeEnvReadError(w, dir, name, err)
		return
	}
	kvs, dups, err := envfile.Parse(bytes.NewReader([]byte(content)), nil)
	if err != nil {

		s.log.Warn("env 变量清单：解析失败", "dir", dir, "name", name, "bytes", size)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	dupSet := make(map[string]bool, len(dups))
	for _, k := range dups {
		dupSet[k] = true
	}
	resp := proto.EnvKeysResp{Keys: make([]proto.EnvKey, 0, len(kvs))}
	for _, kv := range kvs {
		resp.Keys = append(resp.Keys, proto.EnvKey{
			Key:	kv.Key, ValueBytes: len(kv.Value), Duplicate: dupSet[kv.Key],
		})
	}

	s.log.Info("env 变量清单完成", "dir", dir, "name", name,
		"keys", len(resp.Keys), "dups", len(dups), "bytes", size)
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleEnvMapping.signature:
// handleEnvMapping 处理 PUT /api/env/mapping[?machine=]。
//
// 请求体 proto.EnvMappingReq：**整段替换**该机的 env 配置段。
//
// 响应：200 proto.EnvResp（保存后的最新状态，界面直接拿它刷新）
//
//	400 mode 非法 / executor 为空 / file 档文件名为空或指向不存在的文件
//	503 manager 未就绪
//
// **两档翻译（与 discipline 错位，照抄必错）**：
//
//	off  → 配置里**删掉这个键**（不是写空串！空串会让 Resolver 走到「读
//	     <dir>/」这种无意义路径，是纯粹的脏数据）
//	file → 校验文件存在后写入文件名
//
// 为什么要校验「file 档的文件必须存在」：Resolver 的既定语义是「配了但读不到
// = 派发失败」。把错误挡在保存这一刻，好过让它在三天后某次派发时炸出来。
// 注意这只是保存时的一次性校验——文件仍可能事后被删，那时的失败仍由派发路径承担。
func (s *Server) handleEnvMapping(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	if s.mgr == nil {
		s.log.Warn("env 映射保存：manager 未就绪")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req proto.EnvMappingReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("env 映射保存：请求体无法解析")
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体不是合法 JSON"})
		return
	}
	dir := envfile.Dir(s.conf().DataDir)
	s.log.Info("env 映射保存请求", "bindings", len(req.Bindings), "dir", dir)

	next := map[string]string{}
	for _, b := range req.Bindings {
		name := strings.TrimSpace(b.Executor)
		if name == "" {
			s.log.Warn("env 映射保存被拒：executor 名为空")
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "executor 名不能为空"})
			return
		}
		switch b.Mode {
		case proto.EnvModeOff:

		case proto.EnvModeFile:
			file := strings.TrimSpace(b.File)
			if file == "" {
				s.log.Warn("env 映射保存被拒：file 档文件名为空", "executor", name)
				writeJSON(w, http.StatusBadRequest, map[string]string{
					"error": fmt.Sprintf("%s 选了「指定文件」但没给文件名", name)})
				return
			}
			if _, _, _, err := envfile.Read(dir, file); err != nil {
				s.log.Warn("env 映射保存被拒：文件不可用", "executor", name, "file", file)
				writeJSON(w, http.StatusBadRequest, map[string]string{
					"error": fmt.Sprintf("%s 指定的 env 文件不可用：%v", name, err)})
				return
			}
			next[name] = file
		default:
			s.log.Warn("env 映射保存被拒：档位非法", "executor", name, "mode", b.Mode)
			writeJSON(w, http.StatusBadRequest, map[string]string{
				"error": fmt.Sprintf("%s 的档位 %q 非法：只支持 file/off", name, b.Mode)})
			return
		}
	}
	if err := s.swapConf(func(c *config.Config) error {
		c.Env = next
		return nil
	}); err != nil {
		s.log.Error("env 映射落盘失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("env 映射已保存", "configured", len(next))
	s.handleEnvGet(w, r)
}

n_agentd_Server_handleEvents.signature:
// handleEvents 处理 /ws/events：先订阅 hub 实时流，再补发 store 中 seq>from_seq 的
// 历史事件；排空器 goroutine 在整个连接生命周期内持续消费订阅通道，主循环按批次
// 归并（按 seq 升序、去重）后写出。
//
// 参数：
//   - task: 任务 ID（必填）
//   - from_seq: 起始 seq（不含，默认 0）；客户端自存 cursor，重连时带最后收到的 seq 即可补齐断线事件
//
// 注意：
//   - 客户端只读不写：CloseRead 接管读侧（响应 ping/pong/close 帧），其返回的 ctx 在
//     连接关闭时取消，作为写循环的退出信号，避免空闲断连连接泄漏订阅
//   - **为什么先订阅后补发**：重放写循环可能因 TCP 背压阻塞任意久，若先重放后订阅，
//     窗口期内 Publish 的事件订阅者为零、被 hub 直接丢弃。丢的是 question/
//     permission_request 这类一次性唤醒事件：任务随即进入 waiting_answer 不再产出
//     事件，客户端连接健康不会重连（WaitEvent 只在连接出错时重连），协调者永远
//     不被唤醒，executor 阻塞到看门狗兜底。先订阅 + 排空器全程消费 + seq 归并去重后，
//     窗口期事件既不丢也不重。
//   - **为什么排空器覆盖整个连接生命周期**：任何一次事件写出都可能因背压阻塞任意久，
//     阻塞期间若订阅通道无人消费，16 缓冲被 Publish 写满后 hub 即按慢订阅者契约丢
//     弃——排空器与所有写出并发运行，订阅通道从握手完成到连接关闭永不写满。
//   - 重放用 EventsFromAsc（截断尾部、缺口可凭更大 cursor 续拉），而非 EventsFrom
//     （截最旧、cursor 越过缺口永不补齐，见 store 包两方法的语义说明）
//   - **镜像任务同形**：本机 tasks 表没有、但 mirror_tasks 有的任务，从
//     mirror_events 重放历史，活事件由镜像订阅经同一个 Hub 送来。对浏览器
//     协议完全同形（帧就是带 seq 的 Event），ws.ts 无感——这正是「浏览器
//     永远只连本机一条 WS」的兑现处
//   - 任务归档（done）时 hub 会关闭本连接的订阅，此处以 StatusNormalClosure +
//     "task archived" 收尾。客户端据这个关闭码区分「归档」与「断线」——断线要
//     重连，归档要退出，两者搞混就是无限重连一个已经结束的任务
func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	taskID := r.URL.Query().Get("task")
	if taskID == "" {
		s.log.Warn("WS 连接缺少 task 参数", "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "缺少 task 参数"})
		return
	}
	fromSeq := int64(0)
	if q := r.URL.Query().Get("from_seq"); q != "" {
		var err error
		fromSeq, err = strconv.ParseInt(q, 10, 64)
		if err != nil || fromSeq < 0 {
			s.log.Warn("WS from_seq 参数非法", "task", taskID, "from_seq", q, "remote_addr", r.RemoteAddr)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "from_seq 必须是大于等于 0 的整数"})
			return
		}
	}

	conn, err := websocket.Accept(w, r, nil)
	if err != nil {

		s.log.Warn("WS 握手失败", "task", taskID, "remote_addr", r.RemoteAddr, "err", err)
		return
	}
	defer conn.CloseNow()

	mirrored := false
	if _, err := s.st.GetTask(taskID); err != nil {
		if errors.Is(err, store.ErrNotFound) {

			if _, ok, mErr := s.st.MirrorTaskTarget(taskID); mErr == nil && ok {
				mirrored = true
				s.log.Info("WS 订阅镜像任务", "task", taskID, "from_seq", fromSeq)
			} else {
				s.log.Warn("WS 订阅任务不存在", "task", taskID, "remote_addr", r.RemoteAddr)
				if cerr := conn.Close(websocket.StatusPolicyViolation, "task not found"); cerr != nil {

					s.log.Warn("WS 关闭任务不存在连接失败", "task", taskID, "err", cerr)
				}
				return
			}
		} else {
			s.log.Error("WS 校验任务失败", "task", taskID, "cause", err)
			return
		}
	}

	sent := 0
	defer func() {
		s.log.Info("WS 连接断开", "task", taskID, "from_seq", fromSeq, "sent", sent)
	}()

	ctx := conn.CloseRead(r.Context())

	if id := identityFrom(r.Context()); id.session != "" {
		go s.watchSession(ctx, conn, id.session, taskID)
	}

	ch, cancel := s.hub.Subscribe(taskID)
	defer cancel()

	// 实时事件排空器：整个连接生命周期内的唯一消费者 goroutine，持续阻塞消费订阅
	// 通道并收集进 live 切片（互斥锁保护），每收集一条向 drainNotify 发送一次唤醒
	// （缓冲 1；主循环总是整批快照 live，单个待处理唤醒足够，default 分支防堆积）。
	//
	// 为什么必须覆盖「整个连接生命周期」而非只覆盖重放阶段：任何一次事件写出
	// （重放写、归并写、实时写）都可能因 TCP 背压阻塞任意久，阻塞期间若无人消费
	// 订阅通道，16 缓冲被 Publish 写满后 hub 的 select-default 慢订阅者丢弃逻辑
	// 开始丢事件——排空器与所有写出并发运行，订阅通道从握手完成到连接关闭永不
	// 写满，Publish 的事件 100% 进入 live 等待写出，不存在「停止排空后再写归并」
	// 的丢事件窗口。
	//
	// 缓冲有上限（liveLimit）：对端「连着不读」时写循环会阻塞任意久，无上限的
	// 收集会把 hub 的有界丢弃换成 agentd 的无界内存增长。越限即置 overflow 并
	// 唤醒主循环断开连接——所有事件都已落库，客户端凭 cursor 重连可完整补拉。
	var (
		liveMu		sync.Mutex
		live		[]proto.Event
		overflow	bool
		archived	bool	// 订阅被 hub 关闭（任务归档），与「本连接自己结束」区分
		drainNotify	= make(chan struct{}, 1)
	)
	notifyDrain := func() {
		select {
		case drainNotify <- struct{}{}:
		default:
		}
	}
	go func() {
		for {
			select {
			case ev, ok := <-ch:
				if !ok {

					liveMu.Lock()
					archived = true
					liveMu.Unlock()
					notifyDrain()
					return
				}
				liveMu.Lock()
				if len(live) >= s.liveLimit {
					overflow = true
					liveMu.Unlock()
					notifyDrain()
					return
				}
				live = append(live, ev)
				liveMu.Unlock()
				notifyDrain()
			case <-ctx.Done():
				return
			}
		}
	}()

	// 阶段一：补发历史事件（from_seq 之后按 seq 升序的最旧 limit 条，截断在尾部）
	// 镜像任务（本机 tasks 表没有、mirror_tasks 有）从 mirror_events 重放，
	// 语义与本机 EventsFromAsc 一致（开区间、截尾部、可凭更大 cursor 续拉）。
	var replays []proto.Event
	if mirrored {
		replays, err = s.st.MirrorEventsFrom(taskID, fromSeq, s.replayLimit)
	} else {
		replays, err = s.st.EventsFromAsc(taskID, fromSeq, s.replayLimit)
	}
	if err != nil {
		s.log.Error("WS 补发历史事件失败", "task", taskID, "from_seq", fromSeq, "mirrored", mirrored, "cause", err)
		return
	}

	maxReplayed := int64(0)
	if len(replays) > 0 {
		maxReplayed = replays[len(replays)-1].Seq
	}

	storeMax := int64(0)
	if latest, lerr := s.st.LatestEvent(taskID); lerr == nil {
		storeMax = latest.Seq
	}
	s.log.Debug("WS 重放开始", "task", taskID, "from_seq", fromSeq, "replays", len(replays), "store_max", storeMax)
	for _, ev := range replays {
		if err := writeEvent(ctx, conn, ev); err != nil {
			s.log.Warn("WS 补发写入失败", "task", taskID, "seq", ev.Seq, "err", err)
			return
		}
		sent++
	}
	s.log.Info("WS 连接建立", "task", taskID, "from_seq", fromSeq, "replayed", len(replays))

	lastWrittenSeq := maxReplayed

	deliveredInGap := 0

	writeLiveBatch := func(pending []proto.Event) bool {
		sort.Slice(pending, func(i, j int) bool { return pending[i].Seq < pending[j].Seq })
		for _, ev := range pending {
			if ev.Seq <= maxReplayed {
				continue
			}
			if ev.Seq <= lastWrittenSeq {

				s.log.Warn("WS 收到乱序迟到事件，断开连接由客户端凭 cursor 重连补齐",
					"task", taskID, "seq", ev.Seq, "last_written", lastWrittenSeq)
				return false
			}
			if err := writeEvent(ctx, conn, ev); err != nil {
				s.log.Warn("WS 实时写入失败", "task", taskID, "seq", ev.Seq, "err", err)
				return false
			}
			lastWrittenSeq = ev.Seq
			if ev.Seq <= storeMax {
				deliveredInGap++
			}
			sent++
		}
		return true
	}

	liveMu.Lock()
	pending := live
	live = nil
	liveMu.Unlock()
	if !writeLiveBatch(pending) {
		return
	}
	s.log.Debug("WS 重放归并完成", "task", taskID, "live_merged", len(pending))

	if len(replays) == s.replayLimit && storeMax > maxReplayed {
		gapTotal, cerr := s.st.CountEvents(taskID, maxReplayed, storeMax)
		switch {
		case cerr != nil:
			s.log.Error("WS 截断缺口核对失败", "task", taskID, "cause", cerr)
			s.noteTruncationDiagnosed("error")
		case gapTotal > deliveredInGap:
			s.log.Warn("WS 补发窗口截断且缺口未由实时流补齐", "task", taskID, "from_seq", fromSeq,
				"replayed", len(replays), "gap_total", gapTotal, "gap_delivered", deliveredInGap,
				"store_max", storeMax)
			s.noteTruncationDiagnosed("warned")
		default:
			s.log.Debug("WS 补发窗口截断但缺口已由实时流补齐", "task", taskID,
				"replayed", len(replays), "gap_total", gapTotal, "store_max", storeMax)
			s.noteTruncationDiagnosed("covered")
		}
	}

	for {
		select {
		case <-drainNotify:
			liveMu.Lock()
			pending := live
			live = nil
			over := overflow
			arch := archived
			liveMu.Unlock()
			if !writeLiveBatch(pending) {
				return
			}
			if arch {

				s.log.Info("任务已归档，以正常关闭码结束事件流", "task", taskID,
					"sent", sent, "last_written", lastWrittenSeq)
				if cerr := conn.Close(websocket.StatusNormalClosure, "task archived"); cerr != nil {

					s.log.Debug("WS 归档关闭失败", "task", taskID, "err", cerr)
				}
				return
			}
			if over {
				s.log.Warn("WS 待写缓冲越限，断开连接（对端长时间不读）：客户端凭 cursor 重连补拉",
					"task", taskID, "limit", s.liveLimit, "last_written", lastWrittenSeq)
				return
			}
		case <-ctx.Done():
			return
		}
	}
}

n_agentd_Server_handleExecutorDefaultGet.signature:
// handleExecutorDefaultGet 处理 GET /api/executor/default[?machine=]。
//
// 响应：200 proto.ExecutorDefaultResp / 503 manager 未就绪。
//
// 为什么 manager 未就绪要 503 而不是回一个空名单：空名单会让界面画出一个
// 选无可选的下拉框，用户会以为配置丢了。诚实地说「现在答不上来」更好。
func (s *Server) handleExecutorDefaultGet(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	s.log.Info("缺省执行者查询请求", "method", r.Method, "path", r.URL.Path)
	if s.mgr == nil {
		s.log.Warn("缺省执行者查询：manager 未就绪")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	resp := s.executorDefaultResp()
	s.log.Info("缺省执行者查询完成",
		"default", resp.Default, "has_model", resp.Model != "", "available", len(resp.Available))
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleExecutorDefaultPut.signature:
// handleExecutorDefaultPut 处理 PUT /api/executor/default[?machine=]。
//
// 请求体 proto.ExecutorDefaultReq：**整体替换** executor 段的两个字段。
//
// 响应：200 proto.ExecutorDefaultResp（保存后的最新状态，界面直接拿它刷新）
//
//	400 default 为空或未注册
//	503 manager 未就绪
//
// 为什么 default 必须校验：它是 resolveExecutor 的兜底值。写进一个该机没有的
// 名字，此后**每一次**不带 --executor 的派发都会失败——一个下拉框搞挂一台机。
//
// 为什么 model 不校验：agentd 不认识任何执行器的模型名单（模型名按执行器、
// 也按机器不同），没有可判据。它的失败面也小得多：只影响缺省执行者、只影响
// 不带 --model 的派发，且失败是当场的（第一个事件就是 400 或秒退）。
func (s *Server) handleExecutorDefaultPut(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	if s.mgr == nil {
		s.log.Warn("缺省执行者保存：manager 未就绪")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var req proto.ExecutorDefaultReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("缺省执行者保存：请求体无法解析", "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体不是合法 JSON"})
		return
	}

	def := strings.TrimSpace(req.Default)
	model := strings.TrimSpace(req.Model)
	s.log.Info("缺省执行者保存请求", "default", def, "has_model", model != "")

	names := s.mgr.ExecutorNames()
	if def == "" {
		s.log.Warn("缺省执行者保存被拒：为空", "cause", "缺省执行者不能为空")
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("缺省执行者不能为空（可选: %s）", strings.Join(names, ", "))})
		return
	}
	if !containsString(names, def) {
		s.log.Warn("缺省执行者保存被拒：未注册", "default", def, "registered", names,
			"cause", "该机没有这个执行者")
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("未知 executor %q（可选: %s）", def, strings.Join(names, ", "))})
		return
	}

	if err := s.swapConf(func(c *config.Config) error {

		c.Executor = config.ExecutorConfig{Default: def, Model: model}
		return nil
	}); err != nil {
		s.log.Error("缺省执行者落盘失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("缺省执行者已保存", "default", def, "has_model", model != "")
	writeJSON(w, http.StatusOK, s.executorDefaultResp())
}

n_agentd_Server_handleFlowGet.signature:
// handleFlowGet 取单条工作流的指定版本（含节点定义）；缺省 version 取最新版本。
//
// 老 def（只有 states）读出时会被补出等价的纯人工节点序列，所以前端永远
// 只需要看 nodes 一个字段。
func (s *Server) handleFlowGet(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	version := 0
	if rawVersion := r.URL.Query().Get("version"); rawVersion != "" {
		parsed, err := strconv.Atoi(rawVersion)
		if err != nil || parsed <= 0 {
			s.log.Warn("读取工作流版本参数无效", "name", name, "version", rawVersion)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version 必须是正整数"})
			return
		}
		version = parsed
	}
	workflow, err := s.ledger.GetWorkflow(name, version)
	if err != nil {
		s.log.Warn("取工作流失败", "name", name, "version", version, "cause", err)
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("读出工作流", "name", name, "version", workflow.Version, "nodes", len(workflow.Def.Nodes))
	nodes := make([]proto.NodeDef, 0, len(workflow.Def.Nodes))
	for _, node := range workflow.Def.Nodes {
		nodes = append(nodes, ledgerNodeWire(node))
	}
	board := workflow.Def.Board
	if board == nil {
		defaultBoard := ledger.DefaultBoardLayout(workflow.Def.States)
		board = &defaultBoard
	}
	writeJSON(w, http.StatusOK, proto.FlowDetail{
		Name:	workflow.Name, Version: workflow.Version, Nodes: nodes, States: workflow.Def.States, Board: board,
	})
}

n_agentd_Server_handleFlowPut.signature:
// handleFlowPut 发布该工作流的**下一个版本**。
//
// 注意：这不是「改」——工作流不可变版本化，每次保存都是插一个新版本，
// 已经钉在老版本上的卡完全不受影响。想让老卡用新流程要显式迁移
// （MigrateCardWorkflow），那是另一个动作。
func (s *Server) handleFlowPut(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	var body struct {
		Nodes	[]ledger.NodeDef	`json:"nodes"`
		Board	*proto.BoardLayout	`json:"board,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": fmt.Errorf("解析请求体: %w", err).Error()})
		return
	}
	if len(body.Nodes) == 0 {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "nodes 不能为空"})
		return
	}
	version, err := s.ledger.PutWorkflow(name, ledger.WorkflowDef{Nodes: body.Nodes, Board: body.Board})
	if err != nil {

		if errors.Is(err, ledger.ErrBadState) {
			s.log.Warn("工作流节点校验未过", "name", name, "cause", err)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
			return
		}
		s.log.Error("写工作流失败", "name", name, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	boardColumns := 0
	if body.Board != nil {
		boardColumns = len(body.Board.Columns)
	}
	s.log.Info("已发布工作流新版本", "name", name, "version", version, "nodes", len(body.Nodes), "board_columns", boardColumns)
	writeJSON(w, http.StatusOK, map[string]any{"name": name, "version": version})
}

n_agentd_Server_handleFlows.signature:
func (s *Server) handleFlows(w http.ResponseWriter, r *http.Request) {
	names, err := s.ledger.ListWorkflowNames()
	if err != nil {
		ledgerErr(w, err)
		return
	}
	flows := make([]map[string]any, 0, len(names))
	for _, name := range names {
		workflow, err := s.ledger.GetWorkflow(name, 0)
		if err != nil {
			continue
		}
		def := workflow.Def
		if def.Board == nil {
			defaultBoard := ledger.DefaultBoardLayout(def.States)
			def.Board = &defaultBoard
		}
		flows = append(flows, map[string]any{
			"name":	workflow.Name, "version": workflow.Version, "def": def,
		})
	}
	templateNames, _ := s.ledger.ListTemplateNames()
	templates := make([]map[string]any, 0, len(templateNames))
	for _, name := range templateNames {
		template, err := s.ledger.GetTemplate(name, 0)
		if err != nil {
			continue
		}
		templates = append(templates, map[string]any{
			"name":	template.Name, "version": template.Version, "def": template.Def,
		})
	}
	writeJSON(w, http.StatusOK, map[string]any{"workflows": flows, "templates": templates})
}

n_agentd_Server_handleFootprint.signature:
// handleFootprint 返回全部任务（含已归档）的进程足迹体检。
//
// 注意：这是慢接口——它遍历全部历史任务目录逐个枚举进程。与 /api/status
// 分开正是为了不把那条「必须快」的诊断路径拖下水。
func (s *Server) handleFootprint(w http.ResponseWriter, r *http.Request) {
	s.log.Info("足迹体检请求", "method", r.Method, "path", r.URL.Path)
	if s.mgr == nil {
		s.log.Error("manager 未就绪，无法体检足迹")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	resp, err := s.mgr.FootprintAll()
	if err != nil {
		s.log.Error("足迹体检失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		return
	}
	s.log.Info("足迹体检请求完成", "rows", len(resp.Rows))
	resp.Pty = s.ptyFootprint()
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleGC.signature:
// handleGC 处理 GET/POST /api/gc。GET 仅预览，POST 才执行；两条路由都受 Server.Handler 的 auth 包裹。
// POST 解码失败时 force=false。
func (s *Server) handleGC(w http.ResponseWriter, r *http.Request) {
	force := r.URL.Query().Get("force") == "true"
	if r.Method == http.MethodPost {
		var req proto.GCRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			s.log.Warn("gc 请求体解码失败，按默认 force=false 处理", "cause", err)
		}
		force = req.Force
	}
	execute := r.Method == http.MethodPost
	s.log.Info("gc HTTP 进入", "method", r.Method, "path", r.URL.Path, "force", force, "execute", execute)
	if s.mgr == nil {
		s.log.Warn("gc 请求到达但 manager 未注入", "method", r.Method, "path", r.URL.Path)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	resp, err := s.mgr.GC(r.Context(), force, execute)
	if err != nil {
		s.log.Error("gc 请求失败", "method", r.Method, "force", force, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		return
	}
	s.log.Info("gc HTTP 完成", "method", r.Method, "force", force, "execute", execute,
		"scanned", resp.Scanned, "failures", resp.Failures)
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleGetTask.signature:
// handleGetTask 返回任务详情（任务 + 待办工单 + 最近事件），是 attach 命令的数据源。
func (s *Server) handleGetTask(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("任务详情请求", "method", r.Method, "path", r.URL.Path, "task", taskID)

	task, err := s.st.GetTask(taskID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			s.log.Warn("任务不存在", "task", taskID)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "任务不存在"})
			return
		}
		s.log.Error("读取任务失败", "task", taskID, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		return
	}
	pending, err := s.st.PendingTickets(taskID)
	if err != nil {
		s.log.Error("读取待办工单失败", "task", taskID, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		return
	}
	events, err := s.st.EventsFrom(taskID, 0, recentEventsLimit)
	if err != nil {
		s.log.Error("读取最近事件失败", "task", taskID, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		return
	}

	if pending == nil {
		pending = []proto.Ticket{}
	}
	if events == nil {
		events = []proto.Event{}
	}
	watchers := s.hub.Watchers(taskID)
	task.ProjectID = s.projectIndex().ProjectIDOf(task.RepoPath)
	s.log.Info("任务详情完成", "task", taskID, "state", task.State,
		"pending", len(pending), "watchers", watchers)
	writeJSON(w, http.StatusOK, taskDetail{
		Task:		proto.TaskView{Task: *task, Watchers: watchers},
		PendingTickets:	pending,
		RecentEvents:	events,
	})
}

n_agentd_Server_handleHomeProbe.signature:
// handleHomeProbe POST /api/host/probe?machine=：只读探测。?machine= 先转发。
func (s *Server) handleHomeProbe(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	var in proto.HomeProbeReq
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("解析请求体: %v", err)})
		return
	}
	if in.CLI == "" || in.Path == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": "cli 与 path 必填"})
		return
	}
	s.log.Info("探测隔离 HOME", "cli", in.CLI, "path", in.Path,
		"main_home_sync", in.Credential == "main_home_sync")
	reply, err := s.hostAPI.ProbeHome(r.Context(), hostapi.ProbeRequest{
		Path:	in.Path, CLI: in.CLI, Credential: in.Credential,
	})
	if err != nil {
		s.hostProbeErr(w, err)
		return
	}
	writeJSON(w, http.StatusOK, proto.HomeProbeResp{Kind: string(reply.Kind), Detail: reply.Detail})
}

n_agentd_Server_handleHomeWake.signature:
// handleHomeWake POST /api/host/wake?machine=：本机有时限唤起。?machine= 先转发。
// 空 home_dir 合法（代表目标机主 HOME，原样交给 WakeHome 回落处理）。
func (s *Server) handleHomeWake(w http.ResponseWriter, r *http.Request) {
