n_agentd_Server_handleInbox.signature:
// handleInbox GET /api/inbox → 收件箱三源聚合（契约 §3.6 编排单元，位置冻结在
// gateway 层）。decision/mention 源失败如实 500（承重）；ticket 源失败降级跳过
// （与 handleCardsList 的 tickets 徽标同族，不吞主查询）。
func (s *Server) handleInbox(w http.ResponseWriter, r *http.Request) {
	items := make([]proto.InboxItem, 0, 8)

	decisions, err := s.ledger.ListDecisions(true)
	if err != nil {
		s.log.Warn("收件箱 decision 源读取失败", "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	for _, d := range decisions {
		payload, err := json.Marshal(ledgerDecisionWire(d))
		if err != nil {
			s.log.Warn("收件箱 decision 投影失败", "decision", d.ID, "cause", err)
			continue
		}
		items = append(items, proto.InboxItem{
			Origin:	proto.InboxOriginDecision, Title: decisionTitle(d), CardID: d.CardID,
			RefID:	strconv.FormatInt(d.ID, 10), Payload: payload,
		})
	}

	tasks, err := s.st.ListTasks()
	if err != nil {
		s.log.Warn("收件箱 ticket 源读取失败", "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	for _, task := range tasks {
		if task.State != proto.TaskStateWaitingAnswer {
			continue
		}
		pending, err := s.st.PendingTickets(task.ID)
		if err != nil {
			s.log.Warn("收件箱 ticket 源读取失败", "task", task.ID, "cause", err)
			continue
		}
		if len(pending) == 0 {
			continue
		}
		watchers := s.hub.Watchers(task.ID)
		for _, tk := range pending {
			if watchers > 0 && !s.ticketDestructive(task.ID, tk.ID) {
				continue
			}
			items = append(items, proto.InboxItem{
				Origin:	proto.InboxOriginTicket, Title: ticketTitle(tk), RefID: tk.ID,
			})
		}
	}

	mentions, err := s.rooms.Mentions(s.roomUserActor(r), 0, 0)
	if err != nil {
		s.log.Warn("收件箱 mention 源读取失败", "member", s.roomUserActor(r), "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	for _, ev := range mentions {
		var msg proto.RoomMessage
		if err := json.Unmarshal(ev.Payload, &msg); err != nil {
			continue
		}
		items = append(items, proto.InboxItem{
			Origin:	proto.InboxOriginMention, Title: "@你：" + msg.Body, CardID: ev.CardID,
			RefID:	strconv.FormatInt(ev.Seq, 10),
		})
	}

	s.log.Info("收件箱已聚合", "member", s.roomUserActor(r), "items", len(items))
	writeJSON(w, http.StatusOK, map[string]any{"items": items})
}

n_agentd_Server_handleIssueTicket.signature:
// handleIssueTicket 由主令牌签发一次性 ticket。
func (s *Server) handleIssueTicket(w http.ResponseWriter, r *http.Request) {
	if id := identityFrom(r.Context()); id.session != "" {

		s.log.Warn("会话身份尝试签发 ticket，已拒绝", "session", id.session, "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "签发 ticket 需要主令牌"})
		return
	}
	var req struct {
		DeviceName string `json:"device_name"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil && !errors.Is(err, io.EOF) {

		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体非法"})
		return
	}
	plain, err := randCredential()
	if err != nil {
		s.log.Error("签发 ticket 失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "签发失败"})
		return
	}
	now := time.Now()
	expires := now.Add(ticketLifetime)
	device := sanitizeDeviceName(req.DeviceName)
	if err := s.st.CreateAuthTicket(store.HashCredential(plain), device, now, expires); err != nil {
		s.log.Error("签发 ticket 失败", "device_name", device, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "签发失败"})
		return
	}
	s.log.Info("签发 ticket", "device_name", device, "expires_at", expires)
	writeJSON(w, http.StatusOK, proto.AuthTicketResp{URL: consoleURL(r, plain), ExpiresAt: expires})
}

n_agentd_Server_handleLaunchersGet.signature:
// handleLaunchersGet 处理 GET /api/launchers[?machine=]。
//
// 读盘失败时返回 500 并带真因（文件坏了要让人看得见，不是静默当空）。
// 文件不存在返回空列表——那是正常起点（launcher.Load 的既有语义）。
func (s *Server) handleLaunchersGet(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	dataDir := s.conf().DataDir
	list, err := launcher.Load(dataDir)
	if err != nil {
		s.log.Error("读取启动项配置失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	resp := proto.LaunchersResp{Launchers: toProtoLaunchers(envfile.Dir(dataDir), list)}
	s.log.Debug("启动项列表查询完成", "count", len(resp.Launchers))
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleLaunchersPut.signature:
// handleLaunchersPut 处理 PUT /api/launchers[?machine=]：整段替换。
//
// 校验分两段：
//  1. launcher.Validate 的四条纯规则（名字非空/唯一、至少填一个、无路径分隔符）；
//  2. 本层追加的第五条——env 文件必须真实存在。它要读盘，故不在纯函数里。
//
// 两段的顺序不能反：先跑纯规则，「第 3 条名字为空」这类错误才不会被
// 「文件不存在」抢先报出来（用户看到的应该是最根本的那条）。
//
// **客户端送来的 env_missing 一律忽略**：它是 GET 时现算的派生字段，
// 采信客户端等于让前端能往磁盘上写一个谎。
func (s *Server) handleLaunchersPut(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	var req proto.LaunchersReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("启动项保存：请求体无法解析")
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体不是合法 JSON"})
		return
	}
	dataDir := s.conf().DataDir
	list := make([]launcher.Item, 0, len(req.Launchers))
	withCmd := 0
	for _, l := range req.Launchers {

		it := launcher.Item{
			Name:	strings.TrimSpace(l.Name), EnvFile: strings.TrimSpace(l.EnvFile),
			Command:	strings.TrimSpace(l.Command),
		}
		if it.Command != "" {
			withCmd++
		}
		list = append(list, it)
	}
	s.log.Info("启动项保存请求", "count", len(list), "with_command", withCmd)

	if err := launcher.Validate(list); err != nil {

		s.log.Warn("启动项保存被拒：规则校验不通过", "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	envDir := envfile.Dir(dataDir)
	for _, it := range list {
		if it.EnvFile == "" {
			continue
		}
		if _, _, _, err := envfile.Read(envDir, it.EnvFile); err != nil {

			s.log.Warn("启动项保存被拒：env 文件不可用", "launcher", it.Name, "file", it.EnvFile)
			writeJSON(w, http.StatusBadRequest, map[string]string{
				"error": fmt.Sprintf("启动项 %q 指定的 env 文件 %q 不可用：%v", it.Name, it.EnvFile, err),
			})
			return
		}
	}
	if err := launcher.Save(dataDir, list); err != nil {
		if errors.Is(err, launcher.ErrInvalid) {

			s.log.Warn("启动项落盘被拒：规则校验不通过", "cause", err)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
			return
		}
		s.log.Error("启动项落盘失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("启动项已保存", "count", len(list), "with_command", withCmd)
	s.handleLaunchersGet(w, r)
}

