n_agentd_Server_handleProjectWorktreeCre.signature:
// handleProjectWorktreeCreate 处理 POST /api/projects/{name}/worktrees[?machine=]。
//
// 在该项目位置上开一棵不属于任何任务的工作树（spec §3.2）。
//
// 参数：
//   - name（路径）: 项目登记名
//   - machine（查询）: 可选，转发到指定机器
//   - 请求体: proto.CreateWorktreeReq
//
// 响应：200 proto.Workspace；项目不存在 404；请求不合法 400；git 失败 500（原文透出）
func (s *Server) handleProjectWorktreeCreate(w http.ResponseWriter, r *http.Request) {
	handled, forwarded, cardIDs := s.forwardWorktreeIfRequested(w, r)
	if handled {
		if forwarded == nil {
			return
		}
		if len(cardIDs) > 0 && s.ledger != nil {
			*forwarded = s.attachCardBaseBranches(*forwarded, cardIDs, s.ledgerActor(r))
		}
		writeJSON(w, http.StatusOK, *forwarded)
		s.log.Info("跨机建树完成并由本机挂卡", "machine", r.URL.Query().Get("machine"),
			"branch", forwarded.Branch, "card_result_count", len(forwarded.CardResults))
		return
	}
	if s.forwardIfRequested(w, r) {
		return
	}
	name := r.PathValue("name")
	var req proto.CreateWorktreeReq
	if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		s.log.Warn("建树请求体解析失败", "name", name, "status", http.StatusBadRequest, "cause", err)
		writeJSON(w, http.StatusBadRequest,
			map[string]string{"error": "请求体必须是 JSON {mode, branch, base}"})
		return
	}
	s.log.Info("建树请求", "name", name, "machine", r.URL.Query().Get("machine"),
		"mode", req.Mode, "branch", req.Branch, "base", req.Base, "card_count", len(req.CardIDs))
	loc, err := s.st.GetProjectLocationByName(name)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			s.log.Warn("建树被拒：项目不存在", "name", name, "status", http.StatusNotFound, "cause", err)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "项目 " + name + " 未登记"})
			return
		}
		s.log.Error("建树失败：查询位置表", "name", name, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	if s.mgr == nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	if err := s.mgr.RequireWorkspace(); err != nil {
		s.log.Error("建树失败：工作区能力未注入", "name", name, "cause", err)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("准备通过工作区能力创建手工树", "name", name, "repo", loc.Path,
		"mode", req.Mode, "branch", req.Branch)
	tree, err := s.mgr.Workspace().CreateManual(r.Context(), loc.Path,
		filepath.Join(s.conf().DataDir, "worktrees"),
		workspace.ManualReq{Mode: req.Mode, Branch: req.Branch, Base: req.Base})
	if err != nil {
		status := http.StatusInternalServerError
		if errors.Is(err, workspace.ErrBadWorktreeReq) {
			status = http.StatusBadRequest
		}
		s.log.Error("建树失败", "name", name, "repo", loc.Path, "mode", req.Mode,
			"branch", req.Branch, "status", status, "cause", err)
		writeJSON(w, status, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	s.log.Info("手工树创建成功", "name", name, "path", tree.Path, "branch", tree.Branch)
	ws := proto.Workspace{Path: tree.Path, Branch: tree.Branch, Head: tree.Head, Managed: tree.Managed}
	if len(req.CardIDs) > 0 && s.ledger != nil {
		ws = s.attachCardBaseBranches(ws, req.CardIDs, s.ledgerActor(r))
	}
	s.log.Info("建树完成", "name", name, "dir", ws.Path, "branch", ws.Branch,
		"card_result_count", len(ws.CardResults))
	writeJSON(w, http.StatusOK, ws)
}

n_agentd_Server_handlePtyWS.signature:
// handlePtyWS 处理 GET /ws/pty?session=<id>&since=<n>[&machine=]。
func (s *Server) handlePtyWS(w http.ResponseWriter, r *http.Request) {
	if machine := r.URL.Query().Get("machine"); machine != "" && !isForwarded(r) {
		s.forwardWS(w, r, machine)
		return
	}
	id := r.URL.Query().Get("session")
	since, _ := strconv.ParseUint(r.URL.Query().Get("since"), 10, 64)

	conn, err := websocket.Accept(w, r, nil)
	if err != nil {
		s.log.Warn("终端 WS 升级失败", "session", id, "cause", err)
		return
	}
	att, aerr := s.pty.Attach(id, since)
	if aerr != nil {

		s.log.Warn("终端 WS 建连被拒", "session", id, "since", since, "cause", aerr)
		_ = conn.Close(websocket.StatusPolicyViolation, aerr.Error())
		return
	}
	defer att.Detach()
	ctx := r.Context()

	if err := writeCtrl(ctx, conn, proto.PtyControl{
		Type:	proto.PtyCtrlAttached, Since: att.Since, Truncated: att.Truncated,
		BacklogBytes:	uint64(len(att.Backlog)),
	}); err != nil {
		s.log.Warn("终端 WS 首帧写失败", "session", id, "cause", err)
		_ = conn.Close(websocket.StatusInternalError, "首帧写失败")
		return
	}
	if len(att.Backlog) > 0 {
		if err := conn.Write(ctx, websocket.MessageBinary, att.Backlog); err != nil {
			s.log.Warn("终端 WS 回放写失败", "session", id,
				"backlog_bytes", len(att.Backlog), "cause", err)
			_ = conn.Close(websocket.StatusInternalError, "回放写失败")
			return
		}
	}
	s.log.Info("终端 WS 已建连", "session", id, "since", att.Since,
		"backlog_bytes", len(att.Backlog), "truncated", att.Truncated)

	upDone := make(chan struct{})
	go func() {
		defer close(upDone)
		s.pumpPtyUplink(ctx, conn, att, id)
	}()

	for {
		select {
		case <-ctx.Done():
			s.log.Info("终端 WS 断开（客户端离开）", "session", id)
			_ = conn.Close(websocket.StatusNormalClosure, "")
			return
		case <-upDone:
			_ = conn.Close(websocket.StatusNormalClosure, "")
			return
		case b, ok := <-att.Out:
			if !ok {
				code := att.ExitCode()
				s.log.Info("终端 WS 收尾：会话已退出", "session", id, "exit_code", code)
				_ = writeCtrl(ctx, conn, proto.PtyControl{Type: proto.PtyCtrlExit, ExitCode: code})
				_ = conn.Close(websocket.StatusNormalClosure, "会话已退出")
				return
			}
			if err := conn.Write(ctx, websocket.MessageBinary, b); err != nil {
				s.log.Warn("终端 WS 下行写失败", "session", id, "bytes", len(b), "cause", err)
				return
			}
		}
	}
}

n_agentd_Server_handlePullUpdate.signature:
// handlePullUpdate 处理自拉换版：校验参数、抢并发锁、受理后交给后台。
//
// 参数：
//   - tag / sum: 协调者下发的目标版本与期望 sha256，**必须成对**
//   - busy: 已统计出的活跃任务数，只用于日志
//
// 注意：
//   - 两道闸已由调用方检查过，这里不重复
func (s *Server) handlePullUpdate(w http.ResponseWriter, tag, sum string, busy int) {
	if tag == "" || sum == "" {
		s.log.Warn("自拉被拒：缺 tag 或 sha256", "tag", tag, "has_sum", sum != "")
		writeJSON(w, http.StatusBadRequest, proto.UpdateError{
			Error: "mode=pull 时 tag 与 sha256 都必须给：缺了它们无从校验完整性，也无从自检",
		})
		return
	}
	if !s.pull.begin(tag) {

		cur := s.pull.snapshot()
		s.log.Warn("自拉被拒：已有一个自拉在跑", "tag", tag, "current", cur)
		writeJSON(w, http.StatusConflict, proto.UpdateError{
			Error:	"已有一个自拉换版在进行中，去 status 看 pull_state",
			Reason:	proto.UpdateReasonPullInProgress,
		})
		return
	}
	s.log.Info("自拉换版已受理", "tag", tag, "sha256", sum, "busy", busy)
	writeJSON(w, http.StatusAccepted, proto.UpdateResp{OK: true, Accepted: true, Version: tag})

	go s.runPull(tag, sum)
}

n_agentd_Server_handleQueueGet.signature:
// handleQueueGet GET /api/queue：两队列的只读快照，按清队顺序给全局位次。
// 只读不出队——PopReady 才删除头部。
func (s *Server) handleQueueGet(w http.ResponseWriter, r *http.Request) {
	rows, err := s.scheduling.QueueSnapshot()
	if err != nil {
		s.log.Error("读队列快照失败", "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	resp := proto.QueueResp{Queue: make([]proto.QueueEntry, 0, len(rows))}
	for _, row := range rows {
		resp.Queue = append(resp.Queue, queueEntryView(row))
	}
	s.log.Info("已读取点火队列", "entries", len(resp.Queue))
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleReclaim.signature:
// handleReclaim 回收单个终态任务的 managed worktree。
//
// 状态码：404 任务不存在；409 四种拒绝（reason 区分）；200 成功。
//
// 注意：四种 409 共用状态码，响应体必须带机器码 reason——CLI 靠它分派渲染，
// 解析中文文案是不行的（文案会改，机器码不改）
func (s *Server) handleReclaim(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("回收请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	if s.mgr == nil {
		s.log.Warn("回收请求到达但 manager 未注入", "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	var body struct {
		Force bool `json:"force"`
	}

	_ = json.NewDecoder(r.Body).Decode(&body)

	resp, err := s.mgr.Reclaim(r.Context(), taskID, body.Force)
	if err != nil {
		s.writeReclaimError(w, taskID, err)
		return
	}
	s.log.Info("回收请求完成", "task", taskID, "action", resp.Action, "removed", resp.Removed)
	writeJSON(w, http.StatusOK, resp)
}

