n_agentd_Server_handleRoomSend.signature:
// handleRoomSend POST /api/rooms/{id}/messages → 用户发言（kind 服务端固定 user，
// actor 服务端注入，均不经请求体）。空正文拒绝（无意义消息不进房间）。
func (s *Server) handleRoomSend(w http.ResponseWriter, r *http.Request) {
	roomID := r.PathValue("id")
	var req struct {
		Body		string		`json:"body"`
		Refs		[]string	`json:"refs,omitempty"`
		Mentions	[]string	`json:"mentions,omitempty"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeErr(w, http.StatusBadRequest, errors.New("bad json"))
		return
	}
	if strings.TrimSpace(req.Body) == "" {
		writeErr(w, http.StatusBadRequest, errors.New("消息正文不能为空"))
		return
	}
	seq, err := s.rooms.Send(roomID, proto.RoomMessage{
		Kind:	proto.RoomMsgUser, Body: req.Body, Refs: req.Refs, Mentions: req.Mentions,
	}, s.roomUserActor(r))
	if err != nil {
		s.log.Warn("房间消息发送失败", "room", roomID, "actor", s.roomUserActor(r), "cause", err)
		collabErr(w, err)
		return
	}
	s.log.Info("房间消息已发送", "room", roomID, "seq", seq, "actor", s.roomUserActor(r))
	writeJSON(w, http.StatusOK, map[string]int64{"seq": seq})
}

n_agentd_Server_handleRoomsList.signature:
// handleRoomsList GET /api/rooms?project= → ListRooms（扁平活动排序列表）。
func (s *Server) handleRoomsList(w http.ResponseWriter, r *http.Request) {
	project := r.URL.Query().Get("project")
	member := s.roomUserActor(r)
	rooms, err := s.rooms.ListRoomsForMember(project, member)
	if err != nil {
		s.log.Warn("会话列表读取失败", "project", project, "member", member, "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	s.enrichRoomAttachments(r.Context(), rooms)
	s.log.Info("会话列表响应成功", "project", project, "member", member, "rooms", len(rooms))
	writeJSON(w, http.StatusOK, map[string]any{"rooms": rooms})
}

n_agentd_Server_handleSquadPut.signature:
// handleSquadPut PUT /api/squads/squads/{name}?expect=N：以 CAS 写小队。
// 规则校验（角色词表、成员存在性）权威在 PutSquad，这里只做形状翻译与
// 错误分类（ErrNotFound 臂=成员引用缺失 → 400，schedPutErr=其余）。
func (s *Server) handleSquadPut(w http.ResponseWriter, r *http.Request) {
	name := r.PathValue("name")
	expect, ok, err := expectVersion(r)
	if !ok {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	var in proto.SquadInput
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("解析请求体: %v", err)})
		return
	}
	if in.Name != "" && in.Name != name {
		writeJSON(w, http.StatusBadRequest, map[string]string{
			"error": fmt.Sprintf("请求体 name %q 与路径 %q 不一致", in.Name, name)})
		return
	}
	squad := scheduling.Squad{
		Name:	name, Role: scheduling.SquadRole(in.Role),
		Members:	make([]scheduling.SquadMember, len(in.Members)),
	}
	for i, member := range in.Members {
		squad.Members[i] = scheduling.SquadMember{
			Carrier:	member.Carrier, MaxConcurrency: member.MaxConcurrency,
		}
	}
	memberPolicyCount := 0
	for _, member := range squad.Members {
		if member.MaxConcurrency > 0 {
			memberPolicyCount++
		}
	}
	s.log.Info("登记小队", "name", name, "expect", expect,
		"role", in.Role, "members", len(in.Members),
		"member_policy_count", memberPolicyCount, "empty_members", len(in.Members) == 0)
	if err := s.scheduling.PutSquad(squad, expect); err != nil {
		if errors.Is(err, scheduling.ErrNotFound) {

			s.log.Warn("小队登记被拒（成员引用缺失）", "name", name, "cause", err)
			writeErr(w, http.StatusBadRequest, err)
			return
		}
		s.schedPutErr(w, "小队", name, err)
		return
	}
	s.log.Info("小队登记成功", "name", name, "expect", expect,
		"role", in.Role, "members", len(in.Members),
		"member_policy_count", memberPolicyCount, "empty_members", len(in.Members) == 0,
		"version", expect+1)
	writeJSON(w, http.StatusOK, proto.SquadPutResp{Name: name, Version: expect + 1})
}

n_agentd_Server_handleSquadsGet.signature:
// handleSquadsGet GET /api/squads：载体+小队全量读面（各行带 registry 版本）。
// 未登记时返回空集而非 404——「什么都没配」是合法态（breakdown K3 门禁判据）。
func (s *Server) handleSquadsGet(w http.ResponseWriter, r *http.Request) {
	carrierRows, err := s.scheduling.CarrierRows()
	if err != nil {
		s.log.Error("列载体失败", "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	squadRows, err := s.scheduling.SquadRows()
	if err != nil {
		s.log.Error("列小队失败", "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
		return
	}
	resp := proto.SquadsResp{
		Carriers:	make([]proto.CarrierView, 0, len(carrierRows)),
		Squads:		make([]proto.SquadView, 0, len(squadRows)),
	}
	for _, row := range carrierRows {
		resp.Carriers = append(resp.Carriers, carrierView(row.Carrier, row.Version))
	}
	for _, row := range squadRows {
		resp.Squads = append(resp.Squads, squadView(row.Squad, row.Version))
	}
	s.log.Info("已读取编制登记面", "carriers", len(resp.Carriers), "squads", len(resp.Squads))
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleStatus.signature:
// handleStatus 返回本 agentd 的可用性与身份信息（handoff status 的数据源）。
//
// 注意：
//   - manager 未就绪时返回 503：任务计数与探活都要经 manager，此时没有能给的
//     真实答案，宁可明确报「未就绪」也不返回一个半真的响应
func (s *Server) handleStatus(w http.ResponseWriter, r *http.Request) {
	s.log.Info("状态查询请求", "method", r.Method, "path", r.URL.Path)
	if s.mgr == nil {
		s.log.Error("manager 未就绪，无法回答状态查询")
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	resp, err := s.mgr.Status()
	if err != nil {
		s.log.Error("聚合状态失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		return
	}
	resp.StartedAt = s.startedAt

	if resp.Update != nil {
		yes := true
		resp.Update.Pull = &yes
		resp.Update.PullState = s.pull.snapshot()
	}
	ptyOK := s.pty.Supported()
	resp.PtySupported = &ptyOK
	launchersOK := true
	resp.LaunchersSupported = &launchersOK

	disciplinesOK := true
	resp.DisciplinesSupported = &disciplinesOK
	revealOK := revealSupportedOS
	resp.RevealSupported = &revealOK
	resp.ScratchRoot = s.scratchRoot()
	webEmbedded := webui.Embedded()
	resp.WebEmbedded = &webEmbedded

	if s.pty != nil {
		n := len(s.pty.List())
		resp.PtySessions = &n
	}
	s.log.Info("状态查询完成", "active", len(resp.Active), "executors", len(resp.Executors))
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleStop.signature:
// handleStop 主动中止任务（停 executor、落 failed；作废由终态迁移收口完成）。
//
// 响应体：status=stopped；worktree_removed 是兼容字段，成功 Stop 恒为 false。
// Stop 只落 failed 并留存现场，显式 reclaim/gc 才清理 managed worktree；用户自带
// worktree / 原地模式同样返回 false。CLI 据此打印提示文案，不猜。
//
// 错误映射：任务不存在 404；已是终态 409（manager 返回 store.ErrBadTransit）。
func (s *Server) handleStop(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("stop 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	if s.mgr == nil {
		s.log.Warn("stop 请求到达但 manager 未注入", "remote_addr", r.RemoteAddr)
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	task, taskErr := s.st.GetTask(taskID)
	if taskErr != nil {
		s.log.Error("stop 读取任务快照失败，未执行终态迁移", "task", taskID, "cause", taskErr)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "读取任务快照失败"})
		return
	}
	outcome, err := s.mgr.Stop(r.Context(), taskID)
	if err != nil {
		s.writeManagerError(w, taskID, "stop", err)
		return
	}
	if !outcome.Claimed {

		s.log.Warn("stop 并发竞争失败，任务已被终结", "task", taskID)
		writeJSON(w, http.StatusConflict, map[string]string{"error": "任务已是终态"})
		return
	}
	terminal, snapshotErr := s.st.GetTask(taskID)
	if snapshotErr != nil {

		s.log.Error("stop 成功后读取终态任务快照失败，使用迁移前身份快照释放占用",
			"task", taskID, "cause", snapshotErr)
		s.releaseTaskCarrierOccupancy(task)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "任务已停止但读取终态快照失败"})
		return
	}
	s.releaseTaskCarrierOccupancy(terminal)
	writeJSON(w, http.StatusOK, map[string]any{"status": "stopped", "worktree_removed": outcome.WorktreeRemoved})
}

n_agentd_Server_handleTaskBranches.signature:
// handleTaskBranches 返回任务仓库的本地分支名列表与推导出的默认基准分支。
//
// 供前端审阅栏的基准下拉用（spec 2026-08-17 §6.2）。只读，不做状态门禁。
// default 为空表示推导不出（前端下拉退化为仅「自动推导」项）。
func (s *Server) handleTaskBranches(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("branches 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	task, ok := s.taskOrErr(w, taskID)
	if !ok {
		return
	}
	repo := task.Workdir()
	branches, err := workspace.Branches(repo)
	if err != nil {
		s.log.Error("列分支失败", "task", taskID, "repo", repo, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	s.log.Info("branches 完成", "task", taskID, "count", len(branches))
	writeJSON(w, http.StatusOK, map[string]any{
		"branches":	branches,
		"default":	workspace.ResolveBaseBranch(repo),
		"task_base":	task.BaseCommit,
	})
}

n_agentd_Server_handleTaskBundle.signature:
// handleTaskBundle 吐任务分支的 git bundle，供协调者 pull 时不经 ssh 取回改动。
//
// 请求：GET /api/tasks/{id}/bundle?have=<sha>
//   - have 给了：生成 <have>..<branch> 的薄包（常态，通常几百字节）
//   - have 空：  生成全量包（协调者手上没有基线时的罕见退路）
//
// 响应：
//   - 200 application/octet-stream，带 Content-Length
//   - **没有 204**：区间为空时 BundleRange 自动放宽区间（§5.2），照样产出一个
//     带 ref 的包。客户端的本地分支引用是 fetch 的副产品，短路掉 fetch 就会让
//     「已是最新」在协调者手上什么都没有的情况下打出来
//   - 400 任务无分支 / have 在任务仓库中不存在 / 参数以 - 开头
//   - 404 任务不存在（byTask 已处理）
//   - 500 git 失败
//
// 注意：
//   - 用 task.RepoPath（主仓库）而不是 Workdir()：worktree 是主仓的从属工作树，
//     分支对象在主仓库里。这与 handleTaskDiff 不同，那个要的是工作树状态
//   - 先把包落临时文件再整体发出，**不**把 git 的输出直接流进 ResponseWriter：
//     直接流的话 git 中途失败时响应头早已发出，客户端收到的是一个截断的 200——
//     一次服务端故障被伪装成内容不完整的成功
func (s *Server) handleTaskBundle(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	have := r.URL.Query().Get("have")
	s.log.Info("bundle 请求", "method", r.Method, "path", r.URL.Path, "task", taskID, "have", have)
	task, ok := s.taskOrErr(w, taskID)
	if !ok {
		return
	}
	if task.Branch == "" {
		s.log.Warn("任务尚无分支，无可打包", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "任务尚无分支，无可同步"})
		return
	}
	start := time.Now()
	path, err := workspace.BundleRange(r.Context(), task.RepoPath, have, task.Branch)
	switch {
	case errors.Is(err, workspace.ErrHaveMissing), errors.Is(err, workspace.ErrBadBaseBranch):

		s.log.Warn("bundle 请求参数被拒", "task", taskID, "have", have, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	case err != nil:
		s.log.Error("生成 bundle 失败", "task", taskID, "repo", task.RepoPath,
			"branch", task.Branch, "have", have, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	defer os.Remove(path)

	f, err := os.Open(path)
	if err != nil {
		s.log.Error("打开生成的 bundle 失败", "task", taskID, "path", path, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		s.log.Error("读取 bundle 大小失败", "task", taskID, "path", path, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Length", strconv.FormatInt(fi.Size(), 10))
	n, err := io.Copy(w, f)
	if err != nil {

		s.log.Error("发送 bundle 中断", "task", taskID, "sent", n, "total", fi.Size(), "cause", err)
		return
	}
	s.log.Info("bundle 发送完成", "task", taskID, "branch", task.Branch, "have", have,
		"bytes", n, "elapsed_ms", time.Since(start).Milliseconds())
}

n_agentd_Server_handleTaskDiff.signature:
// handleTaskDiff 返回任务分支相对基准分支的审阅素材（git diff + 提交列表）。
//
// 参数：
//   - base: 查询参数，基准；缺省时优先用任务 BaseCommit，没有才按仓库推导
//
// 注意：
//   - diff 是协调者主动发起的只读审阅，不做状态门禁——running 中即可看实时进度
func (s *Server) handleTaskDiff(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("diff 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	task, ok := s.taskOrErr(w, taskID)
	if !ok {
		return
	}
	repo, headRev := workspace.TaskDiffTarget(task)
	base := r.URL.Query().Get("base")
	if base == "" {
		base = workspace.DiffBaseFor(task, repo)
	}
	s.log.Info("diff 基准已确定", "task", taskID, "base", base,
		"from_task_base", r.URL.Query().Get("base") == "" && task.BaseCommit != "")
	if base == "" {
		s.log.Warn("无法确定基准分支", "task", taskID, "repo", repo)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "无法确定基准分支，请用 base 参数指定"})
		return
	}

	if repo != task.Workdir() && !workspace.ManualBranchExists(r.Context(), repo, headRev) {
		s.log.Warn("任务分支已不存在，无可比对素材", "task", taskID, "repo", repo, "branch", headRev)
		writeJSON(w, http.StatusNotFound, map[string]string{
			"error": fmt.Sprintf("任务分支 %s 已不存在，且任务 worktree 已回收——没有可比对的素材了", headRev)})
		return
	}
	if s.mgr == nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	ref, err := s.mgr.AssembleResultRef(r.Context(), task, repo, headRev)
	if err != nil {
		s.log.Error("组装任务结果引用失败", "task", taskID, "repo", repo,
			"head_rev", headRev, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}

	head := headRev
	if ref.Commit != "" {
		head = ref.Commit
		s.log.Info("任务 diff 使用结果引用 commit", "task", taskID, "repo", repo,
			"head_rev", headRev, "commit", ref.Commit, "result_path", ref.Path,
			"result_path_empty", ref.Path == "")
	} else {
		s.log.Warn("ResultRef 缺少准确 commit，按任务分支降级", "task", taskID,
			"repo", repo, "head_rev", headRev, "result_path", ref.Path,
			"result_path_empty", ref.Path == "", "commit_fallback", true,
			"cause", "assembleResultRef 未取得有效 commit")
	}
	if err := s.mgr.RequireWorkspace(); err != nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	s.log.Info("开始取得任务 diff", "task", taskID, "repo", repo, "base", base, "head", head)
	diff, err := s.mgr.Workspace().DiffRange(r.Context(), repo, base, head)
	if err != nil {
		if errors.Is(err, workspace.ErrBadBaseBranch) {

			s.log.Warn("diff 基准分支非法被拒绝", "task", taskID, "base", base)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": truncateRunes(err.Error(), 200)})
			return
		}
		s.log.Error("取 diff 失败", "task", taskID, "repo", repo, "base", base, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	s.log.Info("diff 完成", "task", taskID, "base", base, "bytes", len(diff))
	writeJSON(w, http.StatusOK, map[string]string{"diff": diff})
}

n_agentd_Server_handleTaskFile.signature:
// handleTaskFile 返回任务仓库内指定文件的内容（协调者取上下文用）。
//
// 参数：
//   - path: 查询参数，相对仓库根的路径（必须）；逃逸出仓库的路径返回 400
func (s *Server) handleTaskFile(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	rel := r.URL.Query().Get("path")
	s.log.Info("file 请求", "method", r.Method, "path", r.URL.Path, "task", taskID, "file", rel)
	repo, ok := s.taskRepoOrErr(w, taskID)
	if !ok {
		return
	}
	if rel == "" {
		s.log.Warn("file 请求缺 path 参数", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "缺少 path 参数"})
		return
	}
	if s.mgr == nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": "manager 未就绪"})
		return
	}
	if err := s.mgr.RequireWorkspace(); err != nil {
		writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
		return
	}
	fc, err := s.mgr.Workspace().ReadFile(r.Context(), repo, rel)
	if err != nil {
		switch {
		case errors.Is(err, workspace.ErrPathEscape):
			s.log.Warn("file 路径逃逸被拒绝", "task", taskID, "path", rel)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "路径不合法（不允许逃出任务仓库）"})
		case errors.Is(err, fs.ErrNotExist):
			s.log.Warn("file 目标不存在", "task", taskID, "path", rel)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "文件不存在"})
		case errors.Is(err, workspace.ErrPathIsDir):

			s.log.Warn("file 目标是目录", "task", taskID, "path", rel)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "路径是目录，不是文件"})
		case errors.Is(err, workspace.ErrNotRegularFile):
			s.log.Warn("file 目标不是普通文件", "task", taskID, "path", rel)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "路径不是普通文件"})
		default:
			s.log.Error("读取文件失败", "task", taskID, "path", rel, "cause", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "读取文件失败"})
		}
		return
	}
	res := proto.FileRead{
		Content:	fc.Content,
		Size:		fc.Size,
		Truncated:	fc.Truncated,
		Binary:		fc.Binary,
		SHA256:		fc.SHA256,
	}

	content := res.Content
	if res.Truncated {
		content += workspace.TruncatedNotice(res.Size)
	}
	writeJSON(w, http.StatusOK, map[string]string{"content": content})
}

n_agentd_Server_handleTaskFrames.signature:
// handleTaskFrames 流式输出任务的 frames.jsonl。
//
// 查询参数（语义与 /render 完全一致，单位都是**字节**）：
//   - offset: 起始字节偏移；与 tail 互斥，两者都不给时按 framesDefaultTail 回溯
//   - tail:   从文件尾部回溯的字节数
//   - follow: 1 表示到达文件尾后不关闭连接，持续追送增量
//
// 响应：200 + application/x-ndjson 流；响应头 X-Handoff-Frames-Size 为响应
// 开始时的文件大小。
//
// 注意：
//   - frames.jsonl 尚不存在时返回 200 空内容而非 404——任务刚 dispatch、
//     模型还没产出第一帧是正常状态（与 /render 同一处置）
//   - 客户端断开时 r.Context() 被取消，本函数随即返回，不留 goroutine
func (s *Server) handleTaskFrames(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	if _, ok := s.taskRepoOrErr(w, taskID); !ok {
		return
	}
	framesPath := filepath.Join(s.conf().DataDir, "tasks", taskID, turn.FramesFileName)

	size := renderSize(framesPath)
	offset, err := renderStartOffset(r, size)
	if err != nil {
		s.log.Warn("frames 请求参数非法", "task", taskID, "cause", err)
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	follow := r.URL.Query().Get("follow") == "1"

	w.Header().Set("Content-Type", "application/x-ndjson")
	w.Header().Set("X-Handoff-Frames-Size", strconv.FormatInt(size, 10))
	w.WriteHeader(http.StatusOK)
	flusher, _ := w.(http.Flusher)

	s.log.Info("frames 流开始", "task", taskID, "offset", offset, "size", size, "follow", follow)
	sent, err := streamFrames(r.Context(), w, flusher, framesPath, offset, follow)
	if err != nil && !errors.Is(err, context.Canceled) {
		s.log.Error("frames 流中断", "task", taskID, "sent", sent, "cause", err)
		return
	}
	s.log.Info("frames 流结束", "task", taskID, "sent", sent)
}

n_agentd_Server_handleTaskPlan.signature:
// handleTaskPlan 处理 GET /api/tasks/{id}/plan。
//
// 响应：
//   - 200 proto.TaskPlan：指令原文（超过 maxPlanBytes 时截断并置 truncated）
//   - 404：任务不存在 / 该任务没有归档指令（老任务）/ 归档文件已被删除
//
// 注意：文件缺失返回 404 而不是 200 空串——「没有这份东西」与「这份东西是空的」
// 对界面是两件事，后者会被画成一个空气泡。
func (s *Server) handleTaskPlan(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("派发指令请求", "method", r.Method, "path", r.URL.Path, "task", taskID)

	task, err := s.st.GetTask(taskID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			s.log.Warn("派发指令请求：任务不存在", "task", taskID)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "任务不存在"})
			return
		}
		s.log.Error("派发指令请求：查任务失败", "task", taskID, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		return
	}
	if task.PlanPath == "" {
		s.log.Warn("派发指令请求：任务没有归档指令", "task", taskID)
		writeJSON(w, http.StatusNotFound, map[string]string{
			"error": "该任务没有归档派发指令（派发于本功能上线之前）"})
		return
	}

	fi, err := os.Stat(task.PlanPath)
	if err != nil {

		s.log.Warn("派发指令请求：归档文件不可读", "task", taskID, "path", task.PlanPath, "cause", err)
		writeJSON(w, http.StatusNotFound, map[string]string{
			"error": "派发指令文件已不存在：" + task.PlanPath})
		return
	}
	data, err := os.ReadFile(task.PlanPath)
	if err != nil {
		s.log.Error("派发指令请求：读取失败", "task", taskID, "path", task.PlanPath, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "读取派发指令失败"})
		return
	}
	truncated := false
	if len(data) > maxPlanBytes {
		data = data[:maxPlanBytes]
		truncated = true
	}
	s.log.Info("派发指令完成", "task", taskID, "name", filepath.Base(task.PlanPath),
		"size", fi.Size(), "truncated", truncated)
	writeJSON(w, http.StatusOK, proto.TaskPlan{
		Name:		filepath.Base(task.PlanPath),
		Content:	string(data),
		Size:		fi.Size(),
		Truncated:	truncated,
	})
}

n_agentd_Server_handleTaskRender.signature:
// handleTaskRender 流式输出任务的 render.log。
//
// 查询参数：
//   - offset: 起始字节偏移；与 tail 互斥，两者都不给时按 renderDefaultTail 回溯
//   - tail:   从文件尾部回溯的字节数
//   - follow: 1 表示到达文件尾后不关闭连接，持续追送增量
//
// 响应：200 + text/plain 流；响应头 X-Handoff-Render-Size 为响应开始时的文件大小。
//
// 注意：
//   - render.log 尚不存在时返回 200 空内容而非 404——任务刚 dispatch、模型还没
//     吐第一个字是完全正常的状态，attach 应该连上等着，而不是报错让人以为任务不对
//   - 客户端断开（Ctrl+C）时 r.Context() 被取消，本函数随即返回，不留 goroutine
func (s *Server) handleTaskRender(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	if _, ok := s.taskRepoOrErr(w, taskID); !ok {
		return
	}
	renderPath := filepath.Join(s.conf().DataDir, "tasks", taskID, "render.log")

	size := renderSize(renderPath)
	offset, err := renderStartOffset(r, size)
	if err != nil {
		s.log.Warn("render 请求参数非法", "task", taskID, "cause", err)
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	follow := r.URL.Query().Get("follow") == "1"

	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("X-Handoff-Render-Size", strconv.FormatInt(size, 10))
	w.WriteHeader(http.StatusOK)
	flusher, _ := w.(http.Flusher)

	s.log.Info("render 流开始", "task", taskID, "offset", offset, "size", size, "follow", follow)
	sent, err := streamRender(r.Context(), w, flusher, renderPath, offset, follow)
	if err != nil && !errors.Is(err, context.Canceled) {

		s.log.Error("render 流中断", "task", taskID, "sent", sent, "cause", err)
		return
	}
	s.log.Info("render 流结束", "task", taskID, "sent", sent)
}

n_agentd_Server_handleTaskRun.signature:
// handleTaskRun 在任务仓库执行一条审阅命令（sh -c），返回合并输出与退出码。
//
// 注意：这是协调者主动发起的只读审阅动作（跑测试/lint），**不走审批门**——
// 命令由协调者指定并经 sh 执行，agentd 只负责执行、限时（10min 超时被杀，退出码
// 124）与回收。命令非零退出同样返回 200，退出码在响应体中表达。
func (s *Server) handleTaskRun(w http.ResponseWriter, r *http.Request) {
	taskID := r.PathValue("id")
	s.log.Info("run 请求", "method", r.Method, "path", r.URL.Path, "task", taskID)
	repo, ok := s.taskRepoOrErr(w, taskID)
	if !ok {
		return
	}
	var req runRequest

	if err := json.NewDecoder(io.LimitReader(r.Body, 1<<20)).Decode(&req); err != nil {
		s.log.Warn("run 请求体解析失败", "task", taskID, "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求体必须是 JSON {cmd}"})
		return
	}
	if strings.TrimSpace(req.Cmd) == "" {
		s.log.Warn("run 命令为空", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "cmd 不能为空"})
		return
	}
	stdout, exitCode, err := workspace.RunCmd(r.Context(), repo, req.Cmd)
	if err != nil {
		if errors.Is(err, ErrNoProcHeadroom) || errors.Is(err, workspace.ErrWorkdirGone) {
			s.log.Warn("run 被拒", "task", taskID, "repo", repo,
				"cmd", truncateRunes(req.Cmd, 200), "cause", err)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": truncateRunes(err.Error(), 200)})
			return
		}
		s.log.Error("run 执行失败", "task", taskID, "cmd", truncateRunes(req.Cmd, 200), "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": truncateRunes(err.Error(), 200)})
		return
	}
	writeJSON(w, http.StatusOK, runResponse{Stdout: stdout, ExitCode: exitCode})
}

n_agentd_Server_handleUpdate.signature:
// handleUpdate 处理换版请求。
//
// 请求：POST /api/update?tag=&sha256=&force=，body 为 tar.gz 原文；
// **body 为空表示只重启不换版**——本机的二进制由 CLI 直接换掉了，
// 但正在跑的 agentd 仍是旧进程，需要重启才生效（spec D8）。
//
// 注意：
//   - 两道闸的检查顺序是「闸二在前」：非托管是硬拒绝，先说这一条能让操作者
//     少绕一圈（他会先去装服务，而不是先去等任务结束）
//   - 触发关停必须在写完响应之后。优雅关停会等在途请求结束，所以本 handler
//     返回前进程不会退——但反过来先 Trigger 再写响应，客户端拿到的就是一个
//     断掉的连接，等于把一次成功的换版报成失败
func (s *Server) handleUpdate(w http.ResponseWriter, r *http.Request) {
	force := r.URL.Query().Get("force") != ""
	tag := r.URL.Query().Get("tag")
	sum := r.URL.Query().Get("sha256")
	s.log.Info("换版请求", "tag", tag, "force", force, "content_length", r.ContentLength)

	if !selfupdate.IsManaged(s.upd.Getenv) {
		s.log.Warn("换版被拒：agentd 非托管启动", "tag", tag, "force", force)
		writeJSON(w, http.StatusConflict, proto.UpdateError{
			Error:	"agentd 非托管启动，换版后没有进程管理器把它拉起来",
			Reason:	proto.UpdateReasonUnmanaged,
		})
		return
	}

	busy, err := s.activeCount()
	if err != nil {
		s.log.Error("换版预检：查任务列表失败", "cause", err)
		writeJSON(w, http.StatusInternalServerError, proto.UpdateError{Error: "内部错误"})
		return
	}
	if busy > 0 && !force {
		s.log.Warn("换版被拒：有活跃任务", "tag", tag, "busy", busy)
		writeJSON(w, http.StatusConflict, proto.UpdateError{
			Error:	fmt.Sprintf("有 %d 个活跃任务（running/waiting_answer）", busy),
			Reason:	proto.UpdateReasonBusy,
		})
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, maxUpdateBytes))
	if err != nil {
		s.log.Error("换版：读请求体失败", "tag", tag, "cause", err)
		writeJSON(w, http.StatusBadRequest, proto.UpdateError{Error: "读请求体: " + err.Error()})
		return
	}

	mode := r.URL.Query().Get("mode")
	switch mode {
	case "", proto.UpdateModePush, proto.UpdateModePull:
	default:

		s.log.Warn("换版被拒：未知 mode", "mode", mode, "tag", tag)
		writeJSON(w, http.StatusBadRequest, proto.UpdateError{
			Error: fmt.Sprintf("未知 mode %q，只支持 %q 与 %q（省略 mode 时按 body 空不空判别）",
				mode, proto.UpdateModePull, proto.UpdateModePush),
		})
		return
	}

	if mode == proto.UpdateModePush && len(body) == 0 {
		s.log.Warn("换版被拒：mode=push 但 body 为空", "tag", tag)
		writeJSON(w, http.StatusBadRequest, proto.UpdateError{
			Error: "mode=push 必须带 tar.gz 原文；只想重启请省略 mode 并发空 body",
		})
		return
	}
	if mode == proto.UpdateModePull && len(body) > 0 {
		s.log.Warn("换版被拒：mode=pull 但带了 body", "tag", tag, "bytes", len(body))
		writeJSON(w, http.StatusBadRequest, proto.UpdateError{
			Error: "mode=pull 由 agentd 自己下载，不接受 body",
		})
		return
	}

	if mode == proto.UpdateModePull {
		s.handlePullUpdate(w, tag, sum, busy)
		return
	}

	if len(body) == 0 {
		s.log.Info("换版：body 为空，只重启不换版", "busy", busy)
		writeJSON(w, http.StatusOK, proto.UpdateResp{OK: true, Restarted: true})
		s.triggerRestart("收到重启请求")
		return
	}

	if s.pull.busy() {
		s.log.Warn("换版被拒：已有自拉换版在进行中", "tag", tag)
		writeJSON(w, http.StatusConflict, proto.UpdateError{
			Error:	"已有自拉换版在进行中，等它跑完再推送；去 status 看 pull_state",
			Reason:	proto.UpdateReasonPullInProgress,
		})
		return
	}

	if tag == "" || sum == "" {
		s.log.Warn("换版被拒：带 body 但缺 tag 或 sha256", "tag", tag, "has_sum", sum != "")
		writeJSON(w, http.StatusBadRequest, proto.UpdateError{
			Error: "带二进制时 tag 与 sha256 都必须给：缺了它们无从校验完整性，也无从自检",
		})
		return
	}

	target, err := s.upd.Executable()
	if err != nil {
		s.log.Error("换版：取当前二进制路径失败", "tag", tag, "cause", err)
		writeJSON(w, http.StatusInternalServerError, proto.UpdateError{Error: "取当前二进制路径: " + err.Error()})
		return
	}

	s.log.Info("换版：开始校验与解包", "tag", tag, "target", target, "bytes", len(body))
	newPath, err := s.upd.Install(body, sum, tag, filepath.Dir(target))
	if err != nil {
		s.log.Error("换版被拒：校验或自检未通过", "tag", tag, "cause", err)
		writeJSON(w, http.StatusBadRequest, proto.UpdateError{Error: err.Error()})
		return
	}
	prev, err := s.upd.Activate(newPath, target)
	if err != nil {
		s.log.Error("换版失败：替换二进制出错", "tag", tag, "target", target, "cause", err)
		writeJSON(w, http.StatusInternalServerError, proto.UpdateError{Error: "替换二进制: " + err.Error()})
		return
	}

	s.log.Info("换版完成，准备重启", "tag", tag, "target", target, "prev", prev, "busy", busy)
	writeJSON(w, http.StatusOK, proto.UpdateResp{OK: true, Version: tag, Prev: prev, Restarted: true})
	s.triggerRestart("换版到 " + tag)
}

n_agentd_Server_handleUpdateLatest.signature:
// handleUpdateLatest 返回缓存的最新 release tag。
//
// 参数：refresh=1 时忽略 24h 缓存；其他参数不改变缓存策略。
// 返回：始终 200 + LatestResp；查找失败时 Tag 为空，不把网络故障升级成控制台故障。
func (s *Server) handleUpdateLatest(w http.ResponseWriter, r *http.Request) {
	refresh := r.URL.Query().Get("refresh") == "1"
	c, err := s.loadLatestCheck(r.Context(), refresh)
	if err != nil {
		s.log.Error("查最新版失败，按空结果返回", "refresh", refresh, "cause", err)
		writeJSON(w, http.StatusOK, proto.LatestResp{})
		return
	}
	writeJSON(w, http.StatusOK, latestResp(c))
}

n_agentd_Server_handleWorkbenchBasePut.signature:
// handleWorkbenchBasePut 处理 PUT /api/workbench/state/base。
//
// 请求体 proto.WorkbenchBaseReq：Payload 取 null 表示删除该行。
// 响应：200 空对象 / 400 参数错（坏 JSON、空 base_key、payload 超长）/ 500 写库失败。
func (s *Server) handleWorkbenchBasePut(w http.ResponseWriter, r *http.Request) {
	var req proto.WorkbenchBaseReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("工作台基准行写入：请求体无法解码", "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	if req.BaseKey == "" {
		s.log.Warn("工作台基准行写入：base_key 为空")
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "base_key 不能为空"})
		return
	}
	if req.Payload == nil {
		if err := s.st.DeleteWorkbenchBase(req.BaseKey); err != nil {
			s.log.Error("删除工作台基准行失败", "base_key", req.BaseKey, "err", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
			return
		}
		s.log.Debug("工作台基准行已删除", "key", req.BaseKey, "payload_bytes", 0)
		writeJSON(w, http.StatusOK, map[string]string{})
		return
	}
	if len(*req.Payload) > maxWorkbenchPayload {
		s.log.Warn("工作台基准行写入：payload 超长",
			"base_key", req.BaseKey, "bytes", len(*req.Payload), "limit", maxWorkbenchPayload)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "payload 超过长度上限"})
		return
	}
	if err := s.st.PutWorkbenchBase(req.BaseKey, *req.Payload, nowMilli()); err != nil {
		s.log.Error("写工作台基准行失败", "base_key", req.BaseKey, "err", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Debug("工作台基准行已写入", "base_key", req.BaseKey, "bytes", len(*req.Payload))
	writeJSON(w, http.StatusOK, map[string]string{})
}

n_agentd_Server_handleWorkbenchDockPut.signature:
// handleWorkbenchDockPut 处理 PUT /api/workbench/state/dock。
//
// 请求体 proto.WorkbenchDockReq：Payload 取 null 表示清空悬浮窗现场。
// 响应：200 空对象 / 400 参数错 / 500 写库失败。
func (s *Server) handleWorkbenchDockPut(w http.ResponseWriter, r *http.Request) {
	var req proto.WorkbenchDockReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("悬浮窗现场写入：请求体无法解码", "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	if req.Payload == nil {
		if err := s.st.DeleteWorkbenchSingleton(store.WorkbenchKeyDock); err != nil {
			s.log.Error("清空悬浮窗现场失败", "err", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
			return
		}
		s.log.Debug("悬浮窗现场已清空", "key", store.WorkbenchKeyDock, "payload_bytes", 0)
		writeJSON(w, http.StatusOK, map[string]string{})
		return
	}
	if len(*req.Payload) > maxWorkbenchPayload {
		s.log.Warn("悬浮窗现场写入：payload 超长", "bytes", len(*req.Payload), "limit", maxWorkbenchPayload)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "payload 超过长度上限"})
		return
	}
	if err := s.st.PutWorkbenchSingleton(store.WorkbenchKeyDock, *req.Payload, nowMilli()); err != nil {
		s.log.Error("写悬浮窗现场失败", "err", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Debug("悬浮窗现场已写入", "key", store.WorkbenchKeyDock,
		"payload_bytes", len(*req.Payload))
	writeJSON(w, http.StatusOK, map[string]string{})
}

n_agentd_Server_handleWorkbenchSelectedP.signature:
// handleWorkbenchSelectedPut 处理 PUT /api/workbench/state/selected。
//
// 请求体 proto.WorkbenchSelectedReq。BaseKey 为空串是**合法状态**（当前没选中任何目录），
// 落库成空串而不是删行——删行与存空串在读取端等价，但存空串让「用户确实取消了选中」
// 与「从来没写过」在库里可区分，排障时有用。
//
// 响应：200 空对象 / 400 坏 JSON / 500 写库失败。
func (s *Server) handleWorkbenchSelectedPut(w http.ResponseWriter, r *http.Request) {
	var req proto.WorkbenchSelectedReq
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		s.log.Warn("选中目录写入：请求体无法解码", "err", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
		return
	}
	if len(req.BaseKey) > maxWorkbenchPayload {
		s.log.Warn("选中目录写入：base_key 超长", "bytes", len(req.BaseKey))
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "base_key 超过长度上限"})
		return
	}
	if err := s.st.PutWorkbenchSingleton(store.WorkbenchKeySelected, req.BaseKey, nowMilli()); err != nil {
		s.log.Error("写选中目录失败", "base_key", req.BaseKey, "err", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	s.log.Debug("选中目录已写入", "key", store.WorkbenchKeySelected, "base_key", req.BaseKey,
		"payload_bytes", len(req.BaseKey))
	writeJSON(w, http.StatusOK, map[string]string{})
}

n_agentd_Server_handleWorkbenchStateGet.signature:
// handleWorkbenchStateGet 处理 GET /api/workbench/state。
//
// 响应：200 proto.WorkbenchStateResp / 500 读库失败。
//
// 注意：Selected 与 Dock 缺席时返回**空串**而不是缺键——两者都是「当前没有」
// 这个明确结论，缺键会让前端分不清它和「这版服务端还不认识这个字段」。
// Bases 恒为数组（可能为空），不返回 null，省掉前端一条判空分支。
func (s *Server) handleWorkbenchStateGet(w http.ResponseWriter, r *http.Request) {
	bases, singles, err := s.st.ListWorkbench()
	if err != nil {
		s.log.Error("读取工作台状态失败", "err", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
		return
	}
	resp := proto.WorkbenchStateResp{
		Selected:	singles[store.WorkbenchKeySelected],
		Dock:		singles[store.WorkbenchKeyDock],
		Bases:		bases,
	}
	payloadBytes := len(resp.Selected) + len(resp.Dock)
	for _, base := range resp.Bases {
		payloadBytes += len(base.Payload)
	}
	s.log.Debug("工作台状态查询完成",
		"key", "state", "bases", len(resp.Bases), "payload_bytes", payloadBytes)
	writeJSON(w, http.StatusOK, resp)
}

n_agentd_Server_handleWorkspaceDir.signature:
// handleWorkspaceDir 处理 GET /api/workspaces/dir?path=&rel=[&machine=]。
//
// 参数：
//   - path: 工作树绝对路径（必须，且必须命中白名单，否则 400）
//   - rel: 工作树内的相对目录路径；省略或空串表示工作树根
//   - machine: 可选，转发到指定机器（复用 forwardIfRequested）
func (s *Server) handleWorkspaceDir(w http.ResponseWriter, r *http.Request) {
	if s.forwardIfRequested(w, r) {
		return
	}
	rel := r.URL.Query().Get("rel")
	s.log.Info("工作树目录列举请求", "path", r.URL.Query().Get("path"), "rel", rel)
	root, ok := s.workspaceRootOrErr(w, r)
	if !ok {
		return
	}
	entries, err := workspace.ListDir(root, rel)
	if err != nil {
		switch {
		case errors.Is(err, workspace.ErrPathEscape):
			s.log.Warn("目录列举路径逃逸被拒绝", "root", root, "rel", rel)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "路径不合法（不允许逃出工作树）"})
		case errors.Is(err, fs.ErrNotExist):
			s.log.Warn("目录列举目标不存在", "root", root, "rel", rel)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "目录不存在"})
		case errors.Is(err, workspace.ErrPathNotDir):
			s.log.Warn("目录列举目标不是目录", "root", root, "rel", rel)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "路径不是目录"})
		default:
			s.log.Error("目录列举失败", "root", root, "rel", rel, "cause", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "目录列举失败"})
		}
		return
	}

	workspace.MarkIgnored(r.Context(), root, rel, entries)
	s.log.Info("工作树目录列举完成", "root", root, "rel", rel, "entries", len(entries))
	writeJSON(w, http.StatusOK, proto.DirListResult{Entries: entries})
}

