n_agentd_Server_loadLatestCheck.signature:
// loadLatestCheck 读取或刷新 CLI/薄壳共用的 24h release 缓存。
//
// 参数：ctx 用于 release 查询；refresh=true 强制查询。
// 返回：缓存内容；网络、缓存写入或依赖缺失错误由调用方转成空 tag。
func (s *Server) loadLatestCheck(ctx context.Context, refresh bool) (*selfupdate.CLICheck, error) {
	cached := selfupdate.LoadCLICheck(s.conf().DataDir)
	now := time.Now().UTC()
	if !refresh && !selfupdate.CLICheckStale(cached, now) {
		return cached, nil
	}
	if s.latestFetch == nil {
		return nil, errors.New("最新版查询依赖未注入")
	}
	rel, err := s.latestFetch(ctx)
	if err != nil {
		return nil, err
	}
	c := &selfupdate.CLICheck{CheckedAt: now, Latest: rel.Tag}
	if err := selfupdate.SaveCLICheck(s.conf().DataDir, c); err != nil {
		return nil, fmt.Errorf("保存最新版缓存: %w", err)
	}
	return c, nil
}

n_agentd_Server_localMachine.signature:
// localMachine 投影本机：进程内直查，不自拨 HTTP（自拨会在 agentd 忙时把
// 自己的健康状态也一起拖垮，且毫无必要）。
func (s *Server) localMachine() proto.Machine {
	m := proto.Machine{
		Name:	"", Addr: s.conf().Listen, Reachable: true,
		Executors:	[]string{}, ProbeMs: 0, ScratchRoot: s.scratchRoot(),
	}
	if s.mgr == nil {

		m.Error = "manager 未就绪"
		return m
	}
	st, err := s.mgr.Status()
	if err != nil {
		s.log.Warn("本机探活：聚合状态失败", "cause", err)
		m.Error = err.Error()
		return m
	}
	fillFromStatus(&m, st)

	m.ScratchRoot = s.scratchRoot()

	ptyOK := s.pty.Supported()
	m.PtySupported = &ptyOK
	launchersOK := true
	m.LaunchersSupported = &launchersOK

	disciplinesOK := true
	m.DisciplinesSupported = &disciplinesOK
	revealOK := revealSupportedOS
	m.RevealSupported = &revealOK
	return m
}

n_agentd_Server_lookupRoomAttach.signature:
// lookupRoomAttach 只接受真实任务详情和 Workdir()；不从 bound_session 猜测 task。
// localTasks 是列表装配点的一次性本机任务索引，避免逐挂账查询。
func (s *Server) lookupRoomAttach(ctx context.Context, link ledger.TaskLink, localTasks map[string]proto.Task) (*proto.RoomAttach, error) {
	var workDir string
	if link.Target == "" {
		task, ok := localTasks[link.TaskID]
		if !ok {
			return nil, fmt.Errorf("读取本机任务 %s: 任务不存在", link.TaskID)
		}
		workDir = task.Workdir()
	} else {
		peer, err := s.pool.For(link.Target)
		if err != nil {
			return nil, fmt.Errorf("获取 target %s 客户端: %w", link.Target, err)
		}
		info, err := peer.Attach(ctx, link.TaskID)
		if err != nil {
			return nil, fmt.Errorf("读取远端任务 %s: %w", link.TaskID, err)
		}
		workDir = info.Task.Workdir()
	}
	if strings.TrimSpace(workDir) == "" {
		return nil, errors.New("任务没有可用工作目录")
	}
	return &proto.RoomAttach{
		Target:	link.Target, TaskID: link.TaskID, WorkDir: workDir,
		Command:	"handoff attach " + link.TaskID,
	}, nil
}

