n_agentd_Server_openCoordinatorTUI.signature:
func (s *Server) openCoordinatorTUI(card string, carrier scheduling.Carrier, spec keysclient.SessionSpec) (string, error) {
	if s.openCoordTUI != nil {
		return s.openCoordTUI(card, carrier, spec)
	}

	localAlias := scheduling.IsLocalMachine(carrier.Machine)
	selfTarget := s.IsSelfTarget(carrier.Machine)
	if !localAlias && !selfTarget {
		s.log.Info("协调者 TUI 转发到远端", "card", card, "machine", carrier.Machine)
		return s.openRemoteCoordinatorTUI(card, carrier, spec)
	}
	if s.pty == nil {
		return "", fmt.Errorf("PTY 未装配，无法打开协调者 TUI")
	}
	workdir := spec.Workdir
	if workdir == "" {
		workdir = s.resolveCoordWorkdir(card)
	}
	if workdir == "" {
		return "", fmt.Errorf("卡 %s 没有项目主工作树，无法打开协调者 TUI", card)
	}
	if selfTarget && !localAlias {
		s.log.Info("协调者 TUI 把本机 target 名当本地", "card", card, "machine", carrier.Machine)
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}
	cmd := coordTUIInitCommand(carrier, spec)
	env := pinGrokOsc52Sink(append(s.sessionEnv(), "HANDOFF_CARD="+card))
	s.log.Info("打开协调者 TUI", "card", card, "machine", carrier.Machine,
		"cli", spec.CLI, "workdir", workdir, "home_empty", strings.TrimSpace(carrier.HomeDir) == "")
	sess, err := s.pty.Open(ptyhost.OpenOptions{
		BasePath:	workdir, BaseKind: "workspace", Shell: shell,
		Env:	env, Cols: 120, Rows: 32, InitCommand: cmd,
	})
	if err != nil {
		s.log.Error("打开协调者 TUI 失败", "card", card, "workdir", workdir, "cli", spec.CLI, "cause", err)
		return "", err
	}
	s.log.Info("协调者 TUI 已打开", "card", card, "pty", sess.ID, "pid", sess.PID, "workdir", workdir)
	return sess.ID, nil
}

n_agentd_Server_openRemoteCoordinatorTUI.signature:
func (s *Server) openRemoteCoordinatorTUI(card string, carrier scheduling.Carrier, spec keysclient.SessionSpec) (string, error) {
	workdir, err := s.remoteCoordWorkdir(carrier.Machine, card)
	if err != nil {
		s.log.Error("解析远端协调者工作目录失败", "card", card, "machine", carrier.Machine, "cause", err)
		return "", err
	}
	if workdir == "" {
		return "", fmt.Errorf("卡 %s 在机器 %s 没有项目主工作树，无法打开协调者 TUI", card, carrier.Machine)
	}
	req := proto.CreatePtySessionReq{
		BasePath:	workdir, BaseKind: "workspace",
		Cols:	120, Rows: 32, InitCommand: coordTUIInitCommand(carrier, spec),
	}
	s.log.Info("打开远端协调者 TUI", "card", card, "machine", carrier.Machine,
		"cli", spec.CLI, "workdir", workdir)
	id, err := s.createRemoteCoordinatorPty(carrier.Machine, req)
	if err != nil {
		s.log.Error("打开远端协调者 TUI 失败", "card", card, "machine", carrier.Machine,
			"workdir", workdir, "cli", spec.CLI, "cause", err)
		return "", err
	}
	s.log.Info("远端协调者 TUI 已打开", "card", card, "machine", carrier.Machine, "pty", id, "workdir", workdir)
	return id, nil
}

n_agentd_Server_prepareReceiverBinding.signature:
// prepareReceiverBinding 是裸派发的完整准备链：ResolveLookup → 准入 → BindPhysical。
// 返回的 Binding 是可交给 Manager 的身份快照；准入已成功但后续绑定失败时，本函数
// 负责释放本次占用。
func (s *Server) prepareReceiverBinding(requested string, overlay scheduling.PhysicalOverlay, requestModel string) (scheduling.Binding, scheduling.ResolvedReceiver, error) {
	resolved, err := s.resolveReceiver(requested)
	if err != nil {
		return scheduling.Binding{}, scheduling.ResolvedReceiver{}, err
	}

	var binding scheduling.Binding
	switch resolved.Kind {
	case scheduling.ReceiverCarrier:
		binding, err = s.scheduling.AdmitCarrier(resolved.Name)
	case scheduling.ReceiverSquad:
		binding, err = s.scheduling.Admit(scheduling.IgnitionRequest{
			Squad:	resolved.Name, Model: requestModel, Actor: "dispatch",
		})
	default:
		err = fmt.Errorf("%w: 未知接收者类型 %s", scheduling.ErrInvalid, resolved.Kind)
	}
	if err != nil {
		s.log.Error("接收者准入失败", "requested", requested, "name", resolved.Name,
			"kind", string(resolved.Kind), "error_kind", "admit", "cause", err)
		return scheduling.Binding{}, resolved, err
	}

	id := scheduling.PhysicalIdentity{Machine: binding.Target, CLI: binding.Executor, HomeDir: binding.HomeDir}
	bound, err := scheduling.BindPhysical(id, overlay)
	if err != nil {
		s.log.Warn("物理覆盖被拒", "requested", requested, "carrier", binding.Carrier,
			"squad", binding.Squad, "error_kind", "physical_override", "cause", err)
		if relErr := s.scheduling.Release(binding.Squad, binding.Carrier); relErr != nil {
			s.log.Error("物理覆盖拒绝后释放占用失败", "requested", requested,
				"carrier", binding.Carrier, "squad", binding.Squad, "error_kind", "release", "cause", relErr)
		}
		return scheduling.Binding{}, resolved, err
	}
	binding.Target = bound.Machine
	binding.Executor = bound.CLI
	binding.HomeDir = bound.HomeDir
	binding.Model = scheduling.EffectiveModel(binding.Model, requestModel)
	s.log.Info("接收者已绑定", "requested", requested, "name", resolved.Name,
		"kind", string(resolved.Kind), "via_default", resolved.ViaDefault,
		"carrier", binding.Carrier, "squad", binding.Squad, "machine", binding.Target,
		"cli", binding.Executor, "home_dir", binding.HomeDir, "model", binding.Model,
		"error_kind", "success")
	return binding, resolved, nil
}

n_agentd_Server_probeMachines.signature:
// probeMachines 投影并探活全部机器。
//
// 返回：
//   - 机器列表（本机恒在第一条，其余按名字排序）；**永不返回错误**——
//     单台不可达是数据，整体恒 200
func (s *Server) probeMachines(ctx context.Context) proto.MachinesResp {
	ctx, cancel := context.WithTimeout(ctx, machineProbeBudget)
	defer cancel()

	out := make([]proto.Machine, 0, len(s.conf().Targets)+1)
	out = append(out, s.localMachine())

	names := s.pool.Names()

	remote := make([]proto.Machine, len(names))
	var wg sync.WaitGroup
	for i, name := range names {
		wg.Add(1)
		go func(i int, name string) {
			defer wg.Done()
			m := s.probeRemote(ctx, name)

			m.Upgrade = s.machineUpgradeState(name)
			remote[i] = m
		}(i, name)
	}
	wg.Wait()
	out = append(out, remote...)

	unreachable := 0
	for _, m := range out {
		if !m.Reachable {
			unreachable++
		}
	}
	s.log.Info("机器探活完成", "machines", len(out), "unreachable", unreachable)
	return proto.MachinesResp{Machines: out}
}

n_agentd_Server_probeRemote.signature:
// probeRemote 探活一台远程机器。
func (s *Server) probeRemote(ctx context.Context, name string) proto.Machine {
	t := s.conf().Targets[name]
	m := proto.Machine{Name: name, Addr: t.Addr, Relay: t.Node, Executors: []string{}}
	start := time.Now()

	c, err := s.pool.For(name)
	if err != nil {
		m.ProbeMs = time.Since(start).Milliseconds()
		s.log.Warn("机器探活：取客户端失败", "machine", name, "relay", t.IsRelay(), "cause", err)
		m.Error = err.Error()
		return m
	}

	st, err := c.Status(ctx)
	m.ProbeMs = time.Since(start).Milliseconds()
	if err != nil {
		s.log.Warn("机器探活失败", "machine", name, "addr", t.Addr, "relay", t.Node,
			"probe_ms", m.ProbeMs, "cause", err)
		m.Error = err.Error()
		return m
	}
	m.Reachable = true
	fillFromStatus(&m, st)
	s.log.Debug("机器探活成功", "machine", name, "probe_ms", m.ProbeMs,
		"active_tasks", m.ActiveTasks)
	return m
}

