n_agentd_Server_ptyFootprint.signature:
// ptyFootprint 体检当前全部终端会话的进程占用。
//
// 返回：每个活着的会话一行。会话已退出的不入表——它已经没有进程组可数了。
//
// 注意：数不出来（平台不支持进程枚举）时 Procs 留 nil 并记一条日志，不写 0。
func (s *Server) ptyFootprint() []proto.PtyFootprintRow {
	if s.pty == nil {
		return nil
	}
	sessions := s.pty.List()
	rows := make([]proto.PtyFootprintRow, 0, len(sessions))
	for _, sess := range sessions {
		if sess.ExitCode != nil {
			continue
		}
		row := proto.PtyFootprintRow{
			ID:	sess.ID, BasePath: sess.BasePath, PID: sess.PID, Foreground: sess.Foreground,
		}
		if n, err := prochost.CountGroup(sess.PID); err == nil {
			row.Procs = &n
		} else {
			s.log.Warn("终端会话足迹：进程组数不出来，该字段留空",
				"session", sess.ID, "pid", sess.PID, "cause", err)
		}
		rows = append(rows, row)
	}
	s.log.Info("终端会话足迹完成", "sessions", len(rows))
	return rows
}

n_agentd_Server_ptyRoot.signature:
// ptyRoot 返回 PTY 会话目录根路径。
//
// 返回：通常是 <DataDir>/ptys；构造时固定，避免配置热更新改变正在托管的会话根。
// 注意：测试与启动器可在构造后替换 ptyRootPath，但生产不会动态迁移会话目录。
func (s *Server) ptyRoot() string	{ return s.ptyRootPath }

n_agentd_Server_ptySessionsAll.signature:
// ptySessionsAll 现场扇出所有 target，给每行盖 machine 章。
//
// 现场扇出而非读镜像：终端会话是内存态、生死以秒计，缓存出来的列表会让用户
// 恢复出一批早就没了的 tab。单台失败只影响它自己那一行（machines 里 ok=false）。
func (s *Server) ptySessionsAll(r *http.Request, local []proto.PtySession) proto.PtySessionsResp {
	out := proto.PtySessionsResp{
		Sessions:	local,
		Machines:	[]proto.MachineStatus{{Name: "", Ok: true, FetchedAt: time.Now().UTC()}},
	}
	names := s.pool.Names()
	remote := make([]string, 0, len(names))
	for _, name := range names {
		if s.IsSelfTarget(name) {
			s.log.Info("终端会话扇出：跳过本机回环 target", "machine", name)
			continue
		}
		remote = append(remote, name)
	}

	ctx, cancel := context.WithTimeout(r.Context(), ptyFanoutBudget)
	defer cancel()

	type result struct {
		status	proto.MachineStatus
		resp	*proto.PtySessionsResp
	}
	results := make([]result, len(remote))
	var wg sync.WaitGroup
	for i, name := range remote {
		wg.Add(1)
		go func(i int, name string) {
			defer wg.Done()
			st := proto.MachineStatus{Name: name, FetchedAt: time.Now().UTC()}

			pc, err := s.clientForPtyFanout(name)
			if err != nil {
				s.log.Warn("终端会话扇出：取客户端失败", "machine", name, "cause", err)
				st.Error = err.Error()
				results[i] = result{status: st}
				return
			}
			resp, err := pc.PtySessions(ctx)
			if err != nil {
				s.log.Warn("终端会话扇出失败", "machine", name, "cause", err)
				st.Error = err.Error()
				results[i] = result{status: st}
				return
			}
			st.Ok = true
			results[i] = result{status: st, resp: resp}
		}(i, name)
	}
	wg.Wait()

	for _, res := range results {
		out.Machines = append(out.Machines, res.status)
		if res.resp == nil {
			continue
		}
		for _, sess := range res.resp.Sessions {

			sess.Machine = res.status.Name
			out.Sessions = append(out.Sessions, sess)
		}
	}
	s.log.Info("终端会话汇总完成", "machines", len(out.Machines), "sessions", len(out.Sessions))
	return out
}

n_agentd_Server_pumpPtyUplink.signature:
// pumpPtyUplink 读客户端上行：binary=按键，text=控制帧。
func (s *Server) pumpPtyUplink(ctx context.Context, conn *websocket.Conn, att *ptyhost.Attachment, id string) {
	for {
		typ, data, err := conn.Read(ctx)
		if err != nil {
			s.log.Debug("终端 WS 上行结束", "session", id, "cause", err)
			return
		}
		if typ == websocket.MessageBinary {
			if err := s.pty.Write(id, data); err != nil {

				s.log.Warn("终端 WS 上行写入失败", "session", id, "bytes", len(data), "cause", err)
				_ = writeCtrl(ctx, conn, proto.PtyControl{Type: proto.PtyCtrlError, Message: err.Error()})
				return
			}
			continue
		}
		var ctrl proto.PtyControl
		if err := json.Unmarshal(data, &ctrl); err != nil {
			s.log.Warn("终端 WS 控制帧无法解析", "session", id, "cause", err)
			continue
		}
		if ctrl.Type == proto.PtyCtrlDebug {
			s.log.Debug("[DEBUG-b270] 前端", "session", id, "msg", ctrl.Message)
			continue
		}
		if ctrl.Type != proto.PtyCtrlResize {
			s.log.Warn("终端 WS 收到未知控制帧类型", "session", id, "type", ctrl.Type)
			continue
		}
		if err := att.Resize(ctrl.Cols, ctrl.Rows); err != nil {
			s.log.Warn("终端 WS resize 失败", "session", id,
				"cols", ctrl.Cols, "rows", ctrl.Rows, "cause", err)
		}
	}
}

n_agentd_Server_pushWorkBranchOrigin.signature:
// pushWorkBranchOrigin 在持有工作分支的那台机把分支推到 origin。
// 走任务仓库的 git push，失败由调用方打 needs_human。
func (s *Server) pushWorkBranchOrigin(ctx context.Context, target, branch, taskID string) error {
	if strings.TrimSpace(branch) == "" {
		return fmt.Errorf("工作分支名为空，无法 push origin")
	}
	if strings.TrimSpace(taskID) == "" {
		return fmt.Errorf("没有任务 id，无法在执行机 push origin %s", branch)
	}
	canonical := s.CanonicalTarget(target)
	cl, err := s.clientForTarget(canonical)
	if err != nil {
		s.log.Error("取得 push origin 客户端失败", "target", target, "canonical_target", canonical,
			"branch", branch, "task", taskID, "cause", err)
		return fmt.Errorf("取得 %s 客户端去 push origin: %w", target, err)
	}
	return s.pushWorkBranchVia(ctx, cl, canonical, branch, taskID)
}

n_agentd_Server_pushWorkBranchVia.signature:
// pushWorkBranchVia 在持有工作分支的机器上执行一次 git push。具名入口，
// 依赖声明收窄到 runClient；canonical target 由调用方归一后传入。
func (s *Server) pushWorkBranchVia(ctx context.Context, cl runClient, target, branch, taskID string) error {
	cmd := "git push origin " + strconv.Quote(branch)
	s.log.Info("推送工作分支到 origin", "target", target, "branch", branch, "task", taskID)
	out, code, runErr := cl.Run(ctx, taskID, cmd)
	if runErr != nil {
		s.log.Error("推送工作分支请求失败", "target", target, "branch", branch,
			"task", taskID, "cause", runErr)
		return runErr
	}
	if code != 0 {
		s.log.Error("推送工作分支非零退出", "target", target, "branch", branch,
			"task", taskID, "exit", code)
		return fmt.Errorf("git push origin %s 退出码 %d：%s", branch, code, strings.TrimSpace(out))
	}
	s.log.Info("工作分支已推到 origin", "target", target, "branch", branch, "task", taskID)
	return nil
}

n_agentd_Server_reclaimPtySessions.signature:
// reclaimPtySessions 扫描并认领 agentd 之前留下的 PTY 会话。
//
// 返回：扫描根目录失败时报错；单个 broken 条目不会让启动失败。
// 注意：StateBroken 既不登记也不删除，活会话只登记静态元数据，不连接 socket。
func (s *Server) reclaimPtySessions() error {
	root := s.ptyRoot()
	entries, err := sessdir.Scan(root)
	if err != nil {
		return fmt.Errorf("扫描 PTY 会话目录 %s: %w", root, err)
	}
	var live, cleaned, broken int
	adopt := make([]sessdir.Entry, 0, len(entries))
	for _, entry := range entries {
		switch entry.State {
		case sessdir.StateLive:
			adopt = append(adopt, entry)
			live++
		case sessdir.StateDead:
			if err := sessdir.Remove(root, entry.ID); err != nil {
				s.log.Warn("清理已死的 PTY 会话目录失败", "session", entry.ID, "err", err)
				continue
			}
			cleaned++
		case sessdir.StateBroken:

			s.log.Error("PTY 会话目录异常，已跳过（进程可能仍在运行，需人工处理）",
				"session", entry.ID, "dir", sessdir.Dir(root, entry.ID), "err", entry.Err)
			broken++
		}
	}
	s.pty.Adopt(adopt)
	s.log.Info("PTY 会话认领完成", "live", live, "cleaned", cleaned, "broken", broken)
	return nil
}

n_agentd_Server_refreshSession.signature:
// refreshSession 按节流规则写回滑动续期与最后活跃时刻。
//
// 参数：
//   - sess: 刚刚通过鉴权的会话
//
// 注意：
//   - **必须节流**：文件树、事件流、终端这些高频路由若每个请求都写一次库，
//     会把 SQLite 写成瓶颈。续期只在剩余寿命不足一半时做（正常使用下每 15 天
//     最多一次），last_seen_at 只在与库中值相差超过 lastSeenThrottle 时写
//   - **写失败只 Warn、不影响放行**：会话是否有效在调用本方法前已经判完，
//     续期失败最坏结果是会话提前过期——属安全侧失败，不该把一次正常请求变成 500
func (s *Server) refreshSession(sess *store.Session) {
	now := time.Now()
	expires := sess.ExpiresAt
	if time.Until(expires) < sessionLifetime/2 {
		expires = now.Add(sessionLifetime)
	}
	lastSeen := sess.LastSeenAt
	if now.Sub(lastSeen) > lastSeenThrottle {
		lastSeen = now
	}
	if expires.Equal(sess.ExpiresAt) && lastSeen.Equal(sess.LastSeenAt) {
		return
	}
	if err := s.st.TouchSession(sess.ID, lastSeen, expires); err != nil {
		s.log.Warn("会话续期写入失败（不影响本次请求放行）", "session", sess.ID, "cause", err)
	}
}

n_agentd_Server_registerEventFrameHook.signature:
// registerEventFrameHook 在装配期把事件帧钩子挂到 store 上。
//
// 为什么是一个注册点而不是改 20 个 AppendEvent 调用点：调用点散落在
// manager.go / reconcile.go / watchdog.go，逐点补一行既啰嗦，又留下
// 「以后新增调用点忘了补」的失效模式。钩子自动覆盖现有与未来的全部调用点。
func (s *Server) registerEventFrameHook() {
	s.st.SetEventHook(eventFrameHook(s.conf().DataDir, s.log))
	s.log.Info("事件帧钩子已注册", "datadir", s.conf().DataDir)
}

