n_agentd_Server_remoteCoordWorkdir.signature:
func (s *Server) remoteCoordWorkdir(machine, card string) (string, error) {
	if s.lookupRemoteCoordWorkdir != nil {
		return s.lookupRemoteCoordWorkdir(machine, card)
	}
	row, err := s.ledger.GetCard(card)
	if err != nil {
		return "", fmt.Errorf("读卡 %s: %w", card, err)
	}
	c, err := s.clientForProjectList(machine)
	if err != nil {
		return "", fmt.Errorf("取机器 %s 客户端: %w", machine, err)
	}
	locs, err := c.ProjectList(context.Background())
	if err != nil {
		return "", fmt.Errorf("列机器 %s 项目: %w", machine, err)
	}
	loc, err := workspace.ResolveProject("", row.Project, locs)
	if err != nil {
		return "", err
	}
	return loc.Path, nil
}

n_agentd_Server_removeMachine.signature:
// removeMachine 从配置里删除一台开发机并落盘。
//
// 参数：
//   - name: 机器名（不能为空；空串是本机的保留名）
//
// 返回：
//   - 包装了 ErrMachineNotFound 的错误表示不存在（调用方应答 404）
func (s *Server) removeMachine(name string) error {
	if name == "" {
		return fmt.Errorf("%w: 名字为空", ErrMachineNotFound)
	}
	s.log.Info("删除开发机", "name", name)
	return s.swapConf(func(c *config.Config) error {
		if _, ok := c.Targets[name]; !ok {
			return fmt.Errorf("%w: %s", ErrMachineNotFound, name)
		}
		delete(c.Targets, name)
		return nil
	})
}

