n_agentd_Server_resolveCoordWorkdir.signature:
// resolveCoordWorkdir 尽力解析卡所属项目在本机的位置根作为会话工作目录
// （SessionSpec.Workdir=项目位置根）。解析不到不阻断拉起（置空由承载层缺省），
// 只留日志——plan §D5.2 的 best-effort 定案。
func (s *Server) resolveCoordWorkdir(cardID string) string {
	card, err := s.ledger.GetCard(cardID)
	if err != nil {
		return ""
	}
	entries, err := s.st.ListProjectLocations()
	if err != nil {
		s.log.Warn("协调者工作目录解析失败：列项目位置出错", "card", cardID, "cause", err)
		return ""
	}
	loc, err := workspace.ResolveProject("", card.Project, entries)
	if err != nil {
		s.log.Warn("协调者工作目录解析失败：项目未登记", "card", cardID, "project", card.Project, "cause", err)
		return ""
	}
	return loc.Path
}

n_agentd_Server_resolveCoordinatorSquad.signature:
// resolveCoordinatorSquad 找出唯一的协调者小队（SquadRows 过滤 role=coordinator）。
// 0 → errNoCoordinatorSquad；≥2 → errAmbiguousCoordinatorSquad（错误带全部候选名）。
// SquadRows 由 K3 交付（internal/scheduling/registry_read.go），开工前已确认并入。
func (s *Server) resolveCoordinatorSquad() (scheduling.Squad, error) {
	rows, err := s.scheduling.SquadRows()
	if err != nil {
		return scheduling.Squad{}, err
	}
	var names []string
	var single *scheduling.Squad
	for i := range rows {
		if rows[i].Squad.Role != scheduling.RoleCoordinator {
			continue
		}
		names = append(names, rows[i].Squad.Name)
		if single == nil {
			q := rows[i].Squad
			single = &q
		}
	}
	switch len(names) {
	case 0:
		return scheduling.Squad{}, errNoCoordinatorSquad
	case 1:
		return *single, nil
	default:
		return scheduling.Squad{}, fmt.Errorf("%w（候选：%s）", errAmbiguousCoordinatorSquad, strings.Join(names, "、"))
	}
}

n_agentd_Server_resolvePtyBase.signature:
// resolvePtyBase 把请求里的 base_kind/base_path/rel 归一化成实际 cwd。
//
// **这是参数校验，不是安全边界。** 控制台会话在能力上等价于主令牌
// （POST /api/tasks/{id}/run 就是 sh -c，见 spec §1），白名单挡不住任何有心人
// ——终端里一条 `cd ~` 就出去了。它存在的唯一理由是：防止前端传一个打错的
// 路径、让 shell 起在文件系统某个莫名其妙的角落。因此失败是 400（参数错），
// 不是 403（没权限）。
//
// rel 是相对工作树根的子目录：空串 = 根，否则在词汇层把 rel 限定在 root 之内
// 并确认它真的存在且是目录。这里**不用 os.OpenRoot** 做内核级 jail：与
// Task 1-3 的 CreateEntry 等不同，那些是文件写入的内核边界，这里是纯参数
// 校验（终端起在哪个目录本就由用户全权决定，一条 `cd ~` 就出去了），
// 词汇层校验只是为了不让打错的 rel 把 shell 起在角落。
func (s *Server) resolvePtyBase(r *http.Request, req proto.CreatePtySessionReq) (path, kind string, err error) {
	if req.BaseKind == "home" {
		home, herr := os.UserHomeDir()
		if herr != nil {
			return "", "", errors.New("服务端无法确定 $HOME: " + herr.Error())
		}
		return home, "home", nil
	}
	if req.BasePath == "" {
		return "", "", errors.New("缺少 base_path 参数")
	}
	root, ok := s.resolveWorkspace(r.Context(), req.BasePath)
	if !ok {
		return "", "", errors.New("base_path " + filepath.Clean(req.BasePath) +
			" 不是本机已探测到的工作树，请从工作树列表里选一个")
	}
	if req.Rel != "" {
		clean := filepath.Clean(req.Rel)
		if filepath.IsAbs(clean) || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
			return "", "", errors.New("rel " + req.Rel + " 必须是指向工作树内目录的相对路径")
		}
		dir := filepath.Join(root, clean)
		st, serr := os.Stat(dir)
		if serr != nil {
			return "", "", errors.New("rel " + req.Rel + " 不存在或不可访问: " + serr.Error())
		}
		if !st.IsDir() {
			return "", "", errors.New("rel " + req.Rel + " 不是目录，终端的 cwd 必须是目录")
		}
		return dir, "workspace", nil
	}
	return root, "workspace", nil
}

n_agentd_Server_resolveReceiver.signature:
// resolveReceiver 通过编制域统一解析显式或默认接收者。
// 显式名称不依赖默认记录；空名称的默认记录错误原样上浮。
func (s *Server) resolveReceiver(requested string) (scheduling.ResolvedReceiver, error) {
	if s.scheduling == nil {
		err := errors.New("编制域服务未装配（SetupAutomation 未执行）")
		s.log.Error("接收者解析失败", "requested", requested, "error_kind", "scheduling_unavailable", "cause", err)
		return scheduling.ResolvedReceiver{}, err
	}

	defaultName, defErr := s.scheduling.DefaultCarrier()
	if defErr != nil && strings.TrimSpace(requested) == "" {
		s.log.Warn("派发无有效默认载体", "requested", requested, "error_kind", "no_default", "cause", defErr)
		return scheduling.ResolvedReceiver{}, defErr
	}
	if defErr != nil {
		defaultName = ""
	}

	var lookupErr error
	lookup := func(name string) (bool, bool) {
		_, carrierErr := s.scheduling.Carrier(name)
		_, squadErr := s.scheduling.Squad(name)
		if carrierErr != nil && !errors.Is(carrierErr, scheduling.ErrNotFound) {
			lookupErr = carrierErr
		}
		if squadErr != nil && !errors.Is(squadErr, scheduling.ErrNotFound) && lookupErr == nil {
			lookupErr = squadErr
		}
		return carrierErr == nil, squadErr == nil
	}
	resolved, err := scheduling.ResolveLookup(requested, defaultName, lookup)
	if lookupErr != nil {
		s.log.Error("接收者登记查询失败", "requested", requested, "default", defaultName, "error_kind", "lookup", "cause", lookupErr)
		return scheduling.ResolvedReceiver{}, lookupErr
	}
	if err != nil {
		s.log.Warn("接收者解析失败", "requested", requested, "default", defaultName, "error_kind", "resolve", "cause", err)
		return scheduling.ResolvedReceiver{}, err
	}
	s.log.Info("接收者已解析", "requested", requested, "name", resolved.Name,
		"kind", string(resolved.Kind), "via_default", resolved.ViaDefault, "error_kind", "success")
	return resolved, nil
}

n_agentd_Server_resolveStepDiscipline.signature:
// resolveStepDiscipline 是环节派发的缝 1 收口（B229 契约 §2.2）：按与 ViaTemplate
// 完全相同的裁决顺序算出有效（角色名，目标机），绑账本 lookup 与能力位探活各一次，
// 经 discipline.ResolveDispatch 产出随派发下发的正文三元组。未点名模板同样过闸，
// 产物是纯平台层正文、版本 0（§3.1：拒发闸覆盖一切带正文派发）。
//
// 为什么探活失败不能按不支持处置：能力位缺席(nil)只表示探活成功后对端未上报，
// 网络/认证错误必须保留 cause 并停止派发；只有 nil/false 能力位才进入升级拒发。
func (s *Server) resolveStepDiscipline(node ledger.NodeDef, reqTarget string) (discipline.ResolvedDiscipline, string, error) {
	name, target, err := ledgerstep.PreflightDiscipline(s.ledger, node.Template, node.Override.Discipline, reqTarget)
	if err != nil {
		return discipline.ResolvedDiscipline{}, "", err
	}
	target = s.CanonicalTarget(target)
	if isLocalMachine(target) {

		target = ""
	}
	cl, err := s.clientForTarget(target)
	if err != nil {
		s.log.Error("环节纪律探活取得客户端失败", "node", node.Name, "target", target,
			"canonical_target", target, "cause", err)
		return discipline.ResolvedDiscipline{}, target, fmt.Errorf(
			"目标机探活失败：请确认目标机可达、agentd 正在运行且 token 一致：%w", err)
	}
	status, err := probeStatus(context.Background(), cl)
	if err != nil {
		s.log.Error("环节纪律探活失败", "node", node.Name, "target", target,
			"canonical_target", target, "cause", err)
		return discipline.ResolvedDiscipline{}, target, fmt.Errorf(
			"目标机探活失败：请确认目标机可达、agentd 正在运行且 token 一致：%w", err)
	}
	s.log.Info("环节纪律探活完成", "node", node.Name, "target", target,
		"canonical_target", target, "cap_absent", status.DisciplinesSupported == nil)
	cap := status.DisciplinesSupported
	lookup := func(n string) (int, string, error) {
		d, gerr := s.ledger.GetDiscipline(n, 0)
		if gerr != nil {
			return 0, "", gerr
		}
		return d.Version, d.Body, nil
	}
	res, err := discipline.ResolveDispatch(lookup, discipline.DisciplineRef{Name: name},
		s.conf().PlatformInvariantsEnabled(), cap)
	if err != nil {
		s.log.Warn("环节派发被拒发闸拦下", "node", node.Name, "target", target,
			"discipline", name, "cap_absent", cap == nil, "cause", err)
		return discipline.ResolvedDiscipline{}, target, fmt.Errorf("环节 %s 派发前纪律解析失败: %w", node.Name, err)
	}
	s.log.Info("环节派发纪律正文已就绪", "node", node.Name, "target", target,
		"discipline", name, "version", res.Version, "bytes", len(res.Text))
	return res, target, nil
}

n_agentd_Server_resolveWorkspace.signature:
// resolveWorkspace 判定 path 是否是本机**已探测到**的某个工作树。
//
// 判定口径与 GET /api/projects/tree 完全一致：先比登记表里的位置路径（一次
// 数据库读，绝大多数请求命中主目录时到此为止），未命中再对每个 location 跑一次
// git worktree list 现场探测。两段式是为了让最常见的请求不付探测成本。
//
// 为什么不缓存探测结果：worktree 会在 agentd 背后被 git worktree add/remove
// 改动，缓存必然产生「已经删掉的工作树还能浏览」的失真窗口——而这条闸门是
// **参数校验**，失真窗口会让用户浏览到一个已经不存在的工作树，报错莫名其妙。
// 真变慢了再谈带短 TTL 的缓存。
//
// 参数：
//   - ctx: 上下文，透传给 probeWorkspaces（其内部另有 5s 兜底超时）
//   - path: 调用方上送的工作树绝对路径
//
// 返回：
//   - 归一化（filepath.Clean）后的路径，仅在 ok 为真时有意义
//   - ok: 命中白名单为真
func (s *Server) resolveWorkspace(ctx context.Context, path string) (string, bool) {
	want := filepath.Clean(path)

	if root := s.scratchRoot(); root != "" && want == root {
		return root, true
	}
	locs, err := s.st.ListProjectLocations()
	if err != nil {

		s.log.Error("工作树白名单：查询位置表失败，按拒绝处理", "cause", err)
		return "", false
	}
	for _, l := range locs {
		if l.ProjectID == "" {
			continue
		}
		if filepath.Clean(l.Path) == want {
			return want, true
		}
	}
	managedRoot := filepath.Join(s.conf().DataDir, "worktrees")
	for _, l := range locs {
		if l.ProjectID == "" {
			continue
		}
		ws, probeErr := workspace.ProbeWorkspaces(ctx, l.Path, managedRoot)
		if probeErr != "" {
			continue
		}
		for _, w := range ws {
			if filepath.Clean(w.Path) == want {
				return want, true
			}
		}
	}
	return "", false
}

n_agentd_Server_resumeIfIdle.signature:
// resumeIfIdle 当任务处于 waiting_answer 且已无未答工单时，把状态回迁 running。
//
// 为什么用有界重试：两个工单被并发回答时，先回答的请求可能读到「仍有未答工单」而跳过，
// 后回答的请求负责回迁；也可能两个请求都读到「已无工单」，此时先执行者成功，
// 后执行者因 CAS（WHERE state = 旧值）收到 ErrBadTransit。重试让意图在最新快照上重新
// 评估，而不是把并发迁移当作错误直接吞掉。
func (s *Server) resumeIfIdle(taskID string) {
	for attempt := 0; attempt < 3; attempt++ {
		task, err := s.st.GetTask(taskID)
		if err != nil {
			s.log.Error("reply 后读取任务失败", "task", taskID, "cause", err)
			return
		}
		if task.State != proto.TaskStateWaitingAnswer {
			return
		}
		pending, err := s.st.PendingTickets(taskID)
		if err != nil {
			s.log.Error("reply 后查询待办工单失败", "task", taskID, "cause", err)
			return
		}
		if len(pending) > 0 {
			return
		}
		if err := s.st.UpdateTaskState(taskID, proto.TaskStateRunning); err == nil {
			return
		} else if !errors.Is(err, store.ErrBadTransit) {
			s.log.Error("reply 后恢复任务运行失败", "task", taskID, "cause", err)
			return
		}

	}
	s.log.Warn("reply 后恢复任务运行重试耗尽", "task", taskID)
}

n_agentd_Server_revoke.signature:
// revoke 执行吊销并记录发起方，供 handleRevokeSession 与 handleLogout 共用。
func (s *Server) revoke(r *http.Request, id string) error {
	by := "主令牌"
	if cur := identityFrom(r.Context()); cur.session != "" {
		by = "会话 " + cur.session
	}
	if err := s.st.RevokeSession(id, time.Now()); err != nil {
		if errors.Is(err, store.ErrNotFound) {
			s.log.Warn("吊销会话未命中（不存在或已吊销）", "session", id, "by", by)
			return err
		}
		s.log.Error("吊销会话失败", "session", id, "by", by, "cause", err)
		return err
	}
	s.log.Info("吊销会话", "session", id, "by", by)
	return nil
}

