n_agentd_Server_runMachineUpgradeBackgro.signature:
// runMachineUpgradeBackground 使用独立 context：请求返回后 r.Context 已不可用。
func (s *Server) runMachineUpgradeBackground(name string, m upgrade.Machine, target config.Target,
	rel release.Release, force bool) {
	ctx, cancel := context.WithTimeout(context.Background(), machineUpgradeTimeout)
	defer cancel()
	progress := func(message string) {
		s.log.Info("执行机升级进度", "name", name, "stage", message)
	}
	runner := s.machineUpgradeRunner
	if runner == nil {
		runner = s.executeMachineUpgrade
	}
	result := runner(ctx, m, target, rel, force, progress)

	s.finishMachineUpgrade(name, result)
	if result.Status == upgrade.StatusOK {
		s.log.Info("后台执行机升级成功", "name", name, "from", result.From, "to", result.To)
		return
	}
	s.log.Warn("后台执行机升级结束", "name", name, "status", result.Status.String(),
		"verdict", result.Verdict.String(), "reason", result.Reason)
}

n_agentd_Server_runPull.signature:
// runPull 在后台执行一次自拉换版：下载 → 安装（校验+解包+自检）→ 换版 → 重启。
//
// 参数：
//   - tag: 目标版本
//   - sum: 协调者下发的期望 sha256。**不是本机自己取的**——校验和与资产走
//     两条不同的信任路径，本机代理/镜像被投毒时才抓得住（spec §5.5）
//
// 注意：
//   - 由 handlePullUpdate 在抢到 pull 锁之后起。任何失败路径都必须调
//     s.pull.fail 释放锁，否则这台 agentd 从此再也不能自拉
//   - 成功路径不释放锁：换版成功即触发重启，进程整个换掉
func (s *Server) runPull(tag, sum string) {
	ctx := s.pullBaseCtx
	if ctx == nil {
		ctx = context.Background()
	}
	goos, goarch := s.upd.Platform()
	s.log.Info("自拉换版开始", "tag", tag, "platform", goos+"/"+goarch, "sha256", sum)

	s.pull.stage(proto.PullStageDownloading)
	tgz, err := s.upd.FetchByTag(ctx, tag, goos, goarch, sum)
	if err != nil {
		s.log.Error("自拉换版失败：下载或校验不过", "tag", tag,
			"platform", goos+"/"+goarch, "cause", err)
		s.pull.fail(err)
		return
	}
	s.log.Info("自拉换版：资产已就绪", "tag", tag, "bytes", len(tgz))

	target, err := s.upd.Executable()
	if err != nil {
		s.log.Error("自拉换版失败：取当前二进制路径", "tag", tag, "cause", err)
		s.pull.fail(err)
		return
	}

	s.pull.stage(proto.PullStageInstalling)

	newPath, err := s.upd.Install(tgz, sum, tag, filepath.Dir(target))
	if err != nil {
		s.log.Error("自拉换版失败：校验或自检未通过", "tag", tag, "target", target, "cause", err)
		s.pull.fail(err)
		return
	}
	prev, err := s.upd.Activate(newPath, target)
	if err != nil {
		s.log.Error("自拉换版失败：替换二进制出错", "tag", tag, "target", target, "cause", err)
		s.pull.fail(err)
		return
	}

	s.log.Info("自拉换版完成，准备重启", "tag", tag, "target", target, "prev", prev)
	s.triggerRestart("自拉换版到 " + tag)
}

n_agentd_Server_runStep.signature:
// runStep 是 runStepFn 的生产实现：跑环节并把结果记进日志。
//
// 为什么错误只进日志不往上抛：调用它的 goroutine 没有上游。环节的成败
// 由 ledgerstep 落进卡的事件流，那是界面看得见的地方；日志是排查时的第二现场。
func (s *Server) runStep(ctx context.Context, runner *ledgerstep.StepRunner, cardID, node string) {
	outcome, err := runner.Run(ctx, cardID, node)
	if err != nil {
		s.log.Error("节点失败", "card", cardID, "node", node, "cause", err)
		return
	}
	s.log.Info("节点结束", "card", cardID, "node", node,
		"action", string(outcome.Action), "reason", outcome.Reason)
}

n_agentd_Server_schedDeleteErr.signature:
// schedDeleteErr 把编制域删除错误翻译成状态码：400 校验未过（仍在小队或名字非法） /
// 404 载体不存在 / 409 CAS 冲突 / 500 内部故障。
func (s *Server) schedDeleteErr(w http.ResponseWriter, name string, err error) {
	switch {
	case errors.Is(err, scheduling.ErrInvalid):
		s.log.Warn("编制域删除被拒", "name", name, "cause", err)
		writeErr(w, http.StatusBadRequest, err)
	case errors.Is(err, scheduling.ErrNotFound):
		s.log.Warn("编制域删除未找到", "name", name, "cause", err)
		writeErr(w, http.StatusNotFound, err)
	case errors.Is(err, schedclient.ErrCASConflict):
		s.log.Warn("编制域删除版本冲突", "name", name, "cause", err)
		writeErr(w, http.StatusConflict, err)
	default:
		s.log.Error("编制域删除失败", "name", name, "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
	}
}

n_agentd_Server_schedPutErr.signature:
// schedPutErr 把编制域登记错误翻译成状态码：400 校验未过 / 409 CAS 冲突 /
// 500 registry 故障。分级日志让「用户填错」与「存储坏了」在日志里第一眼可分。
//
// ErrCASConflict 判定用 schedclient 哨兵正主：它经组装点适配器 translateRegistryErr
// 翻译后随域内错误上浮（K2 已落地，本卡不改写）；ErrInvalid 由 PutCarrier/PutSquad
// 校验行的 %w 包装产生（B156.3.3 修复轮 Major-2：400 而非 409，与 doc 注释一致）。
func (s *Server) schedPutErr(w http.ResponseWriter, kind, name string, err error) {
	switch {
	case errors.Is(err, scheduling.ErrInvalid):
		s.log.Warn("编制域登记被拒", "kind", kind, "name", name, "cause", err)
		writeErr(w, http.StatusBadRequest, err)
	case errors.Is(err, schedclient.ErrCASConflict):
		s.log.Warn("编制域登记版本冲突", "kind", kind, "name", name, "cause", err)
		writeErr(w, http.StatusConflict, err)
	default:
		s.log.Error("编制域登记失败", "kind", kind, "name", name, "cause", err)
		writeErr(w, http.StatusInternalServerError, err)
	}
}

n_agentd_Server_scratchRoot.signature:
// scratchRoot 返回草稿区的绝对路径；不可用时返回空串。
//
// 草稿区是控制台右下角浮窗「临时文件」的落点：一个不属于任何 git 工作树、
// 也不在 project_locations 表里的受管目录（spec §5.1）。
//
// 返回空串的两种情形都不是故障：DataDir 没配出来，或目录建不出来（磁盘满、
// 权限）。此时闸门那一支恒不命中、StatusResp 里这个字段缺席、前端入口不渲染
// ——整条链路对「草稿区不可用」是收敛的，不会有任何一处拿着空路径去发请求。
//
// 每次调用都 MkdirAll 而不是启动时建一次：目录可能在 agentd 运行期间被人删掉，
// 而 MkdirAll 对已存在的目录是零成本的 stat。
func (s *Server) scratchRoot() string {
	dataDir := s.conf().DataDir
	if dataDir == "" {
		return ""
	}
	root := filepath.Join(dataDir, scratchDirName)
	if err := os.MkdirAll(root, 0o700); err != nil {

		s.log.Warn("草稿区目录建立失败，临时文件功能不可用", "path", root, "cause", err)
		return ""
	}
	return filepath.Clean(root)
}

n_agentd_Server_sessionEnv.signature:
// sessionEnv 组装一个会话的完整环境。
//
// 基础三件：从 agentd 自身环境继承（PATH 已由 B71 的 pathenv.Apply 在任何 fork
// 之前补全过，见 spec §4.1），再钉死 TERM / COLORTERM。
//
// 之后叠加 env_forward 的解析结果：配置为 nil 时用内置默认清单，非 nil 时完全
// 以配置为准（含显式空列表 = 一个都不转发）。**默认值只在这里取，绝不回填进
// cfg**——回填会让下一次 Save 把它落进 config.yaml 顶死旧 agentd（spec §4.2）。
func (s *Server) sessionEnv() []string {
	base := append([]string{}, os.Environ()...)
	base = append(base, "TERM=xterm-256color", "COLORTERM=truecolor")
	names := s.conf().EnvForward
	if names == nil {
		names = ptyhost.DefaultEnvForward()
	}
	return ptyhost.ResolveEnvForward(names, base, s.log)
}

n_agentd_Server_sessionFromRequest.signature:
// sessionFromRequest 用 cookie 查会话并判定其有效性。
//
// 参数：
//   - r: 当前请求
//
// 返回：
//   - 有效会话；无效时为 nil
//   - reason: 失败原因，用于鉴权失败日志。spec §11 要求区分「无凭据 / Bearer
//     不匹配 / 会话不存在 / 会话过期 / 会话已吊销」，因此不能只回一个 bool
func (s *Server) sessionFromRequest(r *http.Request) (*store.Session, string) {
	c, err := r.Cookie(sessionCookieName)
	if err != nil || c.Value == "" {

		if _, ok := bearerToken(r); ok {
			return nil, "Bearer 不匹配"
		}
		return nil, "无凭据"
	}
	sess, err := s.st.SessionByTokenHash(store.HashCredential(c.Value))
	switch {
	case errors.Is(err, store.ErrNotFound):
		return nil, "会话不存在"
	case err != nil:
		s.log.Error("查询会话失败", "cause", err)
		return nil, "会话查询失败"
	case sess.RevokedAt != nil:
		return nil, "会话已吊销"
	case !time.Now().Before(sess.ExpiresAt):
		return nil, "会话过期"
	}
	return sess, ""
}

