n_agentd_Server_shutdownPtySessions.signature:
// shutdownPtySessions 显式停止全部已登记的 PTY 会话。
//
// 参数：ctx 是 agentd 关停上下文；函数会在最多 ptyShutdownWait 后返回。
// 返回：无；单个会话关闭失败与整体超时都只记日志，不能阻塞 agentd 退出。
// 注意：每个 Host.Close 会等待自身的 ptyhost/PTY 收摊；这里仍保留 2 秒总预算，
// 到点只记录 Warn 并继续退出。这是唯一的批量 kill 路径；agentd 崩溃与升级不调用它。
func (s *Server) shutdownPtySessions(ctx context.Context) {
	ctx, cancel := context.WithTimeout(ctx, ptyShutdownWait)
	defer cancel()
	list := s.pty.List()
	if len(list) == 0 {
		s.log.Info("PTY 会话收口完成", "count", 0)
		return
	}

	var wg sync.WaitGroup
	for _, sess := range list {
		id := sess.ID
		pid := sess.PID
		wg.Add(1)
		go func() {
			defer wg.Done()
			if err := s.pty.Close(id); err != nil {
				s.log.Warn("停止 PTY 会话失败", "session", id, "pid", pid, "cause", err)
				return
			}
			s.log.Info("停止 PTY 会话完成", "session", id, "pid", pid)
		}()
	}
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	select {
	case <-done:
		s.log.Info("PTY 会话收口完成", "count", len(list))
	case <-ctx.Done():
		s.log.Warn("PTY 会话收口超时，继续退出", "count", len(list), "wait", ptyShutdownWait, "cause", ctx.Err())
	}
}

n_agentd_Server_startCardStep.signature:
// startCardStep 装配并异步启动一个卡节点。
//
// 参数：cardID 是卡号；req 是已完成 actor 归一和字段校验的规范请求。
// 返回：同卡已有在飞节点时返回 errStepInFlight；其它前置校验错误原样返回；成功
// 只表示 goroutine 已启动，不表示节点完成。后台结束时必须释放既有卡槽位。
//
// 为什么必须异步：审阅环节会阻塞到被派出去的 task 跑到回合终态——几分钟到
// 几十分钟，executor 挂在 waiting_answer 时更久。HTTP 请求扛不住这个时长，
// 界面靠已有的卡事件流看进展。
//
// 注意：返回 nil 不代表环节成功，只代表它启动了。成败落在卡的事件流上。
func (s *Server) startCardStep(cardID string, req proto.CardStepReq) error {
	if !s.claimCardStep(cardID) {
		return fmt.Errorf("%w: %s 的 %s 节点正在运行", errStepInFlight, cardID, req.Step)
	}

	node, err := ledgerstep.ResolveNode(s.ledger, cardID, req.Step)
	if err != nil {
		s.releaseCardStep(cardID)
		return err
	}
	if node.Override.Squad != "" {
		if named := strings.TrimSpace(req.Target); named != "" {
			s.releaseCardStep(cardID)
			s.log.Warn("小队节点拒绝点名机器", "card", cardID, "node", node.Name,
				"squad", node.Override.Squad, "target", named)
			return fmt.Errorf("节点 %s 已绑小队 %q，禁止 --target %s；由 Admit 选机器",
				node.Name, node.Override.Squad, named)
		}
		if named := strings.TrimSpace(req.Executor); named != "" {
			s.releaseCardStep(cardID)
			s.log.Warn("小队节点拒绝点名执行器", "card", cardID, "node", node.Name,
				"squad", node.Override.Squad, "executor", named)
			return fmt.Errorf("节点 %s 已绑小队 %q，禁止 --executor %s；由 Admit 选载体 CLI",
				node.Name, node.Override.Squad, named)
		}
	}

	binding := scheduling.Binding{}
	if node.Override.Squad != "" {
		outcome := squadDispatchAdmitted
		binding, outcome, err = s.admitSquadStep(cardID, req, node)
		if err != nil {
			s.releaseCardStep(cardID)
			return err
		}
		if outcome == squadDispatchQueued {
			s.releaseCardStep(cardID)
			return nil
		}
	}
	target := req.Target
	if binding.Target != "" {
		target = binding.Target
	}
	var dispatchHomeDir *string
	if binding.Carrier != "" {

		homeDir := binding.HomeDir
		dispatchHomeDir = &homeDir
	}
	resolved, target, err := s.resolveStepDiscipline(node, target)
	if err != nil {
		s.releaseCardStep(cardID)
		s.log.Warn("卡节点冻结身份后装配失败，未释放执行占用", "card", cardID,
			"node", req.Step, "squad", binding.Squad, "carrier", binding.Carrier,
			"error_kind", "assembly", "cause", err)
		return err
	}
	host, _ := os.Hostname()
	runner := &ledgerstep.StepRunner{
		St:	s.ledger, Session: req.Actor,
		RunHolder:	fmt.Sprintf("run:%s#%d#%d", host, os.Getpid(), time.Now().UnixNano()),
		Dispatcher: &ledgerstep.Dispatcher{
			St:	s.ledger, Transport: s.stepTransport, Actor: req.Actor,

			Compensate: func(ctx context.Context, target, taskID string) error {
				cl, err := s.clientForTarget(target)
				if err != nil {
					s.log.Error("agentd 派发失败补偿创建 client 失败", "card", cardID, "target", target, "task", taskID, "cause", err)
					return err
				}
				return s.compensateStep(ctx, cl, cardID, target, taskID)
			},
			HomeDir:		dispatchHomeDir,
			Carrier:		binding.Carrier,
			Squad:			binding.Squad,
			DisciplineText:		resolved.Text,
			DisciplineVersion:	resolved.Version,
			NormalizeTarget:	s.CanonicalTarget,
		},
		Clients: func(target string) (ledgerstep.StepClient, error) {
			return s.clientForTarget(target)
		},
		Target:		target,
		Executor:	req.Executor,
		Model:		req.Model,
		Extra:		req.Extra,
		PublishWorkBranch: func(ctx context.Context, target, branch, taskID string) error {
			return s.pushWorkBranchOrigin(ctx, target, branch, taskID)
		},
	}
	s.log.Info("卡节点装配完成", "card", cardID, "node", req.Step,
		"actor", req.Actor, "target", req.Target, "canonical_target", target, "executor", req.Executor,
		"model", req.Model, "run_holder", runner.RunHolder,
		"has_extra", strings.TrimSpace(req.Extra) != "")
	if binding.Squad != "" {

		runner.Target = binding.Target
		runner.Executor = binding.Executor
		runner.Model = binding.Model
	}
	go func() {
		defer s.releaseCardStep(cardID)
		s.log.Info("卡节点回合开始", "card", cardID, "node", req.Step,
			"squad", binding.Squad, "carrier", binding.Carrier)
		s.runStepFn(context.Background(), runner, cardID, req.Step)
		s.log.Info("卡节点回合返回", "card", cardID, "node", req.Step,
			"squad", binding.Squad, "carrier", binding.Carrier,
			"occupancy_owner", "task_terminal", "card_slot_owner", "card_step")
	}()
	return nil
}

n_agentd_Server_startRoomAttachRefresh.signature:
// startRoomAttachRefresh asynchronously resolves remote task workdirs. A single
// refresh is shared by concurrent list requests and throttled between passes.
func (s *Server) startRoomAttachRefresh(links []ledger.TaskLink) {
	remoteLinks := make(map[string]ledger.TaskLink)
	for _, link := range links {
		if link.Target == "" {
			continue
		}
		remoteLinks[roomAttachCacheKey(link)] = link
	}
	if len(remoteLinks) == 0 {
		return
	}

	s.roomAttachMu.Lock()
	now := time.Now()
	if s.roomAttachRefreshing || (!s.roomAttachLastRefresh.IsZero() &&
		now.Sub(s.roomAttachLastRefresh) < roomAttachRefreshInterval) {
		s.roomAttachMu.Unlock()
		return
	}
	s.roomAttachRefreshing = true
	s.roomAttachLastRefresh = now
	s.roomAttachMu.Unlock()

	go func() {
		defer func() {
			s.roomAttachMu.Lock()
			s.roomAttachRefreshing = false
			s.roomAttachMu.Unlock()
		}()

		ctx, cancel := context.WithTimeout(context.Background(), roomAttachBackgroundTimeout)
		defer cancel()
		workers := make(chan struct{}, roomAttachRefreshWorkers)
		var wg sync.WaitGroup
		for _, link := range remoteLinks {
			link := link
			wg.Add(1)
			go func() {
				defer wg.Done()
				select {
				case workers <- struct{}{}:
				case <-ctx.Done():
					s.log.Warn("房间 attach 后台刷新取消", "target", link.Target,
						"task", link.TaskID, "cause", ctx.Err())
					return
				}
				defer func() { <-workers }()
				attach, err := s.lookupRoomAttach(ctx, link, nil)
				if err != nil {
					s.invalidateRoomAttach(link)
					s.log.Warn("房间 attach 后台刷新失败", "target", link.Target,
						"task", link.TaskID, "cause", err)
					return
				}
				s.storeRoomAttach(link, attach)
				s.log.Info("房间 attach 后台刷新成功", "target", link.Target,
					"task", link.TaskID, "workdir", attach.WorkDir)
			}()
		}
		wg.Wait()
		s.log.Info("房间 attach 后台刷新完成", "links", len(remoteLinks),
			"timed_out", ctx.Err() != nil)
	}()
}

n_agentd_Server_stepTransport.signature:
func (s *Server) stepTransport(ctx context.Context, opts ledgerstep.DispatchOpts) (string, string, error) {
	canonical := s.CanonicalTarget(opts.Target)
	if isLocalMachine(canonical) {
		canonical = ""
	}
	dispatchTarget := canonical
	if opts.Carrier != "" {

		dispatchTarget = opts.Target
	}

	s.log.Info("agentd 节点派发请求", "target", opts.Target, "canonical_target", canonical,
		"executor", opts.Executor,
		"model", opts.Model, "prompt_bytes", len(opts.Prompt),
		"carrier", opts.Carrier, "squad", opts.Squad, "home_dir_set", opts.HomeDir != nil,
		"discipline", opts.Discipline, "discipline_version", opts.DisciplineVersion,
		"discipline_bytes", len(opts.DisciplineText))
	cl, err := s.clientForTarget(canonical)
	if err != nil {
		s.log.Warn("取得节点派发客户端失败", "target", opts.Target,
			"canonical_target", canonical, "cause", err)
		return "", "", err
	}
	task, err := dispatchStep(ctx, cl, opts, dispatchTarget)
	if err != nil {
		s.log.Warn("agentd 节点派发失败", "target", opts.Target, "canonical_target", canonical,
			"executor", opts.Executor, "carrier", opts.Carrier, "squad", opts.Squad,
			"model", opts.Model, "cause", err)
		return "", "", err
	}
	s.log.Info("agentd 节点派发已受理", "target", opts.Target, "canonical_target", canonical, "task", task.ID,
		"carrier", task.Carrier, "squad", task.Squad, "base_commit", task.BaseCommit)
	return task.ID, task.BaseCommit, nil
}

n_agentd_Server_storeRoomAttach.signature:
func (s *Server) storeRoomAttach(link ledger.TaskLink, attach *proto.RoomAttach) {
	copy := *attach
	s.roomAttachMu.Lock()
	if s.roomAttachCache == nil {
		s.roomAttachCache = make(map[string]roomAttachCacheEntry)
	}
	s.roomAttachCache[roomAttachCacheKey(link)] = roomAttachCacheEntry{
		attach:	&copy, expiresAt: time.Now().Add(roomAttachCacheTTL),
	}
	s.roomAttachMu.Unlock()
}

n_agentd_Server_swapConf.signature:
// swapConf 以写时复制的方式修改配置并落盘。
//
// 参数：
//   - mutate: 在一份可安全修改的副本上施加改动；返回非 nil 则整体中止，
//     既不换快照也不落盘
//
// 返回：
//   - mutate 的错误、或落盘错误；成功时 nil
//
// 注意：
//   - 落盘成功才换快照；落盘失败时内存未曾改变——绝无「内存有、磁盘没有」的窗口
//   - 深拷贝 Targets 与 Discipline 两层——它们在 agentd 运行期可被写接口修改。
//     **新增运行期可变字段时必须在此补一层深拷**：漏了不会有测试变红，但读者
//     会看到改到一半的配置，与 conf() 承诺的「快照自洽」直接冲突
func (s *Server) swapConf(mutate func(*config.Config) error) error {
	s.cfgMu.Lock()
	defer s.cfgMu.Unlock()

	old := s.conf()
	next := *old
	next.Targets = make(map[string]config.Target, len(old.Targets)+1)
	for k, v := range old.Targets {
		next.Targets[k] = v
	}
	next.Discipline = make(map[string]string, len(old.Discipline)+1)
	for k, v := range old.Discipline {
		next.Discipline[k] = v
	}

	next.Env = make(map[string]string, len(old.Env)+1)
	for k, v := range old.Env {
		next.Env[k] = v
	}
	if err := mutate(&next); err != nil {
		return err
	}
	if s.cfgPath == "" {
		s.log.Error("未注入配置文件路径，拒绝写配置")
		return errors.New("agentd 未注入配置文件路径，无法写配置")
	}
	if err := config.Save(s.cfgPath, &next); err != nil {
		s.log.Error("配置落盘失败，内存快照未变更", "path", s.cfgPath, "cause", err)
		return fmt.Errorf("保存配置 %s: %w", s.cfgPath, err)
	}
	s.cfg.Store(&next)
	s.log.Info("配置已更新并落盘", "path", s.cfgPath,
		"targets", len(next.Targets), "discipline", len(next.Discipline), "env", len(next.Env))
	return nil
}

n_agentd_Server_taskOrErr.signature:
// taskOrErr 读取路径中的任务并做门禁：任务不存在写 404、缺工作区路径写 400，
// 两种情况都返回 ok=false（调用方直接 return 即可）。
//
// 为什么独立于 taskRepoOrErr：diff / branches 两个端点除了工作区路径还要读
// 任务的 BaseCommit（B65），而另外三个调用点只关心路径。拆开后既不动它们的
// 签名，也不必让它们承担一个用不到的返回值。
//
// 返回的是 task.Workdir() 而非 task.RepoPath（为什么 diff/fetch/run 必须在
// Workdir 而非主仓库：worktree 任务的 executor cwd 与分支 HEAD 都在 Workdir，
// 主仓库的 HEAD 停在派发前的位置——diff 相对基准、fetch 看工作区文件、run 跑
// 测试都必须落在 executor 真正干活的目录，否则审阅的是错误的代码状态）。
//
// 供 diff/fetch/run 三条审阅路由共用——它们只关心任务指向的仓库，不依赖状态机。
func (s *Server) taskOrErr(w http.ResponseWriter, taskID string) (*proto.Task, bool) {
	task, err := s.st.GetTask(taskID)
	if err != nil {
		if errors.Is(err, store.ErrNotFound) {
			s.log.Warn("任务不存在", "task", taskID)
			writeJSON(w, http.StatusNotFound, map[string]string{"error": "任务不存在"})
		} else {
			s.log.Error("读取任务失败", "task", taskID, "cause", err)
			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
		}
		return nil, false
	}
	if task.Workdir() == "" {
		s.log.Warn("任务缺少工作区路径", "task", taskID)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "任务没有工作区路径"})
		return nil, false
	}
	return task, true
}

n_agentd_Server_taskRepoOrErr.signature:
// taskRepoOrErr 读取路径中的任务并返回其工作区目录；任务不存在（404）或没有
// 工作区路径（400）时已写好响应并返回 ok=false。
func (s *Server) taskRepoOrErr(w http.ResponseWriter, taskID string) (repo string, ok bool) {
	task, ok := s.taskOrErr(w, taskID)
	if !ok {
		return "", false
	}
	return task.Workdir(), true
}

n_agentd_Server_tasksAll.signature:
// tasksAll 汇总本机与全部镜像任务为 §5.3 信封。
//
// 返回值恒有效：本机列表读不出来时照常返回信封（镜像部分仍可用）；
// 机器应答情况逐台进 Machines，不因单台缺失让整个响应失败。
func (s *Server) tasksAll(ctx context.Context) proto.TasksResp {
	tasks, err := s.st.ListTasks()
	if err != nil {
		s.log.Error("任务汇总：查询本机任务失败", "cause", err)
		tasks = []proto.Task{}
	}
	idx := s.projectIndex()
	views := make([]proto.TaskView, 0, len(tasks))
	for _, t := range tasks {
		t.ProjectID = idx.ProjectIDOf(t.RepoPath)
		views = append(views, proto.TaskView{Task: t, Watchers: s.hub.Watchers(t.ID)})
	}

	mirrors, err := s.st.ListMirrorTasks()
	if err != nil {
		s.log.Error("任务汇总：查询镜像快照失败", "cause", err)
		mirrors = []store.MirrorTask{}
	}

	targets := s.conf().Targets
	skipped := 0

	fetched := map[string]time.Time{}
	for _, mt := range mirrors {
		if _, ok := targets[mt.Target]; !ok {
			skipped++
			continue
		}
		t := mt.Task
		t.Machine = mt.Target
		views = append(views, proto.TaskView{Task: t, Watchers: s.hub.Watchers(t.ID)})
		if prev, ok := fetched[mt.Target]; !ok || mt.FetchedAt.After(prev) {
			fetched[mt.Target] = mt.FetchedAt
		}
	}
	if skipped > 0 {
		s.log.Debug("任务汇总：跳过已删机器的镜像快照", "skipped", skipped)
	}

	machines := []proto.MachineStatus{{Name: "", Ok: true, FetchedAt: time.Now().UTC()}}
	names := make([]string, 0, len(targets))
	for name := range targets {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		st := proto.MachineStatus{Name: name}
		if ts, ok := fetched[name]; ok {
			st.Ok = true
			st.FetchedAt = ts
		} else {

			st.Ok = false
			st.Error = "尚无该机器的镜像快照（可能从未可达，或它上面没有任务）"
		}
		machines = append(machines, st)
	}

	s.log.Info("任务汇总完成", "local", len(tasks), "mirrored", len(mirrors),
		"machines", len(machines))
	return proto.TasksResp{Machines: machines, Tasks: views}
}

n_agentd_Server_ticketDestructive.signature:
// ticketDestructive 判定工单是否属「破坏性/不可逆/外部可见」类（既有硬纪律的机械
// 代理，D-destructive 台账 L10）：该工单 task 事件流存在 approver_decision 事件
// （ticket_id 匹配且 decision ∈ {escalate, error}）——审批者不敢放行或裁决失败即
// 系统标记的危险请求。窗口用 recentEventsLimit=100（server.go:65，与任务详情同款）。
func (s *Server) ticketDestructive(taskID, ticketID string) bool {
	events, err := s.st.EventsFrom(taskID, 0, recentEventsLimit)
	if err != nil {
		return false
	}
	for _, ev := range events {
		if ev.Type != proto.EventTypeApproverDecision {
			continue
		}
		var p ApproverDecisionPayload
		if err := json.Unmarshal(ev.Payload, &p); err != nil {
			continue
		}
		if p.TicketID == ticketID && (p.Decision == "escalate" || p.Decision == "error") {
			return true
		}
	}
	return false
}

n_agentd_Server_triggerRestart.signature:
// triggerRestart 触发优雅关停。restart 未注入时只打日志——这只可能发生在
// 测试或 bootstrap 顺序出错时，静默返回会让「换版成功但永远不重启」变成
// 一个查不出根因的现象。
func (s *Server) triggerRestart(reason string) {
	if s.restart == nil {
		s.log.Error("换版后无法触发重启：restart 未注入", "reason", reason)
		return
	}
	if !s.restart(reason) {
		s.log.Warn("触发重启：已在关停中，本次触发被忽略", "reason", reason)
	}
}

n_agentd_Server_unlinkedSummary.signature:
// unlinkedSummary 「未挂账」摘要：登记 target 上存在、card_tasks 里没有、
// **且还没走到终态**的 task。拨号失败进入 unknown_targets，而不是假装为零。
//
// 为什么排除终态（见 unlinkedRowsFor）：这个摘要的用途是「账目对不上，需要
// 补挂卡」的兜底提醒——已 completed/failed 的历史任务补挂已无意义，把它们
// 算进来只会让角标常年停在三位数（实测本机 164 条全是终态），提醒退化成噪声。
func (s *Server) unlinkedSummary() map[string]any {
	s.unlinkedMu.Lock()
	defer s.unlinkedMu.Unlock()
	if time.Since(s.unlinkedAt) < 30*time.Second && s.unlinkedCache != nil {
		return s.unlinkedCache
	}

	linked := map[string]bool{}
	if links, err := s.ledger.AllTaskLinks(); err == nil {
		for _, link := range links {
			linked[link.Target+"/"+link.TaskID] = true
		}
	} else {
		s.log.Warn("读取挂账 task 失败，未挂账摘要可能不完整", "err", err)
	}

	rows := make([]map[string]any, 0)
	unknown := make([]string, 0)
	targets := s.cfgTargets()
	names := make([]string, 0, len(targets))
	for name := range targets {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {

		cl, err := s.pool.For(name)
		if err != nil {
			s.log.Warn("取 target 客户端失败，该机器计入未对账", "target", name, "cause", err)
			unknown = append(unknown, name)
			continue
		}
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
		tasks, err := cl.ListTasks(ctx)
		cancel()
		if err != nil {
			unknown = append(unknown, name)
			continue
		}
		rows = append(rows, unlinkedRowsFor(name, tasks, linked)...)
	}
	sort.Slice(rows, func(i, j int) bool {
		leftTarget, _ := rows[i]["target"].(string)
		rightTarget, _ := rows[j]["target"].(string)
		if leftTarget != rightTarget {
			return leftTarget < rightTarget
		}
		leftTask, _ := rows[i]["task_id"].(string)
		rightTask, _ := rows[j]["task_id"].(string)
		return leftTask < rightTask
	})
	sort.Strings(unknown)
	s.unlinkedCache = map[string]any{
		"count":	len(rows), "tasks": rows, "unknown_targets": unknown,
	}
	s.unlinkedAt = time.Now()
	return s.unlinkedCache
}

n_agentd_Server_wakeCoordinatorRound.signature:
// wakeCoordinatorRound 为 Wake 临时占用协调者回合名额，Wake 返回后释放。
// Release 失败只留完整身份日志，不覆盖 Wake 原始结果；启动对账仅是兜底。
func (s *Server) wakeCoordinatorRound(ctx context.Context, card string,
	evs []keystone.WakeEvent) (keystone.RoundResult, error) {
	var zero keystone.RoundResult
	current, err := s.ledger.GetCard(card)
	if err != nil {
		return zero, fmt.Errorf("读取唤醒席位: %w", err)
	}
	if current.DriverSession == "" && current.DriverSource == "" {
		s.keystone.Forget(card)
		s.log.Info("空座跳过协调者唤醒", "card", card, "event_count", len(evs))
		return zero, nil
	}
	if current.DriverSource == string(proto.SeatSourceBind) {
		s.keystone.Forget(card)
		s.log.Info("bind 席位跳过协调者唤醒", "card", card, "event_count", len(evs))
		return zero, nil
	}
	if err := proto.ValidateSeat(current.DriverSession, proto.SeatSource(current.DriverSource)); err != nil {
		return zero, fmt.Errorf("唤醒席位非法: %w", err)
	}
	squad, err := s.resolveCoordinatorSquad()
	if err != nil {
		return zero, &coordinatorLookupError{err: err}
	}
	binding, err := s.scheduling.LaunchAdmit(squad.Name)
	if err != nil {
		return zero, &coordinatorAdmissionError{squad: squad.Name, err: err}
	}
	defer s.releaseSchedulingBinding(card, binding)
	carrier, err := s.scheduling.Carrier(binding.Carrier)
	if err != nil {
		s.log.Error("读协调者载体失败", "card", card,
			"squad", binding.Squad, "carrier", binding.Carrier, "cause", err)
		return zero, fmt.Errorf("读载体 %s: %w", binding.Carrier, err)
	}
	spec := keysclient.SessionSpec{
		CLI:	binding.Executor, HomeDir: carrier.HomeDir, Model: binding.Model,
		Workdir:	s.resolveCoordWorkdir(card),
	}
	normalized, err := normalizeCoordinatorSpec(spec)
	if err != nil {
		s.log.Error("规范化协调者 SessionSpec 失败", "card", card,
			"squad", binding.Squad, "carrier", binding.Carrier, "cause", err)
		return zero, err
	}
	spec = normalized
	s.log.Info("自动化唤醒协调者回合", "card", card,
		"event_count", len(evs), "squad", binding.Squad, "carrier", binding.Carrier,
		"cli", spec.CLI, "home_dir", spec.HomeDir)
	result, err := s.keystone.Wake(ctx, card, evs, spec)
	if err != nil {
		s.log.Error("自动化唤醒协调者回合失败", "card", card,
			"event_count", len(evs), "squad", binding.Squad,
			"carrier", binding.Carrier, "cause", err)
		return result, fmt.Errorf("唤醒协调者回合失败: %w", err)
	}
	if result.Rebuilt && result.SessionID != "" && result.SessionID != current.DriverSession {
		cli, _, parseErr := proto.ParseSeatIdentity(current.DriverSession)
		if parseErr != nil {
			return result, fmt.Errorf("重建后解析旧席位: %w", parseErr)
		}
		identity, encodeErr := proto.EncodeSeatIdentity(cli, result.SessionID)
		if encodeErr != nil {
			return result, fmt.Errorf("重建后编码新席位: %w", encodeErr)
		}
		if rebindErr := s.ledger.RebindSeat(card, identity, proto.SeatSourceCoordinate, current.DriverSession); rebindErr != nil {
			if errors.Is(rebindErr, ledger.ErrCASConflict) {
				s.log.Error("协调者重建后席位 CAS 冲突，新会话保留待人工回收", "card", card,
					"event_count", len(evs), "session", result.SessionID, "cause", rebindErr)
				return result, &coordinatorSeatConflict{result: result}
			}
			return result, fmt.Errorf("重建后写协调者席位: %w", rebindErr)
		}
		s.log.Info("协调者重建后席位已更新", "card", card, "event_count", len(evs), "session", result.SessionID)
	}
	s.log.Info("自动化唤醒协调者回合结束", "card", card,
		"event_count", len(evs), "session", result.SessionID,
		"rebuilt", result.Rebuilt, "escalated", result.Escalated)
	return result, nil
}

n_agentd_Server_watchSession.signature:
// watchSession 周期性复验 WS 连接背后的会话，失效即以 close code 1008 关闭连接。
//
// 参数：
//   - ctx: 连接生命周期上下文（conn.CloseRead 返回的那个），连接断开即取消
//   - conn: 要看护的 WS 连接
//   - sessionID / taskID: 仅用于日志定位
//
// 注意：
//   - **为什么不建「会话 id → 连接 cancel 函数」的中心注册表**：注册表漏登记、
//     漏清理都不会报错，只会表现为「吊销了但没断」或连接泄漏，两者都难以观察
//     （封存清单缺陷 #4 的教训）。周期性复验是自愈的——查询失败就关连接，
//     fail-closed，最坏情况只是一个周期的滞后
//   - 只对会话身份的连接启动；Bearer（CLI）连接不受影响
func (s *Server) watchSession(ctx context.Context, conn *websocket.Conn, sessionID, taskID string) {
	t := time.NewTicker(s.sessionRecheck)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-t.C:
			sess, err := s.st.SessionByID(sessionID)
			switch {
			case err == nil && sess.RevokedAt == nil && time.Now().Before(sess.ExpiresAt):
				continue
			case err != nil && !errors.Is(err, store.ErrNotFound):

				s.log.Error("WS 会话复验失败，断开连接（fail-closed）",
					"session", sessionID, "task", taskID, "cause", err)
			default:
				s.log.Info("WS 会话已失效，断开在线连接", "session", sessionID, "task", taskID)
			}
			if cerr := conn.Close(websocket.StatusPolicyViolation, "session revoked"); cerr != nil {
				s.log.Warn("WS 关闭失效会话连接失败", "session", sessionID, "task", taskID, "err", cerr)
			}
			return
		}
	}
}

