n_agentd_Server_writeManagerError.signature:
// writeManagerError 把 manager 返回的错误映射为 HTTP 状态码与提示。
//
// 映射规则：store.ErrNotFound → 404；store.ErrBadTransit → 409（状态不允许）；
// executor.ErrTaskNotRunning → 409（executor 运行态已丢失，agentd 可能重启过，
// 需重新派发——可行动提示而非扁平 500）；其余 → 500。
func (s *Server) writeManagerError(w http.ResponseWriter, taskID, op string, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		s.log.Warn("manager 操作目标任务不存在", "task", taskID, "op", op)
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "任务不存在"})
	case errors.Is(err, store.ErrBadTransit):
		s.log.Warn("manager 操作状态不允许", "task", taskID, "op", op, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": "任务当前状态不允许该操作"})
	case errors.Is(err, executor.ErrTaskNotRunning):

		s.log.Warn("manager 操作遇执行器运行态已丢失", "task", taskID, "op", op, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": "任务执行器运行态已丢失（agentd 可能重启过），请重新派发"})
	default:
		s.log.Error("manager 操作失败", "task", taskID, "op", op, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "内部错误"})
	}
}

n_agentd_Server_writePreviewError.signature:
func (s *Server) writePreviewError(w http.ResponseWriter, operation, id string, err error) {
	status := http.StatusInternalServerError
	var inputErr *workspace.PreviewInputError
	switch {
	case errors.As(err, &inputErr):
		status = http.StatusBadRequest
	case errors.Is(err, store.ErrNotFound), errors.Is(err, workspace.ErrPreviewClosed):
		status = http.StatusNotFound
	}
	s.log.Warn("预览操作失败", "operation", operation, "session", id, "status", status, "cause", err)
	writeJSON(w, status, map[string]string{"error": err.Error()})
}

n_agentd_Server_writeProjectError.signature:
// writeProjectError 把项目登记操作的失败映射为 HTTP 状态码与可读原因。
//
// 映射规则（与 writeDispatchError 同一套哲学：调用方拿到就能行动）：
//   - store.ErrNotFound → 404：登记名不存在
//   - ErrProjectAlreadyExists → 409：项目/名字/路径已被占用，或克隆落点已存在——
//     与 ErrDirtyWorktree/ErrWorkdirBusy 同为状态冲突
//   - store.ErrProjectDuplicate → 409：改名/改路径撞上已被占用的名字或路径
//     （handleProjectPatch 直接透传 store 的冲突哨兵，映射集中在这一处）
//   - ErrWorkdirBusy → 409：注销时项目仓库仍被活跃任务占用
//   - ErrProjectOriginMismatch → 400：路径上是另一个项目——报文同时给出两边
//     的 origin，人一眼就能看出「你说的是 A，那儿实际是 B」
//   - workspace.ErrRepoUnusable / ErrBadDispatchRequest → 400：请求本身的问题
//     （路径不是仓库、没有 origin、clone 失败、参数缺失）
//   - 其余 → 500
func (s *Server) writeProjectError(w http.ResponseWriter, name string, err error) {
	switch {
	case errors.Is(err, store.ErrNotFound):
		s.log.Warn("项目登记操作被拒：登记不存在", "name", name, "cause", err)
		writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrProjectAlreadyExists):
		s.log.Warn("项目登记操作被拒：已存在", "name", name, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, store.ErrProjectDuplicate):
		s.log.Warn("项目登记操作被拒：名字或路径已被占用", "name", name, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, ErrWorkdirBusy):
		s.log.Warn("项目登记操作被拒：被活跃任务占用", "name", name, "cause", err)
		writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrProjectOriginMismatch):
		s.log.Warn("项目登记被拒：路径上是另一个项目", "name", name, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	case errors.Is(err, workspace.ErrRepoUnusable), errors.Is(err, ErrBadDispatchRequest):
		s.log.Warn("项目登记操作被拒：请求非法", "name", name, "cause", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})
	default:
		s.log.Error("项目登记操作失败", "name", name, "cause", err)
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "项目登记操作失败"})
	}
}

n_agentd_Server_writeReclaimError.signature:
// writeReclaimError 把 Reclaim 的错误翻成 HTTP 应答。
//
// 注意：4xx 一律 Warn 不 Error（B11 已定的纪律）——被拒不是 agentd 出故障
func (s *Server) writeReclaimError(w http.ResponseWriter, taskID string, err error) {
	var de *workspace.DirtyWorktreeError
	switch {
	case errors.Is(err, store.ErrNotFound):
		s.log.Warn("回收被拒：任务不存在", "task", taskID)
		writeJSON(w, http.StatusNotFound, proto.ReclaimError{Error: err.Error()})
	case errors.As(err, &de):
		s.log.Warn("回收被拒：工作树脏", "task", taskID, "dirty", len(de.Files))
		writeJSON(w, http.StatusConflict, proto.ReclaimError{
			Error:	err.Error(), Reason: proto.ReasonDirty, Dirty: de.Files})
	case errors.Is(err, ErrReclaimNotTerminal):
		s.log.Warn("回收被拒：任务非终态", "task", taskID)
		writeJSON(w, http.StatusConflict, proto.ReclaimError{
			Error:	err.Error(), Reason: proto.ReasonNotTerminal})
	case errors.Is(err, ErrReclaimNotManaged):
		s.log.Warn("回收被拒：非 managed 工作区", "task", taskID)
		writeJSON(w, http.StatusConflict, proto.ReclaimError{
			Error:	err.Error(), Reason: proto.ReasonNotManaged})
	case errors.Is(err, ErrReclaimRepoUnreachable):
		s.log.Warn("回收被拒：仓库不可达", "task", taskID, "cause", err)
		writeJSON(w, http.StatusConflict, proto.ReclaimError{
			Error:	err.Error(), Reason: proto.ReasonRepoUnreachable})
	default:
		s.log.Error("回收失败", "task", taskID, "cause", err)
		writeJSON(w, http.StatusInternalServerError, proto.ReclaimError{Error: err.Error()})
	}
}

n_agentd_Server_writeTicketError.signature:
// writeTicketError 输出兑换失败的说明。
//
// 为什么是 text/plain 而不是一张 HTML 错误页：纯文本既够用，又完全没有 HTML 注入面。
// （W5a 之后 agentd 确实托管前端了，但那不构成把这里换成 HTML 的理由——
// 这条路径处理的是**无效凭据**，此时给的东西越简单越好。）
func (s *Server) writeTicketError(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(http.StatusUnauthorized)
	if _, err := io.WriteString(w, "这个链接已失效，请重新执行 handoff console\n"); err != nil {
		s.log.Warn("写出 ticket 失效说明失败", "err", err)
	}
}

n_agentd_SetTaskProcCounter.signature:
// SetTaskProcCounter 注入「数某任务名下进程数」的实现，由 agentd 启动时调用一次。
//
// 参数：fn 为按任务 ID 返回 (进程数, 是否可信) 的实现，生产恒传 Manager.TaskProcCount。
//
// 注意：测试直接赋包级 taskProcCountFn 即可，不需要走本函数。
func SetTaskProcCounter(fn func(taskID string) (int, bool)) {
	taskProcCountFn = fn
}

n_agentd_Shutdown_Reason.signature:
// Reason 返回首次触发的停机原因；未触发时返回空串。
func (s *Shutdown) Reason() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.reason
}

n_agentd_Shutdown_Serve.signature:
// Serve 绑定 addrs 上的全部监听并阻塞，直到停机或任一监听失败。
//
// 参数：
//   - srv: 已配置好 Handler 的 HTTP 服务；addrs 为空时回退用 srv.Addr（单监听）
//   - cleanup: 停机时跑一次的清理闭包（关数据库、释放锁等）。**由调用方决定顺序**
//   - addrs: 监听地址列表（B85 双监听：主地址 + 可选的 loopback 辅址）
//
// 返回：
//   - nil 表示优雅关停完成（进程应 exit 0，管理器据此重新拉起）
//   - 非 nil 表示监听/启动失败（进程应 exit 1）。**任一地址绑不上都是启动失败**
//     （B85 决策：辅助监听与主监听同等对待，「第三档 = 两个监听都在」恒成立）
func (s *Shutdown) Serve(srv *http.Server, cleanup func(), addrs ...string) error {
	if len(addrs) == 0 {
		addrs = []string{srv.Addr}
	}
	lns := make([]net.Listener, 0, len(addrs))
	for _, a := range addrs {
		ln, err := net.Listen("tcp", a)
		if err != nil {

			for _, held := range lns {
				held.Close()
			}

			return fmt.Errorf("监听 %s: %w", a, err)
		}
		s.log.Debug("监听建立", "addr", ln.Addr().String())
		lns = append(lns, ln)
	}
	return s.serveWithListeners(lns, srv, cleanup)
}

n_agentd_Shutdown_Trigger.signature:
// Trigger 请求停机。
//
// 参数：
//   - reason: 停机原因，形如 "signal:terminated" / "update:v0.2.0"。会进日志
//
// 返回：
//   - true 表示本次调用真的触发了停机；false 表示已经在停了，本次被忽略
//
// 注意：
//   - 幂等。多路来源（信号 + 自更新）可能同时触发，只有第一个算数，
//     否则会有两条关停流程并发跑 cleanup
func (s *Shutdown) Trigger(reason string) bool {
	first := false
	s.once.Do(func() {
		first = true
		s.mu.Lock()
		s.reason = reason
		s.mu.Unlock()
		s.log.Info("收到停机请求", "reason", reason)
		close(s.fired)
	})
	if !first {
		s.log.Debug("停机请求被忽略（已在停机中）", "reason", reason, "first_reason", s.Reason())
	}
	return first
}

n_agentd_Shutdown_serveWithListeners.signature:
// serveWithListeners 是 Serve 的可测形态：监听器由调用方给。
//
// 拆出来的理由：单测要在随机可用端口上跑（net.Listen ":0"），而 Serve
// 从地址串里取地址、拿不到实际分配的端口。测试拿着 listener 才能知道
// 该往哪儿探活。
//
// 多 listener 挂同一个 http.Server：net/http 自己追踪所有经 Serve 注入的
// listener，srv.Shutdown 会把它们全部关掉——优雅关停无需感知监听个数。
func (s *Shutdown) serveWithListeners(lns []net.Listener, srv *http.Server, cleanup func()) error {

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	defer signal.Stop(sigCh)
	go func() {
		sig, ok := <-sigCh
		if !ok {
			return
		}
		s.Trigger("signal:" + sig.String())
	}()

	errCh := make(chan error, len(lns))
	for _, ln := range lns {
		go func(ln net.Listener) {

			if err := srv.Serve(ln); err != nil && !errors.Is(err, http.ErrServerClosed) {
				errCh <- err
				return
			}
			errCh <- nil
		}(ln)
	}

	select {
	case err := <-errCh:

		if err != nil {
			s.log.Error("HTTP 服务异常退出", "cause", err)
			return fmt.Errorf("HTTP 服务: %w", err)
		}

		s.log.Warn("HTTP 服务在未触发停机的情况下正常返回")
		cleanup()
		return nil
	case <-s.fired:
	}

	reason := s.Reason()
	s.log.Info("开始优雅关停", "reason", reason, "grace", ShutdownGrace)
	ctx, cancel := context.WithTimeout(context.Background(), ShutdownGrace)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {

		s.log.Warn("等待在途请求超时，继续收尾", "cause", err, "grace", ShutdownGrace)
	}
	cleanup()
	s.log.Info("优雅关停完成", "reason", reason)
	return nil
}

n_agentd_VoidTicketsWithAudit.signature:
// VoidTicketsWithAudit 作废任务的全部挂起工单，并在确实作废了东西时留一条审计事件。
//
// 参数：
//   - st: 存储
//   - taskID: 任务 ID
//   - reason: 作废原因，进事件 payload 与日志
//   - log: 日志入口
//
// 返回：
//   - 本次被作废的工单数；出错或无单可作废时为 0
//
// 注意：
//   - voided == 0 时**不产出事件**：绝大多数任务终结时本就没有挂起工单，
//     无条件写事件等于给每条正常事件流添噪音
//   - 依赖 VoidPendingTickets 的幂等（第二次起返回 0）来天然去重，本函数不另做判重
//   - 失败一律只记日志：见文件头「不中断调用方」
func VoidTicketsWithAudit(st *store.Store, taskID, reason string, log *slog.Logger) int {
	voided, err := st.VoidPendingTickets(taskID)
	if err != nil {
		log.Error("作废挂起工单失败", "task", taskID, "reason", reason, "cause", err)
		return 0
	}
	if voided == 0 {
		return 0
	}
	log.Warn("挂起工单已作废", "task", taskID, "reason", reason, "voided", voided)
	if _, err := st.AppendEvent(taskID, proto.EventTypeTicketsVoided,
		TicketsVoidedPayload{Voided: voided, Reason: reason}); err != nil {
		log.Error("追加工单作废审计事件失败", "task", taskID, "voided", voided, "cause", err)
	}
	return voided
}

n_agentd_alignToLineStart.signature:
// alignToLineStart 丢掉开头那个不完整的行，返回从第一个完整行开始的切片。
//
// 整段都没有换行时返回空切片：一个完整行都没有，什么也发不了。
func alignToLineStart(b []byte) []byte {
	i := bytes.IndexByte(b, '\n')
	if i < 0 {
		return nil
	}

	if i == len(b)-1 {
		return b
	}
	return b[i+1:]
}

n_agentd_attachLocator_Locate.signature:
func (l attachLocator) Locate(ref keysclient.SessionRef, workdir string) (keysclient.AttachInfo, error) {
	if ref.SessionID == "" {
		return keysclient.AttachInfo{}, errors.New("该卡没有绑定的协调者会话")
	}
	if strings.TrimSpace(ref.HomeDir) == "" {
		return keysclient.AttachInfo{}, errors.New("协调者 attach 缺少 HomeDir")
	}
	expand := l.expandHome
	if expand == nil {
		expand = hostapi.ExpandHomePath
	}
	expandedHome, err := expand(ref.HomeDir)
	if err != nil {
		return keysclient.AttachInfo{}, fmt.Errorf("展开协调者 attach HOME %q: %w", ref.HomeDir, err)
	}
	if !filepath.IsAbs(expandedHome) {
		return keysclient.AttachInfo{}, fmt.Errorf("协调者 attach HOME 不是绝对路径: %q", expandedHome)
	}
	return keysclient.AttachInfo{
		Machine:	ref.Machine, Dir: workdir,
		Command:	fmt.Sprintf("HOME=%s %s --session %s", shellQuote(expandedHome), shellQuote(ref.CLI), shellQuote(ref.SessionID)),
	}, nil
}

n_agentd_automationCursorStore_Load.signature:
// Load 读取本机自动化消费水位；缺文件表示首次运行并返回 0，其余错误保留路径上下文。
func (s *automationCursorStore) Load() (int64, error) {
	raw, err := os.ReadFile(s.path)
	if os.IsNotExist(err) {
		return 0, nil
	}
	if err != nil {
		return 0, fmt.Errorf("读自动化 cursor 文件 %s: %w", s.path, err)
	}
	var disk automationCursorDisk
	if err := json.Unmarshal(raw, &disk); err != nil {
		return 0, fmt.Errorf("解析自动化 cursor 文件 %s: %w", s.path, err)
	}
	return disk.Seq, nil
}

n_agentd_automationCursorStore_Save.signature:
// Save 以 JSON seq 原子替换本机 cursor；失败时清理临时文件并保留主文件。
func (s *automationCursorStore) Save(seq int64) error {
	raw, err := json.Marshal(automationCursorDisk{Seq: seq})
	if err != nil {
		return fmt.Errorf("编码自动化 cursor: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(s.path), 0o700); err != nil {
		return fmt.Errorf("创建自动化 cursor 目录 %s: %w", filepath.Dir(s.path), err)
	}
	tmp := s.path + ".tmp"
	if err := os.WriteFile(tmp, raw, 0o600); err != nil {
		_ = os.Remove(tmp)
		return fmt.Errorf("写自动化 cursor 临时文件 %s: %w", tmp, err)
	}
	if err := os.Rename(tmp, s.path); err != nil {
		_ = os.Remove(tmp)
		return fmt.Errorf("替换自动化 cursor 文件 %s: %w", s.path, err)
	}
	return nil
}

n_agentd_automationWakeEvent.signature:
// automationWakeEvent 的 false 表示合法但不唤醒；摘要最多 400 rune，原事件仍在账本。
func automationWakeEvent(ev proto.LedgerEvent) (keystone.WakeEvent, bool, error) {
	if ev.CardID == "" {
		return keystone.WakeEvent{}, false, nil
	}
	switch ev.Type {
	case ledger.EvTaskMirrored:
		taskType, payload, err := mirroredTaskTypeAndPayload(ev)
		if err != nil {
			return keystone.WakeEvent{}, false, err
		}
		if !client.WaitDeliveryPolicy(proto.EventType(taskType)) {
			slog.Default().Debug("task_mirrored 因任务消费策略过滤", "seq", ev.Seq,
				"card", ev.CardID, "type", ev.Type, "task_type", taskType,
				"reason", "delivery_policy_false")
			return keystone.WakeEvent{}, false, nil
		}
		kind := keystone.WakeTaskTerminal
		if proto.EventType(taskType) == proto.EventTypePermissionRequest ||
			proto.EventType(taskType) == proto.EventTypeQuestion {
			kind = keystone.WakeTicket
		}
		return keystone.WakeEvent{
			Kind:	kind, Card: ev.CardID,
			Summary:	fmt.Sprintf("%s: %s", taskType, truncateRunes(string(payload), 400)),
		}, true, nil
	case ledger.EvRoomMessage:
		msg, yes, err := decodeHumanRoomMessage(ev)
		if err != nil {
			return keystone.WakeEvent{}, false, err
		}
		if !yes {
			return keystone.WakeEvent{}, false, nil
		}
		return keystone.WakeEvent{
			Kind:	keystone.WakeMessage, Card: ev.CardID,
			Summary:	truncateRunes(msg.Body, 400),
		}, true, nil
	case ledger.EvStatusMoved:
		var moved struct {
			To string `json:"to"`
		}
		if err := json.Unmarshal(ev.Payload, &moved); err == nil {

			return keystone.WakeEvent{}, false, nil
		}
		return keystone.WakeEvent{}, false, nil
	case ledger.EvNeedsHuman, ledger.EvNeedsCleared,
		ledger.EvDecisionOpened, ledger.EvDecisionAnswered:
		return keystone.WakeEvent{
			Kind:	keystone.WakeTaskTerminal, Card: ev.CardID,
			Summary:	fmt.Sprintf("%s: %s", ev.Type, truncateRunes(string(ev.Payload), 400)),
		}, true, nil
	default:
		return keystone.WakeEvent{}, false, nil
	}
}

n_agentd_bearerToken.signature:
// bearerToken 从 Authorization 头解析 "Bearer <token>" 形式的令牌。
//
// 返回：
//   - token: 解析出的令牌
//   - ok: 头部存在且前缀为 "Bearer "（token 本身可为空，由调用方与配置比较）
func bearerToken(r *http.Request) (string, bool) {
	return strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
}

n_agentd_browserName.signature:
// browserName 从 User-Agent 里粗略识别浏览器名。
//
// 只做展示用途，因此刻意保持极简：识别不出就返回空串，绝不把整个 UA 串塞进
// 设备名（那既难看又是一条把攻击者可控长文本写进库的路径）。
// 注意顺序：Edge 与 Chrome 的 UA 都含 "Chrome"，Chrome 与 Safari 的都含 "Safari"。
func browserName(ua string) string {
	switch {
	case strings.Contains(ua, "Edg/"):
		return "Edge"
	case strings.Contains(ua, "Firefox/"):
		return "Firefox"
	case strings.Contains(ua, "Chrome/"):
		return "Chrome"
	case strings.Contains(ua, "Safari/"):
		return "Safari"
	}
	return ""
}

n_agentd_carrierView.signature:
// carrierView 把载体实体投影成 wire DTO。逐字段来源：八个业务字段来自实体，
// Version 来自 registry 行版本——没有派生字段，不存在恒空死字段。
func carrierView(c scheduling.Carrier, version int) proto.CarrierView {
	return proto.CarrierView{
		Name:	c.Name, Machine: c.Machine, CLI: c.CLI, HomeDir: c.HomeDir,
		Model:	c.Model, Credential: string(c.Credential),
		MaxConcurrency:	c.MaxConcurrency,
		Status:		string(c.Status), LastError: c.LastError, Version: version,
	}
}

n_agentd_checkProcHeadroom.signature:
// checkProcHeadroom 在开工前判读一次进程余量。
//
// 参数：op 为动作名（"dispatch" / "run"），只用于日志与错误文案
//
// 返回：余量耗尽时返回包装 ErrNoProcHeadroom 的错误（文案带 used/limit
// 真实数字）；其余情况一律 nil。
//
// 注意：
//   - 高水位（九成）**放行**并打 Warn：拦在这里等于把「快满了」当「满了」，
//     会把还能正常完成的任务无谓挡掉
//   - 读数不可信时**放行**（fail-open）：为「量不出来」而拒绝派发，会让
//     handoff 在不支持的平台上彻底不能用，代价远大于收益
//
// 与 spec §3.4 的一处有意偏离：spec 写「`used ≥ 0.9L`：放行，但 stderr 警告
// + 事件记录」。这里只打服务端 Warn 日志，**不在准入闸里发事件**——高水位事件
// 由 Task 6 的看门狗统一按「越线沿一次」发射。若准入闸也发，一轮密集派发会
// 产生 N 条重复事件，把协调者的会话刷爆，反而淹掉真正要处置的工单。协调者
// 得到的信息量不减（同一条 `resource_pressure` 事件），噪声大减。
func checkProcHeadroom(op string) error {
	a := admissionFn()
	if !a.Known {
		log().Debug("进程余量未知，放行", "op", op)
		return nil
	}
	if a.Full() {
		log().Error("进程余量耗尽，拒绝开工", "op", op, "used", a.Used, "limit", a.Limit)
		return fmt.Errorf("%w：当前 %d/%d，请等待在跑的任务结束或先回收残留",
			ErrNoProcHeadroom, a.Used, a.Limit)
	}
	if a.NearFull() {
		log().Warn("进程余量已达高水位，仍放行", "op", op, "used", a.Used, "limit", a.Limit)
		return nil
	}
	log().Debug("进程余量充足", "op", op, "used", a.Used, "limit", a.Limit)
	return nil
}

n_agentd_cleanupOldDesktopDownloads.signature:
// cleanupOldDesktopDownloads 删除同目录里旧的 handoff-desktop_* 普通文件。
//
// 参数：dir 是下载目录，keep 是当前安装包文件名。
// 返回：成功删除的文件数量；目录读取或单文件删除失败只记日志并继续清理。
func cleanupOldDesktopDownloads(log *slog.Logger, dir, keep string) int {
	entries, err := os.ReadDir(dir)
	if err != nil {
		log.Error("清理旧安装包失败", "dir", dir, "cause", err)
		return 0
	}
	removed := 0
	for _, entry := range entries {
		if entry.Name() == keep || !strings.HasPrefix(entry.Name(), "handoff-desktop_") {
			continue
		}
		info, err := entry.Info()
		if err != nil {
			log.Warn("检查旧安装包失败", "path", filepath.Join(dir, entry.Name()), "cause", err)
			continue
		}
		if !info.Mode().IsRegular() {
			continue
		}
		path := filepath.Join(dir, entry.Name())
		if err := os.Remove(path); err != nil {
			log.Warn("删除旧安装包失败", "path", path, "cause", err)
			continue
		}
		removed++
	}
	return removed
}

n_agentd_collabErr.signature:
// collabErr 把 collab.Service 哨兵翻译为 HTTP 状态（契约 §3.3 哨兵集 + §3.5 映射表）。
// ErrNoRoom/ErrKindNotAllowed→400、ErrNotWriter→403、ErrReadOnly/ErrNotBound→409。
// History 的 ErrNoRoom→404 特例由 handleRoomMessages 自行处理。
func collabErr(w http.ResponseWriter, err error) {
	code := http.StatusInternalServerError
	switch {
	case errors.Is(err, collab.ErrNoRoom), errors.Is(err, collab.ErrKindNotAllowed):
		code = http.StatusBadRequest
	case errors.Is(err, collab.ErrNotWriter):
		code = http.StatusForbidden
	case errors.Is(err, collab.ErrReadOnly), errors.Is(err, collab.ErrNotBound):
		code = http.StatusConflict
	}
	writeErr(w, code, err)
}

n_agentd_consoleURL.signature:
// consoleURL 用请求自身的 Host 拼出 /console 的兑换地址。
//
// 为什么用 r.Host 而不是 cfg.Listen：CLI 可能经 --target 访问一台远端 agentd，
// 也可能经 --agentd 指定别的端点。请求打到哪里，能兑换的就是哪里。
// scheme 只按 r.TLS 判定，不读 X-Forwarded-Proto（理由见文件头边界）。
func consoleURL(r *http.Request, ticket string) string {
	scheme := "http"
	if r.TLS != nil {
		scheme = "https"
	}
	return scheme + "://" + r.Host + "/console?ticket=" + url.QueryEscape(ticket)
}

n_agentd_containsString.signature:
// containsString 判断名单里有没有某个名字（名单只有个位数长度，线性扫足够）。
func containsString(list []string, want string) bool {
	for _, s := range list {
		if s == want {
			return true
		}
	}
	return false
}

