n_agentd_coordinatorSessionRefResolver_R.signature:
func (r coordinatorSessionRefResolver) ResolveSessionRef(card string, ref keysclient.SessionRef) (keysclient.SessionRef, error) {
	if r.server == nil || r.server.scheduling == nil {
		return ref, errors.New("协调者 attach 无编制域读取端口")
	}
	slog.Default().Info("协调者 SessionRef 解析开始", "card", card, "has_home", ref.HomeDir != "",
		"has_session", ref.SessionID != "")
	if ref.HomeDir == "" {
		squad, err := r.server.resolveCoordinatorSquad()
		if err != nil {
			slog.Default().Error("读取协调者小队失败", "card", card, "cause", err)
			return ref, fmt.Errorf("读取协调者小队以恢复卡 %s HOME: %w", card, err)
		}
		var found bool
		for _, member := range squad.Members {
			carrier, readErr := r.server.scheduling.Carrier(member.Carrier)
			if readErr != nil {
				slog.Default().Error("读取协调者载体失败", "card", card, "carrier", member.Carrier, "cause", readErr)
				return ref, fmt.Errorf("读取协调者载体 %s HOME: %w", member.Carrier, readErr)
			}
			if carrier.Status != scheduling.StatusOnline {
				continue
			}
			ref.HomeDir = carrier.HomeDir
			if strings.TrimSpace(ref.HomeDir) == "" {
				ref.HomeDir = "~"
			}
			found = true
			break
		}
		if !found {
			err := fmt.Errorf("协调者小队 %s 没有已上线载体可恢复 HOME", squad.Name)
			slog.Default().Error("恢复协调者 HOME 失败", "card", card, "squad", squad.Name, "cause", err)
			return ref, err
		}
	}
	expand := r.expandHomeDir
	if expand == nil {
		expand = hostapi.ExpandHomePath
	}
	expanded, err := expand(ref.HomeDir)
	if err != nil {
		slog.Default().Error("展开协调者 attach HOME 失败", "card", card, "home_dir", ref.HomeDir, "cause", err)
		return ref, fmt.Errorf("展开卡 %s 的协调者 attach HOME %q: %w", card, ref.HomeDir, err)
	}
	if !filepath.IsAbs(expanded) {
		err := fmt.Errorf("卡 %s 的协调者 attach HOME 不是绝对路径: %q", card, expanded)
		slog.Default().Error("协调者 attach HOME 非绝对路径", "card", card, "expanded", expanded, "cause", err)
		return ref, err
	}
	ref.HomeDir = expanded
	slog.Default().Info("协调者 SessionRef 解析成功", "card", card, "home_dir", ref.HomeDir)
	return ref, nil
}

n_agentd_copyForwardHeaders.signature:
// copyForwardHeaders 只搬 agentd 线契约拥有的响应头（Content-Type 与 X-Handoff-*）。
//
// 为什么不整份复制：逐跳头（Connection、Transfer-Encoding 之类）与传输层相关的头
// 描述的是**本端到对端那一条连接**，搬给下游客户端会与本端真实的传输方式冲突。
func copyForwardHeaders(w http.ResponseWriter, headers http.Header) {
	if contentType := headers.Get("Content-Type"); contentType != "" {
		w.Header().Set("Content-Type", contentType)
	}
	for key, values := range headers {
		if !strings.HasPrefix(http.CanonicalHeaderKey(key), "X-Handoff-") {
			continue
		}
		for _, value := range values {
			w.Header().Add(key, value)
		}
	}
}

n_agentd_copyFrom.signature:
// copyFrom 把 path 从 offset 起的全部剩余内容拷到 w，返回拷贝字节数。
//
// 文件不存在返回 (0, nil)：follow 模式下这是「还没开始产出」的正常状态。
func copyFrom(w io.Writer, path string, offset int64) (int64, error) {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("打开 %s: %w", path, err)
	}
	defer f.Close()
	if _, err := f.Seek(offset, io.SeekStart); err != nil {
		return 0, fmt.Errorf("定位 %s 到 %d: %w", path, offset, err)
	}
	n, err := io.Copy(w, f)
	if err != nil {
		return n, fmt.Errorf("读 %s: %w", path, err)
	}
	return n, nil
}

n_agentd_copyMissingCoordinatorCredentia.signature:
// copyMissingCoordinatorCredential 仅拷贝该 CLI 缺失的单文件登录凭据。
// 为什么不用整树同步：隔离 HOME 不依赖主 HOME 的生命周期，也不会通过 symlink 越出白名单；
// 整树同步会覆盖隔离侧已有的 session 数据库或运行状态。因此仅复制白名单内的缺失凭据。
func copyMissingCoordinatorCredential(mainHome, targetHome, cli string,
	credentialPath func(string) (string, bool)) error {
	if credentialPath == nil {
		return nil
	}
	rel, ok := credentialPath(filepath.Base(cli))
	if !ok || rel == "" || filepath.IsAbs(rel) {
		return nil
	}
	source := filepath.Join(mainHome, rel)
	info, err := os.Lstat(source)
	if errors.Is(err, os.ErrNotExist) {
		slog.Default().Warn("协调者主 HOME 缺少表内凭据，跳过供给", "cli", cli, "source", source)
		return nil
	}
	if err != nil {
		return fmt.Errorf("stat 主 HOME 凭据 %q: %w", source, err)
	}
	if info.Mode()&os.ModeSymlink != 0 || !info.Mode().IsRegular() {
		return fmt.Errorf("主 HOME 凭据不是普通文件 %q", source)
	}
	destination := filepath.Join(targetHome, rel)
	if existing, statErr := os.Lstat(destination); statErr == nil {
		if existing.Mode()&os.ModeSymlink != 0 || !existing.Mode().IsRegular() {
			return fmt.Errorf("隔离凭据目标不是普通文件 %q", destination)
		}
		slog.Default().Info("协调者隔离凭据已存在，保留原文件", "cli", cli, "target", destination,
			"mode", existing.Mode().String())
		return nil
	} else if !errors.Is(statErr, os.ErrNotExist) {
		return fmt.Errorf("检查隔离凭据 %q: %w", destination, statErr)
	}
	if err := os.MkdirAll(filepath.Dir(destination), 0o700); err != nil {
		return fmt.Errorf("创建隔离凭据父目录 %q: %w", filepath.Dir(destination), err)
	}
	data, err := os.ReadFile(source)
	if err != nil {
		return fmt.Errorf("读取主 HOME 凭据 %q: %w", source, err)
	}
	if err := os.WriteFile(destination, data, info.Mode().Perm()); err != nil {
		return fmt.Errorf("写隔离凭据 %q: %w", destination, err)
	}
	if err := os.Chmod(destination, info.Mode().Perm()); err != nil {
		return fmt.Errorf("设置隔离凭据权限 %q: %w", destination, err)
	}
	slog.Default().Info("协调者缺失凭据已供给", "cli", cli, "target", destination)
	return nil
}

n_agentd_decisionTitle.signature:
// decisionTitle 收件箱 decision 条目标题 = 裁决正文首行（简报六段的第一段是「一句话」）。
func decisionTitle(d ledger.Decision) string {
	body := strings.TrimSpace(d.Body)
	if i := strings.IndexByte(body, '\n'); i >= 0 {
		body = body[:i]
	}
	if n := len([]rune(body)); n > 80 {
		return string([]rune(body)[:80]) + "…"
	}
	return body
}

n_agentd_decodeHumanRoomMessage.signature:
func decodeHumanRoomMessage(ev proto.LedgerEvent) (proto.RoomMessage, bool, error) {
	var msg proto.RoomMessage
	if err := json.Unmarshal(ev.Payload, &msg); err != nil {
		return proto.RoomMessage{}, false,
			fmt.Errorf("事件 %d 的 room_message 解码失败: %w", ev.Seq, err)
	}
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(ev.Payload, &fields); err != nil {
		return proto.RoomMessage{}, false,
			fmt.Errorf("事件 %d 的 room_message 字段解码失败: %w", ev.Seq, err)
	}
	if raw, present := fields["by_system"]; present &&
		bytes.Equal(bytes.TrimSpace(raw), []byte("null")) {
		return msg, false, nil
	}
	if msg.Kind != proto.RoomMsgUser || msg.BySystem {
		return msg, false, nil
	}
	return msg, true, nil
}

n_agentd_decodeMirroredTaskEnvelope.signature:
func decodeMirroredTaskEnvelope(ev proto.LedgerEvent) (mirroredTaskEnvelope, error) {
	var envelope mirroredTaskEnvelope
	if ev.Type != ledger.EvTaskMirrored {
		return envelope, fmt.Errorf("事件 %d 不是 task_mirrored: %s", ev.Seq, ev.Type)
	}
	if err := json.Unmarshal(ev.Payload, &envelope); err != nil {
		return envelope, fmt.Errorf("事件 %d 的 task_mirrored envelope 解码失败: %w", ev.Seq, err)
	}
	if envelope.TaskType == "" || len(envelope.Payload) == 0 {
		return envelope, fmt.Errorf("事件 %d 的 task_mirrored 缺 task_type/payload", ev.Seq)
	}
	return envelope, nil
}

n_agentd_decodePreviewJSON.signature:
func decodePreviewJSON(r *http.Request, dst any) error {
	dec := json.NewDecoder(r.Body)
	if err := dec.Decode(dst); err != nil {
		return err
	}
	var extra any
	if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("请求体不允许尾随 JSON")
		}
		return err
	}
	return nil
}

n_agentd_desktopDownloadChecksum.signature:
// desktopDownloadChecksum 构造生产校验和查询缝。
//
// 参数：inst 是带 agentd 出网代理与日志的 release installer。
// 返回：按 tag/资产名从该 release 的 checksums.txt 解出的 sha256。
func desktopDownloadChecksum(inst *release.Installer) func(context.Context, string, string) (string, error) {
	return func(ctx context.Context, tag, assetName string) (string, error) {
		rel := release.Release{Tag: tag, Assets: []release.Asset{
			{Name: release.ChecksumsName, URL: release.AssetURL(release.DefaultRepo, tag, release.ChecksumsName)},
		}}
		return inst.FetchChecksumFor(ctx, rel, assetName)
	}
}

n_agentd_desktopDownloadFetcher.signature:
// desktopDownloadFetcher 构造生产下载缝：校验和走 release 的 checksums.txt，
// 安装包走确定性的 release 资产地址；两者都不经过控制台或 reveal 路由。
//
// 参数：inst 是带 agentd 出网代理与日志的 release installer。
// 返回：按 tag/资产名返回安装包字节、期望 sha256 与错误。
func desktopDownloadFetcher(inst *release.Installer) func(context.Context, string, string) ([]byte, string, error) {
	return func(ctx context.Context, tag, assetName string) ([]byte, string, error) {
		want, err := desktopDownloadChecksum(inst)(ctx, tag, assetName)
		if err != nil {
			return nil, "", err
		}

		url := release.AssetURL(release.DefaultRepo, tag, assetName)
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
		if err != nil {
			return nil, "", fmt.Errorf("构造安装包请求: %w", err)
		}
		resp, err := inst.HTTP.Do(req)
		if err != nil {
			return nil, "", fmt.Errorf("下载安装包: %w", err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			return nil, "", fmt.Errorf("下载安装包返回 %d", resp.StatusCode)
		}
		body, err := io.ReadAll(io.LimitReader(resp.Body, maxUpdateBytes+1))
		if err != nil {
			return nil, "", fmt.Errorf("读取安装包: %w", err)
		}
		if len(body) > maxUpdateBytes {
			return nil, "", fmt.Errorf("安装包超过 %d 字节上限", maxUpdateBytes)
		}
		return body, want, nil
	}
}

n_agentd_detectEvidence.signature:
// detectEvidence 是 detect handler 唯一的 wake outcome 白名单。未知值不落库，
// 防止新增/拼错 outcome 误走 default online。
func detectEvidence(outcome string) (scheduling.DetectEvidence, bool) {
	switch outcome {
	case string(hostapi.WakeReady):
		return scheduling.DetectEvidence{Reachable: true}, true
	case string(hostapi.WakeNeedLogin):
		return scheduling.DetectEvidence{Reachable: true, NeedLogin: true}, true
	case string(hostapi.WakeQuota):
		return scheduling.DetectEvidence{Reachable: true, Quota: true}, true
	case string(hostapi.WakeUnreachable):
		return scheduling.DetectEvidence{Reachable: false}, true
	default:
		return scheduling.DetectEvidence{}, false
	}
}

n_agentd_dispatchStep.signature:
// dispatchStep 是节点派发的具名执行消费点，依赖声明收窄到 client.ExecutionClient。
// 只把 ledgerstep 已经装配好的请求镜像成 client.DispatchOpts，不做准入或改写。
func dispatchStep(ctx context.Context, cl client.ExecutionClient, opts ledgerstep.DispatchOpts, target string) (*proto.Task, error) {
	return cl.Dispatch(ctx, client.DispatchOpts{
		Prompt:	opts.Prompt, Target: target,
		Receiver:	opts.Receiver,
		Carrier:	opts.Carrier, Squad: opts.Squad,
		NewBranch:	opts.Branch, Branch: opts.ExistingBranch,
		ProjectName:	opts.Project, Executor: opts.Executor, Model: opts.Model,
		HomeDir:		opts.HomeDir,
		Discipline:		opts.Discipline,
		DisciplineText:		opts.DisciplineText,
		DisciplineVersion:	opts.DisciplineVersion,
		PlanB64:		opts.PlanB64, PlanName: opts.PlanName, Base: opts.Base,
		ResolveDefaultBase:	opts.ResolveDefaultBase,
		LocalBaseBranch:	opts.LocalBaseBranch,
		NewWorktree:		opts.NewWorktree,
	})
}

n_agentd_effectiveCovers.signature:
// effectiveCovers 只算模型覆盖；物理身份必须由已准入载体提供。
// 返回的 target/executor 恒为空，避免卡节点在绑定前后形成第二条物理落点路径。
//
// 模型的成对规则仍与 dispatchNodeWithGate 一致；ledgerstep 不再接收卡节点物理
// 覆盖。模型行由本文件的矩阵测试锁定，物理恒空是本卡 P7(a) 的新边界。
func effectiveCovers(req proto.CardStepReq, node ledger.NodeDef) (target, executor, model string) {
	executor = node.Override.Executor
	model = node.Override.Model
	if req.Executor != "" {
		executor = req.Executor
		if req.Model != "" || req.Executor != node.Override.Executor {
			model = req.Model
		}
	} else if req.Model != "" {
		model = req.Model
	}
	return "", "", model
}

n_agentd_emitReclaimFailed.signature:
// emitReclaimFailed 在强制回收失败时向协调者发一条可见提示。
//
// 参数：taskID / used / hardLimit / cause 全部进文案——审核者要据此判断该不该
// 人工上机处理；log 为本模块日志入口。
//
// 注意：调用方负责边沿去重（见 scanTaskProcs 的 reclaimFailed）。本函数不改
// 任务状态——回收失败时任务必须留在活跃集里继续被点名。
func emitReclaimFailed(st *store.Store, hub *Hub, taskID string, used, hardLimit int, cause error, log *slog.Logger) {
	text := fmt.Sprintf("强制回收失败：任务进程数 %d 超过硬上限 %d，但 executor 未能停止（原因：%v）。"+
		"任务保持活跃并将每轮重试，请用 handoff status %s 确认后人工处理", used, hardLimit, cause, taskID)
	evt, err := st.AppendEvent(taskID, proto.EventTypeProgress, ProgressPayload{Text: text})
	if err != nil {
		log.Error("追加强制回收失败提示事件失败", "task", taskID, "cause", err)
		return
	}
	hub.Publish(evt)
	log.Warn("已向协调者发出强制回收失败提示", "task", taskID, "used", used, "hard_limit", hardLimit)
}

n_agentd_eventFrameHook.signature:
// eventFrameHook 返回一个「事件落库后写 event 引用帧」的回调。
//
// 参数：
//   - dataDir: agentd 数据目录（任务目录在 dataDir/tasks/<id> 下）
//   - log:     日志入口
//
// 注意：任务目录不存在时静默跳过——事件可能属于一个目录已被清掉的任务，
// 那不是错误，只是没有帧文件可写。
func eventFrameHook(dataDir string, log *slog.Logger) func(proto.Event) {
	return func(e proto.Event) {
		taskDir := filepath.Join(dataDir, "tasks", e.TaskID)
		if _, err := os.Stat(taskDir); err != nil {
			return
		}
		w, err := turn.WriterFor(taskDir, log)
		if err != nil {
			log.Warn("事件帧：创建帧写入器失败", "task", e.TaskID, "seq", e.Seq, "cause", err)
			return
		}
		if err := w.EventRef(e.Seq, string(e.Type)); err != nil {
			log.Warn("事件帧：写入失败", "task", e.TaskID, "seq", e.Seq,
				"type", e.Type, "cause", err)
			return
		}
		log.Debug("事件帧已写入", "task", e.TaskID, "seq", e.Seq, "type", e.Type)
	}
}

n_agentd_expectVersion.signature:
// expectVersion 解析 ?expect= 版本参数。缺席/非整数/负数都是 400：版本语义
// 不设隐含默认，防止「没带就当 0」把更新静默变新建。
func expectVersion(r *http.Request) (int, bool, error) {
	raw := r.URL.Query().Get("expect")
	if raw == "" {
		return 0, false, errors.New("缺少 expect 版本参数（GET /api/squads 取各行 version；新建传 0）")
	}
	n, err := strconv.Atoi(raw)
	if err != nil || n < 0 {
		return 0, false, fmt.Errorf("expect 不是合法版本号: %q", raw)
	}
	return n, true, nil
}

