n_agentd_fillFromStatus.signature:
// fillFromStatus 把 GET /api/status 的响应投影进机器条目。
//
// executors / default_executor 是探活本来就拿到的东西，丢掉纯属浪费；
// active_tasks 是活跃任务条数。
func fillFromStatus(m *proto.Machine, st *proto.StatusResp) {
	m.Reachable = true
	m.Version = st.Version.Version
	if st.Executors != nil {
		m.Executors = st.Executors
	}
	m.DefaultExecutor = st.DefaultExecutor
	m.ActiveTasks = len(st.Active)

	m.PtySupported = st.PtySupported
	m.LaunchersSupported = st.LaunchersSupported
	m.DisciplinesSupported = st.DisciplinesSupported
	m.RevealSupported = st.RevealSupported
	m.ScratchRoot = st.ScratchRoot
}

n_agentd_forwardURL.signature:
// forwardURL 拼出目标 URL：目标机基址 + 原路径 + 去掉 machine 的查询串。
//
// addr 现在恒为池客户端的 BaseURL()（已带 scheme），normalizeAddr 只是兜底保留。
//
// 为什么要摘掉 machine：它是**本机的路由指令**，不是业务参数。留着它，目标机
// 看到的就是一个「让我转发给我自己」的请求——虽然被防环头挡住，但语义上是脏的。
func forwardURL(addr string, src *url.URL) (string, error) {
	base, err := url.Parse(normalizeAddr(addr))
	if err != nil {
		return "", err
	}
	q := src.Query()
	q.Del("machine")
	base.Path = src.Path
	base.RawQuery = q.Encode()
	return base.String(), nil
}

n_agentd_hostAllowlist_allow.signature:
// allow 判断 host（已去端口、未归一大小写）是否在白名单内。
//
// 参数：host 为 hostOnly 的结果
//
// 返回：允许则 true
//
// 注意：只有「未命中 + 监听通配 + host 是 IP 字面量」三条同时成立时才会重新枚举
// 网卡。**域名一律不触发枚举**——域名不可能等于本机网卡 IP，为它付 syscall 代价
// 毫无收益，而且那会让攻击者用随机域名刷出无限次 InterfaceAddrs 调用。
func (a *hostAllowlist) allow(host string) bool {
	h := strings.ToLower(host)
	a.mu.RLock()
	_, ok := a.set[h]
	a.mu.RUnlock()
	if ok {
		return true
	}
	if !a.wildcard || net.ParseIP(h) == nil {
		return false
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	if _, ok := a.set[h]; ok {
		return true
	}
	now := time.Now()
	if now.Before(a.nextScan) {
		return false
	}
	a.nextScan = now.Add(nicRefreshGap)
	added := 0
	for _, ip := range localIPsFn() {
		if _, dup := a.set[ip]; !dup {
			a.set[ip] = struct{}{}
			added++
		}
	}
	if added > 0 {

		a.log.Info("监听通配地址，重新枚举本机网卡后补入 Host 白名单",
			"added", added, "probe_host", h)
	}
	_, ok = a.set[h]
	return ok
}

n_agentd_hostOnly.signature:
// hostOnly 取 host:port 中的 host 部分，并去掉 IPv6 字面量的方括号。
//
// 为什么不直接拿 r.Host 比对：端口不是安全边界。同一个 agentd 会被
// 127.0.0.1:7777 与 httptest 的随机端口访问，把端口算进白名单会让全部现有
// 测试与任意换端口的部署一起失效。
func hostOnly(hostport string) string {
	if h, _, err := net.SplitHostPort(hostport); err == nil {
		return strings.Trim(h, "[]")
	}
	return strings.Trim(hostport, "[]")
}

n_agentd_identityFrom.signature:
// identityFrom 取出本次请求的身份；未经 auth 中间件的请求返回零值（=主令牌身份）。
//
// 注意：零值与「主令牌身份」不可区分是有意的——本函数的全部调用点都在 auth
// 中间件之内，不存在「没经过鉴权却调用它」的路径
func identityFrom(ctx context.Context) identity {
	id, _ := ctx.Value(identityKey{}).(identity)
	return id
}

n_agentd_isForwarded.signature:
// isForwarded 报告该请求是否已经是别的 agentd 转过来的。
//
// 带此头的请求**永不再向外扇出**（scope=all 降级为仅本机、?machine= 忽略）。
func isForwarded(r *http.Request) bool	{ return r.Header.Get(forwardedHeader) != "" }

n_agentd_isLocalMachine.signature:
// isLocalMachine 统一本机 carrier 的登记写法；其他值必须走 target 池，
// 从而检测状态仍只落在协调机 registry。词表与 PutCarrier 同源。
func isLocalMachine(machine string) bool {
	return scheduling.IsLocalMachine(machine)
}

n_agentd_isLocalMachineName.signature:
func isLocalMachineName(name string) bool {
	if name == "" || name == "本机" {
		return true
	}
	host, err := os.Hostname()
	return err == nil && name == host
}

n_agentd_isLoopbackAddr.signature:
// isLoopbackAddr 判断 RemoteAddr（"host:port"）是否来自回环。
//
// 为什么需要这一层：Host 白名单**不止回环**（回环三件套 + cfg.Listen 的 host +
// cfg.Web.AllowedHosts + 通配监听时本机网卡的非回环 IP，见 B104），所以
// 「请求没带 machine」**不等于**「人坐在这台机器前」。判不出来时返回 false
// （拒绝），不放行——放行的代价是在别人机器上弹窗，拒绝的代价只是一条错误提示。
func isLoopbackAddr(remoteAddr string) bool {
	host, _, err := net.SplitHostPort(remoteAddr)
	if err != nil {
		host = remoteAddr
	}
	ip := net.ParseIP(strings.Trim(host, "[]"))
	return ip != nil && ip.IsLoopback()
}

n_agentd_isSafeShellWord.signature:
// isSafeShellWord 检查字符串是否由合法安全的 shell 字符组成：
// [A-Za-z0-9_+\-.,/:@%]
func isSafeShellWord(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
			c == '_' || c == '+' || c == '-' || c == '.' || c == ',' || c == '/' || c == ':' || c == '@' || c == '%' {
			continue
		}
		return false
	}
	return true
}

n_agentd_isWildcardListen.signature:
// isWildcardListen 判断监听地址是不是「全网卡」。
//
// 参数：listen 为 cfg.Listen 原文（可能是 ":7777" / "0.0.0.0:7777" / "0.0.0:7777"）
//
// 注意：空 host 也算通配——`:7777` 与 `0.0.0.0:7777` 语义相同。
// `0.0.0` 这种少一段的写法在生产配置里真实出现过（mac-02 的 `listen: 0.0.0:7777`），
// 它被 net 库当成合法 host 解析，所以必须一并认出来，否则这条修复对它无效。
func isWildcardListen(listen string) bool {
	switch strings.ToLower(hostOnly(listen)) {
	case "", "0.0.0.0", "0.0.0", "::", "[::]":
		return true
	}
	return false
}

n_agentd_joinDevice.signature:
// joinDevice 把登记设备名与浏览器名拼成展示名（任一为空时不留多余分隔符）。
func joinDevice(device, browser string) string {
	switch {
	case device == "":
		return browser
	case browser == "":
		return device
	}
	return device + " / " + browser
}

n_agentd_latestResp.signature:
