n_agentd_ledgerNodeWire.signature:
func ledgerNodeWire(node ledger.NodeDef) proto.NodeDef {
	// 详情 GET 的账本到 proto 投影必须保留 Purpose；同时显式投影指针，
	// 保留旧节点字段缺失与新节点显式对象之间的区别。
	var produces *proto.NodeOutput
	if node.Produces != nil {
		produces = &proto.NodeOutput{
			Kind:	node.Produces.Kind,
			Path:	node.Produces.Path,
		}
	}
	return proto.NodeDef{
		Name:	node.Name, Template: node.Template,
		Override: proto.NodeOverride{
			Executor:	node.Override.Executor, Discipline: node.Override.Discipline,
			Target:	node.Override.Target, Model: node.Override.Model,
			Squad:	node.Override.Squad, Purpose: node.Override.Purpose,
		},
		Dispatch:	node.Dispatch, Verdict: node.Verdict, CarryCardContext: node.CarryCardContext,
		MaxRounds:	node.MaxRounds, OmitAcceptance: node.OmitAcceptance, Next: node.Next, OnFail: node.OnFail,
		Gate: proto.Gate{
			RequireAttachment:	node.Gate.RequireAttachment,
			RequireAttachmentAny:	node.Gate.RequireAttachmentAny,
			RequireAcceptance:	node.Gate.RequireAcceptance,
			RequireChildrenDone:	node.Gate.RequireChildrenDone,
		},
		HumanBases:	node.HumanBases,
		Produces:	produces,
	}
}

n_agentd_legacyDisciplineFilePath.signature:
// legacyDisciplineFilePath 换算机器级映射指向的旧文件路径（只读校验用）。
//
// 为什么它还活着：PUT /api/discipline/mapping 的保存语义**不动**（B229 契约 §2.7，
// ③层映射 Out of Scope），file 档仍要求目标文件此刻可读——这是既有行为，不是新
// 解析入口。目录布局知识内联于此并注明来历，避免误以为它可复用。
func legacyDisciplineFilePath(dataDir, name string) string {
	return filepath.Join(dataDir, "discipline", name)
}

n_agentd_localIPs.signature:
// localIPs 枚举本机所有网卡上的非回环单播地址。
//
// 返回：地址的字符串形式（IPv6 不带方括号也不带 zone）；枚举失败时返回 nil
//
// 为什么剔除 **IPv6 链路本地**（fe80::/10）：它们作为 Host **根本用不了**——
// 访问 fe80 地址必须带 zone（`fe80::1%en0`），而 `net.IP.String()` 不带 zone，
// 存进白名单的是一个永远不会被任何请求命中的字符串。真机实测一台 Mac 上有
// **20 条** fe80 地址，把启动日志那行白名单撑到没法读——而那行正是排查跨机
// 403 的第一现场。剔除它们不损失任何可达性。
//
// IPv4 链路本地（169.254/16）保留：它不需要 zone，用它访问本机是正当的。
//
// 为什么不进一步只留「公网/内网可路由」的：那要引入一套子网判断，而多留几条
// 本机自己的地址并不扩大攻击面——见 allowedHosts 的安全论证。
func localIPs() []string {
	addrs, err := net.InterfaceAddrs()
	if err != nil {
		return nil
	}
	out := make([]string, 0, len(addrs))
	for _, a := range addrs {
		ipnet, ok := a.(*net.IPNet)
		if !ok || ipnet.IP == nil || ipnet.IP.IsLoopback() {
			continue
		}
		if ipnet.IP.To4() == nil && ipnet.IP.IsLinkLocalUnicast() {
			continue
		}
		out = append(out, strings.ToLower(ipnet.IP.String()))
	}
	return out
}

n_agentd_machineUpgradeStatusCode.signature:
// machineUpgradeStatusCode 是端点的五种 HTTP 结论映射。
func machineUpgradeStatusCode(result upgrade.Result) int {
	switch result.Verdict {
	case upgrade.VerdictUnreachable:
		return http.StatusBadGateway
	case upgrade.VerdictUnmanaged, upgrade.VerdictTooOld, upgrade.VerdictManagedUnknown:
		return http.StatusUnprocessableEntity
	case upgrade.VerdictLatest:
		return http.StatusOK
	case upgrade.VerdictNeedsUpgrade:
		if result.Status == upgrade.StatusSkip {
			return http.StatusConflict
		}
		return http.StatusAccepted
	default:
		return http.StatusUnprocessableEntity
	}
}

