n_agentd_newSPAHandler.signature:
// newSPAHandler 返回伺服单页应用的 handler。
//
// 参数：
//   - fsys: 静态资源根文件系统，index.html 必须位于根。通常来自 webui.FS()。
//   - log:  日志器，用于记录回落与异常。不可为 nil。
//
// 行为：
//   - GET/HEAD 命中真实文件 → 200 + 文件内容 + 按 hash 决定的缓存头
//   - GET/HEAD 未命中 → 200 + index.html + no-cache（客户端路由接管）
//   - 其它方法 → 405
//   - index.html 本身缺失 → 500
//
// 注意：本 handler 假定调用方已保证 /api、/ws、/console 不会落到这里。
func newSPAHandler(fsys fs.FS, log *slog.Logger) http.Handler {
	fileServer := http.FileServerFS(fsys)

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {

			log.Warn("SPA handler 收到非读请求，已拒绝",
				"method", r.Method, "path", r.URL.Path, "remote_addr", r.RemoteAddr)
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
			return
		}

		name := strings.TrimPrefix(path.Clean(r.URL.Path), "/")
		if name == "" || name == "." {
			serveIndex(w, r, fsys, log)
			return
		}

		if !fs.ValidPath(name) {
			log.Debug("SPA 收到非法路径，按未命中处理", "path", r.URL.Path)
			serveIndex(w, r, fsys, log)
			return
		}

		info, err := fs.Stat(fsys, name)
		if err != nil || info.IsDir() {

			log.Debug("SPA 未命中静态文件，回落 index.html", "path", r.URL.Path)
			serveIndex(w, r, fsys, log)
			return
		}

		if hashedAsset.MatchString(name) {
			w.Header().Set("Cache-Control", cacheImmutable)
		} else {
			w.Header().Set("Cache-Control", cacheNone)
		}
		fileServer.ServeHTTP(w, r)
	})
}

n_agentd_normalizeAddr.signature:
// normalizeAddr 给缺 scheme 的地址补 http://，与 client.New 的行为一致。
//
// 为什么不直接复用 client 里的那份：那是包内私有的，且这里只需要这三行。
// 若将来 client 导出了它，换过来即可。
func normalizeAddr(addr string) string {
	if !strings.Contains(addr, "://") {
		return "http://" + addr
	}
	return addr
}

n_agentd_normalizeCoordinatorSpec.signature:
// normalizeCoordinatorSpec 将 SessionSpec.HomeDir 展开为绝对路径。
// 空值视为主 HOME（~）展开；展开失败或非绝对路径返回包含原串的错误，防止字面 ~ 漏进 keystone。
func normalizeCoordinatorSpec(spec keysclient.SessionSpec) (keysclient.SessionSpec, error) {
	home := spec.HomeDir
	if strings.TrimSpace(home) == "" {
		home = "~"
	}
	expanded, err := hostapi.ExpandHomePath(home)
	if err != nil {
		return spec, fmt.Errorf("展开协调者 HOME %q: %w", home, err)
	}
	if !filepath.IsAbs(expanded) {
		return spec, fmt.Errorf("协调者 HOME 不是绝对路径: %q", expanded)
	}
	spec.HomeDir = expanded
	return spec, nil
}

n_agentd_openDownloadedFile.signature:
// openDownloadedFile 按当前平台唤起文件管理器。
//
// 参数：path 是已落盘的绝对路径。
// 返回：只有子进程无法启动时返回错误；Start 成功后由后台 goroutine Wait 收尸，
// 防止长驻 agentd 每次下载都积累僵尸子进程。Windows explorer 的退出码不参与判断，
// 因为它天生可能用非零码结束。
func openDownloadedFile(path string) error {
	var cmd *exec.Cmd
	switch runtime.GOOS {
	case "darwin":
		cmd = exec.Command("open", path)
	case "windows":
		cmd = exec.Command("explorer", "/select,"+path)
	default:
		cmd = exec.Command("xdg-open", filepath.Dir(path))
	}
	if err := cmd.Start(); err != nil {
		return err
	}

	go func() { _ = cmd.Wait() }()
	return nil
}

n_agentd_parseForce.signature:
// parseForce 解析 resume 的 force 查询参数。
//
// 为什么自己解析而不用 strconv.ParseBool 的错误：非法值（如 force=yes）一律
// 按 false 处理——强制收口是绕过正常流程的动作，看不懂的输入必须走保守的那边。
func parseForce(r *http.Request) bool {
	switch r.URL.Query().Get("force") {
	case "true", "1":
		return true
	}
	return false
}

n_agentd_pinGrokOsc52Sink.signature:
// pinGrokOsc52Sink 把 GROK_OSC52_SINK=1 钉进会话环境。
//
// 先剥掉同名键再放在末尾：execve/getenv 取首次出现，只 append 挡不住
// sessionEnv 继承或 env_file 写在前面的 0/空。B303 写死，文件不能关。
func pinGrokOsc52Sink(env []string) []string {
	out := make([]string, 0, len(env)+1)
	for _, e := range env {
		if strings.HasPrefix(e, "GROK_OSC52_SINK=") {
			continue
		}
		out = append(out, e)
	}
	return append(out, grokOsc52SinkEnv)
}

n_agentd_pipeSOCKS.signature:
func pipeSOCKS(client, upstream net.Conn) {
	result := make(chan struct{}, 2)
	go func() { _, _ = io.Copy(upstream, client); result <- struct{}{} }()
	go func() { _, _ = io.Copy(client, upstream); result <- struct{}{} }()
	<-result
}

n_agentd_pipeWS.signature:
// pipeWS 把 src 的每一帧原样写进 dst，**保持帧类型**。
//
// 帧类型必须保持：数据走 binary、控制走 text 是 /ws/pty 的契约（spec §5.3），
// 反代若把一切都当 text 转发，二进制里任何非 UTF-8 字节都会被判为协议错误。
func pipeWS(ctx context.Context, src, dst *websocket.Conn) error {
	for {
		typ, data, err := src.Read(ctx)
		if err != nil {
			return err
		}
		if err := dst.Write(ctx, typ, data); err != nil {
			return err
		}
	}
}

n_agentd_previewBrowserCandidates.signature:
func previewBrowserCandidates() []string {
	candidates := []string{
		"google-chrome",
		"google-chrome-stable",
