n_agentd_pullTracker_begin.signature:
// begin 尝试开始一次自拉。
//
// 返回：
//   - true 表示抢到了，调用方可以起后台 goroutine；false 表示已有一个在跑，
//     调用方应当回 409 + proto.UpdateReasonPullInProgress
//
// 注意：
//   - 抢到锁的一方**必须**最终调用 fail 或让进程重启，否则锁永不释放。
//     成功路径不需要显式释放：换版成功即触发重启，进程整个换掉
func (p *pullTracker) begin(tag string) bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.running {
		return false
	}
	now := time.Now()
	p.running = true
	p.st = &proto.PullState{
		Tag:	tag, Stage: proto.PullStageDownloading,
		StartedAt:	now, UpdatedAt: now,
	}
	return true
}

n_agentd_pullTracker_busy.signature:
// busy 报告是否有一个自拉正在推进。
func (p *pullTracker) busy() bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	return p.running
}

n_agentd_pullTracker_fail.signature:
// fail 记录失败并释放锁。
//
// 注意：
//   - 失败状态**保留**在内存里（不清空 st）：进程不会重启，操作者要靠
//     /api/status 拿到这条原文才知道该改代理还是改网络
func (p *pullTracker) fail(err error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.running = false
	if p.st == nil {
		return
	}
	p.st.Stage = proto.PullStageFailed
	p.st.Error = err.Error()
	p.st.UpdatedAt = time.Now()
}

n_agentd_pullTracker_snapshot.signature:
// snapshot 返回状态副本，供 status 装配。没跑过时返回 nil。
//
// 返回副本而不是内部指针：status 的装配与后台 goroutine 的阶段推进并发，
// 直接外露指针会让 json.Marshal 撞上数据竞争。
func (p *pullTracker) snapshot() *proto.PullState {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.st == nil {
		return nil
	}
	cp := *p.st
	return &cp
}

n_agentd_pullTracker_stage.signature:
// stage 推进阶段。没有进行中的自拉时是空操作。
func (p *pullTracker) stage(s string) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.st == nil {
		return
	}
	p.st.Stage = s
	p.st.UpdatedAt = time.Now()
}

n_agentd_queueEntryView.signature:
// queueEntryView 把队列快照行投影成 wire DTO。Kind/ID/Seq/Position 来自快照
// 元数据，其余九个字段逐一来自入队时刻的 IgnitionRequest 快照。
func queueEntryView(row scheduling.QueuedRequest) proto.QueueEntry {
	return proto.QueueEntry{
		Kind:	row.Kind, ID: row.ID,
		Card:	row.Req.Card, Node: row.Req.Node, Squad: row.Req.Squad,
		Target:	row.Req.Target, Executor: row.Req.Executor, Model: row.Req.Model,
		Priority:	row.Req.Priority, Ready: row.Req.Ready, Actor: row.Req.Actor,
		Seq:	row.Seq, Position: row.Position,
	}
}

n_agentd_randCredential.signature:
// randCredential 生成 256 位随机凭据明文（ticket 与会话 cookie 共用）。
//
// 返回：
//   - 64 字符十六进制串
//   - crypto/rand 读取失败时返回错误（不 panic：这是一条 HTTP 路径，
//     500 比让整个 agentd 崩掉合理）
func randCredential() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("生成随机凭据: %w", err)
	}
	return hex.EncodeToString(b), nil
}

n_agentd_readFrom.signature:
// readFrom 读出 path 从 offset 起的全部剩余内容。
//
// 文件不存在返回 (nil, nil)：follow 模式下这是「还没开始产出」的正常状态
// （与 copyFrom 同一处置，只是这里要拿到字节而不是直接搬运）。
func readFrom(path string, offset int64) ([]byte, error) {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	defer f.Close()
	if _, err := f.Seek(offset, io.SeekStart); err != nil {
		return nil, err
	}
	return io.ReadAll(f)
}

n_agentd_readSOCKSRequest.signature:
func readSOCKSRequest(conn net.Conn) (string, uint16, error) {
	var header [4]byte
	if _, err := io.ReadFull(conn, header[:]); err != nil {
		return "", 0, err
	}
	if header[0] != 5 || header[1] != 1 {
		return "", 0, fmt.Errorf("SOCKS request version/cmd=%d/%d", header[0], header[1])
	}
	var host string
	switch header[3] {
	case 1:
		ip := make([]byte, net.IPv4len)
		if _, err := io.ReadFull(conn, ip); err != nil {
			return "", 0, err
		}
		host = net.IP(ip).String()
	case 3:
		var length [1]byte
		if _, err := io.ReadFull(conn, length[:]); err != nil {
			return "", 0, err
		}
		name := make([]byte, int(length[0]))
		if _, err := io.ReadFull(conn, name); err != nil {
			return "", 0, err
		}
		host = string(name)
	case 4:
		ip := make([]byte, net.IPv6len)
		if _, err := io.ReadFull(conn, ip); err != nil {
			return "", 0, err
		}
		host = net.IP(ip).String()
	default:
		return "", 0, fmt.Errorf("未知 SOCKS address type=%d", header[3])
	}
	var port [2]byte
	if _, err := io.ReadFull(conn, port[:]); err != nil {
		return "", 0, err
	}
	return host, binary.BigEndian.Uint16(port[:]), nil
}

n_agentd_reconcileSchedRunning.signature:
// reconcileSchedRunning 是启动对账，对共享 sched_running **只读不写**。
//
// 为什么不清零：sched_running 在共享账本上跨机可见。本机 ListTasks 看不到 owner
// 不等于集群里没有占用者（他机执行、没有 Task 的 LaunchAdmit 会话都在同一把键上
// 计数）。以「本机无非终态 owner」或「本机对应任务已终态」为由把共享计数写成 0，
// 会跨机误伤别人的占用。本机 pending/running/waiting_review owner 本就不该被改写，
// 一并原样保留。
//
// 仍保留解码校验：损坏记录在启动时带 key/version 暴露并阻断后续 executor 恢复，
// 而不是被悄悄清零或跳过。对账本身不再产生任何写者。
func reconcileSchedRunning(st *store.Store, repo schedclient.Registry, log *slog.Logger) error {
	tasks, err := st.ListTasks()
	if err != nil {
		log.Error("启动对账读取任务列表失败", "error_kind", "task_list", "cause", err)
		return fmt.Errorf("启动对账读取任务列表: %w", err)
	}
	owned := make(map[string]struct{})
	for _, task := range tasks {
		if task.State.IsTerminal() || task.Carrier == "" {
			continue
		}
		owned[scheduling.OccupancyCarrierKey(task.Carrier)] = struct{}{}
		if task.Squad != "" {
			owned[scheduling.OccupancyMemberKey(task.Squad, task.Carrier)] = struct{}{}
		}
	}
	rows, err := repo.List(schedRunningKind)
	if err != nil {
		log.Error("启动对账读取 sched_running 失败", "error_kind", "running_list", "cause", err)
		return fmt.Errorf("启动对账读取 sched_running: %w", err)
	}
	foreignPreserved := 0
	for _, row := range rows {
		var body schedRunningBody
		if err := json.Unmarshal(row.Body, &body); err != nil {
			log.Error("启动对账解码运行计数失败", "key", row.ID, "version", row.Version,
				"count", body.Count, "error_kind", "decode", "cause", err)
			return fmt.Errorf("启动对账解码 %s: %w", row.ID, err)
		}
		if body.Count <= 0 {
			log.Info("启动对账跳过非正运行计数", "key", row.ID, "version", row.Version,
				"count", body.Count, "error_kind", "non_positive")
			continue
		}
		if _, ok := owned[row.ID]; ok {
			log.Info("启动对账保留本机任务所有的运行计数", "key", row.ID, "count", body.Count,
				"version", row.Version, "error_kind", "owned")
			continue
		}
		foreignPreserved++
		log.Info("启动对账保留无本机 owner 的运行计数（跨机占用不得清零）", "key", row.ID,
			"count", body.Count, "version", row.Version, "error_kind", "foreign_preserved")
	}
	log.Info("启动调度占用对账完成（只读，不清零）", "task_count", len(tasks),
		"record_count", len(rows), "owned_count", len(owned), "foreign_preserved", foreignPreserved)
	return nil
}

n_agentd_recoverTransit.signature:
// recoverTransit 把恢复失败的任务迁移到 waiting_review。
//
// why（两跳）：状态机只有 6 状态，迁移表中 waiting_answer 只允许去 running/failed，
// 直接迁 waiting_review 会被 ErrBadTransit 拒绝；经 running 中转的两跳
// （waiting_answer→running→waiting_review）均合法，与 manager.transitToReviewRetry
// 的竞态兜底路径同构。running 任务则直跳。首跳失败（ErrBadTransit）时继续尝试
// 第二跳：失败意味着状态已被并发变更，以最新快照为准补跳即可收敛。
func recoverTransit(st *store.Store, taskID string, cur proto.TaskState) error {
	if cur == proto.TaskStateWaitingAnswer {
		if err := st.UpdateTaskState(taskID, proto.TaskStateRunning); err != nil && !errors.Is(err, store.ErrBadTransit) {
			return err
		}
	}
	return st.UpdateTaskState(taskID, proto.TaskStateWaitingReview)
}

n_agentd_rejectCoordinatorHomeSymlinks.signature:
// rejectCoordinatorHomeSymlinks 只检查隔离 HOME 根和供给白名单中的路径。
// 不向上遍历文件系统祖先：那会把主机卷别名或其他无关路径误当成隔离 HOME 的风险，
// 而真正需要防护的是即将被 MkdirAll/WriteFile 使用的白名单路径不能跟随链接越界。
func rejectCoordinatorHomeSymlinks(targetHome string) error {
	paths := []string{
		targetHome,
		filepath.Join(targetHome, ".handoff"),
		filepath.Join(targetHome, ".handoff", "config.yaml"),
		filepath.Join(targetHome, ".config"),
		filepath.Join(targetHome, ".config", "opencode"),
		filepath.Join(targetHome, ".config", "opencode", "AGENTS.md"),
		filepath.Join(targetHome, ".config", "opencode", "skills"),
		filepath.Join(targetHome, ".local"),
		filepath.Join(targetHome, ".local", "share"),
		filepath.Join(targetHome, ".local", "share", "opencode"),
		filepath.Join(targetHome, ".local", "share", "opencode", "auth.json"),
		filepath.Join(targetHome, ".grok"),
		filepath.Join(targetHome, ".grok", "auth.json"),
		filepath.Join(targetHome, ".codex"),
		filepath.Join(targetHome, ".codex", "auth.json"),
	}
	for _, path := range paths {
		info, err := os.Lstat(path)
		switch {
		case errors.Is(err, os.ErrNotExist):
			continue
		case err != nil:
			return fmt.Errorf("检查协调者隔离 HOME 白名单路径 %q: %w", path, err)
		case info.Mode()&os.ModeSymlink != 0:
			return fmt.Errorf("协调者隔离 HOME 白名单路径是 symlink %q", path)
		}
	}
	return nil
}

n_agentd_renderSize.signature:
// renderSize 返回 render.log 当前字节数；文件不存在时返回 0（见 handleTaskRender 的注意）。
func renderSize(path string) int64 {
	fi, err := os.Stat(path)
	if err != nil {
		return 0
	}
	return fi.Size()
}

n_agentd_renderStartOffset.signature:
// renderStartOffset 依据 offset/tail 参数算出起始偏移。
//
// 优先级：显式 offset > tail > renderDefaultTail。
// offset 超过当前大小时钳到大小（不报错：文件可能刚被归档重建，钳住即可继续 follow）。
func renderStartOffset(r *http.Request, size int64) (int64, error) {
	q := r.URL.Query()
	if v := q.Get("offset"); v != "" {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n < 0 {
			return 0, fmt.Errorf("offset 非法: %q", v)
		}
		if n > size {
			return size, nil
		}
		return n, nil
	}
	back := int64(renderDefaultTail)
	if v := q.Get("tail"); v != "" {
		n, err := strconv.ParseInt(v, 10, 64)
		if err != nil || n < 0 {
			return 0, fmt.Errorf("tail 非法: %q", v)
		}
		back = n
	}
	if size <= back {
		return 0, nil
	}
	return size - back, nil
}

n_agentd_requiresInlineLocalFile.signature:
// requiresInlineLocalFile 判断一次 step 请求是否要求把调用方 CWD 的本地文件
// 内联发送给 agentd。
//
// 今天恒为 false 是有意的：CardStepReq 没有 PlanPath 或本地文件字段，StepRunner
// 也没有 PlanPath；PlanPath 只由不带 --step 的 CLI TemplateDispatch 在调用方 CWD 读取。
// 如果未来增加本地文件字段，必须先改冻结契约并把拒绝测试落在同一条 wire 上。
func requiresInlineLocalFile(req proto.CardStepReq) bool {
	return false
}

n_agentd_resolvedExecutable.signature:
// resolvedExecutable 返回当前二进制的真实路径。
//
// 必须 EvalSymlinks：装在 ~/.local/bin 的二进制常常是个 symlink，
// 替换 symlink 本身只会把链接换成普通文件，链接目标仍是旧版。
// 与 cmd/agentd.go 的同名函数分属两包，互不冲突。
func resolvedExecutable() (string, error) {
	exe, err := os.Executable()
	if err != nil {
		return "", err
	}
	if resolved, err := filepath.EvalSymlinks(exe); err == nil {
		return resolved, nil
	}
	return exe, nil
}

n_agentd_resumeTurnRequest.signature:
// resumeTurnRequest 把 SessionRef 上的续接环境映射进 RunTurn。HOME 空时
// 子进程继承 agentd 默认 HOME，隔离会话必然找不到——调用方必须带上。
func resumeTurnRequest(ref keysclient.SessionRef, prompt string) hostapi.TurnRequest {
	if ref.HomeDir == "" {
		slog.Default().Warn("协调者续接未带隔离 HOME，将继承 agentd 默认 HOME",
			"component", "agentd", "has_cli", ref.CLI != "", "has_session", ref.SessionID != "")
	}
	return hostapi.TurnRequest{
		CLI:	ref.CLI, SessionID: ref.SessionID, Prompt: prompt,
		HomeDir:	ref.HomeDir, Workdir: ref.Workdir, Model: ref.Model,
		Env: []string{
			"HANDOFF_SESSION_CLI=" + ref.CLI,
			"HANDOFF_SESSION_ID=" + ref.SessionID,
		},
	}
}

n_agentd_revealTarget.signature:
// revealTarget 把 rel 解析成一个可以交给 open 的绝对路径，并确认它没跑出工作树。
//
// 返回：解析后的绝对路径；越界或不存在时返回错误。
//
// 为什么这里用 EvalSymlinks 而不是 B107 §3.2 规定的 os.OpenRoot：
// os.Root 的产物是 **jail 内的 fd**，而这里要的是一个**交给外部进程的路径字符串**
// （`open -R /dev/fd/N` 没有意义）。所以红线在这里不适用——**这不是遗漏**。
//
// 代价是校验后、open 前存在残留 TOCTOU 窗口。可接受的依据只有这三条：
//  1. 动作是 reveal-only：不执行、不改写、不读内容，上限是「Finder 选中了另一个文件」
//  2. 利用它要先能在工作树内写符号链接，而有这能力的调用方本来就有 PTY 全权 shell
//  3. 后果发生在用户自己看得见的桌面上，不是一条静默通道
//
// **不要把这条让步反向套回 B107**：那边的动作是 RemoveAll/Rename，上限是静默
// 删掉仓库外的文件，两者不在同一个量级。
func revealTarget(root, rel string) (string, error) {
	realRoot, err := filepath.EvalSymlinks(root)
	if err != nil {
		return "", err
	}
	abs, err := filepath.EvalSymlinks(filepath.Join(realRoot, filepath.Clean(rel)))
	if err != nil {
		return "", err
	}
	if abs != realRoot && !strings.HasPrefix(abs, realRoot+string(filepath.Separator)) {
		return "", errors.New("路径逃逸被拒绝")
	}
	return abs, nil
}

n_agentd_roomAttachCacheKey.signature:
func roomAttachCacheKey(link ledger.TaskLink) string {
	return link.Target + "\x00" + link.TaskID
}

n_agentd_runWatchdog.signature:
// runWatchdog 是看门狗的实现骨架：tick 间隔可注入（生产固定一分钟，
// 测试注入 10ms），其余语义与 RunWatchdog 一致。
func runWatchdog(ctx context.Context, st *store.Store, hub *Hub, stallTimeout time.Duration, tick time.Duration, budget, hardLimit int, reclaim func(taskID, reason string) error, startedAt time.Time, minAge time.Duration, transit stateMismatchTransit, log *slog.Logger) {
	ticker := time.NewTicker(tick)
	defer ticker.Stop()
	log.Info("看门狗启动", "tick", tick, "stall_timeout", stallTimeout)
	pressure := false

	taskFired := map[string]bool{}
	taskReclaimFailed := map[string]bool{}
	for {
		select {
		case <-ctx.Done():
			log.Info("看门狗退出", "cause", ctx.Err())
			return
		case <-ticker.C:
			scanStalled(st, hub, stallTimeout, log)
			scanStateMismatch(st, hub, startedAt, minAge, transit, log)
			pressure = scanPressure(st, hub, pressure, log)
			scanTaskProcs(st, hub, budget, hardLimit, taskFired, taskReclaimFailed, reclaim, log)
		}
	}
}

n_agentd_sanitizeDeviceName.signature:
// sanitizeDeviceName 净化设备名：剥掉控制字符并按 rune 截断。
//
// 参数：
//   - s: 客户端提供的原始设备名（来自 --device 或 User-Agent）
//
// 返回：
//   - 可安全写入库、可安全打印到终端的展示名
//
// 注意：
//   - 设备名**纯展示，不参与任何鉴权判断**，但它来自客户端——一个构造过的
//     User-Agent 能往终端里注入 ANSI 转义序列，因此必须在入库这道边界剥掉
func sanitizeDeviceName(s string) string {
	cleaned := strings.Map(func(r rune) rune {
		if r == '\t' || unicode.IsControl(r) {
			return -1
		}
		return r
	}, s)
	rs := []rune(strings.TrimSpace(cleaned))
	if len(rs) > deviceNameMaxRunes {
		rs = rs[:deviceNameMaxRunes]
	}
	return string(rs)
}

n_agentd_scanPressure.signature:
// scanPressure 判读一次进程余量，越线沿时给每个活跃任务发一条高水位事件。
//
// 参数：
//   - active: 上一轮的置位状态（越线后为 true）
//   - 其余同 scanStalled
//
// 返回：本轮结束后的置位状态，由调用方持有并回传——**不用包级变量**，
// 那会让两个 agentd 实例（测试里常见）互相踩状态。
//
// 三条语义：
//   - 越线（!active && NearFull）：对每个活跃任务发一次，置位
//   - 已置位且仍在高水位：不重发。事件风暴会把协调者的会话刷爆，
//     反而淹掉真正要处置的工单
//   - 回落到水位线以下：复位，下次越线可再发
//
// 读数未知时**原样返回 active，什么都不做**：把「量不出来」当成「回落了」，
// 会让下一次真越线因为状态错乱而漏报——漏报一次高水位，就等于回到事故当天
// 那个「第一个信号是整机瘫痪」的处境。
func scanPressure(st *store.Store, hub *Hub, active bool, log *slog.Logger) bool {
	a := admissionFn()
	if !a.Known {
		log.Debug("进程余量未知，跳过高水位判读")
		return active
	}
	if !a.NearFull() {
		if active {
			log.Info("进程余量已回落到水位线以下", "used", a.Used, "limit", a.Limit)
		}
		return false
	}
	if active {
		return true
	}
	tasks, err := st.ListTasks()
	if err != nil {
		log.Error("高水位告警读取任务列表失败", "cause", err)
		return false
	}
	fired := 0
	for _, t := range tasks {

		if t.State.IsTerminal() {
			continue
		}
		evt, aerr := st.AppendEvent(t.ID, proto.EventTypeResourcePressure,
			resourcePressurePayload{Used: a.Used, Limit: a.Limit})
		if aerr != nil {
			log.Error("追加高水位事件失败", "task", t.ID, "cause", aerr)
			continue
		}
		hub.Publish(evt)
		fired++
	}
	log.Warn("执行机进程余量达高水位，已告警活跃任务",
		"used", a.Used, "limit", a.Limit, "fired", fired)
	return true
}

n_agentd_scanStalled.signature:
// scanStalled 扫描一轮：对 running/waiting_answer 任务判定是否卡住并触发 stalled。
//
// 为什么只扫 running/waiting_answer：pending 尚在启动中（无事件正常）、
// waiting_review 卡住说明协调者还没处理（那是人的节奏，不归看门狗）、
// completed/failed 已终结；只有「executor 应该在干活」的状态才是卡住判定对象。
// waiting_answer 卡住正是「审批挂起过夜」场景——executor 等协调者答复等太久，
// 值得再发一条 stalled 把协调者拽回来。
//
// 活动基线（P1-15 重新设计）：
//   - 最新事件时间；零事件任务（建好后从未产出事件，即「静默挂起」）以
//     task.UpdatedAt 兜底——没有任何事件可锚，任务行是仅有的活动痕迹
//   - 每次触发后以「新 stalled 事件成为最新事件」自然重置基线，无内存记忆
//
// 「只发一次」裁决（P1-15a 重新设计）：最新事件已是 stalled 时，仅当任务在
// 该 stalled 之后出现过活动（task.UpdatedAt 前进）才允许重发。为什么以
// UpdatedAt 变化为二次触发的准绳：reply 回程的 AnswerTicket 会刷新任务的
// updated_at（见 store.AnswerTicket），resumeIfIdle 回迁 running 也会刷新——
// 正是「已 stalled → 协调者回答 → executor 仍然死着」这个最需要二次告警的
// 场景（旧实现永远不再告警）；而普通无活动状态下 updated_at 停在 stalled
// 事件之前，每轮扫描照旧跳过，不产生事件风暴。新 stalled 事件落库时间晚于
// 当时 updated_at，下一轮自然回到「不重发」分支。
//
// 每轮扫描独立执行，与其他轮之间无共享状态：两种裁决都只依赖持久化事实
// （最新事件 + task.UpdatedAt），重启后语义依然正确。
func scanStalled(st *store.Store, hub *Hub, stallTimeout time.Duration, log *slog.Logger) {
	tasks, err := st.ListTasks()
	if err != nil {
		log.Error("看门狗扫描任务列表失败", "cause", err)
		return
	}
	checked, fired := 0, 0
	for _, t := range tasks {
		if t.State != proto.TaskStateRunning && t.State != proto.TaskStateWaitingAnswer {
			continue
		}
		checked++
		last, err := st.LatestEvent(t.ID)
		var (
			lastEv		*proto.Event	// 最新事件；零事件任务为 nil
			baseline	time.Time	// 空闲判定的活动基线
		)
		switch {
		case errors.Is(err, store.ErrNotFound):

			baseline = t.UpdatedAt
		case err != nil:
			log.Error("看门狗读取任务最新事件失败", "task", t.ID, "cause", err)
			continue
		default:
			lastEv = last
			baseline = last.CreatedAt
		}
		idle := time.Since(baseline)
		if idle < stallTimeout {
			continue
		}
		if lastEv != nil && lastEv.Type == proto.EventTypeStalled && !t.UpdatedAt.After(lastEv.CreatedAt) {

			continue
		}
		lastSeq := int64(0)
		if lastEv != nil {
			lastSeq = lastEv.Seq
		}
		evt, err := st.AppendEvent(t.ID, proto.EventTypeStalled, stalledPayload{
			LastSeq:	lastSeq, Idle: idle.Round(time.Second).String(),
		})
		if err != nil {
			log.Error("追加 stalled 事件失败", "task", t.ID, "cause", err)
			continue
		}
		hub.Publish(evt)
		fired++
		log.Warn("任务卡住，触发 stalled 事件", "task", t.ID,
			"idle", idle.Round(time.Second).String(), "last_seq", lastSeq)
	}
	log.Debug("看门狗扫描完成", "checked", checked, "fired", fired)
}

n_agentd_scanStateMismatch.signature:
// scanStateMismatch 扫描一轮失配任务：最新事件是 failed、状态却非终态（判据见
// mismatchVerdict，三条护栏缺一不可），则经 transit 回调把状态补成 failed。
//
// 为什么必须复用 transit 而不裸调 UpdateTaskState：终态迁移的挂起工单作废与审计留痕
// （B63）挂在 Manager.transit 上，绕过它就只改了状态、留下一堆永远不会被回答的工单。
// 迁移失败只记 Error 不重试——下一轮 tick 自然再扫。
//
// 不补第二条 failed 事件（会重复），改为追加一条 progress 审计：说明这是对账修的、
// 原始事件的 seq 是多少。状态凭空变了却没有痕迹，比不修更难排查。
//
// 不清扫进程、不杀 executor：那是 SweepTaskProcs 的职责，且能走到这一步说明 executor
// 早已被判死，清扫在别的路径上已经做过。
func scanStateMismatch(st *store.Store, hub *Hub, startedAt time.Time, minAge time.Duration, transit stateMismatchTransit, log *slog.Logger) {
	tasks, err := st.ListTasks()
	if err != nil {
		log.Error("失配对账读取任务列表失败", "cause", err)
		return
	}
	now := time.Now()
	for _, t := range tasks {
		latest, err := st.LatestEvent(t.ID)
		if errors.Is(err, store.ErrNotFound) {
			continue
		}
		if err != nil {
			log.Error("失配对账读取任务最新事件失败", "task", t.ID, "cause", err)
			continue
		}
		if !mismatchVerdict(t.State, latest, now, startedAt, minAge) {
			continue
		}
		age := now.Sub(latest.CreatedAt)

		log.Warn("失配对账：任务最新事件是 failed 但状态非终态，补迁 failed",
			"task", t.ID, "seq", latest.Seq, "state", t.State, "event_age", age.Round(time.Second).String())
		if terr := transit(t.ID, proto.TaskStateFailed, "mismatch-scan"); terr != nil {
			log.Error("失配对账补迁 failed 失败，下一轮再试", "task", t.ID, "cause", terr)
			continue
		}

		evt, aerr := st.AppendEvent(t.ID, proto.EventTypeProgress, ProgressPayload{
			Text: fmt.Sprintf("失配对账：任务状态已补正为 failed（对账前的 failed 事件 seq=%d）", latest.Seq),
		})
		if aerr != nil {
			log.Error("失配对账追加审计事件失败", "task", t.ID, "seq", latest.Seq, "cause", aerr)
			continue
		}
		hub.Publish(evt)
	}
}

n_agentd_scanTaskProcs.signature:
// scanTaskProcs 按任务点名进程数，两档处置。
//
// 参数：
//   - budget: 告警线，<=0 表示该档关闭
//   - hardLimit: 硬上限，<=0 表示该档关闭
//   - fired: 每任务的告警置位状态，由调用方持有并跨轮传递（**不用包级变量**，
//     那会让两个 agentd 实例互相踩状态——沿用 scanPressure 的同一条理由）
//   - reclaimFailed: 每任务的强制回收失败边沿状态，由调用方持有并跨轮传递；
//     与 fired 分开，因为两者的回落判据不同
//   - reclaim: 强制回收入口；返回非 nil 表示 executor 没停掉，此时任务不落终态
//
// 三条语义（与 scanPressure 同构）：
//   - 越线且未置位：发一次 task_proc_pressure 并置位
//   - 仍越线且已置位：不重发。事件风暴会把协调者的会话刷爆
//   - 回落到预算以下：复位，下次越线可再发
//
// 硬上限档是本仓库第一次让 agentd 在无人裁决的情况下杀进程，所以：读数不可信
// 一律什么都不做；理由里必须写上 used 与 hardLimit 两个真实数字，让审核者
// 事后能判断杀得对不对。
func scanTaskProcs(st *store.Store, hub *Hub, budget, hardLimit int,
	fired, reclaimFailed map[string]bool,
	reclaim func(taskID, reason string) error, log *slog.Logger) {

	if budget <= 0 && hardLimit <= 0 {
		return
	}
	if taskProcCountFn == nil {
		return
	}
	tasks, err := st.ListTasks()
	if err != nil {
		log.Error("任务进程点名读取任务列表失败", "cause", err)
		return
	}
	for _, t := range tasks {

		if t.State.IsTerminal() {
			continue
		}
		n, ok := taskProcCountFn(t.ID)
		if !ok {
			continue
		}
		if hardLimit > 0 && n > hardLimit {
			log.Error("任务进程数超过硬上限，强制回收", "task", t.ID, "used", n, "hard_limit", hardLimit)
			reason := fmt.Sprintf("任务进程数 %d 超过硬上限 %d，已强制回收", n, hardLimit)
			if err := reclaim(t.ID, reason); err != nil {

				if !reclaimFailed[t.ID] {
					reclaimFailed[t.ID] = true
					emitReclaimFailed(st, hub, t.ID, n, hardLimit, err, log)
				}
				continue
			}
			delete(fired, t.ID)
			delete(reclaimFailed, t.ID)
			continue
		}
		if budget <= 0 {
			continue
		}
		if n <= budget {
			if fired[t.ID] {
				log.Info("任务进程数已回落到预算以下", "task", t.ID, "used", n, "budget", budget)
			}
			delete(fired, t.ID)
			continue
		}
		if fired[t.ID] {
			continue
		}
		evt, aerr := st.AppendEvent(t.ID, proto.EventTypeTaskProcPressure,
			taskProcPressurePayload{Used: n, Budget: budget})
		if aerr != nil {
			log.Error("追加任务进程越线事件失败", "task", t.ID, "cause", aerr)
			continue
		}

		hub.Publish(evt)
		fired[t.ID] = true
		log.Warn("任务进程数超过预算，已告警", "task", t.ID, "used", n, "budget", budget)
	}
}

n_agentd_securePreviewFileHandler.signature:
func securePreviewFileHandler(root string) http.Handler {
	files := http.FileServer(http.Dir(root))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rel := filepath.FromSlash(strings.TrimPrefix(r.URL.Path, "/"))
		if rel == "" {
			rel = "."
		}
		resolved, err := filepath.EvalSymlinks(filepath.Join(root, rel))
		if err != nil {
			http.NotFound(w, r)
			return
		}
		relRoot, err := filepath.Rel(root, resolved)
		if err != nil || relRoot == ".." || strings.HasPrefix(relRoot, ".."+string(os.PathSeparator)) {
			http.NotFound(w, r)
			return
		}
		files.ServeHTTP(w, r)
	})
}

n_agentd_serveIndex.signature:
// serveIndex 发送 index.html，并显式设置 no-cache。
//
// 为什么 index.html 必须 no-cache：它引用的 JS/CSS 文件名带 hash，换版后
// hash 会变。若 index.html 被缓存，浏览器会拿着旧 index 去请求已经不存在的
// 资源，表现为白屏，且在用户手工清缓存之前无法自愈。
func serveIndex(w http.ResponseWriter, r *http.Request, fsys fs.FS, log *slog.Logger) {
	b, err := fs.ReadFile(fsys, "index.html")
	if err != nil {

		log.Error("控制台 index.html 缺失，这份二进制的前端资源不完整",
			"path", r.URL.Path, "err", err)
		if errors.Is(err, fs.ErrNotExist) {
			http.Error(w, "console assets missing", http.StatusInternalServerError)
			return
		}
		http.Error(w, "console assets unreadable", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", cacheNone)
	w.WriteHeader(http.StatusOK)
	if r.Method == http.MethodHead {
		return
	}
	if _, err := w.Write(b); err != nil {
		log.Debug("写 index.html 响应失败（客户端多半已断开）", "err", err)
	}
}

n_agentd_sessionCookie.signature:
// sessionCookie 构造会话 cookie。下发与删除共用，属性只在这一处定义。
//
// 参数：
//   - r: 仅用于判断是否走 TLS（决定 Secure）
//   - value: cookie 值；删除时传空串
//   - maxAge: 秒；负值表示删除（浏览器立即丢弃）
//
// SameSite 取 Lax 而不是 Strict，这条是承重的：桌面薄壳用 WKWebView，
// 它加载控制台走的是**程序发起**的顶层导航（Wails 的 setURL），没有同站发起方，
// WebKit 会把 Strict cookie 扣下不发。症状是 ticket 明明兑换成功、Set-Cookie
// 也收下了，紧跟的 302 到 / 却报「无凭据」，用户看到「需要登录」页。
// Chromium（Chrome / Windows 的 WebView2）在同样情形下认作同站照发，所以这个
// bug 只在 macOS 出现——两边跑同一份 agentd 代码，别据此怀疑构建产物。
//
// 降到 Lax 不放松实际防护：Lax 只对**顶层 GET 导航**放行，写操作走 POST/DELETE，
// 跨站 POST 一样带不上 cookie。而 Strict 在这里唯一多挡的场景，恰好就是我们
// 自己要用的那一跳。
//
// 历史成因：这段 cookie 代码写于 agentd 还不托管前端时（当时注释写的是
// 「/ 返回 404 是预期结果」），W5a 让 agentd 托管控制台之后，才把一条从没被
// WKWebView 走过的跳转变成了主路径。
func sessionCookie(r *http.Request, value string, maxAge int) *http.Cookie {
	return &http.Cookie{
		Name:		sessionCookieName,
		Value:		value,
		Path:		"/",
		HttpOnly:	true,
		SameSite:	http.SameSiteLaxMode,

		Secure:	r.TLS != nil,
		MaxAge:	maxAge,
	}
}

n_agentd_sha256Hex.signature:
// sha256Hex 返回字节的十六进制 sha256。
func sha256Hex(body []byte) string {
	sum := sha256.Sum256(body)
	return hex.EncodeToString(sum[:])
}

n_agentd_shellQuote.signature:
// shellQuote 将字符串安全引用为 POSIX shell 单词：
// 安全字符原样输出，其余字符用单引号包围并把内部 ' 转义为 '\”。
func shellQuote(s string) string {
	if isSafeShellWord(s) {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

n_agentd_shortHash.signature:
// shortHash 取哈希前 8 位供日志用（agentd 私有副本；工作区包另有一份）。
func shortHash(h string) string {
	if len(h) <= 8 {
		return h
	}
	return h[:8]
}

n_agentd_sortStrings.signature:
func sortStrings(values []string) {
	for i := 1; i < len(values); i++ {
		for j := i; j > 0 && values[j] < values[j-1]; j-- {
			values[j], values[j-1] = values[j-1], values[j]
		}
	}
}

n_agentd_sortedKeys.signature:
// sortedKeys 取集合的有序键，让启动日志里的白名单顺序稳定可比。
func sortedKeys(m map[string]struct{}) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

n_agentd_squadView.signature:
// squadView 把小队实体投影成 wire DTO（来源同上）。
func squadView(q scheduling.Squad, version int) proto.SquadView {
	members := make([]proto.SquadMember, len(q.Members))
	for i, member := range q.Members {
		members[i] = proto.SquadMember{
			Carrier:	member.Carrier, MaxConcurrency: member.MaxConcurrency,
		}
	}
	return proto.SquadView{
		Name:	q.Name, Role: string(q.Role), Members: members, Version: version,
	}
}

n_agentd_startsAtLineStart.signature:
// startsAtLineStart 判断 path 在 offset 处的字节是否恰好位于行首。
//
// 行首 = 文件开头，或紧跟在换行符之后。streamFrames 用它决定首轮要不要走
// alignToLineStart：起点在行首时首行完整，对齐反而会把这条完整行吞掉。
//
// 判据：
//   - offset <= 0：文件开头，必是行首
//   - offset > 0：读 offset-1 处的一个字节，是换行符即行首
//
// 读前一字节失败时返回 false，走对齐路径丢残缺头：该路径只在「readFrom 刚
// 读过、文件紧接着被并发删除/替换」的极端窗口里出现，宁可丢半行，也不能让
// 客户端把残缺首行当成完整帧解析——何况失败概率极低，正常路径读前一字节是
// 可靠的（文件刚被 readFrom 打开读过）。
func startsAtLineStart(path string, offset int64) bool {
	if offset <= 0 {
		return true
	}
	f, err := os.Open(path)
	if err != nil {
		return false
	}
	defer f.Close()
	if _, err := f.Seek(offset-1, io.SeekStart); err != nil {
		return false
	}
	buf := make([]byte, 1)
	n, err := f.Read(buf)
	if err != nil || n != 1 {
		return false
	}
	return buf[0] == '\n'
}

n_agentd_streamFrames.signature:
// streamFrames 从 offset 起把 path 的内容按**完整行**写到 w；follow 为真时持续追送。
//
// 返回：已发送字节数与终止原因（客户端断开时返回 ctx.Err()）。
//
// 与 streamRender 的差异只有一处：这里维护一个「已读到但还不完整」的尾部，
// 不把它发出去，下一轮补齐后再连同后续内容一起发。
func streamFrames(ctx context.Context, w io.Writer, flusher http.Flusher,
	path string, offset int64, follow bool) (int64, error) {
	var sent int64
	first := true
	lastBeat := time.Now()
	for {
		chunk, err := readFrom(path, offset)
		if err != nil {
			return sent, err
		}
		if first && len(chunk) > 0 && !startsAtLineStart(path, offset) {

			aligned := alignToLineStart(chunk)
			offset += int64(len(chunk) - len(aligned))
			chunk = aligned
		}
		first = false
		complete, held := trimIncompleteTail(chunk)
		if len(complete) > 0 {
			n, werr := w.Write(complete)
			sent += int64(n)
			offset += int64(n)
			if werr != nil {
				return sent, werr
			}
			lastBeat = time.Now()
			if flusher != nil {
				flusher.Flush()
			}
		}
		_ = held
		if !follow {
			return sent, nil
		}

		if len(complete) == 0 && time.Since(lastBeat) >= renderHeartbeat {
			if _, err := w.Write([]byte("\n")); err != nil {
				return sent, err
			}
			if flusher != nil {
				flusher.Flush()
			}
			lastBeat = time.Now()
		}
		select {
		case <-ctx.Done():
			return sent, ctx.Err()
		case <-time.After(renderPollInterval):
		}
	}
}

n_agentd_streamRender.signature:
// streamRender 从 offset 起把 path 的内容写到 w；follow 为真时持续追送增量。
//
// 返回：已发送字节数与终止原因（客户端断开时返回 ctx.Err()）。
//
// 注意：文件不存在时不报错——follow 模式下等它出现即可（任务刚起、模型还没吐字）。
func streamRender(ctx context.Context, w io.Writer, flusher http.Flusher,
	path string, offset int64, follow bool) (int64, error) {
	var sent int64
	lastBeat := time.Now()
	for {
		n, err := copyFrom(w, path, offset)
		if err != nil {
			return sent, err
		}
		if n > 0 {
			offset += n
			sent += n
			lastBeat = time.Now()
			if flusher != nil {
				flusher.Flush()
			}
		}
		if !follow {
			return sent, nil
		}

		if n == 0 && time.Since(lastBeat) >= renderHeartbeat {
			if _, err := w.Write([]byte("\n")); err != nil {
				return sent, err
			}
			if flusher != nil {
				flusher.Flush()
			}
			lastBeat = time.Now()
		}
		select {
		case <-ctx.Done():
			return sent, ctx.Err()
		case <-time.After(renderPollInterval):
		}
	}
}

n_agentd_stripWorktreeCardIDs.signature:
// stripWorktreeCardIDs 只摘掉 card_ids 这一条**属于协调者本地账本**的指令。
//
// 为什么用「反序列化成 map 再删一个键」而不是重新编码一个结构体：结构体编码会把
// 本端不认识的字段一并丢掉，而两端 agentd 版本可能不同——新端加的请求字段会在
// 转发途中被旧端静默抹掉，且不报错。保留未知字段，转发才是透明的。
func stripWorktreeCardIDs(raw []byte) ([]byte, error) {
	var object map[string]json.RawMessage
	if err := json.Unmarshal(raw, &object); err != nil {
		return nil, err
	}
	delete(object, "card_ids")
	return json.Marshal(object)
}

n_agentd_ticketTitle.signature:
// ticketTitle 收件箱 ticket 条目标题：gate=权限工单、ask=提问工单。
func ticketTitle(tk proto.Ticket) string {
	if tk.Kind == "gate" {
		return "权限工单待答复"
	}
	return "提问工单待答复"
}

n_agentd_toProtoLaunchers.signature:
// toProtoLaunchers 把落盘形态换算成线格式，并现算 env_missing。
//
// **env_missing 必须在这里算、不落盘**：落一份派生值就有两个真相——文件里
// 说 false、磁盘上那个 env 文件早已被删。这也是 launcher.Item 刻意不带这个
// 字段的原因（见该类型的注释）。
//
// 返回值恒为非 nil 切片：JSON 里 `[]` 与 `null` 对前端是两种东西，
// 列表接口只该给前者。
func toProtoLaunchers(envDir string, list []launcher.Item) []proto.Launcher {
	out := make([]proto.Launcher, 0, len(list))
	for _, it := range list {
		l := proto.Launcher{Name: it.Name, EnvFile: it.EnvFile, Command: it.Command}
		if it.EnvFile != "" {

			if _, _, _, err := envfile.Read(envDir, it.EnvFile); err != nil {
				l.EnvMissing = true
			}
		}
		out = append(out, l)
	}
	return out
}

n_agentd_toWSScheme.signature:
// toWSScheme 把 http/https 换成 ws/wss。forwardURL 产出的恒是 http(s)://。
func toWSScheme(u string) string {
	switch {
	case strings.HasPrefix(u, "https://"):
		return "wss://" + strings.TrimPrefix(u, "https://")
	case strings.HasPrefix(u, "http://"):
		return "ws://" + strings.TrimPrefix(u, "http://")
	}
	return u
}

n_agentd_translateRegistryErr.signature:
// translateRegistryErr 把账本门面的错误翻译成 schedclient 契约哨兵（NotFound/
// CASConflict）。代价声明（拍板记录，2026-08-26）：哨兵替换会丢底层报文，
// 诊断信息由调用方日志补。
func translateRegistryErr(err error) error {
	switch {
	case errors.Is(err, ledger.ErrNotFound):
		return schedclient.ErrNotFound
	case errors.Is(err, ledger.ErrCASConflict):

		return schedclient.ErrCASConflict
	default:
		return err
	}
}

n_agentd_trimIncompleteTail.signature:
// trimIncompleteTail 把 b 切成「完整行部分」与「被扣住的残缺尾部长度」。
//
// 为什么服务端要保证这件事，而客户端还要再缓冲一层：服务端保证是契约
// （任何客户端都能按行解析），客户端缓冲是防御（代理与中间设备可能在任意
// 字节处切包）。两层都要有。
func trimIncompleteTail(b []byte) (complete []byte, held int) {
	i := bytes.LastIndexByte(b, '\n')
	if i < 0 {
		return nil, len(b)
	}
	return b[:i+1], len(b) - (i + 1)
}

n_agentd_truncateRunes.signature:
// truncateRunes 将字符串截断为最多 n 个字符（按 rune 截断，避免切断多字节 UTF-8 字符）。
//
// 用途：日志里记录用户应答时限制长度，防止超长自由文本刷爆日志。
func truncateRunes(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n])
}

n_agentd_unlinkedRowsFor.signature:
// unlinkedRowsFor 从一台 target 的任务列表里挑出该计入「未挂账」的行。
//
// 参数：target 为本机配置里这台机器的键名；tasks 为它当前的任务列表；
// linked 为 "target/task_id" → true 的挂账索引（由 ledger.AllTaskLinks 建立）。
// 返回：可直接进 JSON 的行，顺序与 tasks 一致（排序由调用方统一做）。
//
// 两条排除规则，缺一不可：
//   - 已挂账的跳过——它们在工作项看板里有卡认领，不属于「对不上账」
//   - 终态（completed / failed）的跳过——终态任务不再有 executor 持有工作区，
//     事后补挂卡改变不了任何事实；它们是历史残留而非待办
func unlinkedRowsFor(target string, tasks []proto.TaskView, linked map[string]bool) []map[string]any {
	rows := make([]map[string]any, 0, len(tasks))
	for _, task := range tasks {
		if linked[target+"/"+task.ID] {
			continue
		}
		if task.State.IsTerminal() {
			continue
		}
		rows = append(rows, map[string]any{
			"target":	target, "task_id": task.ID, "title": task.Name, "state": task.State,
		})
	}
	return rows
}

n_agentd_validConsoleNext.signature:
// validConsoleNext 判断 ticket 兑换后的站内跳转目标。
//
// 只允许 /cards 或其子路径，且目标必须是无 scheme、host、userinfo、fragment 的
// 相对 URL。raw 值与 query 解码值都检查控制字符和反斜杠，避免浏览器把它解释成
// 外部或另一种路径；非法值由调用方回落到根路径。
func validConsoleNext(next string) bool {
	if next == "" {
		return false
	}
	if strings.IndexFunc(next, func(r rune) bool { return r < 0x20 || r == 0x7f }) >= 0 {
		return false
	}
	if strings.Contains(next, "\\") || strings.HasPrefix(next, "//") {
		return false
	}
	parsed, err := url.Parse(next)
	if err != nil || parsed.IsAbs() || parsed.Scheme != "" ||
		parsed.Host != "" || parsed.User != nil || parsed.Fragment != "" {
		return false
	}
	if strings.Contains(parsed.Path, "\\") ||
		strings.IndexFunc(parsed.Path, func(r rune) bool { return r < 0x20 || r == 0x7f }) >= 0 {
		return false
	}
	for _, values := range parsed.Query() {
		for _, value := range values {
			if strings.Contains(value, "\\") ||
				strings.IndexFunc(value, func(r rune) bool { return r < 0x20 || r == 0x7f }) >= 0 {
				return false
			}
		}
	}
	return parsed.Path == "/cards" || strings.HasPrefix(parsed.Path, "/cards/")
}

n_agentd_validateAddMachine.signature:
// validateAddMachine 校验新增开发机的请求。
//
// 参数：
//   - req: 请求体
//   - existing: 现有 targets，用于判重名
//
// 返回：
//   - 包装了 ErrMachineExists 的错误表示重名（调用方应答 409）
//   - 其余非 nil 错误都是请求体本身的问题（调用方应答 400）
func validateAddMachine(req proto.AddMachineReq, existing map[string]config.Target) error {

	if req.Name == "" {
		return errors.New("name 不能为空")
	}
	if strings.ContainsAny(req.Name, " \t\r\n") {
		return errors.New("name 不能含空白字符")
	}
	if _, ok := existing[req.Name]; ok {
		return fmt.Errorf("%w: %s", ErrMachineExists, req.Name)
	}
	if _, _, err := net.SplitHostPort(req.Addr); err != nil {
		return fmt.Errorf("addr 需形如 host:port: %w", err)
	}
	if req.Token == "" {
		return errors.New("token 不能为空")
	}
	return nil
}

n_agentd_validateLegacyDisciplineFileNam.signature:
// validateLegacyDisciplineFileName 校验映射里的文件名仍是「纯文件名」，
// 与退役前 resolvePath 的判据一致（拒分隔符/./..），保存语义不动的一部分。
func validateLegacyDisciplineFileName(name string) error {
	if strings.ContainsRune(name, filepath.Separator) || strings.ContainsRune(name, '/') ||
		name == "" || name == "." || name == ".." {
		return fmt.Errorf("%q 不能含路径分隔符或为空", name)
	}
	return nil
}

n_agentd_waitPreviewBackoff.signature:
func waitPreviewBackoff(ctx context.Context, delay time.Duration) bool {
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return false
	case <-timer.C:
		return true
	}
}

n_agentd_waitPreviewProcess.signature:
func waitPreviewProcess(ctx context.Context, process *previewProcess) error {
	select {
	case <-process.exitDone:
		return nil
	case <-ctx.Done():
		return fmt.Errorf("等待 preview 浏览器退出: %w", ctx.Err())
	}
}

n_agentd_wantsHTML.signature:
// wantsHTML 报告请求方是否更希望拿到 HTML。
//
// 判据刻意从严：只有 Accept 里**显式**出现 text/html 才算。浏览器地址栏发起的
// 导航一定带它；而 fetch/XHR、CLI、`*/*` 都不带，会走原有 JSON 分支——
// 那些调用方的错误处理都按 JSON 写的，给它们 HTML 会让整条错误链失效。
func wantsHTML(r *http.Request) bool {
	return strings.Contains(strings.ToLower(r.Header.Get("Accept")), "text/html")
}

n_agentd_withIdentity.signature:
// withIdentity 返回携带身份的新 context。
