n_agentd_writeCtrl.signature:
// writeCtrl 发一帧 JSON 控制信息（text 帧）。
func writeCtrl(ctx context.Context, conn *websocket.Conn, c proto.PtyControl) error {
	b, err := json.Marshal(c)
	if err != nil {
		return err
	}
	return conn.Write(ctx, websocket.MessageText, b)
}

n_agentd_writeErr.signature:
// writeErr 按本文件既有约定写错误响应：{"error": "<原因>"}。
//
// 抽出来只是省重复，语义与散落各处的 writeJSON(w, code, map[string]string{"error": ...}) 完全一致。
func writeErr(w http.ResponseWriter, code int, err error) {
	writeJSON(w, code, map[string]string{"error": err.Error()})
}

n_agentd_writeEvent.signature:
// writeEvent 将事件序列化为 JSON 文本帧写入 WS 连接。
func writeEvent(ctx context.Context, conn *websocket.Conn, ev proto.Event) error {
	b, err := json.Marshal(ev)
	if err != nil {
		return fmt.Errorf("序列化事件 %d: %w", ev.Seq, err)
	}
	return conn.Write(ctx, websocket.MessageText, b)
}

n_agentd_writeJSON.signature:
// writeJSON 以指定状态码写出 JSON 响应。
//
// 编码失败（响应已开始后无法回退）仅打日志，不改变已写出的状态码。
func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(v); err != nil {
		slog.Default().Warn("JSON 编码失败", "err", err)
	}
}

n_agentd_writeSOCKSReply.signature:
func writeSOCKSReply(conn net.Conn, code byte) error {
	_, err := conn.Write([]byte{5, code, 0, 1, 0, 0, 0, 0, 0, 0})
	return err
}

n_agentd_writeUnauthorized.signature:
// writeUnauthorized 按调用方偏好输出 401。
//
// 注意：无论走哪个分支，**状态码恒为 401**。不要因为返回了 HTML 就改成 200，
// 那会让监控与前端的鉴权拦截器同时失效。
func writeUnauthorized(w http.ResponseWriter, r *http.Request) {
	if wantsHTML(r) {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Header().Set("Cache-Control", "no-store")
		w.WriteHeader(http.StatusUnauthorized)
		_, _ = io.WriteString(w, unauthorizedPage)
		return
	}
	writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "未授权"})
}

