n_agy_OneShotArgv.signature:
// OneShotArgv 编码 agy 一次性调用的 argv。
func OneShotArgv(model, prompt string, _ executor.OneShotLimits) ([]string, error) {
	if model != "" {
		return []string{"agy", "--model", model, "-p", prompt}, nil
	}
	return []string{"agy", "-p", prompt}, nil
}

n_agy_OneShot_Invoke.signature:
func (s *OneShot) Invoke(ctx context.Context, req executor.OneShotReq) (executor.OneShotReply, error) {
	s.log.Info("OneShot.Invoke 进入", "harness", executor.HarnessAGY, "model", req.Model, "prompt_bytes", len(req.Prompt), "effort", req.Limits.Effort)
	argv, err := OneShotArgv(req.Model, req.Prompt, req.Limits)
	if err != nil {
		s.log.Error("OneShot argv 编码失败", "cause", err)
		return executor.OneShotReply{Status: executor.OneShotFailed}, err
	}
	out, err := executor.RunOneShotProcess(ctx, argv, req.Env, req.Workdir, req.HomeDir)
	if ctx.Err() != nil {
		s.log.Info("OneShot 已取消", "cause", ctx.Err())
		return executor.OneShotReply{Text: out, Status: executor.OneShotCanceled}, ctx.Err()
	}
	if err != nil {
		s.log.Error("OneShot 进程失败", "cause", err)
		return executor.OneShotReply{Text: out, Status: executor.OneShotFailed}, err
	}
	s.log.Info("OneShot.Invoke 完成", "status", executor.OneShotOK, "output_bytes", len(out))
	return executor.OneShotReply{Text: out, Status: executor.OneShotOK}, nil
}

n_agy_ParseUsage.signature:
// ParseUsage 把 agy 的原始用量转换为 proto.Usage。
//
// 上下文占用 = input_tokens + cache_read_tokens。
// 零值时返回 nil（不使用 0 冒充）。
func ParseUsage(raw *AgyUsageRaw) *proto.Usage {
	if raw == nil {
		return nil
	}
	ctxTokens := raw.InputTokens + raw.CacheReadTokens
	if ctxTokens <= 0 {
		return nil
	}
	return &proto.Usage{
		ContextTokens: ctxTokens,
	}
}

n_agy_Proc_Alive.signature:
// Alive 探测 agy 进程是否仍存活。
func (p *Proc) Alive() bool {
	if !prochost.Alive(p.Handle) {
		return false
	}
	if exited, _ := procExited(filepath.Join(p.TaskDir, outFileName)); exited {
		return false
	}
	return true
}

n_agy_Proc_Kill.signature:
// Kill 终止 agy 进程并清理存活锁。
func (p *Proc) Kill() error {
	return killProcHost(p.Handle)
}

n_agy_Proc_WriteInput.signature:
// WriteInput 往输入通道投递一条 stream-json user message。
func (p *Proc) WriteInput(text string) error {
	path := filepath.Join(p.TaskDir, fifoFileName)
	line, err := json.Marshal(map[string]any{
		"event":	"user",
		"message": map[string]any{
			"role":	"user",
			"content": []map[string]string{
				{
					"type":	"text",
					"text":	text,
				},
			},
		},
	})
	if err != nil {
		return fmt.Errorf("序列化 user message: %w", err)
	}
	if err := prochost.WriteInputChannel(path, append(line, '\n')); err != nil {
		return err
	}
	slog.Default().Debug("已投递指令到输入通道", "task_dir", p.TaskDir, "bytes", len(line)+1)
	return nil
}

n_agy_Profile_Inspect.signature:
func (p *Profile) Inspect(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
