}

n_agy_Profile_Prepare.signature:
func (p *Profile) Prepare(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
	}
	if req.HomeDir == "" {
		return rep, errors.New("Profile.Prepare 缺少 HomeDir")
	}
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 开始", "harness", executor.HarnessAGY, "home", req.HomeDir, "isolated", req.Isolated)
	}
	nativeRoot := filepath.Join(req.HomeDir, filepath.Dir(RulesRelFile))
	if err := os.MkdirAll(nativeRoot, 0700); err != nil {
		return rep, fmt.Errorf("创建原生配置目录 %q: %w", nativeRoot, err)
	}

	for _, r := range req.Rules {
		if strings.Contains(r.Name, "..") {
			return rep, fmt.Errorf("规则文件名含非法字符: %q", r.Name)
		}
		var target string
		if strings.HasPrefix(filepath.Clean(r.Name), filepath.Dir(RulesRelFile)) {
			target = filepath.Join(req.HomeDir, filepath.Clean(r.Name))
		} else {
			target = filepath.Join(nativeRoot, filepath.Clean(r.Name))
		}
		if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
			return rep, fmt.Errorf("创建规则父目录 %q: %w", filepath.Dir(target), err)
		}
		if err := os.WriteFile(target, []byte(r.Content), 0600); err != nil {
			return rep, fmt.Errorf("写入规则文件 %q: %w", target, err)
		}
	}

	if len(req.Skills) > 0 {
		skillsRoot := filepath.Join(req.HomeDir, SkillsRelDir)
		for _, s := range req.Skills {
			if strings.Contains(s.Name, "..") {
				return rep, fmt.Errorf("skill 文件名含非法字符: %q", s.Name)
			}
			target := filepath.Join(skillsRoot, filepath.Clean(s.Name))
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建 skill 父目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(s.Content), 0600); err != nil {
				return rep, fmt.Errorf("写入 skill 文件 %q: %w", target, err)
			}
		}
	}

	if len(req.TaskOverlay) > 0 {
		overlayRoot := filepath.Join(req.HomeDir, ".handoff", "task-overlay")
		for _, o := range req.TaskOverlay {
			if strings.Contains(o.Name, "..") {
				return rep, fmt.Errorf("overlay 文件名含非法字符: %q", o.Name)
			}
			target := filepath.Join(overlayRoot, filepath.Clean(o.Name))
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建 overlay 父目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(o.Content), 0600); err != nil {
				return rep, fmt.Errorf("写入 overlay 文件 %q: %w", target, err)
			}
		}
	}

	rep.Prepared = true
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 完成", "harness", executor.HarnessAGY, "prepared", true)
	}
	return rep, nil
}

n_agy_Profile_Verify.signature:
func (p *Profile) Verify(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
		EngineOK:	false,
	}
	if req.HomeDir == "" {
		return rep, nil
	}
	rulePath := filepath.Join(req.HomeDir, RulesRelFile)
	globalOK := false
	if len(req.Rules) == 0 {
		_, err := os.Stat(rulePath)
		globalOK = err == nil
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			if p != nil && p.log != nil {
				p.log.Error("Profile.Verify 读取原生规则失败", "harness", executor.HarnessAGY,
					"home", req.HomeDir, "path", rulePath, "cause", err)
			}
			return rep, fmt.Errorf("校验原生规则 %q: %w", rulePath, err)
		}
	} else {
		expected := req.Rules[0].Content
		for _, rule := range req.Rules {
			if filepath.Base(filepath.Clean(rule.Name)) == filepath.Base(RulesRelFile) {
				expected = rule.Content
			}
		}
		got, readErr := os.ReadFile(rulePath)
		if readErr != nil {
			rep.Missing = append(rep.Missing, RulesRelFile)
		} else if !bytes.Equal(got, []byte(expected)) {
			rep.Notes = append(rep.Notes, fmt.Sprintf("规则内容不符: %s", RulesRelFile))
		} else {
			globalOK = true
		}
	}
	overlayOK := true
	for _, overlay := range req.TaskOverlay {
		if strings.Contains(overlay.Name, "..") {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 文件名含非法字符: %s", overlay.Name))
			continue
		}
		rel := filepath.Join(".handoff", "task-overlay", filepath.Clean(overlay.Name))
		got, readErr := os.ReadFile(filepath.Join(req.HomeDir, rel))
		if readErr != nil {
			overlayOK = false
			rep.Missing = append(rep.Missing, rel)
			if p != nil && p.log != nil {
				actualState := "read_error"
				if errors.Is(readErr, os.ErrNotExist) {
					actualState = "missing"
				}
				p.log.Warn("Profile.Verify 任务层内容缺失",
					"harness", executor.HarnessAGY, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", actualState,
					"expected_bytes", len(overlay.Content), "actual_bytes", 0, "cause", readErr)
			}
			continue
		}
		if !bytes.Equal(got, []byte(overlay.Content)) {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 内容不符: %s", rel))
			if p != nil && p.log != nil {
				p.log.Warn("Profile.Verify 任务层内容不符",
					"harness", executor.HarnessAGY, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", "content_mismatch",
					"expected_bytes", len(overlay.Content), "actual_bytes", len(got))
			}
		}
	}
	rep.Verified = globalOK && overlayOK
	if p != nil && p.log != nil {
		p.log.Info("Profile.Verify 完成", "harness", executor.HarnessAGY,
			"home", req.HomeDir, "verified", rep.Verified, "engine_ok", rep.EngineOK,
			"overlay_count", len(req.TaskOverlay))
	}
	return rep, nil
}

n_agy_RestoreTaskEnv.signature:
// RestoreTaskEnv 从 taskDir 的 sidecar 恢复 agy hooks 物料。
//
// 参数：taskDir 为任务专属目录，sidecar 位于其中。
// 返回：所有恢复动作成功时返回 nil；缺少 sidecar 视为幂等成功。
// 注意：workdir 被回收时跳过文件恢复；已跟踪 hooks 的 skip-worktree 必须清除。
func RestoreTaskEnv(taskDir string) (err error) {
	log := slog.Default()
	sidecarPath := filepath.Join(taskDir, restoreFileName)
	log.Info("agy 开始还原任务 hooks", "task_dir", taskDir, "sidecar", sidecarPath)
	data, err := os.ReadFile(sidecarPath)
	if os.IsNotExist(err) {
		log.Info("agy hooks 无恢复凭据，按幂等路径返回", "task_dir", taskDir)
		return nil
	}
	if err != nil {
		log.Error("读取 agy hooks 恢复凭据失败", "task_dir", taskDir, "cause", err)
		return fmt.Errorf("读取 %s: %w", sidecarPath, err)
	}
	var state hooksRestoreState
	if err := json.Unmarshal(data, &state); err != nil {
		log.Error("解析 agy hooks 恢复凭据失败", "task_dir", taskDir, "cause", err)
		return fmt.Errorf("解析 %s: %w", sidecarPath, err)
	}
	if state.Workdir == "" || state.HooksPath == "" {
		err := fmt.Errorf("恢复凭据字段不完整")
		log.Error("agy hooks 恢复凭据无工作区路径", "task_dir", taskDir, "cause", err)
		return err
	}

	if _, statErr := os.Stat(state.Workdir); os.IsNotExist(statErr) {
		log.Info("工作区已不在，跳过 hooks 还原", "task_dir", taskDir, "workdir", state.Workdir)
		if removeErr := os.Remove(sidecarPath); removeErr != nil {
			log.Error("工作区已回收但删除 agy hooks 恢复凭据失败", "task_dir", taskDir, "cause", removeErr)
			return fmt.Errorf("删除 %s: %w", sidecarPath, removeErr)
		}
		log.Info("agy hooks 恢复凭据已清理", "task_dir", taskDir, "workdir", state.Workdir)
		return nil
	} else if statErr != nil {
		log.Error("检查 agy hooks 工作区失败", "task_dir", taskDir, "workdir", state.Workdir, "cause", statErr)
		return fmt.Errorf("检查工作区 %s: %w", state.Workdir, statErr)
	}

	var restoreErr error
	addRestoreError := func(operation string, cause error) {
		if cause == nil {
			return
		}
		log.Error("agy hooks 恢复步骤失败", "task_dir", taskDir, "workdir", state.Workdir,
			"operation", operation, "cause", cause)
		restoreErr = errors.Join(restoreErr, fmt.Errorf("%s: %w", operation, cause))
	}
	if state.CreatedFile {
		if removeErr := os.Remove(state.HooksPath); removeErr != nil && !os.IsNotExist(removeErr) {
			addRestoreError("删除新建 hooks.json", removeErr)
		}
	} else if writeErr := os.WriteFile(state.HooksPath, state.OriginalJSON, 0644); writeErr != nil {
		addRestoreError("写回 hooks.json 原文", writeErr)
	}

	if state.SkipWorktree {
		if clearErr := updateHooksSkipWorktree(state.Workdir, false); clearErr != nil {
			addRestoreError("清除 hooks.json skip-worktree", clearErr)
		} else {
			log.Info("agy hooks.json skip-worktree 已清除", "task_dir", taskDir, "workdir", state.Workdir)
		}
	}
	if state.ExcludePattern != "" {
		if excludeErr := removeGitExclude(state.Workdir, state.ExcludePattern); excludeErr != nil {
			addRestoreError("撤销 hooks exclude", excludeErr)
		} else {
			log.Info("agy hooks exclude 已撤销", "task_dir", taskDir, "workdir", state.Workdir,
				"pattern", state.ExcludePattern)
		}
	}
	if restoreErr != nil {
		log.Error("agy hooks 还原未完成，保留恢复凭据供重试", "task_dir", taskDir, "workdir", state.Workdir,
			"cause", restoreErr)
		return fmt.Errorf("还原 agy hooks: %w", restoreErr)
	}
	if err := os.Remove(sidecarPath); err != nil {
		log.Error("删除 agy hooks 恢复凭据失败", "task_dir", taskDir, "cause", err)
		return fmt.Errorf("删除 %s: %w", sidecarPath, err)
	}
	log.Info("agy hooks 还原完成", "task_dir", taskDir, "workdir", state.Workdir,
		"created_file", state.CreatedFile, "skip_worktree", state.SkipWorktree)
	return nil
}

n_agy_StartProc.signature:
// StartProc 备物料、经 prochost 拉起 shim 承载 agy，返回进程句柄。
func StartProc(ctx context.Context, req StartProcReq, log *slog.Logger) (*Proc, error) {
	l := log.With("task", req.TaskID)
	if len(req.Env) > 0 {
		l.Info("注入 env 变量到 agy 进程", "keys", envKeys(req.Env), "count", len(req.Env))
	}
	fifoPath := filepath.Join(req.TaskDir, fifoFileName)
	if err := prochost.CreateInputChannel(fifoPath); err != nil {
		l.Error("创建输入通道失败", "path", fifoPath, "cause", err)
		return nil, err
	}
	bin, err := lookAgyPath()
	if err != nil {
		l.Error("agy 未安装", "cause", err)
		return nil, fmt.Errorf("agy 未安装: %w", err)
	}
	l.Info("解析 agy 可执行文件", "bin", bin)
	selfExe, err := os.Executable()
	if err != nil {
		l.Error("取 handoff 自身路径失败（shim 无法拉起）", "cause", err)
		return nil, fmt.Errorf("取自身可执行路径: %w", err)
	}
	argv := agyArgv(req)
	argv[0] = bin

	lockPath := filepath.Join(req.TaskDir, lockFileName)
	infoPath := filepath.Join(req.TaskDir, procInfoFileName)
	if err := writeProcInfo(req.TaskDir, &procInfo{
		Handle:	prochost.Handle{LockPath: lockPath}, SessionID: req.SessionID,
	}); err != nil {
		l.Error("写恢复凭据失败", "cause", err)
		return nil, err
	}
	spec := prochost.Spec{
		Argv:	argv, Dir: req.RepoPath, Env: append(os.Environ(), req.Env...),
		Stdout:		filepath.Join(req.TaskDir, outFileName),
		Stderr:		filepath.Join(req.TaskDir, stderrFileName),
		InputCh:	fifoPath, LockPath: lockPath, InfoPath: infoPath,
		Sentinel:	true,
	}
	spec.TaskID = req.TaskID
	spec.MarkRoot = req.MarkRoot
	l.Info("启动 agy 执行者", "bin", bin, "repo", req.RepoPath, "add_dir", req.RepoPath != "", "resume", req.Resume)
	handle, err := startProcHost(spec, selfExe)
	if err != nil {
		l.Error("拉起 agy 执行者失败", "cause", err)
		return nil, err
	}
	p := &Proc{Handle: handle, TaskDir: req.TaskDir, SessionID: req.SessionID}
	elapsed, err := prochost.WaitInputReader(fifoPath, fifoReaderTimeout)
	if err != nil {
		l.Error("shim 未在时限内打开 in.fifo", "cause", err, "log_tail", agyLogTail(req.TaskDir))
		if kerr := p.Kill(); kerr != nil {
			l.Warn("回收读端未就绪的执行者失败，可能需人工清理", "cause", kerr)
		}
		return nil, err
	}
	l.Debug("agy in.fifo 读端就绪", "wait", elapsed)
	if err := writeProcInfo(req.TaskDir, &procInfo{
		Handle:	handle, SessionID: req.SessionID,
	}); err != nil {
		l.Warn("回写恢复凭据失败，重启恢复将不可用", "cause", err)
	}
	l.Info("agy 执行者已就位", "shim_pid", handle.PID)
	return p, nil
}

n_agy_WriteTaskEnv.signature:
// WriteTaskEnv 在任务 HOME 落下 agy 策略物料，并渲染首回合 prompt。
//
// 参数：workdir 为任务工作区（本函数不再往其中写 gate）；taskDir 为任务专属目录；
// sockPath 为权限裁决套接字；其余参数用于 prompt 与 hooks 命令。
// 返回任务 HOME 内 hooks.json 路径和首回合 prompt；oauth 凭据缺失或任一物料
// 写入失败时返回错误。
//
// 不写 workspace .agents/hooks.json：headless 读的是 HOME；B309 --add-dir 会
// 再加载 workspace 那份，双写同一 gate 导致同一 step_N 打两次（B310/B314）。
func WriteTaskEnv(workdir, taskDir, taskID, planContent, sockPath, handoffBin, disciplineBlock string) (hooksPath, promptText string, err error) {
	log := slog.Default()
	agyHome := filepath.Join(taskDir, agyHomeDirName)
	agyGeminiDir := filepath.Join(agyHome, ".gemini")
	agyConfigDir := filepath.Join(agyGeminiDir, "config")
	agyCLIDir := filepath.Join(agyGeminiDir, "antigravity-cli")
	if err := os.MkdirAll(agyConfigDir, 0700); err != nil {
		log.Error("创建 agy 任务 HOME config 目录失败", "task", taskID, "path", agyConfigDir, "cause", err)
		return hooksPath, "", fmt.Errorf("创建 %s: %w", agyConfigDir, err)
	}
	if err := os.MkdirAll(agyCLIDir, 0700); err != nil {
		log.Error("创建 agy 任务 HOME antigravity-cli 目录失败", "task", taskID, "path", agyCLIDir, "cause", err)
		return hooksPath, "", fmt.Errorf("创建 %s: %w", agyCLIDir, err)
	}
	for _, dir := range []string{agyHome, agyGeminiDir, agyConfigDir, agyCLIDir} {
		if err := os.Chmod(dir, 0700); err != nil {
			log.Error("设置 agy 任务 HOME 目录权限失败", "task", taskID, "path", dir, "cause", err)
			return hooksPath, "", fmt.Errorf("设置 %s 权限: %w", dir, err)
		}
	}
	log.Info("agy 准备任务环境", "task", taskID, "task_dir", taskDir, "workdir", workdir, "path", agyHome)

	userHome, err := os.UserHomeDir()
	if err != nil {
		log.Error("解析 agy oauth 用户 HOME 失败", "task", taskID, "cause", err)
		return hooksPath, "", fmt.Errorf("解析用户 HOME: %w", err)
	}
	sourceOAuth := filepath.Join(userHome, ".gemini", "antigravity-cli", "antigravity-oauth-token")
	oauthData, err := os.ReadFile(sourceOAuth)
	if err != nil {
		log.Error("读取 agy oauth token 失败", "task", taskID, "source", sourceOAuth, "cause", err)
		return hooksPath, "", fmt.Errorf("读取 agy oauth token %s: %w", sourceOAuth, err)
	}
	destOAuth := filepath.Join(agyCLIDir, "antigravity-oauth-token")
	if err := os.WriteFile(destOAuth, oauthData, 0600); err != nil {
		log.Error("拷贝 agy oauth token 失败", "task", taskID, "source", sourceOAuth, "destination", destOAuth, "cause", err)
		return hooksPath, "", fmt.Errorf("写入 agy oauth token %s: %w", destOAuth, err)
	}
	log.Info("agy oauth token 已拷贝到任务 HOME", "task", taskID, "source", sourceOAuth, "destination", destOAuth, "bytes", len(oauthData))

	originalOAuth := sourceOAuth + ".orig-google-oauth"
	if originalData, readErr := os.ReadFile(originalOAuth); readErr == nil {
		destOriginal := filepath.Join(agyCLIDir, "antigravity-oauth-token.orig-google-oauth")
		if err := os.WriteFile(destOriginal, originalData, 0600); err != nil {
			log.Error("拷贝 agy 原始 oauth token 失败", "task", taskID, "source", originalOAuth, "destination", destOriginal, "cause", err)
			return hooksPath, "", fmt.Errorf("写入 agy 原始 oauth token %s: %w", destOriginal, err)
		}
		log.Info("agy 原始 oauth token 已拷贝到任务 HOME", "task", taskID, "source", originalOAuth, "destination", destOriginal, "bytes", len(originalData))
	} else if !os.IsNotExist(readErr) {
		log.Error("读取 agy 原始 oauth token 失败", "task", taskID, "source", originalOAuth, "cause", readErr)
		return hooksPath, "", fmt.Errorf("读取 agy 原始 oauth token %s: %w", originalOAuth, readErr)
	}

	settings := struct {
		Permissions struct {
			Allow []string `json:"allow"`
		} `json:"permissions"`
	}{}
	settings.Permissions.Allow = append([]string(nil), nativeCommandAllow...)
	settingsJSON, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		log.Error("序列化 agy 原生权限策略失败", "task", taskID, "path", filepath.Join(agyCLIDir, "settings.json"), "cause", err)
		return hooksPath, "", fmt.Errorf("序列化 agy settings.json: %w", err)
	}
	settingsPath := filepath.Join(agyCLIDir, "settings.json")
	if err := os.WriteFile(settingsPath, append(settingsJSON, '\n'), 0600); err != nil {
		log.Error("写 agy 原生权限策略失败", "task", taskID, "path", settingsPath, "cause", err)
		return hooksPath, "", fmt.Errorf("写入 %s: %w", settingsPath, err)
	}
	log.Info("agy 原生权限策略已写入任务 HOME", "task", taskID, "path", settingsPath, "allow_count", len(nativeCommandAllow))

	gateCfg := map[string]any{
		"handoff-safety-gate": hookNamedConfig{
			PreToolUse: []hookGroup{
				{
					Matcher:	preToolUseMatcher,
					Hooks: []hookHandler{
						{
							Type:		"command",
							Command:	fmt.Sprintf("%s permission-hook --sock %s", strconv.Quote(handoffBin), strconv.Quote(sockPath)),
							Timeout:	86400,
						},
					},
				},
			},
		},
	}
	hooksJSON, err := json.MarshalIndent(gateCfg, "", "  ")
	if err != nil {
		log.Error("agy 序列化 hooks.json 失败", "task", taskID, "cause", err)
		return hooksPath, "", fmt.Errorf("序列化 hooks.json: %w", err)
	}
	hooksPath = filepath.Join(agyConfigDir, hooksFileName)
	if err := os.WriteFile(hooksPath, append(hooksJSON, '\n'), 0600); err != nil {
		log.Error("写 agy 任务 HOME hooks.json 失败", "task", taskID, "path", hooksPath, "cause", err)
		return hooksPath, "", fmt.Errorf("写入 %s: %w", hooksPath, err)
	}
	log.Info("agy 任务 HOME hooks.json 已写入", "task", taskID, "path", hooksPath, "sock", sockPath, "matcher", preToolUseMatcher)

	promptText, err = turn.RenderPrompt(taskID, planContent, disciplineBlock)
	if err != nil {
		return hooksPath, "", err
	}
	return hooksPath, promptText, nil
}

n_agy_agyArgv.signature:
// agyArgv 组装 agy 的完整命令行参数列表。
//
// 说明：
//   - --input-format / --output-format stream-json: 启用双向流式 stdin/stdout 协议。
//   - --print-timeout 24h: 避免受默认 5m 打印等待墙截断。
//   - --add-dir <RepoPath>：隔离 HOME 后 run_command 的默认 cwd 是
//     $HOME/.gemini/antigravity-cli/scratch，不是进程 Dir。5530b65b 实测 init.cwd
//     已是 worktree，pwd 仍打出 scratch。必须把 worktree 登记成 workspace。
//   - --dangerously-skip-permissions：只跳过原生 print-mode 确认（B308 canary：
//     deny hook 仍拦住 touch）。否决权在 PreToolUse matcher=*。不写 always-proceed。
//   - 不传 --sandbox：agy 的 OS 级别 sandbox 会严格限制只写工作区，与 handoff 分配在
//     任务目录下（~/.handoff/tasks/<id>/tmp）的 TMPDIR/GOCACHE 互斥。
func agyArgv(req StartProcReq) []string {
	argv := []string{
		"agy",
		"--input-format", "stream-json",
		"--output-format", "stream-json",
		"--print-timeout", "24h",
		"--dangerously-skip-permissions",
	}
	if req.RepoPath != "" {
		argv = append(argv, "--add-dir", req.RepoPath)
	}
	if req.Model != "" {
		argv = append(argv, "--model", req.Model)
	}
	if req.Resume && req.SessionID != "" {
		argv = append(argv, "--conversation", req.SessionID)
	}
	return argv
}

n_agy_agyLogTail.signature:
func agyLogTail(taskDir string) string {
	path := filepath.Join(taskDir, stderrFileName)
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Sprintf("（读取 %s 失败: %v）", stderrFileName, err)
	}
	lines := strings.Split(strings.TrimSpace(string(data)), "\n")
	if len(lines) > 5 {
		lines = lines[len(lines)-5:]
	}
	return strings.Join(lines, "\n")
}

n_agy_ensureGitExclude.signature:
// ensureGitExclude 将 pattern 追加写入 workdir 对应 git 仓库的 info/exclude 文件，
// 避免未跟踪的 hooks.json 导致 git status --porcelain 变脏或触发 ensureCleanWorktree 拦截。
// info/exclude 仅对本地工作树生效，不影响 git 追踪历史，不会被提交或推送到远端。
func ensureGitExclude(workdir, pattern string) (bool, error) {
	log := slog.Default()
	excludePath, err := gitInfoExcludePath(workdir)
	if err != nil {
		log.Error("解析 git info/exclude 路径失败", "workdir", workdir, "pattern", pattern, "cause", err)
		return false, err
	}
	data, err := os.ReadFile(excludePath)
	if err == nil {
		lines := strings.Split(string(data), "\n")
		for _, line := range lines {
			if strings.TrimSpace(line) == pattern {
				return false, nil
			}
		}
	} else if !os.IsNotExist(err) {
		log.Error("读取 git info/exclude 失败", "workdir", workdir, "path", excludePath, "pattern", pattern, "cause", err)
		return false, fmt.Errorf("读取 %s: %w", excludePath, err)
	}
	if err := os.MkdirAll(filepath.Dir(excludePath), 0755); err != nil {
		log.Error("创建 git info/exclude 目录失败", "workdir", workdir, "path", excludePath, "pattern", pattern, "cause", err)
		return false, fmt.Errorf("创建 %s: %w", filepath.Dir(excludePath), err)
	}
	f, err := os.OpenFile(excludePath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0644)
	if err != nil {
		log.Error("打开 git info/exclude 失败", "workdir", workdir, "path", excludePath, "pattern", pattern, "cause", err)
		return false, fmt.Errorf("打开 %s: %w", excludePath, err)
	}
	_, writeErr := f.WriteString("\n" + pattern + "\n")
	closeErr := f.Close()
	if writeErr != nil {
		log.Error("写 git info/exclude 失败", "workdir", workdir, "path", excludePath, "pattern", pattern, "cause", writeErr)
		return true, fmt.Errorf("写 %s: %w", excludePath, writeErr)
	}
	if closeErr != nil {
		log.Error("关闭 git info/exclude 失败", "workdir", workdir, "path", excludePath, "pattern", pattern, "cause", closeErr)
		return true, fmt.Errorf("关闭 %s: %w", excludePath, closeErr)
	}
	return true, nil
}

