n_agy_parseSpend.signature:
// parseSpend 从 AgyUsageRaw 解析出 SpendEntry。
func parseSpend(raw *AgyUsageRaw, conversationID string) (proto.SpendEntry, bool) {
	if raw == nil || conversationID == "" {
		return proto.SpendEntry{}, false
	}
	if raw.InputTokens == 0 && raw.OutputTokens == 0 && raw.CacheReadTokens == 0 {
		return proto.SpendEntry{}, false
	}

	return proto.SpendEntry{
		Key:		fmt.Sprintf("%s-spend", conversationID),
		InputTokens:	raw.InputTokens,
		CachedTokens:	raw.CacheReadTokens,
		OutputTokens:	raw.OutputTokens + raw.ThinkingTokens,
		CostTicks:	0,
		CostState:	proto.CostUnknown,
	}, true
}

n_agy_permPathFromInput.signature:
func permPathFromInput(input json.RawMessage, keys ...string) string {
	var raw map[string]any
	if json.Unmarshal(input, &raw) != nil {
		return ""
	}
	for _, k := range keys {
		if v, ok := raw[k].(string); ok && v != "" {
			return v
		}
	}
	return ""
}

n_agy_permServer_Close.signature:
// Close 关闭服务端并释放所有 pending 连接。
func (s *permServer) Close() error {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return nil
	}
	s.closed = true
	for id, conn := range s.pending {
		_ = json.NewEncoder(conn).Encode(permDecision{Behavior: "deny", Message: "服务已停止"})
		_ = conn.Close()
		delete(s.pending, id)
	}
	s.mu.Unlock()

	var err error
	if s.ln != nil {
		err = s.ln.Close()
	}
	_ = os.Remove(s.sockPath)
	return err
}

n_agy_permServer_Respond.signature:
// Respond 对指定 tool_use_id 做出裁决并回发。
func (s *permServer) Respond(toolUseID, behavior, message string) error {
	s.mu.Lock()
	conn, ok := s.pending[toolUseID]
	if ok {
		delete(s.pending, toolUseID)
	}
	s.mu.Unlock()

	if !ok {
		s.log.Error("裁决目标不存在（请求已失效或连接已断开）", "tool_use_id", toolUseID, "behavior", behavior)
		return fmt.Errorf("裁决请求 %s 不存在（可能已应答或连接已断开）", toolUseID)
	}
	defer conn.Close()

	if behavior != "allow" && behavior != "deny" {
		behavior = "deny"
	}
	d := permDecision{
		Type:		"decision",
		Behavior:	behavior,
		Message:	message,
	}
	if err := json.NewEncoder(conn).Encode(d); err != nil {
		s.log.Error("发送裁决帧失败", "id", toolUseID, "behavior", behavior, "cause", err)
		return fmt.Errorf("发送裁决 %s: %w", toolUseID, err)
	}
	s.log.Info("已下发权限裁决", "id", toolUseID, "behavior", behavior)
	return nil
}

n_agy_permServer_handle.signature:
func (s *permServer) handle(conn net.Conn) {
	var ask struct {
		Type		string		`json:"type"`
		ToolUseID	string		`json:"tool_use_id"`
		ToolName	string		`json:"tool_name"`
		Input		json.RawMessage	`json:"input"`
	}
	if err := json.NewDecoder(bufio.NewReader(conn)).Decode(&ask); err != nil {
		s.log.Error("解析裁决请求失败，回发拒绝并丢弃该连接", "cause", err)
		_ = json.NewEncoder(conn).Encode(permDecision{Behavior: "deny", Message: "非法权限请求: " + err.Error()})
		_ = conn.Close()
		return
	}
	if ask.Type != "ask" || ask.ToolUseID == "" {
		s.log.Error("收到非法 ask 帧（缺 tool_use_id 或 type!=ask）", "type", ask.Type, "id", ask.ToolUseID)
		_ = json.NewEncoder(conn).Encode(permDecision{Behavior: "deny", Message: "缺少 tool_use_id 或非法类型"})
		_ = conn.Close()
		return
	}

	s.mu.Lock()
	if old, exists := s.pending[ask.ToolUseID]; exists {
		s.log.Info("tool_use_id 发生重连，关闭旧连接", "id", ask.ToolUseID)
		_ = old.Close()
	}
	s.pending[ask.ToolUseID] = conn
	s.mu.Unlock()

	s.log.Info("收到权限裁决请求", "tool_use_id", ask.ToolUseID, "tool", ask.ToolName)
	s.onAsk(permAsk{
		ToolUseID:	ask.ToolUseID,
		ToolName:	ask.ToolName,
		Input:		ask.Input,
	})

	go func(id string, c net.Conn) {
		buf := make([]byte, 1)
		for {
			if _, err := c.Read(buf); err != nil {
				s.mu.Lock()
				if cur, ok := s.pending[id]; ok && cur == c {
					delete(s.pending, id)
					s.log.Info("权限请求连接已断开，从待裁决表移除", "tool_use_id", id)
				}
				s.mu.Unlock()
				return
			}
		}
	}(ask.ToolUseID, conn)
}

n_agy_permServer_serve.signature:
func (s *permServer) serve() {
	for {
		conn, err := s.ln.Accept()
		if err != nil {
			s.mu.Lock()
			closed := s.closed
			s.mu.Unlock()
			if closed {
				return
			}
			s.log.Warn("接收裁决连接失败", "sock", s.sockPath, "cause", err)
			return
		}
		go s.handle(conn)
	}
}

n_agy_permTextAndRequest.signature:
func permTextAndRequest(toolName string, input json.RawMessage) (string, *executor.PermRequest) {
	switch strings.ToLower(toolName) {
	case "run_command":
		var in struct {
			CommandLine	string	`json:"CommandLine"`
			Command		string	`json:"command"`
		}
		if json.Unmarshal(input, &in) == nil {
			cmd := in.CommandLine
			if cmd == "" {
				cmd = in.Command
			}
			if cmd != "" {
				return "run_command: " + cmd, &executor.PermRequest{
					Tool:		executor.PermToolBash,
					Command:	cmd,
				}
			}
		}
	case "write_file", "write_to_file", "replace_file_content", "multi_replace_file_content", "sed_file":
		var in struct {
			TargetFile	string	`json:"TargetFile"`
			AbsolutePath	string	`json:"AbsolutePath"`
			FilePath	string	`json:"file_path"`
			Path		string	`json:"path"`
		}
		if json.Unmarshal(input, &in) == nil {
			p := in.TargetFile
			if p == "" {
				p = in.AbsolutePath
			}
			if p == "" {
				p = in.FilePath
			}
			if p == "" {
				p = in.Path
			}
			if p != "" {
				toolType := executor.PermToolWrite
				if strings.ToLower(toolName) != "write_to_file" && strings.ToLower(toolName) != "write_file" {
					toolType = executor.PermToolEdit
				}
				return fmt.Sprintf("%s: %s", toolName, p), &executor.PermRequest{
					Tool:	toolType,
					Paths:	[]string{p},
				}
			}
		}
	case "view_file", "read_file", "grep_search", "find_by_name", "list_dir":
		p := permPathFromInput(input, "AbsolutePath", "TargetFile", "SearchPath", "SearchDirectory", "DirectoryPath", "Path", "path")
		if p != "" {
			return fmt.Sprintf("%s: %s", toolName, p), &executor.PermRequest{
				Tool:	executor.PermToolEdit,
				Paths:	[]string{p},
			}
		}
	case "read_url_content", "search_web":
		var in struct {
			URL	string	`json:"Url"`
			Query	string	`json:"query"`
		}
		if json.Unmarshal(input, &in) == nil {
			arg := in.URL
			if arg == "" {
				arg = in.Query
			}
			if arg != "" {
				return fmt.Sprintf("%s: %s", toolName, arg), &executor.PermRequest{
					Tool: executor.PermToolWebFetch,
				}
			}
		}
	}
	text := fmt.Sprintf("%s: %s", toolName, turn.TruncateRunes(string(input), 200))
	return text, &executor.PermRequest{Tool: executor.PermToolOther}
}

n_agy_procExited.signature:
// procExited 检查 out.jsonl 是否出现死亡哨兵。
func procExited(outJSONLPath string) (exited bool, code int) {
	f, err := os.Open(outJSONLPath)
	if err != nil {
		return false, 0
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return false, 0
	}
	const scanBytes = 8 << 10
	offset := fi.Size() - scanBytes
	if offset < 0 {
		offset = 0
	}
	buf := make([]byte, fi.Size()-offset)
	if _, err := f.ReadAt(buf, offset); err != nil {
		return false, 0
	}
	for _, line := range strings.Split(string(buf), "\n") {
		if !strings.Contains(line, prochost.SentinelPrefix) {
			continue
		}
		var s struct {
			Code int `json:"code"`
		}
		_ = json.Unmarshal([]byte(line), &s)
		return true, s.Code
	}
	return false, 0
}

n_agy_readHooksRestoreState.signature:
func readHooksRestoreState(taskDir string) (hooksRestoreState, bool, error) {
	path := filepath.Join(taskDir, restoreFileName)
	data, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return hooksRestoreState{}, false, nil
	}
	if err != nil {
		return hooksRestoreState{}, true, fmt.Errorf("读取 %s: %w", path, err)
	}
	var state hooksRestoreState
	if err := json.Unmarshal(data, &state); err != nil {
		return hooksRestoreState{}, true, fmt.Errorf("解析 %s: %w", path, err)
	}
	return state, true, nil
}

