n_agy_removeGitExclude.signature:
func removeGitExclude(workdir, pattern string) error {
	excludePath, err := gitInfoExcludePath(workdir)
	if err != nil {
		return err
	}
	data, err := os.ReadFile(excludePath)
	if os.IsNotExist(err) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("读取 %s: %w", excludePath, err)
	}
	lines := strings.Split(string(data), "\n")
	kept := make([]string, 0, len(lines))
	removed := false
	for _, line := range lines {
		if strings.TrimSpace(line) == pattern {
			removed = true
			continue
		}
		kept = append(kept, line)
	}
	if !removed {
		return nil
	}
	if err := os.WriteFile(excludePath, []byte(strings.Join(kept, "\n")), 0644); err != nil {
		return fmt.Errorf("写回 %s: %w", excludePath, err)
	}
	return nil
}

n_agy_rotateOutJSONL.signature:
func rotateOutJSONL(taskDir string) error {
	oldPath := filepath.Join(taskDir, outFileName)
	if _, err := os.Stat(oldPath); os.IsNotExist(err) {
		return nil
	}
	ts := time.Now().Format("20060102-150405.000")
	newPath := filepath.Join(taskDir, fmt.Sprintf("out.%s.jsonl", ts))
	return os.Rename(oldPath, newPath)
}

n_agy_runState_captureStartCommit.signature:
