n_agy_runState_streamLoop.signature:
func (r *runState) streamLoop(a *Adapter) {
	defer func() {
		r.closeOnce.Do(r.closeEvents)
		select {
		case <-r.stopCh:
		default:
			a.drop(r.taskID)
		}
		a.log.Info("agy 事件流退出", "task", r.taskID)
	}()
	tl := newTailer(filepath.Join(r.taskDir, outFileName), r.startOffset, a.log)
	tl.rawTap = rawtap.Open("agy", r.taskID, a.log)
	var lastPersist time.Time
	err := tl.Run(r.runCtx, func(m streamMsg) {
		if now := time.Now(); now.Sub(lastPersist) >= persistOffsetEvery {
			if r.session != "" && r.proc != nil {
				if perr := writeProcInfo(r.taskDir, &procInfo{
					Handle:	r.proc.Handle, SessionID: r.session, Offset: tl.Offset(),
				}); perr != nil {
					a.log.Warn("持久化 agy offset 失败", "task", r.taskID, "cause", perr)
				}
				lastPersist = now
			}
		}
		a.mapMessage(r, m)
	})
	select {
	case <-r.stopCh:
		return
	default:
	}
	if r.exitHandled {
		return
	}
	tail := agyLogTail(r.taskDir)
	if err != nil {
		a.log.Error("agy 事件流损坏", "task", r.taskID, "cause", err)
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	false, SessionID: r.session,
			FailReason:	"agy 事件流损坏: " + turn.TailRunes(fmt.Sprint(err), 200),
		}})
		return
	}
	a.log.Warn("agy 事件流意外中断，按失败结束回合", "task", r.taskID, "stderr_tail", tail)
	a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
		OK:	false, SessionID: r.session,
		FailReason:	"agy 事件流意外中断: " + tail,
	}})
}

n_agy_tailer_Run.signature:
func (t *tailer) Run(ctx context.Context, onMsg func(streamMsg)) error {
	t.log.Info("tailer 启动", "path", t.path, "offset", t.Offset())
	defer t.rawTap.Close()
	garbage := 0
	for {
		adv, err := t.scanOnce(onMsg, &garbage)
		if err != nil {
			t.log.Error("流损坏，中止解析", "path", t.path, "garbage", garbage, "cause", err)
			return err
		}
		if adv == 0 {
			select {
			case <-ctx.Done():
				t.log.Info("tailer 退出", "path", t.path, "offset", t.Offset())
				return nil
			case <-time.After(tailPollInterval):
			}
		}
	}
}

n_agy_tailer_scanOnce.signature:
func (t *tailer) scanOnce(onMsg func(streamMsg), garbage *int) (int64, error) {
	f, err := os.Open(t.path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("打开 %s: %w", t.path, err)
	}
	defer f.Close()
	if _, err := f.Seek(t.offset.Load(), io.SeekStart); err != nil {
		return 0, fmt.Errorf("seek %s: %w", t.path, err)
	}
	r := bufio.NewReader(f)
	var consumed int64
	for {
		line, rerr := r.ReadBytes('\n')
		if len(line) == 0 {
			if rerr == io.EOF {
				break
			}
			if rerr != nil {
				return consumed, fmt.Errorf("读 %s: %w", t.path, rerr)
			}
			continue
		}
		if line[len(line)-1] != '\n' {
			break
		}
		consumed += int64(len(line))
		t.offset.Add(int64(len(line)))
		t.rawTap.Write(line)

		trimmed := bytes.TrimSpace(line)
		if len(trimmed) == 0 {
			continue
		}
		var msg streamMsg
		if err := json.Unmarshal(trimmed, &msg); err != nil {
			*garbage++
			t.log.Debug("跳过非 JSON 行", "path", t.path, "garbage", *garbage, "line", string(trimmed))
			if *garbage >= garbageLimit {
				return consumed, fmt.Errorf("连续 %d 行非 JSON 数据，流已损坏", *garbage)
			}
			continue
		}
		*garbage = 0
		onMsg(msg)
	}
	return consumed, nil
}

n_agy_updateHooksSkipWorktree.signature:
func updateHooksSkipWorktree(workdir string, skip bool) error {
	mode := "--no-skip-worktree"
	if skip {
		mode = "--skip-worktree"
	}
	path := filepath.ToSlash(filepath.Join(agentsDirName, hooksFileName))
	if out, err := exec.Command("git", "-C", workdir, "update-index", mode, "--", path).CombinedOutput(); err != nil {
		if text := strings.TrimSpace(string(out)); text != "" {
			return fmt.Errorf("git update-index %s: %w: %s", mode, err, text)
		}
		return fmt.Errorf("git update-index %s: %w", mode, err)
	}
	return nil
}

