n_buildinfo_Read.signature:
// Read 返回当前二进制的构建标识。
//
// 返回：
//   - ok=false：读不到构建信息（极少见，如用非 go 工具链链接的二进制）
//   - Revision 为空：不是 go build 产物（go run / 测试二进制），调用方应显示
//     「版本未知」而不是空字符串
func Read() (proto.BuildInfo, bool) {

	platform := runtime.GOOS + "/" + runtime.GOARCH
	bi, ok := readBuildInfo()
	if !ok {

		return proto.BuildInfo{Version: releaseVersion, Platform: platform}, false
	}

	version := releaseVersion
	if version == "" {
		version = moduleReleaseVersion(bi)
	}
	out := proto.BuildInfo{Go: bi.GoVersion, Version: version, Platform: platform}
	for _, s := range bi.Settings {
		switch s.Key {
		case "vcs.revision":
			out.Revision = s.Value
		case "vcs.time":
			out.Time = s.Value
		case "vcs.modified":

			out.Modified = s.Value == "true"
		}
	}

	if releaseRevision != "" {
		out.Revision = releaseRevision
		out.Modified = releaseModified == "true"

		if releaseTime != "" {
			out.Time = releaseTime
		}
	}
	return out, true
}

n_buildinfo_moduleReleaseVersion.signature:
// moduleReleaseVersion 从构建信息里取模块版本，仅当它是 release tag 形态时返回，
// 否则返回空串。
//
// why（为什么需要这条回落）：`go install github.com/Xsxdot/handoff@v0.2.3` 是
// 一条对外承诺的安装路径，而它永远不经过 release.yml 的 -X 注入。没有回落的话，
// 这样装的二进制版本恒为 unknown，升级巡检会永远劝它「需要升级」。
//
// why（为什么只认 vX.Y.Z）：Main.Version 还有另外两种取值，认了就会出错——
//   - 仓库内 go build 得到 "(devel)"：认了它，status 会拿 "(devel)" 顶掉
//     revision 展示，而本地构建恰恰只有 revision 有排障价值
//   - `@main` 之类得到 v0.0.0-<时间>-<sha> 伪版本：它在语义上恒小于任何真实
//     tag，认了就等于把开发版说成「比最新 release 旧的 release」，
//     巡检会据此劝人升级到一个他本来就领先的版本
func moduleReleaseVersion(bi *debug.BuildInfo) string {
	if bi == nil || !releaseTagRe.MatchString(bi.Main.Version) {
		return ""
	}
	return bi.Main.Version
}

n_claudecode_Adapter_DenyReasonInBand.signature:
// DenyReasonInBand 表明本 adapter 把拒绝理由与裁决同帧送达模型。
//
// 返回恒为 true：理由进 permDecision.Message，经裁决 socket 回到
// cmd/permission_mcp.go，再作为 tool_result 正文当场交给模型。
//
// manager 据此跳过 B50 的带外挂起注入——两条路都走会让模型被同一条理由说两遍。
func (a *Adapter) DenyReasonInBand() bool	{ return true }

n_claudecode_Adapter_Events.signature:
// Events 返回任务的事件流通道（Start 后可用；Stop 或执行终结后关闭）。
//
// 注意（P1-11 同款）：任务不在运行（未启动/已 Stop/运行态已随终结注销）时返回
// **已关闭的通道**而非 nil——契约是「通道关闭 = 执行终结」，nil 会让 for-range 永久阻塞。
func (a *Adapter) Events(taskID string) <-chan executor.AdapterEvent {
	if r := a.lookup(taskID); r != nil {
		return r.evCh
	}
	ch := make(chan executor.AdapterEvent)
	close(ch)
	return ch
}

n_claudecode_Adapter_Inspect.signature:
func (a *Adapter) Inspect(ctx context.Context, home string) ([]executor.SkillSite, error) {
	name := executor.SkillDirName("")
	site := filepath.Join(home, SkillsRelDir, name)
	target := filepath.Join(site, "SKILL.md")
	parent := filepath.Dir(filepath.Join(home, SkillsRelDir))
	if _, err := os.Stat(parent); errors.Is(err, os.ErrNotExist) {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
			Note:	parent + " 不存在（该 agent 未安装）",
		}}, nil
	}
	if _, err := os.Stat(target); errors.Is(err, os.ErrNotExist) {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
		}}, nil
	} else if err != nil {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
			Note:	"读取失败: " + err.Error(),
		}}, nil
	}
	return []executor.SkillSite{{
		Path:	target,
		State:	executor.SkillInstalled,
	}}, nil
}

n_claudecode_Adapter_Install.signature:
func (a *Adapter) Install(ctx context.Context, req executor.SkillInstallReq) ([]executor.SkillSite, error) {
	name := executor.SkillDirName(req.Name)
	dir := filepath.Join(req.Home, SkillsRelDir)
	parent := filepath.Dir(dir)
	if _, err := os.Stat(parent); err != nil {
		return []executor.SkillSite{{
			Path:	filepath.Join(dir, name),
			State:	executor.SkillSkipped,
			Note:	parent + " 不存在（该 agent 未安装）",
		}}, nil
	}
	site := filepath.Join(dir, name)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"创建目录失败: " + err.Error(),
		}}, nil
	}
	if err := os.RemoveAll(site); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"清理旧落点失败: " + err.Error(),
		}}, nil
	}
	if err := os.MkdirAll(site, 0o755); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"创建落点目录失败: " + err.Error(),
		}}, nil
	}
	if err := os.WriteFile(filepath.Join(site, "SKILL.md"), []byte(req.Content), 0o644); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"写落点副本失败: " + err.Error(),
		}}, nil
	}
	return []executor.SkillSite{{
		Path:	site,
		State:	executor.SkillInstalled,
	}}, nil
}

n_claudecode_Adapter_Invoke.signature:
