n_claudecode_Adapter_RespondPermission.signature:
// RespondPermission 把协调者的权限裁决回发到 perm.sock。
//
// 参数：
//   - permID: 与 permission 事件中的 PermissionID 一致（manager 还原后的裸 tool_use_id）
//   - decision: "once"（批准本次）或 "reject"（拒绝）
//   - reason: 协调者给出的拒绝理由；decision 为 reject 且理由非空时，经
//     permDecision.Message 与裁决同帧送达模型（见下方 DenyReasonInBand）
//
// 注意：
//   - decision 取值**除 once 外一律 deny**：不认识的裁决绝不当成放行
//     （与 manager 侧 gateDecision「allow 之外一律 reject」同一条纪律）
//   - 找不到挂起请求（进程已死 / 请求已被重试替换）时按 ErrTaskNotRunning 处置
func (a *Adapter) RespondPermission(ctx context.Context, taskID, permID, decision, reason string) (err error) {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	select {
	case <-r.stopCh:
		return fmt.Errorf("任务 %s 已停止，不能应答权限", taskID)
	default:
	}
	a.log.Info("claude adapter 收到权限应答", "task", taskID, "perm", permID, "decision", decision)
	defer func() {
		if err != nil {
			a.log.Error("claude adapter 权限应答转发失败", "task", taskID, "perm", permID, "cause", err)
		} else {
			a.log.Info("claude adapter 权限应答已转发", "task", taskID, "perm", permID)
		}
	}()
	if r.perm == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	behavior, msg := "allow", ""
	if decision != "once" {
		behavior = "deny"
		withReason := false

		if r := strings.TrimSpace(reason); r != "" {
			msg, withReason = turn.DenyGuidanceText(r), true
		} else {

			msg = "协调者拒绝了本次操作"
		}
		a.log.Info("claude 回发拒绝裁决", "task", taskID, "perm", permID,
			"with_reason", withReason)
	}
	if err := r.perm.Respond(permID, behavior, msg); err != nil {
		return err
	}

	a.log.Info("claude 权限等待结束", "task", taskID, "perm", permID)
	entries := r.seg.Resume(permID)
	if len(entries) == 0 {
		a.log.Warn("claude 权限应答成功但未找到等待窗口", "task", taskID, "perm", permID)
	} else {
		a.reportTiming(r, entries)
	}
	return nil
}

n_claudecode_Adapter_Resume.signature:
// Resume 恢复 agentd 重启前已在执行的任务（manager 的 restorer 可选接口）。
//
// 存活判据（本 adapter 与 opencode 的关键差异）：prochost 的存活锁**不够**——
// claude 自己退出后 shim 会写哨兵再退出，锁与哨兵之间有一个极短窗口锁还在但
// 进程已死（opencode 靠 HTTP 探活兜住这一点，claude 没有这个面）。统一走
// Proc.Alive()：存活锁被持有 **且** out.jsonl 无 handoff_exit 哨兵，缺一即死。
//
// 参数：
//   - req: 恢复请求（TaskDir 是 proc.json 所在，即 DataDir/tasks/<id>；
//     RepoPath 用于重启后重新捕获 git 兜底分类的起点 commit 基线；
//     SessionID 是落库的 claude 会话 id）
//
// 返回：
//   - Alive=false 时调用方（manager）把任务转 failed 交协调者裁决（保守优于静默）
//   - err: 重建失败（proc.json 缺失/损坏、SessionID 为空），视为不可恢复
//
// 注意：
//   - 恢复出的运行态与 Start 对称：Stop（done 归档）对其同样有效
//   - 挂起权限不需要在此重建应答：MCP 子进程（claude 拉起的）会自行重连
//     perm.sock 重登记同一 tool_use_id，manager 侧 ticket 按 id 幂等去重
func (a *Adapter) Resume(req executor.ResumeReq) (out executor.ResumeOutcome, err error) {
	a.log.Info("claude adapter 恢复任务执行", "task", req.TaskID, "session", req.SessionID)
	defer func() {
		if err != nil {
			a.log.Error("claude adapter 恢复任务失败", "task", req.TaskID, "cause", err)
		} else if out.Alive {
			a.log.Info("claude adapter 任务已恢复", "task", req.TaskID, "session", out.SessionID)
		}
	}()

	if req.SessionID == "" {
		return executor.ResumeOutcome{}, fmt.Errorf("任务 %s 缺 executor_session，无法重建订阅", req.TaskID)
	}

	a.mu.Lock()
	if _, busy := a.runs[req.TaskID]; busy {
		a.mu.Unlock()
		a.log.Info("该任务已有运行态或恢复进行中，跳过本次恢复", "task", req.TaskID)
		return executor.ResumeOutcome{Alive: false, Note: "该任务的恢复正在进行中"}, nil
	}
	a.runs[req.TaskID] = &runState{taskID: req.TaskID}
	a.mu.Unlock()
	defer func() {

		a.mu.Lock()
		if cur, ok := a.runs[req.TaskID]; ok && cur.evCh == nil {
			delete(a.runs, req.TaskID)
		}
		a.mu.Unlock()
	}()

	pi, err := readProcInfo(req.TaskDir)
	if err != nil {
		return executor.ResumeOutcome{}, err
	}
	proc := &Proc{Handle: pi.Handle, TaskDir: req.TaskDir, SessionID: req.SessionID}

	mode := executor.ResumeModeReattach
	dead := !proc.Alive()
	if dead {
		if exited, code := procExited(filepath.Join(req.TaskDir, outFileName)); exited {
			a.log.Info("恢复探活失败：claude 已退出（哨兵）", "task", req.TaskID,
				"shim_pid", pi.Handle.PID, "code", code)
		} else {
			a.log.Info("恢复探活失败：存活锁已释放", "task", req.TaskID, "shim_pid", pi.Handle.PID)
		}

		if kerr := proc.Kill(); kerr != nil {
			a.log.Warn("回收已死执行者失败", "task", req.TaskID, "cause", kerr)
		}
		if !req.Cold {
			return executor.ResumeOutcome{Alive: false,
				Note:	"claude 进程已不在（本次只允许热重连）"}, nil
		}

		if _, serr := os.Stat(req.TaskDir); serr != nil {
			a.log.Info("任务目录已不存在，判不可恢复", "task", req.TaskID, "cause", serr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务目录已不存在（可能已归档清理），无法恢复"}, nil
		}
		if _, rerr := os.Stat(req.RepoPath); rerr != nil {
			a.log.Info("任务工作区已不存在，判不可恢复", "task", req.TaskID, "cause", rerr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务工作区已不存在（可能已归档清理），无法恢复"}, nil
		}

		if rerr := rotateOutJSONL(req.TaskDir); rerr != nil {
			a.log.Warn("轮转 out.jsonl 失败，仍尝试冷恢复", "task", req.TaskID, "cause", rerr)
		}
		a.log.Info("claude 已不在，进入冷恢复", "task", req.TaskID, "session", req.SessionID)
		tmpDir, managedEnv := managedTaskTmpEnv(req.TaskDir, req.TaskID)
		if err := ensureTaskTmp(req.TaskID, tmpDir, a.log); err != nil {
			return executor.ResumeOutcome{}, fmt.Errorf("创建任务临时目录 %s: %w", tmpDir, err)
		}
		env := append(append([]string{}, req.Env...), managedEnv...)
		newProc, err := startProc(context.Background(), StartProcReq{

			RepoPath:	req.RepoPath, TaskID: req.TaskID, TaskDir: req.TaskDir,
			SessionID:	req.SessionID, Model: req.Model,
			SettingsPath:	filepath.Join(req.TaskDir, settingsFileName),
			MCPPath:	filepath.Join(req.TaskDir, mcpFileName),
			Env:		env, MarkRoot: req.MarkRoot, Resume: true,
		}, a.log)
		if err != nil {
			a.log.Warn("冷恢复重起 claude 失败，判不可恢复", "task", req.TaskID, "cause", err)
			return executor.ResumeOutcome{Alive: false,
				Note:	fmt.Sprintf("重起 claude 失败：%v", err)}, nil
		}
		proc = newProc
		mode = executor.ResumeModeCold
	}

	r := a.newRun(req.TaskID, req.TaskDir, req.RepoPath)
	r.session = req.SessionID
	r.proc = proc
	if mode == executor.ResumeModeCold {
		r.startOffset = 0
	} else {
		r.startOffset = pi.Offset
	}
	perm, err := newPermServerFn(filepath.Join(req.TaskDir, sockFileName), a.log,
		func(ask permAsk) { a.onPermissionAsk(r, ask) })
	if err != nil {
		a.drop(req.TaskID)
		return executor.ResumeOutcome{}, err
	}
	r.perm = perm
	r.captureStartCommit(a)
	go r.streamLoop(a)
	go a.watchdog(r)
	return executor.ResumeOutcome{
		Alive:	true, Mode: mode, SessionID: req.SessionID,
		Note:	resumeNote(mode, req.SessionID),
	}, nil
}

n_claudecode_Adapter_Send.signature:
// Send 往同一会话续发指令（fifo 续接：上下文完整保留）。
//
// 参数：
//   - text: 协调者的回答/修改指令，原样透传，不得加工
//
// 注意：
//   - 进程不在（fifo 无读端，O_NONBLOCK 打开失败）时包装 executor.ErrTaskNotRunning
func (a *Adapter) Send(ctx context.Context, taskID, text string) (err error) {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	select {
	case <-r.stopCh:
		return fmt.Errorf("任务 %s 已停止，不能续接", taskID)
	default:
	}
	a.log.Info("claude adapter 收到续接指令", "task", taskID, "text", turn.TruncateRunes(text, 80))
	defer func() {
		if err != nil {
			a.log.Error("claude adapter 续接指令发送失败", "task", taskID, "cause", err)
		} else {
			a.log.Info("claude adapter 续接指令已发送", "task", taskID)
		}
	}()
	if r.proc == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	if err := r.frames.BeginTurn("send", text); err != nil {
		a.log.Warn("写 turn_start 帧失败，不影响回合", "task", taskID, "cause", err)
	}
	a.reportTiming(r, r.seg.BeginTurn(r.frames.Turn()))
	r.textPart = r.frames.NextPart()
	if err := r.proc.WriteInput(text); err != nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	return nil
}

n_claudecode_Adapter_Start.signature:
// Start 按「perm server → 任务物料 → prochost 进程 → 等 init → 投首回合 prompt →
// 会话就绪」流程启动任务执行并立即返回。
//
// 参数：
//   - ctx: 控制启动阶段的超时/取消（prochost 拉起、等 init 受其约束）；
//     不代表执行生命周期（执行延续到 Stop）
//   - req: 任务快照、计划原文与任务工作目录
//
// 返回：
//   - 任一启动阶段失败返回错误，调用方（manager）应把任务标记 failed
//
// 注意：
//   - 已建资源（perm server / 执行者进程）在失败时逐级回滚，避免半启动残留
//   - req.Env 必须原样透传进 StartProc（B19）：漏传编译照过、用户 env 静默失效
func (a *Adapter) Start(ctx context.Context, req executor.StartReq) (err error) {
	a.log.Info("claude adapter 开始启动任务", "task", req.Task.ID,
		"task_dir", req.TaskDir, "workdir", req.Task.Workdir())
	defer func() {
		if err != nil {
			a.log.Error("claude adapter 启动任务失败", "task", req.Task.ID, "cause", err)
		}
	}()

	sessionID := uuid.NewString()
	sockPath := filepath.Join(req.TaskDir, sockFileName)
	r := a.newRun(req.Task.ID, req.TaskDir, req.Task.Workdir())
	if err := r.frames.BeginTurn("dispatch", ""); err != nil {
		a.log.Warn("写 turn_start 帧失败，不影响回合", "task", req.Task.ID, "cause", err)
	}
	a.reportTiming(r, r.seg.BeginTurn(r.frames.Turn()))
	r.textPart = r.frames.NextPart()
	r.session = sessionID

	rollback := func() {
		if r.perm != nil {
			r.perm.Close()
		}
		if r.proc != nil {
			r.proc.Kill()
		}
		r.runCancel()
		a.drop(req.Task.ID)
	}

	perm, err := newPermServerFn(sockPath, a.log, func(ask permAsk) { a.onPermissionAsk(r, ask) })
	if err != nil {
		return err
	}
	r.perm = perm

	bin, err := os.Executable()
	if err != nil {
		rollback()
		return fmt.Errorf("定位 handoff 二进制: %w", err)
	}
	var snap executor.PolicySnapshot
	if req.Approval != nil {
		s, serr := req.Approval.PolicySnapshot(ctx)
		if serr != nil {
			rollback()
			return fmt.Errorf("读取政策快照: %w", serr)
		}
		snap = s
		a.log.Info("claude 使用政策快照", "task", req.Task.ID, "version", snap.Version)
	}
	settingsPath, mcpPath, promptText, err := WriteTaskEnv(req.TaskDir, req.Task.ID, req.PlanContent, sockPath, bin, req.Discipline, snap)
	if err != nil {
		rollback()
		return err
	}
	if strings.TrimSpace(req.Discipline) == "" {
		a.log.Info("claude 未注入纪律块", "task", req.Task.ID)
	} else {
		a.log.Info("claude 纪律块已注入 prompt", "task", req.Task.ID, "bytes", len(req.Discipline))
	}

	tmpDir, managedEnv := managedTaskTmpEnv(req.TaskDir, req.Task.ID)
	if err := ensureTaskTmp(req.Task.ID, tmpDir, a.log); err != nil {
		rollback()
		return fmt.Errorf("创建任务临时目录 %s: %w", tmpDir, err)
	}
	env := append(append([]string{}, req.Env...), managedEnv...)
	proc, err := startProc(ctx, StartProcReq{
		RepoPath:	req.Task.Workdir(),
		TaskID:		req.Task.ID,
		TaskDir:	req.TaskDir,
		SessionID:	sessionID,
		Model:		req.Task.Model,
		SettingsPath:	settingsPath,
		MCPPath:	mcpPath,
		Env:		env,
		MarkRoot:	prochost.ResolveMarkRoot(req.Task.Workdir(), req.Task.WorktreeManaged),
	}, a.log)
	if err != nil {
		rollback()
		return err
	}
	r.proc = proc

	go r.streamLoop(a)
	go a.watchdog(r)

	if err := proc.WriteInput(promptText); err != nil {
		rollback()
		return fmt.Errorf("投递首回合 prompt: %w", err)
	}
	a.log.Info("claude 初始 prompt 已投递", "task", req.Task.ID, "prompt_len", len(promptText))

	select {
	case <-r.ready:
		a.log.Info("claude 就绪", "task", req.Task.ID, "session", r.session)
	case <-time.After(startReadyTimeout):
		tail := claudeLogTail(req.TaskDir)
		rollback()
		a.log.Error("claude 就绪超时", "task", req.Task.ID, "stderr_tail", tail)
		return fmt.Errorf("claude 就绪超时（%s）: %s", startReadyTimeout, tail)
	case <-ctx.Done():
		rollback()
		return fmt.Errorf("启动被取消: %w", ctx.Err())
	}

	r.captureStartCommit(a)
	a.emit(r, executor.AdapterEvent{Type: "progress", SessionID: sessionID, Text: "会话就绪"})
	return nil
}

n_claudecode_Adapter_Stop.signature:
// Stop 终止任务执行：停 socket 受理 → 回收执行者进程组 → 事件通道关闭 → 注销运行态。
//
// 注意：
//   - 幂等：重复 Stop 不 panic；事件通道只关闭一次（由 streamLoop 的 defer 持有关闭权）
//   - kill 失败时仍注销运行态（claude 没有 opencode 那类必须保句柄的端口/凭据回收场景，
//     进程残留由 handoff stop 兜底，与 opencode Kill 同规则）
func (a *Adapter) Stop(taskID string) (err error) {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	a.log.Info("claude adapter 停止任务", "task", taskID)
	defer func() {
		if err != nil {
			a.log.Error("claude adapter 停止任务失败", "task", taskID, "cause", err)
		} else {
			a.log.Info("claude adapter 任务已停止", "task", taskID)
		}
	}()

	r.stopOnce.Do(func() {
		close(r.stopCh)
		r.runCancel()
	})
	if r.perm != nil {
		r.perm.Close()
	}
	if r.proc != nil {
		if kerr := r.proc.Kill(); kerr != nil {
			return kerr
		}
	}
	a.drop(taskID)
	return nil
}

n_claudecode_Adapter_Verify.signature:
// Verify 校验 Claude Code 规则落点；Keychain 凭据不伪造为文件同步成功。
func (a *Adapter) Verify(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	return a.Profile().Verify(ctx, req)
}

n_claudecode_Adapter_appendActionSummary.signature:
// appendActionSummary 往 render.log 追加一行工具动作摘要（render 流的旁观内容），
// 并落一条 tool_call 帧。
//
// toolUseID 用作帧的 part：user 消息里的 tool_result 带同值的 tool_use_id，
// 两条帧因此天然配对，不需要本地再维护一张映射表。
func (a *Adapter) appendActionSummary(r *runState, toolUseID, toolName string, input json.RawMessage) {
	line := "→ " + toolName
	if toolName == "Bash" {
		var in struct {
			Command string `json:"command"`
		}
		if json.Unmarshal(input, &in) == nil && in.Command != "" {
			line += ": " + firstLine(in.Command)
		}
	} else {
		line += ": " + compactJSON(input)
	}
	if err := turn.AppendRender(r.renderPath, "\n"+line+"\n"); err != nil {
		a.log.Warn("追加 render.log 失败", "task", r.taskID, "cause", err)
	}

	a.reportTiming(r, r.seg.ToolStart(toolUseID, toolName, timingDetail(toolName, input)))

	if err := r.frames.ToolCall(toolUseID, toolName, string(input)); err != nil {
		a.log.Warn("写 tool_call 帧失败，不影响回合", "task", r.taskID, "cause", err)
	}
}

n_claudecode_Adapter_drop.signature:
// drop 注销一个任务的运行态（启动失败清理用）。
func (a *Adapter) drop(taskID string) {
	a.mu.Lock()
	defer a.mu.Unlock()
	delete(a.runs, taskID)
}

n_claudecode_Adapter_emit.signature:
// emit 向事件通道投递一条 AdapterEvent 并打产出日志（所有事件统一的出口）。
//
// 并发：streamLoop 与可能并发触发的应答路径（本实现中仅 streamLoop）写通道，
// 统一由 emitMu 串行化，evClosed 使关闭后的迟到投递静默丢弃而非 panic。
func (a *Adapter) emit(r *runState, ev executor.AdapterEvent) bool {
	switch ev.Type {
	case "permission":
		a.log.Info("claude 产出权限事件", "task", r.taskID, "type", ev.Type,
			"perm", ev.PermissionID, "text", turn.TruncateRunes(ev.Text, 120))
	case "question":
		a.log.Info("claude 产出提问事件", "task", r.taskID, "type", ev.Type,
			"text", turn.TruncateRunes(ev.Text, 80))
	case "progress":
		a.log.Info("claude 产出进度事件", "task", r.taskID, "type", ev.Type,
			"text", turn.TruncateRunes(ev.Text, 80))
	case "result":
		ok := ev.Result != nil && ev.Result.OK
		a.log.Info("claude 产出结果事件", "task", r.taskID, "type", ev.Type, "ok", ok)
	case "usage":

	default:
		a.log.Info("claude 产出未知事件", "task", r.taskID, "type", ev.Type)
	}
	r.emitMu.Lock()
	defer r.emitMu.Unlock()
	if r.evClosed {
		a.log.Debug("事件通道已关闭，丢弃迟到事件", "task", r.taskID, "type", ev.Type)
		return false
	}
	select {
	case r.evCh <- ev:
		return true
	case <-r.stopCh:
		return false
	}
}

n_claudecode_Adapter_fallbackClassify.signature:
// fallbackClassify 是「模型未按纪律输出协议 trailer」的兜底分类。
//
// why（兜底分类规则）：回合结束但 turn.ParseTrailer 判 none。此时拿 git 实况裁决：
//   - 相对回合起点有新 commit → 发 result{OK:false}（B74）。**不替模型宣布完成**：
//     模型没说完成，handoff 就不说。翻转不给协调者加任何一次操作——OK 与 !OK
//     都落 waiting_review，done 与 continue 在那里都合法；变的只是事件从
//     「已完成，摘要如下」变成「有新提交，但模型未按纪律宣布完成」。
//   - 没有新 commit / git 查询失败 → 把回合全文交协调者裁决（question），流程不卡死；
//     其中零文本回合没有内容可问，是故障报告，转 result{OK:false}。
func (a *Adapter) fallbackClassify(r *runState, text string) {
	a.log.Warn("回合未输出协议 trailer，走 git 兜底", "task", r.taskID,
		"turn_tail", turn.TailRunes(text, 120))
	branch, commit, hasNew, err := turn.GitTurnStatus(r.repoPath, r.startCommit)
	if err != nil || !hasNew {
		if err != nil {
			a.log.Error("git 兜底查询失败", "task", r.taskID, "cause", err)
		}
		a.log.Info("兜底判定无新提交，转提问交协调者裁决", "task", r.taskID, "has_new", hasNew)

		if strings.TrimSpace(text) == "" {
			a.log.Warn("回合零文本且无新提交，转失败结果交协调者", "task", r.taskID)
			a.emit(r, executor.AdapterEvent{Type: "result", SessionID: r.session,
				Result: &executor.Result{OK: false, SessionID: r.session,
					FailReason:	"回合结束但零文本产出（可能是供应商流中断）；executor 仍在线，可 continue 续接重试",

					VoidReason:	executor.VoidReasonTurnDiscipline}})
			return
		}
		a.emit(r, executor.AdapterEvent{Type: "question", Text: turn.ClampQuestion(text)})
		return
	}
	a.log.Warn("兜底判定有新提交，但模型未宣布完成，转失败交协调者裁决",
		"task", r.taskID, "branch", branch, "commit", commit)
	a.emit(r, executor.AdapterEvent{Type: "result",
		Result:	turn.NoTrailerResult(r.session, branch, commit, text)})
}

n_claudecode_Adapter_lookup.signature:
// lookup 按任务 id 取运行态。
func (a *Adapter) lookup(taskID string) *runState {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.runs[taskID]
}

n_claudecode_Adapter_mapAssistant.signature:
// mapAssistant 处理 assistant 整块消息：text 块做回合文本累积（供收尾分类与
// progress），tool_use 块往 render.log 追加动作摘要。
//
// why（text 块不重复追加 render.log）：render.log 已由 text_delta 增量写过，
// 整块再写会出两遍正文；这里只累积进 turnBuf 供分类用。
func (a *Adapter) mapAssistant(r *runState, msg json.RawMessage) {

	if model, u, ok := parseAssistantUsage(msg); ok && (model != "" || u != nil) {
		if model != "" {
			r.actualModel = model
		}
		if u != nil && r.ctxWindow > 0 {
			w := r.ctxWindow
			u.ContextWindow = &w
		}
		a.emit(r, executor.AdapterEvent{Type: "usage", ActualModel: model, Usage: u})
	}
	var m struct {
		Content []struct {
			Type	string		`json:"type"`
			Text	string		`json:"text"`
			ID	string		`json:"id"`
			Name	string		`json:"name"`
			Input	json.RawMessage	`json:"input"`
		} `json:"content"`
	}
	if err := json.Unmarshal(msg, &m); err != nil {
		a.log.Debug("assistant 消息解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	for _, block := range m.Content {
		switch block.Type {
		case "text":
			if block.Text == "" {
				continue
			}
			r.turnMu.Lock()
			r.turnBuf.WriteString(block.Text)
			r.turnMu.Unlock()
			a.maybeProgress(r)
		case "tool_use":
			a.appendActionSummary(r, block.ID, block.Name, block.Input)
		}
	}
}

n_claudecode_Adapter_mapExit.signature:
// mapExit 处理死亡哨兵：code=0 且本回合已收尾视为正常终结（result 已产出，
// 不再产事件）；否则按失败结束，FailReason 带退出码与 claude.log 尾部。
func (a *Adapter) mapExit(r *runState, m streamMsg) {
	if m.ExitCode == 0 && r.turnEnded {
		a.log.Info("claude 进程正常退出（回合已收尾）", "task", r.taskID, "code", m.ExitCode)
	} else {
		tail := claudeLogTail(r.taskDir)
		a.log.Error("claude 进程退出", "task", r.taskID, "code", m.ExitCode, "stderr_tail", tail)
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	false, SessionID: r.session,
			FailReason:	fmt.Sprintf("claude 进程退出（code=%d）: %s", m.ExitCode, tail),
		}})
	}

	r.exitHandled = true
	if r.proc != nil {
		if kerr := r.proc.Kill(); kerr != nil {
			a.log.Warn("哨兵后回收执行者进程失败", "task", r.taskID, "cause", kerr)
		}
	}
	r.runCancel()
}

n_claudecode_Adapter_mapResult.signature:
// mapResult 处理回合收尾：result.result 是最后一条 assistant 正文，正是
// turn.ParseTrailer 的输入；subtype!=success 时按失败处理（带 claude.log 尾部）。
func (a *Adapter) mapResult(r *runState, m streamMsg) {

	a.reportTiming(r, r.seg.EndTurn())

	w, confident := pickModelUsageWindow(m.ModelUsage, r.actualModel)
	if !confident {
		a.log.Warn("claude result 多模型且都匹配不上已知模型，取了任意一个的窗口",
			"task", r.taskID, "window", w)
	}
	r.ctxWindow = w

	if e, next, ok := parseResultSpend(m, r.prevCostUSD); ok {
		if m.TotalCostUSD < r.prevCostUSD {
			a.log.Warn("claude 花费基线陈旧，本轮按当前值入账",
				"task", r.taskID, "prev", r.prevCostUSD, "now", m.TotalCostUSD)
		}
		r.prevCostUSD = next
		a.emit(r, executor.AdapterEvent{Type: "usage", Spend: &e})
	} else {
		a.log.Debug("claude result 行不带可入账的消耗，跳过", "task", r.taskID, "uuid", m.UUID)
	}
	if m.Subtype != "success" || m.IsError {
		tail := claudeLogTail(r.taskDir)
		a.log.Error("claude 回合异常结束", "task", r.taskID, "subtype", m.Subtype, "stderr_tail", tail)
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	false, SessionID: r.session,
			FailReason:	"claude 回合异常结束（subtype=" + m.Subtype + "）: " + tail,
		}})
		r.turnEnded = true
		return
	}
	text := m.Result
	if strings.TrimSpace(text) == "" {
		r.turnMu.Lock()
		text = r.turnBuf.String()
		r.turnMu.Unlock()
	}
	kind, tr := turn.ParseTrailer(text)
	a.log.Info("claude 回合收尾", "task", r.taskID, "kind", kind,
		"final_text_len", len([]rune(text)))
	switch kind {
	case "ask":
		a.emit(r, executor.AdapterEvent{Type: "question", Text: turn.ClampQuestion(tr.Question)})
	case "finish":
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	true, Branch: tr.Branch, CommitHash: tr.Commit,
			Summary:	tr.Summary, SessionID: r.session,
			FinalText:	turn.FinalText(text),
		}})
	default:
		a.fallbackClassify(r, text)
	}
	r.clearTurn()

	r.captureStartCommit(a)
	r.turnEnded = true
}

n_claudecode_Adapter_mapStreamEvent.signature:
// mapStreamEvent 处理流式增量：text_delta 追加 render.log（实况流式来源），
// 不产生 AdapterEvent（spec §4.2）；thinking_delta 被 textDelta 过滤掉，
// 但会单独落一条 reasoning 帧（W4a：隔离从「丢弃」改成「分流」）。
//
// 隔离不变式：thinking 内容只走 r.frames，绝不进 render.log、绝不进 turnBuf，
// 因此绝不喂 turn.ParseTrailer、绝不进权限闸。
func (a *Adapter) mapStreamEvent(r *runState, ev json.RawMessage) {
	text, reasoning := splitDelta(ev)
	if reasoning != "" {
		if err := r.frames.Reasoning(r.textPart, reasoning); err != nil {
			a.log.Warn("写 reasoning 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
		return
	}
	if text == "" {
		return
	}
	if err := turn.AppendRender(r.renderPath, text); err != nil {
		a.log.Warn("追加 render.log 失败", "task", r.taskID, "cause", err)
	}
	if err := r.frames.Text(r.textPart, text); err != nil {
		a.log.Warn("写 text 帧失败，不影响回合", "task", r.taskID, "cause", err)
	}
}

n_claudecode_Adapter_mapUserMessage.signature:
// mapUserMessage 处理 user 消息：tool_result 块往 render.log 追加结果摘要，
// 并落一条 tool_result 帧（part 取 tool_use_id，与 tool_call 帧配对）。
func (a *Adapter) mapUserMessage(r *runState, msg json.RawMessage) {
	var m struct {
		Content []struct {
			Type		string		`json:"type"`
			ToolUseID	string		`json:"tool_use_id"`
			IsError		bool		`json:"is_error"`
			Content		json.RawMessage	`json:"content"`
		} `json:"content"`
	}
	if err := json.Unmarshal(msg, &m); err != nil {
		a.log.Debug("user 消息解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	for _, block := range m.Content {
		if block.Type != "tool_result" {
			continue
		}
		summary := compactJSON(block.Content)
		if s, ok := jsonString(block.Content); ok {
			summary = firstLine(s)
		}
		line := "↩ " + turn.TruncateRunes(summary, 200)
		if err := turn.AppendRender(r.renderPath, "\n"+line+"\n"); err != nil {
			a.log.Warn("追加 render.log 失败", "task", r.taskID, "cause", err)
		}

		full := compactJSON(block.Content)
		if s, ok := jsonString(block.Content); ok {
			full = s
		}
		status := "ok"
		if block.IsError {
			status = "error"
		}

		dur, entries := r.seg.ToolEnd(block.ToolUseID)
		if err := r.frames.ToolResult(block.ToolUseID, status, full, dur); err != nil {
			a.log.Warn("写 tool_result 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
		a.reportTiming(r, entries)
	}
}

n_claudecode_Adapter_maybeProgress.signature:
// maybeProgress 节流发 progress：每任务至多每 progressThrottle 一条（与 opencode 同款）。
func (a *Adapter) maybeProgress(r *runState) {
	now := time.Now()
	if now.Sub(r.lastProgress) < progressThrottle {
		return
	}
	r.lastProgress = now
	r.turnMu.Lock()
	text := r.turnBuf.String()
	r.turnMu.Unlock()
	a.emit(r, executor.AdapterEvent{Type: "progress", Text: turn.TailRunes(text, 200)})
}

n_claudecode_Adapter_newRun.signature:
// newRun 创建并登记一个任务的运行态。
func (a *Adapter) newRun(taskID, taskDir, repoPath string) *runState {
	r := &runState{
		taskID:		taskID,
		taskDir:	taskDir,
		repoPath:	repoPath,
		evCh:		make(chan executor.AdapterEvent, 16),
		stopCh:		make(chan struct{}),
		renderPath:	filepath.Join(taskDir, renderFileName),
		ready:		make(chan struct{}),
	}

	fw, err := turn.WriterFor(taskDir, a.log)
	if err != nil {
		a.log.Warn("创建帧写入器失败，本任务无结构化帧", "task", taskID, "cause", err)
	}
	r.frames = fw

	r.seg = turn.NewSegmenter(nil)
	r.runCtx, r.runCancel = context.WithCancel(context.Background())
	a.mu.Lock()
	a.runs[taskID] = r
	a.mu.Unlock()
	return r
}

n_claudecode_Adapter_onPermissionAsk.signature:
// onPermissionAsk 把 perm.sock 的 ask 请求转成 permission 事件。
//
// Text = "<ToolName>: <关键入参>"：Bash 取 command，Edit/Write 取 file_path，
// 其余取 input 的紧凑 JSON。**不在本层做展示级截断**（黑名单扫描/模型审批/工单
// 全文都以 Text 为真相源），只有 64KB 防失控硬上限；空描述给兜底文本。
func (a *Adapter) onPermissionAsk(r *runState, ask permAsk) {
	text, req := permTextAndRequest(ask.ToolName, ask.Input)
	if strings.TrimSpace(text) == "" {
		a.log.Warn("claude 权限请求无可读描述，按未说明权限交协调者",
			"task", r.taskID, "perm", ask.ToolUseID)
		text = "claude 未提供可读描述（tool_use_id " + ask.ToolUseID + "），请 handoff attach 查看现场"
	}
	if req == nil {

		a.log.Warn("claude 权限请求提取不出结构化载荷，将由 manager 升级人工",
			"task", r.taskID, "perm", ask.ToolUseID, "tool", ask.ToolName)
	}
	if ask.ToolUseID == "" {
		a.log.Warn("claude 权限请求缺少工具配对键，不暂停耗时窗口",
			"task", r.taskID, "tool", ask.ToolName)
	} else {
		a.log.Info("claude 权限等待开始", "task", r.taskID, "perm", ask.ToolUseID)
		entries := r.seg.PauseWaiting(ask.ToolUseID)
		if len(entries) == 0 {
			a.log.Warn("claude 权限请求未找到对应工具等待窗口",
				"task", r.taskID, "perm", ask.ToolUseID, "tool", ask.ToolName)
		} else {
			a.reportTiming(r, entries)
		}
	}
	a.emit(r, executor.AdapterEvent{
		Type:	"permission", PermissionID: ask.ToolUseID,
		Text:	turn.TruncateMarked(text, permTextHardLimit),
		Perm:	req,
	})
}

n_claudecode_Adapter_reportTiming.signature:
// reportTiming 把段切分器产出的条目逐条经 usage 事件上报。
//
// 为什么走 usage 而不是新事件类型：Usage（当前占用）、Spend（累计消耗）与
// Timing（耗时）是同一次模型调用结束时的三样产物；拆成两个事件，两者之间
// 就能插进一次 agentd 重启（契约文档 §6.3 的拍板记录）。
//
// entries 为空是常态（不是错误），静默返回。
func (a *Adapter) reportTiming(r *runState, entries []proto.TimingEntry) {
	for i := range entries {
		e := entries[i]
		if !a.emit(r, executor.AdapterEvent{Type: "usage", Timing: &e}) {

			a.log.Debug("耗时条目未能上报（事件通道已终止）",
				"task", r.taskID, "key", e.Key, "remaining", len(entries)-i)
			return
		}
	}
}

n_claudecode_Adapter_watchdog.signature:
// watchdog 是 claude 存活兜底看门狗：周期探活（存活锁 + 无哨兵），连续
// watchdogFailThreshold 次失败判定死亡，取消运行 ctx 让 streamLoop 退出——
// failed 结果由 streamLoop 统一产出（哨兵路径则由 mapExit 产出），保持
// 「事件通道只有一个写入者」的关闭权约定。
func (a *Adapter) watchdog(r *runState) {
	failures := 0
	ticker := time.NewTicker(watchdogInterval)
	defer ticker.Stop()
	for {
		select {
		case <-r.stopCh:
			return
		case <-r.runCtx.Done():
			return
		case <-ticker.C:
			if r.proc != nil && r.proc.Alive() {
				failures = 0
				continue
			}
			failures++
			if failures >= watchdogFailThreshold {
				a.log.Error("claude 探活失败达阈值，判定死亡", "task", r.taskID, "failures", failures)
				r.runCancel()
				return
			}
		}
	}
}

n_claudecode_New.signature:
// New 创建 claude adapter。
//
// 参数：
//   - log: 本模块日志入口（nil 时退回 slog.Default()）
func New(log *slog.Logger) *Adapter {
	if log == nil {
		log = slog.Default()
	}
	return &Adapter{log: log, runs: make(map[string]*runState)}
}

n_claudecode_NewOneShot.signature:
func NewOneShot(log *slog.Logger) *OneShot {
	if log == nil {
		log = slog.Default()
	}
	return &OneShot{log: log}
}

n_claudecode_OneShotArgv.signature:
// OneShotArgv 编码 claude 一次性调用的 argv。
func OneShotArgv(model, prompt string, _ executor.OneShotLimits) ([]string, error) {
	if model != "" {
		return []string{"claude", "-p", "--model", model, prompt}, nil
	}
	return []string{"claude", "-p", prompt}, nil
}

n_claudecode_OneShot_Invoke.signature:
func (s *OneShot) Invoke(ctx context.Context, req executor.OneShotReq) (executor.OneShotReply, error) {
	s.log.Info("OneShot.Invoke 进入", "harness", executor.HarnessClaude, "model", req.Model, "prompt_bytes", len(req.Prompt), "effort", req.Limits.Effort)
	argv, err := OneShotArgv(req.Model, req.Prompt, req.Limits)
	if err != nil {
		s.log.Error("OneShot argv 编码失败", "cause", err)
		return executor.OneShotReply{Status: executor.OneShotFailed}, err
	}
	out, err := executor.RunOneShotProcess(ctx, argv, req.Env, req.Workdir, req.HomeDir)
	if ctx.Err() != nil {
		s.log.Info("OneShot 已取消", "cause", ctx.Err())
		return executor.OneShotReply{Text: out, Status: executor.OneShotCanceled}, ctx.Err()
	}
	if err != nil {
		s.log.Error("OneShot 进程失败", "cause", err)
		return executor.OneShotReply{Text: out, Status: executor.OneShotFailed}, err
	}
	s.log.Info("OneShot.Invoke 完成", "status", executor.OneShotOK, "output_bytes", len(out))
	return executor.OneShotReply{Text: out, Status: executor.OneShotOK}, nil
}

n_claudecode_Proc_Alive.signature:
// Alive 检查 claude 是否仍然存活：存活锁被持有 且 out.jsonl 无死亡哨兵。
//
// 为什么两条都要：锁只证明 shim 活着；claude 自己退出后 shim 会写哨兵再退出，
// 两者之间有一个极短窗口锁还在但 claude 已死，哨兵兜住它。
// （旧实现这里的第一条是 tmux has-session，而第二窗口的 tail -f 会一直吊着会话，
// 导致 claude 早死了会话还在——换成锁之后这个假存活来源被连根拔掉。）
func (p *Proc) Alive() bool {
	if p == nil || !prochost.Alive(p.Handle) {
		return false
	}
	exited, _ := procExited(filepath.Join(p.TaskDir, outFileName))
	return !exited
}

n_claudecode_Proc_Kill.signature:
// Kill 终止 claude 及其后代（按进程组），幂等。
func (p *Proc) Kill() error {
	if p == nil {
		return nil
	}
	return killProcHost(p.Handle)
}

n_claudecode_Proc_WriteInput.signature:
// WriteInput 往输入通道投递一条 stream-json user message。
//
// 参数：
//   - text: 指令原文，原样透传不加工（executor 契约要求）
//
// 注意：
//   - 投递失败多半意味着执行者已不在（读端消失），调用方据此包装
//     executor.ErrTaskNotRunning。平台差异（unix 的 ENXIO / Windows 的
//     ERROR_FILE_NOT_FOUND）由 prochost 吸收，本层不感知
func (p *Proc) WriteInput(text string) error {
	path := filepath.Join(p.TaskDir, fifoFileName)
	line, err := json.Marshal(map[string]any{
		"type":	"user",
		"message": map[string]any{
			"role":		"user",
			"content":	text,
		},
	})
	if err != nil {
		return fmt.Errorf("序列化 user message: %w", err)
	}
	if err := prochost.WriteInputChannel(path, append(line, '\n')); err != nil {
		return err
	}
	slog.Default().Debug("已投递指令到输入通道", "task_dir", p.TaskDir, "bytes", len(line)+1)
	return nil
}

n_claudecode_Profile_Inspect.signature:
func (p *Profile) Inspect(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
	}
	if req.HomeDir == "" {
		return rep, nil
	}
	rulePath := filepath.Join(req.HomeDir, RulesRelFile)
	if _, err := os.Stat(rulePath); errors.Is(err, os.ErrNotExist) {
		rep.Missing = append(rep.Missing, RulesRelFile)
	}
	skillsPath := filepath.Join(req.HomeDir, SkillsRelDir)
	if _, err := os.Stat(skillsPath); errors.Is(err, os.ErrNotExist) {
		rep.Missing = append(rep.Missing, SkillsRelDir)
	}
	return rep, nil
}

n_claudecode_Profile_Prepare.signature:
func (p *Profile) Prepare(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
	}
	if req.HomeDir == "" {
		return rep, errors.New("Profile.Prepare 缺少 HomeDir")
	}
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 开始", "harness", executor.HarnessClaude, "home", req.HomeDir, "isolated", req.Isolated)
	}
	nativeRoot := filepath.Join(req.HomeDir, filepath.Dir(RulesRelFile))
	if err := os.MkdirAll(nativeRoot, 0700); err != nil {
		return rep, fmt.Errorf("创建原生配置目录 %q: %w", nativeRoot, err)
	}

	for _, r := range req.Rules {
		if strings.Contains(r.Name, "..") {
			return rep, fmt.Errorf("规则文件名含非法字符: %q", r.Name)
		}
		var target string
		if strings.HasPrefix(filepath.Clean(r.Name), filepath.Dir(RulesRelFile)) {
			target = filepath.Join(req.HomeDir, filepath.Clean(r.Name))
		} else {
			target = filepath.Join(nativeRoot, filepath.Clean(r.Name))
		}
		if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
			return rep, fmt.Errorf("创建规则父目录 %q: %w", filepath.Dir(target), err)
		}
		if err := os.WriteFile(target, []byte(r.Content), 0600); err != nil {
			return rep, fmt.Errorf("写入规则文件 %q: %w", target, err)
		}
	}

	if len(req.Skills) > 0 {
		skillsRoot := filepath.Join(req.HomeDir, SkillsRelDir)
		for _, s := range req.Skills {
			if strings.Contains(s.Name, "..") {
				return rep, fmt.Errorf("skill 文件名含非法字符: %q", s.Name)
			}
			target := filepath.Join(skillsRoot, filepath.Clean(s.Name))
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建 skill 父目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(s.Content), 0600); err != nil {
				return rep, fmt.Errorf("写入 skill 文件 %q: %w", target, err)
			}
		}
	}

	if len(req.TaskOverlay) > 0 {
		overlayRoot := filepath.Join(req.HomeDir, ".handoff", "task-overlay")
		for _, o := range req.TaskOverlay {
			if strings.Contains(o.Name, "..") {
				return rep, fmt.Errorf("overlay 文件名含非法字符: %q", o.Name)
			}
			target := filepath.Join(overlayRoot, filepath.Clean(o.Name))
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建 overlay 父目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(o.Content), 0600); err != nil {
				return rep, fmt.Errorf("写入 overlay 文件 %q: %w", target, err)
			}
		}
	}

	rep.Notes = append(rep.Notes, "claude 凭据在 Keychain，无可靠文件判据，未拷贝登录态")
	rep.Prepared = true
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 完成", "harness", executor.HarnessClaude, "prepared", true)
	}
	return rep, nil
}

n_claudecode_Profile_Verify.signature:
func (p *Profile) Verify(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
		EngineOK:	false,
	}
	if req.HomeDir == "" {
		return rep, nil
	}
	rulePath := filepath.Join(req.HomeDir, RulesRelFile)
	globalOK := false
	if len(req.Rules) == 0 {
		_, err := os.Stat(rulePath)
		globalOK = err == nil
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			if p != nil && p.log != nil {
				p.log.Error("Profile.Verify 读取原生规则失败", "harness", executor.HarnessClaude,
					"home", req.HomeDir, "path", rulePath, "cause", err)
			}
			return rep, fmt.Errorf("校验原生规则 %q: %w", rulePath, err)
		}
	} else {
		expected := req.Rules[0].Content
		for _, rule := range req.Rules {
			if filepath.Base(filepath.Clean(rule.Name)) == filepath.Base(RulesRelFile) {
				expected = rule.Content
			}
		}
		got, readErr := os.ReadFile(rulePath)
		if readErr != nil {
			rep.Missing = append(rep.Missing, RulesRelFile)
		} else if !bytes.Equal(got, []byte(expected)) {
			rep.Notes = append(rep.Notes, fmt.Sprintf("规则内容不符: %s", RulesRelFile))
		} else {
			globalOK = true
		}
	}
	overlayOK := true
	for _, overlay := range req.TaskOverlay {
		if strings.Contains(overlay.Name, "..") {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 文件名含非法字符: %s", overlay.Name))
			continue
		}
		rel := filepath.Join(".handoff", "task-overlay", filepath.Clean(overlay.Name))
		got, readErr := os.ReadFile(filepath.Join(req.HomeDir, rel))
		if readErr != nil {
			overlayOK = false
			rep.Missing = append(rep.Missing, rel)
			if p != nil && p.log != nil {
				actualState := "read_error"
				if errors.Is(readErr, os.ErrNotExist) {
					actualState = "missing"
				}
				p.log.Warn("Profile.Verify 任务层内容缺失",
					"harness", executor.HarnessClaude, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", actualState,
					"expected_bytes", len(overlay.Content), "actual_bytes", 0, "cause", readErr)
			}
			continue
		}
		if !bytes.Equal(got, []byte(overlay.Content)) {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 内容不符: %s", rel))
			if p != nil && p.log != nil {
				p.log.Warn("Profile.Verify 任务层内容不符",
					"harness", executor.HarnessClaude, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", "content_mismatch",
					"expected_bytes", len(overlay.Content), "actual_bytes", len(got))
			}
		}
	}
	rep.Verified = globalOK && overlayOK
	if p != nil && p.log != nil {
		p.log.Info("Profile.Verify 完成", "harness", executor.HarnessClaude,
			"home", req.HomeDir, "verified", rep.Verified, "engine_ok", rep.EngineOK,
			"overlay_count", len(req.TaskOverlay))
	}
	return rep, nil
}

n_claudecode_StartProc.signature:
// StartProc 备物料、经 prochost 拉起 shim 承载 claude，返回进程句柄。
//
// 参数：
//   - ctx: 保留以与 adapter 契约一致（当前未参与拉起，启动是子秒级操作）；
//     执行生命周期延续到 Kill
//   - req: 进程完整入参（见 StartProcReq）
//   - log: 本模块日志入口（进程启动点，日志需要显式传入而非走默认）
//
// 返回：
//   - 已拉起的进程句柄；任一阶段失败返回错误（此时无残留进程）
//
// 注意：
//   - 就绪判定（等 system/init）由 adapter 在 stream 层完成，本函数只负责拉起
//   - in.fifo 必须先于进程存在：shim 第一件事是 O_RDWR 打开它，
//     fifo 缺失会让整条 claude 命令失败
//   - startProcHost 返回后必须等 in.fifo 出现读者（WaitInputReader）才能返回：
//     Start 只代表 shim 已 fork，写端不等到读端会 ENXIO（见 fifoReaderTimeout 的 why）
//   - startProcHost 成功之后的一切失败路径必须自行 Kill 回收：调用方 rollback
//     依赖 r.proc，而 StartProc 失败时返回 nil（见 WaitInputReader 失败处）
func StartProc(ctx context.Context, req StartProcReq, log *slog.Logger) (*Proc, error) {
	l := log.With("task", req.TaskID)
	if len(req.Env) > 0 {

		l.Info("注入 env 变量到 claude 进程", "keys", envKeys(req.Env), "count", len(req.Env))
	}
	fifoPath := filepath.Join(req.TaskDir, fifoFileName)
	if err := prochost.CreateInputChannel(fifoPath); err != nil {
		l.Error("创建输入通道失败", "path", fifoPath, "cause", err)
		return nil, err
	}
	bin, err := lookClaudePath()
	if err != nil {
		l.Error("claude 未安装", "cause", err)
		return nil, fmt.Errorf("claude 未安装: %w", err)
	}

	l.Info("解析 claude 可执行文件", "bin", bin)
	selfExe, err := os.Executable()
	if err != nil {
		l.Error("取 handoff 自身路径失败（shim 无法拉起）", "cause", err)
		return nil, fmt.Errorf("取自身可执行路径: %w", err)
	}
	argv := claudeArgv(req)
	argv[0] = bin

	lockPath := filepath.Join(req.TaskDir, lockFileName)
	infoPath := filepath.Join(req.TaskDir, procInfoFileName)

	if err := writeProcInfo(req.TaskDir, &procInfo{
		Handle:	prochost.Handle{LockPath: lockPath}, SessionID: req.SessionID,
	}); err != nil {
		l.Error("写恢复凭据失败", "cause", err)
		return nil, err
	}
	spec := prochost.Spec{
		Argv:	argv, Dir: req.RepoPath, Env: append(os.Environ(), req.Env...),
		Stdout:		filepath.Join(req.TaskDir, outFileName),
		Stderr:		filepath.Join(req.TaskDir, stderrFileName),
		InputCh:	fifoPath, LockPath: lockPath, InfoPath: infoPath,
		Sentinel:	true,
	}
	spec.TaskID = req.TaskID
	spec.MarkRoot = req.MarkRoot
	l.Info("启动 claude 执行者", "bin", bin, "repo", req.RepoPath, "resume", req.Resume)
	handle, err := startProcHost(spec, selfExe)
	if err != nil {
		l.Error("拉起 claude 执行者失败", "cause", err)
		return nil, err
	}
	p := &Proc{Handle: handle, TaskDir: req.TaskDir, SessionID: req.SessionID}

	elapsed, err := prochost.WaitInputReader(fifoPath, fifoReaderTimeout)
	if err != nil {
		l.Error("shim 未在时限内打开 in.fifo", "cause", err, "log_tail", claudeLogTail(req.TaskDir))

		if kerr := p.Kill(); kerr != nil {
			l.Warn("回收读端未就绪的执行者失败，可能需人工清理", "cause", kerr)
		}
		return nil, err
	}
	l.Debug("claude in.fifo 读端就绪", "wait", elapsed)

	if err := writeProcInfo(req.TaskDir, &procInfo{
		Handle:	handle, SessionID: req.SessionID,
	}); err != nil {
		l.Warn("回写恢复凭据失败，重启恢复将不可用", "cause", err)
	}
	l.Info("claude 执行者已就位", "shim_pid", handle.PID)
	return p, nil
}

n_claudecode_WriteTaskEnv.signature:
// WriteTaskEnv 在 taskDir 生成 Claude Code 的任务级物料并渲染首回合 prompt。
//
// 参数：
//   - taskDir: 任务工作目录（须已存在，由 manager 创建，0700）
//   - taskID: 任务 ID，写入 prompt 标题行
//   - planContent: 实现计划全文，原样嵌入 prompt
//   - sockPath: 本任务的权限裁决 socket 路径（perm.go 监听它）
//   - handoffBin: handoff 二进制绝对路径，作为裁决 MCP server 的启动命令
//   - disciplineBlock: 唯一来自 StartReq 的纪律块正文；taskenv 不自行解析
//
// 返回：
//   - settingsPath / mcpPath: 生成的两个配置文件路径
//   - promptText: 渲染后的首回合 prompt 原文（由 adapter 投递进 fifo）
//   - err: 渲染或写文件失败
//
// 注意：
//   - 重复调用幂等覆盖，Start 失败重试可安全重来
//   - 两个配置文件都是 0600：mcp.json 泄露 socket 路径即泄露裁决入口
func WriteTaskEnv(taskDir, taskID, planContent, sockPath, handoffBin, disciplineBlock string, snap executor.PolicySnapshot) (settingsPath, mcpPath, promptText string, err error) {
	log := slog.Default()
	settingsPath = filepath.Join(taskDir, settingsFileName)
	mcpPath = filepath.Join(taskDir, mcpFileName)
	log.Info("claude 生成任务环境", "task", taskID, "version", snap.Version, "task_dir", taskDir,
		"settings", settingsPath, "mcp", mcpPath, "sock", sockPath)

	if strings.TrimSpace(snap.Version) != "" && strings.TrimSpace(snap.Scope.Workdir) == "" {
		log.Error("claude 政策快照无法精确表达", "task", taskID, "version", snap.Version, "cause", "空 Workdir")
		return "", "", "", fmt.Errorf("%w: 空 Workdir", executor.ErrUnrepresentablePolicy)
	}

	allow := append([]string(nil), allowRules...)
	filtered := allow[:0]
	for _, r := range allow {
		if r == "Bash" {
			continue
		}
		filtered = append(filtered, r)
	}
	allow = filtered

	settings := settingsFile{Permissions: permissionsSection{
		Allow:	allow,
		Ask:	askRules,
		Deny:	[]string{},
	}}
	settingsJSON, err := json.MarshalIndent(settings, "", "  ")
	if err != nil {
		log.Error("claude 序列化 settings 失败", "task", taskID, "cause", err)
		return settingsPath, mcpPath, "", fmt.Errorf("序列化 settings: %w", err)
	}
	if err := os.WriteFile(settingsPath, settingsJSON, 0o600); err != nil {
		log.Error("claude 写 settings 失败", "task", taskID, "path", settingsPath, "cause", err)
		return settingsPath, mcpPath, "", fmt.Errorf("写 %s: %w", settingsPath, err)
	}

	mcp := mcpConfig{MCPServers: map[string]mcpServer{
		"handoff": {Command: handoffBin, Args: []string{"permission-mcp", "--sock", sockPath}},
	}}
	mcpJSON, err := json.MarshalIndent(mcp, "", "  ")
	if err != nil {
		log.Error("claude 序列化 mcp 配置失败", "task", taskID, "cause", err)
		return settingsPath, mcpPath, "", fmt.Errorf("序列化 mcp 配置: %w", err)
	}
	if err := os.WriteFile(mcpPath, mcpJSON, 0o600); err != nil {
		log.Error("claude 写 mcp 配置失败", "task", taskID, "path", mcpPath, "cause", err)
		return settingsPath, mcpPath, "", fmt.Errorf("写 %s: %w", mcpPath, err)
	}

	promptText, err = turn.RenderPrompt(taskID, planContent, disciplineBlock)
	if err != nil {
		log.Error("claude 渲染 prompt 失败", "task", taskID, "cause", err)
		return settingsPath, mcpPath, "", fmt.Errorf("渲染 prompt: %w", err)
	}
	log.Info("claude 任务环境已生成", "task", taskID,
		"ask_rules", len(askRules), "allow_rules", len(allowRules), "prompt_bytes", len(promptText))
	return settingsPath, mcpPath, promptText, nil
}

n_claudecode_claudeArgv.signature:
// claudeArgv 组 claude 的完整 argv。
//
// 为什么返回 argv 而不是命令串：argv 直接交给 execve，不经任何 shell——
// 旧实现把它拼进 sh 脚本，路径里的空格要引号、值里的 $ 会被二次展开，
// 这类问题在 argv 形态下从根上不存在。
//
// 注意：Resume=true 用 --resume（载入既有会话），false 用 --session-id
// （新建该 id 的会话）。两者语义相反，写错的表现是「日志说恢复成功、模型
// 却什么都不记得」——测试 TestClaudeArgvHasNoShell 钉死了这条。
func claudeArgv(req StartProcReq) []string {
	argv := []string{
		"claude", "-p",
		"--input-format", "stream-json",
		"--output-format", "stream-json",
		"--verbose", "--include-partial-messages",
	}
	if req.Model != "" {
		argv = append(argv, "--model", req.Model)
	}
	if req.Resume {
		argv = append(argv, "--resume", req.SessionID)
	} else {
		argv = append(argv, "--session-id", req.SessionID)
	}
	argv = append(argv, "--setting-sources", "user,project")
	argv = append(argv, "--settings", req.SettingsPath)
	argv = append(argv, "--mcp-config", req.MCPPath)
	argv = append(argv, "--permission-prompt-tool", "mcp__handoff__ask")
	return argv
}

n_claudecode_claudeLogTail.signature:
// claudeLogTail 读 claude.log 尾部最多 500 字节，供就绪超时/死亡诊断。
//
// why（读文件而非 capture-pane）：claude 所在窗格随命令退出关闭，capture-pane 读不到
// 已关闭窗格；claude.log 是 tee 落盘的持久副本，进程死后仍可读。
func claudeLogTail(taskDir string) string {
	f, err := os.Open(filepath.Join(taskDir, stderrFileName))
	if err != nil {
		return ""
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return ""
	}
	const n = 4 << 10
	offset := fi.Size() - n
	if offset < 0 {
		offset = 0
	}
	buf := make([]byte, fi.Size()-offset)
	if _, err := f.ReadAt(buf, offset); err != nil {
		return ""
	}
	return tail(string(buf), 500)
}

n_claudecode_compactJSON.signature:
// compactJSON 把任意 JSON 压成一行（render.log 摘要与权限描述用）。
func compactJSON(raw json.RawMessage) string {
	if len(raw) == 0 {
		return "{}"
	}
	var buf bytes.Buffer
	if err := json.Compact(&buf, raw); err != nil {
		return string(raw)
	}
	return buf.String()
}

n_claudecode_ensureTaskTmp.signature:
// ensureTaskTmp creates the task-private directory immediately before a new
// process is started; hot reattach paths must not create it.
func ensureTaskTmp(taskID, tmpDir string, log *slog.Logger) error {
	if err := os.MkdirAll(tmpDir, 0o700); err != nil {
		log.Error("创建任务临时目录失败", "task", taskID, "tmp_dir", tmpDir, "cause", err)
		return err
	}
	log.Info("任务临时目录已就绪", "task", taskID, "tmp_dir", tmpDir)
	return nil
}

n_claudecode_envKeys.signature:
// envKeys 提取 KEY=VALUE 列表里的 key（日志用；值绝不出现在日志里）。
func envKeys(env []string) []string {
	keys := make([]string, 0, len(env))
	for _, kv := range env {
		if k, _, ok := strings.Cut(kv, "="); ok {
			keys = append(keys, k)
		}
	}
	return keys
}

n_claudecode_firstLine.signature:
// firstLine 取字符串首行（render.log 摘要用）。
func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

n_claudecode_jsonString.signature:
// jsonString 尝试把 JSON 值当作字符串读出。
func jsonString(raw json.RawMessage) (string, bool) {
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return "", false
	}
	return s, true
}

n_claudecode_managedTaskTmpEnv.signature:
// managedTaskTmpEnv derives the task-private environment from TaskDir.
//
// The managed entries are appended after user entries at the process seam so
// handoff's isolation values cannot be overridden by task configuration.
func managedTaskTmpEnv(taskDir, taskID string) (string, []string) {
	dataDir := filepath.Dir(filepath.Dir(taskDir))
	if filepath.Base(filepath.Dir(taskDir)) != "tasks" {

		dataDir = filepath.Dir(taskDir)
	}
	tmpDir := executor.TaskTmpDir(dataDir, taskID)
	return tmpDir, []string{
		"TMPDIR=" + tmpDir,
		"GOTMPDIR=" + tmpDir,
		"GOCACHE=" + filepath.Join(tmpDir, "gocache"),
	}
}

n_claudecode_newPermServer.signature:
// newPermServer 建立并开始受理裁决请求。
//
// 参数：
//   - sockPath: socket 文件路径（位于 0700 的任务目录内）
//   - log: 日志入口
//   - onAsk: 收到请求时的回调（adapter 在其中 emit permission 事件）；同一
//     tool_use_id 重连重登记时会**再次**回调——manager 侧 ticket 按 id 幂等，
//     重发是 agentd 重启后能继续裁决的必要条件
//
// 返回：
//   - 已在受理的服务端；监听失败时返回错误
//
// 注意：
//   - 复用已存在的 socket 文件前会先删除（agentd 重启后残留），否则 bind 报
//     address already in use
func newPermServer(sockPath string, log *slog.Logger, onAsk func(permAsk)) (*permServer, error) {
	// AF_UNIX 的 sun_path 上限是 108 字节（含结尾 NUL），三大平台一致。
	// 不在这里拦下的话，用户拿到的是 net.Listen 的原始错误，指不到真因。
	// 上限取 107 是给结尾 NUL 留位。
	const sunPathMax = 107
	if len(sockPath) > sunPathMax {
		return nil, fmt.Errorf("裁决 socket 路径过长（%d 字节，上限 %d）: %s——把 DataDir 配到更浅的位置", len(sockPath), sunPathMax, sockPath)
	}

	if err := os.Remove(sockPath); err != nil && !os.IsNotExist(err) {
		log.Error("清理残留 socket 失败", "sock", sockPath, "cause", err)
		return nil, fmt.Errorf("清理残留 socket %s: %w", sockPath, err)
	}
	ln, err := net.Listen("unix", sockPath)
	if err != nil {
		log.Error("监听裁决 socket 失败", "sock", sockPath, "cause", err)
		return nil, fmt.Errorf("监听 %s: %w", sockPath, err)
	}
	if err := os.Chmod(sockPath, 0o600); err != nil {
		log.Warn("设置 socket 权限失败，继续（任务目录本身 0700）", "sock", sockPath, "cause", err)
	}
	s := &permServer{sockPath: sockPath, ln: ln, log: log, onAsk: onAsk,
		pending:	map[string]net.Conn{}}
	log.Info("裁决 socket 已就绪", "sock", sockPath)
	go s.acceptLoop()
	return s, nil
}

n_claudecode_newTailer.signature:
// newTailer 创建 out.jsonl 的增量读取器。
//
// 参数：
//   - path: out.jsonl 路径（proc.go 的 stdout 落盘目标）
//   - offset: 起始读取位置（0 表示从头；agentd 重启时用 proc.json 持久化的值）
//   - log: 日志入口
func newTailer(path string, offset int64, log *slog.Logger) *tailer {
	t := &tailer{path: path, log: log}
	t.offset.Store(offset)
	return t
}

n_claudecode_parseAssistantUsage.signature:
// parseAssistantUsage 从一条 assistant 的 **message 对象**里取模型名与 context 占用。
//
// 参数：
//   - msg: streamMsg.Message 的原文（model / content / usage 都在这一层，
//     与 content 同级；**不在 stream 行的顶层**）
//
// 返回：
//   - model: 该条消息的模型名（可能为空）
//   - u: context 占用；零值时为 nil（**不用 0 冒充**）
//   - ok: 报文可解析时为 true
//
// 注意：**缓存两项要相加**（`input_tokens` 不含缓存），与 codex 的规则相反。
// 窗口**不在 assistant 消息里**，而在 result 行的 modelUsage 里
// （见 pickModelUsageWindow），且要等第一个回合结束才有——所以本函数返回的
// ContextWindow 恒为 nil，由 mapAssistant 接线把 runState 暂存的 r.ctxWindow
// 挂进来。
func parseAssistantUsage(msg json.RawMessage) (string, *proto.Usage, bool) {
	var m struct {
		Model	string	`json:"model"`
		Usage	struct {
			InputTokens		int	`json:"input_tokens"`
			CacheCreationTokens	int	`json:"cache_creation_input_tokens"`
			CacheReadTokens		int	`json:"cache_read_input_tokens"`
		}	`json:"usage"`
	}
	if err := json.Unmarshal(msg, &m); err != nil {
		return "", nil, false
	}
	tokens := m.Usage.InputTokens + m.Usage.CacheCreationTokens + m.Usage.CacheReadTokens
	if tokens <= 0 {
		return m.Model, nil, true
	}
	return m.Model, &proto.Usage{ContextTokens: tokens}, true
}

n_claudecode_parseResultSpend.signature:
// parseResultSpend 从 result 行取本轮新增的消耗。
//
// 参数：
//   - m: result 行
//   - prevCostUSD: **同一个进程内**上一次 result 行的 total_cost_usd（首个回合传 0）
//
// 返回：
//   - e: 账目；Key 取 result 行的 uuid
//   - nextPrev: 本次的 total_cost_usd，调用方存回 runState 作下次的基线
//   - ok: uuid 非空且 usage 可解析时为 true
//
// 两条 claudecode 独有的规则（**改错了不会报错，只会显示错的数**）：
//   - **取 `usage.*` 不取 `modelUsage.*`**：前者是本轮，后者是**进程累计**。
//     进程累计在 --resume 后会归零（实测前一进程收尾 in=3095，新进程首轮 in=98），
//     所以它既不是会话累计也不能直接用。
//   - **`input_tokens` 不含缓存，缓存两项要相加**——与 codex/grok 相反。
//     实测轮 3 的 input_tokens 只有 54 而 cache_read 有 32768。
//
// 花费只有进程内累计值 `total_cost_usd`，所以本轮花费 = 本次 − 上次。
// runState 天生是进程级的，新进程基线自然从 0 起，首个回合的差分就是它自己——正确。
// 差分为负说明基线陈旧（不该发生），退回取当前值本身，绝不写负数进账本。
func parseResultSpend(m streamMsg, prevCostUSD float64) (proto.SpendEntry, float64, bool) {
	if m.UUID == "" {
		return proto.SpendEntry{}, prevCostUSD, false
	}
	var u struct {
		InputTokens		int	`json:"input_tokens"`
		CacheReadTokens		int	`json:"cache_read_input_tokens"`
		CacheCreationTokens	int	`json:"cache_creation_input_tokens"`
		OutputTokens		int	`json:"output_tokens"`
	}
	if len(m.Usage) == 0 {
		return proto.SpendEntry{}, prevCostUSD, false
	}
	if err := json.Unmarshal(m.Usage, &u); err != nil {
		return proto.SpendEntry{}, prevCostUSD, false
	}

	delta := m.TotalCostUSD - prevCostUSD
	if delta < 0 {
		delta = m.TotalCostUSD
	}
	return proto.SpendEntry{
		Key:		m.UUID,
		InputTokens:	u.InputTokens,
		CachedTokens:	u.CacheReadTokens + u.CacheCreationTokens,
		OutputTokens:	u.OutputTokens,
		CostTicks:	usdToTicks(delta),
		CostState:	proto.CostReported,
	}, m.TotalCostUSD, true
}

n_claudecode_permFallbackText.signature:
// permFallbackText 组装展示文本的兜底分支：工具名 + 入参的紧凑 JSON。
func permFallbackText(toolName string, input json.RawMessage) string {
	return toolName + ": " + compactJSON(input)
}

n_claudecode_permServer_Close.signature:
// Close 停止受理并关闭全部挂起连接。
//
// 挂起连接被关闭后，MCP 侧会按退避重连重登记——若 agentd 是重启而非退出，
// 重连会落到新的 permServer 上继续裁决。
func (s *permServer) Close() error {
	s.mu.Lock()
	if s.closed {
		s.mu.Unlock()
		return nil
	}
	s.closed = true
	conns := make([]net.Conn, 0, len(s.pending))
	for _, c := range s.pending {
		conns = append(conns, c)
	}
	s.pending = map[string]net.Conn{}
	s.mu.Unlock()

	for _, c := range conns {
		c.Close()
	}
	err := s.ln.Close()
	s.log.Info("裁决 socket 已关闭", "sock", s.sockPath, "closed_pending", len(conns))
	return err
}

n_claudecode_permServer_Respond.signature:
// Respond 回发裁决并关闭该连接。
//
// 参数：
//   - toolUseID: 目标请求 id（= claude 的 tool_use_id）
//   - behavior: "allow" 或 "deny"
//   - message: deny 时的拒绝理由（allow 时忽略）
//
// 返回：
//   - 找不到挂起请求或写失败时报错。**不得静默成功**：静默成功会让 manager
//     以为裁决已送达，而 claude 侧其实还在等，任务就此卡死
func (s *permServer) Respond(toolUseID, behavior, message string) error {
	s.mu.Lock()
	conn, ok := s.pending[toolUseID]
	if ok {
		delete(s.pending, toolUseID)
	}
	s.mu.Unlock()
	if !ok {
		s.log.Error("裁决目标不存在（请求已失效或进程已退）", "tool_use_id", toolUseID, "behavior", behavior)
		return fmt.Errorf("裁决请求 %s 不存在", toolUseID)
	}
	defer conn.Close()
	b, err := json.Marshal(permDecision{Type: "decision", Behavior: behavior, Message: message})
	if err != nil {
		s.log.Error("序列化裁决失败", "tool_use_id", toolUseID, "cause", err)
		return fmt.Errorf("序列化裁决: %w", err)
	}
	if _, err := conn.Write(append(b, '\n')); err != nil {
		s.log.Error("回发裁决失败", "tool_use_id", toolUseID, "behavior", behavior, "cause", err)
		return fmt.Errorf("回发裁决 %s: %w", toolUseID, err)
	}
	s.log.Info("裁决已回发", "tool_use_id", toolUseID, "behavior", behavior)
	return nil
}

n_claudecode_permServer_acceptLoop.signature:
// acceptLoop 持续受理连接，每条连接一次请求。
func (s *permServer) acceptLoop() {
	for {
		conn, err := s.ln.Accept()
		if err != nil {
			s.mu.Lock()
			closed := s.closed
			s.mu.Unlock()
			if closed {
				s.log.Debug("裁决 socket 已关闭，停止受理", "sock", s.sockPath)
				return
			}
			s.log.Error("受理裁决连接失败", "sock", s.sockPath, "cause", err)
			return
		}
		go s.serveConn(conn)
	}
}

n_claudecode_permServer_serveConn.signature:
// serveConn 读一条 ask 帧、登记挂起并回调；连接在裁决回发后由 Respond 关闭。
func (s *permServer) serveConn(conn net.Conn) {
	var ask permAsk
	if err := json.NewDecoder(bufio.NewReader(conn)).Decode(&ask); err != nil {
		s.log.Error("解析裁决请求失败，丢弃该连接", "cause", err)
		conn.Close()
		return
	}
	if ask.ToolUseID == "" {
		s.log.Error("裁决请求缺 tool_use_id，丢弃", "tool", ask.ToolName)
		conn.Close()
		return
	}
	s.mu.Lock()

	if old, ok := s.pending[ask.ToolUseID]; ok && old != conn {
		old.Close()
		s.log.Info("裁决请求重连重登记", "tool_use_id", ask.ToolUseID, "tool", ask.ToolName)
	}
	s.pending[ask.ToolUseID] = conn
	s.mu.Unlock()

	s.log.Info("收到权限裁决请求", "tool_use_id", ask.ToolUseID, "tool", ask.ToolName)
	s.onAsk(ask)
}

n_claudecode_permText.signature:
// permText 保留原签名，只取展示文本（结构化载荷见 permTextAndRequest）。
func permText(toolName string, input json.RawMessage) string {
	text, _ := permTextAndRequest(toolName, input)
	return text
}

n_claudecode_permTextAndRequest.signature:
// permTextAndRequest 从工具名与入参同时组装展示文本与结构化载荷。
//
// 参数：
//   - toolName: claude 的原始工具名（Bash / Write / Edit / …）
//   - input: 该次工具调用的原始入参 JSON
//
// 返回：
//   - text: 展示文本，形如 "Bash: <命令>" / "Write: <路径>"；提取不出关键
//     入参时退回工具名 + 紧凑 JSON
//   - req: 结构化载荷；**关键字段缺失时返回 nil**——伪造空壳会让判据误以为
//     拿到了结构，从而跳过 fail-closed 升级
//
// 两者共用一次解析：它们必须描述同一件事，分两处解析迟早漂移。
func permTextAndRequest(toolName string, input json.RawMessage) (string, *executor.PermRequest) {
	switch toolName {
	case "Bash":
		var in struct {
			Command string `json:"command"`
		}
		if json.Unmarshal(input, &in) == nil && in.Command != "" {
			return "Bash: " + in.Command,
				&executor.PermRequest{Tool: executor.PermToolBash, Command: in.Command}
		}
	case "Edit", "Write":
		var in struct {
			FilePath string `json:"file_path"`
		}
		if json.Unmarshal(input, &in) == nil && in.FilePath != "" {
			return toolName + ": " + in.FilePath,
				&executor.PermRequest{Tool: executor.NormalizePermTool(toolName),
					Paths:	[]string{in.FilePath}}
		}
	}

	return permFallbackText(toolName, input), nil
}

n_claudecode_pickModelUsageWindow.signature:
// pickModelUsageWindow 从 result 行的 modelUsage map 里取当前模型的窗口上限。
//
// 参数：
//   - mu: modelUsage 原文（键=模型名）
//   - prefer: runState 上已知的实际模型名（多键时优先匹配它）
//
// 返回：
//   - window: 选中的 contextWindow；空 map 或没有有效数字时为 0
//   - confident: false 表示「多键且按 prefer / canonicalModel 都匹配不上，
//     挑了任意一个」——调用方必须打 Warn，不能静默挑第一个
//
// 为什么空 map 返回 confident=true：没有 modelUsage 是正常形态（结果行不带计数），
// 不是歧义，不需要告警。
func pickModelUsageWindow(mu map[string]modelUsage, prefer string) (window int, confident bool) {
	if len(mu) == 0 {
		return 0, true
	}
	if len(mu) == 1 {
		for _, v := range mu {
			return v.ContextWindow, true
		}
	}

	for key, v := range mu {
		if key == prefer || v.CanonicalModel == prefer {
			return v.ContextWindow, true
		}
	}

	for _, v := range mu {
		return v.ContextWindow, false
	}
	return 0, true
}

n_claudecode_procExited.signature:
// procExited 检查 out.jsonl 是否出现死亡哨兵。
//
// 返回：
//   - exited: 是否已退出；code: 退出码（exited=false 时无意义）
//
// why（从文件读而非记内存）：agentd 重启后内存态全丢，而哨兵落在文件里——
// 重读同样能发现死亡，这是 Resume 判存活的第一条判据。
func procExited(outJSONLPath string) (exited bool, code int) {
	f, err := os.Open(outJSONLPath)
	if err != nil {
		return false, 0
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return false, 0
	}
	// 反向扫文件尾部：哨兵由 shim 在进程退出后追加，必然在末尾；文件可能很大，
	// 只读尾部 8KB 足够覆盖（任何一行的长度都不会超过它）
	const scanBytes = 8 << 10
	offset := fi.Size() - scanBytes
	if offset < 0 {
		offset = 0
	}
	buf := make([]byte, fi.Size()-offset)
	if _, err := f.ReadAt(buf, offset); err != nil {
		return false, 0
	}
	for _, line := range strings.Split(string(buf), "\n") {
		if !strings.Contains(line, prochost.SentinelPrefix) {
			continue
		}
		var s struct {
			Code int `json:"code"`
		}
		_ = json.Unmarshal([]byte(line), &s)
		return true, s.Code
	}
	return false, 0
}

n_claudecode_readProcInfo.signature:
// readProcInfo 读取任务目录的恢复凭据。
//
// 返回：
//   - 文件缺失/损坏/字段不完整时返回错误（调用方据此判「无法恢复」）
func readProcInfo(taskDir string) (*procInfo, error) {
	b, err := os.ReadFile(filepath.Join(taskDir, procInfoFileName))
	if err != nil {
		return nil, fmt.Errorf("读恢复凭据 %s: %w", procInfoFileName, err)
	}
	var pi procInfo
	if err := json.Unmarshal(b, &pi); err != nil {
		return nil, fmt.Errorf("解析恢复凭据 %s: %w", procInfoFileName, err)
	}
	if pi.Handle.LockPath == "" || pi.SessionID == "" {
		return nil, fmt.Errorf("恢复凭据 %s 字段不完整", procInfoFileName)
	}
	return &pi, nil
}

n_claudecode_resumeNote.signature:
// resumeNote 拼恢复结果的一句话结论（进 ResumeOutcome.Note 供 manager 转播）。
func resumeNote(mode, sessionID string) string {
	switch mode {
	case executor.ResumeModeReattach:
		return "executor 仍存活，已重连事件流"
	case executor.ResumeModeCold:
		return "已从磁盘载入原会话 " + sessionID + "，上下文完整"
	case executor.ResumeModeFresh:
		return "原会话已不可载入，已新开会话 " + sessionID + "，上下文从下一条指令开始"
	}
	return "已恢复"
}

n_claudecode_rotateOutJSONL.signature:
// rotateOutJSONL 把 out.jsonl 轮转到 out.<n>.jsonl（n 从 1 递增到第一个不存在的），
// 并重置恢复凭据里的 offset。
//
// why（冷恢复需要轮转）：冷恢复后是全新的输出流，旧 offset 无意义——不轮转的话
// tailer 从旧 offset 续读新文件，会把新会话的开头当成旧内容跳过。旧文件保留
// （诊断价值），新开 out.jsonl 让 tailer 从 0 读。
//
// 返回：nil（成功或文件本就不存在）；轮转中读写错误。
func rotateOutJSONL(taskDir string) error {
	src := filepath.Join(taskDir, outFileName)
	if _, err := os.Stat(src); os.IsNotExist(err) {
		return nil
	}

	for i := 1; ; i++ {
		dst := filepath.Join(taskDir, fmt.Sprintf("out.%d.jsonl", i))
		if _, err := os.Stat(dst); os.IsNotExist(err) {
			if rerr := os.Rename(src, dst); rerr != nil {
				return fmt.Errorf("轮转 %s -> %s: %w", src, dst, rerr)
			}
			return nil
		}
	}
}

n_claudecode_runState_captureStartCommit.signature:
// captureStartCommit 记录任务起点 commit：git 兜底分类（fallbackClassify）用
// 「是否有新提交」裁决的基线；非 git 仓库或查询失败时留空，兜底一律按无新提交处理。
func (r *runState) captureStartCommit(a *Adapter) {
	if out, err := exec.Command("git", "-C", r.repoPath, "rev-parse", "HEAD").Output(); err != nil {
		a.log.Warn("捕获任务起点 commit 失败，兜底按无新提交处理",
			"task", r.taskID, "repo", r.repoPath, "cause", err)
	} else {
		r.startCommit = strings.TrimSpace(string(out))
	}
}

n_claudecode_runState_clearTurn.signature:
// clearTurn 清空回合累积（回合分类终结时调用）。
func (r *runState) clearTurn() {
	r.turnMu.Lock()
	r.turnBuf.Reset()
	r.turnMu.Unlock()
}

n_claudecode_runState_closeEvents.signature:
// closeEvents 关闭事件通道（只由 streamLoop 的 defer 调用，关闭权唯一）。
func (r *runState) closeEvents() {
	r.emitMu.Lock()
	defer r.emitMu.Unlock()
	if r.evClosed {
		return
	}
	r.evClosed = true
	close(r.evCh)
}

n_claudecode_runState_markReady.signature:
// markReady 标记会话就绪（init 事件到达），只关闭一次。
func (r *runState) markReady() {
	r.readyOnce.Do(func() { close(r.ready) })
}

n_claudecode_runState_streamLoop.signature:
// streamLoop 是单任务的事件流主循环（唯一持有 evCh 关闭权的 goroutine）：
// 从 offset 0 起读 out.jsonl → mapMessage 逐条映射产出 AdapterEvent；顺带每
// persistOffsetEvery 持久化一次 proc.json 的 offset（agentd 重启后续读的依据）。
func (r *runState) streamLoop(a *Adapter) {
	defer func() {
		r.closeOnce.Do(r.closeEvents)
		select {
		case <-r.stopCh:
		default:
			a.drop(r.taskID)
		}
		a.log.Info("claude 事件流退出", "task", r.taskID)
	}()
	tl := newTailer(filepath.Join(r.taskDir, outFileName), r.startOffset, a.log)

	tl.rawTap = rawtap.Open("claudecode", r.taskID, a.log)
	var lastPersist time.Time
	err := tl.Run(r.runCtx, func(m streamMsg) {

		if now := time.Now(); now.Sub(lastPersist) >= persistOffsetEvery {
			if r.session != "" && r.proc != nil {
				if perr := writeProcInfo(r.taskDir, &procInfo{
					Handle:	r.proc.Handle, SessionID: r.session, Offset: tl.Offset(),
				}); perr != nil {
					a.log.Warn("持久化 claude offset 失败", "task", r.taskID, "cause", perr)
				}
				lastPersist = now
			}
		}
		a.mapMessage(r, m)
	})
	select {
	case <-r.stopCh:
		return
	default:
	}

	if r.exitHandled {
		return
	}
	tail := claudeLogTail(r.taskDir)
	if err != nil {
		a.log.Error("claude 事件流损坏", "task", r.taskID, "cause", err)
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	false, SessionID: r.session,
			FailReason:	"claude 事件流损坏: " + turn.TailRunes(fmt.Sprint(err), 200),
		}})
		return
	}
	a.log.Warn("claude 事件流意外中断，按失败结束回合", "task", r.taskID, "stderr_tail", tail)
	a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
		OK:	false, SessionID: r.session,
		FailReason:	"claude 事件流意外中断: " + tail,
	}})
}

n_claudecode_splitDelta.signature:
// splitDelta 从 stream_event 里同时取出正文增量与思维链增量。
//
// 返回：
//   - text:      delta.type == "text_delta" 时的正文，否则空串
//   - reasoning: delta.type == "thinking_delta" 时的思维链，否则空串
//
// 两者互斥，至多一个非空。
//
// 为什么另开一个函数而不是改 textDelta：textDelta 是既有隔离判定的入口
// （mapStreamEvent 靠它把思维链挡在 render.log 与回合正文之外）。改它的返回
// 语义等于动隔离，而本期的纪律是隔离一行不许放松——多一个函数是最便宜的守法方式。
func splitDelta(ev json.RawMessage) (text, reasoning string) {
	var e struct {
		Type	string	`json:"type"`
		Delta	struct {
			Type		string	`json:"type"`
			Text		string	`json:"text"`
			Thinking	string	`json:"thinking"`
		}	`json:"delta"`
	}
	if err := json.Unmarshal(ev, &e); err != nil {
		return "", ""
	}
	if e.Type != "content_block_delta" {
		return "", ""
	}
	switch e.Delta.Type {
	case "text_delta":
		return e.Delta.Text, ""
	case "thinking_delta":
		return "", e.Delta.Thinking
	}
	return "", ""
}

n_claudecode_tail.signature:
// tail 返回字符串尾部最多 n 个字符（按字节截断，日志用）。
func tail(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[len(s)-n:]
}

n_claudecode_tailer_Offset.signature:
// Offset 返回已消费的字节 offset（供持久化到 proc.json 供重启续读）。
func (t *tailer) Offset() int64 {
	return t.offset.Load()
}

n_claudecode_tailer_Run.signature:
// Run 持续读新行并把每条解码结果交回调，直到 ctx 取消或流损坏。
//
// 返回：
//   - ctx 取消时返回 nil；连续 garbageLimit 行解析失败（流损坏）返回错误
//
// 注意：
//   - 回调在调用 Run 的 goroutine 内同步执行：回调慢会拖慢消费，但保证顺序
//   - 半行（未以换行符结尾）不推进 offset：下轮轮询会从同一位置重读
func (t *tailer) Run(ctx context.Context, onMsg func(streamMsg)) error {
	t.log.Info("tailer 启动", "path", t.path, "offset", t.Offset())
	defer t.rawTap.Close()
	garbage := 0
	for {
		adv, err := t.scanOnce(onMsg, &garbage)
		if err != nil {
			t.log.Error("流损坏，中止解析", "path", t.path, "garbage", garbage, "cause", err)
			return err
		}
		if adv == 0 {
			select {
			case <-ctx.Done():
				t.log.Info("tailer 退出", "path", t.path, "offset", t.Offset())
				return nil
			case <-time.After(tailPollInterval):
			}
		}
	}
}

n_claudecode_tailer_scanOnce.signature:
// scanOnce 从当前 offset 读到文件尾，处理所有完整行，返回消费的字节数。
//
// 半行（未以换行符结尾）留在 offset 之外不推进，由下一轮轮询补齐。
func (t *tailer) scanOnce(onMsg func(streamMsg), garbage *int) (int64, error) {
	f, err := os.Open(t.path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("打开 %s: %w", t.path, err)
	}
	defer f.Close()
	if _, err := f.Seek(t.offset.Load(), io.SeekStart); err != nil {
		return 0, fmt.Errorf("seek %s: %w", t.path, err)
	}
	r := bufio.NewReader(f)
	var consumed int64
	for {
		line, rerr := r.ReadBytes('\n')
		if len(line) == 0 {
			if rerr == io.EOF {
				break
			}
			if rerr != nil {
				return consumed, fmt.Errorf("读 %s: %w", t.path, rerr)
			}
			continue
		}

		if line[len(line)-1] != '\n' {
			break
		}
		consumed += int64(len(line))
		t.offset.Add(int64(len(line)))

		t.rawTap.Write(line)

		var m streamMsg
		if jerr := json.Unmarshal(line, &m); jerr != nil {
			*garbage++
			if *garbage >= garbageLimit {
				return consumed, fmt.Errorf("连续 %d 行非 JSON，流已损坏", *garbage)
			}
			t.log.Warn("out.jsonl 非 JSON 行，跳过", "path", t.path,
				"garbage_consecutive", *garbage, "line", truncate(string(line), 80))
		} else {
			*garbage = 0
			onMsg(m)
		}
		if rerr == io.EOF {
			break
		}
		if rerr != nil {
			return consumed, fmt.Errorf("读 %s: %w", t.path, rerr)
		}
	}
	return consumed, nil
}

n_claudecode_textDelta.signature:
// textDelta 从 stream_event 里提取模型正文增量。
//
// 返回：
//   - text, true：event 是 content_block_delta 且 delta 是 text_delta
//   - "", false：thinking_delta / signature_delta / 其他——思维链绝不能进
//     render.log 与回合文本（与 opencode 的 reasoning 隔离一致）
func textDelta(ev json.RawMessage) (string, bool) {
	var e struct {
		Type	string	`json:"type"`
		Delta	struct {
			Type	string	`json:"type"`
			Text	string	`json:"text"`
		}	`json:"delta"`
	}
	if err := json.Unmarshal(ev, &e); err != nil {
		return "", false
	}
	if e.Type != "content_block_delta" || e.Delta.Type != "text_delta" {
		return "", false
	}
	return e.Delta.Text, true
}

n_claudecode_timingDetail.signature:
// timingDetail 从工具入参里取出进 TimingEntry.Detail 的摘要。
//
// Bash 取完整命令原文（聚合层要按命令首词分桶，摘要里没有命令就分不了桶）；
// 其余工具取紧凑 JSON。截断由 Segmenter 负责，本函数不截。
//
// 为什么不复用 appendActionSummary 里那行 render.log 摘要：那行走的是
// firstLine，会切掉多行命令的后续行——而多行命令的首行往往只是 `set -e`。
func timingDetail(toolName string, input json.RawMessage) string {
	if toolName == "Bash" {
		var in struct {
			Command string `json:"command"`
		}
		if json.Unmarshal(input, &in) == nil && in.Command != "" {
			return in.Command
		}
	}
	return compactJSON(input)
}

n_claudecode_truncate.signature:
// truncate 截断日志行预览（按字节，日志用）。
func truncate(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n] + "…"
}

n_claudecode_usdToTicks.signature:
// usdToTicks 把浮点美元换成整数 ticks（1 USD = 10^10）。
//
// 为什么统一到整数：花费要跨回合求和，浮点累加的误差对不上服务端的账
// （grok 官方文档的原话）。转换在**入账时**做一次，之后全程整数。
func usdToTicks(usd float64) int64 {
	if usd <= 0 {
		return 0
	}
	return int64(math.Round(usd * 1e10))
}

n_claudecode_writeProcInfo.signature:
// writeProcInfo 把恢复凭据写入任务目录 proc.json（0600）。
//
// why（必须持久化）：agentd 重启后内存中的 Proc 丢失，而 shim 内的 claude 进程
// 独立存活；Resume 凭此文件探活、续读 offset 并重建事件流。写失败不阻断启动
// （adapter 只 Warn），缺失时重启按「执行器已不在」转 failed——保守胜于静默丢事件。
func writeProcInfo(taskDir string, pi *procInfo) error {
	b, err := json.Marshal(pi)
	if err != nil {
		return fmt.Errorf("序列化恢复凭据: %w", err)
	}
	if err := os.WriteFile(filepath.Join(taskDir, procInfoFileName), b, 0o600); err != nil {
		return fmt.Errorf("写恢复凭据 %s: %w", procInfoFileName, err)
	}
	return nil
}

n_client_Client_Attach.signature:
// Attach 获取任务的完整现场快照（任务 + 待办工单 + 最近事件），
// 是协调者恢复会话现场（pending_tickets）的数据源。
//
// 参数：
//   - taskID: 任务 ID；任务不存在时返回 404 错误
func (c *Client) Attach(ctx context.Context, taskID string) (*AttachInfo, error) {
	resp, err := c.do(ctx, http.MethodGet, "/api/tasks/"+taskID, nil)
	if err != nil {
		return nil, fmt.Errorf("任务详情请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, c.httpError("任务详情", resp)
	}
	var info AttachInfo
	if err := json.NewDecoder(resp.Body).Decode(&info); err != nil {
		return nil, fmt.Errorf("解析任务详情响应: %w", err)
	}
	return &info, nil
}

n_client_Client_BaseURL.signature:
// BaseURL 返回这个 client 的基址。
//
// 用途：调用方判定「选路选对了没有」——relay 形态恒为 http://localhost（经隧道
// 直达对端），直连形态是 http://<addr>。只读，不暴露 token。
func (c *Client) BaseURL() string	{ return c.baseURL }

n_client_Client_Bundle.signature:
// Bundle 取任务分支的 git bundle 字节流。
//
// 参数：
//   - taskID: 完整任务 UUID
//   - have:   协调者本地已有的基线提交；空串请求全量包
//
// 返回：
//   - rc:  bundle 字节流，**调用方负责 Close**
//   - err: 404 → ErrBundleUnsupported（对端过旧，调用方应回落）；其余为故障
//
// 注意：
//   - 成功路径**不能** defer resp.Body.Close()：Body 就是返回给调用方的 rc
func (c *Client) Bundle(ctx context.Context, taskID, have string) (io.ReadCloser, error) {
	path := "/api/tasks/" + url.PathEscape(taskID) + "/bundle"
	if have != "" {
		path += "?have=" + url.QueryEscape(have)
	}
	c.log().Debug("请求任务 bundle", "task", taskID, "have", have)
	resp, err := c.do(ctx, http.MethodGet, path, nil)
	if err != nil {
		return nil, fmt.Errorf("bundle 请求: %w", err)
	}
	switch resp.StatusCode {
	case http.StatusOK:
		c.log().Debug("bundle 响应就绪", "task", taskID, "content_length", resp.ContentLength)
		return resp.Body, nil
	case http.StatusNoContent:

		resp.Body.Close()
		c.log().Warn("对端返回 204（空区间），本实现的服务端不应产生它", "task", taskID, "have", have)
		return nil, fmt.Errorf("对端返回 204 空区间响应：该版本不产出带 ref 的包，本地分支引用无法建立")
	case http.StatusNotFound:

		resp.Body.Close()
		c.log().Debug("对端 agentd 不支持 bundle 端点，按版本过旧处理", "task", taskID)
		return nil, ErrBundleUnsupported
	default:
		defer resp.Body.Close()
		return nil, c.httpError("取 bundle", resp)
	}
}

n_client_Client_CardStep.signature:
// CardStep 向 agentd 提交一个卡节点，成功只表示服务端已受理。
//
// 参数：ctx 控制本次短 HTTP 请求；cardID 是 URL 中的卡号；req 是带节点名、一次性
// 覆盖项和发起会话 actor 的规范请求。调用方不得把 --plan 文件塞进 req。
//
// 返回：agentd 返回 HTTP 202 且 JSON body 为 {"ok":true} 时返回 nil；非 2xx 保留
// agentd 的状态码和错误体；连接失败保留 ErrUnreachable；响应 JSON 非法或 ok=false
// 返回错误。nil 不代表回合已完成，进展由 card wait/事件流读取。
func (c *Client) CardStep(ctx context.Context, cardID string, req proto.CardStepReq) error {
	logger := c.log().With("card", cardID, "step", req.Step, "actor", req.Actor)
	logger.Info("提交卡节点")
	resp, err := c.do(ctx, http.MethodPost, "/api/cards/"+cardID+"/step", req)
	if err != nil {
		logger.Warn("提交卡节点请求失败", "cause", err)
		return fmt.Errorf("card step 请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusAccepted {
		err := c.httpError("card step", resp)
		logger.Warn("卡节点未受理", "status", resp.StatusCode, "cause", err)
		return err
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, maxCardStepAck+1))
	if err != nil {
		logger.Warn("卡节点受理响应读取失败", "cause", err)
		return fmt.Errorf("读取 card step 响应: %w", err)
	}
	if len(body) > maxCardStepAck {
		logger.Warn("卡节点受理响应超限", "limit", maxCardStepAck)
		return fmt.Errorf("card step 响应超过 %d 字节", maxCardStepAck)
	}
	var ack struct {
		OK bool `json:"ok"`
	}
	if err := json.Unmarshal(body, &ack); err != nil {
		logger.Warn("卡节点受理响应解码失败", "cause", err, "body", string(body))
		return fmt.Errorf("解析 card step 响应: %w", err)
	}
	if !ack.OK {

		err := fmt.Errorf("card step 响应未确认受理: %s", strings.TrimSpace(string(body)))
		logger.Warn("卡节点受理响应为 ok=false", "cause", err)
		return err
	}
	logger.Info("卡节点已受理")
	return nil
}

