// 同一条 WS 路径）；收窄后的订阅缝经本方法拿到带标记的能力，不再引用聚合类型。
// 每次调用现做标记副本——与镜像源逐次重订的既有节奏一致。
func (c *Client) ForwardedStreamEventsOnce(ctx context.Context, taskID string, fromSeq int64,
