n_client_Client_FramesStream.signature:
// FramesStream 打开任务的结构化回合帧（frames.jsonl）流式读取。
//
// 参数：
//   - taskID: 目标任务
//   - offset: 起始字节偏移；>0 时优先于 tail（用于断线续传）
//   - tail:   从尾部回溯的字节数（offset<=0 时生效；两者都为 0 时由服务端取默认值）
//   - follow: 是否在到达文件尾后继续等待增量
//
// 返回：
//   - 流（调用方负责 Close，每行一个 proto.Frame 的 JSON）、响应开始时的文件
//     字节数、错误
//
// 注意：
//   - 与 RenderStream 一样**不设读超时**：follow 模式下长时间无输出是正常的
//   - 服务端保证只在完整行边界切，但调用方仍应按行缓冲——中间设备可能在
//     任意字节处切包
func (c *Client) FramesStream(ctx context.Context, taskID string,
	offset, tail int64, follow bool) (io.ReadCloser, int64, error) {
	q := url.Values{}
	if offset > 0 {
		q.Set("offset", strconv.FormatInt(offset, 10))
	} else if tail > 0 {
		q.Set("tail", strconv.FormatInt(tail, 10))
	}
	if follow {
		q.Set("follow", "1")
	}
	path := "/api/tasks/" + taskID + "/frames"
	if len(q) > 0 {
		path += "?" + q.Encode()
	}
	resp, err := c.doStream(ctx, http.MethodGet, path)
	if err != nil {
		return nil, 0, fmt.Errorf("frames 流请求: %w", err)
	}
	if resp.StatusCode != http.StatusOK {
		defer resp.Body.Close()
		return nil, 0, c.httpError("frames 流", resp)
	}
	size, _ := strconv.ParseInt(resp.Header.Get("X-Handoff-Frames-Size"), 10, 64)
	return resp.Body, size, nil
}

n_client_Client_GC.signature:
// GC 执行目标 agentd 的 gc；只有本次调用的 execute=true 才允许动盘。
//
// 参数：
//   - ctx: 请求生命周期，用于取消 HTTP 调用
//   - force: 是否透传 reclaim 语义的脏 managed worktree 强删开关
//
// 返回：
//   - 目标 agentd 返回的 gc 报告
//   - 请求失败、响应非法或对端过旧时返回错误
//
// 注意：POST 404 时补探测 GET /api/gc，只有两条路由皆 404 才判为旧 agentd。
func (c *Client) GC(ctx context.Context, force bool) (*proto.GCResp, error) {
	slog.Default().Info("gc 执行进入", "force", force)
	resp, err := c.do(ctx, http.MethodPost, "/api/gc", proto.GCRequest{Force: force})
	if err != nil {
		slog.Default().Error("gc 执行请求失败", "force", force, "cause", err)
		return nil, fmt.Errorf("gc 执行请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusNotFound {
		if _, lerr := c.GCPreview(ctx, force); errors.Is(lerr, ErrGCUnsupported) {
			c.log().Debug("对端两条 gc 路由皆 404，按版本过旧处理")
			return nil, ErrGCUnsupported
		}
		return nil, c.httpError("gc 执行", resp)
	}
	if resp.StatusCode != http.StatusOK {
		return nil, c.httpError("gc 执行", resp)
	}
	var out proto.GCResp
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		slog.Default().Error("gc 执行响应解析失败", "force", force, "cause", err)
		return nil, fmt.Errorf("解析 gc 执行响应: %w", err)
	}
	slog.Default().Info("gc 执行完成", "force", force, "cache_rows", len(out.CacheRows),
		"worktree_rows", len(out.WorktreeRows), "failures", out.Failures)
	return &out, nil
}

n_client_Client_GCPreview.signature:
// GCPreview 请求目标 agentd 生成一次只读 gc 预览。
//
// 参数：
//   - ctx: 请求生命周期，用于取消 HTTP 调用
//   - force: 只改变脏 managed worktree 的预览处置，不会触发删除
//
// 返回：
//   - 目标 agentd 返回的 gc 报告
//   - 请求失败、响应非法或对端过旧时返回错误
func (c *Client) GCPreview(ctx context.Context, force bool) (*proto.GCResp, error) {
	slog.Default().Info("gc 预览进入", "force", force)
	path := "/api/gc"
	if force {
		path += "?force=true"
	}
	resp, err := c.do(ctx, http.MethodGet, path, nil)
	if err != nil {
		slog.Default().Error("gc 预览请求失败", "force", force, "cause", err)
		return nil, fmt.Errorf("gc 预览请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusNotFound {
		c.log().Debug("对端 agentd 不支持 /api/gc，按版本过旧处理")
		return nil, ErrGCUnsupported
	}
	if resp.StatusCode != http.StatusOK {
		return nil, c.httpError("gc 预览", resp)
	}
	var out proto.GCResp
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		slog.Default().Error("gc 预览响应解析失败", "force", force, "cause", err)
		return nil, fmt.Errorf("解析 gc 预览响应: %w", err)
	}
	slog.Default().Info("gc 预览完成", "force", force, "cache_rows", len(out.CacheRows),
		"worktree_rows", len(out.WorktreeRows))
	return &out, nil
}

n_client_Client_HTTPClient.signature:
// HTTPClient 返回本 client 的底层 http.Client，供 agentd 的转发基座做原样搬运。
//
// 为什么要暴露它：跨机转发（REST/WS 反代）搬的是任意方法与路径的原始报文，
// 走不了本包的类型化方法；而选路（relay 隧道还是直连）恰恰长在这个 http.Client
// 的 Transport 里——转发层自己 new 一个就等于绕开选路，relay 机器会退化成
// "no Host in request URL"。
//
// 注意：
//   - 返回的是共享实例，调用方**不得**改它的字段（Timeout/Transport 等）
//   - Timeout 恒为 0（超时由调用方经 context 施加），同时满足 coder/websocket
//     对 HTTPClient.Timeout 必须为零的硬要求
//   - 不暴露 token：转发层的 Authorization 由它自己按 target 配置设置
func (c *Client) HTTPClient() *http.Client	{ return c.hc }

n_client_Client_Inbox.signature:
// Inbox 拉取待回复收件箱（B156.2 C7）：room inbox 走 agentd HTTP /api/inbox
// （breakdown 岔口三裁决——ticket 源判据 Hub.Watchers(taskID)==0 是 agentd
// 进程内快照，CLI 本地重算会让所有等待工单全量误上浮）。三源聚合在服务端
// 编排单元（C6），本方法只做传输与解码，不含业务判断。
func (c *Client) Inbox(ctx context.Context) ([]proto.InboxItem, error) {
	c.log().Debug("拉取 agentd 收件箱", "url", c.baseURL, "path", "/api/inbox")
	resp, err := c.do(ctx, http.MethodGet, "/api/inbox", nil)
	if err != nil {
		c.log().Warn("拉取 agentd 收件箱失败", "url", c.baseURL, "cause", err)
		return nil, fmt.Errorf("连接 agentd %s 失败（它在运行吗？可先执行 handoff status 确认）: %w", c.baseURL, err)
	}
	defer resp.Body.Close()
	c.log().Debug("agentd 收件箱响应已收到", "url", c.baseURL, "status", resp.StatusCode)
	if resp.StatusCode != http.StatusOK {
		return nil, c.httpError("拉收件箱", resp)
	}
	var out struct {
		Items []proto.InboxItem `json:"items"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		c.log().Warn("解析 agentd 收件箱失败", "url", c.baseURL, "status", resp.StatusCode, "cause", err)
		return nil, fmt.Errorf("解析收件箱: %w", err)
	}
	if out.Items == nil {
		out.Items = []proto.InboxItem{}
	}
	c.log().Info("agentd 收件箱已解码", "url", c.baseURL, "count", len(out.Items))
	return out.Items, nil
}

