n_client_Client_Stop.signature:
// Stop 主动中止任务：停 executor、作废挂起工单、任务落 failed。
//
// 参数：
//   - taskID: 待中止的任务 ID
//
// 返回：
//   - worktreeRemoved: 响应体 worktree_removed 如实回传——true=本次删除了
//     managed worktree，false=用户自带 worktree / 原地模式（没删）；响应体缺字段
//     （旧版 agentd）按 false 处理。CLI 据此打印与行为一致的提示，不猜
//   - 任务不存在（404）或已是终态（409）时返回错误
func (c *Client) Stop(ctx context.Context, taskID string) (worktreeRemoved bool, err error) {
	c.log().Info("Stop 进入", "url", c.baseURL, "relay", c.relayBacked, "task", taskID)
	resp, err := c.do(ctx, http.MethodPost, "/api/tasks/"+taskID+"/stop", nil)
	if err != nil {
		c.log().Error("Stop 失败", "url", c.baseURL, "task", taskID, "cause", err)
		return false, fmt.Errorf("中止任务请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		err = c.httpError("中止任务", resp)
		c.log().Error("Stop 失败", "url", c.baseURL, "task", taskID, "cause", err)
		return false, err
	}
	var body struct {
		WorktreeRemoved bool `json:"worktree_removed"`
	}
	_ = json.NewDecoder(resp.Body).Decode(&body)
	c.log().Info("Stop 完成", "task", taskID, "worktree_removed", body.WorktreeRemoved)
	return body.WorktreeRemoved, nil
}

n_client_Client_StopAndReclaim.signature:
// StopAndReclaim 先停止远端任务，再以 force=true 回收其孤儿资源。
// 参数 taskID 是远端任务 ID；返回 nil 表示已完成或命中契约规定的软成功。
// 注意：Stop 404 不再发 Reclaim；Stop 409 继续 Reclaim；Reclaim 404/不支持视为软成功。
func (c *Client) StopAndReclaim(ctx context.Context, taskID string) error {
	c.log().Info("孤儿派发补偿进入", "task", taskID)
	_, err := c.Stop(ctx, taskID)
	if err != nil {
		if hasHTTPStatus(err, http.StatusNotFound) {
			c.log().Info("Stop 返回 404，孤儿补偿视为完成", "task", taskID)
			return nil
		}
		if !hasHTTPStatus(err, http.StatusConflict) {
			c.log().Error("Stop 失败，未进入 Reclaim", "task", taskID, "cause", err)
			return err
		}
		c.log().Warn("Stop 返回 409，继续强制回收", "task", taskID, "cause", err)
	} else {
		c.log().Info("Stop 成功，开始强制回收", "task", taskID)
	}
	if _, err := c.Reclaim(ctx, taskID, true); err != nil {
		if hasHTTPStatus(err, http.StatusNotFound) || errors.Is(err, ErrReclaimUnsupported) {
			c.log().Info("Reclaim 不可用或任务已消失，孤儿补偿视为完成", "task", taskID, "cause", err)
			return nil
		}
		c.log().Error("Reclaim 失败", "task", taskID, "cause", err)
		return err
	}
	c.log().Info("孤儿派发补偿完成", "task", taskID)
	return nil
}

n_client_Client_StreamEventsOnce.signature:
// StreamEventsOnce 建立一次事件流连接，把收到的每一帧交给 onEvent，直到连接
// 断开或 ctx 取消。**不读写任何 cursor 文件，不做重连**。
//
// 参数：
//   - taskID: 任务 id（必须是完整 UUID）
//   - fromSeq: 起始 seq（开区间）；调用方自己持有水位
//   - onEvent: 每帧回调；返回错误即中止本次连接
//
// 为什么必须有这个「无 cursor」变体：FollowEvents / WaitEvent 把水位存在
// ~/.handoff/cursors/<agentd 地址>/<task>，那是**审核者本机**的状态。agentd 做事件镜像时
// 跑在同一台机器上，若复用带 cursor 的路径，agentd 的镜像与人手敲的
// handoff wait 会互相推进对方的水位——一方吃掉另一方的事件，且极难归因。
// 镜像的水位属于 mirror_events 表，不属于文件系统。
//
// 注意：单次连接、不重连。退避与重连策略由调用方（镜像订阅循环）决定，
// 它的节奏（300ms→×2→10s）与审核者 CLI 的（1s→60s）刻意不同。
func (c *Client) StreamEventsOnce(ctx context.Context, taskID string, fromSeq int64,
	onEvent func(proto.Event) error) error {
	c.log().Debug("镜像事件流建立", "addr", c.baseURL, "task", taskID, "from_seq", fromSeq)

	return c.streamOnce(ctx, taskID, fromSeq, func() time.Time { return time.Time{} }, onEvent)
}

n_client_Client_StreamPreviewEventsOnce.signature:
// StreamPreviewEventsOnce consumes one live owner/coordinator WS connection.
// Catch-up is deliberately not cursor based: callers list first, then
// reconnect by listing again before opening a fresh stream.
func (c *Client) StreamPreviewEventsOnce(ctx context.Context, onEvent func(proto.PreviewEvent) error) error {
	if err := c.checkInit(); err != nil {
		return err
	}
	wsScheme := "ws"
	if strings.HasPrefix(c.baseURL, "https://") {
		wsScheme = "wss"
	}
	host := strings.TrimPrefix(strings.TrimPrefix(c.baseURL, "http://"), "https://")
	wsURL := wsScheme + "://" + host + "/ws/previews"
	dialCtx, cancel := context.WithTimeout(ctx, dialTimeout)
	conn, resp, err := websocket.Dial(dialCtx, wsURL, c.wsDialOptions())
	cancel()
	if err != nil {
		if resp != nil {
			return fmt.Errorf("预览 WS 拨号失败 status=%d: %w", resp.StatusCode, err)
		}
		return fmt.Errorf("预览 WS 拨号失败: %w", err)
	}
	defer conn.CloseNow()
	conn.SetReadLimit(512 << 10)
	for {
		_, body, err := conn.Read(ctx)
		if err != nil {
			return fmt.Errorf("预览 WS 读取: %w", err)
		}
		var event proto.PreviewEvent
		if err := json.Unmarshal(body, &event); err != nil {
			return fmt.Errorf("预览 WS 事件反序列化: %w", err)
		}
		if err := onEvent(event); err != nil {
			return err
		}
	}
}

n_client_Client_WaitArchived.signature:
// WaitArchived 等待任务出现真实的 archived 事件（B67 依赖门闩）。
//
// 参数：
//   - ctx: 总等待时限。它不会被任何中间帧或重连重置，到点即返回
//     context.DeadlineExceeded。
//   - taskID: 任务 id（必须是完整 UUID）
//
// 返回：
//   - *proto.Event: 原始 archived 事件（与 B68 落库一致，不合成）
//   - ErrDependencyFailed: 任务 failed（快照阶段或事件流阶段）
//   - ErrArchivedEventMissing: 任务 completed 但 archived 事件缺失
//   - 永久错误（4xx/1008）与 ctx 取消
//
// 边界：不读写 ~/.handoff/cursors/ 下的任何游标，水位只留在进程内；等待期间不交付
// question/permission_request/completed 等中间事件，也不触发任何远端状态变更。
func (c *Client) WaitArchived(ctx context.Context, taskID string) (*proto.Event, error) {
	backoff := c.wsInitialBackoff

	emptyRechecks := 0
	c.log().Debug("等待归档开始", "addr", c.baseURL, "task", taskID)

	for attempt := 1; ; attempt++ {
		if err := ctx.Err(); err != nil {
			c.log().Debug("等待归档结束：上下文取消", "task", taskID, "cause", err)
			return nil, err
		}

		c.log().Debug("等待归档读取权威快照", "task", taskID, "attempt", attempt)
		snap, err := c.Attach(ctx, taskID)
		if err != nil {
			if ctx.Err() != nil {
				return nil, ctx.Err()
			}
			if isPermanent(err) {
				c.log().Error("等待归档失败：快照永久错误",
					"task", taskID, "attempt", attempt, "cause", err)
				return nil, err
			}
			c.log().Debug("等待归档快照暂时失败，退避重试",
				"task", taskID, "attempt", attempt, "backoff", backoff, "cause", err)
			if err := waitArchivedRetry(ctx, &backoff,
				c.wsInitialBackoff, c.wsMaxBackoff, false); err != nil {
				return nil, err
			}
			continue
		}
		terminal, fromSeq, err := classifyArchivedSnapshot(taskID, snap)
		if err != nil {
			c.log().Error("等待归档结束：快照终态失败",
				"task", taskID, "from_seq", fromSeq, "cause", err)
			return nil, err
		}
		if terminal != nil {
			c.log().Debug("等待归档完成：快照已有 archived",
				"task", taskID, "seq", terminal.Seq)
			return terminal, nil
		}

		var archived *proto.Event
		var failed *proto.Event
		seqBefore := fromSeq
		started := time.Now()
		streamErr := c.StreamEventsOnce(ctx, taskID, fromSeq, func(ev proto.Event) error {

			fromSeq = ev.Seq
			switch ev.Type {
			case proto.EventTypeArchived:
				copy := ev
				archived = &copy
				return errStopStream
			case proto.EventTypeFailed:
				copy := ev
				failed = &copy
				return errStopStream
			default:
				return nil
			}
		})
		lived := time.Since(started)

		if archived != nil {
			c.log().Debug("等待归档完成：收到 archived",
				"task", taskID, "seq", archived.Seq)
			return archived, nil
		}
		if failed != nil {
			err := fmt.Errorf("%w: task=%s seq=%d payload=%s",
				ErrDependencyFailed, taskID, failed.Seq, string(failed.Payload))
			c.log().Error("等待归档结束：依赖任务失败",
				"task", taskID, "seq", failed.Seq, "cause", err)
			return nil, err
		}
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		if errors.Is(streamErr, errArchived) {

			if fromSeq != seqBefore {
				emptyRechecks = 0
			}
			c.log().Debug("等待归档连接正常关闭，回查归档事件",
				"task", taskID, "from_seq", fromSeq, "empty_rechecks", emptyRechecks)
			if emptyRechecks == 0 {
				emptyRechecks++
				continue
			}
			emptyRechecks++
			if err := waitArchivedRetry(ctx, &backoff,
				c.wsInitialBackoff, c.wsMaxBackoff,
				lived >= c.wsStableAfter); err != nil {
				return nil, err
			}
			continue
		}
		if streamErr == nil {
			err := fmt.Errorf("归档事件流无终态却正常结束: task=%s from_seq=%d", taskID, fromSeq)
			c.log().Error("等待归档协议异常", "task", taskID, "cause", err)
			return nil, err
		}
		if isPermanent(streamErr) {
			c.log().Error("等待归档失败：事件流永久错误",
				"task", taskID, "from_seq", fromSeq, "cause", streamErr)
			return nil, streamErr
		}
		c.log().Debug("等待归档事件流暂时断开，退避重连",
			"task", taskID, "attempt", attempt, "from_seq", fromSeq,
			"backoff", backoff, "cause", streamErr)
		if err := waitArchivedRetry(ctx, &backoff,
			c.wsInitialBackoff, c.wsMaxBackoff,
			lived >= c.wsStableAfter); err != nil {
			return nil, err
		}
	}
}

n_client_Client_WaitEvent.signature:
// WaitEvent 阻塞等待任务的下一个事件：跳过 progress（除非 all=true），
// 拿到首个可动作事件即返回并把 cursor 写盘；断线指数退避 1s→2s→…→60s
// 无限重连，ctx 取消才退出。
//
// cursor 语义（事件不丢不重的根基）：
//   - 每次调用开始时从 <游标根>/cursors/<agentd>/<task> 读取上次交付事件的 seq，
//     连接 WS 时以 from_seq=cursor 补拉断线期间产生的事件
//   - 返回首个可动作事件时把 cursor 原子写盘为该事件的 seq；被跳过的 progress
//     事件不推进 cursor（下次调用会重新收到并再次跳过，重复跳过无副作用）
//   - 因此每条可动作事件恰好交付一次（不重），cursor 之后的事件断线后一条不丢（不丢）
//
// 为什么 progress 不唤醒：progress 是高频、无需人工动作的状态播报（如「正在运行」），
// 若用它唤醒，wait 会在每次进度变化时把协调者叫醒做无意义的一次「看-忽略」；
// 协调者只需在真正需要决策的事件（question/permission_request/completed/failed/stalled）
// 到达时被唤醒。需要全量事件流时显式传 all=true。
//
// 永久性失败（不重试）：握手 400/401/403（配置错误）与任务不存在（PolicyViolation
// close）立即返回错误——退避重连只为瞬时故障设计，见 isPermanent 的 why。
//
// 参数：
//   - taskID: 要等待的任务 ID
//   - all: true 时不做类型过滤，第一个到达的事件即返回
//
// 返回：
//   - 首个可动作事件；ctx 取消时返回 ctx.Err()（context.Canceled/DeadlineExceeded）；
//     永久性失败时返回对应的错误（不做退避）
func (c *Client) WaitEvent(ctx context.Context, taskID string, all bool) (*proto.Event, error) {
	fromSeq := c.readCursor(taskID)

	backoff := c.wsInitialBackoff
	for attempt := 1; ; attempt++ {
		start := time.Now()
		ev, err := c.waitOnce(ctx, taskID, fromSeq, all)
		lived := time.Since(start)
		if err == nil {
			if werr := c.writeCursor(taskID, ev.Seq); werr != nil {

				c.log().Warn("cursor 写盘失败", "task", taskID, "seq", ev.Seq, "cause", werr)
			}

			if ev.Type == proto.EventTypeArchived {
				c.DropCursor(taskID)
			}
			return ev, nil
		}
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}

		if isPermanent(err) {
			c.log().Error("wait 永久失败，不再重试", "addr", c.baseURL, "task", taskID, "cause", err)
			return nil, err
		}

		c.log().Info("WS 连接断开，等待后重连", "addr", c.baseURL, "task", taskID,
			"attempt", attempt, "next_backoff_seconds", int(backoff.Seconds()), "cause", err)

		if lived >= c.wsStableAfter {
			backoff = c.wsInitialBackoff
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(backoff):
		}
		if lived < c.wsStableAfter {
			backoff *= 2
			if backoff > c.wsMaxBackoff {
				backoff = c.wsMaxBackoff
			}
		}
	}
}

n_client_Client_WaitVersion.signature:
// WaitVersion 轮询 status 直到对端版本变成 want，或超时。
//
// 参数：
//   - want: 期望的版本号（形如 v0.1.1）
//   - timeout / interval: 等待时限与轮询间隔（生产取 60s / 2s）
//   - checkPull: 是否检查对端 pull_state。自拉 true——真失败立刻中止，
//     干等满超时只会得到一句「版本仍是 X」；推送 false——同 tag 先自拉失败
//     留下的陈旧 failed 态不该让一次真的会成功的 --push 被提前判死
//
// 注意：
//   - **轮询期间的失败一律忽略继续等**。重启窗口里连接被拒、502、503 都是
//     过程而不是结论；第一次 dial 失败就放弃，等于把每一次正常换版都报成失败
//   - 超时返回错误。不确认就报成功是主张不是事实，而 agentd 起不来恰恰是最
//     需要立刻知道的时刻
func (c *Client) WaitVersion(ctx context.Context, want string, timeout, interval time.Duration, checkPull bool) error {
	deadline := time.Now().Add(timeout)
	var last error
	for attempt := 1; ; attempt++ {
		st, err := c.Status(ctx)
		switch {
		case err == nil && st.Version.Version == want:
			c.log().Info("新版本已上线", "want", want, "attempts", attempt)
			return nil
		case err == nil:
			if checkPull {

				if ps := pullFailure(st, want); ps != nil {
					c.log().Error("对端自拉换版失败", "want", want,
						"stage", ps.Stage, "detail", ps.Error)
					return fmt.Errorf("对端自拉 %s 失败：%s", want, ps.Error)
				}
				if ps := pullProgress(st, want); ps != nil {
					c.log().Info("对端自拉进行中", "want", want, "stage", ps.Stage)
				}
			}
			last = fmt.Errorf("对端版本仍是 %q", st.Version.Version)
		default:
			last = err
		}
		if time.Now().After(deadline) {
			c.log().Error("等待新版本上线超时", "want", want, "timeout", timeout, "last", last)
			return fmt.Errorf("等待 %s 上线超时（%s）：%w", want, timeout, last)
		}
		c.log().Debug("等待新版本上线", "want", want, "attempt", attempt, "last", last)
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(interval):
		}
	}
}

n_client_Client_checkInit.signature:
// checkInit 在发请求前查毒化标记。
//
// 返回：initErr 原样返回；未毒化时 nil。
func (c *Client) checkInit() error	{ return c.initErr }

n_client_Client_cursorPath.signature:
// cursorPath 返回任务 cursor 文件路径（<游标根>/<agentd 命名空间>/<taskID>）。
//
// 为什么放用户主目录而非配置 DataDir：cursor 是协调者侧的本地状态，
// 与配置/数据库文件位置解耦；即使 DataDir 被移动，协调者已看过的进度也不重投。
// 该决策保留，cursordir.go 只是让这个根在不可写时可以降级。
//
// 为什么要 agentd 这一层：文件名只按 taskID 时，两台 agentd 上碰巧同 ID 的
// 任务会共用一个游标文件，互相把对方的进度顶掉。
func (c *Client) cursorPath(taskID string) (string, error) {
	root, err := c.cursorRootDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(root, cursorNamespace(c.baseURL), taskID), nil
}

n_client_Client_cursorRootDir.signature:
// cursorRootDir 返回已确认可写的游标根目录（形如 <root>/cursors）。
//
// 返回：
//   - 目录绝对路径；两级候选都不可写时返回错误，错误里点名两个路径与各自原因
//
// 注意：
//   - 全 Client 生命周期只解析一次，结果（含错误）被缓存
//   - 降级发生时打一条 Warn（stderr），只打一次
func (c *Client) cursorRootDir() (string, error) {
	c.cursorRootOnce.Do(func() {
		c.cursorRoot, c.cursorRootErr = c.resolveCursorRoot()
		if c.cursorRootErr == nil {

			c.purgeLegacyFlatCursors()
			c.sweepCursors()
		}
	})
	return c.cursorRoot, c.cursorRootErr
}

n_client_Client_do.signature:
// do 发送带 Bearer token 的请求，返回响应（调用方负责关闭 resp.Body）。
func (c *Client) do(ctx context.Context, method, path string, body any) (*http.Response, error) {
	if err := c.checkInit(); err != nil {
		return nil, err
	}
	var rd io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return nil, fmt.Errorf("序列化请求体 %s: %w", path, err)
		}
		rd = bytes.NewReader(b)
	}
	req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, rd)
	if err != nil {
		return nil, fmt.Errorf("构造请求 %s: %w", path, err)
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	for k, v := range c.extraHeaders {
		req.Header.Set(k, v)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := c.hc.Do(req)
	if err != nil {

		if errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded) {
			return nil, err
		}
		if c.relayBacked {
			c.log().Debug("relay 隧道请求未拿到响应",
				"method", method, "path", path, "url", c.baseURL, "cause", err)
			return nil, fmt.Errorf("%w: %s %s: %w", ErrTunnelDisconnected, method, path, err)
		}

		c.log().Debug("agentd 请求未拿到响应",
			"method", method, "path", path, "url", c.baseURL, "cause", err)
		return nil, fmt.Errorf("%w: %s %s: %w", ErrUnreachable, method, path, err)
	}
	c.log().Debug("agentd 请求拿到响应",
		"method", method, "path", path, "status", resp.StatusCode, "url", c.baseURL, "relay", c.relayBacked)
	return resp, nil
}

n_client_Client_doStream.signature:
// doStream 发送带 Bearer token 的流式 GET 请求，返回不关闭 body 的响应。
//
// 为什么不能复用 do：do 不做任何读体/超时假设，但它没有专门的流式语义——
// 而 RenderStream 需要保证响应体不被整体超时掐断（follow 长连接可能挂很久）。
// c.hc 本就没有全局 Timeout（只有拨号超时），直接复用即可；本函数与 do 的
// 区别只在明确「调用方负责消费并 Close body」。
func (c *Client) doStream(ctx context.Context, method, path string) (*http.Response, error) {
	if err := c.checkInit(); err != nil {
		return nil, err
	}
	req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, nil)
	if err != nil {
		return nil, fmt.Errorf("构造请求 %s: %w", path, err)
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	return c.hc.Do(req)
}

n_client_Client_httpError.signature:
// httpError 把非 2xx 响应转成错误，并按状态码分级记录日志。
//
// 为什么按状态码分级：4xx 是预期内的客户端错误（任务不存在、状态不允许），
// 在 attach 列表、pull 等常规路径上会正常出现——一律打 ERROR 会刷出假告警，
// 把真正需要注意的服务端故障（5xx）淹没在噪音里。
func (c *Client) httpError(op string, resp *http.Response) error {

	b, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
	if resp.StatusCode >= 500 {
		c.log().Error("agentd 请求失败", "op", op, "status", resp.StatusCode, "body", string(b))
	} else {
		c.log().Warn("agentd 请求被拒", "op", op, "status", resp.StatusCode, "body", string(b))
	}
	body := strings.TrimSpace(string(b))
	return &httpStatusError{op: op, code: resp.StatusCode, body: body}
}

n_client_Client_listPreviews.signature:
func (c *Client) listPreviews(ctx context.Context, path, op string) (*proto.PreviewListResp, error) {
	resp, err := c.do(ctx, http.MethodGet, path, nil)
	if err != nil {
		return nil, fmt.Errorf("%s请求: %w", op, err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, c.httpError(op, resp)
	}
	var out proto.PreviewListResp
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, fmt.Errorf("解析%s响应: %w", op, err)
	}
	return &out, nil
}

n_client_Client_log.signature:
// log 返回运行时 slog.Default()。
//
// 为什么不用包级 var：cli 命令在 RunE 里才 logx.Setup + slog.SetDefault，包级 var
// 在 init 时求值会锁死默认 logger，导致本包日志绕开 logx 的 stderr 文本输出
// （与 agentd 侧 store/config 的同款修正）。
func (c *Client) log() *slog.Logger	{ return slog.Default() }

n_client_Client_postUpdate.signature:
func (c *Client) postUpdate(ctx context.Context, tag, sum string, tgz []byte, force bool, mode string) (*proto.UpdateResp, error) {
	if err := c.checkInit(); err != nil {
		return nil, err
	}
	q := url.Values{}
	if tag != "" {
		q.Set("tag", tag)
	}
	if sum != "" {
		q.Set("sha256", sum)
	}
	if force {
		q.Set("force", "1")
	}
	if mode != "" {
		q.Set("mode", mode)
	}
	u := c.baseURL + "/api/update"
	if len(q) > 0 {
		u += "?" + q.Encode()
	}
	var rd io.Reader
	if len(tgz) > 0 {
		rd = bytes.NewReader(tgz)
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, u, rd)
	if err != nil {
		return nil, fmt.Errorf("构造换版请求: %w", err)
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}
	req.Header.Set("Content-Type", "application/octet-stream")

	c.log().Info("推送换版请求", "tag", tag, "bytes", len(tgz), "force", force, "mode", mode)
	resp, err := c.hc.Do(req)
	if err != nil {
		c.log().Error("换版请求失败", "tag", tag, "cause", err)
		return nil, fmt.Errorf("换版请求: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusNotFound {
		c.log().Debug("对端 agentd 不支持 /api/update，按版本过旧处理")
		return nil, ErrUpdateUnsupported
	}
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
	if resp.StatusCode != http.StatusOK && resp.StatusCode != http.StatusAccepted {
		var e proto.UpdateError

		if err := json.Unmarshal(body, &e); err != nil || e.Error == "" {
			c.log().Warn("换版被拒", "tag", tag, "status", resp.StatusCode, "body", string(body))
			return nil, fmt.Errorf("换版: 状态码 %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
		}
		c.log().Warn("换版被拒", "tag", tag, "status", resp.StatusCode, "reason", e.Reason, "detail", e.Error)
		return nil, &UpdateRejected{Reason: e.Reason, Msg: e.Error}
	}
	var out proto.UpdateResp
	if err := json.Unmarshal(body, &out); err != nil {
		return nil, fmt.Errorf("解析换版响应: %w", err)
	}
	c.log().Info("换版已受理，对端将重启", "tag", out.Version, "prev", out.Prev)
	return &out, nil
}

n_client_Client_purgeLegacyFlatCursors.signature:
// purgeLegacyFlatCursors 一次性清除旧平铺布局遗留的 cursor-* 文件。
//
// 为什么删而不迁移：旧文件里绝大多数是已归档任务的游标，本来就该删；保住它们
// 唯一的收益是极少数仍在 waiting_review 的老任务下次 wait 少重放一次历史事件，
// 不值得为此写一段只跑一次的迁移代码及其测试。
//
// 只删严格匹配 cursor-* 的文件，config.yaml / agentd.log / skill 等一律不碰。
func (c *Client) purgeLegacyFlatCursors() {
	home, err := os.UserHomeDir()
	if err != nil {
		return
	}
	matches, err := filepath.Glob(filepath.Join(home, ".handoff", "cursor-*"))
	if err != nil {
		c.log().Debug("扫描旧平铺游标失败", "cause", err)
		return
	}
	var removed int
	for _, m := range matches {
		fi, err := os.Stat(m)
		if err != nil || fi.IsDir() {
			continue
		}
		if rerr := os.Remove(m); rerr != nil {
			c.log().Debug("清除旧平铺游标失败", "path", m, "cause", rerr)
			continue
		}
		removed++
	}
	if removed > 0 {
		c.log().Info("已清除旧布局遗留的游标文件", "n", removed)
	}
}

n_client_Client_putRegistration.signature:
// putRegistration 是 PUT 登记的公共尾段：路径带 ?expect=，成功解码 SquadPutResp。
func (c *Client) putRegistration(ctx context.Context, op, path string, in any) (*proto.SquadPutResp, error) {
	resp, err := c.do(ctx, http.MethodPut, path, in)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, c.httpError(op, resp)
	}
	var out proto.SquadPutResp
	if err := decodeWire(resp, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

n_client_Client_readCursor.signature:
// readCursor 读取任务 cursor；任何读不出来的情形都返回 0（从头开始）。
func (c *Client) readCursor(taskID string) int64 {
	seq, _ := c.readCursorWithDiag(taskID)
	return seq
}

n_client_Client_readCursorWithDiag.signature:
// readCursorWithDiag 是 readCursor 的可诊断变体。
//
// 返回：
//   - seq: 游标值；读不出来时为 0
//   - reported: 是否属于「游标存在但用不了」并已告警（供测试断言，生产不用）
//
// 为什么要把「文件不存在」与其它错误分开：文件不存在是每个任务第一次 wait 的
// 常态，报它等于每次都喊狼来了；而权限被拒与内容损坏意味着游标存在却用不了，
// 后果是静默从 0 重放全部历史事件——协调者会看到一串早就处理过的旧事件，
// 却没有任何一条信息指向真正的原因。这是 B75 现场的成因。
func (c *Client) readCursorWithDiag(taskID string) (seq int64, reported bool) {
	p, err := c.cursorPath(taskID)
	if err != nil {
		c.log().Warn("游标路径不可用，本次从头开始", "task", taskID, "cause", err)
		return 0, true
	}
	b, err := os.ReadFile(p)
	if err != nil {
		if os.IsNotExist(err) {
			c.log().Debug("cursor 文件不存在，从头开始", "task", taskID, "path", p)
			return 0, false
		}
		c.log().Warn("cursor 存在但读不了，本次将从头重放事件",
			"task", taskID, "path", p, "cause", err)
		return 0, true
	}
	n, err := strconv.ParseInt(strings.TrimSpace(string(b)), 10, 64)
	if err != nil || n < 0 {
		c.log().Warn("cursor 内容损坏，本次将从头重放事件",
			"task", taskID, "path", p, "content", turnTailForLog(string(b)))
		return 0, true
	}
	c.log().Debug("cursor 读取", "task", taskID, "path", p, "seq", n)
	return n, false
}

n_client_Client_reconcileBacklog.signature:
// reconcileBacklog 在建立 WS 连接前对账：拿一次权威快照，判断本机 cursor 之后
// 是否积压了未读事件；有则吐一行摘要并把 cursor 直接推到当前水位。
//
// 参数：
//   - taskID: 完整 UUID
//   - fromSeq: 本机 cursor 当前停在哪
//   - onBacklog: 摘要的消费者（cmd 层写 stdout）；返回非 nil 立即上抛
//
// 返回：
//   - next: WS 应当使用的 from_seq——有积压时是当前水位，否则原样是 fromSeq
//   - terminal: 快照显示任务已 failed，调用方应吐完摘要后正常收尾（返回 nil）
//   - err: 仅当 onBacklog 报错；**网络/HTTP 失败一律不报错**（见下）
//
// 为什么积压事件不拉取而是直接跳过：摘要用的是权威快照，比逐条重放**信息更全**
// ——重放里混着已被审批链答掉的历史工单（补 reply 会 404），而 PendingTickets
// 只含真正还欠的，且每张带完整 Request 原文。
//
// 为什么 Attach 失败是降级而不是报错：摘要是优化不是正确性，对账失败就该退回
// 改动前的逐条重放，绝不能因此中断 follow。永久性（401/404）也不在这里判——
// Client.Attach 的错误是普通 fmt.Errorf 而非 permanentError，isPermanent 认不出
// 它；紧随其后的 WS 握手会用既有的、已被测试覆盖的路径判出同一个结论。判定
// 只留一处，不复制。
func (c *Client) reconcileBacklog(ctx context.Context, taskID string, fromSeq int64,
	onBacklog func(*BacklogSummary) error) (int64, bool, error) {
	c.log().Debug("follow 积压对账开始", "task", taskID, "from_seq", fromSeq)

	snap, err := c.Attach(ctx, taskID)
	if err != nil {
		c.log().Warn("follow 积压对账失败，退回逐条重放", "task", taskID,
			"from_seq", fromSeq, "cause", err)
		return fromSeq, false, nil
	}

	sum := computeBacklog(taskID, fromSeq, snap)
	if sum == nil {
		c.log().Debug("follow 积压对账完成：无积压", "task", taskID, "from_seq", fromSeq)
		return fromSeq, false, nil
	}

	c.log().Info("follow 积压对账：有积压", "task", taskID,
		"from_seq", sum.FromSeq, "to_seq", sum.ToSeq, "missed", sum.Missed,
		"stale", sum.Stale, "actionable", len(sum.Actionable),
		"truncated", sum.MissedTruncated, "state", string(sum.State))

	if berr := onBacklog(sum); berr != nil {
		return fromSeq, false, berr
	}
	if werr := c.writeCursor(taskID, sum.ToSeq); werr != nil {

		c.log().Warn("对账后 cursor 写盘失败", "task", taskID, "seq", sum.ToSeq, "cause", werr)
	}
	return sum.ToSeq, sum.State == proto.TaskStateFailed, nil
}

n_client_Client_resolveCursorRoot.signature:
// resolveCursorRoot 执行两级确定性降级。
//
// 顺序硬约束：先 ~/.handoff（缺省，与历史行为一致），不可写才退 <cwd>/.handoff。
// 为什么降级目标是 cwd 而不是 $TMPDIR：codex 的 workspace-write 可写 cwd、
// $TMPDIR、/tmp 三处，但只有 cwd 是协调者的项目目录、跨 session 稳定；
// $TMPDIR 会被清理，游标续不上等于没修。
func (c *Client) resolveCursorRoot() (string, error) {
	var homeReason string
	home, err := os.UserHomeDir()
	if err != nil {
		homeReason = fmt.Sprintf("读取用户主目录失败: %v", err)
	} else {
		cand := filepath.Join(home, ".handoff", cursorDirName)
		if perr := probeCursorDirWritable(cand); perr == nil {
			c.log().Debug("游标根就位", "dir", cand)
			return cand, nil
		} else {
			homeReason = fmt.Sprintf("%s 不可写: %v", filepath.Dir(cand), perr)
		}
	}

	cwd, err := os.Getwd()
	if err != nil {
		return "", fmt.Errorf("游标目录不可用：%s；且读取当前目录失败: %w", homeReason, err)
	}
	cand := filepath.Join(cwd, ".handoff", cursorDirName)
	if perr := probeCursorDirWritable(cand); perr != nil {
		return "", fmt.Errorf("游标目录不可用：%s；%s 也不可写: %v",
			homeReason, filepath.Dir(cand), perr)
	}

	c.log().Warn("游标目录不可写，已降级", "原因", homeReason, "改用", cand)
	return cand, nil
}

n_client_Client_streamOnce.signature:
// streamOnce 建立一次 WS 连接并把收到的每一帧交给 onFrame，直到 onFrame 收手或连接结束。
//
// 参数：
//   - fromSeq: 断线续拉起点（服务端据此补发历史事件）
//   - readDeadline: 每次 Read 前调用一次，返回本次读取的**绝对**截止时刻；
//     返回零值表示不设。为什么是绝对时刻而不是时长：空闲要跨重连累计，
//     每次连接都从头计时等于让一个反复断连的对端永远超不了时
//   - onFrame: 每收到一帧调用一次（**含 progress**，过滤由调用方做）
//
// 返回：
//   - nil: onFrame 返回 errStopStream
//   - errArchived: 对端以 StatusNormalClosure 关闭（任务已归档）
//   - ErrIdleTimeout: 读取超过 readDeadline 且外层 ctx 未取消
//   - permanentError / 其他: 拨号或读取失败，由调用方决定是否重连
func (c *Client) streamOnce(ctx context.Context, taskID string, fromSeq int64,
	readDeadline func() time.Time, onFrame func(proto.Event) error) error {
	if err := c.checkInit(); err != nil {
		return err
	}

	wsScheme := "ws"
	if strings.HasPrefix(c.baseURL, "https://") {
		wsScheme = "wss"
	}
	host := strings.TrimPrefix(strings.TrimPrefix(c.baseURL, "http://"), "https://")
	wsURL := wsScheme + "://" + host + "/ws/events?task=" + taskID +
		"&from_seq=" + strconv.FormatInt(fromSeq, 10)

	opts := c.wsDialOptions()
	dialCtx, dialCancel := context.WithTimeout(ctx, dialTimeout)
	conn, resp, err := websocket.Dial(dialCtx, wsURL, opts)
	dialCancel()
	if err != nil {
		if resp != nil && isPermanentStatus(resp.StatusCode) {
			return &permanentError{op: "WS 拨号", code: resp.StatusCode, cause: err}
		}
		if resp != nil {
			return fmt.Errorf("WS 拨号失败 status=%d: %w", resp.StatusCode, err)
		}
		return fmt.Errorf("WS 拨号失败: %w", err)
	}
	c.log().Debug("WS 连接建立", "addr", c.baseURL, "task", taskID, "from_seq", fromSeq)
	defer func() {
		conn.CloseNow()
		c.log().Debug("WS 连接关闭", "addr", c.baseURL, "task", taskID)
	}()

	for {
		readCtx, cancelRead := ctx, context.CancelFunc(func() {})
		if readDeadline != nil {
			if dl := readDeadline(); !dl.IsZero() {
				readCtx, cancelRead = context.WithDeadline(ctx, dl)
			}
		}
		_, b, err := conn.Read(readCtx)

		idleExpired := ctx.Err() == nil && errors.Is(readCtx.Err(), context.DeadlineExceeded)
		cancelRead()
		if err != nil {
			if idleExpired {
				return ErrIdleTimeout
			}
			if websocket.CloseStatus(err) == websocket.StatusNormalClosure {
				return errArchived
			}
			return fmt.Errorf("WS 读取: %w", err)
		}
		var ev proto.Event
		if err := json.Unmarshal(b, &ev); err != nil {

			return fmt.Errorf("WS 事件反序列化: %w", err)
		}
		if err := onFrame(ev); err != nil {
			if errors.Is(err, errStopStream) {
				return nil
			}
			return err
		}
	}
}

n_client_Client_sweepCursors.signature:
// sweepCursors 清扫本 agentd 命名空间下超期的游标与遗留临时文件。
//
// 注意：只扫自己这一篓，不碰别的 agentd 的目录——判断别人的文件是否超期需要
// 别人的上下文，本客户端没有。
func (c *Client) sweepCursors() {

	if c.cursorRoot == "" {
		return
	}
	dir := filepath.Join(c.cursorRoot, cursorNamespace(c.baseURL))
	entries, err := os.ReadDir(dir)
	if err != nil {
		c.log().Debug("扫描游标目录失败", "dir", dir, "cause", err)
		return
	}
	var removed int
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		fi, err := e.Info()
		if err != nil {
			continue
		}
		ttl := cursorTTL
		if strings.HasSuffix(e.Name(), ".tmp") {
			ttl = cursorTempTTL
		}
		if time.Since(fi.ModTime()) < ttl {
			continue
		}
		p := filepath.Join(dir, e.Name())
		if rerr := os.Remove(p); rerr != nil {
			c.log().Debug("清理超期游标失败", "path", p, "cause", rerr)
			continue
		}
		removed++
	}
	if removed > 0 {
		c.log().Debug("已清理超期游标", "dir", dir, "n", removed)
	}
}

n_client_Client_sweepStaleCursorTemps.signature:
// sweepStaleCursorTemps 清理该任务遗留的 cursor 临时文件。
//
// 为什么需要它：writeCursor 用 CreateTemp + Rename 保证原子写，进程若在两步
// 之间被杀（Ctrl+C、机器重启、oom kill）就会留下一个 .tmp，而此后没有任何
// 代码会再碰它——游标目录里的 .tmp 只增不减。
//
// 清理失败一律只记 Debug：这是顺带的卫生工作，绝不能影响 cursor 写入的成败。
func (c *Client) sweepStaleCursorTemps(dir, taskID string) {
	matches, err := filepath.Glob(filepath.Join(dir, taskID+"-*.tmp"))
	if err != nil {
		c.log().Debug("扫描遗留 cursor 临时文件失败", "task", taskID, "cause", err)
		return
	}
	for _, m := range matches {
		fi, err := os.Stat(m)
		if err != nil || time.Since(fi.ModTime()) < cursorTempTTL {
			continue
		}
		if rerr := os.Remove(m); rerr != nil {
			c.log().Debug("清理遗留 cursor 临时文件失败", "path", m, "cause", rerr)
			continue
		}
		c.log().Debug("已清理遗留 cursor 临时文件", "task", taskID, "path", m)
	}
}

n_client_Client_waitOnce.signature:
// waitOnce 建立一次 WS 连接并消费事件，直到返回首个可动作事件或连接失败。
//
// 返回：
//   - 可动作事件；连接失败/断流时返回错误（由 WaitEvent 决定是否重连）
//
// 注意：
//   - 返回错误时调用方凭 fromSeq 重连补拉，已消费的事件不会重复交付（见 WaitEvent doc）
//   - 永久性失败以 permanentError 返回（握手 400/401/403），或原样透传对端的
//     StatusPolicyViolation close（任务不存在）——两者均被 isPermanent 识别，不再重连
//   - 本函数现在是 streamOnce 的薄封装，外部行为与重构前逐字节一致；
//     正常关闭码在 streamOnce 里被识别为 errArchived，它不是永久失败，
//     WaitEvent 仍按断线重连处理（ws_backoff_test 钉住了这条等价性）
func (c *Client) waitOnce(ctx context.Context, taskID string, fromSeq int64, all bool) (*proto.Event, error) {
	var got *proto.Event
	err := c.streamOnce(ctx, taskID, fromSeq, nil, func(ev proto.Event) error {

		if !all && !isDeliverable(ev.Type) {
			c.log().Debug("wait 跳过不可交付事件", "task", taskID, "seq", ev.Seq, "type", ev.Type)
			return nil
		}
		c.log().Info("wait 事件返回", "task", taskID, "seq", ev.Seq, "type", ev.Type)
		got = &ev
		return errStopStream
	})
	if err != nil {
		return nil, err
	}
	return got, nil
}

n_client_Client_writeCursor.signature:
// writeCursor 把 seq 原子写入 cursor 文件（临时文件 + rename）。
//
// 为什么先写临时文件再 rename：直接写目标文件在写盘中途崩溃会留下截断内容，
// 下一次 wait 会把截断文本解析成 0（从头重投全部事件）；rename 保证读到的一定是
// 完整内容——要么旧值要么新值，不存在中间态。
//
// 为什么临时文件必须唯一（L-3）：两个 wait 进程/goroutine 并发写同一任务的
// 游标文件时，固定后缀的 <path>.tmp 会被两边同时打开/截断——先写完者
// rename 掉的是对方可能还没写完的共享文件，目标文件会短暂出现半截内容，对端
// 恰好读到即「读到一半的 tmp」。CreateTemp 同目录生成 O_EXCL 唯一名，rename
// 的始终是「自己写完整并关闭的文件」，并发读保证只看到完整旧值或完整新值。
func (c *Client) writeCursor(taskID string, seq int64) error {
	p, err := c.cursorPath(taskID)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o700); err != nil {
		return fmt.Errorf("创建 cursor 目录: %w", err)
	}
	f, err := os.CreateTemp(filepath.Dir(p), filepath.Base(p)+"-*.tmp")
	if err != nil {
		return fmt.Errorf("创建临时 cursor 文件: %w", err)
	}
	tmp := f.Name()
	if _, err := f.WriteString(strconv.FormatInt(seq, 10)); err != nil {
		f.Close()
		os.Remove(tmp)
		return fmt.Errorf("写临时 cursor 文件: %w", err)
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("关闭临时 cursor 文件: %w", err)
	}
	if err := os.Rename(tmp, p); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("cursor 落盘: %w", err)
	}
	c.log().Debug("cursor 写入", "task", taskID, "path", p, "seq", seq)
	c.sweepStaleCursorTemps(filepath.Dir(p), taskID)
	return nil
}

n_client_Client_wsDialOptions.signature:
// wsDialOptions 组装 WS 拨号选项：本 Client 自己的 http.Client + Bearer 头。
//
// **HTTPClient 必须显式给出，这是本函数存在的全部理由。** 不给时
// coder/websocket 退回 http.DefaultClient，而 DefaultTransport 的 Proxy 是
// http.ProxyFromEnvironment——WS 拨号会被送进 HTTP_PROXY/HTTPS_PROXY。这破的是
// proxycfg 包头写死的那条纪律：「协调者↔agentd 那条链路永不走代理」。
//
// 实测症状（B161）：本机设了 HTTP_PROXY 且 NO_PROXY 不含执行机 IP 时，每次拨号
// 都被代理回 503，follow 长连接永远建不起来，只剩每 6s 一次的 HTTP 对账兜底
// ——**而且不报错**，看起来和「executor 正在长考」一模一样，极难发现。当时
// curl 拨同一个地址是 101，因为 curl 对 http:// URL 只读小写 http_proxy。
//
// 顺带两点：c.hc 的 DialContext 已带 dialTimeout，不必再靠 DefaultClient；
// c.hc.Timeout 恒为 0（只设 Transport），满足 coder/websocket 对
// HTTPClient.Timeout 必须为零的硬要求。
//
// 单独抽成函数是为了可测：拿 HTTP_PROXY 环境变量做判据不可靠——
// net/http 对它有 sync.Once 缓存，t.Setenv 很可能不生效，测试会因为
// 「代理压根没被解析」而变绿，是典型的为错误理由通过。
func (c *Client) wsDialOptions() *websocket.DialOptions {
	opts := &websocket.DialOptions{HTTPClient: c.hc}
	if c.token != "" {
		opts.HTTPHeader = http.Header{"Authorization": []string{"Bearer " + c.token}}
	}
	for k, v := range c.extraHeaders {
		if opts.HTTPHeader == nil {
			opts.HTTPHeader = http.Header{}
		}
		opts.HTTPHeader.Set(k, v)
	}
	return opts
}

n_client_New.signature:
// New 创建 agentd 客户端。
//
// 参数：
//   - addr: agentd 地址（如 http://127.0.0.1:7777）；缺少 scheme 时自动补 http://
//   - token: Bearer 访问令牌；为空时请求不带 Authorization 头
//
// 注意：
//   - 仅做地址归一化，不做任何网络请求，连接在首次调用时建立
func New(addr, token string) *Client {
	return NewWithWSTiming(addr, token, wsInitialBackoff, wsMaxBackoff, wsStableAfter)
}

n_client_NewRelay.signature:
// NewRelay creates a client backed by a relay Dialer. The fixed baseURL is an
// HTTP URL placeholder used to build request paths and WS URLs; routing is done
// by the Dialer. token remains the agentd Bearer credential as a defense-in-depth
// layer after the relay's E2E channel is established.
//
// baseURL 的 host 必须用 loopback 名（localhost）：relay 投递的请求经隧道直达
// 对端 agentd.Handler，会先过 agentd 的 hostGuard（Host 白名单，防 DNS rebinding）。
// loopback 三件套恒在白名单内，而任意占位名（如 "relay"）会被 403 拒。语义上
// relay 投递等价于对端本地投递，用 localhost 正合适。
func NewRelay(d *relay.Dialer, token string) *Client {
	return &Client{
		baseURL:	"http://localhost",
		token:		token,
		hc: &http.Client{
			Transport: d.Transport(),
		},
		relayBacked:		true,
		wsInitialBackoff:	wsInitialBackoff,
		wsMaxBackoff:		wsMaxBackoff,
		wsStableAfter:		wsStableAfter,
	}
}

n_client_NewWithWSTiming.signature:
// NewWithWSTiming 是 New 的 WS 重连节奏可注入变体：测试注入毫秒级退避与
// 健康门槛，让「连接活够了才复位退避」的断言不必真等 1s..60s；生产一律走 New。
//
// 参数：
//   - initial/max: 断线重连的初始/封顶退避
//   - stableAfter: 连接存活多久才算健康、才复位退避（见 WaitEvent）
func NewWithWSTiming(addr, token string, initial, max, stableAfter time.Duration) *Client {
	raw := addr
	if !strings.Contains(addr, "://") {
		addr = "http://" + addr
	}
	base := strings.TrimRight(addr, "/")
	c := &Client{
		baseURL:	base,
		token:		token,
		hc: &http.Client{
			Transport: &http.Transport{
				DialContext:	(&net.Dialer{Timeout: dialTimeout}).DialContext,

				Proxy:	nil,
			},
		},
		wsInitialBackoff:	initial,
		wsMaxBackoff:		max,
		wsStableAfter:		stableAfter,
	}

	if u, err := url.Parse(base); err != nil || u.Host == "" {
		c.initErr = fmt.Errorf("agentd 地址不含主机名（原始地址 %q）：relay 形态的机器没有 addr，应经 targetclient 选路而不是直连构造", raw)
		slog.Default().Error("client 构造时地址不含主机名，该实例已毒化", "raw_addr", raw, "base_url", base)
	}
	return c
}

n_client_WaitDeliveryPolicy.signature:
// WaitDeliveryPolicy 判定 wait/follow 默认是否唤醒协调者。
//
// 这是任务事件消费策略，不是传输过滤：WS/HTTP 流必须仍能见到被判 false 的类型
// （FollowEvents all=true 与服务端 store 重放是现成证据）。传输只负责按游标可靠交付。
//
// 可交付 = 全部类型 − {progress, approver_decision, approver_disabled,
// tickets_voided, ticket_answered, permission_auto_allow, permission_reuse}。
//
// 审计类在服务端只入库不 Publish，实时流本就见不到；WS 重放读 store 会把它们
// 一并推来。不过滤就会出现「重连交付比实时流更多」的唤醒风暴。tickets_voided
// 与 completed/failed 同时刻产生，可交付会抢走一次性 wait 的收手权。
//
// 词表与 B233.1 冻结 17–26 对齐；本卡冻结的是归属（应用，不在传输），不是另造一套。
// all=true 时调用方不使用本谓词，全量交付。
func WaitDeliveryPolicy(t proto.EventType) bool {
	switch t {
	case proto.EventTypeProgress,
		proto.EventTypeApproverDecision,
		proto.EventTypeApproverDisabled,
		proto.EventTypeTicketsVoided,
		proto.EventTypeTicketAnswered,
		proto.EventTypePermissionAutoAllow,
		proto.EventTypePermissionReuse:
		return false
	}
	return true
}

n_client_classifyArchivedSnapshot.signature:
// classifyArchivedSnapshot 在权威快照里寻找真实 archived。
//
// 返回：
//   - 已归档：返回原始 archived 事件与最新水位（供断线重拉）；
//   - 任务 failed：返回 ErrDependencyFailed——等待目标已经不可能达成；
//   - 任务 completed 却找不到 archived：返回 ErrArchivedEventMissing——兼容性/
//     数据错误，绝不合成假事件；
//   - 其余活状态：返回 nil，调用方从最新水位续拉。
//
// 为什么 completed 缺 archived 是错误而不是成功：B68 的 done 路径在归档时
// 追加 archived 事件，completed 却无 archived 意味着对端 agentd 旧版或数据损坏，
// 合成假事件会骗过门闩的调用方，必须显式失败让人升级/查数据。
func classifyArchivedSnapshot(taskID string, snap *AttachInfo) (*proto.Event, int64, error) {
	var fromSeq int64
	if n := len(snap.RecentEvents); n > 0 {
		fromSeq = snap.RecentEvents[n-1].Seq
	}
	if snap.Task.State == proto.TaskStateFailed {
		return nil, fromSeq, fmt.Errorf("%w: task=%s", ErrDependencyFailed, taskID)
	}
	for i := len(snap.RecentEvents) - 1; i >= 0; i-- {
		if snap.RecentEvents[i].Type == proto.EventTypeArchived {
			ev := snap.RecentEvents[i]
			return &ev, fromSeq, nil
		}
	}
	if snap.Task.State == proto.TaskStateCompleted {
		return nil, fromSeq, fmt.Errorf("%w: task=%s", ErrArchivedEventMissing, taskID)
	}
	return nil, fromSeq, nil
}

n_client_computeBacklog.signature:
// computeBacklog 从权威快照算出积压摘要。
//
// 参数：
//   - taskID: 完整 UUID，原样写进摘要
//   - fromSeq: 本机 cursor 停在哪（0 表示本机从未交付过该任务的事件）
//   - snap: GET /api/tasks/{id} 的快照
//
// 返回：
//   - 摘要；**无积压时返回 nil**（快照事件窗口为空，或水位不超过 fromSeq）
//
// 注意：
//   - 三个计数各自独立算，不做减法（why 见 BacklogSummary.Actionable 的注释）
//   - seq 是全局 AUTOINCREMENT、跨任务共享，单任务 seq 不连续：ToSeq-FromSeq
//     不是条数，只能逐条遍历来数
func computeBacklog(taskID string, fromSeq int64, snap *AttachInfo) *BacklogSummary {
	if snap == nil || len(snap.RecentEvents) == 0 {
		return nil
	}

	toSeq := snap.RecentEvents[len(snap.RecentEvents)-1].Seq
	if toSeq <= fromSeq {
		return nil
	}

	pending := make(map[string]struct{}, len(snap.PendingTickets))
	for _, tk := range snap.PendingTickets {
		pending[tk.ID] = struct{}{}
	}

	missed, stale := 0, 0
	for _, ev := range snap.RecentEvents {

		if ev.Seq <= fromSeq || !isDeliverable(ev.Type) {
			continue
		}
		missed++
		id := ticketIDOf(ev)
		if id == "" {
			continue
		}
		if _, still := pending[id]; !still {
			stale++
		}
	}

	actionable := snap.PendingTickets
	if actionable == nil {
		actionable = []proto.Ticket{}
	}

	return &BacklogSummary{
		Type:		BacklogSummaryType,
		TaskID:		taskID,
		FromSeq:	fromSeq,
		ToSeq:		toSeq,
		State:		snap.Task.State,
		Missed:		missed,

		MissedTruncated:	snap.RecentEvents[0].Seq > fromSeq,
		Stale:			stale,
		Actionable:		actionable,
	}
}

n_client_cursorNamespace.signature:
// cursorNamespace 把 agentd 的 baseURL 折算成一个可作路径段的名字。
//
// 参数：baseURL 为 Client 持有的 agentd 地址，可带或不带 scheme
//
// 返回：只含字母数字与 . - 的路径段（如 "100.73.238.21_7777"）；无法解析时返回 "unknown"
//
// 为什么按地址而不是 --target 名字：地址是 agentd 的身份，名字只是本机别名。
// 两个 target 名指向同一台 agentd 时按名字分篓会把同一批任务的游标分裂成两份；
// 改个名字则让已有游标全部失联。这与 resolveProject 里「projectID 是身份、
// 名字只是引用」是同一个判断。
func cursorNamespace(baseURL string) string {
	host := baseURL

	if u, err := url.Parse(baseURL); err == nil && u.Host != "" {
		host = u.Host
	}
	var b strings.Builder
	for _, r := range host {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z',
			r >= '0' && r <= '9', r == '.', r == '-':
			b.WriteRune(r)
		default:
			b.WriteByte('_')
		}
	}
	if b.Len() == 0 {
		return "unknown"
	}
	return b.String()
}

n_client_decodeWire.signature:
// decodeWire 整段读入再解码（Decoder.Decode 只吃第一个 JSON 值、尾随内容被
// 静默丢弃，截断或串包会被当成有效响应——理由同 CardStep 的注释）。
func decodeWire(resp *http.Response, into any) error {
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return fmt.Errorf("读取响应: %w", err)
	}
	if err := json.Unmarshal(body, into); err != nil {
		return fmt.Errorf("解析响应 %s: %w", string(body), err)
	}
	return nil
}

n_client_encodeQuery.signature:
func encodeQuery(value string) string {
	return url.QueryEscape(value)
}

n_client_hasHTTPStatus.signature:
func hasHTTPStatus(err error, code int) bool {
	var statusErr *httpStatusError
	return errors.As(err, &statusErr) && statusErr.code == code
}

n_client_httpStatusError_Error.signature:
func (e *httpStatusError) Error() string {
	return fmt.Sprintf("%s: 状态码 %d: %s", e.op, e.code, e.body)
}

n_client_isDeliverable.signature:
// isDeliverable 是 WaitDeliveryPolicy 的包内别名。既有 wait/follow/backlog
// 调用点未迁；策略归属见 WaitDeliveryPolicy（应用，不在传输）。
func isDeliverable(t proto.EventType) bool {
	return WaitDeliveryPolicy(t)
}

n_client_isPermanent.signature:
// isPermanent 判定错误是否属于「重试无意义」的永久性失败。
//
// 判定来源：
//   - waitOnce 显式构造的 permanentError（握手状态码 400/401/403 等配置类错误）
//   - WS 对端以 StatusPolicyViolation（1008）关闭——服务端「任务不存在」的约定
//     close code（打错 task-id 的永久配置错误，见 server.go handleEvents）
//   - httpStatusError 携带 4xx 状态码（长驻等待的 Attach 快照被 401/403/404 拒绝）
//
// 为什么正常关闭（1000）/GoingAway（1001）不在此列：agentd 重启、主动断开等
// 瞬时场景都会先关连接，重连即可恢复；只有对端明示「你的请求本身非法」才该退出。
func isPermanent(err error) bool {
	var pe *permanentError
	if errors.As(err, &pe) {
		return true
	}
	var he *httpStatusError
	if errors.As(err, &he) && isPermanentStatus(he.code) {
		return true
	}
	var ce websocket.CloseError
	return errors.As(err, &ce) && ce.Code == websocket.StatusPolicyViolation
}

n_client_isPermanentStatus.signature:
// isPermanentStatus 判定握手状态码是否属于「重试无意义」的永久性失败。
//
// 为什么 400/401/403/404 永久：它们都表示请求本身非法——400 是参数错误、
// 401/403 是 token 未同步/无权限、404 是路由不存在（handoff 路由改名后旧
// agentd 会一直命中 404）。token 不同步正是文档写明的手工配对步骤（最常见的
// 配置错误），退避重连只会无限循环，且与「还没有事件」的静默挂起无法区分
// （P0-2 根因）。其余状态（如 500、网关错误）可能是 agentd 瞬时故障，继续退避重连。
func isPermanentStatus(code int) bool {
	switch code {
	case http.StatusBadRequest, http.StatusUnauthorized, http.StatusForbidden,
		http.StatusNotFound:
		return true
	}
	return false
}

n_client_permanentError_Error.signature:
func (e *permanentError) Error() string {
	return fmt.Sprintf("%s: 永久失败 code=%d: %v", e.op, e.code, e.cause)
}

n_client_probeCursorDirWritable.signature:
// probeCursorDirWritable 通过「真写一次」确认目录可写。
//
// 为什么不查权限位：沙箱（codex 的 seatbelt/landlock）的拒绝不体现在 mode 上，
// 目录 mode 是 0700 而写入照样 EPERM。唯一可靠的判据是真的建一个文件。
func probeCursorDirWritable(dir string) error {
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("创建目录: %w", err)
	}
	f, err := os.CreateTemp(dir, ".probe-*")
	if err != nil {
		return fmt.Errorf("试写: %w", err)
	}
	name := f.Name()
	f.Close()
	os.Remove(name)
	return nil
}

n_client_pullFailure.signature:
// pullFailure 返回对端针对 want 这个版本的自拉失败状态；无失败时返回 nil。
//
// 为什么要比对 tag：陈旧的失败态（上一次升别的版本没成）留在内存里，
// 若不加区分地据此中止，这台机器就永远升不上去了。
func pullFailure(st *proto.StatusResp, want string) *proto.PullState {
	if st == nil || st.Update == nil || st.Update.PullState == nil {
		return nil
	}
	ps := st.Update.PullState
	if ps.Tag != want || ps.Stage != proto.PullStageFailed {
		return nil
	}
	return ps
}

n_client_pullProgress.signature:
// pullProgress 返回对端针对 want 的进行中状态，供轮询时打进度日志。
func pullProgress(st *proto.StatusResp, want string) *proto.PullState {
	if st == nil || st.Update == nil || st.Update.PullState == nil {
		return nil
	}
	ps := st.Update.PullState
	if ps.Tag != want || ps.Stage == proto.PullStageFailed {
		return nil
	}
	return ps
}

n_client_ticketIDOf.signature:
// ticketIDOf 取事件 payload 里的 ticket_id。
//
// 参数：
//   - ev: 任意事件
//
// 返回：
//   - 工单 ID；非工单类事件、payload 非法或缺该字段时返回空串
//
// 注意：ticket_id 是 permission_request / question 事件 payload 的既有线格式契约
// （服务端定义在 internal/agentd/manager.go 的 permissionPayload / questionPayload）。
// 此处只解这一个字段，不与服务端结构体耦合。
func ticketIDOf(ev proto.Event) string {
	switch ev.Type {
	case proto.EventTypePermissionRequest, proto.EventTypeQuestion:
	default:
		return ""
	}
	var p struct {
		TicketID string `json:"ticket_id"`
	}
	if err := json.Unmarshal(ev.Payload, &p); err != nil {

		return ""
	}
	return p.TicketID
}

n_client_turnTailForLog.signature:
// turnTailForLog 把可能很长的损坏内容截到可入日志的长度。
//
// 为什么截断：损坏的 cursor 文件可能是任意内容（磁盘故障写进了别的东西），
// 原样入日志会把一行日志撑成几 MB。
func turnTailForLog(s string) string {
	const max = 64
	if len(s) <= max {
		return s
	}
	return s[:max] + "…"
}

n_client_waitArchivedRetry.signature:
// waitArchivedRetry 实现门闩的确定性退避：健康连接先把 backoff 复位为 initial，
// ctx 可取消等待，非健康失败后倍增并封顶。
//
// healthy 参数为什么能复位：连接活够 wsStableAfter 说明对端与网络都稳定，
// 上次的累积退避已无意义，重新从 initial 起步（与 WaitEvent 同语义）。
func waitArchivedRetry(ctx context.Context, backoff *time.Duration,
	initial, max time.Duration, healthy bool) error {
	if healthy {
		*backoff = initial
	}
	delay := *backoff
	timer := time.NewTimer(delay)
	defer timer.Stop()
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-timer.C:
	}
	if !healthy {
		next := delay * 2
		if next > max {
			next = max
		}
		*backoff = next
	}
	return nil
}

n_cmd_Endpoints.signature:
// Endpoints 返回要处理的机器清单。
//
// 参数：
//   - only: 为空时返回 [本机, 全部 target（按名字排序）]；非空时只返回该 target
//
// 返回：
//   - 机器清单；only 指定的 target 不存在时返回错误
//
// 为什么本机也在清单里：版本一致本身就是要解决的问题，把本机排除在外，
// 「本机新远端旧」就会成为常态。而操作者不必记住配置里有哪些 target——
// 这正是「一条命令看清所有机器」的前提（spec D2）。
func Endpoints(only string) ([]Endpoint, error) {
	p := configPath
	if p == "" {
		p = config.DefaultPath()
	}
	cfg, err := config.Load(p)
	if err != nil {
		return nil, fmt.Errorf("加载配置 %s: %w", p, err)
	}
	if only != "" {
		t, ok := cfg.Targets[only]
		if !ok {
			return nil, fmt.Errorf("target %q 未在配置 %s 中定义", only, p)
		}
		return []Endpoint{endpointForTarget(only, t)}, nil
	}
	local := localDialAddr(cfg.Listen)
	eps := []Endpoint{{Name: "本机", Addr: local, Token: cfg.Token, Local: true}}
	names := make([]string, 0, len(cfg.Targets))
	for n := range cfg.Targets {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		eps = append(eps, endpointForTarget(n, cfg.Targets[n]))
	}
	return eps, nil
}

n_cmd_Execute.signature:
// Execute 运行根命令，错误返回给 main。
func Execute() error {
	resetPerRunState(rootCmd)
	return rootCmd.Execute()
}

n_cmd_ExecuteContext.signature:
// ExecuteContext 是带 ctx 的 Execute（同样先清理单次执行的残留状态）。
//
// 参数：
//   - ctx: 传给命令 RunE 的上下文（取消即中断长驻命令，如 wait）
func ExecuteContext(ctx context.Context) error {
	resetPerRunState(rootCmd)
	return rootCmd.ExecuteContext(ctx)
}

n_cmd_ExitCode.signature:
// ExitCode 把 Execute 返回的错误换算成进程退出码。
//
// 参数：
//   - err: Execute 的返回值（nil 表示成功）
//
// 返回：
//   - 0（成功）、错误自带的专属退出码，或通用失败码 ExitFailure
func ExitCode(err error) int {
	if err == nil {
		return 0
	}
	var ec *exitCodeError
	if errors.As(err, &ec) {
		return ec.code
	}
	return ExitFailure
}

n_cmd_LocalEndpoint.signature:
// LocalEndpoint 返回**本机** agentd 的地址与令牌，忽略 --target。
//
// 返回：
//   - addr: 本机 agentd 完整地址（含 http:// 前缀）
//   - token: 本机令牌
//   - err: 配置加载失败或本机 token 为空时返回
//
// 为什么需要它而不是复用 TargetEndpoint：登记是**两跳**（本机 + 目标机，
// spec §6.1），而 TargetEndpoint 读的是包级 targetName，指定了 --target 时
// 拿不到本机端点。两跳都要发，就必须有一个不受 --target 影响的取端点入口。
func LocalEndpoint() (addr, token string, err error) {
	saved := targetName
	targetName = ""
	defer func() { targetName = saved }()
	return TargetEndpoint()
}

n_cmd_TargetEndpoint.signature:
// TargetEndpoint 根据 --target / --agentd / --config 换算实际请求的 agentd 端点与令牌。
//
// 参数（读取全局 flag）：
//   - --target 为空（本机模式）：token 一律取本地配置 cfg.Token（服务端无条件要求
//     Bearer，无 token 的本机调用必然 401）；地址由 localDialAddr 决议（loopback
//     照拨，通配/单网卡改拨 127.0.0.1，B85）；显式 --agentd 优先；cfg.Token 为空时
//     返回错误
//   - --target 非空：从配置 Targets 中查出 addr/token（远程配对）
//
// 返回：
//   - addr: agentd 完整地址（含 http:// 前缀）
//   - token: 访问令牌
//   - err: 配置加载失败、target 未定义或本机 token 为空时返回
func TargetEndpoint() (addr, token string, err error) {
	p := configPath
	if p == "" {
		p = config.DefaultPath()
	}
	cfg, err := config.Load(p)
	if err != nil {
		return "", "", fmt.Errorf("加载配置 %s: %w", p, err)
	}
	if targetName == "" {

		if cfg.Token == "" {
			return "", "", fmt.Errorf("配置 %s 未设置 token，无法认证本机 agentd", p)
		}

		if rootCmd.PersistentFlags().Changed("agentd") {
			addr = agentdURL
		} else {
			addr = localDialAddr(cfg.Listen)
		}
		return addr, cfg.Token, nil
	}
	t, ok := cfg.Targets[targetName]
	if !ok {
		return "", "", fmt.Errorf("target %q 未在配置 %s 中定义", targetName, p)
	}
	if t.IsRelay() {

		return "http://relay", t.Token, nil
	}
	return "http://" + t.Addr, t.Token, nil
}

n_cmd_actionLabel.signature:
// actionLabel 把回收动作渲染成人读标签。
func actionLabel(a proto.ReclaimAction) string {
	if a == proto.ReclaimPruned {
		return "在册条目已清理"
	}
	return "已删除"
}

n_cmd_adaptersFor.signature:
// claude 从 B128 起在所有平台注册：Windows 的输入通道（inputch_windows.go）
// 与裁决 socket（AF_UNIX，Windows 原生支持）都已落地。
// adaptersFor 按平台能力构造执行器注册表。
//
// 参数：goos 为目标平台；logger 用于播报不注册的理由
//
// 返回：可用执行器的注册表。
//
// 注意：
//   - **不注册必须有明确理由并打日志**：静默缺席会让用户以为是配置问题，
//     而 dispatch 在门口被拒时只知道「没这个执行器」
//   - grok 走**运行期能力探测**而不是按平台写死：它卡的是符号链接权限，
//     而那是部署形态决定的（管理员 / 开发者模式），同一个 Windows 上装法
//     不同结论就不同。写死等于把一台其实可用的机器判成不可用
func adaptersFor(goos string, logger *slog.Logger) map[string]executor.Adapter {
	return adaptersForWithProbe(goos, logger, os.TempDir())
}

n_cmd_adaptersForWithProbe.signature:
// adaptersForWithProbe 是 adaptersFor 的可测形态：探测目录由调用方给。
func adaptersForWithProbe(goos string, logger *slog.Logger, probeDir string) map[string]executor.Adapter {
	ads := map[string]executor.Adapter{
		"opencode":	opencode.New(logger),
		"codex":	codex.New(logger),
		"claude":	claudecode.New(logger),
		"agy":		agy.New(logger),
		"fake":		fake.New(nil),
	}
	if supported, reason := grok.SymlinkCapability(probeDir); supported {
		ads["grok"] = grok.New(logger)
	} else {
		logger.Warn("不注册 grok：本机不具备创建符号链接的能力",
			"reason", reason,
			"note", "grok 用软链让 auth 文件只有一份权威副本，改成复制会让用户那份与任务那份静默漂移")
	}
	_ = goos
	return ads
}

n_cmd_advertiseAddr.signature:
// advertiseAddr 把 listen 换成配对片段里该抄的 host:port。
//
// 参数：
//   - listen: 配置里的绑定地址（形如 0.0.0.0:7777 / 127.0.0.1:7777）
//
// 返回：
//   - 通配（0.0.0.0 / :: / 空 host）→ 第一条可广告 IP + listen 的端口
//   - 一条都探不到 → `<本机IP>:<port>`
//   - 具体 host（含 127.0.0.1）原样保留，只规范化 host:port
//
// 注意：
//   - 解析不出端口时默认 7777，与出厂 listen 一致
//   - 决策打到 slog，不要写进 init 的 stdout（那是给人抄的 yaml）
func advertiseAddr(listen string) string {
	host, port, err := net.SplitHostPort(listen)
	if err != nil {
		port = "7777"
		host = listen
	}
	switch host {
	case "0.0.0.0", "::", "":
		ips := listAdvertiseAddrs()
		if len(ips) == 0 {
			fallback := "<本机IP>:" + port
			slog.Warn("没有可广告的网卡地址，配对 addr 退回占位符", "listen", listen, "addr", fallback)
			return fallback
		}
		addr := net.JoinHostPort(ips[0].String(), port)
		slog.Info("配对 addr 选用探到的可达 IP", "listen", listen, "addr", addr, "candidates", len(ips))
		return addr
	default:
		return net.JoinHostPort(host, port)
	}
}

n_cmd_appleScriptQuote.signature:
// appleScriptQuote 把字符串包成单引号 shell 字面量（内含单引号转义为 '\”）。
//
// 为什么留在 cmd 包而不是抽公共包：拆掉 tmux 后全项目只剩这一处需要 shell 引号
// ——osascript 的 do script 参数。为一个调用点维护一个包不划算，且抽出去容易
// 被误当成「通用 shell 拼接工具」重新用起来，那正是我们刚拆掉的东西。
func appleScriptQuote(s string) string {
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

n_cmd_askDecision.signature:
// askDecision 把一次授权请求转给 adapter 并阻塞等裁决，返回 claude 认识的裁决 JSON 文本。
func askDecision(params json.RawMessage, sockPath string) string {
	var p struct {
		Arguments struct {
			ToolName	string		`json:"tool_name"`
			ToolUseID	string		`json:"tool_use_id"`
			Input		json.RawMessage	`json:"input"`
		} `json:"arguments"`
	}
	if err := json.Unmarshal(params, &p); err != nil {
		fmt.Fprintf(os.Stderr, "解析 tools/call 入参失败: %v\n", err)
		return `{"behavior":"deny","message":"handoff 无法解析授权请求"}`
	}
	askFrame, err := json.Marshal(map[string]any{
		"type":	"ask", "tool_use_id": p.Arguments.ToolUseID,
		"tool_name":	p.Arguments.ToolName, "input": p.Arguments.Input,
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "序列化 ask 帧失败: %v\n", err)
		return `{"behavior":"deny","message":"handoff 内部错误"}`
	}

	for attempt := 1; ; attempt++ {
		decision, err := exchange(sockPath, askFrame)
		if err == nil {
			fmt.Fprintf(os.Stderr, "裁决到达 tool_use_id=%s behavior=%s\n",
				p.Arguments.ToolUseID, decision.Behavior)
			b, _ := json.Marshal(map[string]any{
				"behavior":	decision.Behavior, "message": decision.Message,
				"updatedInput":	p.Arguments.Input,
			})
			return string(b)
		}
		fmt.Fprintf(os.Stderr, "裁决通道不可用（第 %d 次），%v 后重试 tool_use_id=%s: %v\n",
			attempt, permDialRetryInterval, p.Arguments.ToolUseID, err)
		time.Sleep(permDialRetryInterval)
	}
}

n_cmd_attachPriority.signature:
// attachPriority 返回任务状态在列表中的优先级（越小越靠前）：
// 可动作状态（running/waiting_answer/waiting_review）在前，终态与挂起外的
// 状态靠后——attach 是为了「看活着的执行者」，优先把能进的会话排前面。
func attachPriority(st proto.TaskState) int {
	switch st {
	case proto.TaskStateRunning:
		return 0
	case proto.TaskStateWaitingAnswer:
		return 1
	case proto.TaskStateWaitingReview:
		return 2
	default:
		return 3
	}
}

n_cmd_attendance.signature:
func attendance(a proto.ActiveTask, lookup func(taskID string) (cardID, driver string, heartbeatAt time.Time, ok bool)) attendanceResult {
	result := attendanceResult{}
	if a.Watchers == nil || *a.Watchers > 0 {
		return result
	}
	switch proto.TaskState(a.State) {
	case proto.TaskStatePending, proto.TaskStateRunning, proto.TaskStateWaitingAnswer:
		result.Unattended = true
	default:
		return result
	}
	if lookup == nil {
		return result
	}
	cardID, driver, heartbeatAt, ok := lookup(a.ID)
	if !ok || cardID == "" || driver == "" {
		return result
	}
	result.Unattended = false
	result.CardID = cardID
	result.Driver = driver
	if !heartbeatAt.IsZero() {
		result.HeartbeatAge = time.Since(heartbeatAt)
	}
	return result
}

n_cmd_autoSyncAfterWait.signature:
// autoSyncAfterWait 在任务进入等待审核的事件（completed/turn_failed）或任务
// 终结（failed）到达后，把远程任务分支同步到本地仓库。
//
// 参数：
//   - ev: 刚返回的事件；只有 completed/turn_failed/failed 触发（回合中途的
//     permission/question/progress 不触发——那时活还没干完）
//
// 注意：
//   - 全部失败路径只打印到 stderr、绝不改变 wait 的退出码：wait 的唯一职责是
//     唤醒协调者，把同步做成阻塞条件等于让「ssh 临时不通」变成「收不到完成通知」
//   - 失败（含回合失败）也同步：失败恰恰是最需要把代码拉到本地翻的时候
func autoSyncAfterWait(cmd *cobra.Command, cli waitClient, addr string, ev *proto.Event) {
	if waitNoSync || ev == nil {
		return
	}
	if !shouldAutoSync(ev.Type) {
		return
	}
	if !loadCLIConfig().Sync.Auto {
		slog.Debug("配置 sync.auto=false，跳过自动同步", "task", ev.TaskID)
		return
	}
	info, err := cli.Attach(cmd.Context(), ev.TaskID)
	if err != nil {
		fmt.Fprintln(cmd.ErrOrStderr(), "自动同步跳过：读取任务失败:", err)
		return
	}
	res, err := syncTaskBranch(cmd.Context(), &info.Task.Task)
	if err != nil {
		fmt.Fprintln(cmd.ErrOrStderr(), "自动同步跳过:", err)
		return
	}
	fmt.Fprintln(cmd.ErrOrStderr(), syncMessage(res))
}

n_cmd_baselineLine.signature:
// baselineLine 拼派发后回显给协调者的那一行（分支 + 起点 [+ base 原文] [+ 领先提示]）。
//
// 参数：
//   - task: 派发应答里的任务；BaseCommit 由 agentd 保证是 40 位 sha
//   - userBase: 用户在命令行给的 --base 原文（空=没给）
//
// 为什么要同时打三样：B76 的现场里回显只有「基线 worktre」——BaseCommit 当时
// 存的是分支名，又被 shortSHA 按短 sha 截成 7 字符，于是「任务开错了分支」这件
// 事在派发那一刻毫无痕迹，一路静默到收工 pull 才炸。三个信息同行互证，任何一
// 项不符当场看得见。
func baselineLine(task *proto.Task, userBase string) string {
	line := fmt.Sprintf("分支 %s，起点 %s", task.Branch, shortSHA(task.BaseCommit))
	if userBase != "" && !looksLikeSHA(userBase) {
		line += "（" + userBase + "）"
	}
	if task.BaseAhead > 0 {
		line += fmt.Sprintf("（任务仓库 HEAD 领先 %d 个提交，新分支不含它们）", task.BaseAhead)
	}
	return line
}

n_cmd_bindApproverOneShot.signature:
// bindApproverOneShot 绑定审批者使用的 OneShot 能力。
// 架构法边界：组装点只从同一 ads Bundle 取 OneShot；未实现能力必须启动失败，
// 禁止另起一份按名称构造表。
func bindApproverOneShot(ap *orchestration.Approver, ads map[string]executor.Adapter, name string, log *slog.Logger) error {
	if ap == nil || name == "" {
		return nil
	}
	if log == nil {
		log = slog.Default()
	}
	supported := strings.Join(executor.SupportedHarnesses(), ", ")
	ad, ok := ads[name]
	if !ok {
		err := fmt.Errorf("审批者执行者 %q 未注册（支持 OneShot 的执行者: %s）", name, supported)
		log.Error("审批者执行者未注册，无法绑定 OneShot", "executor", name, "supported", supported, "cause", err)
		return err
	}
	shot, ok := ad.(executor.OneShot)
	if !ok {
		err := fmt.Errorf("审批者执行者 %q 未实现 OneShot（支持 OneShot 的执行者: %s）", name, supported)
		log.Error("审批者执行者未实现 OneShot，无法绑定", "executor", name, "supported", supported, "cause", err)
		return err
	}
	ap.BindOneShot(shot)
	log.Info("审批者已绑定 OneShot", "executor", name)
	return nil
}

n_cmd_canonicalCLITarget.signature:
// targetClient 按登记名取一个可用的 agentd 客户端。
//
// why 不再解析出 (addr, token) 自己 client.New：relay 形态的机器**没有
// addr**，直连构造对它们恒失败（会退化成一个没有 Host 的 URL）。选路判据
// 只允许有一份，在 internal/targetclient，CLI 与 agentd 共用。
//
// canonicalCLITarget 把已登记且指向本机的 target 归一为空串。
//
// 空串本身就是本机；未知名称保留原名并返回可行动错误，不增加“本机”或
// “localhost”魔法别名。
func canonicalCLITarget(target string) (string, error) {
	if target == "" {
		return "", nil
	}
	cfg, err := config.Load(effectiveConfigPath())
	if err != nil {
		return "", fmt.Errorf("加载配置: %w", err)
	}
	t, ok := cfg.Targets[target]
	if !ok {
		return target, fmt.Errorf("目标机 %s 未登记（handoff init/机器登记先行）", target)
	}
	if config.IsSelfTarget(cfg.Listen, t) {
		return "", nil
	}
	return target, nil
}

n_cmd_cardViewWire.signature:
// cardViewWire 列表行的线格式（字段名稳定，看板/脚本共用词汇）。
func cardViewWire(view ledger.CardView) map[string]any {
	out := map[string]any{
		"id":	view.ID, "title": view.Title, "status": view.Status, "priority": view.Priority,
		"project":	view.Project, "parent": view.ParentID, "base_branch": view.BaseBranch,
		"base_frozen":	view.BaseFrozen,
		"following":	view.Following, "blocked": view.Blocked, "blocked_by": view.BlockedBy,
		"needs":	view.NeedsReason, "open_decisions": view.OpenDecisions,
	}
