n_cmd_closePtySessionsForStop.signature:
// closePtySessionsForStop 在显式停止服务前杀掉本机全部 PTY 会话。
//
// 参数：out 是命令的标准输出，用于把「关掉了几个」告诉用户。
// 返回：无。**任何失败都不阻断停服务**——用户要的是服务停下来，
// 收不干净的 ptyhost 各自持有锁，shell 退出后有 24 小时 TTL 兜底。
//
// 注意：它自己读配置拿 DataDir，不经 agentd。调用这条命令时 agentd 可能
// 已经不在了（先停了服务才想起来收口，或者它本来就崩着）。
func closePtySessionsForStop(out io.Writer) {
	cfg, err := config.Load(effectiveConfigPath())
	if err != nil {
		slog.Default().Warn("停止服务前读配置失败，跳过 PTY 收口", "cause", err)
		return
	}
	root := filepath.Join(cfg.DataDir, "ptys")
	closed, err := ptyhost.CloseAll(root, slog.Default(), ptyCloseBudget)
	if err != nil {
		slog.Default().Warn("停止服务前收口 PTY 会话失败", "root", root, "cause", err)
		return
	}
	if closed > 0 {
		fmt.Fprintf(out, "已关闭   %d 个终端会话\n", closed)
	}
}

n_cmd_compareBuild.signature:
// compareBuild 渲染「本地」行：本机 CLI 与对端 agentd 的对照结论。
//
// 优先比 release 版本号（自动更新真正关心的维度）；任一侧没有版本号时退回
// revision 比较（既有行为）。不一致**不阻断**：handoff 没有兼容矩阵，
// 版本不同不等于不兼容，并列报出交给人判。
func compareBuild(cli, agentd proto.BuildInfo) string {
	if cli.Version == "" || agentd.Version == "" {
		return compareByRevision(cli, agentd)
	}
	if cli.Version == agentd.Version {
		return cli.Version + "  一致"
	}
	return fmt.Sprintf("%s  与对端不一致（对端 %s，不一定不兼容，请自行判断）", cli.Version, agentd.Version)
}

n_cmd_compareByRevision.signature:
// compareByRevision 是任一侧没有 release 版本号时的对照（B54 之前的原样行为）。
func compareByRevision(cli, agentd proto.BuildInfo) string {
	if cli.Revision == "" {
		return "本地版本未知（非 go build 产物）"
	}
	s := short12(cli.Revision)
	if cli.Modified {
		s += "  带未提交改动"
	}
	if agentd.Revision == "" {
		return s + "  （对端版本未知，无从对照）"
	}
	if cli.Revision == agentd.Revision {
		return s + "  一致"
	}
	return s + "  与对端不一致（不一定不兼容，请自行判断）"
}

n_cmd_compensateCardDispatch.signature:
// compensateCardDispatch 回收一次已取得 task id 的失败派发。具名入口（原为
// 内联闭包），依赖声明收窄到 compensateClient；只回收，不改原始错误。
func compensateCardDispatch(ctx context.Context, cl compensateClient, cardID, target, taskID string) error {
