n_cmd_composeAnswer.signature:
// composeAnswer 把 --approve/--deny/--answer 三种裁决方式翻译成应答原文。
//
// 规则（与 manager 侧语义对齐，见 Task 8 计划）：
//   - --approve  → "allow"（manager 收到 allow 才回 once）
//   - --deny     → "deny"；带 --reason 时拼成 "deny: <原因>"（manager 对 allow 之外的
//     一律回 reject，原因随应答落库供后续追溯）
//   - --answer   → 原样透传（提问的自由文本回答，不加工）
func composeAnswer() (string, error) {
	modes := 0
	if replyApprove {
		modes++
	}
	if replyDeny {
		modes++
	}
	if replyAnswer != "" {
		modes++
	}
	if modes != 1 {
		return "", errors.New("--approve、--deny、--answer 必须且只能指定一种")
	}
	if replyApprove {
		return "allow", nil
	}
	if replyDeny {
		if reason := strings.TrimSpace(replyReason); reason != "" {
			return "deny: " + reason, nil
		}
		return "deny", nil
	}
	return replyAnswer, nil
}

n_cmd_confirmDestructive.signature:
// confirmDestructive 三处破坏性动作（close/merge/workflow migrate）的
// 二次确认：--yes 跳过；非 TTY 且无 --yes 直接拒绝（脚本必须显式表态，
// 不许静默走破坏路径）。
func confirmDestructive(cmd *cobra.Command, yes bool, msg string) error {
	if yes {
		return nil
	}
	f, ok := cmd.InOrStdin().(*os.File)
	if !ok || !isatty.IsTerminal(f.Fd()) {
		return fmt.Errorf("%s：非交互环境需 --yes 显式确认", msg)
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "%s (y/N) ", msg)
	line, _ := bufio.NewReader(cmd.InOrStdin()).ReadString('\n')
	switch strings.ToLower(strings.TrimSpace(line)) {
	case "y", "yes":
		return nil
	default:
		return fmt.Errorf("%s：已取消", msg)
	}
}

n_cmd_countSquadPolicies.signature:
func countSquadPolicies(members []proto.SquadMember) int {
	count := 0
	for _, member := range members {
		if member.MaxConcurrency > 0 {
			count++
		}
	}
