n_cmd_dispatchWithAutoRegister.signature:
// dispatchWithAutoRegister 执行「派发 → 未登记则补登记 → 重发一次」的编排。
//
// 参数：
//   - dispatch: 发一次派发请求
//   - register: 补一次登记（两跳：本机 + 目标机）
//
// 返回：
//   - 派发成功的任务；任一环节失败时返回错误
//
// 注意：
//   - 为什么「先发再被拒再重发」而不是先预检：项目解析是 dispatch 的第一道闸，
//     早于建任务目录、早于工作区准备、早于 executor 启动——被拒的全部代价就是
//     一次 HTTP 400，没有任何残留要清理。而预检还多一次 TOCTOU（查完到派发之间
//     可以 project rm），服务端照样得判（spec §6.4）
//   - **最多重发一次**：登记成功后仍被拒说明另有原因（如刚被别人 rm 掉），
//     无限重试只会把一个可诊断的失败变成一个死循环
//   - 登记失败时**不重发、不降级**，原文透出：clone 失败或落点被占都需要人去
//     那台机器上处置，替它猜只会掩盖真因
//   - 两个副作用以闭包注入，编排本身因此可以零网络单测
func dispatchWithAutoRegister(dispatch func() (*proto.Task, error), register func() error) (*proto.Task, error) {
	task, err := dispatch()
	if !isProjectNotRegistered(err) {
		return task, err
	}
	if rerr := register(); rerr != nil {
		return nil, fmt.Errorf("自动登记失败: %w", rerr)
	}
	return dispatch()
}

n_cmd_displayName.signature:
// displayName 净化设备名后再打到终端。
//
// 为什么 CLI 也要净化（服务端已经净化过一道）：CLI 可能连的是一台**旧版**
// agentd，那边没有这道处理。展示层不能假设对端一定是新版——一个构造过的
// User-Agent 能往终端里注入 ANSI 转义序列。
func displayName(s string) string {
	cleaned := strings.Map(func(r rune) rune {
		if unicode.IsControl(r) {
			return -1
		}
		return r
	}, s)
	if cleaned == "" {
		return "（未命名设备）"
	}
	rs := []rune(cleaned)
	if len(rs) > 40 {
		return string(rs[:40]) + "…"
	}
	return cleaned
}

n_cmd_durableBinCandidates.signature:
// durableBinCandidates 返回本机可能装过 handoff 的稳定路径，按优先序。
//
// install.sh 默认落点是 ~/.local/bin；HANDOFF_INSTALL_DIR 覆盖那个目录。
// PATH 上的 handoff 放最后：开发机上它有时仍指向一份临时文件。
func durableBinCandidates() []string {
	var out []string
	if dir := os.Getenv("HANDOFF_INSTALL_DIR"); dir != "" {
		out = append(out, filepath.Join(dir, "handoff"))
	}
	if home, err := os.UserHomeDir(); err == nil {
		out = append(out, filepath.Join(home, ".local", "bin", "handoff"))
	}
	if p, err := exec.LookPath("handoff"); err == nil {
		out = append(out, p)
	}
	return out
}

