n_cmd_exchange.signature:
// exchange 连一次 socket：发 ask 帧、读一条裁决帧。
func exchange(sockPath string, askFrame []byte) (struct {
	Behavior	string	`json:"behavior"`
	Message		string	`json:"message"`
}, error) {
	var decision struct {
		Behavior	string	`json:"behavior"`
		Message		string	`json:"message"`
	}
	conn, err := net.Dial("unix", sockPath)
	if err != nil {
		return decision, fmt.Errorf("连 %s: %w", sockPath, err)
	}
	defer conn.Close()
	if _, err := conn.Write(append(askFrame, '\n')); err != nil {
		return decision, fmt.Errorf("发送授权请求: %w", err)
	}
	if err := json.NewDecoder(bufio.NewReader(conn)).Decode(&decision); err != nil {
		return decision, fmt.Errorf("读取裁决: %w", err)
	}
	if decision.Behavior != "allow" && decision.Behavior != "deny" {
		return decision, fmt.Errorf("裁决 behavior 非法: %q", decision.Behavior)
	}
	return decision, nil
}

n_cmd_exchange.returns:
struct {
	Behavior	string	`json:"behavior"`
	Message		string	`json:"message"`
}, error

n_cmd_firstLineOf.signature:
// firstLineOf 取多行输出的首行，用于把子进程的失败原因压成一行。
//
// 为什么只取首行：这行文案是缀在升级报告里的，把几十行 stderr 原样铺进去
// 会把真正的结论淹掉；完整输出用户可以自己重跑那条命令拿到。
func firstLineOf(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return strings.TrimSpace(s[:i])
	}
	return strings.TrimSpace(s)
}

n_cmd_formatDirtyList.signature:
// formatDirtyList 把文件名列表拼成一行给人读；超过 dirtyListLimit 截断并补计数。
//
// 参数：files 为路径列表，可为空
// 返回：逗号连接的单行文本；files 为空时返回空串
func formatDirtyList(files []string) string {
	if len(files) == 0 {
		return ""
	}
	if len(files) <= dirtyListLimit {
		return strings.Join(files, ", ")
	}
	return fmt.Sprintf("%s ... 另有 %d 处",
		strings.Join(files[:dirtyListLimit], ", "), len(files)-dirtyListLimit)
}

n_cmd_formatSquadMembers.signature:
func formatSquadMembers(members []proto.SquadMember) string {
	labels := make([]string, len(members))
	for i, member := range members {
		labels[i] = member.Carrier
		if member.MaxConcurrency > 0 {
			labels[i] += fmt.Sprintf("/%d", member.MaxConcurrency)
		}
	}
	return strings.Join(labels, ",")
}

