n_cmd_handleRPC.signature:
// handleRPC 处理一条 JSON-RPC 请求。
//
// 返回：
//   - resp: 待回写的响应
//   - ok: false 表示这是通知（无 id），不得回响应
//
// 注意：
//   - tools/call 会阻塞直到拿到裁决（fail-closed，见 permDialRetryInterval）
func handleRPC(req rpcRequest, sockPath string) (rpcResponse, bool) {
	if len(req.ID) == 0 {
		return rpcResponse{}, false
	}
	resp := rpcResponse{JSONRPC: "2.0", ID: req.ID}
	switch req.Method {
	case "initialize":
		resp.Result = map[string]any{
			"protocolVersion":	"2024-11-05",
			"capabilities":		map[string]any{"tools": map[string]any{}},
			"serverInfo":		map[string]any{"name": "handoff", "version": "1"},
		}
	case "tools/list":
		resp.Result = map[string]any{"tools": []any{askToolDefinition}}
	case "tools/call":
		resp.Result = map[string]any{"content": []any{
			map[string]any{"type": "text", "text": askDecision(req.Params, sockPath)},
		}}
	default:
		resp.Result = map[string]any{}
	}
	return resp, true
}

n_cmd_hasLocalCommit.signature:
// hasLocalCommit 报告本地仓库里是否已有该提交对象。
//
// 参数：
//   - repo: 本地仓库路径
//   - sha:  完整或缩写的提交号
//
// 返回：true 表示对象存在且是一个 commit；空 sha、以 - 开头的 sha、仓库不可用
// 一律返回 false（不是错误——「没有」是这里的正常答案）。
//
// 为什么拒绝 - 前缀：git 会把它解释为选项，属参数注入面（与 agentd 侧
// ErrBadBaseBranch 同源）。
func hasLocalCommit(ctx context.Context, repo, sha string) bool {
	if repo == "" || sha == "" || strings.HasPrefix(sha, "-") {
		return false
	}
	err := exec.CommandContext(ctx, "git", "-C", repo, "cat-file", "-e", sha+"^{commit}").Run()
	if err != nil {
		slog.Default().Debug("本地无该基线提交，将请求全量包", "repo", repo, "sha", sha)
		return false
	}
	return true
}

