	cardNeedsCmd.Flags().BoolVar(&cardNeedsClear, "clear", false, "清除等人标记（不需要原因）")
}

n_cmd_installService.signature:
// installService 安装并启动服务单元，把结果打给用户。
//
// 参数：
//   - out: 面向用户的输出（不是日志）
//   - cfgPath: 传给 agentd 的配置路径
//
// 返回：
//   - 错误：构造管理器、解析 Spec、安装任一步失败
//
// 注意：
//   - 抽成函数是为了让 handoff init 能走**同一条**代码路径追问并代跑（B71）。
//     init 复制一份逻辑的话，两处的托管行为会各自演化
func installService(out io.Writer, cfgPath string) error {
	log := slog.Default()
	m, err := newServiceManager(log)
	if err != nil {
		return err
	}
	spec, err := resolveSpec(cfgPath)
	if err != nil {
		return err
	}
	if err := m.Install(spec); err != nil {
		return fmt.Errorf("安装服务失败: %w", err)
	}
	unit, _ := m.UnitPath()
	fmt.Fprintf(out, "已托管   %s\n", m.Kind())
	fmt.Fprintf(out, "单元     %s\n", unit)
	fmt.Fprintf(out, "二进制   %s\n", spec.BinPath)
	fmt.Fprintf(out, "配置     %s\n", spec.ConfigPath)
	fmt.Fprintf(out, "日志     %s\n", spec.LogPath)

	fmt.Fprintf(out, "\n注意     agentd 现在由 %s 托管，崩溃或退出都会被自动拉起。\n", m.Kind())
	fmt.Fprintf(out, "         临时停掉用 handoff service stop；彻底摘掉托管用 handoff service uninstall。\n")
	return nil
}

n_cmd_ipFromAddr.signature:
// ipFromAddr 从 net.InterfaceAddrs 常见的两种具体类型里取出 IP。
func ipFromAddr(a net.Addr) net.IP {
	switch v := a.(type) {
	case *net.IPNet:
		return v.IP
	case *net.IPAddr:
		return v.IP
	default:
		return nil
	}
}

n_cmd_isEphemeralBin.signature:
// isEphemeralBin 判断路径是不是 go run / go test 的编译缓存，或落在临时目录里。
//
// 这类路径不能写进 launchd/systemd：管理器下次拉起时文件多半已经没了，
// macOS 上 launchctl bootstrap 还会直接报 Input/output error（exit 5）。
func isEphemeralBin(path string) bool {
	if path == "" {
		return true
	}
	slashed := filepath.ToSlash(path)

	for _, part := range strings.Split(slashed, "/") {
		if strings.HasPrefix(part, "go-build") {
			return true
		}
	}
	// macOS 的 TempDir 是 /var/folders/.../T，Linux 常见是 /tmp；两边都要认。
	var tmps []string
	if tmp := os.TempDir(); tmp != "" {
		tmps = append(tmps, tmp)
	}
	tmps = append(tmps, "/tmp", "/var/tmp")
	for _, tmp := range tmps {
		tmpSlash := strings.TrimRight(filepath.ToSlash(tmp), "/")
		if tmpSlash == "" || tmpSlash == "/" {
			continue
		}
		if strings.HasPrefix(slashed, tmpSlash+"/") {
			return true
		}
	}
	return false
}

n_cmd_isProjectNotRegistered.signature:
// isProjectNotRegistered 报告一个 dispatch 错误是不是「目标机上没有这个项目」。
//
// 参数：
//   - err: Dispatch 返回的错误（可为 nil）
//
// 返回：
//   - true 表示可以走自动补登记后重发的路径
func isProjectNotRegistered(err error) bool {
	return err != nil && strings.Contains(err.Error(), projectNotRegisteredMarker)
}

n_cmd_isTTY.signature:
// isTTY 判定 stdin 是否为真终端。
//
// 非 TTY（管道/脚本调用）时 attach 不阻塞读输入，改为打印建议命令——
// 无人值守场景给可复制的命令即可，交互选择框对脚本无意义。
//
// 为什么用 go-isatty 而非 os.ModeCharDevice（修复 5）：字符设备≠终端——/dev/null
// 正是字符设备，旧实现会把它误判成 TTY，导致脚本按标准做法 handoff attach
// < /dev/null 走进交互分支、打完表格再报「读取选择」错误——非 TTY 降级路径在最该
// 生效的场景里失效。go-isatty 走 ioctl 查终端属性（TIOCGETA），/dev/null 无终端
// 语义 → false；管道、重定向文件同样返回 false。
func isTTY() bool {
	return isatty.IsTerminal(os.Stdin.Fd())
}

n_cmd_ledgerActor.signature:
// ledgerActor CLI 写账时的 actor 标识：cli:<user>@<host>。事件流取证用，
// 不做鉴权（账本凭据即权限边界）。
func ledgerActor() string {
	user := os.Getenv("USER")
	if user == "" {
		user = "unknown"
	}
	host, _ := os.Hostname()
	return fmt.Sprintf("cli:%s@%s", user, host)
}

n_cmd_lifecycleErr.signature:
// lifecycleErr 把生命周期操作的失败包成面向用户的报文。
//
// 参数：
//   - action: 「启动」「停止」「重启」
//   - err: 底层错误
//
// 返回：包装后的错误。单元没装时把处置直接写进报文——那是与「装了但操作
// 失败」完全不同的处置（去 install，而不是去查日志）
func lifecycleErr(action string, err error) error {
	if errors.Is(err, service.ErrNotInstalled) {
		return fmt.Errorf("%s服务失败：本机还没有 handoff 的服务单元，先跑 handoff service install（%w）", action, err)
	}
	return fmt.Errorf("%s服务失败: %w", action, err)
}

n_cmd_lifecycleManager.signature:
// lifecycleManager 取一个 Manager，是三个生命周期子命令的共用前半段。
//
// 返回：平台对应的 Manager；构造失败时返回错误（平台不支持等）
func lifecycleManager() (service.Manager, error) {
	return newServiceManager(slog.Default())
}

n_cmd_listAdvertiseAddrs.signature:
// listAdvertiseAddrs 返回本机可写入配对 addr 的 IPv4，Tailscale 在前。
//
// 返回：
//   - 过滤后的 IPv4 列表；枚举失败或筛空则返回 nil
//
// 注意：
//   - 排除 loopback、169.254.0.0/16、fe80::/10（后者本就是 IPv6，IPv4-only
//     时自然掉出；显式跳过是为了以后加 IPv6 时别把链路本地当可达地址）
//   - 同组内保持网卡枚举顺序，不按数值排序
func listAdvertiseAddrs() []net.IP {
	addrs, err := interfaceAddrs()
	if err != nil {
		slog.Warn("枚举网卡地址失败", "cause", err)
		return nil
	}
	var ts, others []net.IP
	for _, a := range addrs {
		ip := ipFromAddr(a)
		if ip == nil {
			continue
		}
		if ip.IsLoopback() || ip.IsLinkLocalUnicast() || linkLocalV4.Contains(ip) {
			continue
		}
		ip4 := ip.To4()
		if ip4 == nil {
			continue
		}

		ip4 = append(net.IP(nil), ip4...)
		if tailscaleCGNAT.Contains(ip4) {
			ts = append(ts, ip4)
		} else {
			others = append(others, ip4)
		}
	}
	return append(ts, others...)
}

n_cmd_liveText.signature:
// liveText 把存活结论渲染成一句人话。
func liveText(a proto.ActiveTask) string {
	switch a.Live {
	case proto.LiveAlive:
