n_cmd_loadCarrierRules.signature:
// loadCarrierRules 为协调者供给隔离 HOME 读取主 HOME 的载体规则和技能树。
// 架构法边界：组装点持有五家规则相对路径常量，负责从主 HOME 读取文本，
// 编排层（internal/agentd）零知识接收抽象规则集。
func loadCarrierRules(mainHome, cli string) ([]executor.ProfileFile, []executor.ProfileFile, error) {
	base := filepath.Base(cli)
	var ruleRel, skillsRel string
	switch base {
	case executor.HarnessOpenCode:
		ruleRel, skillsRel = opencode.RulesRelFile, opencode.SkillsRelDir
	case executor.HarnessClaude:
		ruleRel, skillsRel = claudecode.RulesRelFile, claudecode.SkillsRelDir
	case executor.HarnessGrok:
		ruleRel, skillsRel = grok.RulesRelFile, grok.SkillsRelDir
	case executor.HarnessCodex:
		ruleRel, skillsRel = codex.RulesRelFile, codex.SkillsRelDir
	case executor.HarnessAGY:
		ruleRel, skillsRel = agy.RulesRelFile, agy.SkillsRelDir
	default:
		return nil, nil, executor.UnsupportedError(base, executor.CapProfile)
	}
	var rules []executor.ProfileFile
	if b, err := os.ReadFile(filepath.Join(mainHome, ruleRel)); err == nil {
		rules = append(rules, executor.ProfileFile{Name: filepath.Base(ruleRel), Content: string(b)})
	} else if !errors.Is(err, os.ErrNotExist) {
		return nil, nil, err
	}
	skills, err := readSkillTree(filepath.Join(mainHome, skillsRel), "")
	return rules, skills, err
}

n_cmd_localDialAddr.signature:
// localDialAddr 决议本机模式的拨号地址：host 非 loopback（通配或单网卡 IP）
// 一律改拨 127.0.0.1 同端口（B85 确定性改写，不做先试后退）——单网卡档靠
// agentd 的 loopback 辅助监听兜底，通配档 loopback 本就在监听面里。
//
// 参数：
//   - listen: 配置里的监听地址（可能带也可能不带 scheme；带 scheme 时
//     SplitHostPort 解析失败，归 loopback 档原样保留）
//
// 返回：
//   - 带 http:// 前缀的拨号地址
//
// 已知代价（spec §3.3，接受）：新 CLI + 旧 agentd（无辅助监听）且 listen 为
// 单网卡 IP 时本机命令连接拒绝，升级 agentd 即愈。
func localDialAddr(listen string) string {
	if cls, _ := config.ClassifyListen(listen); cls != config.ListenLoopback {

		slog.Debug("本机拨号地址改写", "listen", listen, "dial", config.LocalDialAddr(listen))
	}
	return config.LocalDialAddr(listen)
}

n_cmd_localHeadCommit.signature:
// localHeadCommit 取当前工作目录所在 git 仓库的 HEAD 提交号，作为远程基线校验的基准。
//
// 返回空串的三种情况（都按「不校验」处理，不报错）：cwd 不是 git 仓库、
// 仓库还没有任何提交、git 不可用。为什么不报错：dispatch 完全可以在非仓库目录
// 发起（如只用 --prompt 派发一次性任务），把它做成硬性前提会挡掉正常用法。
func localHeadCommit() string {
	out, err := exec.Command("git", "rev-parse", "HEAD").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

n_cmd_localOriginURL.signature:
// localOriginURL 读当前目录仓库的 origin 地址；不是 git 仓库或没有 origin 时返回空串。
//
// 注意：取的是 **cwd** 的信息，因此 cwd 必须在你要登记的那个项目里。
func localOriginURL() string {
	out, err := exec.Command("git", "remote", "get-url", "origin").Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

n_cmd_localProjectRoot.signature:
// localProjectRoot 返回 cwd 所属项目在本机的位置（已归并到主工作树）。
//
// 返回：
//   - 主工作树根目录的绝对路径
//   - 错误：cwd 不是 git 仓库时返回可读提示
//
// 为什么归并：位置表一个项目只允许一行，而本仓库有十几个 linked worktree
// （spec §5）。归并算法与 agentd 侧共用同一个实现，绝不在这里复制一份。
func localProjectRoot(ctx context.Context) (string, error) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", fmt.Errorf("取当前目录: %w", err)
	}
	return workspace.MainWorktreeRoot(ctx, cwd)
}

n_cmd_logExecutorDetection.signature:
// logExecutorDetection 把四家 executor 的探测结果成表写进启动日志，并对
// 「默认执行者没找到」打一条带处置的 WARN。
//
// 参数：
//   - log: 日志入口
//   - defaultExecutor: cfg.Executor.Default
//   - rs: toolchain.Detect() 的结果
//
// 注意：
//   - **不阻断启动**：一台机器不该因为少装一个 executor 就彻底起不来；托管形态下
//     启动失败还会变成崩溃循环。codex 那条硬预检拦的是更窄的判据，两者不冲突
//   - defaultExecutor 是 fake 时不会命中任何一条（fake 不在 Detect 的四家里），
//     于是自然不告警——它是脚本演示执行者，本来就没有对应的二进制
func logExecutorDetection(log *slog.Logger, defaultExecutor string, rs []toolchain.Result) {
	attrs := make([]any, 0, len(rs)*2)
	for _, r := range rs {
		v := r.State.String()
		if r.Path != "" {

			v += "  " + r.Path
		}
		attrs = append(attrs, r.Name, v)
	}
	log.Info("executor 探测", attrs...)

	for _, r := range rs {
		if r.Name != defaultExecutor {
			continue
		}
		if r.State == toolchain.StateMissing {
			log.Warn("默认执行者未找到，派发到本机的任务会失败",
				"executor", r.Name,
				"处置", "在本机装上它，或把它所在目录写进 config.yaml 的 path_dirs")
		}
		return
	}
}

n_cmd_looksLikeSHA.signature:
// looksLikeSHA 判断字符串是否是提交号形态（全十六进制且不短于 7 位）。
// 用途单一：决定回显里要不要把用户输入的 --base 原文再打一遍——原文就是
// sha 时再打一遍是纯噪音。
func looksLikeSHA(s string) bool {
	if len(s) < 7 {
		return false
	}
	for _, r := range s {
		if !strings.ContainsRune("0123456789abcdefABCDEF", r) {
			return false
		}
	}
	return true
}

n_cmd_machineState_localSwap.signature:
// localSwap 只换本机文件（并同步 skill），不触发重启。
//
// 供两条路径用：agentd 未运行、agentd 非托管。这两种情况都不能靠接口重启，
// 换完文件如实提示由用户自己把 agentd 起回来。
func (ms *machineState) localSwap(ctx context.Context, out io.Writer, rel release.Release) outcome {
	name := ms.Ep.Name
	target, err := currentBinary()
	if err != nil {
		fmt.Fprintf(out, "%-8s 失败   取当前二进制路径: %s\n", name, err)
		return outcomeFail
	}
	newPath, err := newReleaseFetcher().Fetch(ctx, rel, filepath.Dir(target))
	if err != nil {
		slog.Default().Error("下载本机资产失败", "name", name, "cause", err)
		fmt.Fprintf(out, "%-8s 失败   %s\n", name, err)
		return outcomeFail
	}
	if _, err := activateBinary(newPath, target); err != nil {
		slog.Default().Error("替换本机二进制失败", "name", name, "cause", err)
		fmt.Fprintf(out, "%-8s 失败   替换二进制: %s\n", name, err)
		return outcomeFail
	}
	ms.syncSkill(ctx, out, target)
	return outcomeOK
}

n_cmd_machineState_localUpgrade.signature:
// localUpgrade 本机的完整升级路径：换文件 + 同步 skill + 触发 agentd 重启。
func (ms *machineState) localUpgrade(ctx context.Context, out io.Writer, peer agentdPeer, rel release.Release) outcome {
	name := ms.Ep.Name
	target, err := currentBinary()
	if err != nil {
		fmt.Fprintf(out, "%-8s 失败   取当前二进制路径: %s\n", name, err)
		return outcomeFail
	}
	newPath, err := newReleaseFetcher().Fetch(ctx, rel, filepath.Dir(target))
	if err != nil {
		slog.Default().Error("下载本机资产失败", "name", name, "cause", err)
		fmt.Fprintf(out, "%-8s 失败   %s\n", name, err)
		return outcomeFail
	}
	prev, err := activateBinary(newPath, target)
	if err != nil {
		slog.Default().Error("替换本机二进制失败", "name", name, "cause", err)
		fmt.Fprintf(out, "%-8s 失败   替换二进制: %s\n", name, err)
		return outcomeFail
	}
	ms.syncSkill(ctx, out, target)
	if _, err := peer.RestartAgentd(ctx, upgradeForce); err != nil {
		slog.Default().Error("触发本机 agentd 重启失败", "name", name, "cause", err)
		fmt.Fprintf(out, "%-8s 失败   触发重启: %s\n", name, err)
		return outcomeFail
	}
	slog.Default().Info("本机升级完成", "name", name, "target", target, "prev", prev, "version", rel.Tag)
	fmt.Fprintf(out, "%-8s 成功   已换到 %s，已触发 agentd 重启\n", name, rel.Tag)
	return outcomeOK
}

n_cmd_machineState_process.signature:
// process 对一台机器执行升级，返回结果分类。
//
// 结论来自 upgrade.Classify（唯一判据），本函数只负责把结论翻译成动作与处置建议。
// busy 闸不在 Classify 里：它是「要不要现在换」的闸，只在确实需要换版时才成立
// ——否则会对一台已是最新的忙机器建议 --force，而那条命令跑完只会说「已是最新」。
func (ms *machineState) process(ctx context.Context, cmd *cobra.Command, rel release.Release, sumFor func(context.Context, string, string) (string, error)) outcome {
	out := cmd.OutOrStdout()
	name := ms.Ep.Name
	peer := newAgentdClient(ms.Ep)
	v := upgrade.Classify(ms.toUpgrade(), rel.Tag)
	slog.Default().Info("开始处理机器", "name", name, "addr", ms.Ep.Addr, "local", ms.Ep.Local,
		"verdict", v.String(), "platform", ms.Platform, "busy", ms.Busy)
	if !ms.Ep.Local {
		return ms.remoteUpgrade(ctx, out, peer, rel, sumFor)
	}

	switch v {
	case upgrade.VerdictLatest:
		slog.Default().Info("跳过：已是最新", "name", name)
		fmt.Fprintf(out, "%-8s 跳过   已是最新\n", name)
		return outcomeSkip

	case upgrade.VerdictAgentdDown:
		return ms.swapAndTell(ctx, out, rel, "agentd 未运行，请自行重启它")

	case upgrade.VerdictUnmanaged:
		return ms.swapAndTell(ctx, out, rel, "agentd 非托管启动，请自行重启它")

	case upgrade.VerdictManagedUnknown:
		return ms.swapAndTell(ctx, out, rel, "无法确认 agentd 是否托管启动，请自行重启它")
	}

	if ms.Busy > 0 && !upgradeForce {
		slog.Default().Info("跳过：有活跃任务", "name", name, "busy", ms.Busy)
		fmt.Fprintf(out, "%-8s 跳过   %d 个活跃任务\n", name, ms.Busy)
		if ms.Ep.Local {
			fmt.Fprintf(out, "         handoff upgrade --now --force\n")
		} else {
			fmt.Fprintf(out, "         handoff upgrade --now --target %s --force\n", name)
		}
		return outcomeSkip
	}
	return ms.localUpgrade(ctx, out, peer, rel)
}

n_cmd_machineState_remoteUpgrade.signature:
func (ms *machineState) remoteUpgrade(ctx context.Context, out io.Writer, peer agentdPeer,
	rel release.Release, sumFor func(context.Context, string, string) (string, error)) outcome {
	name := ms.Ep.Name
	result := upgrade.RemoteOne(ctx, slog.Default(), ms.toUpgrade(), peer,
		cliRemoteFetcher{releaseFetcher: newReleaseFetcher(), sumFor: sumFor}, rel,
		upgrade.Options{
			Force:	upgradeForce, PreferPush: upgradePush,
			WaitPull:	upgradeWaitTimeoutPull, WaitPush: upgradeWaitTimeoutPush,
			WaitInterval:	upgradeWaitInterval,
		}, nil)
	switch result.Status {
	case upgrade.StatusOK:
		fmt.Fprintf(out, "%-8s 成功   %s → %s\n", name, result.From, result.To)
		return outcomeOK
	case upgrade.StatusSkip:
		fmt.Fprintf(out, "%-8s 跳过   %s\n", name, result.Reason)
		if result.Remedy != "" {
			fmt.Fprintf(out, "         %s\n", result.Remedy)
		}
		return outcomeSkip
	default:
		fmt.Fprintf(out, "%-8s 失败   %s\n", name, result.Reason)
		if result.Remedy != "" {
			fmt.Fprintf(out, "         %s\n", result.Remedy)
		}
		return outcomeFail
	}
}

n_cmd_machineState_swapAndTell.signature:
// swapAndTell 只换本机文件、不触发重启，并如实说明「为什么要你自己重启」。
//
// 三种本机情形共用（agentd 未运行 / 非托管 / 托管状态未知）：都不能靠接口重启，
// 差别只在给操作者的那句理由，所以理由由调用方传入。
func (ms *machineState) swapAndTell(ctx context.Context, out io.Writer, rel release.Release, why string) outcome {
	oc := ms.localSwap(ctx, out, rel)
