n_cmd_mapHuhErr.signature:
// mapHuhErr 把 huh / 终端错误译成 init 能识别的取消或原样失败。
//
// Ctrl-C 在 huh 里是 ErrUserAborted；带超时的 context 取消是 context.Canceled。
// 这两种都是用户主动离开，打 Warn。其它失败（终端不够用、huh 内部错）打 Error。
// 两种都不写盘——由调用方见到非 nil 就不 Save。
func mapHuhErr(title string, err error) error {
	if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
		slog.Warn("init 向导已取消", "title", title, "cause", err)
		return initflow.ErrCanceled
	}
	slog.Error("init huh 问答失败", "title", title, "cause", err)
	return err
}

n_cmd_markDefault.signature:
// markDefault 给缺省执行者加标注。
func markDefault(names []string, def string) []string {
	out := make([]string, 0, len(names))
	for _, n := range names {
		if n == def {
			out = append(out, n+"(默认)")
			continue
		}
		out = append(out, n)
	}
	return out
}

n_cmd_maybeNotifyUpdate.signature:
// maybeNotifyUpdate 在每条命令跑完后打一行更新提示，并在缓存过期时拉起一次
// 后台检查。
//
// 注意：
//   - 提示打在 **stderr**：stdout 是各命令的机器可读输出（dispatch 的 JSON、
//     tasks 的每行 JSON），往里掺一行人话会让 jq 直接失败
//   - 任何一步失败都静默跳过。这条路径挂在每一条命令上，它自己绝不能成为
//     故障源——少提示一次更新，比让所有命令都报错好得多
//   - 隐藏子命令自己不触发（否则每次后台检查又拉起一个后台检查）
func maybeNotifyUpdate(cmd *cobra.Command) {
	if cmd.Name() == updateCheckCmd.Name() || cmd.Name() == upgradeCmd.Name() {
		return
	}

	if _, err := os.Stat(effectiveConfigPath()); os.IsNotExist(err) {
		return
	} else if err != nil {
		return
	}
	cfg, err := config.Load(effectiveConfigPath())
	if err != nil {
		return
	}
	c := selfupdate.LoadCLICheck(cfg.DataDir)
	bi, _ := buildinfo.Read()
	if line := selfupdate.NotifyLine(c, bi.Version); line != "" {
		fmt.Fprintln(cmd.ErrOrStderr(), line)
	}
	if !selfupdate.CLICheckStale(c, time.Now().UTC()) {
		return
	}

	if testing.Testing() {
		return
	}
	startBackgroundCheck(effectiveConfigPath())
}

n_cmd_newAgentdHTTPServer.signature:
// newAgentdHTTPServer 构造 agentd 的 HTTP 服务监听（独立成函数以便测试断言超时配置）。
//
// 各超时值的 why：
//   - ReadHeaderTimeout 10s：请求头读取上限——防 slowloris（慢速请求头占满连接
//     goroutine）；配合 IdleTimeout 保证半死连接被回收
//   - ReadTimeout 30s：请求体读取上限（reply/fetch 等请求体都很小，30s 充足）。
//     只作用于请求头/体的读取，不约束 handler 执行时长，无需随 run 上限放大
//   - WriteTimeout 11min（= workspace.RunCmdTimeout + 1min 余量）：响应写入上限，
//     **必须** ≥ run 路由的执行上限——handleTaskRun 在 handler 内同步执行 RunCmd
//     （最长 RunCmdTimeout=10min），net/http 的 WriteTimeout 在 handler 执行前设下
//     deadline、响应写完前不重置，若小于命令执行上限，跑测试/lint 的审阅命令
//     （经常超 60s）会在 60s 时被掐断连接，RunCmd 随 r.Context() 取消被提前杀掉，
//     退出码 124 的文档化契约永远无法兑现。dispatch 链路的病态时长（StartServe≤10s
//     叠加 CreateSession 30s 与 PromptAsync 30s ≈ 70s）也在该上限内。对 hijacked 连接
//     （WS 事件流）**不生效**：net/http 在 Hijack 时清除连接上的全部截止时间
//     （server.go hijackLocked 里 rwc.SetDeadline(time.Time{})，实测 Go 1.26 行为），
//     coder/websocket 的 Accept 走 hijack——长连接不受该值约束
//   - IdleTimeout 120s：keep-alive 空闲连接回收，防连接池被死连接占满
func newAgentdHTTPServer(listen string, handler http.Handler) *http.Server {
	return &http.Server{
		Addr:			listen,
		Handler:		handler,
		ReadHeaderTimeout:	10 * time.Second,
		ReadTimeout:		30 * time.Second,
		WriteTimeout:		workspace.RunCmdTimeout + time.Minute,
		IdleTimeout:		120 * time.Second,
	}
}

