n_cmd_parseSquadMember.signature:
// parseSquadMember 解析一个完整 --member 值。StringArray 保留空格、斜杠和中文
// 成员名；只有整个政策值留空（即无冒号）才表示不限，避免把非法 0 静默规范化。
func parseSquadMember(raw string) (proto.SquadMember, error) {
	if strings.TrimSpace(raw) == "" {
		return proto.SquadMember{}, fmt.Errorf("--member 不能为空；合法示例：--member c1 或 --member c1:2")
	}
	if strings.Count(raw, ":") > 1 {
		return proto.SquadMember{}, fmt.Errorf("--member 载体名不能含冒号；合法示例：--member c1 或 --member c1:2")
	}
	carrier := raw
	max := 0
	if i := strings.IndexByte(raw, ':'); i >= 0 {
		carrier = raw[:i]
		rawMax := raw[i+1:]
		if strings.TrimSpace(carrier) == "" {
			return proto.SquadMember{}, fmt.Errorf("--member 必须先给载体名；合法示例：--member c1:2")
		}
		value, err := strconv.Atoi(rawMax)
		if err != nil || value <= 0 {
			return proto.SquadMember{}, fmt.Errorf("--member 政策必须是正整数；留空表示不限；合法示例：--member %s:2", carrier)
		}
		max = value
	}
	return proto.SquadMember{Carrier: carrier, MaxConcurrency: max}, nil
}

n_cmd_pickAttachTask.signature:
// pickAttachTask 无参 attach：列出任务并让用户选择进入实况。
//
// 非 TTY（stdin 非字符设备，如脚本/管道调用）打印每行建议命令后退出 0，
// 不进交互——无人值守场景给出可复制的命令即可。
func pickAttachTask(cmd *cobra.Command, cli client.AttachClient) error {
	tasks, err := cli.ListTasks(cmd.Context())
	if err != nil {
		return err
	}
	if len(tasks) == 0 {
		fmt.Fprintln(cmd.OutOrStdout(), "暂无任务")
		return nil
	}

	sort.SliceStable(tasks, func(i, j int) bool {
		pi, pj := attachPriority(tasks[i].State), attachPriority(tasks[j].State)
		if pi != pj {
			return pi < pj
		}
		return tasks[i].CreatedAt.After(tasks[j].CreatedAt)
	})

	if !isTTY() {

		printAttachSuggestions(cmd.OutOrStdout(), tasks)
		return nil
	}
	fmt.Fprintln(cmd.OutOrStdout(), "序号  name                              executor  状态            更新时间")
	for i, t := range tasks {
		name := t.Name
		if name == "" {
			name = id8(t.ID)
		}
		fmt.Fprintf(cmd.OutOrStdout(), "%2d   %-32s %-10s %-16s %s\n",
			i+1, truncateName(name), t.Executor, t.State, t.UpdatedAt.Format("2006-01-02 15:04:05"))
	}
	fmt.Fprint(cmd.OutOrStdout(), "选择序号: ")
	line, err := bufio.NewReader(cmd.InOrStdin()).ReadString('\n')
	if err != nil {
		return fmt.Errorf("读取选择: %w", err)
	}
	var n int
	if _, err := fmt.Sscanf(strings.TrimSpace(line), "%d", &n); err != nil || n < 1 || n > len(tasks) {
		return fmt.Errorf("序号 %q 非法（范围 1-%d）", strings.TrimSpace(line), len(tasks))
	}
	return runAttach(cmd, cli, tasks[n-1].ID)
}

n_cmd_printAcceptanceInFlightNotice.signature:
// printAcceptanceInFlightNotice 把本次 --accept 新增的在飞影响评论投影到 stderr。
//
// 参数：cmd 为 CLI 输出目标，st 为已打开的账本，cardID 为目标卡，fromSeq 为
// 更新前的全局事件水位。只扫描本次新增的评论，不重复实现 SetAcceptance 的
// LastType 判定；HTTP 路径不调用本函数，而是从卡时间线读取同一评论。
// 返回：读取、解码或输出失败时返回带事件上下文的错误。
func printAcceptanceInFlightNotice(cmd *cobra.Command, st *ledger.Store, cardID string, fromSeq int64) error {
	events, err := st.EventsFromAsc([]string{cardID}, fromSeq, 100)
	if err != nil {
		return fmt.Errorf("读判据更新提示: %w", err)
	}
	for _, event := range events {
		if event.Type != ledger.EvComment {
			continue
		}
		var payload struct {
			Body string `json:"body"`
		}
		if err := json.Unmarshal(event.Payload, &payload); err != nil {
			return fmt.Errorf("解码判据更新提示事件 %d: %w", event.Seq, err)
		}
		if !strings.Contains(payload.Body, ledger.AcceptanceInFlightNotice) {
			continue
		}
		if _, err := fmt.Fprintln(cmd.ErrOrStderr(), payload.Body); err != nil {
			return fmt.Errorf("输出判据更新提示: %w", err)
		}
	}
	return nil
}

n_cmd_printAttachSuggestions.signature:
// printAttachSuggestions 打印每个任务的 attach 建议命令（非 TTY 降级路径）。
//
// 远程任务必须带 --target：不带的话命令会打到本机 agentd，先 404、再 attach
// 一个本机不存在的实况——两条错都指不到「你少了个 --target」这个真原因。
func printAttachSuggestions(w io.Writer, tasks []proto.TaskView) {
	for _, t := range tasks {
		line := "handoff attach " + t.ID
		if t.Target != "" {
			line += " --target " + t.Target
		}
		fmt.Fprintln(w, line)
	}
}

