n_cmd_probeMachine.signature:
// probeMachine 对一台机器做只读探测，填 machineState。
func probeMachine(ctx context.Context, ep Endpoint) machineState {
	ms := machineState{Ep: ep}
	if ep.Local {
		bi, _ := buildinfo.Read()
		ms.Bin = bi.Version
	}
	slog.Default().Info("开始探测机器", "name", ep.Name, "addr", ep.Addr, "local", ep.Local)
	if ep.RelayURL != "" {
		if err := relay.CheckTokenEntropy(ep.Token); err != nil {
			ms.Err = err
			slog.Default().Error("relay requires high-entropy token", "name", ep.Name)
			return ms
		}
	}
	st, err := newAgentdClient(ep).Status(ctx)
	switch {
	case errors.Is(err, client.ErrStatusUnsupported):

		slog.Default().Warn("对端 agentd 过旧，未上报平台", "name", ep.Name)
	case err != nil:
		ms.Err = err
		slog.Default().Warn("探测机器失败", "name", ep.Name, "cause", err)
	default:
		ms.Agentd = st.Version.Version
		ms.Revision = st.Version.Revision
		ms.Platform = st.Version.Platform
		if st.Update != nil {
			managed := st.Update.Managed
			ms.Managed = &managed
			ms.Pull = st.Update.Pull
		}

		for _, a := range st.Active {
			if a.State == string(proto.TaskStateRunning) ||
				a.State == string(proto.TaskStateWaitingAnswer) {
				ms.Busy++
			}
		}
	}
	return ms
}

n_cmd_proxyTransport.signature:
// proxyTransport 按配置造更新链路用的 HTTP transport。
//
// 参数：
//   - cfg: 已加载的配置
//
// 返回：
//   - 配了代理的 *http.Transport；**未配代理或配置有问题时返回 nil**，
//     调用方把 nil 直接传给 release.NewClient/NewInstaller 即为标准库默认行为
//
// 注意：
//   - 坏代理走到这里只可能是绕过了 config.Load 的校验（那里已经硬拒过一道）。
//     此时降级为不用代理并打 Error，而不是 panic 或让整条命令失败——
//     升级链路本身不该因为一个附属设置而彻底不可用
func proxyTransport(cfg *config.Config) http.RoundTripper {
	if cfg == nil || cfg.Proxy == "" {
		return nil
	}
	tr, err := proxycfg.Transport(cfg.Proxy)
	if err != nil {
		slog.Default().Error("代理配置无法使用，本次出网不走代理",
			"proxy", proxycfg.Redact(cfg.Proxy), "cause", err)
		return nil
	}
	slog.Default().Info("更新链路使用代理", "proxy", proxycfg.Redact(cfg.Proxy))
	return tr
}

n_cmd_readSkillTree.signature:
// readSkillTree 递归读取技能目录树为平铺的 ProfileFile 切片。
func readSkillTree(root, rel string) ([]executor.ProfileFile, error) {
	dir := root
	if rel != "" {
		dir = filepath.Join(root, rel)
	}
	entries, err := os.ReadDir(dir)
	if errors.Is(err, os.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var out []executor.ProfileFile
	for _, e := range entries {
		child := e.Name()
		if rel != "" {
			child = filepath.Join(rel, e.Name())
		}
		p := filepath.Join(root, child)
		info, err := os.Lstat(p)
		if err != nil {
			return nil, err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			return nil, fmt.Errorf("规则源含 symlink %q", p)
		}
		if e.IsDir() {
			sub, err := readSkillTree(root, child)
			if err != nil {
				return nil, err
			}
			out = append(out, sub...)
			continue
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return nil, err
		}
		out = append(out, executor.ProfileFile{Name: child, Content: string(b)})
	}
	return out, nil
}

n_cmd_registerProjectBothHops.signature:
// registerProjectBothHops 执行「本机 + 可选目标机」两跳登记。
//
// 参数：
//   - cmd: 用于取 context 与输出流
//   - origin: cwd 的 origin（项目身份来源）
//   - name: 人可读引用名（可空，由 agentd 从 origin 末段派生）
//   - localPath: 本机位置（cwd 的主工作树）
//   - remotePath: 目标机上的落点（可空，空则让那台机器 clone 到自己的 repo_root/<名字>；
//     非空时已存在就登记它、不存在就 clone 到它）
//
// 返回：
//   - 错误：任一跳失败即返回（本机跳「够不着」除外，见「注意」）；
//     **不回滚另一跳**（登记是幂等的，重跑即可）
//
// 注意：
//   - --target 的语义是「本机与那台机器**一起**登记」，不是「只登记那台机器」：
//     项目身份是从 cwd 算的，本机位置已知，登它一并补上本机项目树那一行
//   - 本机永远不 clone（它已经有 cwd 这份了）；远程不给 path 时由它自己 clone
//   - 两跳的「成功」状态行走 cmd.ErrOrStderr()：dispatch 的自动登记路径调用本函数，
//     stdout 必须保持「第一行是任务 JSON」的既有契约（上层脚本按行解析），
//     任何额外输出都不能污染 stdout
//   - **本机那一跳连不上时降级、不失败**：纯协调者机（不跑 agentd）上本机 agentd
//     本就不存在，而本机位置只是「顺带补上的免费信息」（spec §6.2），让它否决
//     整次派发是把记账动作摆在了主线之上。判据只认 client.ErrUnreachable
//     ——拿到了响应的失败（409/400/500）仍然致命，那是真冲突。
//     两跳都做不成（无 --target 且本机连不上）时仍然报错
func registerProjectBothHops(cmd *cobra.Command, origin, name, localPath, remotePath string) error {
	localAddr, localToken, err := LocalEndpoint()
	if err != nil {
		return err
	}

	remoteName := name
	local, err := client.New(localAddr, localToken).ProjectAdd(cmd.Context(), client.ProjectAddOpts{
		OriginURL:	origin, Name: name, Path: localPath,
	})
	switch {
	case err == nil:
		remoteName = local.Name
		fmt.Fprintf(cmd.ErrOrStderr(), "本机 %s → %s\n", local.Name, local.Path)
	case errors.Is(err, client.ErrUnreachable):

		if targetName == "" {
			return fmt.Errorf("本机没有 agentd（%s 连不上），且未指定 --target：两跳都无处登记。"+
				"在本机 handoff service install 起一个，或用 --target <执行机> 登到那台机器上", localAddr)
		}
		slog.Warn("本机 agentd 够不着，跳过本机登记",
			"addr", localAddr, "origin", origin, "target", targetName, "cause", err)

		fmt.Fprintf(cmd.ErrOrStderr(), "本机 没有 agentd（%s 连不上），跳过本机登记\n", localAddr)
		fmt.Fprintln(cmd.ErrOrStderr(), "     本机项目树会缺这一行；本机起了 agentd 之后重跑 handoff project add 补上")
	default:

		return fmt.Errorf("登记到本机: %w", err)
	}
	if targetName == "" {
		slog.Info("项目登记完成", "origin", origin, "scope", "仅本机")
		return nil
	}
	remoteClient, cleanup, err := newTargetClient()
	if err != nil {
		return err
	}
	defer cleanup()
	if remotePath == "" {

		fmt.Fprintf(cmd.ErrOrStderr(), "正在让 %s 落地项目 %s（首次需要 clone，可能较慢）…\n", targetName, origin)
	}
	remote, err := remoteClient.ProjectAdd(cmd.Context(), client.ProjectAddOpts{
		OriginURL:	origin, Name: remoteName, Path: remotePath,
	})
	if err != nil {
		return fmt.Errorf("登记到 %s: %w", targetName, err)
	}
	fmt.Fprintf(cmd.ErrOrStderr(), "%s %s → %s\n", targetName, remote.Name, remote.Path)
	slog.Info("项目登记完成", "origin", origin, "target", targetName, "remote_path", remote.Path)
	return nil
}

n_cmd_regularFileExists.signature:
// regularFileExists 判断 path 是已存在的普通文件。目录或打不开都当没有。
func regularFileExists(path string) bool {
	st, err := os.Stat(path)
	return err == nil && !st.IsDir()
}

n_cmd_renderCheckRow.signature:
// renderCheckRow 渲染巡检表的一行（--check 默认行为）。
//
// 行内三段：名字（定宽）、信息、结论。结论一律来自 upgrade.Classify，本函数只负责把
// Verdict 翻译成一句话——判据不在这里，改判据请改 internal/upgrade（B64）。
//
// 本机必须分别显示二进制与 agentd 两个版本——换掉磁盘上的文件后正在跑的 agentd
// 仍是旧进程，这是正常且常见的中间态，合成一个数字就必然骗人（B59 spec §4.1）。
func renderCheckRow(w io.Writer, s machineState, latest string) {
	name := s.Ep.Name
	v := upgrade.Classify(s.toUpgrade(), latest)
	if v == upgrade.VerdictUnreachable {
		fmt.Fprintf(w, "%-8s 够不着（%s）\n", name, s.Err)
		return
	}
	info := s.Agentd
	if info == "" {
		info = revisionFallback(s.Revision)
	}
	if s.Ep.Local {
		info = "二进制 " + dispVer(s.Bin)
		if s.Agentd == "" {
			info += " · agentd 未运行"
		} else {
			info += " · agentd " + s.Agentd
		}
	}
	fmt.Fprintf(w, "%-8s %s%s%s\n", name, info, checkPad(info), checkConclusion(v))
}

n_cmd_renderCounts.signature:
// renderCounts 渲染任务计数，**只列非零的状态**。
//
// why（只列非零）：六个状态里常年有四个是 0，全列会把真正的结论淹掉。
// JSON 侧不做这个省略——人看的要短，机器读的要齐。
func renderCounts(counts map[string]int) string {
	order := []string{"pending", "running", "waiting_answer", "waiting_review", "completed", "failed"}
	parts := make([]string, 0, len(order))
	for _, k := range order {
		if n := counts[k]; n > 0 {
			parts = append(parts, fmt.Sprintf("%s %d", k, n))
		}
	}
	if len(parts) == 0 {
		return "无"
	}
	return strings.Join(parts, " · ")
}

n_cmd_renderDegraded.signature:
// renderDegraded 渲染老 agentd 的降级结论。
//
// 措辞刻意不写成失败：在版本错配这个场景里「远端过旧」正是要的答案。
// 也不写「该端点自 xxx 版本引入」——CLI 无从知道对端版本，编一个引入点就是编造。
func renderDegraded(w io.Writer, addr string) {
	fmt.Fprintf(w, "agentd   %s   可用（版本过旧）\n", addr)
	fmt.Fprintln(w, "已确认   TCP 可达 · HTTP 正常 · Bearer 鉴权通过")
	fmt.Fprintln(w, "限制     该 agentd 不支持 /api/status，详情不可得")
	fmt.Fprintln(w, "处置     升级远端 agentd 后重试")
}

n_cmd_renderDirtyRejection.signature:
// renderDirtyRejection 渲染脏树拒绝的详情。
func renderDirtyRejection(w io.Writer, taskID, workdir string, files []proto.DirtyFile) {
	fmt.Fprintln(w, "拒绝     工作树有未提交改动，未回收")
