}

n_cmd_renderFootprint.signature:
// renderFootprint 渲染体检结果。
//
// 默认过滤规则：只显示 Procs > 0（确有残留）或 Verdict != ok（我们不敢下结论）
// 的行。**后者必须显示，哪怕 Procs 是 0**——「没有残留」与「判不出」是两回事，
// 把判不出的行按 0 过滤掉，等于用一个假结论把该看的东西藏起来。
func renderFootprint(w io.Writer, fp *proto.FootprintResp) {
	if fp.Usage != nil {
		fmt.Fprintf(w, "进程     %d/%d（本机 uid 已用/上限）\n", fp.Usage.Used, fp.Usage.Limit)
	} else {

		fmt.Fprintln(w, "进程     未知（对端未提供）")
	}
	shown := 0
	for _, r := range fp.Rows {
		if !footprintAll && r.Procs == 0 && r.Verdict == string(prochost.VerdictOK) {
			continue
		}
		shown++
		line := fmt.Sprintf("  %s  %s  %s  %d 进程", short8(r.TaskID), r.Name, r.State, r.Procs)
		if r.Verdict != string(prochost.VerdictOK) {
			line += "  ⚠ " + r.Verdict
		}
		fmt.Fprintln(w, line)
	}
	if shown == 0 {
		fmt.Fprintln(w, "足迹     无残留（共体检 "+strconv.Itoa(len(fp.Rows))+" 个任务）")
	}

	if len(fp.Pty) > 0 {
		fmt.Fprintln(w, "终端会话")
		for _, p := range fp.Pty {
			procs := "未知进程数"
			if p.Procs != nil {
				procs = fmt.Sprintf("%d 进程", *p.Procs)
			}
			line := fmt.Sprintf("  %s  %s  pid %d  %s", short8(p.ID), p.BasePath, p.PID, procs)
			if p.Foreground {

				line += "  ⚠ 有前台命令"
			}
			fmt.Fprintln(w, line)
		}
	}
}

n_cmd_renderGC.signature:
func renderGC(w io.Writer, resp *proto.GCResp) {
	mode := "预览"
	if !resp.Preview {
		mode = "已执行"
	}
	if resp.ReleasableBytes == nil {
		fmt.Fprintf(w, "%s     将释放字节：未计算\n", mode)
	} else {
		fmt.Fprintf(w, "%s     将释放字节：%d\n", mode, *resp.ReleasableBytes)
	}
	fmt.Fprintf(w, "缓存     %d 行；工作树 %d 行；失败 %d\n",
		len(resp.CacheRows), len(resp.WorktreeRows), resp.Failures)
	fmt.Fprintf(w, "共扫     %d 个终态任务\n", resp.Scanned)
	for _, row := range resp.CacheRows {
		fmt.Fprintf(w, "  缓存  %s  %s  %d  %s", short8(row.TaskID), gcItemLabel(row.Status), row.Bytes, row.Path)
		if row.Error != "" {
			fmt.Fprintf(w, "  %s", row.Error)
		}
		fmt.Fprintln(w)
	}
	for _, row := range resp.WorktreeRows {
		fmt.Fprintf(w, "  工作树 %s  %s  %s  %s", short8(row.TaskID), gcItemLabel(row.Status), string(row.Worktree), row.WorkDir)
		if row.Note != "" {
			fmt.Fprintf(w, "  %s", row.Note)
		}
		if row.Error != "" {
			fmt.Fprintf(w, "  %s", row.Error)
		}
		fmt.Fprintln(w)
	}
}

n_cmd_renderMachinesTail.signature:
// renderMachinesTail 打印 --all 的机器应答情况。缺席必须可见：
// 没答上来的机器逐台列出带原因，不能让「某台机器没了」只剩一串少了的行。
func renderMachinesTail(w io.Writer, resp *proto.ProjectTreeResp) {
	fmt.Fprintln(w)
	fmt.Fprintln(w, "机器应答情况：")
	for _, m := range resp.Machines {
		name := m.Name
		if name == "" {
			name = "本机"
		}
		if m.Ok {
			fmt.Fprintf(w, "  %s  应答正常（快照 %s）\n", name, m.FetchedAt.Local().Format("15:04:05"))
			continue
		}
		reason := m.Error
		if reason == "" {
			reason = "未知原因"
		}
		fmt.Fprintf(w, "  %s  未应答：%s\n", name, firstLineOf(reason))
	}
}

n_cmd_renderProjectTree.signature:
// renderProjectTree 打印三层项目树：project → location → workspace。
//
// 形态：
//
//	handoff  (a1b2c3d4e5f60718)  git@github.com:x/handoff.git
//	  本机  /Users/dev/handoff
//	    * main  482aab1  /Users/dev/handoff
//	      w1  9e12a3b  ~/.handoff/worktrees/w1  [任务工作树]
//	  devbox  /home/dev/handoff  ← 探测失败：路径不存在
//
// 探测失败的 location 照常打印，带人话原因——「登记还在、目录已失效」必须可见。
func renderProjectTree(w io.Writer, resp *proto.ProjectTreeResp) {
	tw := tabwriter.NewWriter(w, 0, 0, 2, ' ', 0)
	for _, p := range resp.Projects {
		fmt.Fprintf(tw, "%s  (%s)  %s\n", p.Name, p.ProjectID, p.OriginURL)
		for _, l := range p.Locations {
			machine := l.Machine
			if machine == "" {
				machine = "本机"
			}
			if l.ProbeError != "" {
				fmt.Fprintf(tw, "  %s  %s  ← 探测失败：%s\n", machine, l.Path, firstLineOf(l.ProbeError))
				continue
			}
			fmt.Fprintf(tw, "  %s  %s\n", machine, l.Path)
			for _, ws := range l.Workspaces {
				marker := " "
				if ws.IsMain {
					marker = "*"
				}
				suffix := ""
				if ws.Managed {
					suffix = "  [任务工作树]"
				}
				branch := ws.Branch
				if branch == "" {
					branch = "(detached)"
				}
				fmt.Fprintf(tw, "    %s %s  %s  %s%s\n", marker, branch, ws.Head, ws.Path, suffix)
			}
		}
	}

	for _, u := range resp.Unowned {
		fmt.Fprintf(tw, "%s  (未归属)\n", u)
	}
	_ = tw.Flush()
}

n_cmd_renderReclaimList.signature:
// renderReclaimList 渲染残留列表。
//
// 注意：判不出的行**永远显示**。「没有残留」与「判不出」是两回事，把后者
// 按前者藏起来，等于用一个假结论把该看的东西盖住（同 renderFootprint 的规矩）
func renderReclaimList(w io.Writer, resp *proto.ReclaimListResp) {
	if len(resp.Rows) == 0 {
		fmt.Fprintf(w, "残留     无（共体检 %d 个终态任务）\n", resp.Scanned)
		return
	}
	fmt.Fprintf(w, "残留     %d 个终态任务仍占着 managed worktree（共体检 %d 个）\n",
		len(resp.Rows), resp.Scanned)
	for _, r := range resp.Rows {
		fmt.Fprintf(w, "  %s  %s  %s  %s  %s\n",
			short8(r.TaskID), r.Name, r.State, worktreeLabel(r), r.WorkDir)
	}
}

n_cmd_renderReclaimResult.signature:
// renderReclaimResult 渲染一次回收的结果。
func renderReclaimResult(w io.Writer, taskID string, resp *proto.ReclaimResp) {
	if resp.Action == proto.ReclaimAlreadyAbsent {
		fmt.Fprintf(w, "无残留   %s 的 managed worktree 已不在，无需回收\n", short8(taskID))
		return
	}
	fmt.Fprintf(w, "已回收   %s 的 managed worktree\n", short8(taskID))
	fmt.Fprintf(w, "工作树   %s（%s）\n", resp.WorkDir, actionLabel(resp.Action))
	if n := len(resp.Discarded); n > 0 {

		fmt.Fprintf(w, "已丢弃   %d 项未提交改动\n", n)
		for _, f := range resp.Discarded {
			fmt.Fprintf(w, "         %s  %s\n", f.Status, f.Path)
		}
	}
	if resp.Branch != "" {
		fmt.Fprintf(w, "提示     任务分支 %s 保留——reclaim 不删分支\n", resp.Branch)
	}
}

n_cmd_renderSessions.signature:
// renderSessions 渲染会话列表。
//
// 参数：
//   - w: 输出目标
//   - list: 会话列表（可为空）
func renderSessions(w io.Writer, list []proto.SessionInfo) {
	if len(list) == 0 {
		fmt.Fprintln(w, "没有浏览器会话。执行 handoff console 建立一个。")
		return
	}
	for _, s := range list {
		state := "有效"
		switch {
		case s.RevokedAt != nil:
			state = "已吊销"
		case !time.Now().Before(s.ExpiresAt):
			state = "已过期"
		}
		fmt.Fprintf(w, "%s  %s  %s  最后活跃 %s\n",
			s.ID, displayName(s.DeviceName), state, s.LastSeenAt.Local().Format("01-02 15:04"))
	}
}

n_cmd_renderStatus.signature:
// renderStatus 渲染完整状态。
func renderStatus(w io.Writer, addr string, cli proto.BuildInfo, st *proto.StatusResp) {
	renderStatusWithLookup(w, addr, cli, st, nil)
}

n_cmd_renderStatusWithLookup.signature:
func renderStatusWithLookup(w io.Writer, addr string, cli proto.BuildInfo, st *proto.StatusResp,
	lookup func(taskID string) (cardID, driver string, heartbeatAt time.Time, ok bool)) {
	fmt.Fprintf(w, "agentd   %s   可用\n", addr)
	fmt.Fprintf(w, "版本     %s\n", describeBuild(st.Version))
	fmt.Fprintf(w, "本地     %s\n", compareBuild(cli, st.Version))
	fmt.Fprintf(w, "数据     %s   已运行 %s\n", st.DataDir, humanUptime(st.StartedAt))

	if st.ListenAux != "" {
		fmt.Fprintf(w, "监听     %s（辅 %s）\n", st.Listen, st.ListenAux)
	}
	fmt.Fprintf(w, "执行者   %s\n", strings.Join(markDefault(st.Executors, st.DefaultExecutor), "  "))
	if u := st.Update; u != nil && !u.Managed {

		fmt.Fprintf(w, "更新     agentd 非托管启动，换版会被拒绝（--force 也不越过）\n")
		fmt.Fprintf(w, "         处置 在该机器上 handoff service install\n")
	}

	if targetName == "" && skillContent != "" {
		if home, err := os.UserHomeDir(); err == nil {
			if sites, _ := skill.Status(skillContent, home, defaultSkillProviders(nil)); !skill.InSync(sites) {
				fmt.Fprintf(w, "skill    有落点与当前二进制不一致，handoff skill install 重新同步\n")
			}
		}
	}

	if st.WebEmbedded != nil && !*st.WebEmbedded {
		fmt.Fprintln(w, "控制台  前端未嵌入（当前页面是 stub）；请用带 -tags embedweb 的发布构建")
	}
	fmt.Fprintln(w)
	fmt.Fprintf(w, "任务     %s\n", renderCounts(st.TaskCounts))

	if st.Proc != nil {
		fmt.Fprintf(w, "进程     %d/%d（本机 uid 已用/上限）\n", st.Proc.Used, st.Proc.Limit)
	}

	if st.PtySessions != nil {
		fmt.Fprintf(w, "终端     %d 个会话（handoff footprint 看各自占用）\n", *st.PtySessions)
	}
	if len(st.Active) == 0 {
		return
	}
	fmt.Fprintln(w, "活跃")
	for _, a := range st.Active {
		line := fmt.Sprintf("  %s  %s  %s  %s  %s",
			short8(a.ID), a.Name, a.State, a.Executor, liveText(a))

		if a.Procs != nil {
			line += fmt.Sprintf("  %d 进程", *a.Procs)
		}
		att := attendance(a, lookup)
		if att.Unattended {

			line += "  ⚠ 无人值守"
		} else if att.CardID != "" {
			line += fmt.Sprintf("  ⚠ 无人订阅（卡 %s 驱动 %s，认领于 %s）",
				att.CardID, att.Driver, claimAgeText(att.HeartbeatAge))
		}
		fmt.Fprintln(w, line)
	}
}

n_cmd_resetPerRunState.signature:
// resetPerRunState 清掉命令树上「属于上一次执行」的残留状态。
//
// 为什么必须清（进程内复用命令树时才暴露，如测试与未来的交互式复用）：
//   - ctx：cobra 只在子命令 ctx 为 nil 时才把根的 ctx 传下去
//     （ExecuteC 里的 `if cmd.ctx == nil`）。第二次执行时子命令还挂着上一次
//     那个**已取消**的 ctx，新 ctx 传不进去——命令一进 RunE 就拿到
//     context canceled，表现为「刚启动就被取消」的假故障
//   - SilenceUsage：PersistentPreRun 会把它置为 true（见 rootCmd 的 why），
//     不清零则第二次执行时连参数错误也不再打 usage
func resetPerRunState(c *cobra.Command) {

	c.SetContext(nil)
	c.SilenceUsage = false
	for _, sub := range c.Commands() {
		resetPerRunState(sub)
	}
}

n_cmd_resolveBareDiscipline.signature:
// dispatchCmd 派发一个计划任务到 agentd 执行。
//
// 使用方式：handoff dispatch [--project <名字>] [--prompt ...] [--executor x] [--model m]
// [--branch b | --new-branch b] [--base t] [--worktree w | --new-worktree]
// [--no-terminal] [plan 文件]
// resolveBareDiscipline 是裸派发的缝 1 收口（B229 契约 §2.2/§3.1）：未点名只注入
// 平台层正文（版本 0）；--discipline-file 把文件内容作 RawText 直通（不落库、版本 0，
// 服务 spec 用户故事 3 的「临时捏一份下发」）。无论哪种形态都先探目标机能力位——
// 探活失败必须保留网络/认证 cause 并停止派发；只有探活成功但能力位缺席=nil 或
// false 才交给 ResolveDispatch 产生「升级」拒发文案。
//
// 参数：cli 已装配的目标机客户端（探活用）；rawFile --discipline-file 路径（空=未点名）。
// 返回：随派发下发的正文三元组；文件不可读或拒发闸拦下时返回错误。
func resolveBareDiscipline(ctx context.Context, cli dispatchClient, rawFile string) (discipline.ResolvedDiscipline, error) {
	ref := discipline.DisciplineRef{}
	if rawFile != "" {
		content, err := os.ReadFile(rawFile)
		if err != nil {
			slog.Warn("裸派发读临时纪律正文失败", "path", rawFile, "cause", err)
			return discipline.ResolvedDiscipline{}, fmt.Errorf("读取 --discipline-file %s 失败: %w", rawFile, err)
		}
		ref.RawText = string(content)
	}
	var cap *bool
	status, err := cli.Status(ctx)
	if err != nil {
		slog.Error("裸派发前目标机探活失败", "target", targetName, "cause", err)
		return discipline.ResolvedDiscipline{}, fmt.Errorf(
			"目标机探活失败：请确认目标机可达、agentd 正在运行且 token 一致：%w", err)
	}
	cap = status.DisciplinesSupported
	res, err := discipline.ResolveDispatch(nil, ref, loadCLIConfig().PlatformInvariantsEnabled(), cap)
	if err != nil {
		slog.Warn("裸派发被拒发闸拦下", "target", targetName,
			"has_raw_text", rawFile != "", "cap_absent", cap == nil, "cause", err)
		return discipline.ResolvedDiscipline{}, err
	}
	slog.Info("裸派发纪律正文已就绪", "target", targetName,
		"source", res.Source, "bytes", len(res.Text))
	return res, nil
}

n_cmd_resolveCardDispatchDiscipline.signature:
// resolveCardDispatchDiscipline 是 CLI 模板派发的缝 1 收口（B229 契约 §2.2）：
// 绑账本 lookup 与目标机能力位探活各一次，经 discipline.ResolveDispatch 产出
// 随派发下发的正文三元组。探活失败保留网络/认证 cause 并停止派发；只有探活成功
// 但能力位缺席=nil 或 false 才产生「升级」拒发文案。未点名模板的产物是纯平台层
// 正文、版本 0（§3.1 拒发闸覆盖一切带正文派发）。
func resolveCardDispatchDiscipline(ctx context.Context, cl dispatchClient, st *ledger.Store, name, target string) (discipline.ResolvedDiscipline, error) {
	lookup := func(n string) (int, string, error) {
		d, err := st.GetDiscipline(n, 0)
		if err != nil {
			return 0, "", err
		}
		return d.Version, d.Body, nil
	}
	var cap *bool
	status, err := cl.Status(ctx)
	if err != nil {
		slog.Error("模板派发前目标机探活失败", "target", target, "cause", err)
		return discipline.ResolvedDiscipline{}, fmt.Errorf(
			"目标机探活失败：请确认目标机可达、agentd 正在运行且 token 一致：%w", err)
	}
	cap = status.DisciplinesSupported
	res, err := discipline.ResolveDispatch(lookup, discipline.DisciplineRef{Name: name},
		loadCLIConfig().PlatformInvariantsEnabled(), cap)
	if err != nil {
		return discipline.ResolvedDiscipline{}, err
	}
	slog.Info("模板派发纪律正文已就绪", "target", target,
		"discipline", name, "version", res.Version, "bytes", len(res.Text))
	return res, nil
}

n_cmd_resolveCardDispatchTemplate.signature:
// resolveCardDispatchTemplate 按账本解析裸 card dispatch 的模板。
//
// 参数：st 已打开的账本；全局 cardDispatchTemplate 是显式 --template 值。
// 返回：显式模板原样返回；无显式值时唯一模板自动返回，零/多模板返回可行动错误。
// 注意：仅供不带 --step 的裸 dispatch 使用；工作流节点模板由节点定义决定。
func resolveCardDispatchTemplate(st *ledger.Store) (string, error) {
	if strings.TrimSpace(cardDispatchTemplate) != "" {
		slog.Info("采用显式派发模板", "template", cardDispatchTemplate)
		return cardDispatchTemplate, nil
	}
	slog.Info("解析缺省派发模板")
	names, err := st.ListTemplateNames()
	if err != nil {
		slog.Warn("列派发模板失败", "cause", err)
		return "", fmt.Errorf("解析缺省派发模板: 列模板失败: %w", err)
	}
	switch len(names) {
	case 0:
		err := fmt.Errorf("派发缺少模板：账本中没有模板，请先用 template put 建立一条模板")
		slog.Warn("裸派发被拒：账本没有模板")
		return "", err
	case 1:
		slog.Info("裸派发采用唯一模板", "template", names[0])
		return names[0], nil
	default:
		err := fmt.Errorf("派发缺少模板：账本中有多条模板，请显式指定 --template（可选：%s）", strings.Join(names, "、"))
		slog.Warn("裸派发被拒：缺省模板有歧义", "templates", names)
		return "", err
	}
}

n_cmd_resolveServiceBinFrom.signature:
// resolveServiceBinFrom 把当前可执行文件收成可以写进服务单元的稳定路径。
//
// 参数：
//   - exe: 已经 EvalSymlinks 过的当前进程路径
//   - candidates: 本机可能装过 handoff 的稳定路径，按优先序
//
// 返回：
//   - 可托管的绝对路径
//   - 当前是临时文件且找不到已安装二进制时的错误
//
// 注意：宁可拒绝，也不把 go-build 缓存写进 plist。现场用 go run . init
// 代装服务时，那条路径就是用户日志里的
// Library/Caches/go-build/.../handoff。
func resolveServiceBinFrom(exe string, candidates []string) (string, error) {
	if exe != "" && !isEphemeralBin(exe) {
		slog.Debug("服务二进制使用当前进程", "bin", exe)
		return exe, nil
	}
	slog.Warn("当前二进制是临时编译产物，不能交给进程管理器", "exe", exe)
	for _, c := range candidates {
		if c == "" {
			continue
		}
		resolved := c
		if r, err := filepath.EvalSymlinks(c); err == nil {
			resolved = r
		}
		if resolved == exe || isEphemeralBin(resolved) {
			continue
		}
		if !regularFileExists(resolved) {
			continue
		}
		slog.Info("改用已安装的 handoff 二进制托管", "bin", resolved, "rejected", exe)
		return resolved, nil
	}
	return "", fmt.Errorf("当前二进制是 go run / 编译缓存里的临时文件（%s），不能写进服务单元。请用安装好的 handoff 执行 service install，或先 go build -o ~/.local/bin/handoff .", exe)
}

n_cmd_resolveSpec.signature:
// resolveSpec 组装 Spec：二进制绝对路径 + 配置路径 + 日志路径。
//
// 返回：
//   - 填好的 Spec
//   - 错误：取不到可执行文件路径或加载配置失败
//
// 注意：
//   - BinPath 必须经 EvalSymlinks 解析。装在 ~/.local/bin/handoff 的二进制
//     常常是个 symlink；单元里写 symlink，换版换掉链接目标后单元还指着旧的
//   - go run 的 os.Executable 落在编译缓存里。launchd 加载那种路径会
//     Bootstrap failed: 5: Input/output error，缓存一清服务也死。必须换成
//     已安装的稳定二进制，找不到就硬拒，不能把临时路径写进单元。
func resolveSpec(cfgPath string) (service.Spec, error) {
	exe, err := osExecutable()
	if err != nil {
		return service.Spec{}, fmt.Errorf("取当前可执行文件路径: %w", err)
	}
	if resolved, err := filepath.EvalSymlinks(exe); err == nil {
		exe = resolved
	}
	exe, err = resolveServiceBinFrom(exe, durableBinCandidates())
	if err != nil {
		return service.Spec{}, err
	}
	cfg, err := config.Load(cfgPath)
	if err != nil {
		return service.Spec{}, fmt.Errorf("加载配置 %s: %w", cfgPath, err)
	}
	return service.Spec{
		BinPath:	exe,
		ConfigPath:	cfgPath,
		LogPath:	filepath.Join(cfg.DataDir, "agentd.log"),
	}, nil
}

n_cmd_revisionFallback.signature:
// revisionFallback 在没有 release 版本号时渲染提交号，两者都没有才留空。
//
// 参数：rev 为对端上报的 VCS 提交号（可能为空）。
//
// 为什么截到 12 位：与 handoff status 的版本行同宽，两处对同一台机器的称呼
// 必须一致，否则对照两份输出时会以为是两台机器。
func revisionFallback(rev string) string {
	if rev == "" {
		return ""
	}
	if len(rev) > 12 {
		rev = rev[:12]
	}
	return rev + "（非 release 构建）"
}

n_cmd_revisionText.signature:
// revisionText 渲染 revision 行。
//
// 参数：
//   - b: 构建标识
//
// 返回：
//   - 一行文本；Revision 为空时如实说明「非 go build 产物」而不是留空
func revisionText(b proto.BuildInfo) string {
	if b.Revision == "" {
		return "未知（非 go build 产物）"
	}
	s := b.Revision
	if b.Time != "" {
		s += "  " + b.Time
	}
	if b.Modified {

		s += "  带未提交改动"
	}
	return s
}

n_cmd_roomMessageBody.signature:
// roomMessageBody 解出事件正文；非 room_message 或解码失败返回空串。
func roomMessageBody(ev proto.LedgerEvent) string {
	var m proto.RoomMessage
	if err := json.Unmarshal(ev.Payload, &m); err != nil {
		return ""
	}
	return m.Body
}

n_cmd_roomServiceFor.signature:
// roomServiceFor 是 CLI 侧 collab 的唯一绑定点（架构法第八条：组装点之外
// 不得 new 他方具体类型）。openRoomService 与派发指针 writeDispatchPointer
// 共用它绑定 collab 服务，不在两处分别构造。
