n_cmd_runFollow.signature:
// runFollow 持续订阅任务事件流，每条事件单行输出到 stdout，直到任务终结。
//
// 参数：
//   - taskID: 完整 UUID（agentd 精确匹配，不做前缀补全）
//
// 返回：
//   - nil: 任务终结（failed 或已归档），退出 0
//   - ExitTimeout 的 exitCodeError: 空闲超过 --timeout
//   - 其他错误: 鉴权失败 / 任务不存在 / 连接永久失败
//
// 注意：
//   - stdout 严格是「每事件一行 JSON」，任何人读信息一律走 stderr——上层
//     （Monitor）按行解析，多打一行说明就会打断它
func runFollow(cmd *cobra.Command, taskID, addr string, cli waitClient) error {

	go warnIfTimeoutBelowStall(cmd.Context(), cli, waitTimeout)

	err := cli.FollowEvents(cmd.Context(), taskID, false, waitTimeout,
		func(ev *proto.Event) error {
			if notifyFlag {
				notifyEvent(ev)
			}
			if err := writeEventLine(cmd.OutOrStdout(), ev); err != nil {
				return err
			}

			autoSyncAfterWait(cmd, cli, addr, ev)
			return nil
		},
		func(sum *client.BacklogSummary) error {
			if notifyFlag {
				notifyBacklog(sum)
			}
			return writeBacklogLine(cmd.OutOrStdout(), sum)
		})
	switch {
	case err == nil:
		slog.Info("follow 正常结束：任务已终结", "task", taskID)
		return nil
	case errors.Is(err, client.ErrIdleTimeout):
		slog.Error("follow 空闲超时：期间未收到任何帧（含 progress）",
			"task", taskID, "timeout", waitTimeout.String())
		return &exitCodeError{code: ExitTimeout, err: fmt.Errorf(
			"follow 空闲超时（%s）：期间一帧都没收到。agentd 的 stalled 本应先到，"+
				"先跑 handoff show 看任务状态，再怀疑 agentd 是否失联", waitTimeout)}
	default:
		return err
	}
}

n_cmd_runFrames.signature:
// runFrames 打开帧流并把每一行原样写到 out。
//
// 参数：
//   - addr/token: agentd 端点与令牌（token 只进请求头，绝不进日志或输出）
//   - taskID:     完整 UUID
//   - offset/tail/follow: 与 GET /api/tasks/{id}/frames 的同名参数一致（字节）
//
// 注意：
//   - 空行是服务端的心跳保活，跳过不输出——它不是帧，喷给消费方会让
//     按行解析的脚本收到一条解析失败
//   - follow 模式下本函数直到 ctx 取消（Ctrl+C）或服务端断流才返回
func runFrames(ctx context.Context, addr, token, taskID string,
	offset, tail int64, follow bool, out io.Writer) error {
	return runFramesClient(ctx, client.New(addr, token), taskID, offset, tail, follow, out)
}

n_cmd_runFramesClient.signature:
func runFramesClient(ctx context.Context, c client.FramesClient, taskID string,
	offset, tail int64, follow bool, out io.Writer) error {
	rc, size, err := c.FramesStream(ctx, taskID, offset, tail, follow)
	if err != nil {
		return err
	}
	defer rc.Close()

	sc := bufio.NewScanner(rc)

	sc.Buffer(make([]byte, 0, 64<<10), 1<<20)
	for sc.Scan() {
		line := sc.Bytes()
		if len(line) == 0 {
			continue
		}
		if _, err := fmt.Fprintf(out, "%s\n", line); err != nil {
			return fmt.Errorf("输出帧: %w", err)
		}
	}
	if err := sc.Err(); err != nil {

		if ctx.Err() != nil {
			return nil
		}
		return fmt.Errorf("读帧流（文件当前 %d 字节）: %w", size, err)
	}
	return nil
}

n_cmd_runGC.signature:
// runGC 调用目标 agentd 的单次预览或执行入口。
func runGC(cmd *cobra.Command, cl client.GCClient, addr string) error {
	slog.Default().Info("CLI gc 进入", "target", addr, "force", gcForce, "execute", gcYes, "json", gcJSON)
	var (
		resp	*proto.GCResp
		err	error
	)
	if gcYes {
		resp, err = cl.GC(cmd.Context(), gcForce)
	} else {
		resp, err = cl.GCPreview(cmd.Context(), gcForce)
	}
	if errors.Is(err, client.ErrGCUnsupported) {
		slog.Default().Info("CLI gc 对端过旧", "target", addr)
		_, printErr := fmt.Fprintf(cmd.OutOrStdout(), "agentd %s 过旧，升级后再跑 gc\n", addr)
		return printErr
	}
	if err != nil {
		slog.Default().Error("CLI gc 请求失败", "target", addr, "cause", err)
		return err
	}
	out := cmd.OutOrStdout()
	if gcJSON {
		if err := json.NewEncoder(out).Encode(resp); err != nil {
			slog.Default().Error("CLI gc JSON 输出失败", "target", addr, "cause", err)
			return err
		}
	} else {
		renderGC(out, resp)
	}
	if !resp.Preview && resp.Failures > 0 {
		slog.Default().Error("CLI gc 执行有失败项", "target", addr, "failures", resp.Failures)
		return fmt.Errorf("gc 有 %d 项本应删除但失败", resp.Failures)
	}
	slog.Default().Info("CLI gc 完成", "target", addr, "preview", resp.Preview, "failures", resp.Failures)
	return nil
}

n_cmd_runReclaimList.signature:
// runReclaimList 列出残留。
//
// 注意：**恒退 0**。这是一份报告，「有残留」是它的正常结论而非失败；
// 只有拿不到列表（连不上、401、5xx）才退非零
func runReclaimList(cmd *cobra.Command, cl client.ReclaimClient, addr string) error {
	out := cmd.OutOrStdout()
	resp, err := cl.ReclaimList(cmd.Context())
	switch {
	case errors.Is(err, client.ErrReclaimUnsupported):

		fmt.Fprintf(out, "agentd   %s   可用（版本过旧）\n", addr)
		fmt.Fprintln(out, "限制     该 agentd 不支持 /api/reclaim，残留不可得")
		fmt.Fprintln(out, "处置     升级远端 agentd 后重试")
		return nil
	case err != nil:
		return err
	}
	if reclaimJSON {
		return json.NewEncoder(out).Encode(resp)
	}
	renderReclaimList(out, resp)
	return nil
}

n_cmd_runReclaimOne.signature:
// runReclaimOne 回收单个任务的工作树。
//
// 注意：脏树被拒时把清单渲染到 stdout，只让 cobra 往 stderr 打一行短因由——
// 详情给人看、单行给脚本看，两边都不被对方淹没
func runReclaimOne(cmd *cobra.Command, cl client.ReclaimClient, taskID, addr string) error {
	out := cmd.OutOrStdout()
	resp, err := cl.Reclaim(cmd.Context(), taskID, reclaimForce)
	var rej *client.ReclaimRejected
	switch {
	case errors.Is(err, client.ErrReclaimUnsupported):
		fmt.Fprintf(out, "agentd   %s   可用（版本过旧）\n", addr)
		fmt.Fprintln(out, "限制     该 agentd 不支持 worktree 回收")
		fmt.Fprintln(out, "处置     升级远端 agentd，或上机器手动 git worktree remove")
		return nil
	case errors.As(err, &rej):
		if rej.Reason == proto.ReasonDirty {
			renderDirtyRejection(out, taskID, "", rej.Dirty)
			return errors.New("未回收：工作树有未提交改动")
		}
		return err
	case err != nil:
		return err
	}
	renderReclaimResult(out, taskID, resp)
	return nil
}

