n_cmd_runUntilDone.signature:
// runUntilDone 实现 B67 依赖门闩：静默等待真实 archived，成功只输出一行事件。
//
// 参数：
//   - taskID: 完整 UUID
//   - waitTimeout: 总时限。它被套在 ctx 上，任何中间帧/重连都不能重置——
//     到点即 124，与「事件到达退出 0」可区分
//
// 返回：
//   - nil: 已归档，stdout 是原始 archived JSON（唯一写 stdout 的路径）
//   - exitCodeError(ExitTimeout): 总时限到，任务尚未归档
//   - 其他: 依赖 failed / 鉴权 / 任务不存在 / 协议异常（退出 1）
//
// 边界：不写审核者 cursor、不自动派发后续任务；等待期间 stdout 恒为空。
func runUntilDone(cmd *cobra.Command, taskID, addr string, cli waitClient) error {
	ctx := cmd.Context()
	if waitTimeout > 0 {
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, waitTimeout)
		defer cancel()
	}
	slog.Debug("等待依赖任务归档", "task", taskID, "addr", addr,
		"timeout", waitTimeout.String())
	ev, err := cli.WaitArchived(ctx, taskID)
	if err != nil {
		switch {
		case waitTimeout > 0 && errors.Is(err, context.DeadlineExceeded):
			slog.Error("等待依赖任务归档超时",
				"task", taskID, "timeout", waitTimeout.String(), "cause", err)
			return &exitCodeError{code: ExitTimeout, err: fmt.Errorf(
				"等待任务 %s 归档超时（%s）", taskID, waitTimeout)}
		case errors.Is(err, client.ErrDependencyFailed):
			slog.Error("依赖任务失败，归档门闩终止", "task", taskID, "cause", err)
			return fmt.Errorf("依赖任务 %s 已失败: %w", taskID, err)
		case errors.Is(err, client.ErrArchivedEventMissing):
			slog.Error("任务已完成但缺归档事件", "task", taskID, "cause", err)
			return fmt.Errorf("任务 %s 已归档但缺 archived 事件；请升级对端 agentd 或检查事件数据: %w",
				taskID, err)
		default:
			slog.Error("等待依赖任务归档失败", "task", taskID, "cause", err)
			return err
		}
	}
	if notifyFlag {
		notifyEvent(ev)
	}
	if err := writeEventLine(cmd.OutOrStdout(), ev); err != nil {
		slog.Error("输出归档事件失败", "task", taskID, "seq", ev.Seq, "cause", err)
		return err
	}
	slog.Debug("依赖任务已归档", "task", taskID, "seq", ev.Seq)
	return nil
}

n_cmd_runWaitOnce.signature:
// runWaitOnce 实现 wait 的一次性消费路径：等一个可动作事件、按 --notify 发系统
// 通知、单行写出事件 JSON，事件为回合终态时自动同步远程分支到本地。
//
// 它是「cmd wait 一次性消费点」的具名可注入入口（B233.16 契约冻结，spec 接缝
// 表第 9 行）——RunE 只负责组装（取 addr / 构造 client / 三形态分派），不内联
// 跨机调用，最小替身才能替换该跨机动作。
func runWaitOnce(cmd *cobra.Command, cli waitClient, taskID, addr string) error {
	ctx := cmd.Context()
	if waitTimeout > 0 {
		// 到点 ctx 触发 DeadlineExceeded：WaitEvent 返回 ctx.Err()，
		// 下方转成带时长的明确报错（区别于事件到达的正常返回）
		var cancel context.CancelFunc
		ctx, cancel = context.WithTimeout(ctx, waitTimeout)
		defer cancel()
	}

	ev, err := cli.WaitEvent(ctx, taskID, false)
	if err != nil {
		if waitTimeout > 0 && errors.Is(err, context.DeadlineExceeded) {
			slog.Error("wait 超时未等到事件", "task", taskID, "timeout", waitTimeout.String())

			return &exitCodeError{code: ExitTimeout,
				err:	fmt.Errorf("wait 超时（%s）未等到事件", waitTimeout)}
		}
		return err
	}
	if notifyFlag {
		notifyEvent(ev)
	}
	if err := writeEventLine(cmd.OutOrStdout(), ev); err != nil {
		return err
	}

	autoSyncAfterWait(cmd, cli, addr, ev)
	return nil
}

n_cmd_servePermissionHook.signature:
func servePermissionHook(r io.Reader, w io.Writer, sockPath string) error {
	data, err := io.ReadAll(r)
	if err != nil {
		fmt.Fprintf(os.Stderr, "读取 stdin 失败: %v\n", err)
		enc := json.NewEncoder(w)
		_ = enc.Encode(hookDecisionOutput{Decision: "deny", Reason: "读取权限请求失败"})
		return nil
	}

	var req hookPreToolUseInput
	if err := json.Unmarshal(data, &req); err != nil {
		fmt.Fprintf(os.Stderr, "解析 PreToolUse 入参失败: %v\n", err)
		enc := json.NewEncoder(w)
		_ = enc.Encode(hookDecisionOutput{Decision: "deny", Reason: "解析权限请求失败"})
		return nil
	}

	toolUseID := fmt.Sprintf("step_%d", req.StepIdx)

	askFrame, err := json.Marshal(map[string]any{
		"type":		"ask",
		"tool_use_id":	toolUseID,
		"tool_name":	req.ToolCall.Name,
		"input":	req.ToolCall.Args,
	})
	if err != nil {
		fmt.Fprintf(os.Stderr, "序列化 ask 帧失败: %v\n", err)
		enc := json.NewEncoder(w)
		_ = enc.Encode(hookDecisionOutput{Decision: "deny", Reason: "序列化权限请求失败"})
		return nil
	}

	for attempt := 1; ; attempt++ {
		decision, err := exchange(sockPath, askFrame)
		if err == nil {
			fmt.Fprintf(os.Stderr, "裁决到达 tool_use_id=%s behavior=%s\n", toolUseID, decision.Behavior)
			out := hookDecisionOutput{
				Decision:	decision.Behavior,
				Reason:		decision.Message,
			}
			if out.Decision != "allow" && out.Decision != "deny" {
				out.Decision = "deny"
			}
			return json.NewEncoder(w).Encode(out)
		}
		fmt.Fprintf(os.Stderr, "裁决通道不可用（第 %d 次），%v 后重试 tool_use_id=%s: %v\n",
			attempt, permDialRetryInterval, toolUseID, err)
		time.Sleep(permDialRetryInterval)
	}
}

n_cmd_servePermissionMCP.signature:
// servePermissionMCP 读 stdin 的 JSON-RPC 行流并逐条应答，直到 stdin 关闭。
//
// 注意：
//   - 日志一律写 stderr（stdout 是 JSON-RPC 通道，混入任何非协议内容都会让
//     claude 侧解析失败）
func servePermissionMCP(sockPath string) error {
	fmt.Fprintf(os.Stderr, "handoff permission-mcp 启动，sock=%s\n", sockPath)
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
	enc := json.NewEncoder(os.Stdout)
	for sc.Scan() {
		line := sc.Bytes()
		if len(line) == 0 {
			continue
		}
		var req rpcRequest
		if err := json.Unmarshal(line, &req); err != nil {
			fmt.Fprintf(os.Stderr, "解析请求失败，跳过: %v\n", err)
			continue
		}
		resp, ok := handleRPC(req, sockPath)
		if !ok {
			continue
		}
		if err := enc.Encode(resp); err != nil {
			fmt.Fprintf(os.Stderr, "回写响应失败: %v\n", err)
			return err
		}
	}
	fmt.Fprintln(os.Stderr, "handoff permission-mcp 退出（stdin 关闭）")
	return sc.Err()
}

n_cmd_setupLedger.signature:
// setupLedger 打开账本库并挂载镜像子系统。
//
// B229 §2.6：ledger.enabled 开关退休，账本变必需品——本函数恒执行，
// 不再看任何开关位。dsn 空 = DataDir/ledger.db 单机回退。
//
// 参数：cfg 取 Ledger.DSN 与 DataDir；srv 接收 SetLedger 注入并出镜像
// 所需的 target 客户端池；taskStore 是本机任务事件库，供本机账本源读取；
// ctx 是镜像生命周期（随 agentd 停机取消）；logger 为启动日志入口。
//
// 返回：stop 必须由调用方 defer，且保证先于账本库 Close 执行——订阅
// 回调在写库，Stop 先于 Close 是硬约束（本函数把 Close 一并收进 stop，
// 调用方只需 defer stop() 一个动作）。
func setupLedger(cfg *config.Config, srv *agentd.Server, taskStore *store.Store, ctx context.Context,
	logger *slog.Logger) (func(), error) {
	ldsn := cfg.Ledger.DSN
	if ldsn == "" {
		ldsn = filepath.Join(cfg.DataDir, "ledger.db")
	}
	lst, err := ledger.Open(ldsn)
	if err != nil {
		logger.Error("打开账本库失败", "dsn", ldsn, "cause", err)
		return nil, fmt.Errorf("打开账本库: %w", err)
	}
	srv.SetLedger(lst)

	srv.SetupAutomation(lst)

	facade := srv.AutoLedger()
	rooms := collab.New(facade)
	rooms.SetCursorStore(cursor.New(filepath.Join(srv.Conf()().DataDir, "room-cursors.json")))
	srv.SetRooms(rooms)

	hostAPI := hostapi.NewWithCredentialPathFor(toolchain.CredRelPathFor)
	srv.SetHostAPI(hostAPI)

	prepareHome := agentd.NewCoordinatorPrepareHome(srv.Conf(), srv.Providers(), srv.RuleLoader())
	coord := opencode.NewCoordinator(hostAPI, slog.Default())
	runner := agentd.NewCoordinatorRunner(coord, srv.Providers(), prepareHome)
	resolver := agentd.NewCoordinatorSessionRefResolver(srv, hostapi.ExpandHomePath)
	ks := keystone.New(runner, keystone.NewRoomNarrator(rooms), facade,
		agentd.NewAttachLocator(hostapi.ExpandHomePath))
	ks.SetSessionRefResolver(resolver)
	srv.SetKeystone(ks)

	reg := srv.SchedulingRegistry()
	if reg == nil {
		_ = lst.Close()
		return nil, fmt.Errorf("编制域装配：SchedulingRegistry 为空（SetupAutomation 未装配账本门面）")
	}
	sched := scheduling.New(reg)

	sched.SetKnownMachines(func(name string) bool {
		cfg := srv.Conf()()
		if cfg == nil {
			return false
		}
		_, ok := cfg.Targets[name]
		return ok
	})
	srv.SetScheduling(sched)

	srv.StartAutomation(ctx)
	logger.Info("自动化编排已挂载", "dsn", ldsn, "poll", "2s")

	host, _ := os.Hostname()
	lm := ledgermirror.New(lst, agentd.NewLedgerMirrorMachines(srv.Pool()), ledgermirror.Options{
		Holder:		host,
		LocalSource:	ledgermirror.NewLocalSource(taskStore, logger.With("source", "local")),
		IsSelfTarget:	srv.IsSelfTarget,
	})
	go lm.Run(ctx)
	logger.Info("账本镜像子系统已挂载", "holder", host,
		"machines", len(srv.Pool().Names()), "dsn", ldsn)
	return func() {

		lm.Stop()
		lst.Close()
	}, nil
}

n_cmd_shellJoin.signature:
// shellJoin 把 argv 拼成一条可安全交给远端 sh -c 的命令行。
//
// 两档行为：
//   - **只有一个参数**：原样返回。用户给的就是一条 shell 命令原文
//     （`handoff run T1 "cd sub && go test ./..."`），本来就指望 sh -c 解析它。
//     对它转义会把整条命令当成一个带空格的命令名，报 command not found——
//     这是一条**回归防线**，改动前请先读 cmd/run_test.go 的第一个用例。
//   - **多个参数**：逐个 shellQuote 后以空格连接。用户给的是 argv，本地 shell
//     已完成分词与去引号。
//
// 为什么需要它（B66）：命令要穿两层 shell。本地 shell 已消费掉一层引号，
// 直接 strings.Join 重拼后远端 sh -c 会按新的词边界再解析一次——
// `grep -rn 'foo bar' .` 到远端就成了三个参数。静默失真，不报错，
// 而审阅取证正是「读了就信」的场景。
func shellJoin(args []string) string {
	if len(args) == 1 {
		return args[0]
	}
	parts := make([]string, len(args))
	for i, a := range args {
		parts[i] = shellQuote(a)
	}
	return strings.Join(parts, " ")
}

n_cmd_shellQuote.signature:
// shellQuote 把一个参数转成可安全交给 sh 的形态：安全字符原样返回，
// 其余用单引号包住，内嵌单引号按 POSIX 惯例拆成三段转义序列。
func shellQuote(s string) string {
	if s != "" && shellSafe.MatchString(s) {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

