// 而失败恰恰是最需要把代码拉到本地翻的时候。
func shouldAutoSync(t proto.EventType) bool {
	return t == proto.EventTypeCompleted || t == proto.EventTypeFailed || t == proto.EventTypeTurnFailed
}

