n_cmd_sshHostFromTarget.signature:
// sshHostFromTarget 把配置 target 换算成 ssh 目标（pull 用的远程 git 地址换算点）。
//
// 规则：取 Addr 冒号前段（Addr 形如 devbox:7777，ssh 目标是主机名，不含 agentd
// 端口）；User 非空时返回 user@host，否则只返回 host（与历史行为一致）。
//
// 为什么只服务 pull：attach 已改为走 agentd 的 render 流（复用 agentd 连接与
// 鉴权），不再拼 ssh；只有 pull 仍需要把 Targets[target] 换算成 ssh 目标来做
// git-over-ssh 同步。user 字段让 ssh 用户名可配置——本机用户名与远程不一致
// （如本机 alice 连远端 sycm）时，裸 host 的 ssh 会直接 Permission denied。
func sshHostFromTarget(t config.Target) string {
	host := t.Addr
	if i := strings.IndexByte(host, ':'); i >= 0 {
		host = host[:i]
	}
	if t.User != "" {
		return t.User + "@" + host
	}
	return host
}

n_cmd_startCardWaitIdle.signature:
// startCardWaitIdle 建立 follow 的空闲计时控制器。计时以 Store.Follow 收到
// 任意账本事件为准，过滤掉的审计事件也会调用 noteActivity；stop 等待控制
// goroutine 退出，避免一次性 CLI 测试或命令结束后遗留后台生命周期。
func startCardWaitIdle(parent context.Context, idle time.Duration) (
	ctx context.Context, noteActivity func(), stop func(), timedOut func() bool,
) {
	if idle <= 0 {
		return parent, func() {}, func() {}, func() bool { return false }
	}
	ctx, cancel := context.WithCancel(parent)

	activity := make(chan struct{})
	expired := make(chan struct{})
	done := make(chan struct{})
	go func() {
		defer close(done)
		timer := time.NewTimer(idle)
		defer timer.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-activity:
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				timer.Reset(idle)
			case <-timer.C:
				close(expired)
				cancel()
				return
			}
		}
	}()
	noteActivity = func() {
		select {
		case activity <- struct{}{}:
		case <-ctx.Done():

		}
	}
	stop = func() {
		cancel()
		<-done
	}
	timedOut = func() bool {
		select {
		case <-expired:
			return true
		default:
			return false
		}
	}
	return ctx, noteActivity, stop, timedOut
}

