n_cmd_waitStepFirstState.signature:
// waitStepFirstState 从 POST 前水位之后排他消费当前卡事件，直到发现派发快照、派发失败，
// 或自身短等窗口结束。账本由调用方打开并拥有；ctx 取消、账本读取和回调错误原样返回。
func waitStepFirstState(ctx context.Context, st *ledger.Store, cardID string, watermark int64) (stepFirstState, error) {
	var observed stepFirstState
	logger := slog.Default().With("card", cardID, "watermark", watermark)
	waitCtx, cancel := context.WithTimeout(ctx, stepFirstStateTimeout)
	defer cancel()
	err := st.Follow(waitCtx, func() ([]string, error) {
		return []string{cardID}, nil
	}, watermark, stepFirstStatePollInterval, func(event ledger.Event) error {
		logger.Debug("短等收到卡事件", "seq", event.Seq, "type", event.Type)
		switch event.Type {
		case ledger.EvComment:
			var payload struct {
				Body string `json:"body"`
			}
			if err := json.Unmarshal(event.Payload, &payload); err != nil {
				logger.Warn("短等忽略无法解码的 comment", "seq", event.Seq, "cause", err)
				return nil
			}
			if strings.HasPrefix(payload.Body, "本节点派发失败：\n") {
				observed.FailureComment = payload.Body
			}
		case ledger.EvDispatched:
			var snapshot ledger.DispatchSnapshot
			if err := json.Unmarshal(event.Payload, &snapshot); err != nil {
				logger.Warn("短等忽略无法解码的 dispatched", "seq", event.Seq, "cause", err)
				return nil
			}
			observed.Dispatch = &snapshot
			logger.Info("短等发现 dispatched 首态", "seq", event.Seq,
				"target", snapshot.Target, "branch", snapshot.Branch, "base", snapshot.Base,
				"base_commit", snapshot.BaseCommit, "discipline", snapshot.DisciplineName)
			return errStepFirstState
		case ledger.EvNeedsHuman:
			var payload struct {
				Reason string `json:"reason"`
			}
			if err := json.Unmarshal(event.Payload, &payload); err != nil {
				logger.Warn("短等忽略无法解码的 needs_human", "seq", event.Seq, "cause", err)
				return nil
			}
			if payload.Reason != "派发失败" {
				return nil
			}
			logger.Info("短等发现派发失败首态", "seq", event.Seq,
				"reason", payload.Reason, "has_comment", observed.FailureComment != "")
			return errStepFirstState
		}
		return nil
	})
	if errors.Is(err, errStepFirstState) {
		return observed, nil
	}
	return observed, err
}

n_cmd_warnIfTimeoutBelowStall.signature:
// warnIfTimeoutBelowStall 核对本次 --timeout 是否会抢在 agentd 的 stalled 前面，
// 是则打一条 WARN。
//
// 注意：
//   - 全部失败路径静默（Debug）：这是锦上添花的提醒，取不到对端状态不该影响跟随
//   - 单独设 15 秒时限：status 端要逐个探活，不能挂在这里
func warnIfTimeoutBelowStall(ctx context.Context, cli waitClient, idle time.Duration) {
	if idle <= 0 {
		return
	}
	ctx, cancel := context.WithTimeout(ctx, 15*time.Second)
	defer cancel()
	st, err := cli.Status(ctx)
	if err != nil {
		slog.Debug("取不到对端 stalltimeout，跳过 --timeout 核对", "cause", err)
		return
	}
	stall, err := time.ParseDuration(st.StallTimeout)
	if err != nil {
		slog.Debug("对端 stalltimeout 无法解析，跳过核对", "raw", st.StallTimeout, "cause", err)
		return
	}
	if msg := idleTimeoutWarning(idle, stall); msg != "" {
		slog.Warn(msg)
	}
}

n_cmd_worktreeLabel.signature:
// worktreeLabel 把工作树状态渲染成人读标签。
func worktreeLabel(r proto.ReclaimRow) string {
	switch r.Worktree {
	case proto.WorktreeClean:
		return "净"
	case proto.WorktreeDirty:
		return fmt.Sprintf("脏（%d 项改动）", r.DirtyCount)
	case proto.WorktreePrunable:
		return "元数据残留（目录已不存在）"
	case proto.WorktreeUnknown:
		return "⚠ 判不出：" + r.Note
	default:
		return string(r.Worktree)
	}
}

n_cmd_writeBacklogLine.signature:
// writeBacklogLine 把积压摘要作为**一行** JSON 写出。
//
// 参数：
//   - w: 目标（生产环境是 cmd.OutOrStdout()）
//   - sum: 对账结果
//
// 返回：
//   - 序列化失败时返回错误——写不出摘要就等于协调者不知道自己错过了什么，
//     必须让 follow 停下而不是继续跑一个没人看得见的循环
//
// 注意：严格一行。stdout 是「每行一个 JSON 对象」的契约，上层（Monitor）按行
// 解析，每一行都是一次会话唤醒——多打一行就多叫醒一次，这正是本功能要消灭的东西。
func writeBacklogLine(w io.Writer, sum *client.BacklogSummary) error {
	b, err := json.Marshal(sum)
	if err != nil {
		return fmt.Errorf("序列化积压摘要: %w", err)
	}
	_, err = fmt.Fprintln(w, string(b))
	return err
}

n_cmd_writeDispatchPointer.signature:
// writeDispatchPointer 派发成功后落里程碑指针行（B156.2 欠账 #11 岔口八）。
// 具名函数而非内联进 RunE 闭包：C6 的指针引用白名单守卫按「所在函数」归属，
// 落在匿名闭包里归属不到真正的调用点。成功路径才写（ViaTemplate 失败零半
// 状态）；写失败不打断派发主流程——指针是房间面信号，错误仅日志（判据二，
// TestCardDispatchPointerFailureDoesNotInterrupt）。
func writeDispatchPointer(st *ledger.Store, id, nodeLabel string) {
	if perr := roomPointer(roomServiceFor(st), id, dispatchPointerBody(id, nodeLabel)); perr != nil {
		slog.Warn("派发指针落账失败", "card", id, "cause", perr)
	}
}

n_cmd_writeEventLine.signature:
// writeEventLine 把事件作为**严格一行** JSON 写出。
//
// 为什么统一走它而不是各处 Fprintln：wait 的 stdout 是「每行一个 JSON 对象」的
// 机器契约，写出失败（管道断裂等）必须上抛——原来一次性 wait 的 Fprintln 把
// 错误吞掉，脚本侧拿到的行是残缺的，却没人知道。
func writeEventLine(w io.Writer, ev *proto.Event) error {
	b, err := json.Marshal(ev)
	if err != nil {
		return fmt.Errorf("序列化事件: %w", err)
	}
	if _, err := fmt.Fprintln(w, string(b)); err != nil {
		return fmt.Errorf("写出事件: %w", err)
	}
	return nil
}

n_cmd_writeMachinesSummary.signature:
// writeMachinesSummary 把 --all 的机器应答摘要写到 stderr。
//
// 任何一台机器没答上来都必须在摘要里逐台可见——静默少一行是跨机汇总的
// 头号失败模式。
func writeMachinesSummary(cmd *cobra.Command, resp *proto.TasksResp) {
	if len(resp.Machines) == 0 {
		return
	}
	out := cmd.ErrOrStderr()
	for _, m := range resp.Machines {
		name := m.Name
		if name == "" {
			name = "本机"
		}
		if m.Ok {
			fmt.Fprintf(out, "机器 %s：应答正常\n", name)
			continue
		}
		reason := m.Error
		if reason == "" {
			reason = "未知原因"
		}
		fmt.Fprintf(out, "机器 %s：未应答——%s\n", name, firstLineOf(reason))
	}
}

n_cmd_writeStepDispatchResult.signature:
// writeStepDispatchResult 将账本里的派发快照写成 CLI 成功决议。
// 参数：w 是 stdout；cardID/node 标识卡和节点；snap 是本次首态快照。空 target/base/sha
// 使用本机、无起点分支、无 sha 文案；非空 sha 最多展示七字节，不输出本地 ref 或 origin。
func writeStepDispatchResult(w io.Writer, cardID, node string, snap ledger.DispatchSnapshot) {
	target := snap.Target
	if target == "" {
		target = "本机"
	}
	base := snap.Base
	if base == "" {
		base = "无起点分支"
	}
	baseCommit := snap.BaseCommit
	if baseCommit == "" {
		baseCommit = "无 sha"
	} else if len(baseCommit) > 7 {
		baseCommit = baseCommit[:7]
	}
	_, _ = fmt.Fprintf(w,
		"卡 %s 的节点 %s 已派发；目标机：%s；新分支：%s；起点分支：%s；起点短号：%s；纪律块：%s\n",
		cardID, node, target, snap.Branch, base, baseCommit, snap.DisciplineName)
}

