// OneShotArgv 编码 codex 一次性调用的 argv。
func OneShotArgv(model, prompt string, _ executor.OneShotLimits) ([]string, error) {
	argv := []string{"codex", "exec", "--skip-git-repo-check", "--ephemeral",
		"--color", "never", "--sandbox", "read-only", "--ignore-user-config"}
	if model != "" {
		argv = append(argv, "-m", model)
	}
	return append(argv, prompt), nil
}

n_codex_OneShot_Invoke.signature:
func (s *OneShot) Invoke(ctx context.Context, req executor.OneShotReq) (executor.OneShotReply, error) {
	s.log.Info("OneShot.Invoke 进入", "harness", executor.HarnessCodex, "model", req.Model, "prompt_bytes", len(req.Prompt), "effort", req.Limits.Effort)
	argv, err := OneShotArgv(req.Model, req.Prompt, req.Limits)
	if err != nil {
		s.log.Error("OneShot argv 编码失败", "cause", err)
		return executor.OneShotReply{Status: executor.OneShotFailed}, err
	}
	out, err := executor.RunOneShotProcess(ctx, argv, req.Env, req.Workdir, req.HomeDir)
	if ctx.Err() != nil {
		s.log.Info("OneShot 已取消", "cause", ctx.Err())
		return executor.OneShotReply{Text: out, Status: executor.OneShotCanceled}, ctx.Err()
	}
	if err != nil {
		s.log.Error("OneShot 进程失败", "cause", err)
		return executor.OneShotReply{Text: out, Status: executor.OneShotFailed}, err
	}
	s.log.Info("OneShot.Invoke 完成", "status", executor.OneShotOK, "output_bytes", len(out))
	return executor.OneShotReply{Text: out, Status: executor.OneShotOK}, nil
}

n_codex_Preflight.signature:
// Preflight 检查 executor 机的 codex 环境。
//
// 参数：
//   - home: codex home 目录；空串时取 $HOME/.codex
//   - log: 日志入口（nil 退回 slog.Default()）
//
// 返回：
//   - 硬前提不满足时返回带可行动指引的错误；软污染源只打 WARN，返回 nil
func Preflight(home string, log *slog.Logger) error {
	if log == nil {
		log = slog.Default()
	}
	if home == "" {
		h, err := os.UserHomeDir()
		if err != nil {
			return fmt.Errorf("读取用户主目录失败，无法定位 ~/.codex: %w", err)
		}
		home = filepath.Join(h, ".codex")
	}
	log.Info("codex 环境预检", "home", home)

	if _, err := lookPath("codex"); err != nil {
		return fmt.Errorf("executor 机上找不到 codex 可执行文件，请先安装 codex-cli 并确保它在 PATH 上: %w", err)
	}
	if _, err := os.Stat(filepath.Join(home, "auth.json")); err != nil {
		return fmt.Errorf("codex 未登录（%s/auth.json 不存在），请在 executor 机执行 `codex login`", home)
	}

	if _, err := os.Stat(filepath.Join(home, "AGENTS.md")); err == nil {
		log.Warn("codex home 存在全局 AGENTS.md，executor 的干活方式会被它改变，建议移除",
			"path", filepath.Join(home, "AGENTS.md"))
	}
	if _, err := os.Stat(filepath.Join(home, "hooks.json")); err == nil {

		log.Warn("codex home 存在 hooks.json，且没有协议级开关能关掉它，强烈建议移除",
			"path", filepath.Join(home, "hooks.json"))
	}
	if b, err := os.ReadFile(filepath.Join(home, "config.toml")); err == nil &&
		strings.Contains(string(b), "[mcp_servers") {
		log.Warn("codex config.toml 配了 mcp_servers，executor 会多出一批工具，建议清空",
			"path", filepath.Join(home, "config.toml"))
	}
	log.Info("codex 环境预检通过", "home", home)
	return nil
}

n_codex_Proc_Alive.signature:
// Alive 检查 codex app-server 是否仍然存活：存活锁被持有 且 WS 端口可连。
//
// 为什么第一条是锁：本地文件操作、微秒级；端口探测要走网络栈且失败要等超时。
// 锁判死就不必再探端口。
func (p *Proc) Alive() bool {
	if !prochost.Alive(p.Handle) {
		return false
	}
	return p.probePort()
}

n_codex_Proc_LogTail.signature:
// LogTail 返回 serve.log 尾部，供启动超时与死亡诊断（B16：失败要给可行动真因）。
func (p *Proc) LogTail() string {
	b, err := os.ReadFile(filepath.Join(p.TaskDir, serveLogName))
	if err != nil {
		return ""
	}
	if len(b) > serveLogTailBytes {
		b = b[len(b)-serveLogTailBytes:]
	}
	return turn.TailRunes(string(b), serveLogTailRunes)
}

n_codex_Proc_WSURL.signature:
// WSURL 返回 app-server 的 WebSocket 端点。
//
// 注意：形态由 Task 1 的 V-5 探针实测确认；若实测形态带路径，改这里一处即可。
func (p *Proc) WSURL() string {
	return fmt.Sprintf("ws://127.0.0.1:%d", p.Port)
}

n_codex_Proc_probePort.signature:
// probePort 探测 app-server 的 WS 端口（TCP 能连上即算活）。
func (p *Proc) probePort() bool {
	conn, err := net.DialTimeout("tcp", fmt.Sprintf("127.0.0.1:%d", p.Port), serveProbeDialTO)
	if err != nil {
		return false
	}
	conn.Close()
	return true
}

n_codex_Profile_Inspect.signature:
func (p *Profile) Inspect(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
	}
	if req.HomeDir == "" {
		return rep, nil
	}
	rulePath := filepath.Join(req.HomeDir, RulesRelFile)
	if _, err := os.Stat(rulePath); errors.Is(err, os.ErrNotExist) {
		rep.Missing = append(rep.Missing, RulesRelFile)
	}
	skillsPath := filepath.Join(req.HomeDir, SkillsRelDir)
	if _, err := os.Stat(skillsPath); errors.Is(err, os.ErrNotExist) {
		rep.Missing = append(rep.Missing, SkillsRelDir)
	}
	return rep, nil
}

n_codex_Profile_Prepare.signature:
func (p *Profile) Prepare(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
	}
	if req.HomeDir == "" {
		return rep, errors.New("Profile.Prepare 缺少 HomeDir")
	}
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 开始", "harness", executor.HarnessCodex, "home", req.HomeDir, "isolated", req.Isolated)
	}
	nativeRoot := filepath.Join(req.HomeDir, filepath.Dir(RulesRelFile))
	if err := os.MkdirAll(nativeRoot, 0700); err != nil {
		return rep, fmt.Errorf("创建原生配置目录 %q: %w", nativeRoot, err)
	}

	for _, r := range req.Rules {
		if strings.Contains(r.Name, "..") {
			return rep, fmt.Errorf("规则文件名含非法字符: %q", r.Name)
		}
		var target string
		if strings.HasPrefix(filepath.Clean(r.Name), filepath.Dir(RulesRelFile)) {
			target = filepath.Join(req.HomeDir, filepath.Clean(r.Name))
		} else {
			target = filepath.Join(nativeRoot, filepath.Clean(r.Name))
		}
		if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
			return rep, fmt.Errorf("创建规则父目录 %q: %w", filepath.Dir(target), err)
		}
		if err := os.WriteFile(target, []byte(r.Content), 0600); err != nil {
			return rep, fmt.Errorf("写入规则文件 %q: %w", target, err)
		}
	}

	if len(req.Skills) > 0 {
		skillsRoot := filepath.Join(req.HomeDir, SkillsRelDir)
		for _, s := range req.Skills {
			if strings.Contains(s.Name, "..") {
				return rep, fmt.Errorf("skill 文件名含非法字符: %q", s.Name)
			}
			target := filepath.Join(skillsRoot, filepath.Clean(s.Name))
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建 skill 父目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(s.Content), 0600); err != nil {
				return rep, fmt.Errorf("写入 skill 文件 %q: %w", target, err)
			}
		}
	}

	if len(req.TaskOverlay) > 0 {
		overlayRoot := filepath.Join(req.HomeDir, ".handoff", "task-overlay")
		for _, o := range req.TaskOverlay {
			if strings.Contains(o.Name, "..") {
				return rep, fmt.Errorf("overlay 文件名含非法字符: %q", o.Name)
			}
			target := filepath.Join(overlayRoot, filepath.Clean(o.Name))
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建 overlay 父目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(o.Content), 0600); err != nil {
				return rep, fmt.Errorf("写入 overlay 文件 %q: %w", target, err)
			}
		}
	}

	rep.Prepared = true
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 完成", "harness", executor.HarnessCodex, "prepared", true)
	}
	return rep, nil
}

n_codex_Profile_Verify.signature:
func (p *Profile) Verify(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
		EngineOK:	false,
	}
	if req.HomeDir == "" {
		return rep, nil
	}
	rulePath := filepath.Join(req.HomeDir, RulesRelFile)
	globalOK := false
	if len(req.Rules) == 0 {
		_, err := os.Stat(rulePath)
		globalOK = err == nil
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			if p != nil && p.log != nil {
				p.log.Error("Profile.Verify 读取原生规则失败", "harness", executor.HarnessCodex,
					"home", req.HomeDir, "path", rulePath, "cause", err)
			}
			return rep, fmt.Errorf("校验原生规则 %q: %w", rulePath, err)
		}
	} else {
		expected := req.Rules[0].Content
		for _, rule := range req.Rules {
			if filepath.Base(filepath.Clean(rule.Name)) == filepath.Base(RulesRelFile) {
				expected = rule.Content
			}
		}
		got, readErr := os.ReadFile(rulePath)
		if readErr != nil {
			rep.Missing = append(rep.Missing, RulesRelFile)
		} else if !bytes.Equal(got, []byte(expected)) {
			rep.Notes = append(rep.Notes, fmt.Sprintf("规则内容不符: %s", RulesRelFile))
		} else {
			globalOK = true
		}
	}
	overlayOK := true
	for _, overlay := range req.TaskOverlay {
		if strings.Contains(overlay.Name, "..") {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 文件名含非法字符: %s", overlay.Name))
			continue
		}
		rel := filepath.Join(".handoff", "task-overlay", filepath.Clean(overlay.Name))
		got, readErr := os.ReadFile(filepath.Join(req.HomeDir, rel))
		if readErr != nil {
			overlayOK = false
			rep.Missing = append(rep.Missing, rel)
			if p != nil && p.log != nil {
				actualState := "read_error"
				if errors.Is(readErr, os.ErrNotExist) {
					actualState = "missing"
				}
				p.log.Warn("Profile.Verify 任务层内容缺失",
					"harness", executor.HarnessCodex, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", actualState,
					"expected_bytes", len(overlay.Content), "actual_bytes", 0, "cause", readErr)
			}
			continue
		}
		if !bytes.Equal(got, []byte(overlay.Content)) {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 内容不符: %s", rel))
			if p != nil && p.log != nil {
				p.log.Warn("Profile.Verify 任务层内容不符",
					"harness", executor.HarnessCodex, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", "content_mismatch",
					"expected_bytes", len(overlay.Content), "actual_bytes", len(got))
			}
		}
	}
	rep.Verified = globalOK && overlayOK
	if p != nil && p.log != nil {
		p.log.Info("Profile.Verify 完成", "harness", executor.HarnessCodex,
			"home", req.HomeDir, "verified", rep.Verified, "engine_ok", rep.EngineOK,
			"overlay_count", len(req.TaskOverlay))
	}
	return rep, nil
}

n_codex_ReadServeInfo.signature:
// ReadServeInfo 从任务目录读回 Proc，供 agentd 重启后 Resume（B18）。
func ReadServeInfo(taskDir string) (*Proc, error) {
	b, err := os.ReadFile(filepath.Join(taskDir, procInfoFileName))
	if err != nil {
		return nil, fmt.Errorf("读恢复凭据: %w", err)
	}
	var pi procInfo
	if err := json.Unmarshal(b, &pi); err != nil {
		return nil, fmt.Errorf("解析恢复凭据: %w", err)
	}
	if pi.Handle.LockPath == "" || pi.Port == 0 {
		return nil, fmt.Errorf("恢复凭据字段不完整")
	}
	p := &Proc{Handle: pi.Handle, Port: pi.Port}
	p.TaskDir = taskDir
	return p, nil
}

n_codex_StartServe.signature:
// StartServe 经 prochost 拉起一个任务专属的 codex app-server 并等其就绪。
//
// 参数：
//   - ctx: 控制启动阶段的超时/取消
//   - repoPath: 任务工作目录（serve 的 cwd）
//   - taskID: 任务 ID（日志与 proc.json 定位）
//   - taskDir: 任务物料目录
//   - env: 注入到 app-server 进程的环境变量（B19）
//   - log: 日志入口（nil 退回 slog.Default()）
//
// 返回：就绪的 Proc；任一步失败返回错误（错误携带 serve.log 尾部）
//
// 注意：**没有 model 参数**（与 grok 不同）——codex 的模型选择是协议级的
// （thread/start 的 model 字段），不经启动描述。
func StartServe(ctx context.Context, repoPath, taskID, markRoot, taskDir string, env []string, log *slog.Logger) (*Proc, error) {
	if log == nil {
		log = slog.Default()
	}
	start := time.Now()
	log.Info("codex app-server 启动中", "task", taskID, "repo", repoPath, "task_dir", taskDir)

	port, err := freePort()
	if err != nil {
		return nil, err
	}

	if len(env) > 0 {
		keys := make([]string, 0, len(env))
		for _, kv := range env {
			if k, _, ok := strings.Cut(kv, "="); ok {
				keys = append(keys, k)
			}
		}
		log.Info("注入 env 变量到 codex app-server 进程", "task", taskID, "keys", keys, "count", len(keys))
	}
	bin, err := exec.LookPath("codex")
	if err != nil {
		log.Error("codex 未安装", "task", taskID, "cause", err)
		return nil, fmt.Errorf("codex 未安装: %w", err)
	}

	log.Info("解析 codex 可执行文件", "task", taskID, "bin", bin)
	selfExe, err := os.Executable()
	if err != nil {
		log.Error("取 handoff 自身路径失败（shim 无法拉起）", "task", taskID, "cause", err)
		return nil, fmt.Errorf("取自身可执行路径: %w", err)
	}
	spec := serveSpec(repoPath, taskDir, port, env)
	spec.TaskID = taskID
	spec.MarkRoot = markRoot
	spec.Argv[0] = bin

	if err := writeProcInfo(taskDir, &procInfo{
		Handle:	prochost.Handle{LockPath: spec.LockPath}, Port: port,
	}); err != nil {
		log.Error("写恢复凭据失败", "task", taskID, "cause", err)
		return nil, err
	}
	log.Info("启动 codex app-server", "task", taskID, "port", port, "bin", bin, "repo", repoPath)
	handle, err := startProcHost(spec, selfExe)
	if err != nil {
		log.Error("拉起 codex app-server 失败", "task", taskID, "port", port, "cause", err)
		return nil, err
	}
	p := &Proc{Handle: handle, TaskDir: taskDir, Port: port}
	if err := writeProcInfo(taskDir, &procInfo{
		Handle:	handle, Port: port,
	}); err != nil {
		log.Warn("回写恢复凭据失败，重启恢复将不可用", "task", taskID, "cause", err)
	}

	deadline := time.Now().Add(serveReadyTimeout)
	for time.Now().Before(deadline) {
		if p.probePort() {
			log.Info("codex app-server 就绪", "task", taskID, "port", port,
				"elapsed_ms", time.Since(start).Milliseconds())
			return p, nil
		}
		select {
		case <-ctx.Done():
			_ = p.Kill()
			return nil, ctx.Err()
		case <-time.After(serveProbeInterval):
		}
	}
	tail := p.LogTail()
	_ = p.Kill()
	log.Error("codex app-server 就绪超时", "task", taskID, "timeout", serveReadyTimeout, "log_tail", tail)
	return nil, fmt.Errorf("codex app-server %s 内未就绪: %s", serveReadyTimeout, tail)
}

n_codex_buildThreadResumeParams.signature:
// buildThreadResumeParams 构造 thread/resume 的入参。恢复路径也必须重传
// developerInstructions，否则恢复后常驻纪律会消失。
func buildThreadResumeParams(threadID, repoPath, developerInstructions string) map[string]any {
	params := map[string]any{
		"threadId":		threadID,
		"cwd":			repoPath,
		"approvalPolicy":	"on-request",
		"approvalsReviewer":	"user",
	}
	if developerInstructions != "" {
		params["developerInstructions"] = developerInstructions
	}
	return params
}

n_codex_buildThreadStartParams.signature:
// buildThreadStartParams 构造 thread/start 的入参。
//
// 抽成函数是为了让测试与生产代码用同一份字面量；下次增加安全参数时，
// 两处各写一份必然漏改一处。developerInstructions 是 codex 协议直收的持久
// 指令通道，协议铁律与执行纪律放在这里才能跨回合常驻。
func buildThreadStartParams(cwd, model, developerInstructions string) map[string]any {
	params := map[string]any{
		"cwd":			cwd,
		"sandbox":		"workspace-write",
		"approvalPolicy":	"on-request",
		"approvalsReviewer":	"user",
	}
	if model != "" {
		params["model"] = model
	}
	if developerInstructions != "" {
		params["developerInstructions"] = developerInstructions
	}
	return params
}

n_codex_codexServeArgv.signature:
// codexServeArgv 组 codex app-server 的 argv（命令形态沿用旧启动脚本，原样搬运）。
func codexServeArgv(port int) []string {
	return []string{"codex", "app-server", "--listen", "ws://127.0.0.1:" + strconv.Itoa(port)}
}

n_codex_commandPermText.signature:
// commandPermText 渲染命令审批的人读描述（工单正文与被拒清单都用它）。
func commandPermText(a commandApproval) string {
	var b strings.Builder
	b.WriteString("运行命令：" + a.Command)
	if a.Cwd != "" {
