// noteRejected 记下本回合被拒的权限描述，回合收尾时一并交代给协调者。
func (t *permTable) noteRejected(desc string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.rejected = append(t.rejected, desc)
}

n_codex_permTable_noteReqID.signature:
// noteReqID 记下 JSON-RPC 请求 id 到 itemId 的反查关系。
//
// 为什么需要：serverRequest/resolved 通知带的是 **requestId**（JSON-RPC id），
// 而挂起表按 itemId 索引。没有这张反查表，「该请求已被别处了结」这个通知就无法
// 落到具体挂起项上，那张工单会一直挂着，协调者裁决时才发现回发失败。
func (t *permTable) noteReqID(reqID, itemID string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if t.byReq == nil {
		t.byReq = map[string]string{}
	}
	t.byReq[reqID] = itemID
}

n_codex_permTable_restore.signature:
// restore puts a failed-to-send permission response back into the pending table.
// The executor is still waiting when Reply fails, so the coordinator must be
// able to retry without creating a second timing window.
func (t *permTable) restore(itemID string, pp pendingPerm) {
	t.mu.Lock()
	defer t.mu.Unlock()
	if _, exists := t.pending[itemID]; !exists {
		t.pending[itemID] = pp
	}
}

n_codex_permTable_take.signature:
// take 取出并移除挂起项。
//
// 注意：不清对应的 byReq 孤儿条目——一条 map entry 的代价远小于反向索引的复杂度，
// 孤儿条目在 voidAll 时统一清掉。
func (t *permTable) take(itemID string) (pendingPerm, bool) {
	t.mu.Lock()
	defer t.mu.Unlock()
	pp, ok := t.pending[itemID]
	delete(t.pending, itemID)
	return pp, ok
}

n_codex_permTable_takeRejected.signature:
// takeRejected 取走并清空本回合的被拒记录。
//
// 注意：必须取走而非读取——不清空会让下一回合重复上报同一批被拒项，
// 协调者会收到一张内容陈旧的工单。
func (t *permTable) takeRejected() []string {
	t.mu.Lock()
	defer t.mu.Unlock()
	out := t.rejected
	t.rejected = nil
	return out
}

n_codex_permTable_voidAll.signature:
// voidAll 作废全部挂起项，返回作废数量（连接死亡时调用）。
func (t *permTable) voidAll() int {
	t.mu.Lock()
	defer t.mu.Unlock()
	n := len(t.pending)
	t.pending = map[string]pendingPerm{}
	t.byReq = map[string]string{}
	return n
}

n_codex_readProcInfo.signature:
// readProcInfo 读 proc.json 为松散 Handle 容器（供 Reap 只取 Handle 用）。
func readProcInfo(taskDir string) (*procInfo, error) {
	b, err := os.ReadFile(filepath.Join(taskDir, procInfoFileName))
	if err != nil {
		return nil, fmt.Errorf("读恢复凭据: %w", err)
	}
	var pi procInfo
	if err := json.Unmarshal(b, &pi); err != nil {
		return nil, fmt.Errorf("解析恢复凭据: %w", err)
	}
	if pi.Handle.LockPath == "" {
		return nil, fmt.Errorf("恢复凭据字段不完整（缺 handle.lock_path）")
	}
	return &pi, nil
}

n_codex_rejectedTurnQuestion.signature:
// rejectedTurnQuestion 把被拒清单拼成交给协调者的问题。
