n_collab_Service_ListRooms.signature:
// ListRooms 会话列表：扁平活动排序 + 项目筛选（project=="" 表示全部）。
// 条目=全部卡房间（终态卡沉底）+ 各项目的 project:<name> 群 + global 恒在。
// LastActivity=该房间最新一条 room_message 时刻；卡房间无消息时回退卡的
// UpdatedAt。Live=绑定者租约未过期（同一注入时钟 nowFn 判定），无绑定时
// false；DriverLease 读失败向上传播（C6 handler 退化 503，不吞错）。
// ListRooms 返回不带成员未读视图的会话列表。需要成员维度时使用
// ListRoomsForMember；保留本入口供不关心用户身份的调用方使用。
func (s *Service) ListRooms(project string) ([]proto.RoomSummary, error) {
	return s.listRooms(project, "")
}

n_collab_Service_ListRoomsForMember.signature:
// ListRoomsForMember 返回会话列表并把指定成员的未读数投影到每一行。
// member 为空时不读取游标，保持 ListRooms 的旧语义。
func (s *Service) ListRoomsForMember(project, member string) ([]proto.RoomSummary, error) {
	return s.listRooms(project, member)
}

n_collab_Service_ListSessions.signature:
// ListSessions 列全部会话（含归档），member 非空时投影该成员未读数。
func (s *Service) ListSessions(member string) ([]proto.SessionSummary, error) {
	sessions, err := s.lc.ListSessions()
	if err != nil {
		return nil, err
	}
	cards, err := s.lc.ListAllCards("")
	if err != nil {
		return nil, err
	}
	byCard := make(map[string]proto.Card, len(cards))
	for _, c := range cards {
		byCard[c.ID] = c
	}
	events, err := room.ReadAllEvents(s.lc, 0)
	if err != nil {
		return nil, err
	}
	needs := needsHumanByCard(events)
	var cursors map[string]int64
	if member != "" {
		cursors, err = s.cursor.Snapshot(member)
		if err != nil {
			return nil, err
		}
	}
	out := make([]proto.SessionSummary, 0, len(sessions))
	for _, session := range sessions {
		summary := s.summarizeSession(session, byCard, events, needs)
		if member != "" {
			summary.Unread = unreadByRoom(events, cursors)[session.ID]
		}
		out = append(out, summary)
	}
	return out, nil
}

n_collab_Service_MarkRead.signature:
// MarkRead 未读游标置位（打开房间即已读）。按成员按房间记 seq 水位，单调
// 只进不退；并发到达由 cursor.Store 互斥锁 + tmp+rename 原子写兜底。
func (s *Service) MarkRead(member, roomID string, uptoSeq int64) error {
	if err := s.cursor.MarkRead(member, roomID, uptoSeq); err != nil {
		log().Warn("未读游标置位失败", "member", member, "room", roomID, "upto_seq", uptoSeq, "cause", err)
		return err
	}
	log().Info("未读游标已置位", "member", member, "room", roomID, "upto_seq", uptoSeq)
	return nil
}

n_collab_Service_Mentions.signature:
// Mentions 收件箱源③：@member 的未消费提及。全流扫描 afterSeq 之后、
// mentions∋member 且尚无本人 message_consumed 标记的 room_message。
// limit<=0 取 historyDefaultLimit。
func (s *Service) Mentions(member string, afterSeq int64, limit int) ([]proto.LedgerEvent, error) {
	if limit <= 0 {
		limit = historyDefaultLimit
	}
	events, err := room.ReadAllEvents(s.lc, afterSeq)
	if err != nil {
		log().Warn("提及读取失败：读事件流", "member", member, "cause", err)
		return nil, err
	}
	consumed := room.ConsumedSeqs(events, member)
	out := []proto.LedgerEvent{}
	for _, ev := range events {
		if ev.Type != room.RoomEventType || !room.MentionsMember(ev, member) {
			continue
		}
		if consumed[ev.Seq] {
			continue
		}
		out = append(out, ev)
		if len(out) >= limit {
			break
		}
	}
	log().Info("未消费提及已组装", "member", member, "count", len(out))
	return out, nil
}

n_collab_Service_MessageWakeTargets.signature:
// MessageWakeTargets 是 WakeTargets 的消息级半边（已在手解析好 replyAuthor 的
// 调用方用它）。唤醒路径只认它——签名里没有成员集合，扇出形状写不出来。
func (s *Service) MessageWakeTargets(msg proto.RoomMessage) ([]string, error) {
	return s.resolveMessageTargets(msg, s.replyAuthorOf(msg)), nil
}

n_collab_Service_Pending.signature:
// Pending @定向消费队列（读侧）：全流扫描「mentions∋consumer 且尚无本人
// message_consumed 标记的群级消息」∪「consumer 所绑卡房间内未消费的用户
// 留言（kind==user）」。所绑卡房间 = ListAllCards 里 DriverSession==consumer
// 的全部卡（含终态/并入卡——只读冻结防新写，不抹旧留言，杜绝无人消费的黑洞）。
func (s *Service) Pending(consumer string) ([]proto.LedgerEvent, error) {
	events, err := room.ReadAllEvents(s.lc, 0)
	if err != nil {
		log().Warn("待消费队列组装失败：读事件流", "consumer", consumer, "cause", err)
		return nil, err
	}
	consumed := room.ConsumedSeqs(events, consumer)
	bound := map[string]bool{}
	cards, err := s.lc.ListAllCards("")
	if err != nil {
		log().Warn("待消费队列组装失败：读卡列表", "consumer", consumer, "cause", err)
		return nil, err
	}
	for _, c := range cards {
		if c.DriverSession == consumer {
			bound[c.ID] = true
		}
	}
	out := []proto.LedgerEvent{}
	for _, ev := range events {
		if ev.Type != room.RoomEventType || consumed[ev.Seq] {
			continue
		}
		if ev.CardID == "" {
			if room.MentionsMember(ev, consumer) {
				out = append(out, ev)
			}
			continue
		}
		if bound[ev.CardID] && room.MessageKind(ev) == proto.RoomMsgUser {
			out = append(out, ev)
		}
	}
	log().Info("待消费队列已组装", "consumer", consumer, "count", len(out))
	return out, nil
}

n_collab_Service_Pointer.signature:
// Pointer 系统组件写指针行的专用入口；HTTP/CLI 面不得路由它（冻结清单有
// 对应断言）。kind=pointer 与 BySystem=true 由本方法自置（rooms.go 注释
// 「本键只应由 Service.Pointer 置真」），调用方只递 roomID 与正文；房间
// 解析复用 room.Resolve，并入冻结/终态归档房间拒写（ErrReadOnly）。
func (s *Service) Pointer(roomID string, msg proto.RoomMessage) (int64, error) {
	r, err := room.Resolve(s.lc, roomID)
	if err != nil {
		return 0, err
	}
	if r.ReadOnly {
		return 0, room.ErrReadOnly
	}
	msg.Kind = proto.RoomMsgPointer
	msg.BySystem = true
	msg.Room = roomID
	seq, err := s.lc.RecordRoomMessage(r.CardID, msg, pointerActor)
	if err != nil {
		return 0, err
	}
	log().Info("指针行已落账", "room", roomID, "card", r.CardID, "seq", seq)
	return seq, nil
}

n_collab_Service_Send.signature:
// Send 发消息：白名单 + 书写者执法的唯一写入口（pointer 除外——它只能走
// Pointer，经本方法一律拒收）。返回落账 seq。
//
// 执法矩阵（契约 §3.3 逐条 + §4 冻结清单）：kind 词表校验（pointer 拒收）
// → 房间解析（room.Resolve：存在性 + 只读判定）→ 只读拒写 → 按 kind 的
// 书写者校验（room.VerifyWriter）→ 经 client 发布。全部规则实现在 room
// 子包，本方法只做编排。
func (s *Service) Send(roomID string, msg proto.RoomMessage, actor string) (int64, error) {
	if !room.KindAllowed(msg.Kind) || msg.Kind == proto.RoomMsgPointer {
		return 0, room.ErrKindNotAllowed
	}
	r, err := room.Resolve(s.lc, roomID)
	if err != nil {
		return 0, err
	}
	if r.ReadOnly {
		return 0, room.ErrReadOnly
	}
	if err := room.VerifyWriter(r, msg.Kind, actor); err != nil {
		return 0, err
	}
	msg.Room = roomID
	seq, err := s.lc.RecordRoomMessage(r.CardID, msg, actor)
	if err != nil {
		return 0, err
	}
	if msg.Kind == proto.RoomMsgUser {

		s.consumeRoomMentions(roomID, actor)
	}
	log().Info("房间消息已落账", "room", roomID, "kind", msg.Kind, "actor", actor, "seq", seq)
	return seq, nil
}

n_collab_Service_SessionDetail.signature:
// SessionDetail 读会话详情页投影：成员与成员状态、协调者派发的任务节点、
// 会话 timeline。结构信息不进群聊流。
func (s *Service) SessionDetail(id string) (proto.SessionDetail, error) {
	session, err := s.lc.GetSession(id)
	if err != nil {
		return proto.SessionDetail{}, mapSessionError(err)
	}
	cards, err := s.lc.ListAllCards("")
	if err != nil {
		return proto.SessionDetail{}, err
	}
	byCard := make(map[string]proto.Card, len(cards))
	for _, c := range cards {
		byCard[c.ID] = c
	}
	events, err := room.ReadAllEvents(s.lc, 0)
	if err != nil {
		return proto.SessionDetail{}, err
	}
	needs := needsHumanByCard(events)
	detail := proto.SessionDetail{
		Summary:	s.summarizeSession(session, byCard, events, needs),
		Nodes:		sessionNodes(session, byCard, events),
		Timeline:	sessionTimeline(events, session.ID, byCard),
	}
	return detail, nil
}

n_collab_Service_SetCursorStore.signature:
// SetCursorStore 把未读游标换成指定介质（移交区 A.1 岔口四方案甲：datadir 下
// JSON 文件缓存，tmp+rename 原子写）。组装点（agentd server / CLI main）持
// DataDir，用 cursor.New(filepath.Join(cfg.DataDir, "room-cursors.json")) 接线；
// 不调用则保持 New 的纯内存默认——游标非权威，重启丢失无害、打开房间即自愈。
func (s *Service) SetCursorStore(st *cursor.Store)	{ s.cursor = st }

n_collab_Service_Unread.signature:
// Unread 未读计数：该房间内 room_message 事件中 seq 大于该成员游标的条数
// （水位语义：打开房间 MarkRead 到当前最大 seq 后即 0；未读过 = 全量）。
func (s *Service) Unread(member, roomID string) (int, error) {
	cursorSeq, err := s.cursor.Cursor(member, roomID)
	if err != nil {
		log().Warn("未读计数失败：读游标", "member", member, "room", roomID, "cause", err)
		return 0, err
	}
	events, err := room.ReadAllEvents(s.lc, cursorSeq)
	if err != nil {
		log().Warn("未读计数失败：读事件流", "member", member, "room", roomID, "cause", err)
		return 0, err
	}
	n := 0
	for _, ev := range events {
		if ev.Type != room.RoomEventType || !room.SameRoom(ev, roomID) {
			continue
		}
		n++
	}
	log().Info("未读计数完成", "member", member, "room", roomID, "unread", n)
	return n, nil
}

n_collab_Service_WakeTargets.signature:
// WakeTargets 解析一条 room_message 的寻址，返回被唤醒成员身份集；空集表示
// 不唤醒任何人。规则：
//   - @卡号 解析为该卡当前席位（换绑后指向新席位）；解析不到卡时按外部会话
//     身份原样使用；
//   - reply_to 指向被回复消息的作者（隐式寻址原作者，一人）；作者若是某卡当前
//     席位则保持该席位身份（换绑后再次 @ 该卡仍命中新席位）；
//   - 系统结构行（by_system / pointer）恒不唤醒。
func (s *Service) WakeTargets(ev proto.LedgerEvent) ([]string, error) {
	var msg proto.RoomMessage
	if err := room.UnmarshalMessage(ev.Payload, &msg); err != nil {
		return nil, err
	}
	replyAuthor := s.replyAuthorOf(msg)
	return s.resolveMessageTargets(msg, replyAuthor), nil
}

n_collab_Service_consumeRoomMentions.signature:
// consumeRoomMentions 用户消息落房后，把该房间内 @本人 且未消费的提及一并消费
// （B287 拍板「回复即清提及类」）。只处理卡房间：mentions 角标面只认 card_id
// （agentd handleInbox 用 ev.CardID 亮房间），群级提及本就不进角标；裁决与
// 工单两源不受影响——它们要求显式审批/答复，不因一句话消掉。
//
// 消费身份 = 发送 actor，与收件箱 mention 源（agentd handleInbox 的
// rooms.Mentions(s.roomUserActor(r),…)）同标识，保证「发前亮、回复后灭」
// 同一把尺子。幂等由 Consume 兜底；失败逐条告警，下次回复自然重试。
func (s *Service) consumeRoomMentions(roomID, member string) {
	events, err := room.ReadAllEvents(s.lc, 0)
	if err != nil {
		log().Warn("回复后清理提及失败：读事件流", "room", roomID, "member", member, "cause", err)
		return
	}
	consumed := room.ConsumedSeqs(events, member)
	for _, ev := range events {
		if ev.Type != room.RoomEventType || ev.CardID != roomID || consumed[ev.Seq] {
			continue
		}
		if !room.MentionsMember(ev, member) {
			continue
		}
		if err := s.Consume(ev.Seq, member); err != nil {
			log().Warn("回复后清理提及失败：消费落账", "room", roomID, "member", member, "seq", ev.Seq, "cause", err)
		}
	}
}

n_collab_Service_listRooms.signature:
func (s *Service) listRooms(project, member string) ([]proto.RoomSummary, error) {
	cards, err := s.lc.ListAllCards(project)
	if err != nil {
		log().Warn("会话列表组装失败：读卡列表", "project", project, "cause", err)
		return nil, err
	}
	events, err := room.ReadAllEvents(s.lc, 0)
	if err != nil {
		log().Warn("会话列表组装失败：读事件流", "project", project, "cause", err)
		return nil, err
	}
	rooms := []proto.RoomSummary{}
	byID := map[string]int{}
	terminal := map[string]bool{}
	projects := map[string]bool{}
	for _, c := range cards {
		isTerm := room.IsTerminalStatus(c.Status)
		terminal[c.ID] = isTerm
		byID[c.ID] = len(rooms)
		rooms = append(rooms, proto.RoomSummary{
			ID:	c.ID, Kind: room.KindCard, Project: c.Project, Title: c.Title,
			BoundSession:	c.DriverSession,
			ReadOnly:	isTerm || c.Following != "",
			LastActivity:	c.UpdatedAt,
		})
		if c.Project != "" {
			projects[c.Project] = true
		}
	}
	for p := range projects {
		byID["project:"+p] = len(rooms)
		rooms = append(rooms, proto.RoomSummary{ID: "project:" + p, Kind: room.KindProject, Project: p, Title: p})
	}
	byID["global"] = len(rooms)
	rooms = append(rooms, proto.RoomSummary{ID: "global", Kind: room.KindGlobal, Title: "全员"})

	for _, ev := range events {
		if ev.Type != room.RoomEventType {
			continue
		}
		roomID := room.RoomIDOf(ev)
		idx, ok := byID[roomID]
		if !ok {
			continue
		}
		if ev.CreatedAt.After(rooms[idx].LastActivity) {
			rooms[idx].LastActivity = ev.CreatedAt
		}
		var msg proto.RoomMessage
		if err := room.UnmarshalMessage(ev.Payload, &msg); err != nil {
			log().Warn("会话列表预览投影跳过：消息载荷无效",
				"project", project, "room", roomID, "seq", ev.Seq, "cause", err)
			continue
		}
		if rooms[idx].Preview != nil && rooms[idx].Preview.Seq >= ev.Seq {
			continue
		}
		rooms[idx].Preview = &proto.RoomPreview{
			Body:	truncateRoomPreview(msg.Body), Seq: ev.Seq, CreatedAt: ev.CreatedAt,
		}
	}

	liveOf := map[string]bool{}
	sessionSeen := map[string]bool{}
	for _, r := range rooms {
		if r.BoundSession == "" || sessionSeen[r.BoundSession] {
			continue
		}
		sessionSeen[r.BoundSession] = true
		expiresAt, exists, err := s.lc.DriverLease(r.BoundSession)
		if err != nil {
			log().Warn("会话列表组装失败：读租约", "session", r.BoundSession, "cause", err)
			return nil, err
		}
		liveOf[r.BoundSession] = exists && expiresAt.After(nowFn())
	}
	for i := range rooms {
		if bs := rooms[i].BoundSession; bs != "" {
			rooms[i].Live = liveOf[bs]
		}
	}
	if member != "" {
		cursors, err := s.cursor.Snapshot(member)
		if err != nil {
			log().Warn("会话列表组装失败：读游标快照",
				"project", project, "member", member, "cause", err)
			return nil, err
		}
		unread := unreadByRoom(events, cursors)
		for i := range rooms {
			rooms[i].Unread = unread[rooms[i].ID]
		}
		log().Info("会话列表未读聚合完成", "project", project, "member", member,
			"rooms", len(rooms))
	}

	active := []proto.RoomSummary{}
	sunk := []proto.RoomSummary{}
	for _, r := range rooms {
		if terminal[r.ID] {
			sunk = append(sunk, r)
		} else {
			active = append(active, r)
		}
	}
	sort.SliceStable(active, func(i, j int) bool { return active[i].LastActivity.After(active[j].LastActivity) })
	sort.SliceStable(sunk, func(i, j int) bool { return sunk[i].LastActivity.After(sunk[j].LastActivity) })
	log().Info("会话列表已组装", "project", project, "count", len(rooms))
	return append(active, sunk...), nil
}

n_collab_Service_memberStatus.signature:
// memberStatus 判定成员状态：有未过期租约报 working（活跃租约视为可续租），
// 否则按可证实性报 last_active。绝不报「在线」。
func (s *Service) memberStatus(identity string) (string, time.Time) {
	expiresAt, exists, err := s.lc.DriverLease(identity)
	if err != nil || !exists {
		return proto.SessionMemberLastActive, time.Time{}
	}
	if expiresAt.After(nowFn()) {
		return proto.SessionMemberWorking, expiresAt
	}
	return proto.SessionMemberLastActive, expiresAt
}

n_collab_Service_replyAuthorOf.signature:
// replyAuthorOf 找被回复消息的作者；找不到返回空串。
func (s *Service) replyAuthorOf(msg proto.RoomMessage) string {
	if msg.ReplyTo <= 0 {
		return ""
	}
	events, err := room.ReadAllEvents(s.lc, 0)
	if err != nil {
		return ""
	}
	for _, candidate := range events {
		if candidate.Seq == msg.ReplyTo && candidate.Type == room.RoomEventType {
			return candidate.Actor
		}
	}
	return ""
}

n_collab_Service_resolveMessageTargets.signature:
// resolveMessageTargets 解析消息寻址；@卡号 解析到该卡当前席位。
func (s *Service) resolveMessageTargets(msg proto.RoomMessage, replyAuthor string) []string {
	resolveSeat := func(mention string) (string, bool) {
		card, err := s.lc.GetCard(mention)
		if err != nil {
			return "", false
		}
		return card.DriverSession, true
	}
	return room.ResolveDelivery(msg, replyAuthor, resolveSeat)
}

n_collab_Service_sessionMembers.signature:
// sessionMembers 派生会话成员：显式成员（人/主 agent）+ 会话内各卡的当前席位。
// 状态只报可证实的——有未过期租约报 working/listening，否则报 last_active；
// 空座报 empty。不报「在线」（外部会话随时可能被关掉）。
func (s *Service) sessionMembers(session proto.Session, byCard map[string]proto.Card) []proto.SessionMember {
	members := make([]proto.SessionMember, 0, len(session.Members)+len(session.Cards))
	for _, identity := range session.Members {
		kind := proto.SessionMemberHuman
		if identity == session.Owner && session.Owner != "" {

			if len(identity) >= 4 && identity[:4] == "cli:" {
				kind = proto.SessionMemberAgent
			}
		}
		status, lastActive := s.memberStatus(identity)
		members = append(members, proto.SessionMember{
			Identity:	identity, Kind: kind, Status: status, LastActive: lastActive,
		})
	}
	for _, cardID := range session.Cards {
		card, ok := byCard[cardID]
		if !ok {
			continue
		}
		member := proto.SessionMember{
			Kind:	proto.SessionMemberSeat, CardID: cardID, CardTitle: card.Title,
		}
		if card.DriverSession == "" {
			member.Status = proto.SessionMemberEmpty
		} else {
			member.Identity = card.DriverSession
			member.Status, member.LastActive = s.memberStatus(card.DriverSession)
		}
		members = append(members, member)
	}
	return members
}

n_collab_Service_summarizeSession.signature:
// summarizeSession 组装会话列表/详情头部的会话摘要。
func (s *Service) summarizeSession(session proto.Session, byCard map[string]proto.Card,
	events []proto.LedgerEvent, needs map[string]bool) proto.SessionSummary {
	summary := proto.SessionSummary{
		ID:	session.ID, Kind: proto.SessionKind, Title: session.Title,
		Owner:	session.Owner, Archived: session.Archived,
		LastActivity:	session.UpdatedAt,
		Members:	s.sessionMembers(session, byCard),
		Cards:		sessionCards(session, byCard),
	}
	for _, cardID := range session.Cards {
		if needs[cardID] {
			summary.NeedsHuman = true
			break
		}
	}

	for _, ev := range events {
		if ev.Type != room.RoomEventType || !room.SameRoom(ev, session.ID) {
			continue
		}
		if ev.CreatedAt.After(summary.LastActivity) {
			summary.LastActivity = ev.CreatedAt
		}
		var msg proto.RoomMessage
		if err := room.UnmarshalMessage(ev.Payload, &msg); err != nil {
			continue
		}
		if summary.Preview != nil && summary.Preview.Seq >= ev.Seq {
			continue
		}
		summary.Preview = &proto.RoomPreview{
			Body:	truncateRoomPreview(msg.Body), Seq: ev.Seq, CreatedAt: ev.CreatedAt,
		}
	}
	return summary
}

n_collab_cursor_New.signature:
// New 构造游标存储。path 空 = 纯内存；非空 = 文件介质，首次访问时从 path
// 加载，之后每次 MarkRead 后原子落盘。
func New(path string) *Store {
	return &Store{path: path, data: map[string]map[string]int64{}}
}

n_collab_cursor_Store_Cursor.signature:
// Cursor 读该成员在该房间的已读水位；未记过返回 0。
func (s *Store) Cursor(member, roomID string) (int64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.ensureLoaded(); err != nil {
		return 0, err
	}
	return s.data[member][roomID], nil
}

n_collab_cursor_Store_MarkRead.signature:
// MarkRead 置该成员在该房间的已读水位。单调：只进不退（并发到达时取大值），
// 防止旧请求把新水位拉回。member/roomID 为空直接报错（没有「谁/哪」的游标
// 无意义）。
func (s *Store) MarkRead(member, roomID string, uptoSeq int64) error {
	if member == "" || roomID == "" {
		return fmt.Errorf("游标必须带 member 与 roomID")
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.ensureLoaded(); err != nil {
		return err
	}
	perRoom := s.data[member]
	if perRoom == nil {
		perRoom = map[string]int64{}
		s.data[member] = perRoom
	}
	if uptoSeq > perRoom[roomID] {
		perRoom[roomID] = uptoSeq
	}
	return s.persist()
}

n_collab_cursor_Store_Snapshot.signature:
// Snapshot 返回该成员全部房间的已读水位快照。
//
// 返回值是独立副本，调用方可以在不持有游标锁的情况下聚合事件。一次快照
// 同时覆盖所有房间，供列表读模型避免逐房间重复读取游标文件/内存映射。
func (s *Store) Snapshot(member string) (map[string]int64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.ensureLoaded(); err != nil {
		return nil, err
	}
	perRoom := s.data[member]
	out := make(map[string]int64, len(perRoom))
	for roomID, seq := range perRoom {
		out[roomID] = seq
	}
	return out, nil
}

n_collab_cursor_Store_ensureLoaded.signature:
// ensureLoaded 首次访问时从磁盘加载（重启/换实例后读回持久化水位）。
func (s *Store) ensureLoaded() error {
	if s.path == "" || s.loaded {
		return nil
	}
	s.loaded = true
	raw, err := os.ReadFile(s.path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("读游标文件 %s: %w", s.path, err)
	}
	if len(raw) == 0 {
		return nil
	}
	if err := json.Unmarshal(raw, &s.data); err != nil {
		return fmt.Errorf("解析游标文件 %s: %w", s.path, err)
	}
	return nil
}

n_collab_cursor_Store_persist.signature:
// persist tmp+rename 原子写：主文件不被半截写损坏；崩溃残留的 tmp 残屑无害
// （拍板 5.4「重启丢失无害」同族，只是更保守——数据已过 rename 才可见）。
func (s *Store) persist() error {
	if s.path == "" {
		return nil
	}
	raw, err := json.Marshal(s.data)
	if err != nil {
		return fmt.Errorf("编码游标: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(s.path), 0o700); err != nil {
		return fmt.Errorf("建游标目录: %w", err)
	}
	tmp := s.path + ".tmp"
	if err := os.WriteFile(tmp, raw, 0o600); err != nil {
		return fmt.Errorf("写游标 tmp: %w", err)
	}
	if err := os.Rename(tmp, s.path); err != nil {
		return fmt.Errorf("游标原子替换: %w", err)
	}
	return nil
}

n_collab_mapSessionError.signature:
// mapSessionError 把出站哨兵 client.ErrNotFound 翻译为 collab.ErrNoRoom
// （gateway 据此映射 404）。
func mapSessionError(err error) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, client.ErrNotFound) {
		return ErrNoRoom
	}
	return err
}

n_collab_needsHumanByCard.signature:
// needsHumanByCard 扫描全流，返回当前处于 needs_human 未清除的卡集合。
func needsHumanByCard(events []proto.LedgerEvent) map[string]bool {
	out := map[string]bool{}
	for _, ev := range events {
		switch ev.Type {
		case "needs_human":
			if ev.CardID != "" {
				out[ev.CardID] = true
			}
		case "needs_cleared":
			delete(out, ev.CardID)
		}
	}
	return out
}

n_collab_payloadString.signature:
// payloadString 从事件载荷取一个字符串键。
func payloadString(raw []byte, key string) string {
	var fields map[string]any
	if err := json.Unmarshal(raw, &fields); err != nil {
		return ""
	}
	value, _ := fields[key].(string)
	return value
}

n_collab_room_ConsumedSeqs.signature:
// ConsumedSeqs 收集该消费者已消费的消息 seq 集：按事件 actor 列（=consumer）
// 粗筛 message_consumed 事件 + 载荷 message_seq/consumer 精确匹配（载荷才是
// 权威，ledger/rooms.go 注释同款）。Pending/Mentions 的「未消费」过滤共用。
func ConsumedSeqs(events []proto.LedgerEvent, consumer string) map[int64]bool {
	consumed := make(map[int64]bool)
	for _, ev := range events {
		if ev.Type != ConsumedEventType || ev.Actor != consumer {
			continue
		}
		var marker struct {
			MessageSeq	int64	`json:"message_seq"`
			Consumer	string	`json:"consumer"`
		}
		if err := json.Unmarshal(ev.Payload, &marker); err != nil {
			continue
		}
		if marker.Consumer != consumer {
			continue
		}
		consumed[marker.MessageSeq] = true
	}
	return consumed
}

n_collab_room_IsAddressed.signature:
// IsAddressed 判断消息是否携带任何寻址（显式 @ 或 reply_to）。空 actor 的
// reply_to 不算寻址（找不到原作者时按无寻址处理）。
func IsAddressed(msg proto.RoomMessage, replyAuthor string) bool {
	if msg.BySystem || msg.Kind == proto.RoomMsgPointer {
		return false
	}
	for _, m := range msg.Mentions {
		if strings.TrimSpace(m) != "" {
			return true
		}
	}
	return msg.ReplyTo > 0 && strings.TrimSpace(replyAuthor) != ""
}

n_collab_room_IsSessionRoom.signature:
// IsSessionRoom 会话房间标识形如 session:<n>（B358 的工作单元）。
func IsSessionRoom(roomID string) bool {
	return len(roomID) > len(sessionPrefix) && roomID[:len(sessionPrefix)] == sessionPrefix
}

n_collab_room_IsTerminalStatus.signature:
// IsTerminalStatus 卡终态判据。取值必须等于 ledger.StatusDone/StatusClosed
// （"已完成"/"终止"）；门面禁令禁止 import ledger，等式由 service_test.go
// 的字面量测试钉住。C5 的 ListRooms 只读投影同用它。
func IsTerminalStatus(status string) bool {
	return status == "已完成" || status == "终止"
}

n_collab_room_KindAllowed.signature:
// KindAllowed kind 是否在受控词表内。
func KindAllowed(kind string) bool {
	switch kind {
	case proto.RoomMsgEscalation, proto.RoomMsgDeviation, proto.RoomMsgClosing,
		proto.RoomMsgRelay, proto.RoomMsgReply, proto.RoomMsgUser, proto.RoomMsgPointer:
		return true
	}
	return false
}

n_collab_room_MentionsMember.signature:
// MentionsMember 判断事件的 mentions 是否含该成员。
func MentionsMember(ev proto.LedgerEvent, member string) bool {
	var msg proto.RoomMessage
	if err := UnmarshalMessage(ev.Payload, &msg); err != nil {
		return false
	}
	for _, m := range msg.Mentions {
		if m == member {
			return true
		}
	}
	return false
}

n_collab_room_MessageKind.signature:
// MessageKind 事件载荷的消息 kind；非 room_message 或解码失败返回空串。
func MessageKind(ev proto.LedgerEvent) string {
	var msg proto.RoomMessage
	if err := UnmarshalMessage(ev.Payload, &msg); err != nil {
		return ""
	}
	return msg.Kind
}

n_collab_room_ReadAllEvents.signature:
// ReadAllEvents 分页读完整事件流（升序游标、每页 1000、EventsFromAsc 语义）。
// A.5 护栏注记（契约 §8 A.5，照抄触发条件）：单流 >10^5 行实测变慢再议，
// 不预先优化、不加类型过滤参数——Pending/Mentions/ListRooms/Unread 的全流
// 扫描都走这里。
func ReadAllEvents(lc client.LedgerClient, fromSeq int64) ([]proto.LedgerEvent, error) {
	var out []proto.LedgerEvent
	seq := fromSeq
	for {
		page, err := lc.EventsFromAsc([]string{}, seq, 1000)
		if err != nil {
			return nil, err
		}
		out = append(out, page...)
		if len(page) < 1000 {
			return out, nil
		}
		seq = page[len(page)-1].Seq
	}
}

n_collab_room_Resolve.signature:
// Resolve 把房间标识解析为执法上下文。
//
// 卡房间（卡号）：存在性、终态、并入态与绑定来自一次 ListAllCards 全量投影
// ——GetCard 不派生 Following（契约 §11.4），并入只读判定只有列表方法送得来，
// 且终态卡也在列表内（IncludeTerminal:true）。群房间恒可写（本期群房间无
// 终态、无绑定可比），不查卡。
//
// 返回哨兵：房间不存在 → ErrNoRoom（直接返回不包裹，调用方 == / errors.Is
// 皆可）。账本读失败（ListAllCards 报错）按原样向上传播，不伪装成 ErrNoRoom。
func Resolve(lc client.LedgerClient, roomID string) (*Room, error) {
	if isGroupRoom(roomID) {
		kind, name := groupRoomKind(roomID)
		log().Info("房间解析为群房间", "room", roomID, "kind", kind, "project", name)
		return &Room{ID: roomID, Kind: kind, Project: name}, nil
	}

	if IsSessionRoom(roomID) {
		log().Info("房间解析为会话房间", "room", roomID)
		return &Room{ID: roomID, Kind: KindSession}, nil
	}
	cards, err := lc.ListAllCards("")
	if err != nil {
		return nil, err
	}
	byID := make(map[string]proto.Card, len(cards))
	for _, c := range cards {
		byID[c.ID] = c
	}
	c, ok := byID[roomID]
	if !ok {
		log().Warn("房间解析失败：卡不存在", "room", roomID)
		return nil, ErrNoRoom
	}
	r := &Room{
		ID:		roomID,
		CardID:		c.ID,
		Kind:		KindCard,
		Project:	c.Project,
		ReadOnly:	IsTerminalStatus(c.Status) || c.Following != "",
		Card:		&c,
	}
	if c.ParentID != "" {
		if p, ok := byID[c.ParentID]; ok {
			r.ParentSession = p.DriverSession
		}
	}
	log().Info("房间解析完成", "room", roomID, "card", c.ID, "read_only", r.ReadOnly,
		"bound", c.DriverSession, "parent_session", r.ParentSession)
	return r, nil
}

n_collab_room_ResolveDelivery.signature:
// ResolveDelivery 把一条消息的寻址解析为被唤醒成员身份集。
//
// 规则：
//   - 显式 mentions 逐个解析：@卡号 经 resolveSeat 解析为该卡当前席位（换绑后
//     依然指向新席位）。resolveSeat 返回 isCard=true 时，seat 非空则唤醒该席位、
//     空则落空（卡在群里但没人坐——@ 不到任何人）；isCard=false 表示 mention
//     不是卡号（外部会话身份如 user:sy），原样使用。
//   - reply_to 命中时把 replyAuthor（被回复消息的作者）作为隐式目标；空串忽略。
//   - BySystem 为真或 kind=pointer 的系统结构行不唤醒任何人。
//   - 无任何寻址返回 nil。
//
// 去重保持首次出现顺序（同一人既被 @ 又回复时只唤醒一次）。
func ResolveDelivery(msg proto.RoomMessage, replyAuthor string, resolveSeat func(mention string) (seat string, isCard bool)) []string {
	if msg.BySystem || msg.Kind == proto.RoomMsgPointer {
		return nil
	}
	var out []string
	seen := map[string]bool{}
	add := func(identity string) {
		identity = strings.TrimSpace(identity)
		if identity == "" || seen[identity] {
			return
		}
		seen[identity] = true
		out = append(out, identity)
	}
	for _, mention := range msg.Mentions {
		mention = strings.TrimSpace(mention)
		if mention == "" {
			continue
		}
		if resolveSeat != nil {
			if seat, isCard := resolveSeat(mention); isCard {

				add(seat)
				continue
			}
		}
		add(mention)
	}
	if msg.ReplyTo > 0 {
		add(replyAuthor)
	}
	return out
}

n_collab_room_RoomIDOf.signature:
// RoomIDOf 事件所属房间 id：卡级事件 card_id 即房间号；群级无卡事件看载荷
// Room 字段（ListRooms 建活动索引用）。
func RoomIDOf(ev proto.LedgerEvent) string {
	if ev.CardID != "" {
		return ev.CardID
	}
	var msg proto.RoomMessage
	if err := UnmarshalMessage(ev.Payload, &msg); err != nil {
		return ""
	}
	return msg.Room
}

n_collab_room_SameRoom.signature:
// SameRoom 判断事件是否属于该房间：卡房间的 card_id 即房间号；群级/会话级
// 无卡事件看载荷 Room 字段。
func SameRoom(ev proto.LedgerEvent, roomID string) bool {
	if isGroupRoom(roomID) || IsSessionRoom(roomID) {
		var msg proto.RoomMessage
		if err := UnmarshalMessage(ev.Payload, &msg); err != nil {
			return false
		}
		return msg.Room == roomID
	}
	return ev.CardID == roomID
}

n_collab_room_UnmarshalMessage.signature:
// UnmarshalMessage 解码房间消息载荷；未知键不报错（encoding/json 默认）。
func UnmarshalMessage(raw json.RawMessage, msg *proto.RoomMessage) error {
	return json.Unmarshal(raw, msg)
}

n_collab_room_VerifyWriter.signature:
// VerifyWriter 按 kind 执法书写者身份（契约 §3.3 执法规则 + §4 清单）。失败
// 统一返回 ErrNotWriter（含空 actor）。
//
// 矩阵：
//   - 协调者类（escalation/deviation/closing/reply）：actor==该卡当前绑定值；
//   - relay：actor==该卡当前绑定值，或 actor==直接父卡当前绑定值（只查一级，
//     拍板 5.5）；
//   - user：actor 非空且不等于该卡当前绑定值；卡有直接父时亦不等于直接父卡
//     绑定值（岔口十最窄读法：相关卡={该卡, 直接父}，与拍板 5.5 一级父同构）；
//   - 群房间无卡可比：仅 user 可写且要求 actor 非空。
func VerifyWriter(r *Room, kind, actor string) error {
	if actor == "" {
		log().Warn("书写者被拒：actor 为空", "room", r.ID, "kind", kind)
		return ErrNotWriter
	}
	switch kind {
	case proto.RoomMsgUser:
		if r.Card == nil {
			return nil
		}
		if actor == r.Card.DriverSession {
			log().Warn("user 被拒：actor 是房间卡绑定者", "room", r.ID,
				"card", r.CardID, "actor", actor)
			return ErrNotWriter
		}
		if r.ParentSession != "" && actor == r.ParentSession {
			log().Warn("user 被拒：actor 是直接父卡绑定者", "room", r.ID,
				"card", r.CardID, "parent_actor", actor)
			return ErrNotWriter
		}
	case proto.RoomMsgRelay:
		if r.Card == nil {
			log().Warn("relay 被拒：群房间无卡可比", "room", r.ID)
			return ErrNotWriter
		}
		if actor != r.Card.DriverSession && actor != r.ParentSession {
			log().Warn("relay 被拒：非本卡或直接父绑定者", "room", r.ID,
				"card", r.CardID, "actor", actor, "bound", r.Card.DriverSession,
				"parent_session", r.ParentSession)
			return ErrNotWriter
		}
	default:
		if r.Card == nil {
			log().Warn("协调者类被拒：群房间无绑定席位可比", "room", r.ID, "kind", kind)
			return ErrNotWriter
		}
		if err := proto.ValidateSeat(r.Card.DriverSession, proto.SeatSource(r.Card.DriverSource)); err != nil {
			log().Warn("协调者类被拒：卡席位不是规范身份", "room", r.ID,
				"card", r.CardID, "kind", kind, "cause", err)
			return ErrNotWriter
		}
		if actor != r.Card.DriverSession {
			log().Warn("协调者类被拒：非当前绑定者", "room", r.ID,
				"card", r.CardID, "kind", kind, "actor", actor,
				"bound", r.Card.DriverSession)
			return ErrNotWriter
		}
	}
	return nil
}

n_collab_room_groupRoomKind.signature:
// groupRoomKind 解析群房间形态：global 返回 (global,"")；project 群返回
// (project, 名字)。
func groupRoomKind(roomID string) (kind, name string) {
	if roomID == "global" {
		return KindGlobal, ""
	}
	const prefix = "project:"
	return KindProject, roomID[len(prefix):]
}

n_collab_room_isGroupRoom.signature:
// isGroupRoom 群房间标识形如 project:<name> 或 global。
func isGroupRoom(roomID string) bool {
	const prefix = "project:"
	return roomID == "global" || len(roomID) > len(prefix) && roomID[:len(prefix)] == prefix
}

n_collab_sessionCards.signature:
// sessionCards 投影会话里的工作项卡（空座卡 Seat 为空串）。
func sessionCards(session proto.Session, byCard map[string]proto.Card) []proto.SessionCard {
	out := make([]proto.SessionCard, 0, len(session.Cards))
	for _, cardID := range session.Cards {
		card, ok := byCard[cardID]
		if !ok {
			out = append(out, proto.SessionCard{CardID: cardID})
			continue
		}
		out = append(out, proto.SessionCard{
			CardID:	card.ID, Title: card.Title, Status: card.Status, Seat: card.DriverSession,
		})
	}
	return out
}

n_collab_sessionNodes.signature:
// sessionNodes 从卡挂账/镜像投影协调者派发的任务节点（不新增执行域依赖）。
func sessionNodes(session proto.Session, byCard map[string]proto.Card, events []proto.LedgerEvent) []proto.SessionNode {
	out := []proto.SessionNode{}
	for _, cardID := range session.Cards {
		for _, ev := range events {
			if ev.CardID != cardID || ev.Type != "task_mirrored" {
				continue
			}
			var envelope struct {
				Node		*string	`json:"node"`
				TaskType	string	`json:"task_type"`
			}
			if err := json.Unmarshal(ev.Payload, &envelope); err != nil || envelope.Node == nil {
				continue
			}
			out = append(out, proto.SessionNode{
				CardID:	cardID, Node: *envelope.Node, State: envelope.TaskType,
			})
		}
	}
	return out
}

n_collab_sessionTimeline.signature:
// sessionTimeline 投影会话 timeline：入群/移出/归档结构事件 + 席位变更。
func sessionTimeline(events []proto.LedgerEvent, sessionID string, byCard map[string]proto.Card) []proto.SessionTimelineEvent {
	out := []proto.SessionTimelineEvent{}
	for _, ev := range events {
		kind := ""
		cardID := ""
		detail := ""
		switch ev.Type {
		case "session_card_joined":
			kind, cardID = proto.SessionEventCardJoined, payloadString(ev.Payload, "card")
		case "session_card_left":
			kind, cardID = proto.SessionEventCardLeft, payloadString(ev.Payload, "card")
		case "session_archived":
			kind = proto.SessionEventArchived
		case "session_created":
			kind = proto.SessionEventCreated
		case "driver_takeover":

			cardID = ev.CardID
			if _, ok := byCard[cardID]; !ok {
				continue
			}
			kind, detail = proto.SessionEventSeatRebound, string(ev.Payload)
		default:
			continue
		}
		if kind == proto.SessionEventCreated || kind == proto.SessionEventArchived {
			if payloadString(ev.Payload, "session") != "" && payloadString(ev.Payload, "session") != sessionID {
				continue
			}
		}
		out = append(out, proto.SessionTimelineEvent{
			Seq:	ev.Seq, Kind: kind, CardID: cardID, Detail: detail,
			Actor:	ev.Actor, CreatedAt: ev.CreatedAt,
		})
	}
	return out
}

n_collab_truncateRoomPreview.signature:
// truncateRoomPreview 按 rune 截断列表预览，避免多字节正文被半截字节切坏；
// 省略号占一个预算位，调用方可据此把超长正文识别为摘要。
func truncateRoomPreview(body string) string {
	runes := []rune(body)
	if len(runes) <= roomPreviewMaxRunes {
		return body
	}
	return string(runes[:roomPreviewMaxRunes-1]) + "…"
}

n_collab_unreadByRoom.signature:
// unreadByRoom 从列表已经读取的全量事件中聚合成员未读数。
//
// 列表本来就需要一次事件流读取来计算 LastActivity；复用这批事件，并在一次
// Snapshot 游标快照上比较水位，避免每个房间再次 Cursor+ReadAllEvents。
func unreadByRoom(events []proto.LedgerEvent, cursors map[string]int64) map[string]int {
	out := make(map[string]int)
	for _, ev := range events {
		if ev.Type != room.RoomEventType {
			continue
		}
		roomID := room.RoomIDOf(ev)
		if roomID == "" || ev.Seq <= cursors[roomID] {
			continue
		}
		out[roomID]++
	}
	return out
}

n_config_ClassifyListen.signature:
// ClassifyListen 把 listen 的 host 归为三档，并推导 loopback 变体地址。
//
// 参数：
//   - listen: 形如 "host:port" 的监听地址
//
// 返回：
//   - cls: 三档归类；解析失败归 ListenLoopback（即调用方什么都不做）
//   - loopback: 通配/单点档为 "127.0.0.1:<同端口>"；loopback 档（含解析失败）
//     原样返回 listen，调用方可无条件使用返回值
func ClassifyListen(listen string) (cls ListenClass, loopback string) {
	host, port, err := net.SplitHostPort(listen)
	if err != nil {
		return ListenLoopback, listen
	}
	if host == "" {
		return ListenWildcard, net.JoinHostPort("127.0.0.1", port)
	}

	if host == "localhost" {
		return ListenLoopback, listen
	}
	ip := net.ParseIP(host)
	switch {
	case ip == nil:

		return ListenSingle, net.JoinHostPort("127.0.0.1", port)
	case ip.IsLoopback():
		return ListenLoopback, listen
	case ip.IsUnspecified():
		return ListenWildcard, net.JoinHostPort("127.0.0.1", port)
	default:
		return ListenSingle, net.JoinHostPort("127.0.0.1", port)
	}
}

n_config_Config_PlatformInvariantsEnable.signature:
// PlatformInvariantsEnabled 返回本机是否注入平台不变量恒在层。
//
// 参数：无；接收 nil Config 时按默认启用处理，便于启动早期与测试构造使用。
// 返回：配置缺失或显式 true 时为 true；只有显式 false 时为 false。
// 注意：调用方不要直接解引用 PlatformInvariants，否则旧配置会把默认底线误关掉。
func (c *Config) PlatformInvariantsEnabled() bool {
	if c == nil || c.PlatformInvariants == nil {
		return true
	}
	return *c.PlatformInvariants
}

n_config_Config_validate.signature:
// validate 校验取值域，把「能解析但必然误动作」的配置挡在启动之前。
//
// 为什么 stalltimeout 必须为正：它是「running 任务多久没动静就算卡住」的阈值。
// 写成 0 或负数时，看门狗会在**每个** running 任务的首个 tick 上判定 stalled，
// 协调者被一批凭空的 stalled 事件叫醒，而任务其实好好的。省略该键走默认值
// （2h）是正常用法，只有显式写了非正值才是配置错误。
func (c *Config) validate() error {
	if c.StallTimeout <= 0 {
		return fmt.Errorf("stalltimeout 必须为正时长（当前 %s）；省略该键即用默认 2h", c.StallTimeout)
	}

	if err := proxycfg.Validate(c.Proxy); err != nil {
		return err
	}
	if err := c.Relay.Validate(); err != nil {
		return fmt.Errorf("relay 配置校验失败: %w", err)
	}
	for name, target := range c.Targets {
		if err := target.Validate(); err != nil {
			return fmt.Errorf("target %q 校验失败: %w", name, err)
		}
	}

	if c.Approver.Executor != "" {
		if c.Approver.Timeout <= 0 {
			return fmt.Errorf("approver.timeout 必须为正时长（当前 %s）", c.Approver.Timeout)
		}
		for i, r := range c.Approver.Blacklist {

			if _, err := regexp.Compile(r); err != nil {
				return fmt.Errorf("approver.blacklist[%d] 非法正则 %q: %w", i, r, err)
			}
		}
	}
	return nil
}

n_config_DefaultPath.signature:
// DefaultPath 返回默认配置文件路径（~/.handoff/config.yaml）。
func DefaultPath() string {
	return filepath.Join(defaultDataDir(), "config.yaml")
}

n_config_Defaults.signature:
// Defaults 返回一份「出厂默认 + 随机 token」的配置，**不落盘**。
//
// 与 Load 的分工：Load 在文件不存在时会生成 token 并把默认配置写盘（firstRun），
// 这是给 CLI/agentd 用的。桌面壳的首次引导不能调 Load——向导问答中途崩溃、
// 被杀或取消时，磁盘上绝不允许出现会让 Resolve 判为「已配置」的 config.yaml
// （SIGKILL 实测原样复现过这个坑，且回滚法依赖进程还活着，封不死）。Defaults
// 只构造内存里的配置，落盘由调用方在问答成功后一次性 config.Save。
func Defaults() *Config {
	cfg := newDefaultConfig()
	cfg.Token = randToken()
	applyComputedDefaults(cfg)
	if verr := cfg.validate(); verr != nil {

		panic("config: 出厂默认校验失败: " + verr.Error())
	}
	return cfg
}

n_config_IsSelfTarget.signature:
// IsSelfTarget reports whether target addresses this agentd instance.
//
// 参数：
//   - listen: 本机配置的监听地址，形如 "host:port"
//   - target: 待判断的目标；relay target 永远不是本机
//
// 返回：
//   - true 表示地址与 listen、其 loopback 变体或同端口 loopback/localhost 相符
//
// 注意：此函数只比较地址身份，不验证网络可达性；地址可带 URL scheme。
func IsSelfTarget(listen string, target Target) bool {
	if target.IsRelay() || target.Addr == "" {
		return false
	}
	listenHP, ok := normalizeHostPort(listen)
	if !ok {
		return false
	}
	targetHP, ok := normalizeHostPort(target.Addr)
	if !ok {
		return false
	}
	if targetHP == listenHP {
		return true
	}
	_, loopback := ClassifyListen(listenHP)
	loopbackHP, loopbackOK := normalizeHostPort(loopback)
	if loopbackOK && targetHP == loopbackHP {
		return true
	}
	_, listenPort, listenOK := splitNormalizedHostPort(listenHP)
	targetHost, targetPort, targetOK := splitNormalizedHostPort(targetHP)
	targetIP := net.ParseIP(targetHost)
	return listenOK && targetOK && listenPort == targetPort &&
		(targetHost == "localhost" || targetIP != nil && targetIP.IsLoopback())
}

n_config_Load.signature:
// Load 加载配置：文件不存在时返回带默认值的 Config 并自动生成随机 Token 写盘。
//
// 参数：
//   - path: 配置文件路径
//
// 返回：
//   - 解析后的配置；文件不存在时返回默认配置
//   - 错误信息：读/解析/校验失败时返回。剥 update 后回写失败不返回错误
//
// 注意：
//   - 首次运行生成的 Token 需要人工同步到配对主机的 Targets 中
//   - 旧文件的顶层 update 必须先剥再 KnownFields，否则 v0.1.x 机器升级即砖
//
// 与 Defaults 的分工：Load 在文件不存在时会生成 token 并把默认配置写盘（firstRun），
// 这是给 CLI/agentd 用的；桌面壳的首次引导走 Defaults（见其 doc 注释）。
func Load(path string) (*Config, error) {
	cfg := newDefaultConfig()

	firstRun := false

	stripped := false
	b, err := os.ReadFile(path)
	switch {
	case errors.Is(err, os.ErrNotExist):
		cfg.Token = randToken()
		firstRun = true
		log().Info("首次运行，将生成配置", "path", path)
	case err != nil:
		return nil, fmt.Errorf("读配置 %s: %w", path, err)
	default:
		// 必须先剥顶层 update 再 KnownFields：v0.1.x 写过的旧文件里仍有
		// 这段死配置，直接严格解码会把整个 agentd 卡在启动上。
		var cleaned []byte
		var serr error
		cleaned, stripped, serr = stripDeprecatedTopLevel(b)
		if serr != nil {
			log().Error("配置解析失败", "path", path, "cause", serr)
			return nil, fmt.Errorf("解析配置 %s: %w", path, serr)
		}
		if stripped {
			log().Warn("配置 update 段已废弃，已忽略并将从文件删除", "path", path)
			b = cleaned
		}
		if uerr := decodeStrict(b, cfg); uerr != nil {
			log().Error("配置解析失败", "path", path, "cause", uerr)
			return nil, fmt.Errorf("解析配置 %s: %w", path, uerr)
		}
		// B229 §2.6：ledger.enabled 键退休——字段与键保留（KnownFields 严格解析
		// 不炸存量 config），值已无任何语义。这里按「键是否存在」告警而不是按值：
		// 退休要提醒的是写过这个开关的机器（配了却无效必须可见），没写过的机器
		// 不该被一个自己从未用过的开关天天打扰。指针探测 nil 与显式 false。
		var retiredProbe struct {
			LedgerCfg struct {
				Enabled *bool `yaml:"enabled"`
			} `yaml:"ledger"`
		}
		if perr := yaml.Unmarshal(b, &retiredProbe); perr == nil && retiredProbe.LedgerCfg.Enabled != nil {
			log().Warn("ledger.enabled 已退休：纪律块入库后账本是必需品，该键已忽略", "path", path)
		}
	}
	applyComputedDefaults(cfg)
	if firstRun {
		if werr := save(path, cfg); werr != nil {
			return nil, fmt.Errorf("写默认配置 %s: %w", path, werr)
		}
		log().Info("首次运行，已生成配置", "path", path)
	}
	if verr := cfg.validate(); verr != nil {
		log().Error("配置校验失败", "path", path, "cause", verr)
		return nil, fmt.Errorf("校验配置 %s: %w", path, verr)
	}
	if !cfg.PlatformInvariantsEnabled() {
		log().Warn("平台不变量已通过显式配置关闭", "path", path, "key", "platform_invariants")
	}
	if cfg.Relay != nil {
		log().Info("relay egress configured", "url", cfg.Relay.URL, "node", cfg.Relay.Node)
	}
	if cfg.Proxy != "" {

		log().Info("已配置出网代理", "proxy", proxycfg.Redact(cfg.Proxy))
	}

	if stripped && !firstRun {
		if werr := save(path, cfg); werr != nil {
			log().Error("删除废弃 update 段后回写失败", "path", path, "cause", werr)
		} else {
			log().Info("已从配置文件删除废弃 update 段", "path", path)
		}
	}
	return cfg, nil
}

n_config_LocalDialAddr.signature:
// LocalDialAddr returns the scheme-qualified address used to dial this agentd.
//
// 参数：
//   - listen: 本机配置的监听地址，形如 "host:port"，也可带 scheme
//
// 返回：
//   - 带 http:// scheme 的本机拨号地址；非 loopback listen 改写为同端口的
//     127.0.0.1 地址
//
// 注意：地址归类复用 ClassifyListen；该函数只做确定性地址改写，不做连接尝试。
func LocalDialAddr(listen string) string {
	if cls, loopback := ClassifyListen(listen); cls != ListenLoopback {
		listen = loopback
	}
	if !strings.Contains(listen, "://") {
		listen = "http://" + listen
	}
	return listen
}

n_config_RelayConfig_Validate.signature:
// Validate validates the executor relay configuration. ws:// is accepted for
// local tests; production deployments should use wss://.
func (r *RelayConfig) Validate() error {
	if r == nil {
		return nil
	}
	if err := validateRelayURL(r.URL); err != nil {
		return fmt.Errorf("relay.url: %w", err)
	}
	if r.Credential == "" {
		return errors.New("relay.credential 不能为空")
	}
	if r.Node == "" {
		return errors.New("relay.node 不能为空")
	}
	return nil
}

n_config_Save.signature:
// Save 把配置以 YAML 写盘，自动创建父目录，文件权限 0600。
//
// 参数：
//   - path: 目标路径
//   - cfg: 要写入的配置
//
// 返回：
//   - 错误信息：建目录、序列化或写盘失败时返回
//
// 注意：
//   - 0600 是硬要求：配置里含 token，组内可读就等于把令牌给了同机其他账号
func Save(path string, cfg *Config) error	{ return save(path, cfg) }

n_config_Target_Validate.signature:
// Validate validates a target. Relay and direct targets are mutually exclusive:
// relay targets require Relay, Credential, Node, and Token, while direct targets
// require Addr.
func (t Target) Validate() error {
	if t.IsRelay() {
		if err := validateRelayURL(t.Relay); err != nil {
			return fmt.Errorf("target.relay: %w", err)
		}
		if t.Addr != "" {
			return errors.New("target relay 与 addr 互斥")
		}
		if t.Credential == "" {
			return errors.New("relay target credential 不能为空")
		}
		if t.Node == "" {
			return errors.New("relay target node 不能为空")
		}
		if t.Token == "" {
			return errors.New("relay target token 不能为空")
		}
		return nil
	}
	if t.Addr == "" {
		return errors.New("direct target addr 不能为空")
	}
	return nil
}

n_config_applyComputedDefaults.signature:
// applyComputedDefaults 补算依赖实际值才能定的默认项，必须在解码之后调用：
// repo_root 派生自 DataDir 与 ProcFence 的越界兜底都依赖已解析的配置内容。
func applyComputedDefaults(cfg *Config) {

	if cfg.RepoRoot == "" {
		cfg.RepoRoot = filepath.Join(cfg.DataDir, "repos")
		log().Debug("repo_root 未配置，采用默认落点", "repo_root", cfg.RepoRoot)
	}

	if cfg.ProcFence.ReserveRatio <= 0 || cfg.ProcFence.ReserveRatio >= 1 {
		cfg.ProcFence.ReserveRatio = 0.1
	}

	if cfg.ProcFence.TaskBudget < 0 {
		cfg.ProcFence.TaskBudget = 0
	}
	if cfg.ProcFence.TaskHardLimit < 0 {
		cfg.ProcFence.TaskHardLimit = 0
	}

	if cfg.ProcFence.TaskBudget > 0 && cfg.ProcFence.TaskHardLimit > 0 &&
		cfg.ProcFence.TaskHardLimit < cfg.ProcFence.TaskBudget {
		cfg.ProcFence.TaskHardLimit = cfg.ProcFence.TaskBudget
	}
}

n_config_decodeStrict.signature:
// decodeStrict 用 yaml.Decoder + KnownFields(true) 严格解析配置。
//
// 为什么必须严格（L-1）：yaml.Unmarshal 对未知键静默忽略——旧配置里的
// access_key/secret_key 等已废弃标量会被无声吞掉，而这类键在旧版本中承载
// 鉴权语义：忽略它们会让 agentd 在用户不知情时以无 token 状态启动（安全
// 静默降级）。严格解析让任何键名笔误/废弃键立即报错，错误文本自带未知键名
// （yaml 的 "field <key> not found"）与已知键清单，运维升级时一眼可定位。
// KnownFields 对 targets map 的 value（Target 结构）同样生效，目标条目内的
// 未知键同样被拒绝。
//
// 注意：
//   - 空文件按「无内容」处理（返回 nil、保持默认值），与 yaml.Unmarshal
//     对空输入的 no-op 语义一致——Decode 对空输入返回 io.EOF，不能当错误
func decodeStrict(b []byte, cfg *Config) error {
	dec := yaml.NewDecoder(bytes.NewReader(b))
	dec.KnownFields(true)
	if err := dec.Decode(cfg); err != nil {
		if errors.Is(err, io.EOF) {
			return nil
		}

		return fmt.Errorf("配置包含未知字段（支持: listen/token/datadir/repo_root/path_dirs/proxy/env_forward/stalltimeout/relay{url,credential,node}/targets{addr,user,token,relay,credential,node}/ledger{enabled,dsn}/approver{executor,model,timeout,blacklist}/executor{default,model}/terminal{auto}/sync{auto}/proc_fence/env{<agent>: <文件名>}/discipline{<executor>: <文件名>}/platform_invariants）: %w；旧版 access_key/secret_key 等键已废弃，请删除未知键或升级配置", err)
	}
	return nil
}

n_config_defaultDataDir.signature:
// defaultDataDir 返回默认数据目录；取不到用户主目录时回退到当前目录下的 .handoff。
func defaultDataDir() string {
	if h, err := os.UserHomeDir(); err == nil {
		return filepath.Join(h, ".handoff")
	}
	return ".handoff"
}

n_config_log.signature:
// log 是本包日志入口，运行时取 slog.Default()（与 store 包一致）。
// agentd 在 bootstrap 时 logx.Setup + slog.SetDefault(...)，本包日志即跟随统一格式与级别。
// 为什么不用包级 var 捕获：包级 var 在 package init 时求值，晚于其执行的 slog.SetDefault
// 不会生效；运行时求值才能保证「agentd 先 Setup 后 SetDefault」的接线真正接管本包日志。
func log() *slog.Logger	{ return slog.Default() }

n_config_newDefaultConfig.signature:
// newDefaultConfig 构造出厂默认配置（不落盘）。
//
// 初始字面量预置默认值，yaml 覆盖式解码：配置里没写的键保持默认
// （如 approver.timeout=60s、executor.default=opencode、terminal.auto=false），
// 写了的键覆盖——而非「只读显式配置，其余为空」导致默认值丢失。
func newDefaultConfig() *Config {
	return &Config{
		Listen:	"127.0.0.1:7777", DataDir: defaultDataDir(), StallTimeout: 2 * time.Hour,
		Approver:	ApproverConfig{Timeout: 60 * time.Second},
		Executor:	ExecutorConfig{Default: "opencode"},
		Terminal:	TerminalConfig{Auto: false},
		Sync:		SyncConfig{Auto: true},
		ProcFence: ProcFenceConfig{

			ReserveRatio:	0.1, TaskBudget: 400, TaskHardLimit: 1200,
		},
		Targets:	map[string]Target{},
		Env:		map[string]string{},
		Discipline:	map[string]string{},
	}
}

n_config_normalizeHostPort.signature:
// normalizeHostPort removes a URL scheme before parsing host:port. url.Parse must
// not see a bare host:port because it would treat the first segment as a scheme;
// ClassifyListen likewise only accepts an unqualified host:port.
func normalizeHostPort(raw string) (string, bool) {
	raw = strings.TrimSpace(raw)
	if strings.Contains(raw, "://") {
		u, err := url.Parse(raw)
		if err != nil || u.Host == "" {
			return "", false
		}
		raw = u.Host
	}
	host, port, err := net.SplitHostPort(raw)
	if err != nil || port == "" {
		return "", false
	}
	return net.JoinHostPort(strings.ToLower(host), port), true
}

n_config_randToken.signature:
// randToken 生成 16 字节（32 位十六进制字符）的加密随机令牌。
//
// 16 字节即 128 位随机熵，对本地配对场景足够：token 仅用于本机 agent 与
// agentd 之间的本地认证，不跨网络传输，穷举 2^128 空间不可行。
// 写盘文件权限为 0600，进一步限制了本地其他用户读取的可能。
func randToken() string {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	return hex.EncodeToString(b)
}

n_config_removeMapKey.signature:
// removeMapKey 从 MappingNode 顶层切掉名为 key 的那一对（Content 是
// key/value 交错）。只动这一层，不递归。
func removeMapKey(n *yaml.Node, key string) bool {
	if n == nil || n.Kind != yaml.MappingNode {
		return false
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			n.Content = append(n.Content[:i], n.Content[i+2:]...)
			return true
		}
	}
	return false
}

n_config_save.signature:
// save 将配置以 YAML 形式写盘，自动创建父目录，文件权限 0600。
func save(path string, cfg *Config) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("创建配置目录 %s: %w", filepath.Dir(path), err)
	}
	b, err := yaml.Marshal(cfg)
	if err != nil {
		return fmt.Errorf("序列化配置: %w", err)
	}
	return os.WriteFile(path, b, 0o600)
}

n_config_splitNormalizedHostPort.signature:
func splitNormalizedHostPort(raw string) (host, port string, ok bool) {
	host, port, err := net.SplitHostPort(raw)
	return strings.ToLower(host), port, err == nil
}

n_config_stripDeprecatedTopLevel.signature:
// stripDeprecatedTopLevel 删掉已废弃的顶层键，返回剥过的 yaml 和是否剥到了东西。
//
// 为什么在 KnownFields 之前做：v0.1.x 写过 update 段的机器升级后，直接严格
// 解码会拒启动。剥掉再解码，旧文件能起，其它未知键仍硬拒。只剥顶层，
// 不走进 targets / env，避免误伤嵌套里碰巧叫 update 的键。
func stripDeprecatedTopLevel(b []byte) (out []byte, stripped bool, err error) {
	if len(bytes.TrimSpace(b)) == 0 {
		return b, false, nil
	}
	var root yaml.Node
	if err := yaml.Unmarshal(b, &root); err != nil {
		return nil, false, err
	}

	mapping := &root
	if root.Kind == yaml.DocumentNode {
		if len(root.Content) == 0 {
			return b, false, nil
		}
		mapping = root.Content[0]
	}
	if mapping.Kind != yaml.MappingNode {
		return b, false, nil
	}
	stripped = removeMapKey(mapping, "update")
	if !stripped {
		return b, false, nil
	}
	out, err = yaml.Marshal(&root)
	return out, true, err
}

n_config_validateRelayURL.signature:
func validateRelayURL(raw string) error {
	u, err := url.Parse(raw)
	if err != nil {
		return fmt.Errorf("URL 无法解析: %w", err)
	}
	if (u.Scheme != "wss" && u.Scheme != "ws") || u.Host == "" {
		return fmt.Errorf("URL 必须是 wss:// 或 ws://（当前 %q）", raw)
	}
	return nil
}

n_decision_GateDecision.signature:
// GateDecision preserves the old manager-to-executor translation: only the
// exact answer "allow" grants once; all other answers reject, with a deny
// reason copied only from the explicit deny form.
func GateDecision(answer string) (decision, reason string) {
	trimmed := strings.TrimSpace(answer)
	if trimmed == "allow" {
		return "once", ""
	}
	rest := strings.TrimPrefix(trimmed, "deny")
	rest = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(rest), ":"))
	if rest == trimmed {
		return "reject", ""
	}
	return "reject", rest
}

n_decision_MapGateAnswer.signature:
// MapGateAnswer 把 ticket answer 映射为 executor.ApprovalDecision。
func MapGateAnswer(ans string) executor.ApprovalDecision {
	d, reason := GateDecision(ans)
	if d == "once" {
		return executor.ApprovalDecision{Status: executor.ApprovalAllow}
	}
	return executor.ApprovalDecision{Status: executor.ApprovalDeny, Reason: reason}
}

n_decision_PermEventText.signature:
// PermEventText 截断权限文案到 200 rune 并附 executor.TruncationMarker。
func PermEventText(s string) string {
	const limit = 200
	if len([]rune(s)) <= limit {
		return s
	}
	r := []rune(s)
	return string(r[:limit]) + executor.TruncationMarker
}

n_discipline_Compose.signature:
// Compose 把 Resolver 产出的角色/执行者纪律块与平台层组装成一个 Block。
//
// 参数：base 为 Resolver.ByName 或 Resolver.For 的结果；platformEnabled 控制平台层。
// 返回：启用时按「平台头部、base 正文、平台尾部」组装；关闭时保留 base。
// 注意：这是唯一的平台正文组装函数，调用方不得自己拼接头、base、尾。
func Compose(base Block, platformEnabled bool) Block {
	baseSource := strings.TrimSpace(base.Source)
	if !platformEnabled {
		source := "平台不变量已关闭"
		if baseSource != "" {
			source += " + " + baseSource
		}
		return Block{Text: base.Text, Source: source}
	}

	parts := []string{strings.TrimSpace(platformInvariantHead)}
	if strings.TrimSpace(base.Text) != "" {
		parts = append(parts, strings.TrimSpace(base.Text))
	}
	parts = append(parts, strings.TrimSpace(platformInvariantTail))
	source := "内置:平台不变量"
	if baseSource != "" {
		source += " + " + baseSource
	}
	return Block{Text: strings.Join(parts, "\n\n"), Source: source}
}

n_discipline_ResolveDispatch.signature:
// ResolveDispatch 是一次派发的纪律正文全链路收口（B229 契约 §2.2）。
//
// 参数：
//   - lookup: 账本读取视图。ref 未点名时不调用，可为 nil
//   - ref: 纪律来源（Name / RawText 二选一 / 都空）
//   - platformEnabled: 协调者侧 PlatformInvariantsEnabled() 的原值
//   - targetCap: 目标机 StatusResp.DisciplinesSupported 原值。三态解释：
//     nil（对端没上报 = 版本太老）与 false 都按不支持处置 → 拒发；
//     true 放行。方向与 PtySupported 刻意相反、与 LaunchersSupported 同向，
//     理由见 B229 契约 §2.4：这里放行的代价是静默降级。
func ResolveDispatch(lookup DisciplineLookup, ref DisciplineRef, platformEnabled bool, targetCap *bool) (ResolvedDiscipline, error) {
	if targetCap == nil || !*targetCap {
		return ResolvedDiscipline{}, ErrUnsupportedTarget
	}
	if ref.Name != "" && ref.RawText != "" {
		return ResolvedDiscipline{}, fmt.Errorf("discipline name 与 raw text 只能二选一")
	}
	switch {
	case strings.TrimSpace(ref.Name) != "":
		if ref.Name != strings.TrimSpace(ref.Name) {
			return ResolvedDiscipline{}, fmt.Errorf("纪律块名字 %q 带首尾空白", ref.Name)
		}
		if lookup == nil {
			return ResolvedDiscipline{}, fmt.Errorf("点名纪律块 %s 需要账本，但账本读取视图未注入", ref.Name)
		}
		version, body, err := lookup(ref.Name)
		if err != nil {
			return ResolvedDiscipline{}, fmt.Errorf("未知纪律块名字 %q: %w", ref.Name, err)
		}
		base := Block{Text: body, Source: "账本:" + ref.Name}
		assembled := Compose(base, platformEnabled)
		return ResolvedDiscipline{
			Text:	assembled.Text, Source: assembled.Source,
			Name:	ref.Name, Version: version,
		}, nil
	case ref.RawText != "":
		base := Block{Text: ref.RawText, Source: "临时正文"}
		assembled := Compose(base, platformEnabled)
		return ResolvedDiscipline{Text: assembled.Text, Source: assembled.Source}, nil
	default:
		assembled := Compose(Block{}, platformEnabled)
		return ResolvedDiscipline{Text: assembled.Text, Source: assembled.Source}, nil
	}
}

n_engine_Engine_Attach.signature:
// Attach 订阅一个会话，并原子地取回 since 之后的历史。
//
// 「原子」是关键：回放与订阅必须在同一把锁里完成，否则两者之间产生的输出
// 会两头都不落，用户看到的历史就缺了一段。
func (h *Engine) Attach(id string, since uint64) (*ptyhost.Attachment, error) {
	s, err := h.get(id)
	if err != nil {
		return nil, err
	}
	s.mu.Lock()
	if len(s.subs) >= maxSubscribers {
		s.mu.Unlock()
		h.log.Warn("终端会话连接数已达上限，拒绝新连接",
			"session", id, "limit", maxSubscribers)
		return nil, ptyhost.ErrTooManySubscribers
	}
	backlog, start, truncated := s.buf.since(since)
	sub := &subscriber{ch: make(chan []byte, subscriberBuffer)}
	if s.exited {

		close(sub.ch)
	} else {
		s.subs[sub] = struct{}{}
	}
	attached := len(s.subs)
	s.mu.Unlock()

	h.log.Info("终端会话已接入", "session", id, "since", since,
		"backlog_bytes", len(backlog), "truncated", truncated, "attached", attached)
	return ptyhost.NewAttachment(backlog, start, truncated, sub.ch,
		&engineAttachOps{h: h, s: s, sub: sub}), nil
}

n_engine_Engine_Close.signature:
// Close 显式关闭会话：整组 SIGTERM，宽限 termGrace 后 SIGKILL，并等待已有 reap。
//
// 会话表仍在发信号前摘除，保持 List/第二次 Close 的同步语义；但函数返回前必须
// 观察 exitedDone，确保 shell 的 EXIT trap、exit code、订阅关闭和 PTY 文件关闭已经完成。
func (h *Engine) Close(id string) error {
	h.mu.Lock()
	s, ok := h.sess[id]
	if ok {
		delete(h.sess, id)
	}
	remain := len(h.sess)
	h.mu.Unlock()
	if !ok {
		return ptyhost.ErrNoSession
	}
	started := time.Now()
	if err := terminatePty(s.cmd); err != nil {
		h.log.Error("终止终端会话失败", "session", id, "pid", s.meta.PID, "phase", "sigterm", "err", err)
	}
	sigkill := false
	timer := time.NewTimer(termGrace)
	defer timer.Stop()
	select {
	case <-s.exitedDone:
	case <-timer.C:
		sigkill = true
		h.log.Warn("终端会话在宽限期内未退出，强制终止", "session", id,
			"pid", s.meta.PID, "grace", termGrace)
		if err := killPty(s.cmd); err != nil {
			h.log.Error("强制终止终端会话失败", "session", id, "pid", s.meta.PID, "phase", "sigkill", "err", err)
		}
		<-s.exitedDone
	}
	h.log.Info("终端会话已关闭", "session", id, "pid", s.meta.PID,
		"sessions", remain, "sigkill", sigkill, "elapsed", time.Since(started))
	return nil
}

n_engine_Engine_Get.signature:
// Get 取单个会话快照。第二个返回值 false = 不存在。
func (h *Engine) Get(id string) (ptyhost.Session, bool) {
	s, err := h.get(id)
	if err != nil {
		return ptyhost.Session{}, false
	}
	return s.snapshot(), true
}

n_engine_Engine_List.signature:
// List 返回全部会话快照（含已退出但未被显式关闭的）。
func (h *Engine) List() []ptyhost.Session {
	h.mu.Lock()
	all := make([]*session, 0, len(h.sess))
	for _, s := range h.sess {
		all = append(all, s)
	}
	h.mu.Unlock()
	out := make([]ptyhost.Session, 0, len(all))
	for _, s := range all {
		out = append(out, s.snapshot())
	}
	sort.Slice(out, func(i, j int) bool { return out[i].CreatedAt.Before(out[j].CreatedAt) })
	return out
}

n_engine_Engine_Open.signature:
// Open 起一个新会话。失败时不留残骸。
func (h *Engine) Open(opt ptyhost.OpenOptions) (ptyhost.Session, error) {
	if !ptySupported {
		return ptyhost.Session{}, ptyhost.ErrNotSupported
	}
	if opt.Cols <= 0 {
		opt.Cols = 80
	}
	if opt.Rows <= 0 {
		opt.Rows = 24
	}
	f, cmd, err := startPty(opt.Shell, opt.BasePath, opt.Env, opt.Cols, opt.Rows)
	if err != nil {

		h.log.Error("开终端会话失败", "shell", opt.Shell, "cwd", opt.BasePath, "err", err)
		return ptyhost.Session{}, err
	}
	s := &session{
		meta: ptyhost.Session{
			ID:	uuid.NewString(), BasePath: opt.BasePath, BaseKind: opt.BaseKind,
			Shell:	opt.Shell, CreatedAt: time.Now(),
			Cols:	opt.Cols, Rows: opt.Rows, PID: cmd.Process.Pid,
		},
		f:	f, cmd: cmd, buf: newRing(ringSize), subs: map[*subscriber]struct{}{},
		exitedDone:	make(chan struct{}), firstOut: make(chan struct{}),
	}
	h.mu.Lock()
	h.sess[s.meta.ID] = s
	total := len(h.sess)
	h.mu.Unlock()

	go h.pump(s)
	go h.reap(s)

	if opt.InitCommand != "" {
		go h.writeInitCommand(s, opt.InitCommand)
	}

	h.log.Info("终端会话已创建", "session", s.meta.ID, "pid", s.meta.PID,
		"shell", opt.Shell, "base_kind", opt.BaseKind, "cwd", opt.BasePath,
		"size", fmtSize(opt.Cols, opt.Rows), "sessions", total)
	return s.snapshot(), nil
}

n_engine_Engine_Write.signature:
// Write 把用户按键送进 PTY。会话已退出时返回 ErrSessionExited。
func (h *Engine) Write(id string, p []byte) error {
	s, err := h.get(id)
	if err != nil {
		return err
	}
	s.mu.Lock()
	exited := s.exited
	s.mu.Unlock()
	if exited {
		return ptyhost.ErrSessionExited
	}
	if _, err := s.f.Write(p); err != nil {
		h.log.Error("向终端会话写入失败", "session", id, "bytes", len(p), "err", err)
		return err
	}
	return nil
}

n_engine_Engine_get.signature:
func (h *Engine) get(id string) (*session, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	s, ok := h.sess[id]
	if !ok {
		return nil, ptyhost.ErrNoSession
	}
	return s, nil
}

n_engine_Engine_pump.signature:
// pump 是读循环：把 PTY 输出写进环并广播。PTY 主端在子进程退出后返回
// EIO（linux）或 EOF（darwin），两者都只意味着「读到头了」，不记为错误。
func (h *Engine) pump(s *session) {
	b := make([]byte, readChunk)
	for {
		n, err := s.f.Read(b)
		if n > 0 {
			s.broadcast(b[:n])

			s.firstOutOnce.Do(func() { close(s.firstOut) })
		}
		if err != nil {
			h.log.Debug("终端会话输出流结束", "session", s.meta.ID, "err", err)
			return
		}
	}
}

n_engine_Engine_reap.signature:
// reap 是每个 shell 唯一的 cmd.Wait 所有者。
//
// exitedDone 只在 exit code、订阅通道和 PTY 文件都收口后关闭；Engine.Close 只能等
// 这个通道，禁止另起 cmd.Wait，否则 os/exec 的 Wait 竞态会把 exit code 与清理顺序拆开。
func (h *Engine) reap(s *session) {
	code := waitExitCode(s.cmd)
	s.mu.Lock()
	s.exited = true
	s.exitCode = &code
	for sub := range s.subs {
		close(sub.ch)
	}
	s.subs = map[*subscriber]struct{}{}
	s.mu.Unlock()
	_ = s.f.Close()
	close(s.exitedDone)
	h.log.Info("终端会话已退出", "session", s.meta.ID, "pid", s.meta.PID, "exit_code", code)
}

n_engine_Engine_writeInitCommand.signature:
// writeInitCommand 等 shell 就绪后把启动命令写进 PTY 输入。
//
// 参数：s 为已入表的会话；cmd 为命令原文（不含换行，本函数补）。
//
// 就绪判据：**首字节输出 或 initCommandReadyWait 到点，以先到者为准**。
// 前者是真实就绪信号，后者保证「rc 链一直不出声」的 shell 也不会永远等下去。
//
// 注意：
//   - 写入内容恰好是 `cmd + "\n"`，**不加任何前缀标记**（Q4 拍板 (a)：
//     用户要的是「像人亲手敲进去一样」，多一行 handoff 自己的标记既破坏
//     这个错觉，那行文本还会混进滚动历史被 Ctrl-R 搜到）
//   - **命令原文绝不进日志**：启动项的命令可能含凭据（`API_KEY=xxx cmd`
//     是常见写法）。失败只记会话 id 与错误
//   - 会话在这 0~3 秒内被关掉是正常的：Write 会返回「会话不存在/已退出」，
//     按 Debug 记，不是告警
func (h *Engine) writeInitCommand(s *session, cmd string) {
	select {
	case <-s.firstOut:
	case <-time.After(initCommandReadyWait):
		h.log.Debug("等 shell 首字节超时，按兜底路径写入启动命令",
			"session", s.meta.ID, "wait", initCommandReadyWait)
	}
	if err := h.Write(s.meta.ID, []byte(cmd+"\n")); err != nil {

		h.log.Debug("写入启动命令未成功（会话可能已关闭），终端不受影响",
			"session", s.meta.ID, "cause", err)
		return
	}
	h.log.Info("启动命令已写入终端", "session", s.meta.ID, "bytes", len(cmd)+1)
}

n_engine_New.signature:
// New 创建一个 Engine。参数 log 用于记录会话生命周期与错误，不得为 nil。
func New(log *slog.Logger) *Engine {
	return &Engine{log: log, sess: map[string]*session{}}
}

n_engine_engineAttachOps_Detach.signature:
// Detach 退订。**只断连接，不动进程**——这是 spec §3.2 的核心分工：
// 关页面、切设备、组件卸载一律走这里，杀会话只有 Close 一条路。
func (a *engineAttachOps) Detach() {
	s := a.s
	s.mu.Lock()
	if _, ok := s.subs[a.sub]; ok {
		delete(s.subs, a.sub)
		close(a.sub.ch)
	}
	attached := len(s.subs)
	s.mu.Unlock()
	a.h.log.Info("终端会话已断开连接", "session", s.meta.ID, "attached", attached)
}

n_engine_engineAttachOps_ExitCode.signature:
// ExitCode 返回会话的退出码，nil = 还活着。
func (a *engineAttachOps) ExitCode() *int {
	a.s.mu.Lock()
	defer a.s.mu.Unlock()
	return a.s.exitCode
}

n_engine_engineAttachOps_Resize.signature:
// Resize 上报本订阅者的尺寸，并按「所有订阅者取最小」重新协商实际尺寸。
func (a *engineAttachOps) Resize(cols, rows int) error {
	if cols <= 0 || rows <= 0 {
		return nil
	}
	s := a.s
	s.mu.Lock()
	a.sub.cols, a.sub.rows = cols, rows
	minC, minR := 0, 0
	for sub := range s.subs {
		if sub.cols <= 0 || sub.rows <= 0 {
			continue
		}
		if minC == 0 || sub.cols < minC {
			minC = sub.cols
		}
		if minR == 0 || sub.rows < minR {
			minR = sub.rows
		}
	}
	changed := minC > 0 && minR > 0 && (minC != s.meta.Cols || minR != s.meta.Rows)
	if changed {
		s.meta.Cols, s.meta.Rows = minC, minR
	}
	exited := s.exited
	s.mu.Unlock()
	if exited || !changed {
		return nil
	}
	if err := resizePty(s.f, minC, minR); err != nil {
		a.h.log.Error("调整终端尺寸失败", "session", s.meta.ID,
			"size", fmtSize(minC, minR), "err", err)
		return err
	}
	a.h.log.Debug("终端尺寸已协商", "session", s.meta.ID, "size", fmtSize(minC, minR))
	return nil
}

n_engine_fmtSize.signature:
func fmtSize(cols, rows int) string {
	return strconv.Itoa(cols) + "x" + strconv.Itoa(rows)
}

n_engine_foregroundPgid.signature:
// foregroundPgid 读出该 PTY 当前的前台进程组 id。
//
// 参数：ptmx 为主设备端文件
//
// 返回：
//   - pgid: 前台进程组 id
//   - ok: 读到了才为 true。读不到的两种情形都归到 false：shell 已退出
//     （fd 已关）、或本平台不认这个 ioctl
//
// 注意：调用方要的通常不是 pgid 本身，而是「它是否 != shell 自己的 pid」——
// 相等意味着 shell 在等提示符（没有前台命令），不等意味着有个命令正跑在前台。
//
// 「shell 已退出」这一支正是靠 withFd 兜住的：fd 已被 reap 关掉时 Control
// 不会执行回调，直接返回错误，于是走到 false，而不是拿一个悬空的 fd 号去
// ioctl（见 withFd 的注释）。
func foregroundPgid(ptmx *os.File) (int, bool) {
	var pgid int
	err := withFd(ptmx, func(fd uintptr) error {
		var e error
		pgid, e = unix.IoctlGetInt(int(fd), unix.TIOCGPGRP)
		return e
	})
	if err != nil || pgid <= 0 {
		return 0, false
	}
	return pgid, true
}

n_engine_newRing.signature:
func newRing(size int) *ring {
	return &ring{buf: make([]byte, size)}
}

n_engine_resizePty.signature:
// resizePty 调整伪终端尺寸，内核随即向前台进程组发 SIGWINCH。
//
// 这里自己发 TIOCSWINSZ 而不用 pty.Setsize：后者走的是 f.Fd()（creack/pty
// v1.1.24 的 ioctl.go 只用阻塞路径），会话退出时与 reap 的 Close 撞成数据竞争。
func resizePty(f *os.File, cols, rows int) error {
	ws := unix.Winsize{Col: uint16(cols), Row: uint16(rows)}
	return withFd(f, func(fd uintptr) error {
		return unix.IoctlSetWinsize(int(fd), unix.TIOCSWINSZ, &ws)
	})
}

n_engine_ring_since.signature:
// since 回取绝对序号 from 之后的全部字节。
//
// 返回：
//   - data: 实际能给出的字节（新分配的副本，调用方可在锁外持有）
//   - start: data 首字节的绝对序号；调用方据此推进自己的游标
//   - truncated: from 早于环里最旧的字节，中间有一段永久丢失
//
// 注意：from 大于 total 时（客户端报了一个未来的游标，通常是换了会话）按当前
// 尾部处理，返回空而不是报错——重连路径上宁可少画一段，也不能把连接打掉。
func (r *ring) since(from uint64) (data []byte, start uint64, truncated bool) {
	size := uint64(len(r.buf))
	oldest := uint64(0)
	if r.n > size {
		oldest = r.n - size
	}
	if from < oldest {
		from, truncated = oldest, true
	}
	if from > r.n {
		from = r.n
	}
	out := make([]byte, 0, r.n-from)
	for i := from; i < r.n; i++ {
		out = append(out, r.buf[i%size])
	}
	return out, from, truncated
}

n_engine_ring_write.signature:
// write 把 p 追加进环。p 超过环容量时只保留末尾 len(buf) 个字节，
// 但 n 仍按 len(p) 累加——n 是「输出了多少」，不是「留下了多少」。
func (r *ring) write(p []byte) {
	size := len(r.buf)
	if size == 0 {
		r.n += uint64(len(p))
		return
	}

	if len(p) > size {
		r.n += uint64(len(p) - size)
		p = p[len(p)-size:]
	}
	off := int(r.n % uint64(size))
	c := copy(r.buf[off:], p)
	if c < len(p) {
		copy(r.buf, p[c:])
	}
	r.n += uint64(len(p))
}

n_engine_session_broadcast.signature:
func (s *session) broadcast(p []byte) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.buf.write(p)
	for sub := range s.subs {
		cp := make([]byte, len(p))
		copy(cp, p)
		select {
		case sub.ch <- cp:
		default:

			close(sub.ch)
			delete(s.subs, sub)
		}
	}
}

n_engine_signalGroup.signature:
func signalGroup(cmd *exec.Cmd, sig syscall.Signal) error {
	if cmd == nil || cmd.Process == nil {
		return nil
	}
	err := syscall.Kill(-cmd.Process.Pid, sig)
	if err != nil && errors.Is(err, syscall.ESRCH) {
		return nil
	}
	return err
}

n_engine_startPty.signature:
// startPty 在新伪终端里启动一个 login shell。
//
// 参数：
//   - shell: shell 的绝对路径；cwd: 工作目录；env: 完整环境（不追加 os.Environ）
//   - cols/rows: 初始尺寸
//
// 返回：PTY 主端 fd、已启动的 cmd、错误。
//
// 注意：
//   - 用 `-l` 起 login shell，rc 链照读——用户要的是「和我在 iTerm 里一样」
//   - pty.StartWithSize 内部设置了 Setsid+Setctty，因此 shell 的 pid 即 pgid，
//     terminatePty 才能用 -pid 打整个进程组
//   - env 是**完整替换**：调用方必须自己把要继承的变量拼进来（见 envforward.go）
func startPty(shell, cwd string, env []string, cols, rows int) (*os.File, *exec.Cmd, error) {
	cmd := exec.Command(shell, "-l")
	cmd.Dir = cwd
	cmd.Env = env
	f, err := pty.StartWithSize(cmd, &pty.Winsize{Cols: uint16(cols), Rows: uint16(rows)})
	if err != nil {
		return nil, nil, err
	}
	return f, cmd, nil
}

n_engine_terminatePty.signature:
// terminatePty 向整个进程组发 SIGTERM。
//
// 为什么是 -pid 而不是 pid：用户在终端里起的 `npm run dev`、`sleep 300 &` 都是
// shell 的子进程，只杀 shell 会留下一堆孤儿。startPty 用 Setsid 保证了 pid==pgid。
//
// 进程已经不在时（ESRCH）视为成功——它本来就是我们想要的终局。
func terminatePty(cmd *exec.Cmd) error	{ return signalGroup(cmd, syscall.SIGTERM) }

n_engine_waitExitCode.signature:
// waitExitCode 阻塞等待 shell 退出并换算退出码。
//
// 被信号杀掉时返回 128+signo（SIGKILL → 137），这是 shell 的通行约定，
// 前端直接展示这个数字；返回 -1 会让用户看到一个没有含义的负数。
func waitExitCode(cmd *exec.Cmd) int {
	err := cmd.Wait()
	if err == nil {
		return 0
	}
	var ee *exec.ExitError
	if errors.As(err, &ee) {
		if ws, ok := ee.Sys().(syscall.WaitStatus); ok && ws.Signaled() {
			return 128 + int(ws.Signal())
		}
		return ee.ExitCode()
	}
	return -1
}

n_engine_withFd.signature:
// withFd 在持有 *os.File 引用计数的前提下，把裸 fd 交给 fn 做 ioctl。
//
// 参数：f 为目标文件；fn 收到的 fd 只在回调期间有效，**不得**存下来事后再用。
//
// 返回：fn 自身的错误；文件已关闭（或取不到 SyscallConn）时返回该失败本身。
//
// 为什么不能直接用 f.Fd()：Fd() 不加引用计数地读出 fd 号，与并发的 f.Close()
// 构成数据竞争——而 ptyhost.reap 在 shell 退出的那一刻正是这么关主端的，
// 于是「取快照」「调尺寸」与「会话自然退出」一撞就中。真实危害比竞争本身更
// 隐蔽：拿到的 fd 号可能在 ioctl 发出前已被内核回收并重新分配给别的文件，
// ioctl 就打到了不相干的 fd 上。SyscallConn().Control 会先 incref，文件已关闭
// 时直接返回错误而不执行 fn，正好对上本包「读不到就当读不到」的语义。
func withFd(f *os.File, fn func(fd uintptr) error) error {
	rc, err := f.SyscallConn()
	if err != nil {
		return err
	}
	var inner error
	if err := rc.Control(func(fd uintptr) { inner = fn(fd) }); err != nil {
		return err
	}
	return inner
}

n_envfile_Dir.signature:
// Dir 返回 env 文件目录（<dataDir>/env）。
//
// 目录布局知识只此一处：manager 与 agentd 各自构造 Resolver，若各拼各的路径，
// 日后改布局必然漏改一处。
func Dir(dataDir string) string	{ return filepath.Join(dataDir, "env") }

n_envfile_List.signature:
// List 列举 env 目录下的全部普通文件，按名字升序。
//
// 参数：
//   - dir: env 目录，通常取 Dir(cfg.DataDir)
//
// 返回：
//   - 文件列表（含大小与哈希）；目录不存在时返回空切片与 nil
//
// 注意：
//   - **目录不存在不是错误**：<DataDir>/env 没有任何东西自动创建，首次打开
//     设置页时它本来就不存在，报错会把「还没建」画成「读不了」
//   - 子目录与非普通文件跳过：env 文件只有一层，不递归
func List(dir string) ([]FileInfo, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		if os.IsNotExist(err) {
			return []FileInfo{}, nil
		}
		return nil, fmt.Errorf("读取 env 目录 %s: %w", dir, err)
	}
	out := make([]FileInfo, 0, len(entries))
	for _, e := range entries {
		if e.IsDir() || !e.Type().IsRegular() {
			continue
		}
		data, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, fmt.Errorf("读取 env 文件 %s: %w", e.Name(), err)
		}
		out = append(out, FileInfo{Name: e.Name(), Size: int64(len(data)), SHA256: hashOf(data)})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

n_envfile_LoadFile.signature:
// LoadFile 按**文件名**加载一份 env 文件，返回可注入的 KEY=VALUE 列表。
//
// 参数：
//   - dir: env 文件目录（通常取 Dir(cfg.DataDir)）
//   - name: 纯文件名，含路径分隔符即拒
//   - log: 日志入口；nil 时退回 slog.Default()
//
// 返回：
//   - 变量列表；文件名非法 / 打不开 / 解析失败时返回错误，错误文本带完整路径
//   - **不把「文件不存在」特殊化成 (nil,nil)**：调用方明确点名了一份文件，
//     它不在就是一个要说出来的失败。「没配」那一档由调用方判断（见 For）
//
// 注意：
//   - 每次调用都重新读盘，不缓存（理由见 For）
//   - 展开用 os.LookupEnv：同一份文件在「作为 executor env」与「作为终端 env」
//     时必须展开出相同的值，所以查的是 agentd 自身环境，不查调用方拼好的环境
//   - **日志只打 key 名，绝不打值**：环境类变量里 HTTPS_PROXY=http://user:pass@host
//     是正常写法，值里带凭据的概率不低。这条纪律是本函数存在的主要理由——
//     调用方各写各的三行加载，第二个实现漏掉它时不报错、不变红，只是日志里
//     多了一行带 token 的字符串
func LoadFile(dir, name string, log *slog.Logger) ([]string, error) {
	if log == nil {
		log = slog.Default()
	}
	path, err := resolvePath(dir, name)
	if err != nil {
		log.Error("env 文件名非法", "name", name, "cause", err)
		return nil, err
	}
	f, err := os.Open(path)
	if err != nil {
		log.Error("打开 env 文件失败", "path", path, "cause", err)
		return nil, fmt.Errorf("打开 env 文件 %s: %w", path, err)
	}
	defer f.Close()

	kvs, dups, err := Parse(f, os.LookupEnv)
	if err != nil {
		log.Error("解析 env 文件失败", "path", path, "cause", err)
		return nil, fmt.Errorf("解析 env 文件 %s: %w", path, err)
	}
	for _, k := range dups {
		log.Warn("env 文件存在重复键，后者覆盖前者", "path", path, "key", k)
	}
	out := make([]string, 0, len(kvs))
	keys := make([]string, 0, len(kvs))
	for _, kv := range kvs {
		out = append(out, kv.Key+"="+kv.Value)
		keys = append(keys, kv.Key)
	}
	log.Info("已加载 env 文件", "path", path, "keys", keys, "count", len(keys))
	return out, nil
}

n_envfile_NewResolver.signature:
// NewResolver 构造 Resolver。
//
// 参数：
//   - dir: env 文件目录，通常取 Dir(cfg.DataDir)
//   - mapping: 取当前映射的函数（生产上指向 agentd 的活配置）；nil 视为空映射，
//     此时所有 agent 都不注入
//   - log: 日志入口；nil 时退回 slog.Default()
//
// 注意：mapping 会在每次 For 时被调用，实现方必须是廉价且并发安全的
// （Server.EnvMapping 读的是 atomic 快照，满足这两条）。
func NewResolver(dir string, mapping func() map[string]string, log *slog.Logger) *Resolver {
	if log == nil {
		log = slog.Default()
	}
	if mapping == nil {
		log.Warn("env 映射取值函数为空，所有 agent 都不会注入环境变量", "dir", dir)
		mapping = func() map[string]string { return nil }
	}
	return &Resolver{dir: dir, mapping: mapping, log: log}
}

n_envfile_Parse.signature:
// Parse 解析 env 文件内容。
//
// 参数：
//   - r: 文件内容
//   - lookup: 展开时的外部变量查找（生产传 os.LookupEnv）；nil 表示外部无变量
//
// 返回：
//   - kvs: 按首次出现顺序排列的键值对（重复键后者覆盖前者的值，位置保持在首次出现处）
//   - dups: 出现过重复定义的键名，供调用方打 WARN（本函数是纯函数，不打日志）
//   - err: 语法错误（带行号与原行）或超出大小上限
//
// 语法（完整规则见 spec §3）：
//   - 行尾 \r 先剥离（兼容 CRLF）；trim 后的空行与 # 开头行跳过
//   - 可选 `export ` 前缀；第一个 = 分割；key 须匹配 keyRe
//   - 值 trim 后：'...' 字面量不展开，"..." 与无引号都展开
//
// 为什么不支持行内注释：`HTTPS_PROXY=http://host/a#b` 里 # 是合法字符，支持行内
// 注释会把这类值静默吃掉半截——症状是「代理配了但连不上」，离根因隔了十万八千里。
//
// 为什么展开时文件内的键优先于外部环境：让文件自洽，读文件的人不必脑补外部环境
// 是什么。查不到的变量展开为空串（os.Expand 的默认行为）。
func Parse(r io.Reader, lookup func(string) (string, bool)) (kvs []KV, dups []string, err error) {

	b, err := io.ReadAll(io.LimitReader(r, maxEnvFileSize+1))
	if err != nil {
		return nil, nil, fmt.Errorf("读取 env 内容: %w", err)
	}
	if len(b) > maxEnvFileSize {
		return nil, nil, fmt.Errorf("env 文件超过大小上限 %d 字节（64KiB）", maxEnvFileSize)
	}

	idx := map[string]int{}
	vals := map[string]string{}

	expand := func(s string) string {
		return os.Expand(s, func(name string) string {
			if v, ok := vals[name]; ok {
				return v
			}
			if lookup != nil {
				if v, ok := lookup(name); ok {
					return v
				}
			}
			return ""
		})
	}

	for i, raw := range strings.Split(string(b), "\n") {
		lineNo := i + 1
		line := strings.TrimSpace(strings.TrimSuffix(raw, "\r"))
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if rest, ok := strings.CutPrefix(line, "export"); ok &&
			rest != "" && (rest[0] == ' ' || rest[0] == '\t') {
			line = strings.TrimSpace(rest)
		}
		key, val, ok := strings.Cut(line, "=")
		if !ok {
			return nil, nil, fmt.Errorf("env 第 %d 行缺少 '='：%q", lineNo, line)
		}
		key = strings.TrimSpace(key)
		if !keyRe.MatchString(key) {
			return nil, nil, fmt.Errorf("env 第 %d 行键名非法 %q（须匹配 [A-Za-z_][A-Za-z0-9_]*）", lineNo, key)
		}
		val = strings.TrimSpace(val)
		switch {
		case len(val) >= 2 && strings.HasPrefix(val, "'") && strings.HasSuffix(val, "'"):
			val = val[1 : len(val)-1]
		case len(val) >= 2 && strings.HasPrefix(val, `"`) && strings.HasSuffix(val, `"`):
			val = expand(val[1 : len(val)-1])
		default:
			val = expand(val)
		}
		if i, dup := idx[key]; dup {
			kvs[i].Value = val
			vals[key] = val
			dups = append(dups, key)
			continue
		}
		idx[key] = len(kvs)
		vals[key] = val
		kvs = append(kvs, KV{Key: key, Value: val})
	}
	return kvs, dups, nil
}

n_envfile_Read.signature:
// Read 读一个 env 文件的正文。
//
// 返回：
//   - 正文、sha256、字节数；文件不存在时错误可用 errors.Is(err, fs.ErrNotExist) 判定
//
// 注意：返回的正文**含值**。调用方只应在用户显式要求「编辑正文」时把它交出去；
// 默认视图走 Parse + 丢值的路径（见 agentd 的 keys 端点）。
func Read(dir, name string) (content, sha string, size int64, err error) {
	path, err := resolvePath(dir, name)
	if err != nil {
		return "", "", 0, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "", "", 0, fmt.Errorf("读取 env 文件 %s: %w", path, err)
	}
	return string(data), hashOf(data), int64(len(data)), nil
}

n_envfile_Resolver_For.signature:
// For 返回该 agent 启动时应注入的环境变量（KEY=VALUE 形式）。
//
// 参数：
//   - agent: executor 名（如 opencode）
//
// 返回：
//   - 该 agent 未配置 env 文件时返回 (nil, nil)——不是错误，是「没配」
//   - 文件名非法 / 打不开 / 解析失败时返回错误，错误文本带完整路径与行号
//
// 注意：
//   - 每次调用都重新读盘，不缓存。改了代理下一个任务就生效，不必重启 agentd
//     （重启会打断正在跑的任务的事件订阅，代价不小）；读一个几百字节的文件
//     相对于拉起一个 agent 的开销可以忽略
//   - 日志只打 key 名，绝不打值：环境类变量里 HTTPS_PROXY=http://user:pass@host
//     是正常写法，值里带凭据的概率不低
func (r *Resolver) For(agent string) ([]string, error) {
	name := strings.TrimSpace(r.mapping()[agent])
	if name == "" {
		r.log.Debug("agent 未配置 env 文件，跳过注入", "agent", agent)
		return nil, nil
	}
	return LoadFile(r.dir, name, r.log)
}

n_envfile_Resolver_Preflight.signature:
// Preflight 读一遍所有被引用的 env 文件，把问题以 WARN 暴露在启动日志里。
//
// 为什么只 WARN 不阻断启动：env 文件是数据文件不是配置键，可能在 agentd 启动后
// 才创建，为它拒绝启动太硬；但完全不检查会把问题拖到第一次派发才暴露——WARN 让它
// 在启动日志里就可见，真正的拒发发生在 Dispatch（见 spec §6）。
func (r *Resolver) Preflight() {
	for agent := range r.mapping() {
		if _, err := r.For(agent); err != nil {
			r.log.Warn("env 文件预检失败（不阻断启动，派发时会拒发）", "agent", agent, "cause", err)
		}
	}
}

n_envfile_Static.signature:
// Static 把一份固定映射包成取值函数，供测试与不需要热更新的调用方使用。
func Static(m map[string]string) func() map[string]string {
	return func() map[string]string { return m }
}

n_envfile_Write.signature:
// Write 写一个 env 文件，带前置哈希保护。
//
// 参数：
//   - baseSHA: 空串 = 新建（目标必须不存在）；非空 = 覆盖（须与磁盘现状一致）
//
// 返回：
//   - 新内容的 sha256 与字节数；调用方可直接拿 sha 当下一次写入的 base
//   - 冲突时返回**磁盘现状的哈希** + ErrBaseMismatch，供 409 响应体带上现状
//
// 注意：
//   - **本函数不做语法校验**。调用方须在此之前跑 Parse——先校验再落盘，
//     写坏的文件不该进磁盘（写进去了才发现，症状会拖到下一次派发）
//   - 目录不存在时以 0700 创建；文件 0600——env 里带凭据是常态，权限基线
//     不能松于 DataDir 下其余内容
func Write(dir, name, content, baseSHA string) (sha string, size int64, err error) {
	path, err := resolvePath(dir, name)
	if err != nil {
		return "", 0, err
	}
	if len(content) > MaxFileSize {
		return "", 0, fmt.Errorf("%w: %s 有 %d 字节，上限 %d", ErrTooLarge, name, len(content), MaxFileSize)
	}
	cur, statErr := os.ReadFile(path)
	switch {
	case statErr == nil && baseSHA == "":

		return hashOf(cur), int64(len(cur)), fmt.Errorf("%w: %s", ErrExists, name)
	case statErr == nil && hashOf(cur) != baseSHA:
		return hashOf(cur), int64(len(cur)), fmt.Errorf("%w: %s", ErrBaseMismatch, name)
	case statErr != nil && !os.IsNotExist(statErr):
		return "", 0, fmt.Errorf("读取 env 文件 %s: %w", path, statErr)
	case statErr != nil && baseSHA != "":

		return "", 0, fmt.Errorf("读取 env 文件 %s: %w", path, statErr)
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", 0, fmt.Errorf("创建 env 目录 %s: %w", dir, err)
	}
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		return "", 0, fmt.Errorf("写入 env 文件 %s: %w", path, err)
	}
	return hashOf(content), int64(len(content)), nil
}

n_envfile_hashOf.signature:
// hashOf 返回内容的 sha256 十六进制串（写入与列举共用，保证两处口径一致）。
func hashOf[T string | []byte](data T) string {
	sum := sha256.Sum256([]byte(data))
	return hex.EncodeToString(sum[:])
}

n_envfile_resolvePath.signature:
// resolvePath 把配置里的文件名换算为绝对路径，并拒绝一切非「纯文件名」的写法。
//
// 为什么只收纯文件名：一杜绝路径穿越（../../etc 之类），二保证 env 文件只有
// 一个家、不会散落各处——运维找配置时只需要看一个目录。
func resolvePath(dir, name string) (string, error) {
	if strings.ContainsRune(name, filepath.Separator) || strings.ContainsRune(name, '/') {
		return "", fmt.Errorf("%w: %q 不能含路径分隔符：只支持 %s 下的纯文件名", ErrBadName, name, dir)
	}
	if name == "" || name == "." || name == ".." {
		return "", fmt.Errorf("%w: %q：只支持 %s 下的纯文件名", ErrBadName, name, dir)
	}
	return filepath.Join(dir, name), nil
}

n_executor_AllCapabilityNames.signature:
// AllCapabilityNames 返回五类能力名，固定顺序。
func AllCapabilityNames() []CapabilityName {
	return []CapabilityName{CapExecution, CapCoordination, CapOneShot, CapProfile, CapSkills}
}

n_executor_Authorize.signature:
// Authorize 向 client 请求一次授权。Request 返回 pending 时 Await 直到终态。
//
// 参数：client 必须非 nil；req 为原生权限。
// 返回：终态 allow/deny；ctx 取消时返回错误，不泄漏 waiter。
func Authorize(ctx context.Context, client ApprovalClient, req ApprovalRequest) (ApprovalDecision, error) {
	if client == nil {
		return ApprovalDecision{}, fmt.Errorf("ApprovalClient 为空，不能当成免审")
	}
	res, err := client.Request(ctx, req)
	if err != nil {
		return ApprovalDecision{}, err
	}
	if res.Decision.Status == ApprovalPending {
		return client.Await(ctx, res.Ref)
	}
	if res.Decision.Status == ApprovalAllow || res.Decision.Status == ApprovalDeny {
		return res.Decision, nil
	}
	return ApprovalDecision{}, fmt.Errorf("审批 client 返回非法状态 %q", res.Decision.Status)
}

n_executor_BaselineReport.signature:
// BaselineReport 返回本卡冻结的支持矩阵。未知名字返回 ErrUnknownHarness。
func BaselineReport(harness string) (CapabilityReport, error) {
	switch harness {
	case HarnessOpenCode:
		return reportAll(HarnessOpenCode, true, nil), nil
	case HarnessClaude, HarnessGrok, HarnessAGY:
		return reportAll(harness, false, nil), nil
	case HarnessCodex:
		return reportAll(HarnessCodex, false, []string{
			NativeLimitSandboxReadOnly,
			NativeLimitInvokeExec,
			NativeLimitEphemeral,
			NativeLimitSkipGitRepoCheck,
			NativeLimitColorNever,
			NativeLimitIgnoreUserConfig,
		}), nil
	default:
		return CapabilityReport{}, fmt.Errorf("%w %q（支持 opencode/claude/grok/agy/codex）",
			ErrUnknownHarness, harness)
	}
}

n_executor_GuardRemove.signature:
// GuardRemove 执法 Remove 必须明确授权。实现节点在写盘之前调用。
