n_executor_NewRegistry.signature:
// NewRegistry 登记一组提供方。后写入覆盖同名先写入。
func NewRegistry(ps ...Provider) *Registry {
	r := &Registry{byName: make(map[string]Provider, len(ps))}
	for _, p := range ps {
		if p == nil {
			continue
		}
		r.byName[p.Name()] = p
	}
	return r
}

n_executor_NormalizePermTool.signature:
// NormalizePermTool 把 executor 的原始工具名折算为归一化名。
//
// 参数：raw 为 executor 侧的原始工具名，允许带空白、大小写任意
// 返回：PermTool* 之一；未识别时返回 PermToolOther
//
// 注意：本表只收本项目**实测见过**的名字。新增 executor 时先取真实样本再
// 补表，不要按想象加别名——猜错的代价是判据静默走错路由。
func NormalizePermTool(raw string) string {
	switch strings.ToLower(strings.TrimSpace(raw)) {
	case "bash":
		return PermToolBash
	case "write":
		return PermToolWrite
	case "edit":
		return PermToolEdit
	case "webfetch":
		return PermToolWebFetch
	default:
		return PermToolOther
	}
}

n_executor_PermFingerprint.signature:
// PermFingerprint 计算一次权限请求的裁决指纹。
//
// 域规则（B91，本卡升为执行契约编码）：
//   - Perm.Command 非空 → 命令域：sha256("cmd\x00" + command)
//   - Command 为空但 Paths 非空 → 路径域：sha256("paths\x00" + Tool + "\x00" + 排序后 Paths)
//   - 其余（Perm 为 nil，或提取不出结构）→ 全文域：sha256(Text)
func PermFingerprint(ev AdapterEvent) string {
	if ev.Perm != nil {
		if ev.Perm.Command != "" {
			return permFingerprintHash("cmd\x00" + ev.Perm.Command)
		}
		if len(ev.Perm.Paths) > 0 {
			paths := append([]string(nil), ev.Perm.Paths...)
			sort.Strings(paths)
			return permFingerprintHash("paths\x00" + ev.Perm.Tool + "\x00" + strings.Join(paths, "\x00"))
		}
	}
	return permFingerprintHash(ev.Text)
}

n_executor_ProfileFromProvider.signature:
// ProfileFromProvider returns the Profile capability exposed by a provider bundle.
//
// Production adapters expose Profile through the bundle accessor because Skills
// already owns the method name Inspect with a different request type. Keeping
// this resolution beside the capability contract prevents orchestration code
// from growing a second capability lookup rule.
func ProfileFromProvider(p Provider) (Profile, bool) {
	if p == nil {
		return nil, false
	}
	if profile, ok := p.(Profile); ok {
		return profile, true
	}
	accessor, ok := p.(interface{ Profile() Profile })
	if !ok {
		return nil, false
	}
	profile := accessor.Profile()
	return profile, profile != nil
}

n_executor_Registry_Get.signature:
// Get 按登记名取提供方。未知名字返回 ErrUnknownHarness。
