		Caps: []CapabilityDecl{
			{Name: CapExecution, Supported: true},
			{Name: CapCoordination, Supported: coordination},
			{Name: CapOneShot, Supported: true, NativeLimits: oneshotLimits},
			{Name: CapProfile, Supported: true},
			{Name: CapSkills, Supported: true},
		},
	}
}

n_fake_Fake_Add.signature:
// Add 为任务追加脚本步骤。
//
// 注意：
//   - 追加后步骤要等「续接门禁」放行才会执行：脚本耗尽后（任务已进 waiting_review），
//     runner 阻塞在 Send 上，协调者的 continue 指令（Send）到达才解锁后续步骤——
//     这保证「executor 先收到指令、再继续产出事件」的顺序，测试据此确定性断言
func (f *Fake) Add(taskID string, steps ...Step) {
	r := f.runner(taskID)
	f.mu.Lock()
	r.steps = append(r.steps, steps...)
	f.mu.Unlock()
	f.log().Debug("fake 追加脚本步骤", "task", taskID, "n", len(steps))
}

n_fake_Fake_Events.signature:
// Events 返回任务的事件流通道；任务未启动时返回**已关闭**通道。
//
// 契约（与 opencode adapter 一致，P1-11）：通道关闭 = 执行终结，消费方
// （manager 中介循环）靠 range 在关闭时立即退出。未启动任务若返回惰性新建的
// 打开通道，range 会永久阻塞——对未知任务等价于旧的 nil 通道。已启动任务的
// 通道由 run 循环在 Stop/退出时关闭（defer close(evCh)）。
func (f *Fake) Events(taskID string) <-chan executor.AdapterEvent {
	f.mu.Lock()
	r, ok := f.runs[taskID]

	started := ok && r.started
	f.mu.Unlock()
	if !started {
		ch := make(chan executor.AdapterEvent)
		close(ch)
		return ch
	}
	return r.evCh
}

n_fake_Fake_LastDecision.signature:
// LastDecision 返回最后一次 RespondPermission 收到的 decision；未收到任何应答
// 时返回空串（测试探查用，如断言审批者自动批准路径 executor 收到 once）。
func (f *Fake) LastDecision() string {
	f.mu.Lock()
	defer f.mu.Unlock()
	if n := len(f.perms); n > 0 {
		return f.perms[n-1].Decision
	}
	return ""
}

n_fake_Fake_PermID.signature:
// PermID 返回本 fake 发出的第一个权限请求的 PermissionID（测试探查用）。
//
// 为什么只需「第一个」：单任务测试里权限请求从 perm-1 递增，首个即对应
// 任务的第一个权限工单 id（taskID:perm-1）。
func (f *Fake) PermID() string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.firstPermID
}

n_fake_Fake_Perms.signature:
// Perms 返回全部 RespondPermission 调用实参（按调用顺序）。
func (f *Fake) Perms() []PermCall {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]PermCall(nil), f.perms...)
}

n_fake_Fake_Report.signature:
func (f *Fake) Report() executor.CapabilityReport {
	return executor.CapabilityReport{
		Harness:	"fake",
		Caps: []executor.CapabilityDecl{
			{Name: executor.CapExecution, Supported: true},
			{Name: executor.CapCoordination, Supported: false},
			{Name: executor.CapOneShot, Supported: false},
			{Name: executor.CapProfile, Supported: false},
			{Name: executor.CapSkills, Supported: false},
		},
	}
}

n_fake_Fake_RespondPermission.signature:
// RespondPermission 记录实参并解除对应任务的 Permission 步骤阻塞。
func (f *Fake) RespondPermission(_ context.Context, taskID, permID, decision, reason string) error {
	f.mu.Lock()
	err := f.permErr
	f.mu.Unlock()
	if err != nil {
		f.log().Debug("fake 注入 RespondPermission 错误", "task", taskID, "perm", permID, "reason", reason, "cause", err)
		return err
	}
	r := f.runner(taskID)
	f.log().Debug("fake 收到 RespondPermission", "task", taskID, "perm", permID, "decision", decision, "reason", reason)
	f.mu.Lock()
	f.perms = append(f.perms, PermCall{TaskID: taskID, PermID: permID, Decision: decision, Reason: reason})
	f.mu.Unlock()
	select {
	case r.permCh <- PermCall{TaskID: taskID, PermID: permID, Decision: decision, Reason: reason}:
	default:
	}
	return nil
}

n_fake_Fake_Send.signature:
// Send 记录实参；若恰有 Question 步骤在阻塞则解除其阻塞，否则作为「续接指令」记录，
// 运行循环继续等待后续步骤（模拟 executor 收到修改指令后继续干活）。
func (f *Fake) Send(_ context.Context, taskID, text string) error {
	f.mu.Lock()
	err := f.sendErr
	f.mu.Unlock()
	if err != nil {
		f.log().Debug("fake 注入 Send 错误", "task", taskID, "cause", err)
		return err
	}
	r := f.runner(taskID)
	f.log().Debug("fake 收到 Send", "task", taskID, "text", truncateRunes(text, 80))
	f.mu.Lock()
	f.sends = append(f.sends, SendCall{TaskID: taskID, Text: text})
	f.mu.Unlock()
	select {
	case r.sendCh <- text:
	default:
	}
	return nil
}

n_fake_Fake_Sends.signature:
// Sends 返回全部 Send 调用实参（按调用顺序）。
func (f *Fake) Sends() []SendCall {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]SendCall(nil), f.sends...)
}

n_fake_Fake_SetPermError.signature:
// SetPermError 注入 RespondPermission 的错误返回值（默认 nil 不注入）。
//
// 用途：同 SetSendError，面向权限应答中继的失败场景。
func (f *Fake) SetPermError(err error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.permErr = err
}

n_fake_Fake_SetSendError.signature:
// SetSendError 注入 Send 的错误返回值（默认 nil 不注入）。
//
// 用途：构造「executor 侧递送失败」的测试场景——如模拟 adapter 无该任务运行态
// （opencode adapter 的「任务不在运行中」错误），用于 reply 中继失败路径的断言。
func (f *Fake) SetSendError(err error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.sendErr = err
}

n_fake_Fake_Stop.signature:
// Stop 记录并终止任务的脚本循环，事件通道随即关闭。
//
// 注意：
//   - 幂等：重复 Stop 不 panic，事件通道只关闭一次
func (f *Fake) Stop(taskID string) error {
	r := f.runner(taskID)
	f.log().Debug("fake 收到 Stop", "task", taskID)
	f.mu.Lock()
	f.stops = append(f.stops, taskID)
	f.mu.Unlock()
	r.stopOnce.Do(func() { close(r.stopCh) })
	return nil
}

n_fake_Fake_Stops.signature:
// Stops 返回已收到 Stop 的任务 ID 列表。
func (f *Fake) Stops() []string {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]string(nil), f.stops...)
}

n_fake_Fake_runner.signature:
// runner 返回任务运行态，不存在时惰性创建。
func (f *Fake) runner(taskID string) *taskRun {
	f.mu.Lock()
	defer f.mu.Unlock()
	r, ok := f.runs[taskID]
	if !ok {
		r = &taskRun{
			taskID:	taskID,
			evCh:	make(chan executor.AdapterEvent, 16),
			sendCh:	make(chan string, 1),
			permCh:	make(chan PermCall, 1),
			stopCh:	make(chan struct{}),
		}
		f.runs[taskID] = r
	}
	return r
}

n_fake_New.signature:
// New 创建脚本化 fake adapter。
//
// 参数：
//   - script: 初始步骤队列；运行中可用 Add 追加（典型为测试在续接前注入下一步）
func New(script []Step) *Fake {
	return &Fake{
		script:	append([]Step(nil), script...),
		runs:	make(map[string]*taskRun),
	}
}

n_fake_permRequestFromText.signature:
// permRequestFromText 从权限描述文本派生出结构化载荷（测试替身专用）。
//
// 真实 adapter（claude/grok/opencode）从各自的协议载荷提取结构；fake 没有
// 协议，只能从描述文本推导，供审批链集成测试把请求路由进 Consult 出口——
// 不带 Perm 的事件会被 manager 按 fail-closed 升级人工，审批链集成就测不到了。
//
// 规则与真实 adapter 的展示文本同构：带 "Bash: " 前缀取命令，带 "Write: " /
// "Edit: " 前缀取路径，其余按未识别工具退回判 Text。
func permRequestFromText(text string) *executor.PermRequest {
	switch {
	case strings.HasPrefix(text, "Bash: "):
		return &executor.PermRequest{Tool: executor.PermToolBash, Command: text[len("Bash: "):]}
	case strings.HasPrefix(text, "Write: "):
		return &executor.PermRequest{Tool: executor.PermToolWrite, Paths: []string{text[len("Write: "):]}}
	case strings.HasPrefix(text, "Edit: "):
		return &executor.PermRequest{Tool: executor.PermToolEdit, Paths: []string{text[len("Edit: "):]}}
	default:
		return &executor.PermRequest{Tool: executor.PermToolOther}
	}
}

n_fake_taskRun_emit.signature:
// emit 向事件通道投递事件；阻塞直至 manager 消费或 Stop。
//
// 为什么阻塞而非丢事件：测试全链路依赖每条事件都被 manager 中介处理，
// 丢事件会让流程静默卡死，阻塞投递把问题暴露为超时而不是虚假通过。
func (r *taskRun) emit(f *Fake, ev executor.AdapterEvent) bool {
	select {
	case r.evCh <- ev:
		return true
	case <-r.stopCh:
		return false
	}
}

n_fake_taskRun_nextPermID.signature:
// nextPermID 为任务内第 n 个权限请求生成稳定的 PermissionID（perm-<n>）。
//
// 稳定性即幂等性：同一次权限请求重放时复用同一 id，manager 的 CreateTicket 按
// id 幂等去重（见 executor.go 包级幂等约定）。
func (r *taskRun) nextPermID() string {
	f := fmt.Sprintf("perm-%d", r.permSeq+1)
	r.permSeq++
	return f
}

n_fake_taskRun_nextStep.signature:
// nextStep 取出下一个待执行步骤；脚本为空时阻塞等待 Send（续接门禁）/ Stop。
//
// 续接门禁的 why：脚本耗尽时任务已进 waiting_review，此时 runner 只被 Send 唤醒——
// 协调者的 continue 指令（Send）到达才解锁新步骤，保证「executor 收到指令后才
// 继续产出事件」的因果顺序（Add 只入队，不唤醒）。
//
// 为什么 Send 在这里只排空不记录：Send 的实参已由 fake.Send 同步记录（断言数据源
// 唯一），这里把 sendCh 里的文本消费掉只是为了让门禁与阻塞语义清晰——若留着不清，
// 下一步 Question 阻塞时会把这条「续接指令」误当成提问答案。
func (r *taskRun) nextStep(f *Fake) (Step, bool) {
	for {
		f.mu.Lock()
		if len(r.steps) > 0 {
			s := r.steps[0]
			r.steps = r.steps[1:]
			f.mu.Unlock()
			return s, true
		}
		f.mu.Unlock()
		select {
		case <-r.sendCh:
		case <-r.stopCh:
			return Step{}, false
		}
	}
}

n_fake_taskRun_run.signature:
// run 是脚本执行主循环：逐步骤执行，阻塞步骤等待对应动作解除。
func (r *taskRun) run(f *Fake) {
	defer close(r.evCh)
	for {
		step, ok := r.nextStep(f)
		if !ok {
			return
		}
		switch {
		case step.Permission != "":
			permID := r.nextPermID()
			f.log().Debug("fake 发 permission 事件", "task", r.taskID, "perm", permID)
			f.mu.Lock()
			if f.firstPermID == "" {
				f.firstPermID = permID
			}
			f.mu.Unlock()
			if !r.emit(f, executor.AdapterEvent{Type: "permission", PermissionID: permID,
				Text:	step.Permission, Perm: permRequestFromText(step.Permission)}) {
				return
			}
			f.log().Debug("fake 等待权限应答", "task", r.taskID, "perm", permID)
			select {
			case p := <-r.permCh:
				f.log().Debug("fake 权限已应答", "task", r.taskID, "perm", p.PermID, "decision", p.Decision)
			case <-r.stopCh:
				return
			}
		case step.Question != "":
			f.log().Debug("fake 发 question 事件", "task", r.taskID)
			if !r.emit(f, executor.AdapterEvent{Type: "question", Text: step.Question}) {
				return
			}
			f.log().Debug("fake 等待 Send", "task", r.taskID)
			select {
			case txt := <-r.sendCh:
				f.log().Debug("fake 提问已应答", "task", r.taskID, "text", truncateRunes(txt, 80))
			case <-r.stopCh:
				return
			}
		default:
			res := step.Finish
			f.log().Debug("fake 发 result 事件", "task", r.taskID, "ok", res.OK)
			if !r.emit(f, executor.AdapterEvent{Type: "result", Result: &res}) {
				return
			}
		}
	}
}

n_fake_truncateRunes.signature:
// truncateRunes 将字符串按 rune 截断为最多 n 个字符（日志防刷屏）。
func truncateRunes(s string, n int) string {
	rs := []rune(s)
	if len(rs) <= n {
		return s
	}
	return string(rs[:n])
}

n_grok_ACPClient_Call.signature:
// Call 发起请求并阻塞等待响应。
func (c *ACPClient) Call(ctx context.Context, method string, params any) (json.RawMessage, error) {
	ch, err := c.CallAsync(method, params)
	if err != nil {
		return nil, err
	}
	select {
	case r := <-ch:
		return r.Result, r.Err
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

n_grok_ACPClient_CallAsync.signature:
// CallAsync 发起请求并立即返回结果通道。
//
// 为什么需要它：session/prompt 要跑完一整个回合（可能几十分钟）才响应，
// Start 必须立即返回，不能阻塞在这上面。
func (c *ACPClient) CallAsync(method string, params any) (<-chan ACPResult, error) {
	c.mu.Lock()
	if c.closed {
		c.mu.Unlock()
		return nil, fmt.Errorf("ACP 连接已关闭")
	}
	c.nextID++
	id := c.nextID
	ch := make(chan ACPResult, 1)
	c.pending[id] = ch
	c.mu.Unlock()

	msg := map[string]any{"jsonrpc": "2.0", "id": id, "method": method}
	if params != nil {
		msg["params"] = params
	}
	if err := c.write(msg); err != nil {
		c.mu.Lock()
		delete(c.pending, id)
		c.mu.Unlock()
		c.log.Error("ACP 请求发送失败", "method", method, "cause", err)
		return nil, err
	}
	c.log.Debug("ACP 请求已发出", "method", method, "id", id)
	return ch, nil
}

n_grok_ACPClient_Close.signature:
// Close 关闭连接，所有挂起的请求以错误终结。
func (c *ACPClient) Close() error {
	c.mu.Lock()
	if c.closed {
		c.mu.Unlock()
		return nil
	}
	c.closed = true
	c.activelyClosed = true
	c.mu.Unlock()
	c.cancel()
	c.log.Info("ACP 连接关闭")
	return c.conn.Close(websocket.StatusNormalClosure, "")
}

n_grok_ACPClient_Notify.signature:
// Notify 发送通知（无需应答，用于 session/cancel）。
func (c *ACPClient) Notify(method string, params any) error {
	msg := map[string]any{"jsonrpc": "2.0", "method": method}
	if params != nil {
		msg["params"] = params
	}
	return c.write(msg)
}

n_grok_ACPClient_Reply.signature:
// Reply 应答对方请求（用于权限裁决回发）。reqID 必须是 OnPermission 收到的原值。
func (c *ACPClient) Reply(reqID json.RawMessage, result any) error {
	if err := c.write(map[string]any{
		"jsonrpc":	"2.0", "id": json.RawMessage(reqID), "result": result,
	}); err != nil {
		c.log.Error("ACP 应答发送失败", "req_id", string(reqID), "cause", err)
		return err
	}
	c.log.Info("ACP 应答已发出", "req_id", string(reqID))
	return nil
}

n_grok_ACPClient_readLoop.signature:
// readLoop 消费连接上的全部消息直到出错，并在退出时终结所有挂起请求。
func (c *ACPClient) readLoop(ctx context.Context, h ACPHandler) {
	var exitErr error
	defer func() {
		c.rawTap.Close()
		c.mu.Lock()
		c.closed = true
		active := c.activelyClosed
		pend := c.pending
		c.pending = map[int]chan ACPResult{}
		c.mu.Unlock()

		for id, ch := range pend {
			c.log.Warn("ACP 连接终止，挂起请求作废", "id", id)
			ch <- ACPResult{Err: fmt.Errorf("ACP 连接终止: %w", exitErr)}
		}
		c.log.Info("ACP 读循环退出", "cause", exitErr)

		if active {
			h.OnClosed(nil)
		} else {
			h.OnClosed(exitErr)
		}
	}()

	for {
		_, data, err := c.conn.Read(ctx)
		if err != nil {
			exitErr = err
			return
		}

		c.rawTap.Write(data)

		var msg struct {
			ID	json.RawMessage	`json:"id"`
			Method	string		`json:"method"`
			Params	json.RawMessage	`json:"params"`
			Result	json.RawMessage	`json:"result"`
			Error	*struct {
				Code	int	`json:"code"`
				Message	string	`json:"message"`
				Data	any	`json:"data"`
			}	`json:"error"`
		}
		if err := json.Unmarshal(data, &msg); err != nil {

			c.log.Warn("ACP 消息解析失败，跳过", "cause", err)
			continue
		}

		switch {
		case msg.Method != "" && len(msg.ID) > 0:

			switch msg.Method {
			case "session/request_permission":
				c.log.Info("ACP 收到权限请求", "req_id", string(msg.ID))
				h.OnPermission(append(json.RawMessage(nil), msg.ID...), msg.Params)
				continue
			case "_x.ai/ask_user_question":
				c.log.Info("ACP 收到提问请求", "req_id", string(msg.ID))
				h.OnAskQuestion(append(json.RawMessage(nil), msg.ID...), msg.Params)
				continue
			}
			c.log.Debug("ACP 未处理的对方请求，回 -32601", "method", msg.Method)
			_ = c.write(map[string]any{"jsonrpc": "2.0", "id": json.RawMessage(msg.ID),
				"error":	map[string]any{"code": -32601, "message": "unhandled"}})
		case msg.Method != "":
			h.OnNotify(msg.Method, msg.Params)
		case len(msg.ID) > 0:
			var id int
			if err := json.Unmarshal(msg.ID, &id); err != nil {
				c.log.Warn("ACP 响应 id 非数字，跳过", "id", string(msg.ID))
				continue
			}
			c.mu.Lock()
			ch, ok := c.pending[id]
			delete(c.pending, id)
			c.mu.Unlock()
			if !ok {
				c.log.Warn("ACP 响应无对应请求，丢弃", "id", id)
				continue
			}
			if msg.Error != nil {
				ch <- ACPResult{Err: fmt.Errorf("ACP 错误 %d: %s", msg.Error.Code, msg.Error.Message)}
				continue
			}
			ch <- ACPResult{Result: msg.Result}
		default:
			c.log.Debug("ACP 无法归类的消息，跳过")
		}
	}
}

n_grok_ACPClient_write.signature:
func (c *ACPClient) write(msg map[string]any) error {
	b, err := json.Marshal(msg)
	if err != nil {
		return fmt.Errorf("序列化 ACP 消息: %w", err)
	}
	c.writeMu.Lock()
	defer c.writeMu.Unlock()
	return c.conn.Write(context.Background(), websocket.MessageText, b)
}

n_grok_Adapter_Events.signature:
// Events 返回该任务的事件流通道（Start 后可用）。通道关闭表示执行终结。
func (a *Adapter) Events(taskID string) <-chan executor.AdapterEvent {
	r := a.lookup(taskID)
	if r == nil {
		return nil
	}
	return r.evCh
}

n_grok_Adapter_Inspect.signature:
func (a *Adapter) Inspect(ctx context.Context, home string) ([]executor.SkillSite, error) {
	name := executor.SkillDirName("")
	site := filepath.Join(home, SkillsRelDir, name)
	target := filepath.Join(site, "SKILL.md")
	parent := filepath.Dir(filepath.Join(home, SkillsRelDir))
	if _, err := os.Stat(parent); errors.Is(err, os.ErrNotExist) {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
			Note:	parent + " 不存在（该 agent 未安装）",
		}}, nil
	}
	if _, err := os.Stat(target); errors.Is(err, os.ErrNotExist) {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
		}}, nil
	} else if err != nil {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
			Note:	"读取失败: " + err.Error(),
		}}, nil
	}
	return []executor.SkillSite{{
		Path:	target,
		State:	executor.SkillInstalled,
	}}, nil
}

n_grok_Adapter_Install.signature:
func (a *Adapter) Install(ctx context.Context, req executor.SkillInstallReq) ([]executor.SkillSite, error) {
	name := executor.SkillDirName(req.Name)
	dir := filepath.Join(req.Home, SkillsRelDir)
	parent := filepath.Dir(dir)
	if _, err := os.Stat(parent); err != nil {
		return []executor.SkillSite{{
			Path:	filepath.Join(dir, name),
			State:	executor.SkillSkipped,
			Note:	parent + " 不存在（该 agent 未安装）",
		}}, nil
	}
	site := filepath.Join(dir, name)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"创建目录失败: " + err.Error(),
		}}, nil
	}
	if err := os.RemoveAll(site); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"清理旧落点失败: " + err.Error(),
		}}, nil
	}
	if err := os.MkdirAll(site, 0o755); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"创建落点目录失败: " + err.Error(),
		}}, nil
	}
	if err := os.WriteFile(filepath.Join(site, "SKILL.md"), []byte(req.Content), 0o644); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"写落点副本失败: " + err.Error(),
		}}, nil
	}
	return []executor.SkillSite{{
		Path:	site,
		State:	executor.SkillInstalled,
	}}, nil
}

n_grok_Adapter_Invoke.signature:
func (a *Adapter) Invoke(ctx context.Context, req executor.OneShotReq) (executor.OneShotReply, error) {
