n_ledger_Store_GetDiscipline.signature:
// GetDiscipline 取指定版本；version = 0 取最新。
func (s *Store) GetDiscipline(name string, version int) (Discipline, error) {
	var zero Discipline
	q := `SELECT name, version, body, created_at FROM disciplines WHERE name = ?`
	args := []any{name}
	if version > 0 {
		q += ` AND version = ?`
		args = append(args, version)
	}
	q += ` ORDER BY version DESC LIMIT 1`
	var d Discipline
	var ct any
	err := s.db.QueryRow(s.q(q), args...).Scan(&d.Name, &d.Version, &d.Body, &ct)
	if errors.Is(err, sql.ErrNoRows) {
		return zero, fmt.Errorf("纪律块 %s v%d: %w", name, version, ErrNotFound)
	}
	if err != nil {
		return zero, fmt.Errorf("读纪律块: %w", err)
	}
	d.CreatedAt = toTime(ct)
	return d, nil
}

n_ledger_Store_GetSession.signature:
// GetSession 读单会话；不存在返回 ErrNotFound。
func (s *Store) GetSession(id string) (Session, error) {
	session, err := scanSession(s.db.QueryRow(s.q(sessionSelect+` WHERE id = ?`), id))
	if errors.Is(err, sql.ErrNoRows) {
		return Session{}, fmt.Errorf("会话 %s: %w", id, ErrNotFound)
	}
	if err != nil {
		return Session{}, err
	}
	if err := s.attachSessionCards(s.db, &session); err != nil {
		return Session{}, err
	}
	return session, nil
}

n_ledger_Store_GetTemplate.signature:
// GetTemplate 取指定版本；0 = 最新。
func (s *Store) GetTemplate(name string, version int) (Template, error) {
	q := `SELECT name, version, definition, created_at FROM dispatch_templates WHERE name = ?`
	args := []any{name}
	if version > 0 {
		q += ` AND version = ?`
		args = append(args, version)
	}
	q += ` ORDER BY version DESC LIMIT 1`
	var t Template
	var raw string
	var ct any
	err := s.db.QueryRow(s.q(q), args...).Scan(&t.Name, &t.Version, &raw, &ct)
	if errors.Is(err, sql.ErrNoRows) {
		return Template{}, fmt.Errorf("模板 %s v%d: %w", name, version, ErrNotFound)
	}
	if err != nil {
		return Template{}, fmt.Errorf("读模板: %w", err)
	}
	if err := jsonUnmarshal(raw, &t.Def); err != nil {
		return Template{}, err
	}

	if t.Def.Discipline == "" && t.Def.DisciplinePath != "" {
		if name := disciplineNameFromLegacyPath(t.Def.DisciplinePath); name != "" {
			t.Def.Discipline = name
			log().Warn("模板用了废弃字段 discipline_path，已按文件名映射为角色名；建议 template put 重写",
				"template", t.Name, "legacy_path", t.Def.DisciplinePath, "name", name)
		} else {
			log().Warn("模板用了废弃字段 discipline_path 且认不出对应角色，本次派发将按 executor 兜底；建议 template put 重写",
				"template", t.Name, "legacy_path", t.Def.DisciplinePath)
		}
	}
	t.CreatedAt = toTime(ct)
	return t, nil
}

n_ledger_Store_GetWorkflow.signature:
// GetWorkflow 取指定版本；version==0 取最新版。找不到返回 ErrNotFound。
func (s *Store) GetWorkflow(name string, version int) (Workflow, error) {
	workflow, err := s.getWorkflowStored(name, version)
	if err != nil {
		return Workflow{}, err
	}
	workflow.Def = workflow.Def.withNodesFromStates()
	if len(workflow.Def.Nodes) > 0 && len(workflow.Def.Nodes) == len(workflow.Def.States) {
		log().Debug("读出工作流", "name", workflow.Name, "version", workflow.Version, "nodes", len(workflow.Def.Nodes))
	}
	return workflow, nil
}

n_ledger_Store_ImportCard.signature:
// ImportCard 显式 ID 导入建卡：携带既有带前缀卡号（markdown 存量总账的行、
// 搁置条目复活）原号迁入账本。这是永久能力，不是一次性迁移脚本。
//
// 参数：id 目标卡号（顶层 "B153"/"C1" 或点号子卡 "C1.1"，父卡 id 由点号前缀
// 推导，nc.Parent 无需也不应自行填写）；source 导入来源标注（落进
// card_created 事件负载，空串记为「手工导入」）；nc 卡字段（标题、project
// 必填；优先级缺省「中」；工作流为空时按账本唯一流规则解析）。
// 返回：建成的卡；目标号已存在返回包装 ErrBadState 的错误。
//
// 注意：
//   - **导入不受 min_b 水位约束**——min_b 只约束自动取号（nextTopID），
//     导入一律按原号落位；导入号高于水位时，后续自动取号会自然跳过它
//     （nextTopID 取「现存最大号」与 min_b 的较大者 +1）。
//   - 点号子卡要求父卡**已存在**，缺父直接拒，不自动补建——补建等于
//     替用户猜父卡的标题与状态，猜错比报错难发现。
//   - 除 card_created 事件多带 imported/import_source 两个字段外，导入卡
//     与 CreateCard 建的卡零行为差别：同样钉工作流最新版本、初始态 =
//     工作流首态、子卡同样在父卡 timeline 留痕。
func (s *Store) ImportCard(id, source string, nc NewCard) (Card, error) {
	id = strings.TrimSpace(id)
	if !importIDPat.MatchString(id) {
		return Card{}, fmt.Errorf("导入卡: id %q 形如 B153、C1 或 C1.1", id)
	}
	if strings.TrimSpace(source) == "" {
		source = "手工导入"
	}

	if idx := strings.LastIndex(id, "."); idx >= 0 {
		nc.Parent = id[:idx]
	} else {
		nc.Parent = ""
	}
	wf, err := s.prepareCard(&nc)
	if err != nil {
		return Card{}, err
	}
	var card Card
	err = s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, id); err == nil {
			log().Warn("导入被拒：目标卡号已存在", "card", id)
			return fmt.Errorf("卡 %s 已存在，导入拒绝覆盖: %w", id, ErrBadState)
		} else if !errors.Is(err, ErrNotFound) {
			return fmt.Errorf("导入查重 %s: %w", id, err)
		}
		if err := s.checkParentTx(tx, nc.Parent, wf.Name); err != nil {
			return err
		}
		card, err = s.insertCardTx(tx, sink, id, nc, wf,
			map[string]any{"imported": true, "import_source": source})
		if err != nil {
			return err
		}
		log().Info("导入卡完成", "card", id, "workflow", wf.Name, "source", source)
		return nil
	})
	return card, err
}

n_ledger_Store_JoinCardToSession.signature:
// JoinCardToSession 把卡拉进会话：卡必须存在、会话必须存在且未归档、卡必须
// 当前不属于任何会话（一卡同时只挂一个会话），全部判定与写入在同一 mutate
// 事务内完成（唯一索引 uq_session_cards_card 是最后一道兜底）。落
// EvSessionCardJoined（无卡事件）。进群 ≠ 配人——本方法不碰卡席位。
func (s *Store) JoinCardToSession(sessionID, cardID, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		session, err := getSessionTx(s, tx, sessionID)
		if err != nil {
			return err
		}
		if session.Archived {
			return fmt.Errorf("会话 %s 已归档: %w", sessionID, ErrBadState)
		}
		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("拉卡进群: %w", err)
		}
		if owner, err := sessionOfCardTx(s, tx, cardID); err != nil {
			return err
		} else if owner != "" && owner != sessionID {
			return fmt.Errorf("卡 %s 已属会话 %s: %w", cardID, owner, ErrBadState)
		}
		if _, err := tx.Exec(s.q(`INSERT INTO session_cards (session_id, card_id, created_at)
			VALUES (?, ?, ?) ON CONFLICT (session_id, card_id) DO NOTHING`),
			sessionID, cardID, s.tval(s.timeNow())); err != nil {
			return fmt.Errorf("写会话卡归属 %s/%s: %w", sessionID, cardID, err)
		}
		if _, err := tx.Exec(s.q(`UPDATE sessions SET updated_at = ? WHERE id = ?`),
			s.tval(s.timeNow()), sessionID); err != nil {
			return fmt.Errorf("触会话 %s: %w", sessionID, err)
		}
		if _, err := s.appendEvent(tx, sink, "", EvSessionCardJoined, actor,
			map[string]string{"session": sessionID, "card": cardID}); err != nil {
			return err
		}
		return nil
	})
}

n_ledger_Store_LatestTaskStates.signature:
// LatestTaskStates 一张卡全部挂账 task 的实况。
func (s *Store) LatestTaskStates(cardID string) ([]TaskStateRow, error) {
	links, err := s.TasksOf(cardID)
	if err != nil {
		return nil, err
	}
	out := make([]TaskStateRow, 0, len(links))
	for _, link := range links {
		row := TaskStateRow{Target: link.Target, TaskID: link.TaskID, Purpose: link.Purpose}
		var raw string
		err := s.db.QueryRow(s.q(`SELECT payload, source_seq FROM card_events
			WHERE source_target = ? AND source_task = ?
			ORDER BY source_seq DESC LIMIT 1`), link.Target, link.TaskID).
			Scan(&raw, &row.LastSeq)
		if errors.Is(err, sql.ErrNoRows) {
			out = append(out, row)
			continue
		}
		if err != nil {
			return nil, fmt.Errorf("读 task 实况 %s@%s: %w", link.TaskID, link.Target, err)
		}
		var payload struct {
			TaskType string `json:"task_type"`
		}
		if err := json.Unmarshal([]byte(raw), &payload); err != nil {
			return nil, fmt.Errorf("解码 task 实况 %s@%s: %w", link.TaskID, link.Target, err)
		}
		row.LastType = payload.TaskType
		out = append(out, row)
	}
	return out, nil
}

n_ledger_Store_LeaveCardToSession.signature:
// LeaveCardToSession 把卡移出会话；幂等（不在会话内返回 nil）。落
// EvSessionCardLeft。
func (s *Store) LeaveCardToSession(sessionID, cardID, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getSessionTx(s, tx, sessionID); err != nil {
			return err
		}
		res, err := tx.Exec(s.q(`DELETE FROM session_cards WHERE session_id = ? AND card_id = ?`),
			sessionID, cardID)
		if err != nil {
			return fmt.Errorf("移卡出群 %s/%s: %w", sessionID, cardID, err)
		}
		n, err := res.RowsAffected()
		if err != nil {
			return fmt.Errorf("读移卡影响行数: %w", err)
		}
		if n == 0 {
			return nil
		}
		if _, err := tx.Exec(s.q(`UPDATE sessions SET updated_at = ? WHERE id = ?`),
			s.tval(s.timeNow()), sessionID); err != nil {
			return fmt.Errorf("触会话 %s: %w", sessionID, err)
		}
		if _, err := s.appendEvent(tx, sink, "", EvSessionCardLeft, actor,
			map[string]string{"session": sessionID, "card": cardID}); err != nil {
			return err
		}
		return nil
	})
}

n_ledger_Store_LinkTask.signature:
// LinkTask 把 (target, task) 挂到卡上。purpose ∈ {implement, review, merge}
// 语义由调用方保证（词表不在库层锁死——三期可能扩）。落 comment 事件。
func (s *Store) LinkTask(cardID, target, taskID, purpose, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("挂账: 卡 %s: %w", cardID, err)
		}
		if _, err := tx.Exec(s.q(`INSERT INTO card_tasks (card_id, target, task_id, purpose, created_at)
			VALUES (?,?,?,?,?)`), cardID, target, taskID, purpose, s.tval(time.Now())); err != nil {
			return fmt.Errorf("写挂账（task 可能已挂在别的卡）: %w", err)
		}
		_, err := s.appendEvent(tx, sink, cardID, EvComment, actor,
			map[string]any{"kind": "普通", "body": fmt.Sprintf("挂账 task %s@%s（%s）", taskID, target, purpose)})
		return err
	})
}

n_ledger_Store_ListCards.signature:
// ListCards 过滤 + 派生。排序：待人处理的在前（needs/blocked），其余按
// id 升序——CLI 领活与看板共用此序。
func (s *Store) ListCards(filter CardFilter) ([]CardView, error) {
	query := `SELECT ` + cardColumns + ` FROM cards WHERE 1=1`
	var args []any
	if filter.Project != "" {
		query += ` AND project = ?`
		args = append(args, filter.Project)
	}
	if filter.Status != "" {
		query += ` AND status = ?`
		args = append(args, filter.Status)
	}
	if !filter.IncludeTerminal {
		query += ` AND status NOT IN (?, ?)`
		args = append(args, StatusDone, StatusClosed)
	}
	rows, err := s.db.Query(s.q(query), args...)
	if err != nil {
		return nil, fmt.Errorf("列卡: %w", err)
	}
	var cards []Card
	for rows.Next() {
		card, err := scanCard(rows)
		if err != nil {
			rows.Close()
			return nil, fmt.Errorf("扫卡行: %w", err)
		}
		cards = append(cards, card)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return nil, err
	}
	rows.Close()

	relations, err := s.allRelations()
	if err != nil {
		return nil, err
	}
	statusOf, err := s.allStatuses()
	if err != nil {
		return nil, err
	}
	needs, err := s.needsMap()
	if err != nil {
		return nil, err
	}
	baseFrozen, err := s.baseFrozenMap()
	if err != nil {
		return nil, err
	}
	openDecisions, err := s.openDecisionCount()
	if err != nil {
		return nil, err
	}
	parents, err := s.allParents()
	if err != nil {
		return nil, err
	}
	type childStat struct{ total, done int }
	childStats := map[string]*childStat{}
	for child, parent := range parents {
		stat := childStats[parent]
		if stat == nil {
			stat = &childStat{}
			childStats[parent] = stat
		}
		stat.total++

		if status := statusOf[child]; status == StatusDone || status == StatusClosed {
			stat.done++
		}
	}

	var out []CardView
	for _, card := range cards {
		view := CardView{Card: card, BaseFrozen: baseFrozen[card.ID], OpenDecisions: openDecisions[card.ID], NeedsReason: needs[card.ID]}
		if stat := childStats[card.ID]; stat != nil {
			view.ChildrenTotal, view.ChildrenDone = stat.total, stat.done
		}
		for _, relation := range relations {
			switch {
			case relation.Type == RelMergedInto && relation.From == card.ID:
				view.Following = relation.To
			case relation.Type == RelMergedInto && relation.To == card.ID:
				view.MergedCount++
			case relation.Type == RelBlocks && relation.To == card.ID:

				status := statusOf[relation.From]
				if status != StatusDone {
					view.Blocked = true
					view.BlockedBy = append(view.BlockedBy, relation.From)
					if status == StatusClosed && view.NeedsReason == "" {
						view.NeedsReason = "前置 " + relation.From + " 已终止"
					}
				}
			}
		}
		if filter.BaseBranch != "" {
			effective, err := s.EffectiveBaseBranch(card.ID)
			if err != nil {
				return nil, err
			}
			if effective != filter.BaseBranch {
				continue
			}
		}
		if filter.Blocked && !view.Blocked {
			continue
		}
		if filter.Needs && view.NeedsReason == "" && view.OpenDecisions == 0 {
			continue
		}
		out = append(out, view)
	}
	sort.Slice(out, func(i, j int) bool {
		iPriority := out[i].NeedsReason != "" || out[i].Blocked
		jPriority := out[j].NeedsReason != "" || out[j].Blocked
		if iPriority != jPriority {
			return iPriority
		}
		return out[i].ID < out[j].ID
	})
	return out, nil
}

