n_ledger_Store_MergeCards.signature:
// MergeCards 把 ids 并入承载卡 into。校验（任一不过全拒，ErrBadMerge）：
// 卡都存在且非终态；不含 into 自身；无重复并入；无链式（into 自身未被并
// 入、ids 里没有正在承载别人的卡）；全体有效基线一致。
func (s *Store) MergeCards(ids []string, into, actor string) error {
	if len(ids) == 0 {
		return fmt.Errorf("合并: 成员为空")
	}
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		carrier, err := getCardTx(s, tx, into)
		if err != nil {
			return fmt.Errorf("合并: 承载卡 %s: %w", into, err)
		}
		if carrier.Status == StatusClosed || carrier.Status == StatusDone {
			log().Warn("合并被拒：承载卡终态", "card", into, "status", carrier.Status)
			return fmt.Errorf("承载卡 %s 已处于终态 %s: %w", into, carrier.Status, ErrBadMerge)
		}
		if current, err := s.mergedIntoTx(tx, into); err != nil {
			return err
		} else if current != "" {
			log().Warn("合并被拒：链式", "into", into, "its_carrier", current)
			return fmt.Errorf("承载卡 %s 自身已并入 %s，不许链式: %w", into, current, ErrBadMerge)
		}
		intoBase, err := s.effectiveBaseTx(tx, into)
		if err != nil {
			return err
		}
		seen := make(map[string]bool, len(ids))
		for _, id := range ids {
			if seen[id] {
				log().Warn("合并被拒：成员重复", "card", id, "into", into)
				return fmt.Errorf("卡 %s 在成员列表中重复: %w", id, ErrBadMerge)
			}
			seen[id] = true
			if id == into {
				log().Warn("合并被拒：自并入", "card", id)
				return fmt.Errorf("卡 %s 不能并入自己: %w", id, ErrBadMerge)
			}
			member, err := getCardTx(s, tx, id)
			if err != nil {
				return fmt.Errorf("合并: 成员 %s: %w", id, err)
			}
			if member.Status == StatusClosed || member.Status == StatusDone {
				log().Warn("合并被拒：成员终态", "card", id, "status", member.Status)
				return fmt.Errorf("成员 %s 已处于终态 %s: %w", id, member.Status, ErrBadMerge)
			}
			if current, err := s.mergedIntoTx(tx, id); err != nil {
				return err
			} else if current != "" {
				log().Warn("合并被拒：重复并入", "card", id, "already", current)
				return fmt.Errorf("卡 %s 已并入 %s: %w", id, current, ErrBadMerge)
			}
			var carrierCount int
			if err := tx.QueryRow(s.q(`SELECT COUNT(*) FROM card_relations WHERE to_id = ? AND type = ?`),
				id, RelMergedInto).Scan(&carrierCount); err != nil {
				return fmt.Errorf("查承载: %w", err)
			}
			if carrierCount > 0 {
				log().Warn("合并被拒：成员在承载别人", "card", id)
				return fmt.Errorf("卡 %s 正承载着别的卡，不许链式: %w", id, ErrBadMerge)
			}
			base, err := s.effectiveBaseTx(tx, id)
			if err != nil {
				return err
			}
			if base != intoBase {
				log().Warn("合并被拒：跨基线", "card", id, "base", base, "into_base", intoBase)
				return fmt.Errorf("卡 %s 基线 %q ≠ 承载卡基线 %q: %w", id, base, intoBase, ErrBadMerge)
			}
		}
		for _, id := range ids {
			if _, err := tx.Exec(s.q(`INSERT INTO card_relations (from_id, to_id, type, created_at)
				VALUES (?,?,?,?)`), id, into, RelMergedInto, s.tval(time.Now())); err != nil {
				return fmt.Errorf("写并入边 %s: %w", id, err)
			}
		}
		_, err = s.appendEvent(tx, sink, into, EvMerged, actor, map[string]any{"members": ids})
		return err
	})
}

n_ledger_Store_MigrateCardWorkflow.signature:
// MigrateCardWorkflow 把卡显式迁到目标工作流、版本和状态列，并返回迁移审计投影。
// Version==0 取事务内目标流最新版；目标流和状态列都必须由调用方显式提供。
func (s *Store) MigrateCardWorkflow(cardID, toWorkflow string, toVersion int, toStatus, actor string) (WorkflowMigration, error) {
	var migration WorkflowMigration
	if strings.TrimSpace(toWorkflow) == "" || strings.TrimSpace(toStatus) == "" {
		return migration, fmt.Errorf("迁移目标工作流和状态列不能为空: %w", ErrBadState)
	}
	err := s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		card, err := getCardTx(s, tx, cardID)
		if err != nil {
			log().Error("迁移读取原位置失败", "card", cardID, "cause", err)
			return fmt.Errorf("迁工作流: 卡 %s: %w", cardID, err)
		}

		inFlight, taskID, err := s.cardStepInFlightTx(tx, cardID)
		if err != nil {
			return fmt.Errorf("迁移检查卡 %s 在飞状态: %w", cardID, err)
		}
		if inFlight {
			log().Warn("迁移被拒：卡环节仍在飞", "card", cardID, "task", taskID,
				"to_workflow", toWorkflow, "to_status", toStatus)
			return fmt.Errorf("卡 %s 的任务 %s 仍在运行，不能迁移: %w", cardID, taskID, ErrStepInFlight)
		}
		if toVersion == 0 {
			if err := tx.QueryRow(s.q(`SELECT COALESCE(MAX(version), 0) FROM workflows WHERE name = ?`), toWorkflow).Scan(&toVersion); err != nil {
				return fmt.Errorf("取目标工作流 %q 最新版本: %w", toWorkflow, err)
			}
		}
		target, err := s.getWorkflowTx(tx, toWorkflow, toVersion)
		if err != nil {
			return err
		}
		found := toStatus == StatusClosed
		for _, state := range target.Def.States {
			if state == toStatus {
				found = true
				break
			}
		}
		if !found {
			log().Warn("迁移被拒：状态悬空", "card", cardID, "status", toStatus, "to_workflow", toWorkflow, "to_version", toVersion)
			return fmt.Errorf("卡 %s 当前状态 %q 不在 %s v%d 中，先转移状态再迁: %w",
				cardID, toStatus, toWorkflow, toVersion, ErrBadState)
		}

		if err := s.checkWorkflowGateTx(tx, card, target, toStatus, "迁移"); err != nil {
			return err
		}

		from := WorkflowLocation{Workflow: card.WorkflowName, Version: card.WorkflowVersion, Status: card.Status}
		to := WorkflowLocation{Workflow: toWorkflow, Version: toVersion, Status: toStatus}
		if _, err := tx.Exec(s.q(`UPDATE cards SET workflow_name = ?, workflow_version = ?, status = ?, updated_at = ? WHERE id = ?`),
			toWorkflow, toVersion, toStatus, s.tval(time.Now()), cardID); err != nil {
			return fmt.Errorf("写迁移: %w", err)
		}
		payload := map[string]any{
			"from_workflow":	from.Workflow,
			"from_version":		from.Version,
			"from_status":		from.Status,
			"to_workflow":		to.Workflow,
			"to_version":		to.Version,
			"to_status":		to.Status,
		}
		eventAt := time.Now().UTC()
		seq, err := s.appendEventAt(tx, sink, cardID, EvWorkflowMigrated, actor, payload, eventAt)
		if err != nil {
			return err
		}
		raw, err := json.Marshal(payload)
		if err != nil {
			return fmt.Errorf("编码迁移事件投影: %w", err)
		}
		migration = WorkflowMigration{
			CardID:	cardID,
			From:	from,
			To:	to,
			Event: Event{
				Seq:	seq, CardID: cardID, Type: EvWorkflowMigrated, Actor: actor,
				Payload:	raw, CreatedAt: eventAt,
			},
		}
		log().Info("工作流迁移完成", "card", cardID,
			"from_workflow", from.Workflow, "from_version", from.Version, "from_status", from.Status,
			"to_workflow", to.Workflow, "to_version", to.Version, "to_status", to.Status)
		return nil
	})
	return migration, err
}

n_ledger_Store_MirrorHealth.signature:
// MirrorHealth 全部 target 的健康行（看板滞后判定：now-UpdatedAt>60s 且 Live 才亮灯）。
func (s *Store) MirrorHealth() ([]MirrorHealthRow, error) {
	rows, err := s.db.Query(`SELECT target, last_seq, updated_at FROM mirror_cursors ORDER BY target`)
	if err != nil {
		return nil, fmt.Errorf("读镜像健康: %w", err)
	}
	defer rows.Close()
	var out []MirrorHealthRow
	for rows.Next() {
		var r MirrorHealthRow
		var ut any
		if err := rows.Scan(&r.Target, &r.LastSeq, &ut); err != nil {
			return nil, err
		}
		r.UpdatedAt = toTime(ut)
		out = append(out, r)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	live, err := s.LiveMirrorTargets()
	if err != nil {
		return nil, err
	}
	for i := range out {
		out[i].Live = live[out[i].Target]
	}
	return out, nil
}

