n_ledger_Store_NeedsOf.signature:
// NeedsOf 取一张卡当前的等人原因；没打标记（或已清除）返回空串。
//
// why 单卡要有自己的取法：needsMap 是为列表视图一次性扫全表的，详情抽屉
// 只关心一张卡。看板卡片上有「需要你」角标、点进抽屉却看不到原因，等于把
// 「卡的一切只在抽屉一处看」拆成了两处（2026-08-19 真机看到）。
//
// 语义与 needsMap 一致：按 seq 顺序回放，needs_cleared 抵消先前的 needs_human。
func (s *Store) NeedsOf(cardID string) (string, error) {
	rows, err := s.db.Query(s.q(`SELECT type, payload FROM card_events
		WHERE card_id = ? AND type IN (?, ?) ORDER BY seq ASC`), cardID, EvNeedsHuman, EvNeedsCleared)
	if err != nil {
		return "", fmt.Errorf("读卡 %s 的等人事件: %w", cardID, err)
	}
	defer rows.Close()
	reason := ""
	for rows.Next() {
		var typ, payload string
		if err := rows.Scan(&typ, &payload); err != nil {
			return "", err
		}
		if typ == EvNeedsCleared {
			reason = ""
			continue
		}
		var data struct {
			Reason string `json:"reason"`
		}
		if err := jsonUnmarshal(payload, &data); err != nil {
			return "", err
		}
		reason = data.Reason
	}
	return reason, rows.Err()
}

n_ledger_Store_OnEvent.signature:
// OnEvent 注册进程内事件回调（仅 SQLite 回退模式有意义；PG 模式下
// 消费者应走 LISTEN card_events）。回调在提交后同步触发，勿做慢活。
func (s *Store) OnEvent(fn func(seq int64)) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.listeners = append(s.listeners, fn)
}

n_ledger_Store_OpenDecision.signature:
// OpenDecision 开一条裁决。cardID 空 = 项目级请示；options 可空 = 开放问答。
func (s *Store) OpenDecision(cardID, body string, options []string, createdBy string) (Decision, error) {
	if body == "" {
		return Decision{}, fmt.Errorf("裁决 body 不能为空")
	}
	var decision Decision
	err := s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if cardID != "" {
			if _, err := getCardTx(s, tx, cardID); err != nil {
				return fmt.Errorf("裁决: 卡 %s: %w", cardID, err)
			}
		}
		var opts any
		if len(options) > 0 {
			raw, _ := json.Marshal(options)
			opts = string(raw)
		}
		var cardIDValue any
		if cardID != "" {
			cardIDValue = cardID
		}
		now := time.Now()
		var id int64
		if s.dialect == dialectPG {
			if err := tx.QueryRow(s.q(`INSERT INTO decisions (card_id, body, options, status, created_by, created_at)
				VALUES (?,?,?,'open',?,?) RETURNING id`), cardIDValue, body, opts, createdBy, s.tval(now)).Scan(&id); err != nil {
				return fmt.Errorf("写裁决: %w", err)
			}
		} else {
			result, err := tx.Exec(s.q(`INSERT INTO decisions (card_id, body, options, status, created_by, created_at)
				VALUES (?,?,?,'open',?,?)`), cardIDValue, body, opts, createdBy, s.tval(now))
			if err != nil {
				return fmt.Errorf("写裁决: %w", err)
			}
			id, err = result.LastInsertId()
			if err != nil {
				return fmt.Errorf("取裁决 id: %w", err)
			}
		}
		if _, err := s.appendEvent(tx, sink, cardID, EvDecisionOpened, createdBy,
			map[string]any{"decision_id": id, "body": body, "options": options}); err != nil {
			return err
		}
		decision = Decision{ID: id, CardID: cardID, Body: body, Options: options,
			Status:	"open", CreatedBy: createdBy, CreatedAt: now}
		return nil
	})
	return decision, err
}

n_ledger_Store_OpenTicketCounts.signature:
// OpenTicketCounts 每张卡的未决工单数：单遍扫描镜像事件，按 ticket_id
// 回放 创建→答复/作废。镜像滞后即工单滞后——与实况同一显性化通道
// （MirrorHealth），不另设真相源。
func (s *Store) OpenTicketCounts() (map[string]int, error) {
	rows, err := s.db.Query(s.q(`SELECT card_id, source_target, source_task, payload
		FROM card_events WHERE type = ? AND source_target IS NOT NULL ORDER BY seq ASC`), EvTaskMirrored)
	if err != nil {
		return nil, fmt.Errorf("读镜像工单事件: %w", err)
	}
	defer rows.Close()

	open := make(map[openTicketKey]struct{})
	for rows.Next() {
		var cardID, target, taskID, raw string
		if err := rows.Scan(&cardID, &target, &taskID, &raw); err != nil {
			return nil, fmt.Errorf("扫镜像工单事件: %w", err)
		}
		var event mirroredTaskPayload
		if err := json.Unmarshal([]byte(raw), &event); err != nil {
			return nil, fmt.Errorf("解码镜像工单事件: %w", err)
		}
		keyPrefix := func(ticketID string) openTicketKey {
			return openTicketKey{cardID: cardID, target: target, taskID: taskID, ticketID: ticketID}
		}
		switch event.TaskType {
		case evTicketCreated, evTicketQuestion:
			var ticket ticketPayload
			if err := json.Unmarshal(event.Payload, &ticket); err != nil {
				return nil, fmt.Errorf("解码镜像工单 payload: %w", err)
			}
			if ticket.TicketID != "" {
				open[keyPrefix(ticket.TicketID)] = struct{}{}
			}
		case evTicketAnswered:
			var ticket ticketPayload
			if err := json.Unmarshal(event.Payload, &ticket); err != nil {
				return nil, fmt.Errorf("解码镜像答复 payload: %w", err)
			}
			if ticket.TicketID != "" {
				delete(open, keyPrefix(ticket.TicketID))
			}
		case evTicketsVoided:
			for key := range open {
				if key.cardID == cardID && key.target == target && key.taskID == taskID {
					delete(open, key)
				}
			}
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("读镜像工单事件: %w", err)
	}

	counts := make(map[string]int)
	for key := range open {
		counts[key.cardID]++
	}
	return counts, nil
}

n_ledger_Store_PurposeRounds.signature:
// PurposeRounds 数该卡已派出的指定 purpose 轮数（只增不减，用于给重跑轮的
// 分支编号，避免 <prefix>/<卡>-<purpose> 固定拼法第二轮撞名）。成功挂账与
// 已创建但落账失败的耗费轮次相加，确保失败后重试不会再次使用残留的首轮分支名。
// 与 ledgerstep 的 CountRounds 不是一回事：那个数的是「裁决回合」（人工重置
// 会清零，用于封顶），这个数的是「派过几次」（只增不减，用于起名）。
func (s *Store) PurposeRounds(cardID, purpose string) (int, error) {
	links, err := s.TasksOf(cardID)
	if err != nil {
		log().Warn("读取成功派发轮次失败", "card", cardID, "purpose", purpose, "cause", err)
		return 0, err
	}
	succeeded := 0
	for _, link := range links {
		if link.Purpose == purpose {
			succeeded++
		}
	}
	var failed int
	if err := s.db.QueryRow(s.q(`SELECT COUNT(*)
		FROM card_dispatch_rounds WHERE card_id = ? AND purpose = ?`),
		cardID, purpose).Scan(&failed); err != nil {
		log().Warn("读取派发耗费轮次失败", "card", cardID, "purpose", purpose, "cause", err)
		return 0, fmt.Errorf("读派发耗费轮次: %w", err)
	}
	total := succeeded + failed
	log().Info("派发轮次读取完成", "card", cardID, "purpose", purpose,
		"succeeded", succeeded, "failed", failed, "total", total)
	return total, nil
}

n_ledger_Store_PutDiscipline.signature:
// PutDiscipline 写入下一版本（不改旧行），返回新版本号。
//
// name 非法、body 为空或超限时拒绝——坏数据挡在写入这一刻，好过第一次派发才炸。
func (s *Store) PutDiscipline(name, body string) (int, error) {
	if err := validateDisciplineName(name); err != nil {
		return 0, err
	}
	if strings.TrimSpace(body) == "" {
		return 0, fmt.Errorf("纪律块 %s 正文不能为空", name)
	}
	if len(body) > maxDisciplineBody {
		return 0, fmt.Errorf("纪律块 %s 正文超过 %d 字节上限（实际 %d）", name, maxDisciplineBody, len(body))
	}
	var ver int
	err := s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		if err := tx.QueryRow(s.q(`SELECT COALESCE(MAX(version),0) FROM disciplines WHERE name = ?`),
			name).Scan(&ver); err != nil {
			return fmt.Errorf("查纪律块版本: %w", err)
		}
		ver++
		if _, err := tx.Exec(s.q(`INSERT INTO disciplines (name, version, body, created_at)
			VALUES (?,?,?,?)`), name, ver, body, s.tval(time.Now())); err != nil {
			return fmt.Errorf("写纪律块 %s v%d: %w", name, ver, err)
		}
		return nil
	})
	return ver, err
}

n_ledger_Store_PutTemplate.signature:
// PutTemplate 写入下一版本（不改旧行）。
func (s *Store) PutTemplate(name string, def TemplateDef) (int, error) {
	raw, err := json.Marshal(def)
	if err != nil {
		return 0, fmt.Errorf("编码模板定义: %w", err)
	}
