		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("验收: 卡 %s: %w", cardID, err)
		}
		_, err := s.appendEvent(tx, sink, cardID, EvAcceptanceRecorded, actor,
			map[string]any{"verified_on_real_machine": verified, "evidence": evidence})
		return err
	})
}

n_ledger_Store_RecordBranchMerged.signature:
// RecordBranchMerged 落合并环节的外部动作事件。
//
// 参数：workBranch 工作分支名；base 基线分支名；pushedWorkBranch 本次是否
// 真的推了工作分支（本地已有则推，走 fetch 兜底那条腿则为 false）。
//
// 为什么要专门落这条：合并环节会 push 到 origin——外部可见、不易撤回。
// 自动化做的外部动作必须在 timeline 上留痕，否则「这次到底往 origin 推了
// 什么」只能去翻日志。
func (s *Store) RecordBranchMerged(cardID, workBranch, base string, pushedWorkBranch bool, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("合并落账: 卡 %s: %w", cardID, err)
		}
		_, err := s.appendEvent(tx, sink, cardID, EvBranchMerged, actor,
			map[string]any{
				"work_branch":		workBranch,
				"pushed_work_branch":	pushedWorkBranch,
				"merged_into":		base,
				"pushed_base":		base,
			})
		return err
	})
}

n_ledger_Store_RecordDispatch.signature:
// RecordDispatch 落派发事件。
func (s *Store) RecordDispatch(cardID string, snap DispatchSnapshot) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("派发落账: 卡 %s: %w", cardID, err)
		}
		_, err := s.appendEvent(tx, sink, cardID, EvDispatched, snap.Actor, snap)
		return err
	})
}

n_ledger_Store_RecordDispatchAndLinkTask.signature:
// RecordDispatchAndLinkTask 在同一账本事务内先追加 dispatched 快照，再写
// card_tasks 挂账及其 comment。返回错误时事务整体回消，因此远端 task 已创建
// 但本地挂账冲突不会留下看似成功的派发快照；调用方仍需负责远端孤儿回收。
//
// 参数：cardID 是卡号；snap 携带快照、Node/Attempt、目标 task 与审计 actor。
// 返回：派发快照 seq、挂账 comment seq，以及账本写入或挂账失败的原始错误包装。
// 注意：快照与挂账只在提交后对镜像可见，事务内顺序仍固定为快照→挂账。
func (s *Store) RecordDispatchAndLinkTask(cardID string, snap DispatchSnapshot) (int64, int64, error) {
	log().Debug("派发快照与挂账事务进入", "card", cardID, "node", snap.Node,
		"attempt", snap.Attempt, "target", snap.Target, "task", snap.TaskID,
		"seq", 0, "type", EvDispatched)
	var dispatchSeq, linkSeq int64
	err := s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, cardID); err != nil {
			log().Warn("派发快照与挂账事务取卡失败", "card", cardID, "node", snap.Node,
				"attempt", snap.Attempt, "target", snap.Target, "task", snap.TaskID,
				"seq", 0, "type", EvDispatched, "cause", err)
			return fmt.Errorf("派发落账: 卡 %s: %w", cardID, err)
		}
		var err error
		dispatchSeq, err = s.appendEvent(tx, sink, cardID, EvDispatched, snap.Actor, snap)
		if err != nil {
			log().Warn("派发快照事务写入失败", "card", cardID, "node", snap.Node,
				"attempt", snap.Attempt, "target", snap.Target, "task", snap.TaskID,
				"seq", dispatchSeq, "type", EvDispatched, "cause", err)
			return err
		}
		log().Debug("派发快照已写入事务", "card", cardID, "node", snap.Node,
			"attempt", snap.Attempt, "target", snap.Target, "task", snap.TaskID,
			"seq", dispatchSeq, "type", EvDispatched)
		if _, err := tx.Exec(s.q(`INSERT INTO card_tasks (card_id, target, task_id, purpose, created_at)
			VALUES (?,?,?,?,?)`), cardID, snap.Target, snap.TaskID, snap.Purpose, s.tval(time.Now())); err != nil {
			log().Warn("派发快照事务挂账失败，回消快照", "card", cardID, "node", snap.Node,
				"attempt", snap.Attempt, "target", snap.Target, "task", snap.TaskID,
				"seq", dispatchSeq, "type", EvComment, "cause", err)
			return fmt.Errorf("写挂账（task 可能已挂在别的卡）: %w", err)
		}
		linkSeq, err = s.appendEvent(tx, sink, cardID, EvComment, snap.Actor,
			map[string]any{"kind": "普通", "body": fmt.Sprintf("挂账 task %s@%s（%s）", snap.TaskID, snap.Target, snap.Purpose)})
		if err != nil {
			log().Warn("派发快照事务挂账留痕失败，回消快照", "card", cardID, "node", snap.Node,
				"attempt", snap.Attempt, "target", snap.Target, "task", snap.TaskID,
				"seq", linkSeq, "type", EvComment, "cause", err)
			return err
		}
		log().Info("派发快照与挂账事务完成", "card", cardID, "node", snap.Node,
			"attempt", snap.Attempt, "target", snap.Target, "task", snap.TaskID,
			"seq", linkSeq, "type", EvComment, "snapshot_seq", dispatchSeq)
		return nil
	})
	return dispatchSeq, linkSeq, err
}

n_ledger_Store_RecordDispatchRound.signature:
// RecordDispatchRound 记录一次未形成 card_tasks 挂账的耗费轮次。
// 参数 cardID 和 purpose 必须非空；返回值保留事务、卡不存在或 SQL 错误。
// 注意：该记录是独立计数，不向事件流广播，也不替代成功挂账。
func (s *Store) RecordDispatchRound(cardID, purpose string) error {
	log().Debug("派发耗费轮次落账进入", "card", cardID, "purpose", purpose)
	err := s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		if cardID == "" {
			return fmt.Errorf("派发耗费轮次: 卡号不能为空")
		}
		if purpose == "" {
			return fmt.Errorf("派发耗费轮次: purpose 不能为空")
		}
		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("派发耗费轮次: 卡 %s: %w", cardID, err)
		}
		if _, err := tx.Exec(s.q(`INSERT INTO card_dispatch_rounds
			(card_id, purpose, created_at) VALUES (?, ?, ?)`),
			cardID, purpose, s.tval(s.timeNow())); err != nil {
			return fmt.Errorf("写派发耗费轮次: %w", err)
		}
		return nil
	})
	if err != nil {
		log().Warn("派发耗费轮次落账失败", "card", cardID, "purpose", purpose, "cause", err)
		return err
	}
	log().Info("派发耗费轮次落账完成", "card", cardID, "purpose", purpose)
	return nil
}

n_ledger_Store_RecordMessageConsumed.signature:
// RecordMessageConsumed 落消息消费标记：同一 mutate 事务内查重后写
// （ClearNeedsHumanFrom 同形，events.go），同 (msgSeq, consumer) 重复消费
// 是幂等 no-op。恰好一次由 mutate 的单写者串行化免费获得（store.go mutate
// 注释）——查重与写入之间的窗口被事务吃掉，这是拍板 5.4「权威在账本事件」
// 的机制兑现。
//
// 语义边界（都有测试钉着）：
//   - cardID 非空时必须指向存在的卡（ErrNotFound），标记挂同一张卡的流上；
//     cardID=""=群级消息的项目级标记。cardID 不参与查重键——seq 全局唯一，
//     传错 cardID 时幂等性优先于报错。
//   - 不校验 msgSeq 是否指向存在的 room_message：目标态「已消费」对不存在
//     消息天然成立（breakdown 岔口六方案甲，未知 seq 同样真落一条标记），
//     静默面由 Pending/Mentions 只列未消费兜底。要改这个选择先回 contract。
//   - consumer 为空直接报错：「谁消费了哪条」没有「谁」无意义。
//
// 返回 nil 含三种情形：首次写入成功、本人重复消费跳过、他人已消费后再写
// 自己的标记（各消费者一条，互不顶替）——前两种全流恰一条本人标记，第三种
// 是新消费者的首次写入。
func (s *Store) RecordMessageConsumed(cardID string, msgSeq int64, consumer string) error {
	if consumer == "" {
		return fmt.Errorf("消费标记必须带 consumer")
	}
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if cardID != "" {
			if _, err := getCardTx(s, tx, cardID); err != nil {
				return fmt.Errorf("消费标记: 卡 %s: %w", cardID, err)
			}
		}

		rows, err := tx.Query(s.q(`SELECT payload FROM card_events WHERE type = ? AND actor = ?`),
			EvMessageConsumed, consumer)
		if err != nil {
			return fmt.Errorf("查消费标记: %w", err)
		}
		defer rows.Close()
		for rows.Next() {
			var raw string
			if err := rows.Scan(&raw); err != nil {
				return fmt.Errorf("扫消费标记行: %w", err)
			}
			var marker consumedMarker
			if err := json.Unmarshal([]byte(raw), &marker); err != nil {
				continue
			}
			if marker.MessageSeq == msgSeq && marker.Consumer == consumer {
				log().Info("消费标记幂等跳过：同参标记已存在",
					"msg_seq", msgSeq, "consumer", consumer, "card", cardID)
				return nil
			}
		}
		if err := rows.Err(); err != nil {
			return fmt.Errorf("遍历消费标记: %w", err)
		}
		seq, err := s.appendEvent(tx, sink, cardID, EvMessageConsumed, consumer,
			consumedMarker{MessageSeq: msgSeq, Consumer: consumer})
		if err != nil {
			return err
		}
		log().Info("消息消费标记已落账", "msg_seq", msgSeq, "consumer", consumer,
			"card", cardID, "event_seq", seq)
		return nil
	})
}

n_ledger_Store_RecordReviewVerdict.signature:
// RecordReviewVerdict 落审阅裁决事件（node 是回合计数分组键，raw 是
// verdict block 原文取证）。
func (s *Store) RecordReviewVerdict(cardID, node string, pass bool, raw, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("裁决落账: 卡 %s: %w", cardID, err)
		}
		_, err := s.appendEvent(tx, sink, cardID, EvReviewVerdict, actor,
			map[string]any{"node": node, "pass": pass, "raw": raw})
		return err
	})
}

n_ledger_Store_RecordRoomMessage.signature:
// RecordRoomMessage 落一条房间消息事件。cardID 非空 = 卡会话消息（必须
// 指向存在的卡）；空 = 群级无卡事件（项目群/全员群，天然不进多路 wait）。
// 返回 seq。白名单与书写者执法在 d_collab 的 Send，不在本方法。
func (s *Store) RecordRoomMessage(cardID string, msg proto.RoomMessage, actor string) (int64, error) {
