n_ledger_Store_RegistryDelete.signature:
// RegistryDelete 以 CAS 语义删除一条注册表实体。expectVersion 必须等于当前
// 版本（0 表示「当前必须是新建未改过的」不存在合法场景——删除前先 Get 取版本）。
func (s *Store) RegistryDelete(kind, id string, expectVersion int, actor string) error {
	return s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		result, err := tx.Exec(s.q(`DELETE FROM registry WHERE kind = ? AND id = ? AND version = ?`),
			kind, id, expectVersion)
		if err != nil {
			return fmt.Errorf("registry delete: %w", err)
		}
		if count, _ := result.RowsAffected(); count == 0 {
			return fmt.Errorf("registry %s/%s 删除冲突: 版本非 %d 或已不存在: %w", kind, id, expectVersion, ErrCASConflict)
		}
		return nil
	})
}

n_ledger_Store_RegistryGet.signature:
// RegistryGet 读一条注册表实体；不存在返回 ErrNotFound。
func (s *Store) RegistryGet(kind, id string) (RegistryEntry, error) {
	row := s.db.QueryRow(s.q(`SELECT kind, id, version, seq, body FROM registry WHERE kind = ? AND id = ?`), kind, id)
	var e RegistryEntry
	var body string
	if err := row.Scan(&e.Kind, &e.ID, &e.Version, &e.Seq, &body); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return RegistryEntry{}, fmt.Errorf("registry %s/%s: %w", kind, id, ErrNotFound)
		}
		return RegistryEntry{}, fmt.Errorf("registry get: %w", err)
	}
	e.Body = json.RawMessage(body)
	return e, nil
}

n_ledger_Store_RegistryList.signature:
// RegistryList 按 kind 列出全部实体，按 seq 升序（写入序 = 出队序的自然读法）。
func (s *Store) RegistryList(kind string) ([]RegistryEntry, error) {
	rows, err := s.db.Query(s.q(`SELECT kind, id, version, seq, body FROM registry WHERE kind = ? ORDER BY seq ASC`), kind)
	if err != nil {
		return nil, fmt.Errorf("registry list: %w", err)
	}
	defer rows.Close()
	var out []RegistryEntry
	for rows.Next() {
		var e RegistryEntry
		var body string
		if err := rows.Scan(&e.Kind, &e.ID, &e.Version, &e.Seq, &body); err != nil {
			return nil, err
		}
		e.Body = json.RawMessage(body)
		out = append(out, e)
	}
	return out, rows.Err()
}

n_ledger_Store_RegistryPut.signature:
// RegistryPut 以 CAS 语义写入一条注册表实体，返回新版本号。
//
// expectVersion 必须等于当前版本；0 表示必须不存在（新建）。冲突返回
// ErrCASConflict 包装错误，与 MoveCard 同款判据。版本从 1 起，成功即 +1。
func (s *Store) RegistryPut(kind, id string, expectVersion int, body []byte, actor string) (int, error) {
	var version int
	err := s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		if kind == "" || id == "" {
			return fmt.Errorf("registry put: kind 与 id 不能为空")
		}
		if len(body) == 0 {
			return fmt.Errorf("registry put: %s/%s: body 不能为空", kind, id)
		}
		var current int
		scanErr := tx.QueryRow(s.q(`SELECT version FROM registry WHERE kind = ? AND id = ?`), kind, id).Scan(&current)
		switch {
		case scanErr == nil:
		case errors.Is(scanErr, sql.ErrNoRows):
			current = 0
		default:
			return fmt.Errorf("registry put 读当前版本: %w", scanErr)
		}
		if current != expectVersion {
			return fmt.Errorf("registry %s/%s 版本冲突: 期望 %d 实际 %d: %w", kind, id, expectVersion, current, ErrCASConflict)
		}
		version = current + 1
		if current == 0 {
			_, err := tx.Exec(s.q(`INSERT INTO registry (kind, id, version, seq, body, actor, updated_at)
				VALUES (?, ?, ?, (SELECT COALESCE(MAX(seq), 0) + 1 FROM registry), ?, ?, ?)`),
				kind, id, version, string(body), actor, s.tval(time.Now()))
			if err != nil {
				return fmt.Errorf("registry insert: %w", err)
			}
			return nil
		}
		result, err := tx.Exec(s.q(`UPDATE registry SET version = ?, seq = (SELECT COALESCE(MAX(seq), 0) + 1 FROM registry),
			body = ?, actor = ?, updated_at = ? WHERE kind = ? AND id = ? AND version = ?`),
			version, string(body), actor, s.tval(time.Now()), kind, id, current)
		if err != nil {
			return fmt.Errorf("registry update: %w", err)
		}
		if count, _ := result.RowsAffected(); count == 0 {
			return fmt.Errorf("registry %s/%s 并发修改: %w", kind, id, ErrCASConflict)
		}
		return nil
	})
	if err != nil {
		return 0, err
	}
	return version, nil
}

n_ledger_Store_RelationsOf.signature:
// RelationsOf 双向取一张卡的全部关系边（from 或 to 命中皆返回）。
func (s *Store) RelationsOf(id string) ([]Relation, error) {
	rows, err := s.db.Query(s.q(`SELECT from_id, to_id, type, created_at FROM card_relations
		WHERE from_id = ? OR to_id = ? ORDER BY created_at`), id, id)
	if err != nil {
		return nil, fmt.Errorf("读关系边: %w", err)
	}
	defer rows.Close()
	var out []Relation
	for rows.Next() {
		var relation Relation
		var createdAt any
		if err := rows.Scan(&relation.From, &relation.To, &relation.Type, &createdAt); err != nil {
			return nil, err
		}
		relation.CreatedAt = toTime(createdAt)
		out = append(out, relation)
	}
	return out, rows.Err()
}

n_ledger_Store_ReleaseCard.signature:
// ReleaseCard 释放驱动归属（幂等；只动自己持有的那份）。
//
// 参数：id 卡号；session 仅用于兼容日志。空座幂等成功，非空席位拒绝且保留原值。
func (s *Store) ReleaseCard(id, session string) error {
	log().Info("开始释放归属", "card", id, "session", session)
	err := s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		card, err := getCardTx(s, tx, id)
		if err != nil {
			return fmt.Errorf("释放: 卡 %s: %w", id, err)
		}
		switch {
		case card.DriverSession == "" && card.DriverSource == "":
			log().Info("释放无操作：卡无主", "card", id)
			return nil
		default:
			err := fmt.Errorf("卡 %s 当前有席位，请使用 rebind（release 不清席位）: %w", id, ErrBadState)
			log().Warn("释放被拒：席位由新流程管理", "card", id, "has_session", card.DriverSession != "", "has_source", card.DriverSource != "", "cause", err)
			return err
		}
	})
	if err != nil {
		log().Warn("释放归属失败", "card", id, "session", session, "cause", err)
		return err
	}
	return nil
}

n_ledger_Store_ReleaseRunLock.signature:
// ReleaseRunLock 释放运行锁（回合结束的尽力而为清理；非持有者是 no-op，
// 失去锁的权威信号在 RenewRunLock 的 false）。
func (s *Store) ReleaseRunLock(cardID, holder string) error {
	return s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		res, err := tx.Exec(s.q(`DELETE FROM card_run_locks WHERE card_id = ? AND holder = ?`),
			cardID, holder)
		if err != nil {
			return fmt.Errorf("释放运行锁: %w", err)
		}
		if n, _ := res.RowsAffected(); n > 0 {
			log().Info("运行锁已释放", "card", cardID, "holder", holder)
		}
		return nil
	})
}

n_ledger_Store_RemoveRelation.signature:
// RemoveRelation 删关系边。merged_into 请走 UnmergeCard。
func (s *Store) RemoveRelation(from, to, typ string) error {
	if typ == RelMergedInto {
		return fmt.Errorf("解除并入请走 unmerge")
	}
	return s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		result, err := tx.Exec(s.q(`DELETE FROM card_relations WHERE from_id = ? AND to_id = ? AND type = ?`),
			from, to, typ)
		if err != nil {
			return fmt.Errorf("删关系边: %w", err)
		}
		if count, _ := result.RowsAffected(); count == 0 {
			return fmt.Errorf("关系 %s-%s-%s: %w", from, typ, to, ErrNotFound)
		}
		return nil
	})
}

n_ledger_Store_RenewDriverLease.signature:
// RenewDriverLease 续租/首建该 session 的租约行（upsert，session 全局一行：
// 兼任 N 卡的协调者一条租约覆盖全部席位，「它活着吗」问的就是会话本身）。
// 返回是否生效：true=行已写入（首建或续期）。负 ttl 合法——产已过期行，
// 供消费侧与测试在注入时钟下演练活性翻转；活性判定不在本方法内做
// （RunLockOf 同一约定：读面不过滤过期）。
func (s *Store) RenewDriverLease(session string, ttl time.Duration) (bool, error) {
	if session == "" {
		log().Warn("租约续期被拒：session 为空")
		return false, fmt.Errorf("租约续期被拒：session 为空")
	}
	renewed := false
	var expiresAt time.Time
	err := s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		expiresAt = s.timeNow().Add(ttl)

		if _, err := tx.Exec(s.q(`INSERT INTO driver_leases (session, expires_at) VALUES (?, ?)
			ON CONFLICT(session) DO UPDATE SET expires_at = excluded.expires_at`),
			session, s.tval(expiresAt)); err != nil {
			return fmt.Errorf("续驱动租约: %w", err)
		}
		renewed = true
		return nil
	})
	if err != nil {
		log().Warn("驱动租约续期失败", "session", session, "cause", err)
		return false, err
	}
	log().Info("驱动租约已续", "session", session,
		"expires_at", expiresAt.Format(time.RFC3339))
	return renewed, nil
}

n_ledger_Store_RenewRunLock.signature:
// RenewRunLock 续租：只有当前持有者可续。返回 false = 已失去（被抢或从未
// 持有），调用方必须停止对这张卡的一切写。
func (s *Store) RenewRunLock(cardID, holder string, ttl time.Duration) (bool, error) {
	renewed := false
	err := s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		res, err := tx.Exec(s.q(`UPDATE card_run_locks SET expires_at = ?
			WHERE card_id = ? AND holder = ?`), s.tval(s.timeNow().Add(ttl)), cardID, holder)
		if err != nil {
			return fmt.Errorf("续租运行锁: %w", err)
		}
		n, err := res.RowsAffected()
		if err != nil {
			return fmt.Errorf("读续租影响行数: %w", err)
		}
		renewed = n > 0
		return nil
	})
	if err != nil {
		return false, err
	}
	return renewed, nil
}

n_ledger_Store_ReviewRounds.signature:
// ReviewRounds 已派出的审阅轮数——PurposeRounds 在 review 上的特例，保留旧名
// 不动既有调用方。
func (s *Store) ReviewRounds(cardID string) (int, error) {
	return s.PurposeRounds(cardID, PurposeReview)
}

n_ledger_Store_ReviveCard.signature:
// ReviveCard 复活：仅 终止(搁置) → 待办。
func (s *Store) ReviveCard(id, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		card, err := getCardTx(s, tx, id)
		if err != nil {
			return fmt.Errorf("复活: 卡 %s: %w", id, err)
		}
		if card.Status != StatusClosed || card.TerminateReason != CloseShelved {
			log().Warn("复活被拒", "card", id, "status", card.Status, "reason", card.TerminateReason)
			return fmt.Errorf("卡 %s 非 终止(搁置)，不可复活: %w", id, ErrBadState)
		}
		if _, err := tx.Exec(s.q(`UPDATE cards SET status = ?, terminate_reason = NULL, updated_at = ? WHERE id = ?`),
			StatusTodo, s.tval(time.Now()), id); err != nil {
			return fmt.Errorf("写复活: %w", err)
		}
		_, err = s.appendEvent(tx, sink, id, EvStatusMoved, actor,
			map[string]any{"from": StatusClosed, "to": StatusTodo, "reason": "复活"})
		return err
	})
}

n_ledger_Store_RunLockOf.signature:
// RunLockOf 读单卡的运行锁行；第二个返回值 = 行是否存在。**不过滤过期**：
// 「是否正在跑」由消费侧按 ExpiresAt 与同一注入时钟判定。
func (s *Store) RunLockOf(cardID string) (RunLock, bool, error) {
	var lock RunLock
	var acquiredAt, expiresAt any
	err := s.db.QueryRow(s.q(`SELECT card_id, node, holder, acquired_at, expires_at
		FROM card_run_locks WHERE card_id = ?`), cardID).
		Scan(&lock.CardID, &lock.Node, &lock.Holder, &acquiredAt, &expiresAt)
	if errors.Is(err, sql.ErrNoRows) {
		return RunLock{}, false, nil
	}
	if err != nil {
		return RunLock{}, false, fmt.Errorf("读运行锁 %s: %w", cardID, err)
	}
	lock.AcquiredAt, lock.ExpiresAt = toTime(acquiredAt), toTime(expiresAt)
	return lock, true, nil
}

n_ledger_Store_SessionOfCard.signature:
// SessionOfCard 返回该卡当前所属会话 id；不属于任何会话返回空串。
func (s *Store) SessionOfCard(cardID string) (string, error) {
	var sessionID string
	err := s.db.QueryRow(s.q(`SELECT session_id FROM session_cards WHERE card_id = ?`), cardID).Scan(&sessionID)
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("读卡 %s 的会话: %w", cardID, err)
	}
	return sessionID, nil
}

n_ledger_Store_SetAcceptance.signature:
// SetAcceptance 写验收判据文本（判据是卡字段；验收**结果**走
// RecordAcceptance 落事件，Task 8）。写入成功后查询挂账 task 的镜像实况；
// 这是唯一能同时覆盖 CLI 与 HTTP 的写点，也让新判据不会静默影响已经启动的轮次。
// 查询到在飞 task 时，先落原有更新评论，再以既有评论事件记录影响提示。
func (s *Store) SetAcceptance(id, criteria, actor string) error {
	log().Info("更新验收判据进入", "card", id, "actor", actor, "criteria_bytes", len(criteria))
	if err := s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		result, err := tx.Exec(s.q(`UPDATE cards SET acceptance_criteria = ?, updated_at = ? WHERE id = ?`),
			criteria, s.tval(time.Now()), id)
		if err != nil {
			return fmt.Errorf("写判据: %w", err)
		}
		if count, _ := result.RowsAffected(); count == 0 {
			return fmt.Errorf("卡 %s: %w", id, ErrNotFound)
		}
		_, err = s.appendEvent(tx, sink, id, EvComment, actor,
			map[string]any{"kind": "普通", "body": "更新验收判据"})
		return err
	}); err != nil {
		log().Error("更新验收判据失败", "card", id, "actor", actor, "cause", err)
		return err
	}

	states, err := s.LatestTaskStates(id)
	if err != nil {
		log().Error("判据已写入但读取在飞 task 失败", "card", id, "actor", actor, "cause", err)
		return nil
	}
	liveIDs := make([]string, 0, len(states))
	for _, state := range states {
		if state.LastType != "archived" && state.LastType != "failed" {
			liveIDs = append(liveIDs, state.Target+"/"+state.TaskID)
		}
	}
	if len(liveIDs) == 0 {
		log().Info("验收判据更新完成，无在飞 task", "card", id, "actor", actor)
		return nil
	}

	body := AcceptanceInFlightNotice + "：" + strings.Join(liveIDs, "、")
	if _, err := s.AddComment(id, body, "普通", actor); err != nil {
		log().Error("判据已写入但在飞提示落账失败", "card", id, "actor", actor,
			"tasks", liveIDs, "cause", err)
		return fmt.Errorf("写在飞判据提示: %w", err)
	}
	log().Warn("更新验收判据影响在飞轮次", "card", id, "actor", actor, "tasks", liveIDs)
	return nil
}

n_ledger_Store_SetCardBaseBranch.signature:
// SetCardBaseBranch 为尚未出现任何 dispatched 事件的卡设置或清除显式基线。
// id 是卡号，branch 非空为显式分支、空串清除自身覆盖值，actor 是审计主体。
// 首次派发判定、cards 更新和 EvComment 必须在同一个 mutate 事务内完成。
func (s *Store) SetCardBaseBranch(id, branch, actor string) error {
	log().Info("设置卡基线进入", "card", id, "branch", branch, "actor", actor)
	err := s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, id); err != nil {
			log().Warn("设置卡基线失败：卡不存在或读取失败", "card", id, "cause", err)
			return fmt.Errorf("设置卡基线：卡 %s: %w", id, err)
		}
		var raw string
		var createdAt any
		err := tx.QueryRow(s.q(`SELECT payload, created_at FROM card_events
			WHERE card_id = ? AND type = ? ORDER BY seq ASC LIMIT 1`), id, EvDispatched).Scan(&raw, &createdAt)
		switch {
		case err == nil:
			var snapshot DispatchSnapshot
			if decodeErr := json.Unmarshal([]byte(raw), &snapshot); decodeErr != nil {
				log().Error("首条 dispatched payload 损坏", "card", id, "cause", decodeErr)
				return fmt.Errorf("卡 %s 的首次派发快照损坏: %w", id, ErrBadState)
			}
			at := toTime(createdAt).Format(time.RFC3339Nano)
			log().Warn("设置卡基线被拒：基线已冻结", "card", id,
				"first_branch", snapshot.Branch, "first_dispatched_at", at, "actor", actor)
			return fmt.Errorf("卡 %s 已在分支 %q 于 %s 首次派发，基线已冻结: %w",
				id, snapshot.Branch, at, ErrBadState)
		case !errors.Is(err, sql.ErrNoRows):
			log().Error("查询 dispatched 事件失败", "card", id, "cause", err)
			return fmt.Errorf("查询卡 %s 的 dispatched 事件: %w", id, err)
		}
		now := s.timeNow()
		if _, err := tx.Exec(s.q(`UPDATE cards SET base_branch = ?, updated_at = ? WHERE id = ?`),
			branch, s.tval(now), id); err != nil {
			log().Error("写 cards 基线失败", "card", id, "branch", branch, "cause", err)
			return fmt.Errorf("写卡 %s 基线: %w", id, err)
		}
		payload := map[string]any{"kind": "普通", "base_branch": branch,
			"body":	fmt.Sprintf("更新卡基线：%q", branch)}
		if _, err := s.appendEventAt(tx, sink, id, EvComment, actor, payload, now); err != nil {
			log().Error("落基线 comment 失败", "card", id, "branch", branch, "cause", err)
			return fmt.Errorf("记录卡 %s 基线变更: %w", id, err)
		}
		log().Info("设置卡基线完成", "card", id, "branch", branch, "actor", actor)
		return nil
	})
	if err != nil {
		log().Warn("设置卡基线未提交", "card", id, "branch", branch, "cause", err)
	}
	return err
}

n_ledger_Store_SetCardPrefix.signature:
// SetCardPrefix 为项目设置或修改卡号前缀。
//
// 参数：project 自由字符串项目名；prefix 为 1~4 个大写 ASCII 字母。
// 返回：映射落库成功返回 nil；格式非法、前缀占用或项目已有卡时报错。
//
// 注意：已有卡的项目禁止修改，即使新前缀与旧前缀相同也只允许在无卡时
// 幂等重放。前缀一旦随卡号发出就不能迁移，避免已发出的卡号变成孤儿。
func (s *Store) SetCardPrefix(project, prefix string) error {
	log().Info("开始设置卡号前缀", "project", project, "prefix", prefix)
	if strings.TrimSpace(project) == "" {
		log().Warn("设置卡号前缀被拒：项目名为空", "prefix", prefix)
		return fmt.Errorf("项目名不能为空")
	}
	if !cardPrefixPat.MatchString(prefix) {
		log().Warn("设置卡号前缀被拒：前缀格式非法", "project", project, "prefix", prefix)
		return fmt.Errorf("卡号前缀 %q 非法，必须是 1~4 个大写 ASCII 字母", prefix)
	}
	err := s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		var cardCount int
		if err := tx.QueryRow(s.q(`SELECT COUNT(*) FROM cards WHERE project = ?`), project).Scan(&cardCount); err != nil {
			return fmt.Errorf("检查项目 %q 是否已有卡: %w", project, err)
		}
		if cardCount > 0 {
			log().Warn("设置卡号前缀被拒：项目已有卡", "project", project, "prefix", prefix, "cards", cardCount)
			return fmt.Errorf("项目 %q 已有卡，不能修改卡号前缀", project)
		}

		var owner string
		err := tx.QueryRow(s.q(`SELECT project FROM card_prefixes WHERE prefix = ?`), prefix).Scan(&owner)
		if err == nil && owner != project {
			log().Warn("设置卡号前缀被拒：前缀已占用", "project", project, "prefix", prefix, "owner", owner)
			return fmt.Errorf("卡号前缀 %s 已被项目 %q 占用", prefix, owner)
		}
		if err != nil && !errors.Is(err, sql.ErrNoRows) {
			return fmt.Errorf("查卡号前缀 %s 的占用方: %w", prefix, err)
		}

		var existing string
		err = tx.QueryRow(s.q(`SELECT prefix FROM card_prefixes WHERE project = ?`), project).Scan(&existing)
		switch {
		case err == nil:
			if existing == prefix {
				log().Info("卡号前缀设置幂等完成", "project", project, "prefix", prefix)
				return nil
			}
			if _, err := tx.Exec(s.q(`UPDATE card_prefixes SET prefix = ? WHERE project = ?`), prefix, project); err != nil {
				return fmt.Errorf("更新项目 %q 的卡号前缀: %w", project, err)
			}
		case errors.Is(err, sql.ErrNoRows):
			if _, err := tx.Exec(s.q(`INSERT INTO card_prefixes (project, prefix) VALUES (?, ?)`), project, prefix); err != nil {
				return fmt.Errorf("写入项目 %q 的卡号前缀: %w", project, err)
			}
		default:
			return fmt.Errorf("读项目 %q 的卡号前缀: %w", project, err)
		}
		log().Info("卡号前缀设置完成", "project", project, "prefix", prefix)
		return nil
	})
	if err != nil {
		log().Error("设置卡号前缀失败", "project", project, "prefix", prefix, "cause", err)
	}
	return err
}

n_ledger_Store_SplitCard.signature:
// SplitCard 拆子卡：建子卡（点号 id、同工作流、同 project）+ split_from 边。
func (s *Store) SplitCard(parent, title, actor string) (Card, error) {
	parentCard, err := s.GetCard(parent)
	if err != nil {
		return Card{}, fmt.Errorf("拆分: 父卡 %s: %w", parent, err)
	}
	child, err := s.CreateCard(NewCard{Title: title, Project: parentCard.Project,
		Workflow:	parentCard.WorkflowName, Parent: parent, Actor: actor})
	if err != nil {
		return Card{}, err
	}
	err = s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := tx.Exec(s.q(`INSERT INTO card_relations (from_id, to_id, type, created_at)
			VALUES (?,?,?,?)`), child.ID, parent, RelSplitFrom, s.tval(time.Now())); err != nil {
			return fmt.Errorf("写 split_from: %w", err)
		}
		_, err := s.appendEvent(tx, sink, parent, EvSplit, actor,
			map[string]any{"child": child.ID, "title": title})
		return err
	})
	return child, err
}

n_ledger_Store_Subtree.signature:
// Subtree 返回卡树成员 id 集：root + 全部后代（parent 链）+ 并入成员
// （merged_into 指向集内任一成员的卡）。多路 wait 用。
//
// 注意：它的语义含并入成员，与抽屉「子任务」区不是一回事——
// 那里要的是直接子卡，走 ChildrenOf。
func (s *Store) Subtree(rootID string) ([]string, error) {
	if _, err := s.GetCard(rootID); err != nil {
		return nil, err
	}
	set := map[string]bool{rootID: true}
	frontier := []string{rootID}
	for len(frontier) > 0 {
		q := `SELECT id FROM cards WHERE parent_id IN (?` + strings.Repeat(",?", len(frontier)-1) + `)`
		args := make([]any, len(frontier))
		for i, id := range frontier {
			args[i] = id
		}
		rows, err := s.db.Query(s.q(q), args...)
		if err != nil {
			return nil, fmt.Errorf("读子树: %w", err)
		}
		var next []string
		for rows.Next() {
			var id string
			if err := rows.Scan(&id); err != nil {
				rows.Close()
				return nil, err
			}
			if !set[id] {
				set[id] = true
				next = append(next, id)
			}
		}
		rowErr := rows.Err()
		rows.Close()
		if rowErr != nil {
			return nil, rowErr
		}
		frontier = next
	}
	ids := make([]string, 0, len(set))
	for id := range set {
		ids = append(ids, id)
	}
	q := `SELECT from_id FROM card_relations WHERE type = 'merged_into' AND to_id IN (?` +
		strings.Repeat(",?", len(ids)-1) + `)`
	args := make([]any, len(ids))
	for i, id := range ids {
		args[i] = id
	}
	rows, err := s.db.Query(s.q(q), args...)
	if err != nil {
		return nil, fmt.Errorf("读并入成员: %w", err)
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		set[id] = true
	}
	out := make([]string, 0, len(set))
	for id := range set {
		out = append(out, id)
	}
	sort.Strings(out)
	return out, rows.Err()
}

n_ledger_Store_TakeoverCard.signature:
// TakeoverCard 保留旧的人尺度命令签名，但不再改变协调者席位或落
// EvDriverTakeover；请使用 BindSeat/RebindSeat 完成三颗按钮语义。
func (s *Store) TakeoverCard(id, session, actor string) error {
	log().Warn("旧接管入口已停用", "card", id, "has_session", session != "", "has_actor", actor != "")
	if _, err := s.GetCard(id); err != nil {
		return fmt.Errorf("接管驱动: 卡 %s: %w", id, err)
	}
	return fmt.Errorf("卡 %s 不再通过 takeover 占座，请使用 bind、coordinate 或 rebind: %w", id, ErrBadState)
}

n_ledger_Store_TasksOf.signature:
// TasksOf 列一张卡挂的全部 task，并从同卡的最新 dispatched 快照投影
// workflow Node/Attempt。card_tasks 保持五列兼容形状，旧挂账没有匹配快照
// 时返回空投影，不从 task id 或 purpose 猜身份。
func (s *Store) TasksOf(cardID string) ([]TaskLink, error) {
	rows, err := s.db.Query(s.q(`SELECT card_id, target, task_id, purpose, created_at
		FROM card_tasks WHERE card_id = ? ORDER BY created_at`), cardID)
	if err != nil {
		log().Warn("读挂账失败", "card", cardID, "cause", err)
		return nil, fmt.Errorf("读挂账: %w", err)
	}
	defer rows.Close()
	var out []TaskLink
	for rows.Next() {
		var link TaskLink
		var createdAt any
		if err := rows.Scan(&link.CardID, &link.Target, &link.TaskID, &link.Purpose, &createdAt); err != nil {
			log().Warn("扫描挂账失败", "card", cardID, "cause", err)
			return nil, err
		}
		link.CreatedAt = toTime(createdAt)
		out = append(out, link)
	}
	if err := rows.Err(); err != nil {
		log().Warn("读挂账行失败", "card", cardID, "cause", err)
		return nil, fmt.Errorf("读挂账行: %w", err)
	}
	return s.projectTaskLinks(cardID, out)
}

n_ledger_Store_TouchMirrorHealth.signature:
// TouchMirrorHealth per-target 心跳：updated_at 恒更新，last_seq 只升不降。
func (s *Store) TouchMirrorHealth(target string, lastSeq int64) error {
	return s.mutate(func(tx *sql.Tx, _ *eventSink) error {
		_, err := tx.Exec(s.q(`INSERT INTO mirror_cursors (target, last_seq, updated_at)
			VALUES (?,?,?)
			ON CONFLICT (target) DO UPDATE SET
				last_seq = CASE WHEN excluded.last_seq > mirror_cursors.last_seq
					THEN excluded.last_seq ELSE mirror_cursors.last_seq END,
				updated_at = excluded.updated_at`),
			target, lastSeq, s.tval(time.Now()))
		if err != nil {
			return fmt.Errorf("touch 镜像健康 %s: %w", target, err)
		}
		return nil
	})
}

n_ledger_Store_UnmergeCard.signature:
// UnmergeCard 拆回：删 merged_into 边，恢复自主流转。判据/事件无损
// （它们从未被动过）。
func (s *Store) UnmergeCard(id, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		carrier, err := s.mergedIntoTx(tx, id)
		if err != nil {
			return err
		}
		if carrier == "" {
			return fmt.Errorf("卡 %s 未并入任何卡: %w", id, ErrNotFound)
		}
		if _, err := tx.Exec(s.q(`DELETE FROM card_relations WHERE from_id = ? AND type = ?`),
			id, RelMergedInto); err != nil {
			return fmt.Errorf("删并入边: %w", err)
		}
		_, err = s.appendEvent(tx, sink, id, EvUnmerged, actor, map[string]any{"from_carrier": carrier})
		return err
	})
}

n_ledger_Store_UpdateCardMeta.signature:
// UpdateCardMeta 改标题/优先级（空串 = 不改该项）。落 comment 事件。
func (s *Store) UpdateCardMeta(id, title, priority, actor string) error {
	return s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		card, err := getCardTx(s, tx, id)
		if err != nil {
			return fmt.Errorf("改卡: 卡 %s: %w", id, err)
		}
		if title == "" {
			title = card.Title
		}
		if priority == "" {
			priority = card.Priority
		}
		if _, err := tx.Exec(s.q(`UPDATE cards SET title = ?, priority = ?, updated_at = ? WHERE id = ?`),
			title, priority, s.tval(time.Now()), id); err != nil {
			return fmt.Errorf("写改卡: %w", err)
		}
		_, err = s.appendEvent(tx, sink, id, EvComment, actor,
			map[string]any{"kind": "普通", "body": fmt.Sprintf("改卡：标题=%q 优先级=%s", title, priority)})
		return err
	})
}

n_ledger_Store_WorkBranch.signature:
// WorkBranch 卡的工作分支：最近一次**非审阅**派发所用的分支。
// 审阅是只读的、跑在工作分支上，不新开分支——所以「卡的分支」这个问题
// 的答案必须跳过审阅轮，否则合并节点会去合一条审阅分支，而第二轮审阅
// 会撞上第一轮的同名分支（真机实测：fatal: a branch named ... already exists）。
// 老快照没有 purpose 字段时回落到挂账表按 task_id 查用途。
func (s *Store) WorkBranch(cardID string) (WorkBranchInfo, error) {
	var zero WorkBranchInfo
	events, err := s.EventsFromAsc([]string{cardID}, 0, 10000)
	if err != nil {
		return zero, fmt.Errorf("读卡 dispatched 事件: %w", err)
	}
	links, err := s.TasksOf(cardID)
	if err != nil {
		return zero, err
	}
	purposeOf := map[string]string{}
	for _, link := range links {
		purposeOf[link.TaskID] = link.Purpose
	}
	info := WorkBranchInfo{}
	for _, event := range events {
		if event.Type != EvDispatched {
			continue
		}
		var snapshot DispatchSnapshot
		if err := json.Unmarshal(event.Payload, &snapshot); err != nil {
			continue
		}
		purpose := snapshot.Purpose
		if purpose == "" {
			purpose = purposeOf[snapshot.TaskID]
		}
		if purpose == PurposeReview {
			continue
		}
		if snapshot.Branch != "" {
			info = WorkBranchInfo{Branch: snapshot.Branch, Target: snapshot.Target, TaskID: snapshot.TaskID}
		}
	}
	if info.Branch == "" {
		return zero, fmt.Errorf("卡 %s 没有非审阅的 dispatched 快照（还没派过实现轮？）: %w", cardID, ErrNotFound)
	}
	return info, nil
}

n_ledger_Store_WorkBranchPublished.signature:
// WorkBranchPublished 报告该卡当前工作分支是否已有 origin 发布事件。
func (s *Store) WorkBranchPublished(cardID, branch string) (bool, error) {
	if branch == "" {
		return false, nil
	}
	events, err := s.EventsFromAsc([]string{cardID}, 0, 10000)
	if err != nil {
		return false, fmt.Errorf("读卡 origin 发布事件: %w", err)
	}
	for _, event := range events {
		if event.Type != EvWorkBranchPublished {
			continue
		}
		var snap WorkBranchPublishedSnap
		if err := json.Unmarshal(event.Payload, &snap); err != nil {
			continue
		}
		if snap.Branch == branch {
			return true, nil
		}
	}
	return false, nil
}

n_ledger_Store_addComment.signature:
func (s *Store) addComment(cardID, body, kind, actor, resetNode string) (Event, error) {
	if kind != "普通" && kind != "更正" {
		return Event{}, fmt.Errorf("评论 kind %q 不在 {普通,更正}", kind)
	}
	var event Event
	err := s.mutate(func(tx *sql.Tx, sink *eventSink) error {
		if _, err := getCardTx(s, tx, cardID); err != nil {
			return fmt.Errorf("评论: 卡 %s: %w", cardID, err)
		}
		var refs []string
		for _, match := range cardRefPat.FindAllStringSubmatch(body, -1) {
			ref := match[1]
			if ref == cardID {
				continue
			}
			refs = append(refs, ref)
			if _, err := getCardTx(s, tx, ref); err != nil {
				if errors.Is(err, ErrNotFound) {
					continue
				}
				return fmt.Errorf("评论引用查卡 %s: %w", ref, err)
			}

			if _, err := tx.Exec(s.q(`INSERT INTO card_relations (from_id, to_id, type, created_at)
				VALUES (?,?,?,?) ON CONFLICT (from_id, to_id, type) DO NOTHING`),
				cardID, ref, RelRelates, s.tval(time.Now())); err != nil {
				return fmt.Errorf("评论引用建边 %s: %w", ref, err)
			}
		}
		payload := map[string]any{"kind": kind, "body": body, "refs": refs}
		if resetNode != "" {
			payload["human_reset_node"] = resetNode
		}
		now := time.Now()
		seq, err := s.appendEventAt(tx, sink, cardID, EvComment, actor, payload, now)
		if err != nil {
			return err
		}
		event = Event{Seq: seq, CardID: cardID, Type: EvComment, Actor: actor,
			CreatedAt:	now.UTC()}
		raw, _ := json.Marshal(payload)
		event.Payload = raw
		return nil
	})
	return event, err
}

n_ledger_Store_allParents.signature:
// allParents 全量 child→parent 映射（只含有父的卡）。与 allStatuses 同为
// 「全量小表 + 内存组装」——卡量级数百张，正确性优先（见文件头）。
func (s *Store) allParents() (map[string]string, error) {
	rows, err := s.db.Query(s.q(`SELECT id, parent_id FROM cards WHERE parent_id IS NOT NULL`))
