n_ledger_Store_ancestorsTx.signature:
// ancestorsTx 取卡的祖先集合（parent 链，含防御性深度上限）。
func (s *Store) ancestorsTx(tx *sql.Tx, id string) (map[string]bool, error) {
	ancestors := map[string]bool{}
	current := id
	for i := 0; i < 64; i++ {
		var parent sql.NullString
		err := tx.QueryRow(s.q(`SELECT parent_id FROM cards WHERE id = ?`), current).Scan(&parent)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return ancestors, nil
			}
			return nil, fmt.Errorf("读父链: %w", err)
		}
		if !parent.Valid || parent.String == "" {
			return ancestors, nil
		}
		ancestors[parent.String] = true
		current = parent.String
	}
	return ancestors, fmt.Errorf("父链深度超限（数据疑似成环）: %s", id)
}

n_ledger_Store_appendEvent.signature:
// appendEvent 在事务内落一条账本事件并（PG）推送通知。cardID 可空 =
// 项目级事件。返回 seq。所有领域操作共用此入口，禁止绕过它裸 INSERT。
func (s *Store) appendEvent(tx *sql.Tx, sink *eventSink, cardID, typ, actor string, payload any) (int64, error) {
	return s.appendEventAt(tx, sink, cardID, typ, actor, payload, time.Now())
}

n_ledger_Store_appendEventAt.signature:
// appendEventAt 同 appendEvent，但由调用方给定事件时间——调用方需要把
// 同一个时间戳回填进返回给上层的 Event，否则返回值的 CreatedAt 是零值，
// 机器消费方（CLI stdout、Plan D 的 HTTP API）会读到 0001-01-01。
func (s *Store) appendEventAt(tx *sql.Tx, sink *eventSink, cardID, typ, actor string, payload any, at time.Time) (int64, error) {
	raw, err := json.Marshal(payload)
	if err != nil {
		return 0, fmt.Errorf("编码事件 payload: %w", err)
	}
	var cid any
	if cardID != "" {
		cid = cardID
	}
	var seq int64
	if s.dialect == dialectPG {

		err = tx.QueryRow(s.q(`INSERT INTO card_events (card_id, type, actor, payload, created_at)
			VALUES (?,?,?,?,?) RETURNING seq`),
			cid, typ, actor, string(raw), s.tval(at)).Scan(&seq)
		if err == nil {
			_, err = tx.Exec(`SELECT pg_notify('card_events', $1)`, fmt.Sprint(seq))
		}
	} else {
		var result sql.Result
		result, err = tx.Exec(s.q(`INSERT INTO card_events (card_id, type, actor, payload, created_at)
			VALUES (?,?,?,?,?)`),
			cid, typ, actor, string(raw), s.tval(at))
		if err == nil {
			seq, err = result.LastInsertId()
		}
	}
	if err != nil {
		return 0, fmt.Errorf("落账本事件 %s: %w", typ, err)
	}
	sink.seqs = append(sink.seqs, seq)
	return seq, nil
}

n_ledger_Store_attachSessionCards.signature:
// attachSessionCards 填充会话的卡号列表，按卡号升序。
func (s *Store) attachSessionCards(db queryer, session *Session) error {
	rows, err := db.Query(s.q(`SELECT card_id FROM session_cards WHERE session_id = ? ORDER BY card_id`), session.ID)
	if err != nil {
		return fmt.Errorf("读会话 %s 卡列表: %w", session.ID, err)
	}
	defer rows.Close()
	for rows.Next() {
		var cardID string
		if err := rows.Scan(&cardID); err != nil {
			return fmt.Errorf("扫会话卡行: %w", err)
		}
		session.Cards = append(session.Cards, cardID)
	}
	return rows.Err()
}

n_ledger_Store_baseFrozenMap.signature:
// baseFrozenMap 从 dispatched 事件流推导基线冻结态；不新增或维护状态列，避免
// 派发与列表投影之间出现需要人工修复的双写窗口。
func (s *Store) baseFrozenMap() (map[string]bool, error) {
	rows, err := s.db.Query(s.q(`SELECT card_id FROM card_events WHERE type = ? AND card_id IS NOT NULL`), EvDispatched)
	if err != nil {
		log().Error("推导卡基线冻结态失败：查询 dispatched 事件", "cause", err)
		return nil, fmt.Errorf("读卡基线冻结事件: %w", err)
	}
	defer rows.Close()
	frozen := map[string]bool{}
	for rows.Next() {
		var cardID string
		if err := rows.Scan(&cardID); err != nil {
			log().Error("推导卡基线冻结态失败：读取 dispatched 卡号", "cause", err)
			return nil, fmt.Errorf("读卡基线冻结卡号: %w", err)
		}
		frozen[cardID] = true
	}
	if err := rows.Err(); err != nil {
		log().Error("推导卡基线冻结态失败：遍历 dispatched 事件", "cause", err)
		return nil, fmt.Errorf("遍历卡基线冻结事件: %w", err)
	}
	return frozen, nil
}

n_ledger_Store_blocksEdgesTx.signature:
// blocksEdgesTx 事务内读全部阻塞边成邻接表（from 阻塞 → to 列表）。
func (s *Store) blocksEdgesTx(tx *sql.Tx) (map[string][]string, error) {
	rows, err := tx.Query(s.q(`SELECT from_id, to_id FROM card_relations WHERE type = ?`), RelBlocks)
	if err != nil {
		return nil, fmt.Errorf("读阻塞图: %w", err)
	}
	defer rows.Close()
	edges := map[string][]string{}
	for rows.Next() {
		var from, to string
		if err := rows.Scan(&from, &to); err != nil {
			return nil, err
		}
		edges[from] = append(edges[from], to)
	}
	return edges, rows.Err()
}

n_ledger_Store_cardPrefixTx.signature:
// cardPrefixTx 返回项目已有前缀；首次建卡时按项目名首个 ASCII 字母分配。
//
// 参数：tx 当前建卡事务；project 卡的自由字符串项目名。
// 返回：已存在或新分配的前缀；前缀撞车、项目无 ASCII 字母或数据库失败时报错。
//
// 注意：调用方必须处于 mutate 的写事务内。这样前缀占用与卡行插入同进同退，
// 并发首建不会出现两个项目同时看见同一个空闲前缀。
func (s *Store) cardPrefixTx(tx *sql.Tx, project string) (string, error) {
	var prefix string
	err := tx.QueryRow(s.q(`SELECT prefix FROM card_prefixes WHERE project = ?`), project).Scan(&prefix)
	if err == nil {
		return prefix, nil
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return "", fmt.Errorf("读项目 %q 的卡号前缀: %w", project, err)
	}

	candidate := firstASCIILetter(project)
	if candidate == "" {
		log().Warn("建卡被拒：项目名没有 ASCII 字母", "project", project)
		return "", fmt.Errorf("项目 %q 没有 ASCII 字母，无法自动分配前缀；请先执行 `handoff card prefix %s <前缀>`", project, project)
	}
	var owner string
	err = tx.QueryRow(s.q(`SELECT project FROM card_prefixes WHERE prefix = ?`), candidate).Scan(&owner)
	if err == nil {
		log().Warn("建卡被拒：自动前缀已占用", "project", project, "prefix", candidate, "owner", owner)
		return "", fmt.Errorf("项目 %q 的自动前缀 %s 已被项目 %q 占用，请先执行 `handoff card prefix %s <前缀>`",
			project, candidate, owner, project)
	}
	if !errors.Is(err, sql.ErrNoRows) {
		return "", fmt.Errorf("查卡号前缀 %s 的占用方: %w", candidate, err)
	}
	if _, err := tx.Exec(s.q(`INSERT INTO card_prefixes (project, prefix) VALUES (?, ?)`), project, candidate); err != nil {
		return "", fmt.Errorf("分配项目 %q 的卡号前缀 %s: %w", project, candidate, err)
	}
	log().Info("自动分配卡号前缀", "project", project, "prefix", candidate)
	return candidate, nil
}

n_ledger_Store_cardStepInFlightQuery.signature:
func (s *Store) cardStepInFlightQuery(q taskEventQueryer, cardID string) (bool, string, error) {
	rows, err := q.Query(s.q(`SELECT type, source_task, payload
		FROM card_events
		WHERE card_id = ? AND type IN (?, ?)
		ORDER BY seq ASC`), cardID, EvDispatched, EvTaskMirrored)
	if err != nil {
		err = fmt.Errorf("读卡在飞事件: %w", err)
		log().Error("读取在飞任务事件失败", "card", cardID, "cause", err)
		return false, "", err
	}
	defer rows.Close()

	dispatched := make(map[string]struct{})
	closed := make(map[string]struct{})
	for rows.Next() {
		var eventType, raw string
		var sourceTask sql.NullString
		if err := rows.Scan(&eventType, &sourceTask, &raw); err != nil {
			err = fmt.Errorf("扫卡在飞事件: %w", err)
			log().Error("扫描在飞任务事件失败", "card", cardID, "cause", err)
			return false, "", err
		}
		switch eventType {
		case EvDispatched:
			var dispatch DispatchSnapshot
			if err := json.Unmarshal([]byte(raw), &dispatch); err != nil {
				err = fmt.Errorf("解码卡在飞派发事件: %w", err)
				log().Error("解码在飞任务派发失败", "card", cardID, "cause", err)
				return false, "", err
			}
			if dispatch.TaskID == "" {
				err := fmt.Errorf("卡在飞派发事件缺少 task_id")
				log().Error("解码在飞任务派发失败", "card", cardID, "cause", err)
				return false, "", err
			}
			dispatched[dispatch.TaskID] = struct{}{}
		case EvTaskMirrored:
			if !sourceTask.Valid || sourceTask.String == "" {
				err := fmt.Errorf("卡在飞镜像事件缺少 source_task")
				log().Error("扫描在飞任务镜像失败", "card", cardID, "cause", err)
				return false, "", err
			}
			var event mirroredTaskPayload
			if err := json.Unmarshal([]byte(raw), &event); err != nil {
				err = fmt.Errorf("解码卡在飞镜像事件: %w", err)
				log().Error("解码在飞任务镜像失败", "card", cardID, "cause", err)
				return false, "", err
			}
			if event.TaskType == "archived" || event.TaskType == "failed" {
				closed[sourceTask.String] = struct{}{}
			}
		}
	}
	if err := rows.Err(); err != nil {
		err = fmt.Errorf("读卡在飞事件: %w", err)
		log().Error("读取在飞任务事件失败", "card", cardID, "cause", err)
		return false, "", err
	}
	for taskID := range dispatched {
		if _, done := closed[taskID]; !done {
			log().Debug("卡环节仍在飞", "card", cardID, "task", taskID)
			return true, taskID, nil
		}
	}
	return false, "", nil
}

n_ledger_Store_cardStepInFlightTx.signature:
// cardStepInFlightTx 是迁移事务使用的同一派生查询，避免把门禁读到事务外
// 形成 TOCTOU 窗口。公开查询与事务查询共享回放实现，保持两个入口同一把尺。
func (s *Store) cardStepInFlightTx(tx *sql.Tx, cardID string) (bool, string, error) {
	return s.cardStepInFlightQuery(tx, cardID)
}

n_ledger_Store_checkParentTx.signature:
// checkParentTx 校验父卡存在且同名工作流嵌套未超限。
//
// 参数：parent 父卡 id（空串直接放行）；workflowName 新卡要绑的工作流名。
// 返回：父卡不存在返回包装 ErrNotFound 的错误，嵌套超限返回包装 ErrBadState 的错误。
func (s *Store) checkParentTx(tx *sql.Tx, parent, workflowName string) error {
	if parent == "" {
		return nil
	}
	if _, err := getCardTx(s, tx, parent); err != nil {
		return fmt.Errorf("父卡 %s: %w", parent, err)
	}
	nesting, err := s.workflowNestingTx(tx, parent, workflowName)
	if err != nil {
		return err
	}
	if nesting+1 > maxWorkflowNesting {
		log().Warn("建卡被拒：工作流嵌套超限",
			"parent", parent, "workflow", workflowName, "nesting", nesting)
		return fmt.Errorf("父链上已有 %d 层 %q 工作流（上限 %d）——先竖切域或给子卡换更细粒度的工作流: %w",
			nesting, workflowName, maxWorkflowNesting, ErrBadState)
	}
	return nil
}

n_ledger_Store_checkWorkflowGateTx.signature:
// checkWorkflowGateTx 检查进入 workflow 的 to 列所需的全部 gate。
// moveCardTx 与 MigrateCardWorkflow 必须共用这里，避免新增 gate 时两条入口
// 分裂；action 只区分日志前缀，检查顺序、错误文案和 ErrGateBlocked 保持一致。
func (s *Store) checkWorkflowGateTx(tx *sql.Tx, card Card, workflow Workflow, to, action string) error {
	gate, ok := workflow.Def.Gates[to]
	if !ok {
		return nil
	}
	if gate.RequireAttachment != "" && !cardHasAttachmentKind(card, gate.RequireAttachment) {
		log().Warn(action+"被拒：gate 缺附件", "card", card.ID, "to", to, "need", gate.RequireAttachment)
		return fmt.Errorf("进 %q 需要 %s 附件（当前没有）: %w", to, gate.RequireAttachment, ErrGateBlocked)
	}

	if len(gate.RequireAttachmentAny) > 0 {
		matched := false
		for _, kind := range gate.RequireAttachmentAny {
			if cardHasAttachmentKind(card, kind) {
				matched = true
				break
			}
		}
		if !matched {
			need := strings.Join(gate.RequireAttachmentAny, " 或 ")
			log().Warn(action+"被拒：gate 缺附件（择一）", "card", card.ID, "to", to, "need", need)
			return fmt.Errorf("进 %q 需要 %s 附件之一（当前都没有）: %w", to, need, ErrGateBlocked)
		}
	}
	if gate.RequireAcceptance && card.AcceptanceCriteria == "" {
		log().Warn(action+"被拒：gate 缺判据", "card", card.ID, "to", to)
		return fmt.Errorf("进 %q 需要验收判据非空: %w", to, ErrGateBlocked)
	}
	if gate.RequireChildrenDone {
		pending, err := s.pendingChildrenTx(tx, card.ID)
		if err != nil {
			return err
		}
		if len(pending) > 0 {
			log().Warn(action+"被拒：聚合闸有未完结子卡", "card", card.ID, "to", to, "pending", pending)
			return fmt.Errorf("进 %q 需全部子卡完结，未完结: %s: %w",
				to, strings.Join(pending, ", "), ErrGateBlocked)
		}
	}
	return nil
}

n_ledger_Store_effectiveBaseTx.signature:
func (s *Store) effectiveBaseTx(tx *sql.Tx, id string) (string, error) {
	current := id
	for i := 0; i < 64; i++ {
		var base, parent sql.NullString
		err := tx.QueryRow(s.q(`SELECT base_branch, parent_id FROM cards WHERE id = ?`), current).Scan(&base, &parent)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return "", fmt.Errorf("卡 %s: %w", current, ErrNotFound)
			}
			return "", fmt.Errorf("读基线: %w", err)
		}
		if base.Valid && strings.TrimSpace(base.String) != "" {
			return base.String, nil
		}
		if !parent.Valid || parent.String == "" {
			return "", nil
		}
		current = parent.String
	}
	return "", fmt.Errorf("父链深度超限: %s", id)
}

n_ledger_Store_ensureSchema.signature:
// ensureSchema 幂等建表。与 internal/store 相同的策略：CREATE IF NOT
// EXISTS 列表顺序执行，无版本号——幂等即契约；后续加列走「ALTER +
// 容忍 duplicate column」。
func (s *Store) ensureSchema() error {
	for _, stmt := range ddlStatements(s.dialect == dialectPG) {
		if _, err := s.db.Exec(stmt); err != nil {
			short := stmt
			if len(short) > 40 {
				short = short[:40]
			}
			return fmt.Errorf("执行 DDL %q: %w", short, err)
		}
	}

	if _, err := s.db.Exec(`ALTER TABLE cards ADD COLUMN driver_carrier TEXT`); err != nil {
		msg := err.Error()
		if !strings.Contains(msg, "duplicate column") && !strings.Contains(msg, "already exists") {
			return fmt.Errorf("迁移 cards.driver_carrier: %w", err)
		}
		log().Info("cards.driver_carrier 列已存在，跳过加列")
	} else {
		log().Info("账本加列迁移完成", "table", "cards", "column", "driver_carrier")
	}
	if _, err := s.db.Exec(`ALTER TABLE cards ADD COLUMN driver_source TEXT`); err != nil {
		msg := err.Error()
		if !strings.Contains(msg, "duplicate column") && !strings.Contains(msg, "already exists") {
			log().Warn("账本加列迁移失败", "table", "cards", "column", "driver_source", "dialect", map[bool]string{true: "postgres", false: "sqlite"}[s.dialect == dialectPG], "cause", err)
			return fmt.Errorf("迁移 cards.driver_source: %w", err)
		}
		log().Info("cards.driver_source 列已存在，跳过加列")
	} else {
		log().Info("账本加列迁移完成", "table", "cards", "column", "driver_source")
	}
	return nil
}

n_ledger_Store_getWorkflowStored.signature:
// getWorkflowStored 读取工作流存储的原始定义，不做老 def 的 Nodes 投影。
//
// 参数：name 工作流名；version==0 取最新版。返回：数据库中的 Workflow，
// 找不到返回 ErrNotFound。注意：仅供 Store 内部判定存储形态；对外读取必须
// 使用 GetWorkflow，保持老 def 也能被消费方当作节点形态使用的兼容语义。
func (s *Store) getWorkflowStored(name string, version int) (Workflow, error) {
	q := `SELECT name, version, definition, created_at FROM workflows WHERE name = ?`
	args := []any{name}
	if version > 0 {
		q += ` AND version = ?`
		args = append(args, version)
	}
	q += ` ORDER BY version DESC LIMIT 1`
	row := s.db.QueryRow(s.q(q), args...)
	var workflow Workflow
	var raw string
	var createdAt any
	if err := row.Scan(&workflow.Name, &workflow.Version, &raw, &createdAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return Workflow{}, fmt.Errorf("工作流 %s v%d: %w", name, version, ErrNotFound)
		}
		return Workflow{}, fmt.Errorf("读工作流: %w", err)
	}
	if err := jsonUnmarshal(raw, &workflow.Def); err != nil {
		return Workflow{}, fmt.Errorf("解码工作流定义: %w", err)
	}
	workflow.CreatedAt = toTime(createdAt)
	return workflow, nil
}

n_ledger_Store_getWorkflowTx.signature:
// getWorkflowTx 事务内取指定版本工作流（Move 的 gate 判定必须与写同事务）。
func (s *Store) getWorkflowTx(tx *sql.Tx, name string, version int) (Workflow, error) {
	row := tx.QueryRow(s.q(`SELECT name, version, definition, created_at FROM workflows
		WHERE name = ? AND version = ?`), name, version)
	var workflow Workflow
	var raw string
	var createdAt any
	if err := row.Scan(&workflow.Name, &workflow.Version, &raw, &createdAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return Workflow{}, fmt.Errorf("工作流 %s v%d: %w", name, version, ErrNotFound)
		}
		return Workflow{}, fmt.Errorf("读工作流 %s v%d: %w", name, version, err)
	}
	if err := jsonUnmarshal(raw, &workflow.Def); err != nil {
		return Workflow{}, err
	}
	workflow.CreatedAt = toTime(createdAt)
	return workflow, nil
}

n_ledger_Store_insertCardTx.signature:
// insertCardTx 事务内落卡：插行 + card_created 事件 + 子卡时父卡 timeline 留痕。
//
// 参数：id 已定好的卡号；nc 已过 prepareCard 的请求；wf 钉定版本的工作流；
// extra 并入 card_created 负载的附加字段（导入通道用来标注来源，普通建卡传 nil）。
// 返回：建成的卡（内存态，字段与刚插入的行一致）。
func (s *Store) insertCardTx(tx *sql.Tx, sink *eventSink, id string, nc NewCard, wf Workflow, extra map[string]any) (Card, error) {
	now := time.Now()
	var parent any
	if nc.Parent != "" {
		parent = nc.Parent
	}
	var base any
	if nc.BaseBranch != "" {
		base = nc.BaseBranch
	}
	_, err := tx.Exec(s.q(`INSERT INTO cards
		(id, title, status, priority, project, parent_id, workflow_name, workflow_version,
		 attachments, acceptance_criteria, base_branch, created_at, updated_at)
		VALUES (?,?,?,?,?,?,?,?,'[]','',?,?,?)`),
		id, nc.Title, wf.Def.States[0], nc.Priority, nc.Project, parent,
		wf.Name, wf.Version, base, s.tval(now), s.tval(now))
	if err != nil {
		return Card{}, fmt.Errorf("插入卡 %s: %w", id, err)
	}
	payload := map[string]any{"title": nc.Title, "workflow": wf.Name, "workflow_version": wf.Version}
	maps.Copy(payload, extra)
	if _, err := s.appendEvent(tx, sink, id, EvCardCreated, nc.Actor, payload); err != nil {
		return Card{}, err
	}

	if nc.Parent != "" {
		if _, err := s.appendEvent(tx, sink, nc.Parent, EvComment, nc.Actor,
			map[string]any{"kind": "普通",
				"body":	fmt.Sprintf("创建子卡 %s：%s", id, nc.Title),
				"refs":	[]string{id}}); err != nil {
			return Card{}, err
		}
	}
	return Card{ID: id, Title: nc.Title, Status: wf.Def.States[0], Priority: nc.Priority,
		Project:	nc.Project, ParentID: nc.Parent, WorkflowName: wf.Name,
		WorkflowVersion:	wf.Version, BaseBranch: nc.BaseBranch, CreatedAt: now, UpdatedAt: now}, nil
}

n_ledger_Store_mergedIntoTx.signature:
// mergedIntoTx 查卡当前并入的承载卡（"" = 未并入）。也承担 SQLite 侧
// 「一卡至多一条 merged_into」的应用层校验职责（PG 有 partial unique
// index 兜底，SQLite 靠 MergeCards 的先查后插 + 全局写锁保证）。
func (s *Store) mergedIntoTx(tx *sql.Tx, id string) (string, error) {
	var carrier string
	err := tx.QueryRow(s.q(`SELECT to_id FROM card_relations WHERE from_id = ? AND type = ?`),
		id, RelMergedInto).Scan(&carrier)
	if errors.Is(err, sql.ErrNoRows) {
		return "", nil
	}
	if err != nil {
		return "", fmt.Errorf("查并入: %w", err)
	}
	return carrier, nil
}

n_ledger_Store_moveCardTx.signature:
// moveCardTx 事务内的转移实现。状态读取、workflow gate 与状态写入必须共用
// 一个事务，避免并发转移依据过期状态放行。
func (s *Store) moveCardTx(tx *sql.Tx, sink *eventSink, id, to, expect, actor string) error {
	{
		card, err := getCardTx(s, tx, id)
		if err != nil {
			return fmt.Errorf("转移: 卡 %s: %w", id, err)
		}
		if card.Status == StatusDone || card.Status == StatusClosed {
			log().Warn("转移被拒：终态卡", "card", id, "status", card.Status)
			return fmt.Errorf("卡 %s 已处于终态 %s: %w", id, card.Status, ErrBadState)
		}
		if expect != "" && card.Status != expect {
			log().Warn("转移被拒：CAS 冲突", "card", id, "expect", expect, "actual", card.Status)
			return fmt.Errorf("卡 %s 当前是 %q 非 %q: %w", id, card.Status, expect, ErrCASConflict)
		}
		workflow, err := s.getWorkflowTx(tx, card.WorkflowName, card.WorkflowVersion)
		if err != nil {
			return fmt.Errorf("转移取工作流: %w", err)
		}
		found := false
		for _, state := range workflow.Def.States {
			if state == to {
				found = true
				break
			}
		}
		if !found {

			log().Warn("转移被拒：未知状态", "card", id, "to", to)
			return fmt.Errorf("状态 %q 不在工作流 %s v%d 中: %w", to, workflow.Name, workflow.Version, ErrBadState)
		}
		if err := s.checkWorkflowGateTx(tx, card, workflow, to, "转移"); err != nil {
			return err
		}

		result, err := tx.Exec(s.q(`UPDATE cards SET status = ?, updated_at = ? WHERE id = ? AND status = ?`),
			to, s.tval(time.Now()), id, card.Status)
		if err != nil {
			return fmt.Errorf("写转移: %w", err)
		}
		if count, _ := result.RowsAffected(); count == 0 {
			return fmt.Errorf("卡 %s 状态已被并发修改: %w", id, ErrCASConflict)
		}
		_, err = s.appendEvent(tx, sink, id, EvStatusMoved, actor,
			map[string]any{"from": card.Status, "to": to})
		return err
	}
}

n_ledger_Store_mutate.signature:
// mutate 写事务包裹：PG 先拿全局 advisory lock 串行化全部账本写
// （B 号分配的 max+1、环检测的读全图、合并校验都要求读-判-写原子；
// 写 QPS 极小，一把粗锁换正确性，蓝图 §3.1 记过这笔账）；SQLite 由
// 单写者天然串行。fn 内经 sink append 的事件在提交后触发本地 listeners。
func (s *Store) mutate(fn func(tx *sql.Tx, sink *eventSink) error) error {
	tx, err := s.db.Begin()
	if err != nil {
		return fmt.Errorf("开账本事务: %w", err)
	}
	defer tx.Rollback()
	if s.dialect == dialectPG {
		if _, err := tx.Exec(`SELECT pg_advisory_xact_lock(915601)`); err != nil {
			return fmt.Errorf("取账本写锁: %w", err)
		}
	}
	sink := &eventSink{}
	if err := fn(tx, sink); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("提交账本事务: %w", err)
	}
	if s.dialect == dialectSQLite && len(sink.seqs) > 0 {
		s.mu.Lock()
		listeners := append([]func(int64){}, s.listeners...)
		s.mu.Unlock()
		for _, listener := range listeners {
			for _, seq := range sink.seqs {
				listener(seq)
			}
		}
	}
	return nil
}

n_ledger_Store_needsMap.signature:
// needsMap 每卡最后一条 needs_human/needs_cleared 决定当前等人态。
// 单卡最多几十条事件、卡数百张，直接扫两类事件按 seq 归并即可。
func (s *Store) needsMap() (map[string]string, error) {
	rows, err := s.db.Query(s.q(`SELECT card_id, type, payload FROM card_events
		WHERE type IN (?, ?) AND card_id IS NOT NULL ORDER BY seq ASC`), EvNeedsHuman, EvNeedsCleared)
	if err != nil {
		return nil, fmt.Errorf("读等人事件: %w", err)
	}
	defer rows.Close()
	needs := map[string]string{}
	for rows.Next() {
		var cardID, typ, payload string
		if err := rows.Scan(&cardID, &typ, &payload); err != nil {
			return nil, err
		}
		if typ == EvNeedsCleared {
			delete(needs, cardID)
			continue
		}
		var data struct {
			Reason string `json:"reason"`
		}
		if err := jsonUnmarshal(payload, &data); err != nil {
			return nil, err
		}
		needs[cardID] = data.Reason
	}
	return needs, rows.Err()
}

n_ledger_Store_nextChildID.signature:
// nextChildID 分配 parent 下一个点号子位（C1 → C1.1、C1.2…）。
func (s *Store) nextChildID(tx *sql.Tx, parent string) (string, error) {
	rows, err := tx.Query(s.q(`SELECT id FROM cards WHERE parent_id = ?`), parent)
	if err != nil {
		return "", fmt.Errorf("扫子卡号: %w", err)
	}
	defer rows.Close()
	maxNumber := 0
	prefix := parent + "."
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return "", err
		}
		if rest, ok := strings.CutPrefix(id, prefix); ok {
			if number, err := strconv.Atoi(rest); err == nil && number > maxNumber {
				maxNumber = number
			}
		}
	}
	if err := rows.Err(); err != nil {
		return "", err
	}
	return fmt.Sprintf("%s.%d", parent, maxNumber+1), nil
}

n_ledger_Store_nextSessionSeqTx.signature:
// nextSessionSeqTx 事务内分配下一个会话号（读-增-写 ledger_meta 计数器）。
func (s *Store) nextSessionSeqTx(tx *sql.Tx) (int64, error) {
	var raw string
	err := tx.QueryRow(s.q(`SELECT value FROM ledger_meta WHERE key = ?`), sessionCounterKey).Scan(&raw)
	current := int64(0)
	if err == nil {
		current, _ = strconv.ParseInt(raw, 10, 64)
	} else if !errors.Is(err, sql.ErrNoRows) {
		return 0, fmt.Errorf("读会话号水位: %w", err)
	}
	next := current + 1
	if _, err := tx.Exec(s.q(`INSERT INTO ledger_meta (key, value) VALUES (?, ?)
		ON CONFLICT (key) DO UPDATE SET value = excluded.value`), sessionCounterKey, strconv.FormatInt(next, 10)); err != nil {
		return 0, fmt.Errorf("写会话号水位: %w", err)
	}
	return next, nil
}

n_ledger_Store_nextTopID.signature:
// nextTopID 事务内分配下一个指定前缀的顶层号：
// max(该前缀现存顶层号, B 前缀的 min_b 水位) + 1。
// 号永不复用（终止/归档的卡仍占号）。在 mutate 的全局写锁内调用，
// 无并发分配竞态。min_b 只对 B 前缀生效，其它前缀从 1 起步。
func (s *Store) nextTopID(tx *sql.Tx, prefix string) (string, error) {
	maxNumber := 0
	rows, err := tx.Query(`SELECT id FROM cards WHERE parent_id IS NULL`)
	if err != nil {
		return "", fmt.Errorf("扫现存 %s 号: %w", prefix, err)
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return "", fmt.Errorf("扫现存 %s 号时读卡: %w", prefix, err)
		}
		if match := topIDPat.FindStringSubmatch(id); match != nil {
			if match[1] != prefix {
				continue
			}
			if number, _ := strconv.Atoi(match[2]); number > maxNumber {
				maxNumber = number
			}
		}
	}
	if err := rows.Err(); err != nil {
		return "", fmt.Errorf("扫现存 %s 号: %w", prefix, err)
	}
	var value string
	if prefix == "B" {
		if err := tx.QueryRow(s.q(`SELECT value FROM ledger_meta WHERE key = 'min_b'`)).Scan(&value); err == nil {
			if number, _ := strconv.Atoi(value); number > maxNumber {
				maxNumber = number
			}
		} else if !errors.Is(err, sql.ErrNoRows) {
			return "", fmt.Errorf("读 B 前缀水位 min_b: %w", err)
		}
	}
	return fmt.Sprintf("%s%d", prefix, maxNumber+1), nil
}

n_ledger_Store_openDecisionCount.signature:
// openDecisionCount 每卡 open 裁决数（decisions 表在 Task 10 前恒空，
// 查询天然返回空 map，不需要桩）。
func (s *Store) openDecisionCount() (map[string]int, error) {
	rows, err := s.db.Query(`SELECT card_id, COUNT(*) FROM decisions
		WHERE status = 'open' AND card_id IS NOT NULL GROUP BY card_id`)
	if err != nil {
		return nil, fmt.Errorf("读裁决计数: %w", err)
	}
	defer rows.Close()
	counts := map[string]int{}
	for rows.Next() {
		var cardID sql.NullString
		var count int
		if err := rows.Scan(&cardID, &count); err != nil {
			return nil, err
		}
		if cardID.Valid {
			counts[cardID.String] = count
		}
	}
	return counts, rows.Err()
}

n_ledger_Store_pendingChildrenTx.signature:
// pendingChildrenTx 事务内取未完结（非 已完成/终止）的直接子卡 id 列表。
// 与转移同事务读：闸判定和状态写之间不留「子卡刚好在窗口里完结/复活」的缝。
func (s *Store) pendingChildrenTx(tx *sql.Tx, id string) ([]string, error) {
	rows, err := tx.Query(s.q(`SELECT id, status FROM cards WHERE parent_id = ?`), id)
	if err != nil {
		return nil, fmt.Errorf("聚合闸读子卡: %w", err)
	}
	defer rows.Close()
	var pending []string
	for rows.Next() {
		var childID, status string
		if err := rows.Scan(&childID, &status); err != nil {
			return nil, err
		}
		if status != StatusDone && status != StatusClosed {
			pending = append(pending, childID)
		}
	}
	return pending, rows.Err()
}

n_ledger_Store_prepareCard.signature:
// prepareCard 校验建卡请求并补默认值（优先级缺省「中」、工作流按账本现有流解析），
// 取回要钉住的工作流版本。
//
// 参数：nc 建卡请求（就地补默认，故取指针）。
// 返回：钉定版本的工作流；标题/project 为空、工作流不存在或状态序列为空时报错。
//
// 注意：只做纯校验与取流，不开事务——CreateCard 与 ImportCard 共用它，
// 保证两条通道的入参语义逐字一致（差别只在 id 从哪来）。
func (s *Store) prepareCard(nc *NewCard) (Workflow, error) {
	if strings.TrimSpace(nc.Title) == "" {
		return Workflow{}, fmt.Errorf("建卡: 标题不能为空")
	}
	if nc.Project == "" {
		return Workflow{}, fmt.Errorf("建卡: project 不能为空")
	}
	if nc.Priority == "" {
		nc.Priority = "中"
	}
	if strings.TrimSpace(nc.Workflow) == "" {
		log().Info("建卡解析缺省工作流", "project", nc.Project, "title", nc.Title)
		names, err := s.ListWorkflowNames()
		if err != nil {
			log().Error("建卡列工作流失败", "project", nc.Project, "title", nc.Title, "cause", err)
			return Workflow{}, fmt.Errorf("建卡解析缺省工作流: 列工作流失败: %w", err)
		}
		switch len(names) {
		case 0:
			err := fmt.Errorf("建卡缺少工作流：账本中没有工作流，请先用 workflow put 建立一条工作流")
			log().Warn("建卡被拒：账本没有工作流", "project", nc.Project, "title", nc.Title)
			return Workflow{}, err
		case 1:
			nc.Workflow = names[0]
			log().Info("建卡采用唯一工作流", "project", nc.Project, "title", nc.Title, "workflow", nc.Workflow)
		default:
			err := fmt.Errorf("建卡缺少工作流：账本中有多条工作流，请显式指定 --workflow（可选：%s）", strings.Join(names, "、"))
			log().Warn("建卡被拒：缺省工作流有歧义", "project", nc.Project, "title", nc.Title, "workflows", names)
			return Workflow{}, err
		}
	}
	wf, err := s.GetWorkflow(nc.Workflow, 0)
	if err != nil {
		return Workflow{}, fmt.Errorf("建卡取工作流 %q: %w", nc.Workflow, err)
	}
	if len(wf.Def.States) == 0 {
		return Workflow{}, fmt.Errorf("建卡取工作流 %q: 状态序列不能为空", nc.Workflow)
	}
	return wf, nil
}

n_ledger_Store_projectTaskLinks.signature:
// projectTaskLinks 把 workflow 身份作为读取投影加入 card_tasks 行。
// 为什么按卡事件逐条取最新快照：card_tasks 是跨机弱引用，不能扩列或把派发
// 事实复制成第二权威；事件顺序同时保证重试后最新快照会覆盖旧身份。
func (s *Store) projectTaskLinks(cardID string, links []TaskLink) ([]TaskLink, error) {
	if len(links) == 0 {
		return links, nil
	}
	query := `SELECT seq, card_id, payload FROM card_events WHERE type = ?`
	args := []any{EvDispatched}
	if cardID != "" {
		query += ` AND card_id = ?`
		args = append(args, cardID)
	}
	query += ` ORDER BY seq ASC`
	rows, err := s.db.Query(s.q(query), args...)
	if err != nil {
		log().Warn("读派发快照投影失败", "card", cardID, "node", "", "attempt", "",
			"target", "", "task", "", "seq", 0, "type", EvDispatched, "cause", err)
		return nil, fmt.Errorf("读派发快照投影: %w", err)
	}
	defer rows.Close()
	projections := make(map[string]dispatchProjection)
	for rows.Next() {
		var eventSeq int64
		var eventCard, raw string
		if err := rows.Scan(&eventSeq, &eventCard, &raw); err != nil {
			log().Warn("扫描派发快照投影失败", "card", cardID, "node", "", "attempt", "",
				"target", "", "task", "", "seq", eventSeq, "type", EvDispatched, "cause", err)
			return nil, fmt.Errorf("扫描派发快照投影: %w", err)
		}
		var snapshot DispatchSnapshot
		if err := json.Unmarshal([]byte(raw), &snapshot); err != nil {
			log().Warn("派发快照投影解码失败，保留空身份", "card", eventCard,
				"node", "", "attempt", "", "target", "", "task", "", "seq", eventSeq,
				"type", EvDispatched, "cause", err)
			continue
		}
		key := eventCard + "\x00" + snapshot.Target + "\x00" + snapshot.TaskID
		projection := dispatchProjection{Seq: eventSeq}
		if snapshot.Node != "" && snapshot.Attempt != "" {
			projection.Node = snapshot.Node
			projection.Attempt = snapshot.Attempt
		}
		projections[key] = projection
	}
	if err := rows.Err(); err != nil {
		log().Warn("读取派发快照投影行失败", "card", cardID, "node", "", "attempt", "",
			"target", "", "task", "", "seq", 0, "type", EvDispatched, "cause", err)
		return nil, fmt.Errorf("读派发快照投影: %w", err)
	}
	for i := range links {
		key := links[i].CardID + "\x00" + links[i].Target + "\x00" + links[i].TaskID
		projection, ok := projections[key]
		if !ok {
			log().Debug("挂账没有匹配派发快照，保留空身份", "card", links[i].CardID,
				"node", links[i].Node, "attempt", links[i].Attempt, "target", links[i].Target,
				"task", links[i].TaskID, "seq", 0, "type", EvDispatched)
			continue
		}
		links[i].Node = projection.Node
		links[i].Attempt = projection.Attempt
		log().Debug("挂账派发身份投影完成", "card", links[i].CardID, "node", links[i].Node,
			"attempt", links[i].Attempt, "target", links[i].Target, "task", links[i].TaskID,
			"seq", projection.Seq, "type", EvDispatched)
	}
	log().Debug("挂账派发身份投影完成", "card", cardID, "links", len(links))
	return links, nil
}

n_ledger_Store_q.signature:
// q 把 ? 占位符重写为 PG 的 $N。仅做占位符转换，不做任何转义——
// SQL 里不许出现字面 '?'（本包 SQL 全部自控，无用户拼接）。
func (s *Store) q(query string) string {
	if s.dialect != dialectPG {
		return query
	}
	var b strings.Builder
	n := 0
	for _, r := range query {
		if r == '?' {
			n++
			fmt.Fprintf(&b, "$%d", n)
		} else {
			b.WriteRune(r)
		}
	}
	return b.String()
}

n_ledger_Store_timeNow.signature:
// timeNow 取当前时间：测试注入了 now 就用假时钟，否则真实壁钟。
func (s *Store) timeNow() time.Time {
	if s.now != nil {
		return s.now()
	}
	return time.Now()
}

n_ledger_Store_tval.signature:
// tval 时间入库编码：PG 直接传 time.Time（timestamptz），SQLite 存
// RFC3339Nano 文本。
func (s *Store) tval(t time.Time) any {
	if s.dialect == dialectPG {
		return t.UTC()
	}
	return t.UTC().Format(time.RFC3339Nano)
}

n_ledger_Store_validateNodes.signature:
// validateNodes 校验节点序列的内部一致性。
//
// 参数：nodes 节点序列（可为空，空 = 老 def 形态，不校验）。
// 返回：第一处违规的错误（包装 ErrBadState，供 HTTP 层翻成 400）；全部合法返回 nil。
//
// 校验范围**刻意只覆盖 Store 看得见的东西**：模板存在性能查（同一个库），
// 纪律块存在性查不了（正文在 agentd 的 DataDir 下，Store 不认识文件系统），
// 那一项留给派发时报错。把校验硬塞进来只会让 Store 依赖 agentd 的目录布局。
func (s *Store) validateNodes(nodes []NodeDef) error {
	if len(nodes) == 0 {
		return nil
	}
	seen := make(map[string]bool, len(nodes))
	for _, node := range nodes {
		if node.Name == "" {
			return fmt.Errorf("节点名不能为空: %w", ErrBadState)
		}
		if seen[node.Name] {
			return fmt.Errorf("节点名 %q 重复: %w", node.Name, ErrBadState)
		}
		seen[node.Name] = true
	}
	for _, node := range nodes {

		if node.Verdict && !node.Dispatch {
			return fmt.Errorf("节点 %q 开了 Verdict 却没开 Dispatch（没有派发就没有报文可裁决）: %w",
				node.Name, ErrBadState)
		}
		if node.Dispatch && node.Template == "" {
			return fmt.Errorf("节点 %q 开了 Dispatch 但没写模板: %w", node.Name, ErrBadState)
		}
		if node.Dispatch {
			if _, err := s.GetTemplate(node.Template, 0); err != nil {
				return fmt.Errorf("节点 %q 引用的模板 %q 不可用: %w", node.Name, node.Template, ErrBadState)
			}
		}
		if node.MaxRounds < 0 {
			return fmt.Errorf("节点 %q 的 MaxRounds 不能为负: %w", node.Name, ErrBadState)
		}
		if node.MaxRounds > 0 && !node.Verdict {
			return fmt.Errorf("节点 %q 设了 MaxRounds 却没开 Verdict（不裁决就没有轮次）: %w",
				node.Name, ErrBadState)
		}
		if node.Produces != nil {
			if strings.TrimSpace(node.Produces.Kind) == "" || strings.TrimSpace(node.Produces.Path) == "" {
				return fmt.Errorf("节点 %q 的 produces 必须同时填写 kind 和 path: %w",
					node.Name, ErrBadState)
			}
		}
		if node.OnFail != "" && !node.Verdict {
			return fmt.Errorf("节点 %q 设了 OnFail 却没开 Verdict（不裁决就没有失败分支）: %w",
				node.Name, ErrBadState)
		}

		for label, to := range map[string]string{"Next": node.Next, "OnFail": node.OnFail} {
			if to == "" || seen[to] {
				continue
			}
			return fmt.Errorf("节点 %q 的 %s 指向不存在的节点 %q: %w",
				node.Name, label, to, ErrBadState)
		}
	}
	return nil
}

n_ledger_Store_workflowNestingTx.signature:
// workflowNestingTx 数父链（从 parent 起向上、含 parent 自身）里钉了
// 同名工作流的卡数。64 层上限与 ancestorsTx 同源：防坏数据成环死循环。
func (s *Store) workflowNestingTx(tx *sql.Tx, parent, workflowName string) (int, error) {
	count := 0
	current := parent
	for i := 0; i < 64; i++ {
		var name string
		var up sql.NullString
		err := tx.QueryRow(s.q(`SELECT workflow_name, parent_id FROM cards WHERE id = ?`), current).
			Scan(&name, &up)
		if err != nil {
			if errors.Is(err, sql.ErrNoRows) {
				return count, nil
			}
			return 0, fmt.Errorf("数工作流嵌套: 读卡 %s: %w", current, err)
		}
		if name == workflowName {
			count++
		}
		if !up.Valid || up.String == "" {
			return count, nil
		}
		current = up.String
	}
	return 0, fmt.Errorf("父链深度超限（数据疑似成环）: %s", parent)
}

n_ledger_WorkflowDef_withNodesFromStates.signature:
// withNodesFromStates 为只有 States 的老 def 补出等价节点序列（读取侧）。
//
// 参数：无（值接收者）。返回：补齐 Nodes 的副本；Nodes 非空时原样返回。
// 补出的节点全部是纯人工列（所有能力开关关闭），Next 按 States 顺序串起来，
// 末节点无 Next——与老 def 在界面上的行为完全一致。
func (d WorkflowDef) withNodesFromStates() WorkflowDef {
	if len(d.Nodes) > 0 || len(d.States) == 0 {
		return d
	}
	nodes := make([]NodeDef, 0, len(d.States))
	for i, state := range d.States {
		node := NodeDef{Name: state, Gate: d.Gates[state]}
		if i+1 < len(d.States) {
			node.Next = d.States[i+1]
		}
		nodes = append(nodes, node)
	}
	d.Nodes = nodes
	return d
}

n_ledger_WorkflowDef_withStatesFromNodes.signature:
// withStatesFromNodes 把 Nodes 投影成 States/Gates（写入侧）。
//
// 参数：无（值接收者）。返回：投影后的副本；Nodes 为空时原样返回。
// 注意：会**覆盖**调用方传入的 States/Gates——Nodes 在场时它们是派生物，
// 允许两者不一致等于允许账本自相矛盾。
func (d WorkflowDef) withStatesFromNodes() WorkflowDef {
	if len(d.Nodes) == 0 {
		return d
	}
	states := make([]string, 0, len(d.Nodes))
	gates := make(map[string]Gate, len(d.Nodes))
	for _, node := range d.Nodes {
		states = append(states, node.Name)

		if !reflect.DeepEqual(node.Gate, Gate{}) {
			gates[node.Name] = node.Gate
		}
	}
	d.States = states
	if len(gates) == 0 {
		gates = nil
	}
	d.Gates = gates
	return d
}

