//
// 只按 basename 匹配已知的三个出厂文件名：用户自定义的路径指向的是什么纪律
// 我们不知道，猜错比退回兜底更危险。
func disciplineNameFromLegacyPath(path string) string {
	if path == "" {
		return ""
	}
	return legacyDisciplinePaths[filepath.Base(path)]
}

