func encodeMembers(members []string) (string, error) {
	if len(members) == 0 {
		return "[]", nil
	}
	raw, err := json.Marshal(members)
	if err != nil {
		return "", fmt.Errorf("编码会话成员: %w", err)
	}
	return string(raw), nil
}

n_ledger_firstASCIILetter.signature:
// firstASCIILetter 取 project 中第一个 ASCII 字母并转成大写。
// 非 ASCII 字母不参与推导，刻意让中文名/纯数字名走显式配置，避免
// 不透明的拼音或随机回退破坏「看到前缀即可定位项目」的约定。
func firstASCIILetter(project string) string {
	for i := 0; i < len(project); i++ {
		c := project[i]
		if c >= 'a' && c <= 'z' {
			return string(c - ('a' - 'A'))
		}
		if c >= 'A' && c <= 'Z' {
			return string(c)
		}
	}
	return ""
}

