n_ledger_parseBool.signature:
// parseBool 兼容 PG bool 与 SQLite INTEGER 两方言的扫描产物。
func parseBool(v any) bool {
	switch t := v.(type) {
	case bool:
		return t
	case int64:
		return t != 0
	case int:
		return t != 0
	case string:
		return t == "1" || t == "true"
	case []byte:
		return string(t) == "1" || string(t) == "true"
	}
	return false
}

n_ledger_redactDSN.signature:
// redactDSN 保留 Open 日志需要的目标定位信息，同时不把 PG URL 中的密码
// 写进日志；SQLite 路径没有凭据，原样保留。
func redactDSN(dsn string, d dialect) string {
	if d != dialectPG {
		return dsn
	}
	u, err := url.Parse(dsn)
	if err != nil {
		return "<postgres dsn>"
	}
	if u.User != nil {
		u.User = url.User(u.User.Username())
	}
	return u.String()
}

n_ledger_scanCard.signature:
func scanCard(row rowScanner) (Card, error) {
	var card Card
	var terminateReason, parentID, acceptanceCriteria, baseBranch, driverSession, driverSource sql.NullString
	var attachments string
	var heartbeatAt, createdAt, updatedAt any
	if err := row.Scan(&card.ID, &card.Title, &card.Status, &terminateReason, &card.Priority,
		&card.Project, &parentID, &card.WorkflowName, &card.WorkflowVersion, &attachments,
		&acceptanceCriteria, &baseBranch, &driverSession, &driverSource, &heartbeatAt, &createdAt, &updatedAt); err != nil {
		return Card{}, err
	}
	card.TerminateReason, card.ParentID, card.AcceptanceCriteria = terminateReason.String, parentID.String, acceptanceCriteria.String
	card.BaseBranch, card.DriverSession, card.DriverSource = baseBranch.String, driverSession.String, driverSource.String
	if err := json.Unmarshal([]byte(attachments), &card.Attachments); err != nil {
		return Card{}, fmt.Errorf("解码附件: %w", err)
	}
	card.DriverHeartbeatAt, card.CreatedAt, card.UpdatedAt = toTime(heartbeatAt), toTime(createdAt), toTime(updatedAt)
	return card, nil
}

n_ledger_scanDecisions.signature:
// scanDecisions 把结果集扫成 Decision 切片；调用方负责 rows 的来源，本函数负责关闭。
func scanDecisions(rows *sql.Rows) ([]Decision, error) {
	defer rows.Close()
	var out []Decision
	for rows.Next() {
		var decision Decision
		var cardID, options, answer, answeredBy sql.NullString
		var createdAt, answeredAt any
		if err := rows.Scan(&decision.ID, &cardID, &decision.Body, &options, &decision.Status,
			&decision.CreatedBy, &answer, &answeredBy, &createdAt, &answeredAt); err != nil {
			return nil, fmt.Errorf("扫裁决行: %w", err)
		}
		decision.CardID, decision.Answer, decision.AnsweredBy = cardID.String, answer.String, answeredBy.String
		if options.Valid && options.String != "" {
			if err := jsonUnmarshal(options.String, &decision.Options); err != nil {
				return nil, err
			}
		}
		decision.CreatedAt, decision.AnsweredAt = toTime(createdAt), toTime(answeredAt)
		out = append(out, decision)
	}
	return out, rows.Err()
}

n_ledger_scanSession.signature:
func scanSession(row rowScanner) (Session, error) {
	var session Session
	var archived any
	var members string
	var createdAt, updatedAt any
	if err := row.Scan(&session.ID, &session.Title, &session.Owner, &archived, &members, &createdAt, &updatedAt); err != nil {
		return Session{}, err
	}
	session.Archived = parseBool(archived)
	decoded, err := decodeMembers(members)
	if err != nil {
		return Session{}, fmt.Errorf("解码会话 %s 成员: %w", session.ID, err)
	}
	session.Members = decoded
	session.CreatedAt, session.UpdatedAt = toTime(createdAt), toTime(updatedAt)
	return session, nil
}

