n_ledger_toTime.signature:
// toTime 时间出库解码，兼容两方言的扫描产物。
func toTime(v any) time.Time {
	switch t := v.(type) {
	case time.Time:
		return t
	case string:
		parsed, _ := time.Parse(time.RFC3339Nano, t)
		return parsed
	case []byte:
		parsed, _ := time.Parse(time.RFC3339Nano, string(t))
		return parsed
	}
	return time.Time{}
}

n_ledger_validateBoardLayout.signature:
func validateBoardLayout(layout *proto.BoardLayout) error {
	if layout == nil {
		return nil
	}
	if len(layout.Columns) != 5 {
		return fmt.Errorf("看板列必须恰好五列: %w", ErrBadState)
	}
	seen := make(map[string]bool, len(layout.Columns))
	for _, column := range layout.Columns {
		if strings.TrimSpace(column) == "" || seen[column] {
			return fmt.Errorf("看板列名必须非空且唯一: %q: %w", column, ErrBadState)
		}
		seen[column] = true
	}
	if !seen[layout.Fallback] {
		return fmt.Errorf("看板兜底列 %q 不在列序中: %w", layout.Fallback, ErrBadState)
	}
	for state, column := range layout.StateToColumn {
		if !seen[column] {
			return fmt.Errorf("状态 %q 映射到不存在的看板列 %q: %w", state, column, ErrBadState)
		}
	}
	return nil
}

n_ledger_validateDisciplineName.signature:
// validateDisciplineName 拒绝一切非「纯名字」的取值：路径穿越与散落多处的
// 纪律块都从名字开始防（resolver.resolvePath 同款理由）。
func validateDisciplineName(name string) error {
	if strings.TrimSpace(name) == "" || name == "." || name == ".." ||
		strings.ContainsRune(name, filepath.Separator) || strings.ContainsRune(name, '/') {
		return fmt.Errorf("纪律块名字 %q 不能为空或含路径分隔符", name)
	}
	return nil
}

n_ledgermirror_DefaultSource.signature:
// DefaultSource 生产事件源：client.ForwardedStreamEventsOnce 的薄包装。
//
// 为什么带一跳封顶：这一跳是 agentd→agentd，标记让对端不再向外扇出
// （一跳封顶，A→B→A 不成环），与任务镜像的镜像订阅同款
// （internal/workspace 的 RemoteTaskSource 适配器也包 MarkForwarded）。
func DefaultSource(ctx context.Context, c client.EventStreamClient, taskID string, fromSeq int64,
	onEvent func(proto.Event) error) error {
	return c.ForwardedStreamEventsOnce(ctx, taskID, fromSeq, onEvent)
}

n_ledgermirror_Mirror_Run.signature:
// Run 主循环：每 Tick 取/续 lease；持有则对账订阅集，失去则停掉全部
// 订阅（续约失败立即停写，绝不双写）。阻塞直到 ctx 取消。
func (m *Mirror) Run(ctx context.Context) {
	runCtx, runStop := context.WithCancel(ctx)
	runDone := make(chan struct{})
	m.runMu.Lock()
	m.runStop = runStop
	m.runDone = runDone
	m.runMu.Unlock()
	m.runStarted.Store(true)
	defer close(runDone)
	defer runStop()
	if m.stopAsked.Load() || runCtx.Err() != nil {
		return
	}
	m.log.Info("账本镜像子系统启动", "holder", m.opt.Holder, "tick", m.opt.Tick, "lease_ttl", m.opt.LeaseTTL)
	tick := time.NewTicker(m.opt.Tick)
	defer tick.Stop()
	for {
		if runCtx.Err() != nil {
			return
		}
		got, err := m.st.AcquireMirrorLease(m.opt.Holder, m.opt.LeaseTTL)
		if err != nil {
			m.log.Warn("lease 操作失败", "err", err)
		}
		if got != m.holding.Load() {
			m.log.Info("镜像 lease 状态变化", "holding", got)
		}
		m.holding.Store(got)
		if got {
			m.reconcile(runCtx)
		} else {
			m.stopAllSubs("失去 lease")
		}
		select {
		case <-runCtx.Done():
			m.holding.Store(false)
			m.log.Info("账本镜像子系统退出", "cause", runCtx.Err())
			m.stopAllSubs("关停")
			return
		case <-tick.C:
		}
	}
}

n_ledgermirror_Mirror_Stop.signature:
// Stop 等全部订阅 goroutine 退出。必须在账本库 Close 之前调用。
func (m *Mirror) Stop() {
	m.stopAsked.Store(true)
	m.holding.Store(false)
	m.runMu.Lock()
	runStop, runDone := m.runStop, m.runDone
	m.runMu.Unlock()
	if m.runStarted.Load() && runStop != nil {
		runStop()
	}
	m.stopAllSubs("Stop")
	m.wgMu.Lock()
	m.wg.Wait()
	m.wgMu.Unlock()
	if m.runStarted.Load() && runDone != nil {
		<-runDone
	}
}

n_ledgermirror_Mirror_dropSubLocked.signature:
// dropSubLocked 退订一条并清掉连接状态。**调用方必须持有 m.mu**。
//
// 注意：不动 m.ended —— 那是「这条挂账已终态」的记忆，与「这条订阅为什么被收掉」
// 是两件事；误删会让已归档的 task 在下一轮被重新订阅。
func (m *Mirror) dropSubLocked(key string, sub *subscription, reason string) {
	sub.cancel()
	delete(m.subs, key)
	delete(m.conn, key)
	m.log.Info("退订", "sub", key, "reason", reason)
}

n_ledgermirror_Mirror_isLocalTarget.signature:
func (m *Mirror) isLocalTarget(target string) bool {
	return target == "" || m.opt.IsSelfTarget != nil && m.opt.IsSelfTarget(target)
}

n_ledgermirror_Mirror_reconcile.signature:
// reconcile 对账挂账表与当前登记机器，建立和收掉订阅，并刷新健康行。
//
// 三条判据都取自活配置（经 Machines）：机器在不在、客户端是不是同一个实例、
// 该机器本轮取不取得到客户端。任何一条不成立都收掉对应订阅——镜像宁可少订，
// 也不能拿旧凭据连下去（那正是 B163 ② 的形态：改了地址却永不生效）。
func (m *Mirror) reconcile(ctx context.Context) {
	names := m.machines.Names()
	registered := make(map[string]bool, len(names))
	for _, n := range names {
		registered[n] = true
	}
	links, err := m.st.AllTaskLinks()
	if err != nil {
		m.log.Warn("读挂账表失败", "err", err)
		return
	}
	live, err := m.st.LiveMirrorTargets()
	if err != nil {
		m.log.Warn("读在飞镜像 target 失败", "err", err)
		return
	}
	want := map[string]ledger.TaskLink{}
	for _, link := range links {
		if link.Target != "" && !registered[link.Target] && !m.isLocalTarget(link.Target) {
			continue
		}
		want[link.Target+"/"+link.TaskID] = link
	}

	clients := map[string]client.EventStreamClient{}
	for _, link := range want {
		if m.isLocalTarget(link.Target) {
			continue
		}
		if _, ok := clients[link.Target]; ok {
			continue
		}
		c, err := m.machines.For(link.Target)
		if err != nil {
			m.log.Warn("取机器客户端失败，本轮跳过该机器", "target", link.Target, "err", err)
			continue
		}
		clients[link.Target] = c
	}

	m.mu.Lock()
	defer m.mu.Unlock()
	for key, sub := range m.subs {
		link, ok := want[key]
		switch {
		case !ok:
			m.dropSubLocked(key, sub, "机器或挂账已不在")

			delete(m.ended, key)
		case m.isLocalTarget(link.Target) && sub.client != nil:
			m.dropSubLocked(key, sub, "本机目标形态变更，退订重订")
		case !m.isLocalTarget(link.Target) && clients[link.Target] == nil:
			m.dropSubLocked(key, sub, "本轮取不到该机器的客户端")
		case !m.isLocalTarget(link.Target) && clients[link.Target] != sub.client:
			m.dropSubLocked(key, sub, "机器配置已变更，退订重订")
		case sub.link.CardID != link.CardID || sub.link.Node != link.Node || sub.link.Attempt != link.Attempt:

			m.dropSubLocked(key, sub, "工作流尝试身份已变更，退订重订")
		}
	}
	for key, link := range want {
		if ctx.Err() != nil {
			return
		}
		if m.ended[key] {
			continue
		}
		if _, ok := m.subs[key]; ok {
			continue
		}
		c := clients[link.Target]
		if !m.isLocalTarget(link.Target) && c == nil {
			continue
		}
		subCtx, cancel := context.WithCancel(ctx)
		m.subs[key] = &subscription{cancel: cancel, client: c, link: link}
		m.wgMu.Lock()
		m.wg.Add(1)
		m.wgMu.Unlock()
		go m.subscribe(subCtx, link, c)
		m.log.Info("起订", "sub", key, "target", link.Target, "task", link.TaskID,
			"node", link.Node, "attempt", link.Attempt)
	}

	alive := map[string]bool{}
	for key := range want {
		if m.ended[key] {
			continue
		}
		separator := strings.IndexByte(key, '/')
		if separator < 0 {
			continue
		}
		target := key[:separator]
		if m.conn[key] {
			alive[target] = true
		}
	}
	for _, name := range names {
		if m.isLocalTarget(name) {
			continue
		}

		if live[name] && !alive[name] {
			continue
		}
		if err := m.st.TouchMirrorHealth(name, 0); err != nil {
			m.log.Warn("touch 健康失败", "target", name, "err", err)
		}
	}

	rows, err := m.st.MirrorHealth()
	if err != nil {
		m.log.Warn("读镜像健康失败", "err", err)
		return
	}
	for _, row := range rows {
		if m.isLocalTarget(row.Target) {
			continue
		}
		if registered[row.Target] {
			continue
		}
		if live[row.Target] {
			continue
		}
		if err := m.st.TouchMirrorHealth(row.Target, 0); err != nil {
			m.log.Warn("touch 健康失败", "target", row.Target, "err", err)
		}
	}
}

n_ledgermirror_Mirror_setConn.signature:
func (m *Mirror) setConn(key string, ok bool) {
	m.mu.Lock()
	m.conn[key] = ok
	m.mu.Unlock()
}

n_ledgermirror_Mirror_stopAllSubs.signature:
func (m *Mirror) stopAllSubs(reason string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if len(m.subs) > 0 {
		m.log.Info("停全部订阅", "n", len(m.subs), "reason", reason)
	}
	for key, sub := range m.subs {
		sub.cancel()
		delete(m.subs, key)
		delete(m.conn, key)
	}
}

n_ledgermirror_Mirror_subscribe.signature:
// subscribe 单 task 常驻订阅：watermark 起拉、断线退避重连、事件过滤后幂等落账。
//
// 参数 c 是起订那一刻的客户端实例；它对应的机器配置若在运行期被改，reconcile
// 会取消本 ctx 并用新实例重起一条（见 subscription 的注释），**本函数不自行换客户端**。
func (m *Mirror) subscribe(ctx context.Context, link ledger.TaskLink, c client.EventStreamClient) {
	defer m.wg.Done()
	key := link.Target + "/" + link.TaskID
	defer m.setConn(key, false)
	backoff := 300 * time.Millisecond
	const maxBackoff = 10 * time.Second
	for ctx.Err() == nil {
		wm, err := m.st.MirrorWatermark(link.Target, link.TaskID)
		if err != nil {
			m.log.Warn("读 watermark 失败，退避重试", "card", link.CardID, "target", link.Target,
				"task", link.TaskID, "node", link.Node, "attempt", link.Attempt,
				"backoff", backoff, "cause", err)
			m.setConn(key, false)
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
			}
			backoff *= 2
			if backoff > maxBackoff {
				backoff = maxBackoff
			}
			continue
		}
		m.setConn(key, true)
		var source Source
		if m.isLocalTarget(link.Target) {
			source = m.opt.LocalSource
			if source == nil {
				err = errors.New("本机账本源未配置")
				m.log.Warn("本机订阅无法建立", "card", link.CardID, "target", link.Target,
					"task", link.TaskID, "node", link.Node, "attempt", link.Attempt,
					"from_seq", wm, "cause", err)
			} else {
				m.log.Info("建立本机账本订阅", "card", link.CardID, "target", link.Target,
					"task", link.TaskID, "node", link.Node, "attempt", link.Attempt, "from_seq", wm)
			}
		} else {
			if c == nil {
				err = errors.New("远端客户端缺失")
				m.log.Warn("远端订阅无法建立", "card", link.CardID, "target", link.Target,
					"task", link.TaskID, "node", link.Node, "attempt", link.Attempt,
					"from_seq", wm, "cause", err)
			} else {
				source = m.opt.Source
				m.log.Info("建立远端账本订阅", "card", link.CardID, "target", link.Target,
					"task", link.TaskID, "node", link.Node, "attempt", link.Attempt, "from_seq", wm)
			}
		}
		if source != nil {
			err = source(ctx, c, link.TaskID, wm, func(e proto.Event) error {
				if mirrorSkip[e.Type] {
					m.log.Debug("账本镜像过滤事件", "target", link.Target, "task", link.TaskID,
						"node", link.Node, "attempt", link.Attempt, "seq", e.Seq, "type", e.Type)
					return nil
				}
				wrote, err := m.st.AppendMirroredEvent(link.CardID, ledger.MirroredEvent{
					Target:	link.Target, Task: link.TaskID, Node: link.Node, Attempt: link.Attempt, SourceSeq: e.Seq,
					Type:	string(e.Type), Payload: e.Payload, CreatedAt: e.CreatedAt,
				})
				if err != nil {
					m.log.Warn("账本镜像落库失败", "target", link.Target, "task", link.TaskID,
						"node", link.Node, "attempt", link.Attempt, "seq", e.Seq, "type", e.Type, "card", link.CardID, "cause", err)
					return err
				}
				if wrote {
					m.log.Debug("账本镜像事件已落账", "target", link.Target, "task", link.TaskID,
						"node", link.Node, "attempt", link.Attempt, "seq", e.Seq, "type", e.Type, "card", link.CardID)
					if !m.isLocalTarget(link.Target) {
						if err := m.st.TouchMirrorHealth(link.Target, e.Seq); err != nil {
							m.log.Warn("touch 健康失败", "card", link.CardID, "target", link.Target,
								"task", link.TaskID, "node", link.Node, "attempt", link.Attempt,
								"seq", e.Seq, "cause", err)
						}
					}
				}
				if e.Type == proto.EventTypeArchived {
					return errMirrorArchived
				}
				return nil
			})
		}
		m.setConn(key, false)
		if ctx.Err() != nil {
			return
		}
		if errors.Is(err, errMirrorArchived) || err == nil {
			m.mu.Lock()
			m.ended[key] = true
			m.mu.Unlock()
			m.log.Info("订阅正常终结（task 归档）", "target", link.Target, "task", link.TaskID)
			return
		}
		m.log.Warn("订阅断开，退避重连", "card", link.CardID, "target", link.Target,
			"task", link.TaskID, "node", link.Node, "attempt", link.Attempt,
			"backoff", backoff, "cause", err)
		select {
		case <-ctx.Done():
			return
		case <-time.After(backoff):
		}
		backoff *= 2
		if backoff > maxBackoff {
			backoff = maxBackoff
		}
	}
}

n_ledgermirror_New.signature:
// New 构造。
//
// 参数：
//   - st: 账本库，镜像事件的落点
//   - machines: 活的机器清单与客户端来源；生产传 agentd 的 target 客户端池，
//     **必须与任务镜像共用同一个池实例**——两个池等于两套 relay 隧道，
//     relay 侧会看到重复的节点连接
//   - opt: 参数，零值取生产默认
func New(st *ledger.Store, machines Machines, opt Options) *Mirror {
	if opt.Tick == 0 {
		opt.Tick = 10 * time.Second
	}
	if opt.LeaseTTL == 0 {
		opt.LeaseTTL = 30 * time.Second
	}
	if opt.Source == nil {
		opt.Source = DefaultSource
	}
	if opt.Holder == "" {
		opt.Holder = "unknown"
	}
	return &Mirror{st: st, machines: machines, opt: opt,
		log:	slog.Default().With("subsystem", "ledgermirror"),
		subs:	map[string]*subscription{}, conn: map[string]bool{}, ended: map[string]bool{}}
}

n_ledgermirror_NewLocalSource.signature:
// NewLocalSource creates a source that reads persisted events from the local store.
//
// 参数：
//   - events: 本机事件库；必须同时提供按 seq 升序的排他回放和 task 门铃
//   - log: 结构化日志器；nil 时使用默认日志器
//
// 返回：
//   - 本机事件源。调用时 c 必须为 nil；fromSeq 是排他的，事件按 seq 升序回放，
//     函数阻塞至 ctx 取消或事件回调失败
//
// 注意：本机路径不读取 c、不订阅 Hub；门铃只提示有新事件，真实事件每次都从
// store 读取，以避免 Hub 的有限缓冲造成事件缺口。
func NewLocalSource(events LocalEventStore, logger *slog.Logger) Source {
	if logger == nil {
		logger = slog.Default()
	}
	return func(ctx context.Context, _ client.EventStreamClient, taskID string, fromSeq int64,
		onEvent func(proto.Event) error) error {
		if events == nil {
			err := errors.New("本机事件源缺少 store")
			logger.Warn("本机账本源无法启动", "task", taskID, "from_seq", fromSeq, "cause", err)
			return err
		}
		if onEvent == nil {
			err := errors.New("本机事件源缺少事件回调")
			logger.Warn("本机账本源无法启动", "task", taskID, "from_seq", fromSeq, "cause", err)
			return err
		}
		wake, cancel := events.SubscribeEventDoorbell(taskID)
		defer cancel()
		cursor := fromSeq
		logger.Info("本机账本源启动", "task", taskID, "from_seq", fromSeq)
		for {
			if err := ctx.Err(); err != nil {
				logger.Info("本机账本源退出", "task", taskID, "from_seq", cursor, "cause", err)
				return err
			}
			batch, err := events.EventsFromAsc(taskID, cursor, localSourceBatchSize)
			if err != nil {
				logger.Warn("本机账本源回放失败", "task", taskID, "from_seq", cursor, "cause", err)
				return err
			}
			if len(batch) > 0 {
				logger.Debug("本机账本源回放事件", "task", taskID, "from_seq", cursor, "count", len(batch))
				for _, event := range batch {
					if err := ctx.Err(); err != nil {
						logger.Info("本机账本源退出", "task", taskID, "from_seq", cursor, "cause", err)
						return err
					}
					if err := onEvent(event); err != nil {
						logger.Warn("本机账本源交付失败", "task", taskID,
							"seq", event.Seq, "type", event.Type, "cause", err)
						return err
					}
					cursor = event.Seq
					logger.Debug("本机账本源事件已交付", "task", taskID,
						"seq", event.Seq, "type", event.Type)
				}
				continue
			}
			select {
			case <-ctx.Done():
				logger.Info("本机账本源退出", "task", taskID, "from_seq", cursor, "cause", ctx.Err())
				return ctx.Err()
			case <-wake:
				logger.Debug("本机账本源收到门铃", "task", taskID, "from_seq", cursor)
			}
		}
	}
}

n_ledgerstep_ChangedPaths.signature:
// ChangedPaths 提取 git diff 中首次出现的仓内相对路径，并保持其出现顺序。
// 只接受 diff --git、rename from/to 和非 /dev/null 的 ---/+++ 记录，避免把
// 提交标题、作者、索引或 hunk 内容误当成产出路径。
// 不能只按行首字符判断：hunk 中原文以 "++ " 开头的新增内容会渲染为
// "+++ ..."，同理原文以 "-- " 开头的删除内容会渲染为 "--- ..."。
func ChangedPaths(diff string) []string {
	paths := make([]string, 0)
	seen := make(map[string]struct{})
	add := func(raw string) {
		path := diffPath(raw)
		if path == "" {
			return
		}
		if _, ok := seen[path]; ok {
			return
		}
		seen[path] = struct{}{}
		paths = append(paths, path)
	}

	inFileHeader := false
	scanner := bufio.NewScanner(strings.NewReader(diff))
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "diff --git ") {
			inFileHeader = true
			fields := diffHeaderFields(strings.TrimPrefix(line, "diff --git "))
			if len(fields) >= 2 {
				add(fields[0])
				add(fields[1])
			}
			continue
		}
		if inFileHeader && strings.HasPrefix(line, "@@") {
			inFileHeader = false
			continue
		}
		if !inFileHeader {
			continue
		}
		switch {
		case strings.HasPrefix(line, "rename from "):
			add(strings.TrimPrefix(line, "rename from "))
		case strings.HasPrefix(line, "rename to "):
			add(strings.TrimPrefix(line, "rename to "))
		case strings.HasPrefix(line, "--- "):
			add(strings.TrimPrefix(line, "--- "))
		case strings.HasPrefix(line, "+++ "):
			add(strings.TrimPrefix(line, "+++ "))
		}
	}
	return paths
}

n_ledgerstep_CountRounds.signature:
// CountRounds 数 step 自最近一次人工重置以来的裁决回合数。
// evs 必须按 seq 升序（EventsFromAsc 的自然输出）。
func CountRounds(evs []ledger.Event, step string) int {
	n := 0
	for _, event := range evs {
		var payload map[string]any
		if err := json.Unmarshal(event.Payload, &payload); err != nil {
			continue
		}
		switch event.Type {
		case ledger.EvReviewVerdict:
			if payload["node"] == step {
				n++
			}
		case ledger.EvComment:
			if payload["human_reset_node"] == step {
				n = 0
			}
		}
	}
	return n
}

n_ledgerstep_Dispatcher_ViaTemplate.signature:
// ViaTemplate 按模板把一张卡派出去。
//
// 参数：c 卡；req 模板名、目标机、可选 plan 路径与纪律块角色名覆盖。
// 返回：派发结果（含 task id、起点分支、agentd Task.BaseCommit、模板版本、纪律块角色名）。
//
// 注意：不含协调者席位语义。实现类与环节派发都只负责派任务；运行互斥由
// 节点编排的 RunLock 负责，席位由 bind/coordinate/rebind 命令管理。
// 本次只调用一次 Transport；快照和五列挂账在一个事务内完成，不因本地落账
// 失败重派第二个 task。已创建 task 的失败回收由 Compensate 注入，不删除分支。
//
// req.PlanPath 按调用方进程的 CWD 解析。agentd 一侧永远传空串：
// 浏览器里没有 plan 文件，实现类派发也不从界面走。
func (d *Dispatcher) ViaTemplate(ctx context.Context, c ledger.Card, req TemplateDispatch) (DispatchResult, error) {
	var zero DispatchResult
	tpl, err := d.St.GetTemplate(req.Template, 0)
	if err != nil {
		slog.Default().Warn("取模板失败", "card", c.ID, "template", req.Template, "cause", err)
		return zero, fmt.Errorf("取模板: %w", err)
	}

	target := req.Target
	if target == "" {
		target = tpl.Def.Target
	}
	rawTarget := target
	if d.NormalizeTarget != nil {
		target = d.NormalizeTarget(target)
	}
	disciplineName := tpl.Def.Discipline
	if req.DisciplineOverride != "" {
		disciplineName = req.DisciplineOverride
	}
	slog.Default().Info("模板派发目标已归一", "card", c.ID, "template", req.Template,
		"raw_target", rawTarget, "target", target)

	templateDef := tpl.Def
	purpose := templateDef.Purpose
	if req.PurposeOverride != "" {
		purpose = req.PurposeOverride
	}

	workInfo, workErr := d.St.WorkBranch(c.ID)
	hasWorkBranch := workErr == nil
	if workErr != nil && !errors.Is(workErr, ledger.ErrNotFound) {
		slog.Default().Error("读取卡工作分支失败", "card", c.ID, "target", target,
			"previous_target", "", "branch", "", "cause", workErr)
		return zero, fmt.Errorf("取卡工作分支: %w", workErr)
	}
	previousTarget := ""
	if hasWorkBranch {
		previousTarget = workInfo.Target
		if d.NormalizeTarget != nil {
			previousTarget = d.NormalizeTarget(previousTarget)
		}
	}
	originReady := false
	if hasWorkBranch && previousTarget != target {
		published, pubErr := d.St.WorkBranchPublished(c.ID, workInfo.Branch)
		if pubErr != nil {
			slog.Default().Error("读取工作分支 origin 发布失败", "card", c.ID,
				"branch", workInfo.Branch, "cause", pubErr)
			return zero, fmt.Errorf("取工作分支 origin 发布: %w", pubErr)
		}
		if !published {
			slog.Default().Warn("工作分支跨目标机且未发布 origin，拒绝接续", "card", c.ID,
				"branch", workInfo.Branch, "previous_target", previousTarget, "target", target,
				"cause", "目标机身份不一致且 origin 未见该分支")
			return zero, fmt.Errorf("工作分支只存在于创建它的那台机器：上次目标机 %q，本次目标机 %q；请先在上一台 git push origin %s（失败则 needs_human）。日常路径不使用 --base",
				previousTarget, target, workInfo.Branch)
		}
		originReady = true
		slog.Default().Info("工作分支已在 origin，跨机接续", "card", c.ID,
			"branch", workInfo.Branch, "previous_target", previousTarget, "target", target)
	}

	acceptance := c.AcceptanceCriteria
	if req.OmitAcceptance {
		acceptance = "（本节点不注入整卡验收判据——那是实现级的最终判据；本节点的产出物与 pass 依据以纪律块为准）"
	}
	body := strings.NewReplacer(
		"{{TITLE}}", c.Title,
		"{{CARD}}", c.ID,
		"{{ACCEPT}}", acceptance,
	).Replace(tpl.Def.Prompt)

	branch := fmt.Sprintf("%s/%s-%s", tpl.Def.BranchPrefix, c.ID, purpose)
	existingBranch := ""
	if purpose == ledger.PurposeReview {
		if !hasWorkBranch {
			return zero, fmt.Errorf("审阅轮取工作分支: %w", workErr)
		}

		round, err := d.St.ReviewRounds(c.ID)
		if err != nil {
			return zero, fmt.Errorf("审阅轮取轮次: %w", err)
		}
		branch = fmt.Sprintf("%s/%s-review-%d", tpl.Def.BranchPrefix, c.ID, round+1)
	} else {

		rounds, err := d.St.PurposeRounds(c.ID, purpose)
		if err != nil {
			return zero, fmt.Errorf("取 %s 轮次: %w", purpose, err)
		}
		if rounds > 0 {
			branch = fmt.Sprintf("%s-%d", branch, rounds+1)
			slog.Default().Info("重跑轮分支挂号", "card", c.ID,
				"purpose", purpose, "round", rounds+1, "branch", branch)
		}
	}
	base, err := d.St.EffectiveBaseBranch(c.ID)
	if err != nil {
		slog.Default().Warn("取有效基线失败", "card", c.ID, "target", target,
			"previous_target", previousTarget, "branch", "", "cause", err)
		return zero, fmt.Errorf("取有效基线: %w", err)
	}
	localBaseBranch := false
	if hasWorkBranch {
		base = workInfo.Branch
		if !originReady {
			localBaseBranch = true
		}
	}
	resolveDefaultBase := base == ""

	cardBase, err := d.St.EffectiveBaseBranch(c.ID)
	if err != nil {
		slog.Default().Warn("取卡上下文基线失败", "card", c.ID, "target", target,
			"previous_target", previousTarget, "branch", branch, "cause", err)
		return zero, fmt.Errorf("取卡上下文基线: %w", err)
	}
	prompt := buildPrompt(body, c, cardBase, req.CarryCardContext, req.OmitAcceptance, req.Extra, req.OutputPath)
	model := ""
	if tpl.Def.ModelByTarget != nil {
		model = tpl.Def.ModelByTarget[target]
	}
	executor := tpl.Def.Executor
	if req.ExecutorOverride != "" && req.ExecutorOverride != tpl.Def.Executor {
		executor = req.ExecutorOverride

		model = ""
	} else if req.ExecutorOverride != "" {
		executor = req.ExecutorOverride
	}
	if req.ModelOverride != "" {
		model = req.ModelOverride
	}
	var planB64, planName string
	if req.PlanPath != "" {
		content, err := os.ReadFile(req.PlanPath)
		if err != nil {
			return zero, fmt.Errorf("读 plan %s: %w", req.PlanPath, err)
		}
		planB64 = base64.StdEncoding.EncodeToString(content)
		planName = filepath.Base(req.PlanPath)
	}
	slog.Default().Info("按模板派发",
		"card", c.ID, "node", req.Node, "template", req.Template, "target", target,
		"receiver", req.Receiver, "carrier", d.Carrier, "squad", d.Squad, "home_dir_set", d.HomeDir != nil,
		"executor", executor, "model", model, "discipline", disciplineName,
		"discipline_version", d.DisciplineVersion,
		"discipline_bytes", len(d.DisciplineText),
		"purpose", purpose, "purpose_overridden", req.PurposeOverride != "",
		"omit_acceptance", req.OmitAcceptance,
		"branch", branch, "base", base,
		"resolve_default_base", resolveDefaultBase,
		"carry_card_context", req.CarryCardContext, "has_extra", strings.TrimSpace(req.Extra) != "",
		"output_path", req.OutputPath,
		"prompt_bytes", len(prompt))
	slog.Default().Info("派发前已确定节点产出路径", "card", c.ID, "node", req.Node,
		"template", req.Template, "target", target, "receiver", req.Receiver,
		"output_path", req.OutputPath)
	taskID, baseCommit, err := d.Transport(ctx, DispatchOpts{
		Prompt:	prompt, Branch: branch, Target: target, Project: c.Project,
		Executor:	executor, Model: model, PlanB64: planB64,
		Receiver:	req.Receiver,
		Carrier:	d.Carrier,
		Squad:		d.Squad,
		HomeDir:	d.HomeDir,
		OutputPath:	req.OutputPath,
		PlanName:	planName, Base: base, NewWorktree: true,
		ExistingBranch:	existingBranch, Discipline: disciplineName,

		DisciplineText:		d.DisciplineText,
		DisciplineVersion:	d.DisciplineVersion,
		ResolveDefaultBase:	resolveDefaultBase,
		LocalBaseBranch:	localBaseBranch,
	})
	if err != nil {
		slog.Default().Warn("模板派发传输失败", "card", c.ID, "node", req.Node,
			"attempt", "", "target", target, "task", "", "seq", 0,
			"type", ledger.EvDispatched, "branch", branch, "base", base, "cause", err)
		return zero, fmt.Errorf("派发: %w", err)
	}
	slog.Default().Info("模板派发传输已返回", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", 0,
		"type", ledger.EvDispatched, "receiver", req.Receiver, "carrier", d.Carrier, "squad", d.Squad,
		"base", base, "base_commit", baseCommit)
	slog.Default().Info("模板派发已裁定纪律块角色", "card", c.ID, "node", req.Node,
		"template", req.Template, "discipline", disciplineName,
		"overridden", req.DisciplineOverride != "")
	snapshotBranch := branch
	if snapshotBranch == "" {
		snapshotBranch = existingBranch
	}

	if req.WriteGate != nil && !req.WriteGate() {
		originalErr := fmt.Errorf("派发落账被拒：%w", ErrWriteGateClosed)
		slog.Default().Warn("失去写权，停止派发快照与挂账", "card", c.ID,
			"node", req.Node, "attempt", taskID, "target", target, "task", taskID,
			"seq", 0, "type", ledger.EvDispatched, "cause", originalErr)
		d.compensateFailedDispatch(ctx, c, purpose, target, taskID, originalErr)
		return zero, originalErr
	}
	snapshot := ledger.DispatchSnapshot{
		Template:	tpl.Name, TemplateVersion: tpl.Version, DisciplineName: disciplineName,
		DisciplineVersion:	d.DisciplineVersion,
		Target:			target, TaskID: taskID, Branch: snapshotBranch,
		Node:	req.Node, Attempt: taskID,
		Base:	base, BaseCommit: baseCommit,
		Executor:	executor, Model: model,
		Purpose:	purpose, PlanPath: req.PlanPath, Actor: d.Actor,
	}
	slog.Default().Info("模板派发快照与挂账落账开始", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", 0,
		"type", ledger.EvDispatched, "snapshot", snapshot)
	snapshotSeq, linkSeq, err := d.St.RecordDispatchAndLinkTask(c.ID, snapshot)
	if err != nil {
		slog.Default().Warn("模板派发快照与挂账落账失败", "card", c.ID, "node", req.Node,
			"attempt", taskID, "target", target, "task", taskID, "seq", snapshotSeq,
			"type", ledger.EvDispatched, "link_seq", linkSeq, "cause", err)
		originalErr := fmt.Errorf("快照与挂账落账: %w", err)
		d.compensateFailedDispatch(ctx, c, purpose, target, taskID, originalErr)
		return zero, originalErr
	}
	slog.Default().Info("模板派发快照与挂账落账完成", "card", c.ID, "node", req.Node,
		"attempt", taskID, "target", target, "task", taskID, "seq", linkSeq,
		"type", ledger.EvComment, "snapshot_seq", snapshotSeq, "snapshot", snapshot)
	slog.Default().Info("模板派发完成", "card", c.ID, "node", req.Node, "template", tpl.Name,
		"attempt", taskID, "task", taskID, "target", target, "receiver", req.Receiver,
		"carrier", d.Carrier, "squad", d.Squad, "home_dir_set", d.HomeDir != nil,
		"executor", executor, "model", model, "branch", snapshotBranch, "discipline", disciplineName)
	return DispatchResult{
		Card:	c.ID, Task: taskID, Target: target, Branch: snapshotBranch,
		Node:	req.Node, Attempt: taskID,
		Base:	base, BaseCommit: baseCommit,
		Template:	tpl.Name, TemplateVersion: tpl.Version, DisciplineName: disciplineName,
		DisciplineVersion:	d.DisciplineVersion,
	}, nil
}

n_ledgerstep_Dispatcher_compensateFailed.signature:
// compensateFailedDispatch 记录已创建 task 的耗费轮次并执行一次注入补偿。
// 失败轮次独立于 card_tasks：后者随失败的快照事务回滚，若复用它会让重试再次
// 使用仍留在执行机上的首轮分支名。副作用失败只记日志，保留 ViaTemplate 原错。
func (d *Dispatcher) compensateFailedDispatch(
	ctx context.Context,
	card ledger.Card,
	purpose, target, taskID string,
	originalErr error,
) {
	logger := slog.Default().With("card", card.ID, "purpose", purpose,
		"target", target, "task", taskID)
	logger.Warn("模板派发记录失败，登记耗费轮次", "cause", originalErr)
	if err := d.St.RecordDispatchRound(card.ID, purpose); err != nil {
		logger.Error("派发耗费轮次落账失败，保留原始错误", "cause", err)
	}
	if d.Compensate == nil {
		logger.Warn("派发补偿钩子未装配")
		return
	}
	logger.Info("派发失败补偿开始")
	if err := d.Compensate(ctx, target, taskID); err != nil {
		logger.Error("派发失败补偿失败，保留原始错误", "cause", err)
		return
	}
	logger.Info("派发失败补偿完成")
}

n_ledgerstep_NodeStep_RunOnce.signature:
// RunOnce 跑一次本节点；review 用途且裁决为 pass 时，会在裁决落账前用 Diff
// 执行只读闸；成功抢救裁决时会为被丢弃字段写普通评论，写评论失败原样返回。
//
// 参数：cardID 卡。
// 返回：Outcome（下一步动作 + 裁决 + 理由）；只有「本节点根本不该被执行」
// （纯人工列）和账本写失败才返回 error，其余异常一律转成 needs_human 并留痕。
//
// 阻塞行为：Node.Verdict 为真时会阻塞到被派出去的 task 跑到回合终态——几分钟
// 到几十分钟，executor 挂在 waiting_answer 时更久。调用方自行决定要不要放
// goroutine 里跑。
func (n *NodeStep) RunOnce(ctx context.Context, cardID string) (Outcome, error) {
	logger := slog.Default().With("node", n.Node.Name, "card", cardID)
	logger.Info("进入节点",
		"dispatch", n.Node.Dispatch, "verdict", n.Node.Verdict,
		"template", n.Node.Template, "max_rounds", n.maxRounds())

	card, err := n.St.GetCard(cardID)
	if err != nil {
		logger.Warn("读取节点所属卡失败", "cause", err)
		return Outcome{}, err
	}
	logger.Debug("读取节点所属卡完成", "workflow", card.WorkflowName,
		"workflow_version", card.WorkflowVersion, "status", card.Status)

	if card.Status == ledger.StatusDone || card.Status == ledger.StatusClosed {
		open, openErr := n.St.ListDecisions(true)
		if openErr != nil {
			logger.Warn("读取 open 裁决失败", "cause", openErr)
			return Outcome{}, openErr
		}
		var leftover []ledger.Decision
		for _, d := range open {
			if d.CardID == cardID {
				leftover = append(leftover, d)
			}
		}
		if len(leftover) > 0 {
			ids := make([]string, 0, len(leftover))
			for _, d := range leftover {
				ids = append(ids, fmt.Sprint(d.ID))
			}
			reason := fmt.Sprintf("终态遗留裁决：卡已到终态（%s）但仍有 %d 条未答复裁决", card.Status, len(leftover))
			body := "本卡已到终态但仍有 open 裁决未答复（协调者死亡窗口的产物）。答案属于用户，系统不代答（绝不伪造 decision_answered）——请恢复推进的协调者把裁决转达用户。open 裁决 id：" + strings.Join(ids, ", ")
			logger.Warn("检测到终态遗留裁决，转等人", "status", card.Status, "open_decisions", len(leftover))
			return n.haltForHumanEnsure(cardID, reason, "终态遗留裁决:"+cardID, body)
		}
	}
	if !n.Node.Dispatch {

		logger.Warn("纯人工列被要求执行", "workflow", card.WorkflowName,
			"hint", "用 handoff workflow put 发布节点形定义")
		return Outcome{}, fmt.Errorf("节点 %q 没有 Dispatch 能力，不可执行；这条流是老定义 / 这一列是人工列，要让它可派发用 `handoff workflow put %s --file <定义文件>`",
			n.Node.Name, card.WorkflowName)
	}
	base, err := n.St.EffectiveBaseBranch(cardID)
	if err != nil {
		return Outcome{}, err
	}
	for _, human := range n.Node.HumanBases {
		if base != human {
			continue
		}
		reason := fmt.Sprintf("基线 %s 在本节点的人工清单里：不自动执行", base)
		logger.Info("基线命中人工清单，跳过派发", "base", base)
		return n.haltForHuman(cardID, reason, "")
	}
	if n.Node.Verdict {
		events, err := n.St.EventsFromAsc([]string{cardID}, 0, 10000)
		if err != nil {
			return Outcome{}, err
		}
		rounds := CountRounds(events, n.Node.Name)
		logger.Info("读取裁决回合数", "rounds", rounds, "max_rounds", n.maxRounds())
		if rounds >= n.maxRounds() {
			reason := fmt.Sprintf("裁决超轮（%d/%d）", rounds, n.maxRounds())
			logger.Info("回合封顶转等人", "rounds", rounds)
			return n.haltForHuman(cardID, reason, "")
		}
	}

	target, taskID, err := n.Dispatch(ctx, card, n.Node)
	if err != nil {

		logger.Warn("派发失败，转等人", "cause", err)
		return n.haltForHuman(cardID, "派发失败", "本节点派发失败：\n"+err.Error())
	}
	logger.Info("已派发", "target", target, "task", taskID)
	if !n.Node.Verdict {

		logger.Info("节点结束（只派发不裁决）", "action", string(ActionDispatched))
		return Outcome{Action: ActionDispatched}, nil
	}

	message, err := n.Await(ctx, target, taskID)
	if err != nil {
		logger.Warn("未取到报文，转等人", "cause", err)
		return n.haltForHuman(cardID, "未取到裁决报文", "本节点未取到裁决报文：\n"+err.Error())
	}
	if n.FinishTask != nil {
		defer func() {
			if finErr := n.FinishTask(ctx, target, taskID); finErr != nil {
				logger.Warn("归档节点 task 失败（报文已取到）", "cause", finErr)
			} else {
				logger.Info("节点 task 已归档")
			}
		}()
	}
	verdict, parseErr := ParseVerdict(message)
	if parseErr != nil {
		logger.Info("裁决解析失败转等人", "cause", parseErr)
		return n.haltForHuman(cardID, "裁决解析失败", "裁决解析失败，报文原文：\n"+message)
	}
	if verdict.salvaged && (verdict.notesDropped || verdict.findingsDropped) {
		dropped := make([]string, 0, 2)
		if verdict.notesDropped {
			dropped = append(dropped, "notes")
		}
		if verdict.findingsDropped {
			dropped = append(dropped, "findings")
		}
		body := fmt.Sprintf("裁决 JSON 已抢救，仍按 %t 路由；以下字段因 JSON 损坏被丢弃：%s。Raw 保留在裁决事件中。",
			verdict.Pass, strings.Join(dropped, "、"))
		if err := n.gatedWrite("裁决抢救留痕"); err != nil {
			return Outcome{}, err
		}
		if _, err := n.St.AddComment(cardID, body, "普通", n.actor()); err != nil {
			logger.Warn("裁决抢救留痕失败", "dropped", dropped, "cause", err)
			return Outcome{}, err
		}
		logger.Warn("裁决抢救字段已丢弃并留普通评论", "dropped", dropped)
	}

	if verdict.Pass && n.Node.Override.Purpose == ledger.PurposeReview {
		logger.Info("开始校验 review 节点只读改动", "target", target, "task", taskID)
		if n.Diff == nil {
			err := fmt.Errorf("review 节点 diff 依赖未装配")
			logger.Error("读取审阅改动失败", "target", target, "task", taskID, "cause", err)
			return n.haltForHuman(cardID, "读取审阅改动失败",
				"本节点无法确认审阅轮是否只读：\n"+err.Error())
		}
		changedPaths, diffErr := n.Diff(ctx, target, taskID)
		if diffErr != nil {
			logger.Warn("读取审阅改动失败", "target", target, "task", taskID, "cause", diffErr)
			return n.haltForHuman(cardID, "读取审阅改动失败",
				"本节点无法确认审阅轮是否只读：\n"+diffErr.Error())
		}
		violations := reviewReadOnlyViolations(changedPaths)
		if len(violations) == 0 {
			logger.Info("review 节点只读改动通过", "target", target, "task", taskID,
				"changed_paths", changedPaths)
		} else {
			verdict.Pass = false
			body := "审阅节点检测到白名单外改动，按 fail 处理；越界路径：\n" +
				strings.Join(violations, "\n")
			if err := n.gatedWrite("审阅只读违规留痕"); err != nil {
				logger.Warn("审阅只读违规留痕被写闸拒绝", "target", target, "task", taskID,
					"paths", violations, "cause", err)
				return Outcome{}, err
			}
			if _, err := n.St.AddComment(cardID, body, "普通", n.actor()); err != nil {
				logger.Warn("审阅只读违规评论写入失败", "target", target, "task", taskID,
					"paths", violations, "cause", err)
				return Outcome{}, err
			}
			logger.Warn("review 节点只读闸未通过，按 fail 路由", "target", target, "task", taskID,
				"out_of_scope_paths", violations)
		}
	}
	if err := n.gatedWrite("裁决落账"); err != nil {
		return Outcome{}, err
	}
	if err := n.St.RecordReviewVerdict(cardID, n.Node.Name, verdict.Pass, verdict.Raw, n.actor()); err != nil {
		return Outcome{}, err
	}
	logger.Info("裁决落账", "pass", verdict.Pass, "findings", len(verdict.Findings))

	if err := n.gatedWrite("撤等人标记"); err != nil {
		return Outcome{}, err
	}
	if cleared, cerr := n.St.ClearNeedsHumanFrom(cardID, n.actor()); cerr != nil {
		logger.Warn("撤回本节点旧等人标记失败", "cause", cerr)
	} else if cleared {
		logger.Info("已撤回本节点此前的等人标记")
	}

	if verdict.Pass && n.Node.Produces != nil {
		output := n.Node.Produces
		if n.OutputPath == nil || n.Diff == nil || n.Attach == nil {
			logger.Error("节点声明产出但输出依赖未装配",
				"kind", output.Kind, "declared_path", output.Path)
			return n.haltForHuman(cardID, "产出物校验未装配",
				"本节点声明了产出物，但协调者未装配输出校验依赖")
		}
		declaredPath := n.OutputPath()
		logger.Info("开始校验节点产出物",
			"kind", output.Kind, "declared_path", declaredPath, "target", target, "task", taskID)
		changedPaths, diffErr := n.Diff(ctx, target, taskID)
		if diffErr != nil {
			logger.Warn("读取本轮改动失败，转等人",
				"kind", output.Kind, "declared_path", declaredPath,
				"target", target, "task", taskID, "cause", diffErr)
			return n.haltForHuman(cardID, "读取产出物改动失败",
				"本节点无法确认产出物是否在本轮改动中：\n"+diffErr.Error())
		}
		logger.Info("本轮改动已取得",
			"kind", output.Kind, "declared_path", declaredPath,
			"changed_paths", changedPaths)
		if declaredPath == "" || !containsPath(changedPaths, declaredPath) {
			body := "本节点要求的产出物路径：\n" + declaredPath +
				"\n本轮实际改动文件：\n" + changedPathsText(changedPaths)
			if actualPath, ok := datePrefixedDeclaredPath(declaredPath, changedPaths); ok {
				body += "\n检测到日期前缀文件名：" + actualPath +
					"；这是日期前缀，请改名为：" + declaredPath
				logger.Warn("检测到日期前缀法定产出",
					"kind", output.Kind, "declared_path", declaredPath,
					"changed_paths", changedPaths, "actual_path", actualPath,
					"cause", "产出路径必须逐字匹配")
			} else {
				logger.Warn("法定产出物未出现在本轮改动",
					"kind", output.Kind, "declared_path", declaredPath,
					"changed_paths", changedPaths, "cause", "未找到精确路径或日期前缀版本")
			}
			return n.haltForHuman(cardID, "缺少约定产出物", body)
		}
		if err := n.gatedWrite("挂附件"); err != nil {
			return Outcome{}, err
		}
		if attachErr := n.Attach(cardID, output.Kind, declaredPath, n.actor()); attachErr != nil {
			logger.Warn("挂载节点产出物失败，继续尝试路由",
				"kind", output.Kind, "path", declaredPath, "target", target, "task", taskID, "cause", attachErr)
		} else {
			logger.Info("节点产出物已挂载",
				"kind", output.Kind, "path", declaredPath, "actor", n.actor())
		}
	}

	if verdict.Pass && n.PublishWorkBranch != nil {
		info, workErr := n.St.WorkBranch(cardID)
		if workErr != nil && !errors.Is(workErr, ledger.ErrNotFound) {
			logger.Error("pass 后读取工作分支失败", "cause", workErr)
			return n.haltForHuman(cardID, "读取工作分支失败",
				"裁决已通过，但无法读取工作分支去推 origin：\n"+workErr.Error())
		}
		if workErr == nil && info.Branch != "" {
			already, publishedErr := n.St.WorkBranchPublished(cardID, info.Branch)
			if publishedErr != nil {
				logger.Error("查询工作分支是否已发布失败", "branch", info.Branch, "cause", publishedErr)
				return n.haltForHuman(cardID, "查询工作分支发布状态失败",
					"裁决已通过，但无法确认工作分支是否已在 origin：\n"+publishedErr.Error())
			}
			if already {

				logger.Info("工作分支已在 origin，跳过再推", "branch", info.Branch,
					"target", info.Target, "task", info.TaskID)
			} else {
				pushTarget, pushTask := info.Target, info.TaskID
				if pushTarget == "" {
					pushTarget = target
				}
				if pushTask == "" {
					pushTask = taskID
				}
				logger.Info("开始把工作分支推到 origin", "branch", info.Branch,
					"target", pushTarget, "task", pushTask)
				if pubErr := n.PublishWorkBranch(ctx, pushTarget, info.Branch, pushTask); pubErr != nil {
					logger.Error("工作分支未能推到 origin", "branch", info.Branch,
						"target", pushTarget, "task", pushTask, "cause", pubErr)
					return n.haltForHuman(cardID, "工作分支未能推到 origin",
						"裁决已通过，但 git push origin "+info.Branch+" 失败：\n"+pubErr.Error())
				}
				if err := n.gatedWrite("工作分支 origin 发布落账"); err != nil {
					return Outcome{}, err
				}
				if recErr := n.St.RecordWorkBranchPublished(cardID, info.Branch, pushTarget, pushTask, n.actor()); recErr != nil {
					logger.Error("工作分支发布落账失败", "branch", info.Branch, "cause", recErr)
					return n.haltForHuman(cardID, "工作分支发布落账失败",
						"origin 已推送，但账本未能记下发布事件：\n"+recErr.Error())
				}
				logger.Info("工作分支已发布到 origin", "branch", info.Branch, "target", pushTarget)
			}
		}
	}

	to, action := n.Node.OnFail, ActionContinue
	if verdict.Pass {
		to, action = n.Node.Next, ActionPass
	}
	if err := n.routeTo(cardID, to); err != nil {

		reason := fmt.Sprintf("裁决已落账但移到 %q 失败", to)
		logger.Warn("路由失败转等人", "to", to, "cause", err)
		return n.haltForHuman(cardID, reason, reason+"：\n"+err.Error())
	}
	logger.Info("节点结束", "action", string(action), "moved_to", to)
	return Outcome{Action: action, Verdict: verdict}, nil
}

n_ledgerstep_NodeStep_gatedWrite.signature:
// gatedWrite 在实际账本写入前确认本轮仍拥有运行锁；关闭时 fail-closed，
// 防止续租失败后的编排继续移列、落裁决、挂附件或改等人标记。
func (n *NodeStep) gatedWrite(action string) error {
	if n.WriteGate == nil || n.WriteGate() {
		return nil
	}
	return fmt.Errorf("%s被拒：%w", action, ErrWriteGateClosed)
}

n_ledgerstep_NodeStep_haltForHuman.signature:
// haltForHuman 落一条说明性 comment（body 非空时）并打等人标记，返回统一的 Outcome。
//
// why 抽出来：这条「留痕 + 打旗 + 返回」三件套在本文件里出现五次，每次漏掉
// 其中任何一件，卡在看板上都会看着一切正常而实际没人在推它。
func (n *NodeStep) haltForHuman(cardID, reason, body string) (Outcome, error) {
	if err := n.gatedWrite("等人留痕"); err != nil {
		return Outcome{Action: ActionNeedsHuman, Reason: reason}, err
	}
	if body != "" {
		if _, err := n.St.AddComment(cardID, body, "普通", n.actor()); err != nil {
			return Outcome{}, err
		}
	}
	if err := n.St.MarkNeedsHuman(cardID, reason, n.actor()); err != nil {
		return Outcome{}, err
	}
	return Outcome{Action: ActionNeedsHuman, Reason: reason}, nil
}

n_ledgerstep_NodeStep_haltForHumanEnsure.signature:
// haltForHumanEnsure 与 haltForHuman 同构，但说明评论走 EnsureComment 幂等
// 留痕：同 dedupeKey 不产生第二条评论。供「终态遗留裁决」补解析（契约 §3.7）
// 用——重复驱动同一张卡只留一条说明，避免看板被刷屏；也绝不伪造
// decision_answered（答案是用户的事实，系统不代答）。
func (n *NodeStep) haltForHumanEnsure(cardID, reason, dedupeKey, body string) (Outcome, error) {
	if err := n.gatedWrite("等人留痕"); err != nil {
		return Outcome{Action: ActionNeedsHuman, Reason: reason}, err
	}
	if body != "" {
		if _, err := n.St.EnsureComment(cardID, dedupeKey, body, n.actor()); err != nil {
			return Outcome{}, err
		}
	}
	if err := n.St.MarkNeedsHuman(cardID, reason, n.actor()); err != nil {
		return Outcome{}, err
	}
	return Outcome{Action: ActionNeedsHuman, Reason: reason}, nil
}

n_ledgerstep_NodeStep_maxRounds.signature:
// maxRounds 返回本节点的轮次封顶：节点没配就用包内默认。
func (n *NodeStep) maxRounds() int {
	if n.Node.MaxRounds > 0 {
		return n.Node.MaxRounds
	}
	return MaxRounds
}

n_ledgerstep_NodeStep_routeTo.signature:
// routeTo 把卡移到 to 列；to 为空表示停在本列（不是错误）。
//
// 返回：移动失败时返回错误原文，由调用方转等人——门槛没过（如「待合并」要求
// 验收判据非空）是常态而不是异常，硬失败会让已经落账的裁决白跑。
func (n *NodeStep) routeTo(cardID, to string) error {
	if to == "" {
		return nil
	}
	card, err := n.St.GetCard(cardID)
	if err != nil {
		return err
	}
	if card.Status == to {
		return nil
	}
	if err := n.gatedWrite("移列"); err != nil {
		return err
	}
	return n.St.MoveCard(cardID, to, card.Status, n.actor())
}

n_ledgerstep_ParseVerdict.signature:
// ParseVerdict 从审阅报文提取最后一个 handoff-verdict block 并解析。
// 严格 JSON 失败时，只从该围栏正文逐字段抢救；无法确认 verdict 时仍报错。
func ParseVerdict(message string) (Verdict, error) {
	blocks := verdictBlockPat.FindAllStringSubmatch(message, -1)
	if len(blocks) == 0 {
		return Verdict{}, fmt.Errorf("报文中没有 handoff-verdict block")
	}
	raw := strings.TrimSpace(blocks[len(blocks)-1][1])
	var wire struct {
		Verdict		string		`json:"verdict"`
		Findings	[]Finding	`json:"findings"`
		Notes		string		`json:"notes"`
	}
	if err := json.Unmarshal([]byte(raw), &wire); err != nil {
		verdictValue, ok := firstVerdictValue(raw)
		if !ok {
			return Verdict{}, fmt.Errorf("裁决 JSON 解析失败，且无法从围栏正文抢救 verdict")
		}
		var findings []Finding
		findingsPresent := strings.Contains(raw, `"findings"`)
		findingsOK := !findingsPresent || decodeVerdictField(raw, "findings", &findings)
		if !findingsOK {
			findings = nil
		}
		var notes string
		notesPresent := strings.Contains(raw, `"notes"`)
		notesOK := !notesPresent || decodeVerdictField(raw, "notes", &notes)
		if !notesOK {
			notes = ""
		}
		result := Verdict{
			Pass:	verdictValue == "pass", Findings: findings, Notes: notes, Raw: raw,
			salvaged:	true, notesDropped: notesPresent && !notesOK,
			findingsDropped:	findingsPresent && !findingsOK,
		}
		slog.Warn("裁决围栏已抢救", "verdict", verdictValue,
			"notes_dropped", result.notesDropped, "findings_dropped", result.findingsDropped)
		return result, nil
	}
	switch wire.Verdict {
	case "pass":
		return Verdict{Pass: true, Findings: wire.Findings, Notes: wire.Notes, Raw: raw}, nil
	case "fail":
		return Verdict{Pass: false, Findings: wire.Findings, Notes: wire.Notes, Raw: raw}, nil
	default:
		return Verdict{}, fmt.Errorf("verdict 值 %q 不在 {pass,fail}", wire.Verdict)
	}
}

n_ledgerstep_PreflightDiscipline.signature:
// PreflightDiscipline 以与 ViaTemplate 完全相同的裁决顺序算出一次模板派发的
// 有效（纪律角色名，目标机），供调用方在装配 Dispatcher 前完成缝 1 解析：
// 名字经账本 lookup 取正文、目标机探 Status 拿能力位，一并交给
// discipline.ResolveDispatch 产出正文三元组，再填进 Dispatcher 数据字段。
//
// 参数：st 账本；templateName 模板名；overrideName 调用方角色覆盖（空=不覆盖）；
// reqTarget 调用方目标机覆盖（空=用模板的）。
// 返回：有效角色名与目标机。target 为空表示「模板与请求都没定目标机」——这是
// 纯计算结果不是错误，如何处置（提前拒绝 / 放给 ViaTemplate 的既有失败路径）
// 由调用方按自己的同步语义决定；模板取不到时返回错误。
//
// 为什么导出：有效值依赖「请求覆盖 > 模板缺省」这套回退顺序，本包内
// ViaTemplate 与这里是唯一两处消费点且共用同一私有实现；调用方绕开它
// 自行推导就会与实际派发漂移。
func PreflightDiscipline(st *ledger.Store, templateName, overrideName, reqTarget string) (name, target string, err error) {
	tpl, err := st.GetTemplate(templateName, 0)
	if err != nil {
		return "", "", fmt.Errorf("取模板: %w", err)
	}
	name, target = disciplineAndTarget(tpl.Def, overrideName, reqTarget)
	return name, target, nil
}

n_ledgerstep_RenderOutputPath.signature:
// RenderOutputPath 将工作流声明中的四个占位符渲染成一次派发确定的路径。
// 参数：template 为声明模板；card/node 提供卡号与节点名；now 提供派发日期。
// 返回：只做字符串替换；未知占位符原样保留，便于配置错误在 diff 校验时显式暴露。
func RenderOutputPath(template string, card ledger.Card, node ledger.NodeDef, now time.Time) string {
	return strings.NewReplacer(
		"{{CARD}}", card.ID,
		"{{CARD_LOWER}}", strings.ToLower(card.ID),
		"{{NODE}}", node.Name,
		"{{DATE}}", now.Format("2006-01-02"),
	).Replace(template)
}

n_ledgerstep_ResolveNode.signature:
// nodeFor 在卡**钉住的**工作流版本里按名字找节点。
//
// why 一定要用卡钉的版本而不是最新版：工作流是不可变版本化的，卡在建卡时
// 钉了版本号。拿最新版去解释一张老卡，等于用今天的流程图判昨天的卡走到哪了。
// ResolveNode 查一张卡在它钉住的工作流里的某个节点定义。
//
// 参数：st 是账本；cardID 是卡号；nodeName 是节点名（= 看板列名）。
// 返回：卡不存在时原样透传 ledger.ErrNotFound（调用方据此映射 404）；工作流取不到、
// 或节点名不在该工作流里，返回带卡号与工作流版本的描述性错误。
//
// 为什么导出：受理一个节点请求是有副作用的（取得运行锁、派任务），而编排跑在后台
// goroutine 里——HTTP 层必须能在受理之前用同一份判断拒掉无效输入，否则卡号或节点名
// 打错只会换来一句「已受理」，失败连一条卡事件都留不下。两处必须查同一个真相源，
// 各查各的迟早漂移。
func ResolveNode(st *ledger.Store, cardID, nodeName string) (ledger.NodeDef, error) {
	card, err := st.GetCard(cardID)
	if err != nil {
		return ledger.NodeDef{}, err
	}
	workflow, err := st.GetWorkflow(card.WorkflowName, card.WorkflowVersion)
	if err != nil {
		return ledger.NodeDef{}, fmt.Errorf("取卡 %s 钉住的工作流 %s v%d: %w",
			cardID, card.WorkflowName, card.WorkflowVersion, err)
	}
	for _, node := range workflow.Def.Nodes {
		if node.Name == nodeName {
			return node, nil
		}
	}
	return ledger.NodeDef{}, fmt.Errorf("节点 %q 不在卡 %s 的工作流 %s v%d 里",
		nodeName, cardID, card.WorkflowName, card.WorkflowVersion)
}

n_ledgerstep_StepRunner_Run.signature:
// Run 跑一次节点。
//
// 参数：cardID 卡；nodeName 节点名（= 看板的列名），从卡钉住的工作流版本里查。
// 返回：Outcome；入口失败先落 needs_human 与原文评论，再返回错误。
//
// 阻塞行为：节点开了 Verdict 时会阻塞到被派出去的 task 跑到回合终态
// （几分钟到几十分钟，executor 挂在 waiting_answer 时更久）。调用方要么
// 自己在 goroutine 里跑（agentd 就是这么做的），要么接受前台阻塞（CLI）。
// 归属锁持久保留；运行锁由本轮续租并在回合结束释放。
func (r *StepRunner) Run(ctx context.Context, cardID, nodeName string) (Outcome, error) {
	logger := slog.Default().With("card", cardID, "node", nodeName, "run_holder", r.RunHolder)
	logger.Info("进入节点执行")
	node, err := r.nodeFor(cardID, nodeName)
	if err != nil {
		logger.Warn("读取节点失败", "cause", err)
		o, haltErr := r.haltEntrypoint(cardID, nodeName, "节点解不开",
			fmt.Sprintf("本节点无法从卡钉住的工作流里解开：%s", err.Error()))
		if haltErr != nil {
			return Outcome{}, haltErr
		}
		return o, err
	}
	outputPath := ""
	nodeStep := &NodeStep{
		St:		r.St,
		Node:		node,
		Await:		r.awaitNode(),
		OutputPath:	func() string { return outputPath },
		Diff:		r.diffNode(),
		Attach: func(cardID, kind, path, actor string) error {
			_, err := r.St.AttachFile(cardID, kind, path, actor)
			return err
		},
		PublishWorkBranch:	r.PublishWorkBranch,
		FinishTask:		r.finishTask(),
	}
	nodeStep.Dispatch = func(ctx context.Context, card ledger.Card, node ledger.NodeDef) (string, string, error) {
		return r.dispatchNodeWithGate(&outputPath, nodeStep.WriteGate)(ctx, card, node)
	}
	if !node.Dispatch {

		logger.Info("纯人工节点跳过运行锁与派发")
		return nodeStep.RunOnce(ctx, cardID)
	}

	session := r.Session
	if session == "" && r.Dispatcher != nil {

		session = r.Dispatcher.Actor
	}
	if session == "" {
		err := fmt.Errorf("节点归属会话未设置")
		logger.Error("节点执行被拒", "cause", err)
		o, haltErr := r.haltEntrypoint(cardID, nodeName, "会话未设置",
			"本节点执行被拒：发起方归属会话未设置。\n"+err.Error())
		if haltErr != nil {
			return Outcome{}, haltErr
		}
		return o, err
	}
	if r.RunHolder == "" {
		err := fmt.Errorf("运行标识未装配（RunHolder 为空）")
		logger.Error("运行锁路径拒绝放行", "cause", err)
		return r.haltEntrypoint(cardID, nodeName, "运行标识缺失", "本节点执行被拒："+err.Error())
	}
	lock, acquired, err := r.St.AcquireRunLock(cardID, nodeName, r.RunHolder, ledger.RunLockTTL)
	if err != nil {
		logger.Error("取得运行锁失败", "cause", err)
		o, haltErr := r.haltEntrypoint(cardID, nodeName, "取得运行锁失败", "本节点取得运行锁失败：\n"+err.Error())
		if haltErr != nil {
			return Outcome{}, fmt.Errorf("取得运行锁: %w", err)
		}
		return o, fmt.Errorf("取得运行锁: %w", err)
	}
	if !acquired {
		detail := fmt.Sprintf("卡正由 %s 运行节点 %s，租期到 %s",
			lock.Holder, lock.Node, lock.ExpiresAt.Format(time.RFC3339))
		logger.Warn("运行锁被拒", "lock_holder", lock.Holder,
			"lock_node", lock.Node, "expires_at", lock.ExpiresAt.Format(time.RFC3339))
		o, haltErr := r.haltEntrypoint(cardID, nodeName, "运行锁被他方占用",
			"本节点无法开跑："+detail+"。\n原因原文：AcquireRunLock 返回 acquired=false")
		if haltErr != nil {
			return Outcome{}, haltErr
		}
		return o, fmt.Errorf("运行锁被拒：%s", detail)
	}
	logger.Info("运行锁已取得", "expires_at", lock.ExpiresAt.Format(time.RFC3339))
	defer func() {
		if err := r.St.ReleaseRunLock(cardID, r.RunHolder); err != nil {
			logger.Warn("释放运行锁失败", "cause", err)
			return
		}
		logger.Info("运行锁已释放", "holder", r.RunHolder)
	}()

	logger.Info("节点执行继续：席位不由派发占用", "session", session)

	done := make(chan struct{})
	finished := make(chan struct{})
	var lostOnce sync.Once
	var lostReport struct {
		holder		string
		expiresAt	string
		readError	string
	}
	noteLost := func() (string, string, string) {
		lostOnce.Do(func() {
			lock, ok, err := r.St.RunLockOf(cardID)
			var lockInfo string
			switch {
			case err != nil:
				lostReport.readError = err.Error()
				lockInfo = "现持有者读取失败：" + lostReport.readError
				logger.Warn("失去写权说明读取运行锁失败", "cause", err)
			case !ok:
				lostReport.readError = "运行锁行不存在"
				lockInfo = "现持有者读取失败：" + lostReport.readError
				logger.Warn("失去写权说明读取运行锁失败", "cause", lostReport.readError)
			default:
				lostReport.holder = lock.Holder
				lostReport.expiresAt = lock.ExpiresAt.Format(time.RFC3339)
				lockInfo = fmt.Sprintf("holder=%s expires_at=%s", lostReport.holder, lostReport.expiresAt)
			}
			body := fmt.Sprintf("本轮运行锁已被接手（%s）：本回合自即刻起停止对这张卡的移列、裁决、附件与等人标记写入；已在跑的远端任务继续等待并照常归档。", lockInfo)
			if _, err := r.St.AddComment(cardID, body, "普通", "node:"+nodeName); err != nil {
				logger.Warn("失去写权说明落卡失败", "cause", err)
				return
			}
			if lostReport.readError != "" {
				logger.Info("失去写权说明已落卡", "lock_holder_read_error", lostReport.readError)
			} else {
				logger.Info("失去写权说明已落卡", "lock_holder", lostReport.holder, "expires_at", lostReport.expiresAt)
			}
		})
		return lostReport.holder, lostReport.expiresAt, lostReport.readError
	}
	beats := r.RenewBeat
	if beats == nil {
		ticker := time.NewTicker(ledger.RunLockRenewInterval)
		defer ticker.Stop()
		beats = ticker.C
	}
	go func() {
		defer close(finished)
		for {
			select {
			case <-ctx.Done():
				return
			case <-done:
				return
			case <-beats:
				ok, err := r.St.RenewRunLock(cardID, r.RunHolder, ledger.RunLockTTL)
				switch {
				case err != nil:
					logger.Warn("续租出错（下一节拍重试）", "cause", err)
				case ok:
					logger.Info("运行锁已续租", "ttl", ledger.RunLockTTL.String())
				default:
					holder, expiresAt, readError := noteLost()
					if readError != "" {
						logger.Warn("续租被拒：本轮已失去对卡的写权", "lock_holder_read_error", readError)
					} else {
						logger.Warn("续租被拒：本轮已失去对卡的写权", "lock_holder", holder, "expires_at", expiresAt)
					}
					return
				}
			}
		}
	}()
	defer func() { <-finished }()
	defer close(done)

	nodeStep.WriteGate = func() bool {
		ok, err := r.St.RenewRunLock(cardID, r.RunHolder, ledger.RunLockTTL)
		if err != nil {
			logger.Warn("写闸续租判定出错（按失权处理）", "cause", err)
			noteLost()
			return false
		}
		if !ok {
			noteLost()
		}
		return ok
	}
	defer func() {
		logger.Info("节点执行收口", "session", session)
	}()
	return nodeStep.RunOnce(ctx, cardID)
}

n_ledgerstep_StepRunner_awaitNode.signature:
// awaitNode 生产 NodeStep.Await：等回合终态并取最终报文。归档在 FinishTask，
// 必须排在 PublishWorkBranch 之后。
func (r *StepRunner) awaitNode() func(context.Context, string, string) (string, error) {
	return func(ctx context.Context, target, taskID string) (string, error) {
		logger := slog.Default().With("target", target, "task", taskID)
		logger.Info("节点等待开始")
		if r.Clients == nil {
			err := fmt.Errorf("节点等待客户端未装配")
			logger.Warn("取得节点等待客户端失败", "cause", err)
			return "", err
		}
		cl, err := r.Clients(target)
		if err != nil {
			logger.Warn("取得节点等待客户端失败", "cause", err)
			return "", err
		}

		logger.Info("节点等待客户端已就绪")
		if err := waitForTurnEnd(ctx, func(ctx context.Context) (*proto.Event, error) {
			return cl.WaitEvent(ctx, taskID, false)
		}); err != nil {
			logger.Warn("节点等待终态失败", "cause", err)
			return "", fmt.Errorf("等回合终态: %w", err)
		}
		message, err := clientFinalMessage(ctx, cl, taskID)
		if err != nil {
			logger.Warn("节点读取最终报文失败", "cause", err)
			return "", err
		}
		logger.Info("节点等待完成", "message_bytes", len(message))
		return message, nil
	}
}

n_ledgerstep_StepRunner_diffNode.signature:
// diffNode 只通过已装配的 Client.Diff 取得本轮改动，再投影成路径清单。
// 不访问目标机的其它文件 API，确保产出存在性判定仍以同一 diff 通道为准。
func (r *StepRunner) diffNode() func(context.Context, string, string) ([]string, error) {
	return func(ctx context.Context, target, taskID string) ([]string, error) {
		logger := slog.Default().With("target", target, "task", taskID)
		logger.Info("读取节点本轮 diff")
		if r.Clients == nil {
			err := fmt.Errorf("节点 diff 客户端未装配")
			logger.Warn("取得节点 diff 客户端失败", "cause", err)
			return nil, err
		}
		cl, err := r.Clients(target)
		if err != nil {
			logger.Warn("取得节点 diff 客户端失败", "cause", err)
			return nil, err
		}
		raw, err := cl.Diff(ctx, taskID, "")
		if err != nil {
			logger.Warn("取得节点 diff 失败", "cause", err)
			return nil, err
		}
		paths := ChangedPaths(raw)
		logger.Info("节点本轮 diff 已投影", "changed_paths", paths)
		return paths, nil
	}
}

n_ledgerstep_StepRunner_dispatchNode.signature:
// dispatchNode 生产 NodeStep.Dispatch：按节点的模板引用 + 单字段覆盖派发。
func (r *StepRunner) dispatchNode(outputPath *string) func(context.Context, ledger.Card, ledger.NodeDef) (string, string, error) {
	return r.dispatchNodeWithGate(outputPath, nil)
}

n_ledgerstep_StepRunner_dispatchNodeWith.signature:
// dispatchNodeWithGate 是运行节点的派发适配器；写闸只在 Transport 返回后
// 约束协调者原子账本写入，远端任务已经受理的事实不回滚，也不因此重派第二 task。
func (r *StepRunner) dispatchNodeWithGate(outputPath *string, writeGate func() bool) func(context.Context, ledger.Card, ledger.NodeDef) (string, string, error) {
	return func(ctx context.Context, card ledger.Card, node ledger.NodeDef) (string, string, error) {
		target := r.Target
		if target == "" {
			target = node.Override.Target
		}
		executor := node.Override.Executor
		model := node.Override.Model
		if r.Executor != "" {

			executor = r.Executor
			if r.Model != "" || r.Executor != node.Override.Executor {
				model = r.Model
			}
		} else if r.Model != "" {
			model = r.Model
		}
		renderedPath := ""
		if node.Produces != nil {
			renderedPath = RenderOutputPath(node.Produces.Path, card, node, r.now())
		}
		if outputPath != nil {
			*outputPath = renderedPath
		}
		slog.Default().Info("准备派发节点", "card", card.ID, "node", node.Name,
			"target", target, "kind", outputKind(node), "output_path", renderedPath)
		result, err := r.Dispatcher.ViaTemplate(ctx, card, TemplateDispatch{
			Template:		node.Template,
			Target:			target,
			Receiver:		node.Override.Squad,
			Node:			node.Name,
			DisciplineOverride:	node.Override.Discipline,
			ExecutorOverride:	executor,
			ModelOverride:		model,
			CarryCardContext:	node.CarryCardContext,
			PurposeOverride:	node.Override.Purpose,
			OmitAcceptance:		node.OmitAcceptance,
			Extra:			r.Extra,
			OutputPath:		renderedPath,
			WriteGate:		writeGate,
		})
		if err != nil {
			slog.Default().Warn("节点派发失败", "card", card.ID, "node", node.Name,
				"target", target, "output_path", renderedPath, "cause", err)
			return "", "", err
		}
		slog.Default().Info("节点派发完成", "card", card.ID, "node", node.Name,
			"target", result.Target, "task", result.Task, "output_path", renderedPath)
		return result.Target, result.Task, nil
	}
}

n_ledgerstep_StepRunner_finishTask.signature:
// finishTask 生产 NodeStep.FinishTask：在发布工作分支之后归档，避免 Done 先回收 worktree。
func (r *StepRunner) finishTask() func(context.Context, string, string) error {
	return func(ctx context.Context, target, taskID string) error {
		logger := slog.Default().With("target", target, "task", taskID)
		if r.Clients == nil {
			return fmt.Errorf("节点归档客户端未装配")
		}
		cl, err := r.Clients(target)
		if err != nil {
			logger.Warn("取得节点归档客户端失败", "cause", err)
			return err
		}
		if _, err := cl.Done(ctx, taskID, ""); err != nil {
			return err
		}
		return nil
	}
}

n_ledgerstep_StepRunner_haltEntrypoint.signature:
// haltEntrypoint 把 RunOnce 之外的入口失败同步写入卡事件流，保证 card wait 有唯一可见证据。
func (r *StepRunner) haltEntrypoint(cardID, nodeName, reason, body string) (Outcome, error) {
	logger := slog.Default().With("card", cardID, "node", nodeName)
	if _, err := r.St.AddComment(cardID, body, "普通", "node:"+nodeName); err != nil {
		logger.Error("入口失败落卡：写评论失败", "reason", reason, "cause", err)
		return Outcome{}, fmt.Errorf("入口失败落卡（原始原因：%s）：%w", body, err)
	}
	if err := r.St.MarkNeedsHuman(cardID, reason, "node:"+nodeName); err != nil {
		logger.Error("入口失败落卡：打等人标记失败", "reason", reason, "cause", err)
		return Outcome{}, fmt.Errorf("入口失败打等人标记（原始原因：%s）：%w", body, err)
	}
	logger.Info("入口失败已落卡", "reason", reason)
	return Outcome{Action: ActionNeedsHuman, Reason: reason}, nil
}

