n_ledgerstep_clientFinalMessage.signature:
// clientFinalMessage 从 attach 快照取最后一条 completed/turn_failed/failed
// 事件，按真实协议字段返回最终报文；缺失即报错，不拿 progress 凑数。
func clientFinalMessage(ctx context.Context, cl finalMessageClient, taskID string) (string, error) {
	info, err := cl.Attach(ctx, taskID)
	if err != nil {
		slog.ErrorContext(ctx, "取审阅 Attach 快照失败", "task", taskID, "error", err)
		return "", fmt.Errorf("取审阅最终报文: %w", err)
	}
	slog.InfoContext(ctx, "取到审阅 Attach 快照", "task", taskID, "events", len(info.RecentEvents))
	message, err := finalMessageFromEvents(info.RecentEvents)
	if err != nil {
		slog.ErrorContext(ctx, "从 Attach 快照取审阅最终报文失败", "task", taskID, "error", err)
		return "", fmt.Errorf("取审阅最终报文: %w", err)
	}
	slog.InfoContext(ctx, "取审阅最终报文完成", "task", taskID, "bytes", len(message))
	return message, nil
}

n_ledgerstep_containsPath.signature:
func containsPath(paths []string, want string) bool {
	for _, path := range paths {
		if path == want {
			return true
		}
	}
	return false
}

n_ledgerstep_datePrefixedDeclaredPath.signature:
// datePrefixedDeclaredPath 只识别与 declaredPath 同目录、且 basename 形如
// YYYY-MM-DD-+声明 basename 的改名错误；其它日期文件仍按普通缺失处理。
func datePrefixedDeclaredPath(declaredPath string, changedPaths []string) (actualPath string, ok bool) {
	if declaredPath == "" {
		return "", false
	}
	declaredDir := filepath.Dir(declaredPath)
	declaredBase := filepath.Base(declaredPath)
	const datePrefixLength = len("YYYY-MM-DD-")
	for _, changedPath := range changedPaths {
		if filepath.Dir(changedPath) != declaredDir {
			continue
		}
		actualBase := filepath.Base(changedPath)
		if len(actualBase) != datePrefixLength+len(declaredBase) ||
			actualBase[datePrefixLength:] != declaredBase ||
			actualBase[4] != '-' || actualBase[7] != '-' || actualBase[10] != '-' {
			continue
		}
		validDigits := true
		for i := 0; i < 10; i++ {
			if i == 4 || i == 7 {
				continue
			}
			if actualBase[i] < '0' || actualBase[i] > '9' {
				validDigits = false
				break
			}
		}
		if validDigits {
			return changedPath, true
		}
	}
	return "", false
}

n_ledgerstep_decodeCompletedPayload.signature:
func decodeCompletedPayload(event *proto.Event) (completedPayload, error) {
	if event == nil {
		return completedPayload{}, errors.New("completed event 为空")
	}
	var payload completedPayload
	if err := json.Unmarshal(event.Payload, &payload); err != nil {
		return completedPayload{}, fmt.Errorf("解析 completed payload 失败: %w", err)
	}
	return payload, nil
}

n_ledgerstep_decodeVerdictField.signature:
func decodeVerdictField(raw, key string, dst any) bool {
	pat := regexp.MustCompile(`(?s)"` + regexp.QuoteMeta(key) + `"\s*:\s*`)
	loc := pat.FindStringIndex(raw)
	if loc == nil {
		return false
	}
	dec := json.NewDecoder(strings.NewReader(raw[loc[1]:]))
	if err := dec.Decode(dst); err != nil {
		return false
	}
	tail := strings.TrimSpace(raw[loc[1]+int(dec.InputOffset()):])
	return tail == "" || tail[0] == ',' || tail[0] == '}'
}

n_ledgerstep_diffHeaderFields.signature:
func diffHeaderFields(raw string) []string {
	fields := make([]string, 0, 2)
	for len(strings.TrimSpace(raw)) > 0 && len(fields) < 2 {
		raw = strings.TrimLeft(raw, " \t")
		if raw == "" {
			break
		}
		if raw[0] == '"' {
			end := 1
			escaped := false
			for end < len(raw) {
				if raw[end] == '"' && !escaped {
					break
				}
				if raw[end] == '\\' && !escaped {
					escaped = true
				} else {
					escaped = false
				}
				end++
			}
			if end >= len(raw) {
				break
			}
			fields = append(fields, raw[:end+1])
			raw = raw[end+1:]
			continue
		}
		end := strings.IndexAny(raw, " \t")
		if end < 0 {
			fields = append(fields, raw)
			break
		}
		fields = append(fields, raw[:end])
		raw = raw[end:]
	}
	return fields
}

n_ledgerstep_diffPath.signature:
func diffPath(raw string) string {
	path := strings.TrimSpace(raw)
	if tab := strings.IndexByte(path, '\t'); tab >= 0 {
		path = path[:tab]
	}
	if len(path) >= 2 && path[0] == '"' && path[len(path)-1] == '"' {
		if unquoted, err := strconv.Unquote(path); err == nil {
			path = unquoted
		}
	}
	if path == "/dev/null" {
		return ""
	}
	if strings.HasPrefix(path, "a/") || strings.HasPrefix(path, "b/") {
		return path[2:]
	}
	return path
}

n_ledgerstep_disciplineAndTarget.signature:
// disciplineAndTarget 返回一次模板派发的有效（纪律角色名，目标机）：
// 请求覆盖优先，模板缺省兜底。ViaTemplate 与 PreflightDiscipline 必须共用
// 这一份实现——调用方的缝 1 解析若与派发时的裁决漂移，探活会打错机器、
// 正文会配错名字，拒发闸反而变成事故源。
func disciplineAndTarget(def ledger.TemplateDef, overrideName, reqTarget string) (name, target string) {
	name = def.Discipline
	if overrideName != "" {
		name = overrideName
	}
	target = reqTarget
	if target == "" {
		target = def.Target
	}
	return name, target
}

n_ledgerstep_finalMessageFromEvents.signature:
// finalMessageFromEvents 是协议字段解析的纯函数，供 wire 层单测固定
// completed.summary 与 turn_failed/failed.fail_reason 的真实线格式。
func finalMessageFromEvents(events []proto.Event) (string, error) {
	// completed 优先于失败类事件，即使失败排在后面：codex 收尾时常在
	// completed 之后再补一条 turn_failed（app-server 的 WebSocket 断开），
	// 那是传输层的假警报，不是回合失败——报告已经在 completed 里了。
	// 多条 completed 时继续扫描，非空 final_text 优先于摘要与显式空值。
	var summary string
	summaryAvailable := false
	explicitEmpty := false
	for i := len(events) - 1; i >= 0; i-- {
		event := events[i]
		if event.Type != proto.EventTypeCompleted {
			continue
		}
		payload, err := decodeCompletedPayload(&event)
		if err != nil {
			slog.Warn("跳过不可解析的 completed payload", "index", i, "error", err)
			continue
		}
		if payload.FinalText != nil {
			if *payload.FinalText != "" {
				return *payload.FinalText, nil
			}
			explicitEmpty = true
			continue
		}
		if payload.Summary == "" {
			slog.Warn("completed payload 缺 summary", "index", i)
			continue
		}
		if !summaryAvailable {
			summary = payload.Summary
			summaryAvailable = true
		}
	}
	if summaryAvailable {
		return summary, nil
	}
	if explicitEmpty {
		return "", fmt.Errorf("completed payload final_text 为空")
	}
	for i := len(events) - 1; i >= 0; i-- {
		event := events[i]
		if event.Type != proto.EventTypeTurnFailed && event.Type != proto.EventTypeFailed {
			continue
		}
		var payload struct {
			FailReason string `json:"fail_reason"`
		}
		if err := json.Unmarshal(event.Payload, &payload); err != nil {
			return "", fmt.Errorf("failed payload 解析失败: %w", err)
		}
		if payload.FailReason == "" {
			return "", fmt.Errorf("failed payload 缺 fail_reason")
		}
		return payload.FailReason, nil
	}
	return "", fmt.Errorf("事件流中没有 completed/failed 最终报文")
}

n_ledgerstep_firstVerdictValue.signature:
func firstVerdictValue(raw string) (string, bool) {
	pat := regexp.MustCompile(`(?s)"verdict"\s*:\s*"(pass|fail)"`)
	match := pat.FindStringSubmatch(raw)
	if len(match) != 2 {
		return "", false
	}
	return match[1], true
}

n_ledgerstep_indentLines.signature:
// indentLines 给多行文本每行加前缀，让验收判据在 markdown 列表下缩进对齐。
func indentLines(s, prefix string) string {
	lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
	for i, line := range lines {
		lines[i] = prefix + line
	}
	return strings.Join(lines, "\n")
}

n_ledgerstep_isReviewLedgerPath.signature:
// isReviewLedgerPath 只允许审阅节点写入两类台账目录自身或其 POSIX 子路径。
// 使用字符串边界而非 filepath，是因为 Diff 契约传的是仓内 POSIX 路径，不能让执行平台
// 的分隔符转换改变白名单；尾斜杠边界也防止 docs/ledgers-extra 越过目录边界。
func isReviewLedgerPath(path string) bool {
	for _, prefix := range reviewLedgerPathPrefixes {
		if path == prefix || strings.HasPrefix(path, prefix+"/") {
			return true
		}
	}
	return false
}

n_ledgerstep_outputKind.signature:
func outputKind(node ledger.NodeDef) string {
	if node.Produces == nil {
		return ""
	}
	return node.Produces.Kind
}

n_ledgerstep_reviewReadOnlyViolations.signature:
// reviewReadOnlyViolations 按 Diff 返回顺序保留全部白名单外路径，不去重、不排序，供
// review 节点在裁决落账前形成可审计的普通评论。
func reviewReadOnlyViolations(paths []string) []string {
	violations := make([]string, 0)
	for _, path := range paths {
		if !isReviewLedgerPath(path) {
			violations = append(violations, path)
		}
	}
	return violations
}

n_ledgerstep_waitForTurnEnd.signature:
// waitForTurnEnd 反复 wait 直到收到带正文的 completed 或真实失败终态，
// 中途的权限门与工单一律跳过继续等。
//
// why 要循环：WaitEvent 返回的是「首个可动作事件」而非终态。审阅虽只跑
// 只读命令，但同样要过权限门，也可能发工单——2026-08-19 真机实测，环节
// 几乎必然醒在 permission_request/question 上，随即去取最终报文，报
// 「事件流中没有 completed/failed 最终报文」，一轮审阅白跑。函数头写的
// 「wait 终态」是意图，WaitEvent 的语义不是，这里补上差额。
//
// 收到缺正文的 completed 后，后续 wait 使用秒级 child deadline 给迟到正文机会；
// deadline 到期且 parent 仍存活时返回成功，由 Attach 快照回落摘要。
func waitForTurnEnd(ctx context.Context, wait func(context.Context) (*proto.Event, error)) error {
	for {
		event, err := wait(ctx)
		if err != nil {
			slog.ErrorContext(ctx, "等待回合终态失败", "saw_completed", false, "error", err)
			return err
		}
		if event == nil {
			slog.WarnContext(ctx, "等待回合终态收到空事件")
			continue
		}
		switch event.Type {
		case proto.EventTypeCompleted:
			payload, decodeErr := decodeCompletedPayload(event)
			if decodeErr != nil {
				slog.WarnContext(ctx, "completed payload 不可解析，进入宽限", "error", decodeErr)
			} else if payload.FinalText != nil && *payload.FinalText != "" {
				slog.InfoContext(ctx, "收到带 final_text 的 completed")
				return nil
			} else {
				finalTextPresent := payload.FinalText != nil
				slog.InfoContext(ctx, "收到残缺 completed，进入宽限", "final_text_present", finalTextPresent)
			}
			return waitForTurnEndGrace(ctx, wait)
		case proto.EventTypeTurnFailed, proto.EventTypeFailed:
			slog.InfoContext(ctx, "未见 completed，失败事件收口", "event_type", event.Type)
			return nil
		}
	}
}

n_ledgerstep_waitForTurnEndGrace.signature:
func waitForTurnEndGrace(ctx context.Context, wait func(context.Context) (*proto.Event, error)) error {
	waitCtx, cancel := context.WithTimeout(ctx, turnEndGrace)
	defer cancel()
	for {
		event, err := wait(waitCtx)
		if err != nil {
			if errors.Is(err, context.DeadlineExceeded) && ctx.Err() == nil {
				slog.InfoContext(ctx, "completed 宽限到期，继续收取 Attach 摘要")
				return nil
			}
			slog.ErrorContext(ctx, "等待回合终态失败", "saw_completed", true, "error", err)
			return err
		}
		if event == nil {
			slog.WarnContext(ctx, "等待回合终态收到空事件")
			continue
		}
		if event.Type == proto.EventTypeCompleted {
			payload, decodeErr := decodeCompletedPayload(event)
			if decodeErr != nil {
				slog.WarnContext(ctx, "宽限内 completed payload 不可解析，继续等待", "error", decodeErr)
				continue
			}
			if payload.FinalText != nil && *payload.FinalText != "" {
				slog.InfoContext(ctx, "宽限内收到带 final_text 的 completed")
				return nil
			}
			slog.InfoContext(ctx, "宽限内收到残缺 completed，继续等待", "final_text_present", payload.FinalText != nil)
			continue
		}
		if event.Type == proto.EventTypeTurnFailed || event.Type == proto.EventTypeFailed {
			slog.InfoContext(ctx, "宽限内忽略失败事件，继续等待 completed", "event_type", event.Type)
		}
	}
}

n_localsync_Fetch.signature:
// Fetch 把远程任务分支同步到本地同名分支。
//
// 参数：
//   - ctx: 上层上下文；内部叠加 FetchTimeout
//   - o:   同步参数，见 Opts
//
// 返回：
//   - Result: 同步增量
//   - err: LocalRepo 不是 git 仓库、参数非法、ssh/网络失败、或本地分支与远程分叉
//     （非快进）时返回错误，错误文本含 git stderr 原文
//
// 注意：
//   - 非快进由 git 自身拒绝（fetch <src>:<dst> 的默认语义），这正是要的行为——
//     宁可报错也不能悄悄覆盖协调者的本地提交
func Fetch(ctx context.Context, o Opts) (Result, error) {
	if o.LocalRepo == "" || o.RemoteURL == "" || o.Branch == "" {
		return Result{}, fmt.Errorf("同步参数不完整：local=%q remote=%q branch=%q", o.LocalRepo, o.RemoteURL, o.Branch)
	}

	if strings.HasPrefix(o.Branch, "-") || strings.HasPrefix(o.RemoteURL, "-") {
		return Result{}, fmt.Errorf("分支名/远程地址不允许以 - 开头：branch=%q remote=%q", o.Branch, o.RemoteURL)
	}
	ctx, cancel := context.WithTimeout(ctx, FetchTimeout)
	defer cancel()

	if _, _, err := run(ctx, o.LocalRepo, "rev-parse", "--git-dir"); err != nil {
		return Result{}, fmt.Errorf("%s 不是 git 仓库，跳过同步: %w", o.LocalRepo, err)
	}
	before, _, err := run(ctx, o.LocalRepo, "rev-parse", "--verify", "--quiet", "refs/heads/"+o.Branch)
	created := err != nil || strings.TrimSpace(before) == ""

	log().Info("本地同步开始", "local", o.LocalRepo, "remote", o.RemoteURL, "branch", o.Branch, "created", created)
	refspec := o.Branch + ":" + o.Branch
	if _, stderr, ferr := run(ctx, o.LocalRepo, "fetch", o.RemoteURL, refspec); ferr != nil {

		log().Debug("本地同步失败", "local", o.LocalRepo, "remote", o.RemoteURL, "branch", o.Branch,
			"stderr", strings.TrimSpace(stderr), "cause", ferr)
		return Result{}, fmt.Errorf("git fetch %s %s: %s: %w", o.RemoteURL, refspec, strings.TrimSpace(stderr), ferr)
	}

	res := Result{Branch: o.Branch, Created: created}
	if !created {

		countOut, _, cerr := run(ctx, o.LocalRepo, "rev-list", "--count", strings.TrimSpace(before)+".."+o.Branch)
		if cerr == nil {
			if n, perr := strconv.Atoi(strings.TrimSpace(countOut)); perr == nil {
				res.Commits = n
			}
		}
	}
	log().Info("本地同步完成", "branch", res.Branch, "commits", res.Commits, "created", res.Created)
	return res, nil
}

n_localsync_run.signature:
// run 在 dir 里执行 git 命令，返回 stdout 与 stderr。
func run(ctx context.Context, dir string, args ...string) (stdout, stderr string, err error) {
	cmd := exec.CommandContext(ctx, "git", append([]string{"-C", dir}, args...)...)
	var out, errb strings.Builder
	cmd.Stdout = &out
	cmd.Stderr = &errb
	err = cmd.Run()
	return out.String(), errb.String(), err
}

n_logging_StatusLog.signature:
// StatusLog 返回编制域结构化 logger（mod=scheduling）。包级日志入口的实现细节，
// 无跨域消费者；公开 scheduling 包经 statusLog() 转发，保持调用点不变。
func StatusLog() *slog.Logger	{ return slog.Default().With("mod", "scheduling") }

n_logx_Setup.signature:
// Setup 创建并返回带 component 标签的 logger。
//
// 参数：
//   - component: 日志中固定的组件标识（如 "agentd"）
//   - logPath: JSON 日志文件路径；为空时只写 stderr 文本日志
//
// 返回：
//   - 同时写 JSON 文件与 stderr 文本的 logger
//
// 注意：
//   - 日志级别由环境变量 HANDOFF_LOG_LEVEL 控制（debug/info/warn/error，默认 info）
//   - 日志文件打开失败时降级为仅 stderr 并输出 Warn，不影响程序运行
func Setup(component, logPath string) *slog.Logger {
	lvl := parseLevel(os.Getenv("HANDOFF_LOG_LEVEL"))
	hs := []slog.Handler{slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{Level: lvl})}
	if logPath != "" {
		if f, err := os.OpenFile(logPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600); err == nil {
			hs = append(hs, slog.NewJSONHandler(f, &slog.HandlerOptions{Level: lvl}))
		} else {

			slog.Warn("日志文件打开失败，降级为仅 stderr", "path", logPath, "err", err)
		}
	}
	return slog.New(&multiHandler{hs: hs}).With("component", component)
}

n_logx_multiHandler_Enabled.signature:
// Enabled 只要任一子 handler 启用该级别即视为启用。
func (m *multiHandler) Enabled(ctx context.Context, lvl slog.Level) bool {
	for _, h := range m.hs {
		if h.Enabled(ctx, lvl) {
			return true
		}
	}
	return false
}

n_logx_multiHandler_Handle.signature:
// Handle 将记录依次交给所有子 handler，任一失败即返回错误。
func (m *multiHandler) Handle(ctx context.Context, r slog.Record) error {
	for _, h := range m.hs {
		if err := h.Handle(ctx, r); err != nil {
			return err
		}
	}
	return nil
}

n_logx_multiHandler_WithAttrs.signature:
// WithAttrs 将属性广播给所有子 handler 后返回新的 multiHandler。
func (m *multiHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	hs := make([]slog.Handler, len(m.hs))
	for i, h := range m.hs {
		hs[i] = h.WithAttrs(attrs)
	}
	return &multiHandler{hs: hs}
}

n_logx_multiHandler_WithGroup.signature:
// WithGroup 将分组广播给所有子 handler 后返回新的 multiHandler。
func (m *multiHandler) WithGroup(name string) slog.Handler {
	hs := make([]slog.Handler, len(m.hs))
	for i, h := range m.hs {
		hs[i] = h.WithGroup(name)
	}
	return &multiHandler{hs: hs}
}

n_logx_parseLevel.signature:
// parseLevel 将环境变量字符串解析为 slog.Level，非法或空值回退到 info。
func parseLevel(s string) slog.Level {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "debug":
		return slog.LevelDebug
	case "warn", "warning":
		return slog.LevelWarn
	case "error":
		return slog.LevelError
	default:
		return slog.LevelInfo
	}
}

n_main_main.signature:
func main() {
	cmd.SetSkillContent(skillContent)

	if err := cmd.Execute(); err != nil {
		os.Exit(cmd.ExitCode(err))
	}
}

n_opencode_API_CreateSession.signature:
// CreateSession 在 opencode server 上创建会话。
//
// 返回：
//   - sessionID: 新建会话的 id，后续 PromptAsync / RespondPermission 都需要它
//   - err: 请求或解析失败
func (a *API) CreateSession(ctx context.Context) (sessionID string, err error) {
	start := time.Now()
	const path = "/session"
	a.log().Info("opencode 创建会话", "path", path)
	defer func() {
		if err != nil {
			a.log().Error("opencode 创建会话失败", "path", path, "cause", err)
		} else {
			a.log().Info("opencode 会话已创建", "path", path, "session", sessionID,
				"elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodPost, path, sessionCreateRequest{Title: sessionTitle})
	if err != nil {
		return "", fmt.Errorf("创建会话请求: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return "", a.httpError("创建会话", resp)
	}
	var out sessionResponse
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", fmt.Errorf("解析创建会话响应: %w", err)
	}
	if out.ID == "" {
		return "", fmt.Errorf("创建会话响应缺少 id 字段")
	}
	return out.ID, nil
}

n_opencode_API_GetSession.signature:
// GetSession 取单个会话的详情，用于把子会话归属回父任务。
//
// 参数：
//   - ctx: 上下文；调用方负责叠加 ownershipTimeout
//   - sessionID: 目标会话 id
//
// 返回：
//   - sessionDetail: 会话详情
//   - err: sessionID 为空、请求失败、非 2xx、响应解析失败时非 nil，此时详情为零值
//
// 注意：
//   - sessionID 为空直接返回错误，不触达服务端：拿空 id 拼出的 "/session/" 只会
//     换来一个 404，白白占掉一次超时预算
//   - 本方法在 SSE 事件回调里同步调用（见 adapter.resolveChildSession），
//     阻塞的是本任务的事件流——超时必须用 ownershipTimeout 而非 unaryTimeout
func (a *API) GetSession(ctx context.Context, sessionID string) (d sessionDetail, err error) {
	if sessionID == "" {
		return sessionDetail{}, fmt.Errorf("查询会话详情：会话 id 为空")
	}
	start := time.Now()
	path := "/session/" + sessionID
	a.log().Info("opencode 查询会话详情", "path", path, "session", sessionID)
	defer func() {
		if err != nil {
			a.log().Error("opencode 查询会话详情失败", "path", path, "session", sessionID, "cause", err)
		} else {
			a.log().Info("opencode 会话详情已取得", "path", path, "session", sessionID,
				"parent", d.ParentID, "elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodGet, path, nil)
	if err != nil {
		return sessionDetail{}, fmt.Errorf("查询会话详情请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return sessionDetail{}, a.httpError("查询会话详情", resp)
	}
	if err := json.NewDecoder(resp.Body).Decode(&d); err != nil {
		return sessionDetail{}, fmt.Errorf("解析会话详情: %w", err)
	}
	return d, nil
}

n_opencode_API_HasSession.signature:
// HasSession 检查指定会话 id 是否仍存在于 serve 的会话列表里。
//
// 返回：
//   - ok: 会话是否在场；GET /session 失败或列表解析失败时返回 (false, err)
//
// 注意：
//   - 本方法只用于冷恢复的会话在场校验（spec §5.5.2）：会话存在全局 sqlite，
//     进程重起不影响它，但要确认它真的还在——不能默认。不在就降级新会话
func (a *API) HasSession(ctx context.Context, sessionID string) (ok bool, err error) {
	start := time.Now()
	const path = "/session"
	a.log().Info("opencode 查询会话列表", "path", path)
	defer func() {
		if err != nil {
			a.log().Error("opencode 查询会话列表失败", "path", path, "cause", err)
		} else {
			a.log().Info("opencode 会话在场校验完成", "path", path, "session", sessionID,
				"ok", ok, "elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodGet, path, nil)
	if err != nil {
		return false, fmt.Errorf("查询会话列表请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return false, a.httpError("查询会话列表", resp)
	}
	var list []sessionListItem
	if err := json.NewDecoder(resp.Body).Decode(&list); err != nil {
		return false, fmt.Errorf("解析会话列表: %w", err)
	}
	for _, s := range list {
		if s.ID == sessionID {
			return true, nil
		}
	}
	return false, nil
}

n_opencode_API_LastAssistantMessage.signature:
// LastAssistantMessage 取会话里最后一条 assistant 消息（对账的数据源，B38）。
//
// 参数：
//   - ctx: 控制单次请求超时
//   - sessionID: 目标会话
//
// 返回：
//   - (*SessionMessage, nil): 找到了。CompletedMS==0 表示该回合仍在进行
//   - (nil, nil): 会话里还没有任何 assistant 消息——**合法状态，不是错误**
//   - (nil, err): 请求或解析失败
//
// 注意：
//   - 只看最后一条 assistant 消息就够，依据是「一个断连窗口内至多跨越一个回合
//     边界」（spec §2.2）；不需要全量拉取比对
//   - 权限请求**查不回来**：本端点的 tool part 只有 callID 没有权限 id，而
//     RespondPermission 要求真实 id、伪造即 404（更早的 spike 结论，见
//     adapter.go 的 onReconnect 降级告警）。故本方法不尝试提取权限
func (a *API) LastAssistantMessage(ctx context.Context, sessionID string) (msg *SessionMessage, err error) {
	start := time.Now()
	path := "/session/" + sessionID + "/message"
	a.log().Info("opencode 查会话尾部", "path", path, "session", sessionID)
	defer func() {
		switch {
		case err != nil:
			a.log().Error("opencode 查会话尾部失败", "path", path, "session", sessionID, "cause", err)
		case msg == nil:
			a.log().Info("opencode 会话尾部无 assistant 消息", "path", path,
				"session", sessionID, "elapsed_ms", time.Since(start).Milliseconds())
		default:
			a.log().Info("opencode 会话尾部已取得", "path", path, "session", sessionID,
				"msg", msg.ID, "completed_ms", msg.CompletedMS, "has_error", msg.ErrorText != "",
				"text_runes", len([]rune(msg.Text)), "elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodGet, path, nil)
	if err != nil {
		return nil, fmt.Errorf("查会话消息请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, a.httpError("查会话消息", resp)
	}
	var list []sessionMessageEnvelope
	if err := json.NewDecoder(resp.Body).Decode(&list); err != nil {
		return nil, fmt.Errorf("解析会话消息: %w", err)
	}

	for i := len(list) - 1; i >= 0; i-- {
		e := list[i]
		if e.Info.Role != "assistant" {
			continue
		}
		out := &SessionMessage{
			ID:		e.Info.ID,
			Role:		e.Info.Role,
			CompletedMS:	e.Info.Time.Completed,
			Finish:		e.Info.Finish,
		}

		if s := strings.TrimSpace(string(e.Info.Error)); s != "" && s != "null" {
			out.ErrorText = s
			var errObj struct {
				Name string `json:"name"`
			}
			if json.Unmarshal(e.Info.Error, &errObj) == nil {
				out.ErrorName = errObj.Name
			}
		}
		var sb strings.Builder
		for _, p := range e.Parts {
			if p.Type == "text" && p.Text != "" {
				sb.WriteString(p.Text)
			}
			if p.Type == "tool" && p.State.Status != "" {
				out.ToolStatus = p.State.Status
			}
		}
		out.Text = sb.String()
		return out, nil
	}
	return nil, nil
}

n_opencode_API_ListPendingQuestions.signature:
// ListPendingQuestions 拉取当前全部挂起的提问请求（跨会话）。
//
// 返回：挂起请求列表；请求失败或解析失败时返回错误，列表为 nil
//
// 注意：
//   - 返回的是**全部会话**的挂起请求，调用方必须按 SessionID 过滤出自己的
//   - agentd 重启后重新发现挂起提问的唯一途径：SSE 无重放语义，重启窗口里
//     发生的 question.asked 永远收不到
func (a *API) ListPendingQuestions(ctx context.Context) (out []PendingQuestion, err error) {
	start := time.Now()
	const path = "/question"
	a.log().Info("opencode 查询挂起提问", "path", path)
	defer func() {
		if err != nil {
			a.log().Error("opencode 查询挂起提问失败", "path", path, "cause", err)
		} else {
			a.log().Info("opencode 挂起提问已取得", "path", path, "count", len(out),
				"elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodGet, path, nil)
	if err != nil {
		return nil, fmt.Errorf("查询挂起提问请求: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, a.httpError("查询挂起提问", resp)
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return nil, fmt.Errorf("解析挂起提问: %w", err)
	}
	return out, nil
}

n_opencode_API_PromptAsync.signature:
// PromptAsync 向会话发送一条 prompt，opencode 随即开始执行，函数立即返回。
//
// 参数：
//   - sessionID: CreateSession 返回的会话 id
//   - text: prompt 文本（计划内容、用户指令等）
//
// 注意：
//   - 本调用不等待执行结果，执行事件通过 SubscribeEvents 消费
func (a *API) PromptAsync(ctx context.Context, sessionID, text string) (err error) {
	start := time.Now()
	path := "/session/" + sessionID + "/prompt_async"
	a.log().Info("opencode 发送 prompt", "path", path, "session", sessionID,
		"prompt_len", len(text))
	defer func() {
		if err != nil {
			a.log().Error("opencode 发送 prompt 失败", "path", path, "session", sessionID,
				"cause", err)
		} else {
			a.log().Info("opencode prompt 已发送", "path", path, "session", sessionID,
				"elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodPost, path, promptAsyncRequest{
		Parts: []promptPart{{Type: "text", Text: text}},
	})
	if err != nil {
		return fmt.Errorf("发送 prompt: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return a.httpError("发送 prompt", resp)
	}
	return nil
}

n_opencode_API_RejectQuestion.signature:
// RejectQuestion 拒绝一条挂起的提问，解除 question 工具的阻塞。
//
// 参数：requestID 为 question.asked 事件里的 properties.id
//
// 注意：
//   - 用于「任务要停了但提问还挂着」的兜底解阻塞，不是协调者的正常答复通道
func (a *API) RejectQuestion(ctx context.Context, requestID string) (err error) {
	if requestID == "" {
		return fmt.Errorf("拒绝提问：请求 id 为空")
	}
	start := time.Now()
	path := "/question/" + requestID + "/reject"
	a.log().Info("opencode 拒绝提问", "path", path, "request", requestID)
	defer func() {
		if err != nil {
			a.log().Error("opencode 拒绝提问失败", "path", path, "request", requestID,
				"cause", err)
		} else {
			a.log().Info("opencode 提问已拒绝", "path", path, "request", requestID,
				"elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodPost, path, nil)
	if err != nil {
		return fmt.Errorf("拒绝提问: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return a.httpError("拒绝提问", resp)
	}
	return nil
}

n_opencode_API_ReplyQuestion.signature:
// ReplyQuestion 把协调者的答案回填给 opencode 的 question 工具，工具随即返回、
// 回合继续。
//
// 参数：
//   - requestID: question.asked 事件里的 properties.id
//   - answers: 按问题顺序排列，每项是该问选中的 label 数组
//
// 返回：
//   - 4xx 时返回可 errors.Is 命中 ErrCustomAnswerRejected 的错误（答案不被接受）
//   - 其余失败返回普通错误
func (a *API) ReplyQuestion(ctx context.Context, requestID string, answers [][]string) (err error) {
	if requestID == "" {
		return fmt.Errorf("应答提问：请求 id 为空")
	}
	start := time.Now()
	path := "/question/" + requestID + "/reply"
	a.log().Info("opencode 应答提问", "path", path, "request", requestID,
		"answer_count", len(answers))
	defer func() {
		if err != nil {
			a.log().Error("opencode 应答提问失败", "path", path, "request", requestID,
				"cause", err)
		} else {
			a.log().Info("opencode 提问应答完成", "path", path, "request", requestID,
				"elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodPost, path, questionReplyRequest{Answers: answers})
	if err != nil {
		return fmt.Errorf("应答提问: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode >= 400 && resp.StatusCode < 500 {

		return fmt.Errorf("%w: %v", ErrCustomAnswerRejected, a.httpError("应答提问", resp))
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return a.httpError("应答提问", resp)
	}
	return nil
}

n_opencode_API_RespondPermission.signature:
// RespondPermission 应答 opencode 的权限请求。
//
// 参数：
//   - sessionID: 权限所属会话
//   - permID: 权限请求 id（来自 SSE 事件的 permissionID 字段）
//   - response: "once"（批准本次）或 "reject"（拒绝）
//
// 注意：
//   - 非法 response 值直接返回错误，不触达服务端
func (a *API) RespondPermission(ctx context.Context, sessionID, permID, response string) (err error) {
	if response != "once" && response != "reject" {
		return fmt.Errorf("非法权限应答 %q，仅支持 once/reject", response)
	}
	start := time.Now()
	path := "/session/" + sessionID + "/permissions/" + permID
	a.log().Info("opencode 应答权限", "path", path, "session", sessionID,
		"permission", permID, "response", response)
	defer func() {
		if err != nil {
			a.log().Error("opencode 应答权限失败", "path", path, "session", sessionID,
				"permission", permID, "cause", err)
		} else {
			a.log().Info("opencode 权限应答完成", "path", path, "session", sessionID,
				"permission", permID, "elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	resp, err := a.do(ctx, http.MethodPost, path, map[string]string{"response": response})
	if err != nil {
		return fmt.Errorf("应答权限: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return a.httpError("应答权限", resp)
	}
	return nil
}

n_opencode_API_SubscribeEvents.signature:
// SubscribeEvents 订阅 GET /event（SSE），每收到一条事件就同步调用
// onEvent(raw)，直到 ctx 取消。
//
// 断流处理：连接意外断开（EOF/网络错误/服务端未就绪）后指数退避重连，
// 1s→2s→4s→…→30s 封顶，无限重试；ctx 取消时立即返回 nil。
//
// 参数：
//   - onEvent: 每条事件的回调（同步调用：顺序有保证，但回调阻塞会暂停消费）
//   - onReconnect: 断连后成功重连的回调（首次建连不触发）；调用方借此把
//     「断连间隙可能丢事件」的告警交到业务层（P1-10b，可为 nil）
//
// 返回：
//   - ctx 取消时返回**最后一次连接的失败原因**（最后一次连接健康则返回 nil）：
//     调用方拿它填 FailReason（A-7）。恒返回 nil 会让「看门狗判死 → 事件流退出」
//     的失败现场只剩 "<nil>"，零信息
//   - 解析器遇到无法恢复的流异常（如单行超过 1MB 上限）时返回错误
//
// 注意：
//   - 未知/解析失败的行（event: 行、注释、非 JSON data）Debug 跳过，绝不中断订阅
func (a *API) SubscribeEvents(ctx context.Context, onEvent func(json.RawMessage), onReconnect func()) error {
	backoff := a.sseInitialBackoff
	var lastErr error
	for attempt := 1; ; attempt++ {

		onEstablished := func() {
			if attempt > 1 && onReconnect != nil {

				onReconnect()
			}
		}
		start := time.Now()
		err := a.streamOnce(ctx, onEvent, onEstablished)
		lived := time.Since(start)
		lastErr = err
		if ctx.Err() != nil {

			return dropCtxCause(lastErr, ctx)
		}
		if err != nil {
			a.log().Info("SSE 连接失败，等待后重连", "attempt", attempt,
				"backoff_seconds", int(backoff.Seconds()), "lived_ms", lived.Milliseconds(),
				"cause", err)
		} else {
			a.log().Info("SSE 流结束，等待后重连", "attempt", attempt,
				"backoff_seconds", int(backoff.Seconds()), "lived_ms", lived.Milliseconds())
		}

		if lived >= a.sseStableAfter {
			backoff = a.sseInitialBackoff
		}
		select {
		case <-ctx.Done():
			return dropCtxCause(lastErr, ctx)
		case <-time.After(backoff):
		}
		if lived < a.sseStableAfter {
			backoff *= 2
			if backoff > a.sseMaxBackoff {
				backoff = a.sseMaxBackoff
			}
		}
	}
}

n_opencode_API_dispatch.signature:
// dispatch 把聚合的 data 行拼成事件体，合法 JSON 才回调 onEvent，其余 Debug 跳过。
//
// 多条 data 行按 SSE 规范用换行连接（对齐官方 SDK 的 dataLines.join("\n")）。
func (a *API) dispatch(data []string, onEvent func(json.RawMessage)) {
	if len(data) == 0 || (len(data) == 1 && data[0] == "") {
		return
	}
	raw := json.RawMessage(strings.Join(data, "\n"))
	if !json.Valid(raw) {
		a.log().Debug("SSE 事件非合法 JSON，跳过", "data", turn.TruncateRunes(string(raw), 120))
		return
	}
	onEvent(raw)
}

n_opencode_API_do.signature:
// do 发送带 basic auth 的 JSON 请求，返回响应（调用方负责关闭 resp.Body）。
//
// body 为 nil 时请求体为空；非 nil 时序列化为 JSON 并带 Content-Type。
func (a *API) do(ctx context.Context, method, path string, body any) (*http.Response, error) {
	var rd io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return nil, fmt.Errorf("序列化请求体 %s: %w", path, err)
		}
		rd = bytes.NewReader(b)
	}
	req, err := http.NewRequestWithContext(ctx, method, a.baseURL+path, rd)
	if err != nil {
		return nil, fmt.Errorf("构造请求 %s: %w", path, err)
	}
	req.Header.Set("Authorization", "Basic "+basicAuth("opencode", a.password))
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	return a.httpClient.Do(req)
}

n_opencode_API_httpError.signature:
// httpError 把非 2xx 响应转为带状态码与响应体（截断 200 字符）的错误，
// 并打 Error 日志——响应体是「服务端为什么拒绝」的第一手线索。
func (a *API) httpError(op string, resp *http.Response) error {
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 256))
	trunc := turn.TruncateRunes(string(body), 200)
	a.log().Error("opencode 请求失败", "op", op, "status", resp.StatusCode, "body", trunc)
	return fmt.Errorf("%s: 状态码 %d: %s", op, resp.StatusCode, trunc)
}

n_opencode_API_log.signature:
// log 返回运行时 slog.Default()。
//
// 为什么不用包级 var：logx.Setup 在 main 里才执行 slog.SetDefault，包级 var 在
// init 时求值会锁死默认 logger，导致本模块日志绕开 logx 的「JSON 文件 + stderr
// 双路」输出（与 Task 5 对 store/config 的同款修正）。
func (a *API) log() *slog.Logger {
	return slog.Default()
}

n_opencode_API_streamOnce.signature:
// streamOnce 建立一次 SSE 连接并消费到流结束，期间每条事件同步回调 onEvent。
//
// 返回：
//   - 流正常结束（服务端关闭）时返回 nil
//   - 连接失败、非 200、扫描器异常时返回对应错误
//
// 参数：
//   - onEstablished: 连接建立（HTTP 200）后立即回调（可为 nil）；供上层做
//     「成功连接」的退避复位与断连恢复通知（见 SubscribeEvents）
func (a *API) streamOnce(ctx context.Context, onEvent func(json.RawMessage), onEstablished func()) error {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, a.baseURL+"/event", nil)
	if err != nil {
		return fmt.Errorf("构造 SSE 请求: %w", err)
	}
	req.Header.Set("Authorization", "Basic "+basicAuth("opencode", a.password))

	resp, err := a.sseClient.Do(req)
	if err != nil {
		return fmt.Errorf("SSE 连接: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return a.httpError("订阅事件流", resp)
	}
	if onEstablished != nil {
		onEstablished()
	}

	a.log().Info("SSE 连接建立", "path", "/event")
	defer a.log().Info("SSE 连接关闭", "path", "/event")

	rawTap := rawtap.Open("opencode", "", a.log())
	defer rawTap.Close()

	sc := bufio.NewScanner(resp.Body)
	sc.Buffer(make([]byte, 64*1024), sseScanBuffer)
	var data []string
	for sc.Scan() {
		rawTap.Write(sc.Bytes())
		line := sc.Text()
		switch {
		case strings.HasPrefix(line, "data:"):

			data = append(data, strings.TrimSpace(strings.TrimPrefix(line, "data:")))
		case line == "":

			a.dispatch(data, onEvent)
			data = nil
		default:
			a.log().Debug("SSE 忽略未知行", "line", turn.TruncateRunes(line, 80))
		}
	}
	if err := sc.Err(); err != nil {

		if ctx.Err() == nil {
			a.log().Warn("SSE 流读取异常", "cause", err)
			return fmt.Errorf("SSE 流读取: %w", err)
		}
		return err
	}
	return nil
}

n_opencode_Adapter_ApplySnapshot.signature:
// ApplySnapshot 实现 executor.SnapshotApplier。
func (a *Adapter) ApplySnapshot(ctx context.Context, taskID string, snap executor.PolicySnapshot) error {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	a.log.Info("ApplySnapshot", "task", taskID, "version", snap.Version)
	if _, err := WritePermissionConfig(r.taskDir, "", snap); err != nil {
		return err
	}
	ok, err := probeServeReloadsConfig(ctx, r)
	if err != nil {
		return err
	}
	if !ok {
		return fmt.Errorf("OpenCode serve 未重载任务目录 opencode.json，新快照无法保证原生 allow ⊆ 快照")
	}
	return nil
}

n_opencode_Adapter_BindApproval.signature:
// BindApproval 实现 executor.ApprovalBinder。
func (a *Adapter) BindApproval(taskID string, client executor.ApprovalClient) error {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	r.approval = client
	return nil
}

n_opencode_Adapter_Events.signature:
// Events 返回任务的事件流通道（Start 后可用；Stop 或执行终结后关闭）。
//
// 注意（P1-11）：任务不在运行（未启动/已 Stop/运行态已随终结注销）时返回
// **已关闭的通道**而非 nil——契约是「通道关闭 = 执行终结」，消费方（manager
// 中介循环）靠 range 在关闭时退出；nil 通道会让 for-range 永久阻塞。Dispatch →
// go mediate 的调度窗口内 serve 若死亡，运行态已注销而中介循环尚未开始：返回
// 已关闭通道让中介循环立即退出、不泄漏 goroutine；该窗口内已产出的 failed
// 结果随运行态注销而丢失，是「尚未开始消费」的必然缝隙，任务状态由看门狗与
// 重启恢复兜底。
func (a *Adapter) Events(taskID string) <-chan executor.AdapterEvent {
	if r := a.lookup(taskID); r != nil {
		return r.evCh
	}
	ch := make(chan executor.AdapterEvent)
	close(ch)
	return ch
}

n_opencode_Adapter_Inspect.signature:
func (a *Adapter) Inspect(ctx context.Context, home string) ([]executor.SkillSite, error) {
	name := executor.SkillDirName("")
	site := filepath.Join(home, SkillsRelDir, name)
	target := filepath.Join(site, "SKILL.md")
	parent := filepath.Dir(filepath.Join(home, SkillsRelDir))
	if _, err := os.Stat(parent); errors.Is(err, os.ErrNotExist) {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
			Note:	parent + " 不存在（该 agent 未安装）",
		}}, nil
	}
	if _, err := os.Stat(target); errors.Is(err, os.ErrNotExist) {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
		}}, nil
	} else if err != nil {
		return []executor.SkillSite{{
			Path:	target,
			State:	executor.SkillMissing,
			Note:	"读取失败: " + err.Error(),
		}}, nil
	}
	return []executor.SkillSite{{
		Path:	target,
		State:	executor.SkillInstalled,
	}}, nil
}

n_opencode_Adapter_Install.signature:
func (a *Adapter) Install(ctx context.Context, req executor.SkillInstallReq) ([]executor.SkillSite, error) {
	name := executor.SkillDirName(req.Name)
	dir := filepath.Join(req.Home, SkillsRelDir)
	parent := filepath.Dir(dir)
	if _, err := os.Stat(parent); err != nil {
		return []executor.SkillSite{{
			Path:	filepath.Join(dir, name),
			State:	executor.SkillSkipped,
			Note:	parent + " 不存在（该 agent 未安装）",
		}}, nil
	}
	site := filepath.Join(dir, name)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"创建目录失败: " + err.Error(),
		}}, nil
	}
	if err := os.RemoveAll(site); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"清理旧落点失败: " + err.Error(),
		}}, nil
	}
	if err := os.MkdirAll(site, 0o755); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"创建落点目录失败: " + err.Error(),
		}}, nil
	}
	if err := os.WriteFile(filepath.Join(site, "SKILL.md"), []byte(req.Content), 0o644); err != nil {
		return []executor.SkillSite{{
			Path:	site,
			State:	executor.SkillSkipped,
			Note:	"写落点副本失败: " + err.Error(),
		}}, nil
	}
	return []executor.SkillSite{{
		Path:	site,
		State:	executor.SkillInstalled,
	}}, nil
}

n_opencode_Adapter_Invoke.signature:
func (a *Adapter) Invoke(ctx context.Context, req executor.OneShotReq) (executor.OneShotReply, error) {
	var log *slog.Logger
	if a != nil {
		log = a.log
	}
	return NewOneShot(log).Invoke(ctx, req)
}

n_opencode_Adapter_Prepare.signature:
// Prepare 将规则、技能与任务 overlay 写入 OpenCode 原生落点。
func (a *Adapter) Prepare(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	return a.Profile().Prepare(ctx, req)
}

n_opencode_Adapter_Probe.signature:
// Probe 只读探测 opencode serve 是否仍存活（manager 的 prober 可选接口）。
//
// 判据与 Resume 共用同一份 Proc.Alive：存活锁被持有且端口有 HTTP 应答，
// 缺一即视为死亡。
//
// 参数：
//   - req: 探测请求（TaskDir 是 proc.json 所在，即 DataDir/tasks/<id>）
//
// 返回：
//   - Alive=true：serve 仍在
//   - Alive=false + Note：已判死，Note 给协调者看
//   - err != nil：探不出结论（proc.json 缺失/损坏），调用方按 unknown 处理
func (a *Adapter) Probe(req executor.ProbeReq) (executor.ProbeOutcome, error) {
	si, err := readProcInfo(req.TaskDir)
	if err != nil {
		a.log.Info("opencode 探活：恢复凭据不可读，结论未知", "task", req.TaskID, "cause", err)
		return executor.ProbeOutcome{}, fmt.Errorf("读 opencode 恢复凭据: %w", err)
	}
	proc := &Proc{Handle: si.Handle, Port: si.Port, Password: si.Password}
	if proc.Alive() {
		a.log.Info("opencode 探活：serve 存活", "task", req.TaskID,
			"shim_pid", si.Handle.PID, "port", si.Port)
		return executor.ProbeOutcome{Alive: true}, nil
	}

	note := fmt.Sprintf("opencode serve 已不在（进程 pid %d，端口 %d）", si.Handle.PID, si.Port)
	a.log.Info("opencode 探活：serve 已不在", "task", req.TaskID,
		"shim_pid", si.Handle.PID, "port", si.Port)
	return executor.ProbeOutcome{Alive: false, Note: note}, nil
}

n_opencode_Adapter_ProcHandle.signature:
// ProcHandle 交出该任务的进程句柄（来自任务目录的 proc.json）。
//
// 参数：
//   - taskID: 任务 ID，仅用于日志定位
//   - taskDir: 任务目录（凭据所在）
//
// 返回：
//   - 进程句柄；proc.json 不存在或不可解析时返回错误
//
// 注意：本方法**只读**，不探活、不发信号——存活判定与回收分别是
// prochost.Alive 与 prochost.Sweep 的职责。agentd 以可选接口消费它
// （不实现该方法的 adapter 一律按「无凭据」降级，与 reaper/prober 同款路数）。
func (a *Adapter) ProcHandle(taskID, taskDir string) (prochost.Handle, error) {
	pi, err := readProcInfo(taskDir)
	if err != nil {
		a.log.Error("读取进程句柄失败", "task", taskID, "dir", taskDir, "cause", err)
		return prochost.Handle{}, fmt.Errorf("读取进程句柄: %w", err)
	}
	a.log.Debug("取得进程句柄", "task", taskID, "shim_pid", pi.Handle.PID,
		"has_started_at", pi.Handle.StartedAt > 0)
	return pi.Handle, nil
}

n_opencode_Adapter_Profile.signature:
// Profile 返回绑定当前 Adapter 日志器的 Profile 能力实现。
func (a *Adapter) Profile() executor.Profile {
	if a == nil {
		return &Profile{}
	}
	return &Profile{log: a.log}
}

n_opencode_Adapter_Reap.signature:
// Reap 在没有内存运行态时按 proc.json 兜底回收 executor 侧资源。
//
// 回收顺序：读 proc.json 拿 Handle → prochost.Kill（内部先试锁，锁空闲直接成功）。
//
// 为什么不再有「确定性命名兜底」：旧实现在 proc.json 缺失时退到 tmux 会话名
// handoff-<id8>，因为会话名可由 taskID 推导。锁+pid 无法从 taskID 推导，
// proc.json 缺失就是真的无据可查——如实报错交协调者，不猜。
//
// 返回：Handle 对应的进程本就不在时返回 nil——目标是「确保它没了」，
// 不是「确保我杀了它」。
func (a *Adapter) Reap(taskID, taskDir string) error {
	pi, err := readProcInfo(taskDir)
	if err != nil {
		a.log.Error("读恢复凭据失败，无法兜底回收", "task", taskID, "cause", err)
		return fmt.Errorf("兜底回收任务 %s: %w", taskID, err)
	}
	a.log.Info("兜底回收 executor 资源", "task", taskID, "shim_pid", pi.Handle.PID)
	if err := prochost.Kill(pi.Handle); err != nil {
		a.log.Error("兜底回收失败", "task", taskID, "shim_pid", pi.Handle.PID, "cause", err)
		return err
	}
	a.log.Info("兜底回收完成", "task", taskID)
	return nil
}

n_opencode_Adapter_Reconcile.signature:
// Reconcile 把断连期间错过的回合终态补回事件流。
//
// 参数：
//   - ctx: 控制查询超时
//   - taskID: 目标任务；运行态不在（未 Start / 已 Stop）时返回「无运行态」结论而非错误
//
// 返回：
//   - ReconcileOutcome: 结论。Emitted 只可能是 0 或 1（spec §2.2 的不变量）；
//     Pending 恒为 0（见文件头注释）
//   - err: 查会话失败。**调用方收到错误时只记 WARN、不改任何状态**——一次网络
//     抖动不该把能恢复的任务判成不可恢复
//
// 注意：
//   - 是否补发由 WatermarkArmed 决定（见 proc.go 的 armed 语义）：未 armed 的
//     legacy 会话**不补发**，只把当前尾部认作已消费基线——否则升级到本版本的
//     存量任务会在第一次恢复时集体重放最后一个回合；armed 会话空水位即「第一个
//     回合尚未消费」，必须补发（B38 头号场景）
//   - 「补发 → 前进水位」在 turnMu 下串行完成，与实时路径的 mapIdle 互斥；
//     拆成两步会让两条路同时判「未消费」而补出两条终态
func (a *Adapter) Reconcile(ctx context.Context, taskID string) (executor.ReconcileOutcome, error) {
	a.log.Info("adapter 开始对账", "task", taskID)

	a.mu.Lock()
	r := a.runs[taskID]
	a.mu.Unlock()
	if r == nil || r.api == nil {
		a.log.Info("对账跳过：该任务无运行态", "task", taskID)
		return executor.ReconcileOutcome{Note: "该任务当前无运行态，无需对账"}, nil
	}

	msg, err := r.api.LastAssistantMessage(ctx, r.session)
	if err != nil {
		a.log.Warn("对账查会话尾部失败，不改任何状态", "task", taskID, "cause", err)
		return executor.ReconcileOutcome{Note: "查会话尾部失败"},
			fmt.Errorf("对账查会话尾部: %w", err)
	}
	if msg == nil {
		a.log.Info("对账结论：会话尚无 assistant 消息", "task", taskID)
		return executor.ReconcileOutcome{Note: "会话里还没有模型消息，无需对账"}, nil
	}
	ended, reason := reconcileTurnEnded(msg)
	if !ended {
		a.log.Info("对账结论：回合仍在进行，不补发",
			"task", taskID, "msg", msg.ID, "reason", reason)
		return executor.ReconcileOutcome{Note: "executor 的回合仍在进行中，没有丢失的终态"}, nil
	}

	r.turnMu.Lock()
	defer r.turnMu.Unlock()

	pi, err := readProcInfo(r.taskDir)
	if err != nil {
		a.log.Warn("对账读凭据失败，不改任何状态", "task", taskID, "cause", err)
		return executor.ReconcileOutcome{Note: "读恢复凭据失败"},
			fmt.Errorf("对账读恢复凭据: %w", err)
	}
	if pi.LastTurnMsgID == msg.ID {
		a.log.Info("对账结论：终态已送达过，无需补发", "task", taskID, "msg", msg.ID)
		return executor.ReconcileOutcome{TurnEnded: true,
			Note:	"回合已完结，且终态此前已送达，无需补发"}, nil
	}
	if !pi.WatermarkArmed {

		pi.LastTurnMsgID = msg.ID
		if werr := writeProcInfo(r.taskDir, pi); werr != nil {
			a.log.Warn("首次对账写水位失败", "task", taskID, "cause", werr)
		}
		a.log.Info("对账结论：未 armed 认基线，已把当前会话尾部记为基线，不补发",
			"task", taskID, "msg", msg.ID, "armed", false)
		return executor.ReconcileOutcome{TurnEnded: true,
			Note:	"会话非本版本新建（legacy），已把当前进度记为基线（不回溯此前的回合）"}, nil
	}

	ev, note := a.classifyReconciled(r, msg)
	if !a.emit(r, ev) {
		a.log.Warn("对账补发失败：事件通道已关闭", "task", taskID, "msg", msg.ID)
		return executor.ReconcileOutcome{TurnEnded: true,
			Note:	"回合已完结但事件通道已关闭，未能补发"}, nil
	}
	pi.LastTurnMsgID = msg.ID
	if werr := writeProcInfo(r.taskDir, pi); werr != nil {
		a.log.Warn("对账后写水位失败，下次对账可能重复补发",
			"task", taskID, "msg", msg.ID, "cause", werr)
	}
	a.log.Info("对账完成：已补发断连期间丢失的终态",
		"task", taskID, "msg", msg.ID, "event", ev.Type, "note", note, "armed", true)
	return executor.ReconcileOutcome{TurnEnded: true, Emitted: 1, Note: note}, nil
}

n_opencode_Adapter_Remove.signature:
func (a *Adapter) Remove(ctx context.Context, req executor.SkillRemoveReq) error {
	if err := executor.GuardRemove(req); err != nil {
		return err
	}
	name := executor.SkillDirName(req.Name)
	site := filepath.Join(req.Home, SkillsRelDir, name)
	return os.RemoveAll(site)
}

n_opencode_Adapter_Report.signature:
// Report 返回本家能力矩阵。查询面与 BaselineReport 对齐；「支持」不等于已接线。
func (a *Adapter) Report() executor.CapabilityReport {
	rep, err := executor.BaselineReport(executor.HarnessOpenCode)
	if err != nil {
		if a != nil && a.log != nil {
			a.log.Error("BaselineReport 失败，返回空能力报告", "harness", executor.HarnessOpenCode, "cause", err)
		}
		return executor.CapabilityReport{Harness: executor.HarnessOpenCode}
	}
	return rep
}

n_opencode_Adapter_RespondAsk.signature:
// RespondAsk 按问题身份回答：原生仍挂起则 ReplyQuestion 且不开新 Prompt；
// 提问回合已结束则以带 TicketID 关联的 Prompt 续接。
//
// 参数：req.TaskID 必须命中运行态；req.TicketID 必填（尝试身份）；req.QuestionID
// 可空，空时用 NativeIDFromTicket(taskID, ticketID)。
// 注意：不得按「当前唯一挂起槽」寻址——只给 TaskID 不合法。
func (a *Adapter) RespondAsk(ctx context.Context, req executor.RespondAskReq) (err error) {
	if req.TaskID == "" || req.TicketID == "" {
		return fmt.Errorf("RespondAsk 必须携带 TaskID 与 TicketID")
	}
	r := a.lookup(req.TaskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", req.TaskID, executor.ErrTaskNotRunning)
	}
	select {
	case <-r.stopCh:
		return fmt.Errorf("任务 %s 已停止（运行态保留待回收），不能答问", req.TaskID)
	default:
	}
	native := req.QuestionID
	if native == "" {
		native = executor.NativeIDFromTicket(req.TaskID, req.TicketID)
	}
	a.log.Info("RespondAsk 进入", "task", req.TaskID, "ticket", req.TicketID,
		"question", native, "answer_runes", len([]rune(req.Answer)))
	defer func() {
		if err != nil {
			a.log.Error("RespondAsk 失败", "task", req.TaskID, "ticket", req.TicketID, "cause", err)
		} else {
			a.log.Info("RespondAsk 完成", "task", req.TaskID, "ticket", req.TicketID, "question", native)
		}
	}()
	reqID, qs := r.takePendingQuestionSnapshot()
	if reqID != "" && (native == "" || reqID == native) {
		return a.replyPendingQuestion(ctx, r, reqID, qs, req.Answer)
	}

	text := "【回答工单 " + req.TicketID + "】\n" + req.Answer
	if err := r.frames.BeginTurn("respond_ask", text); err != nil {
		a.log.Warn("写 turn_start 帧失败，不影响回合", "task", req.TaskID, "cause", err)
	}
	return r.api.PromptAsync(ctx, r.session, text)
}

n_opencode_Adapter_RespondPermission.signature:
// RespondPermission 把协调者的权限裁决转发给 opencode server。
//
// 参数：
//   - permID: 与 permission 事件中的 PermissionID 一致（manager 的 ticket id
//     经 taskID:permID 命名空间化，此处为裸 permID，由 manager 还原后传入）
//   - decision: "once"（批准本次）或 "reject"（拒绝）
//   - reason: 本 adapter 忽略。handoff 走的老端点
//     POST /session/{id}/permissions/{permID} 服务端只读 payload.response，
//     多带的字段被静默丢弃；带 message 的是新端点 /permission/{requestID}/reply
//     （2026-08-18 读 opencode 1.18.18 二进制实证，spec §2.5）。迁端点另计
//
// 注意：
//   - stopCh 已关时拒绝转发：与 Send 同因（见 Send 注释），保留态不接新裁决
func (a *Adapter) RespondPermission(ctx context.Context, taskID, permID, decision, _ string) (err error) {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	select {
	case <-r.stopCh:
		return fmt.Errorf("任务 %s 已停止（运行态保留待回收），不能应答权限", taskID)
	default:
	}
	a.log.Info("adapter 收到权限应答", "task", taskID, "perm", permID, "decision", decision)
	defer func() {
		if err != nil {
			a.log.Error("adapter 权限应答转发失败", "task", taskID, "perm", permID, "cause", err)
		} else {
			a.log.Info("adapter 权限应答已转发", "task", taskID, "perm", permID)
		}
	}()

	sess := r.session
	r.sessMu.RLock()
	mapped, known := r.permSession[permID]
	r.sessMu.RUnlock()
	if known {
		sess = mapped
	} else {

		a.log.Warn("权限应答未在会话映射表里找到该 permID，退回父会话应答",
			"task", taskID, "perm", permID, "session", sess)
	}
	a.log.Info("权限应答选定会话", "task", taskID, "perm", permID,
		"session", sess, "from_map", known)
	if r.api == nil {
		return fmt.Errorf("任务 %s: api 未就绪", taskID)
	}
	if err := r.api.RespondPermission(ctx, sess, permID, decision); err != nil {
		return err
	}
	r.sessMu.Lock()
	timing, knownTiming := r.permTiming[permID]
	shouldResume := knownTiming && timing.paused
	if shouldResume {
		timing.paused = false
		r.permTiming[permID] = timing
	}
	r.sessMu.Unlock()
	if !knownTiming {
		a.log.Warn("opencode 权限应答成功但缺少工具等待映射",
			"task", taskID, "perm", permID)
	} else if !shouldResume {
		a.log.Warn("opencode 权限应答重复恢复被忽略",
			"task", taskID, "perm", permID, "part", timing.part)
	} else {
		a.log.Info("opencode 权限等待结束", "task", taskID, "perm", permID,
			"part", timing.part)
		entries := r.seg.Resume(timing.part)
		if len(entries) == 0 {
			a.log.Warn("opencode 权限应答成功但未找到工具等待窗口",
				"task", taskID, "perm", permID, "part", timing.part)
		} else {
			a.reportTiming(r, entries)
		}
	}

	if decision == "reject" {
		r.noteRejected(permID)
	}
	return nil
}

n_opencode_Adapter_Resume.signature:
// Resume 重建 agentd 重启前已在执行的任务（spec §8「存活则重连 SSE 继续」）：
// 从任务目录的 proc.json 恢复 serve 连接凭据并探活（存活锁 + HTTP 应答）；
// 存活则重建 SSE 订阅、看门狗与事件通道，返回 Reattach。
//
// 参数：
//   - req: 恢复请求（TaskDir 是 proc.json 所在，即 DataDir/tasks/<id>；
//     RepoPath 用于重启后重新捕获 git 兜底分类的起点 commit 基线；
//     SessionID 是落库的 opencode 会话 id）
//
// 返回：
//   - Alive=false 时调用方（manager）把任务转 failed 交协调者裁决（保守优于静默）
//   - err: 重建失败（proc.json 缺失/损坏、SessionID 为空），此时视为不可恢复
//
// 注意：
//   - SessionID 为空时拒绝恢复：mapEvent 按会话 id 过滤事件，空 id 会把全部
//     事件当「其他会话」丢弃，静默恢复等于无声断流，宁可交协调者裁决
//   - 重启时正在进行的回合文本累积在内存里已丢失：重建后的回合从 SSE 重放的新
//     快照重新累积（partSeen/partSnap 重新对账），idle 分类的 git 基线以重启
//     时刻的 HEAD 为准——这是 MVP 接受的缝隙，由 e2e 清单「agentd 重启」项
//     实测观察
//   - 与 Start 的对称性：Stop（done 归档）对恢复出来的运行态同样有效，
//     会按进程组 Kill 回收执行者资源
func (a *Adapter) Resume(req executor.ResumeReq) (out executor.ResumeOutcome, err error) {
	a.log.Info("adapter 恢复任务执行", "task", req.TaskID, "session", req.SessionID)
	defer func() {
		if err != nil {
			a.log.Error("adapter 恢复任务失败", "task", req.TaskID, "cause", err)
		} else if out.Alive {
			a.log.Info("adapter 任务已恢复", "task", req.TaskID, "session", out.SessionID)
		}
	}()

	a.mu.Lock()
	if _, busy := a.runs[req.TaskID]; busy {
		a.mu.Unlock()
		a.log.Info("该任务已有运行态或恢复进行中，跳过本次恢复", "task", req.TaskID)
		return executor.ResumeOutcome{Alive: false, Note: "该任务的恢复正在进行中"}, nil
	}
	a.runs[req.TaskID] = &runState{taskID: req.TaskID}
	a.mu.Unlock()
	defer func() {

		a.mu.Lock()
		if cur, ok := a.runs[req.TaskID]; ok && cur.evCh == nil {
			delete(a.runs, req.TaskID)
		}
		a.mu.Unlock()
	}()

	if req.SessionID == "" {
		return executor.ResumeOutcome{}, fmt.Errorf("任务 %s 缺 executor_session，无法重建订阅", req.TaskID)
	}
	si, err := readProcInfo(req.TaskDir)
	if err != nil {
		return executor.ResumeOutcome{}, err
	}

	proc := &Proc{Handle: si.Handle, Port: si.Port, Password: si.Password,
		ServeLogPath:	filepath.Join(req.TaskDir, serveLogFileName)}

	mode := executor.ResumeModeReattach
	if !proc.Alive() {

		if kerr := proc.Kill(); kerr != nil {
			a.log.Warn("回收已死执行者失败，可能需人工清理",
				"task", req.TaskID, "shim_pid", proc.Handle.PID, "cause", kerr)
		}
		if !req.Cold {
			a.log.Info("serve 已不在且不允许冷恢复，判不可恢复",
				"task", req.TaskID, "shim_pid", proc.Handle.PID)
			return executor.ResumeOutcome{Alive: false,
				Note:	"serve 进程已不在（本次只允许热重连）"}, nil
		}

		if _, serr := os.Stat(req.TaskDir); serr != nil {
			a.log.Info("任务目录已不存在，判不可恢复", "task", req.TaskID, "cause", serr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务目录已不存在（可能已归档清理），无法恢复"}, nil
		}
		if _, rerr := os.Stat(req.RepoPath); rerr != nil {
			a.log.Info("任务工作区已不存在，判不可恢复", "task", req.TaskID, "cause", rerr)
			return executor.ResumeOutcome{Alive: false,
				Note:	"任务工作区已不存在（可能已归档清理），无法恢复"}, nil
		}
		a.log.Info("serve 已不在，进入冷恢复", "task", req.TaskID, "session", req.SessionID)

		configPath := filepath.Join(req.TaskDir, configFileName)
		tmpDir, managedEnv := managedTaskTmpEnv(req.TaskDir, req.TaskID)
		if err := ensureTaskTmp(req.TaskID, tmpDir, a.log); err != nil {
			return executor.ResumeOutcome{}, fmt.Errorf("创建任务临时目录 %s: %w", tmpDir, err)
		}
		env := append(append([]string{}, req.Env...), managedEnv...)
		newProc, err := startServe(context.Background(), req.RepoPath, req.TaskID, req.MarkRoot,
			req.TaskDir, configPath, env, a.log)
		if err != nil {
			a.log.Warn("冷恢复重起 serve 失败，判不可恢复", "task", req.TaskID, "cause", err)
			return executor.ResumeOutcome{Alive: false,
				Note:	fmt.Sprintf("重起 opencode serve 失败：%v", err)}, nil
		}

		if werr := writeProcInfo(req.TaskDir, &procInfo{
			Handle:	newProc.Handle, Port: newProc.Port, Password: newProc.Password,
			LastTurnMsgID:	si.LastTurnMsgID, WatermarkArmed: si.WatermarkArmed,
		}); werr != nil {
			a.log.Warn("冷恢复写 proc.json 失败，下次重启恢复将不可用",
				"task", req.TaskID, "cause", werr)
		}
		proc = newProc
		mode = executor.ResumeModeCold
		a.log.Info("冷恢复新 serve 就绪", "task", req.TaskID, "port", proc.Port)
	}
	if mode == executor.ResumeModeCold && req.Approval == nil {
		return executor.ResumeOutcome{}, fmt.Errorf("OpenCode 冷恢复必须注入 ApprovalClient；nil 不是全部免审")
	}
	r := a.newRun(req.TaskID, req.TaskDir, req.RepoPath)
	r.approval = req.Approval
	sessionID := req.SessionID
	r.session = sessionID
	r.api = NewAPI(fmt.Sprintf("http://127.0.0.1:%d", proc.Port), proc.Password)
	r.handle = procHandle{p: proc}

	if mode == executor.ResumeModeCold {

		has, err := r.api.HasSession(context.Background(), sessionID)
		if err != nil {
			a.log.Warn("查询会话列表失败，保守降级新会话", "task", req.TaskID, "cause", err)
			has = false
		}
		if !has {
			newID, nerr := r.api.CreateSession(context.Background())
			if nerr != nil {
				a.log.Warn("降级新建会话失败，判不可恢复", "task", req.TaskID, "cause", nerr)
				a.drop(req.TaskID)
				return executor.ResumeOutcome{Alive: false,
					Note:	fmt.Sprintf("原会话已不在且新建失败：%v", nerr)}, nil
			}
			a.log.Warn("原会话已不在，已新开会话", "task", req.TaskID,
				"old", sessionID, "new", newID)
			sessionID, mode = newID, executor.ResumeModeFresh

			if werr := writeProcInfo(req.TaskDir, &procInfo{
				Handle:	proc.Handle, Port: proc.Port, Password: proc.Password,
				WatermarkArmed:	true,
			}); werr != nil {
				a.log.Warn("新会话清零对账水位失败", "task", req.TaskID, "cause", werr)
			}
		}
		r.session = sessionID
	}
	r.captureStartCommit(a)
	go r.subscribeLoop(a)
	go a.watchdog(r)

	if mode != executor.ResumeModeFresh {
		go a.reconcileAfterRecovery(context.Background(), req.TaskID, "startup")
		go a.rediscoverPendingQuestions(context.Background(), req.TaskID)
	}
	return executor.ResumeOutcome{
		Alive:	true, Mode: mode, SessionID: sessionID,
		Note:	resumeNote(mode, sessionID),
	}, nil
}

n_opencode_Adapter_Send.signature:
// Send 向 opencode 发送用户输入或续接指令。
//
// 职责：Send 只发普通续接；答问走 RespondAsk。有 pending 时 Send 不得消费它。
// 拆开是为了冻结契约（9/94），避免普通续接误答挂起的提问。
//
// 参数：
//   - text: 协调者的回答/修改指令，原样透传，不得加工
//
// 注意：
//   - stopCh 已关（Stop 已介入，运行态可能因 kill 失败被保留）时拒绝发送：
//     订阅已退出，prompt 发出也没有事件回程，任务会静默挂死——宁可让协调者
//     看到「任务不在运行」的明确错误
func (a *Adapter) Send(ctx context.Context, taskID, text string) (err error) {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	select {
	case <-r.stopCh:
		return fmt.Errorf("任务 %s 已停止（运行态保留待回收），不能续接", taskID)
	default:
	}
	if err := r.frames.BeginTurn("send", text); err != nil {
		a.log.Warn("写 turn_start 帧失败，不影响回合", "task", taskID, "cause", err)
	}
	a.reportTiming(r, r.seg.BeginTurn(r.frames.Turn()))
	a.log.Info("adapter 收到续接指令", "task", taskID, "text", turn.TruncateRunes(text, 80))
	defer func() {
		if err != nil {
			a.log.Error("adapter 续接指令发送失败", "task", taskID, "cause", err)
		} else {
			a.log.Info("adapter 续接指令已发送", "task", taskID, "session", r.session)
		}
	}()
	return r.api.PromptAsync(ctx, r.session, text)
}

n_opencode_Adapter_Start.signature:
// Start 按「WriteTaskEnv → StartServe → 建会话 → 初始 prompt → 订阅映射」
// 流程启动任务执行并立即返回。
//
// 参数：
//   - ctx: 控制启动阶段的超时/取消（CreateSession/PromptAsync 受其约束）；
//     不代表执行生命周期（执行延续到 Stop）
//   - req: 任务快照、计划原文与任务工作目录
//
// 返回：
//   - 任一启动阶段失败（环境物料生成/serve 启动/建会话/发 prompt）返回错误，
//     调用方（manager）应把任务标记 failed
//
// 注意：
//   - serve 已拉起但后续阶段失败时自动 Kill 清理进程残留，避免半启动进程占端口
func (a *Adapter) Start(ctx context.Context, req executor.StartReq) (err error) {
	a.log.Info("adapter 开始启动任务", "task", req.Task.ID,
		"task_dir", req.TaskDir, "workdir", req.Task.Workdir())
	defer func() {
		if err != nil {
			a.log.Error("adapter 启动任务失败", "task", req.Task.ID, "cause", err)
		}
	}()

	if req.Approval == nil {
		return fmt.Errorf("OpenCode 任务必须注入 ApprovalClient；nil 不是全部免审")
	}
	snap, err := req.Approval.PolicySnapshot(ctx)
	if err != nil {
		return err
	}
	configPath, _, err := WriteTaskEnv(req.TaskDir, req.Task.ID, req.Task.Model, req.PlanContent, req.Discipline, snap)
	if err != nil {
		return err
	}
	if strings.TrimSpace(req.Discipline) == "" {
		a.log.Info("opencode 未注入纪律块", "task", req.Task.ID)
	} else {
		a.log.Info("opencode 纪律块已注入 prompt", "task", req.Task.ID, "bytes", len(req.Discipline))
	}

	tmpDir, managedEnv := managedTaskTmpEnv(req.TaskDir, req.Task.ID)
	if err := ensureTaskTmp(req.Task.ID, tmpDir, a.log); err != nil {
		return fmt.Errorf("创建任务临时目录 %s: %w", tmpDir, err)
	}
	env := append(append([]string{}, req.Env...), managedEnv...)
	proc, err := startServe(ctx, req.Task.Workdir(), req.Task.ID,
		prochost.ResolveMarkRoot(req.Task.Workdir(), req.Task.WorktreeManaged),
		req.TaskDir, configPath, env, a.log)
	if err != nil {
		return err
	}
	a.log.Info("opencode serve 已启动", "task", req.Task.ID,
		"port", proc.Port, "shim_pid", proc.Handle.PID)

	if err := writeProcInfo(req.TaskDir, &procInfo{
		Handle:	proc.Handle, Port: proc.Port, Password: proc.Password,
	}); err != nil {
		a.log.Warn("写 serve 连接凭据失败，重启恢复将不可用", "task", req.Task.ID, "cause", err)
	}
	api := NewAPI(fmt.Sprintf("http://127.0.0.1:%d", proc.Port), proc.Password)
	if _, err := a.startRun(ctx, req, api, procHandle{p: proc}); err != nil {
		if kerr := proc.Kill(); kerr != nil {
			a.log.Warn("清理 serve 残留失败", "task", req.Task.ID, "cause", kerr)
		}
		return err
	}

	if werr := writeProcInfo(req.TaskDir, &procInfo{
		Handle:	proc.Handle, Port: proc.Port, Password: proc.Password,
		WatermarkArmed:	true,
	}); werr != nil {
		a.log.Warn("新建会话后写 armed 标记失败，对账可能误判水位可信度",
			"task", req.Task.ID, "cause", werr)
	}
	return nil
}

n_opencode_Adapter_Stop.signature:
// Stop 终止任务执行：取消订阅 → kill serve（执行者进程组）→ 事件通道关闭 → 注销运行态。
//
// 注意：
//   - 幂等：重复 Stop 不 panic；事件通道只关闭一次（由订阅 goroutine 持有关闭权）
//   - kill 失败但 serve 仍存活时**保留运行态**（P1-9）：serve 占着端口与模型
//     会话，drop 掉就没有任何途径回收；保留期间运行态是惰性的（订阅与看门狗
//     都已退出、事件通道已关），Send/RespondPermission 经 stopCh 守卫拒绝继续执行
//   - 保留态由 reapRetained 后台重试回收（A-10），重试有上限、放弃时打 Error
//     交人工（handoff stop 回收）：**agentd 重启不会接走它**——RecoverOnStartup
//     只探测 running/waiting_answer 任务（watchdog.go），而 Stop 只由 Done 在
//     归档时调用（manager.go），进程内保留态只可能属于已归档任务
//   - 运行态注销（drop）与 subscribeLoop 退出时的 drop 是幂等的 map 删除，
//     mu 保护下不会重复释放——runs 表因此不随任务累积无界增长
func (a *Adapter) Stop(taskID string) (err error) {
	r := a.lookup(taskID)
	if r == nil {
		return fmt.Errorf("任务 %s: %w", taskID, executor.ErrTaskNotRunning)
	}
	a.log.Info("adapter 停止任务", "task", taskID)
	defer func() {
		if err != nil {
			a.log.Error("adapter 停止任务失败", "task", taskID, "cause", err)
		} else {
			a.log.Info("adapter 任务已停止", "task", taskID)
		}
	}()

	r.stopOnce.Do(func() {
		close(r.stopCh)
		r.runCancel()
	})

	if reqID, _ := r.takePendingQuestionSnapshot(); reqID != "" {
		ctx, cancel := context.WithTimeout(context.Background(), unaryTimeout)
		if rerr := r.api.RejectQuestion(ctx, reqID); rerr != nil {
			a.log.Warn("停止前拒绝挂起提问失败，该请求可能仍挂在 opencode 侧",
				"task", taskID, "request", reqID, "cause", rerr)
		} else {
			a.log.Info("停止前已拒绝挂起提问", "task", taskID, "request", reqID)
		}
		cancel()
		r.clearPendingQuestion()
	}
	// 挂起的权限请求同样解阻塞再杀进程（B233.1）：避免 opencode 侧权限等待死锁
	var pendingPerms []struct{ id, sess string }
	r.sessMu.Lock()
	for permID, timing := range r.permTiming {
		if timing.paused {
			sess := r.session
			if mapped, ok := r.permSession[permID]; ok {
				sess = mapped
			}
			pendingPerms = append(pendingPerms, struct{ id, sess string }{id: permID, sess: sess})
			timing.paused = false
			r.permTiming[permID] = timing
		}
	}
	r.sessMu.Unlock()

	if len(pendingPerms) > 0 && r.api != nil {
		ctx, cancel := context.WithTimeout(context.Background(), unaryTimeout)
		for _, p := range pendingPerms {
			if rerr := r.api.RespondPermission(ctx, p.sess, p.id, "reject"); rerr != nil {
				a.log.Warn("停止前拒绝挂起权限失败，该请求可能仍挂在 opencode 侧",
					"task", taskID, "perm", p.id, "cause", rerr)
			} else {
				a.log.Info("停止前已拒绝挂起权限", "task", taskID, "perm", p.id)
			}
		}
		cancel()
	}
	if r.handle != nil {
		if kerr := r.handle.Kill(); kerr != nil {
			if r.handle.Alive() {

				a.log.Error("kill serve 失败，保留运行态并转入后台重试", "task", taskID, "cause", kerr)
				go a.reapRetained(r)
				return fmt.Errorf("kill serve: %w", kerr)
			}

			a.log.Warn("kill serve 失败但 serve 已死，照常注销运行态", "task", taskID, "cause", kerr)
		}
	}

	a.drop(taskID)
	return nil
}

n_opencode_Adapter_Verify.signature:
// Verify 校验 OpenCode 规则落点；引擎健康仍需真机探证。
func (a *Adapter) Verify(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	return a.Profile().Verify(ctx, req)
}

n_opencode_Adapter_acceptForeign.signature:
// acceptForeign 裁决一条「会话 id 与本任务不符」的事件是否仍要处理，
// 并保证两个方向都不静默。
//
// 参数：
//   - sessionID: 从顶层或 properties 提取到的会话 id（"" 表示事件没带）
//
// 返回：
//   - true 表示继续按本任务的事件处理，false 表示丢弃
//
// why（三条实测结论，改这里之前先读）：
//   - opencode 会为 subagent/task 工具派生子会话，其权限请求带子会话 id。
//     GET /session/{id} 返回 parentID，**父子关系端点是存在的**——本函数早期
//     版本的注释断言「本层无法把子会话映射回任务」，那是错的，B52 已实测推翻：
//     子会话的 parentID 就等于本任务的会话 id
//   - 子会话被 opencode 自己下了 permission:[{task,*,deny}]，不能再派生 subagent，
//     所以嵌套深度恒为 1，比一次 parentID 就够，不需要向上遍历
//   - 每个任务起自己的 opencode serve（见 proc.go 的 freePort），所以 /event 的
//     「全服务器广播」实际是「本任务这一个 serve 的广播」，流上出现的陌生会话
//     本就只可能是本任务自己派生的子会话
//
// why 仍然保留校验（不能改成一律放行）：校验存在的理由是防止跨任务串台。
// 缺 sessionID 的任务级事件更不能 fail-open——一条无归属的 permission.asked
// 会被当成本任务的审批门，协调者的批准动作会发到错误的会话。
func (a *Adapter) acceptForeign(r *runState, ev sseEvent, sessionID string) bool {
	if !taskScopedEvents[ev.Type] {
		return true
	}
	if ev.Type == "permission.asked" {
		if sessionID == "" {
			a.log.Warn("收到不带会话 id 的审批请求，无法归属，未产出工单",
				"task", r.taskID, "own_session", r.session,
				"properties", turn.TruncateRunes(string(ev.Properties), 200))
			a.emitOwnershipFailure(r, sessionID, "事件未携带会话 id")
			return false
		}
		if _, ok := a.resolveChildSession(r, sessionID); ok {
			return true
		}
		a.emitOwnershipFailure(r, sessionID, "认亲失败")
		return false
	}

	a.log.Debug("收到其他会话事件，跳过", "task", r.taskID,
		"type", ev.Type, "session", sessionID)
	return false
}

n_opencode_Adapter_advanceWatermark.signature:
// advanceWatermark 把本回合最后一条 assistant 消息 id 落进 proc.json，作为对账水位。
//
// why（正常路径也必须写）：对账靠「会话尾部消息 id != 水位」判定「有未消费的
// 已完结回合」。若只在对账成功时写水位，一个正常送达的终态就不会推进水位，
// 下一次对账会把它当成丢失事件**重复补发**一遍。
//
// 失败只 Warn 不中断：水位写不进去的后果是下次可能重复补发一条终态（事件表多
// 一条、状态机 waiting_review→waiting_review 被 ErrBadTransit 挡掉），比中断
// 回合分类轻得多。
func (a *Adapter) advanceWatermark(r *runState) {
	msgID := r.lastAssistantMsgID
	if msgID == "" {
		a.log.Debug("本回合无 assistant 消息 id，跳过水位前进", "task", r.taskID)
		return
	}
	pi, err := readProcInfo(r.taskDir)
	if err != nil {
		a.log.Warn("前进对账水位失败：读凭据出错，下次对账可能重复补发",
			"task", r.taskID, "msg", msgID, "cause", err)
		return
	}
	if pi.LastTurnMsgID == msgID {
		return
	}
	old := pi.LastTurnMsgID
	pi.LastTurnMsgID = msgID
	if err := writeProcInfo(r.taskDir, pi); err != nil {
		a.log.Warn("前进对账水位失败：写凭据出错，下次对账可能重复补发",
			"task", r.taskID, "msg", msgID, "cause", err)
		return
	}
	a.log.Info("对账水位已前进", "task", r.taskID, "from", old, "to", msgID)
}

n_opencode_Adapter_authorizeNativePermis.signature:
func (a *Adapter) authorizeNativePermission(r *runState, ev executor.AdapterEvent) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	go func() {
		select {
		case <-r.stopCh:
			cancel()
		case <-ctx.Done():
		}
	}()
	a.log.Info("原生权限交 client", "task", r.taskID, "perm", ev.PermissionID)
	dec, err := executor.Authorize(ctx, r.approval, executor.ApprovalRequest{
		NativeID:	ev.PermissionID,
		Text:		ev.Text,
		Perm:		ev.Perm,
		Truncated:	strings.Contains(ev.Text, executor.TruncationMarker),
	})
	if err != nil {
		a.log.Error("Authorize 失败，拒绝该权限", "task", r.taskID, "perm", ev.PermissionID, "cause", err)
		if rejectErr := a.RespondPermission(ctx, r.taskID, ev.PermissionID, "reject", "审批失败"); rejectErr != nil {
			a.log.Error("Authorize 失败后的 reject 回传失败", "task", r.taskID,
				"perm", ev.PermissionID, "cause", rejectErr)

			a.reportDeliveryFailure(ctx, r, ev.PermissionID, rejectErr)
		} else {
			a.log.Info("Authorize 失败后的 reject 已回传", "task", r.taskID, "perm", ev.PermissionID)
		}
		return
	}
	decision, reason := "reject", dec.Reason
	if dec.Status == executor.ApprovalAllow {
		decision, reason = "once", ""
	}
	ref := executor.ApprovalRef{ID: executor.NamespacedTicketID(r.taskID, ev.PermissionID)}
	_ = r.approval.Acknowledge(ctx, executor.ApprovalAck{Ref: ref, NativeID: ev.PermissionID, Stage: executor.AckFormed})
	if err := a.RespondPermission(ctx, r.taskID, ev.PermissionID, decision, reason); err != nil {
		a.log.Error("RespondPermission 失败", "task", r.taskID, "perm", ev.PermissionID, "cause", err)
		if deliveryFailureHasTicket(dec) {
			a.reportDeliveryFailure(ctx, r, ev.PermissionID, err)
		} else {
			a.log.Warn("免审 AutoAllow 回传失败，无工单可恢复，不产 delivery_failed",
				"task", r.taskID, "perm", ev.PermissionID, "rule", dec.Rule, "cause", err)
		}
		return
	}
	_ = r.approval.Acknowledge(ctx, executor.ApprovalAck{Ref: ref, NativeID: ev.PermissionID, Stage: executor.AckDelivered})
	_ = r.approval.Acknowledge(ctx, executor.ApprovalAck{Ref: ref, NativeID: ev.PermissionID, Stage: executor.AckExecuted})
	if decision == "reject" && strings.TrimSpace(reason) != "" {
		guide := turn.DenyGuidanceText(reason)
		if r.api != nil && r.session != "" {
			if perr := r.api.PromptAsync(ctx, r.session, "【关联权限 "+ev.PermissionID+"】\n"+guide); perr != nil {
				a.log.Error("拒绝指导下发失败", "task", r.taskID, "perm", ev.PermissionID, "cause", perr)
			}
		}
	}
	a.log.Info("原生权限已回传", "task", r.taskID, "perm", ev.PermissionID, "decision", decision)
}

n_opencode_Adapter_classifyReconciled.signature:
// classifyReconciled 把取回的消息翻译成一条与实时路径同形的 AdapterEvent。
//
// 分类**复用** turn.ParseTrailer——与 mapIdle 走同一套判据，于是以提问收尾的
// 回合会正确地还原成 question 工单，而不是一条假的「做完了」。
//
// 返回：事件本身，以及一句给协调者看的结论。
func (a *Adapter) classifyReconciled(r *runState, msg *SessionMessage) (executor.AdapterEvent, string) {

	if msg.ErrorName == "MessageAbortedError" {
		text := "断连期间该会话被人工 abort 解开（可能是救援动作）。回合停在这里等人指路，"
		if msg.Text != "" {
			text += "回合原文：\n" + turn.TailRunes(msg.Text, 1000)
		}
		a.log.Warn("对账发现回合被 abort，转提问交协调者裁决",
			"task", r.taskID, "msg", msg.ID)
		return executor.AdapterEvent{Type: "question", SessionID: r.session,
				Text:	turn.ClampQuestion(text)},
			"补回了一条断连期间被 abort 的回合（需人工裁决，含原文）"
	}
	if msg.ErrorText != "" {
		a.log.Warn("对账发现回合以错误告终", "task", r.taskID, "msg", msg.ID,
			"error", turn.TruncateRunes(msg.ErrorText, 200))
		return executor.AdapterEvent{Type: "result", SessionID: r.session,
				Result: &executor.Result{OK: false,
					FailReason: "回合在 agentd 断连期间以错误告终：" +
						turn.TruncateRunes(msg.ErrorText, 200)}},
			"补回了一条断连期间丢失的失败结果"
	}

	if msg.ToolStatus == "error" {
		text := "断连期间该回合以工具被拒或工具报错告终"
		if msg.Text != "" {
			text += "，回合原文：\n" + turn.TailRunes(msg.Text, 1000)
		}
		a.log.Warn("对账发现回合以工具错误告终，转提问交协调者裁决",
			"task", r.taskID, "msg", msg.ID)
		return executor.AdapterEvent{Type: "question", SessionID: r.session,
				Text:	turn.ClampQuestion(text)},
			"补回了一条断连期间丢失的回合（工具被拒/报错而终），需人工裁决"
	}
	kind, t := turn.ParseTrailer(msg.Text)
	switch kind {
	case "ask":
		return executor.AdapterEvent{Type: "question", SessionID: r.session,
			Text:	turn.ClampQuestion(t.Question)}, "补回了一条断连期间丢失的提问"
	case "finish":
		return executor.AdapterEvent{Type: "result", SessionID: r.session,
			Result: &executor.Result{OK: true, Branch: t.Branch, CommitHash: t.Commit,
				Summary:	t.Summary, SessionID: r.session}}, "补回了一条断连期间丢失的完成结果"
	}

	a.log.Warn("对账发现回合无协议 trailer，转提问交协调者裁决",
		"task", r.taskID, "msg", msg.ID)
	return executor.AdapterEvent{Type: "question", SessionID: r.session,
		Text: turn.ClampQuestion("agentd 断连期间该回合已结束，但未输出协议结论。" +
			"回合原文：\n" + turn.TailRunes(msg.Text, 1000))}, "补回了一条断连期间丢失的回合，需人工裁决"
}

n_opencode_Adapter_drop.signature:
// drop 注销一个任务的运行态（启动失败清理用）。
func (a *Adapter) drop(taskID string) {
	a.mu.Lock()
	defer a.mu.Unlock()
	delete(a.runs, taskID)
}

n_opencode_Adapter_emit.signature:
// emit 向事件通道投递一条 AdapterEvent 并打产出日志（所有事件统一的出口）。
//
// 同时为看门狗打活跃点（lastEventAt）：探活降频的「收到新事件回高频」信号
// （P1-17，见 watchdogWithConfig）。
//
// 并发：订阅 goroutine 与 idle 去抖定时器 goroutine 都会 emit，故写入与关闭
// 统一由 emitMu 串行化，evClosed 使关闭后的迟到投递静默丢弃而非 panic。
//
// 返回 false 表示 Stop 已关闭 stopCh 或通道已关闭，事件未被投递。
func (a *Adapter) emit(r *runState, ev executor.AdapterEvent) bool {
	r.lastEventAt.Store(time.Now().UnixNano())
	switch ev.Type {
	case "permission":
		a.log.Info("adapter 产出权限事件", "task", r.taskID, "type", ev.Type,
			"perm", ev.PermissionID, "text", turn.TruncateRunes(ev.Text, 80))
	case "question":
		a.log.Info("adapter 产出提问事件", "task", r.taskID, "type", ev.Type,
			"text", turn.TruncateRunes(ev.Text, 80))
	case "progress":
		a.log.Info("adapter 产出进度事件", "task", r.taskID, "type", ev.Type,
			"text", turn.TruncateRunes(ev.Text, 80))
	case "result":
		ok := ev.Result != nil && ev.Result.OK
		a.log.Info("adapter 产出结果事件", "task", r.taskID, "type", ev.Type, "ok", ok)
	case "usage":

	default:
		a.log.Info("adapter 产出未知事件", "task", r.taskID, "type", ev.Type)
	}
	r.emitMu.Lock()
	defer r.emitMu.Unlock()
	if r.evClosed {
		a.log.Debug("事件通道已关闭，丢弃迟到事件", "task", r.taskID, "type", ev.Type)
		return false
	}
	select {
	case r.evCh <- ev:
		return true
	case <-r.stopCh:
		return false
	}
}

n_opencode_Adapter_emitOwnershipFailure.signature:
// emitOwnershipFailure 把一次归属判定失败播报给协调者。
//
// 参数：
//   - sessionID: 判定失败的会话 id（可能为空串）
//   - reason:    失败原因短语，进 progress 文本
//
// why：丢弃一条审批请求意味着 opencode 在等一个永远不会到来的决策，而 serve
// 活着、看门狗不触发——只写日志的话协调者在 handoff 里完全看不见。progress
// 只入库不阻塞，是把这件事送到 handoff show 事件历史的最轻通道。
func (a *Adapter) emitOwnershipFailure(r *runState, sessionID, reason string) {
	if sessionID == "" {
		sessionID = "(未携带)"
	}
	a.emit(r, executor.AdapterEvent{
		Type:	"progress",
		Text: "丢弃了一条无法归属的审批请求（" + reason + "，会话 " + sessionID +
			"）：opencode 可能在等一个看不见的决策，任务若卡住请 handoff attach 查看现场",
	})
}

n_opencode_Adapter_fallbackClassify.signature:
// fallbackClassify 是「模型未按纪律输出协议 trailer」的兜底分类。
//
// why（兜底分类规则）：回合结束但 turn.ParseTrailer 判 none。此时拿 git 实况裁决：
//   - 相对回合起点有新 commit → 发 result{OK:false}（B74）。**不替模型宣布完成**：
//     模型没说完成，handoff 就不说。翻转不给协调者加任何一次操作——OK 与 !OK
//     都落 waiting_review，done 与 continue 在那里都合法；变的只是事件从
//     「已完成，摘要如下」变成「有新提交，但模型未按纪律宣布完成」。
//   - 没有新 commit / git 查询失败 → 把回合全文交协调者裁决（question），流程不卡死。
func (a *Adapter) fallbackClassify(r *runState, text string) {
	a.log.Warn("回合未输出协议 trailer，走 git 兜底", "task", r.taskID,
		"turn_tail", turn.TailRunes(text, 120))
	branch, commit, hasNew, err := a.gitTurnStatus(r)
	if err != nil || !hasNew {
		if err != nil {
			a.log.Error("git 兜底查询失败", "task", r.taskID, "cause", err)
		}
		a.log.Info("兜底判定无新提交，转提问交协调者裁决", "task", r.taskID, "has_new", hasNew)
		a.emit(r, executor.AdapterEvent{Type: "question", Text: turn.ClampQuestion(text)})
		return
	}
	a.log.Warn("兜底判定有新提交，但模型未宣布完成，转失败交协调者裁决",
		"task", r.taskID, "branch", branch, "commit", commit)
	a.emit(r, executor.AdapterEvent{Type: "result",
		Result:	turn.NoTrailerResult(r.session, branch, commit, text)})
}

n_opencode_Adapter_flushPending.signature:
// flushPending 在 part 类型揭晓时处置它的暂存增量：是文本就落地进回合，
// 不是就整段丢弃（reasoning/tool 的增量绝不能进回合与 render.log）。
//
// W4a：丢弃前先按真实类型分流出一路帧——reasoning 的暂存增量落 reasoning 帧，
// 其余照旧整段丢弃。回合与 render.log 的走向一字不改。
//
// 为什么参数从 isText bool 换成 partType string：bool 分不出 reasoning 与
// tool，而这两者的帧处置不同（前者产帧、后者不产）。
func (a *Adapter) flushPending(r *runState, key, partType string) {
	buf, ok := r.pendingDelta[key]
	if !ok {
		return
	}
	delete(r.pendingDelta, key)
	r.pendingBytes -= len(buf)
	switch frameKind(partType) {
	case kindText:
		a.setPartText(r, key, r.partSeen[key]+buf)
		return
	case kindReasoning:
		if err := r.frames.Reasoning(key, buf); err != nil {
			a.log.Warn("写 reasoning 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
	}
	a.log.Debug("暂存增量所属 part 非文本，不进回合", "task", r.taskID,
		"type", partType, "bytes", len(buf))
}

n_opencode_Adapter_gitTurnStatus.signature:
// gitTurnStatus 查询仓库当前分支与 HEAD commit，并对比任务起点判定是否有新提交。
//
// 薄封装：实现在 turn 共享包（B2/B3 两个 adapter 同构逻辑），本方法保留
// 调用点已有的 r 上下文（repoPath/startCommit）。
func (a *Adapter) gitTurnStatus(r *runState) (branch, commit string, hasNew bool, err error) {
	return turn.GitTurnStatus(r.repoPath, r.startCommit)
}

n_opencode_Adapter_lookup.signature:
// lookup 按任务 id 取运行态。
func (a *Adapter) lookup(taskID string) *runState {
	a.mu.Lock()
	defer a.mu.Unlock()
	return a.runs[taskID]
}

n_opencode_Adapter_mapEvent.signature:
// mapEvent 把一条 SSE 事件映射为 0~N 条 AdapterEvent（宽容解析：未知事件
// Debug 跳过，绝不 panic、绝不中断订阅）。
func (a *Adapter) mapEvent(r *runState, raw json.RawMessage) {

	r.lastEventAt.Store(time.Now().UnixNano())
	var ev sseEvent
	if err := json.Unmarshal(raw, &ev); err != nil {
		a.log.Debug("SSE 事件解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}

	sessionID := ev.SessionID
	if sessionID == "" {
		var prop struct {
			SessionID string `json:"sessionID"`
		}
		if json.Unmarshal(ev.Properties, &prop) == nil {
			sessionID = prop.SessionID
		}
	}
	if sessionID != r.session && !a.acceptForeign(r, ev, sessionID) {
		return
	}

	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	switch {
	case ev.Type == "permission.asked":
		a.mapPermissionAsked(r, ev.Properties)
	case ev.Type == "permission.replied":

		a.log.Debug("permission.replied 应答回显，忽略", "task", r.taskID, "type", ev.Type)
	case ev.Type == "question.asked":
		a.mapQuestionAsked(r, ev.Properties)
	case ev.Type == "question.replied", ev.Type == "question.rejected":

		a.log.Debug("question 应答回显，忽略", "task", r.taskID, "type", ev.Type)
	case ev.Type == "message.updated":
		a.mapMessageUpdated(r, ev.Properties)
	case ev.Type == "message.part.updated":
		a.mapPartUpdated(r, ev.Properties)
	case ev.Type == "message.part.delta":
		a.mapPartDelta(r, ev.Properties)
	case ev.Type == "session.status":
		a.mapSessionStatus(r, ev.Properties)
	case ev.Type == "session.idle":

		a.log.Debug("session.idle 与 session.status idle 同现，忽略防重复触发",
			"task", r.taskID, "type", ev.Type)
	case ev.Type == "session.error":
		a.log.Warn("opencode 会话报错", "task", r.taskID,
			"properties", turn.TruncateRunes(string(ev.Properties), 200))
	default:
		a.log.Debug("未知 SSE 事件，跳过", "task", r.taskID, "type", ev.Type)
	}
}

n_opencode_Adapter_mapIdle.signature:
// mapIdle 回合结束（session.status idle 主信号）时分类收尾：turn.ParseTrailer 判定
// ask/finish/none，none 走 git 实况兜底（why 见 fallbackClassify）。分类后清空
// 回合缓冲。
//
// 空回合（无累积文本）不再静默跳过：零文本转失败结果交协调者（B21）——idle 但
// 无文本说明文本流没被本层接住（事件结构变化/增量对账失败）或供应商流中断，
// 这是「任务可能静默挂死」的观测点，必须产事件而非 Debug 静默。被拒终止的
// 空回合例外，它走 question（有内容可问，见下文）。props 为触发 idle 的
// session.status 载荷，仅用于日志上下文。
func (a *Adapter) mapIdle(r *runState, raw json.RawMessage) {

	a.reportTiming(r, r.seg.EndTurn())
	text := r.turnText()
	if strings.TrimSpace(text) == "" {

		if rejected := r.takeTurnRejected(); len(rejected) > 0 {
			a.log.Warn("回合因权限被拒终止且无文本产出，转提问交协调者裁决",
				"task", r.taskID, "rejected", rejected)
			a.emit(r, executor.AdapterEvent{
				Type:	"question", Text: turn.ClampQuestion(rejectedTurnQuestion(rejected)),
			})
			a.advanceWatermark(r)
			r.clearTurn()
			r.takeAskedViaTool()
			r.captureStartCommit(a)
			return
		}

		a.log.Warn("idle 但回合无文本，转失败结果交协调者", "task", r.taskID,
			"event", turn.TailRunes(string(raw), 120))
		a.emit(r, executor.AdapterEvent{Type: "result", SessionID: r.session, Result: &executor.Result{
			OK:	false,
			FailReason: "回合结束但零文本产出（可能是供应商流中断）；executor 仍在线，" +
				"可 continue 续接重试",
		}})
		a.advanceWatermark(r)
		r.clearTurn()
		r.takeAskedViaTool()
		r.captureStartCommit(a)
		return
	}

	askedViaTool := r.takeAskedViaTool()
	kind, t := turn.ParseTrailer(text)
	a.log.Info("opencode 回合收尾", "task", r.taskID, "kind", kind,
		"asked_via_tool", askedViaTool, "final_text_len", len([]rune(text)))
	switch kind {
	case "ask":

		if askedViaTool {
			a.log.Debug("本回合已通过 question 工具提问，抑制 trailer 提问工单",
				"task", r.taskID, "trailer_tail", turn.TailRunes(t.Question, 80))
			break
		}
		a.emit(r, executor.AdapterEvent{Type: "question", Text: turn.ClampQuestion(t.Question)})
	case "finish":
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	true, Branch: t.Branch, CommitHash: t.Commit,
			Summary:	t.Summary, SessionID: r.session,
			FinalText:	turn.FinalText(text),
		}})
	case "none":
		a.fallbackClassify(r, text)
	}
	a.advanceWatermark(r)
	r.clearTurn()

	r.captureStartCommit(a)
}

n_opencode_Adapter_mapMessageUpdated.signature:
// mapMessageUpdated 处理 message.updated：真实事件只携带 properties.info
// （role/messageID），不带文本——文本载体是 message.part.updated/delta。本层
// 只用它登记「哪些 messageID 属于 user」，这些消息的 text part 不进回合累积
// （回合只算模型输出）。
//
// why（不拿它清空回合）：user 消息曾被当作「新回合开始」的清空信号，但服务端
// 会重播同一条 user 消息（spike5 实测同一 msg id 出现 3 次，每次 session.diff
// 后一次）。进程内的 userMsgs 只在本次运行有效——agentd 重启后 Resume 出来的
// 运行态拿到的是空表，重播的老消息会被当「首见」而清空整个回合，恢复后累积的
// 文本全部丢弃、idle 走空回合分支永不分类，任务静默挂死（A-3）。回合缓冲由
// mapIdle 在分类后清空即可，不需要第二个清空信号。
func (a *Adapter) mapMessageUpdated(r *runState, props json.RawMessage) {

	if model, u, ok := parseMessageUsage(props); ok && (model != "" || u != nil) {
		a.emit(r, executor.AdapterEvent{Type: "usage", ActualModel: model, Usage: u})
	}

	if e, ok := parseMessageSpend(props); ok {
		a.emit(r, executor.AdapterEvent{Type: "usage", Spend: &e})
	}
	var msg struct {
		Info struct {
			ID	string	`json:"id"`
			Role	string	`json:"role"`
		} `json:"info"`
	}
	if err := json.Unmarshal(props, &msg); err != nil {
		a.log.Debug("message.updated 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if msg.Info.Role != "user" || msg.Info.ID == "" {
		return
	}
	r.userMsgs[msg.Info.ID] = true
}

n_opencode_Adapter_mapPartDelta.signature:
// mapPartDelta 处理 message.part.delta：field=text 的流式增量。
//
// why（已知类型才落地 + 未知类型暂存 + 与快照对账）：
//   - 只有**已登记为 text** 的 part 增量才进回合：partTypes 由 part.updated
//     登记（delta 本身只有 field 无类型，spike5 实测 reasoning 增量同样是
//     field=text），不加这道闸，reasoning/tool 增量会被当模型输出
//   - 类型未知时不猜（A-5）：「part.updated 总是先于 delta 到达」只是抓包里的
//     观测顺序，SSE 跨重连无顺序保证。猜 text 会泄漏思维链，直接丢弃会丢模型
//     输出——暂存进 pendingDelta，等 part.updated 揭示类型再落地或丢弃
//   - 若该 part 已收到非空全量快照（part.updated），增量已被快照覆盖，
//     跳过防重复；否则增量直接追加——真实流里「part 创建（空文本）→
//     逐条 delta 增长」期间并无有效快照可对账（spike5 实测）
func (a *Adapter) mapPartDelta(r *runState, props json.RawMessage) {
	var pd struct {
		MessageID	string	`json:"messageID"`
		PartID		string	`json:"partID"`
		Field		string	`json:"field"`
		Delta		string	`json:"delta"`
	}
	if err := json.Unmarshal(props, &pd); err != nil {
		a.log.Debug("message.part.delta 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if pd.Field != "text" || pd.Delta == "" || pd.MessageID == "" || pd.PartID == "" {
		return
	}
	if r.userMsgs[pd.MessageID] {
		return
	}
	r.lastAssistantMsgID = pd.MessageID
	key := partKey(pd.MessageID, pd.PartID)
	switch r.partTypes[key] {
	case "text":
		if r.partSnap[key] {
			return
		}
		a.setPartText(r, key, r.partSeen[key]+pd.Delta)
	case "":

		if r.pendingBytes+len(pd.Delta) > pendingDeltaLimit {
			a.log.Warn("类型未知的 part 增量超出暂存上限，丢弃",
				"task", r.taskID, "msg", pd.MessageID, "part", pd.PartID,
				"limit_bytes", pendingDeltaLimit)
			return
		}
		r.pendingDelta[key] += pd.Delta
		r.pendingBytes += len(pd.Delta)
	default:

		if frameKind(r.partTypes[key]) == kindReasoning {
			if err := r.frames.Reasoning(key, pd.Delta); err != nil {
				a.log.Warn("写 reasoning 帧失败，不影响回合", "task", r.taskID, "cause", err)
			}
		}
	}
}

n_opencode_Adapter_mapPartUpdated.signature:
// mapPartUpdated 处理 message.part.updated：text 类型 part 携带该 part 的
// 全量文本快照（真实流：文本首帧可能是空串的「part 创建」事件，随后走
// part.delta 增量，收尾再回发完整快照）。
//
// why（类型登记先于过滤 + 按 part 存当前值 + 与 delta 对账）：
//   - part 类型必须在 text 过滤前登记进 partTypes：message.part.delta 只有
//     field 没有 part 类型字段（spike5 实测 reasoning 增量也是 field=text），
//     part.updated 是唯一携带类型的事件——错过登记，reasoning/tool 增量会被
//     当模型输出累积进回合与 render.log。类型揭晓时还要处置该 part 在
//     pendingDelta 里的暂存增量（见 mapPartDelta）
//   - 服务端对同一 part 可能多次回发快照，且增量流结束后会补发全量快照——
//     按 messageID+partID 保存该 part 的当前文本，快照即覆盖，天然去重
//   - 快照不是已见文本的延续时（服务端修订了这一段），覆盖而非叠加：回合文本
//     与 render.log 都是给人读的，"Hello world" 改成 "Hi world" 不该读到
//     "Hello worldHi world"
//   - 空文本快照是 part 创建事件而非有效全量，不置 partSnap、也不清空已累积：
//     后续 delta 仍要照常累积（spike5 实测顺序：空快照 → delta 流 → 全量快照）
func (a *Adapter) mapPartUpdated(r *runState, props json.RawMessage) {
	var pu struct {
		Part struct {
			ID		string	`json:"id"`
			MessageID	string	`json:"messageID"`
			Type		string	`json:"type"`
			Text		string	`json:"text"`
			// 以下四个只在 type=="tool" 时有意义（见 mapToolPart）
			Tool	string	`json:"tool"`
			CallID	string	`json:"callID"`
			State	struct {
				Status	string		`json:"status"`
				Input	json.RawMessage	`json:"input"`
				Output	string		`json:"output"`
			}	`json:"state"`
		} `json:"part"`
	}
	if err := json.Unmarshal(props, &pu); err != nil {
		a.log.Debug("message.part.updated 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	p := pu.Part
	if p.ID == "" || p.MessageID == "" {
		return
	}
	key := partKey(p.MessageID, p.ID)

	r.partTypes[key] = p.Type
	if p.Type == "tool" {

		a.mapToolPart(r, p.Tool, toolPartKey(p.CallID, p.ID),
			p.State.Status, p.State.Input, p.State.Output)
	}
	isText := p.Type == "text" && !r.userMsgs[p.MessageID]
	if isText {
		r.lastAssistantMsgID = p.MessageID
	}

	pendingType := p.Type
	if p.Type == "text" && r.userMsgs[p.MessageID] {
		pendingType = "user-text"
	}
	a.flushPending(r, key, pendingType)
	if !isText {
		return
	}
	if p.Text == "" {
		return
	}
	r.partSnap[key] = true
	seen := r.partSeen[key]
	if p.Text == seen {
		return
	}
	if seen != "" && !strings.HasPrefix(p.Text, seen) {
		a.log.Debug("part 快照被服务端修订，按新快照覆盖",
			"task", r.taskID, "msg", p.MessageID, "part", p.ID)
	}
	a.setPartText(r, key, p.Text)
}

n_opencode_Adapter_mapPermissionAsked.signature:
// mapPermissionAsked 处理 permission.asked（真实事件）：properties.id 即
// PermissionID（manager 按其派生命名空间化的 ticket id，稳定幂等：SSE 重连
// 重放同一权限请求时复用同一 id，CreateTicket 按派生 id 去重）。
//
// 描述组合：permission 字段（如 bash） + metadata.command（如 echo spike-hi）；
// 无 command 时退回 patterns 拼接——尽量贴近工具将要执行的表述。
func (a *Adapter) mapPermissionAsked(r *runState, props json.RawMessage) {
	var pa struct {
		ID		string		`json:"id"`
		SessionID	string		`json:"sessionID"`
		Permission	string		`json:"permission"`
		Patterns	[]string	`json:"patterns"`
		Tool		struct {
			CallID string `json:"callID"`
		}	`json:"tool"`
		Metadata	struct {
			Command	string	`json:"command"`
			// filepath 是小写 p——真机样本如此（testdata/perm_edit.json）。
			// 写成 filePath 会静默取到空串，然后整条请求退化成「提取不出
			// 结构」被 fail-closed 升级，表现为每次编辑都唤醒人，很难查。
			FilePath	string	`json:"filepath"`
			// external_directory 的 bash 形态没有 filepath，越界目录在这里
			ParentDir	string		`json:"parentDir"`
			Directories	[]string	`json:"directories"`
		}	`json:"metadata"`
	}
	if err := json.Unmarshal(props, &pa); err != nil {
		a.log.Debug("permission.asked 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if pa.ID == "" {
		a.log.Debug("permission.asked 事件缺 id，跳过", "task", r.taskID)
		return
	}
	text := pa.Permission
	if cmd := pa.Metadata.Command; cmd != "" {
		text += ": " + cmd
	} else if len(pa.Patterns) > 0 {
		text += ": " + strings.Join(pa.Patterns, " ")
	}

	if strings.TrimSpace(text) == "" {
		a.log.Warn("permission.asked 无可读描述，按未说明权限交协调者",
			"task", r.taskID, "perm", pa.ID)
		text = "opencode 未提供权限描述（id " + pa.ID + "），请 handoff attach 查看现场"
	}

	permSess := pa.SessionID
	if permSess == "" {
		permSess = r.session
	}
	if permSess != r.session {
		r.sessMu.RLock()
		title := r.childSessions[permSess]
		r.sessMu.RUnlock()
		if title != "" {
			text = "[子 agent: " + title + "] " + text
		} else {

			text = "[子 agent] " + text
		}
	}
	r.sessMu.Lock()
	r.permSession[pa.ID] = permSess
	r.sessMu.Unlock()
	a.log.Info("权限请求已归属会话", "task", r.taskID, "perm", pa.ID,
		"session", permSess, "is_child", permSess != r.session)

	r.permText[pa.ID] = text
	if pa.Tool.CallID == "" {
		a.log.Warn("opencode 权限请求缺少 tool.callID，不暂停未知工具",
			"task", r.taskID, "perm", pa.ID, "session", permSess)
	} else {
		r.sessMu.Lock()
		if r.permTiming == nil {
			r.permTiming = map[string]permissionTiming{}
		}
		_, duplicate := r.permTiming[pa.ID]
		if !duplicate {
			r.permTiming[pa.ID] = permissionTiming{part: pa.Tool.CallID, paused: true}
		}
		r.sessMu.Unlock()
		if duplicate {
			a.log.Debug("重复 permission.asked 不重复暂停工具窗口",
				"task", r.taskID, "perm", pa.ID, "part", pa.Tool.CallID)
		} else {
			a.log.Info("opencode 权限等待开始", "task", r.taskID,
				"perm", pa.ID, "part", pa.Tool.CallID, "session", permSess)
			entries := r.seg.PauseWaiting(pa.Tool.CallID)
			if len(entries) == 0 {
				a.log.Warn("opencode 权限请求未找到对应工具等待窗口",
					"task", r.taskID, "perm", pa.ID, "part", pa.Tool.CallID)
			} else {
				a.reportTiming(r, entries)
			}
		}
	}

	// 结构化载荷（B23/B27）：permission 字段就是 opencode 的工具类别原文，
	// 真机实测取值有 bash / edit / external_directory，直接作归一化来源。
	//
	// 为什么路径不取 patterns：patterns 里是相对路径与通配摘要（真机样本里
	// edit 的 patterns 是 ["probe.md"]、external_directory 的是 ["/tmp/*"]），
	// 拿它判归属会把通配符当成路径。绝对路径只在 metadata 里。
	var req *executor.PermRequest
	tool := executor.NormalizePermTool(pa.Permission)
	paths := pa.Metadata.Directories
	if pa.Metadata.FilePath != "" {
		paths = append([]string{pa.Metadata.FilePath}, paths...)
	}
	switch {
	case pa.Metadata.Command != "":
		if tool == executor.PermToolOther {
			tool = executor.PermToolBash
		}

		req = &executor.PermRequest{Tool: tool, Command: pa.Metadata.Command, Paths: paths}
	case len(paths) > 0:
		if tool == executor.PermToolOther {
			tool = executor.PermToolWrite
		}
		req = &executor.PermRequest{Tool: tool, Paths: paths}
	}
	if req == nil {

		a.log.Warn("opencode 权限请求提取不出结构化载荷，将由 manager 升级人工",
			"task", r.taskID, "perm", pa.ID, "permission", pa.Permission)
	}
	if r.approval != nil {
		ev := executor.AdapterEvent{Type: "permission", PermissionID: pa.ID,
			Text:	turn.TruncateMarked(text, permTextHardLimit), Perm: req}
		go a.authorizeNativePermission(r, ev)
		return
	}
	a.emit(r, executor.AdapterEvent{
		Type:	"permission", PermissionID: pa.ID,
		Text:	turn.TruncateMarked(text, permTextHardLimit),
		Perm:	req,
	})
}

n_opencode_Adapter_mapQuestionAsked.signature:
// mapQuestionAsked 处理 question.asked：opencode 原生 question 工具的提问请求。
//
// 与 permission.asked 同构（同一条 SSE 流上的并排事件），但有一处根本差别：
// **提问不结束回合**。question 工具阻塞等应答，session 不会转 idle，答复之后
// 是同一个回合继续——因此本函数**不得** clearTurn / advanceWatermark，
// 清缓冲会丢掉该回合已累积的文本，推进水位会让后续对账错位。
//
// 参数：props 为事件的 properties 原文（{id, sessionID, questions[], tool{}}）
//
// 注意：
//   - 本函数在 turnMu 下执行（见 mapEvent 的 switch 契约），可安全读写回合状态；
//     不得在此做网络 I/O
//   - 按 requestID 去重：seenQuestionIDs 只负责**进程内**的 SSE 重放去重；
//     跨进程（agentd 重启）的幂等由 manager 按事件上的 QuestionID 承担
func (a *Adapter) mapQuestionAsked(r *runState, props json.RawMessage) {
	var qa struct {
		ID		string		`json:"id"`
		SessionID	string		`json:"sessionID"`
		Questions	[]QuestionInfo	`json:"questions"`
	}
	if err := json.Unmarshal(props, &qa); err != nil {
		a.log.Debug("question.asked 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if qa.ID == "" {
		a.log.Debug("question.asked 事件缺 id，跳过", "task", r.taskID)
		return
	}
	if r.seenQuestionIDs[qa.ID] {
		a.log.Debug("question.asked 重复到达（SSE 重放），已忽略",
			"task", r.taskID, "request", qa.ID)
		return
	}
	r.seenQuestionIDs[qa.ID] = true

	text := renderQuestionTicket(qa.Questions)

	if len(qa.Questions) == 0 {
		a.log.Warn("question.asked 无问题内容，按未说明提问交协调者",
			"task", r.taskID, "request", qa.ID)
		text = "opencode 提出了一个空提问（id " + qa.ID + "），请 handoff attach 查看现场后作答"
	}

	qSess := qa.SessionID
	if qSess == "" {
		qSess = r.session
	}
	if qSess != r.session {
		r.sessMu.RLock()
		title := r.childSessions[qSess]
		r.sessMu.RUnlock()
		if title != "" {
			text = "[子 agent: " + title + "] " + text
		} else {
			text = "[子 agent] " + text
		}
	}

	r.pendingQuestionID = qa.ID
	r.pendingQuestions = qa.Questions

	r.askedViaTool = true

	a.log.Info("收到 executor 提问，转工单交协调者", "task", r.taskID,
		"request", qa.ID, "session", qSess, "is_child", qSess != r.session,
		"question_count", len(qa.Questions))
	a.emit(r, executor.AdapterEvent{
		Type:	"question", QuestionID: qa.ID, Text: turn.ClampQuestion(text),
	})

}

n_opencode_Adapter_mapSessionStatus.signature:
// mapSessionStatus 处理 session.status：status.type=idle 是回合结束的主信号
// （真实样本：{"type":"session.status","properties":{"status":{"type":"idle"}}}；
// busy 状态同结构，不触发）。同现的 session.idle 由 mapEvent 忽略防重复。
func (a *Adapter) mapSessionStatus(r *runState, props json.RawMessage) {
	var st struct {
		Status struct {
			Type string `json:"type"`
		} `json:"status"`
	}
	if err := json.Unmarshal(props, &st); err != nil {
		a.log.Debug("session.status 载荷解析失败，跳过", "task", r.taskID, "cause", err)
		return
	}
	if st.Status.Type == "idle" {
		a.scheduleIdle(r, props)
		return
	}

	r.idleGen++
}

n_opencode_Adapter_mapToolPart.signature:
// mapToolPart 把一次工具调用的推进落成帧 + 打点。调用方必须持有 r.turnMu。
//
// 参数：tool 是工具名（part.tool）；key 是配对键；status/input/output 取自
// part.state。
//
// 去重是本函数的主要职责：opencode 对同一个 tool part 会反复发 running
// （输出边长边发），终态也可能因 SSE 重放再来一次。toolStages 保证
// tool_call 帧与 tool_result 帧各恰好一条。
//
// 打点必须在写帧**之前**：写帧要过一次头尾截断与文件 IO，把那段时间算进
// 工具耗时是在给工具记别人的账。
//
// 为什么 dur 取 Segmenter 的墙钟而不是 part.state.time：state.time 记的是
// 「最后一次尝试」的起点，重试时会跳变、且不含权限审批等待（真机抓包实测：
// 同一个 callID 的 time.start 在一次审批前后从 …464643 跳到 …478355）。
// claudecode/codex 的工具耗时都含审批等待，取 state.time 会让 opencode 的
// 同一条命令看起来比别家快——那是**口径差不是性能差**（计划 §1.4 的拍板）。
func (a *Adapter) mapToolPart(r *runState, tool, key, status string,
	input json.RawMessage, output string) {
	if key == "" {
		return
	}
	st, terminal := toolResultStatus(status)

	if r.toolStages[key] == toolStageNone && (toolInputReady(input) || terminal) {
		r.toolStages[key] = toolStageStarted
		a.reportTiming(r, r.seg.ToolStart(key, tool, toolDetail(input)))

		if err := r.frames.ToolCall(key, tool, string(input)); err != nil {
			a.log.Warn("写 tool_call 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
	}
	if !terminal || r.toolStages[key] == toolStageDone {
		return
	}
	r.toolStages[key] = toolStageDone

	dur, entries := r.seg.ToolEnd(key)
	if err := r.frames.ToolResult(key, st, output, dur); err != nil {
		a.log.Warn("写 tool_result 帧失败，不影响回合", "task", r.taskID, "cause", err)
	}
	a.reportTiming(r, entries)
}

n_opencode_Adapter_maybeProgress.signature:
// maybeProgress 节流发 progress：每任务至多每 progressThrottle 一条
// （Task 12 e2e 遗留：按回合粒度细化）。
func (a *Adapter) maybeProgress(r *runState) {
	now := time.Now()
	if now.Sub(r.lastProgress) < progressThrottle {
		return
	}
	r.lastProgress = now
	a.emit(r, executor.AdapterEvent{Type: "progress", Text: turn.TailRunes(r.turnText(), 200)})
}

n_opencode_Adapter_reapRetained.signature:
// reapRetained 回收 Stop 时因 kill 失败而保留的运行态（A-10）。
//
// 周期重试 Kill：成功（或 serve 已自灭）即注销运行态；连续失败达
// reapMaxAttempts 后放弃并注销，打 Error 交人工清理执行者进程。
//
// why（保留必须配重试与上限）：保留态是惰性的——没有 goroutine、事件通道已关，
// 它唯一的价值就是「还留着 handle，还有机会回收孤儿 serve」。不重试，这个价值
// 从不兑现（Stop 只由归档调用一次，重启也不接管），条目只是 runs 表里的内存与
// lookup 阴影；不设上限，runs 表就只增不减。
func (a *Adapter) reapRetained(r *runState) {
	interval := a.reapInterval
	if interval <= 0 {
		interval = reapIntervalDefault
	}
	maxAttempts := a.reapMaxAttempts
	if maxAttempts <= 0 {
		maxAttempts = reapMaxAttemptsDefault
	}
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		<-ticker.C
		kerr := r.handle.Kill()
		if kerr == nil || !r.handle.Alive() {
			a.log.Info("保留态回收成功", "task", r.taskID, "attempt", attempt, "cause", kerr)
			a.drop(r.taskID)
			return
		}
		a.log.Warn("保留态回收重试失败", "task", r.taskID,
			"attempt", attempt, "max_attempts", maxAttempts, "cause", kerr)
	}
	a.log.Error("保留态回收重试耗尽，注销条目并交人工清理（请 handoff stop 回收）",
		"task", r.taskID, "attempts", maxAttempts)
	a.drop(r.taskID)
}

n_opencode_Adapter_reconcileAfterRecover.signature:
// reconcileAfterRecovery 是两个自动触发点共用的对账入口。
//
// 参数：
//   - ctx: 控制查询超时
//   - taskID: 目标任务
//   - trigger: 触发来源，只用于日志（"startup" = agentd 启动恢复，
//     "reconnect" = 连接断开重连）
//
// 注意：
//   - **不返回错误，且绝不 panic**：spec §6.3 的硬要求——对账失败不能阻断恢复。
//     一次网络抖动若能让 Resume 判不可恢复，比 B38 本身还糟
func (a *Adapter) reconcileAfterRecovery(ctx context.Context, taskID, trigger string) {
	out, err := a.Reconcile(ctx, taskID)
	if err != nil {
		a.log.Warn("恢复后对账失败，恢复本身不受影响",
			"task", taskID, "trigger", trigger, "cause", err)
		return
	}
	a.log.Info("恢复后对账完成", "task", taskID, "trigger", trigger,
		"turn_ended", out.TurnEnded, "emitted", out.Emitted, "note", out.Note)
}

n_opencode_Adapter_rediscoverPendingQues.signature:
// rediscoverPendingQuestions 在恢复后重新发现本任务挂起的提问并补发工单。
//
// 参数：taskID 为已完成运行态重建的任务 id
//
// 为什么必须有这一步：SSE 没有重放语义，agentd 重启窗口里发生的
// question.asked 永远收不到。而 opencode 侧的 question 工具还在阻塞等应答——
// 不重新发现，任务就是个谁也叫不醒的孤儿（与 B18/B20/B24 同一条纪律：
// 重启后一切「executor 那边还等着人」的状态都必须被重新发现）。
//
// 注意：
//   - GET /question 返回全部会话的挂起请求，必须按本任务的会话 id 过滤
//   - 本函数在 goroutine 里跑，不阻塞 Resume 返回；失败只记日志（挂起提问
//     发现不了仍有 stall 看门狗兜底，不该让恢复本身失败）
func (a *Adapter) rediscoverPendingQuestions(ctx context.Context, taskID string) {
	r := a.lookup(taskID)
	if r == nil || r.api == nil {
		a.log.Debug("重新发现挂起提问跳过：该任务无运行态", "task", taskID)
		return
	}
	pending, err := r.api.ListPendingQuestions(ctx)
	if err != nil {
		a.log.Warn("重新发现挂起提问失败，若确有挂起提问将由 stall 看门狗兜底",
			"task", taskID, "cause", err)
		return
	}
	for _, p := range pending {
		if p.SessionID != r.session {
			continue
		}
		r.turnMu.Lock()
		if r.seenQuestionIDs[p.ID] {
			r.turnMu.Unlock()
			continue
		}
		r.seenQuestionIDs[p.ID] = true
		r.pendingQuestionID = p.ID
		r.pendingQuestions = p.Questions
		r.turnMu.Unlock()

		a.log.Info("恢复后发现挂起提问，补发工单", "task", taskID,
			"request", p.ID, "question_count", len(p.Questions))

		a.emit(r, executor.AdapterEvent{Type: "question", QuestionID: p.ID,
			Text:	turn.ClampQuestion(renderQuestionTicket(p.Questions))})
		return
	}
	a.log.Info("恢复后未发现本任务的挂起提问", "task", taskID, "total_pending", len(pending))
}

n_opencode_Adapter_replyPendingQuestion.signature:
// replyPendingQuestion 把协调者的答复折算并回填给 opencode 的 question 工具。
//
// 参数：
//   - reqID/qs: 挂起请求的 id 与问题结构
//   - text: 协调者答复原文
//
// 返回：
//   - nil: 应答成功，或答复折算不了/被服务端拒绝而已重发工单（两者对协调者
//     都不是错误，是「再答一次」）
//   - 非 nil: 网络/服务端故障等真错误，冒泡给协调者终端
//
// 注意：
//   - 折算失败**不触达服务端**：猜一个最接近的选项会让模型按错误前提继续干活
func (a *Adapter) replyPendingQuestion(ctx context.Context, r *runState,
	reqID string, qs []QuestionInfo, text string) error {

	answers, perr := parseQuestionAnswers(qs, text)
	if perr != nil {
		a.log.Warn("答复无法折算成选项，重发工单请协调者再答",
			"task", r.taskID, "request", reqID, "cause", perr)

		a.emit(r, executor.AdapterEvent{Type: "question", QuestionID: reqID,
			Text: turn.ClampQuestion("上一次答复没能对上选项（" + perr.Error() + "）。\n\n" +
				renderQuestionTicket(qs))})
		return nil
	}
	a.log.Info("答复已折算，回填 executor 提问", "task", r.taskID,
		"request", reqID, "answers", answers)
	if err := r.api.ReplyQuestion(ctx, reqID, answers); err != nil {
		if errors.Is(err, ErrCustomAnswerRejected) {
			a.log.Warn("opencode 不接受该自定义答案，重发工单请协调者改填选项",
				"task", r.taskID, "request", reqID, "cause", err)
			a.emit(r, executor.AdapterEvent{Type: "question", QuestionID: reqID,
				Text: turn.ClampQuestion("opencode 不接受自定义答案，请改填编号或选项原文。\n\n" +
					renderQuestionTicket(qs))})
			return nil
		}
		return err
	}
	r.clearPendingQuestion()
	a.log.Info("提问已应答，回合继续", "task", r.taskID, "request", reqID)
	return nil
}

n_opencode_Adapter_reportDeliveryFailure.signature:
// reportDeliveryFailure 将“审批已形成但原生回传失败”交给既有注入对象。
//
// 参数：r 为当前任务运行态；permID 为原生权限身份；cause 为真实回传错误。
// 注意：缺少可选能力时只能记录错误并结束当前授权，不伪造 Ack 或本地事件。
func (a *Adapter) reportDeliveryFailure(ctx context.Context, r *runState, permID string, cause error) {
	reporter, ok := r.approval.(deliveryFailureReporter)
	if !ok {
		a.log.Error("权限回传失败但审批 client 缺少 delivery failure 能力",
			"task", r.taskID, "perm", permID,
			"ref", executor.NamespacedTicketID(r.taskID, permID), "cause", cause)
		return
	}
	ticketID := executor.NamespacedTicketID(r.taskID, permID)
	a.log.Info("权限回传失败开始上报", "task", r.taskID, "perm", permID,
		"ticket", ticketID, "cause", cause)
	reporter.NoteDeliveryFailed(r.taskID, ticketID, cause)
	a.log.Info("权限回传失败已上报", "task", r.taskID, "perm", permID, "ticket", ticketID)
}

n_opencode_Adapter_reportTiming.signature:
// reportTiming 把段切分器产出的条目逐条经 usage 事件上报。
//
// 为什么走 usage 而不是新事件类型：Usage（当前占用）、Spend（累计消耗）与
// Timing（耗时）是同一次模型调用结束时的三样产物；拆成两个事件，两者之间
// 就能插进一次 agentd 重启（契约文档 §6.3 的拍板记录）。
//
// entries 为空是常态（不是错误），静默返回。
func (a *Adapter) reportTiming(r *runState, entries []proto.TimingEntry) {
	for i := range entries {
		e := entries[i]
		if !a.emit(r, executor.AdapterEvent{Type: "usage", Timing: &e}) {
			a.log.Debug("opencode 耗时条目未能上报（事件通道已终止或已满）",
				"task", r.taskID, "key", e.Key, "remaining", len(entries)-i)
			return
		}
	}
}

n_opencode_Adapter_resolveChildSession.signature:
// resolveChildSession 判定一个陌生会话是否是本任务派生的子会话。
//
// 参数：
//   - sessionID: 事件携带的会话 id（调用方保证非空）
//
// 返回：
//   - title: 子会话标题（供工单标注）；认亲失败时为空
//   - ok:    是否认亲成功
//
// 注意：
//   - 只缓存正结果。一次网络抖动导致的判定失败若被缓存，这个子会话就被永久
//     拉黑，它后续每一条审批都会被丢弃——那正是本次要修的故障形态
//   - 不持 sessMu 跨 HTTP 调用：查缓存与写缓存各自短暂加锁，网络 I/O 不在锁下。
//     同一个新子会话的两条事件并发到达会各发一次 GET /session，幂等且无害，
//     不值得为它加 singleflight
//   - 不向上递归找祖先：opencode 自己给 subagent 下了 permission:[{task,*,deny}]
//     （真机实测），嵌套深度恒为 1。真出现二级说明这条不变量被打破了，那是断言
//     失败，该报警而不是在事件热路径上做无界遍历
func (a *Adapter) resolveChildSession(r *runState, sessionID string) (title string, ok bool) {
	r.sessMu.RLock()
	title, cached := r.childSessions[sessionID]
	r.sessMu.RUnlock()
	if cached {
		a.log.Debug("子会话认亲命中缓存", "task", r.taskID, "child", sessionID)
		return title, true
	}

	a.log.Info("子会话认亲开始", "task", r.taskID, "event_session", sessionID, "own_session", r.session)
	start := time.Now()

	ctx, cancel := context.WithTimeout(context.Background(), ownershipTimeout)
	defer cancel()
	d, err := r.api.GetSession(ctx, sessionID)
	if err != nil {
		a.log.Warn("子会话认亲失败：查询会话详情出错，本条审批请求丢弃",
			"task", r.taskID, "event_session", sessionID, "cause", err)
		return "", false
	}
	switch {
	case d.ParentID == r.session:
		r.sessMu.Lock()
		r.childSessions[sessionID] = d.Title
		r.sessMu.Unlock()
		a.log.Info("子会话认亲成功", "task", r.taskID, "child", sessionID,
			"parent", d.ParentID, "title", d.Title, "elapsed_ms", time.Since(start).Milliseconds())
		return d.Title, true
	case d.ParentID == "":
		a.log.Warn("子会话认亲失败：该会话没有父会话，是与本任务无关的顶层会话，本条审批请求丢弃",
			"task", r.taskID, "event_session", sessionID, "own_session", r.session)
	default:
		a.log.Warn("子会话认亲失败：父会话不是本任务会话，opencode「subagent 不可再派生 subagent」"+
			"（task:deny）的不变量可能已被打破，本条审批请求丢弃",
			"task", r.taskID, "event_session", sessionID, "event_parent", d.ParentID, "own_session", r.session)
	}
	return "", false
}

n_opencode_Adapter_resolveIdle.signature:
// resolveIdle 是 idle 去抖到期后的回合分类入口（定时器 goroutine 执行）。
// 代次不匹配说明宽限期内回合又推进了，本次候选作废。
func (a *Adapter) resolveIdle(r *runState, gen uint64, raw json.RawMessage) {
	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	if r.idleGen != gen {
		a.log.Debug("候选回合结束已被新活动撤销", "task", r.taskID,
			"scheduled_gen", gen, "current_gen", r.idleGen)
		return
	}
	a.mapIdle(r, raw)
}

n_opencode_Adapter_scheduleIdle.signature:
// scheduleIdle 把一次 idle 登记为「候选回合结束」，静默满 idleGrace 后才真正分类。
// 调用方须持有 turnMu。
//
// why（去抖而非见 idle 即分类）：idle 是 opencode 的会话状态信号，不等于「模型
// 这一轮说完了」——工具调用间隙、权限等待期间都可能出现瞬时 idle。见 idle 即
// 分类会把半截回合当成完整回合：命中 git 兜底时更会因「仓库里已有新提交」谎报
// completed，协调者据此执行 done，Stop 就在 opencode 仍在干活时杀掉了执行者进程。
//
// 宽限期内任何回合推进（新增文本、非 idle 状态、下一条 idle）都会自增 idleGen，
// 使在途的候选失效——真正的回合结束后不会再有事件，宽限期自然走完。代价是回合
// 分类延迟 idleGrace，相对协调者分钟级的往返可忽略。
func (a *Adapter) scheduleIdle(r *runState, raw json.RawMessage) {
	r.idleGen++
	gen := r.idleGen
	if r.idleTimer != nil {
		r.idleTimer.Stop()
	}
	grace := a.idleGrace
	if grace <= 0 {
		grace = idleGraceDefault
	}

	snapshot := append(json.RawMessage(nil), raw...)
	a.log.Debug("登记候选回合结束，等待去抖", "task", r.taskID, "grace", grace)
	r.idleTimer = time.AfterFunc(grace, func() { a.resolveIdle(r, gen, snapshot) })
}

n_opencode_Adapter_setPartText.signature:
// setPartText 把某个 part 的当前文本置为 text，并把变化反映到 render.log
// 与 progress——part.updated 与 part.delta 两个入口共用。
//
// 追加（新文本是已见文本的延续）时 render.log 只写增量，保持 tail -f 的
// 流式观感；服务端修订该段时写一条带标记的整段，让旁观者知道前面那段已作废
// （render.log 是 append-only 文件，改不了历史）。
func (a *Adapter) setPartText(r *runState, key, text string) {
	old, existed := r.partSeen[key]
	if !existed {
		r.turnOrder = append(r.turnOrder, key)
	}
	if text == old {
		return
	}

	r.idleGen++
	r.partSeen[key] = text
	render := strings.TrimPrefix(text, old)
	if old != "" && !strings.HasPrefix(text, old) {
		render = "\n[以上一段已被服务端修订为]\n" + text
	}
	if err := r.appendRender(render); err != nil {
		a.log.Warn("追加 render.log 失败", "task", r.taskID, "cause", err)
	}

	if old == "" || strings.HasPrefix(text, old) {
		if err := r.frames.Text(key, render); err != nil {
			a.log.Warn("写 text 帧失败，不影响回合", "task", r.taskID, "cause", err)
		}
	}
	a.maybeProgress(r)
}

n_opencode_Adapter_startRun.signature:
// startRun 完成「建会话 → 发初始 prompt → 记录起点 commit → 启动订阅与看门狗」。
//
// 这是 Start 的内部骨架，单独成函数以便测试注入 httptest server 与假探活
// （免真实 opencode 二进制）。
//
// 返回：
//   - sessionID: 新建的 opencode 会话 id（经 Result.SessionID 随结果事件上报，
//     供 manager 落 task.ExecutorSession）
//   - err: 建会话/发 prompt 失败；失败时运行态已注销
func (a *Adapter) startRun(ctx context.Context, req executor.StartReq, api *API, handle serveHandle) (sessionID string, err error) {
	r := a.newRun(req.Task.ID, req.TaskDir, req.Task.Workdir())
	r.approval = req.Approval
	r.api = api
	r.handle = handle
	if err := r.frames.BeginTurn("dispatch", ""); err != nil {
		a.log.Warn("写 turn_start 帧失败，不影响回合", "task", req.Task.ID, "cause", err)
	}
	a.reportTiming(r, r.seg.BeginTurn(r.frames.Turn()))
	a.log.Info("adapter 启动运行", "task", r.taskID, "task_dir", r.taskDir, "workdir", r.repoPath)
	defer func() {
		if err != nil {
			a.log.Error("adapter 启动运行失败", "task", r.taskID, "cause", err)
			r.runCancel()
			a.drop(r.taskID)
		} else {
			a.log.Info("adapter 运行已启动", "task", r.taskID, "session", sessionID)
		}
	}()

	sessionID, err = api.CreateSession(ctx)
	if err != nil {
		return "", err
	}
	r.session = sessionID
	a.log.Info("opencode 会话已建", "task", r.taskID, "session", sessionID)

	a.emit(r, executor.AdapterEvent{Type: "progress", SessionID: sessionID, Text: "会话就绪"})

	promptPath := filepath.Join(r.taskDir, promptFileName)
	promptContent, err := os.ReadFile(promptPath)
	if err != nil {
		return "", fmt.Errorf("读取任务 prompt %s: %w", promptPath, err)
	}
	if err := api.PromptAsync(ctx, sessionID, string(promptContent)); err != nil {
		return "", err
	}
	a.log.Info("opencode 初始 prompt 已发", "task", r.taskID,
		"session", sessionID, "prompt_len", len(promptContent))

	r.captureStartCommit(a)

	go r.subscribeLoop(a)
	go a.watchdog(r)
	return sessionID, nil
}

n_opencode_Adapter_watchdog.signature:
// watchdog 是 serve 存活看门狗：周期探活，连续 3 次失败判定 serve 死亡，
// 取消运行 ctx 让订阅退出——failed 结果由 subscribeLoop 统一产出（保持
// 「事件通道只有一个写入者」的关闭权约定）。探活间隔自适应用默认配置
// （见 watchdogConfig）。
func (a *Adapter) watchdog(r *runState) {
	a.watchdogWithConfig(r, watchdogConfig{
		fastInterval:	watchdogFastInterval,
		slowInterval:	watchdogSlowInterval,
		fastProbes:	watchdogFastProbes,
	})
}

n_opencode_Adapter_watchdogWithConfig.signature:
// watchdogWithConfig 是 watchdog 的配置注入骨架（探活节奏自适应逻辑）：
//
//   - 收到新事件（emit 打点 lastEventAt 有变化）→ 回到高频：任务活跃（模型在
//     产出/权限在等裁决），serve 死亡要能被快速发现
//   - 高频下连续 fastProbes 次成功探活且无新事件 → 降频到 slow：任务静默
//     （waiting_review 挂过夜），200ms 高频探活是纯浪费——每天每任务约 43 万次
//     HTTP 请求（P1-17）
//   - 任一失败 → 立即回到高频：死亡判定是看门狗唯一职责，不能被降频拖慢
//     （慢档最坏 3 次 × 2s ≈ 6s 才判死，MVP 可接受）
func (a *Adapter) watchdogWithConfig(r *runState, cfg watchdogConfig) {
	failures := 0
	successes := 0
	prevEvent := r.lastEventAt.Load()
	interval := cfg.fastInterval
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-r.stopCh:
			return
		case <-r.runCtx.Done():
			return
		case <-ticker.C:
			evTs := r.lastEventAt.Load()
			active := evTs != prevEvent
			prevEvent = evTs
			if active && interval != cfg.fastInterval {
				a.log.Debug("探活回到高频：收到新事件，任务活跃", "task", r.taskID)
				successes = 0
				interval = cfg.fastInterval
				ticker.Stop()
				ticker = time.NewTicker(interval)
			}
			if r.handle.Alive() {
				failures = 0
				successes++
				if interval == cfg.fastInterval && !active && successes >= cfg.fastProbes {

					a.log.Debug("探活降频：任务静默，探活间隔升到慢档", "task", r.taskID,
						"fast", cfg.fastInterval, "slow", cfg.slowInterval)
					successes = 0
					interval = cfg.slowInterval
					ticker.Stop()
					ticker = time.NewTicker(interval)
				}
				continue
			}
			failures++
			successes = 0
			if interval != cfg.fastInterval {
				a.log.Debug("探活回到高频：出现失败，需快速判定死亡", "task", r.taskID)
				interval = cfg.fastInterval
				ticker.Stop()
				ticker = time.NewTicker(interval)
			}
			if failures >= watchdogFailThreshold {
				a.log.Error("opencode serve 探活失败达阈值，判定死亡",
					"task", r.taskID, "failures", failures)
				r.runCancel()
				return
			}
		}
	}
}

n_opencode_Coordinator_CancelTurn.signature:
func (c *Coordinator) CancelTurn(_ context.Context, ref executor.CoordSessionRef) error {
	key := ref.SessionID
	if key == "" {
		c.log.Info("CancelTurn 缺少 session id，跳过", "cli", ref.CLI)
		return nil
	}
	c.mu.Lock()
	cancel, ok := c.canc[key]
	c.mu.Unlock()
	if !ok {
		c.log.Info("CancelTurn 无在途回合", "cli", ref.CLI, "session_id", ref.SessionID)
		return nil
	}
	c.log.Info("CancelTurn 取消在途回合", "cli", ref.CLI, "session_id", ref.SessionID)
	cancel()
	return nil
}

n_opencode_Coordinator_Launch.signature:
func (c *Coordinator) Launch(ctx context.Context, spec executor.CoordSessionSpec, prompt string) (executor.CoordTurnResult, error) {
	if err := executor.RequireLaunchPrompt(prompt); err != nil {
		return executor.CoordTurnResult{}, err
	}
	c.log.Info("Coordinator.Launch 进入", "cli", spec.CLI, "home_isolated", spec.HomeDir != "", "prompt_bytes", len(prompt))
	return c.turn(ctx, hostapi.TurnRequest{
		CLI:	spec.CLI, HomeDir: spec.HomeDir, Workdir: spec.Workdir,
		Model:	spec.Model, Prompt: prompt, Env: spec.Env,
	})
}

n_opencode_Coordinator_Resume.signature:
func (c *Coordinator) Resume(ctx context.Context, ref executor.CoordSessionRef, prompt string) (executor.CoordTurnResult, error) {
	if err := executor.RequireResumeRef(ref); err != nil {
		return executor.CoordTurnResult{}, err
	}
	c.log.Info("Coordinator.Resume 进入", "cli", ref.CLI, "session_set", ref.SessionID != "")
	return c.turn(ctx, hostapi.TurnRequest{
		CLI:	ref.CLI, HomeDir: ref.HomeDir, Workdir: ref.Workdir,
		Model:	ref.Model, Prompt: prompt, SessionID: ref.SessionID, Env: nil,
	})
}

n_opencode_Coordinator_turn.signature:
func (c *Coordinator) turn(ctx context.Context, req hostapi.TurnRequest) (res executor.CoordTurnResult, err error) {
	if ctx == nil {
		ctx = context.Background()
	}
	ctx, cancel := context.WithCancel(ctx)
	key := req.SessionID
	c.mu.Lock()
	if key != "" {
		c.canc[key] = cancel
	}
	c.mu.Unlock()
	defer func() {
		cancel()
		c.mu.Lock()
		if key != "" {
			delete(c.canc, key)
		}
		c.mu.Unlock()
		if err != nil {
			c.log.Error("协调回合失败", "cli", req.CLI, "cause", err)
		} else {
			c.log.Info("协调回合完成", "cli", req.CLI, "session_set", res.SessionID != "", "output_bytes", len(res.Output))
		}
	}()
	reply, err := c.Host.RunTurn(ctx, req)
	if err != nil {
		return executor.CoordTurnResult{}, err
	}
	return executor.CoordTurnResult{SessionID: reply.SessionID, Output: reply.Output}, nil
}

n_opencode_New.signature:
// New 创建 opencode adapter。
//
// 参数：
//   - log: 本模块日志入口（nil 时退回 slog.Default()）
func New(log *slog.Logger) *Adapter {
	if log == nil {
		log = slog.Default()
	}
	return &Adapter{
		log:			log,
		runs:			make(map[string]*runState),
		idleGrace:		idleGraceDefault,
		reapInterval:		reapIntervalDefault,
		reapMaxAttempts:	reapMaxAttemptsDefault,
	}
}

n_opencode_NewAPI.signature:
// NewAPI 创建 opencode server 客户端。
//
// 参数：
//   - baseURL: opencode serve 的地址（如 http://127.0.0.1:4345），尾斜杠会被剥掉
//   - password: OPENCODE_SERVER_PASSWORD 的值，与用户名 opencode 拼成 basic auth
func NewAPI(baseURL, password string) *API {
	return NewAPIWithUnaryTimeout(baseURL, password, unaryTimeout)
}

n_opencode_NewAPIWithSSEBackoff.signature:
// NewAPIWithSSEBackoff 是 NewAPI 的 SSE 退避可注入变体：测试注入毫秒级退避，
// 让「成功连接后复位」的时间敏感断言不依赖真实 1s..30s 节奏；生产代码一律走
// NewAPI 的默认退避。
//
// 参数：
//   - initial/max: SSE 断流重连的初始/封顶退避（见 SubscribeEvents）
func NewAPIWithSSEBackoff(baseURL, password string, initial, max time.Duration) *API {
	return NewAPIWithSSETiming(baseURL, password, initial, max, sseStableAfter)
}

n_opencode_NewAPIWithSSETiming.signature:
// NewAPIWithSSETiming 在退避区间之外再注入「连接算健康」的存活门槛，
// 供「退避复位按连接寿命而非按 200 响应」（A-8）的断言把门槛压到毫秒级。
//
// 参数：
//   - stableAfter: 连接存活多久才算健康、才复位退避（生产默认 sseStableAfter）
func NewAPIWithSSETiming(baseURL, password string, initial, max, stableAfter time.Duration) *API {
	return newAPI(baseURL, password, unaryTimeout, initial, max, stableAfter)
}

n_opencode_NewAPIWithUnaryTimeout.signature:
// NewAPIWithUnaryTimeout 是 NewAPI 的超时可注入变体：测试注入毫秒级短超时验证
// 「半死 server 不永久挂起」；生产代码一律走 NewAPI 的 30s 默认值。
//
// 参数：
//   - timeout: 一元调用（httpClient）的超时；SSE 长连接（sseClient）不受影响
func NewAPIWithUnaryTimeout(baseURL, password string, timeout time.Duration) *API {
	return newAPI(baseURL, password, timeout, sseInitialBackoff, sseMaxBackoff, sseStableAfter)
}

