n_opencode_OneShotArgv.signature:
// OneShotArgv 编码 opencode 一次性调用的 argv。
func OneShotArgv(model, prompt string, _ executor.OneShotLimits) ([]string, error) {
	if model != "" {
		return []string{"opencode", "run", "-m", model, prompt}, nil
	}
	return []string{"opencode", "run", prompt}, nil
}

n_opencode_OneShot_Invoke.signature:
func (s *OneShot) Invoke(ctx context.Context, req executor.OneShotReq) (executor.OneShotReply, error) {
	s.log.Info("OneShot.Invoke 进入", "harness", executor.HarnessOpenCode, "model", req.Model, "prompt_bytes", len(req.Prompt), "effort", req.Limits.Effort)
	argv, err := OneShotArgv(req.Model, req.Prompt, req.Limits)
	if err != nil {
		s.log.Error("OneShot argv 编码失败", "cause", err)
		return executor.OneShotReply{Status: executor.OneShotFailed}, err
	}
	out, err := executor.RunOneShotProcess(ctx, argv, req.Env, req.Workdir, req.HomeDir)
	if ctx.Err() != nil {
		s.log.Info("OneShot 已取消", "cause", ctx.Err())
		return executor.OneShotReply{Text: out, Status: executor.OneShotCanceled}, ctx.Err()
	}
	if err != nil {
		s.log.Error("OneShot 进程失败", "cause", err)
		return executor.OneShotReply{Text: out, Status: executor.OneShotFailed}, err
	}
	s.log.Info("OneShot.Invoke 完成", "status", executor.OneShotOK, "output_bytes", len(out))
	return executor.OneShotReply{Text: out, Status: executor.OneShotOK}, nil
}

n_opencode_Proc_Alive.signature:
// Alive 检查 serve 是否仍然存活：存活锁被持有 且 端口有 HTTP 应答。
//
// 两者缺一即视为死亡。锁证明 shim 还在，HTTP 证明 serve 本身还在应答——
// serve 崩了但 shim 尚未收尸的窗口由 HTTP 这条兜住。
func (p *Proc) Alive() bool {
	if !prochost.Alive(p.Handle) {
		return false
	}
	return p.probeHTTP()
}

n_opencode_Proc_probeHTTP.signature:
// probeHTTP 探活 serve 的 HTTP 端口。
//
// 任一 HTTP 响应（含 401/404）都视为「进程起来且 HTTP 层可应答」；
// 网络层失败（连接拒绝/超时）视为不可用。
func (p *Proc) probeHTTP() bool {
	client := &http.Client{Timeout: time.Second}
	req, err := http.NewRequest(http.MethodGet, fmt.Sprintf("http://127.0.0.1:%d/", p.Port), nil)
	if err != nil {
		return false
	}
	req.SetBasicAuth("opencode", p.Password)
	resp, err := client.Do(req)
	if err != nil {
		return false
	}
	resp.Body.Close()
	return true
}

n_opencode_Profile_Inspect.signature:
func (p *Profile) Inspect(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
	}
	if req.HomeDir == "" {
		return rep, nil
	}
	rulePath := filepath.Join(req.HomeDir, RulesRelFile)
	if _, err := os.Stat(rulePath); errors.Is(err, os.ErrNotExist) {
		rep.Missing = append(rep.Missing, RulesRelFile)
	}
	skillsPath := filepath.Join(req.HomeDir, SkillsRelDir)
	if _, err := os.Stat(skillsPath); errors.Is(err, os.ErrNotExist) {
		rep.Missing = append(rep.Missing, SkillsRelDir)
	}
	return rep, nil
}

n_opencode_Profile_Prepare.signature:
func (p *Profile) Prepare(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep := executor.ProfileReport{
		HomeDir:	req.HomeDir,
		Isolated:	req.Isolated,
	}
	if req.HomeDir == "" {
		return rep, errors.New("Profile.Prepare 缺少 HomeDir")
	}
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 开始", "harness", executor.HarnessOpenCode, "home", req.HomeDir, "isolated", req.Isolated)
	}
	nativeRoot := filepath.Join(req.HomeDir, filepath.Dir(RulesRelFile))
	if err := os.MkdirAll(nativeRoot, 0700); err != nil {
		return rep, fmt.Errorf("创建原生配置目录 %q: %w", nativeRoot, err)
	}

	for _, r := range req.Rules {
		if strings.Contains(r.Name, "..") {
			return rep, fmt.Errorf("规则文件名含非法字符: %q", r.Name)
		}
		var target string
		if strings.HasPrefix(filepath.Clean(r.Name), filepath.Dir(RulesRelFile)) {
			target = filepath.Join(req.HomeDir, filepath.Clean(r.Name))
		} else {
			target = filepath.Join(req.HomeDir, RulesRelFile)
		}
		if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
			return rep, fmt.Errorf("创建规则目录 %q: %w", filepath.Dir(target), err)
		}
		if err := os.WriteFile(target, []byte(r.Content), 0644); err != nil {
			return rep, fmt.Errorf("写原生规则 %q: %w", target, err)
		}
	}

	if len(req.Skills) > 0 {
		targetSkillsDir := filepath.Join(req.HomeDir, SkillsRelDir)
		if err := os.MkdirAll(targetSkillsDir, 0700); err != nil {
			return rep, fmt.Errorf("创建原生技能目录 %q: %w", targetSkillsDir, err)
		}
		for _, s := range req.Skills {
			if strings.Contains(s.Name, "..") {
				return rep, fmt.Errorf("技能文件名含非法字符: %q", s.Name)
			}
			target := filepath.Join(targetSkillsDir, s.Name)
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建技能子目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(s.Content), 0644); err != nil {
				return rep, fmt.Errorf("写原生技能文件 %q: %w", target, err)
			}
		}
	}

	if len(req.TaskOverlay) > 0 {
		overlayRoot := filepath.Join(req.HomeDir, ".handoff", "task-overlay")
		for _, o := range req.TaskOverlay {
			if strings.Contains(o.Name, "..") {
				return rep, fmt.Errorf("overlay 文件名含非法字符: %q", o.Name)
			}
			target := filepath.Join(overlayRoot, filepath.Clean(o.Name))
			if err := os.MkdirAll(filepath.Dir(target), 0700); err != nil {
				return rep, fmt.Errorf("创建 overlay 父目录 %q: %w", filepath.Dir(target), err)
			}
			if err := os.WriteFile(target, []byte(o.Content), 0600); err != nil {
				return rep, fmt.Errorf("写入 overlay 文件 %q: %w", target, err)
			}
		}
	}

	rep.Prepared = true
	if p != nil && p.log != nil {
		p.log.Info("Profile.Prepare 完成", "harness", executor.HarnessOpenCode, "home", req.HomeDir, "prepared", rep.Prepared)
	}
	return rep, nil
}

n_opencode_Profile_Verify.signature:
func (p *Profile) Verify(ctx context.Context, req executor.ProfileReq) (executor.ProfileReport, error) {
	rep, err := p.Inspect(ctx, req)
	if err != nil {
		return rep, err
	}
	if req.HomeDir == "" {
		return rep, nil
	}
	rulePath := filepath.Join(req.HomeDir, RulesRelFile)
	globalOK := false
	if len(req.Rules) == 0 {
		_, err = os.Stat(rulePath)
		globalOK = err == nil
		if err != nil && !errors.Is(err, os.ErrNotExist) {
			if p != nil && p.log != nil {
				p.log.Error("Profile.Verify 读取原生规则失败", "harness", executor.HarnessOpenCode,
					"home", req.HomeDir, "path", rulePath, "cause", err)
			}
			return rep, fmt.Errorf("校验原生规则 %q: %w", rulePath, err)
		}
	} else {
		expected := req.Rules[0].Content
		for _, rule := range req.Rules {
			if filepath.Base(filepath.Clean(rule.Name)) == filepath.Base(RulesRelFile) {
				expected = rule.Content
			}
		}
		got, readErr := os.ReadFile(rulePath)
		if readErr != nil {
			rep.Missing = append(rep.Missing, RulesRelFile)
		} else if !bytes.Equal(got, []byte(expected)) {
			rep.Notes = append(rep.Notes, fmt.Sprintf("规则内容不符: %s", RulesRelFile))
		} else {
			globalOK = true
		}
	}
	overlayOK := true
	for _, overlay := range req.TaskOverlay {
		if strings.Contains(overlay.Name, "..") {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 文件名含非法字符: %s", overlay.Name))
			continue
		}
		rel := filepath.Join(".handoff", "task-overlay", filepath.Clean(overlay.Name))
		got, readErr := os.ReadFile(filepath.Join(req.HomeDir, rel))
		if readErr != nil {
			overlayOK = false
			rep.Missing = append(rep.Missing, rel)
			if p != nil && p.log != nil {
				actualState := "read_error"
				if errors.Is(readErr, os.ErrNotExist) {
					actualState = "missing"
				}
				p.log.Warn("Profile.Verify 任务层内容缺失",
					"harness", executor.HarnessOpenCode, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", actualState,
					"expected_bytes", len(overlay.Content), "actual_bytes", 0, "cause", readErr)
			}
			continue
		}
		if !bytes.Equal(got, []byte(overlay.Content)) {
			overlayOK = false
			rep.Notes = append(rep.Notes, fmt.Sprintf("overlay 内容不符: %s", rel))
			if p != nil && p.log != nil {
				p.log.Warn("Profile.Verify 任务层内容不符",
					"harness", executor.HarnessOpenCode, "home", req.HomeDir,
					"relative_path", rel, "expected_state", "present", "actual_state", "content_mismatch",
					"expected_bytes", len(overlay.Content), "actual_bytes", len(got))
			}
		}
	}
	rep.Verified = globalOK && overlayOK
	if p != nil && p.log != nil {
		p.log.Info("Profile.Verify 完成", "harness", executor.HarnessOpenCode, "home", req.HomeDir, "verified", rep.Verified, "engine_ok", rep.EngineOK)
	}
	return rep, nil
}

n_opencode_StartServe.signature:
// StartServe 经 prochost 拉起 opencode serve 并等待就绪。
//
// 参数：
//   - ctx: 上下文；就绪轮询同样受 ctx 取消影响
//   - repoPath: 任务仓库路径，作为 serve 的工作目录（cwd）
//   - taskID: 任务 id，用于日志与任务目录定位
//   - taskDir: 任务目录（0700），serve.log 与 proc.json 都放这里
//   - configPath: 任务级 opencode 配置路径（Task 10 生成），注入 OPENCODE_CONFIG
//   - env: 额外注入的环境变量（形如 KEY=VALUE，来自 env 文件，已解析已展开）；
//     覆盖顺序见 serveSpec 的 why
//   - log: 本模块日志入口（StartServe 是进程启动点，日志需要显式传入而非走默认）
//
// 返回：
//   - 就绪的 Proc；就绪 = 端口上已有 HTTP 服务响应（含 401：密码校验属后续请求的事，
//     这里只关心「serve 进程起来且 HTTP 层可应答」）
//   - 错误：取端口/密码失败、写 proc.json 失败、拉起 shim 失败、10s 内未就绪
//     （错误信息携带 serve.log 尾部的 serve stderr）
//
// 注意：
//   - 端口选择存在 TOCTOU 竞态（见 freePort），MVP 接受
//   - 就绪超时后自动 Kill 清理残留进程，避免半启动进程占着端口
func StartServe(ctx context.Context, repoPath, taskID, markRoot, taskDir, configPath string, env []string, log *slog.Logger) (*Proc, error) {
	l := log.With("task", taskID)
	port, err := freePort()
	if err != nil {
		l.Error("获取随机空闲端口失败", "cause", err)
		return nil, fmt.Errorf("获取空闲端口: %w", err)
	}
	password, err := randomPassword()
	if err != nil {
		l.Error("生成 serve 密码失败", "cause", err)
		return nil, fmt.Errorf("生成 serve 密码: %w", err)
	}

	if len(env) > 0 {
		keys := make([]string, 0, len(env))
		for _, kv := range env {
			k, _, ok := strings.Cut(kv, "=")
			if !ok {
				continue
			}
			keys = append(keys, k)
			if protectedEnvKeys[k] {
				l.Warn("env 文件定义了 handoff 保留变量，将被 handoff 自身注入覆盖",
					"key", k)
			}
		}
		l.Info("注入 env 变量到 serve 进程", "keys", keys, "count", len(keys))
	}
	bin, err := lookPathOpencode()
	if err != nil {
		l.Error("opencode 未安装", "cause", err)
		return nil, fmt.Errorf("opencode 未安装: %w", err)
	}

	l.Info("解析 opencode 可执行文件", "bin", bin)
	selfExe, err := os.Executable()
	if err != nil {
		l.Error("取 handoff 自身路径失败（shim 无法拉起）", "cause", err)
		return nil, fmt.Errorf("取自身可执行路径: %w", err)
	}
	spec := serveSpec(repoPath, taskDir, configPath, port, password, env)
	spec.TaskID = taskID
	spec.MarkRoot = markRoot
	spec.Argv[0] = bin

	if err := writeProcInfo(taskDir, &procInfo{
		Handle:	prochost.Handle{LockPath: spec.LockPath}, Port: port, Password: password,
	}); err != nil {
		l.Error("写恢复凭据失败", "cause", err)
		return nil, err
	}
	l.Info("启动 opencode serve", "port", port, "bin", bin, "repo", repoPath)
	handle, err := startProcHost(spec, selfExe)
	if err != nil {
		l.Error("拉起 opencode serve 失败", "port", port, "cause", err)
		return nil, err
	}
	p := &Proc{Handle: handle, Port: port, Password: password,
		ServeLogPath:	filepath.Join(taskDir, serveLogFileName)}
	if err := writeProcInfo(taskDir, &procInfo{
		Handle:	handle, Port: port, Password: password,
	}); err != nil {
		l.Warn("回写恢复凭据失败，重启恢复将不可用", "cause", err)
	}
	readyCtx, cancel := context.WithTimeout(ctx, serveReadyTimeout)
	defer cancel()

	start := time.Now()
	for {
		if p.probeHTTP() {
			l.Info("opencode serve 就绪", "port", port, "shim_pid", handle.PID,
				"ready_ms", time.Since(start).Milliseconds())
			return p, nil
		}
		select {
		case <-readyCtx.Done():

			stderrTail := serveLogTail(p.ServeLogPath)

			l.Error("opencode serve 就绪超时", "port", port, "shim_pid", handle.PID, "bin", bin,
				"stderr_tail", stderrTail)
			_ = p.Kill()
			return nil, fmt.Errorf("opencode serve 就绪超时（10s，bin=%s）: %s", bin, stderrTail)
		case <-time.After(serveProbeInterval):
		}
	}
}

n_opencode_WritePermissionConfig.signature:
// WritePermissionConfig 把当前政策快照的精确子集写进 opencode.json。
// 规则：
//   - edit: "allow"（范围内编辑，越界由 external_directory 拦截并走 client）
//   - external_directory: "ask"（越界必须经过 client/人工）
//   - webfetch: "ask"（外访必须经过 client/人工）
//   - bash: bashPermissionRules 的副本，且 "*" 必须强制为 "ask"（无法精确表达「无限制 bash ⊆ 快照」）
func WritePermissionConfig(taskDir, model string, snap executor.PolicySnapshot) (string, error) {
	if strings.TrimSpace(snap.Version) == "" {
		return "", fmt.Errorf("PolicySnapshot.Version 为空")
	}
	if strings.TrimSpace(snap.Scope.Workdir) == "" {
		return "", fmt.Errorf("%w: 空 Workdir", ErrUnrepresentablePolicy)
	}
	configPath := filepath.Join(taskDir, configFileName)
	model = strings.TrimSpace(model)
	if model == "" {
		model = strings.TrimSpace(os.Getenv("HANDOFF_OPENCODE_MODEL"))
	}
	bash := cloneBashRulesAskDefault()
	cfg := opencodeConfig{
		Model:	model,
		Permission: permissionConfig{
			Edit:			"allow",
			Bash:			bash,
			Webfetch:		"ask",
			ExternalDirectory:	"ask",
		},
	}
	raw, err := json.MarshalIndent(cfg, "", "  ")
	if err != nil {
		return configPath, err
	}
	if err := os.WriteFile(configPath, raw, 0o644); err != nil {
		return configPath, fmt.Errorf("写 %s: %w", configPath, err)
	}
	return configPath, nil
}

n_opencode_WriteTaskEnv.signature:
// WriteTaskEnv 在 taskDir 生成 opencode 配置与任务 prompt，返回二者路径。
//
// 参数：
//   - taskDir: 任务工作目录（须已存在，由调用方保证）
//   - taskID: 任务 ID，写入 prompt 标题行
//   - model: 任务级模型覆盖（dispatch --model 折算而来）；空则回退环境变量
//   - planContent: 实现计划全文，原样嵌入 prompt 的「实现计划」段
//   - disciplineBlock: 唯一来自 StartReq 的纪律块正文；taskenv 不自行解析
//   - snap: 政策快照；原生配置必须是 snap 的子集（bash 默认 ask，范围内 edit 为 allow）
//
// 返回：
//   - configPath: 生成的 opencode.json 路径
//   - promptPath: 生成的 prompt.md 路径
//   - err: 渲染或写文件失败
//
// 注意：
//   - 重复调用幂等覆盖：同名文件会被新内容覆盖，调用方可安全重试
//   - 配置经结构体 marshal、prompt 经 text/template 渲染，均非字符串拼接
func WriteTaskEnv(taskDir, taskID, model, planContent, disciplineBlock string, snap executor.PolicySnapshot) (configPath, promptPath string, err error) {
	start := time.Now()
	configPath = filepath.Join(taskDir, configFileName)
	promptPath = filepath.Join(taskDir, promptFileName)
	logger := slog.Default()
	logger.Info("opencode 生成任务环境", "task_dir", taskDir, "task_id", taskID,
		"config", configPath, "prompt", promptPath, "version", snap.Version)
	defer func() {
		if err != nil {
			logger.Error("opencode 生成任务环境失败", "task_dir", taskDir,
				"config", configPath, "prompt", promptPath, "cause", err)
		} else {
			logger.Info("opencode 任务环境已生成", "task_dir", taskDir,
				"config", configPath, "prompt", promptPath,
				"elapsed_ms", time.Since(start).Milliseconds())
		}
	}()

	configPath, err = WritePermissionConfig(taskDir, model, snap)
	if err != nil {
		return configPath, promptPath, err
	}

	promptContent, err := turn.RenderPrompt(taskID, planContent, disciplineBlock)
	if err != nil {
		return configPath, promptPath, err
	}

	if err := os.WriteFile(promptPath, []byte(promptContent), 0o644); err != nil {
		return configPath, promptPath, fmt.Errorf("写 %s: %w", promptPath, err)
	}
	return configPath, promptPath, nil
}

n_opencode_basicAuth.signature:
// basicAuth 构造 HTTP basic auth 的 Base64 编码值（用户名:密码）。
func basicAuth(user, pass string) string {
	return base64.StdEncoding.EncodeToString([]byte(user + ":" + pass))
}

n_opencode_cloneBashRulesAskDefault.signature:
func cloneBashRulesAskDefault() map[string]string {
	out := make(map[string]string, len(bashPermissionRules))
	for k, v := range bashPermissionRules {
		out[k] = v
	}
	out["*"] = "ask"
	return out
}

n_opencode_deliveryFailureHasTicket.signature:
// deliveryFailureHasTicket 判定一次终态决定背后是否有可恢复的持久工单。
// 免审 AutoAllow 由审批 client 直接返回且不建工单（B249），失败不产
// delivery_failed（冻结 #11）。adapter 不得 import permgate，只按既有
// ApprovalDecision.Rule/Status 判：
//   - deny 一定来自有工单的裁决（人工/审批者/升级）
//   - allow 只有 approver / reuse 有工单；safe-command / self-command 以及
//     范围内的自动放行（Rule 为空）都无工单
func deliveryFailureHasTicket(dec executor.ApprovalDecision) bool {
	if dec.Status == executor.ApprovalDeny {
		return true
	}
	return dec.Rule == "approver" || dec.Rule == "reuse"
}

n_opencode_dropCtxCause.signature:
// dropCtxCause 在 ctx 已取消时滤掉「由取消本身派生」的错误。
//
// 为什么需要它：正常关停（Stop/看门狗判死）走的就是取消 ctx，此时在途的
// 连接会返回 context canceled。把它当失败原因上报，FailReason 里就会出现
// 一句与真实故障无关的噪音；而真正的失败原因（连不上、500）必须原样透出（A-7）。
func dropCtxCause(err error, ctx context.Context) error {
	if err == nil || errors.Is(err, ctx.Err()) {
		return nil
	}
	return err
}

n_opencode_ensureTaskTmp.signature:
// ensureTaskTmp creates the task-private directory immediately before a new
// process is started; hot reattach paths must not create it.
func ensureTaskTmp(taskID, tmpDir string, log *slog.Logger) error {
	if err := os.MkdirAll(tmpDir, 0o700); err != nil {
		log.Error("创建任务临时目录失败", "task", taskID, "tmp_dir", tmpDir, "cause", err)
		return err
	}
	log.Info("任务临时目录已就绪", "task", taskID, "tmp_dir", tmpDir)
	return nil
}

n_opencode_frameKind.signature:
// frameKind 把 opencode 的 part 类型归类成帧类型。
//
// 为什么 tool 归到 kindSkip：tool part 的**文本增量**是工具入参的流式拼装，
// 不是给人读的内容；工具调用本身由 mapToolPart 以完整的 tool_call 帧上报，
// 在这里再产一路会出现同一次调用两种形态。
//
// 未知类型一律 kindSkip：opencode 上游加了新 part 类型时，宁可少一种帧，
// 也不要把它猜成正文——猜错就是把非正文内容当模型输出展示。
func frameKind(partType string) partFrameKind {
	switch partType {
	case "text":
		return kindText
	case "reasoning":
		return kindReasoning
	default:
		return kindSkip
	}
}

n_opencode_freePort.signature:
// freePort 找一个随机空闲端口。
//
// 注意：存在 TOCTOU 竞态——端口在 Close 之后、opencode serve 真正监听之前可能被
// 其他进程抢走。MVP 阶段接受该竞态（本机空闲端口被抢概率极低），若真被占用，
// serve 会启动失败退出，StartServe 的就绪轮询超时并以 stderr 尾部暴露原因。
func freePort() (int, error) {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return 0, err
	}
	port := ln.Addr().(*net.TCPAddr).Port
	ln.Close()
	return port, nil
}

n_opencode_lookPathOpencode.signature:
// lookPathOpencode 先走 PATH，失败时尝试常见安装位，避免 launchd 最小 PATH 找不到已安装的二进制。
func lookPathOpencode() (string, error) {
	if bin, err := exec.LookPath("opencode"); err == nil {
		return bin, nil
	} else {
		candidates := make([]string, 0, 4)
		if home, herr := os.UserHomeDir(); herr == nil && home != "" {
			candidates = append(candidates,
				filepath.Join(home, ".opencode", "bin", "opencode"),
				filepath.Join(home, ".local", "bin", "opencode"),
			)
		}
		candidates = append(candidates,
			"/opt/homebrew/bin/opencode",
			"/usr/local/bin/opencode",
		)
		for _, cand := range candidates {
			if _, serr := os.Stat(cand); serr == nil {
				return cand, nil
			}
		}
		return "", err
	}
}

n_opencode_managedTaskTmpEnv.signature:
// managedTaskTmpEnv derives the task-private environment from TaskDir.
//
// The managed entries are appended after user entries at the process seam so
// handoff's isolation values cannot be overridden by task configuration.
func managedTaskTmpEnv(taskDir, taskID string) (string, []string) {
	dataDir := filepath.Dir(filepath.Dir(taskDir))
	if filepath.Base(filepath.Dir(taskDir)) != "tasks" {

		dataDir = filepath.Dir(taskDir)
	}
	tmpDir := executor.TaskTmpDir(dataDir, taskID)
	return tmpDir, []string{
		"TMPDIR=" + tmpDir,
		"GOTMPDIR=" + tmpDir,
		"GOCACHE=" + filepath.Join(tmpDir, "gocache"),
	}
}

n_opencode_matchOption.signature:
// matchOption 把一个答复 token 折算成选项 label。
//
// 参数：
//   - q: 该问
//   - idx: 该问的下标（0 起），用于校验 `问.选` 里的问号
//   - tok: 已 TrimSpace 的单个 token
//
// 返回：命中的 label 与是否命中；未命中时由调用方按 Custom 决定透传或重问
func matchOption(q QuestionInfo, idx int, tok string) (string, bool) {

	qn, on, ok := parseOptionNumber(tok)
	if ok && (qn == 0 || qn == idx+1) && on >= 1 && on <= len(q.Options) {
		return q.Options[on-1].Label, true
	}

	norm := strings.ToLower(strings.TrimSpace(tok))
	for _, o := range q.Options {
		if strings.ToLower(strings.TrimSpace(o.Label)) == norm {
			return o.Label, true
		}
	}
	return "", false
}

n_opencode_newAPI.signature:
// newAPI 是全部构造器的公共骨架。
func newAPI(baseURL, password string, unaryTimeout, sseInitial, sseMax, stableAfter time.Duration) *API {

	dialer := (&net.Dialer{Timeout: 10 * time.Second}).DialContext
	return &API{
		baseURL:	strings.TrimRight(baseURL, "/"),
		password:	password,
		sseClient: &http.Client{
			Transport: &http.Transport{DialContext: dialer},
		},
		httpClient: &http.Client{
			Timeout:	unaryTimeout,
			Transport:	&http.Transport{DialContext: dialer},
		},
		sseInitialBackoff:	sseInitial,
		sseMaxBackoff:		sseMax,
		sseStableAfter:		stableAfter,
	}
}

n_opencode_parseMessageSpend.signature:
// parseMessageSpend 从 message.updated 的 properties 取这条消息的消耗。
//
// 参数：
//   - props: 事件的 properties 原文（info 是完整的 message 对象）
//
// 返回：
//   - e: 账目；Key 取 info.id
//   - ok: 是 assistant 消息、有 id、且至少有一个非零计数时为 true
//
// 两条 opencode 独有的规则（**改错了不会报错，只会显示错的数**）：
//   - **`tokens.reasoning` 与 `tokens.output` 平行，要相加**——与 codex/grok
//     相反（那两家的 reasoning 是 output 的子集）。实抓等式：
//     `total 47071 = input 131 + output 182 + reasoning 294 + cache.read 46464`。
//     不加就少算，而且这里 reasoning 比 output 还大，少算得很显眼。
//   - **全零帧必须跳过**：新建的 assistant 消息 tokens 全是 0，入账会产生一行
//     空账目（虽然随后会被同 id 覆盖，但中间态会让界面闪一下 0）。
func parseMessageSpend(props json.RawMessage) (proto.SpendEntry, bool) {
	var p struct {
		Info struct {
			ID	string	`json:"id"`
			Role	string	`json:"role"`
			Cost	float64	`json:"cost"`
			Tokens	struct {
				Input		int	`json:"input"`
				Output		int	`json:"output"`
				Reasoning	int	`json:"reasoning"`
				Cache		struct {
					Read	int	`json:"read"`
					Write	int	`json:"write"`
				}	`json:"cache"`
			}	`json:"tokens"`
		} `json:"info"`
	}
	if err := json.Unmarshal(props, &p); err != nil {
		return proto.SpendEntry{}, false
	}
	if p.Info.Role != "assistant" || p.Info.ID == "" {
		return proto.SpendEntry{}, false
	}
	tk := p.Info.Tokens
	cached := tk.Cache.Read + tk.Cache.Write
	out := tk.Output + tk.Reasoning
	if tk.Input == 0 && cached == 0 && out == 0 && p.Info.Cost == 0 {
		return proto.SpendEntry{}, false
	}
	e := proto.SpendEntry{
		Key:		p.Info.ID,
		InputTokens:	tk.Input,
		CachedTokens:	cached,
		OutputTokens:	out,
		CostState:	proto.CostUnknown,
	}
	if p.Info.Cost > 0 {
		e.CostTicks = int64(math.Round(p.Info.Cost * 1e10))
		e.CostState = proto.CostReported
	}
	return e, true
}

n_opencode_parseMessageUsage.signature:
// parseMessageUsage 从 message.updated 的 properties 里取模型名与 context 占用。
//
// 参数：
//   - props: 事件的 properties 原文（info 是完整的 message 对象）
//
// 返回：
//   - model: info.modelID；u: context 占用，零值或非 assistant 时为 nil；
//     ok: 报文可解析时为 true
//
// 注意（两条，都会导致界面显示错的数）：
//   - **不能取 `tokens.total`**：实测 `total 47071 = input 131 + output 182 +
//     reasoning 294 + cache.read 46464`，它含产出侧，不是占用。
//     占用是 `input + cache.read + cache.write`。
//   - **零值帧必须跳过**：同一条消息会被推多次，且**新建的 assistant 消息
//     tokens 全是 0**。不跳过的话，界面会在每条新消息开头闪回 0
//     （探针笔记 §3.1）。
func parseMessageUsage(props json.RawMessage) (string, *proto.Usage, bool) {
	var p struct {
		Info struct {
			Role	string	`json:"role"`
			ModelID	string	`json:"modelID"`
			Tokens	struct {
				Input	int	`json:"input"`
				Cache	struct {
					Read	int	`json:"read"`
					Write	int	`json:"write"`
				}	`json:"cache"`
			}	`json:"tokens"`
		} `json:"info"`
	}
	if err := json.Unmarshal(props, &p); err != nil {
		return "", nil, false
	}
	if p.Info.Role != "assistant" {
		return "", nil, true
	}
	tokens := p.Info.Tokens.Input + p.Info.Tokens.Cache.Read + p.Info.Tokens.Cache.Write
	if tokens <= 0 {
		return p.Info.ModelID, nil, true
	}
	return p.Info.ModelID, &proto.Usage{ContextTokens: tokens}, true
}

n_opencode_parseOptionNumber.signature:
// parseOptionNumber 解析 "1.2"（问号.选项号）或 "2"（裸选项号，问号返回 0）。
//
// 返回 ok=false 表示 tok 不是编号形态（含小数点但两侧非数字、或整体非数字）。
func parseOptionNumber(tok string) (questionNo, optionNo int, ok bool) {
	if i := strings.Index(tok, "."); i >= 0 {
		q, err1 := strconv.Atoi(strings.TrimSpace(tok[:i]))
		o, err2 := strconv.Atoi(strings.TrimSpace(tok[i+1:]))
		if err1 != nil || err2 != nil {
			return 0, 0, false
		}
		return q, o, true
	}
	o, err := strconv.Atoi(tok)
	if err != nil {
		return 0, 0, false
	}
	return 0, o, true
}

n_opencode_parseQuestionAnswers.signature:
// parseQuestionAnswers 把协调者的自由文本答复折算成 opencode 要的 answers。
//
// 参数：
//   - qs: 本次请求的问题数组（顺序即 answers 的顺序）
//   - reply: 协调者 `handoff reply --answer` 的原文
//
// 返回：
//   - answers: 按问题顺序排列，每项是该问选中的 label 数组
//   - err: 无法折算（答数不匹配 / 某问答不上且不接受自定义）；此时调用方
//     必须重发工单，**不得**猜一个最接近的选项
//
// 注意：
//   - 分级匹配：编号 `问.选`（每段也接受裸选项号——该段的第 N 个选项）→
//     label 原文（TrimSpace + 大小写归一后精确匹配）→ 该问 Custom 时原文透传
//   - 多问用分号分隔，多选用逗号分隔；两级分隔符不重叠，故可先分号后逗号
//   - 猜错一个选项的代价是模型按错误前提继续干活，重问的代价只是协调者多按
//     一次——错误方向必须选后者（与 B6「误升级好过漏放行」同一取舍）
func parseQuestionAnswers(qs []QuestionInfo, reply string) ([][]string, error) {
	if len(qs) == 0 {
		return nil, fmt.Errorf("本次请求没有问题，无法折算答复")
	}
	segs := splitAnswerSegments(reply, len(qs))
	if len(segs) != len(qs) {
		return nil, fmt.Errorf("有 %d 道问题但只解析出 %d 段答复，请按 \"1.2; 2.1\" 的形式按顺序作答",
			len(qs), len(segs))
	}
	answers := make([][]string, len(qs))
	for i, q := range qs {
		seg := strings.TrimSpace(segs[i])
		if seg == "" {
			return nil, fmt.Errorf("问题 %d 没有对应的答复", i+1)
		}
		var picked []string
		tokens := []string{seg}
		if q.Multiple {
			tokens = splitAndTrim(seg, ",")
		}
		for _, tok := range tokens {
			label, ok := matchOption(q, i, tok)
			if !ok {
				if !q.Custom {
					return nil, fmt.Errorf("问题 %d 的答复 %q 既不是编号也不是选项原文，且该问不接受自定义答案；请填编号（如 %d.1）或选项原文",
						i+1, tok, i+1)
				}
				label = tok
			}
			picked = append(picked, label)
		}
		answers[i] = picked
	}
	return answers, nil
}

n_opencode_partKey.signature:
// partKey 生成 part 累积对账的键：messageID+partID 唯一标识一个 part
// （真实流中 part id 全局唯一，双 id 是为了对账键可读可查）。
func partKey(msgID, partID string) string {
	return msgID + "\x00" + partID
}

n_opencode_probeServeReloadsConfig.signature:
func probeServeReloadsConfig(ctx context.Context, r *runState) (bool, error) {

	if r.reloadProbe != nil {
		return r.reloadProbe(ctx)
	}
	return false, nil
}

n_opencode_procHandle_LogTail.signature:
// LogTail 返回脱敏后的 serve.log 尾部。
//
// 为什么必须脱敏（A-12）：这段尾部会进 Result.FailReason（落事件库）和
// agentd.log，而它的内容完全由 opencode 决定——启动横幅、panic 时的环境转储、
// 带认证的 URL 都可能回显 OPENCODE_SERVER_PASSWORD。密码就在手边，抹掉的成本
// 为零，赌 opencode 每个版本都不打印才是不该冒的险。
func (h procHandle) LogTail() string {
	tail := serveLogTail(h.p.ServeLogPath)
	if h.p.Password == "" {
		return tail
	}
	return strings.ReplaceAll(tail, h.p.Password, "***")
}

n_opencode_randomPassword.signature:
// randomPassword 生成 32 位十六进制随机串，用作 OPENCODE_SERVER_PASSWORD。
func randomPassword() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

n_opencode_readProcInfo.signature:
// readProcInfo 读取任务目录的 serve 连接凭据。
//
// 返回：
//   - 文件缺失/损坏/字段不完整时返回错误（调用方据此判「无法重建订阅」）
func readProcInfo(taskDir string) (*procInfo, error) {
	b, err := os.ReadFile(filepath.Join(taskDir, procInfoFileName))
	if err != nil {
		return nil, fmt.Errorf("读恢复凭据 %s: %w", procInfoFileName, err)
	}
	var pi procInfo
	if err := json.Unmarshal(b, &pi); err != nil {
		return nil, fmt.Errorf("解析恢复凭据 %s: %w", procInfoFileName, err)
	}

	if pi.Handle.LockPath == "" || pi.Port == 0 || pi.Password == "" {
		return nil, fmt.Errorf("恢复凭据 %s 字段不完整", procInfoFileName)
	}
	return &pi, nil
}

n_opencode_reconcileTurnEnded.signature:
// reconcileTurnEnded 判定取回的会话尾部消息是否真的意味着「回合已结束」。
//
// 为什么不能只靠 CompletedMS：opencode 一个用户回合会产多条 assistant 消息，
// 工具调用各自成条、各自带 completed。只凭「最后一条 assistant 的 CompletedMS
// != 0」会把一条纯工具消息误判成回合终态——executor 死亡/崩溃后会话冻结在
// 工具消息上，补一条假终态会把正常任务主动推进到 waiting_answer，比 B38 原始
// 症状（冻死）更糟。
//
// 判据按行逐条判定、命中即停（真机数据见各行的注释出处）：
//
//	1  CompletedMS == 0                         → 未结束（消息未 finalize：在飞或冻结）
//	2  Finish == "stop"                         → 已结束（自然结束，无 tool part）
//	3  ErrorName == "MessageAbortedError"       → 已结束（会话被 abort 而终）
//	4  ToolStatus == "error"                    → 已结束（工具被拒/报错而终）
//	5  ToolStatus == "completed"                → 未结束（真·回合中途冻结）
//	6  兜底（无 tool、无 error、finish 缺席/其它）→ 已结束（窄兜底，见下）
//
// row2 为什么成立（Finish=="stop" ⇒ 回合结束）：stop 是 opencode 的自然结束标记——
// 模型把话说完、本轮不再有工具调用，消息的 finish 就是 "stop"。实测该形态消息
// 的 parts 为 step-start/text/step-finish（无 tool part），是「回合到此为止」的
// 最直接信号。与实时路径 mapIdle 的判定口径一致（文本完整、无续接意图即分类收尾）。
//
// row4 为什么成立（工具 error ⇒ 回合结束）：本会话 14 条带 state.status=error
// 工具 part 的消息 14/14 后面紧跟的都是 user 消息（或就是会话尾），零反例——
// 「工具报错模型会自己重试、回合不结束」的担心被数据否掉。更重要的代码佐证：
// 实时路径 adapter.go:1236-1241 早就把「回合因权限被拒而终止」当作回合结束并转成
// question 唤醒协调者（rejectedTurnQuestion，adapter.go:482-488）——row4 不是
// 新发明，是让对账口径与实时路径对齐。
//
// row6 为什么是窄兜底且判已结束：真实 payload 里 completed 的消息几乎总带 finish
// （456 条：tool-calls 452 / unknown 2 / 缺席 2，缺席那两条一条是 abort、一条是
// 在飞）。落进 row6 的是 finish="unknown"（本会话 2 条，均为真实回合终态、无 tool
// part）与缺 finish 的经典终态——它们补发是对的。row6 不是主路径，但缺失它会让
// 老版本/异常形态的终态永远补不上，故判已结束。
//
// 返回：回合是否已结束，以及命中的判据行（进日志，供线上判定回溯）。
func reconcileTurnEnded(msg *SessionMessage) (bool, string) {
	if msg.CompletedMS == 0 {
		return false, "unfinalized"
	}
	if msg.Finish == "stop" {
		return true, "stop"
	}
	if msg.ErrorName == "MessageAbortedError" {
		return true, "aborted"
	}
	if msg.ToolStatus == "error" {
		return true, "tool_error"
	}
	if msg.ToolStatus == "completed" {
		return false, "frozen_tool_tail"
	}
	return true, "fallback_terminal"
}

n_opencode_rejectedTurnQuestion.signature:
// rejectedTurnQuestion 组装「回合因权限被拒而终止」交给协调者的提问文本。
//
// why（必须是 question 而不是 result/failed）：任务没失败也没完成，它只是停在
// 半路等人指路。question 让任务进 waiting_answer，协调者可直接续发指令（换个
// 方式做/跳过这步/收尾提交），会话上下文完整保留——这与 fallbackClassify
// 「流程不卡死」的取向一致。
func rejectedTurnQuestion(rejected []string) string {
	return "上一步操作因权限被拒而终止了本回合（executor 未产出任何文本）：\n  - " +
		strings.Join(rejected, "\n  - ") +
		"\n\n请给出下一步指令：换用其他方式完成该步骤 / 跳过该步骤继续 / 直接收尾提交。"
}

n_opencode_renderQuestionTicket.signature:
// renderQuestionTicket 把一组问题渲染成一张工单的文本。
//
// 参数：qs 为 opencode question 请求里的问题数组（顺序即应答顺序）
//
// 返回：多段文本，每问一段，选项按 `<问号>.<选项号>` 编号
//
// 注意：
//   - 编号跨问连续编排（1.1/1.2/2.1），协调者据此作答，parseQuestionAnswers
//     按同一套编号回读——两者是同一契约的两半，改一个必须改另一个
//   - 无选项的问题不编号，提示直接作答：opencode 允许问题只有正文
func renderQuestionTicket(qs []QuestionInfo) string {
	var b strings.Builder
	b.WriteString("executor 需要你决策：\n")
	for i, q := range qs {
		fmt.Fprintf(&b, "\n问题 %d", i+1)
		if h := strings.TrimSpace(q.Header); h != "" {
			fmt.Fprintf(&b, "（%s）", h)
		}
		b.WriteString("：")
		b.WriteString(strings.TrimSpace(q.Question))
		b.WriteString("\n")
		if len(q.Options) == 0 {
			b.WriteString("  （无候选项，直接作答）\n")
			continue
		}
		for j, o := range q.Options {
			fmt.Fprintf(&b, "  %d.%d %s", i+1, j+1, o.Label)
			if d := strings.TrimSpace(o.Description); d != "" {
				b.WriteString(" — " + d)
			}
			b.WriteString("\n")
		}
		var marks []string
		if q.Multiple {
			marks = append(marks, "可多选（逗号分隔）")
		}
		if q.Custom {
			marks = append(marks, "可自定义（直接写答案）")
		}
		if len(marks) > 0 {
			b.WriteString("  [" + strings.Join(marks, "；") + "]\n")
		}
	}
	b.WriteString("\n用 handoff reply --answer 作答，填编号（如 1.2）或选项原文；" +
		"多问按顺序用分号分隔（如 \"1.2; 2.1\"）。")
	return b.String()
}

n_opencode_resumeNote.signature:
// resumeNote 拼恢复结果的一句话结论（进 ResumeOutcome.Note 供 manager 转播）。
func resumeNote(mode, sessionID string) string {
	switch mode {
	case executor.ResumeModeReattach:
		return "executor 仍存活，已重连事件流"
	case executor.ResumeModeCold:
		return "已从磁盘载入原会话 " + sessionID + "，上下文完整"
	case executor.ResumeModeFresh:
		return "原会话已不可载入，已新开会话 " + sessionID + "，上下文从下一条指令开始"
	}
	return "已恢复"
}

n_opencode_runState_appendRender.signature:
// appendRender 把消息文本增量追加进 render.log（handoff attach 实况可见）。
//
// 薄封装：实现在 turn 共享包（B2/B3 两个 adapter 同构逻辑），本方法保留
// 调用点已有的 taskDir 上下文（renderPath 由 newRun 按 taskDir 推导）。
func (r *runState) appendRender(delta string) error {
	return turn.AppendRender(r.renderPath, delta)
}

n_opencode_runState_cancelPendingIdle.signature:
// cancelPendingIdle 停掉在途的 idle 去抖定时器并作废候选（自行加锁，
// 供订阅结束等 turnMu 未持有的路径调用）。
func (r *runState) cancelPendingIdle() {
	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	r.idleGen++
	if r.idleTimer != nil {
		r.idleTimer.Stop()
		r.idleTimer = nil
	}
}

n_opencode_runState_captureStartCommit.signature:
// captureStartCommit 记录任务起点 commit：git 兜底分类（fallbackClassify）用
// 「是否有新提交」裁决的基线；非 git 仓库或查询失败时留空，兜底一律按无新提交处理。
//
// 由 startRun 与 Resume 复用：两者都需在订阅启动前定下本回合的 git 基线。
func (r *runState) captureStartCommit(a *Adapter) {
	if out, err := exec.Command("git", "-C", r.repoPath, "rev-parse", "HEAD").Output(); err != nil {
		a.log.Warn("捕获任务起点 commit 失败，兜底按无新提交处理",
			"task", r.taskID, "repo", r.repoPath, "cause", err)
	} else {
		r.startCommit = strings.TrimSpace(string(out))
	}
}

n_opencode_runState_clearPendingQuestion.signature:
// clearPendingQuestion 清除挂起提问（应答成功后调用）。
func (r *runState) clearPendingQuestion() {
	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	r.pendingQuestionID = ""
	r.pendingQuestions = nil
}

n_opencode_runState_clearTurn.signature:
// clearTurn 清空回合累积（回合分类终结时调用）。
//
// partTypes/userMsgs 不清空：它们是会话级事实（part 类型、user 消息 id 全会话
// 唯一），保留才能保证回合边界之后到达的 reasoning 增量与重放的 user 文本 part
// 永不混入下一回合（A-4）。pendingDelta 同样保留：类型未揭晓的暂存增量跨回合
// 边界仍可能被 part.updated 认领。
func (r *runState) clearTurn() {
	r.turnOrder = nil
	r.partSeen = make(map[string]string)
	r.partSnap = make(map[string]bool)
}

n_opencode_runState_closeEvents.signature:
// closeEvents 关闭事件通道（只由 subscribeLoop 的 defer 调用，关闭权唯一）。
// 与 emit 共用 emitMu：置位 evClosed 后任何在途的 emit 都会静默丢弃，
// 保证 idle 定时器 goroutine 的迟到投递不会写已关闭通道。
func (r *runState) closeEvents() {
	r.emitMu.Lock()
	defer r.emitMu.Unlock()
	if r.evClosed {
		return
	}
	r.evClosed = true
	close(r.evCh)
}

n_opencode_runState_noteRejected.signature:
// noteRejected 登记一次已送达的权限拒绝，供 mapIdle 识别「被拒终止的空回合」。
//
// 参数：
//   - permID: 被拒的权限 id（描述从 permText 反查，查不到时退化为 id 本身）
func (r *runState) noteRejected(permID string) {
	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	desc := r.permText[permID]
	if strings.TrimSpace(desc) == "" {
		desc = "权限 " + permID
	}
	r.turnRejected = append(r.turnRejected, desc)
}

n_opencode_runState_subscribeLoop.signature:
// subscribeLoop 是单任务的事件流主循环（唯一持有 evCh 关闭权的 goroutine）：
// 订阅 SSE → mapEvent 逐条映射产出 AdapterEvent；订阅退出后按退出原因
// （serve 死亡 / 流不可恢复）产出 failed 结果，随后关闭事件通道。
func (r *runState) subscribeLoop(a *Adapter) {
	defer func() {

		r.cancelPendingIdle()
		r.closeOnce.Do(r.closeEvents)

		select {
		case <-r.stopCh:
		default:
			a.drop(r.taskID)
		}
		a.log.Info("opencode 事件流订阅退出", "task", r.taskID)
	}()
	err := r.api.SubscribeEvents(r.runCtx, func(raw json.RawMessage) {
		a.mapEvent(r, raw)
	}, func() {

		a.log.Warn("SSE 断连已恢复：断连间隙的权限请求可能丢失（/event 无重放语义），"+
			"若任务卡在等待决策请 handoff attach 查看或 handoff resume --force 收口",
			"task", r.taskID, "session", r.session)
		go a.reconcileAfterRecovery(context.Background(), r.taskID, "reconnect")
	})
	select {
	case <-r.stopCh:
		return
	default:
	}
	if !r.handle.Alive() {

		tail := turn.TailRunes(r.handle.LogTail(), 200)
		a.log.Error("opencode serve 已退出", "task", r.taskID, "stderr_tail", tail)
		a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
			OK:	false, SessionID: r.session,
			FailReason:	"opencode serve 已退出: " + tail,
		}})

		if kerr := r.handle.Kill(); kerr != nil {
			a.log.Warn("serve 死亡后回收执行者进程失败", "task", r.taskID, "cause", kerr)
		}
		return
	}
	a.log.Warn("opencode 事件流意外中断，按失败结束回合", "task", r.taskID, "cause", err)
	a.emit(r, executor.AdapterEvent{Type: "result", Result: &executor.Result{
		OK:	false, SessionID: r.session,
		FailReason:	"opencode 事件流意外中断: " + turn.TailRunes(fmt.Sprint(err), 200),
	}})
}

n_opencode_runState_takeAskedViaTool.signature:
// takeAskedViaTool 取走「本回合已通过 question 工具提问」的标记（读后即清）。
//
// 返回：本回合是否已通过工具问过协调者
//
// 为什么必须取走式：标记的生命周期是一个回合。常驻会让下一回合的真 trailer
// 提问被误抑制，任务停在 running 无人知晓——那正是 B49 要消灭的形态。
//
// 注意：调用方须已持 turnMu（mapIdle 的既有契约）
func (r *runState) takeAskedViaTool() bool {
	asked := r.askedViaTool
	r.askedViaTool = false
	return asked
}

n_opencode_runState_takePendingQuestionS.signature:
// takePendingQuestionSnapshot 读一份挂起提问的快照（不清除）。
//
// 返回：请求 id 与问题结构；无挂起请求时 id 为空串
//
// 为什么只读不清：答复可能折算失败或被服务端拒绝，那两条路都要重发工单并
// **保留**挂起请求——提前清掉，协调者的下一次答复就无处可投，任务重新死锁。
// 清除只发生在应答成功之后（见 replyPendingQuestion）。
func (r *runState) takePendingQuestionSnapshot() (string, []QuestionInfo) {
	r.turnMu.Lock()
	defer r.turnMu.Unlock()
	return r.pendingQuestionID, r.pendingQuestions
}

n_opencode_runState_takeTurnRejected.signature:
// takeTurnRejected 取出并清空本回合的拒绝记录（调用方须已持 turnMu）。
func (r *runState) takeTurnRejected() []string {
	rejected := r.turnRejected
	r.turnRejected = nil
	return rejected
}

n_opencode_runState_turnText.signature:
// turnText 按 part 首见顺序拼出当前回合的完整文本。
//
// 为什么不维护一个累加字符串：服务端会修订同一 part 的快照，累加字符串没法
// 撤销已写入的旧值（A-6）；按 part 存当前值再拼接，修订天然是覆盖。
func (r *runState) turnText() string {
	var b strings.Builder
	for _, key := range r.turnOrder {
		b.WriteString(r.partSeen[key])
	}
	return b.String()
}

n_opencode_serveLogTail.signature:
// serveLogTail 读 serve.log 尾部最多 500 字节，供就绪超时/死亡诊断；文件未
// 创建（serve 根本没跑起来）或已被清理时返回空串。
//
// why（Seek 到尾部而非 os.ReadFile 整读）：serve.log 由 serve 写满任务全程且
// 无轮转，而本函数的调用时机恰是 serve 死亡/就绪超时——最不该再分配几百 MB 的
// 时刻。整读一份 100MiB 日志只为取末尾 500 字节，是把诊断动作变成第二次故障。
func serveLogTail(serveLogPath string) string {
	f, err := os.Open(serveLogPath)
	if err != nil {
		return ""
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return ""
	}
	offset := fi.Size() - serveLogTailBytes
	if offset < 0 {
		offset = 0
	}
	if _, err := f.Seek(offset, io.SeekStart); err != nil {
		return ""
	}
	b, err := io.ReadAll(io.LimitReader(f, serveLogTailBytes))
	if err != nil {
		return ""
	}
	return tail(string(b), 500)
}

n_opencode_serveSpec.signature:
// serveSpec 组 opencode serve 的启动描述。
//
// 为什么密码走 Env 而不是 argv：进程 argv 本机全局可读（/proc/<pid>/cmdline），
// 密码进 argv 等于对同机任何用户公开。旧实现靠「密码写进 0600 启动脚本、
// 只把脚本路径给 tmux」达成同样效果；换成 prochost 后由 Spec.Env 承担
// （spec.json 同样 0600）。TestServeSpecPutsPasswordInEnvNotArgv 钉死这条。
//
// 为什么 handoff 注入的变量排在 env 文件之后：切片靠后者覆盖前者，
// 用户 env 文件里若定义了 OPENCODE_* 保留键，必须被 handoff 自己的值压过
// （B19 protectedEnvKeys 纪律，调用方另有 Warn 提示）。
func serveSpec(repoPath, taskDir, configPath string, port int, password string, env []string) prochost.Spec {
	serveLog := filepath.Join(taskDir, serveLogFileName)
	full := append(os.Environ(), env...)
	full = append(full,
		"OPENCODE_SERVER_PASSWORD="+password,
		"OPENCODE_CONFIG="+configPath,
	)
	return prochost.Spec{
		Argv:		[]string{"opencode", "serve", "--port", strconv.Itoa(port), "--hostname", "127.0.0.1"},
		Dir:		repoPath,
		Env:		full,
		Stdout:		serveLog,
		Stderr:		serveLog,
		LockPath:	filepath.Join(taskDir, lockFileName),
		InfoPath:	filepath.Join(taskDir, procInfoFileName),
		Sentinel:	true,
	}
}

n_opencode_splitAndTrim.signature:
// splitAndTrim 按 sep 切分并去掉每段首尾空白，丢弃空段。
//
// 中文全角分隔符（；、）一并接受：协调者在中文输入法下很容易打出全角，
// 因此而重问是纯粹的摩擦。
func splitAndTrim(s, sep string) []string {
	switch sep {
	case ";":
		s = strings.ReplaceAll(s, "；", ";")
	case ",":
		s = strings.ReplaceAll(s, "，", ",")
	}
	var out []string
	for _, p := range strings.Split(s, sep) {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

n_opencode_splitAnswerSegments.signature:
// splitAnswerSegments 把答复切成「每问一段」。
//
// 单问时整段就是一段（分号可能是答案本身的一部分，不能切）；多问时按分号切。
func splitAnswerSegments(reply string, questionCount int) []string {
	if questionCount == 1 {
		return []string{strings.TrimSpace(reply)}
	}
	return splitAndTrim(reply, ";")
}

n_opencode_tail.signature:
// tail 返回字符串尾部最多 n 个字符（按字节截断，日志用，不追求多字节安全——
// 截断点切在中间也无碍诊断）。
func tail(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[len(s)-n:]
}

n_opencode_toolDetail.signature:
// toolDetail 从工具入参里取一句给人看的凭据（进 TimingEntry.Detail）。
//
// 优先 input.command（命令类工具），没有就用整个 input 的紧凑 JSON。
// 截断由 Segmenter 按 DetailRunes 负责，这里不截——两处都截会截两次。
func toolDetail(input json.RawMessage) string {
	var in struct {
		Command string `json:"command"`
	}
	if len(input) > 0 && json.Unmarshal(input, &in) == nil && in.Command != "" {
		return in.Command
	}
	return string(input)
}

n_opencode_toolInputReady.signature:
// toolInputReady 判断 state.input 是否已经带有实际入参。
// opencode 的 pending 事件稳定地带空对象；空对象不是有效凭据，不能据此写死
// tool_call 帧或 TimingEntry.Detail。state.input 契约上是对象，非对象值保守地视为
// 已有内容，终态回落由 mapToolPart 的 terminal 分支负责。
func toolInputReady(input json.RawMessage) bool {
	var fields map[string]json.RawMessage
	if json.Unmarshal(input, &fields) == nil {
		return len(fields) > 0
	}
	trimmed := strings.TrimSpace(string(input))
	return trimmed != "" && trimmed != "null"
}

n_opencode_toolPartKey.signature:
// toolPartKey 取工具调用的配对键：优先 callID，缺失时回落 part.id。
//
// 为什么优先 callID：permission.asked 事件里的 tool.callID 用的就是它
// （testdata/spike5-events.jsonl 第 289 行），拿同一个键才对得上审批与调用。
func toolPartKey(callID, partID string) string {
	if callID != "" {
		return callID
	}
	return partID
}

n_opencode_toolResultStatus.signature:
// toolResultStatus 把 opencode 的工具状态映射成帧上的 status。
//
// 返回 ok=false 表示**不是终态**（pending/running/未知）：不产 tool_result 帧、
// 不收工具段。error 是真实存在的终态——权限被拒会终结回合并只留 error 状态的
// tool part（见 mapIdle 的注释）。
//
// 不认识的状态一律按非终态处置，理由的不对称性与 grok 版一致：把非终态当终态
// 会提前收段并留下一个永远配不上的 start；把终态当非终态只是少一条条目，
// 由聚合层的 Partial 如实标出。
func toolResultStatus(status string) (string, bool) {
	switch status {
	case "completed":
		return "ok", true
	case "error":
		return "error", true
	default:
		return "", false
	}
}

n_opencode_writeProcInfo.signature:
// writeProcInfo 把 serve 连接凭据写入任务目录 proc.json（0600）。
//
// why（必须持久化）：agentd 重启后内存中的 Proc（端口/密码）丢失，而 shim 内的
// serve 进程独立存活；RecoverOnStartup 凭此文件探活并重建 SSE 订阅（spec §8）。
// 写失败不阻断启动（adapter.Start 只 Warn），缺失时该任务重启后按「执行器已不在」
// 转 failed 交协调者——保守胜于静默丢事件。
func writeProcInfo(taskDir string, pi *procInfo) error {
	b, err := json.Marshal(pi)
	if err != nil {
		return fmt.Errorf("序列化恢复凭据: %w", err)
	}
	if err := os.WriteFile(filepath.Join(taskDir, procInfoFileName), b, 0o600); err != nil {
		return fmt.Errorf("写恢复凭据 %s: %w", procInfoFileName, err)
	}
	return nil
}

n_orchestration_AcquireDataDirLock.signature:
// AcquireDataDirLock 对 <dataDir>/agentd.lock 取非阻塞独占锁。
//
// 参数：
//   - dataDir: 数据目录，调用方须保证它已存在（agentd 侧由 os.MkdirAll 保证）
//   - log: 日志入口，nil 时退回 slog.Default()
//
// 返回：
//   - 持有锁的句柄，调用方须一直持有到进程结束
//   - error: 已被另一个 agentd 占用时，错误文本是一段完整的可行动指引
//     （含 dataDir 与 `handoff status`），调用方直接原样返回即可，不要再包一层
//
// 注意：
//   - **必须在 store.Open 之前调用**。别指望端口冲突挡住第二个 agentd——
//     ListenAndServe 是 agentd 启动流程的最后一条语句，在它之前 RecoverOnStartup
//     已经对在役 agentd 的活执行器重建了订阅并写入状态迁移；SQLite 开了 WAL
//     也不拦多进程打开。破坏发生在撞端口之前
func AcquireDataDirLock(dataDir string, log *slog.Logger) (*DataDirLock, error) {
	if log == nil {
		log = slog.Default()
	}
	path := filepath.Join(dataDir, lockFileName)
	if !prochost.LockSupported() {

		log.Warn("本平台不支持文件锁，agentd 单实例保护未生效", "data_dir", dataDir)
	}
	l, err := prochost.AcquireLock(path)
	if err != nil {
		if errors.Is(err, prochost.ErrLockHeld) {
			log.Error("数据目录已被另一个 agentd 占用，拒绝启动",
				"data_dir", dataDir, "path", path)
			return nil, fmt.Errorf(lockHeldMsg, dataDir)
		}

		log.Error("获取单实例锁失败", "path", path, "cause", err)
		return nil, err
	}
	if prochost.LockSupported() {
		log.Info("已取得数据目录单实例锁", "data_dir", dataDir, "path", path)
	} else {
		log.Info("数据目录锁文件已就位，但本平台不提供互斥保护",
			"data_dir", dataDir, "path", path)
	}
	return &DataDirLock{l: l, log: log}, nil
}

n_orchestration_ActiveLeaf.signature:
// ActiveLeaf 返回现役缓存叶子：executor.TaskTmpDir(dataDir, taskID)。
func ActiveLeaf(dataDir, taskID string) string {
	return executor.TaskTmpDir(dataDir, taskID)
}

n_orchestration_ActiveLeafOccupied.signature:
// ActiveLeafOccupied 报告同一 id8 上是否存在「自己以外」的非终态任务。
// 自己即使仍是 waiting_review，也不算占用者——收口时它正在进入终态。
// 不用 ActiveTasksByWorkDir：那是 workdir 占用，不是短号占用。
func ActiveLeafOccupied(tasks []proto.Task, selfID string) bool {
	self8 := ID8(selfID)
	if self8 == "" {
		return false
	}
	for _, t := range tasks {
		if t.ID == selfID {
			continue
		}
		if t.State.IsTerminal() {
			continue
		}
		if ID8(t.ID) == self8 {
			return true
		}
	}
	return false
}

n_orchestration_Approver_BindOneShot.signature:
// BindOneShot 绑定一次性调用能力实现。
func (a *Approver) BindOneShot(shot executor.OneShot) {
	a.shot = shot
}

n_orchestration_Approver_Decide.signature:
// Decide 对一次权限请求做裁决：组装 prompt → 调用 one-shot 执行者 → 解析 JSON。
//
// 参数：
//   - ctx: 上层上下文；本方法在其上叠加 a.timeout 作为裁决截止
//   - permission: 权限请求原文（如 "Bash: rm -rf node_modules"）
//   - taskSummary: 任务摘要（写入 prompt 给模型上下文）
//
// 返回：
//   - ApproverDecision，见该类型注释（fail-closed：一切无法干净裁决的输入
//     都返回 Approve=false + Err 非 nil）
func (a *Approver) Decide(ctx context.Context, permission, taskSummary string) ApproverDecision {
	start := time.Now()
	nonce := randNonce()
	if nonce == "" {
		a.log.Warn("生成裁决 nonce 失败，本次裁决不做防伪校验", "executor", a.executorName)
	}
	a.log.Info("审批者开始裁决", "permission", agentd.TruncateRunes(permission, 80),
		"executor", a.executorName, "model", a.model, "nonce", nonce)
	prompt := fmt.Sprintf(approverPromptTemplate, taskSummary, permission, nonce, nonce)
	if a.shot == nil {
		d := ApproverDecision{Approve: false, ElapsedMS: time.Since(start).Milliseconds(), Err: fmt.Errorf("审批者未绑定 OneShot")}
		a.log.Error("审批者裁决缺少 OneShot", "executor", a.executorName)
		return d
	}
	var env []string
	if a.env != nil {
		extra, err := a.env.For(a.executorName)
		if err != nil {
			a.log.Error("审批者 env 文件解析失败，本次裁决升级人工协调者",
				"executor", a.executorName, "cause", err)
			return ApproverDecision{Approve: false, ElapsedMS: time.Since(start).Milliseconds(), Err: fmt.Errorf("解析审批者 env 文件: %w", err)}
		}
		if len(extra) > 0 {
			env = append(os.Environ(), extra...)
		}
	}
	req := executor.OneShotReq{Prompt: prompt, Model: a.model, Env: env, Limits: executor.OneShotLimits{}}
	if a.executorName == executor.HarnessGrok {
		req.Limits.Effort = executor.EffortLow
	}
	ctx, cancel := context.WithTimeout(ctx, a.timeout)
	defer cancel()
	reply, err := a.shot.Invoke(ctx, req)
	elapsed := time.Since(start).Milliseconds()
	if err != nil {

		d := ApproverDecision{Approve: false, ElapsedMS: elapsed, Err: err}
		a.log.Error("审批者裁决失败", "permission", agentd.TruncateRunes(permission, 80),
			"cause", err, "output", agentd.TruncateRunes(reply.Text, 200), "elapsed_ms", elapsed)
		return d
	}
	d := parseDecision(reply.Text, nonce, elapsed)
	if d.Err != nil && strings.Contains(d.Err.Error(), "nonce 不匹配") {
		a.log.Error("审批者裁决 nonce 校验失败，按升级处理", "task_summary", agentd.TruncateRunes(taskSummary, 60),
			"permission", agentd.TruncateRunes(permission, 80), "cause", d.Err)
	}
	a.log.Info("审批者裁决完成", "decision", decisionLabel(d), "reason", agentd.TruncateRunes(d.Reason, 80),
		"elapsed_ms", elapsed)
	return d
}

n_orchestration_DataDirLock_Release.signature:
// Release 释放锁。
//
// 生产侧可有可无——进程退出内核即释放；保留它是为了让测试能验证「释放后可重新
// 获取」，以及 defer 的习惯写法。重复调用是安全的（第二次直接返回 nil）。
func (l *DataDirLock) Release() error {
	if l == nil || l.l == nil {
		return nil
	}
	err := l.l.Release()
	if err != nil {
		l.log.Warn("释放数据目录单实例锁失败", "cause", err)
		return err
	}
	l.log.Debug("已释放数据目录单实例锁")
	return nil
}

n_orchestration_HashPolicyVersion.signature:
// HashPolicyVersion computes a stable version for policy content. The field
// set and sorted inputs are retained at this assembly-side location so policy
// snapshots keep their existing physical hash contract.
func HashPolicyVersion(blacklist []string, approverOn bool, safeIDs []string, scope executor.ApprovalScope) string {
	bl := append([]string(nil), blacklist...)
	sort.Strings(bl)
	ids := append([]string(nil), safeIDs...)
	sort.Strings(ids)
	type payload struct {
		Blacklist	[]string	`json:"blacklist"`
		ApproverOn	bool		`json:"approver_on"`
		Safe		[]string	`json:"safe"`
		Workdir		string		`json:"workdir"`
		TaskDir		string		`json:"task_dir"`
		TaskTmp		string		`json:"task_tmp"`
	}
	b, _ := json.Marshal(payload{Blacklist: bl, ApproverOn: approverOn, Safe: ids,
		Workdir:	scope.Workdir, TaskDir: scope.TaskDir, TaskTmp: scope.TaskTmpDir})
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

n_orchestration_ID8.signature:
// ID8 返回任务短号（前 8 字符，短于 8 则全取）。
func ID8(taskID string) string {
	if len(taskID) > 8 {
		return taskID[:8]
	}
	return taskID
}

n_orchestration_IsTmpRoot.signature:
// IsTmpRoot 报告 path 是否是 DataDir/tmp 根。
func IsTmpRoot(dataDir, path string) bool {
	return PathEqual(path, TmpRoot(dataDir))
}

n_orchestration_LegacyLeaf.signature:
// LegacyLeaf 返回遗留缓存叶子：dataDir/tasks/<完整 taskID>/tmp。
func LegacyLeaf(dataDir, taskID string) string {
	return filepath.Join(dataDir, "tasks", taskID, "tmp")
}

n_orchestration_Manager_AssembleResultRe.signature:
// AssembleResultRef 在审阅现场组装结果引用。commit 取 rev-parse；失败则空串，不编造。
func (m *Manager) AssembleResultRef(ctx context.Context, task *proto.Task, repo, headRev string) (workspace.ResultRef, error) {
	commit := ""
	if out, _, err := agentd.GitProbe(ctx, repo, "rev-parse", headRev); err == nil {
		got := strings.TrimSpace(out)
		if workspace.IsCommitSHA(got) {
			commit = got
		} else {
			m.log.Warn("rev-parse 不是 40 位小写 hex，commit 留空", "repo", repo, "head", headRev, "got", got)
		}
	}
	path, branch := "", ""
	if task != nil {
		branch = task.Branch
		path = task.Workdir()
		if _, err := os.Stat(path); err != nil {
			path = ""
		}
	}
	ref, err := workspace.NewResultRef(repo, branch, commit, path)
	if err != nil {
		m.log.Error("组装结果引用失败", "repo", repo, "branch", branch, "commit", commit, "cause", err)
		return workspace.ResultRef{}, err
	}
	m.log.Info("结果引用已组装", "repo", ref.Repo, "branch", ref.Branch, "commit", ref.Commit, "path", ref.Path)
	return ref, nil
}

n_orchestration_Manager_Continue.signature:
// Continue 向任务续发修改指令：要求任务处于 waiting_review，先回迁 running 再
// 经 Adapter.Send 原样透传指令（同一会话续接，上下文完整保留）。
//
// 返回：
//   - 任务不存在返回 store.ErrNotFound；状态不允许续接返回 store.ErrBadTransit
//   - Send 失败时任务回迁 waiting_review（协调者可重试指令），并返回该错误
//
// 注意：
//   - Send 撞 ErrTaskNotRunning 时走恢复阶梯（resumeForContinue）：executor
//     进程已死但会话数据在盘上，冷恢复续上原会话再重试 Send 一次；阶梯全走完
//     仍不可恢复则回迁 waiting_review，错误带 Outcome.Note 说明原因
func (m *Manager) Continue(ctx context.Context, taskID, instructions string) (err error) {
	m.log.Info("continue 进入", "task", taskID)
	defer func() {
		if err != nil {
			m.log.Error("continue 失败", "task", taskID, "cause", err)
		} else {
			m.log.Info("continue 完成", "task", taskID)
		}
	}()

	cur, err := m.st.GetTask(taskID)
	if err != nil {
		return err
	}
	if cur.State != proto.TaskStateWaitingReview {
		m.log.Warn("continue 状态不允许", "task", taskID, "state", cur.State)
		return fmt.Errorf("任务 %s 状态 %s 不允许续接（需 waiting_review）: %w", taskID, cur.State, store.ErrBadTransit)
	}
	if err := m.transit(taskID, proto.TaskStateRunning, "continue"); err != nil {
		return err
	}

	ad, err := m.adapterFor(taskID)
	if err != nil {

		m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 路由执行者失败回迁")
		return fmt.Errorf("解析任务 %s 执行者: %w", taskID, err)
	}
	if m.taskIsOpenCode(taskID) {
		task, _ := m.st.GetTask(taskID)
		snap, err := m.resolveSnapshot(task)
		if err != nil {
			m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 快照失败回迁")
			return err
		}
		sa, ok := ad.(executor.SnapshotApplier)
		if !ok {
			m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 无 SnapshotApplier")
			return fmt.Errorf("OpenCode 未实现 SnapshotApplier，无法把新快照投影到原生配置")
		}
		m.log.Info("Continue 投影新快照", "task", taskID, "version", snap.Version)
		if err := sa.ApplySnapshot(ctx, taskID, snap); err != nil {
			m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 投影失败回迁")
			return err
		}
		if ab, ok := ad.(executor.ApprovalBinder); ok {
			if err := ab.BindApproval(taskID, m.bindApproval(taskID, snap)); err != nil {
				m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 重绑 ApprovalClient 失败回迁")
				return fmt.Errorf("绑定新 ApprovalClient 失败: %w", err)
			}
		}
	}
	if err := ad.Send(ctx, taskID, instructions); err != nil {
		if !errors.Is(err, executor.ErrTaskNotRunning) {

			m.log.Error("续发指令失败", "task", taskID, "cause", err)
			m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 发送失败回迁")
			return fmt.Errorf("续发指令: %w", err)
		}
		m.log.Warn("续发指令时 executor 已不在，进入恢复阶梯", "task", taskID, "cause", err)
		if rerr := m.resumeForContinue(ctx, taskID, ad); rerr != nil {
			m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 恢复失败回迁")
			return rerr
		}

		if err := ad.Send(ctx, taskID, instructions); err != nil {
			m.log.Error("恢复后重试续发仍失败", "task", taskID, "cause", err)
			m.transitBestEffort(taskID, proto.TaskStateWaitingReview, "continue 恢复后发送失败回迁")
			return fmt.Errorf("恢复后续发指令: %w", err)
		}
		m.log.Info("恢复后续发指令成功，重启中介循环", "task", taskID)
		go m.mediate(taskID)
	}
	return nil
}

n_orchestration_Manager_Dispatch.signature:
// Dispatch 派发一个新任务：准备任务分支 → 建任务 → 建 taskDir 写 plan → Adapter.Start →
// running → 启动中介 goroutine 消费事件流。Carrier/Squad 已由网关完成冻结准入，
// 本方法只把它们与物理身份落盘，不重新解析接收者或重新选择成员。
//
// 参数：
//   - req: 仓库路径与 base64 计划（字段说明见 agentd.DispatchReq）
//
// 返回：
//   - 已入库的任务（state 为 running）；Adapter.Start 失败时返回错误，
//     此时任务已落库并迁移为 failed（供协调者经 tasks 命令查看失败现场）
//
// 注意：
//   - 任务分支（handoff/<id8>）的准备发生在建任务之前：分支准备是纯前置校验
//     （工作区干净/可开分支），失败时不落任何任务记录，协调者修好仓库重新
//     dispatch 即可——不会为每次被拒的派发留下 failed 噪音
//   - 分支名经 store.SetTaskField 白名单字段 "branch" 写入任务（不随 CreateTask
//     带列写入，保持「创建期只写创建时已知的字段」的约定）
func (m *Manager) Dispatch(ctx context.Context, req agentd.DispatchReq) (task *proto.Task, err error) {
	m.log.Info("dispatch 进入",
		"project_id", req.ProjectID, "project_name", req.ProjectName,
		"plan_name", req.PlanName, "target", req.Target,
		"executor", req.Executor, "receiver", req.Receiver, "carrier", req.Carrier,
		"model", req.Model, "name", req.Name,
		"branch", req.Branch, "new_branch", req.NewBranch, "base", req.Base,
		"base_commit", req.BaseCommit, "resolve_default_base", req.ResolveDefaultBase,
		"local_base_branch", req.LocalBaseBranch,
		"worktree", req.Worktree, "new_worktree", req.NewWorktree,
		"home_dir_set", req.HomeDir != nil && *req.HomeDir != "")
	defer func() {
		if err != nil {
			m.log.Error("dispatch 失败",
				"project_id", req.ProjectID, "project_name", req.ProjectName, "cause", err)
		} else {
			m.log.Info("dispatch 完成", "task", task.ID)
		}
	}()

	entries, err := m.st.ListProjectLocations()
	if err != nil {
		m.log.Error("dispatch 前置：读取项目位置失败", "cause", err)
		return nil, err
	}
	loc, err := workspace.ResolveProject(req.ProjectID, req.ProjectName, entries)
	if err != nil {
		return nil, err
	}

	repoPath := loc.Path
	m.log.Info("dispatch 项目已解析",
		"project_id", loc.ProjectID, "name", loc.Name, "path", repoPath)

	if repoPath == "" || (req.PlanB64 == "" && req.Prompt == "") {
		return nil, fmt.Errorf("%w: repo_path=%q plan_b64 长度=%d prompt 长度=%d",
			agentd.ErrBadDispatchRequest, repoPath, len(req.PlanB64), len(req.Prompt))
	}

	if req.LocalBaseBranch && req.ResolveDefaultBase {
		m.log.Warn("dispatch 被拒：本地工作分支与默认基线标记互斥",
			"base", req.Base, "resolve_default_base", req.ResolveDefaultBase)
		return nil, fmt.Errorf("%w: local_base_branch 与 resolve_default_base 互斥",
			workspace.ErrBadWorkspaceReq)
	}
	if req.LocalBaseBranch && strings.TrimSpace(req.Base) == "" {
		m.log.Warn("dispatch 被拒：本地工作分支缺少 Base")
		return nil, fmt.Errorf("%w: local_base_branch=true 时 base 必须是非空工作分支名",
			workspace.ErrBadWorkspaceReq)
	}

	execName, ad, err := m.resolveExecutor(req.Executor)
	if err != nil {
		return nil, err
	}
	if m.reg != nil {
		if rerr := m.reg.Require(execName, executor.CapExecution); rerr != nil {
			m.log.Error("dispatch 执行能力不足", "executor", execName, "cause", rerr)
			return nil, fmt.Errorf("%w: %w", agentd.ErrBadDispatchRequest, rerr)
		}
	}
	model := m.resolveModel(req.Model, execName)

	envKVs, err := m.env.For(execName)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", agentd.ErrEnvResolveFailed, err)
	}

	discText := req.DisciplineText
	if strings.TrimSpace(req.Discipline) != "" && discText == "" {
		m.log.Warn("dispatch 被拒：点名纪律块但未收到下发正文", "name", req.Discipline)
		return nil, fmt.Errorf("%w: 点名纪律块 %q 但请求未携带 discipline_text（执行机不再本地解析，正文须由协调者下发）",
			agentd.ErrDisciplineResolveFailed, req.Discipline)
	}

	discSource := ""
	if discText != "" {
		discSource = "下发"
		if req.Discipline != "" {
			discSource += ":" + req.Discipline
			if req.DisciplineVersion > 0 {
				discSource += fmt.Sprintf("@v%d", req.DisciplineVersion)
			}
		}
	}

	// 内容合成：plan 解码后作为主体；prompt 非空时——
	//   plan 非空：拼接为「附加指令」小节（为什么：prompt 是派发当刻的补充意图，
	//   与 plan 是同一任务的两个信息面，放进同一文件让 executor 一次读全，避免
	//   二次上下文丢失）；plan 空：prompt 即任务内容
	var planContent []byte
	if req.PlanB64 != "" {
		planContent, err = base64.StdEncoding.DecodeString(req.PlanB64)
		if err != nil {
			return nil, fmt.Errorf("%w: 解码 plan_b64: %v", agentd.ErrBadDispatchRequest, err)
		}
		if req.Prompt != "" {
			planContent = append(planContent, []byte("\n\n## 附加指令（派发时提供）\n\n"+req.Prompt)...)
		}
	} else {
		planContent = []byte(req.Prompt)
	}
	planName := req.PlanName
	if planName == "" {
		planName = "prompt.md"
	}
	summary := planSummaryFromContent(planContent)
	name := deriveName(req.Name, req.PlanName, req.Prompt)

	now := time.Now().UTC()
	taskID := uuid.NewString()

	if err := m.RequireWorkspace(); err != nil {
		m.log.Error("dispatch 失败：工作区能力未注入",
			"project_id", req.ProjectID, "project_name", req.ProjectName)
		return nil, err
	}
	if err := m.ws.EnsureRepoUsable(ctx, repoPath); err != nil {
		return nil, err
	}
	if req.ResolveDefaultBase && req.Base == "" && req.Branch == "" {
		defaultBase, baseErr := workspace.ResolveDefaultBaseBranch(ctx, repoPath)
		if baseErr != nil {
			m.log.Warn("卡派发默认基线解析失败，拒绝派发", "repo", repoPath, "cause", baseErr)
			return nil, baseErr
		}
		req.Base = defaultBase
		m.log.Info("卡派发默认基线已解析", "repo", repoPath, "base", req.Base)
	}

	occupied := ""
	if !req.NewWorktree {
		occupied = repoPath
		if req.Worktree != "" {
			occupied = req.Worktree
		}
	}
	if err := m.guardWorkdirBusy(occupied); err != nil {
		return nil, err
	}

	baselineWS, err := m.ws.ResolveBaseline(ctx, repoPath, req.BaseCommit)
	if err != nil {
		return nil, err
	}
	baseline := baselineWS

	start, ahead := req.Base, 0
	if start == "" && req.Branch == "" {
		start, ahead = baseline.Start, baseline.Ahead
		if ahead > 0 {
			m.log.Warn("任务仓库 HEAD 领先基线，新分支不含这些提交",
				"repo", repoPath, "start", start, "ahead", ahead)
		}
	}
	m.log.Info("基线起点已确定", "repo", repoPath, "start", start, "ahead", ahead,
		"explicit_base", req.Base != "")

	if start != "" {

		resolved, fetched, rerr := workspace.ResolveDispatchBase(ctx, repoPath, start, req.LocalBaseBranch)
		if rerr != nil {
			return nil, rerr
		}
		if fetched {
			m.log.Info("基线分支已补拉并解析", "repo", repoPath, "branch", start, "sha", resolved)
		} else if resolved != start {
			m.log.Info("起点原文已解析为提交号", "repo", repoPath, "base", start, "sha", resolved)
		}
		start = resolved
	}

	if err := agentd.CheckProcHeadroom("dispatch"); err != nil {
		return nil, err
	}

	prepared, err := m.ws.Prepare(ctx, workspace.PrepareReq{
		Repo:	repoPath, TaskID: taskID,
		Branch:	req.Branch, NewBranch: req.NewBranch, Base: start,
		Worktree:	req.Worktree, NewWorktree: req.NewWorktree,
		WorktreesDir:	filepath.Join(m.cfg.DataDir, "worktrees"),
	})
	if err != nil {
		return nil, fmt.Errorf("git 工作区准备: %w", err)
	}
	ws := prepared

	executorStarted := false
	defer func() {
		if err != nil && !executorStarted {
			m.compensateWorkspace(ctx, taskID, repoPath, ws)
		}
	}()

	taskDir := filepath.Join(m.cfg.DataDir, "tasks", taskID)
	if err := os.MkdirAll(taskDir, 0o700); err != nil {
		return nil, fmt.Errorf("创建任务目录 %s: %w", taskDir, err)
	}
	planPath := filepath.Join(taskDir, planName)
	if err := m.writeTaskDirFile(taskDir, planName, planContent); err != nil {
		return nil, fmt.Errorf("写计划文件 %s: %w", planPath, err)
	}

	if discText != "" {
		if err := m.writeTaskDirFile(taskDir, disciplineFileName, []byte(discText)); err != nil {
			m.log.Error("纪律正文落盘失败，拒派", "task", taskID, "bytes", len(discText), "cause", err)
			return nil, fmt.Errorf("落盘纪律块正文: %w", err)
		}
		m.log.Info("纪律正文已落盘", "task", taskID,
			"path", filepath.Join(taskDir, disciplineFileName), "bytes", len(discText))
	}

	taskHomeDir := ""
	if req.HomeDir != nil && *req.HomeDir != "" {
		taskHomeDir = *req.HomeDir
	}
	task = &proto.Task{
		ID:		taskID,
		Target:		req.Target,
		RepoPath:	repoPath,
		HomeDir:	taskHomeDir,
		Carrier:	req.Carrier,
		Squad:		req.Squad,

		PlanPath:	planPath,
		State:		proto.TaskStatePending,
		CreatedAt:	now,
		UpdatedAt:	now,

		Name:		name,
		Executor:	execName,
		Model:		model,
		Discipline:	discSource,
		DisciplineName:	req.Discipline,

		DisciplineVersion:	req.DisciplineVersion,
		WorkDir:		ws.WorkDir,
		WorktreeManaged:	ws.Managed,

		BaseCommit:	start,
		BaseAhead:	ahead,

		RepoDirtyCount:	ws.RepoDirtyCount,
		RepoDirtyFiles:	ws.RepoDirtyFiles,
	}
	if err := m.st.CreateTask(task); err != nil {
		return nil, err
	}

	if err := m.st.SetTaskField(taskID, "branch", ws.Branch); err != nil {
		m.log.Error("写入任务分支失败", "task", taskID, "branch", ws.Branch, "cause", err)

		m.transitBestEffort(taskID, proto.TaskStateFailed, "写分支名失败")
		return nil, fmt.Errorf("记录任务分支: %w", err)
	}

	task.Branch = ws.Branch

	if err := m.st.SetTaskField(taskID, "plan_summary", summary); err != nil {
		m.log.Error("写入任务 plan 摘要失败", "task", taskID, "cause", err)
		m.transitBestEffort(taskID, proto.TaskStateFailed, "写 plan 摘要失败")
		return nil, fmt.Errorf("记录任务 plan 摘要: %w", err)
	}
	task.PlanSummary = summary
	m.log.Info("plan 摘要已生成", "task", taskID, "summary", agentd.TruncateRunes(summary, 40))
	m.log.Info("工作区就绪", "task", taskID, "workdir", ws.WorkDir, "managed", ws.Managed)

	startEnv := envKVs
	if task.HomeDir != "" {

		startEnv = withCarrierHome(envKVs, task.HomeDir)
		m.log.Info("载体 HOME 已覆盖 executor 环境", "task", taskID,
			"home_override", true, "home_dir", task.HomeDir)
	}
	var approval executor.ApprovalClient
	if isOpenCodeExecutor(execName, m.conf().Executor.Default) || execName == executor.HarnessClaude {
		snap, serr := m.resolveSnapshot(task)
		if serr != nil {
			return nil, serr
		}
		approval = m.bindApproval(taskID, snap)
		m.log.Info("Dispatch 注入 ApprovalClient", "task", taskID, "version", snap.Version)
	}
	startReq := executor.StartReq{Task: *task, PlanContent: string(planContent),
		TaskDir:	taskDir, Env: startEnv, Discipline: discText, Approval: approval}
	if err := m.prepareTaskProfile(ctx, startReq); err != nil {
		m.log.Error("任务 Profile 准备失败，拒绝启动 executor", "task", taskID,
			"executor", execName, "home", task.HomeDir, "discipline_present", discText != "", "cause", err)
		m.transitBestEffort(taskID, proto.TaskStateFailed, "任务 Profile 准备失败")
		return nil, err
	}
	if err := ad.Start(ctx, startReq); err != nil {
		m.log.Error("adapter 启动失败", "task", taskID, "cause", err)

		m.transitBestEffort(taskID, proto.TaskStateFailed, "adapter start 失败")
		return nil, fmt.Errorf("%w: %v", agentd.ErrExecutorStartFailed, err)
	}
	m.log.Info("dispatch 经执行能力面", "task", taskID, "executor", execName)

	executorStarted = true
	if err := m.transit(taskID, proto.TaskStateRunning, "dispatch"); err != nil {
		return nil, err
	}

	task, err = m.st.GetTask(taskID)
	if err != nil {
		return nil, fmt.Errorf("读取派发后的任务: %w", err)
	}
	task.Discipline = discSource
	task.DisciplineName = req.Discipline
	m.log.Info("纪律正文收文即用完成", "task", taskID, "name", req.Discipline,
		"version", req.DisciplineVersion, "source", discSource)

	if discSource != "" {
		m.appendProgress(taskID, "纪律块: "+discSource)
	}
	m.log.Info("纪律块已注入", "task", taskID, "executor", execName,
		"source", discSource, "bytes", len(discText))
	go m.mediate(taskID)
	return task, nil
}

n_orchestration_Manager_Done.signature:
// Done 归档任务：要求任务处于 waiting_review，迁移 completed 后调用 Adapter.Stop
// 回收 executor 侧资源，并清理 agentd 管理的 worktree。
//
// 返回：
//   - 任务不存在返回 store.ErrNotFound；状态不允许归档返回 store.ErrBadTransit
//
// 参数：
//   - note: 归档说明（handoff done --note）；空串表示未留说明，此时仍照常归档
//     并发布 archived 事件，只不落说明
//
// 注意：
//   - Stop 失败仅打 Error 日志不影响归档：任务已完成，executor 残留交给人工兜底
//   - 顺序是「先落说明、再迁移状态」：写失败时任务仍在 waiting_review，协调者可
//     原样重试；反过来先迁移就会留下「已归档但说明丢了」且不可重试的状态——done
//     对已 completed 的任务返回 409，协调者补不回来
func (m *Manager) Done(ctx context.Context, taskID, note string) (outcome agentd.TerminalOutcome, err error) {

	m.noteSweepOwned(taskID)
	m.log.Info("done 进入", "task", taskID)
	defer func() {
		if err != nil {
			m.log.Error("done 失败", "task", taskID, "cause", err)
		} else {
			m.log.Info("done 完成", "task", taskID, "claimed", outcome.Claimed)
		}
	}()

	cur, err := m.st.GetTask(taskID)
	if err != nil {
		return agentd.TerminalOutcome{}, err
	}

	if cur.State == proto.TaskStateCompleted {
		m.log.Info("done 已幂等完成", "task", taskID, "state", cur.State)
		return agentd.TerminalOutcome{Claimed: false}, nil
	}
	if cur.State != proto.TaskStateWaitingReview {
		m.log.Warn("done 状态不允许", "task", taskID, "state", cur.State)
		return agentd.TerminalOutcome{}, fmt.Errorf("任务 %s 状态 %s 不允许归档（需 waiting_review）: %w", taskID, cur.State, store.ErrBadTransit)
	}

	if note != "" {
		if err := m.st.SetTaskField(taskID, "done_note", note); err != nil {
			m.log.Error("写入归档说明失败", "task", taskID, "note_bytes", len(note), "cause", err)
			return agentd.TerminalOutcome{}, fmt.Errorf("写入归档说明: %w", err)
		}
		m.log.Info("归档说明已落库", "task", taskID, "note_bytes", len(note))
	}
	claimed, err := m.transitClaim(taskID, proto.TaskStateCompleted, "done")
	if err != nil {
		return agentd.TerminalOutcome{}, err
	}
	if !claimed {

		m.log.Info("done 幂等成功（并发中他人已完成迁移）", "task", taskID)
		return agentd.TerminalOutcome{Claimed: false}, nil
	}

	if evt, aerr := m.st.AppendEvent(taskID, proto.EventTypeArchived,
		proto.ArchivedPayload{Note: note}); aerr != nil {
		m.log.Error("追加归档事件失败", "task", taskID, "cause", aerr)
	} else {
		m.hub.Publish(evt)
		m.log.Info("归档事件已发布", "task", taskID, "seq", evt.Seq, "has_note", note != "")
	}

	m.clearApproverState(taskID)

	if n := m.hub.CloseTask(taskID); n > 0 {
		m.log.Info("done 关闭事件订阅", "task", taskID, "closed", n)
	}

	ad, err := m.adapterFor(taskID)
	if err != nil {
		m.log.Error("解析任务执行者失败", "task", taskID, "cause", err)
	} else {
		m.stopExecutor(taskID, ad)
	}

	m.sweepAfterStop(taskID)

	dec := workspace.MayRecycle(workspace.RecycleInput{
		Managed:	cur.WorktreeManaged,
		Manual:		false,
		Terminal:	true,
		State:		string(proto.TaskStateCompleted),
		Trigger:	workspace.TriggerDone,
	})
	m.log.Info("done 回收判据", "task", taskID, "decision", dec,
		"managed", cur.WorktreeManaged, "workdir", cur.WorkDir)
	if dec == workspace.RetainRecycle {
		if err := m.RequireWorkspace(); err != nil {
			m.log.Error("done 需回收但工作区能力未注入", "task", taskID, "cause", err)
		} else if werr := m.ws.RecycleManaged(ctx, cur.RepoPath, cur.WorkDir); werr != nil {
			m.log.Error("清理 managed worktree 失败", "task", taskID, "workdir", cur.WorkDir, "cause", werr)

			if evt, aerr := m.st.AppendEvent(taskID, proto.EventTypeProgress, agentd.ProgressPayload{
				Text: worktreeCleanupHint(taskID, werr),
			}); aerr != nil {
				m.log.Error("追加 worktree 清理失败事件失败", "task", taskID, "cause", aerr)
			} else {
				m.hub.Publish(evt)
			}
		} else {
			m.log.Info("managed worktree 已清理", "task", taskID, "workdir", cur.WorkDir)
		}
	} else {
		m.log.Info("done 按判据留存工作树", "task", taskID, "decision", dec, "workdir", cur.WorkDir)
	}

	m.purgeTaskCache(taskID)
	return agentd.TerminalOutcome{Claimed: true}, nil
}

n_orchestration_Manager_ExecutorNames.signature:
// ExecutorNames 返回本机已注册的 executor 名，按名字升序。
//
// 用途：纪律配置端点要把「注册的 adapter」与「配置里已出现的键」取并集，
// 后者不能省——一个配了纪律块但当前没注册的名字（改名、临时摘掉）若不列出，
// 界面就看不见它，而它还躺在配置里。
func (m *Manager) ExecutorNames() []string	{ return registeredNames(m.ads) }

n_orchestration_Manager_FootprintAll.signature:
// FootprintAll 体检全部任务（含已归档）的进程足迹。
//
// 返回：
//   - 每个任务一行（含判定结论）与本机 uid 占用；查询任务列表失败才返回错误
//
// 注意：
//   - **只读，绝不发信号**：本方法只数不杀。数出来之后要不要动手是人的决定
//   - 与 status 分开的理由：本方法遍历全部历史任务目录，天然是慢命令；
//     status 有「不能变成慢命令」的硬纪律，两者不能合并
//   - 已归档任务同样体检：Done 只删 worktree、不删任务目录，凭据都还在
func (m *Manager) FootprintAll() (*proto.FootprintResp, error) {
	tasks, err := m.st.ListTasks()
	if err != nil {
		m.log.Error("足迹体检：查询任务列表失败", "cause", err)
		return nil, fmt.Errorf("查询任务列表: %w", err)
	}
	m.log.Info("足迹体检开始", "tasks", len(tasks))
	resp := &proto.FootprintResp{Rows: make([]proto.FootprintRow, 0, len(tasks))}
	scanned, withProcs := 0, 0
	for _, t := range tasks {
		ad, aerr := m.adapterFor(t.ID)
		if aerr != nil {
			continue
		}
		fp, ok := ad.(footprinter)
		if !ok {
			continue
		}
		h, herr := fp.ProcHandle(t.ID, filepath.Join(m.cfg.DataDir, "tasks", t.ID))
		if herr != nil {
			continue
		}
		scanned++
		members, v, ferr := prochost.Footprint(h)
		if ferr != nil {
			m.log.Warn("足迹体检：枚举失败", "task", t.ID, "cause", ferr)
			continue
		}
		if len(members) > 0 {
			withProcs++
		}
		resp.Rows = append(resp.Rows, proto.FootprintRow{
			TaskID:	t.ID, Name: t.Name, State: string(t.State),
			Procs:	len(members), Verdict: string(v),
		})
	}
	if used, limit, uerr := prochost.UIDUsage(); uerr == nil {
		resp.Usage = &proto.ProcUsage{Used: used, Limit: limit}
	} else {
		m.log.Warn("足迹体检：读不到进程占用，该字段留空", "cause", uerr)
	}
	m.log.Info("足迹体检完成", "scanned", scanned, "with_procs", withProcs, "rows", len(resp.Rows))
	return resp, nil
}

n_orchestration_Manager_ForceReclaim.signature:
// ForceReclaim 强制回收一个失控任务：先停 executor，停掉了才把任务落 failed。
//
// 参数：
//   - taskID: 目标任务
//   - reason: 落 failed 时写进事件的理由，必须含可判断的真实数字（如实际进程数
//     与硬上限），审核者事后要凭它判断回收得对不对
//
// 返回：
//   - nil: executor 已停、任务已落 failed（清扫与工单作废由 transit 的终态收口
//     自动完成）
//   - 非 nil: 没停掉或状态迁移失败，**任务状态保持不变**——调用方应让它留在活跃
//     集里下一轮继续点名重试
//
// 注意：
//   - **顺序不可换**：想清掉一个正在 fork 的任务，必须先让 fork 的源头停下来；
//     杀子进程而留着父进程是打地鼠。这也是 B119 的根因——改前直接对活着的
//     executor 调 Sweep，段①被跳过后什么都没收，却照样宣布「已强制回收」
//   - 不删 managed worktree：1200 进程这种现场最需要留证，删 worktree 是不可逆
//     且外部可见的动作，留给协调者事后 handoff reclaim
func (m *Manager) ForceReclaim(taskID, reason string) error {
	m.log.Warn("强制回收进入", "task", taskID, "reason", reason)
	ad, err := m.adapterFor(taskID)
	if err != nil {
		m.log.Error("强制回收解析执行者失败", "task", taskID, "cause", err)
		return fmt.Errorf("强制回收解析执行者: %w", err)
	}
	if serr := m.stopExecutor(taskID, ad); serr != nil {

		m.log.Error("强制回收失败：executor 未停止，任务保持活跃", "task", taskID, "cause", serr)
		return fmt.Errorf("强制回收停止 executor: %w", serr)
	}
	if terr := m.transit(taskID, proto.TaskStateFailed, reason); terr != nil {
		m.log.Error("强制回收落 failed 失败", "task", taskID, "cause", terr)
		return fmt.Errorf("强制回收落 failed: %w", terr)
	}
	evt, aerr := m.st.AppendEvent(taskID, proto.EventTypeFailed, agentd.NewFailedPayload(reason, "", ""))
	if aerr != nil {
		m.log.Error("强制回收追加 failed 事件失败", "task", taskID, "cause", aerr)
		return fmt.Errorf("强制回收追加事件: %w", aerr)
	}
	m.hub.Publish(evt)
	m.log.Warn("强制回收完成", "task", taskID, "reason", reason)
	return nil
}

n_orchestration_Manager_GC.signature:
// GC 预览或执行目标 agentd 上的终态缓存与残留 managed worktree 清理。
//
// 参数：
//   - ctx: HTTP 请求生命周期；执行路径传入 Reclaim
//   - force: 是否允许按 reclaim 语义强删脏 managed worktree；缓存删除不读 force
//   - execute: false 为预览，true 为在同一判定语义下执行；执行自己重读 ListTasks
//
// 返回：
//   - GC 报告；任务列表失败才返回 error。Failures>0 仍返回 resp 且 err=nil
//
// 注意：缓存删除不依赖 force；force 不加 execute 仍只能影响预览报告。
func (m *Manager) GC(ctx context.Context, force, execute bool) (resp *proto.GCResp, err error) {
	if m.log != nil {
		m.log.Info("gc 进入", "force", force, "execute", execute)
		defer func() {
			if err != nil {
				m.log.Error("gc 未完成", "force", force, "execute", execute, "cause", err)
				return
			}
			if resp != nil {
				var bytes int64
				if resp.ReleasableBytes != nil {
					bytes = *resp.ReleasableBytes
				}
				m.log.Info("gc 完成", "force", force, "execute", execute,
					"preview", resp.Preview, "scanned", resp.Scanned,
					"failures", resp.Failures, "bytes", bytes,
					"cache_rows", len(resp.CacheRows), "worktree_rows", len(resp.WorktreeRows))
			}
		}()
	}
	if m.st == nil || m.cfg == nil {
		return nil, fmt.Errorf("gc 未就绪")
	}
	tasks, err := m.st.ListTasks()
	if err != nil {
		return nil, fmt.Errorf("查询任务列表: %w", err)
	}
	if m.log != nil {
		m.log.Info("gc 已读任务快照", "tasks", len(tasks), "execute", execute)
	}
	resp = &proto.GCResp{
		Preview:	!execute,
		Force:		force,
		CacheRows:	[]proto.GCCacheRow{},
		WorktreeRows:	[]proto.GCWorktreeRow{},
	}
	var releasable int64
	seen := map[string]struct{}{}
	for _, t := range tasks {
		if !t.State.IsTerminal() {
			continue
		}
		resp.Scanned++
		for _, leaf := range cacheplan.PlanTaskCacheLeaves(m.cfg.DataDir, t.ID, tasks) {
			key := filepath.Clean(leaf.Path)
			if _, ok := seen[key]; ok {
				continue
			}
			seen[key] = struct{}{}
			row := proto.GCCacheRow{TaskID: t.ID, Path: leaf.Path}
			if leaf.Skip || cacheplan.IsTmpRoot(m.cfg.DataDir, leaf.Path) {
				row.Status = proto.GCItemSkipped
				row.Error = leaf.Note
				if row.Error == "" {
					row.Error = "拒绝删除 DataDir/tmp 根"
				}
				if m.log != nil {
					m.log.Info("gc 跳过缓存叶子", "task", t.ID, "path", leaf.Path, "reason", row.Error)
				}
				resp.CacheRows = append(resp.CacheRows, row)
				continue
			}
			n, werr := cacheplan.SumRegularFileBytes(leaf.Path)
			if werr != nil {
				if m.log != nil {
					m.log.Error("gc 统计缓存字节失败", "task", t.ID, "path", leaf.Path, "cause", werr)
				}
			} else {
				row.Bytes = n
			}
			_, lerr := os.Lstat(leaf.Path)
			missing := lerr != nil && os.IsNotExist(lerr)
			if !execute {
				if missing {
					continue
				}
				row.Status = proto.GCItemPlanned
				releasable += row.Bytes
				resp.CacheRows = append(resp.CacheRows, row)
				continue
			}
			if missing {
				continue
			}
			if m.log != nil {
				m.log.Info("gc 删除缓存叶子前", "task", t.ID, "path", leaf.Path, "bytes", row.Bytes)
			}
			if rerr := m.removeCacheLeaf(leaf.Path); rerr != nil {
				if m.log != nil {
					m.log.Error("gc 删除缓存叶子失败", "task", t.ID, "path", leaf.Path, "cause", rerr)
				}
				row.Status = proto.GCItemFailed
				row.Error = rerr.Error()
				resp.Failures++
				resp.CacheRows = append(resp.CacheRows, row)
				continue
			}
			row.Status = proto.GCItemDeleted
			releasable += row.Bytes
			resp.CacheRows = append(resp.CacheRows, row)
		}
	}
	resp.ReleasableBytes = &releasable
	if execute {
		m.appendGCWorktreesExecute(ctx, resp, tasks, force)
	} else {
		m.appendGCWorktreesPreview(resp, tasks, force)
	}
	return resp, nil
}

n_orchestration_Manager_InspectRepoDir.signature:
// InspectRepoDir 检查一个目录是否是一份可用的、带 origin 的 git 仓库，并归并到
// 主工作树。
//
// 三步序列（EnsureRepoUsable → MainWorktreeRoot → 现读 origin）在「登记已有目录」
// 与「克隆落点认领」两条路径共用，绝不能复制两份——校验逻辑一分开就会漂移。
//
// 参数：
//   - ctx: 控制 git 调用生命周期
//   - dir: 待检查的目录
//
// 返回：
//   - root: 归并主工作树后的仓库根（绝对路径）
//   - origin: 该仓库 origin 的现读值（非空；读不到即返回错误）
//   - err: 任一步失败时的包装错误（ErrRepoUnusable 系列）
func (m *Manager) InspectRepoDir(ctx context.Context, dir string) (root, origin string, err error) {
	if err := workspace.EnsureRepoUsable(ctx, dir); err != nil {
		m.log.Warn("登记被拒：路径不是可用的 git 仓库", "path", dir, "cause", err)
		return "", "", err
	}

	root, err = workspace.MainWorktreeRoot(ctx, dir)
	if err != nil {
		m.log.Warn("登记被拒：归并主工作树失败", "path", dir, "cause", err)
		return "", "", err
	}

	origin, err = workspace.OriginURL(ctx, root)
	if err != nil {
		m.log.Warn("登记被拒：读不到 origin", "path", root, "cause", err)
		return "", "", err
	}
	return root, origin, nil
}

n_orchestration_Manager_ListProjects.signature:
// ListProjects 列出本机全部项目位置，并现场探测每条的实际状态。
//
// 参数：
//   - ctx: 控制探测用的 git 调用生命周期
//
// 返回：
//   - 位置列表（Status 已填充）；查库失败时返回错误
//
// 注意：
//   - 探测是登记与文件系统漂移的可见化手段。探测失败不影响列出——
//     状态本身就是要报给人看的结果，不是错误
func (m *Manager) ListProjects(ctx context.Context) ([]proto.ProjectLocation, error) {
	locs, err := m.st.ListProjectLocations()
	if err != nil {
		m.log.Error("列出项目位置失败", "cause", err)
		return nil, err
	}
	for i := range locs {
		locs[i].Status = probeProjectStatus(ctx, locs[i].Path)
	}
	m.log.Info("列出项目位置", "count", len(locs))
	return locs, nil
}

n_orchestration_Manager_MismatchTransit.signature:
// MismatchTransit 返回失配对账扫描（watchdog.scanStateMismatch）的迁移回调包装。
//
// 为什么需要导出：watchdog.go 与 manager.go 同包，扫描本可以直接调 m.transit；
// 但看门狗的接线点在 cmd/agentd.go（agentd 包外），transit 未导出无法从包外引用，
// 于是经这个导出方法把「把任务迁到 failed 并做终态收口」的能力交给 cmd 接线。
// 终态收口（挂起工单作废 + 审计留痕，B63）仍挂在 transit 内部，扫描只负责判定。
func (m *Manager) MismatchTransit() func(taskID string, to proto.TaskState, reason string) error {
	return func(taskID string, to proto.TaskState, reason string) error {
		return m.transit(taskID, to, reason)
	}
}

n_orchestration_Manager_NoteDeliveryFail.signature:
// NoteDeliveryFailed 产出 delivery_failed 事件：应答已落库但没送到 executor。
//
// 参数：
//   - taskID: 任务 ID
//   - ticketID: 未送达的工单 ID
//   - cause: 送达失败的原因（原样进 payload 供协调者诊断）
//
// why（必须是事件而不只是日志）：此时 executor 仍原地阻塞，而工单已被应答消耗、
// 不再出现在 attach 的挂起项里——只写日志的话协调者这边完全无感，任务一路挂到
// 看门狗超时。产出事件才能唤醒协调者（wait 不过滤该类型），提示执行 handoff resume。
// 供 manager 内部的应答等待链路与 server 的 reply 回程共用。
func (m *Manager) NoteDeliveryFailed(taskID, ticketID string, cause error) {
	m.log.Info("追加 delivery_failed 事件", "task", taskID, "ticket", ticketID, "cause", cause)
	evt, err := m.st.AppendEvent(taskID, proto.EventTypeDeliveryFailed, deliveryFailedPayload{
		TicketID:	ticketID,
		Reason:		agentd.TruncateRunes(fmt.Sprint(cause), 500),
		Hint:		"应答已落库但未送达 executor，执行 handoff resume <task> 重投",
	})
	if err != nil {
		m.log.Error("追加 delivery_failed 事件失败", "task", taskID, "ticket", ticketID, "cause", err)
		return
	}
	m.hub.Publish(evt)
	m.log.Info("delivery_failed 事件已发布", "task", taskID, "ticket", ticketID)
}

n_orchestration_Manager_Reclaim.signature:
// Reclaim 回收一个终态任务残留的 managed worktree。
//
// 参数：
//   - ctx: 上层上下文（HTTP 请求）
//   - taskID: 目标任务
//   - force: 为真时对脏工作树也强删（丢弃未提交改动），并在响应里报出丢弃清单
//
// 返回：
//   - 回收结果（removed / pruned / already_absent）
//   - store.ErrNotFound: 任务不存在
//   - agentd.ErrReclaimNotTerminal / agentd.ErrReclaimNotManaged / agentd.ErrReclaimRepoUnreachable
//   - *DirtyWorktreeError: 脏树且未带 force
//
// 注意：
//   - **纯资源动作**：不改任务状态、不追加事件、不删分支、不删任务目录
//   - 幂等：树已不在则报 already_absent 并成功返回。一条重试第二次会报错的
//     入口不是重试入口
//   - 动手前重读任务快照：failed→running 是合法迁移，列表之后任务可能已被
//     重新派发，终态判定不能停在列表那一刻
func (m *Manager) Reclaim(ctx context.Context, taskID string, force bool) (resp *proto.ReclaimResp, err error) {
	m.log.Info("reclaim 进入", "task", taskID, "force", force)
	defer func() {
		if err != nil {
			m.log.Warn("reclaim 未完成", "task", taskID, "cause", err)
		}
	}()

	cur, err := m.st.GetTask(taskID)
	if err != nil {
		return nil, err
	}
	if !cur.State.IsTerminal() {
		return nil, fmt.Errorf("任务 %s 状态 %s，%w", taskID, cur.State, agentd.ErrReclaimNotTerminal)
	}
	if !cur.WorktreeManaged || cur.WorkDir == "" {
		return nil, fmt.Errorf("任务 %s：%w", taskID, agentd.ErrReclaimNotManaged)
	}

	dec := workspace.MayRecycle(workspace.RecycleInput{
		Managed:	cur.WorktreeManaged,
		Manual:		false,
		Terminal:	cur.State.IsTerminal(),
		State:		string(cur.State),
		Trigger:	workspace.TriggerExplicit,
	})
	m.log.Info("reclaim 回收判据", "task", taskID, "decision", dec, "state", cur.State)
	if dec != workspace.RetainRecycle {
		m.log.Warn("reclaim 被判据拒绝", "task", taskID, "decision", dec, "state", cur.State)
		if !cur.State.IsTerminal() {
			return nil, fmt.Errorf("任务 %s 状态 %s，%w", taskID, cur.State, agentd.ErrReclaimNotTerminal)
		}
		if !cur.WorktreeManaged || cur.WorkDir == "" {
			return nil, fmt.Errorf("任务 %s：%w", taskID, agentd.ErrReclaimNotManaged)
		}
		return nil, fmt.Errorf("任务 %s 回收判据为 %s，拒绝回收", taskID, dec)
	}

	entries, lerr := workspace.ListWorktrees(ctx, cur.RepoPath)
	if lerr != nil {
		return nil, fmt.Errorf("任务 %s 的仓库 %s：%v：%w",
			taskID, cur.RepoPath, lerr, agentd.ErrReclaimRepoUnreachable)
	}
	state, dirty, note := workspace.ClassifyWorktree(ctx, entries, cur.WorkDir)
	base := &proto.ReclaimResp{WorkDir: cur.WorkDir, Branch: cur.Branch}

	switch state {
	case proto.WorktreeAbsent:
		m.log.Info("reclaim 完成：本就无残留", "task", taskID, "workdir", cur.WorkDir)
		base.Action = proto.ReclaimAlreadyAbsent
		return base, nil
	case proto.WorktreeUnknown:
		return nil, fmt.Errorf("任务 %s 工作树 %s：%s：%w",
			taskID, cur.WorkDir, note, agentd.ErrReclaimRepoUnreachable)
	case proto.WorktreeDirty:
		if !force {
			return nil, &workspace.DirtyWorktreeError{Files: dirty}
		}
		m.log.Warn("reclaim 强删脏工作树", "task", taskID,
			"workdir", cur.WorkDir, "discard", len(dirty))
	}

	if stderr, rerr := workspace.RemoveWorktree(ctx, cur.RepoPath, cur.WorkDir, force); rerr != nil {

		if state == proto.WorktreePrunable {
			m.log.Warn("reclaim：prunable 条目 remove 失败，退回 prune",
				"task", taskID, "stderr", agentd.TruncateRunes(stderr, 200), "cause", rerr)
			if perr := workspace.PruneWorktrees(ctx, cur.RepoPath); perr != nil {
				return nil, perr
			}
			after, verr := workspace.ListWorktrees(ctx, cur.RepoPath)
			if verr != nil {
				return nil, fmt.Errorf("prune 后复查工作树册：%w", verr)
			}
			if _, still := workspace.FindWorktree(after, cur.WorkDir); still {
				return nil, fmt.Errorf("prune 后条目 %s 仍在册", cur.WorkDir)
			}
			m.log.Info("reclaim 完成：prune 清掉在册条目", "task", taskID, "workdir", cur.WorkDir)
			base.Removed, base.Action = true, proto.ReclaimPruned
			return base, nil
		}
		return nil, rerr
	}

	m.log.Info("reclaim 完成：工作树已删除", "task", taskID,
		"workdir", cur.WorkDir, "branch", cur.Branch, "discarded", len(dirty))
	base.Removed, base.Action, base.Discarded = true, proto.ReclaimRemoved, dirty
	return base, nil
}

n_orchestration_Manager_ReclaimList.signature:
// ReclaimList 体检全部终态任务的 managed worktree 残留。
//
// 返回：
//   - 只含「仍有残留或判不出」的行，外加体检总数；查询任务列表失败才返回错误
//
// 注意：
//   - **单个仓库不可达不拖垮整张表**：该行标 unknown 继续走完。列表的核心
//     价值正是在环境已经不健康的时候还能用——这与单任务回收「判不出就拒绝」
//     的处置刻意相反，因为两者的失败代价不同
//   - 按仓库分组只拉一次工作树册：同一仓库下的多个任务共用一次 git 调用
//   - 与 FootprintAll 分工：那个数进程，这个数工作树，互不覆盖
func (m *Manager) ReclaimList() (*proto.ReclaimListResp, error) {
	tasks, err := m.st.ListTasks()
	if err != nil {
		m.log.Error("残留体检：查询任务列表失败", "cause", err)
		return nil, fmt.Errorf("查询任务列表: %w", err)
	}
	m.log.Info("残留体检开始", "tasks", len(tasks))

	ctx := context.Background()
	resp := &proto.ReclaimListResp{Rows: make([]proto.ReclaimRow, 0)}

	cache := make(map[string]map[string]workspace.WorktreeEntry)
	failed := make(map[string]string)

	for _, t := range tasks {
		if !t.State.IsTerminal() || !t.WorktreeManaged || t.WorkDir == "" {
			continue
		}
		resp.Scanned++
		entries, cached := cache[t.RepoPath]
		if !cached {
			e, lerr := workspace.ListWorktrees(ctx, t.RepoPath)
			if lerr != nil {
				failed[t.RepoPath] = strings.TrimSpace(agentd.TruncateRunes(lerr.Error(), 200))
			}
			cache[t.RepoPath], entries = e, e
		}
		row := proto.ReclaimRow{
			TaskID:	t.ID, Name: t.Name, State: string(t.State),
			Branch:	t.Branch, WorkDir: t.WorkDir,
		}
		if entries == nil {
			row.Worktree, row.Note = proto.WorktreeUnknown, failed[t.RepoPath]
			resp.Rows = append(resp.Rows, row)
			continue
		}
		state, dirty, note := workspace.ClassifyWorktree(ctx, entries, t.WorkDir)
		if state == proto.WorktreeAbsent {
			continue
		}
		row.Worktree, row.DirtyCount, row.Note = state, len(dirty), note
		resp.Rows = append(resp.Rows, row)
	}
	m.log.Info("残留体检完成", "scanned", resp.Scanned, "rows", len(resp.Rows),
		"bad_repos", len(failed))
	return resp, nil
}

n_orchestration_Manager_RecoverStuck.signature:
// RecoverStuck 是协调者的显式恢复操作（CLI: handoff resume <task>），
// 用来解开两类卡死：
//   - 「应答已落库但没送到 executor」：重投未送达的应答
//   - 「agentd 与 executor 断连期间回合已完结、终态事件丢失」（B38）：
//     会话对账补发丢失的终态
//
// 为什么需要它：reply 的回程里，应答一旦落库就消耗掉了工单的 answer IS NULL
// 守卫；若此时中继失败（executor 半死、调用超时），协调者会拿到 502，而工单
// 已从 pending 里消失、任务停在 waiting_answer——reply 得 404、continue/done
// 得 409，CLI 上再无一条可走的路。此前唯一的出口是运维重启 agentd 让
// RecoverOnStartup 探活，而那条路只在 executor **已死**时有效：executor 还
// 活着并仍阻塞在权限上时，重启探活成功、订阅重建、已答工单从不重放，是彻底的
// 死锁。B38 又补上第二类：断连窗口内完成的回合，终态事件在 /event 上永久丢失，
// 任务冻死在 running。本方法把出口交到协调者自己手里。
//
// 参数：
//   - taskID: 任务 ID
//   - force: 为真时即使对账判不出（executor 不支持对账 / 回合确实还在忙 /
//     查询失败），仍把任务强制收口到 waiting_review，使 continue/done 可用；
//     收口会留下写明「人工强制、未经 executor 确认」的事件
//
// 返回：
//   - 恢复结果快照（即使返回错误也可能非 nil，用于区分「executor 已死」与「这次没成功」）
//   - 任务不存在、已终结，或重投过程中 executor 仍不可用时返回错误
//
// 行为：
//  1. 无未送达应答 → 转入会话对账（adapter 支持且状态合适时）；force 时再收口
//  2. 有未送达应答 → 逐条重投；成功即标记送达，全部成功后任务回 running
//  3. 重投遇到 executor.ErrTaskNotRunning（executor 确实不在）→ 追加 failed
//     事件、作废挂起工单、任务转 waiting_review 交协调者，不再重试
//  4. 重投遇到其他错误（executor 还在，只是这次调用失败）→ 保持 waiting_answer
//     与未送达标记，返回错误；协调者稍后可再执行一次
//
// 注意：
//   - 幂等：已标记送达的应答不会被重投，重复执行是安全的；对账也幂等（水位已
//     过的回合不会二次补发）
//   - 与 ResumeTask 的区别：ResumeTask 是 agentd 重启时的执行器存活探测与订阅
//     重建（进程级），本方法是单任务的应答重投与会话对账（工单级），两者互不替代
func (m *Manager) RecoverStuck(taskID string, force bool) (*agentd.RecoverReport, error) {
	task, err := m.st.GetTask(taskID)
	if err != nil {
		return nil, fmt.Errorf("读取任务 %s: %w", taskID, err)
	}
	if task.State == proto.TaskStateCompleted || task.State == proto.TaskStateFailed {
		return nil, fmt.Errorf("任务 %s 已终结（%s），无可恢复项: %w", taskID, task.State, store.ErrBadTransit)
	}
	rep := &agentd.RecoverReport{Task: taskID, State: task.State}

	stuck, err := m.st.UndeliveredAnswers(taskID)
	if err != nil {
		return nil, err
	}
	if len(stuck) == 0 {
		m.log.Info("恢复操作：无未送达应答，转入会话对账", "task", taskID, "state", task.State)
		m.reconcileInto(rep, taskID, task.State)
		if force {
			m.forceToReview(rep, taskID, task.State)
		}
		return rep, nil
	}
	m.log.Info("恢复操作：开始重投未送达应答", "task", taskID, "count", len(stuck))

	for _, tk := range stuck {
		answer := ""
		if tk.Answer != nil {
			answer = *tk.Answer
		}
		if err := m.RelayAnswer(taskID, tk.ID, answer); err != nil {
			if errors.Is(err, executor.ErrTaskNotRunning) {

				rep.ExecutorGone = true
				rep.State = m.abandonToReview(taskID, tk.ID, err)
				rep.Note = "executor 已不在，任务已转交审核（可 continue 重新派发或 done 归档）"
				m.log.Warn("恢复操作：executor 已不在，任务转交审核",
					"task", taskID, "ticket", tk.ID, "cause", err)
				return rep, nil
			}

			rep.Note = "重投失败，executor 仍在但未响应；稍后可再执行一次 resume"
			m.log.Error("恢复操作：重投应答失败", "task", taskID, "ticket", tk.ID, "cause", err)
			return rep, fmt.Errorf("重投应答 %s: %w", tk.ID, err)
		}
		rep.Redelivered++
	}

	if task.State == proto.TaskStateWaitingAnswer {
		m.transitBestEffort(taskID, proto.TaskStateRunning, "恢复操作重投应答成功")
	}
	if cur, gerr := m.st.GetTask(taskID); gerr == nil {
		rep.State = cur.State
	}
	rep.Note = "应答已重新送达 executor，执行继续"
	m.log.Info("恢复操作完成", "task", taskID, "redelivered", rep.Redelivered, "state", rep.State)
	return rep, nil
}

n_orchestration_Manager_RegisterProject.signature:
// RegisterProject 登记一个项目位置（各形态与分派见 RegisterProjectReq 的决策表）。
//
// 参数：
//   - ctx: 控制整组 git 调用的生命周期
//   - req: 登记请求
//
// 返回：
//   - 落库后的位置条目
//   - 错误：ErrRepoUnusable（400，路径不是仓库/无 origin/clone 失败）、
//     ErrProjectOriginMismatch（400，路径上是另一个项目）、
//     ErrProjectAlreadyExists（409，项目/名字/路径已被占用，或落点已存在）、
//     ErrBadDispatchRequest（400，参数缺失或名字非法）
//
// 注意：
//   - **登记在 clone 成功之后才落库**：反过来会在 clone 失败时留下一条指向
//     不存在路径的死记录
//   - Path 非空时必须是绝对路径，否则 400（见 RegisterProjectReq）
//   - clone 的落点若已存在则直接拒绝，绝不往里 clone、绝不覆盖
func (m *Manager) RegisterProject(ctx context.Context, req workspace.RegisterProjectReq) (proto.ProjectLocation, error) {
	m.log.Info("登记项目请求", "origin", req.OriginURL, "name", req.Name, "path", req.Path)
	req.OriginURL = strings.TrimSpace(req.OriginURL)
	req.Name = strings.TrimSpace(req.Name)
	req.Path = strings.TrimSpace(req.Path)
	if req.OriginURL != "" && strings.HasPrefix(req.OriginURL, "-") {

		return proto.ProjectLocation{}, fmt.Errorf("%w: origin_url 不允许以 - 开头", agentd.ErrBadDispatchRequest)
	}
	if req.Path != "" {

		if !filepath.IsAbs(req.Path) {
			m.log.Warn("登记被拒：path 不是绝对路径", "path", req.Path)
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: path 必须是绝对路径（不支持 ~ 展开与相对路径）：%s",
				agentd.ErrBadDispatchRequest, req.Path)
		}
		req.Path = filepath.Clean(req.Path)
		return m.registerAtPath(ctx, req)
	}

	if req.OriginURL == "" {
		return proto.ProjectLocation{}, fmt.Errorf(
			"%w: 不带 path 时必须提供 origin_url（否则既无落点也无项目身份）",
			agentd.ErrBadDispatchRequest)
	}
	return m.cloneAndRegisterProject(ctx, req)
}

n_orchestration_Manager_RelayAnswer.signature:
// RelayAnswer 在 reply 回程找不到等待者时，把已落库的协调者应答直接回传给
// executor，自愈「agentd 重启后等待 goroutine 消亡 → 回答丢失 → executor 永远阻塞」。
//
// 场景：agentd 重启时 waitPermission/waitQuestion goroutine 随进程消亡，且 /event
// 不重放历史的话，协调者的 reply 在 hub 里找不到等待者；若应答就此丢弃，任务状态
// 被 resumeIfIdle 回迁 running，executor 却永远等不到权限裁决——工单已答、二次
// reply 404、done 409，不可恢复。本方法读取工单把应答按既有翻译规则直接送达 executor。
//
// 参数：
//   - taskID: 工单所属任务 ID（reply 路由的路径参数）
//   - ticketID: 已回答的工单 ID（AnswerTicket 已落库，此处只负责回传）
//   - answer: 协调者应答原文（与落库值一致）
//
// 返回：
//   - 工单不存在/不属于该任务/类型不识别返回错误；adapter 回传失败返回错误
//
// 规则（与 waitPermission/waitQuestion 的翻译规则完全一致）：
//   - kind=gate：answer trim 后为 "allow" → RespondPermission("once")，其余一律 "reject"
//   - kind=ask：OpenCode 经 RespondAsk 使用持久化 QuestionID；其他 executor 经 Send 透传
func (m *Manager) RelayAnswer(taskID, ticketID, answer string) error {
	tk, err := m.st.GetTicket(ticketID)
	if err != nil {
		return fmt.Errorf("读取工单 %s: %w", ticketID, err)
	}
	if tk.TaskID != taskID {
		return fmt.Errorf("工单 %s 不属于任务 %s", ticketID, taskID)
	}
	var req ticketRequest
	if err := json.Unmarshal(tk.Request, &req); err != nil {
		return fmt.Errorf("解析工单 %s 请求体: %w", ticketID, err)
	}
	switch req.Kind {
	case "gate":
		decision, reason := gateDecision(answer)

		permID := strings.TrimPrefix(ticketID, taskID+":")
		m.log.Info("reply 无等待者，自愈中继权限应答", "task", taskID,
			"ticket", ticketID, "perm", permID, "decision", decision)

		actx, acancel := unaryCtx(context.Background())
		defer acancel()
		ad, err := m.adapterFor(taskID)
		if err != nil {
			return fmt.Errorf("解析任务 %s 执行者: %w", taskID, err)
		}
		if err := ad.RespondPermission(actx, taskID, permID, decision, reason); err != nil {
			return fmt.Errorf("中继权限应答: %w", err)
		}
		m.noteDenyGuidanceUnlessInBand(taskID, permID, reason)
		m.markDelivered(taskID, ticketID)
		return nil
	case "ask":
		m.log.Info("reply 无等待者，自愈中继提问回答", "task", taskID, "ticket", ticketID)
		actx, acancel := unaryCtx(context.Background())
		defer acancel()
		ad, err := m.adapterFor(taskID)
		if err != nil {
			return fmt.Errorf("解析任务 %s 执行者: %w", taskID, err)
		}
		if m.taskIsOpenCode(taskID) {
			ar, ok := ad.(executor.AskResponder)
			if !ok {
				return fmt.Errorf("OpenCode 未实现 AskResponder，禁止回退 Send")
			}
			q, qerr := m.questionIDFromTicket(taskID, ticketID)
			if qerr != nil {
				return qerr
			}
			m.log.Info("reply 读取持久提问身份", "task", taskID, "ticket", ticketID, "question_id", q)
			if err := ar.RespondAsk(actx, executor.RespondAskReq{
				TaskID:	taskID, TicketID: ticketID, QuestionID: q, Answer: answer,
			}); err != nil {
				return fmt.Errorf("中继提问回答: %w", err)
			}
			m.log.Info("reply 提问回答已回传", "task", taskID, "ticket", ticketID, "question_id", q)
		} else {
			if err := ad.Send(actx, taskID, answer); err != nil {
				return fmt.Errorf("中继提问回答: %w", err)
			}
		}
		m.markDelivered(taskID, ticketID)
		return nil
	default:
		return fmt.Errorf("工单 %s 类型 %q 不支持中继", ticketID, req.Kind)
	}
}

