n_orchestration_Manager_Status.signature:
// Status 聚合本 agentd 的可用性与身份信息。
//
// 返回：
//   - StatusResp：版本、监听地址、DataDir、执行者清单、六状态计数、活跃任务
//     及其存活结论。StartedAt 由调用方（server 层）填，manager 不持有它
//   - err：只有查询任务列表失败才返回错误；探活失败不是错误，落到单个任务的
//     Live=unknown 上
func (m *Manager) Status() (*proto.StatusResp, error) {
	tasks, err := m.st.ListTasks()
	if err != nil {
		m.log.Error("状态聚合：查询任务列表失败", "cause", err)
		return nil, fmt.Errorf("查询任务列表: %w", err)
	}
	ver, ok := buildinfo.Read()
	if !ok {
		m.log.Warn("状态聚合：读不到构建标识，版本字段留空")
	}
	names := registeredNames(m.ads)
	sort.Strings(names)

	resp := &proto.StatusResp{
		Version:		ver,
		Listen:			m.cfg.Listen,
		DataDir:		m.cfg.DataDir,
		Executors:		names,
		DefaultExecutor:	m.conf().Executor.Default,
		StallTimeout:		m.cfg.StallTimeout.String(),
		TaskCounts:		map[string]int{},
		Active:			[]proto.ActiveTask{},
	}

	if cls, aux := config.ClassifyListen(m.cfg.Listen); cls == config.ListenSingle {
		resp.ListenAux = aux
	}

	for _, s := range []proto.TaskState{
		proto.TaskStatePending, proto.TaskStateRunning, proto.TaskStateWaitingAnswer,
		proto.TaskStateWaitingReview, proto.TaskStateCompleted, proto.TaskStateFailed,
	} {
		resp.TaskCounts[string(s)] = 0
	}

	var active []proto.Task
	for _, t := range tasks {
		resp.TaskCounts[string(t.State)]++
		if !agentd.IsTerminalState(t.State) {
			active = append(active, t)
		}
	}
	resp.Active = m.probeActive(active)
	unattended := 0
	for _, a := range resp.Active {
		if a.Watchers != nil && *a.Watchers == 0 &&
			a.State != string(proto.TaskStateWaitingReview) {
			unattended++
		}
	}

	resp.Update = &proto.UpdateStatus{Managed: selfupdate.IsManaged(os.Getenv)}

	if used, limit, err := prochost.UIDUsage(); err != nil {
		m.log.Warn("状态聚合：读不到进程占用，该字段留空", "cause", err)
	} else {
		resp.Proc = &proto.ProcUsage{Used: used, Limit: limit}
	}

	m.log.Info("状态聚合完成", "tasks", len(tasks), "active", len(active),
		"executors", len(names), "unattended", unattended, "managed", resp.Update.Managed)
	return resp, nil
}

n_orchestration_Manager_Stop.signature:
// Stop 主动中止一个任务：停 executor、落 failed 并唤醒协调者；挂起工单的作废
// 交由终态迁移的收口完成（B63），不在此处单独做。
//
// 参数：
//   - ctx: 上层上下文（HTTP 请求）
//   - taskID: 待中止的任务
//
// 返回：
//   - worktreeRemoved: 本次是否实际删除了 managed worktree。
//     成功 Stop 后恒为 false（现场留存，显式 reclaim/gc 才清，契约 C-6）
//   - store.ErrNotFound: 任务不存在
//   - store.ErrBadTransit: 任务已是终态（completed/failed），无可中止
//   - 其余：落库失败
//
// 注意：
//   - 复用 failed 终态而不新增 aborted：状态机零改动，且 failed→running 已允许，
//     中止后仍可重新派发。「人为中止」与「真失败」的区分靠 failed 事件的
//     fail_reason 文本，不靠状态
//   - 不删任务分支：那是协调者的工作成果，stop 只让它停下（审阅/回滚仍可切回分支）
//   - 留存工作树（B233.4 / 契约 C-6）：取消不是归档，现场必须保留供排查。有 commit 不构成删树授权；
//     显式 reclaim 或 gc 才清理。成功路径 worktreeRemoved 恒为 false。
//   - adapter.Stop 失败只 Warn 不中断：目的是让任务离开活跃态，executor 残留
//     由执行者进程兜底，不能因为「停不掉进程」就让任务永远卡在 running
func (m *Manager) Stop(ctx context.Context, taskID string) (outcome agentd.TerminalOutcome, err error) {

	m.noteSweepOwned(taskID)
	m.log.Info("stop 进入", "task", taskID)
	defer func() {
		if err != nil {
			m.log.Error("stop 失败", "task", taskID, "cause", err)
		} else {
			m.log.Info("stop 完成", "task", taskID, "claimed", outcome.Claimed)
		}
	}()

	cur, err := m.st.GetTask(taskID)
	if err != nil {
		return agentd.TerminalOutcome{}, err
	}
	if cur.State.IsTerminal() {
		m.log.Warn("stop 状态不允许", "task", taskID, "state", cur.State)
		return agentd.TerminalOutcome{}, fmt.Errorf("任务 %s 已是终态 %s，无可中止: %w", taskID, cur.State, store.ErrBadTransit)
	}

	ad, aerr := m.adapterFor(taskID)
	if aerr != nil {
		m.log.Error("解析任务执行者失败", "task", taskID, "cause", aerr)
	} else {

		_ = m.stopExecutor(taskID, ad)
	}

	m.sweepAfterStop(taskID)

	claimed, terr := m.transitClaim(taskID, proto.TaskStateFailed, "stop")
	if terr != nil {
		return agentd.TerminalOutcome{}, terr
	}
	if !claimed {

		return agentd.TerminalOutcome{}, fmt.Errorf("任务 %s 已在并发中被终结: %w", taskID, store.ErrBadTransit)
	}
	evt, err := m.st.AppendEvent(taskID, proto.EventTypeFailed, agentd.NewFailedPayload("协调者主动中止（handoff stop）", "", ""))
	if err != nil {
		return agentd.TerminalOutcome{}, fmt.Errorf("追加中止事件: %w", err)
	}

	m.clearApproverState(taskID)

	dec := workspace.MayRecycle(workspace.RecycleInput{
		Managed:	cur.WorktreeManaged,
		Manual:		false,
		Terminal:	true,
		State:		string(proto.TaskStateFailed),
		Trigger:	workspace.TriggerStop,
	})
	m.log.Info("stop 留存判据", "task", taskID, "decision", dec,
		"managed", cur.WorktreeManaged, "workdir", cur.WorkDir, "trigger", workspace.TriggerStop)
	if dec != workspace.RetainKeep {
		m.log.Error("stop 判据不是 keep，仍不回收（冻结 62）", "task", taskID, "decision", dec)
	}

	m.purgeTaskCache(taskID)
	m.hub.Publish(evt)
	return agentd.TerminalOutcome{Claimed: true, WorktreeRemoved: false}, nil
}

n_orchestration_Manager_SweepTaskProcs.signature:
// SweepTaskProcs 清扫一个任务的残留进程，best-effort。
//
// 参数：taskID 为目标任务
//
// 注意：
//   - 无返回值是刻意的：它的调用方（watchdog、RecoverOnStartup、reconcileExecutorGone）
//     全都处在收尾路径上，清扫成败不该反过来影响那件事
//   - 需要知道清扫结果的调用方（Done/Stop 的有界重试）走 sweepTaskProcsOnce
//   - 导出是因为 RecoverOnStartup 的接线点在 cmd/agentd.go（与 ResumeTask 同理），
//     不是给外部当通用 API 用
func (m *Manager) SweepTaskProcs(taskID string) {
	_ = m.sweep(taskID)
}

n_orchestration_Manager_TaskProcCount.signature:
// TaskProcCount 数一个任务名下当前有几个进程。
//
// 参数：taskID 为完整任务 id
//
// 返回：(n, ok)。**ok 为 false 时 n 无意义**，调用方必须什么都不做——
// 取不到句柄、adapter 不支持、Footprint 判定不可信（Verdict 非 OK）都归此类。
// 把「量不出来」当成「超了」会误杀，当成「没超」会让告警的置位状态错乱。
//
// 导出是因为 watchdog 的接线点在 cmd/agentd.go（与 SweepTaskProcs 同理），
// 不是给外部当通用 API 用。
func (m *Manager) TaskProcCount(taskID string) (int, bool) {
	ad, err := m.adapterFor(taskID)
	if err != nil {
		m.log.Debug("点名解析执行者失败", "task", taskID, "cause", err)
		return 0, false
	}
	fp, ok := ad.(footprinter)
	if !ok {
		m.log.Debug("adapter 不支持进程句柄，跳过点名", "task", taskID)
		return 0, false
	}
	h, err := fp.ProcHandle(taskID, filepath.Join(m.cfg.DataDir, "tasks", taskID))
	if err != nil {
		m.log.Debug("点名取进程句柄失败", "task", taskID, "cause", err)
		return 0, false
	}
	members, v, err := prochost.Footprint(h)
	if err != nil || v != prochost.VerdictOK {
		m.log.Debug("点名读数不可信", "task", taskID, "verdict", string(v), "cause", err)
		return 0, false
	}
	return len(members), true
}

n_orchestration_Manager_UnregisterProjec.signature:
// UnregisterProject 注销一条项目位置。
//
// 参数：
//   - ctx: 上下文（当前实现不发起 git 调用，保留以对齐其余操作签名）
//   - name: 项目引用名
//
// 返回：
//   - 错误：位置不存在时 store.ErrNotFound（404）；路径被活跃任务占用时
//     agentd.ErrWorkdirBusy（409）
//
// 注意：
//   - **只删登记，永不删磁盘上的仓库**。磁盘上那份是不是还要留，由人自己决定
func (m *Manager) UnregisterProject(ctx context.Context, name string) error {
	loc, err := m.st.GetProjectLocationByName(name)
	if err != nil {
		m.log.Warn("注销项目失败：位置不存在", "name", name, "cause", err)
		return err
	}
	tasks, err := m.st.ActiveTasksByRepoPath(loc.Path)
	if err != nil {
		m.log.Error("注销项目前查活跃任务失败", "name", name, "path", loc.Path, "cause", err)
		return err
	}
	if len(tasks) > 0 {
		ids := make([]string, 0, len(tasks))
		for _, t := range tasks {
			ids = append(ids, t.ID)
		}
		m.log.Warn("注销项目被拒：仓库被活跃任务占用",
			"name", name, "path", loc.Path, "tasks", strings.Join(ids, ","))
		return fmt.Errorf("%w: 项目 %s（%s）上还有 %d 个活跃任务（%s）；先 done 或 stop 它们",
			agentd.ErrWorkdirBusy, name, loc.Path, len(tasks), strings.Join(ids, ", "))
	}
	if err := m.st.DeleteProjectLocation(name); err != nil {
		m.log.Error("注销项目落库失败", "name", name, "cause", err)
		return err
	}
	m.log.Info("项目位置已注销（磁盘仓库未动）", "name", name, "path", loc.Path)
	return nil
}

n_orchestration_Manager_abandonToReview.signature:
// abandonToReview 在确认 executor 已不在时收尾：留下 failed 事件说明原因、
// 作废挂起工单（避免 attach 继续展示不可能被回答的项）、任务转 waiting_review。
// 返回收尾后的任务状态。
//
// 收尾实现已统一到 reconcileExecutorGone，本函数只负责拼这一句 reason。
func (m *Manager) abandonToReview(taskID, ticketID string, cause error) proto.TaskState {
	return agentd.ReconcileExecutorGone(m.st, m.hub, taskID,
		fmt.Sprintf("恢复操作发现 executor 已不在，应答 %s 无法送达: %v", ticketID, cause), m.log, m.SweepTaskProcs)
}

n_orchestration_Manager_adapterFor.signature:
// adapterFor 按任务记录的执行者名解析其 adapter。
//
// 规则：task.Executor 非空时按该名查注册表；为空（老任务兼容）回退缺省执行者
// （cfg.Executor.Default）。查不到时报错（错误带已注册名列表）。
func (m *Manager) adapterFor(taskID string) (executor.Adapter, error) {
	task, err := m.st.GetTask(taskID)
	if err != nil {
		return nil, err
	}
	name := task.Executor
	if name == "" {
		name = m.conf().Executor.Default
	}
	ad, ok := m.ads[name]
	if !ok {
		m.log.Error("任务执行者未注册，无法路由", "task", taskID, "executor", name,
			"registered", registeredNames(m.ads))
		return nil, fmt.Errorf("任务 %s 执行者 %q 未注册", taskID, name)
	}
	return ad, nil
}

n_orchestration_Manager_appendGCWorktree.signature:
func (m *Manager) appendGCWorktreesExecute(ctx context.Context, resp *proto.GCResp, tasks []proto.Task, force bool) {
	for _, t := range tasks {
		if !t.State.IsTerminal() || t.WorkDir == "" {
			continue
		}
		row := proto.GCWorktreeRow{
			TaskID:	t.ID, Name: t.Name, State: string(t.State), Branch: t.Branch, WorkDir: t.WorkDir,
		}
		if !t.WorktreeManaged {
			row.Status = proto.GCItemSkipped
			row.Note = "非 managed 工作树，跳过"
			resp.WorktreeRows = append(resp.WorktreeRows, row)
			continue
		}
		dec := workspace.MayRecycle(workspace.RecycleInput{
			Managed:	t.WorktreeManaged,
			Manual:		false,
			Terminal:	t.State.IsTerminal(),
			State:		string(t.State),
			Trigger:	workspace.TriggerExplicit,
		})
		if dec != workspace.RetainRecycle {
			if m.log != nil {
				m.log.Info("gc 按判据留存工作树，跳过回收", "task", t.ID, "decision", dec)
			}
			row.Status = proto.GCItemSkipped
			row.Note = "按留存判据跳过"
			resp.WorktreeRows = append(resp.WorktreeRows, row)
			continue
		}
		if m.log != nil {
			m.log.Info("gc 调用 reclaim 前", "task", t.ID, "force", force, "workdir", t.WorkDir)
		}
		wr, err := m.Reclaim(ctx, t.ID, force)
		if err == nil {
			row.Status = proto.GCItemDeleted
			if wr != nil {
				row.WorkDir = wr.WorkDir
				row.Branch = wr.Branch
			}
			resp.WorktreeRows = append(resp.WorktreeRows, row)
			continue
		}
		if m.log != nil {
			m.log.Info("gc reclaim 未删除", "task", t.ID, "cause", err)
		}
		var dirty *workspace.DirtyWorktreeError
		switch {
		case errors.As(err, &dirty):
			row.Status = proto.GCItemSkipped
			row.Worktree = proto.WorktreeDirty
			row.DirtyCount = len(dirty.Files)
			row.Note = err.Error()
		case errors.Is(err, agentd.ErrReclaimNotManaged),
			errors.Is(err, agentd.ErrReclaimNotTerminal),
			errors.Is(err, agentd.ErrReclaimRepoUnreachable):
			row.Status = proto.GCItemSkipped
			row.Error = err.Error()
			row.Note = err.Error()
		default:
			row.Status = proto.GCItemFailed
			row.Error = err.Error()
			resp.Failures++
		}
		resp.WorktreeRows = append(resp.WorktreeRows, row)
	}
}

// appendGCWorktreesPreview 用 ReclaimList 填预览工作树行。ReclaimList 无 ctx（B77 冻结签名）。
func (m *Manager) appendGCWorktreesPreview(resp *proto.GCResp, tasks []proto.Task, force bool) {
	list, err := m.ReclaimList()
	if err != nil {
		if m.log != nil {
			m.log.Error("gc 残树体检失败，工作树行留空继续缓存报告", "cause", err)
		}
		return
	}
	for _, r := range list.Rows {
		row := proto.GCWorktreeRow{
			TaskID:	r.TaskID, Name: r.Name, State: r.State, Branch: r.Branch,
			WorkDir:	r.WorkDir, Worktree: r.Worktree, DirtyCount: r.DirtyCount, Note: r.Note,
		}
		switch r.Worktree {
		case proto.WorktreeDirty:
			if !force {
				row.Status = proto.GCItemSkipped
				if row.Note == "" {
					row.Note = "脏工作树未带 force，跳过"
				}
			} else {
				row.Status = proto.GCItemPlanned
			}
		case proto.WorktreeUnknown:
			row.Status = proto.GCItemSkipped
			if row.Note == "" {
				row.Note = "工作树状态判不出，跳过"
			}
		default:
			row.Status = proto.GCItemPlanned
		}
		resp.WorktreeRows = append(resp.WorktreeRows, row)
	}
	for _, t := range tasks {
		if !t.State.IsTerminal() || t.WorkDir == "" || t.WorktreeManaged {
			continue
		}
		resp.WorktreeRows = append(resp.WorktreeRows, proto.GCWorktreeRow{
			TaskID:	t.ID, Name: t.Name, State: string(t.State), Branch: t.Branch,
			WorkDir:	t.WorkDir, Status: proto.GCItemSkipped, Note: "非 managed 工作树，跳过",
		})
	}
}

n_orchestration_Manager_appendGuidanceDr.signature:
// appendGuidanceDropped 记录拒绝原因没能下发的审计事件与告警：回合在下一条
// 提问到达前就终结了，协调者说的话无处送达，必须留痕让协调者知道用 continue
// 自己把话带上（B50）。
func (m *Manager) appendGuidanceDropped(taskID, guidance string, cause error) {
	evt, err := m.st.AppendEvent(taskID, proto.EventTypeDenyGuidanceDropped,
		denyGuidancePayload{Reason: guidance, Cause: cause.Error()})
	if err != nil {
		m.log.Error("追加 deny_guidance_dropped 事件失败", "task", taskID, "cause", err)
	} else {

		m.hub.Publish(evt)
	}
	m.log.Warn("拒绝原因未下发：回合已终结，用 continue 自己把话带上",
		"task", taskID, "reason", agentd.TruncateRunes(guidance, 80), "cause", cause)
}

n_orchestration_Manager_appendProgress.signature:
// appendProgress 追加一条 progress 事件并广播（恢复/强制收口等人工提示用）。
// 落库失败只 Error 不回滚——状态迁移已经发生，事件缺失最坏是协调者少看一条提示。
func (m *Manager) appendProgress(taskID, text string) {
	evt, err := m.st.AppendEvent(taskID, proto.EventTypeProgress, agentd.ProgressPayload{Text: text})
	if err != nil {
		m.log.Error("追加 progress 事件失败", "task", taskID, "cause", err)
		return
	}
	m.hub.Publish(evt)
}

n_orchestration_Manager_approvePermissio.signature:
// approvePermission 审批者批准路径：幂等建工单并自动答题 → RespondPermission(once)
// → 标记送达。全程不动任务状态机——任务保持 running，executor 收 once 后继续跑。
//
// 为什么不动状态：批准不是「任务被挂起等人工」，executor 恢复执行即续跑，
// 状态机不必经过 waiting_answer（那是「有未决人工事项」的语义，此处没有）。
//
// 参数：
//   - fp: 调用方用 permFingerprintFor(ev) 算好的裁决指纹——本函数只收权限描述
//     文本串、拿不到 ev.Perm，不在函数内重新猜域；键从建单就对齐 reuseDecision，
//     审批者路径的工单才进得了复用面（B91 §7）
//   - source: 这次批准的来源，取 "approver"（廉价模型审批者实时裁决）或
//     "reuse"（命中本任务内既有人工批准自动复用，B57②）。日志里必须区分：
//     复用路径若打「审批者自动批准」会把人引向一条根本没发生的裁决链去排查。
func (m *Manager) approvePermission(taskID, ticketID, permID, permission, fp, reason, source string) {
	m.log.Info("权限自动批准", "task", taskID, "ticket", ticketID,
		"perm", permID, "source", source, "reason", agentd.TruncateRunes(reason, 80))
	req, _ := json.Marshal(ticketRequest{Kind: "gate", Permission: permission})
	if _, err := m.st.CreateTicket(&proto.Ticket{
		ID:	ticketID, TaskID: taskID, Kind: "gate",
		Request:	req, CreatedAt: time.Now().UTC(),
		Fingerprint:	fp,
	}); err != nil {

		m.log.Error("审批者批准：创建工单失败", "task", taskID, "ticket", ticketID, "source", source, "cause", err)
		m.countApproverFail(taskID)
		return
	}

	if err := m.st.AnswerTicket(ticketID, "allow"); err != nil {
		m.log.Error("审批者批准：应答失败", "task", taskID, "ticket", ticketID, "source", source, "cause", err)
		m.countApproverFail(taskID)
		return
	}
	if _, err := m.st.AppendEvent(taskID, proto.EventTypeTicketAnswered,
		agentd.TicketAnsweredPayload{TicketID: ticketID, Answer: "allow"}); err != nil {
		m.log.Warn("审批者批准：追加工单答复事件失败", "task", taskID, "ticket", ticketID, "cause", err)
	}
	ad, err := m.adapterFor(taskID)
	if err != nil {

		m.log.Error("审批者批准：解析执行者失败", "task", taskID, "source", source, "cause", err)
		m.NoteDeliveryFailed(taskID, ticketID, err)
		return
	}
	actx, acancel := unaryCtx(context.Background())
	defer acancel()
	if err := ad.RespondPermission(actx, taskID, permID, "once", ""); err != nil {
		m.log.Error("审批者批准：回传 executor 失败", "task", taskID, "perm", permID, "source", source, "cause", err)
		m.NoteDeliveryFailed(taskID, ticketID, err)
		return
	}
	m.markDelivered(taskID, ticketID)
	m.log.Info("审批者批准已送达", "task", taskID, "ticket", ticketID, "source", source)
}

n_orchestration_Manager_auditAutoAllowOn.signature:
// auditAutoAllowOnly 只写自动放行审计并累计计数，不碰原生连接。
//
// bindApproval 把本函数绑给 approval.Hooks.AutoAllow，供 OpenCode 入站使用：
// OpenCode 的原生投递只由 adapter 的 authorizeNativePermission 完成一次。
// 免审无工单（B249），因此这里不产 delivery_failed。
//
// 注意：noteAutoAllowed 跟审计走、不跟原生投递走（P3）——OpenCode 不再回传，
// 计数若留在回传后就会从本段汇总里消失。
func (m *Manager) auditAutoAllowOnly(taskID string, ev executor.AdapterEvent, verdict permgate.Verdict) {
	m.log.Info("权限请求自动放行", "task", taskID, "perm", ev.PermissionID,
		"action", verdict.Action.String(), "rule", verdict.Rule, "reason", verdict.Reason)
	if verdict.Rule == permgate.RuleSafeCommand {
		if ev.Perm == nil {
			m.log.Error("白名单自动放行缺结构化权限载荷", "task", taskID,
				"perm", ev.PermissionID, "rule", verdict.Rule)
		} else {
			payload := permissionAutoAllowPayload{
				PermissionID:	ev.PermissionID,
				Permission:	permEventText(ev.Text),
				Tool:		ev.Perm.Tool,
				Command:	ev.Perm.Command,
				Paths:		append([]string(nil), ev.Perm.Paths...),
				Rule:		verdict.Rule,
				Reason:		verdict.Reason,
			}
			appendEvent := m.appendEvent
			if appendEvent == nil && m.st != nil {
				appendEvent = m.st.AppendEvent
			}
			if appendEvent == nil {
				m.log.Error("白名单自动放行审计无落库入口", "task", taskID,
					"perm", ev.PermissionID, "rule", verdict.Rule)
			} else if _, err := appendEvent(taskID, proto.EventTypePermissionAutoAllow, payload); err != nil {
				m.log.Error("白名单自动放行审计落库失败", "task", taskID,
					"perm", ev.PermissionID, "rule", verdict.Rule, "cause", err)
			} else {
				m.log.Info("白名单自动放行审计已落库", "task", taskID,
					"perm", ev.PermissionID, "rule", verdict.Rule)
			}
		}
	}
	m.noteAutoAllowed(taskID)
}

n_orchestration_Manager_bindApproval.signature:
func (m *Manager) bindApproval(taskID string, snap executor.PolicySnapshot) executor.ApprovalClient {
	if snap.TaskID == "" {
		snap.TaskID = taskID
	}
	m.log.Info("组装 ApprovalClient", "task", taskID, "version", snap.Version)
	return approval.NewClient(taskID, snap, approval.Hooks{
		Log:			m.log,
		Store:			m.st,
		Hub:			m.hub,
		JudgePermission:	m.judgePermission,
		ShouldConsult:		m.shouldConsultApprover,
		Decide: func(ctx context.Context, permission, summary string) approval.ConsultDecision {
			if m.approver == nil {
				return approval.ConsultDecision{Err: errors.New("审批者不可用")}
			}
			d := m.approver.Decide(ctx, permission, summary)
			return approval.ConsultDecision{
				Approve:	d.Approve, Reason: d.Reason,
				ElapsedMS:	d.ElapsedMS, Err: d.Err,
			}
		},
		CountConsultFailure:	m.countApproverFail,
		ResetConsultFailure: func(id string) {
			m.apMu.Lock()
			defer m.apMu.Unlock()
			delete(m.apFails, id)
		},

		AutoAllow:		m.auditAutoAllowOnly,
		TransitBestEffort:	m.transitBestEffort,
		NoteDeliveryFailed:	m.NoteDeliveryFailed,
	})
}

n_orchestration_Manager_cleanupCreatedDi.signature:
// cleanupCreatedDir 回收 clone 失败后本次新建的目录树。
//
// 参数：
//   - created: firstMissingAncestor 的返回值；空串表示本次没造过任何目录，直接返回
//
// 注意：回收失败**不改变**调用方看到的错误——clone 的失败原因才是人要看的那条，
// 残留目录只是需要人工清理的次要事实，写进 Warn 日志即可。
func (m *Manager) cleanupCreatedDir(created string) {
	if created == "" {
		return
	}
	if err := os.RemoveAll(created); err != nil {
		m.log.Warn("克隆失败后回收目录失败，需人工清理", "dir", created, "cause", err)
		return
	}
	m.log.Info("克隆失败，已回收本次新建的目录", "dir", created)
}

n_orchestration_Manager_clearApproverSta.signature:
// clearApproverState 清理任务级审批链运行时状态（apFails/apDisabled/denyGuidance）。
//
// 调用点：任务终结处——Done 归档（→completed）、stop（→failed）与 handleResult
// 的回合结束（→waiting_review）。为什么必须清理（P2-5）：这两张是进程内内存
// map，任务归档后若不清，条目随任务数无界增长；且任务被续接时旧的禁用标记/
// 失败计数也不该残留（新回合从干净状态重新评估审批链）。
//
// 为什么这里一并处理 denyGuidance：拒绝原因的生命周期是「从这次拒绝到下一条
// 提问」；回合终结意味着那条提问永远不会来了。若删除时原因还挂着，说明协调者
// 说的话没机会送达——必须落一条 deny_guidance_dropped 审计事件说明去向，
// 「协调者说的话去哪了」在任何路径下都有答案（B50）。
func (m *Manager) clearApproverState(taskID string) {
	m.apMu.Lock()
	delete(m.apFails, taskID)
	delete(m.apDisabled, taskID)
	guidance, had := m.denyGuidance[taskID]
	delete(m.denyGuidance, taskID)
	m.apMu.Unlock()
	if had {
		m.log.Warn("拒绝原因未下发：回合已终结，用 continue 自己把话带上",
			"task", taskID, "reason", agentd.TruncateRunes(guidance, 80))

		evt, err := m.st.AppendEvent(taskID, proto.EventTypeDenyGuidanceDropped,
			denyGuidancePayload{
				Reason:	guidance,
				Cause:	"回合在拒绝原因下发前终结（Done/stop/result），未送达 executor",
			})
		if err != nil {
			m.log.Error("追加 deny_guidance_dropped 事件失败", "task", taskID, "cause", err)
		} else {
			m.hub.Publish(evt)
		}
	}
}

n_orchestration_Manager_cloneAndRegister.signature:
// cloneAndRegisterProject 先 clone 再登记。
func (m *Manager) cloneAndRegisterProject(ctx context.Context, req workspace.RegisterProjectReq) (proto.ProjectLocation, error) {

	pid := projectid.FromOrigin(req.OriginURL)
	if pid != "" {
		if existing, ok, err := m.registeredProjectByID(pid); err != nil {
			return proto.ProjectLocation{}, err
		} else if ok {
			m.log.Info("项目位置已存在，幂等返回",
				"project_id", existing.ProjectID, "name", existing.Name, "path", existing.Path)
			existing.Status = workspace.ProjectStatusOK
			return existing, nil
		}
	}
	name := req.Name
	if name == "" {
		name = workspace.ProjectNameFromURL(req.OriginURL)
	}

	if err := workspace.ValidateProjectName(name); err != nil {
		m.log.Warn("克隆登记被拒：项目名非法", "name", name, "cause", err)
		return proto.ProjectLocation{}, err
	}
	if m.cfg.RepoRoot == "" {
		return proto.ProjectLocation{}, fmt.Errorf(
			"%w: 本机未配置 repo_root，无法决定克隆落点（在 config.yaml 里配它）", agentd.ErrBadDispatchRequest)
	}
	dest := filepath.Join(m.cfg.RepoRoot, name)

	if _, err := os.Stat(dest); err == nil {
		root, actual, ierr := m.InspectRepoDir(ctx, dest)
		if ierr != nil {
			m.log.Warn("克隆被拒：落点已存在但认领失败", "dest", dest, "cause", ierr)
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: 克隆落点 %s 已存在，但它不是本项目可认领的仓库（%v）；该目录不是 git 仓库或读不到 origin，请人工处置（agentd 不会自动删除或改名）",
				workspace.ErrProjectAlreadyExists, dest, ierr)
		}
		if projectid.FromOrigin(actual) != projectid.FromOrigin(req.OriginURL) {
			m.log.Warn("克隆被拒：落点已存在且属于另一个项目",
				"dest", dest, "actual_origin", actual, "want_origin", req.OriginURL)
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: 克隆落点 %s 已存在，其 origin 是 %s（另一个项目），请求的项目是 %s；请人工处置该目录（agentd 不会自动删除或改名）",
				workspace.ErrProjectAlreadyExists, dest, actual, req.OriginURL)
		}

		m.log.Info("落点已存在且就是本项目，直接登记，未重复 clone",
			"dest", dest, "project_id", projectid.FromOrigin(actual))
		return m.persistProject(name, root, actual)
	} else if !errors.Is(err, os.ErrNotExist) {
		return proto.ProjectLocation{}, fmt.Errorf("%w: 探查落点 %s: %v", agentd.ErrRepoUnusable, dest, err)
	}
	parent := filepath.Dir(dest)

	created := firstMissingAncestor(parent)
	if err := os.MkdirAll(parent, 0o755); err != nil {
		return proto.ProjectLocation{}, fmt.Errorf("%w: 创建落点父目录 %s: %v", agentd.ErrRepoUnusable, parent, err)
	}
	m.log.Info("开始克隆项目", "origin", req.OriginURL, "dest", dest)
	start := time.Now()

	if _, stderr, err := agentd.GitRunNet(ctx, parent, "clone", "--", req.OriginURL, dest); err != nil {
		m.log.Error("克隆项目失败", "origin", req.OriginURL, "dest", dest,
			"elapsed_ms", time.Since(start).Milliseconds(),
			"stderr", agentd.TruncateRunes(strings.TrimSpace(stderr), 300), "cause", err)
		m.cleanupCreatedDir(created)
		return proto.ProjectLocation{}, fmt.Errorf("%w: 克隆 %s 到 %s 失败: %s: %v",
			agentd.ErrRepoUnusable, req.OriginURL, dest, strings.TrimSpace(stderr), err)
	}
	m.log.Info("克隆项目完成", "origin", req.OriginURL, "dest", dest,
		"elapsed_ms", time.Since(start).Milliseconds())
	return m.persistProject(name, dest, req.OriginURL)
}

n_orchestration_Manager_cloneToPathAndRe.signature:
// cloneToPathAndRegister 把 origin clone 到调用方指定的 dest（req.Path）再登记。
//
// 与 cloneAndRegisterProject 的区别只在落点：这里落点是 req.Path 原样使用，
// 那里落点是 repo_root/<name> 并带「落点已存在则尝试认领」的归并逻辑。这里
// 不做认领——落点已存在的请求根本不会进入本函数（由 registerAtPath 分流到
// registerExistingProject），任意 path 上也没有 repo_root 那种「rm 后磁盘残留」
// 的自动登记场景。
//
// 幂等边界：同项目 + 同落点 → 返回已有行（磁盘被 rm 掉、位置表还在时，重复登记
// 不该把自动登记链打断）；同项目 + 异落点 → ErrProjectAlreadyExists，报文指向
// 已有位置。绝不静默返回一个与请求 path 不同的位置。
func (m *Manager) cloneToPathAndRegister(ctx context.Context, req workspace.RegisterProjectReq) (proto.ProjectLocation, error) {

	pid := projectid.FromOrigin(req.OriginURL)
	if pid != "" {
		existing, ok, err := m.registeredProjectByID(pid)
		if err != nil {
			return proto.ProjectLocation{}, err
		}
		if ok {
			if workspace.SameLocation(existing.Path, req.Path) {
				m.log.Info("项目位置已存在且落点相同，幂等返回",
					"project_id", existing.ProjectID, "name", existing.Name, "path", existing.Path)
				existing.Status = workspace.ProjectStatusOK
				return existing, nil
			}
			m.log.Warn("克隆登记被拒：该项目在本机已有位置",
				"project_id", pid, "existing", existing.Path, "requested", req.Path)
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: 项目 %s 在本机已登记于 %s；要换位置先 handoff project rm %s",
				workspace.ErrProjectAlreadyExists, existing.Name, existing.Path, existing.Name)
		}
	}

	name := req.Name
	if name == "" {
		name = workspace.ProjectNameFromURL(req.OriginURL)
	}
	if err := workspace.ValidateProjectName(name); err != nil {
		m.log.Warn("克隆登记被拒：项目名非法", "name", name, "cause", err)
		return proto.ProjectLocation{}, err
	}
	dest := req.Path
	parent := filepath.Dir(dest)

	created := firstMissingAncestor(parent)
	if err := os.MkdirAll(parent, 0o755); err != nil {
		return proto.ProjectLocation{}, fmt.Errorf("%w: 创建落点父目录 %s: %v", agentd.ErrRepoUnusable, parent, err)
	}
	m.log.Info("开始克隆项目到指定路径", "origin", req.OriginURL, "dest", dest)
	start := time.Now()

	if _, stderr, err := agentd.GitRun(ctx, parent, "clone", "--", req.OriginURL, dest); err != nil {
		m.log.Error("克隆到指定路径失败", "origin", req.OriginURL, "dest", dest,
			"elapsed_ms", time.Since(start).Milliseconds(),
			"stderr", agentd.TruncateRunes(strings.TrimSpace(stderr), 300), "cause", err)
		m.cleanupCreatedDir(created)
		return proto.ProjectLocation{}, fmt.Errorf("%w: 克隆 %s 到 %s 失败: %s: %v",
			agentd.ErrRepoUnusable, req.OriginURL, dest, strings.TrimSpace(stderr), err)
	}
	m.log.Info("克隆到指定路径完成", "origin", req.OriginURL, "dest", dest,
		"elapsed_ms", time.Since(start).Milliseconds())
	return m.persistProject(name, dest, req.OriginURL)
}

n_orchestration_Manager_compensateWorksp.signature:
// compensateWorkspace 在 dispatch 后续步骤失败时复原已准备好的工作区。
//
// why：PrepareWorkspace 成功意味着磁盘上已经有了工作树、且分支已经建好/切好。
// 若随后 executor 接管前的任何步骤失败（MkdirAll/WriteFile/CreateTask/
// SetTaskField/adapter.Start），任务要么没落库、要么落 failed——两者都没有 done
// 清理路径（done 只认 waiting_review），痕迹会永久留在用户的仓库里：managed
// 模式留下孤儿 worktree 与挡路的空分支（同名重试直接撞 already exists，B39），
// 非 managed 模式更直接——用户的工作树就停在那个空分支上。
//
// 参数：
//   - ctx: 控制补偿期间的 git 调用
//   - taskID: 用于在清理失败时给出可重试的 handoff reclaim 命令
//   - repo: 主仓库路径
//   - ws: PrepareWorkspace 的产出
//
// 注意：
//   - 由 Dispatch 的 defer 统一调用，且只在 executor 未接管时（见 executorStarted
//     注释）；executor 接管后删工作树是把运行中的任务脚下抽空
//   - 全程只记日志，**不覆盖也不替换原始派发错误**——协调者要看的是任务为什么
//     没派出去，补偿成败是次要信息
//   - 三条 fail-safe：worktree 删除失败 / 切回原 ref 失败 / 分支尖端对不上，
//     任一命中都保留现场不再往下做。宁可留残留，不可误删
func (m *Manager) compensateWorkspace(ctx context.Context, taskID string, repo string, ws workspace.Prepared) {

	if ws.WorkDir == "" {
		return
	}

	defer m.purgeTaskCache(taskID)
	m.log.Warn("dispatch 后续失败，补偿复原工作区", "repo", repo, "workdir", ws.WorkDir,
		"managed", ws.Managed, "branch", ws.Branch, "prev_ref", ws.PrevRef)

	if ws.Managed {
		dec := workspace.MayRecycle(workspace.RecycleInput{
			Managed:	true, Manual: false, Terminal: false, State: "",
			Trigger:	workspace.TriggerCompensate,
		})
		m.log.Info("补偿回收判据", "task", taskID, "decision", dec, "workdir", ws.WorkDir)
		if dec != workspace.RetainRecycle {
			m.log.Info("补偿按判据不回收", "task", taskID, "decision", dec)
		} else if err := m.RequireWorkspace(); err != nil {
			m.log.Error("补偿需回收但工作区能力未注入", "task", taskID, "cause", err)
			return
		} else if err := m.ws.RecycleManaged(ctx, repo, ws.WorkDir); err != nil {

			m.log.Error("补偿清理 managed worktree 失败，保留分支待查",
				"repo", repo, "workdir", ws.WorkDir, "branch", ws.Branch,
				"retry", "handoff reclaim "+shortTaskID(taskID), "cause", err)
			return
		}
	} else {
		if ws.PrevRef == "" {
			m.log.Warn("补偿无法复原：未记录原 ref，工作树仍停在任务分支上",
				"workdir", ws.WorkDir, "branch", ws.Branch,
				"manual", "git -C "+ws.WorkDir+" checkout <你原来的分支>")
			return
		}
		if stderr, err := workspace.RestoreWorktree(ctx, ws.WorkDir, ws.PrevRef); err != nil {
			m.log.Error("补偿切回原 ref 失败，工作树仍停在任务分支上",
				"workdir", ws.WorkDir, "prev_ref", ws.PrevRef,
				"stderr", agentd.TruncateRunes(stderr, 300), "cause", err)
			return
		}
		m.log.Info("补偿已切回原 ref", "workdir", ws.WorkDir, "prev_ref", ws.PrevRef)
	}
	m.deleteCreatedBranch(ctx, repo, ws)
}

n_orchestration_Manager_consultApprover.signature:
// consultApprover 在独立 goroutine 里完成一次权限请求的审批者裁决（不阻塞
// mediate 循环）。流程：Decide → 落 approver_decision 审计事件（不 Publish）→
// 按结果分流：approve 自动放行 / escalate 升级人工协调者 / Err 计数并 fail-closed。
func (m *Manager) consultApprover(ctx context.Context, taskID string, ev executor.AdapterEvent, ticketID string) {
	defer func() {
		m.apMu.Lock()
		delete(m.apInflight, ticketID)
		m.apMu.Unlock()
	}()
	m.log.Info("审批者开始裁决", "task", taskID, "ticket", ticketID,
		"perm", ev.PermissionID, "text", agentd.TruncateRunes(ev.Text, 80))

	summary := ""
	if task, err := m.st.GetTask(taskID); err == nil {
		summary = task.PlanSummary
	}
	d := m.approver.Decide(ctx, ev.Text, summary)

	decision := "error"
	switch {
	case d.Approve:
		decision = "approve"
	case d.Err == nil:
		decision = "escalate"
	}

	reason := d.Reason
	if reason == "" && d.Err != nil {
		reason = d.Err.Error()
	}
	if _, err := m.st.AppendEvent(taskID, proto.EventTypeApproverDecision, agentd.ApproverDecisionPayload{
		TicketID:	ticketID, Permission: permEventText(ev.Text), Decision: decision,
		Reason:	reason, ElapsedMS: d.ElapsedMS,
	}); err != nil {
		m.log.Error("追加 approver_decision 事件失败", "task", taskID, "ticket", ticketID, "cause", err)
	}

	cur, gerr := m.st.GetTask(taskID)
	if gerr != nil {
		m.log.Error("审批者裁决后重读任务失败，按已终结处理", "task", taskID, "cause", gerr)
		return
	}
	if cur.State != proto.TaskStateRunning && cur.State != proto.TaskStateWaitingAnswer {
		m.log.Warn("审批者裁决期间任务已离开 running/waiting_answer，回 reject 并留审计事件",
			"task", taskID, "ticket", ticketID, "decision", decision, "state", cur.State)

		m.respondLateDecision(taskID, ticketID, ev.PermissionID, decision, string(cur.State))
		return
	}

	if d.Err != nil {

		m.countApproverFail(taskID)
		m.escalatePermission(ctx, taskID, ev, ticketID)
		return
	}

	m.apMu.Lock()
	delete(m.apFails, taskID)
	m.apMu.Unlock()

	if d.Approve {
		m.approvePermission(taskID, ticketID, ev.PermissionID, ev.Text, permFingerprintFor(ev), d.Reason, "approver")
		return
	}
	m.escalatePermission(ctx, taskID, ev, ticketID)
}

n_orchestration_Manager_consumeSweepOwne.signature:
// consumeSweepOwned 检查并清除认领标记，返回是否命中（命中即本轮不必兜底清扫）。
//
// 为什么检查即清除：标记只在 Done/Stop 的一次调用内有意义。用完就删让 map 不随
// 任务数无界增长；万一 transit 没走到终态（迁移失败提前返回），残留的那一条会在
// 该任务下次落终态时被消费掉。
func (m *Manager) consumeSweepOwned(taskID string) bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	_, ok := m.sweepOwned[taskID]
	delete(m.sweepOwned, taskID)
	return ok
}

n_orchestration_Manager_countApproverFai.signature:
// countApproverFail 累计一次任务级裁决失败，达到 maxApproverFails 时停用该任务
// 的审批链并留 approver_disabled 审计事件（一次）。
func (m *Manager) countApproverFail(taskID string) {
	m.apMu.Lock()
	defer m.apMu.Unlock()
	m.apFails[taskID]++
	fails := m.apFails[taskID]
	if fails >= maxApproverFails && !m.apDisabled[taskID] {
		m.apDisabled[taskID] = true
		if _, err := m.st.AppendEvent(taskID, proto.EventTypeApproverDisabled, approverDisabledPayload{
			Reason: fmt.Sprintf("连续 %d 次裁决失败，审批链已停用（后续权限直接升级人工协调者）", maxApproverFails),
		}); err != nil {
			m.log.Error("追加 approver_disabled 事件失败", "task", taskID, "cause", err)
		}
		m.log.Warn("审批者连续失败已停用", "task", taskID, "fails", fails)
	}
}

n_orchestration_Manager_deleteCreatedBra.signature:
// deleteCreatedBranch 删除本次 dispatch 新建的分支（补偿路径专用）。
//
// why 这件事不放进 RemoveManagedWorktree：那个函数服务的是 Done/Stop 归档场景，
// 「只删工作树不删分支」在那里完全正确——分支上是任务成果。补偿场景的要求正好
// 相反：分支是几秒前刚建的，executorStarted 守卫保证零提交，留着只会挡路。
// 同一个函数满足不了相反的两组要求，所以在补偿侧单独承担。
//
// 参数：ctx 控制 git 调用；repo 主仓库路径；ws 为 PrepareWorkspace 的产出
//
// 注意：
//   - 调用前必须已经确保分支不再被任何工作树 checkout（managed 已删树 /
//     非 managed 已切回原 ref），否则 git 会拒绝
//   - 删不删的规则全部在 decideBranchAction 里（含「NewBranchTip 为空 = 不是
//     本次新建的，一律不动」这一条），本函数只负责取数据、按决定打日志、执行 git
func (m *Manager) deleteCreatedBranch(ctx context.Context, repo string, ws workspace.Prepared) {
	cur, tipErr := workspace.BranchTip(ctx, repo, ws.Branch)
	switch decideBranchAction(ws.NewBranchTip, cur, tipErr) {
	case branchKeepNotOurs:

		return
	case branchKeepTipUnknown:
		m.log.Warn("取分支尖端失败，无从复核，保留待查",
			"repo", repo, "branch", ws.Branch, "expect", ws.NewBranchTip, "cause", tipErr)
		return
	case branchKeepTipMoved:
		m.log.Warn("分支尖端与创建时不符，疑似已有提交，保留待查",
			"repo", repo, "branch", ws.Branch, "expect", ws.NewBranchTip, "actual", cur)
		return
	}
	m.log.Info("补偿删除本次新建的分支", "repo", repo, "branch", ws.Branch, "tip", ws.NewBranchTip)

	if stderr, err := workspace.DeleteBranch(ctx, repo, ws.Branch); err != nil {
		m.log.Error("补偿删除分支失败", "repo", repo, "branch", ws.Branch,
			"stderr", agentd.TruncateRunes(stderr, 300), "cause", err)
		return
	}
	m.log.Info("补偿删除分支完成", "repo", repo, "branch", ws.Branch)
}

n_orchestration_Manager_deliverAutoAllow.signature:
// deliverAutoAllowOnce 把 AutoAllow 出口的 once 裁决原生回传 executor：
// 解析执行者 + RespondPermission("once")。作为 approval.Authority 的
// DeliverAutoAllow 回调被绑定（B233.21）——AutoAllow 处置的顺序权威（先审计、
// 再恰好一次回传、不碰任何账本）在 approval，本函数只承载投递 mechanics 与
// 失败日志的第一现场。
//
// 注意：没有工单可失败，因此回传失败不产 delivery_failed 事件；最常见的
// 失败成因是订阅重放（同一权限请求被再次投递，而 executor 侧那次请求早已
// 应答完毕），按 Error 记录即可。adapterFor 失败意味着任务的运行态已没，
// executor 侧那次请求将无人应答——Error 级，同样无工单可失败。
func (m *Manager) deliverAutoAllowOnce(taskID, permID string) {
	ad, err := m.adapterFor(taskID)
	if err != nil {
		m.log.Error("自动放行：解析执行者失败，该权限请求将无人应答",
			"task", taskID, "perm", permID, "cause", err)
		return
	}
	actx, acancel := unaryCtx(context.Background())
	defer acancel()
	if err := ad.RespondPermission(actx, taskID, permID, "once", ""); err != nil {
		m.log.Error("自动放行回传 executor 失败（多为订阅重放，请求已失效）",
			"task", taskID, "perm", permID, "cause", err)
		return
	}
	m.log.Info("自动放行已回传 executor", "task", taskID, "perm", permID)
}

n_orchestration_Manager_denyReasonDelive.signature:
// denyReasonDelivered 判断本任务的 executor 是否已把拒绝理由同帧送达。
//
// 参数：taskID 为任务 id
// 返回：true 表示理由已到模型手里
//
// 注意：返回 true 时调用方**不得**再 noteDenyGuidance——两条路都走会让模型
// 被同一条理由说两遍。解析 adapter 失败时保守返回 false：宁可多说一遍，
// 也不能让理由一句都没送到。
func (m *Manager) denyReasonDelivered(taskID string) bool {
	ad, err := m.adapterFor(taskID)
	if err != nil {
		m.log.Warn("判定拒绝理由送达方式时解析执行者失败，按带外注入处置",
			"task", taskID, "cause", err)
		return false
	}
	d, ok := ad.(denyReasonInBander)
	return ok && d.DenyReasonInBand()
}

n_orchestration_Manager_escalatePermissi.signature:
// escalatePermission 把权限请求升级人工协调者：落状态 → 建工单 → 追加事件 →
// waiter → Publish（一期 handlePermission 的完整既有行为，顺序契约见其 doc）。
//
// 本函数同时是审批者 escalate 路径的出口——两路共用保证行为一致。
//
// 工单存权限描述全文，事件 payload 另行截断——全文是协调者裁决的依据，不能只存
// 唤醒用的摘要。
func (m *Manager) escalatePermission(ctx context.Context, taskID string, ev executor.AdapterEvent, ticketID string) {

	if m.reuseDecision(taskID, ev, ticketID) {
		return
	}

	m.transitBestEffort(taskID, proto.TaskStateWaitingAnswer, "permission_request")
	req, _ := json.Marshal(ticketRequest{Kind: "gate", Permission: ev.Text})
	if _, err := m.st.CreateTicket(&proto.Ticket{
		ID:	ticketID, TaskID: taskID, Kind: "gate",
		Request:	req, CreatedAt: time.Now().UTC(),
		Fingerprint:	permFingerprintFor(ev),
	}); err != nil {
		m.log.Error("创建权限工单失败", "task", taskID, "perm", ev.PermissionID, "ticket", ticketID, "cause", err)

		m.transitBestEffort(taskID, proto.TaskStateRunning, "权限工单创建失败回滚")
		return
	}
	evt, err := m.st.AppendEvent(taskID, proto.EventTypePermissionRequest, permissionPayload{
		TicketID:	ticketID, Permission: permEventText(ev.Text), Kind: "gate",
	})
	if err != nil {

		m.log.Error("追加 permission_request 事件失败", "task", taskID, "ticket", ticketID, "cause", err)
		return
	}
	m.log.Info("权限升级人工协调者", "task", taskID, "ticket", ticketID,
		"perm_chars", len([]rune(ev.Text)), "event_truncated", len([]rune(ev.Text)) > permEventTextLimit)
	go m.waitPermission(ctx, taskID, ev.PermissionID, ticketID)
	m.hub.Publish(evt)
}

n_orchestration_Manager_forceToReview.signature:
// forceToReview 把任务强制收口到 waiting_review（handoff resume --force）。
//
// 为什么需要它：对账判不出来（adapter 不支持 / 会话确实还在忙 / 查询失败）时，
// 协调者此前只剩 handoff stop——而 stop 会把一个其实成功了的任务落成 failed，
// 并杀掉 executor。本操作**保住会话**，只把状态推到可 continue/done 的位置。
//
// 风险与护栏：executor 可能真的还在跑，收口后 continue 会往忙碌会话里塞指令。
// 护栏只有事件文本与报告文案——不加更硬的拦截，因为更硬的拦截就是 stop，
// 而这个场景的全部意义恰恰是不杀会话。
func (m *Manager) forceToReview(rep *agentd.RecoverReport, taskID string, state proto.TaskState) {
	rep.Forced = true
	text := "协调者人工强制收口（handoff resume --force）：未经 executor 确认。" +
		"对账当时的结论是：" + rep.Note + "。若 executor 其实仍在执行，" +
		"后续 continue 的指令会进入一个忙碌会话，请先 handoff attach 确认现场。"
	m.log.Warn("恢复操作：人工强制收口", "task", taskID, "from", state, "note", rep.Note)
	m.appendProgress(taskID, text)
	if err := agentd.RecoverTransit(m.st, taskID, state); err != nil {
		rep.Note = "强制收口失败：" + err.Error()
		m.log.Error("恢复操作：强制收口迁移失败", "task", taskID, "cause", err)
		return
	}
	rep.State = proto.TaskStateWaitingReview
	rep.Note = "已人工强制收口到待审核（未经 executor 确认）；" +
		"可 continue 续接或 done 归档。对账当时的结论：" + rep.Note
}

n_orchestration_Manager_guardWorkdirBusy.signature:
// guardWorkdirBusy 拒绝把任务派到已被活跃任务占用的工作目录（B42）。
//
// 参数：
//   - workDir: 目标工作目录；空串=managed 模式（每任务一棵新树），直接放行
//
// 返回：
//   - nil：无人占用，或本次是 managed 模式
//   - agentd.ErrWorkdirBusy：已有非终态任务占着这个目录，错误文本点名占用者与两条出路
//     （server 层据此给 409，与「工作区不干净」同为状态冲突）
//   - 其他错误：查询任务表失败
//
// 注意：
//   - 查询失败按拒发处理：放行的代价是两个 executor 抢同一棵工作树、互相切走
//     HEAD 且全程无报错，比多拒一次派发严重得多
//   - 只报第一个占用者：报文是给人看的行动指引，列出全部只会让它更难读；
//     日志里带了 holders 总数
//   - git 自己已经挡住了分支级冲突（worktree add 遇到已被检出的分支会失败），
//     这道守卫补的是唯一的洞：被共享的主工作树
func (m *Manager) guardWorkdirBusy(workDir string) error {
	if workDir == "" {
		m.log.Info("工作目录占用检查跳过（managed 模式，每任务一棵新树）")
		return nil
	}
	busy, err := m.st.ActiveTasksByWorkDir(workDir)
	if err != nil {
		m.log.Error("查询工作目录占用失败，保守拒发", "workdir", workDir, "cause", err)
		return fmt.Errorf("查询工作目录占用: %w", err)
	}
	if len(busy) == 0 {
		m.log.Info("工作目录占用检查通过", "workdir", workDir)
		return nil
	}
	holder := busy[0]
	m.log.Warn("dispatch 被拒：目标工作目录已被活跃任务占用", "workdir", workDir,
		"holder", holder.ID, "holder_state", holder.State, "holders", len(busy))
	return fmt.Errorf("%w: %s 正被任务 %s（%s, %s）占用；先 handoff done/stop 它，或改用 --new-worktree 在独立工作树上开工",
		agentd.ErrWorkdirBusy, workDir, holder.ID, holder.Name, holder.State)
}

n_orchestration_Manager_handleEvent.signature:
// handleEvent 按事件类型分发中介处理，并打每类事件的入口日志。
func (m *Manager) handleEvent(ctx context.Context, taskID string, ev executor.AdapterEvent) {
	switch ev.Type {
	case adapterEventPermission:
		if m.taskIsOpenCode(taskID) {
			m.log.Warn("OpenCode 仍发出 permission 事件，忽略（权威在 adapter client）",
				"task", taskID, "perm", ev.PermissionID)
			return
		}
		m.log.Info("权限请求事件", "task", taskID, "perm", ev.PermissionID,
			"text", agentd.TruncateRunes(ev.Text, 80))
		m.handlePermission(ctx, taskID, ev)
	case adapterEventQuestion:
		m.log.Info("提问事件", "task", taskID, "text", agentd.TruncateRunes(ev.Text, 80))
		m.handleQuestion(ctx, taskID, ev)
	case adapterEventProgress:
		m.log.Info("进度事件", "task", taskID, "text", agentd.TruncateRunes(ev.Text, 80))
		m.handleProgress(taskID, ev)
	case adapterEventResult:
		if ev.Result != nil {
			m.log.Info("执行结果事件", "task", taskID, "ok", ev.Result.OK,
				"branch", ev.Result.Branch, "commit", ev.Result.CommitHash)
		} else {
			m.log.Warn("执行结果事件缺 Result", "task", taskID)
		}
		m.handleResult(taskID, ev)
	case adapterEventUsage:

		m.handleUsage(taskID, ev)
		m.handleSpend(taskID, ev)
		m.handleTiming(taskID, ev)
	default:
		m.log.Warn("未知 adapter 事件", "task", taskID, "type", ev.Type)
	}
}

n_orchestration_Manager_handlePermission.signature:
// handlePermission 中介权限请求：收 adapter 事件 → 调决策权威 → 按权威结论落
// 账本事实（ticket(id=taskID:permID, kind=gate) → 事件 → waiting_answer →
// goroutine 等协调者应答）→ 原生回传 executor（B233.21 收口后的形状）。
//
// 审批链前置的时序说明（二期新增）：approver 启用且黑名单未命中时，请求先交
// consultApprover 做廉价模型裁决——approve 全程不动状态机（任务保持 running，
// executor 收 once 后继续跑），escalate 则完整走下方「落状态→建工单→waiter→
// Publish」的原契约。因此本函数的中介主体被提取为 escalatePermission，供原路径
// 与审批者 escalate 路径共用，保证两路行为完全一致。
//
// 审批链异步化对原契约的修正（P1-1）：一期 handlePermission 在 mediate 循环内
// 同步执行，同任务的 permission/result 天然串行，「escalate 完整走原契约」的
// 前提隐含了这一点；二期起 consultApprover 是独立 goroutine（最长 60s），裁决
// 期间任务可能已被 handleResult/done 推进到终态。因此 escalatePermission 只能
// 在任务仍处 running/waiting_answer 时被调用——consultApprover 在分流前重读
// 任务快照，状态已终态则只留 approver_decision 审计事件。
//
// 顺序契约（P1-2 时序修复）：ticket/事件落库后，**先置 waiting_answer，再启动
// waiter goroutine，最后才 Publish**。严格说「先注册 waiter」不成立：waitPermission
// 的 hub 注册在 goroutine 启动后才异步发生，Publish 后 reply 仍可能先于注册到达——
// 该情形退化为「无等待者 → 自愈中继」（RelayAnswer 直接回传 executor），任务不卡死。
// 真正必须先就位的是**状态**：resumeIfIdle 读到 running 会跳过回迁，应答已交付但
// 任务随后落回 waiting_answer 且无人再答，永久卡死（探针 1/60 复现「waiting_answer
// 但 pending_tickets=0」）。状态先就位后，reply 无论命中 waiter 还是走中继，
// resumeIfIdle 必看到 waiting_answer，回迁判定一致。
func (m *Manager) handlePermission(ctx context.Context, taskID string, ev executor.AdapterEvent) {
	if ev.PermissionID == "" {
		m.log.Error("权限事件缺 PermissionID", "task", taskID)
		return
	}

	ticketID := taskID + ":" + ev.PermissionID
	if m.permAuthority.IsReplay(taskID, ev.PermissionID, ticketID) {

		m.respondAutoAllowReplay(taskID, ev)

		m.respondAnsweredTicketReplay(taskID, ev, ticketID)
		return
	}

	verdict := m.judgePermission(taskID, ev)
	switch verdict.Action {
	case permgate.AutoAllow:

		m.permAuthority.AutoAllow(taskID, ev, verdict)
		return
	case permgate.Consult:

		if m.shouldConsultApprover(taskID) {
			if m.markApproverInflight(ticketID) {
				go m.consultApprover(ctx, taskID, ev, ticketID)
			}
			return
		}
	}
	m.escalatePermission(ctx, taskID, ev, ticketID)
}

n_orchestration_Manager_handleProgress.signature:
// handleProgress 中介进度事件：只入库广播，不改任务状态。
//
// SessionID 非空时先落 task.ExecutorSession：「会话就绪」信号（adapter 建会话
// 成功后第一条 progress）是会话 id 到达 manager 的可靠通道——审核主路径常以
// question 收尾、result 永不出现。落库失败仅 Warn，不影响主流程（会话 id 属
// 可修复的辅助字段，进度广播照常）。
func (m *Manager) handleProgress(taskID string, ev executor.AdapterEvent) {
	if ev.SessionID != "" {
		if err := m.st.SetTaskField(taskID, "executor_session", ev.SessionID); err != nil {
			m.log.Warn("落库 executor_session 失败", "task", taskID, "session", ev.SessionID, "cause", err)
		}
	}
	evt, err := m.st.AppendEvent(taskID, proto.EventTypeProgress, agentd.ProgressPayload{Text: ev.Text})
	if err != nil {
		m.log.Error("追加 progress 事件失败", "task", taskID, "cause", err)
		return
	}
	m.hub.Publish(evt)
}

n_orchestration_Manager_handleQuestion.signature:
// handleQuestion 中介提问：ticket（原生命名或 uuid，kind=ask）→ 事件 → waiting_answer →
// goroutine 等协调者回答后，按 executor 契约回传。
//
// 顺序契约与 handlePermission 相同（P1-2）：先置 waiting_answer 再 Publish；
// waiter 注册异步，reply 先于注册到达时退化为自愈中继路径兜底。
func (m *Manager) handleQuestion(ctx context.Context, taskID string, ev executor.AdapterEvent) {

	if !m.taskIsOpenCode(taskID) {
		if guidance := m.takeDenyGuidance(taskID); guidance != "" {
			m.relayDenyGuidance(ctx, taskID, guidance)
			return
		}
	}

	ticketID := approval.AskTicketID(taskID, ev.QuestionID)
	m.transitBestEffort(taskID, proto.TaskStateWaitingAnswer, "question")
	req, _ := json.Marshal(ticketRequest{Kind: "ask", Question: ev.Text, QuestionID: ev.QuestionID})
	m.log.Info("提问工单请求已序列化", "task", taskID, "ticket", ticketID,
		"question_id", ev.QuestionID, "question_bytes", len(req))
	created, err := m.st.CreateTicket(&proto.Ticket{
		ID:	ticketID, TaskID: taskID, Kind: "ask",
		Request:	req, CreatedAt: time.Now().UTC(),
	})
	if err != nil {
		m.log.Error("创建提问工单失败", "task", taskID, "ticket", ticketID, "cause", err)
		m.transitBestEffort(taskID, proto.TaskStateRunning, "提问工单创建失败回滚")
		return
	}
	if !created {

		prior, gerr := m.st.GetTicket(ticketID)
		switch approval.ClassifyAskDuplicate(prior, gerr) {
		case approval.AskDuplicateSkip:
			m.log.Error("提问工单已存在但读取失败，按重放跳过", "task", taskID,
				"ticket", ticketID, "cause", gerr)
			return
		case approval.AskDuplicateWait:

			m.log.Info("提问重放，复用既有工单并重挂等待", "task", taskID, "ticket", ticketID)
			go m.waitQuestion(ctx, taskID, ticketID)
			return
		default:

			m.log.Info("提问重发（旧单已答），另开新工单", "task", taskID,
				"prior_ticket", ticketID)
			ticketID = approval.AskReissueTicketID()
			if _, err := m.st.CreateTicket(&proto.Ticket{
				ID:	ticketID, TaskID: taskID, Kind: "ask",
				Request:	req, CreatedAt: time.Now().UTC(),
			}); err != nil {
				m.log.Error("创建重发提问工单失败", "task", taskID, "ticket", ticketID, "cause", err)
				m.transitBestEffort(taskID, proto.TaskStateRunning, "提问工单创建失败回滚")
				return
			}
			m.log.Info("提问重发工单已持久化", "task", taskID, "ticket", ticketID,
				"question_id", ev.QuestionID)
		}
	}
	evt, err := m.st.AppendEvent(taskID, proto.EventTypeQuestion, questionPayload{
		TicketID:	ticketID, Question: ev.Text, Kind: "ask",
	})
	if err != nil {
		m.log.Error("追加 question 事件失败", "task", taskID, "ticket", ticketID, "cause", err)
		return
	}
	go m.waitQuestion(ctx, taskID, ticketID)
	m.hub.Publish(evt)
}

n_orchestration_Manager_handleResult.signature:
// handleResult 中介回合结果：OK → completed 事件，!OK → failed 事件；两者都进
// waiting_review（why 见文件头）——失败也交协调者裁决，不自动重试烧 token。
//
// 顺序是「迁移状态 → 追加事件 → 广播」，三步都不能换位：协调者（或脚本）收到
// completed 事件后可能立即执行 continue/done，若状态尚未回迁 waiting_review 会被
// 409 拒绝，所以状态必须先就位。
//
// 为什么迁移必须排在**追加事件**之前，而不只是排在 Publish 之前（2026-08-13 修）：
// 事件有两条送达路径，Publish 只是其中之一。WS 连接建立时的历史重放直接读 store
// （server.go 的 EventsFromAsc），所以事件在 **AppendEvent 落库的那一刻**就已经
// 可被观测——排在迁移之前就等于把「事件到达时状态已就绪」这条保证只留给实时订阅
// 者，任何断线重连、一次性 wait（每轮新建连接）都会撞进窗口。CI 上实测撞到过：
// TestFullLoop 收到第二条 completed 后立刻 Done，得到 409。
//
// 崩溃语义也因此更好：崩在两步之间留下的是「waiting_review 但缺一条 completed」，
// show 出来仍是可裁决的；反过来则是「卡在 running 却已有 completed」，只能等看门狗。
//
// 迁移失败（如并发 done 已抢先归档）则事件也不追加、不广播：任务已终结，既不该
// 唤醒协调者去操作它，也不该给一个已归档的任务再记一条回合结果。
func (m *Manager) handleResult(taskID string, ev executor.AdapterEvent) {
	if ev.Result == nil {
		m.log.Error("result 事件缺 Result", "task", taskID)
		return
	}

	if n := m.takeAutoAllowed(taskID); n > 0 {
		m.log.Info("本段执行自动放行工作区内写入", "task", taskID, "n", n)
	}

	cur, err := m.st.GetTask(taskID)
	if err != nil {
		m.log.Error("读取任务失败", "task", taskID, "cause", err)
		return
	}
	if cur.State == proto.TaskStateCompleted || cur.State == proto.TaskStateFailed {
		m.log.Debug("任务已终结，忽略 result 事件", "task", taskID, "state", cur.State)
		return
	}

	if ev.Result != nil && !ev.Result.OK && cur.State == proto.TaskStateWaitingReview {
		m.log.Warn("回合已收口后到达的失败结果，判为传输层假警报并丢弃",
			"task", taskID, "state", cur.State, "fail_reason", ev.Result.FailReason)
		return
	}
	r := ev.Result

	if r.SessionID != "" {
		if err := m.st.SetTaskField(taskID, "executor_session", r.SessionID); err != nil {
			m.log.Warn("落库 executor_session 失败", "task", taskID, "session", r.SessionID, "cause", err)
		}
	}
	m.log.Debug("回合结果正文已准备传输", "task", taskID,
		"ok", r.OK, "final_text_len", len([]rune(r.FinalText)),
		"final_text_present", r.FinalText != "")

	if err := m.transitToReview(taskID); err != nil {
		m.log.Error("回迁 waiting_review 失败，不追加也不广播结果事件", "task", taskID, "cause", err)
		return
	}
	var evt proto.Event
	if r.OK {
		var finalTextPtr *string
		if r.FinalText != "" {
			finalTextPtr = &r.FinalText
		}
		evt, err = m.st.AppendEvent(taskID, proto.EventTypeCompleted, agentd.CompletedPayload{
			Branch:	r.Branch, CommitHash: r.CommitHash, Summary: r.Summary,
			FinalText:	finalTextPtr,
		})
	} else {

		voidReason := r.VoidReason
		if voidReason == "" {
			voidReason = executor.VoidReasonExecutorGone
		}
		agentd.VoidTicketsWithAudit(m.st, taskID, voidReason, m.log)
		m.log.Warn("回合以失败收尾", "task", taskID, "reason", r.FailReason,
			"branch", r.Branch, "commit", r.CommitHash, "void_reason", voidReason)

		evt, err = m.st.AppendEvent(taskID, proto.EventTypeTurnFailed,
			agentd.NewFailedPayload(r.FailReason, r.Branch, r.CommitHash))
	}
	if err != nil {
		m.log.Error("追加 result 事件失败", "task", taskID, "cause", err)
		return
	}

	m.clearApproverState(taskID)
	m.hub.Publish(evt)

	_ = m.sweep(taskID)
}

n_orchestration_Manager_handleSpend.signature:
// handleSpend 把 executor 报回的「本次新增消耗」记进账本。
//
// 与 handleUsage 的区别（**两条通道必须互不干扰**）：
//   - handleUsage 走 SetTaskUsage，**整体覆盖** (model, tokens, window) 三元组，
//     描述「当前占用」；
//   - 本方法走 UpsertSpend，按幂等键**覆盖单行**后求和，描述「累计消耗」。
//
// 拿任何一条的值去写另一条，都会产生一个不报错、只是数字错的故障。
//
// 与 handleUsage 相同的两点：**只写库，不追加事件行、不广播**（频率同样高，
// 进事件日志会淹没审核者真正要看的 permission/question/completed）；
// 落库失败仅 Warn（用量属可修复的辅助字段，不影响主流程）。
//
// 幂等不做内存去重：内存态在 agentd 重启后为空，首帧必写一次——对「当前占用」
// 无害（覆盖成同值），对「累计」就是重复计数。所以幂等只能落在库里。
func (m *Manager) handleSpend(taskID string, ev executor.AdapterEvent) {
	if ev.Spend == nil {
		return
	}
	if err := m.st.UpsertSpend(taskID, *ev.Spend); err != nil {
		m.log.Warn("记任务消耗失败", "task", taskID, "key", ev.Spend.Key, "cause", err)
		return
	}
	m.log.Debug("任务消耗已入账", "task", taskID, "key", ev.Spend.Key,
		"input", ev.Spend.InputTokens, "cached", ev.Spend.CachedTokens,
		"output", ev.Spend.OutputTokens, "cost_state", ev.Spend.CostState)
}

n_orchestration_Manager_handleTiming.signature:
// handleTiming 把 executor 报回的「这一段耗时」记进耗时账本。
//
// 与 handleSpend 的关系：两者是同一个 usage 事件上的两样产物，处置纪律逐条
// 相同——**只写库，不追加事件行、不广播**（频率同级，进事件日志会淹没审核者
// 真正要看的 permission/question/completed）；落库失败仅 Warn（耗时是辅助
// 字段，不影响主流程）。
//
// 幂等同样只能落在库里：内存态在 agentd 重启后为空，首帧必写一次；对「当前
// 占用」无害，对「累计」就是重复计数（handleSpend 注释里的同一条理由）。
func (m *Manager) handleTiming(taskID string, ev executor.AdapterEvent) {
	if ev.Timing == nil {
		return
	}
	if err := m.st.UpsertTiming(taskID, *ev.Timing); err != nil {
		m.log.Warn("记任务耗时失败", "task", taskID, "key", ev.Timing.Key, "cause", err)
		return
	}
	m.log.Debug("任务耗时已入账", "task", taskID, "key", ev.Timing.Key,
		"kind", ev.Timing.Kind, "turn", ev.Timing.Turn, "dur_ms", ev.Timing.DurMS)
}

n_orchestration_Manager_handleUsage.signature:
// handleUsage 落 executor 报回的实际模型名与 context 占用。
//
// 与 handleProgress 的区别：**只写任务字段，不追加事件行、不广播**。
// 用量刷新频率高（claudecode 一个回合几百条 assistant 消息），进事件日志会淹没
// 审核者真正要看的 permission/question/completed；界面靠详情轮询自然拿到，
// 不需要事件推送。
//
// 去重是写库风暴的唯一防线：与内存里上一次的三元组全等就直接返回。
// agentd 重启后内存态为空，首帧必写一次，这是可接受的代价。
//
// 落库失败仅 Warn：用量属可修复的辅助字段，与 executor_session 同级，
// 不影响主流程。
func (m *Manager) handleUsage(taskID string, ev executor.AdapterEvent) {
	tokens, window := 0, (*int)(nil)
	if ev.Usage != nil {
		tokens = ev.Usage.ContextTokens
		window = ev.Usage.ContextWindow
	}
	if m.takeUsageUnchanged(taskID, ev.ActualModel, tokens, window) {
		return
	}
	if err := m.st.SetTaskUsage(taskID, ev.ActualModel, tokens, window); err != nil {
		m.log.Warn("落库任务用量失败", "task", taskID, "model", ev.ActualModel,
			"tokens", tokens, "cause", err)
		return
	}
	m.log.Info("任务用量已更新", "task", taskID, "model", ev.ActualModel,
		"tokens", tokens, "window", window)
}

n_orchestration_Manager_judgePermission.signature:
// judgePermission 把一次权限事件交给判据权威（internal/approval.Authority.Judge，
// B233.21 迁入），返回裁决；OpenCode 面 bindApproval 的 JudgePermission 钩子
// 绑的也是这里——判据权威只有一份。
//
// gate 为 nil 是构造契约被违反（NewManager 文档已写明不得为 nil）。这一手兜底
// 留在 Manager：手工构造的 Manager（白盒测试）没有权威实例可调，必须先于权威
// 调用 fail-closed，否则会在权限处理 goroutine 里空指针 panic，把整个 agentd
// 带走——那比升级人工严重得多，也违背「fail-closed 无例外」。
func (m *Manager) judgePermission(taskID string, ev executor.AdapterEvent) permgate.Verdict {
	if m.gate == nil {
		m.log.Error("判据网关未装配，fail-closed 升级人工（NewManager 的 gate 不得为 nil）",
			"task", taskID, "perm", ev.PermissionID)
		return permgate.Verdict{Action: permgate.Escalate, Reason: "判据网关未装配"}
	}
	return m.permAuthority.Judge(taskID, ev)
}

n_orchestration_Manager_loadPersistedDis.signature:
// loadPersistedDiscipline 读首派落盘的纪律正文（B229 §2.5.2）。
//
// 参数：taskID 任务 id（正文固定在 <DataDir>/tasks/<id>/discipline.md）
//
// 返回：正文与读取错误。文件不存在按错误原样返回，不与空正文混淆——
// 调用方据任务是否点名裁决（Cold 拒绝 / 热重连不阻断），本层不做策略。
func (m *Manager) loadPersistedDiscipline(taskID string) (string, error) {
	path := filepath.Join(m.cfg.DataDir, "tasks", taskID, disciplineFileName)
	data, err := os.ReadFile(path)
	if err != nil {
		return "", fmt.Errorf("读取 %s: %w", path, err)
	}
	return string(data), nil
}

n_orchestration_Manager_markApproverInfl.signature:
// markApproverInflight 尝试登记 ticket 的审批中状态；返回 false 表示已有同
// ticket 的裁决在途（SSE 重放），本次直接吞掉不重复咨询。
func (m *Manager) markApproverInflight(ticketID string) bool {
	m.apMu.Lock()
	defer m.apMu.Unlock()
	if m.apInflight[ticketID] {
		return false
	}
	m.apInflight[ticketID] = true
	return true
}

n_orchestration_Manager_markDelivered.signature:
// markDelivered 记录「应答已送达 executor」。失败仅 Warn：送达本身已经发生，
// 标记丢失最坏只会让 RecoverStuck 多重投一次，不影响正确性。
func (m *Manager) markDelivered(taskID, ticketID string) {
	if err := m.st.MarkTicketDelivered(ticketID); err != nil {
		m.log.Warn("标记应答已送达失败", "task", taskID, "ticket", ticketID, "cause", err)
	}
}

n_orchestration_Manager_mediate.signature:
// mediate 是单任务的事件中介循环（每任务一个 goroutine，由 Dispatch 启动）：
// 消费 Adapter.Events 直到通道关闭（Stop），每类事件交给对应 handler。
//
// 任务级 ctx 与取消时机（P1-2）：taskCtx 供 waitPermission/waitQuestion 的应答
// 等待共用，中介循环退出（adapter 事件通道关闭 = 执行终结：Done/Stop/serve 死亡）
// 时 defer cancel 取消全部在等应答的 waiter——否则「协调者永不回答 + 执行终结」
// 的组合会让 wait goroutine 用 context.Background() 永久挂死。
//
// 为什么不在 result 到达时取消：result → waiting_review 后任务仍活（协调者可
// continue/回答挂起工单），回答晚于 result 到达是合法流程（应答后 executor 被
// 唤醒续跑，见 TestTransitToReviewTwoHopFromWaitingAnswer）——只有「事件通道
// 关闭」这一执行终结信号才是取消时机。
func (m *Manager) mediate(taskID string) {
	m.log.Info("中介循环启动", "task", taskID)
	taskCtx, cancelTask := context.WithCancel(context.Background())
	defer cancelTask()
	ad, err := m.adapterFor(taskID)
	if err != nil {

		m.log.Error("中介循环无法路由执行者", "task", taskID, "cause", err)
		return
	}
	events := ad.Events(taskID)
	for ev := range events {
		m.handleEvent(taskCtx, taskID, ev)
	}

	if m.takeStopping(taskID) {
		m.log.Info("中介循环结束（主动停止，跳过对账）", "task", taskID)
		return
	}
	m.log.Info("中介循环结束，开始对账", "task", taskID)
	m.reconcileExecutorGone(taskID, "executor 事件流已终结（进程退出或连接断开）")
}

n_orchestration_Manager_noteAutoAllowed.signature:
// noteAutoAllowed 累计一次自动放行。
func (m *Manager) noteAutoAllowed(taskID string) {
	m.aaMu.Lock()
	defer m.aaMu.Unlock()
	m.aaCount[taskID]++
}

n_orchestration_Manager_noteDenyGuidance.signature:
// noteDenyGuidance 登记一条待下发的拒绝原因。
//
// 参数：taskID 为任务 id；reason 为协调者给出的原因（空串直接忽略）
//
// 为什么不立刻 Send：executor 收到 reject 会当场终结回合（opencode 实测），
// 此刻发消息会撞上正在终结的回合，而回合终结时 adapter 还会补一条兜底提问——
// 协调者刚说完怎么改，又被问一遍「请给出下一步指令」。挂起到下一条 question
// 到达时再下发，正好用那次机会开新回合。
func (m *Manager) noteDenyGuidance(taskID, reason string) {
	if strings.TrimSpace(reason) == "" {
		return
	}
	m.apMu.Lock()
	m.denyGuidance[taskID] = reason
	m.apMu.Unlock()
	m.log.Info("登记待下发的拒绝原因", "task", taskID,
		"reason", agentd.TruncateRunes(reason, 80))
}

// noteDenyGuidanceUnlessInBand 按 executor 的送达能力决定要不要挂起拒绝理由。
//
// 参数：taskID / permID 用于日志定位；reason 为协调者给出的原因
//
// executor 已把理由与裁决同帧送达时直接返回：再挂一份会让模型先在 tool_result
// 里读到理由、下一条 question 时又被同一条理由砸一次。
func (m *Manager) noteDenyGuidanceUnlessInBand(taskID, permID, reason string) {
	if m.denyReasonDelivered(taskID) {
		m.log.Debug("拒绝理由已与裁决同帧送达，跳过带外挂起",
			"task", taskID, "perm", permID)
		return
	}

	m.noteDenyGuidance(taskID, reason)
}

n_orchestration_Manager_noteStopping.signature:
// noteStopping 标记「接下来这次事件通道关闭是我们自己发起的」。
//
// 必须在 ad.Stop() **之前**调用。
//
// why（为什么需要这个标记）：Manager.Stop 先调 ad.Stop() 再落 failed，两步之间
// adapter 已经关掉了事件通道，mediate 随之退出并对账——此时任务状态还是 running，
// 于是补一条它不该有的 failed 事件，并造成 running→waiting_review→failed 的
// 状态抖动（末跳合法，所以不硬失败，但事件是噪音）。
//
// why（为什么不改 Stop 的顺序）：先落 failed 再 ad.Stop() 会让 executor 在状态
// 已定型后仍可能产出事件，各 handler 的「已终结则丢弃」判断要散在更多路径上，
// 风险大于收益。显式标记说的正是「这次关闭是我们自己关的」，诚实且局部。
func (m *Manager) noteStopping(taskID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.stopping[taskID] = struct{}{}
}

n_orchestration_Manager_noteSweepOwned.signature:
// noteSweepOwned 认领本任务的终态清扫：调用方保证自己会调 sweepAfterStop，
// transit 的终态分支据此跳过兜底清扫。必须在调用方自己的 transit 之前调用。
//
// 参数：taskID 为目标任务
func (m *Manager) noteSweepOwned(taskID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.sweepOwned[taskID] = struct{}{}
}

n_orchestration_Manager_notifyOrphanRisk.signature:
// notifyOrphanRisk 追加一条「executor 可能残留」的 progress 事件并广播。
//
// 参数：
//   - taskID: 目标任务
//   - text: 面向协调者的正文；给的必须是「下一步做什么」而不是「出了什么错」
//
// 注意：
//   - 追加失败只记日志、不返回错误：调用方全都处在归档/中止的收尾路径上，
//     那件事本身已经达成，不该因为发不出提示而中断
func (m *Manager) notifyOrphanRisk(taskID, text string) {
	evt, err := m.st.AppendEvent(taskID, proto.EventTypeProgress, agentd.ProgressPayload{Text: text})
	if err != nil {
		m.log.Error("追加 executor 残留提示事件失败", "task", taskID, "cause", err)
		return
	}
	m.hub.Publish(evt)
	m.log.Info("已向协调者发出 executor 残留提示", "task", taskID)
}

n_orchestration_Manager_persistProject.signature:
// persistProject 把一条位置落库：算 project_id、定引用名、翻译冲突哨兵。
func (m *Manager) persistProject(name, path, origin string) (proto.ProjectLocation, error) {

	absPath, err := filepath.Abs(filepath.Clean(path))
	if err != nil {
		m.log.Warn("登记落库被拒：路径无法归一化为绝对路径", "path", path, "cause", err)
		return proto.ProjectLocation{}, fmt.Errorf("%w: 归一化路径 %s: %v", agentd.ErrBadDispatchRequest, path, err)
	}
	path = absPath
	pid := projectid.FromOrigin(origin)
	if pid == "" {
		m.log.Warn("登记落库被拒：origin 算不出 project_id", "origin", origin, "path", path)
		return proto.ProjectLocation{}, fmt.Errorf("%w: origin %q 归一化后为空，算不出项目身份",
			agentd.ErrBadDispatchRequest, origin)
	}
	entries, err := m.st.ListProjectLocations()
	if err != nil {
		m.log.Error("登记落库前读位置表失败", "cause", err)
		return proto.ProjectLocation{}, err
	}

	for _, e := range entries {
		if e.ProjectID == pid {
			m.log.Warn("登记被拒：该项目在本机已有位置",
				"project_id", pid, "existing", e.Path, "requested", path)
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: 项目 %s 在本机已登记于 %s；要换位置先 handoff project rm %s",
				workspace.ErrProjectAlreadyExists, e.Name, e.Path, e.Name)
		}
	}
	if name == "" {
		name = workspace.ProjectNameFromURL(origin)
	}
	if err := workspace.ValidateProjectName(name); err != nil {
		m.log.Warn("登记落库被拒：项目名非法", "name", name, "cause", err)
		return proto.ProjectLocation{}, err
	}
	name, err = uniqueProjectName(name, entries)
	if err != nil {
		m.log.Warn("登记落库被拒：名字退让次数用尽", "name", name, "cause", err)
		return proto.ProjectLocation{}, err
	}
	loc := proto.ProjectLocation{
		ProjectID:	pid, Name: name, Path: path,
		OriginURL:	origin, CreatedAt: time.Now(),
	}
	if err := m.st.CreateProjectLocation(&loc); err != nil {
		if errors.Is(err, store.ErrProjectDuplicate) {
			m.log.Warn("登记被拒：项目/名字/路径已被占用",
				"project_id", pid, "name", name, "path", loc.Path, "cause", err)
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: 项目 %s、名字 %q 或路径 %s 已被登记（handoff project ls 查看）",
				workspace.ErrProjectAlreadyExists, pid, name, loc.Path)
		}
		m.log.Error("登记落库失败", "name", name, "path", loc.Path, "cause", err)
		return proto.ProjectLocation{}, err
	}
	m.log.Info("项目位置登记完成",
		"project_id", pid, "name", name, "path", loc.Path, "origin", origin)
	loc.Status = workspace.ProjectStatusOK
	return loc, nil
}

n_orchestration_Manager_prepareTaskProfi.signature:
// prepareTaskProfile 把 StartReq.Discipline 的唯一权威正文交给执行 Profile 的任务层。
//
// 参数：start 是普通任务启动装配结果，纪律正文只从 start.Discipline 读取。
// 返回：空纪律直接成功；非空纪律若缺 HomeDir/Profile 或 Prepare 未报告成功则返回
// 错误，调用方必须在启动 executor 前将任务置 failed。注意：不从本地纪律目录回退，
// 也不修改载体全局规则文件。
func (m *Manager) prepareTaskProfile(ctx context.Context, start executor.StartReq) error {
	if strings.TrimSpace(start.Discipline) == "" {
		m.log.Info("任务纪律为空，跳过 Profile overlay", "task", start.Task.ID,
			"executor", start.Task.Executor, "overlay_skipped", true)
		return nil
	}
	provider, ok := m.ads[start.Task.Executor].(executor.Provider)
	if !ok {
		return fmt.Errorf("task=%q executor=%q home=%q 不提供 Profile 能力",
			start.Task.ID, start.Task.Executor, start.Task.HomeDir)
	}
	profile, ok := executor.ProfileFromProvider(provider)
	if !ok || profile == nil {
		return fmt.Errorf("task=%q executor=%q home=%q 没有 Profile 能力",
			start.Task.ID, start.Task.Executor, start.Task.HomeDir)
	}

	writePoint, err := taskProfileHome(start.Task.HomeDir)
	if err != nil {
		m.log.Error("任务纪律 overlay 写入点解析失败", "task", start.Task.ID,
			"executor", start.Task.Executor, "home", start.Task.HomeDir, "cause", err)
		return fmt.Errorf("task=%q executor=%q home=%q 解析纪律写入点: %w",
			start.Task.ID, start.Task.Executor, start.Task.HomeDir, err)
	}
	req := executor.ProfileReq{
		HomeDir:	writePoint,
		Isolated:	start.Task.HomeDir != "",
		TaskOverlay: []executor.ProfileFile{{
			Name:	filepath.Join(start.Task.ID, disciplineFileName), Content: start.Discipline,
		}},
	}
	m.log.Info("任务 Profile overlay 准备开始", "task", start.Task.ID,
		"executor", start.Task.Executor, "home", start.Task.HomeDir, "write_point", writePoint,
		"isolated", req.Isolated, "overlay_count", len(req.TaskOverlay),
		"content_bytes", len(start.Discipline))
	rep, err := profile.Prepare(ctx, req)
	if err != nil {
		m.log.Error("任务 Profile overlay 准备失败", "task", start.Task.ID,
			"executor", start.Task.Executor, "home", start.Task.HomeDir,
			"write_point", writePoint, "cause", err)
		return fmt.Errorf("task=%q executor=%q home=%q Profile.Prepare: %w",
			start.Task.ID, start.Task.Executor, start.Task.HomeDir, err)
	}
	if !rep.Prepared {
		err := fmt.Errorf("Profile.Prepare 返回 Prepared=false")
		m.log.Error("任务 Profile overlay 未准备完成", "task", start.Task.ID,
			"executor", start.Task.Executor, "home", start.Task.HomeDir,
			"write_point", writePoint, "cause", err)
		return fmt.Errorf("task=%q executor=%q home=%q: %w", start.Task.ID,
			start.Task.Executor, start.Task.HomeDir, err)
	}
	m.log.Info("任务 Profile overlay 准备完成", "task", start.Task.ID,
		"executor", start.Task.Executor, "home", start.Task.HomeDir, "write_point", writePoint,
		"overlay_count", len(req.TaskOverlay), "content_bytes", len(start.Discipline))
	return nil
}

n_orchestration_Manager_probeActive.signature:
// probeActive 对每个非终结任务做一次只读探活，共享一份总时限预算。
func (m *Manager) probeActive(tasks []proto.Task) []proto.ActiveTask {
	out := make([]proto.ActiveTask, 0, len(tasks))
	deadline := time.Now().Add(probeTotalTimeout)
	for _, t := range tasks {
		at := proto.ActiveTask{
			ID:	t.ID, Name: t.Name, State: string(t.State),
			Executor:	t.Executor, RepoPath: t.RepoPath,
		}

		if at.Executor == "" {
			at.Executor = m.conf().Executor.Default
		}

		w := m.hub.Watchers(t.ID)
		at.Watchers = &w
		at.Live, at.Note = m.probeOne(t, time.Until(deadline))

		if ad, aerr := m.adapterFor(t.ID); aerr == nil {
			if fp, ok := ad.(footprinter); ok {
				taskDir := filepath.Join(m.cfg.DataDir, "tasks", t.ID)
				if h, herr := fp.ProcHandle(t.ID, taskDir); herr == nil {
					if members, v, ferr := prochost.Footprint(h); ferr == nil && v == prochost.VerdictOK {
						n := len(members)
						at.Procs = &n
					} else {
						m.log.Debug("状态聚合：足迹判定不可用，该任务 procs 留空",
							"task", t.ID, "verdict", string(v), "cause", ferr)
					}
				}
			}
		}
		out = append(out, at)
	}
	return out
}

n_orchestration_Manager_probeOne.signature:
// probeOne 对单个任务做一次只读探活，返回三态之一与一句话理由。
//
// 参数：
//   - budget: 本次探测可用的时限（受总预算约束，上限 probeTimeout）
//
// 注意：
//   - **超时归 unknown，不归 dead**。假阳性是诊断命令最贵的失败模式——一条会
//     说谎的诊断命令比没有更糟，因为你会信它
//   - 探测在 goroutine 里跑、用带缓冲的通道回收结果：超时后那个 goroutine 仍
//     能把结果写进缓冲并正常退出，不会泄漏；底层探针本身也都是有界的
//     （HTTP 客户端带超时、探活秒回）
func (m *Manager) probeOne(t proto.Task, budget time.Duration) (live, note string) {
	if budget <= 0 {
		m.log.Warn("状态探活：总时限已用尽，该任务记为未知", "task", t.ID)
		return proto.LiveUnknown, "探活总时限已用尽"
	}
	if budget > probeTimeout {
		budget = probeTimeout
	}
	ad, err := m.adapterFor(t.ID)
	if err != nil {
		m.log.Warn("状态探活：执行者未注册，结论未知", "task", t.ID, "cause", err)
		return proto.LiveUnknown, fmt.Sprintf("执行者未注册：%v", err)
	}
	pr, ok := ad.(prober)
	if !ok {
		m.log.Info("状态探活：该 adapter 不支持探活，结论未知", "task", t.ID)
		return proto.LiveUnknown, "该执行者不支持探活"
	}

	type result struct {
		out	executor.ProbeOutcome
		err	error
	}
	ch := make(chan result, 1)
	go func() {
		o, e := pr.Probe(executor.ProbeReq{
			TaskID:		t.ID,
			TaskDir:	filepath.Join(m.cfg.DataDir, "tasks", t.ID),
			SessionID:	t.ExecutorSession,
		})
		ch <- result{o, e}
	}()

	select {
	case r := <-ch:
		if r.err != nil {
			m.log.Warn("状态探活：探针失败，结论未知", "task", t.ID, "cause", r.err)
			return proto.LiveUnknown, fmt.Sprintf("探活失败：%v", r.err)
		}
		if r.out.Alive {
			m.log.Info("状态探活：executor 存活", "task", t.ID)
			return proto.LiveAlive, ""
		}
		m.log.Info("状态探活：executor 已不在", "task", t.ID, "note", r.out.Note)
		return proto.LiveDead, r.out.Note
	case <-time.After(budget):
		m.log.Warn("状态探活：超时，结论未知（不判死）", "task", t.ID, "budget", budget)
		return proto.LiveUnknown, "探活超时"
	}
}

n_orchestration_Manager_purgeTaskCache.signature:
// purgeTaskCache 尝试删除该任务的两处缓存叶子。失败只打日志。
func (m *Manager) purgeTaskCache(taskID string) {
	if m.log != nil {
		m.log.Info("缓存清理进入", "task", taskID)
	}
	if m.cfg == nil || m.st == nil {
		if m.log != nil {
			m.log.Error("缓存清理缺少 cfg 或 store", "task", taskID)
		}
		return
	}
	tasks, err := m.st.ListTasks()
	if err != nil {
		if m.log != nil {
			m.log.Error("缓存清理读任务表失败", "task", taskID, "cause", err)
		}
		return
	}
	for _, leaf := range cacheplan.PlanTaskCacheLeaves(m.cfg.DataDir, taskID, tasks) {
		if leaf.Skip {
			if m.log != nil {
				m.log.Info("缓存叶子已跳过", "task", taskID, "path", leaf.Path, "kind", leaf.Kind, "reason", leaf.Note)
			}
			continue
		}
		if cacheplan.IsTmpRoot(m.cfg.DataDir, leaf.Path) {
			if m.log != nil {
				m.log.Error("缓存叶子命中 tmp 根，拒绝删除", "task", taskID, "path", leaf.Path)
			}
			continue
		}
		if m.log != nil {
			m.log.Info("缓存叶子删除前", "task", taskID, "path", leaf.Path, "kind", leaf.Kind)
		}
		if err := m.removeCacheLeaf(leaf.Path); err != nil {
			if m.log != nil {
				m.log.Error("缓存叶子删除失败", "task", taskID, "path", leaf.Path, "kind", leaf.Kind, "cause", err)
			}
			continue
		}
		if m.log != nil {
			m.log.Info("缓存叶子已删除", "task", taskID, "path", leaf.Path, "kind", leaf.Kind)
		}
	}
	if m.log != nil {
		m.log.Info("缓存清理完成", "task", taskID)
	}
}

n_orchestration_Manager_questionIDFromTi.signature:
// questionIDFromTicket 从持久工单恢复原生问题身份。
//
// 参数：taskID 与 ticketID 用于校验归属并识别旧版命名工单。
// 返回：持久化的 QuestionID；旧版 taskID:nativeID 工单可从命名空间兼容恢复，
// uuid 工单返回空串。读取或 JSON 解析失败时返回错误。
// 注意：uuid 工单主键没有原生身份，不能把 uuid 猜成 QuestionID。
func (m *Manager) questionIDFromTicket(taskID, ticketID string) (string, error) {
	tk, err := m.st.GetTicket(ticketID)
	if err != nil {
		m.log.Error("读取提问工单失败", "task", taskID, "ticket", ticketID, "cause", err)
		return "", fmt.Errorf("读取提问工单 %s: %w", ticketID, err)
	}
	if tk.TaskID != taskID {
		err := fmt.Errorf("工单 %s 不属于任务 %s", ticketID, taskID)
		m.log.Error("提问工单归属校验失败", "task", taskID, "ticket", ticketID, "cause", err)
		return "", err
	}
	var req ticketRequest
	if err := json.Unmarshal(tk.Request, &req); err != nil {
		m.log.Error("解析提问工单 JSON 失败", "task", taskID, "ticket", ticketID, "cause", err)
		return "", fmt.Errorf("解析提问工单 %s 请求体: %w", ticketID, err)
	}
	if req.QuestionID != "" {
		m.log.Info("从提问工单恢复原生身份", "task", taskID, "ticket", ticketID,
			"question_id", req.QuestionID)
		return req.QuestionID, nil
	}
	prefix := taskID + ":"
	if strings.HasPrefix(ticketID, prefix) && len(ticketID) > len(prefix) {
		native := executor.NativeIDFromTicket(taskID, ticketID)
		m.log.Info("从旧版命名提问工单恢复原生身份", "task", taskID, "ticket", ticketID,
			"question_id", native)
		return native, nil
	}
	m.log.Info("提问工单无原生身份", "task", taskID, "ticket", ticketID)
	return "", nil
}

n_orchestration_Manager_reconcileExecuto.signature:
// reconcileExecutorGone 是 gateway 包级同名函数的方法薄包装（省去调用点重复传 st/hub/log）。
// B233.13：实现留 gateway（watchdog 仍用），编排经 agentd.ReconcileExecutorGone 调用。
