n_orchestration_Manager_reconcileInto.signature:
// reconcileInto 执行一次会话对账并把结论写进报告（B38）。
//
// 参数：
//   - rep: 待填充的报告；本函数只写 Reconciled/TurnEnded/Emitted/State/Note
//   - taskID / state: 目标任务与其当前状态
//
// 注意：
//   - 只对 running / waiting_answer 生效。其余状态如实说明而不是静默成功：
//     pending 尚未启动、waiting_review 本就该走 continue/done、终态已结束
//   - adapter 未实现 reconciler 时不改状态、不伪装成「对账过了」
//   - 对账失败只记 WARN 并把原因写进 Note，**不返回错误**——协调者要的是
//     「现在怎么办」，不是一个让 CLI 退非零的堆栈
func (m *Manager) reconcileInto(rep *agentd.RecoverReport, taskID string, state proto.TaskState) {
	if state != proto.TaskStateRunning && state != proto.TaskStateWaitingAnswer {
		rep.Note = fmt.Sprintf("没有卡在半路的应答；任务处于 %s，不在对账范围"+
			"（pending 尚未启动、waiting_review 请用 continue/done）", state)
		m.log.Info("恢复操作：状态不在对账范围", "task", taskID, "state", state)
		return
	}
	ad, err := m.adapterFor(taskID)
	if err != nil {
		rep.Note = "没有卡在半路的应答；解析任务执行者失败（" + err.Error() +
			"），可 handoff attach 查看现场，或 handoff resume --force 强制收口交审核"
		m.log.Warn("恢复操作：解析任务执行者失败", "task", taskID, "cause", err)
		return
	}
	rc, ok := ad.(reconciler)
	if !ok {
		rep.Note = "没有卡在半路的应答；当前 executor 不支持会话对账，" +
			"可 handoff attach 查看现场，或 handoff resume --force 强制收口交审核"
		m.log.Info("恢复操作：adapter 不支持对账", "task", taskID)
		return
	}
	out, err := rc.Reconcile(context.Background(), taskID)
	if err != nil {
		rep.Note = "没有卡在半路的应答；会话对账失败（" + err.Error() +
			"），未改动任何状态，可稍后重试或 --force 强制收口"
		m.log.Warn("恢复操作：会话对账失败", "task", taskID, "cause", err)
		return
	}
	rep.Reconciled = true
	rep.TurnEnded = out.TurnEnded
	rep.Emitted = out.Emitted
	rep.Note = out.Note
	if out.Emitted > 0 {

		if t, gerr := m.st.GetTask(taskID); gerr == nil {
			rep.State = t.State
		}
	}
	m.log.Info("恢复操作：会话对账完成", "task", taskID,
		"turn_ended", out.TurnEnded, "emitted", out.Emitted, "note", out.Note)
}

n_orchestration_Manager_registerAtPath.signature:
// registerAtPath 处理 Path 非空的请求：按目录是否存在在「登记已有仓」与
// 「clone 到该 Path」间分派。
//
// 目录不存在时：无 OriginURL → 400（无 URL 无法创建）；有 OriginURL →
// cloneToPathAndRegister。目录存在时一律走 registerExistingProject——
// 绝不往已存在的目录里 clone（那里是不是仓库、是不是本项目，由 inspect 校验说）。
func (m *Manager) registerAtPath(ctx context.Context, req workspace.RegisterProjectReq) (proto.ProjectLocation, error) {
	_, err := os.Stat(req.Path)
	if errors.Is(err, os.ErrNotExist) {
		if req.OriginURL == "" {
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: 路径 %s 不存在，且未提供 origin_url，无法 clone",
				agentd.ErrBadDispatchRequest, req.Path)
		}
		return m.cloneToPathAndRegister(ctx, req)
	}
	if err != nil {
		return proto.ProjectLocation{}, fmt.Errorf("%w: 探查路径 %s: %v", agentd.ErrRepoUnusable, req.Path, err)
	}
	return m.registerExistingProject(ctx, req)
}

n_orchestration_Manager_registerExisting.signature:
// registerExistingProject 登记本机上已存在的一份代码（Path 已确认存在）。
//
// OriginURL 可空：空时采用 InspectRepoDir 现读的 actual 作为项目身份与落库值
// （Web「只填 path」主路径——磁盘上的仓库本身就是权威，不要求调用方复述）；
// 非空时仅作一致性校验，不一致仍报 ErrProjectOriginMismatch。
// 落库 origin 永远用 actual，不采信请求串里未校验的写法。
func (m *Manager) registerExistingProject(ctx context.Context, req workspace.RegisterProjectReq) (proto.ProjectLocation, error) {
	root, actual, err := m.InspectRepoDir(ctx, req.Path)
	if err != nil {
		return proto.ProjectLocation{}, err
	}
	if req.OriginURL == "" {
		m.log.Info("登记已有目录（origin 由磁盘现读）", "path", root, "origin", actual)
	} else if projectid.FromOrigin(actual) != projectid.FromOrigin(req.OriginURL) {

		m.log.Warn("登记被拒：路径上的仓库不是请求的项目",
			"path", root, "actual_origin", actual, "want_origin", req.OriginURL)
		return proto.ProjectLocation{}, fmt.Errorf(
			"%w: %s 上的 origin 是 %s，而请求的项目是 %s；换个路径，或去掉 --path 让本机自己 clone",
			workspace.ErrProjectOriginMismatch, root, actual, req.OriginURL)
	}

	pid := projectid.FromOrigin(actual)
	if pid != "" {
		if existing, ok, err := m.registeredProjectByID(pid); err != nil {
			return proto.ProjectLocation{}, err
		} else if ok {
			if workspace.SameLocation(existing.Path, root) {
				m.log.Info("项目位置已存在，幂等返回",
					"project_id", existing.ProjectID, "name", existing.Name, "path", existing.Path)
				existing.Status = workspace.ProjectStatusOK
				return existing, nil
			}

			m.log.Warn("登记被拒：该项目在本机已有位置",
				"project_id", pid, "existing", existing.Path, "requested", root)
			return proto.ProjectLocation{}, fmt.Errorf(
				"%w: 项目 %s 在本机已登记于 %s；要换位置先 handoff project rm %s",
				workspace.ErrProjectAlreadyExists, existing.Name, existing.Path, existing.Name)
		}
	}
	return m.persistProject(req.Name, root, actual)
}

n_orchestration_Manager_registeredProjec.signature:
// registeredProjectByID 在位置表里按 project_id 查已登记的位置。
//
// 返回：
//   - 命中条目的拷贝；未命中时零值
//   - 是否命中
//   - 查库失败时的错误
//
// 为什么单独抽一个助手：登记是**幂等**操作，clone 形态与已有目录形态都要在
// 各自流程的合适节点查一次表（clone 形态要在 clone 之前，已有目录形态要在
// 归并+读 origin+校验之后），两边共用同一条「查表 + 按 project_id 匹配」逻辑。
func (m *Manager) registeredProjectByID(pid string) (proto.ProjectLocation, bool, error) {
	entries, err := m.st.ListProjectLocations()
	if err != nil {
		m.log.Error("登记前读位置表失败", "cause", err)
		return proto.ProjectLocation{}, false, err
	}
	for _, e := range entries {
		if e.ProjectID == pid {
			return e, true, nil
		}
	}
	return proto.ProjectLocation{}, false, nil
}

n_orchestration_Manager_relayDenyGuidanc.signature:
// relayDenyGuidance 把协调者的拒绝原因作为一条普通消息下发给 executor，开新回合。
//
// 正文渲染与 claude 的同帧送达共用 turn.DenyGuidanceText，两条路措辞必须一致。
//
// 注意：
//   - **不得触碰状态机**：本分支不建工单，落 waiting_answer 会造出「等你回答却
//     零挂起工单」的死形态（reply/continue/done 三条路全封死）。任务保持 running
//   - Send 失败只记 Error + 审计事件：executor 此刻没有在等任何应答，
//     发不出去不会让任何东西挂死，协调者可用 continue 自己把话带上
func (m *Manager) relayDenyGuidance(ctx context.Context, taskID, guidance string) {
	text := turn.DenyGuidanceText(guidance)
	ad, err := m.adapterFor(taskID)
	if err != nil {
		m.log.Error("下发拒绝原因：解析执行者失败", "task", taskID, "cause", err)
		m.appendGuidanceDropped(taskID, guidance, err)
		return
	}
	actx, acancel := unaryCtx(ctx)
	defer acancel()
	if err := ad.Send(actx, taskID, text); err != nil {
		m.log.Error("下发拒绝原因失败", "task", taskID, "cause", err)
		m.appendGuidanceDropped(taskID, guidance, err)
		return
	}
	if _, err := m.st.AppendEvent(taskID, proto.EventTypeDenyGuidanceRelayed,
		denyGuidancePayload{Reason: guidance}); err != nil {
		m.log.Error("追加 deny_guidance_relayed 事件失败", "task", taskID, "cause", err)
	}
	m.log.Info("拒绝原因已下发，executor 将据此开新回合", "task", taskID,
		"reason", agentd.TruncateRunes(guidance, 80))
}

n_orchestration_Manager_removeCacheLeaf.signature:
func (m *Manager) removeCacheLeaf(path string) error {
	if m.removeCacheLeafFn != nil {
		return m.removeCacheLeafFn(path)
	}
	return os.RemoveAll(path)
