	}
	return os.WriteFile(filepath.Join(dir, name), data, 0o600)
}

n_orchestration_NewApprover.signature:
// NewApprover 构造审批者。
//
// 参数：
//   - cfg: 审批者配置；cfg.Executor 为空表示不启用审批链，返回 (nil, nil)
