n_orchestration_NewManager.signature:
// NewManager 创建任务管理器。
//
// 参数：
//   - st: 持久化存储（任务/事件/工单的唯一落库点）
//   - hub: 进程内实时路由（事件广播 + ticket 应答等待）
//   - ads: executor 注册表（name → Adapter，如 {"opencode": ..., "fake": ...}）；
//     任务按 executor 名路由，缺省名取 cfg.Executor.Default
//   - cfg: 配置**快照**。运行期可变的字段（Executor / Targets）不要直接读它，
//     走 m.conf()——Server.SetManager 会把活取值函数注入进来（B160 §4.2）
//   - envMapping: 取当前 env 文件映射的函数（生产上传 (*Server).EnvMapping）；
//     nil 时所有 agent 都不注入环境变量
//   - approver: 审批链裁决器；nil=不启用
//   - gate: 权限判据网关；**不得为 nil**，它与 approver 是否启用无关
//   - log: 本模块日志入口
//
// 注意：
//   - 调用方须保证 log 为统一配置后的 logger；st/hub 必须已就绪
//   - B229 起本机不做任何纪律解析（收文即用），机器级 Discipline 映射不再进
//     Manager；映射的保存与回显仍归 Server 的 /api/discipline 端点
func NewManager(st *store.Store, hub *agentd.Hub, ads map[string]executor.Adapter, cfg *config.Config,
	envMapping func() map[string]string,
	approver *Approver, gate *permgate.Gate, log *slog.Logger) *Manager {
	env := envfile.NewResolver(envfile.Dir(cfg.DataDir), envMapping, log)
	m := &Manager{
		st:	st, hub: hub, ads: ads, cfg: cfg,
		appendEvent:	st.AppendEvent,
		conf:		func() *config.Config { return cfg },
		approver:	approver, gate: gate, log: log,
		env:		env,
		apInflight:	map[string]bool{},
		apFails:	map[string]int{},
		apDisabled:	map[string]bool{},
		denyGuidance:	map[string]string{},
		aaCount:	map[string]int{},
		stopping:	map[string]struct{}{},
		sweepOwned:	map[string]struct{}{},
		reg:		registryFromAds(ads),
	}

	m.permAuthority = approval.NewAuthority(approval.AuthorityHooks{
		Log:			log,
		Store:			st,
		Gate:			gate,
		DataDir:		cfg.DataDir,
		AuditAutoAllow:		m.auditAutoAllowOnly,
		DeliverAutoAllow:	m.deliverAutoAllowOnce,
	})
	if m.log != nil {
		names := make([]string, 0, len(ads))
		for n := range ads {
			names = append(names, n)
		}
		m.log.Info("能力 Registry 已从 ads 推导", "n", len(ads), "registered", names)
	}
	return m
}

n_orchestration_PathEqual.signature:
// PathEqual 报告两路径 Clean 后是否相等。
func PathEqual(a, b string) bool {
	return filepath.Clean(a) == filepath.Clean(b)
}

n_orchestration_PlanTaskCacheLeaves.signature:
// PlanTaskCacheLeaves 给出该任务两处缓存叶子的删除计划。
// 遗留叶子也做 tmp 根保护：filepath.Join+Clean 能把 taskID=".." 拼成 DataDir/tmp。
func PlanTaskCacheLeaves(dataDir, taskID string, tasks []proto.Task) []LeafPlan {
	plan := func(path, kind string, skip bool, note string) LeafPlan {
		return LeafPlan{TaskID: taskID, Path: path, Kind: kind, Skip: skip, Note: note}
	}
	var out []LeafPlan
	active := ActiveLeaf(dataDir, taskID)
	switch {
	case IsTmpRoot(dataDir, active):
		out = append(out, plan(active, "active", true, "拒绝删除 DataDir/tmp 根"))
	case ActiveLeafOccupied(tasks, taskID):
		out = append(out, plan(active, "active", true, "短号被其他非终态任务占用"))
	default:
		out = append(out, plan(active, "active", false, ""))
	}
	legacy := LegacyLeaf(dataDir, taskID)
	if IsTmpRoot(dataDir, legacy) {
		out = append(out, plan(legacy, "legacy", true, "拒绝删除 DataDir/tmp 根"))
	} else {
		out = append(out, plan(legacy, "legacy", false, ""))
	}
	return out
}

n_orchestration_RegistryFromAds.signature:
// RegistryFromAds 从 ads 全表推导能力 Registry。
// 仅保留实现了 executor.Provider 的 adapter，重名以后者为准。
func RegistryFromAds(ads map[string]executor.Adapter) *executor.Registry {
	return registryFromAds(ads)
}

n_orchestration_SumRegularFileBytes.signature:
// SumRegularFileBytes 累加 root 下普通文件字节。WalkDir 不跟随目录 symlink；
// d.Info() 描述链接本身而非目标，因此不会把 symlink 当普通文件计入。
func SumRegularFileBytes(root string) (int64, error) {
	var sum int64
	err := filepath.WalkDir(root, func(_ string, d fs.DirEntry, err error) error {
		if err != nil {
			if errors.Is(err, fs.ErrNotExist) {
				return nil
			}
			return err
		}
		if d.IsDir() {
			return nil
		}
		info, ierr := d.Info()
		if ierr != nil {
			if errors.Is(ierr, fs.ErrNotExist) {
				return nil
			}
			return ierr
		}
		if info.Mode().IsRegular() {
			sum += info.Size()
		}
		return nil
	})
	if err != nil && errors.Is(err, fs.ErrNotExist) {
		return 0, nil
	}
	return sum, err
}

n_orchestration_TmpRoot.signature:
// TmpRoot 返回 DataDir/tmp 根。
func TmpRoot(dataDir string) string {
	return filepath.Join(dataDir, "tmp")
}

n_orchestration_WarnIfKillModeUnsafe.signature:
// WarnIfKillModeUnsafe 在 agentd 启动期检查 systemd KillMode 并按需告警。
//
// 注意：
//   - 只打日志，绝不阻断启动（见文件头边界）
//   - 非 systemd 环境完全静默——macOS 开发机是主要使用场景，不能有噪声
func WarnIfKillModeUnsafe(log *slog.Logger) {
	unit, mode, ok := killModeFromCgroup(os.ReadFile, systemctlKillMode)
	if !ok {
		log.Debug("未在 systemd unit 下运行，跳过 KillMode 自检")
		return
	}
	if mode == "process" {
		log.Info("systemd KillMode 配置正确，agentd 重启不会连坐执行者", "unit", unit, "kill_mode", mode)
		return
	}
	log.Warn("systemd KillMode 非 process：agentd 重启会连同执行者一起杀掉，"+
		"正在跑的任务会中断。请在 unit 里设 KillMode=process（模板见 deploy/handoff-agentd.service）",
		"unit", unit, "kill_mode", mode)
}

n_orchestration_decideBranchAction.signature:
// decideBranchAction 判定补偿路径是否可以删除该分支。纯函数：不调 git、不打日志、
// 不碰任何状态，故可以被表驱动测试穷举。
//
// 参数：
//   - recordedTip: PrepareWorkspace 建分支时记下的尖端；空串 = 分支不是本次新建的
//   - currentTip:  当前尖端；tipErr 非 nil 时其值无意义
//   - tipErr:      取当前尖端时的错误
//
// 返回：四种处置之一；只有 branchDelete 允许调用方执行删除。
//
// 注意：
//   - 判定顺序是本函数的全部要点。`recordedTip == ""` 必须排在任何拿 currentTip
//     做的比较之前。旧实现里这条规则靠「碰巧写在前面」生效，一旦有人认为两道闸
//     重复而删掉它，悬空 symref 场景下 branchTip 失败塌缩出的空串会与 recordedTip
//     的空串相等，从而放行删除，毁掉用户自己的分支（该场景已实测可达，见
//     docs/superpowers/specs/2026-08-10-compensation-branch-decision-design.md §2.1）
//   - 取不到尖端一律保留而非删除：删分支不可逆，宁可留残留也不能删错
func decideBranchAction(recordedTip, currentTip string, tipErr error) branchAction {
	if recordedTip == "" {
		return branchKeepNotOurs
	}
	if tipErr != nil {
		return branchKeepTipUnknown
	}
	if currentTip != recordedTip {
		return branchKeepTipMoved
	}
	return branchDelete
}

n_orchestration_decisionLabel.signature:
// decisionLabel 把裁决结果压成一个日志可读的短标签。
