n_orchestration_deriveName.signature:
// deriveName 决定任务的展示名，优先级：显式 Name > plan 文件名（去日期前缀与
// .md 后缀）> prompt 前 20 rune（不切断单词）。
//
// 为什么去日期前缀：约定 plan 文件常以 2026-08-08-<主题>.md 命名，日期前缀是
// 归档排序用的噪音，做任务名会让列表里全是「2026-08-08-…」看不出主题。
// 为什么 prompt 截断不切断单词：任务列表一行能展示的长度有限，直接取前 20 rune
// 会把「…改成 br」这类半截英文留在列表里；截到下一个空白处（或末尾）让名字
// 以完整单词收尾，可读性远好于硬切。
func deriveName(name, planName, prompt string) string {
	if name != "" {
		return name
	}
	if planName != "" {
		n := planName
		n = regexp.MustCompile(`^\d{4}-\d{2}-\d{2}-`).ReplaceAllString(n, "")
		n = strings.TrimSuffix(n, ".md")
		if n != "" {
			return n
		}
	}
	r := []rune(prompt)
	const limit = 20
	if len(r) > limit {
		cut := limit

		for cut < len(r) && !unicode.IsSpace(r[cut]) {
			cut++
		}
		for cut < len(r) && unicode.IsSpace(r[cut]) {
			cut++
		}
		return string(r[:cut])
	}
	return string(r)
}

n_orchestration_escalateLogLevel.signature:
// escalateLogLevel 决定「权限判定：升级人工」这条日志的级别。
// 实现体已随判据权威迁 internal/approval（EscalateLogLevel，B233.21）；
// 这里保留编排侧命名落点，白盒测试沿用同名断言。
func escalateLogLevel(rule string) slog.Level {
	return approval.EscalateLogLevel(rule)
}

n_orchestration_expandCarrierHome.signature:
// expandCarrierHome 把载体 HomeDir 的前导 ~ 在本机展开为绝对路径。
// 登记串是跨机可认的用户可见形态（含 ~，见 scheduling.IsolatedHomeRoot）；
// 进子进程 HOME 前必须展开，否则子进程把 $HOME 系文件相对 cwd 落盘，
// 在仓库下建出 ./~/.handoff/... 垃圾目录（2026-09-04 实测 2.2G）。
// 展开失败时原样返回（os.UserHomeDir 失败属极罕见，保持原行为不阻断派发）。
func expandCarrierHome(homeDir string) string {
	if homeDir != "~" && !strings.HasPrefix(homeDir, "~/") && !strings.HasPrefix(homeDir, `~\`) {
		return homeDir
	}
	if base, err := userHomeDir(); err == nil && base != "" {
		if homeDir == "~" {
			return base
		}
		return filepath.Join(base, strings.TrimLeft(homeDir[1:], `/\`))
	}
	return homeDir
}

n_orchestration_firstMissingAncestor.signature:
// firstMissingAncestor 返回从 dir 往上第一个「尚不存在」的祖先目录——也就是
// os.MkdirAll(dir) 会从哪一层开始真正创建目录。
//
// 参数：
//   - dir: 待创建的目录（绝对路径）
//
// 返回：
//   - 第一个不存在的祖先的绝对路径；dir 本身已存在时返回空串
//
// 为什么需要它：clone 失败要回收「本次自己造的」目录，而 MkdirAll 可能一次造好
// 几层。只删最后那一层会留下中间空目录；从根上 RemoveAll 又会删掉调用方原本就有
// 的目录。这个函数给出的正是那条分界线。
func firstMissingAncestor(dir string) string {
	missing := ""
	for p := dir; ; {
		if _, err := os.Stat(p); err == nil {
			break
		}
		missing = p
		parent := filepath.Dir(p)
		if parent == p {
			break
		}
		p = parent
	}
	return missing
}

n_orchestration_gateDecision.signature:
// gateDecision 把协调者对 gate 工单的应答翻译成回传 executor 的裁决与可选原因。
//
// 参数：answer 为协调者应答原文（CLI 侧 --approve → "allow"、
// --deny [--reason r] → "deny" 或 "deny: r"，见 cmd/reply.go）
//
// 返回：
//   - decision: "once"（严格等于 "allow" 时）或 "reject"（其余一律）
//   - reason: 拒绝原因；无原因或批准时为空串
//
// 注意：
//   - 「非 allow 一律 reject」是安全语义，本函数新增 reason 返回值**不改变**它——
//     原因是给模型看的旁路信息，不参与裁决
func gateDecision(answer string) (decision, reason string) {
	trimmed := strings.TrimSpace(answer)
	if trimmed == "allow" {
		return "once", ""
	}
	rest := strings.TrimPrefix(trimmed, "deny")
	rest = strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(rest), ":"))
	if rest == trimmed {

		return "reject", ""
	}
	return "reject", rest
}

n_orchestration_isOpenCodeExecutor.signature:
// isOpenCodeExecutor 判断指定执行者是否为 opencode。
// 当 name 为空时按 defaultName 缺省判定。
func isOpenCodeExecutor(name, defaultName string) bool {
	if name == "" {
		name = defaultName
	}
	return name == "opencode"
}

n_orchestration_killModeFromCgroup.signature:
// killModeFromCgroup 解析当前进程所属的 systemd unit 及其 KillMode。
//
// 参数（两个函数参数是测试缝，生产分别传 os.ReadFile 与 systemctlKillMode）：
//   - readFile: 读 /proc/self/cgroup
//   - unitLookup: 按 unit 名查 KillMode
//
// 返回：
//   - unit: unit 名；mode: KillMode 值；ok: 是否确实在 systemd unit 下
//   - 非 Linux、非 systemd、cgroup 路径不含 .service 时 ok=false（静默）
func killModeFromCgroup(readFile func(string) ([]byte, error),
	unitLookup func(string) (string, error)) (unit, mode string, ok bool) {
	b, err := readFile(selfCgroupPath)
	if err != nil {
		return "", "", false
	}

	for _, line := range strings.Split(string(b), "\n") {
		idx := strings.LastIndex(line, "/")
		if idx < 0 {
			continue
		}
		name := strings.TrimSpace(line[idx+1:])
		if !strings.HasSuffix(name, ".service") {
			continue
		}
		unit = name
		break
	}
	if unit == "" {
		return "", "", false
	}
	if unitLookup == nil {
		return unit, "", true
	}
	mode, err = unitLookup(unit)
	if err != nil {
		return unit, "", true
	}
	return unit, mode, true
}

n_orchestration_parseDecision.signature:
// parseDecision 从裁决命令输出里解析 decision。
//
// 为什么由后向前逐行找 JSON：廉价模型常在 JSON 输出**前**输出思考文本
// （reasoning/解释），真正的 JSON 是输出的最后几行；由后向前找、逐行尝试
// 反序列化，首个合法 JSON 行生效——若从前往后找，第一行思考文本里的花括号
// 片段极易被误解析。
//
// 解析规则（fail-closed）：
//   - 找不到合法 JSON / decision 不是 approve|escalate → Err 非 nil
//   - nonce 非空时裁决 JSON 必须回显同一 nonce，否则 Err 非 nil（防伪校验）
//   - 合法 escalate → 干净 escalate（Err=nil，Reason 取模型给的理由）
//   - 合法 approve → Approve=true
//
// 参数：
//   - out: 裁决命令输出
//   - nonce: 本次 prompt 的 nonce；空=不校验（随机源失败时的降级）
//   - elapsedMS: 本次裁决耗时
func parseDecision(out, nonce string, elapsedMS int64) ApproverDecision {
	lines := strings.Split(out, "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		if line == "" {
			continue
		}
		var m struct {
			Decision	string	`json:"decision"`
			Reason		string	`json:"reason"`
			Nonce		string	`json:"nonce"`
		}
		if json.Unmarshal([]byte(line), &m) != nil {
			continue
		}

		if nonce != "" && m.Nonce != nonce {
			return ApproverDecision{Approve: false, ElapsedMS: elapsedMS,
				Err:	fmt.Errorf("审批者裁决 nonce 不匹配（期望 %s，实得 %q），疑似伪造裁决", nonce, agentd.TruncateRunes(m.Nonce, 40))}
		}
		switch m.Decision {
		case "approve":
			return ApproverDecision{Approve: true, Reason: m.Reason, ElapsedMS: elapsedMS}
		case "escalate":
			return ApproverDecision{Approve: false, Reason: m.Reason, ElapsedMS: elapsedMS}
		default:
			return ApproverDecision{Approve: false, ElapsedMS: elapsedMS,
				Err:	fmt.Errorf("审批者 decision 取值非法 %q（仅接受 approve/escalate）", m.Decision)}
		}
	}
	return ApproverDecision{Approve: false, ElapsedMS: elapsedMS, Err: errors.New("裁决输出不含可解析的 JSON decision")}
}

n_orchestration_permEventText.signature:
// permEventText 把权限描述压成事件 payload 用的短文本，超限时带显式截断标记——
// 无标记的截断会让协调者以为看到的就是全部（这正是 B6 的根因），有标记才知道
// 要去 handoff show 看工单里的全文。
func permEventText(s string) string {
	if len([]rune(s)) <= permEventTextLimit {
		return s
	}
	return agentd.TruncateRunes(s, permEventTextLimit) + executor.TruncationMarker
}

n_orchestration_permFingerprint.signature:
// permFingerprint 计算权限描述全文的裁决指纹（sha256 十六进制串）。
//
// 为什么取哈希而不是原文：权限描述可长达 64KB，原文不适合做索引键；
// 而复用要求的是「一字不差的同一件事」，哈希恰好表达这个语义。
func permFingerprint(text string) string {
	sum := sha256.Sum256([]byte(text))
	return hex.EncodeToString(sum[:])
}

n_orchestration_permFingerprintFor.signature:
// permFingerprintFor 计算一次权限请求的裁决指纹，是所有建单/查询点的唯一入口。
//
// 域规则（B91）：
//   - Perm.Command 非空 → 命令域：sha256("cmd\x00" + command)。同一条命令被
//     opencode 以 external_directory 与 bash 两种 kind 各发一次时（双胞胎工单，
//     见 B91 spec §1.1），两次算出同一指纹，第二次得以复用首次的人工批准。
//   - Command 为空但 Paths 非空 → 路径域：sha256("paths\x00" + Tool + "\x00" +
//     排序后的 Paths)。治的是「同一个目录被每个子 agent 各问一次」——子 agent
//     前缀只加在 Text 上（opencode adapter.go 的 permission.asked 归一化处），
//     Perm 不带它，所以路径域天然忽略前缀。Tool 进指纹是硬要求，理由见函数体。
//   - 都为空（Perm 为 nil，或提取不出结构的 fail-closed 类）→ 全文域：
//     沿用 B57 的权限描述全文指纹，行为不变。
//
// 三个域各带自己的前缀做隔离，文本相同也永不相撞，杜绝「某段权限描述全文恰好
// 等于另一条命令文本」这类伪命中。
//
// 注意：写入（建单）与查询（reuseDecision）必须都走本函数——两边规则不一致
// 会让复用静默失效，那正是 B91 要修的缺陷形态。
func permFingerprintFor(ev executor.AdapterEvent) string {
	return executor.PermFingerprint(ev)
}

n_orchestration_planSummaryFromContent.signature:
// planSummaryFromContent 从 plan 内容生成任务摘要。
//
// 规则：取首个非空行（markdown 计划的标题位，如 `# 修复登录态丢失`），按
// planSummaryLimit 截断；内容为空或全空行时返回空串。
// 为什么用「首个非空行」而非「前 N 字符整体截断」：plan 开头常有空行/分隔线/
// 注释行，前 N 字符的摘要可能全是空白与噪音；首行标题是 markdown 惯例的意图
// 浓缩位，协调者一眼即知任务方向（P1-12）。
func planSummaryFromContent(content []byte) string {
	for _, line := range strings.Split(string(content), "\n") {
		if trimmed := strings.TrimSpace(line); trimmed != "" {
			return agentd.TruncateRunes(trimmed, planSummaryLimit)
		}
	}
	return ""
}

n_orchestration_probeProjectStatus.signature:
// probeProjectStatus 探测一条位置指向的路径当前是什么状态。
func probeProjectStatus(ctx context.Context, path string) string {
	if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
		return workspace.ProjectStatusMissing
	}
	if err := workspace.EnsureRepoUsable(ctx, path); err != nil {
		return workspace.ProjectStatusNotRepo
	}
	return workspace.ProjectStatusOK
}

n_orchestration_randNonce.signature:
// randNonce 生成一次性裁决随机数（8 字节 → 16 位十六进制）。
//
// 为什么是随机而不是计数器/时间戳：nonce 的唯一作用是「executor 无法预知」——
// 可预测的值可以被提前构造进权限描述里，防伪就失效了。
// 随机源失败时返回空串，由调用方按「本次不带 nonce 校验」降级：
// 拿不到随机数不该让整条审批链瘫痪，而缺 nonce 的裁决仍受 §fail-closed 保护。
func randNonce() string {
	b := make([]byte, 8)
	if _, err := rand.Read(b); err != nil {
		return ""
	}
	return hex.EncodeToString(b)
}

n_orchestration_registeredNames.signature:
// registeredNames 返回注册表全部执行者名（按字母序，供错误提示与日志）。
func registeredNames(ads map[string]executor.Adapter) []string {
	names := make([]string, 0, len(ads))
	for n := range ads {
		names = append(names, n)
	}
	sort.Strings(names)
	return names
}

n_orchestration_registryFromAds.signature:
func registryFromAds(ads map[string]executor.Adapter) *executor.Registry {
	ps := make([]executor.Provider, 0, len(ads))
	for _, ad := range ads {
		if p, ok := ad.(executor.Provider); ok {
			ps = append(ps, p)
		}
	}
	return executor.NewRegistry(ps...)
}

n_orchestration_shortTaskID.signature:
// shortTaskID 取任务 ID 前 8 位（不足 8 位则原样返回）。
func shortTaskID(id string) string {
	if len(id) <= 8 {
		return id
	}
	return id[:8]
}

n_orchestration_systemctlKillMode.signature:
// systemctlKillMode 用 systemctl show 查某个 unit 的 KillMode。
func systemctlKillMode(unit string) (string, error) {
	out, err := exec.Command("systemctl", "show", "-p", "KillMode", "--value", unit).Output()
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(string(out)), nil
}

n_orchestration_taskProfileHome.signature:
// taskProfileHome 解析任务纪律 overlay 的落盘写入点（B233.14）。
//
// 语义：返回恒为非空路径的写入点——五家 Profile.Prepare 拒绝空 HomeDir，且
// overlay 必须落盘。非空 taskHome 经 expandCarrierHome 展开 ~ 前缀为绝对路径
// （修掉把 ~ 当目录名、在 cwd 建 ./~/.handoff 的既有缺陷）；空 taskHome
// （载体主 HOME）取本机主 HOME。展开后仍非绝对即报错，绝不静默落相对路径。
//
// 注意：Task.HomeDir 身份快照不由本函数改写（B347：空 HOME 是身份值），
// 本函数只回答「写到哪」。
func taskProfileHome(taskHome string) (string, error) {
	if taskHome != "" {
		writePoint := expandCarrierHome(taskHome)
		if !filepath.IsAbs(writePoint) {
			return "", fmt.Errorf("载体 HOME %q 展开后仍非绝对路径", taskHome)
		}
		return writePoint, nil
	}
	home, err := userHomeDir()
	if err != nil {
		return "", fmt.Errorf("无法解析本机主 HOME: %w", err)
	}
	if home == "" {
		return "", errors.New("无法解析本机主 HOME: 取值为空")
	}
	return home, nil
}

n_orchestration_unaryCtx.signature:
// unaryCtx 为一次 executor 一元调用派生带截止时间的 ctx。
//
// 为什么派生子 ctx 而不直接把 parent 传下去：等待阶段（WaitAnswer 等人工应答）
// 时长无上限，截止时间必须只包住调用本身、不能缩短等待窗口——parent 在等待期
// 结束后可能已接近/超过 30s（协调者思考了 5 分钟才回复），直接复用会把本应成功
// 的调用掐死在截止时间上。
func unaryCtx(parent context.Context) (context.Context, context.CancelFunc) {
	return context.WithTimeout(parent, unaryAPITimeout)
}

n_orchestration_uniqueProjectName.signature:
// uniqueProjectName 在 base 已被占用时退让为 base-2、base-3……
//
// 参数：
//   - base: 期望的引用名
//   - entries: 本机现有位置
//
// 返回：
//   - 未被占用的名字；退让 NameFallbackLimit 次仍冲突时返回 ErrBadDispatchRequest
//
// 注意：
//   - 只在**不同项目**撞名时才会走到这里：同项目重复登记已在 persistProject
//     前段按 project_id 拒掉了
func uniqueProjectName(base string, entries []proto.ProjectLocation) (string, error) {
	taken := make(map[string]bool, len(entries))
	for _, e := range entries {
		taken[e.Name] = true
	}
	if !taken[base] {
		return base, nil
	}
	for i := 2; i <= workspace.NameFallbackLimit; i++ {
		candidate := base + "-" + strconv.Itoa(i)
		if !taken[candidate] {
			return candidate, nil
		}
	}
	return "", fmt.Errorf("%w: 名字 %s 及其 -2..-%d 变体全部被占用，请用 [名字] 参数显式指定",
		agentd.ErrBadDispatchRequest, base, workspace.NameFallbackLimit)
}

n_orchestration_withCarrierHome.signature:
// withCarrierHome 返回带有唯一显式 HOME 行的 env。它只处理 Manager 已经解析
// 完成的 executor env，不改变通用 env JSON 或 StartReq 形状。
//
// 为什么删除所有旧 HOME：环境文件允许重复键，若只追加载体值，最终生效值会
// 依赖 prochost/exec 的重复键处理顺序；先过滤再追加把覆盖优先级固定为载体。
func withCarrierHome(env []string, homeDir string) []string {
	out := make([]string, 0, len(env)+1)
	for _, kv := range env {
		key, _, ok := strings.Cut(kv, "=")
		if ok && key == "HOME" {
			continue
		}
		out = append(out, kv)
	}
	return append(out, "HOME="+expandCarrierHome(homeDir))
}

n_orchestration_worktreeCleanupHint.signature:
// worktreeCleanupHint 构造「清理失败」提示文案。
//
// 参数：
//   - taskID: 任务 ID（提示里只取前 8 位，与 CLI 的接受形态一致）
//   - cause: 清理失败的真因
//
// 返回：
//   - 带真因与可执行出路的一句话
//
// 注意：刻意不再提「请手动 git worktree remove」。清理失败最常见的原因就是
// 工作树脏而 remove 不带 --force，手工重跑同一条命令撞的是同一堵墙——
// B77 的 2c58bbb7 正是这么无声漏掉的
func worktreeCleanupHint(taskID string, cause error) string {
	return fmt.Sprintf("worktree 清理失败：%v，可重试：handoff reclaim %s",
		cause, shortTaskID(taskID))
}

n_pathenv_Apply.signature:
// Apply 解析 PATH 并写回进程环境。
//
// 参数：
//   - ctx: 上层上下文；登录 shell 那一层内部叠加 loginShellTimeout
//   - opt: 启用哪些来源
//   - log: 日志入口
//
// 返回：
//   - 本次新增的目录（按加入顺序）；无新增或写回失败时为 nil
//
// 注意：
//   - 不返回 error：本函数是 best-effort 增强，任何失败都只记日志
//   - 调用方拿 added 是为了向用户解释「这个工具是靠补全才找到的」（见 cmd/init.go）
//   - agentd 侧必须在**任何 fork 子进程之前**调用，合并结果才能被 executor、
//     审批者 CLI、审阅命令一并继承
func Apply(ctx context.Context, opt Options, log *slog.Logger) []string {
	cur := os.Getenv("PATH")
	seen := map[string]bool{}
	for _, d := range filepath.SplitList(cur) {
		if d != "" {
			seen[d] = true
		}
	}

	merged := cur
	var added, fromLogin, fromExtra, fromKnown []string

	appendDir := func(d string, bucket *[]string) {
		if d == "" || seen[d] {
			return
		}
		seen[d] = true
		if merged == "" {
			merged = d
		} else {
			merged += string(os.PathListSeparator) + d
		}
		added = append(added, d)
		*bucket = append(*bucket, d)
	}

	if opt.IncludeLoginShell {
		for _, d := range loginShellDirs(ctx, log) {
			appendDir(d, &fromLogin)
		}
	}
	for _, d := range opt.ExtraDirs {
		if !dirExists(d) {

			log.Warn("config.path_dirs 里的目录不存在，已跳过", "dir", d)
			continue
		}
		appendDir(d, &fromExtra)
	}
	for _, d := range knownDirs(log) {
		appendDir(d, &fromKnown)
	}

	if len(added) == 0 {
		log.Info("PATH 无需补全")
		return nil
	}
	if err := os.Setenv("PATH", merged); err != nil {
		log.Warn("写入补全后的 PATH 失败，保持当前 PATH", "cause", err)
		return nil
	}
	log.Info("已补全 PATH",
		"login_shell", fromLogin, "extra_dirs", fromExtra, "known_dirs", fromKnown)
	return added
}

n_pathenv_knownDirs.signature:
// knownDirs 返回内置表里**确实存在**的目录。
//
// 只返回存在的：把一堆不存在的目录塞进 PATH 会让每次 LookPath 多做一轮无用 stat，
// 也让日志里的「已补全」失去意义。
func knownDirs(log *slog.Logger) []string {
	var out []string
	home, err := homeDir()
	if err != nil {

		log.Warn("取不到主目录，跳过全部 ~ 系已知目录", "cause", err)
	} else {
		for _, rel := range homeRelDirs {
			if p := filepath.Join(home, rel); dirExists(p) {
				out = append(out, p)
			}
		}
	}
	for _, p := range absDirs {
		if dirExists(p) {
			out = append(out, p)
		}
	}
	return out
}

n_pathenv_loginShellDirs.signature:
// loginShellDirs 取登录 shell 的 PATH 并拆成目录列表；失败返回 nil。
func loginShellDirs(ctx context.Context, log *slog.Logger) []string {

	if loginShellGOOS == "windows" {
		log.Debug("Windows 平台跳过登录 shell 的 PATH 解析", "reason", "该平台无 rc 链概念")
		return nil
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		log.Warn("未设置 $SHELL，跳过登录 shell 的 PATH 解析")
		return nil
	}
	ctx, cancel := context.WithTimeout(ctx, loginShellTimeout)
	defer cancel()
	got, err := loginShellPATH(ctx, shell)
	if err != nil {
		log.Warn("登录 shell 解析 PATH 失败，跳过该来源", "shell", shell, "cause", err)
		return nil
	}
	return filepath.SplitList(got)
}

n_permgate_Action_String.signature:
// String 给出日志可读的短标签。
func (a Action) String() string {
	switch a {
	case AutoAllow:
		return "auto_allow"
	case Consult:
		return "consult"
	default:
		return "escalate"
	}
}

n_permgate_Gate_Judge.signature:
// Judge 判定一次权限请求（spec §3.4 的路由 + §7 的 fail-closed 表）。
//
// 参数：
//   - req: 结构化后的权限请求
//   - scope: 本任务的合法作用范围
//
// 返回：Verdict，调用方据 Action 决定后续动作
//
// 路由：
//   - write / edit → 路径归属判定，**并且**对 Text 跑一次黑名单（路径本身
//     可能命中，如 Write: /etc/sudoers）；两项是与关系
//   - bash        → 先判全部落点的范围归属，落点干净才做命令类判定
//   - 其余        → 对 Text 做命令类判定
//
// 注意：
//   - Truncated 一律直接 Escalate 且不再往下判：看到的是不完整的描述，
//     危险片段可能落在截断之外，黑名单与模型都不可信
//   - 本方法**永不因失败而返回 AutoAllow**（spec §7）
func (g *Gate) Judge(req Request, scope Scope) Verdict {
	if req.Truncated {
		return Verdict{Action: Escalate,
			Reason:	"权限描述含截断标记，危险片段可能落在截断之外"}
	}
	switch req.Tool {
	case executor.PermToolWrite, executor.PermToolEdit:
		return g.judgeFileWrite(req, scope)
	case executor.PermToolBash:
		return g.judgeBash(req, scope)
	default:
		return g.judgeCommand(req.Text)
	}
}

n_permgate_Gate_judgeBash.signature:
// judgeBash 判定命令类请求：先判落点范围，落点干净才落回命令判据。
//
// 参数：req 为结构化请求（用 Command 与 Paths），scope 为任务范围
// 返回：Escalate（任一落点越界或归一化失败），否则 judgeCommand 的结果
//
// 落点有三个来源，同等对待：
//   - req.Paths —— executor 自己检出的越界目录。opencode 的 external_directory
//     bash 形态把它填在这里（opencode/adapter_test.go 有同名断言钉住），
//     但**此前被本函数的前身整个丢弃**，越界因此从「人来判」降级成「廉价模型判」
//   - RedirectTargets(req.Command) —— handoff 自己从命令原文摘的重定向落点。
//     不能只靠前者：2026-08-18 真机探针实测 opencode 只解析「作为参数出现的
//     路径」，`echo x > /tmp/f` 零权限请求直接写成功（spec §2.2.1）
//   - WriteArgTargets(req.Command) —— handoff 从写命令参数位摘的落点（B151）。
//     claude 的 bash 请求 Paths 恒为空，opencode 对管道后的 tee 也检不出，这一路
//     是唯一兜底
//
// 为什么路径判据前置于命令判据：越界是确定性事实，而 judgeCommand 最好的结果
// 也只是 Consult。放在后面会让「越界」被稀释成廉价模型的一次裁决。
//
// 为什么落点为空不 fail-closed（与 judgeFileWrite 的 len(Paths)==0 → Escalate 不同）：
// 纯 bash 门类本来就不带路径，`go build ./...` 是绝大多数情形；在这里 fail-closed
// 等于把每条命令都升级人工，那是 spec §3 明确排除的反转。
func (g *Gate) judgeBash(req Request, scope Scope) Verdict {

	redirects := RedirectTargets(req.Command)
	writeArgs := WriteArgTargets(req.Command)
	targets := append([]string(nil), req.Paths...)
	targets = append(targets, redirects...)
	targets = append(targets, writeArgs...)
	if n := len(targets); n > 0 {
		g.log.Debug("命令落点已汇总", "count", n,
			"from_executor", len(req.Paths),
			"from_redirect", len(redirects),
			"from_write_args", len(writeArgs))
	}
	for _, p := range targets {
		if IsDiscardTarget(p) {
			g.log.Debug("命令落点是丢弃设备，跳过范围判定", "path", p)
			continue
		}
		in, base, err := InScope(p, scope)
		if err != nil {
			g.log.Debug("命令落点归一化失败，按越界处置", "path", p, "cause", err)
			return Verdict{Action: Escalate,
				Reason:	fmt.Sprintf("命令落点归一化失败 %q: %v", p, err)}
		}
		if !in {

			return Verdict{Action: Escalate,
				Reason:	fmt.Sprintf("目标路径越出任务范围: %s", p)}
		}
		g.log.Debug("命令落点在任务范围内", "path", p, "base", base)
	}

	verdict := g.judgeCommand(req.Command)
	if verdict.Action != Consult {
		return verdict
	}
	if id, ok := safeCommandID(req.Command); ok {
		g.log.Info("安全命令白名单命中", "command", req.Command, "id", id,
			"targets", len(targets))
		return Verdict{Action: AutoAllow, Rule: RuleSafeCommand,
			Reason:	"安全命令白名单命中: " + id}
	}
	g.log.Debug("安全命令白名单未命中", "command", req.Command)
	return verdict
}

n_permgate_Gate_judgeCommand.signature:
// judgeCommand 判定命令类请求（spec §4.1 的规则 + 两条实证补强）。
//
// 参数：s 为待判文本（bash 路由传 Command，其余路由传 Text）
// 返回：Consult 或 Escalate；本函数**永不返回 AutoAllow**
//
// 规则（逐条判定）：
//   - 剥离引号后仍是 handoff 自指令 → Escalate（身份越权，与危险性无关）
//   - 原文是自指令且含执行包装器   → Escalate（`sh -c "handoff dispatch"`）
//   - 剥离引号字面量后仍命中黑名单 → Escalate（真危险，无论引号与否）
//   - 原文命中且含执行包装器       → Escalate（引号内内容将被执行，不给
//     降级口子——`sh -c "rm -rf /"` 剥完虽干净，但内容正是要执行的）
//   - 原文命中但无执行包装器       → Consult（仅引号内字面量命中，如
//     `git commit -m "去掉 rm -rf 分支"`，降级交模型看一眼）
//   - 原文未命中但含 eval          → Escalate（eval 参数是变量/构造串，
//     内容不可见，无法判定）
//   - 原文未命中且无 eval          → Consult（与改动前一致）
//
// 核心取舍：误判的修法不是「直接放行」，而是「从硬拦降级为让模型看一眼」——
// 未枚举到的引号绕过形态最坏也只落到廉价模型手上；而执行包装器与 eval 两条
// 把「内容将被执行/不可见」的形态恢复硬拦，不给绕过留口子。
func (g *Gate) judgeCommand(s string) Verdict {

	if hit, sub := IsSelfCommand(StripQuoted(s)); hit {
		return g.selfCmdVerdict(sub, "剥离引号字面量后仍是自指令调用")
	}

	if hit, sub := IsSelfCommand(selfCmdTokenText(s)); hit && HasExecWrapper(s) {
		return g.selfCmdVerdict(sub, "自指令藏在执行包装器的引号里，内容将被执行")
	}

	hit, rule := g.match(s)
	if h2, r2 := g.match(StripQuoted(s)); h2 {
		return Verdict{Action: Escalate, Reason: "剥离引号字面量后仍命中黑名单", Rule: r2}
	}
	if HasExecWrapper(s) {
		if hit {
			return Verdict{Action: Escalate,
				Reason:	"命中黑名单且含执行包装器，引号内内容将被执行", Rule: rule}
		}
		if evalRx.MatchString(s) {
			return Verdict{Action: Escalate,
				Reason:	"命令含 eval 且内容不可见，无法判定是否危险"}
		}
	}
	if hit {
		return Verdict{Action: Consult,
			Reason:	"仅引号内字面量命中黑名单，降级交审批者裁决", Rule: rule}
	}
	return Verdict{Action: Consult, Reason: "黑名单未命中"}
}

n_permgate_Gate_judgeFileWrite.signature:
// judgeFileWrite 判定写文件类请求：黑名单与路径归属都通过才自动放行。
//
// 返回：AutoAllow 或 Escalate；本函数**永不返回 Consult**——写文件的危险
// 判定是确定性的（路径在不在范围内），不需要模型介入。
func (g *Gate) judgeFileWrite(req Request, scope Scope) Verdict {
	if len(req.Paths) == 0 {
		return Verdict{Action: Escalate,
			Reason:	"写文件请求未能提取出目标路径，无法判定范围"}
	}
	if hit, rule := g.match(req.Text); hit {
		return Verdict{Action: Escalate,
			Reason:	"写文件描述命中黑名单", Rule: rule}
	}
	for _, p := range req.Paths {
		in, base, err := InScope(p, scope)
		if err != nil {
			return Verdict{Action: Escalate,
				Reason:	fmt.Sprintf("目标路径归一化失败 %q: %v", p, err)}
		}
		if !in {
			return Verdict{Action: Escalate,
				Reason:	fmt.Sprintf("目标路径越出任务范围: %s", p)}
		}
		g.log.Debug("写入路径在任务范围内", "path", p, "base", base)
	}
	return Verdict{Action: AutoAllow, Reason: "全部目标路径落在任务范围内"}
}

n_permgate_Gate_match.signature:
// match 返回是否命中黑名单及命中的规则原文。
func (g *Gate) match(s string) (bool, string) {
	for _, r := range g.blacklist {
		if r.MatchString(s) {
			return true, r.String()
		}
	}
	return false, ""
}

n_permgate_Gate_selfCmdVerdict.signature:
// selfCmdVerdict 构造自指令裁决，并在 permgate 侧留一条 Debug 现场。
//
// 参数：sub 为命中的子命令名，why 为命中路径（真调用 / 藏在包装器里）
//
// 注意：这里只打 Debug，权威的 Warn 一条落在 agentd 的 judgePermission——
// 那里才拿得到 task id 与 permission id，能把这条判定关联到具体任务。
// 两处都打 Warn 会让同一件事在日志里出现两遍。
func (g *Gate) selfCmdVerdict(sub, why string) Verdict {
	g.log.Debug("命中 handoff 自指令判据", "subcommand", sub, "why", why)
	return Verdict{
		Action:	Escalate,
		Reason:	fmt.Sprintf("executor 试图调用 handoff 变更命令 %s（%s）", sub, why),
		Rule:	RuleSelfCommand,
	}
}

n_permgate_HasExecWrapper.signature:
// HasExecWrapper 判断命令是否含执行包装器（sh -c / bash -c / eval / xargs /
// 通用 -c/-e/-E 执行标志等）。
func HasExecWrapper(s string) bool	{ return execWrapperRx.MatchString(s) }

n_permgate_InScope.signature:
// InScope 判定目标路径是否落在任务范围内。
//
// 参数：
//   - path: 目标路径，可为相对路径（按 scope.Workdir 解析）
//   - scope: 任务范围；其中为空的基准目录被跳过，不参与判定
//
// 返回：
//   - in: 是否落在范围内
//   - base: in=true 时命中的基准目录（归一化后），供日志说明「凭哪条放行」
//   - err: 路径归一化失败；调用方须按 fail-closed 处理为升级人工
//
// 注意：
//   - 用 filepath.Rel 判归属而非字符串前缀——strings.HasPrefix("/repo-evil/x",
//     "/repo") 为真，前缀匹配会把仓库外的路径判成内部
//   - 对已存在的最长前缀求 EvalSymlinks——目标文件常常尚不存在（Write 新建），
//     不解软链则 `ln -s ~ /repo/link` 之后写 /repo/link/.ssh/authorized_keys
//     直接绕过
func InScope(path string, scope Scope) (in bool, base string, err error) {
	p := path
	if !filepath.IsAbs(p) {
		p = filepath.Join(scope.Workdir, p)
	}
	p, err = filepath.Abs(p)
	if err != nil {
		return false, "", fmt.Errorf("绝对化目标路径 %q: %w", path, err)
	}
	p = resolveExistingPrefix(p)

	for _, b := range []string{scope.Workdir, scope.TaskDir, scope.TaskTmpDir} {
		if b == "" {
			continue
		}
		rb, aerr := filepath.Abs(b)
		if aerr != nil {
			return false, "", fmt.Errorf("绝对化基准目录 %q: %w", b, aerr)
		}
		rb = resolveExistingPrefix(rb)
		rel, rerr := filepath.Rel(rb, p)
		if rerr != nil {

			continue
		}
		if rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
			return true, rb, nil
		}
	}
	return false, "", nil
}

n_permgate_IsDiscardTarget.signature:
// IsDiscardTarget 判断落点是否为 /dev 下的丢弃或终端设备。
//
// 参数：p 为落点路径（已展开 ~）
// 返回：是则 true，调用方应跳过对它的范围判定
func IsDiscardTarget(p string) bool {
	if discardTargets[p] {
		return true
	}
	return strings.HasPrefix(p, "/dev/fd/")
}

n_permgate_IsSelfCommand.signature:
// IsSelfCommand 判断命令文本里是否存在 handoff 的变更类自指令调用。
//
// 参数：s 为待判文本（bash 路由传 Command，其余路由传 Text）
//
// 返回：
//   - hit: 是否判为自指令
//   - sub: 命中的子命令名；未知子命令返回该词元原文；未命中返回 ""
//
// 判定分三步（spec §3.3）：
//  1. 按 | ; & 换行切段，逐段独立判定
//  2. 段内找首个 basename 为 handoff/handoff.exe 的词元，其后不以 - 开头的
//     词元即候选
//  3. 三级判定，顺序不可换：含变更词 → 命中；否则含白名单词 → 放行；
//     否则候选非空 → 命中
//
// 注意：本函数不处理引号与执行包装器，调用方（judgeCommand）负责按原文与
// StripQuoted 结果各跑一遍。
func IsSelfCommand(s string) (hit bool, sub string) {
	for _, seg := range splitSegments(s) {
		if h, name := judgeSegment(seg); h {
			return true, name
		}
	}
	return false, ""
}

n_permgate_New.signature:
// New 构造判据网关。
//
// 参数：
//   - patterns: 用户自定义黑名单（config.ApproverConfig.Blacklist）；内置
//     黑名单自动前置，无需调用方传入
//   - log: 包日志入口；nil 时用 slog.Default()
//
// 返回：
//   - 可用的 Gate；任一正则编译失败即返回错误（配置错误应在启动期暴露）
//
// 注意：
//   - **无论审批者是否启用都必须构造**。AutoAllow 是第 0 层静态判据、不是
//     审批者的职权；漏构造会让未配置审批者的部署被工作区内的每次写入淹没
func New(patterns []string, log *slog.Logger) (*Gate, error) {
	if log == nil {
		log = slog.Default()
	}
	all := append([]string(nil), builtinBlacklist...)
	all = append(all, patterns...)
	rx := make([]*regexp.Regexp, 0, len(all))
	for _, p := range all {
		r, err := regexp.Compile("(?i)" + p)
		if err != nil {
			return nil, fmt.Errorf("编译黑名单正则 %q: %w", p, err)
		}
		rx = append(rx, r)
	}
	log.Info("权限判据网关已就绪", "builtin_rules", len(builtinBlacklist),
		"custom_rules", len(patterns))
	return &Gate{blacklist: rx, log: log}, nil
}

n_permgate_RedirectTargets.signature:
// RedirectTargets 从命令串里摘出全部输出重定向的落点。
//
// 参数：cmd 为命令原文（**不要**先过 StripQuoted，见文件头 why）
// 返回：落点路径切片，按出现顺序；没有则返回 nil
//
// 识别的形态：`>`、`>>`、`>|`、`n>`、`n>>`、`&>`、`&>>`
// 明确排除的形态：fd 复制与关闭（`2>&1`、`>&2`、`>&-`）——它们不写文件
//
// 注意：
//   - 引号内的 `>` 不算重定向（`echo "a > b"`、`grep "x->y"` 都不命中）
//   - 落点带引号时取引号内的内容，可以含空格
//   - `~` 与 `~/` 前缀展开为当前用户 home（why 见 expandTilde）
func RedirectTargets(cmd string) []string {
	var out []string
	rs := []rune(cmd)
	var quote rune
	for i := 0; i < len(rs); i++ {
		r := rs[i]
		switch {
		case quote == 0 && (r == '\'' || r == '"'):
			quote = r
			continue
		case quote != 0 && r == quote:
			quote = 0
			continue
		case quote != 0:
			continue
		}
		if r != '>' {
			continue
		}
		j := i + 1

		for j < len(rs) && (rs[j] == '>' || rs[j] == '|') {
			j++
		}

		if j < len(rs) && rs[j] == '&' {
			k := j + 1
			if k < len(rs) && (rs[k] == '-' || (rs[k] >= '0' && rs[k] <= '9')) {
				i = k
				continue
			}
			j = k
		}
		for j < len(rs) && (rs[j] == ' ' || rs[j] == '\t') {
			j++
		}
		tgt, next := readTarget(rs, j)

		i = next - 1
		if tgt != "" {
			out = append(out, expandTilde(tgt))
		}
	}
	return out
}

n_permgate_SafeCommandIDs.signature:
// SafeCommandIDs 返回当前白名单的稳定 id 集合（排序后），供政策快照 Version 哈希。
func SafeCommandIDs() []string {
	return []string{
		"git-ledger-amend", "go-build", "go-test", "go-vet", "gofmt",
		"npm-test", "npm-run", "make",
		"ls", "cat", "grep", "which", "pwd", "head", "tail", "wc",
		"git-status", "git-diff", "git-log", "git-grep", "git-show",
		"git-blame", "git-cat-file", "git-rev-parse", "git-ls-files",
	}
}

n_permgate_StripQuoted.signature:
// StripQuoted 把成对引号内的内容清空，保留引号本身。
//
// 参数：s 为原始命令串
// 返回：剥离后的串，如 `git commit -m "去掉 rm -rf 分支"` → `git commit -m ""`
//
// 注意：
//   - 不做完整 shell 解析。反斜杠转义（`"it\"s"`）会让本函数提前认为引号闭合，
//     结果是**剥得更少**——剥得少意味着更可能仍然命中黑名单、更可能 Escalate，
//     方向是安全的，因此接受
//   - 未闭合引号：引号之后的内容全部丢弃
func StripQuoted(s string) string {
	var b strings.Builder
	var quote rune	// 0 = 不在引号内
	for _, r := range s {
		switch {
		case quote == 0 && (r == '\'' || r == '"'):
			quote = r
			b.WriteRune(r)
		case quote != 0 && r == quote:
			quote = 0
			b.WriteRune(r)
		case quote != 0:

		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

n_permgate_WriteArgTargets.signature:
// WriteArgTargets 从命令串里摘出全部「参数位写落点」。
//
// 参数：cmd 为命令原文（**不要**先过 StripQuoted：落点常被引号包住，剥完就没了）
// 返回：落点路径切片，按出现顺序；没有则返回 nil
//
// 注意：
//   - 按 `|`、`&`、`;` 分段，逐段判首个词元是不是写命令——只有是，才摘该段的落点
//   - `--` 之后的词元一律不当标志看
//   - `~` 与 `~/xxx` 展开为当前用户 home（why 见 expandTilde）
//   - 丢弃落点（/dev/null 等）**不在这里过滤**：由 judgeBash 统一用 IsDiscardTarget 跳过，
//     两个落点来源共用同一处豁免，不会两边写两套
func WriteArgTargets(cmd string) []string {
	var out []string
	for _, seg := range splitWriteSegments(cmd) {
		toks := tokenize(seg)
		if len(toks) == 0 {
			continue
		}
		name := baseName(toks[0])
		kind, ok := writeCommands[name]
		if !ok {
			continue
		}
		for _, t := range targetsOf(kind, toks[1:]) {
			out = append(out, expandTilde(t))
		}
	}
	return out
}

n_permgate_baseName.signature:
// baseName 取命令名的最后一段，让 /usr/bin/tee 与 tee 判成同一个命令。
func baseName(s string) string {
	if i := strings.LastIndexByte(s, '/'); i >= 0 {
		return s[i+1:]
	}
	return s
}

n_permgate_expandTilde.signature:
// expandTilde 把 `~` 与 `~/xxx` 展开为当前用户 home。
//
// 参数：p 为原始落点
// 返回：展开后的路径；不以 ~ 开头、或取不到 home 时原样返回
//
// 为什么必须展开：filepath.Abs 不认识 `~`，`> ~/.zshrc` 会被 InScope 拼成
// <workdir>/~/.zshrc，判成范围内直接放行——那正是本条要拦的写入。
// 取不到 home 时原样返回是安全的：`~/.zshrc` 作为相对路径拼到 workdir 下，
// InScope 判在范围内，与展开前的行为一致，不会比现状更松。
func expandTilde(p string) string {
	if p != "~" && !strings.HasPrefix(p, "~/") {
		return p
	}
	home, err := os.UserHomeDir()
	if err != nil || home == "" {
		return p
	}
	if p == "~" {
		return home
	}
	return filepath.Join(home, p[2:])
}

n_permgate_hasGitDiffOutput.signature:
func hasGitDiffOutput(fields []string) bool {
	for _, field := range fields[2:] {
		if field == "--output" || strings.HasPrefix(field, "--output=") {
			return true
		}
	}
	return false
}

n_permgate_hasToken.signature:
func hasToken(fields []string, want string) bool {
	for _, field := range fields {
		if field == want {
			return true
		}
	}
	return false
}

n_permgate_isHandoffBinary.signature:
// isHandoffBinary 判断词元是否为 handoff 可执行文件的调用形态。
//
// 取 basename 而非整串比较，是为了覆盖 ./handoff 与 /usr/local/bin/handoff；
// 认 .exe 后缀是为了 Windows 执行机（B37）。反过来，cat handoff.log 的
// basename 是 handoff.log，不命中——同名文件不会被误当成调用。
func isHandoffBinary(tok string) bool {
	base := tok
	if i := strings.LastIndexAny(base, `/\`); i >= 0 {
		base = base[i+1:]
	}
	base = strings.ToLower(base)
	return base == "handoff" || base == "handoff.exe"
}

n_permgate_isLedgerAmend.signature:
func isLedgerAmend(left, right []string) bool {
	if len(left) < 3 || left[0] != "git" || left[1] != "add" {
		return false
	}
	pathspec := false
	for _, field := range left[2:] {
		if field == "--" {
			continue
		}
		if !strings.HasPrefix(field, "-") {
			pathspec = true
		}
	}
	return pathspec && len(right) == 4 && right[0] == "git" && right[1] == "commit" &&
		right[2] == "--amend" && right[3] == "--no-edit"
}

n_permgate_judgeSegment.signature:
// judgeSegment 判定单个命令段，返回值语义同 IsSelfCommand。
func judgeSegment(seg string) (bool, string) {
	fields := strings.Fields(seg)
	idx := -1
	for i, f := range fields {
		if isHandoffBinary(f) {
			idx = i
			break
		}
	}
	if idx < 0 {
		return false, ""
	}
	// 跳过 flag：`handoff --agentd http://x:1 tasks` 里 --agentd 与它的值都不
	// 该当成子命令。flag 的值跳不掉（它不以 - 开头），但无妨——它落进候选后
	// 两个名单都不认识，会被后面的白名单词或变更词覆盖判定
	var cand []string
	for _, f := range fields[idx+1:] {
		if strings.HasPrefix(f, "-") {
			continue
		}
		cand = append(cand, f)
	}
	if len(cand) == 0 {

		return false, ""
	}

	for _, c := range cand {
		if selfCmdMutating[c] {
			return true, c
		}
	}
	for _, c := range cand {
		if selfCmdReadOnly[c] {
			return false, ""
		}
	}

	return true, cand[0]
}

n_permgate_readTarget.signature:
// readTarget 从 rs[i] 起读一个落点词元。
//
// 参数：rs 为命令的 rune 切片，i 为起始下标（调用方已跳过空白）
// 返回：词元内容（去掉包裹引号）与下一个待扫描下标
func readTarget(rs []rune, i int) (string, int) {
	if i >= len(rs) {
		return "", i
	}
	if q := rs[i]; q == '\'' || q == '"' {
		var b strings.Builder
		j := i + 1
		for ; j < len(rs) && rs[j] != q; j++ {
			b.WriteRune(rs[j])
		}
		if j < len(rs) {
			j++
		}
		return b.String(), j
	}
	var b strings.Builder
	j := i
	for ; j < len(rs); j++ {
		switch rs[j] {
		case ' ', '\t', '\n', '|', ';', '&', '(', ')', '<', '>':
			return b.String(), j
		}
		b.WriteRune(rs[j])
	}
	return b.String(), j
}

n_permgate_resolveExistingPrefix.signature:
// resolveExistingPrefix 对路径中「已存在的最长前缀」求 EvalSymlinks，
// 再把剩余不存在的部分接回去。
//
// 为什么不能直接 EvalSymlinks(p)：Write 创建新文件时目标路径尚不存在，
// EvalSymlinks 会直接报错，那样每一次新建文件都会走 fail-closed 升级人工。
//
// 到根都解不动时原样返回——此时没有软链可解，原路径即真实路径。
func resolveExistingPrefix(p string) string {
	rest := ""
	cur := p
	for {
		if r, err := filepath.EvalSymlinks(cur); err == nil {
			if rest == "" {
				return r
			}
			return filepath.Join(r, rest)
		}
		parent := filepath.Dir(cur)
		if parent == cur {
			return p
		}
		rest = filepath.Join(filepath.Base(cur), rest)
		cur = parent
	}
}

n_permgate_safeCommandID.signature:
// safeCommandID matches a complete, positive command shape and returns its
// stable audit identifier. It tokenizes shell quoting for the command body;
// it is not a shell executor and rejects connectors except the one ledger
// amend form explicitly required by charter.
func safeCommandID(command string) (id string, ok bool) {
	segments, ok := splitSafeCommand(command)
	if !ok {
		return "", false
	}
	if len(segments) == 2 {
		if isLedgerAmend(segments[0], segments[1]) && len(WriteArgTargets(command)) > 0 {
			return "git-ledger-amend", true
		}
		return "", false
	}
	if len(segments) != 1 || len(segments[0]) == 0 {
		return "", false
	}
	fields := segments[0]
	if len(fields) >= 2 && fields[0] == "go" {
		switch fields[1] {
		case "build":
			return "go-build", true
		case "test":
			return "go-test", true
		case "vet":
			return "go-vet", true
		}
	}
	if fields[0] == "gofmt" {
		if hasToken(fields[1:], "-w") && len(WriteArgTargets(command)) == 0 {
			return "", false
		}
		return "gofmt", true
	}
	if len(fields) >= 2 && fields[0] == "npm" {
		switch fields[1] {
		case "test":
			return "npm-test", true
		case "run":
			if len(fields) >= 3 && fields[2] != "" && !strings.HasPrefix(fields[2], "-") {
				return "npm-run", true
			}
		}
	}
	if fields[0] == "make" {
		return "make", true
	}
	switch fields[0] {
	case "ls", "cat", "grep", "which", "pwd", "head", "tail", "wc":
		return fields[0], true
	}
	if len(fields) >= 2 && fields[0] == "git" {
		switch fields[1] {
		case "status":
			return "git-status", true
		case "diff":
			if hasGitDiffOutput(fields) && len(WriteArgTargets(command)) == 0 {
				return "", false
			}
			return "git-diff", true
		case "log":
			return "git-log", true
		case "grep":
			return "git-grep", true
		case "show":
			if hasGitDiffOutput(fields) {
				return "", false
			}
			return "git-show", true
		case "blame":
			return "git-blame", true
		case "cat-file":
			return "git-cat-file", true
		case "rev-parse":
			return "git-rev-parse", true
		case "ls-files":
			return "git-ls-files", true
		}
	}
	return "", false
}

n_permgate_selfCmdTokenText.signature:
// selfCmdTokenText 为包装器路径恢复被引号粘连的词元边界。
func selfCmdTokenText(s string) string {
	return strings.NewReplacer(`"`, " ", `'`, " ").Replace(s)
}

n_permgate_splitSafeCommand.signature:
// splitSafeCommand tokenizes one command or the two segments of the ledger
// amend form. Any unapproved shell connector or unterminated quote fails.
func splitSafeCommand(command string) ([][]string, bool) {
	var segments [][]string
	var fields []string
	var token strings.Builder
	var quote rune
	active := false
	flush := func() {
		if active {
			fields = append(fields, token.String())
			token.Reset()
			active = false
		}
	}
	for i, rs := 0, []rune(command); i < len(rs); i++ {
		r := rs[i]
		switch {
		case quote != 0:
			if r == quote {
				quote = 0
			} else {
				token.WriteRune(r)
			}
			active = true
		case r == '\'' || r == '"':
			quote = r
			active = true
		case r == ' ' || r == '\t' || r == '\r':
			flush()
		case r == '|', r == ';', r == '\n', r == '(', r == ')', r == '`':
			return nil, false
		case r == '&':
			if i > 0 && rs[i-1] == '>' && i+1 < len(rs) &&
				((rs[i+1] >= '0' && rs[i+1] <= '9') || rs[i+1] == '-') {

				token.WriteRune(r)
				active = true
				continue
			}
			if i+1 >= len(rs) || rs[i+1] != '&' {
				return nil, false
			}
			flush()
			if len(fields) == 0 {
				return nil, false
			}
			segments = append(segments, fields)
			fields = nil
			i++
		case r == '$' && i+1 < len(rs) && (rs[i+1] == '(' || rs[i+1] == '{'):
			return nil, false
		default:
			token.WriteRune(r)
			active = true
		}
	}
	if quote != 0 {
		return nil, false
	}
	flush()
	if len(fields) == 0 {
		return nil, false
	}
	segments = append(segments, fields)
	return segments, true
}

n_permgate_splitSegments.signature:
// splitSegments 按 shell 的命令分隔符把文本切成独立命令段。
//
// 为什么必须先切段：判定问的是「handoff 之后跟了什么」，而 | ; & 之后的词元
// 属于另一条命令。不切的话 `handoff tasks | grep done` 里的 done 会被算成
// handoff 的候选子命令，把一次只读调用误判成变更调用。
func splitSegments(s string) []string {
	return strings.FieldsFunc(s, func(r rune) bool {
		return r == '|' || r == ';' || r == '&' || r == '\n'
	})
}

n_permgate_splitWriteSegments.signature:
// splitWriteSegments 按 shell 的命令分隔符把命令串切成段，引号内的分隔符不算。
//
// 参数：cmd 为命令原文
// 返回：各段原文（可能含前导空白），空段丢弃
//
// 为什么不复用 selfcmd.go 里的 splitSegments：那个用 strings.FieldsFunc，
// **不认引号**——`git commit -m "a | tee /etc/x"` 会被它切出一段 `tee /etc/x`，
// 在本文件里就成了一次凭空的越界升级。那边不认引号是刻意的（judgeCommand 对
// 原文与 StripQuoted 结果各跑一遍来覆盖包装器），改它会动到自指令判据，不碰。
func splitWriteSegments(cmd string) []string {
	var out []string
	var b strings.Builder
	var quote rune
	flush := func() {
		if s := strings.TrimSpace(b.String()); s != "" {
			out = append(out, s)
		}
		b.Reset()
	}
	for _, r := range cmd {
		switch {
		case quote == 0 && (r == '\'' || r == '"'):
			quote = r
			b.WriteRune(r)
		case quote != 0 && r == quote:
			quote = 0
			b.WriteRune(r)
		case quote == 0 && (r == '|' || r == '&' || r == ';' || r == '\n'):
			flush()
		default:
			b.WriteRune(r)
		}
	}
	flush()
	return out
}

n_permgate_targetsOf.signature:
// targetsOf 按落点种类从参数列表里挑出目的地。
//
// 参数：kind 为落点种类，args 为命令名之后的全部词元
// 返回：落点切片；判不出（如 cp 只给了一个参数）时返回 nil
func targetsOf(kind argTargetKind, args []string) []string {
	if kind == targetOfPrefix {
		var out []string
		for _, a := range args {
			if v, ok := strings.CutPrefix(a, "of="); ok && v != "" {
				out = append(out, v)
			}
		}
		return out
	}

	var plain []string	// 非标志参数
	var byFlag []string
	endOfFlags := false
	for i := 0; i < len(args); i++ {
		a := args[i]
		if !endOfFlags && a == "--" {
			endOfFlags = true
			continue
		}
		if !endOfFlags && strings.HasPrefix(a, "-") && a != "-" {

			if v, ok := strings.CutPrefix(a, "--target-directory="); ok && v != "" {
				byFlag = append(byFlag, v)
				continue
			}
			if a == "-t" || a == "--target-directory" {
				if i+1 < len(args) {
					byFlag = append(byFlag, args[i+1])
					i++
				}
				continue
			}
			continue
		}
		plain = append(plain, a)
	}
	if len(byFlag) > 0 {
		return byFlag
	}
	switch kind {
	case targetAllArgs:
		return plain
	case targetLastArg:

		if len(plain) < 2 {
			return nil
		}
		return plain[len(plain)-1:]
	case targetGofmt:
		write := false
		for _, a := range args {
			if a == "-w" {
				write = true
				continue
			}
			if write && !strings.HasPrefix(a, "-") {
				byFlag = append(byFlag, a)
			}
		}
		return byFlag
	case targetGit:
		if len(args) == 0 {
			return nil
		}
		switch args[0] {
		case "add":
			return targetsOf(targetAllArgs, args[1:])
		case "diff":
			var out []string
			for i := 1; i < len(args); i++ {
				a := args[i]
				if v, ok := strings.CutPrefix(a, "--output="); ok && v != "" {
					out = append(out, v)
					continue
				}
				if a == "--output" && i+1 < len(args) && args[i+1] != "" {
					i++
					out = append(out, args[i])
				}
			}
			return out
		default:
			return nil
		}
	}
	return nil
}

n_permgate_tokenize.signature:
// tokenize 把一段命令切成词元，引号内的空白不分词、包裹引号被去掉。
//
// 参数：seg 为单段命令原文
// 返回：词元切片
//
// 复用 readTarget 而不是另写一个扫描器：落点词元与命令词元的边界规则是同一套，
// 两份实现迟早会漂移。
func tokenize(seg string) []string {
	var out []string
	rs := []rune(seg)
	for i := 0; i < len(rs); {
		switch rs[i] {
		case ' ', '\t', '\n':
			i++
			continue
		case '>', '<', '(', ')':

			return out
		}
		tok, next := readTarget(rs, i)
		if next == i {
			i++
			continue
		}
		i = next
		if tok != "" {
			out = append(out, tok)
		}
	}
	return out
}

n_prochost_AcquireLock.signature:
// AcquireLock 对 path 取非阻塞排他锁（文件不存在则以 0600 创建）。
//
// 返回：
//   - 持锁句柄；调用方须持有到不再需要为止
//   - 锁已被他人持有时返回包装了 ErrLockHeld 的错误
//   - 其他失败（打不开、文件系统不支持 flock）返回普通错误
//
// 注意：锁挂在「打开的文件描述」上，不在路径上——`rm` 掉锁文件不能解锁；
// 锁 fd 也不会被子进程继承（Go 的 exec 只传 ExtraFiles），因此锁精确代表本进程。
func AcquireLock(path string) (*Lock, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return nil, fmt.Errorf("打开锁文件 %s: %w", path, err)
	}
	if err := flockExclusiveNB(f); err != nil {
		f.Close()
		if isLockContended(err) {
			return nil, fmt.Errorf("抢占锁 %s: %w", path, ErrLockHeld)
		}
		return nil, fmt.Errorf("给 %s 加锁: %w", path, err)
	}
	return &Lock{f: f}, nil
}

n_prochost_Admission_NearFull.signature:
// NearFull 报告是否已达高水位（参考上限的九成）。读数不可信时恒为 false。
func (a Admission) NearFull() bool {
	return a.Known && float64(a.Used) >= float64(a.Limit)*fenceWatermarkRatio
}

n_prochost_Alive.signature:
// Alive 报告 Handle 对应的 shim 是否仍然活着。
//
// 判据：LockPath 上的排他锁被占用。锁由内核在进程死亡时释放，因此本判定
// 不存在 pid 复用误判，也不需要任何清理代码配合。
//
// 返回：LockPath 为空、文件不存在或探测出错时一律返回 false（保守：宁可判死
// 后走恢复流程，也不要把死进程当活的导致任务永远卡住）。
func Alive(h Handle) bool {
	if h.LockPath == "" {
		return false
	}
	locked, err := IsLocked(h.LockPath)
	if err != nil {
		log().Debug("探测存活锁失败，按已死处理", "lock", h.LockPath, "cause", err)
		return false
	}
	return locked
}

n_prochost_CheckAdmission.signature:
// CheckAdmission 零 fork 读一次当前余量。
//
// 返回：Admission；任何一步读不到数都返回零值（Known=false）。
//
// 注意：读不到数时**不报错也不猜 0**，而是让调用方 fail-open 照常放行。
// 为「量不出来」而拒绝派发，会让 handoff 在不支持的平台上彻底不能用，
// 代价远大于收益——防护装置故障不该变成拒绝服务。
func CheckAdmission() Admission {
	procs, err := enumProcsFn()
	if err != nil {
		log().Debug("余量判读失败（枚举进程），按未知处理", "cause", err)
		return Admission{}
	}
	ref, err := fenceReference()
	if err != nil || ref <= 0 {
		log().Debug("余量判读失败（参考上限不可用），按未知处理", "cause", err, "ref", ref)
		return Admission{}
	}
	used, excluded := chargeableProcessCount(procs)
	if excluded > 0 {
		log().Debug("机器级进程压力统计排除 ptyhost", "excluded", excluded,
			"observed", len(procs), "used", used)
	}
	return Admission{Used: used, Limit: ref, Known: true}
}

n_prochost_ChildPID.signature:
// ChildPID 读取 shim 记下的执行者 pid（诊断用）。
//
// 参数：infoPath 为 adapter 的 proc.json 路径，仅用于定位同目录的 child.pid
//
// 返回：文件缺失（shim 没起来过/还没 spawn 完）或内容非法时返回错误——
// 绝不返回 0 冒充成功，0 会被误读成「pid 为 0 的进程」。
func ChildPID(infoPath string) (int, error) {
	p := childPIDPath(infoPath)
	b, err := os.ReadFile(p)
	if err != nil {
		return 0, fmt.Errorf("读 %s: %w", p, err)
	}
	pid, err := strconv.Atoi(strings.TrimSpace(string(b)))
	if err != nil {
		return 0, fmt.Errorf("解析 %s 内容 %q: %w", p, b, err)
	}
	return pid, nil
}

n_prochost_CountGroup.signature:
// CountGroup 数出进程组 pgid 当前有多少个属于本 uid 的成员。
//
// 参数：pgid 为进程组 id（PTY 会话里就是 shell 自己的 pid，因为它 setsid 后
// 是组长）
//
// 返回：成员数；枚举失败时上抛错误（**不降级成 0**——0 会被渲染成「没有残留」，
// 那是个我们并没有得出的结论）
//
// 注意：
//   - 与 Footprint 不同，这里**没有启动时刻校验**。Footprint 面对的是可能已死的
//     shim，pid 复用是真实风险；本函数的调用方仍然持有组长进程（会话活着、
//     *os.Process 未被回收），此时组长的 pid 不可能被复用，多一道校验只会
//     要求调用方额外记一个内核时间戳
//   - 因此**只能对仍存活的组调用**。对已退出的会话调用它，数出来的东西没有身份
//   - 只读，绝不发信号
func CountGroup(pgid int) (int, error) {
	procs, err := enumProcsFn()
	if err != nil {
		log().Error("进程组计数失败", "pgid", pgid, "cause", err)
		return 0, err
	}
	n := 0
	for _, p := range procs {
		if p.PGID == pgid {
			n++
		}
	}
	log().Debug("进程组计数完成", "pgid", pgid, "members", n)
	return n, nil
}

n_prochost_CreateInputChannel.signature:
// CreateInputChannel 幂等创建输入通道（unix 为 0600 命名管道，Windows 由平台实现）。
//
// 参数：path 为通道路径（通常是 <taskDir>/in.fifo）
//
// 返回：
//   - 已存在且确实是命名管道 → nil（复用）
//   - 已存在但是普通文件/目录 → 错误（残留物会让平台输入通道语义完全改变，必须
//     显式失败而不是静默当通道用）
func CreateInputChannel(path string) error	{ return createInputChannel(path) }

n_prochost_ExplainForkFailure.signature:
// ExplainForkFailure 判读一个进程创建失败是否为配额耗尽，并给出可读归因。
//
// 参数：err 为任意一次 fork/exec 返回的错误（nil 安全）
//
// 返回：
//   - note: 面向人的归因文案；空串表示这个错误与配额无关，调用方不必改写它
//   - quota: 是否**确定**为配额耗尽
//
// 参考上限是**本进程当前实际生效的 RLIMIT_NPROC 软限**（getNprocLimit），不是
// 按 reserve_ratio 重算的策略默认值：fork 失败正是内核拿「调用者自己的软限」
// 比「uid 进程总数」得出的，归因必须引用它。在 shim 里它就是刚装上的围栏
// （spec.NprocLimit）；在 agentd 里它是系统默认上限。两个都不用记账，读现成的。
//
// 三条分支，对应 2026-08-12 事故的教训——当时的
// `fork/exec /bin/sh: resource temporarily unavailable` 埋在测试输出里，长得
// 像 flaky 测试，把排障方向带偏了整整 43 分钟：
//   - 非 EAGAIN：不认领，返回空串
//   - EAGAIN 且占用 ≥ 实际软限：**确定**归因，quota=true，文案带真实数字——
//     内核正是在 used ≥ 软限这个阈值上拒绝 fork，占用不低于它就不可能别的原因
//   - EAGAIN 但占用低于实际软限、或读不出数：**如实说不知道**，quota=false。
//     宁可说「原因未知」也不能猜一个像模像样的结论
func ExplainForkFailure(err error) (note string, quota bool) {
	if err == nil || !errors.Is(err, syscall.EAGAIN) {
		return "", false
	}
	procs, perr := enumProcsFn()
	if perr != nil {
		log().Warn("进程创建失败（EAGAIN），但读不到当前占用，无法归因")
		return "进程创建失败（EAGAIN），且读不到当前进程占用，原因未知", false
	}
	limit, lerr := getNprocLimitFn()
	if lerr != nil || limit <= 0 {
		log().Warn("进程创建失败（EAGAIN），但读不到本进程实际生效的进程数上限，无法归因",
			"cause", lerr, "limit", limit)
		return "进程创建失败（EAGAIN），且读不到本进程实际生效的进程数上限，原因未知", false
	}
	used := len(procs)
	if used >= limit {
		log().Error("进程配额耗尽", "used", used, "limit", limit)
		return fmt.Sprintf("进程配额耗尽（当前 uid %d/%d），命令未执行；"+
			"这不是代码问题，请降低并发后重试", used, limit), true
	}
	log().Warn("进程创建失败（EAGAIN），但占用低于实际上限，原因未知",
		"used", used, "limit", limit)
	return fmt.Sprintf("进程创建失败（EAGAIN），但当前占用仅 %d/%d，"+
		"不像配额问题，原因未知", used, limit), false
}

n_prochost_FallbackKind.signature:
// FallbackKind 报告任务标记归属不可用时，进程归属实际靠什么判定。
//
// 返回：给人读的判据名称，用于启动日志。
//
// 为什么要有这个函数而不是在调用处写死一句话：启动日志原本硬写「退回 pgid +
// 名册采样」，那是 unix 的形态。Windows 上根本没有 pgid，B122 之后实际靠的是
// Job Object 成员表——一条在半数机器上事实错误的 WARN，恰恰出现在操作者排查
// 足迹问题时第一眼会看的地方。判据归谁知道，文案就该由谁给。
func FallbackKind() string {
	if containerSampleFn != nil {
		return "进程容器成员表"
	}
	return "pgid + 名册采样"
}

n_prochost_Footprint.signature:
// Footprint 枚举 h 所代表任务当前占用的进程。
//
// 参数：h 为任务的进程句柄（来自 proc.json）
//
// 返回：
//   - members: 通过身份校验的成员 pid
//   - v: 判定结论；非 VerdictOK 时 members 必然为空
//   - err: 进程枚举失败（平台不支持时为 ErrNotSupported）
//
// 注意：
//   - **只读，绝不发信号**——它是 Sweep 的孪生只读版本，两者共用 classify
//   - 对**存活中**与**已死亡**的执行者均可调用：判据随存活锁状态自动切换
//   - **members 是三段并集**：pgid 组 + 出生名册里仍存活且身份吻合的逃逸后代 +
//     任务标记命中的进程。第三段覆盖「壳活得太短、一次都没被采样到」的残留。
//     Sweep 也必须同步三段，报的数和杀的范围必须一致，否则 handoff footprint
//     就变成一句骗人的话（B70：宣称什么就得是什么）
func Footprint(h Handle) (members []int, v Verdict, err error) {

	if h.MembersPath != "" {
		if snap, rerr := readMembers(h.MembersPath); rerr == nil {
			log().Debug("足迹取自进程容器成员表", "pid", h.PID,
				"members", len(snap.PIDs), "sampled_at", snap.SampledAt)
			return snap.PIDs, VerdictOK, nil
		} else {

			log().Debug("容器成员快照不可用，落回 pgid 判据", "pid", h.PID,
				"path", h.MembersPath, "cause", rerr)
		}
	}
	procs, err := enumProcsFn()
	if err != nil {
		logEnumFailure("足迹枚举失败", err, "pid", h.PID)
		return nil, VerdictNoCredential, err
	}
	members, v = classify(h, procs, aliveFn(h))
	byPgid := len(members)
	var byRoster, byMark, markOnly int
	markSupported := false
	if v == VerdictOK {

		seen := make(map[int]bool, len(members))
		for _, p := range members {
			seen[p] = true
		}
		for _, p := range rosterMembers(h, procs) {
			byRoster++
			if !seen[p] {
				members = append(members, p)
				seen[p] = true
			}
		}

		marked, supported := markMembers(h.cred(), procs)
		markSupported = supported
		for _, p := range marked {

			if startedAtOf(procs, p) < h.StartedAt {
				continue
			}
			byMark++
			if !seen[p] {
				members = append(members, p)
				seen[p] = true
				markOnly++
			}
		}
	}
	log().Debug("足迹判定完成", "pid", h.PID, "verdict", string(v),
		"members", len(members), "by_pgid", byPgid, "by_roster", byRoster,
		"by_mark", byMark, "mark_only", markOnly, "mark_supported", markSupported)
	return members, v, nil
}

n_prochost_Handle_cred.signature:
// cred 把 Handle 投影成一次归属判定所需的凭据。
//
// 为什么要单独一层而不是让判据直接吃 Handle：判据只需要这两个字段，
// 传整个 Handle 会让 taskmark.go 依赖 PID/LockPath 这些与它无关的东西，
// 单测也得构造无关字段。
func (h Handle) cred() TaskCred {
	return TaskCred{TaskID: h.TaskID, MarkRoot: h.MarkRoot}
}

n_prochost_IsLocked.signature:
// IsLocked 报告 path 上的排他锁当前是否被某个进程持有。
//
// 实现：试着非阻塞抢锁——抢到说明没人持有（随即释放），撞锁说明有人持有。
// 文件不存在视为无人持有（返回 false，且**不建文件**：探测不应有副作用）。
func IsLocked(path string) (bool, error) {
	f, err := os.OpenFile(path, os.O_RDWR, 0o600)
	if err != nil {
		if os.IsNotExist(err) {
			return false, nil
		}
		return false, fmt.Errorf("打开锁文件 %s: %w", path, err)
	}
	defer f.Close()
	if err := flockExclusiveNB(f); err != nil {
		if isLockContended(err) {
			return true, nil
		}
		return false, fmt.Errorf("试锁 %s: %w", path, err)
	}
	return false, nil
}

n_prochost_Kill.signature:
// Kill 终止 shim 及其全部后代，并**复核它是否真的死了**。
//
// unix 通过 shim 的进程组回收，Windows 终止 shim 后由 Job Object 句柄关闭连坐回收。
//
// 幂等：锁已空闲说明 shim 已死，直接返回 nil——**绝不对该 pid 发任何信号**，
// 因为它可能已被操作系统复用给毫不相干的进程（workspace.go 的历史教训：
// 旧实现 300 条成功命令误杀 114 次）。
//
// 参数：
//   - h: 目标 shim 的 Handle；PID <= 0 视为无进程可杀，直接 nil
//
// 返回：
//   - nil: 已确认进程组退出（或本来就已经死了）
//   - 包装 ErrStillAlive 的错误: 信号发出去了，但复核窗口（killVerifyWindow）
//     走完进程仍存活——调用方应保留运行态、上抛给 agentd 提示人工
//   - 其它错误: 信号发送本身失败
//
// 注意：
//   - 复核判据用 Alive（文件锁）而非 kill(pid, 0)：锁由内核在进程死亡时释放，
//     不存在 pid 复用误判，而 kill(pid,0) 会把「pid 被复用」误报成「还活着」
//   - 本函数在确认死亡前不返回，因此调用方紧随其后的资源清理
//     （如 RemoveManagedWorktree）天然排在进程真死之后，不需要额外同步
func Kill(h Handle) error {
	if h.PID <= 0 {
		return nil
	}
	if !aliveFn(h) {
		log().Info("存活锁已释放，无需回收", "pid", h.PID, "lock", h.LockPath)
		return nil
	}
	log().Info("回收执行者进程组", "pid", h.PID)
	if err := killGroupFn(h.PID); err != nil {
		log().Error("回收执行者进程组失败", "pid", h.PID, "cause", err)
		return fmt.Errorf("回收进程组 %d: %w", h.PID, err)
	}
	for i, d := range killVerifyBackoff {
		time.Sleep(d)
		if !aliveFn(h) {
			log().Info("回收完成，已确认进程组退出", "pid", h.PID, "probe", i+1)
			return nil
		}
	}
	log().Error("已发 SIGKILL 但复核窗口走完仍存活，可能有逃逸出进程组的后代",
		"pid", h.PID, "lock", h.LockPath, "window", killVerifyWindow)
	return fmt.Errorf("%w: pid=%d，已发 SIGKILL 并复核 %s", ErrStillAlive, h.PID, killVerifyWindow)
}

n_prochost_LockSupported.signature:
// LockSupported 报告本平台是否真的能加锁。
//
// 为什么要暴露：非 unix 平台上加锁是空操作，调用方需要据此打 Warn 明说
// 「保护未生效」，而不是让人误以为锁住了。
func LockSupported() bool	{ return lockSupported }

n_prochost_Lock_Release.signature:
// Release 释放锁。重复调用安全（第二次直接返回 nil）。
//
// 生产侧可有可无——进程退出内核即释放；保留它是为了 defer 的习惯写法，
// 以及让测试能验证「释放后可重新获取」。
func (l *Lock) Release() error {
	if l == nil || l.f == nil {
		return nil
	}
	path := l.f.Name()
	err := l.f.Close()
	l.f = nil
	if err != nil {
		return fmt.Errorf("释放锁 %s: %w", path, err)
	}
	return nil
}

n_prochost_MarkCapability.signature:
// MarkCapability 报告本平台是否具备任务标记归属能力。
//
// 返回：
//   - supported: 是否可用
//   - reason: 不可用的原因（供启动期日志直接呈现）；可用时为空串
//
// 为什么要单独一个导出函数而不是让 agentd 自己试：能力判定的依据在包内
// （平台实现 + darwin 的运行期自检），暴露一个明确的问句比让调用方
// 拿一个假 pid 去试要诚实得多。
func MarkCapability() (supported bool, reason string) {

	_, err := attributesFn(os.Getpid(), TaskCred{TaskID: "capability-probe", MarkRoot: os.TempDir()})
	if err != nil && isNotSupported(err) {
		return false, "本平台不支持任务标记归属"
	}
	return true, ""
}

n_prochost_ProcessCredentialForPID.signature:
// ProcessCredentialForPID 读取一个当前 uid 进程的内核启动时刻。
//
// 参数：pid 是要查的进程号。
// 返回：找到时返回 PID 与启动时刻及 true；进程不存在、枚举失败或启动时刻缺失时
// 返回零值与 false。
// 注意：调用方应把 false 当成“无法证明身份”，不能因此排除该进程。
func ProcessCredentialForPID(pid int) (ProcessCredential, bool) {
	if pid <= 0 {
		return ProcessCredential{}, false
	}
	procs, err := enumProcsFn()
	if err != nil {
		return ProcessCredential{}, false
	}
	for _, proc := range procs {
		if proc.PID == pid && proc.StartedAt > 0 {
			return ProcessCredential{PID: proc.PID, StartedAt: proc.StartedAt}, true
		}
	}
	return ProcessCredential{}, false
}

n_prochost_PtyhostCredentials.signature:
// PtyhostCredentials 返回当前已登记的 ptyhost 凭据快照。
//
// 返回：提供者给出的凭据切片；未设置提供者时为 nil。
// 注意：这是只读视图，供调用方核对「某个真实会话是否已成为可验证凭据」。
// **不要拿它自己做扣减** —— 扣减判据（PID 与启动时刻必须同时匹配）在
// chargeableProcessCount 里，绕过它会把 PID 复用误判成 ptyhost。
func PtyhostCredentials() []ProcessCredential {
	provider := currentPtyhostCredentialProvider()
	if provider == nil {
		return nil
	}
	return provider()
}

n_prochost_ResolveMarkRoot.signature:
// ResolveMarkRoot 把一个工作目录路径归一成可用于 cwd 比对的形态。
//
// 参数：dir 为任务工作区目录；managed 表示它是否为 agentd 托管的 worktree
//
// 返回：可比对的绝对路径；不允许用 cwd 归属时返回空串
//
// 注意：**必须做符号链接解析**。内核返回的 cwd 是解析后的（macOS 上
// /var/... 会变成 /private/var/...），直接拿未解析的路径去比会得到一个
// 看起来很干净的假阴性——判据静默失效而没有任何报错。
func ResolveMarkRoot(dir string, managed bool) string {
	if !managed || dir == "" {
		return ""
	}
	resolved, err := filepathEvalSymlinks(dir)
	if err != nil {
		log().Warn("解析 worktree 路径失败，本任务不启用 cwd 归属",
			"dir", dir, "cause", err)
		return ""
	}
	return resolved
}

n_prochost_RunShim.signature:
// RunShim 是 shim 进程的入口：读 spec、持锁、拉起 executor、收尸写哨兵。
//
// 参数：specPath 为 Start 落盘的 spec.json 路径
//
// 返回：
//   - 锁已被持有（同任务已有 shim 在跑）、spec 不可读、子进程拉不起来时返回错误
//   - 子进程本身以非零码退出**不算错误**：那是正常业务结果，经哨兵传达
//
// 注意：本函数会阻塞到子进程退出，调用方（handoff _shim）随后即可退出。
func RunShim(specPath string) error {
	spec, err := readSpec(specPath)
	if err != nil {
		return err
	}
	l := log().With("lock", spec.LockPath)

	lock, err := AcquireLock(spec.LockPath)
	if err != nil {
		l.Error("抢占存活锁失败，同任务可能已有 shim 在跑", "cause", err)
		return fmt.Errorf("shim 抢锁: %w", err)
	}
	defer lock.Release()

	stdout, err := openAppend(spec.Stdout)
	if err != nil {
		l.Error("打开 stdout 落盘文件失败", "path", spec.Stdout, "cause", err)
		return err
	}
	defer stdout.Close()
	stderr := stdout
	if spec.Stderr != "" && spec.Stderr != spec.Stdout {
		stderr, err = openAppend(spec.Stderr)
		if err != nil {
			l.Error("打开 stderr 落盘文件失败", "path", spec.Stderr, "cause", err)
			return err
		}
		defer stderr.Close()
	}

	if cerr := installProcessContainer(spec.NprocLimit); cerr != nil {
		l.Error("安装进程容器失败，放弃拉起执行者", "limit", spec.NprocLimit, "cause", cerr)
		return fmt.Errorf("安装进程容器: %w", cerr)
	}

	cmd := exec.Command(spec.Argv[0], spec.Argv[1:]...)
	cmd.Dir = spec.Dir
	cmd.Env = spec.Env
	cmd.Stdout = stdout
	cmd.Stderr = stderr
	if spec.InputCh != "" {

		in, cleanup, ferr := openInputChannel(spec.InputCh)
		if ferr != nil {
			l.Error("打开输入通道失败", "path", spec.InputCh, "cause", ferr)
			return fmt.Errorf("打开输入通道 %s: %w", spec.InputCh, ferr)
		}
		defer cleanup()
		cmd.Stdin = in
		l.Info("输入通道已就位", "path", spec.InputCh)
	}

	l.Info("shim 拉起执行者进程", "bin", spec.Argv[0], "dir", spec.Dir,
		"env_keys", envKeys(spec.Env), "input_ch", spec.InputCh != "")

	if err := cmd.Start(); err != nil {
		if note, _ := ExplainForkFailure(err); note != "" {
			l.Error("拉起执行者进程失败（进程配额）", "bin", spec.Argv[0],
				"note", note, "fence", spec.NprocLimit, "cause", err)
			return fmt.Errorf("%s: 拉起 %s: %w", note, spec.Argv[0], err)
		}
		l.Error("拉起执行者进程失败", "bin", spec.Argv[0], "cause", err)
		return fmt.Errorf("拉起 %s: %w", spec.Argv[0], err)
	}
	childPID := cmd.Process.Pid
	if err := recordChildPID(spec.InfoPath, childPID); err != nil {

		l.Warn("记录 child.pid 失败，不影响执行", "path", childPIDPath(spec.InfoPath), "cause", err)
	}
	l.Info("执行者进程已启动", "child_pid", childPID)

	stopRoster := make(chan struct{})
	rosterDone := make(chan struct{})
	go func() {
		defer close(rosterDone)

		if containerSampleFn != nil {
			sampler := &membersSampler{path: membersPath(spec.InfoPath)}
			runContainerSampling(stopRoster, sampler, l)
			return
		}

		sampler := &rosterSampler{path: rosterPath(spec.InfoPath)}
		runRosterSampling(stopRoster, sampler, l)
	}()

	code := 0
	if werr := cmd.Wait(); werr != nil {
		var ee *exec.ExitError
		if errors.As(werr, &ee) {
			code = ee.ExitCode()
		} else {
			l.Error("等待执行者进程失败", "child_pid", childPID, "cause", werr)
			code = -1
		}
	}

	close(stopRoster)
	<-rosterDone
	l.Info("出生登记已停止", "roster", rosterPath(spec.InfoPath))
	if spec.Sentinel {
		if _, err := fmt.Fprintf(stdout, "{%s,\"code\":%d}\n", SentinelPrefix, code); err != nil {

			l.Error("写死亡哨兵失败，恢复流程将无法判死", "child_pid", childPID, "cause", err)
		}
	}
	l.Info("执行者进程已退出", "child_pid", childPID, "code", code, "sentinel", spec.Sentinel)
	return nil
}

n_prochost_SetFencePolicy.signature:
// SetFencePolicy 注入围栏策略，由 agentd 启动时按 config 调用一次。
//
// 参数：
//   - disabled: true 时完全不装围栏（逃生开关）
//   - reserveRatio: 保留额占系统上限的比例；不在 (0,1) 区间时保留默认值 0.1
//     （只在 unix 的比例模式下生效）
//   - taskHardLimit: 每任务进程数硬上限（只在 Windows 的硬上限模式下生效；0=不启用）
//
// 注意：shim 是独立进程、从不调用本函数，它拿到的围栏值来自 spec.NprocLimit
// （agentd 侧 applyFencePolicy 算好后下发），所以本函数只影响 agentd 侧的计算。
// 本函数只改包级策略，不会影响已经拉起的 shim——它们的围栏在 fork 那一刻就定死了，
// 改策略只对之后启动的任务生效。
func SetFencePolicy(disabled bool, reserveRatio float64, taskHardLimit int) {
	fenceDisabled = disabled
	if reserveRatio > 0 && reserveRatio < 1 {
		fenceReserveRatio = reserveRatio
	}
	fenceTaskHardLimit = taskHardLimit
	log().Info("进程围栏策略已设定", "disabled", fenceDisabled,
		"reserve_ratio", fenceReserveRatio, "task_hard_limit", taskHardLimit,
		"hard_limit_mode", fenceHardLimitMode)
}

n_prochost_SetPtyhostCredentialProvider.signature:
// SetPtyhostCredentialProvider 设置机器级进程压力统计的 ptyhost 凭据来源。
//
// 参数：provider 是当前 agentd 的凭据提供者；传 nil 表示不排除任何进程。
// 返回：无。
// 注意：agentd 启动时设置一次；调用方必须保证 provider 返回的是仍然持有会话锁的
// ptyhost。未知或过期凭据不能用于扣减统计，否则会把 PID 复用误判成 ptyhost。
func SetPtyhostCredentialProvider(provider PtyhostCredentialProvider) {
	ptyhostCredentialMu.Lock()
	ptyhostCredentialProvider = provider
	ptyhostCredentialMu.Unlock()
}

n_prochost_Start.signature:
// Start 以 detached 方式拉起 shim，由 shim 承载 spec 描述的执行者进程。
//
// 参数：
//   - spec: 启动描述；LockPath/InfoPath/Stdout 必填，Argv[0] 必须是绝对路径
//   - selfExe: handoff 自身可执行文件路径（os.Executable() 的结果）
//   - extraArgs: 附加给 selfExe 的参数；生产传空，测试用它指向测试二进制的 shim 入口
//
// 返回：
//   - Handle（PID 为 shim 的 pid；unix 上同时是进程组 id）；spec 落盘失败或 fork 失败时返回错误
//
// 注意：
//   - 返回只代表 shim 已被 fork，**不代表它已持锁或已打开 FIFO**。调用方若要
//     投递输入，必须先 WaitInputReader；若要判存活，必须轮询 Alive 而非立即断言
//   - spec.json 以 0600 落在 InfoPath 同目录：它含完整 env（可能有凭据），
//     权限不能放宽
func Start(spec Spec, selfExe string, extraArgs ...string) (Handle, error) {
	specPath := filepath.Join(filepath.Dir(spec.InfoPath), "spec.json")
	applyFencePolicy(&spec)
	applyTaskMark(&spec)
	log().Debug("任务标记凭据已就位", "task_id", spec.TaskID,
		"mark_root", spec.MarkRoot, "env_injected", spec.TaskID != "")
	b, err := json.Marshal(spec)
	if err != nil {
		return Handle{}, fmt.Errorf("序列化 spec: %w", err)
	}
	if err := os.WriteFile(specPath, b, 0o600); err != nil {
		return Handle{}, fmt.Errorf("写 spec %s: %w", specPath, err)
	}
	argv := append([]string{selfExe}, extraArgs...)
	argv = append(argv, "_shim", "--spec", specPath)

	// shim 的 stderr 接进任务目录的 shim.log：shim 是独立进程，日志走 slog→stderr，
	// 不接的话会落进 /dev/null（spawnDetached 的 stdio=nil），撞墙归因那一行谁
	// 都看不到——2026-08-12 烟测实证「装了围栏却报 363/2400」的归因行确实被丢掉。
	// 打开失败只降级（shim 输出继续落 /dev/null），绝不阻断拉起。
	var shimLog *os.File
	if spec.InfoPath != "" {
		shimLogPath := filepath.Join(filepath.Dir(spec.InfoPath), "shim.log")
		shimLog, err = os.OpenFile(shimLogPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
		if err != nil {
			log().Warn("打开 shim 日志文件失败，shim 输出将落入 /dev/null",
				"path", shimLogPath, "cause", err)
		} else {
			defer shimLog.Close()
		}
	}
	pid, err := spawnDetached(argv, spec.Dir, shimLog)
	if err != nil {
		log().Error("拉起 shim 失败", "spec", specPath, "cause", err)
		return Handle{}, err
	}

	startedAt := lookupStartedAt(pid)
	if startedAt <= 0 {
		log().Warn("读不到 shim 启动时刻，该任务将只能上报残留、无法自动清扫",
			"pid", pid, "spec", specPath)
	}
	roster := rosterPath(spec.InfoPath)
	members := ""
	if containerSampleFn != nil {
		members = membersPath(spec.InfoPath)
	}
	log().Info("shim 已拉起", "pid", pid, "bin", spec.Argv[0], "spec", specPath,
		"started_at", startedAt, "roster", roster, "members", members)
	return Handle{
		PID:		pid,
		LockPath:	spec.LockPath,
		StartedAt:	startedAt,
		RosterPath:	roster,
		MembersPath:	members,
		TaskID:		spec.TaskID,
		MarkRoot:	spec.MarkRoot,
	}, nil
}

n_prochost_Sweep.signature:
// Sweep 回收一个执行者留下的残留后代（执行者仍存活时降级为只做名册点名）。
//
// 参数：h 为任务的进程句柄（来自 proc.json）
//
// 返回：
//   - killed: 实际发出信号回收的成员数（0 表示没动手）
//   - v: 判定结论；非 VerdictOK 时必然 killed == 0
//   - err: 执行者仍存活（ErrExecutorAlive，此时段②已执行、killed 可非 0）、枚举失败、
//     或已发信号但复核仍存活（ErrStillAlive）
//
// 注意：
//   - **存活时降级**：存活锁仍被持有时跳过组清扫（杀活着的执行者是 Kill 的职责），
//     但名册点名照做。两者风险模型不同，互相代劳会把 Kill 那条纪律绕过去
//   - 判定为放弃（leader_reuse / no_credential）**不是错误**，是正常结论：
//     调用方据 v 决定是否上报人工，不该按 err != nil 判
//   - 与 Kill 一致：发完 SIGKILL 必须复核，复核窗口走完仍存活返回 ErrStillAlive
//   - **三段判据**：第一段按 pgid 回收「shim + executor 本体」这一层；第二段按
//     出生名册点名回收 executor 经 Bash 工具 setsid 逃逸出去的后代（B72）；第三段
//     按任务标记逐个回收壳活得太短、一次都没被采样到的残留。第三段比名册段更强在
//     活读 + 杀前复验；macOS 非托管任务没有 MarkRoot，在这一段天然是 no-op。
//     名册缺失或平台不支持时各自自动降级，不影响其它来源。
func Sweep(h Handle) (killed int, v Verdict, err error) {
	if aliveFn(h) {

		procs, eerr := enumProcsFn()
		if eerr != nil {
			logEnumFailure("降级清扫前枚举进程失败", eerr, "pid", h.PID)
			return 0, VerdictNoCredential, eerr
		}
		n := rosterKill(h, procs)
		log().Info("执行者存活，跳过组清扫，转入点名回收",
			"pid", h.PID, "lock", h.LockPath, "killed", n)
		return n, VerdictOK, ErrExecutorAlive
	}
	procs, eerr := enumProcsFn()
	if eerr != nil {
		logEnumFailure("清扫前枚举进程失败", eerr, "pid", h.PID)
		return 0, VerdictNoCredential, eerr
	}
	members, v := classify(h, procs, false)
	if v != VerdictOK {

		log().Warn("组清扫放弃，仍尝试点名回收", "pid", h.PID, "verdict", string(v))
		return rosterKill(h, procs) + markKill(h, procs), v, nil
	}
	if len(members) == 0 {
		log().Info("组内无残留，转入点名回收", "pid", h.PID)
		return rosterKill(h, procs) + markKill(h, procs), VerdictOK, nil
	}
	log().Info("回收残留进程组", "pid", h.PID, "members", len(members), "pids", members)
	if kerr := killGroupFn(h.PID); kerr != nil {
		log().Error("回收残留进程组失败", "pid", h.PID, "cause", kerr)
		return 0, VerdictOK, fmt.Errorf("回收进程组 %d: %w", h.PID, kerr)
	}

	for i, d := range killVerifyBackoff {
		time.Sleep(d)
		rest, rerr := enumProcsFn()
		if rerr != nil {
			log().Error("复核枚举失败", "pid", h.PID, "cause", rerr)
			break
		}
		if left, _ := classify(h, rest, false); len(left) == 0 {
			rk := rosterKill(h, rest)
			mk := markKill(h, rest)
			log().Info("清扫完成，已确认残留退出", "pid", h.PID,
				"group_killed", len(members), "roster_killed", rk,
				"mark_killed", mk, "probe", i+1)
			return len(members) + rk + mk, VerdictOK, nil
		}
	}
	log().Error("已发 SIGKILL 但复核窗口走完仍有残留", "pid", h.PID,
		"window", killVerifyWindow)
	return len(members), VerdictOK,
		fmt.Errorf("%w: pgid=%d，已发 SIGKILL 并复核 %s", ErrStillAlive, h.PID, killVerifyWindow)
}

n_prochost_UIDUsage.signature:
// UIDUsage 报告当前 uid 的进程占用与上限。
//
// 返回：
//   - used: 当前 uid 的进程数；limit: 每 uid 上限
//   - err: 平台不支持（ErrNotSupported）或读取失败
//
// 注意：与 Footprint 共用同一次进程枚举的实现，但回答的是不同问题——
// Footprint 问「这个任务占了多少」，本函数问「这台机器还剩多少」。
// 调用方拿到 err 时必须如实呈现为「未知」，不得回退成 0。
func UIDUsage() (used, limit int, err error) {
	procs, err := enumProcsFn()
	if err != nil {
		logEnumFailure("统计 uid 进程占用失败", err)
		return 0, 0, err
	}
	limit, err = procLimit()
	if err != nil {

		logEnumFailure("读取进程数上限失败", err)
		return len(procs), 0, err
	}
	log().Debug("uid 进程占用", "used", len(procs), "limit", limit)
	return len(procs), limit, nil
}

n_prochost_WaitInputReader.signature:
// WaitInputReader 等待输入通道上出现读端（shim 已执行到持有 FIFO 那一步）。
//
// 为什么必须等：写端以 O_WRONLY|O_NONBLOCK 打开 FIFO 时，POSIX 规定读端未就绪
// 直接失败（ENXIO，macOS 文案 "device not configured"）。Start 返回只代表 shim
// 已被 fork，不代表它已经打开了 FIFO——这个竞态在 tmux 时代真机复现过
// （8fca917 次生缺陷），换成 shim 后窗口更小但依然存在。
//
// 参数：
//   - path: 通道路径
//   - timeout: 等待上限；到点仍无读端返回错误
//
// 返回：等待耗时（调用方记日志）与错误。非「无读者」类错误立即返回，不重试。
func WaitInputReader(path string, timeout time.Duration) (time.Duration, error) {
	return waitInputReader(path, timeout)
}

n_prochost_WriteInputChannel.signature:
// WriteInputChannel 往输入通道投递一段字节。
//
// 参数：
//   - path: 通道路径（与 Spec.InputCh 同一个值）
//   - data: 原样投递的字节，本函数不加工、不追加换行
//
// 返回：读端不在、通道不存在、写失败时返回错误。
//
// 注意：
//   - **「打不开即读端不在」是承重语义**：unix 上以 O_WRONLY|O_NONBLOCK 打开，
//     读端未就绪时 POSIX 规定直接失败（ENXIO）；Windows 上 CreateFile 打不开
//     管道名报 ERROR_FILE_NOT_FOUND。两边都是调用方判定「执行者已不在」的依据，
//     实现不得改成阻塞等待或静默成功
//   - 本函数不做 JSON 序列化：那是 adapter 的协议知识，prochost 只搬字节
func WriteInputChannel(path string, data []byte) error {
	return writeInputChannel(path, data)
}

n_prochost_applyFencePolicy.signature:
// applyFencePolicy 按当前策略把围栏值写进 spec。
//
// 参数：spec 为待下发的进程规格，本函数**就地修改**其 NprocLimit 字段
//
// 为什么由 prochost 自己填而不是让 adapter 填：四个 adapter 各自构造 Spec，
// 交给它们填等于四处都可能漏，而漏掉的后果是这个任务完全没有围栏保护、
// 且日志里看不出任何异常——一个静默失效的防护装置。
//
// 注意：算不出围栏值时字段置 0（不设围栏）并打 Warn，**绝不阻断拉起**。
func applyFencePolicy(spec *Spec) {
	l, err := fenceLimit()
	if err != nil {
		log().Warn("算不出进程围栏值，本次不设围栏", "cause", err)
		spec.NprocLimit = 0
		return
	}
	spec.NprocLimit = l
}

n_prochost_applyTaskMark.signature:
// applyTaskMark 把任务标记注入 spec.Env。
//
// 为什么放在 Start 而不是各 adapter：Start 是四个 adapter 的唯一汇流点，
// 在这里注入既让 adapter 零改动，也保证 Handle.TaskID 与实际注入的环境变量
// 出自同一处赋值、不可能对不上。紧邻的 applyFencePolicy 是同款先例。
//
// 注意：spec.TaskID 为空时什么都不做——没有 id 就没有可比对的标记，
// 注入一个空值只会让判据把所有没有该变量的进程都算成命中。
func applyTaskMark(spec *Spec) {
	if spec.TaskID == "" {
		return
	}
	spec.Env = append(spec.Env, TaskMarkEnvKey+"="+spec.TaskID)
}

n_prochost_attributes.signature:
// attributes 判定 pid 是否属于 cred 所描述的任务（darwin：按 cwd）。
//
// 返回：
//   - true: 该进程的 cwd 落在 cred.MarkRoot 之内
//   - ErrNotSupported: 本机自检未通过（见 cwdReadable），调用方应降级
//   - 其它错误: 该 pid 读不到（多为刚退出），调用方跳过该条
//
// 注意：cred.MarkRoot 为空即一律不命中——「仅托管 worktree 可杀」在这里落地。
// 本判据**不抗 cd**：进程 cd 出任务目录后就脱钩，这是 macOS 侧结构性的覆盖上限。
func attributes(pid int, cred TaskCred) (bool, error) {
	if cred.MarkRoot == "" {
		return false, nil
	}
	if !cwdReadable() {
		return false, ErrNotSupported
	}
	cwd, err := cwdOf(pid)
	if err != nil {
		return false, err
	}
	return underRoot(cwd, cred.MarkRoot), nil
}

n_prochost_chargeableProcessCount.signature:
// chargeableProcessCount 从机器级快照扣除已验证的 ptyhost。
//
// 参数：procs 是一次完整的当前 uid 进程快照。
// 返回：计入机器级压力的进程数，以及成功排除的 ptyhost 数。
// 注意：PID 与启动时刻必须同时匹配；凭据缺失、过期或只匹配 PID 都保留计数。
// 任务级 footprint 不调用本函数，因此它的统计口径不受影响。
func chargeableProcessCount(procs []procEntry) (used, excluded int) {
	provider := currentPtyhostCredentialProvider()
	if provider == nil {
		return len(procs), 0
	}
	credentials := provider()
	if len(credentials) == 0 {
		return len(procs), 0
	}
	known := make(map[ProcessCredential]struct{}, len(credentials))
	for _, credential := range credentials {
		if credential.PID <= 0 || credential.StartedAt <= 0 {
			continue
		}
		known[credential] = struct{}{}
	}
	for _, proc := range procs {
		if _, ok := known[ProcessCredential{PID: proc.PID, StartedAt: proc.StartedAt}]; ok {
			excluded++
			continue
		}
		used++
	}
	return used, excluded
}

n_prochost_childPIDPath.signature:
// childPIDPath 由 proc.json 路径推出 child.pid 路径（两者同目录）。
func childPIDPath(infoPath string) string {
	return filepath.Join(filepath.Dir(infoPath), ChildPIDFileName)
}

n_prochost_classify.signature:
// classify 判定进程快照中哪些成员属于 h 所代表的任务。
//
// 参数：
//   - h: 任务的进程句柄；h.PID 既是 shim pid 也是进程组 id（Setsid 保证）
//   - procs: 一次进程快照（当前 uid 的全部进程）
//   - lockHeld: h.LockPath 上的存活锁是否仍被持有，即 shim 是否还活着
//
// 返回：
//   - members: 通过校验的成员 pid；判定为放弃时**必然为空**
//   - v: 判定结论
//
// 三条规则（spec §3.2）：
//
// 规则一（组长身份判定，以存活锁为准，一票否决）：
//   - 锁仍被持有 ⇒ 组长就是我们的 shim，pgid 不可能被复用（锁由内核在进程死亡时
//     释放，这个判据本身免疫 pid 复用），正常计数
//   - 锁已释放 ⇒ 组长已死；此时组内若仍有活的 pid==pgid==h.PID，那必然是内核把
//     这个 pid 分配给了新进程且它成了组长，即 pgid 被复用 ⇒ 整组放弃
//
// 规则二（会话封闭性——只封闭外侧，无需代码）：组内**不会混入外部进程**。
// 依据：shim 调用过 setsid，该进程组属于 shim 独有的会话；setpgid(2) 要求目标
// 进程组与调用者同会话，会话外的进程加不进来。
//
// 判据覆盖边界（为什么是 pgid 而不是进程树；这既是本判据的定义，也是它的盲区）：
//   - 内侧**不封闭**：组内进程可以随时 setsid 自成新会话逃出去（2026-08-12 真机
//     实证：opencode 的 Bash 工具把每条命令都 setsid 成新会话+新进程组，命令的
//     pgid == 它自己的 pid）。因此本判据只覆盖「与 shim 同进程组的成员」——
//     executor 经 Bash 工具拉起的子进程不在覆盖范围，数不到也杀不到。这是明确的
//     定界不是疏漏：凡是说「这个任务占了多少进程」的地方，指的只是这一层
//   - 为什么事后不能用祖先链补救：setsid 改的是 pgid/sid、**不改 ppid**，所以进程
//     树还活着时沿 ppid 从 shim 能走到逃逸者；但 Sweep/Footprint 要工作的时刻
//     正是执行者已死、子进程被 reparent 给 init/launchd 之后——那一刻 ppid 恰好
//     断在最需要它的地方。按 ppid 实现会得到一个「测试里好使、事故现场失效」的
//     东西，比诚实的盲区更糟：盲区至少不会骗人
//   - 逃逸后代由 rosterMembers 覆盖，见 B72 出生登记：classify 本身只管 pgid 层，
//     逃逸那层的计数与回收走出生名册，两段判据各管一段、口径在 Footprint/Sweep
//     边界上合并
//
// 规则三（时间下界，双保险）：成员启动时刻必须 ≥ h.StartedAt，否则排除。规则二只
// 挡外侧混入、挡不住内侧逃逸，这条补的是「比 shim 更早的进程必然不可能是它的
// 后代」的下界——代价是漏杀而非误杀。
//
// 注意：本函数刻意不打日志——调用方（Footprint/Sweep）在边界上统一记录入参与
// 结论；这里再记一遍等于同一件事写两次，且 status 会高频调用它。
func classify(h Handle, procs []procEntry, lockHeld bool) (members []int, v Verdict) {
	if h.PID <= 0 || h.StartedAt <= 0 {
		return nil, VerdictNoCredential
	}
	if !lockHeld {
		for _, p := range procs {
			if p.PID == h.PID && p.PGID == h.PID {

				return nil, VerdictLeaderReuse
			}
		}
	}
	for _, p := range procs {
		if p.PGID != h.PID {
			continue
		}
		if p.StartedAt < h.StartedAt {
			continue
		}
		members = append(members, p.PID)
	}
	return members, VerdictOK
}

n_prochost_createInputChannel.signature:
// createInputChannel 幂等创建 0600 命名管道（见 CreateInputChannel 的文档）。
func createInputChannel(path string) error {
	err := syscall.Mkfifo(path, 0o600)
	if err == nil {
		return nil
	}
	if !errors.Is(err, syscall.EEXIST) {
		return fmt.Errorf("mkfifo %s: %w", path, err)
	}
	fi, serr := os.Stat(path)
	if serr != nil {
		return fmt.Errorf("stat %s: %w", path, serr)
	}

	if fi.Mode()&os.ModeNamedPipe == 0 {
		return fmt.Errorf("%s 已存在但不是命名管道", path)
	}
	return nil
}

n_prochost_currentPtyhostCredentialProvi.signature:
func currentPtyhostCredentialProvider() PtyhostCredentialProvider {
	ptyhostCredentialMu.RLock()
	provider := ptyhostCredentialProvider
	ptyhostCredentialMu.RUnlock()
	return provider
}

n_prochost_cwdOf.signature:
// cwdOf 读出 pid 的当前工作目录（不 fork）。
//
// 返回：内核给出的**已解析**绝对路径；读不到时返回错误。
//
// 注意：进程刚退出、或对方是本 uid 之外的进程时会失败，这是常态，
// 调用方跳过该条即可，不该据此认定「不属于本任务」。
func cwdOf(pid int) (string, error) {
	buf := make([]byte, vnodePathBufSize)
	got, _, errno := syscall.Syscall6(sysProcInfo, callPIDInfo, uintptr(pid),
		flavorVnodePath, 0, uintptr(unsafe.Pointer(&buf[0])), uintptr(len(buf)))
	if errno != 0 {
		return "", fmt.Errorf("proc_pidinfo(vnodepath) pid=%d: %w", pid, errno)
	}
	if got == 0 || int(got) <= vipPathOffset {
		return "", fmt.Errorf("proc_pidinfo(vnodepath) pid=%d 返回 %d 字节，不足以含路径", pid, got)
	}
	b := buf[vipPathOffset:got]
	if i := indexZero(b); i >= 0 {
		b = b[:i]
	}
	if len(b) == 0 {
		return "", fmt.Errorf("proc_pidinfo(vnodepath) pid=%d 路径为空", pid)
	}
	return string(b), nil
}

n_prochost_cwdReadable.signature:
// cwdReadable 报告本机上 cwd 判据是否可用。
//
// 判据：拿本进程试一次——用 syscall 读出的 cwd 必须等于 os.Getwd() 的解析结果。
//
// 为什么要这道自检：vipPathOffset 是实测值，而 syscall.Syscall6 在 darwin 上是
// deprecated 路径。两者任一在未来失效，解析出来的都会是垃圾字符串——而垃圾
// 字符串「恰好不等于任何 MarkRoot」，判据会**静默退化成永远不命中**，没有任何
// 报错。有了自检，失效表现为整条判据降级回 pgid + roster（spec §8 第四档），
// 那是设计好的行为，不是新的失败模式。
func cwdReadable() bool {
	cwdSelfCheck.once.Do(func() {
		want, err := os.Getwd()
		if err != nil {
			log().Warn("取本进程 cwd 失败，停用 cwd 归属判据", "cause", err)
			return
		}
		wantResolved, err := filepath.EvalSymlinks(want)
		if err != nil {
			log().Warn("解析本进程 cwd 失败，停用 cwd 归属判据", "cwd", want, "cause", err)
			return
		}
		got, err := cwdOf(os.Getpid())
		if err != nil {
			log().Warn("proc_pidinfo 自检失败，停用 cwd 归属判据，归属退回 pgid+roster",
				"cause", err)
			return
		}
		if got != wantResolved {
			log().Warn("proc_pidinfo 自检结果与 os.Getwd 不符，停用 cwd 归属判据",
				"got", got, "want", wantResolved, "offset", vipPathOffset)
			return
		}
		cwdSelfCheck.ok = true
		log().Info("cwd 归属判据可用", "offset", vipPathOffset)
	})
	return cwdSelfCheck.ok
}

n_prochost_descendantsOf.signature:
// descendantsOf 从进程快照里闭包出 root 的全部后代（不含 root 自己）。
//
// 参数：
//   - root: 起点 pid（生产里是 shim 自己）
//   - procs: 一次进程快照（当前 uid 的全部进程）
//
// 返回：后代的 pid 与启动时刻；root 不在快照里或没有后代时返回空切片
//
// 为什么按 ppid 而不是 pgid：executor 经 Bash 工具拉起的子进程会 setsid 自成
// 会话与进程组（2026-08-12 devbox 实证：`33365 92657 33365 (zsh)`，父进程是
// opencode serve 但 pgid 是它自己），pgid 判据看不到它们。ppid 不受 setsid 影响。
//
// 注意：
//   - **本函数只在树活着时有意义**。executor 一死，后代被 reparent 给
//     init/launchd，ppid 链当场断在最需要它的地方——所以名册必须在活着的时候
//     周期落盘，而不是清扫时现算
//   - visited 集合是必需的：真实快照里 pid 1 的 ppid 是 0 或 1（自环），且快照
//     是非原子的，两条记录之间可能出现看起来成环的形态。没有它会死循环
//   - 本函数刻意不打日志：它每个采样间隔（`rosterInterval`，现为 1s）被调用
//     一次、且是纯函数，日志放在调用方（shim 的周期落盘）边界上记一次入参与
//     结论即可，这里再记等于同一件事写两遍并按周期刷屏
func descendantsOf(root int, procs []procEntry) []rosterEntry {
	if root <= 0 || len(procs) == 0 {
		return nil
	}

	children := make(map[int][]procEntry, len(procs))
	for _, p := range procs {
		if p.PID == p.PPID {
			continue
		}
		children[p.PPID] = append(children[p.PPID], p)
	}
	visited := map[int]bool{root: true}
	queue := []int{root}
	out := make([]rosterEntry, 0, 8)
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		for _, c := range children[cur] {
			if visited[c.PID] {
				continue
			}
			visited[c.PID] = true
			out = append(out, rosterEntry{PID: c.PID, StartedAt: c.StartedAt})
			queue = append(queue, c.PID)
		}
	}
	return out
}

n_prochost_enumProcs.signature:
// enumProcs 用 sysctl KERN_PROC_UID 取当前 uid 的全部进程。
//
// 返回：
//   - 每个进程的 pid / pgid / 启动时刻（unix 纳秒）
//   - sysctl 失败时返回错误；不返回 ErrNotSupported（本平台是支持的）
//
// 注意：kinfo_proc 的 p_starttime 是 struct timeval（墙钟），直接换算 unix 纳秒。
func enumProcs() ([]procEntry, error) {
	kps, err := unix.SysctlKinfoProcSlice("kern.proc.uid", os.Getuid())
	if err != nil {
		log().Error("sysctl 枚举进程失败", "uid", os.Getuid(), "cause", err)
		return nil, fmt.Errorf("sysctl kern.proc.uid: %w", err)
	}
	out := make([]procEntry, 0, len(kps))
	for i := range kps {
		st := kps[i].Proc.P_starttime
		out = append(out, procEntry{
			PID:		int(kps[i].Proc.P_pid),
			PPID:		int(kps[i].Eproc.Ppid),
			PGID:		int(kps[i].Eproc.Pgid),
			StartedAt:	int64(st.Sec)*int64(time.Second) + int64(st.Usec)*int64(time.Microsecond),
		})
	}
	log().Debug("进程枚举完成", "uid", os.Getuid(), "count", len(out))
	return out, nil
}

n_prochost_envKeys.signature:
// envKeys 提取 KEY=VALUE 列表里的 key（日志用；值绝不出现在日志里）。
func envKeys(env []string) []string {
	keys := make([]string, 0, len(env))
	for _, kv := range env {
		if i := strings.IndexByte(kv, '='); i > 0 {
			keys = append(keys, kv[:i])
		}
	}
	return keys
}

n_prochost_equalInts.signature:
// equalInts 判断两个 PID 表是否逐项相等。
//
// 不排序、不去重：Job Object 返回的成员顺序由内核给定，保留原始序列可避免
// 不必要的分配，也不抹掉潜在的顺序变化信号。
func equalInts(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

n_prochost_fenceLimit.signature:
// fenceLimit 算出应安装的围栏值 L。
//
// 返回：
//   - L > 0: 应安装的围栏值
//   - L == 0 且 err == nil: 策略关闭，或系统上限小到留不出保留额——两种都是
//     「本次不设围栏」的正常结论，**不是错误**
//   - err != nil: 读不到系统上限
//
// 取法是「贴天花板留救护车道」，不是「给 executor 节流」：保留额只要够
// agentd/sshd/登录 shell 活着即可。压得更低不增加安全性，只会让 executor 更
// 早撞墙、让协调者更容易把配额问题误判成代码问题——一个会误导的防护比没有
// 防护更糟。
func fenceLimit() (int, error) {
	if fenceDisabled {
		return 0, nil
	}
	if fenceHardLimitMode {

		return fenceTaskHardLimit, nil
	}
	limit, err := procLimitFn()
	if err != nil {
		log().Warn("读不到系统进程上限，本次不设围栏", "cause", err)
		return 0, err
	}
	reserve := int(float64(limit) * fenceReserveRatio)
	if reserve < fenceReserveFloor {
		reserve = fenceReserveFloor
	}
	if reserve >= limit {
		log().Warn("系统进程上限过小，留不出保留额，本次不设围栏",
			"limit", limit, "reserve", reserve)
		return 0, nil
	}
	return limit - reserve, nil
}

n_prochost_fenceReference.signature:
// fenceReference 返回余量判读的参考上限：围栏已启用时为 L，否则退回系统上限。
//
// 为什么参考上限不能恒用系统上限：装了围栏之后，executor 的实际天花板是 L，
// 拿 2666 去算水位会让「已经贴着围栏」显示成「才用了九成的九成」，高水位
// 告警永远不触发。
func fenceReference() (int, error) {
	l, err := fenceLimit()
	if err != nil {
		return 0, err
	}
	if l > 0 {
		return l, nil
	}
	return procLimitFn()
}

n_prochost_flockExclusiveNB.signature:
// flockExclusiveNB 对一个已打开的文件取非阻塞独占锁。
//
// 注意：锁挂在「打开的文件描述」上而不是路径上。两个后果——同一进程内两次
// OpenFile 同一路径同样互斥（测试据此免起子进程）；`rm` 掉锁文件并不能解锁。
// （本函数由 internal/agentd/flock_unix.go 原样上移，行为不变。）
func flockExclusiveNB(f *os.File) error {
	return syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB)
}

n_prochost_getNprocLimit.signature:
// getNprocLimit 读当前进程的 RLIMIT_NPROC 软限。
//
// 返回：软限值；getrlimit 失败时返回错误。
//
// 注意：无限大（RLIM_INFINITY）会被钳到 math.MaxInt32——直接 int() 转换会
// 得到 -1，那个负数一路流下去会把「无上限」变成「上限为负」，比钳值危险得多。
func getNprocLimit() (int, error) {
	var rl unix.Rlimit
	if err := unix.Getrlimit(unix.RLIMIT_NPROC, &rl); err != nil {
		return 0, fmt.Errorf("getrlimit RLIMIT_NPROC: %w", err)
	}
	if rl.Cur > uint64(math.MaxInt32) {
		return math.MaxInt32, nil
	}
	return int(rl.Cur), nil
}

n_prochost_getNprocLimits.signature:
// getNprocLimits 读当前进程的 RLIMIT_NPROC 软硬两限。
//
// 返回：软限、硬限；getrlimit 失败时返回错误。
//
// 边界：硬限与软限同样钳到 math.MaxInt32，理由同 getNprocLimit——
// RLIM_INFINITY 直接 int() 转换会得到 -1，把「无上限」误读成「上限为负」。
// 与 getNprocLimit 一样不 fork，保持本包零 fork 约束。
func getNprocLimits() (soft, hard int, err error) {
	var rl unix.Rlimit
	if err := unix.Getrlimit(unix.RLIMIT_NPROC, &rl); err != nil {
		return 0, 0, fmt.Errorf("getrlimit RLIMIT_NPROC: %w", err)
	}
	if rl.Cur > uint64(math.MaxInt32) {
		soft = math.MaxInt32
	} else {
		soft = int(rl.Cur)
	}
	if rl.Max > uint64(math.MaxInt32) {
		hard = math.MaxInt32
	} else {
		hard = int(rl.Max)
	}
	return soft, hard, nil
}

n_prochost_indexZero.signature:
// indexZero 返回第一个 0 字节的下标；没有则返回 -1。
func indexZero(b []byte) int {
	for i := range b {
		if b[i] == 0 {
			return i
		}
	}
	return -1
}

n_prochost_installProcessContainer.signature:
// installProcessContainer 在 spawn 执行者之前，把当前进程（shim）放进本平台的
// 「进程容器」里，使执行者全树继承其约束。
//
// 参数：nprocLimit 为围栏值（执行者树的进程数上限）；<=0 表示不设围栏。
//
// 返回：error 非 nil 时 shim 必须放弃拉起执行者。
//
// unix 的容器就是 RLIMIT_NPROC——rlimit 随 fork 继承，所以装在 shim 上等于装在
// 整棵树上。**装不上不阻断**：防护装置故障不该变成拒绝服务，这是 B73 定的语义，
// 本次泛化不改变它（与 Windows 侧相反，见 platform_windows.go 的同名函数）。
func installProcessContainer(nprocLimit int) error {
	if nprocLimit <= 0 {
		log().Info("本任务未设进程围栏", "reason", "spec 未下发围栏值")
		return nil
	}
	if err := setNprocLimit(nprocLimit); err != nil {
		log().Warn("安装进程围栏失败，本任务无围栏保护", "limit", nprocLimit, "cause", err)
		return nil
	}
	log().Info("进程围栏已安装", "limit", nprocLimit)
	return nil
}

n_prochost_isLockContended.signature:
// isLockContended 判定错误是否为「锁已被他人持有」（LOCK_NB 下的 EWOULDBLOCK），
// 用于把撞锁与真正的 IO 故障分开——两者该给的错误信息完全不同。
func isLockContended(err error) bool {
	return errors.Is(err, syscall.EWOULDBLOCK)
}

n_prochost_isNotSupported.signature:
// isNotSupported 判别「本平台不具备该能力」这一类错误。
//
// 为什么单独抽一个函数：darwin 的实现会在运行期自检失败后也退回这个语义
// （见 taskmark_darwin.go 的偏移量自检），判别点集中在一处才不会漏。
func isNotSupported(err error) bool	{ return err == ErrNotSupported }

n_prochost_killGroup.signature:
// killGroup 向 pid 所在进程组发送 SIGKILL（负 pid 表示按组发送）。
//
// 幂等：组已不存在时内核返回 ESRCH，视为已回收成功。
// 调用方（prochost.Kill）必须先确认存活锁仍被持有才可调用本函数——
// 对已回收的 pid 发信号有误杀被复用 pid 的风险。
func killGroup(pid int) error {
	if err := syscall.Kill(-pid, syscall.SIGKILL); err != nil {
		if errors.Is(err, syscall.ESRCH) {
			return nil
		}
		return fmt.Errorf("kill -9 -%d: %w", pid, err)
	}
	return nil
}

n_prochost_killProc.signature:
// killProc 对**单个 pid** 发 SIGKILL（不是进程组）。
//
// 为什么不能复用 killGroup：第二段清扫的对象是 setsid 逃逸出去的进程，它们
// 各自成组，组里往往还有它们自己的无关兄弟；按组发信号会把没经过身份校验的
// 进程一起带走——那正是 B47 误杀的形态。名册逐条校验、逐条发信号，一条一条来。
func killProc(pid int) error {
	if pid <= 0 {
		return fmt.Errorf("非法 pid %d", pid)
	}
	return syscall.Kill(pid, syscall.SIGKILL)
}

n_prochost_logEnumFailure.signature:
// logEnumFailure 按「平台缺能力」还是「真故障」两档记录进程枚举失败。
//
// 参数：msg 为事件名；err 为 enumProcs 的返回；args 为附加键值对（不含 cause，
// 本函数自己补）。
//
// 为什么不一律按 Error 打：非 darwin/linux 上 enumProcs 恒定返回
// ErrNotSupported，那是**预期形态**而不是故障。按 Error 打的后果实测过——
// Windows 执行机上每次 handoff status 都在 agentd 日志里刷两条红字
// （足迹枚举失败 + 统计 uid 进程占用失败），把真正的枚举故障淹在噪音里
// （B144）。同一档位的正确措辞见 shim.go 的名册采样分支。
//
// 注意：降档的只是**日志**，返回值与降级语义一概不变——调用方仍须把结论
// 呈现为「未知」，绝不能回退成 0。
func logEnumFailure(msg string, err error, args ...any) {
	args = append(args, "cause", err)
	if errors.Is(err, ErrNotSupported) {
		log().Debug(msg+"：本平台不支持进程枚举，结论降级为未知", args...)
		return
	}
	log().Error(msg, args...)
}

n_prochost_lookupStartedAt.signature:
// lookupStartedAt 读回某个 pid 的内核启动时刻（unix 纳秒）；读不到返回 0。
//
// 为什么容忍失败：这是诊断凭据不是运行必需品，取不到只降级为「不能自动清扫」，
// 绝不能反过来影响已经拉起的执行者。
func lookupStartedAt(pid int) int64 {
	procs, err := enumProcsFn()
	if err != nil {
		log().Warn("枚举进程失败，无法读取启动时刻", "pid", pid, "cause", err)
		return 0
	}
	for _, p := range procs {
		if p.PID == pid {
			return p.StartedAt
		}
	}
	log().Warn("枚举结果中没有该 pid，无法读取启动时刻", "pid", pid)
	return 0
}

n_prochost_markKill.signature:
// markKill 执行第三段清扫：按任务标记逐个回收 pgid 与名册都看不见的残留。
//
// 参数：
//   - h: 任务句柄（用 h.cred() 取归属凭据、h.StartedAt 做时间下界）
//   - procs: 一次进程快照（与前两段共用，避免重复枚举）
//
// 返回：killed 为**实际发出信号**的成员数
//
// 判据（比名册那段更强，因为标记是活读的）：
//  1. 标记命中，且
//  2. 启动时刻不早于 shim（比 shim 还早的不可能是它的后代），且
//  3. **发信号前立刻再读一次标记**——枚举与发信号之间进程可能已退出且 pid
//     被复用，复验一次只花一个 syscall，而误杀的代价是打掉用户的登录 shell
//     或 agentd 自己（B47 误杀 114 次的教训）
//
// 注意：
//   - 平台不支持标记是**正常形态**（Windows 走 Job Object，见 B37），安静返回 0
//   - 逐条发信号而不是按组：标记命中的进程各自 setsid 成组，按组会带走未经
//     校验的兄弟进程
//   - macOS 上只有托管 worktree 形态才会有 MarkRoot，非托管任务在这里天然返回 0
func markKill(h Handle, procs []procEntry) (killed int) {
	cred := h.cred()
	candidates, supported := markMembers(cred, procs)
	if !supported {
		log().Debug("本平台无任务标记能力或本任务无凭据，跳过标记回收", "pid", h.PID)
		return 0
	}
	if len(candidates) == 0 {
		return 0
	}
	var skippedOld, skippedRecheck int
	for _, pid := range candidates {
		if startedAtOf(procs, pid) < h.StartedAt {
			skippedOld++
			continue
		}
		ok, err := attributesFn(pid, cred)
		if err != nil {

			log().Debug("杀前复验标记失败，跳过", "pid", pid, "cause", err)
			skippedRecheck++
			continue
		}
		if !ok {

			log().Warn("杀前复验标记不再命中，拒绝发信号", "pid", pid, "task_id", cred.TaskID)
			skippedRecheck++
			continue
		}
		if kerr := killProcFn(pid); kerr != nil {
			log().Error("按标记回收进程失败", "pid", pid, "cause", kerr)
			continue
		}
		killed++
	}
	log().Info("标记回收完成", "pid", h.PID, "candidates", len(candidates),
		"killed", killed, "skipped_older_than_shim", skippedOld,
		"skipped_recheck", skippedRecheck)
	return killed
}

n_prochost_markMembers.signature:
// markMembers 在一次进程快照里筛出属于 cred 的成员。
//
// 参数：cred 为任务凭据；procs 为一次进程快照（与其它判据共用，避免重复枚举）
//
// 返回：
//   - members: 归属本任务的 pid
//   - supported: 本平台是否具备标记判定能力。**false 时 members 必然为空，
//     且调用方必须理解为「这条判据不可用」而非「没有成员」**
//
// 注意：
//   - 单个 pid 读失败（进程刚退出、权限不足）只跳过该条，不影响整批——进程在
//     枚举与读取之间消失是常态
//   - 成功路径刻意不打日志：Footprint 被 handoff status 按任务高频调用，
//     每个 pid 记一行会把 agentd.log 淹掉。汇总由调用方在边界上打一次
func markMembers(cred TaskCred, procs []procEntry) (members []int, supported bool) {
	if cred.empty() {
		return nil, false
	}
	for _, p := range procs {
		ok, err := attributesFn(p.PID, cred)
		if err != nil {
			if isNotSupported(err) {

				return nil, false
			}

			log().Debug("读任务标记失败，跳过该进程", "pid", p.PID, "cause", err)
			continue
		}
		supported = true
		if ok {
			members = append(members, p.PID)
		}
	}
	return members, supported
}

n_prochost_marshalRoster.signature:
// marshalRoster 序列化名册，供「内容未变则不落盘」的比对使用。
//
// 参数：entries 必须已按 pid 升序（mergeRoster 保证）
//
// 返回：JSON 字节；序列化失败时返回错误
func marshalRoster(entries []rosterEntry) ([]byte, error) {
	b, err := json.Marshal(entries)
	if err != nil {
		return nil, fmt.Errorf("序列化名册: %w", err)
	}
	return b, nil
}

n_prochost_membersPath.signature:
// membersPath 由 proc.json 的路径推出 members.json 的路径。
//
// infoPath 为空时返回空串，与 rosterPath 同款降级；调用方据此跳过容器来源。
func membersPath(infoPath string) string {
	if infoPath == "" {
		return ""
	}
	return filepath.Join(filepath.Dir(infoPath), MembersFileName)
}

n_prochost_membersSampler_sample.signature:
// sample 采一次容器成员并按需落盘。
//
// 参数：l 为日志器。
// 返回：是否继续周期采样。false 只表示本平台永久没有进程容器；单次查询或
// 落盘失败都返回 true，因为下一轮可能恢复。
func (s *membersSampler) sample(l *slog.Logger) bool {
	if containerSampleFn == nil {
		l.Info("本平台无进程容器，不做成员采样")
		return false
	}
	if s.path == "" {
		l.Warn("无 info_path，无法落盘成员快照，本任务不做容器计数")
		return false
	}
	pids, err := containerSampleFn()
	if err != nil {
		l.Warn("查询容器成员失败，本轮跳过", "path", s.path, "cause", err)
		return true
	}
	if s.hasLast && equalInts(s.last, pids) {
		l.Debug("容器成员未变，跳过落盘", "count", len(pids))
		return true
	}
	if err := writeMembers(s.path, memberSnapshot{PIDs: pids, SampledAt: time.Now().UnixNano()}); err != nil {
		l.Warn("落盘成员快照失败，本轮跳过", "path", s.path, "cause", err)
		return true
	}
	s.last = append(s.last[:0], pids...)
	s.hasLast = true
	s.writes++
	l.Debug("成员快照已落盘", "count", len(pids), "path", s.path)
	return true
}

n_prochost_mergeRoster.signature:
// mergeRoster 把上一轮名册与本轮 ppid 闭包合并成新名册。
//
// 参数：
//   - prev: 上一轮落盘的名册（readRoster 的结果，可为 nil）
//   - cur: 本轮 descendantsOf 的结果（可为 nil）
//   - procs: 本轮进程快照，用于判断 prev 里哪些条目还活着
//
// 返回：按 pid 升序、去重后的新名册；两边都空时返回空切片（非 nil，便于序列化成 []）
//
// 为什么是并集而不是整份覆盖（这就是 B103 的全部）：executor 的 Bash 工具会把
// 每条命令 setsid 成新会话（grok 1.0.3 / opencode 都是），命令里 `cmd &` 留下的
// 后代继承的是**工具壳的 pgid**；工具壳往往只活约 1 秒就退出，后代随即被 reparent
// 给 init/launchd——ppid 链当场断。整份覆盖会在下一轮把这些**仍然活着**的长命
// 后代当成「早退的短命进程」抹掉，于是既数不到也清不掉（08-15 实测：450 个
// `sleep 900` 全部漏记，任务那一行只报 3 个进程）。
//
// 删除条件只有两条：pid 已不在进程表，或 StartedAt 对不上（pid 被内核复用）。
// **不能**用「本轮从 shim 走不到」当删除条件——那正是这个 bug 本身。
// StartedAt 判据沿用宁漏勿错语义（见 rosterEntry 的注释，B47 教训）。
func mergeRoster(prev, cur []rosterEntry, procs []procEntry) []rosterEntry {
	live := make(map[int]int64, len(procs))
	for _, p := range procs {
		live[p.PID] = p.StartedAt
	}
	seen := make(map[int]bool, len(prev)+len(cur))
	out := make([]rosterEntry, 0, len(prev)+len(cur))
	keep := func(e rosterEntry) {
		if seen[e.PID] {
			return
		}
		if started, ok := live[e.PID]; !ok || started != e.StartedAt {
			return
		}
		seen[e.PID] = true
		out = append(out, e)
	}
	for _, e := range prev {
		keep(e)
	}
	for _, e := range cur {
		keep(e)
	}

	sort.Slice(out, func(i, j int) bool { return out[i].PID < out[j].PID })
	return out
}

n_prochost_openAppend.signature:
// openAppend 以追加模式打开落盘文件（不存在则以 0600 创建）。
func openAppend(path string) (*os.File, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		return nil, fmt.Errorf("打开 %s: %w", path, err)
	}
	return f, nil
}

n_prochost_openInputChannel.signature:
// openInputChannel 为子进程准备 stdin（见 shim.go 调用点）。
//
// 参数：path 为通道路径
//
// 返回：
//   - r: 交给 cmd.Stdin 的读端
//   - cleanup: 子进程退出后调用，释放本函数占用的资源
//   - error: 非 nil 时 shim 必须放弃拉起执行者
//
// 注意：**O_RDWR 而不是 O_RDONLY 是承重的**。只读打开会在所有写端关闭时收到
// EOF，执行者的 stdin 随即关闭；O_RDWR 让 shim 自己同时也是写端，FIFO 因此
// 永不 EOF。这是旧 sh 脚本 `exec 3<> in.fifo` 的等价手法。
func openInputChannel(path string) (io.ReadCloser, func(), error) {
	f, err := os.OpenFile(path, os.O_RDWR, 0)
	if err != nil {
		return nil, nil, fmt.Errorf("打开输入通道 %s: %w", path, err)
	}
	return f, func() { _ = f.Close() }, nil
}

n_prochost_pipeNameFor.signature:
// pipeNameFor 由输入通道路径推导 Windows 命名管道全名。
//
// 参数：path 为通道路径（Spec.InputCh 的值）
//
// 返回：形如 `\\.\pipe\handoff-a1b2c3d4e5f60718` 的全名，恒为 32 个字符。
//
// 注意：
//   - **确定性是硬要求**：agentd 与 shim 是两个进程、不共享额外状态，
//     只能各自从同一个 InputCh 值算出同一个名字。这也是 proc.json 与三个
//     adapter 能零改动的原因
//   - 取哈希而不是直接编码路径：路径含 `\` 与 `:`，而管道名里 `\` 是命名空间
//     分隔符；且路径长度无上限，管道名上限 256
//   - 只取前 8 字节（16 个十六进制字符）：碰撞面是同一台机器上并存的任务数
//     （量级几十），2^64 远够用，换来一个短到便于日志阅读的名字
func pipeNameFor(path string) string {

	normalized := pathpkg.Clean(strings.ReplaceAll(path, `\`, `/`))
	sum := sha256.Sum256([]byte(normalized))
	return pipeNamePrefix + hex.EncodeToString(sum[:8])
}

n_prochost_procLimit.signature:
// procLimit 读 kern.maxprocperuid（每 uid 进程数上限）。
func procLimit() (int, error) {
	n, err := unix.SysctlUint32("kern.maxprocperuid")
	if err != nil {
		log().Error("读 kern.maxprocperuid 失败", "cause", err)
		return 0, fmt.Errorf("sysctl kern.maxprocperuid: %w", err)
	}
	return int(n), nil
}

n_prochost_readMembers.signature:
// readMembers 读取一份成员快照。
//
// 参数：path 为 members.json 的路径。
// 返回：快照；文件缺失或内容损坏时返回错误。
// 注意：缺失与损坏都不能静默返回空快照，否则上层会把「来源不可用」误读成
// 「任务确实没有进程」。
func readMembers(path string) (memberSnapshot, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return memberSnapshot{}, fmt.Errorf("读成员快照 %s: %w", path, err)
	}
	var snap memberSnapshot
	if err := json.Unmarshal(b, &snap); err != nil {
		return memberSnapshot{}, fmt.Errorf("解析成员快照 %s: %w", path, err)
	}
	return snap, nil
}

n_prochost_readRoster.signature:
// readRoster 读回名册。
//
// 参数：path 为名册路径；空串等同于「没有名册」
//
// 返回：
//   - entries: 名册内容；没有名册时为 nil
//   - err: 文件存在但读不动或解析失败
//
// 注意：**文件不存在返回 (nil, nil) 而不是错误**。三种正常形态都会走到这里：
// 任务刚起来还没到第一次落盘、升级前建的老任务、adapter 不带 InfoPath。
// 把它们当错误会让 Sweep 每次都记一条假故障，真故障就淹没了。
// 但**解析失败必须报错**：那是「有名册却读不出来」，与「没有名册」是两回事。
func readRoster(path string) ([]rosterEntry, error) {
	if path == "" {
		return nil, nil
	}
	b, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("读名册 %s: %w", path, err)
	}
	var entries []rosterEntry
	if err := json.Unmarshal(b, &entries); err != nil {
		return nil, fmt.Errorf("解析名册 %s: %w", path, err)
	}
	return entries, nil
}

n_prochost_readSpec.signature:
// readSpec 读取并校验 spec.json。
func readSpec(path string) (Spec, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return Spec{}, fmt.Errorf("读 spec %s: %w", path, err)
	}
	var s Spec
	if err := json.Unmarshal(b, &s); err != nil {
		return Spec{}, fmt.Errorf("解析 spec %s: %w", path, err)
	}
	if len(s.Argv) == 0 || s.LockPath == "" || s.Stdout == "" {
		return Spec{}, fmt.Errorf("spec %s 字段不完整（argv/lock_path/stdout 必填）", path)
	}
	return s, nil
}

n_prochost_recordChildPID.signature:
// recordChildPID 把执行者 pid 写进 proc.json 同目录的 child.pid（0600，整份覆盖）。
//
// 为什么不写进 proc.json：那会让 proc.json 有两个写者。adapter 在 Start 返回后
// 会整份覆写 proc.json 补上 Handle.PID，shim 这边若做读-改-写，就存在这样的交错：
// shim 读到 adapter 的旧版 → adapter 写入含 PID 的新版 → shim 写回旧版+child_pid，
// **Handle.PID 归零**。后果不是丢个诊断字段：prochost.Kill 在 PID<=0 时直接返回
// nil，Reap 于是打出「兜底回收完成」而执行者还活着——假成功加孤儿进程，正是
// 本设计要消灭的那类失配。给 shim 一个独占文件，这个窗口从结构上就不存在。
// TestRunShimNeverTouchesProcInfo 钉死这条。
func recordChildPID(infoPath string, pid int) error {
	p := childPIDPath(infoPath)
	if err := os.WriteFile(p, []byte(strconv.Itoa(pid)), 0o600); err != nil {
		return fmt.Errorf("写 %s: %w", p, err)
	}
	return nil
}

n_prochost_rosterKill.signature:
// rosterKill 执行第二段清扫：按出生名册点名回收 setsid 逃逸的后代。
//
// 参数：
//   - h: 任务句柄，用 h.RosterPath 找名册
//   - procs: 一次进程快照（与第一段共用，避免重复枚举）
//
// 返回：killed 为**实际发出信号**的成员数
//
// 判据（spec §4.2，一条都不能松）：名册里的一条只有在「pid 出现在当前进程表」
// **且**「StartedAt 与表里那条完全相等」时才发信号。任一不符即视为 pid 已易主，
// 绝不发信号——漏杀只是让残留多活一会儿（由 B73 的围栏兜住，只吃预算），
// 误杀则可能打掉用户的登录 shell 或 agentd 自己（B47 误杀 114 次的教训）。
//
// 注意：
//   - 名册缺失（RosterPath 为空、文件不在）是**正常形态**，安静返回 0
//   - 名册损坏只打日志并返回 0，不影响已经完成的第一段
//   - 逐条发信号而不是按组：逃逸者各自成组，按组会带走未经校验的兄弟进程
func rosterKill(h Handle, procs []procEntry) (killed int) {
	entries, err := readRoster(h.RosterPath)
	if err != nil {
		log().Warn("读后代名册失败，跳过点名回收", "pid", h.PID,
			"roster", h.RosterPath, "cause", err)
		return 0
	}
	if len(entries) == 0 {
		log().Debug("无后代名册或名册为空，跳过点名回收", "pid", h.PID, "roster", h.RosterPath)
		return 0
	}
	live := make(map[int]int64, len(procs))
	for _, p := range procs {
		live[p.PID] = p.StartedAt
	}
	var skipped int
	for _, e := range entries {
		if e.PID == h.PID {

			log().Warn("名册含执行者本体，跳过", "pid", e.PID)
			continue
		}
		started, ok := live[e.PID]
		if !ok {
			continue
		}
		if started != e.StartedAt {

			log().Warn("名册成员 pid 已易主，拒绝发信号", "pid", e.PID,
				"roster_started_at", e.StartedAt, "actual_started_at", started)
			skipped++
			continue
		}
		if kerr := killProcFn(e.PID); kerr != nil {
			log().Error("回收名册成员失败", "pid", e.PID, "cause", kerr)
			continue
		}
		killed++
	}
	log().Info("点名回收完成", "pid", h.PID, "roster_total", len(entries),
		"killed", killed, "skipped_reused", skipped)
	return killed
}

n_prochost_rosterMembers.signature:
// rosterMembers 按出生名册筛出仍然存活且身份吻合的后代 pid（只读，不发信号）。
//
// 参数：h 为任务句柄（用 h.RosterPath）；procs 为一次进程快照
//
// 返回：通过「pid 在表 + StartedAt 完全相等」校验的 pid；名册缺失/损坏时为空
//
// 注意：它与 rosterKill 是同一条判据的只读孪生版，两者必须同时改——一个报数、
// 一个动手，判据分叉就意味着「报的和杀的不是同一批」。
//   - 成功路径刻意不打日志：Footprint 被 handoff status 按任务高频调用，
//     每次记一行会把 agentd.log 淹掉。失败才记，且只记一次
func rosterMembers(h Handle, procs []procEntry) []int {
	entries, err := readRoster(h.RosterPath)
	if err != nil {
		log().Warn("读后代名册失败，足迹不含逃逸后代", "pid", h.PID,
			"roster", h.RosterPath, "cause", err)
		return nil
	}
	if len(entries) == 0 {
		return nil
	}
	live := make(map[int]int64, len(procs))
	for _, p := range procs {
		live[p.PID] = p.StartedAt
	}
	var out []int
	for _, e := range entries {
		if started, ok := live[e.PID]; ok && started == e.StartedAt {
			out = append(out, e.PID)
		}
	}
	return out
}

n_prochost_rosterPath.signature:
// rosterPath 由 proc.json 的路径推出名册路径（同目录，固定文件名）。
//
// 为什么不让调用方各自拼：shim 写、Start 记、Sweep 读，三处必须完全一致，
// 拼错一个字符的表现是「名册永远为空」——一个不报错、只是悄悄不干活的故障。
func rosterPath(infoPath string) string {
	if infoPath == "" {
		return ""
	}
	return filepath.Join(filepath.Dir(infoPath), RosterFileName)
}

n_prochost_rosterSampler_sample.signature:
// sample 采一轮名册：枚举进程、与上一轮合并、必要时落盘。
//
// 参数：l 为日志器；本方法所有失败都只记日志并返回，不中断任务——名册写不出去
// 只意味着这一轮没有第二段清扫的依据，不值得让任务失败。
//
// 注意：周期日志一律 Debug 级（每秒一次，Info 会把任务日志刷满）；只有单次采样
// 耗时超过间隔一半时才升 Warn——那意味着采样本身开始拖累这台机器，是必须看见的事。
//
// 返回：true 继续按周期采样；false 表示本平台永久不支持进程枚举，调用方应停止循环。
func (s *rosterSampler) sample(l *slog.Logger) bool {
	if s.path == "" {
		l.Warn("无 info_path，无法落盘后代名册，本任务不做出生登记")
		return true
	}
	start := time.Now()
	procs, err := enumProcsFn()
	if err != nil {
		if errors.Is(err, ErrNotSupported) {
			l.Info("本平台不做后代名册采样，回收由进程容器承担", "cause", err)
			return false
		}
		l.Warn("枚举进程失败，本轮跳过出生登记", "cause", err)
		return true
	}
	prev, err := readRoster(s.path)
	if err != nil {

		l.Warn("读回上一轮名册失败，本轮从空名册重建", "path", s.path, "cause", err)
		prev = nil
	}
	entries := mergeRoster(prev, descendantsOf(os.Getpid(), procs), procs)
	b, err := marshalRoster(entries)
	if err != nil {
		l.Warn("序列化后代名册失败，本轮跳过出生登记", "cause", err)
		return true
	}
	cost := time.Since(start)
	if s.last != nil && bytes.Equal(b, s.last) {

		if cost > rosterInterval/2 {
			l.Warn("后代名册采样耗时偏高", "path", s.path, "count", len(entries),
				"cost", cost, "interval", rosterInterval)
			return true
		}
		l.Debug("后代名册未变，跳过落盘", "count", len(entries), "cost", cost)
		return true
	}
	if err := writeRosterBytes(s.path, b); err != nil {
		l.Warn("落盘后代名册失败，本轮跳过出生登记", "path", s.path, "cause", err)
		return true
	}
	s.last = b
	s.writes++
	if cost > rosterInterval/2 {

		l.Warn("后代名册采样耗时偏高", "path", s.path, "count", len(entries),
			"cost", cost, "interval", rosterInterval)
		return true
	}
	l.Debug("后代名册已更新", "path", s.path, "count", len(entries), "cost", cost)
	return true
}

n_prochost_runContainerSampling.signature:
// runContainerSampling 驱动容器成员的首次采样与周期采样。
//
// 参数：stop 为执行者退出时关闭的停止信号；sampler 为跨轮复用的采样器；l 为日志器。
// sample 返回 false 表示本平台没有进程容器，只记一条 Info 并退出；其它失败继续重试。
func runContainerSampling(stop <-chan struct{}, sampler *membersSampler, l *slog.Logger) {
	if !sampler.sample(l) {
		return
	}
	tk := time.NewTicker(rosterInterval)
	defer tk.Stop()
	for {
		select {
		case <-stop:

			sampler.sample(l)
			return
		case <-tk.C:
			if !sampler.sample(l) {
				return
			}
		}
	}
}

n_prochost_runRosterSampling.signature:
// runRosterSampling 驱动后代名册的首次采样与周期采样。
//
// 参数：stop 为执行者退出时关闭的停止信号；sampler 为跨轮复用的采样器；l 为日志器。
//
// 注意：sample 返回 false 表示本平台永久不支持进程枚举，此时只记一条 Info 并退出；
// 其它错误返回 true，仍按周期重试，因为 unix 上的 sysctl/procfs 可能只是本轮读取失败。
func runRosterSampling(stop <-chan struct{}, sampler *rosterSampler, l *slog.Logger) {
	if !sampler.sample(l) {
		return
	}
	tk := time.NewTicker(rosterInterval)
	defer tk.Stop()
	for {
		select {
		case <-stop:
			return
		case <-tk.C:
			if !sampler.sample(l) {
				return
			}
		}
	}
}

n_prochost_setNprocLimit.signature:
// setNprocLimit 把当前进程的 RLIMIT_NPROC 软硬限一起压到 n。
//
// 参数：n 为围栏值（该 uid 可同时存在的进程数上限），必须为正数
//
// 返回：n 非正数、或 setrlimit 失败时返回错误。调用方应降级为「本次无围栏」
// 并继续，绝不因为防护装置装不上就中断业务。
//
// 注意：
//   - **软硬限必须同设**。只压软限的话，被围住的进程一句 setrlimit 就能把
//     软限抬回硬限，围栏形同虚设；硬限只能降不能升（升需特权），两者同设
//     即构成一扇单向门，executor 及其全部后代都拆不掉。
//   - 限值随 fork/exec 继承，且 **setsid 不重置它**——这正是围栏能覆盖
//     「逃逸出进程组的后代」的原因（2026-08-12 真机验证：进程 setsid 到
//     pid==sid==pgid 的完全独立会话后，rlimit 原样保留）。按进程组回收
//     收不到的那些树，在这里一个也跑不掉。
//   - 计数口径是**整个 uid**而不是本进程树：内核 fork 时拿「调用者自己的
//     限值」比「该 uid 当前活着的进程总数」。这个语义正是围栏能自动跨任务
//     合成的原因——所有 executor 树设同一个 L，uid 总数就不会因它们的
//     fork 越过 L，不需要任何任务间协调。
//   - linux 的 RLIMIT_NPROC 把线程也算进去，而本包 enumProcs 只数进程，
//     两边口径不同，高水位判定在 linux 上会偏乐观。darwin（当前唯一的真实
//     部署平台）只数进程，无此偏差。差异是已知的，靠保留额的余量吸收。
//   - 本函数刻意不打日志：调用方（shim）在安装边界上统一记录围栏值与结果，
//     这里再记一遍等于同一件事写两次。
func setNprocLimit(n int) error {
	if n <= 0 {
		return fmt.Errorf("围栏值必须为正数，得到 %d", n)
	}
	rl := unix.Rlimit{Cur: uint64(n), Max: uint64(n)}
	if err := unix.Setrlimit(unix.RLIMIT_NPROC, &rl); err != nil {
		return fmt.Errorf("setrlimit RLIMIT_NPROC=%d: %w", n, err)
	}
	return nil
}

n_prochost_snapshotRoster.signature:
// snapshotRoster 采一轮名册（无状态入口，仅供不需要跨轮比对的调用方使用）。
//
// 参数：l 为日志器；infoPath 为 proc.json 路径（名册与它同目录）
func snapshotRoster(l *slog.Logger, infoPath string) {
	(&rosterSampler{path: rosterPath(infoPath)}).sample(l)
}

n_prochost_spawnDetached.signature:
// spawnDetached 拉起 argv 并让它脱离当前进程的会话与进程组，返回其 pid。
//
// 参数：
//   - argv: 完整命令行，[0] 必须是绝对路径
//   - dir: 子进程工作目录
//   - shimLog: 非 nil 时把子进程的 **stderr** 接到这个文件（shim 的日志落点，
//     生产里是 <taskDir>/shim.log）。nil 时 stderr 照旧接 /dev/null。stdin/stdout
//     恒为 /dev/null——它们与「日志落点」是两回事
//
// 为什么 stderr 单独开一个通道而不是沿用「全 nil 即 detach」：shim 用 slog 记
// 「围栏已安装 / 撞墙归因」等关键行，slog 默认写 stderr；全 nil 会把它们一并丢进
// /dev/null，撞墙时协调者在任务目录里什么都读不到。
//
// 为什么用 Setsid 而不是让子进程自己调 setsid(2)：子进程被 fork 出来时若已是
// 进程组组长，setsid(2) 会返回 EPERM。由父进程在 SysProcAttr 里声明最干净，
// 且一次系统调用同时拿到「新会话 + 新进程组（pgid == pid）」——后者是 Kill
// 能按组连坐全部后代的前提。
//
// 为什么 stdio 默认全部置 nil：Go 会把它们接到 /dev/null。子进程不能持有本进程的
// 任何 fd，否则 agentd 退出时管道破裂会波及它，detach 就名存实亡。
//
// 为什么起一个 goroutine 收尸而不是 Process.Release：Release 只释放 Go 侧的
// 进程句柄，**不改变内核里的父子关系**——被拉起的进程仍是本进程的亲儿子，死后
// 没人 waitpid 就变成僵尸，占着 pid 槽位直到本进程退出。agentd 是常驻服务，
// 每停一个执行者漏一个僵尸，等于按任务数缓慢泄漏 pid（08-10 真机实测：stop 之后
// `ps` 里留下 `[handoff] <defunct>`，父进程正是 agentd）。收尸不影响 detach：
// 会话与进程组早在 Setsid 时就分开了，agentd 若先死，内核把它交给 init 接管。
//
// 边界：本函数不脱离 cgroup——cgroup 归属由 fork 继承，setsid 改不了它。
// systemd 托管场景必须在 unit 里设 KillMode=process，否则 systemctl restart
// 仍会连坐（见 spec §3.3 与 Task 10 的 unit 模板）。
func spawnDetached(argv []string, dir string, shimLog *os.File) (int, error) {
	if len(argv) == 0 {
		return 0, errors.New("argv 为空")
	}
	cmd := exec.Command(argv[0], argv[1:]...)
	cmd.Dir = dir
	cmd.Stdin, cmd.Stdout, cmd.Stderr = nil, nil, shimLog
	cmd.SysProcAttr = &syscall.SysProcAttr{Setsid: true}
	if err := cmd.Start(); err != nil {
		if note, _ := ExplainForkFailure(err); note != "" {
			log().Error("拉起 shim 失败（进程配额）", "note", note, "cause", err)
			return 0, fmt.Errorf("%s: %w", note, err)
		}
		return 0, fmt.Errorf("拉起 %s: %w", argv[0], err)
	}
	pid := cmd.Process.Pid
	go func() {

		if err := cmd.Wait(); err != nil {
			log().Debug("shim 已退出", "pid", pid, "cause", err)
			return
		}
		log().Debug("shim 已退出", "pid", pid, "cause", nil)
	}()
	return pid, nil
}

n_prochost_startedAtOf.signature:
// startedAtOf 在快照里查 pid 的启动时刻；查不到返回 0（会被时间下界排除）。
//
// 为什么返回 0 而不是报错：pid 来自同一份快照，查不到只可能是调用方传错，
// 返回 0 会让它被下界规则挡掉——宁可漏一个也不放一个身份不明的进 members。
func startedAtOf(procs []procEntry, pid int) int64 {
	for _, p := range procs {
		if p.PID == pid {
			return p.StartedAt
		}
	}
	return 0
}

n_prochost_underRoot.signature:
// underRoot 判定 path 是否等于 root 或在 root 之下。
//
// 为什么不用 strings.HasPrefix 单独判：/a/bc 会被 /a/b 的前缀匹配命中，
// 那是另一个目录。必须带上分隔符。
func underRoot(path, root string) bool {
	if path == "" || root == "" {
		return false
	}
	if path == root {
		return true
	}
	return strings.HasPrefix(path, root+string(filepath.Separator))
}

n_prochost_waitInputReader.signature:
// waitInputReader 轮询探测 FIFO 读端（见 WaitInputReader 的文档）。
func waitInputReader(path string, timeout time.Duration) (time.Duration, error) {
	deadline := time.Now().Add(timeout)
	start := time.Now()
	for {
		f, err := os.OpenFile(path, os.O_WRONLY|syscall.O_NONBLOCK, 0)
		if err == nil {
			f.Close()
			return time.Since(start), nil
		}

		if !errors.Is(err, syscall.ENXIO) {
			return time.Since(start), fmt.Errorf("探测 %s 读端: %w", path, err)
		}
		if time.Now().After(deadline) {
			return time.Since(start), fmt.Errorf("%s 在 %s 内未出现读端", path, timeout)
		}
		time.Sleep(20 * time.Millisecond)
	}
}

n_prochost_writeInputChannel.signature:
// writeInputChannel 往 FIFO 投递字节（见 WriteInputChannel 的文档）。
//
// O_NONBLOCK 不是性能选择而是语义选择：没有它，打开写端会一直阻塞到出现读端，
// 「执行者已不在」就变成「永远等下去」。
func writeInputChannel(path string, data []byte) error {
	f, err := os.OpenFile(path, os.O_WRONLY|syscall.O_NONBLOCK, 0)
	if err != nil {
		return fmt.Errorf("打开输入通道 %s（读端可能已不在）: %w", path, err)
	}
	defer f.Close()
	if _, err := f.Write(data); err != nil {
		return fmt.Errorf("写输入通道 %s: %w", path, err)
	}
	return nil
}

n_prochost_writeMembers.signature:
// writeMembers 原子写一份成员快照。
//
// 参数：path 为落点；snap 为本次采样结果。
// 注意：先写临时文件再 rename，避免 agentd 读到半截 JSON；临时文件与目标文件
// 位于同一目录，rename 才具备同一文件系统内的原子替换语义。
func writeMembers(path string, snap memberSnapshot) error {
	if path == "" {
		return fmt.Errorf("成员快照路径为空")
	}
	b, err := json.Marshal(snap)
	if err != nil {
		return fmt.Errorf("序列化成员快照: %w", err)
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, b, 0o644); err != nil {
		return fmt.Errorf("写临时成员快照 %s: %w", tmp, err)
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return fmt.Errorf("落盘成员快照 %s: %w", path, err)
	}
	return nil
}

n_prochost_writeRoster.signature:
// writeRoster 把名册原子写到 path（临时文件 + rename）。
//
// 参数：
//   - path: 名册路径（rosterPath 的结果）
//   - entries: 本次快照的全部后代；空切片是合法输入（表示这一刻没有后代）
//
// 返回：临时文件写失败或 rename 失败时返回错误
//
// 为什么必须原子：读者是另一个进程（agentd 的 Sweep），它随时可能在 shim
// 正在写的瞬间读。直接覆盖写会让读者拿到半截 JSON——而半截 JSON 解析失败会
// 被当成「名册损坏」，于是一次正常的周期写入就变成了一条错误日志。
//
// 为什么临时文件放同目录：rename 只有在同一文件系统内才是原子的。
//
// 注意：本函数不打日志。它每个采样间隔（`rosterInterval`，现为 1s）被调用一次，
// 成功路径打日志就是按周期刷屏；失败由调用方统一记一条 Warn 并继续——名册写
// 不出去只意味着这一轮没有第二段清扫，不值得中断任务。
// 现状说明：`writeRoster` 现在是 `writeRosterBytes` 的入口包装，生产路径由
// `rosterSampler.sample` 按采样间隔调用。
func writeRoster(path string, entries []rosterEntry) error {
	if path == "" {
		return fmt.Errorf("名册路径为空")
	}
	b, err := marshalRoster(entries)
	if err != nil {
		return err
	}
	return writeRosterBytes(path, b)
}

n_prochost_writeRosterBytes.signature:
// writeRosterBytes 把已序列化的名册原子写到 path（临时文件 + rename）。
//
// 参数：
//   - path: 名册路径（rosterPath 的结果）
//   - b: marshalRoster 的结果
//
// 返回：临时文件写失败或 rename 失败时返回错误
//
// 原子性的理由见 writeRoster 的注释——本函数是它的字节版，两者共用同一套语义。
func writeRosterBytes(path string, b []byte) error {
	if path == "" {
		return fmt.Errorf("名册路径为空")
	}
	tmp := path + ".tmp"
	if err := os.WriteFile(tmp, b, 0o600); err != nil {
		return fmt.Errorf("写名册临时文件 %s: %w", tmp, err)
	}
	if err := os.Rename(tmp, path); err != nil {
		_ = os.Remove(tmp)
		return fmt.Errorf("落盘名册 %s: %w", path, err)
	}
	return nil
}

n_projectid_FromOrigin.signature:
// FromOrigin 由 origin 地址派生 project_id。
//
// 参数：
//   - originURL: 仓库的 origin 原始地址
//
// 返回：
//   - 16 位十六进制串；originURL 归一化后为空时返回空串（调用方据此判「算不出身份」）
//
// 注意：
//   - 这是**纯函数**：每台机器各算各的，同一个 origin 必然得到同一个值。
//     跨机引用因此不需要任何中心服务或协调协议
//   - 取 sha256 而非直接用归一化串：归一化串含 '/' 与大小写，做主键与
//     URL 路径段都要转义；定长十六进制串没有这些麻烦
func FromOrigin(originURL string) string {
	norm := NormalizeGitURL(originURL)
	if norm == "" {
		return ""
	}
	sum := sha256.Sum256([]byte(norm))
	return hex.EncodeToString(sum[:])[:idLen]
}

n_projectid_NormalizeGitURL.signature:
// NormalizeGitURL 把 git 远程地址折叠成可比对的规范串。
//
// 参数：
//   - raw: 原始 URL，如 git@github.com:Xsxdot/handoff.git
//
// 返回：
//   - 规范串，如 github.com/Xsxdot/handoff；输入为空白时返回空串
//
// 注意：
//   - 仅用于**比对与派生**，位置表里存的始终是原始 URL
//   - 只把首段（host）转小写：路径段在部分 git 服务端是大小写敏感的，
//     整串转小写有把两个不同仓库折叠到一起的风险
//   - 不做的事：不解析 DNS、不做 host 别名等价（github.com 与其镜像不视为同一个）
func NormalizeGitURL(raw string) string {
	s := strings.TrimSpace(raw)
	if s == "" {
		return ""
	}

	for _, p := range []string{"ssh://", "git://", "https://", "http://"} {
		if len(s) >= len(p) && strings.EqualFold(s[:len(p)], p) {
			s = s[len(p):]
			break
		}
	}

	if i := strings.IndexByte(s, '@'); i >= 0 {
		if j := strings.IndexByte(s, '/'); j < 0 || i < j {
			s = s[i+1:]
		}
	}

	if c := strings.IndexByte(s, ':'); c >= 0 {
		slash := strings.IndexByte(s, '/')
		if slash < 0 || c < slash {
			rest := s[c+1:]
			seg := rest
			if k := strings.IndexByte(rest, '/'); k >= 0 {
				seg = rest[:k]
			}
			if seg != "" && strings.IndexFunc(seg, func(r rune) bool { return r < '0' || r > '9' }) < 0 {

				s = s[:c] + rest[len(seg):]
			} else {
				s = s[:c] + "/" + rest
			}
		}
	}

	s = strings.TrimRight(s, "/")
	s = strings.TrimSuffix(s, ".git")
	s = strings.TrimRight(s, "/")

	if i := strings.IndexByte(s, '/'); i > 0 {
		s = strings.ToLower(s[:i]) + s[i:]
	} else {
		s = strings.ToLower(s)
	}
	return s
}

n_proto_CanTransit.signature:
// CanTransit 校验状态迁移是否合法（如 completed 不可回 running）。
//
// 参数：
//   - from: 来源状态
//   - to: 目标状态
//
// 返回：
//   - true 表示迁移合法，false 表示不允许该迁移
//
// 注意：
//   - 未在迁移表中登记的状态一律视为不可迁移
//   - 本函数仅做静态校验，不实际变更状态
func CanTransit(from, to TaskState) bool {
	for _, allowed := range transitTable[from] {
		if allowed == to {
			return true
		}
	}
	return false
}

n_proto_EncodeSeatIdentity.signature:
// EncodeSeatIdentity 把当前 CLI 物种名和会话 id 编成账本/房间共用的出示身份。
// 语法固定为 cli:<cli>#<session_id>；# 是唯一分隔符，旧的 cli:user@host
// 因而不会被误认成合法席位。
func EncodeSeatIdentity(cli, sessionID string) (string, error) {
	if err := validateSeatPart("cli", cli, true); err != nil {
		return "", err
	}
	if err := validateSeatPart("session_id", sessionID, false); err != nil {
		return "", err
	}
	return "cli:" + cli + "#" + sessionID, nil
}

n_proto_ParseSeatIdentity.signature:
// ParseSeatIdentity 解出 EncodeSeatIdentity 的规范值。空串由调用方表示空座，
// 传入空串本身视为非法输入，避免把缺失身份悄悄降级成空座。
func ParseSeatIdentity(raw string) (cli, sessionID string, err error) {
	if raw == "" {
		return "", "", fmt.Errorf("席位身份为空")
	}
	if !strings.HasPrefix(raw, "cli:") {
		return "", "", fmt.Errorf("席位身份格式非法: %q", raw)
	}
	parts := strings.Split(raw[len("cli:"):], "#")
	if len(parts) != 2 {
		return "", "", fmt.Errorf("席位身份格式非法: %q", raw)
	}
	if err := validateSeatPart("cli", parts[0], true); err != nil {
		return "", "", err
	}
	if err := validateSeatPart("session_id", parts[1], false); err != nil {
		return "", "", err
	}
	return parts[0], parts[1], nil
}

n_proto_TaskState_IsTerminal.signature:
// IsTerminal 报告该状态是否为终态（completed / failed）。
func (s TaskState) IsTerminal() bool {
	return s == TaskStateCompleted || s == TaskStateFailed
}

n_proto_Task_Workdir.signature:
// Workdir 返回 executor cwd 与审阅命令的统一取值点：WorkDir 非空返回它
// （worktree 模式），否则返回 RepoPath（原地模式）。
//
// 注意：所有需要「任务在哪个目录工作」的代码必须走本方法，直接读 RepoPath
// 会在 worktree 模式下拿到错误的工作目录。
func (t *Task) Workdir() string {
	if t.WorkDir != "" {
		return t.WorkDir
	}
	return t.RepoPath
}

n_proto_ValidateSeat.signature:
// ValidateSeat 检查席位身份与来源是否构成可占用的规范席位。
// identity 为空时仅允许 source 为空；非空 identity 必须能被
// ParseSeatIdentity 解码，来源只能是 bind 或 coordinate。
func ValidateSeat(identity string, source SeatSource) error {
	if identity == "" {
		if source != "" {
			return fmt.Errorf("空席位不能带来源 %q", source)
		}
		return nil
	}
	if _, _, err := ParseSeatIdentity(identity); err != nil {
		return fmt.Errorf("席位身份无效: %w", err)
	}
	switch source {
	case SeatSourceBind, SeatSourceCoordinate:
		return nil
	default:
		return fmt.Errorf("席位来源非法: %q", source)
	}
}

n_proto_validateSeatPart.signature:
func validateSeatPart(name, value string, cli bool) error {
	if value == "" || strings.TrimSpace(value) != value {
		return fmt.Errorf("%s 不能为空或带首尾空白", name)
	}
	if strings.IndexFunc(value, unicode.IsSpace) >= 0 || strings.ContainsRune(value, '#') {
		return fmt.Errorf("%s 含非法字符", name)
	}
	if cli && strings.ContainsRune(value, ':') {
		return fmt.Errorf("cli 含非法字符")
	}
	return nil
}

n_proxycfg_GitArgs.signature:
// GitArgs 返回给 git 子进程的代理参数，须插在子命令**之前**。
//
// 参数：
//   - proxy: 代理地址；空串返回 nil
//
// 返回：
//   - 形如 []string{"-c", "http.proxy=socks5://127.0.0.1:1080"}
//
// 注意：
//   - git 的 http.proxy 只对 http(s):// 的 remote 生效，**对 ssh:// 与
//     git@host:path 无效**。SSH remote 要走代理得配 ssh 的 ProxyCommand，
//     那会动到用户的 ssh 配置面，不在 handoff 的职责内（见 README）
//   - 用 -c 而不是注入 HTTPS_PROXY 环境变量：不污染子进程环境，也不会让
//     本地 git 操作平白多一个配置
func GitArgs(proxy string) []string {
	if proxy == "" {
		return nil
	}
	return []string{"-c", "http.proxy=" + proxy}
}

n_proxycfg_Redact.signature:
// Redact 返回可安全打进日志的代理文本。
//
// 参数：
//   - proxy: 代理地址；空串返回空串
//
// 返回：
//   - 含 user:pass@ 时凭据部分替换为 ***，其余原样；解析不了时**只返回 scheme
//     加省略号**，绝不返回原文——解析失败恰恰是最可能把整串密码原样打出去的场合
//
// 注意：
//   - 这不是可选的美化。代理 URL 常含凭据，本仓纪律见 internal/envfile/resolver.go:64
func Redact(proxy string) string {
	if proxy == "" {
		return ""
	}
	u, err := url.Parse(proxy)
	if err != nil || u.Host == "" {
		return "<无法解析的 proxy 值，已隐藏>"
	}
	if u.User != nil {
		u.User = url.User("***")
	}
	return u.String()
}

n_proxycfg_Transport.signature:
// Transport 按 proxy 造一个 *http.Transport。
//
// 参数：
//   - proxy: 代理地址；**空串 = 不配**，返回的 Transport 沿用
//     http.ProxyFromEnvironment（即 HTTPS_PROXY/HTTP_PROXY/NO_PROXY），
//     与本功能上线前的行为一字不差
//
// 返回：
//   - 可直接塞进 http.Client 的 Transport
//   - 错误：proxy 未通过 Validate
//
// 注意：
//   - 非空 proxy 时**固定返回**该地址，不再看 NO_PROXY。显式配置就是显式意图，
//     而 handoff 自己走代理的出网只有 GitHub 一个域，"某些域不走代理"这个需求
//     在这里不存在
//   - 基于 http.DefaultTransport 克隆，因此连接池、HTTP/2、超时等默认值全部保留；
//     从零 new 一个 &http.Transport{} 会静默丢掉这些，症状是并发下载变慢而无人知晓
func Transport(proxy string) (*http.Transport, error) {
	if err := Validate(proxy); err != nil {
		return nil, err
	}
	base, ok := http.DefaultTransport.(*http.Transport)
	if !ok {

		return nil, fmt.Errorf("http.DefaultTransport 不是 *http.Transport（被第三方替换？）")
	}
	tr := base.Clone()
	if proxy == "" {
		return tr, nil
	}
	u, err := url.Parse(proxy)
	if err != nil {
		return nil, fmt.Errorf("解析 proxy %q: %w", proxy, err)
	}
	tr.Proxy = func(*http.Request) (*url.URL, error) { return u, nil }
	return tr, nil
}

n_proxycfg_Validate.signature:
// Validate 校验 proxy 取值域。空串合法（= 不配代理）。
//
// 参数：
//   - proxy: 代理地址，形如 socks5://127.0.0.1:1080
//
// 返回：
//   - 错误：URL 畸形、scheme 不在 SupportedSchemes、或缺 host。
//     错误文本一律列出支持的 scheme——只说"不支持"而不说"支持什么"，
//     等于让用户去猜
//   - 错误文本一律经 Redact，凭据不得落日志：Validate 的错误最终会被
//     config.Load 记进启动日志，原文回显等于把 user:pass@ 里的密码打出去
func Validate(proxy string) error {
	if proxy == "" {
		return nil
	}
	u, err := url.Parse(proxy)
	if err != nil {
		return fmt.Errorf("proxy %q 不是合法 URL: %w（支持 %s）",
			Redact(proxy), err, strings.Join(SupportedSchemes, "/"))
	}
	if !schemeSupported(u.Scheme) {
		return fmt.Errorf("proxy %q 的 scheme 为 %q，只支持 %s（裸 host:port 也不行，必须带 scheme）",
			Redact(proxy), u.Scheme, strings.Join(SupportedSchemes, "/"))
	}
	if u.Host == "" {
		return fmt.Errorf("proxy %q 缺少主机地址（支持 %s）",
			Redact(proxy), strings.Join(SupportedSchemes, "/"))
	}
	return nil
}

n_proxycfg_schemeSupported.signature:
func schemeSupported(s string) bool {
	for _, want := range SupportedSchemes {
		if s == want {
			return true
		}
	}
	return false
}

n_ptyapi_Host_Has.signature:
// Has 报告会话是否存活可附着（直通镜像：ptyhost.Host.Get 的存在性半边）。
func (p *Host) Has(id string) bool {
	_, ok := p.h.Get(id)
	return ok
}

n_ptyapi_Host_Snapshot.signature:
// Snapshot 读会话快照（直通镜像：ptyhost.Host.Get）。不存在返回 ok=false。
func (p *Host) Snapshot(id string) (SessionInfo, bool) {
	sess, ok := p.h.Get(id)
	if !ok {
		return SessionInfo{}, false
	}
	return SessionInfo{ID: sess.ID, Dir: sess.BasePath}, true
}

n_ptyhost_CloseAll.signature:
// CloseAll 扫描 root 下全部会话并 kill 掉还活着的那些。
//
// 参数：
//   - root: 会话根目录，通常是 <DataDir>/ptys。**不存在不算错**——这台机器
//     可能从没开过终端
//   - log: 日志入口，不能为 nil
//   - budget: 总时间预算；到点就返回，不阻塞调用方
//
// 返回：成功发出 kill 并等到收摊的会话数，以及扫描失败时的错误。
// 单个会话关不掉只记 Warn 不算整体失败——它可能刚好自己退了。
//
// 注意：dead 与 broken 状态的目录一概不碰。dead 的由 agentd 下次启动时清；
// broken 的意味着「有个进程活着而我们不知道它是什么」，杀它不安全。
func CloseAll(root string, log *slog.Logger, budget time.Duration) (int, error) {
	entries, err := sessdir.Scan(root)
	if err != nil {
		return 0, err
	}
	live := make([]sessdir.Entry, 0, len(entries))
	for _, e := range entries {
		if e.State == sessdir.StateLive {
			live = append(live, e)
		}
	}
	if len(live) == 0 {
		log.Debug("显式停止：没有活着的 PTY 会话", "root", root)
		return 0, nil
	}

	h := New(root, "", log)
	h.Adopt(live)

	ctx, cancel := context.WithTimeout(context.Background(), budget)
	defer cancel()
	var (
		mu	sync.Mutex
		closed	int
		wg	sync.WaitGroup
	)
	for _, e := range live {
		id := e.ID
		wg.Add(1)
		go func() {
			defer wg.Done()
			if err := h.Close(id); err != nil {
				log.Warn("显式停止 PTY 会话失败", "session", id, "err", err)
				return
			}
			mu.Lock()
			closed++
			mu.Unlock()
		}()
	}
	done := make(chan struct{})
	go func() {
		wg.Wait()
		close(done)
	}()
	select {
	case <-done:
		log.Info("显式停止：PTY 会话已收口", "closed", closed, "total", len(live))
	case <-ctx.Done():

		log.Warn("显式停止：PTY 会话收口超时，继续停止服务",
			"closed", closed, "total", len(live), "budget", budget)
	}
	mu.Lock()
	defer mu.Unlock()
	return closed, nil
}

n_ptyhost_DefaultEnvForward.signature:
// DefaultEnvForward 返回内置默认清单的副本。
//
// 返回副本而不是切片本身：调用方（config 解析、测试）拿到后可能就地排序或改写，
// 那会污染进程内所有后续会话。
func DefaultEnvForward() []string {
	out := make([]string, len(defaultEnvForward))
	copy(out, defaultEnvForward)
	return out
}

n_ptyhost_Host_Adopt.signature:
// Adopt 登记启动扫描发现的活会话。
//
// 参数：entries 是 sessdir.Scan 的结果；只有 StateLive 会被登记，broken 与 dead 由调用方处理。
// 返回：无。已有同 id 登记会被新的静态元数据覆盖。
// 注意：Adopt 不连接 socket、不验证协议、不删除目录；它是启动路径的纯登记动作。
func (h *Host) Adopt(entries []sessdir.Entry) {
	h.mu.Lock()
	adopted := 0
	for _, entry := range entries {
		if entry.State != sessdir.StateLive {
			continue
		}
		h.sessions[entry.ID] = &clientSession{meta: entry.Meta, waitDone: nil}
		if credential, ok := prochost.ProcessCredentialForPID(entry.Meta.PID); ok {
			h.credentials[entry.ID] = credential
		} else {
			delete(h.credentials, entry.ID)
		}
		adopted++
	}
	h.mu.Unlock()
	h.log.Info("ptyhost 会话已登记", "count", adopted)
}

n_ptyhost_Host_Attach.signature:
// Attach 建立一条长期订阅连接。
//
// 参数：id 是会话 id；since 是环形缓冲的输出水位。
// 返回：带历史回放与实时输出通道的 Attachment。
// 注意：协议版本先从 meta.json 检查；Backlog 在返回前已从 attached 后的第一数据帧取出。
func (h *Host) Attach(id string, since uint64) (*Attachment, error) {
	entry, ok := h.session(id)
	if !ok {
		return nil, ErrNoSession
	}
	if entry.meta.ProtoVersion != wire.ProtoVersion {
		return nil, fmt.Errorf("会话 %s 由 v%d 托管，本版（v%d）接不进来: %w", id,
			entry.meta.ProtoVersion, wire.ProtoVersion, ErrProtoMismatch)
	}
	conn, err := h.dial(id, socketWait)
	if err != nil {
		return nil, fmt.Errorf("连接 PTY 会话 %s 订阅: %w", id, err)
	}
	closeConn := true
	defer func() {
		if closeConn {
			_ = conn.Close()
		}
	}()
	if err := conn.SetDeadline(time.Now().Add(socketWait)); err != nil {
		return nil, fmt.Errorf("设置 PTY 会话 %s 订阅超时: %w", id, err)
	}
	if err := wire.WriteControl(conn, wire.Control{Type: wire.CtrlAttach, Since: since}); err != nil {
		return nil, fmt.Errorf("发送 PTY 会话 %s attach: %w", id, err)
	}
	kind, _, ctrl, err := wire.ReadFrame(conn)
	if err != nil {
		return nil, fmt.Errorf("读取 PTY 会话 %s attached: %w", id, err)
	}
	if kind != wire.KindControl || ctrl == nil || ctrl.Type != wire.CtrlAttached {
		return nil, fmt.Errorf("PTY 会话 %s 首帧不是 attached", id)
	}
	if ctrl.ProtoVersion != wire.ProtoVersion {
		return nil, fmt.Errorf("会话 %s 返回 v%d，本版为 v%d: %w", id, ctrl.ProtoVersion,
			wire.ProtoVersion, ErrProtoMismatch)
	}
	kind, backlog, _, err := wire.ReadFrame(conn)
	if err != nil {
		return nil, fmt.Errorf("读取 PTY 会话 %s 回放: %w", id, err)
	}
	if kind != wire.KindData {
		return nil, fmt.Errorf("PTY 会话 %s attached 后未收到数据回放帧", id)
	}
	if err := conn.SetDeadline(time.Time{}); err != nil {
		return nil, fmt.Errorf("清除 PTY 会话 %s 订阅超时: %w", id, err)
	}
	a := &clientAttachment{host: h, id: id, conn: conn, out: make(chan []byte, attachmentBuffer)}
	h.addAttachment(a)
	closeConn = false
	go a.readLoop()
	h.log.Info("ptyhost 会话已订阅", "session", id, "since", ctrl.Since,
		"backlog_bytes", len(backlog), "truncated", ctrl.Truncated)
	return NewAttachment(backlog, ctrl.Since, ctrl.Truncated, a.out, a), nil
}

n_ptyhost_Host_Close.signature:
// Close 显式发送 kill 并等待 ptyhost/PTY 收摊后摘除本地登记。
//
// 参数：id 是已登记会话 id。
// 返回：控制写失败、控制读非 EOF/timeout、ptyhost 退出失败或等待超时均返回错误。
// 注意：EOF/timeout 不是收摊事实；只有 cmd_wait 或 session_dir wait 成功才可返回 nil。
func (h *Host) Close(id string) error {
	started := time.Now()
	entry, ok := h.session(id)
	if !ok {
		h.log.Warn("关闭 PTY 会话：登记不存在", "session", id, "pid", 0, "wait_path", "unknown",
			"phase", "lookup", "elapsed", time.Since(started), "cause", ErrNoSession)
		return ErrNoSession
	}
	waitPath := "session_dir"
	if entry.waitDone != nil {
		waitPath = "cmd_wait"
	}
	conn, err := h.dial(id, statWait)
	if err != nil {
		h.log.Warn("关闭 PTY 会话：连接失败", "session", id, "pid", entry.meta.PID, "wait_path", waitPath,
			"phase", "dial", "elapsed", time.Since(started), "cause", err)
		return fmt.Errorf("连接 PTY 会话 %s 关闭: %w", id, err)
	}
	if err := conn.SetDeadline(time.Now().Add(statWait)); err != nil {
		_ = conn.Close()
		h.log.Warn("关闭 PTY 会话：设置 deadline 失败", "session", id, "pid", entry.meta.PID, "wait_path", waitPath,
			"phase", "control_deadline", "elapsed", time.Since(started), "cause", err)
		return fmt.Errorf("设置 PTY 会话 %s 关闭超时: %w", id, err)
	}
	if err := wire.WriteControl(conn, wire.Control{Type: wire.CtrlKill}); err != nil {
		_ = conn.Close()
		h.log.Error("关闭 PTY 会话：发送 kill 失败", "session", id, "pid", entry.meta.PID, "wait_path", waitPath,
			"phase", "send_kill", "elapsed", time.Since(started), "cause", err)
		return fmt.Errorf("发送 PTY 会话 %s kill: %w", id, err)
	}
	_, _, _, controlErr := wire.ReadFrame(conn)
	_ = conn.Close()
	if controlErr != nil {
		h.log.Warn("关闭 PTY 会话：未收到 control ack，继续等待进程事实", "session", id,
			"pid", entry.meta.PID, "wait_path", waitPath, "phase", "control_ack",
			"elapsed", time.Since(started), "cause", controlErr)
	}
	waitErr := h.waitPtyhostExit(entry, time.Now().Add(closeWait))
	h.forget(id)
	if waitErr != nil {
		h.log.Error("关闭 PTY 会话：等待收摊失败", "session", id, "pid", entry.meta.PID,
			"wait_path", waitPath, "phase", "wait", "elapsed", time.Since(started), "control_error", controlErr, "cause", waitErr)
		return fmt.Errorf("等待 PTY 会话 %s 收摊: %w", id, waitErr)
	}
	if controlErr != nil && !errors.Is(controlErr, io.EOF) && !isTimeout(controlErr) {
		h.log.Error("关闭 PTY 会话：control ack 失败", "session", id, "pid", entry.meta.PID,
			"wait_path", waitPath, "phase", "control_ack", "elapsed", time.Since(started), "cause", controlErr)
		return fmt.Errorf("等待 PTY 会话 %s 收摊控制帧: %w", id, controlErr)
	}
	h.log.Info("ptyhost 会话已按请求关闭", "session", id, "pid", entry.meta.PID,
		"wait_path", waitPath, "phase", "complete", "elapsed", time.Since(started), "control_error", controlErr)
	return nil
}

n_ptyhost_Host_Get.signature:
// Get 取一个已登记会话的最新快照。
//
// 返回：第二个返回值 false 表示客户端没有登记该 id；stat 失败时仍返回静态快照与 true。
// 注意：活事实不从旧缓存猜，查询失败的字段保持其零值。
func (h *Host) Get(id string) (Session, bool) {
	entry, ok := h.session(id)
	if !ok {
		return Session{}, false
	}
	sess := sessionFromMeta(entry.meta)
	fresh, err := h.stat(id)
	if err != nil {
		h.log.Debug("查询 PTY 会话活事实失败，返回静态元数据", "session", id, "err", err)
		return sess, true
	}
	return fresh, true
}

n_ptyhost_Host_List.signature:
// List 返回已登记的全部会话。
//
// 返回：每条会话都保留；stat 失败时返回静态元数据与活事实零值，并记 Debug。
// 注意：查询并发进行，每条连接最多等待 statWait，避免 N 个会话串行拖慢恢复。
func (h *Host) List() []Session {
	entries := h.sessionEntries()
	out := make([]Session, len(entries))
	var wg sync.WaitGroup
	for i, entry := range entries {
		wg.Add(1)
		go func(i int, entry *clientSession) {
			defer wg.Done()
			sess := sessionFromMeta(entry.meta)
			fresh, err := h.stat(entry.meta.ID)
			if err != nil {
				h.log.Debug("查询 PTY 会话活事实失败，保留静态元数据", "session", entry.meta.ID, "err", err)
				out[i] = sess
				return
			}
			out[i] = fresh
		}(i, entry)
	}
	wg.Wait()
	sort.Slice(out, func(i, j int) bool { return out[i].CreatedAt.Before(out[j].CreatedAt) })
	return out
}

n_ptyhost_Host_Open.signature:
// Open 创建会话并拉起一个脱离 agentd 生命周期的 ptyhost 进程。
//
// 参数：opt 是 shell、cwd、环境与初始尺寸。
// 返回：成功时返回会话快照；失败时保证不会留下本次创建的会话目录。
// 注意：启动路径不阻塞等待 ptyhost；成功登记后显式 Close 保留并等待该 Open child
// 的 waitDone。
func (h *Host) Open(opt OpenOptions) (Session, error) {
	if !h.Supported() {
		return Session{}, ErrNotSupported
	}
	if h.selfExe == "" {
		return Session{}, errors.New("无法拉起 ptyhost：handoff 可执行文件路径为空")
	}
	id := uuid.NewString()
	if err := sessdir.CheckSockPath(h.root, id); err != nil {
		return Session{}, fmt.Errorf("检查新会话 socket 路径: %w", err)
	}
	if err := sessdir.Create(h.root, id); err != nil {
		return Session{}, fmt.Errorf("创建新 PTY 会话目录 %s: %w", id, err)
	}
	cleanupDir := true
	defer func() {
		if cleanupDir {
			_ = sessdir.Remove(h.root, id)
		}
	}()

	spec := launchSpec{
		Root:	h.root, ID: id, BasePath: opt.BasePath, BaseKind: opt.BaseKind,
		Cwd:	opt.BasePath, Shell: opt.Shell, Env: opt.Env, Cols: opt.Cols, Rows: opt.Rows,
		InitCommand:	opt.InitCommand,
	}
	body, err := json.Marshal(spec)
	if err != nil {
		return Session{}, fmt.Errorf("编码 ptyhost spec %s: %w", id, err)
	}
	specPath := filepath.Join(sessdir.Dir(h.root, id), "spec.json")
	if err := os.WriteFile(specPath, body, 0o600); err != nil {
		return Session{}, fmt.Errorf("写 ptyhost spec %s: %w", specPath, err)
	}

	cmd := exec.Command(h.selfExe, "_ptyhost", "--spec", specPath)
	configureDetached(cmd)
	if err := cmd.Start(); err != nil {
		return Session{}, fmt.Errorf("拉起 ptyhost %s: %w", id, err)
	}
	waitDone := make(chan error, 1)
	go func() { waitDone <- cmd.Wait() }()
	h.log.Info("ptyhost 启动请求已发出", "session", id, "pid", cmd.Process.Pid)

	deadline := time.Now().Add(socketWait)
	for time.Now().Before(deadline) {
		select {
		case waitErr := <-waitDone:
			if waitErr == nil {
				waitErr = errors.New("退出码 0")
			}
			return Session{}, fmt.Errorf("ptyhost %s 在 socket 出现前退出: %w", id, waitErr)
		default:
		}
		if _, err := os.Stat(sessdir.SockPath(h.root, id)); err == nil {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	if _, err := os.Stat(sessdir.SockPath(h.root, id)); err != nil {
		cleanupDetached(cmd, waitDone)
		return Session{}, fmt.Errorf("等待 ptyhost socket %s 超时: %w", sessdir.SockPath(h.root, id), err)
	}

	meta, err := readMetaUntil(h.root, id, deadline)
	if err != nil {
		cleanupDetached(cmd, waitDone)
		return Session{}, fmt.Errorf("读取新 ptyhost 会话元数据 %s: %w", id, err)
	}
	h.remember(meta, waitDone)
	sess, err := h.getFresh(id)
	if err != nil {
		h.forget(id)
		cleanupDetached(cmd, waitDone)
		return Session{}, fmt.Errorf("查询新 ptyhost 会话 %s: %w", id, err)
	}
	cleanupDir = false
	h.log.Info("ptyhost 会话已可用", "session", id, "pid", sess.PID, "cwd", sess.BasePath)
	return sess, nil
}

n_ptyhost_Host_Supported.signature:
// Supported 报告本平台是否支持 PTY。
//
// 返回：Windows 与其它未实现平台为 false；Unix 为 true。
// 注意：这是编译期能力，不会为了探测能力而启动子进程。
func (h *Host) Supported() bool	{ return Supported() }

n_ptyhost_Host_Write.signature:
// Write 把按键写进会话。
//
// 参数：id 是会话 id；p 是 PTY 原始字节。
// 返回：写入 socket 或 ptyhost 失败时报错。
// 注意：优先复用该会话已有的订阅连接；没有订阅时只建立一条短连接。
func (h *Host) Write(id string, p []byte) error {
	if _, ok := h.session(id); !ok {
		return ErrNoSession
	}
	for _, att := range h.attachments(id) {
		if err := att.writeData(p); err == nil {
			return nil
		}
	}
	conn, err := h.dial(id, statWait)
	if err != nil {
		return fmt.Errorf("连接 PTY 会话 %s 写入: %w", id, err)
	}
	defer conn.Close()
	if err := conn.SetDeadline(time.Now().Add(statWait)); err != nil {
		return fmt.Errorf("设置 PTY 会话 %s 写入超时: %w", id, err)
	}
	if err := wire.WriteData(conn, p); err != nil {
		return fmt.Errorf("写入 PTY 会话 %s: %w", id, err)
	}
	return nil
}

n_ptyhost_Host_addAttachment.signature:
func (h *Host) addAttachment(att *clientAttachment) {
	h.mu.Lock()
	if h.conns[att.id] == nil {
		h.conns[att.id] = make(map[*clientAttachment]struct{})
	}
	h.conns[att.id][att] = struct{}{}
	h.mu.Unlock()
}

n_ptyhost_Host_attachments.signature:
func (h *Host) attachments(id string) []*clientAttachment {
	h.mu.RLock()
	set := h.conns[id]
	out := make([]*clientAttachment, 0, len(set))
	for att := range set {
		out = append(out, att)
	}
	h.mu.RUnlock()
	return out
}

n_ptyhost_Host_dial.signature:
func (h *Host) dial(id string, timeout time.Duration) (net.Conn, error) {
	conn, err := net.DialTimeout("unix", sessdir.SockPath(h.root, id), timeout)
	if err != nil {
		return nil, fmt.Errorf("连接会话 socket %s: %w", sessdir.SockPath(h.root, id), err)
	}
	return conn, nil
}

n_ptyhost_Host_forget.signature:
func (h *Host) forget(id string) {
	h.mu.Lock()
	delete(h.sessions, id)
	delete(h.credentials, id)
	attachments := h.conns[id]
	delete(h.conns, id)
	h.mu.Unlock()
	for att := range attachments {
		att.close()
	}
}

n_ptyhost_Host_getFresh.signature:
func (h *Host) getFresh(id string) (Session, error) {
	deadline := time.Now().Add(statWait)
	var last error
	for time.Now().Before(deadline) {
		sess, err := h.stat(id)
		if err == nil {
			return sess, nil
		}
		last = err
		time.Sleep(10 * time.Millisecond)
	}
	if last == nil {
		last = errors.New("未收到 stat 响应")
	}
	return Session{}, fmt.Errorf("stat 超时: %w", last)
}

n_ptyhost_Host_machineCredentials.signature:
// machineCredentials 返回仍登记的 ptyhost 凭据快照。
//
// 返回：调用方可安全持有的凭据副本。
// 注意：凭据不是按进程名推断出来的；它们只来自当前 Host 对 StateLive 会话的登记，
// 并且每条都在登记时与内核启动时刻核对过。快照不含无法核对的进程。
func (h *Host) machineCredentials() []prochost.ProcessCredential {
	h.mu.RLock()
	out := make([]prochost.ProcessCredential, 0, len(h.credentials))
	for _, credential := range h.credentials {
		out = append(out, credential)
	}
	h.mu.RUnlock()
	return out
}

n_ptyhost_Host_remember.signature:
// remember 登记静态元数据与 Open 子进程的唯一 Wait 通道。
//
// waitDone 只对当前进程直接启动的 Open 有值；Adopt 的跨进程会话必须传 nil，
// 由 waitPtyhostExit 观察会话目录，而不是错误地对非 child 调 exec.Cmd.Wait。
func (h *Host) remember(meta sessdir.Meta, waitDone <-chan error) {
	credential, credentialOK := prochost.ProcessCredentialForPID(meta.PID)
	h.mu.Lock()
	h.sessions[meta.ID] = &clientSession{meta: meta, waitDone: waitDone}
	if credentialOK {
		h.credentials[meta.ID] = credential
	} else {
		delete(h.credentials, meta.ID)
	}
	h.mu.Unlock()
}

n_ptyhost_Host_removeAttachment.signature:
func (h *Host) removeAttachment(att *clientAttachment) {
	h.mu.Lock()
	if set := h.conns[att.id]; set != nil {
		delete(set, att)
		if len(set) == 0 {
			delete(h.conns, att.id)
		}
	}
	h.mu.Unlock()
}

n_ptyhost_Host_session.signature:
func (h *Host) session(id string) (*clientSession, bool) {
	h.mu.RLock()
	entry, ok := h.sessions[id]
	h.mu.RUnlock()
	return entry, ok
}

n_ptyhost_Host_sessionEntries.signature:
func (h *Host) sessionEntries() []*clientSession {
	h.mu.RLock()
	out := make([]*clientSession, 0, len(h.sessions))
	for _, entry := range h.sessions {
		copyEntry := *entry
		out = append(out, &copyEntry)
	}
	h.mu.RUnlock()
	return out
}

n_ptyhost_Host_stat.signature:
func (h *Host) stat(id string) (Session, error) {
	entry, ok := h.session(id)
	if !ok {
		return Session{}, ErrNoSession
	}
	conn, err := h.dial(id, statWait)
	if err != nil {
		return Session{}, fmt.Errorf("查询会话 %s: %w", id, err)
	}
	defer conn.Close()
	if err := conn.SetDeadline(time.Now().Add(statWait)); err != nil {
		return Session{}, fmt.Errorf("设置会话 %s 查询超时: %w", id, err)
	}
	if err := wire.WriteControl(conn, wire.Control{Type: wire.CtrlStat}); err != nil {
		return Session{}, fmt.Errorf("发送会话 %s stat: %w", id, err)
	}
	kind, _, ctrl, err := wire.ReadFrame(conn)
	if err != nil {
		return Session{}, fmt.Errorf("读取会话 %s stat: %w", id, err)
	}
	if kind != wire.KindControl || ctrl == nil || ctrl.Type != wire.CtrlStatResp {
		return Session{}, fmt.Errorf("会话 %s stat 响应类型错误", id)
	}
	sess := sessionFromMeta(entry.meta)
	sess.Cols, sess.Rows, sess.Attached = ctrl.Cols, ctrl.Rows, ctrl.Attached
	sess.BytesOut, sess.Foreground, sess.ExitCode = ctrl.BytesOut, ctrl.Foreground, ctrl.ExitCode
	return sess, nil
}

n_ptyhost_Host_waitPtyhostExit.signature:
// waitPtyhostExit 等待本次 Close 触发的 ptyhost 真正退出。
//
// Open 的 waitDone 是唯一 child Wait 结果；Adopt 没有 child Wait，只能把 hostproc
// defer 的 sessdir.Remove 作为完成事实。deadline 由 Host.Close 统一提供。
func (h *Host) waitPtyhostExit(entry *clientSession, deadline time.Time) error {
	waitPath := "session_dir"
	if entry.waitDone != nil {
		waitPath = "cmd_wait"
		remaining := time.Until(deadline)
		if remaining <= 0 {
			return fmt.Errorf("等待 ptyhost %s(pid=%d) 退出超时: wait_path=%s", entry.meta.ID, entry.meta.PID, waitPath)
		}
		timer := time.NewTimer(remaining)
		defer timer.Stop()
		select {
		case err := <-entry.waitDone:
			if err != nil {
				return fmt.Errorf("ptyhost %s(pid=%d) 退出失败: wait_path=%s: %w", entry.meta.ID, entry.meta.PID, waitPath, err)
			}
			return nil
		case <-timer.C:
			return fmt.Errorf("等待 ptyhost %s(pid=%d) 退出超时: wait_path=%s", entry.meta.ID, entry.meta.PID, waitPath)
		}
	}
	ticker := time.NewTicker(10 * time.Millisecond)
	defer ticker.Stop()
	for {
		_, err := os.Stat(sessdir.Dir(h.root, entry.meta.ID))
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		if err != nil {
			return fmt.Errorf("检查 ptyhost %s(pid=%d) 会话目录 %s: wait_path=%s: %w",
				entry.meta.ID, entry.meta.PID, sessdir.Dir(h.root, entry.meta.ID), waitPath, err)
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("等待 ptyhost %s(pid=%d) 会话目录消失超时: path=%s wait_path=%s",
				entry.meta.ID, entry.meta.PID, sessdir.Dir(h.root, entry.meta.ID), waitPath)
		}
		<-ticker.C
	}
}

n_ptyhost_New.signature:
// New 创建一个 ptyhost 客户端。
//
// 参数：root 是 <DataDir>/ptys 会话根目录；selfExe 是当前 handoff 可执行文件的绝对路径；
// log 是 agentd 日志入口，不能为 nil。
// 返回：一个尚未登记会话的 Host。
// 注意：New 不扫描 root，也不连接任何 socket；启动时认领由 Adopt 完成。
func New(root, selfExe string, log *slog.Logger) *Host {
	h := &Host{
		root:	root, selfExe: selfExe, log: log,
		sessions:	make(map[string]*clientSession),
		credentials:	make(map[string]prochost.ProcessCredential),
		conns:		make(map[string]map[*clientAttachment]struct{}),
	}
	prochost.SetPtyhostCredentialProvider(h.machineCredentials)
	return h
}

n_ptyhost_NewAttachment.signature:
// NewAttachment 组装一个订阅壳。
//
// 参数：backlog/since/truncated/out 是订阅结果；ops 提供 Detach、ExitCode、Resize 行为。
// 返回：可交给 pty_ws.go 的具体 Attachment。
// 注意：ops 不应为 nil；调用三个方法前必须由构造者注入有效行为。
func NewAttachment(backlog []byte, since uint64, truncated bool, out <-chan []byte, ops AttachOps) *Attachment {
	return &Attachment{Backlog: backlog, Since: since, Truncated: truncated, Out: out, ops: ops}
}

n_ptyhost_ResolveEnvForward.signature:
// ResolveEnvForward 把 names 里每个变量按三级顺序解析后追加到 base，返回新环境。
//
// 参数：
//   - names: 要转发的变量名清单（调用方已按 nil→默认清单 归一化）
//   - base:  会话的基础环境（PATH / TERM 等），原样保留
//   - log:   逐个变量记录三态结论，不得为 nil
//
// 返回：base + 解析成功的 `NAME=VALUE`。探不到的变量**不出现**在结果里。
//
// 注意：日志只记变量名与结论来源，**不记变量值**——今天转发的是 socket 路径，
// 但这份清单是用户可配的，明天可能就有人往里加一个带凭据的变量。
func ResolveEnvForward(names []string, base []string, log *slog.Logger) []string {
	out := make([]string, 0, len(base)+len(names))
	out = append(out, base...)
	for _, name := range names {
		name = strings.TrimSpace(name)
		if name == "" {
			continue
		}
		if v := os.Getenv(name); v != "" {
			out = append(out, name+"="+v)
			log.Info("终端环境变量已转发", "name", name, "source", "inherited")
			continue
		}
		if v, ok := launchctlGetenv(name); ok {
			out = append(out, name+"="+v)
			log.Info("终端环境变量已转发", "name", name, "source", "resolved", "via", "launchctl")
			continue
		}

		log.Warn("终端环境变量无法解析，该会话里将没有它",
			"name", name, "source", "unavailable", "goos", runtime.GOOS)
	}
	return out
}

n_ptyhost_Supported.signature:
// Supported 报告本平台是否支持 PTY，供 /api/status 的 pty_supported 上报。
//
// 它是编译期常量而不是运行时探测：agentd 与 ptyhost 由同一个二进制在同一台机器上运行，
// 两者能力必然相同。
func Supported() bool	{ return ptySupported }

n_ptyhost_cleanupDetached.signature:
func cleanupDetached(cmd *exec.Cmd, waitDone <-chan error) {
	select {
	case <-waitDone:
		return
	default:
	}
	if cmd.Process != nil {
		_ = killDetached(cmd)
	}
	select {
	case <-waitDone:
	case <-time.After(statWait):
	}
}

n_ptyhost_clientAttachment_Detach.signature:
func (a *clientAttachment) Detach() {
	a.closeMu.Do(func() {
		a.host.log.Info("ptyhost 会话订阅已 detach", "session", a.id)
		a.host.removeAttachment(a)
		_ = a.conn.Close()
	})
}

n_ptyhost_clientAttachment_ExitCode.signature:
func (a *clientAttachment) ExitCode() *int {
	a.exitMu.Lock()
	defer a.exitMu.Unlock()
	if a.exit == nil {
		return nil
	}
	code := *a.exit
	return &code
}

n_ptyhost_clientAttachment_Resize.signature:
func (a *clientAttachment) Resize(cols, rows int) error {
	a.writeMu.Lock()
	defer a.writeMu.Unlock()
	if err := wire.WriteControl(a.conn, wire.Control{Type: wire.CtrlResize, Cols: cols, Rows: rows}); err != nil {
		return fmt.Errorf("发送 PTY 会话 %s resize: %w", a.id, err)
	}
	return nil
}

n_ptyhost_clientAttachment_readLoop.signature:
func (a *clientAttachment) readLoop() {
	defer close(a.out)
	defer a.host.removeAttachment(a)
	defer a.conn.Close()
	for {
		kind, data, ctrl, err := wire.ReadFrame(a.conn)
		if err != nil {
			if !errors.Is(err, io.EOF) && !errors.Is(err, io.ErrUnexpectedEOF) {
				a.host.log.Debug("ptyhost 订阅读取结束", "session", a.id, "err", err)
			}
			return
		}
		if kind == wire.KindData {
			a.out <- data
			continue
		}
		if kind == wire.KindControl && ctrl != nil && ctrl.Type == wire.CtrlExit {
			a.exitMu.Lock()
			if ctrl.ExitCode != nil {
				code := *ctrl.ExitCode
				a.exit = &code
			}
			a.exitMu.Unlock()
			return
		}
	}
}

n_ptyhost_clientAttachment_writeData.signature:
func (a *clientAttachment) writeData(p []byte) error {
	a.writeMu.Lock()
	defer a.writeMu.Unlock()
	if err := wire.WriteData(a.conn, p); err != nil {
		return fmt.Errorf("复用 PTY 会话 %s 订阅写入: %w", a.id, err)
	}
	return nil
}

n_ptyhost_isTimeout.signature:
func isTimeout(err error) bool {
	var ne net.Error
	return errors.As(err, &ne) && ne.Timeout()
}

n_ptyhost_killDetached.signature:
func killDetached(cmd *exec.Cmd) error {
	if cmd.Process == nil {
		return nil
	}
	if err := syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL); err != nil && !errors.Is(err, syscall.ESRCH) {
		return err
	}
	return nil
}

n_ptyhost_launchctlGetenvReal.signature:
// launchctlGetenvReal 在 macOS 上用 `launchctl getenv <name>` 查会话级变量。
//
// 关于这次 fork：B73 要求「防线全链路零 fork」，那条约束的对象是**进程耗尽时
// 仍需工作的诊断路径**。会话创建本身就要 fork 一个 shell，此处多一次 fork
// 不改变可用性边界。
//
// Linux 不猜：systemd 用户会话下没有等价的稳定查询口径，直接返回 false，
// 由「继承 + 用户显式配置」两条路兜底。
func launchctlGetenvReal(name string) (string, bool) {
	if runtime.GOOS != "darwin" {
		return "", false
	}
	out, err := exec.Command("launchctl", "getenv", name).Output()
	if err != nil {
		return "", false
	}
	v := strings.TrimSpace(string(out))
	if v == "" {
		return "", false
	}
	return v, true
}

n_ptyhost_readMetaUntil.signature:
func readMetaUntil(root, id string, deadline time.Time) (sessdir.Meta, error) {
	var last error
	for time.Now().Before(deadline) {
		meta, err := sessdir.ReadMeta(root, id)
		if err == nil {
			return meta, nil
		}
		last = err
		time.Sleep(10 * time.Millisecond)
	}
	return sessdir.Meta{}, fmt.Errorf("等待 meta.json: %w", last)
}

n_ptyhost_sessionFromMeta.signature:
func sessionFromMeta(m sessdir.Meta) Session {
	return Session{ID: m.ID, BasePath: m.BasePath, BaseKind: m.BaseKind, Shell: m.Shell,
		CreatedAt:	m.CreatedAt, PID: m.PID, Incompatible: m.ProtoVersion != wire.ProtoVersion}
}

n_ptytestroot_Choose.signature:
// Choose 按 candidates 顺序选择第一个 socket 路径不超过 socketLimit 的根。
//
// 参数：socketID 是会话 ID 或等长预算占位；socketLimit 是字节上限。
// 返回：成功时返回根、完整 socket 路径和字节数；全部候选失败时返回含每个实测值的错误。
// 注意：Choose 是纯函数，不做文件系统访问，也不负责 Cleanup。
func Choose(candidates []Candidate, socketID string, socketLimit int) (Decision, error) {
	if socketLimit <= 0 {
		return Decision{}, fmt.Errorf("PTY socket 路径上限必须为正数：%d", socketLimit)
	}
	attempts := make([]attempt, 0, len(candidates))
	for _, candidate := range candidates {
		path := socketPath(candidate.Root, socketID)
		bytes := len([]byte(path))
		attempt := attempt{
			source:		candidate.Source,
			root:		candidate.Root,
			socketPath:	path,
			socketBytes:	bytes,
			socketLimit:	socketLimit,
		}
		if bytes <= socketLimit {
			return Decision{
				Root:		candidate.Root,
				SocketPath:	path,
				SocketBytes:	bytes,
				SocketLimit:	socketLimit,
				Source:		candidate.Source,
			}, nil
		}
		attempts = append(attempts, attempt)
	}
	return Decision{}, &unavailableError{attempts: attempts}
}

n_ptytestroot_Resolve.signature:
// Resolve 在真实测试进程中执行根目录择位。
//
// 参数：socketID/socketLimit 定义长度预算；logger 接收入口、候选 IO、错误和成功节点，
// 传 nil 时使用 slog.Default。
// 返回：成功时返回可直接交给 PTY Host 的根和清理函数；失败时返回可供 t.Skipf 展示的
// 环境错误，错误文本列出每个候选的实测 socket 字节数与上限。
// 注意：覆盖根是调用方指定的目录，Resolve 不会在 Cleanup 中删除它。
func Resolve(socketID string, socketLimit int, logger *slog.Logger) (Decision, error) {
	if logger == nil {
		logger = slog.Default()
	}
	logger.Info("解析 PTY 测试根目录", "socket_id", socketID, "socket_limit", socketLimit,
		"override_set", os.Getenv("HANDOFF_PTY_TEST_ROOT") != "")

	cmd := exec.Command("go", "env", "GOMOD")
	logger.Debug("解析 Go module 根", "command", "go env GOMOD")
	gomod, err := cmd.Output()
	if err != nil {
		logger.Error("解析 Go module 根失败", "command", "go env GOMOD", "err", err)
		return Decision{}, fmt.Errorf("解析 Go module 根（go env GOMOD）失败: %w", err)
	}
	modPath := strings.TrimSpace(string(gomod))
	if modPath == "" {
		logger.Error("go env GOMOD 返回空路径")
		return Decision{}, errors.New("解析 Go module 根失败: go env GOMOD 返回空路径")
	}
	repoRoot := filepath.Dir(filepath.Clean(modPath))
	logger.Debug("Go module 根已解析", "gomod", modPath, "repo_root", repoRoot)
	return resolveFrom(repoRoot, socketID, socketLimit, os.Getenv("HANDOFF_PTY_TEST_ROOT"),
		fileSystem{
			mkdirTemp:	os.MkdirTemp,
			mkdirAll:	os.MkdirAll,
		}, logger)
}

n_ptytestroot_appendUnavailable.signature:
func appendUnavailable(dst []attempt, err error) []attempt {
	var unavailable *unavailableError
	if errors.As(err, &unavailable) {
		return append(dst, unavailable.attempts...)
	}
	return dst
}

n_ptytestroot_cleanupEmptyParent.signature:
func cleanupEmptyParent(parent string, logger *slog.Logger) {

	if err := os.Remove(parent); err != nil && !errors.Is(err, os.ErrNotExist) {
		logger.Debug("保留非空 PTY 测试父目录", "parent", parent, "err", err)
		return
	}
	logger.Debug("PTY 测试父目录已清理或不存在", "parent", parent)
}

n_ptytestroot_generatedCleanup.signature:
func generatedCleanup(root, parent string, source Source, logger *slog.Logger) func() {
	return func() {
		logger.Info("清理 PTY 测试根目录", "source", source, "root", root)
		removeGeneratedRoot(root, source, logger)
		if source == SourceRepoDot && parent != "" {
			cleanupEmptyParent(parent, logger)
		}
	}
}

n_ptytestroot_makeAttempt.signature:
func makeAttempt(source Source, root, socketID string, socketLimit int, err error) attempt {
	path := socketPath(root, socketID)
	return attempt{
		source:		source,
		root:		root,
		socketPath:	path,
		socketBytes:	len([]byte(path)),
		socketLimit:	socketLimit,
		err:		err,
	}
}

n_ptytestroot_removeGeneratedRoot.signature:
func removeGeneratedRoot(root string, source Source, logger *slog.Logger) {
	if err := os.RemoveAll(root); err != nil {
		logger.Warn("清理 PTY 测试根目录失败", "source", source, "root", root, "err", err)
		return
	}
	logger.Debug("PTY 测试根目录清理完成", "source", source, "root", root)
}

n_ptytestroot_resolveFrom.signature:
func resolveFrom(repoRoot, socketID string, socketLimit int, override string, fs fileSystem,
	logger *slog.Logger) (Decision, error) {
	if logger == nil {
		logger = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	if override != "" {
		logger.Info("尝试 HANDOFF_PTY_TEST_ROOT 覆盖根", "root", override)
		probe := makeAttempt(SourceOverride, override, socketID, socketLimit, nil)
		if err := fs.mkdirAll(override, 0o700); err != nil {
			probe.err = fmt.Errorf("创建覆盖根 %s: %w", override, err)
			logger.Warn("PTY 测试覆盖根不可写", "root", override, "socket_bytes", probe.socketBytes,
				"socket_limit", socketLimit, "err", probe.err)
			return Decision{}, &unavailableError{attempts: []attempt{probe}}
		}
		decision, err := Choose([]Candidate{{Root: override, Source: SourceOverride}}, socketID, socketLimit)
		if err != nil {
			logger.Warn("PTY 测试覆盖根路径超限", "root", override, "err", err)
			return Decision{}, err
		}
		decision.Cleanup = func() {
			logger.Info("保留 PTY 测试覆盖根", "source", decision.Source, "root", decision.Root)
		}
		logger.Info("PTY 测试根目录已选择", "source", decision.Source, "root", decision.Root,
			"socket", decision.SocketPath, "socket_bytes", decision.SocketBytes)
		return decision, nil
	}

	attempts := make([]attempt, 0, 2)
	logger.Debug("尝试 /tmp PTY 测试根", "parent", "/tmp")
	tmpRoot, err := fs.mkdirTemp("/tmp", "handoff-pty-")
	if err != nil {
		probe := makeAttempt(SourceTmp, "/tmp", socketID, socketLimit, err)
		attempts = append(attempts, probe)
		logger.Warn("/tmp PTY 测试根不可写", "parent", "/tmp", "socket_bytes", probe.socketBytes,
			"socket_limit", socketLimit, "err", err)
	} else {
		decision, chooseErr := Choose([]Candidate{{Root: tmpRoot, Source: SourceTmp}}, socketID, socketLimit)
		if chooseErr == nil {
			decision.Cleanup = generatedCleanup(tmpRoot, "", SourceTmp, logger)
			logger.Info("PTY 测试根目录已选择", "source", decision.Source, "root", decision.Root,
				"socket", decision.SocketPath, "socket_bytes", decision.SocketBytes)
			return decision, nil
		}
		attempts = appendUnavailable(attempts, chooseErr)
		logger.Warn("/tmp PTY 测试根 socket 路径超限", "root", tmpRoot, "err", chooseErr)
		removeGeneratedRoot(tmpRoot, SourceTmp, logger)
	}

	parent := filepath.Join(repoRoot, ".pty-test-root")
	logger.Debug("尝试仓库点号 PTY 测试根", "parent", parent)
	if err := fs.mkdirAll(parent, 0o700); err != nil {
		probe := makeAttempt(SourceRepoDot, parent, socketID, socketLimit, err)
		attempts = append(attempts, probe)
		logger.Warn("仓库点号 PTY 测试父目录不可写", "parent", parent,
			"socket_bytes", probe.socketBytes, "socket_limit", socketLimit, "err", err)
		cleanupEmptyParent(parent, logger)
		return Decision{}, &unavailableError{attempts: attempts}
	}
	repoRootPath, err := fs.mkdirTemp(parent, "handoff-pty-")
	if err != nil {
		probe := makeAttempt(SourceRepoDot, parent, socketID, socketLimit, err)
		attempts = append(attempts, probe)
		logger.Warn("仓库点号 PTY 测试根不可写", "parent", parent,
			"socket_bytes", probe.socketBytes, "socket_limit", socketLimit, "err", err)
		cleanupEmptyParent(parent, logger)
		return Decision{}, &unavailableError{attempts: attempts}
	}
	decision, chooseErr := Choose([]Candidate{{Root: repoRootPath, Source: SourceRepoDot}}, socketID, socketLimit)
	if chooseErr != nil {
		attempts = appendUnavailable(attempts, chooseErr)
		logger.Warn("仓库点号 PTY 测试根 socket 路径超限", "root", repoRootPath, "err", chooseErr)
		removeGeneratedRoot(repoRootPath, SourceRepoDot, logger)
		cleanupEmptyParent(parent, logger)
		return Decision{}, &unavailableError{attempts: attempts}
	}
	decision.Cleanup = generatedCleanup(repoRootPath, parent, SourceRepoDot, logger)
	logger.Info("PTY 测试根目录已选择", "source", decision.Source, "root", decision.Root,
		"socket", decision.SocketPath, "socket_bytes", decision.SocketBytes)
	return decision, nil
}

