func Decode(b []byte) (Frame, error) {
	var f Frame
	if err := json.Unmarshal(b, &f); err != nil {
		return Frame{}, fmt.Errorf("decode relay frame: %w", err)
	}
	if !knownFrameType(f.Type) {
		return Frame{}, fmt.Errorf("decode relay frame: unknown type %q", f.Type)
	}
	return f, nil
}

