n_relay_derivePSK.signature:
// derivePSK uses domain separation and identity binding: changing account or
// node changes the key and prevents cross-pairing confusion.
func derivePSK(token, account, node string, salt []byte) ([]byte, error) {
	if len(salt) != saltLen {
		return nil, fmt.Errorf("e2e salt must be %d bytes, got %d", saltLen, len(salt))
	}
	info := []byte(e2eInfoPrefix + "|" + account + "|" + node)
	key := make([]byte, 32)
	if _, err := io.ReadFull(hkdf.New(sha256.New, []byte(token), salt, info), key); err != nil {
		return nil, fmt.Errorf("derive e2e PSK: %w", err)
	}
	return key, nil
}

n_relay_knownFrameType.signature:
func knownFrameType(t FrameType) bool {
	switch t {
	case Register, Connect, Registered, ConnectOK, Error:
		return true
	default:
		return false
	}
}

n_relay_readAppFrame.signature:
func readAppFrame(r io.Reader) ([]byte, error) {
	var prefix [appPrefixLen]byte
	if _, err := io.ReadFull(r, prefix[:]); err != nil {
		return nil, err
	}
	n := binary.BigEndian.Uint16(prefix[:])
	b := make([]byte, n)
	if _, err := io.ReadFull(r, b); err != nil {
		return nil, err
	}
	return b, nil
}

n_relay_readFrame.signature:
func readFrame(r io.Reader, max int) ([]byte, error) {
	var prefix [lengthPrefixLen]byte
	if _, err := io.ReadFull(r, prefix[:]); err != nil {
		return nil, err
	}
	n := binary.BigEndian.Uint32(prefix[:])
	if n > uint32(max) {
		return nil, fmt.Errorf("frame length %d exceeds maximum %d", n, max)
	}
	b := make([]byte, n)
	if _, err := io.ReadFull(r, b); err != nil {
		return nil, err
	}
	return b, nil
}

n_relay_readLengthPrefixed.signature:
func readLengthPrefixed(r io.Reader, dst []byte, expected int) error {
	var prefix [lengthPrefixLen]byte
	if _, err := io.ReadFull(r, prefix[:]); err != nil {
		return err
	}
	n := binary.BigEndian.Uint32(prefix[:])
	if n != uint32(expected) {
		return fmt.Errorf("unexpected frame length %d, want %d", n, expected)
	}
	_, err := io.ReadFull(r, dst)
	return err
}

n_relay_readPreviewRawRequest.signature:
func readPreviewRawRequest(r io.Reader) (network, addr string, err error) {
	magic := make([]byte, len(previewRawMagic))
	if _, err := io.ReadFull(r, magic); err != nil {
		return "", "", err
	}
	if string(magic) != previewRawMagic {
		return "", "", fmt.Errorf("relay raw magic 非法: %q", magic)
	}
	parts := make([]string, 2)
	for i := range parts {
		var size [2]byte
		if _, err := io.ReadFull(r, size[:]); err != nil {
			return "", "", err
		}
		length := int(binary.BigEndian.Uint16(size[:]))
		if length == 0 || length > previewRawMaxPart {
			return "", "", fmt.Errorf("relay raw request 字段长度非法: %d", length)
		}
		part := make([]byte, length)
		if _, err := io.ReadFull(r, part); err != nil {
			return "", "", err
		}
		parts[i] = string(part)
	}
	return parts[0], parts[1], nil
}

n_relay_readPreviewRawResponse.signature:
func readPreviewRawResponse(r io.Reader) error {
	var status [1]byte
	if _, err := io.ReadFull(r, status[:]); err != nil {
		return fmt.Errorf("读取 relay raw 响应: %w", err)
	}
	if status[0] == previewRawOK {
		return nil
	}
	if status[0] != previewRawError {
		return fmt.Errorf("relay raw 响应状态非法: %d", status[0])
	}
	var size [2]byte
	if _, err := io.ReadFull(r, size[:]); err != nil {
		return fmt.Errorf("读取 relay raw 错误长度: %w", err)
	}
	length := int(binary.BigEndian.Uint16(size[:]))
	if length > previewRawMaxPart {
		return fmt.Errorf("relay raw 错误长度非法: %d", length)
	}
	message := make([]byte, length)
	if _, err := io.ReadFull(r, message); err != nil {
		return fmt.Errorf("读取 relay raw 错误: %w", err)
	}
	return fmt.Errorf("owner raw dial 失败: %s", strings.TrimSpace(string(message)))
}

n_relay_recvControl.signature:
// recvControl reads one text control message. An Error frame is returned as a
// ControlError so callers can preserve the relay's machine-readable code.
func recvControl(ctx context.Context, ws *websocket.Conn) (Frame, error) {
	typ, b, err := ws.Read(ctx)
	if err != nil {
		return Frame{}, fmt.Errorf("receive relay control frame: %w", err)
	}
	if typ != websocket.MessageText {
		return Frame{}, fmt.Errorf("receive relay control frame: expected text message, got %s", typ)
	}
	f, err := Decode(b)
	if err != nil {
		return Frame{}, err
	}
	if f.Type == Error {
		return Frame{}, &ControlError{Code: f.Code, Message: f.Message}
	}
	return f, nil
}

n_relay_relayYamuxConfig.signature:
// relayYamuxConfig suppresses yamux's default stderr logger. Relay lifecycle
// failures are reported through the package slog logger with node/account
// context; yamux must not emit raw transport details on its own.
func relayYamuxConfig() *yamux.Config {
	cfg := yamux.DefaultConfig()
	cfg.LogOutput = io.Discard
	cfg.Logger = nil
	return cfg
}

n_relay_secure.signature:
func secure(ctx context.Context, raw net.Conn, token, account, node string, initiator bool) (net.Conn, error) {
	if raw == nil {
		return nil, errors.New("e2e: nil raw connection")
	}
	stop := watchContext(ctx, raw)
	defer stop()
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	salt := make([]byte, saltLen)
	if initiator {
		if _, err := rand.Read(salt); err != nil {
			return nil, fmt.Errorf("generate e2e salt: %w", err)
		}

		if err := writeLengthPrefixed(raw, salt); err != nil {
			return nil, fmt.Errorf("send e2e salt: %w", err)
		}
	} else if err := readLengthPrefixed(raw, salt, saltLen); err != nil {
		return nil, fmt.Errorf("receive e2e salt: %w", err)
	}

	psk, err := derivePSK(token, account, node, salt)
	if err != nil {
		return nil, err
	}
	hs, err := noise.NewHandshakeState(noise.Config{
		CipherSuite:		noise.NewCipherSuite(noise.DH25519, noise.CipherChaChaPoly, noise.HashSHA256),
		Pattern:		noise.HandshakeNN,
		Initiator:		initiator,
		PresharedKey:		psk,
		PresharedKeyPlacement:	0,
	})
	if err != nil {
		return nil, fmt.Errorf("initialize e2e handshake: %w", err)
	}

	var send, recv *noise.CipherState
	if initiator {
		msg, _, _, err := hs.WriteMessage(nil, nil)
		if err != nil {
			return nil, fmt.Errorf("write e2e handshake: %w", err)
		}
		if err := writeLengthPrefixed(raw, msg); err != nil {
			return nil, fmt.Errorf("send e2e handshake: %w", err)
		}
		reply, err := readFrame(raw, noise.MaxMsgLen)
		if err != nil {
			return nil, fmt.Errorf("read e2e handshake: %w", err)
		}
		msg, send, recv, err = hs.ReadMessage(nil, reply)
		if err != nil {
			return nil, fmt.Errorf("read e2e handshake: %w", err)
		}
		_ = msg
	} else {
		msg, err := readFrame(raw, noise.MaxMsgLen)
		if err != nil {
			return nil, fmt.Errorf("receive e2e handshake: %w", err)
		}
		if _, _, _, err := hs.ReadMessage(nil, msg); err != nil {
			return nil, fmt.Errorf("read e2e handshake: %w", err)
		}
		msg, send, recv, err = hs.WriteMessage(nil, nil)
		if err != nil {
			return nil, fmt.Errorf("write e2e handshake: %w", err)
		}
		if err := writeLengthPrefixed(raw, msg); err != nil {
			return nil, fmt.Errorf("send e2e handshake: %w", err)
		}

		send, recv = recv, send
	}
	if send == nil || recv == nil {
		return nil, errors.New("e2e handshake completed without cipher states")
	}
	return &secureConn{raw: raw, send: send, recv: recv}, nil
}

n_relay_secureConn_Close.signature:
func (c *secureConn) Close() error {
	var err error
	c.closeOnce.Do(func() { err = c.raw.Close() })
	return err
}

n_relay_secureConn_Read.signature:
func (c *secureConn) Read(p []byte) (int, error) {
	c.readMu.Lock()
	defer c.readMu.Unlock()
	if len(p) == 0 {
		return 0, nil
	}
	c.bufMu.Lock()
	if len(c.readBuf) > 0 {
		n := copy(p, c.readBuf)
		c.readBuf = c.readBuf[n:]
		c.bufMu.Unlock()
		return n, nil
	}
	c.bufMu.Unlock()

	ciphertext, err := readAppFrame(c.raw)
	if err != nil {
		return 0, err
	}
	plaintext, err := c.recv.Decrypt(nil, nil, ciphertext)
	if err != nil {
		return 0, fmt.Errorf("decrypt e2e frame: %w", err)
	}
	n := copy(p, plaintext)
	if n < len(plaintext) {
		c.bufMu.Lock()
		c.readBuf = append(c.readBuf, plaintext[n:]...)
		c.bufMu.Unlock()
	}
	return n, nil
}

n_relay_secureConn_Write.signature:
func (c *secureConn) Write(p []byte) (int, error) {
	if len(p) == 0 {
		return 0, nil
	}
	c.writeMu.Lock()
	defer c.writeMu.Unlock()
	written := 0
	for written < len(p) {
		n := len(p) - written
		if n > maxPlaintext {
			n = maxPlaintext
		}
		ciphertext, err := c.send.Encrypt(nil, nil, p[written:written+n])
		if err != nil {
			return written, fmt.Errorf("encrypt e2e frame: %w", err)
		}
		if err := writeAppFrame(c.raw, ciphertext); err != nil {
			return written, err
		}
		written += n
	}
	return written, nil
}

n_relay_sendControl.signature:
// sendControl sends a single control frame as a WebSocket text message.
func sendControl(ctx context.Context, ws *websocket.Conn, f Frame) error {
