n_relay_writeAppFrame.signature:
func writeAppFrame(w io.Writer, payload []byte) error {
	if len(payload) > maxFrameLen {
		return fmt.Errorf("app frame too large: %d", len(payload))
	}
	var prefix [appPrefixLen]byte
	binary.BigEndian.PutUint16(prefix[:], uint16(len(payload)))
	if err := writeFull(w, prefix[:]); err != nil {
		return err
	}
	return writeFull(w, payload)
}

n_relay_writeFull.signature:
func writeFull(w io.Writer, p []byte) error {
	for len(p) > 0 {
		n, err := w.Write(p)
		if err != nil {
			return err
		}
		if n == 0 {
			return io.ErrShortWrite
		}
		p = p[n:]
	}
	return nil
}

n_relay_writeLengthPrefixed.signature:
func writeLengthPrefixed(w io.Writer, payload []byte) error {
	if len(payload) > maxFrameLen {
		return fmt.Errorf("frame too large: %d", len(payload))
	}
	var prefix [lengthPrefixLen]byte
	binary.BigEndian.PutUint32(prefix[:], uint32(len(payload)))
	if err := writeFull(w, prefix[:]); err != nil {
		return err
	}
	return writeFull(w, payload)
}

n_relay_writePreviewRawRequest.signature:
func writePreviewRawRequest(w io.Writer, network, addr string) error {
	if len(network) > previewRawMaxPart || len(addr) > previewRawMaxPart {
		return fmt.Errorf("relay raw request 字段过长 network=%d addr=%d", len(network), len(addr))
	}
	if _, err := io.WriteString(w, previewRawMagic); err != nil {
		return err
	}
	for _, part := range []string{network, addr} {
		var size [2]byte
		binary.BigEndian.PutUint16(size[:], uint16(len(part)))
		if _, err := w.Write(size[:]); err != nil {
			return err
		}
		if _, err := io.WriteString(w, part); err != nil {
			return err
		}
	}
	return nil
}

n_relay_writePreviewRawResponse.signature:
func writePreviewRawResponse(w io.Writer, err error) error {
	if err == nil {
		_, writeErr := w.Write([]byte{previewRawOK})
		return writeErr
	}
	message := err.Error()
	if len(message) > previewRawMaxPart {
		message = message[:previewRawMaxPart]
	}
	var size [2]byte
	binary.BigEndian.PutUint16(size[:], uint16(len(message)))
	if _, writeErr := w.Write([]byte{previewRawError}); writeErr != nil {
		return writeErr
	}
	if _, writeErr := w.Write(size[:]); writeErr != nil {
		return writeErr
	}
	_, writeErr := io.WriteString(w, message)
	return writeErr
}

n_release_Activate.signature:
// Activate 把新二进制换到目标路径，旧的留成 <target>.prev。
//
// 参数：
//   - newPath: Fetch 返回的临时文件路径（必须与 target 同目录）
//   - target: 目标二进制路径（应已 EvalSymlinks 解析过）
//
// 返回：
//   - 留存的旧二进制路径
//   - 错误：目录不可写、rename 失败
//
// 注意：
//   - 两次 rename 都是同目录内操作，因而是原子的。中途失败最坏的结果是
//     「旧的已挪到 .prev、新的还没就位」——此时目标路径暂时缺失，
//     所以第二次 rename 失败时会把 .prev 挪回来
//   - **两次 rename 的顺序在 Windows 上是承重的**：Windows 允许 rename 一个
//     正在运行的 exe，但不允许覆盖或删除它。所以「先把旧的挪走、再把新的挪进来」
//     恰好就是 Windows 自更新的标准手法。**不要**把它「优化」成先删后写——
//     那在 unix 上照样绿，在 Windows 上当场炸
func Activate(newPath, target string) (string, error) {
	dir := filepath.Dir(target)

	if err := checkDirWritable(dir); err != nil {
		return "", err
	}
	prev := PrevPath(target)
	if err := os.Rename(target, prev); err != nil && !errors.Is(err, os.ErrNotExist) {
		return "", fmt.Errorf("留存旧二进制到 %s: %w", prev, err)
	}
	if err := os.Rename(newPath, target); err != nil {

		if rerr := os.Rename(prev, target); rerr != nil {
			return "", fmt.Errorf("换入新二进制失败且旧二进制未能复位（现在在 %s，请手动 mv 回 %s）: %w", prev, target, err)
		}
		return "", fmt.Errorf("换入新二进制 %s: %w", target, err)
	}
	return prev, nil
}

n_release_AssetName.signature:
// AssetName 拼装某平台的资产名。
//
// 参数：
//   - tag: 版本号，形如 v0.1.0
//   - goos / goarch: 目标平台
//
// 返回：
//   - 资产文件名
//
// 注意：
//   - 格式必须与 .github/workflows/release.yml 里的产出**逐字一致**。
//     不一致的症状是查得到版本但下不到东西，且每轮重试
//   - 扩展名按平台分（见 archiveExt），install.sh / install.ps1 两边也依赖这条
func AssetName(tag, goos, goarch string) string {
	return fmt.Sprintf("handoff_%s_%s_%s%s", tag, goos, goarch, archiveExt(goos))
}

n_release_AssetURL.signature:
// AssetURL 拼一个 release 资产的下载地址。
//
// 参数：
//   - repo: owner/name，如 Xsxdot/handoff
//   - tag: 版本号，形如 v0.2.3
//   - name: 资产文件名，用 AssetName 生成
//
// 返回：
//   - 完整下载地址
//
// 注意：
//   - GitHub 的这个地址是**确定性**的，不需要先查 API 就能拼出来。agentd
//     自拉时用的正是它——api.github.com 有 60 次/小时/IP 的匿名限流，
//     而多台执行机很可能共用一个代理出口 IP，走 API 迟早互相打架
func AssetURL(repo, tag, name string) string {
	return fmt.Sprintf("%s/%s/releases/download/%s/%s", DownloadBase, repo, tag, name)
}

n_release_Client_Latest.signature:
// Latest 查最新发布。
//
// 参数：
//   - ctx: 上下文，用于超时与取消
//
// 返回：
//   - 解析后的 Release
//   - 错误：网络失败、非 200、响应畸形
//
// 注意：
//   - 匿名调用有 60 次/小时/IP 的限流，被限流时返回带 403 的错误。
//     **调用方不要重试**——interval 本身就是退避（spec §4.7）
func (c *Client) Latest(ctx context.Context) (Release, error) {
	url := fmt.Sprintf("%s/repos/%s/releases/latest", strings.TrimSuffix(c.APIBase, "/"), c.Repo)
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return Release{}, fmt.Errorf("构造请求: %w", err)
	}
	req.Header.Set("Accept", "application/vnd.github+json")
	resp, err := c.HTTP.Do(req)
	if err != nil {
		return Release{}, fmt.Errorf("查最新版本 %s: %w", url, err)
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, 4<<20))
	if err != nil {
		return Release{}, fmt.Errorf("读响应: %w", err)
	}
	if resp.StatusCode != http.StatusOK {

		return Release{}, fmt.Errorf("查最新版本返回 %d: %s", resp.StatusCode, firstLine(string(body)))
	}
	var gr ghRelease
	if err := json.Unmarshal(body, &gr); err != nil {
		return Release{}, fmt.Errorf("解析响应: %w", err)
	}
	if gr.TagName == "" {

		return Release{}, fmt.Errorf("响应里没有 tag_name（仓库 %s 可能还没有任何 release）", c.Repo)
	}
	rel := Release{Tag: gr.TagName}
	for _, a := range gr.Assets {
		rel.Assets = append(rel.Assets, Asset{Name: a.Name, URL: a.URL})
	}
	return rel, nil
}

n_release_DesktopAssetName.signature:
// DesktopAssetName 返回桌面薄壳在某平台的发布物文件名。
//
// 参数：tag 形如 v0.3.1；goos/goarch 用 runtime 的取值。
// 返回：文件名与「该平台有没有薄壳发布物」。ok 为 false 时文件名为空，
// 调用方必须先判 ok，不能拿空串去拼下载地址。
//
// 注意：
//   - 前缀是 handoff-desktop_，与 CLI 的 handoff_ 不同。checksums.txt 里两者
//     并列，用 handoff_* 通配是匹配不到薄壳资产的（release.yml 的注释点名了这一条）。
//   - 不与 AssetName 合并：两者的扩展名规则完全不同，薄壳按 goos 选
//     dmg/zip/AppImage，合并会让两套互不相干的分支挤在一起。
//   - 发布流水线只构建 darwin/arm64、windows/amd64、linux/amd64 三种薄壳，
//     其余平台一律返回 false——判不出就说没有，不猜一个不存在的文件名。
func DesktopAssetName(tag, goos, goarch string) (string, bool) {
	ext := ""
	switch {
	case goos == "darwin" && goarch == "arm64":
		ext = "dmg"
	case goos == "windows" && goarch == "amd64":
		ext = "zip"
	case goos == "linux" && goarch == "amd64":
		ext = "AppImage"
	default:
		return "", false
	}
	return fmt.Sprintf("handoff-desktop_%s_%s_%s.%s", tag, goos, goarch, ext), true
}

n_release_Installer_Fetch.signature:
// Fetch 下载本平台资产、校验、解包、自检，返回可供 Activate 的临时文件路径。
//
// 参数：
//   - ctx: 上下文
//   - rel: 目标发布
//   - destDir: 临时文件落点，**必须**与目标二进制同目录
//
// 返回：
//   - 临时二进制的完整路径（已 chmod 0755 并通过自检）
//   - 错误：缺资产、下载失败、校验不过、解包失败、自检不过
//
// 注意：
//   - 任何一步失败都会把临时文件删掉，不留残件
//   - 本函数是 FetchArchive + InstallArchive 的本机组合，行为与拆分前一致
func (i *Installer) Fetch(ctx context.Context, rel Release, destDir string) (string, error) {
	goos, goarch := CurrentPlatform()
	tgz, sum, err := i.FetchArchive(ctx, rel, goos, goarch)
	if err != nil {
		return "", err
	}
	return i.InstallArchive(tgz, sum, rel.Tag, destDir)
}

n_release_Installer_FetchArchive.signature:
// FetchArchive 按指定平台下载资产并校验完整性，返回字节与期望哈希。
//
// 参数：
//   - ctx: 上下文
//   - rel: 目标发布
//   - goos / goarch: **目标机器**的平台，不是本机——跨平台推送时远端可能
//     是 linux/amd64 而本机是 darwin/arm64，必须知道该下哪份资产
//
// 返回：
//   - tgz: 资产原文（tar.gz 字节，**未经解包**）
//   - 期望的 sha256（十六进制小写），**来自 checksums.txt 的声明**——
//     这是信任链的第一道校验，消费方把它原样传给 InstallArchive 让两端
//     比同一个来自 release 的声明，不互相背书
//   - 错误：缺资产、下载失败、校验不过
//
// 注意：
//   - **不解包、不自检**。自检要 exec 执行新二进制，而本机执行别的平台的
//     二进制必然失败——自检必须在目标平台上做（agentd 收到推送后）
//   - 不重试：完整性失败重试只会重下同一份坏数据（spec §4.7）
func (i *Installer) FetchArchive(ctx context.Context, rel Release, goos, goarch string) ([]byte, string, error) {
	asset, ok := rel.AssetFor(goos, goarch)
	if !ok {
		return nil, "", fmt.Errorf("发布 %s 没有 %s/%s 的资产（%s）", rel.Tag, goos, goarch, AssetName(rel.Tag, goos, goarch))
	}
	ck, ok := rel.Checksums()
	if !ok {

		return nil, "", fmt.Errorf("发布 %s 没有 %s，无法校验完整性", rel.Tag, ChecksumsName)
	}

	i.Log.Info("开始下载资产", "tag", rel.Tag, "platform", goos+"/"+goarch, "asset", asset.Name, "url", asset.URL)
	tgz, err := i.get(ctx, asset.URL)
	if err != nil {
		return nil, "", fmt.Errorf("下载 %s: %w", asset.Name, err)
	}
	sums, err := i.get(ctx, ck.URL)
	if err != nil {
		return nil, "", fmt.Errorf("下载 %s: %w", ChecksumsName, err)
	}

	want, err := sumFor(string(sums), asset.Name)
	if err != nil {
		return nil, "", err
	}
	got := sha256.Sum256(tgz)
	if hex.EncodeToString(got[:]) != want {
		return nil, "", fmt.Errorf("sha256 校验不通过（期望 %s，实得 %s）", want, hex.EncodeToString(got[:]))
	}
	i.Log.Info("资产校验通过", "tag", rel.Tag, "asset", asset.Name, "sha256", want, "bytes", len(tgz))
	return tgz, want, nil
}

n_release_Installer_FetchByTag.signature:
// FetchByTag 按 tag 拼出下载地址、下载资产并用**给定的** sha256 校验。
//
// 参数：
//   - ctx: 上下文
//   - repo: owner/name
//   - tag: 目标版本
//   - goos / goarch: 本机平台
//   - wantSum: 期望的 sha256（十六进制小写）。自拉模式下**来自协调者下发**
//
// 返回：
//   - 资产原文（tar.gz / zip 字节，未解包）
//   - 错误：下载失败、sha256 不符
//
// 注意：
//   - 与 FetchArchive 的区别是**不需要 Release 对象、不查 API**：地址由
//     AssetURL 确定性拼出，wantSum 由调用方给。这让执行机完全不碰
//     api.github.com（避开 60 次/小时/IP 的匿名限流）
//   - wantSum 由调用方给而不是自己去取 checksums，是刻意的：校验和与资产
//     走两条不同的信任路径，本机代理/镜像被投毒时才抓得住（spec §5.5）。
//     **别"优化"成自己下 checksums**
//   - 不重试：完整性失败重试只会重下同一份坏数据（spec §4.7）
func (i *Installer) FetchByTag(ctx context.Context, repo, tag, goos, goarch, wantSum string) ([]byte, error) {
	base := i.DownloadBase
	if base == "" {
		base = DownloadBase
	}
	name := AssetName(tag, goos, goarch)
	url := fmt.Sprintf("%s/%s/releases/download/%s/%s", base, repo, tag, name)

	i.Log.Info("开始下载资产", "tag", tag, "platform", goos+"/"+goarch, "asset", name, "url", url)
	b, err := i.get(ctx, url)
	if err != nil {
		i.Log.Error("下载资产失败", "tag", tag, "url", url, "cause", err)
		return nil, fmt.Errorf("下载 %s: %w", name, err)
	}
	got := sha256.Sum256(b)
	if hex.EncodeToString(got[:]) != wantSum {
		i.Log.Error("资产校验不通过", "tag", tag, "asset", name,
			"want", wantSum, "got", hex.EncodeToString(got[:]), "bytes", len(b))
		return nil, fmt.Errorf("sha256 校验不通过（期望 %s，实得 %s）", wantSum, hex.EncodeToString(got[:]))
	}
	i.Log.Info("资产校验通过", "tag", tag, "asset", name, "sha256", wantSum, "bytes", len(b))
	return b, nil
}

n_release_Installer_FetchChecksum.signature:
// FetchChecksum 只下载 checksums.txt 并解出本平台 CLI 资产的期望哈希。
// 保留是为了不动既有调用方；新代码请直接用 FetchChecksumFor。
//
// 参数：
//   - ctx: 上下文
//   - rel: 目标发布（需要它的 Assets 里有 checksums.txt 的 URL）
//   - goos / goarch: 目标机器的平台
//
// 返回：
//   - 该平台资产的 sha256（十六进制小写）
//   - 错误：缺 checksums 资产、下载失败、文件里没有该资产的行
//
// 注意：
//   - **不下资产**。这正是自拉模式的省流量点：协调者只下几百字节的 checksums，
//     20MB 的资产由执行机自己去下（spec §5.5）
//   - 一次 upgrade --now 涉及多台机器时，调用方应当只调一次并缓存——
//     同一个 release 的 checksums.txt 对所有平台是同一份
func (i *Installer) FetchChecksum(ctx context.Context, rel Release, goos, goarch string) (string, error) {
	return i.FetchChecksumFor(ctx, rel, AssetName(rel.Tag, goos, goarch))
}

n_release_Installer_FetchChecksumFor.signature:
// FetchChecksumFor 只下载 checksums.txt，并按调用方给定的资产名解出期望哈希。
//
// 参数：
//   - ctx：上下文，用于取消与超时
//   - rel：目标发布，需要它的 Assets 里有 checksums.txt 的 URL
//   - assetName：要查的完整资产名，由调用方给定；checksums.txt 里 CLI 与薄壳
//     资产并列，按平台推导只能推出其中一种
//
// 返回：
//   - 指定资产的 sha256（十六进制小写）
//   - 错误：缺 checksums 资产、下载失败、文件里没有该资产的行
//
// 注意：不下载资产本身；自拉模式只取几百字节的 checksums，20MB 的资产由
// 执行机自己下载。解析失败的错误会带上要找的资产名，便于定位发布清单问题。
func (i *Installer) FetchChecksumFor(ctx context.Context, rel Release, assetName string) (string, error) {
	ck, ok := rel.Checksums()
	if !ok {
		i.Log.Error("发布没有校验和文件，无法校验完整性", "tag", rel.Tag, "asset", ChecksumsName)
		return "", fmt.Errorf("发布 %s 没有 %s，无法校验完整性", rel.Tag, ChecksumsName)
	}
	i.Log.Info("下载校验和文件", "tag", rel.Tag, "url", ck.URL)
	sums, err := i.get(ctx, ck.URL)
	if err != nil {
		i.Log.Error("下载校验和文件失败", "tag", rel.Tag, "url", ck.URL, "cause", err)
		return "", fmt.Errorf("下载 %s: %w", ChecksumsName, err)
	}
	sum, err := sumFor(string(sums), assetName)
	if err != nil {
		i.Log.Error("校验和文件里没有该资产的行", "tag", rel.Tag,
			"asset", assetName, "cause", err)
		return "", err
	}
	i.Log.Info("取得校验和", "tag", rel.Tag, "asset", assetName, "sha256", sum)
	return sum, nil
}

n_release_Installer_InstallArchive.signature:
// InstallArchive 校验、解包、自检一份已下载的资产，返回可供 Activate 的临时文件路径。
//
// 参数：
//   - tgz: FetchArchive 返回的资产原文
//   - wantSum: 期望的 sha256（十六进制小写），agentd 侧来自 CLI 推来的
//     query 参数，是信任链的第二道校验（传输完整性）
//   - wantTag: 目标版本，自检时拿新二进制 version 首行与它比对
//   - destDir: 临时文件落点，**必须**与目标二进制同目录
//
// 返回：
//   - 临时二进制的完整路径（已 chmod 0755 并通过自检）
//   - 错误：校验不过、解包失败、置位失败、自检不过
//
// 注意：
//   - 任何一步失败都会把临时文件删掉，不留残件
func (i *Installer) InstallArchive(tgz []byte, wantSum, wantTag, destDir string) (string, error) {
	got := sha256.Sum256(tgz)
	if hex.EncodeToString(got[:]) != wantSum {
		i.Log.Error("安装被拒：sha256 校验不通过", "tag", wantTag,
			"want", wantSum, "got", hex.EncodeToString(got[:]))
		return "", fmt.Errorf("sha256 校验不通过（期望 %s，实得 %s）", wantSum, hex.EncodeToString(got[:]))
	}

	i.Log.Info("开始安装资产", "tag", wantTag, "dest_dir", destDir, "bytes", len(tgz))
	tmp := filepath.Join(destDir, TempName(wantTag))

	cleanup := func() {
		if err := os.Remove(tmp); err != nil && !errors.Is(err, os.ErrNotExist) {
			i.Log.Warn("清理临时文件失败", "path", tmp, "cause", err)
		}
	}
	format, err := extractBinary(tgz, tmp)
	if err != nil {
		cleanup()
		i.Log.Error("安装被拒：解包失败", "tag", wantTag, "path", tmp, "cause", err)
		return "", fmt.Errorf("解包 %s: %w", wantTag, err)
	}

	i.Log.Info("归档解包完成", "tag", wantTag, "format", format, "path", tmp)
	if err := os.Chmod(tmp, 0o755); err != nil {
		cleanup()
		i.Log.Error("安装被拒：置可执行位失败", "tag", wantTag, "path", tmp, "cause", err)
		return "", fmt.Errorf("置可执行位 %s: %w", tmp, err)
	}
	if err := i.selfCheck(tmp, wantTag); err != nil {
		cleanup()
		i.Log.Error("安装被拒：自检失败", "tag", wantTag, "path", tmp, "cause", err)
		return "", err
	}
	i.Log.Info("新版本已就绪", "tag", wantTag, "path", tmp)
	return tmp, nil
}

n_release_Installer_get.signature:
// get 取一个 URL 的全部内容，带大小上限，失败时按策略重试。
//
// 重试策略：
//   - 总尝试次数上限 downloadRetryMax（3 次）：首次 + 2 次重试
//   - 退避间隔从 downloadRetryBase（2s）开始指数翻倍：第 2 次尝试前等 2s，
//     第 3 次尝试前等 4s
//
// 可重试的失败：
//   - 传输层错误（Do / 读响应体失败）：超时、连接被拒、连接重置、EOF——
//     这一类大概率是瞬时网络抖动，几秒内能自愈
//   - HTTP 5xx 与 429：服务端过载或暂时不可用，缓一缓再问是合理的
//
// 不可重试的失败：
//   - 4xx（429 除外）：404 表示「这个版本没有这个资产」，是确定性的缺失，
//     重试一百次还是 404，只会把一句清晰的错误拖成更久的沉默；
//     同理，请求构造错误（URL 非法等）也是确定性的，重试没有意义
//
// 所以这里把重试留给「大概率会自愈」的失败，剩下的尽快如实报错——
// 重试不是无脑重复，区分的关键不是次数，而是失败的性质。
func (i *Installer) get(ctx context.Context, url string) ([]byte, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	var lastErr error
	for attempt := 1; attempt <= downloadRetryMax; attempt++ {
		body, err := i.getOnce(ctx, req)
		if err == nil {
			if attempt > 1 {
				i.Log.Info("下载重试成功", "url", url, "attempt", attempt)
			}
			return body, nil
		}
		lastErr = err
		if !isRetryable(err) {

			return nil, err
		}
		if attempt >= downloadRetryMax {
			break
		}
		backoff := downloadRetryBase << uint(attempt-1)
		i.Log.Warn("下载失败，即将重试", "url", url, "attempt", attempt, "backoff", backoff, "cause", err)
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(backoff):
		}
	}
	return nil, fmt.Errorf("尝试 %d 次仍失败: %w", downloadRetryMax, lastErr)
}

n_release_Installer_getOnce.signature:
// getOnce 执行单次请求：Do + 读响应体。非 200 返回带状态码的 httpStatusError。
func (i *Installer) getOnce(ctx context.Context, req *http.Request) ([]byte, error) {
	resp, err := i.HTTP.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, httpStatusError{code: resp.StatusCode}
	}
	return io.ReadAll(io.LimitReader(resp.Body, maxAssetBytes))
}

n_release_Installer_selfCheck.signature:
// selfCheck 跑新二进制的 version 子命令，要求首行等于期望 tag。
//
// 这是 D10 的第一道防线。它挡下的是「sha256 对但二进制跑不起来」——架构拿错、
// 动态库缺失、资产本身构建错。没有它，换版会把一个跑不了的东西 rename 到位，
// 然后 agentd 再也起不来，而且现场只剩一个「进程起不来」的空结论。
func (i *Installer) selfCheck(path, wantTag string) error {
	ctx, cancel := context.WithTimeout(context.Background(), selfCheckTimeout)
	defer cancel()
	out, err := exec.CommandContext(ctx, path, "version").CombinedOutput()
	if err != nil {

		return fmt.Errorf("新二进制自检失败（%s version 执行出错）: %s（%w）", path, firstLine(string(out)), err)
	}
	got := firstLine(string(out))
	if got != wantTag {
		return fmt.Errorf("新二进制自检失败：version 首行为 %q，期望 %q", got, wantTag)
	}
	i.Log.Info("新二进制自检通过", "path", path, "version", got)
	return nil
}

n_release_NewClient.signature:
// NewClient 构造 release 查询 client：30s 超时，打 GitHub 官方端点。
//
// 参数：
//   - tr: HTTP transport；**nil = 用标准库默认**（认 HTTPS_PROXY 等环境变量），
//     与本参数加入前的行为一字不差。要走配置里的代理，传 proxycfg.Transport 的产物
//
// 注意：
//   - 本包不读 handoff 配置（见 package 注释），所以收的是造好的 transport
//     而不是配置字符串——这条边界是刻意的，别"顺手"改成传 *config.Config
//   - 30s 而不是更长：查版本是一个可以失败的后台动作（失败就等下一个 interval），
//     卡住一个 goroutine 几分钟没有任何好处
func NewClient(tr http.RoundTripper) *Client {
	return &Client{
		HTTP:		&http.Client{Timeout: 30 * time.Second, Transport: tr},
		APIBase:	DefaultAPIBase,
		Repo:		DefaultRepo,
	}
}

n_release_NewInstaller.signature:
// NewInstaller 构造默认 installer（10 分钟超时，覆盖慢网下的 20MB 下载）。
//
// 参数：
//   - log: 日志入口
//   - tr: HTTP transport；**nil = 用标准库默认**（认 HTTPS_PROXY 等环境变量）
func NewInstaller(log *slog.Logger, tr http.RoundTripper) *Installer {
	return &Installer{
		HTTP:		&http.Client{Timeout: 10 * time.Minute, Transport: tr},
		Log:		log,
		DownloadBase:	DownloadBase,
	}
}

n_release_Release_AssetFor.signature:
// AssetFor 取本平台的资产。
//
// 返回：
//   - 资产与是否找到。找不到说明这次发布漏了某平台
func (r Release) AssetFor(goos, goarch string) (Asset, bool) {
	want := AssetName(r.Tag, goos, goarch)
	for _, a := range r.Assets {
		if a.Name == want {
			return a, true
		}
	}
	return Asset{}, false
}

n_release_Release_Checksums.signature:
// Checksums 取校验和文件资产。
func (r Release) Checksums() (Asset, bool) {
	for _, a := range r.Assets {
		if a.Name == ChecksumsName {
			return a, true
		}
	}
	return Asset{}, false
}

n_release_Rollback.signature:
// Rollback 把 <target>.prev 换回 target。
//
// 注意：
//   - 这是 D10 的第二道防线，**只由人工命令触发**，自动更新循环永远不调它
func Rollback(target string) error {
	prev := PrevPath(target)
	if _, err := os.Stat(prev); err != nil {
		return fmt.Errorf("没有可回滚的旧二进制（%s 不存在）", prev)
	}
	if err := checkDirWritable(filepath.Dir(target)); err != nil {
		return err
	}
	if err := os.Rename(prev, target); err != nil {
		return fmt.Errorf("回滚 %s: %w", target, err)
	}
	return nil
}

n_release_TempName.signature:
// TempName 返回某版本的临时文件名。
//
// 前导点让它在目录列表里不显眼；带上 tag 使多次尝试不同版本时互不覆盖。
// Windows 上追加 .exe——selfCheck 要 exec 这个临时文件跑 version，
// 没有该后缀的文件在 Windows 上起不来。
func TempName(tag string) string	{ return tempName(tag, runtime.GOOS) }

n_release_archiveExt.signature:
// archiveExt 返回某平台的归档扩展名。
//
// Windows 用 zip 而非 tar.gz：zip 在资源管理器里双击即开，而 tar.gz 必须敲
// 命令行；且 Expand-Archive 存在于每一个 PowerShell，tar.exe 只有 Win10
// 1803+ 才有。手动下载是 Windows 用户的常见路径，这个差异值得多一种格式。
func archiveExt(goos string) string {
	if goos == "windows" {
		return ".zip"
	}
	return ".tar.gz"
}

n_release_checkDirWritable.signature:
// checkDirWritable 试着在目录里建一个临时文件，以此判断可写性。
//
// 为什么不看权限位：权限位判可写要考虑 uid/gid/ACL/只读挂载，判错的方向
// 还不确定。实际写一次是唯一可靠的判据。
func checkDirWritable(dir string) error {
	f, err := os.CreateTemp(dir, ".handoff-wtest-")
	if err != nil {
		return fmt.Errorf("目录 %s 没有写权限，无法替换二进制；把 handoff 装到 ~/.local/bin，或用 sudo 手动升级（原因: %w）", dir, err)
	}
	name := f.Name()
	_ = f.Close()
	_ = os.Remove(name)
	return nil
}

n_release_extractBinary.signature:
// extractBinary 从归档里取出 handoff 可执行文件写到 dest。
//
// 参数：
//   - data: 归档原文（tar.gz 或 zip）
//   - dest: 落点路径
//
// 返回：
//   - format: 实际识别出的格式（"tar.gz" / "zip"），供调用方打进日志
//   - 错误：格式不认、解包失败、包内没有可执行文件
//
// 注意：
//   - 格式**按魔数判定，不按调用方传入的平台**。传平台会制造第二个真相来源，
//     一旦它与实际字节不符，报错会指向错误的方向；字节才是权威。这条选择的
//     额外好处是 InstallArchive / Fetch / FetchArchive 三个签名都不用动
func extractBinary(data []byte, dest string) (string, error) {
	switch {
	case bytes.HasPrefix(data, gzipMagic):
		return "tar.gz", extractFromTarGz(data, dest)
	case bytes.HasPrefix(data, zipMagic):
		return "zip", extractFromZip(data, dest)
	default:
		head := data
		if len(head) > 4 {
			head = head[:4]
		}
		return "", fmt.Errorf("无法识别的归档格式：既不是 gzip 也不是 zip（前 %d 字节 %x）", len(head), head)
	}
}

n_release_extractFromTarGz.signature:
// extractFromTarGz 从 tar.gz 里取出可执行文件写到 dest。
func extractFromTarGz(data []byte, dest string) error {
	gz, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return fmt.Errorf("gzip: %w", err)
	}
	defer gz.Close()
	tr := tar.NewReader(gz)
	for {
		h, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return errors.New("包里没有名为 handoff / handoff.exe 的文件")
		}
		if err != nil {
			return fmt.Errorf("tar: %w", err)
		}
		if !binaryNames[filepath.Base(h.Name)] || h.Typeflag != tar.TypeReg {
			continue
		}
		return writeExtracted(tr, dest)
	}
}

n_release_extractFromZip.signature:
// extractFromZip 从 zip 里取出可执行文件写到 dest。
func extractFromZip(data []byte, dest string) error {
	zr, err := zip.NewReader(bytes.NewReader(data), int64(len(data)))
	if err != nil {
		return fmt.Errorf("zip: %w", err)
	}
	for _, f := range zr.File {
		if f.FileInfo().IsDir() || !binaryNames[filepath.Base(f.Name)] {
			continue
		}
		rc, err := f.Open()
		if err != nil {
			return fmt.Errorf("zip 打开 %s: %w", f.Name, err)
		}
		defer rc.Close()
		return writeExtracted(rc, dest)
	}
	return errors.New("包里没有名为 handoff / handoff.exe 的文件")
}

n_release_firstLine.signature:
// firstLine 取多行文本的第一行，用作错误摘要。
func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return strings.TrimSpace(s[:i])
	}
	return strings.TrimSpace(s)
}

n_release_isRetryable.signature:
// isRetryable 判断一次失败是否值得重试。
//
// 传输层错误（Do / 读响应体失败）视为瞬时故障，一律可重试；
// 状态码错误只重试 429 与 5xx——4xx 是确定性的，重试只是把清晰的错误拖成沉默。
func isRetryable(err error) bool {
	var se httpStatusError
	if errors.As(err, &se) {
		return se.code == http.StatusTooManyRequests || se.code >= 500
	}
	return true
}

n_release_sumFor.signature:
// sumFor 从 checksums.txt 里取某个资产的期望哈希。
//
// 行格式是 sha256sum 的产出：`<hex>  <name>`。GNU sha256sum 在二进制模式下会
// 给文件名加 `*` 前缀，这里一并容忍——生成端换个实现不该让所有机器停止更新。
func sumFor(body, name string) (string, error) {
	for _, line := range strings.Split(body, "\n") {
		f := strings.Fields(line)
		if len(f) != 2 {
			continue
		}
		if strings.TrimPrefix(f[1], "*") == name {
			return f[0], nil
		}
	}
	return "", fmt.Errorf("%s 里没有 %s 的校验和", ChecksumsName, name)
}

n_release_tempName.signature:
// tempName 是 TempName 的可测实现，平台由调用方给定。
//
// 拆出这一层的唯一理由是可测性：判据写死成 runtime.GOOS 时，
// 「Windows 上带 .exe」这条行为在非 Windows 的 CI 上永远测不到。
func tempName(tag, goos string) string {
	name := ".handoff.new-" + tag
	if goos == "windows" {
		name += ".exe"
	}
	return name
}

n_release_writeExtracted.signature:
// writeExtracted 把归档条目的内容写到 dest，带大小上限。
//
// 抽出来是因为两种格式的写盘部分完全一样，而这段恰好是唯一会在磁盘上
// 留下痕迹的地方——只有一处，出问题时也只需要看一处。
func writeExtracted(r io.Reader, dest string) error {
	f, err := os.OpenFile(dest, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o755)
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = io.Copy(f, io.LimitReader(r, maxAssetBytes))
	return err
}

n_scheduling_BindPhysical.signature:
// BindPhysical 把请求覆盖套到已绑定身份上。未指定字段保持载体值；指定但与载体
// 不同则 ErrPhysicalOverride。相同值重述合法。
func BindPhysical(id PhysicalIdentity, overlay PhysicalOverlay) (PhysicalIdentity, error) {
	if overlay.Machine != "" && overlay.Machine != id.Machine {
		return PhysicalIdentity{}, ErrPhysicalOverride
	}
	if overlay.CLI != "" && overlay.CLI != id.CLI {
		return PhysicalIdentity{}, ErrPhysicalOverride
	}
	if overlay.HomeDir != nil && *overlay.HomeDir != id.HomeDir {
		return PhysicalIdentity{}, ErrPhysicalOverride
	}
	return id, nil
}

n_scheduling_CarrierStatus_Label.signature:
// Label 返回状态的用户可见中文名（设置页药丸与 CLI 共用这一份）。
func (s CarrierStatus) Label() string {
	switch s {
	case StatusPending:
		return "未上线"
	case StatusOnline:
		return "已上线"
	case StatusQuota:
		return "限额中"
	case StatusUnreachable:
		return "不可达"
	default:
		return string(s)
	}
}

n_scheduling_CheckDefaultKind.signature:
// CheckDefaultKind 要求默认解析结果必须是载体。默认名命中小队或冲突都不算有效默认。
func CheckDefaultKind(kind ReceiverKind) error {
	if kind != ReceiverCarrier {
		return ErrNoDefault
	}
	return nil
}

n_scheduling_ClassifyRegistered.signature:
// ClassifyRegistered 在已知「该名是否存在于载体表/小队表」后分类。
// 两边都有 → ErrNameConflict；两边都无 → ErrNotFound；只在一边 → 对应 Kind。
func ClassifyRegistered(name string, hasCarrier, hasSquad bool) (ReceiverKind, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return "", fmt.Errorf("%w: 接收者名不能为空", ErrNotFound)
	}
	if hasCarrier && hasSquad {
		return "", fmt.Errorf("%w: %s", ErrNameConflict, name)
	}
	if hasCarrier {
		return ReceiverCarrier, nil
	}
	if hasSquad {
		return ReceiverSquad, nil
	}
	return "", fmt.Errorf("%w: %s", ErrNotFound, name)
}

n_scheduling_CrossKindConflict.signature:
// CrossKindConflict 在写入一侧时，对侧同名已存在则冲突。
func CrossKindConflict(otherExists bool) error {
	if otherExists {
		return ErrNameConflict
	}
	return nil
}

n_scheduling_DecodeDefaultCarrier.signature:
// DecodeDefaultCarrier 解码默认载体 singleton body。空 name 视为没有有效默认。
func DecodeDefaultCarrier(body []byte) (string, error) {
	var rec DefaultCarrierRecord
	if err := json.Unmarshal(body, &rec); err != nil {
		return "", err
	}
	name := strings.TrimSpace(rec.Name)
	if name == "" {
		return "", ErrNoDefault
	}
	return name, nil
}

n_scheduling_DefaultHomeDir.signature:
// DefaultHomeDir 返回隔离 HOME 的用户可见配方：`~/.handoff/home/<载体名>`。
// 名字空（含纯空白）返回空串。B334 起登记弹窗不再预填它；空 HOME = 主 HOME。
func DefaultHomeDir(name string) string {
	name = strings.TrimSpace(name)
	if name == "" {
		return ""
	}
	return IsolatedHomeRoot + "/" + name
}

n_scheduling_EffectiveModel.signature:
// EffectiveModel 是允许的逐任务运行参数：请求非空则用请求，否则用载体模型。
// 它不改变物理身份，也不扩大权限。
func EffectiveModel(carrierModel, requestModel string) string {
	if trimmed := strings.TrimSpace(requestModel); trimmed != "" {
		return trimmed
	}
	return carrierModel
}

n_scheduling_EffectiveReceiverName.signature:
// EffectiveReceiverName 决定本次要用的接收者名。requested 非空则用它；
// 否则用 defaultName；两者都空则 ErrNoDefault。
func EffectiveReceiverName(requested, defaultName string) (name string, viaDefault bool, err error) {
	requested = strings.TrimSpace(requested)
	if requested != "" {
		return requested, false, nil
	}
	defaultName = strings.TrimSpace(defaultName)
	if defaultName == "" {
		return "", true, ErrNoDefault
	}
	return defaultName, true, nil
}

n_scheduling_EncodeDefaultCarrier.signature:
// EncodeDefaultCarrier 编码默认载体 singleton body。空名拒绝。
func EncodeDefaultCarrier(name string) ([]byte, error) {
	name = strings.TrimSpace(name)
	if name == "" {
		return nil, fmt.Errorf("%w: 默认载体名不能为空", ErrNoDefault)
	}
	return json.Marshal(DefaultCarrierRecord{Name: name})
}

n_scheduling_IdentityOf.signature:
// IdentityOf 从载体取出物理身份。空 HOME 表示沿用该机主 HOME，仍是身份的一部分。
func IdentityOf(c Carrier) PhysicalIdentity {
	return PhysicalIdentity{Machine: c.Machine, CLI: c.CLI, HomeDir: c.HomeDir}
}

n_scheduling_IgnitionRequest_orderRank.signature:
// orderRank 返回优先级排名：高=0 中=1 低=2，未知词一律垫底（卡优先级是自由
// 文本，cards.go 默认「中」，这里只认出厂词表）。
func (r IgnitionRequest) orderRank() int {
	switch r.Priority {
	case "高":
		return 0
	case "", "中":
		return 1
	case "低":
		return 2
	default:
		return 3
	}
}

n_scheduling_IsLocalMachine.signature:
// IsLocalMachine 报告 carrier.machine 是否为本机别名。空串、local、本机、
// 以及当前进程 hostname 都算本机；其余名字必须出现在 targets 里才能登记。
func IsLocalMachine(machine string) bool {
	name := strings.TrimSpace(machine)
	if name == "" || name == "local" || name == "本机" {
		return true
	}
	hostname, err := os.Hostname()
	return err == nil && name == hostname
}

n_scheduling_OccupancyCarrierKey.signature:
// OccupancyCarrierKey 是载体物理位计数 id。与 acquire 现状拼接 `carrier/<name>` 同形。
func OccupancyCarrierKey(carrier string) string {
	if carrier == "" {
		return ""
	}
	return "carrier/" + carrier
}

n_scheduling_OccupancyKeys.signature:
// OccupancyKeys 返回一次占用要动的计数 id。载体直派（小队名为空）只有载体键。
func OccupancyKeys(squad, carrier string) (memberKey, carrierKey string) {
	return OccupancyMemberKey(squad, carrier), OccupancyCarrierKey(carrier)
}

n_scheduling_OccupancyMemberKey.signature:
// OccupancyMemberKey 是小队成员政策位计数 id。与 acquire 现状拼接
// `squad/<squad>/<carrier>` 同形。小队或载体名为空时返回空串——空小队不得
// 写出 `squad//<carrier>`（那会把载体直派算成一个不存在的成员键）。
func OccupancyMemberKey(squad, carrier string) string {
	if squad == "" || carrier == "" {
		return ""
	}
	return "squad/" + squad + "/" + carrier
}

n_scheduling_ResolveLookup.signature:
// ResolveLookup 组合空名默认与登记分类。lookup 报告该名在两张表里是否存在。
// viaDefault 且分类失败（不存在/是小队）时统一成 ErrNoDefault；显式名的冲突仍是 ErrNameConflict。
func ResolveLookup(requested, defaultName string, lookup func(string) (hasCarrier, hasSquad bool)) (ResolvedReceiver, error) {
	name, viaDefault, err := EffectiveReceiverName(requested, defaultName)
	if err != nil {
		return ResolvedReceiver{}, err
	}
	hasCarrier, hasSquad := lookup(name)
	kind, err := ClassifyRegistered(name, hasCarrier, hasSquad)
	if err != nil {
		if viaDefault && !errors.Is(err, ErrNameConflict) {
			return ResolvedReceiver{}, fmt.Errorf("%w: %s", ErrNoDefault, name)
		}
		if viaDefault && errors.Is(err, ErrNameConflict) {
			return ResolvedReceiver{}, fmt.Errorf("%w: %s", ErrNameConflict, name)
		}
		return ResolvedReceiver{}, err
	}
	if viaDefault {
		if err := CheckDefaultKind(kind); err != nil {
			return ResolvedReceiver{}, err
		}
	}
	return ResolvedReceiver{Kind: kind, Name: name, ViaDefault: viaDefault}, nil
}

n_scheduling_RunCommand.signature:
// RunCommand 返回「运行」按钮要复制的那条命令。客户端不得再拼接。
// 有隔离 HOME 时为 `HOME=<home_dir> <cli>`；空 HOME 只输出 CLI，沿用该机主 HOME。
func RunCommand(c Carrier) string {
	if strings.TrimSpace(c.HomeDir) == "" {
		return c.CLI
	}
	return "HOME=" + c.HomeDir + " " + c.CLI
}

n_scheduling_Service_AdmitCarrier.signature:
// AdmitCarrier 对一次无小队的载体直派只占载体物理位。
// Binding.Squad 为空；HomeDir 是绑定当时的 IdentityOf 快照。
// 与 Admit 的小队两级准入不同，直派不创建小队成员计数键。
func (s *Service) AdmitCarrier(name string) (Binding, error) {
	name = strings.TrimSpace(name)
	statusLog().Info("scheduling.admit_carrier.start", "carrier", name, "error_kind", "start")
	c, err := s.Carrier(name)
	if err != nil {
		statusLog().Error("scheduling.admit_carrier.error", "carrier", name, "error_kind", "lookup", "cause", err)
		return Binding{}, err
	}
	if c.Status != StatusOnline {
		err := fmt.Errorf("%w: 载体 %s 状态为 %s", ErrNoHealthy, c.Name, c.Status)
		statusLog().Warn("scheduling.admit_carrier.error", "carrier", c.Name, "status", c.Status, "error_kind", "no_healthy", "cause", err)
		return Binding{}, err
	}
	_, carrierKey := OccupancyKeys("", c.Name)
	for attempt := 0; attempt < maxCASAttempts; attempt++ {
		running, expect, err := s.readCount(carrierKey)
		if err != nil {
			statusLog().Error("scheduling.admit_carrier.error", "carrier", c.Name, "carrier_key", carrierKey, "attempt", attempt+1, "error_kind", "counter_read", "cause", err)
			return Binding{}, err
		}
		if c.MaxConcurrency > 0 && running >= c.MaxConcurrency {
			err := fmt.Errorf("%w: 载体 %s", ErrNoSlot, c.Name)
			statusLog().Warn("scheduling.admit_carrier.full", "carrier", c.Name, "carrier_key", carrierKey, "running", running, "carrier_cap", c.MaxConcurrency, "error_kind", "no_slot", "cause", err)
			return Binding{}, err
		}
		if err := s.casCount(carrierKey, expect, running+1); err != nil {
			if errors.Is(err, schedclient.ErrCASConflict) {
				continue
			}
			statusLog().Error("scheduling.admit_carrier.error", "carrier", c.Name, "carrier_key", carrierKey, "attempt", attempt+1, "error_kind", "counter_write", "cause", err)
			return Binding{}, err
		}
		id := IdentityOf(c)
		b := Binding{Squad: "", Carrier: c.Name, Target: id.Machine, Executor: id.CLI, Model: c.Model, HomeDir: id.HomeDir}
		statusLog().Info("scheduling.admit_carrier.success", "carrier", c.Name, "carrier_key", carrierKey, "target", b.Target, "executor", b.Executor, "home_dir", b.HomeDir, "error_kind", "success")
		return b, nil
	}
	err = fmt.Errorf("%w: %s", ErrRetryExhausted, carrierKey)
	statusLog().Error("scheduling.admit_carrier.error", "carrier", c.Name, "carrier_key", carrierKey, "error_kind", "retry_exhausted", "cause", err)
	return Binding{}, err
}

n_scheduling_Service_AdmitFrozen.signature:
// AdmitFrozen 按 Binding.Carrier 对冻结载体执行一次两级 CAS 准入，并核验绑定时
// 的机器、CLI、HOME 与载体登记仍一致。它绝不按 Binding.Squad 重新选择成员；
// Squad 为空时只占载体物理键，不产生成员键。
func (s *Service) AdmitFrozen(binding Binding) (Binding, error) {
	memberKey, carrierKey := OccupancyKeys(binding.Squad, binding.Carrier)
	logger := statusLog().With("squad", binding.Squad, "carrier", binding.Carrier,
		"target", binding.Target, "executor", binding.Executor, "model", binding.Model,
		"home_dir", binding.HomeDir, "member_key", memberKey, "carrier_key", carrierKey)
	logger.Info("冻结载体准入开始", "error_kind", "admit_frozen_start")
	if strings.TrimSpace(binding.Carrier) == "" {
		err := fmt.Errorf("%w: 冻结载体不能为空", ErrInvalid)
		logger.Error("冻结载体准入拒绝", "error_kind", "carrier_missing", "cause", err)
		return Binding{}, err
	}
	carrier, err := s.Carrier(binding.Carrier)
	if err != nil {
		logger.Error("冻结载体读取失败", "error_kind", "carrier_read", "cause", err)
		return Binding{}, err
	}
	if carrier.Status != StatusOnline {
		err := fmt.Errorf("%w: 载体 %s 当前状态为 %s", ErrNoHealthy, binding.Carrier, carrier.Status)
		logger.Warn("冻结载体不在线", "error_kind", "carrier_offline", "cause", err)
		return Binding{}, err
	}

	q := Squad{}
	member := SquadMember{Carrier: binding.Carrier}
	if strings.TrimSpace(binding.Squad) != "" {
		q, err = s.Squad(binding.Squad)
		if err != nil {
			logger.Error("冻结小队读取失败", "error_kind", "squad_read", "cause", err)
			return Binding{}, err
		}
		if q.Role != RoleExecutor {
			err := fmt.Errorf("%w: %s 是协调者小队", ErrRoleMismatch, q.Name)
			logger.Error("冻结载体准入拒绝协调者小队", "error_kind", "role_mismatch", "cause", err)
			return Binding{}, err
		}
		found := false
		for _, candidate := range q.Members {
			if candidate.Carrier == binding.Carrier {
				member = candidate
				found = true
				break
			}
		}
		if !found {
			err := fmt.Errorf("%w: 载体 %s 不在小队 %s", ErrRoleMismatch, binding.Carrier, binding.Squad)
			logger.Warn("冻结载体不是小队成员", "error_kind", "member_mismatch", "cause", err)
			return Binding{}, err
		}
	}
	identity := IdentityOf(carrier)
	if !samePhysicalMachine(binding.Target, identity.Machine) || binding.Executor != identity.CLI || binding.HomeDir != identity.HomeDir {
		err := fmt.Errorf("%w: 冻结物理身份与载体登记不一致", ErrRoleMismatch)
		logger.Warn("冻结物理身份不匹配", "registered_target", identity.Machine,
			"registered_executor", identity.CLI, "registered_home_dir", identity.HomeDir,
			"error_kind", "physical_mismatch", "cause", err)
		return Binding{}, err
	}

	admitted, err := s.acquire(q, member, carrier, IgnitionRequest{
		Squad:	binding.Squad, Model: binding.Model, Actor: "admit_frozen",
	})
	if errors.Is(err, errMemberFull) {
		err = ErrNoSlot
	}
	if err != nil {
		memberKey, carrierKey := OccupancyKeys(binding.Squad, binding.Carrier)
		logger.Error("冻结载体准入失败", "member_key", memberKey, "carrier_key", carrierKey,
			"error_kind", admissionErrorKind(err), "cause", err)
		return Binding{}, err
	}

	admitted.Model = binding.Model
	logger.Info("冻结载体准入成功", "member_key", OccupancyMemberKey(admitted.Squad, admitted.Carrier),
		"carrier_key", OccupancyCarrierKey(admitted.Carrier), "target", admitted.Target,
		"executor", admitted.Executor, "model", admitted.Model, "home_dir", admitted.HomeDir,
		"error_kind", "admit_frozen_success")
	return admitted, nil
}

n_scheduling_Service_ApplyDetect.signature:
// ApplyDetect 按「不可达优先、限额次之、需登录再次之、否则上线」的四态表把
// 一次检测结果写进载体。它读取 registry 当前版本并以一次 CAS 写回；CAS、读取
// 或解码失败都保留旧状态并返回带载体名上下文的错误。online 清空 LastError，
// 其他状态原样保存 detail（包括空 detail）。
func (s *Service) ApplyDetect(name string, ev DetectEvidence, detail string) (Carrier, error) {
	statusLog().Info("开始写入载体检测", "name", name, "reachable", ev.Reachable,
		"need_login", ev.NeedLogin, "quota", ev.Quota, "detail_bytes", len(detail))
	rec, err := s.repo.Get(kindCarrier, name)
	if err != nil {
		statusLog().Error("读取载体检测目标失败", "name", name, "cause", err)
		if errors.Is(err, schedclient.ErrNotFound) {
			return Carrier{}, fmt.Errorf("载体 %s 不存在: %w", name, ErrNotFound)
		}
		return Carrier{}, fmt.Errorf("载体 %s 读取失败: %w", name, err)
	}
	var carrier Carrier
	if err := json.Unmarshal(rec.Body, &carrier); err != nil {
		statusLog().Error("解码载体检测目标失败", "name", name, "version", rec.Version, "cause", err)
		return Carrier{}, fmt.Errorf("载体 %s/%d 解码失败: %w", name, rec.Version, err)
	}
	previous := carrier.Status
	switch {
	case !ev.Reachable:
		if previous == StatusOnline || previous == StatusQuota || previous == StatusUnreachable {
			carrier.Status = StatusUnreachable
		} else {
			carrier.Status = StatusPending
		}
	case ev.Quota:
		carrier.Status = StatusQuota
	case ev.NeedLogin:
		carrier.Status = StatusPending
	default:
		carrier.Status = StatusOnline
	}
	if carrier.Status == StatusOnline {
		carrier.LastError = ""
	} else {
		carrier.LastError = detail
	}
	body, err := json.Marshal(carrier)
	if err != nil {
		statusLog().Error("编码载体检测结果失败", "name", name, "version", rec.Version, "cause", err)
		return Carrier{}, fmt.Errorf("载体 %s 检测结果编码失败: %w", name, err)
	}
	version, err := s.repo.Put(kindCarrier, name, rec.Version, body, "scheduling.detect")
	if err != nil {
		statusLog().Error("写入载体检测结果失败", "name", name, "version", rec.Version,
			"next_status", carrier.Status, "cause", err)
		return Carrier{}, fmt.Errorf("载体 %s 检测写入冲突: %w", name, err)
	}
	statusLog().Info("写入载体检测结果成功", "name", name, "version", version,
		"previous_status", previous, "status", carrier.Status)
	return carrier, nil
}

n_scheduling_Service_Carrier.signature:
// Carrier 读一个载体。
func (s *Service) Carrier(name string) (Carrier, error) {
	var c Carrier
	if err := s.getEntity(kindCarrier, name, &c); err != nil {
		return Carrier{}, err
	}
	return c, nil
}

n_scheduling_Service_CarrierRows.signature:
// CarrierRows 列出全部载体（repo.List 写入序稳定），每行带 registry 版本。
func (s *Service) CarrierRows() ([]CarrierRow, error) {
	recs, err := s.repo.List(kindCarrier)
	if err != nil {
		return nil, err
	}
	out := make([]CarrierRow, 0, len(recs))
	for _, rec := range recs {
		var c Carrier
		if err := json.Unmarshal(rec.Body, &c); err != nil {
			return nil, fmt.Errorf("carrier/%s 解码失败: %w", rec.ID, err)
		}
		out = append(out, CarrierRow{Version: rec.Version, Carrier: c})
	}
	return out, nil
}

n_scheduling_Service_Carriers.signature:
// Carriers 列出全部载体（写入序稳定）。
func (s *Service) Carriers() ([]Carrier, error) {
	var out []Carrier
	return out, s.listEntities(kindCarrier, func(raw []byte) error {
		var c Carrier
		if err := json.Unmarshal(raw, &c); err != nil {
			return err
		}
		out = append(out, c)
		return nil
	})
}

n_scheduling_Service_DefaultCarrier.signature:
// DefaultCarrier 读取已确认的默认载体名。没有记录或记录指向未登记载体时返回 ErrNoDefault。
func (s *Service) DefaultCarrier() (string, error) {
	statusLog().Info("scheduling.default_carrier.read.start", "kind", KindDefaultCarrier, "id", DefaultCarrierID)
	rec, err := s.repo.Get(KindDefaultCarrier, DefaultCarrierID)
	if err != nil {
		if errors.Is(err, schedclient.ErrNotFound) {
			err = ErrNoDefault
		}
		statusLog().Error("scheduling.default_carrier.read.error", "kind", KindDefaultCarrier, "id", DefaultCarrierID, "error_kind", "registry", "cause", err)
		return "", err
	}
	name, err := DecodeDefaultCarrier(rec.Body)
	if err != nil {
		statusLog().Error("scheduling.default_carrier.decode.error", "kind", KindDefaultCarrier, "id", DefaultCarrierID, "error_kind", "decode", "cause", err)
		return "", err
	}
	if _, err := s.Carrier(name); err != nil {
		if errors.Is(err, ErrNotFound) {
			err = fmt.Errorf("%w: 默认载体 %s 未登记", ErrNoDefault, name)
		}
		statusLog().Error("scheduling.default_carrier.read.error", "name", name, "error_kind", "carrier_lookup", "cause", err)
		return "", err
	}
	statusLog().Info("scheduling.default_carrier.read.success", "name", name, "kind", KindDefaultCarrier, "id", DefaultCarrierID, "error_kind", "success")
	return name, nil
}

n_scheduling_Service_DeleteCarrier.signature:
// DeleteCarrier 以 CAS 语义删除未入队载体。
// 若载体名为空或仍在任一小队成员中，拒绝删除返回 ErrInvalid；
// 若载体不存在返回 ErrNotFound；若版本不匹配返回 ErrCASConflict。
func (s *Service) DeleteCarrier(name string, expect int) error {
	statusLog().Info("删除载体请求", "name", name, "expect", expect)
	if strings.TrimSpace(name) == "" {
		statusLog().Warn("删除载体校验失败", "name", name, "expect", expect, "cause", "name 必填")
		return fmt.Errorf("%w: 载体名不能为空", ErrInvalid)
	}

	squadRecs, err := s.repo.List(kindSquad)
	if err != nil {
		statusLog().Error("读取小队列表失败", "name", name, "expect", expect, "cause", err)
		return fmt.Errorf("读取小队列表失败: %w", err)
	}
	for _, rec := range squadRecs {
		var q Squad
		if err := json.Unmarshal(rec.Body, &q); err != nil {
			statusLog().Error("解码小队记录失败", "id", rec.ID, "cause", err)
			return fmt.Errorf("squad/%s 解码失败: %w", rec.ID, err)
		}
		for _, m := range q.Members {
			if m.Carrier == name {
				statusLog().Warn("删除载体被拒：仍在小队中", "name", name, "expect", expect, "squad", q.Name)
				return fmt.Errorf("%w: 载体 %s 仍在小队 %s 中，请先从小队移除", ErrInvalid, name, q.Name)
			}
		}
	}

	if _, err := s.repo.Get(kindCarrier, name); err != nil {
		if errors.Is(err, schedclient.ErrNotFound) {
			statusLog().Warn("删除载体未找到", "name", name, "expect", expect)
			return fmt.Errorf("载体 %s 旧记录不存在: %w", name, ErrNotFound)
		}
		statusLog().Error("读取载体记录失败", "name", name, "expect", expect, "cause", err)
		return fmt.Errorf("读取载体 %s 失败: %w", name, err)
	}

	if err := s.repo.Delete(kindCarrier, name, expect, "scheduling"); err != nil {
		statusLog().Error("删除载体失败", "name", name, "expect", expect, "cause", err)
		return err
	}
	statusLog().Info("删除载体成功", "name", name, "expect", expect)
	return nil
}

n_scheduling_Service_Enqueue.signature:
// Enqueue 把一次满员的点火请求持久入队。同一（卡，节点）重复排队按更新处理
// 并保留原入队序（body.Seq 不变），位置按当前队序重算返回。
func (s *Service) Enqueue(req IgnitionRequest, kind string) (position int, err error) {
	if kind != KindIgnitionQueue && kind != KindLaunchQueue {
		return 0, fmt.Errorf("未知的排队种类 %q", kind)
	}
	id := queueID(req)
	existing, getErr := s.repo.Get(kind, id)
	seq := int64(0)
	expect := 0
	switch {
	case getErr == nil:
		var old queuedEntry
		if json.Unmarshal(existing.Body, &old) == nil {
			seq = old.Seq
		}
		expect = existing.Version
	case errors.Is(getErr, schedclient.ErrCASConflict), errors.Is(getErr, schedclient.ErrNotFound):

	default:
		return 0, getErr
	}
	body, err := json.Marshal(queuedEntry{Req: req, Seq: seq})
	if err != nil {
		return 0, err
	}
	if _, err := s.repo.Put(kind, id, expect, body, req.Actor); err != nil {
		return 0, err
	}
	return s.position(kind, id), nil
}

n_scheduling_Service_PopReady.signature:
// PopReady 取走队列头部的下一个请求（就绪度 → 卡优先级 → FIFO）。
// 队列为空返回 (zero, false, nil)。取走即删除（CAS 版本防并发双取）。
func (s *Service) PopReady(kind string) (IgnitionRequest, bool, error) {
	var zero IgnitionRequest
	entries, err := s.repo.List(kind)
	if err != nil {
		return zero, false, err
	}
	type ranked struct {
		rec	schedclient.Record
		req	IgnitionRequest
		seq	int64
		rank	int
	}
	items := make([]ranked, 0, len(entries))
	for _, rec := range entries {
		var e queuedEntry
		if err := json.Unmarshal(rec.Body, &e); err != nil {
			return zero, false, fmt.Errorf("queue %s/%s 解码失败: %w", kind, rec.ID, err)
		}
		items = append(items, ranked{rec: rec, req: e.Req, seq: e.Seq, rank: e.Req.orderRank()})
	}
	if len(items) == 0 {
		return zero, false, nil
	}
	sort.SliceStable(items, func(i, j int) bool {
		if items[i].req.Ready != items[j].req.Ready {
			return items[i].req.Ready
		}
		if items[i].rank != items[j].rank {
			return items[i].rank < items[j].rank
		}
		if items[i].seq != items[j].seq {
			return items[i].seq < items[j].seq
		}
		return items[i].rec.Seq < items[j].rec.Seq
	})
	head := items[0]
	if err := s.repo.Delete(kind, head.rec.ID, head.rec.Version, head.req.Actor); err != nil {
		return zero, false, err
	}
	return head.req, true, nil
}

n_scheduling_Service_PutCarrier.signature:
// PutCarrier 以 CAS 写载体定义（expect=0 新建）。新建时忽略输入状态并落
// pending；更新时 HOME 变化会清掉旧错误并回到 pending，HOME 未变则保留旧
// 状态。这避免登记请求伪造上线，也避免编辑无关字段抹掉检测结果。
func (s *Service) PutCarrier(c Carrier, expect int) error {
	if strings.TrimSpace(c.Name) == "" || strings.TrimSpace(c.Machine) == "" || strings.TrimSpace(c.CLI) == "" {
		statusLog().Error("载体登记校验失败", "name", c.Name, "expect", expect, "cause", "name/machine/cli 必填")
		return fmt.Errorf("%w: 载体登记不完整：name/machine/cli 必填", ErrInvalid)
	}
	if strings.TrimSpace(string(c.Credential)) == "" {
		c.Credential = CredentialStandalone
	}
	if c.Credential != CredentialStandalone && c.Credential != CredentialMainHomeSync {
		statusLog().Error("载体登记校验失败", "name", c.Name, "expect", expect, "cause", "credential 来源非法")
		return fmt.Errorf("%w: 载体 %s 的凭据来源只能是 standalone 或 main_home_sync", ErrInvalid, c.Name)
	}
	if err := s.checkKnownMachine(c.Name, c.Machine, expect); err != nil {
		return err
	}
	if _, squadErr := s.Squad(c.Name); squadErr == nil {
		if err := CrossKindConflict(true); err != nil {
			statusLog().Error("载体登记跨 kind 冲突", "name", c.Name, "expect", expect, "cause", err)
			return fmt.Errorf("%w: %s", err, c.Name)
		}
	} else if !errors.Is(squadErr, ErrNotFound) {
		statusLog().Error("检查载体同名小队失败", "name", c.Name, "expect", expect, "cause", squadErr)
		return squadErr
	}
	homeChanged := false
	if expect == 0 {
		c.Status = StatusPending
		c.LastError = ""
	} else {
		rec, err := s.repo.Get(kindCarrier, c.Name)
		if err != nil {
			statusLog().Error("读取载体旧记录失败", "name", c.Name, "expect", expect, "cause", err)
			if errors.Is(err, schedclient.ErrNotFound) {
				return fmt.Errorf("载体 %s 旧记录不存在: %w", c.Name, ErrNotFound)
			}
			return fmt.Errorf("载体 %s 读取旧记录失败: %w", c.Name, err)
		}
		var previous Carrier
		if err := json.Unmarshal(rec.Body, &previous); err != nil {
			statusLog().Error("解码载体旧记录失败", "name", c.Name, "expect", expect, "version", rec.Version, "cause", err)
			return fmt.Errorf("载体 %s/%d 解码失败: %w", c.Name, rec.Version, err)
		}
		homeChanged = previous.HomeDir != c.HomeDir
		if homeChanged {
			c.Status = StatusPending
			c.LastError = ""
		} else {

			c.Status = previous.Status
			c.LastError = previous.LastError
		}
	}
	statusLog().Info("写入载体", "name", c.Name, "expect", expect, "home_changed", homeChanged,
		"status", c.Status, "last_error_bytes", len(c.LastError))
	body, err := json.Marshal(c)
	if err != nil {
		statusLog().Error("编码载体失败", "name", c.Name, "expect", expect, "cause", err)
		return err
	}
	version, err := s.repo.Put(kindCarrier, c.Name, expect, body, "scheduling")
	if err != nil {
		statusLog().Error("写入载体失败", "name", c.Name, "expect", expect, "version", version, "cause", err)
		return err
	}
	statusLog().Info("写入载体成功", "name", c.Name, "expect", expect, "version", version,
		"home_changed", homeChanged, "status", c.Status, "machine", c.Machine,
		"credential", string(c.Credential), "home_empty", strings.TrimSpace(c.HomeDir) == "")
	return nil
}

n_scheduling_Service_PutSquad.signature:
// PutSquad 以 CAS 写小队定义（expect=0 新建）。成员引用必须指向已存在的载体。
func (s *Service) PutSquad(q Squad, expect int) error {
	if strings.TrimSpace(q.Name) == "" {
		return fmt.Errorf("%w: 小队名不能为空", ErrInvalid)
	}
	if q.Role != RoleExecutor && q.Role != RoleCoordinator {
		return fmt.Errorf("%w: 小队 %s 角色只能是 executor 或 coordinator", ErrInvalid, q.Name)
	}
	if _, carrierErr := s.Carrier(q.Name); carrierErr == nil {
		if err := CrossKindConflict(true); err != nil {
			statusLog().Error("小队登记跨 kind 冲突", "name", q.Name, "expect", expect, "cause", err)
			return fmt.Errorf("%w: %s", err, q.Name)
		}
	} else if !errors.Is(carrierErr, ErrNotFound) {
		statusLog().Error("检查小队同名载体失败", "name", q.Name, "expect", expect, "cause", carrierErr)
		return carrierErr
	}
	for _, m := range q.Members {
		if _, err := s.Carrier(m.Carrier); err != nil {
			return fmt.Errorf("小队 %s 成员 %s: %w", q.Name, m.Carrier, err)
		}
	}
	return s.putEntity(kindSquad, q.Name, q, expect)
}

n_scheduling_Service_QueueSnapshot.signature:
// QueueSnapshot 按 QueueKinds 的清队顺序返回两个队列的全部排队请求与全局位次。
// Position 从 1 起连续计数：launch_queue 整队在前（QueueKinds 是法定清队顺序），
// 队内位次 = position() 原样取用。只读不出队——PopReady 才删除头部。
func (s *Service) QueueSnapshot() ([]QueuedRequest, error) {
	out := make([]QueuedRequest, 0)
	offset := 0
	for _, kind := range QueueKinds {
		recs, err := s.repo.List(kind)
		if err != nil {
			return nil, err
		}
		type snapRow struct {
			id	string
			req	IgnitionRequest
			seq	int64
			pos	int
		}
		rows := make([]snapRow, 0, len(recs))
		for _, rec := range recs {
			var e queuedEntry
			if err := json.Unmarshal(rec.Body, &e); err != nil {
				continue
			}
			rows = append(rows, snapRow{id: rec.ID, req: e.Req, seq: e.Seq})
		}
		for i := range rows {
			rows[i].pos = s.position(kind, rows[i].id)
		}
		sort.SliceStable(rows, func(i, j int) bool { return rows[i].pos < rows[j].pos })
		for _, r := range rows {
			out = append(out, QueuedRequest{Kind: kind, ID: r.id,
				Req:	r.req, Seq: r.seq, Position: offset + r.pos})
		}
		offset += len(rows)
	}
	return out, nil
}

n_scheduling_Service_Release.signature:
// Release 归还一个已结束回合占用的两级名额。幂等：计数到 0 后不再下探。
// 空小队是载体直派，必须跳过成员键，避免释放一个从未存在的 squad//carrier 计数。
func (s *Service) Release(squadName, carrierName string) error {
	capacity := s.capacityContext(squadName, carrierName)
	slog.Default().Info("scheduling.release.start", "squad", squadName, "carrier", carrierName,
		"member_policy", capacity.memberPolicy, "carrier_cap", capacity.carrierCap,
		"error_kind", "start")
	memberKey, carrierKey := OccupancyKeys(squadName, carrierName)
	if memberKey != "" {
		if err := s.stepRunning(memberKey, -1); err != nil {
			slog.Default().Error("scheduling.release.error", "squad", squadName,
				"carrier", carrierName, "member_policy", capacity.memberPolicy,
				"carrier_cap", capacity.carrierCap, "error_kind", "squad_counter", "cause", err)
			return err
		}
	}
	if carrierKey != "" {
		if err := s.stepRunning(carrierKey, -1); err != nil {
			slog.Default().Error("scheduling.release.error", "squad", squadName,
				"carrier", carrierName, "member_policy", capacity.memberPolicy,
				"carrier_cap", capacity.carrierCap, "error_kind", "carrier_counter", "cause", err)
			return err
		}
	}
	slog.Default().Info("scheduling.release.success", "squad", squadName, "carrier", carrierName,
		"member_policy", capacity.memberPolicy, "carrier_cap", capacity.carrierCap,
		"member_key", memberKey, "carrier_key", carrierKey, "error_kind", "success")
	return nil
}

n_scheduling_Service_Select.signature:
// Select 从 req.Squad 按登记顺序选择一个在线且两级计数均有空位的载体，并返回
// 当时的物理身份快照。它只读 Registry，不为后续执行预占任何运行计数；调用方
// 必须把返回的 Binding 原样交给执行侧 AdmitFrozen，容量竞态由后者的 CAS 裁决。
func (s *Service) Select(req IgnitionRequest) (Binding, error) {
	logger := statusLog().With("squad", req.Squad, "card", req.Card, "node", req.Node,
		"target", req.Target, "executor", req.Executor, "model", req.Model)
	logger.Info("冻结身份选择开始", "error_kind", "select_start")
	if strings.TrimSpace(req.Squad) == "" {
		err := fmt.Errorf("%w: 选择小队不能为空", ErrInvalid)
		logger.Error("冻结身份选择拒绝", "error_kind", "squad_missing", "cause", err)
		return Binding{}, err
	}
	q, err := s.Squad(req.Squad)
	if err != nil {
		logger.Error("冻结身份选择读取小队失败", "error_kind", "squad_read", "cause", err)
		return Binding{}, err
	}
	if q.Role != RoleExecutor {
		err := fmt.Errorf("%w: %s 是协调者小队", ErrRoleMismatch, q.Name)
		logger.Error("冻结身份选择拒绝协调者小队", "error_kind", "role_mismatch", "cause", err)
		return Binding{}, err
	}

	anyOnline := false
	for _, member := range q.Members {
		carrier, carrierErr := s.Carrier(member.Carrier)
		if carrierErr != nil {
			if errors.Is(carrierErr, ErrNotFound) {
				logger.Warn("冻结身份选择跳过未登记载体", "carrier", member.Carrier,
					"member_key", OccupancyMemberKey(q.Name, member.Carrier),
					"carrier_key", OccupancyCarrierKey(member.Carrier), "error_kind", "carrier_missing")
				continue
			}
			logger.Error("冻结身份选择读取载体失败", "carrier", member.Carrier,
				"member_key", OccupancyMemberKey(q.Name, member.Carrier),
				"carrier_key", OccupancyCarrierKey(member.Carrier), "error_kind", "carrier_read", "cause", carrierErr)
			return Binding{}, carrierErr
		}
		if carrier.Status != StatusOnline {
			logger.Info("冻结身份选择跳过离线载体", "carrier", carrier.Name,
				"member_key", OccupancyMemberKey(q.Name, carrier.Name),
				"carrier_key", OccupancyCarrierKey(carrier.Name), "status", carrier.Status,
				"error_kind", "carrier_offline")
			continue
		}
		anyOnline = true
		memberKey, carrierKey := OccupancyKeys(q.Name, carrier.Name)
		memberRunning, _, memberErr := s.readCount(memberKey)
		if memberErr != nil {
			logger.Error("冻结身份选择读取成员计数失败", "carrier", carrier.Name,
				"member_key", memberKey, "carrier_key", carrierKey,
				"error_kind", "member_counter_read", "cause", memberErr)
			return Binding{}, memberErr
		}
		carrierRunning, _, carrierCountErr := s.readCount(carrierKey)
		if carrierCountErr != nil {
			logger.Error("冻结身份选择读取载体计数失败", "carrier", carrier.Name,
				"member_key", memberKey, "carrier_key", carrierKey,
				"error_kind", "carrier_counter_read", "cause", carrierCountErr)
			return Binding{}, carrierCountErr
		}
		if member.MaxConcurrency > 0 && memberRunning >= member.MaxConcurrency {
			logger.Info("冻结身份选择跳过成员满员载体", "carrier", carrier.Name,
				"member_key", memberKey, "carrier_key", carrierKey,
				"running", memberRunning, "member_cap", member.MaxConcurrency,
				"error_kind", "member_full")
			continue
		}
		if carrier.MaxConcurrency > 0 && carrierRunning >= carrier.MaxConcurrency {
			logger.Info("冻结身份选择跳过载体满员载体", "carrier", carrier.Name,
				"member_key", memberKey, "carrier_key", carrierKey,
				"running", carrierRunning, "carrier_cap", carrier.MaxConcurrency,
				"error_kind", "carrier_full")
			continue
		}
		binding := bindingFor(q, carrier, req)
		logger.Info("冻结身份选择成功", "carrier", binding.Carrier,
			"member_key", memberKey, "carrier_key", carrierKey,
			"target", binding.Target, "executor", binding.Executor, "model", binding.Model,
			"home_dir", binding.HomeDir, "error_kind", "select_success")
		return binding, nil
	}
	if !anyOnline {
		err := fmt.Errorf("%w: 小队 %s 没有在线载体", ErrNoHealthy, q.Name)
		logger.Warn("冻结身份选择无在线载体", "error_kind", "no_healthy", "cause", err)
		return Binding{}, err
	}
	err = fmt.Errorf("%w: 小队 %s 所有在线载体均无空位", ErrNoSlot, q.Name)
	logger.Info("冻结身份选择无空位", "error_kind", "no_slot", "cause", err)
	return Binding{}, err
}

n_scheduling_Service_SetDefaultCarrier.signature:
// SetDefaultCarrier 写入默认载体 singleton；kind 为 default_carrier、id 为 current。
// 空名由 EncodeDefaultCarrier 拒绝，非载体名不写入记录。
func (s *Service) SetDefaultCarrier(name string) error {
	name = strings.TrimSpace(name)
	body, err := EncodeDefaultCarrier(name)
	if err != nil {
		statusLog().Error("scheduling.default_carrier.write.error", "name", name, "error_kind", "invalid_name", "cause", err)
		return err
	}
	if _, err := s.Carrier(name); err != nil {
		if errors.Is(err, ErrNotFound) {
			err = fmt.Errorf("%w: 默认载体 %s 未登记为载体", ErrNoDefault, name)
		}
		statusLog().Error("scheduling.default_carrier.write.error", "name", name, "error_kind", "carrier_lookup", "cause", err)
		return err
	}
	expect := 0
	if rec, getErr := s.repo.Get(KindDefaultCarrier, DefaultCarrierID); getErr == nil {
		expect = rec.Version
	} else if !errors.Is(getErr, schedclient.ErrNotFound) {
		statusLog().Error("读取默认载体版本失败", "name", name, "expect", expect, "cause", getErr)
		return getErr
	}
	version, err := s.repo.Put(KindDefaultCarrier, DefaultCarrierID, expect, body, "scheduling")
	if err != nil {
		statusLog().Error("写入默认载体失败", "name", name, "expect", expect, "version", version, "cause", err)
		return err
	}
	statusLog().Info("写入默认载体成功", "name", name, "expect", expect, "version", version, "kind", KindDefaultCarrier, "id", DefaultCarrierID, "error_kind", "success")
	return nil
}

n_scheduling_Service_SetKnownMachines.signature:
// SetKnownMachines 注入「这台机器现在能不能派到」的查询。生产绑
// conf().Targets 的键；本机别名不走这张表。fn 为 nil 时只放行本机别名之外的
// 任意名——单测不持 agentd 配置时用，生产组装点必须注入。
func (s *Service) SetKnownMachines(fn func(string) bool)	{ s.knownMachines = fn }

n_scheduling_Service_Squad.signature:
// Squad 读一个小队。
func (s *Service) Squad(name string) (Squad, error) {
	var q Squad
	if err := s.getEntity(kindSquad, name, &q); err != nil {
		return Squad{}, err
	}
	return q, nil
}

n_scheduling_Service_SquadRows.signature:
// SquadRows 列出全部小队（repo.List 写入序稳定），每行带 registry 版本。
func (s *Service) SquadRows() ([]SquadRow, error) {
	recs, err := s.repo.List(kindSquad)
	if err != nil {
		return nil, err
	}
	out := make([]SquadRow, 0, len(recs))
	for _, rec := range recs {
		var q Squad
		if err := json.Unmarshal(rec.Body, &q); err != nil {
			return nil, fmt.Errorf("squad/%s 解码失败: %w", rec.ID, err)
		}
		out = append(out, SquadRow{Version: rec.Version, Squad: q})
	}
	return out, nil
}

n_scheduling_Service_acquire.signature:
// acquire 对「小队 q + 成员 m + 载体 c」做一次原子准入尝试（B156.3 契约岔口三·方案A）：
// 每次先读两级计数并各自对上限复核，任一级满员返回 errMemberFull，再以 CAS
// 递增；冲突则带着新读数重试。两级上界判断只此一份——它是防超发的唯一执法
// 闸，去掉它并发准入必超发（变异复验的靶子）。
//
// 计数键仍只有 squad/<队>/<载体> 与 carrier/<载体> 两类，按（角色,名字）二元组计数不按卡
// （B292 修订契约 §3），不得引入第三类。MaxConcurrency<=0 视为不设上限：两个
// 上界分支恒不走时，本函数等价于无上界的 CAS 直增。
//
// 半程回滚：小队侧 +1 成功而载体侧失败时，用带符号减法回滚小队侧而不是按版本
// 回写——期间可能有第三方又动了小队计数，按版本回写会把别人的增量踩掉。回滚
// 失败只吞掉：计数偏高是保守方向（多拒不超发），偏低才会超发。
func (s *Service) acquire(q Squad, member SquadMember, c Carrier, req IgnitionRequest) (Binding, error) {
	squadKey, carrierKey := OccupancyKeys(q.Name, member.Carrier)
	for attempt := 0; attempt < maxCASAttempts; attempt++ {
		squadRunning, squadExpect := 0, 0
		if squadKey != "" {
			var err error
			squadRunning, squadExpect, err = s.readCount(squadKey)
			if err != nil {
				slog.Default().Error("scheduling.acquire.error", "squad", q.Name,
					"carrier", c.Name, "member_policy", member.MaxConcurrency,
					"carrier_cap", c.MaxConcurrency, "member_key", squadKey,
					"error_kind", "member_counter_read", "cause", err)
				return Binding{}, err
			}
		}
		carrierRunning, carrierExpect, err := s.readCount(carrierKey)
		if err != nil {
			slog.Default().Error("scheduling.acquire.error", "squad", q.Name,
				"carrier", c.Name, "member_policy", member.MaxConcurrency,
				"carrier_cap", c.MaxConcurrency, "error_kind", "carrier_counter_read", "cause", err)
			return Binding{}, err
		}
		if squadKey != "" && member.MaxConcurrency > 0 && squadRunning >= member.MaxConcurrency {
			slog.Default().Warn("scheduling.acquire.member_full", "squad", q.Name,
				"carrier", c.Name, "member_policy", member.MaxConcurrency,
				"carrier_cap", c.MaxConcurrency, "error_kind", "member_full")
			return Binding{}, errMemberFull
		}
		if c.MaxConcurrency > 0 && carrierRunning >= c.MaxConcurrency {
			slog.Default().Warn("scheduling.acquire.carrier_full", "squad", q.Name,
				"carrier", c.Name, "member_policy", member.MaxConcurrency,
				"carrier_cap", c.MaxConcurrency, "error_kind", "carrier_full")
			return Binding{}, errMemberFull
		}
		if squadKey != "" {
			if err := s.casCount(squadKey, squadExpect, squadRunning+1); err != nil {
				if errors.Is(err, schedclient.ErrCASConflict) {
					continue
				}
				slog.Default().Error("scheduling.acquire.error", "squad", q.Name,
					"carrier", c.Name, "member_policy", member.MaxConcurrency,
					"carrier_cap", c.MaxConcurrency, "member_key", squadKey,
					"error_kind", "member_counter_write", "cause", err)
				return Binding{}, err
			}
		}
		if err := s.casCount(carrierKey, carrierExpect, carrierRunning+1); err != nil {
			if squadKey != "" {
				if rollbackErr := s.stepRunning(squadKey, -1); rollbackErr != nil {
					slog.Default().Error("scheduling.acquire.rollback_error", "squad", q.Name,
						"carrier", c.Name, "member_key", squadKey, "carrier_key", carrierKey,
						"error_kind", "member_rollback", "cause", rollbackErr)
				}
			}
			if errors.Is(err, schedclient.ErrCASConflict) {
				continue
			}
			slog.Default().Error("scheduling.acquire.error", "squad", q.Name,
				"carrier", c.Name, "member_policy", member.MaxConcurrency,
				"carrier_cap", c.MaxConcurrency, "error_kind", "carrier_counter_write", "cause", err)
			return Binding{}, err
		}
		binding := bindingFor(q, c, req)
		slog.Default().Info("scheduling.acquire.success", "squad", q.Name,
			"carrier", c.Name, "member_policy", member.MaxConcurrency,
			"carrier_cap", c.MaxConcurrency, "target", binding.Target,
			"executor", binding.Executor, "model", binding.Model)
		return binding, nil
	}
	err := fmt.Errorf("%w: %s 与 %s", ErrRetryExhausted, squadKey, carrierKey)
	slog.Default().Error("scheduling.acquire.error", "squad", q.Name,
		"carrier", c.Name, "member_policy", member.MaxConcurrency,
		"carrier_cap", c.MaxConcurrency, "error_kind", "retry_exhausted", "cause", err)
	return Binding{}, err
}

n_scheduling_Service_admitInto.signature:
// admitInto 按成员声明顺序对每个健康载体尝试原子准入：某成员满员不终局，
// 换下一个继续；健康成员全部满员才 ErrNoSlot，一个健康成员都没有才
// ErrNoHealthy（两种失败处置不同：前者是常态排队，后者是配置或限额问题）。
//
// 为什么按成员循环而不是「先挑一个成员、再对它 +1」：两步之间隔着若干次共享
// 读，高争用下准入者拿着过时的成员选择撞上终局 ErrNoSlot——另一成员明明有位
// 也报满员，违反冻结准入判据「小队有位 且 载体有位」（本卡台账实测：字面实现
// N=16 打容量 4 只进 2~3 个）。权威裁决只在计数 CAS 里做，成员选择随之在同一
// 趟里完成。
func (s *Service) admitInto(q Squad, req IgnitionRequest) (Binding, error) {
	anyOnline := false
	for _, member := range q.Members {
		carrier, err := s.Carrier(member.Carrier)
		if err != nil {
			if errors.Is(err, ErrNotFound) {
				continue
			}
			statusLog().Error("读取准入载体失败", "squad", q.Name, "carrier", member.Carrier, "cause", err)
			return Binding{}, err
		}
		if carrier.Status != StatusOnline {
			continue
		}
		anyOnline = true
		binding, err := s.acquire(q, member, carrier, req)
		switch {
		case err == nil:
			return binding, nil
		case errors.Is(err, errMemberFull):
			continue
		default:
			statusLog().Error("准入载体失败", "squad", q.Name, "carrier", member.Carrier, "cause", err)
			return Binding{}, err
		}
	}
	if !anyOnline {
		statusLog().Warn("准入无已上线载体", "squad", q.Name, "members", len(q.Members))
		return Binding{}, ErrNoHealthy
	}
	statusLog().Info("准入无空槽", "squad", q.Name)
	return Binding{}, ErrNoSlot
}

n_scheduling_Service_capacityContext.signature:
// capacityContext 为入口日志尽力补齐实际成员政策和载体物理上限；日志读取失败不
// 改变准入/释放结果，避免可观测性反过来成为调度路径的第二个错误出口。
func (s *Service) capacityContext(squadName, carrierName string) capacityLogContext {
	context := capacityLogContext{carrier: carrierName}
	q, err := s.Squad(squadName)
	if err == nil {
		for _, member := range q.Members {
			if carrierName != "" && member.Carrier != carrierName {
				continue
			}
			context.carrier = member.Carrier
			context.memberPolicy = member.MaxConcurrency
			break
		}
	}
	if context.carrier != "" {
		if carrier, err := s.Carrier(context.carrier); err == nil {
			context.carrierCap = carrier.MaxConcurrency
		}
	}
	return context
}

n_scheduling_Service_casCount.signature:
// casCount 以 CAS 把一条运行计数置为 next；冲突原样透传
// schedclient.ErrCASConflict 供调用方重试。
func (s *Service) casCount(id string, expect, next int) error {
	bodyBytes, _ := json.Marshal(map[string]int{"count": next})
	_, err := s.repo.Put(kindRunning, id, expect, bodyBytes, "scheduling")
	return err
}

n_scheduling_Service_checkKnownMachine.signature:
func (s *Service) checkKnownMachine(name, machine string, expect int) error {
	if IsLocalMachine(machine) {
		return nil
	}
	if s.knownMachines == nil {
		return nil
	}
	key := strings.TrimSpace(machine)
	if s.knownMachines(key) {
		return nil
	}
	statusLog().Error("载体登记校验失败", "name", name, "machine", key, "expect", expect, "cause", "machine 不在 targets")
	return fmt.Errorf("%w: 载体机器 %q 未在 targets 中定义", ErrInvalid, key)
}

n_scheduling_Service_getEntity.signature:
func (s *Service) getEntity(kind, id string, into any) error {
	rec, err := s.repo.Get(kind, id)
	if err != nil {
		if errors.Is(err, schedclient.ErrNotFound) {
			return ErrNotFound
		}
		return err
	}
	if err := json.Unmarshal(rec.Body, into); err != nil {
		return fmt.Errorf("%s/%s 解码失败: %w", kind, id, err)
	}
	return nil
}

n_scheduling_Service_listEntities.signature:
func (s *Service) listEntities(kind string, visit func([]byte) error) error {
	rows, err := s.repo.List(kind)
	if err != nil {
		return err
	}
	for _, rec := range rows {
		if err := visit(rec.Body); err != nil {
			return err
		}
	}
	return nil
}

n_scheduling_Service_position.signature:
// position 计算某请求在当前队序中的 1 基位置。
func (s *Service) position(kind, id string) int {
	entries, err := s.repo.List(kind)
	if err != nil {
		return 0
	}
	type ranked struct {
		eid	string
		req	IgnitionRequest
		rec	schedclient.Record
		seq	int64
		rank	int
	}
	items := make([]ranked, 0, len(entries))
	for _, rec := range entries {
		var e queuedEntry
		if json.Unmarshal(rec.Body, &e) != nil {
			continue
		}
		items = append(items, ranked{eid: rec.ID, req: e.Req, rec: rec, seq: e.Seq, rank: e.Req.orderRank()})
	}
	sort.SliceStable(items, func(i, j int) bool {
		if items[i].req.Ready != items[j].req.Ready {
			return items[i].req.Ready
		}
		if items[i].rank != items[j].rank {
			return items[i].rank < items[j].rank
		}
		if items[i].seq != items[j].seq {
			return items[i].seq < items[j].seq
		}
		return items[i].rec.Seq < items[j].rec.Seq
	})
	for i, item := range items {
		if item.eid == id {
			return i + 1
		}
	}
	return 0
}

n_scheduling_Service_putEntity.signature:
func (s *Service) putEntity(kind, id string, entity any, expect int) error {
	body, err := json.Marshal(entity)
	if err != nil {
		return err
	}
	_, err = s.repo.Put(kind, id, expect, body, "scheduling")
	return err
}

n_scheduling_Service_readCount.signature:
// readCount 读一条运行计数的当前值与 CAS 期望版本；缺失视为 0、期望版本 0
// （agentd 重启后计数随用随建，权威状态在账本不在内存）。
func (s *Service) readCount(id string) (count, expect int, err error) {
	rec, err := s.repo.Get(kindRunning, id)
	if err != nil {
		if errors.Is(err, schedclient.ErrNotFound) {
			return 0, 0, nil
		}
		return 0, 0, err
	}
	var body struct {
		Count int `json:"count"`
	}
	if err := json.Unmarshal(rec.Body, &body); err != nil {
		return 0, 0, fmt.Errorf("运行计数 %s 解码失败: %w", id, err)
	}
	return body.Count, rec.Version, nil
}

n_scheduling_Service_stepRunning.signature:
// stepRunning 对一条运行计数记录做带符号增量，CAS 重试读改写。
func (s *Service) stepRunning(id string, delta int) error {
	for attempt := 0; attempt < maxCASAttempts; attempt++ {
		rec, err := s.repo.Get(kindRunning, id)
		count := 0
		expect := 0
		if err == nil {
			var body struct {
				Count int `json:"count"`
			}
			if json.Unmarshal(rec.Body, &body) != nil {
				return fmt.Errorf("运行计数 %s 解码失败", id)
			}
			count = body.Count
			expect = rec.Version
		} else if !errors.Is(err, schedclient.ErrNotFound) {
			return err
		}
		next := count + delta
		if next < 0 {
			next = 0
		}
		bodyBytes, _ := json.Marshal(map[string]int{"count": next})
		if _, err := s.repo.Put(kindRunning, id, expect, bodyBytes, "scheduling"); err != nil {
			if errors.Is(err, schedclient.ErrCASConflict) {
				continue
			}
			return err
		}
		return nil
	}
	return fmt.Errorf("%w: %s", ErrRetryExhausted, id)
}

n_scheduling_Squad_UnmarshalJSON.signature:
// UnmarshalJSON 兼容 B156.3 的存量成员字符串形状。旧队级 max_concurrency 刻意不
// 出现在目标形状中，因此由 encoding/json 忽略；旧成员逐个规范化为不限政策位。
func (q *Squad) UnmarshalJSON(data []byte) error {
	type squadWire struct {
		Name	string		`json:"name"`
		Role	SquadRole	`json:"role"`
		Members	json.RawMessage	`json:"members"`
	}
	var raw squadWire
	if err := json.Unmarshal(data, &raw); err != nil {
		return err
	}
	q.Name, q.Role = raw.Name, raw.Role
	if len(raw.Members) == 0 || string(raw.Members) == "null" {
		q.Members = nil
		return nil
	}
	var members []SquadMember
	if err := json.Unmarshal(raw.Members, &members); err == nil {
		q.Members = members
		return nil
	}
	var legacy []string
	if err := json.Unmarshal(raw.Members, &legacy); err != nil {
		return json.Unmarshal(raw.Members, &members)
	}
	q.Members = make([]SquadMember, len(legacy))
	for i, carrier := range legacy {
		q.Members[i] = SquadMember{Carrier: carrier}
	}
	return nil
}

n_scheduling_admissionErrorKind.signature:
func admissionErrorKind(err error) string {
	switch {
	case errors.Is(err, ErrNoSlot):
		return "no_slot"
	case errors.Is(err, ErrNoHealthy):
		return "no_healthy"
	case errors.Is(err, ErrRetryExhausted):
		return "retry_exhausted"
	default:
		return "admission"
	}
}

n_scheduling_bindingFor.signature:
// bindingFor 产出绑定快照：物理身份来自载体，只有模型接受请求覆盖。
// 只在两级计数都成功递增后调用；请求侧物理字段由网关在此之前校验。
func bindingFor(q Squad, c Carrier, req IgnitionRequest) Binding {
	id := IdentityOf(c)
	return Binding{
		Squad:		q.Name,
		Carrier:	c.Name,
		Target:		id.Machine,
		Executor:	id.CLI,
		Model:		EffectiveModel(c.Model, req.Model),
		HomeDir:	id.HomeDir,
	}
}

n_scheduling_queueID.signature:
// queueID 是队列行的主键：卡号，节点级排队加节点名。
func queueID(req IgnitionRequest) string {
	if req.Node == "" {
		return req.Card
	}
	return req.Card + "|" + req.Node
}

n_scheduling_samePhysicalMachine.signature:
// samePhysicalMachine 把空串、local、本机和当前 hostname 统一看作本 agentd。
// 冻结目标的原始登记名仍保留在 Binding/Task 中；这里只在物理核验时消除本机
// 别名差异，避免 client 直连 canonical 化后把同一台机器误判成两台。
func samePhysicalMachine(left, right string) bool {
	left = strings.TrimSpace(left)
	right = strings.TrimSpace(right)
	if IsLocalMachine(left) && IsLocalMachine(right) {
		return true
	}
	return left == right
}

n_selfupdate_CLICheckPath.signature:
// CLICheckPath 返回缓存文件路径。
func CLICheckPath(dataDir string) string {
	return filepath.Join(dataDir, "update", "cli-check.json")
}

n_selfupdate_CLICheckStale.signature:
// CLICheckStale 判断是否该重新检查。nil（没查过）视为过期。
func CLICheckStale(c *CLICheck, now time.Time) bool {
	if c == nil {
		return true
	}
	return now.Sub(c.CheckedAt) >= cliCheckInterval
}

n_selfupdate_CompareVersion.signature:
// CompareVersion 比较两个版本号，是**全仓唯一**的版本比较入口。
//
// 参数：
//   - a, b: 形如 v0.1.2 或 v0.1.2-rc3 的标签，前缀 v 可有可无，
//     +构建元数据 按 semver 规则忽略
//
// 返回：
//   - a 小于/等于/大于 b 时分别为 -1/0/1
//   - 核心段不是三段非负整数时 ok 为 false，此时第一个返回值无意义
//
// 注意：
//   - 三段核心号都按整数比，不能用字典序——字典序会判定 v0.10.0 比 v0.9.0 旧
//   - **预发布号一律早于同号正式版**（semver 规则）：v0.3.0-rc11 < v0.3.0
//   - **标识符内部按「自然序」比，这是对严格 semver 的刻意偏离。**
//     semver 规定字母数字标识符按 ASCII 字典序比，那样 "rc11" < "rc8"
//     （因为 '1' < '8'）——正好和我们要的相反。本仓库的 tag 用 -rcN 而不是
//     semver 推荐的 -rc.N，所以这里把数字段与非数字段拆开、数字段按数值比，
//     于是 rc2 < rc8 < rc11。点分形态（-rc.1）照样正确
//   - **不要在别处另写一份。** 消费者已有三个（CLI 提示、桌面同步、桌面
//     通知）；本函数被写错过一次（B59 验收抓出的反向提示），三份实现意味着
//     错一次要修三处、而且一定有一处会被漏掉
//
// 边界：本函数只回答「谁新谁旧」。**「该不该给用户装这个版本」是另一回事**
// ——install.sh 的 latest_tag 只认 releases/latest 的重定向，GitHub 本就把
// 预发布排除在外，所以放宽这里不会让谁被自动装上一个 rc。
func CompareVersion(a, b string) (int, bool) {
	pa, ok := parseVersion(a)
	if !ok {
		return 0, false
	}
	pb, ok := parseVersion(b)
	if !ok {
		return 0, false
	}
	for i := range pa.core {
		switch {
		case pa.core[i] < pb.core[i]:
			return -1, true
		case pa.core[i] > pb.core[i]:
			return 1, true
		}
	}
	return comparePre(pa.pre, pb.pre), true
}

n_selfupdate_IsManaged.signature:
// IsManaged 判断换完版 exit(0) 之后还有没有人把 agentd 拉起来。
//
// 参数：
//   - getenv: 取环境变量的函数（测试注入用；生产传 os.Getenv）
//
// 返回：
//   - true 表示托管。**判不出来一律返回 false（fail-closed）**
//
// 注意：
//   - 这是「非托管则拒绝自动更新」这条防线的判据，也是整个自动更新里最
//     重要的一个判断。如果 agentd 不是被管理器拉起的，换完版 exit(0) 之后
//     没人拉起，机器上就此没有 handoff 在跑，而且没有任何信号告诉任何人
//   - **绝不能用 PPID**。手工 nohup / `zsh -c … &` 起的进程被 init 收养后
//     PPID 同样是 1，拿 PPID==1 当判据会把所有裸进程误判成托管，
//     正好把这条防线打穿
//   - XPC_SERVICE_NAME 的 `!= "0"` 是必要的额外防御：从 Finder / Terminal.app
//     启动的进程会继承 XPC_SERVICE_NAME=0（launchd 给非 XPC 服务的占位值），
//     只判「非空」会把桌面上手动跑的 agentd 误判成托管
//   - 判据取值来自 spec §7.1 的 P1 真机实测：launchd 托管时该变量等于 job
//     Label，ssh / tmux / 裸进程三种形态全为空
func IsManaged(getenv func(string) string) bool {

	if getenv("INVOCATION_ID") != "" {
		return true
	}

	if v := getenv("XPC_SERVICE_NAME"); v != "" && v != "0" {
		return true
	}
	ok, _ := platformManaged()
	return ok
}

n_selfupdate_LoadCLICheck.signature:
// LoadCLICheck 读缓存。
//
// 返回：
//   - 缓存；**缺失或损坏一律返回 nil，不返回错误**（理由见文件头注释）
func LoadCLICheck(dataDir string) *CLICheck {
	b, err := os.ReadFile(CLICheckPath(dataDir))
	if err != nil {
		return nil
	}
	var c CLICheck
	if err := json.Unmarshal(b, &c); err != nil {
		return nil
	}
	return &c
}

n_selfupdate_NotifyLine.signature:
// NotifyLine 生成提示行；不需要提示时返回空串。
//
// 参数：
//   - c: 缓存（可为 nil）
//   - current: 本进程版本；**空串表示非 release 构建**
//
// 注意：
//   - current 为空时一律不提示。开发时每条命令都被劝「有新版」是纯噪音，
//     而且本地构建本来就不该被劝去装 release
//   - **只有缓存里的版本严格新于当前版本才提示**。缓存最长会陈 24h，
//     刚升级完的机器读到的仍是升级前那次检查的结果；只判「不相等」就会
//     反过来劝人降级。这不是假设：v0.1.1 发布当天实测被劝
//     「有新版本 v0.1.0（当前 v0.1.1）」，且这条错误提示会挂满一整个刷新周期
func NotifyLine(c *CLICheck, current string) string {
	if c == nil || c.Latest == "" || current == "" || c.Latest == current {
		return ""
	}
	if cmp, ok := CompareVersion(c.Latest, current); !ok || cmp <= 0 {
		return ""
	}
	return fmt.Sprintf("有新版本 %s（当前 %s），运行 handoff upgrade --now 升级", c.Latest, current)
}

n_selfupdate_SaveCLICheck.signature:
// SaveCLICheck 写缓存，自动建目录。
func SaveCLICheck(dataDir string, c *CLICheck) error {
	path := CLICheckPath(dataDir)
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("建目录 %s: %w", filepath.Dir(path), err)
	}
	b, err := json.MarshalIndent(c, "", "  ")
	if err != nil {
		return fmt.Errorf("序列化: %w", err)
	}
	if err := os.WriteFile(path, b, 0o600); err != nil {
		return fmt.Errorf("写 %s: %w", path, err)
	}
	return nil
}

n_selfupdate_compareIdent.signature:
// compareIdent 按自然序比较单个标识符：把数字段与非数字段交替拆开，
// 数字段按数值比、非数字段按字典序比。
//
// 为什么不用字典序：本仓库的 tag 形如 -rc8 / -rc11，字典序会判 rc11 比 rc8 旧。
func compareIdent(a, b string) int {
	for a != "" || b != "" {
		if a == "" {
			return -1
		}
		if b == "" {
			return 1
		}
		da, ra := takeRun(a)
		db, rb := takeRun(b)
		aNum, bNum := isDigits(da), isDigits(db)
		switch {
		case aNum && bNum:

			na, ea := strconv.Atoi(da)
			nb, eb := strconv.Atoi(db)
			if ea != nil || eb != nil {
				if c := strings.Compare(da, db); c != 0 {
					return c
				}
			} else if na != nb {
				if na < nb {
					return -1
				}
				return 1
			}
		case aNum != bNum:

			if aNum {
				return -1
			}
			return 1
		default:
			if c := strings.Compare(da, db); c != 0 {
				return c
			}
		}
		a, b = ra, rb
	}
	return 0
}

n_selfupdate_comparePre.signature:
// comparePre 比较两个预发布标识符列表，返回 -1/0/1。
//
// 规则（前两条是 semver 原文，第三条是本仓库的偏离，理由见 CompareVersion）：
//   - 有预发布段的一方**更旧**；两边都没有则相等
//   - 逐个标识符比；全部相等时标识符少的一方更旧
//   - 单个标识符按自然序比（数字段按数值），而非 ASCII 字典序
func comparePre(a, b []string) int {
	switch {
	case len(a) == 0 && len(b) == 0:
		return 0
	case len(a) == 0:

		return 1
	case len(b) == 0:
		return -1
	}
	for i := 0; i < len(a) && i < len(b); i++ {
		if c := compareIdent(a[i], b[i]); c != 0 {
			return c
		}
	}
	switch {
	case len(a) < len(b):
		return -1
	case len(a) > len(b):
		return 1
	}
	return 0
}

n_selfupdate_isDigits.signature:
// isDigits 判断整段是否全为十进制数字（空串为否）。
func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

n_selfupdate_parseVersion.signature:
// parseVersion 把 v?X.Y.Z[-预发布][+构建] 拆开；形态不符时 ok 为 false。
func parseVersion(v string) (parsedVersion, bool) {
	var out parsedVersion
	v = strings.TrimPrefix(v, "v")

	if i := strings.IndexByte(v, '+'); i >= 0 {
		v = v[:i]
	}
	core := v

	if i := strings.IndexByte(v, '-'); i >= 0 {
		core = v[:i]
		pre := v[i+1:]
		if pre == "" {

			return out, false
		}
		out.pre = strings.Split(pre, ".")
		for _, id := range out.pre {
			if id == "" {
				return out, false
			}
		}
	}
	parts := strings.Split(core, ".")
	if len(parts) != 3 {
		return out, false
	}
	for i, p := range parts {
		n, err := strconv.Atoi(p)
		if err != nil || n < 0 {
			return out, false
		}
		out.core[i] = n
	}
	return out, true
}

n_selfupdate_takeRun.signature:
// takeRun 从头切下一段同类字符（全数字或全非数字），返回该段与剩余部分。
func takeRun(s string) (string, string) {
	if s == "" {
		return "", ""
	}
	digit := s[0] >= '0' && s[0] <= '9'
	for i := 1; i < len(s); i++ {
		if (s[i] >= '0' && s[i] <= '9') != digit {
			return s[:i], s[i:]
		}
	}
	return s, ""
}

n_service_New.signature:
// New 按当前平台返回对应的 Manager。
//
// 参数：
//   - log: 日志入口
//
// 返回：
//   - 平台对应的 Manager
//   - 不支持的平台返回错误，报文里说清为什么不支持而不是只说「不支持」
func New(log *slog.Logger) (Manager, error) {
	switch runtime.GOOS {
	case "darwin":
		return newLaunchd(log), nil
	case "linux":
		return newSystemd(log), nil
	case "windows":
		return newWindows(log), nil
	default:
		return nil, fmt.Errorf("不支持的平台 %s（仅 darwin/linux/windows）", runtime.GOOS)
	}
}

n_service_UnitReferences.signature:
// UnitReferences 报告已注册的计划任务是否指向 exePath 这个二进制。
//
// 参数：
//   - log: 日志入口
//   - exePath: 调用方自己的可执行文件绝对路径（须先 EvalSymlinks）
//
// 返回：
//   - true 表示「本进程退出后，计划任务会把同一个二进制重新拉起」
//   - 第二个返回值是判否的理由原文，供调用方打日志；判是时为空
//
// 为什么问的是「任务指不指向我」而不是「谁把我拉起来的」：换版闸二真正
// 要的保证是「我 exit(0) 之后还有人把我拉回来」。schtasks 不像 systemd /
// launchd 那样给被拉起的进程注入任何环境变量，「谁拉起我」在 Windows 上
// 根本问不出来；而「任务在不在、指的是不是我」既问得出，又恰好是那个保证。
//
// 顺带挡住一个真实的坑：从别的目录跑一个 agentd（如临时工作树里的构建），
// 此时任务指向的是另一个二进制——换版会换掉没人运行的那个文件，upgrade
// 报成功而机器上跑的还是旧版。路径对不上就判否，正是闸二该拦的情形。
func UnitReferences(log *slog.Logger, exePath string) (bool, string) {
	return newWindows(log).unitReferences(exePath)
}

n_service_errNotInstalled.signature:
// errNotInstalled 造一个带单元路径的 ErrNotInstalled。
//
// 参数：
//   - unit: 单元文件路径或任务名，用于告诉用户该去看哪个东西
//
// 返回：可被 errors.Is(err, ErrNotInstalled) 认出的错误
func errNotInstalled(unit string) error {
	return fmt.Errorf("%w: %s（先跑 handoff service install）", ErrNotInstalled, unit)
}

n_service_esc.signature:
// esc 按 XML 文本规则转义字符串。
//
// 用户目录和可执行文件路径可以含有 & 或 < 等字符；不转义会让 schtasks 拒绝
// 整个任务定义，而且错误信息不会明确指出是哪个路径字符造成的。
func esc(s string) string {
	var buf bytes.Buffer
	if err := xml.EscapeText(&buf, []byte(s)); err != nil {
		return s
	}
	return buf.String()
}

n_service_firstLine.signature:
// firstLine 取多行输出的第一行，用作 Detail 摘要。
func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return strings.TrimSpace(s[:i])
	}
	return strings.TrimSpace(s)
}

n_service_launchdManager_Install.signature:
// Install 写 plist 并加载，最后复核服务真的注册上了。
func (m *launchdManager) Install(spec Spec) error {
	path, err := m.UnitPath()
	if err != nil {
		return err
	}
	m.log.Info("安装 launchd 服务", "label", LaunchdLabel, "plist", path, "bin", spec.BinPath)

	if out, err := m.run("launchctl", "bootout", m.target()); err != nil {
		m.log.Debug("bootout 旧 job（未装时报错属正常）", "output", strings.TrimSpace(string(out)))
	}

	if out, err := m.run("launchctl", "enable", m.target()); err != nil {
		m.log.Debug("enable（从未停用过时报错属正常）", "output", strings.TrimSpace(string(out)))
	}

	if err := m.mkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("创建 %s: %w", filepath.Dir(path), err)
	}
	if err := m.writeFile(path, []byte(m.plistBody(spec)), 0o644); err != nil {
		return fmt.Errorf("写 plist %s: %w", path, err)
	}

	if out, err := m.run("launchctl", "bootstrap", m.domain(), path); err != nil {

		if rmErr := m.remove(path); rmErr != nil {
			m.log.Error("回滚删除 plist 失败", "path", path, "cause", rmErr)
		}
		m.log.Error("加载 launchd 服务失败，已回滚", "cause", err, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("加载 launchd 服务失败: %s（%w）", strings.TrimSpace(string(out)), err)
	}

	if out, err := m.run("launchctl", "print", m.target()); err != nil {
		m.log.Error("服务已加载但复核失败", "cause", err, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("服务已加载但复核不到（可能起来即退出，检查 %s）: %w", spec.LogPath, err)
	}
	m.log.Info("launchd 服务安装完成", "label", LaunchdLabel)
	return nil
}

n_service_launchdManager_Restart.signature:
// Restart 就地重启服务，不改动 plist。
//
// 返回：错误——plist 不在（ErrNotInstalled）、发信号失败、
// 或复核窗口内 pid 没换
//
// 注意：
//   - **发 SIGTERM 而不是 kickstart -k。** 后者是 SIGKILL，会把在途任务砍在
//     半路；SIGTERM 走的是 agentd 自己的优雅关停（停收新连接 → 等在途请求
//     → 按序收尾），而 plist 里的 KeepAlive=true 保证它随后被拉回来
//   - **复核判据是 pid 变了且在跑，不是「还在跑」。** launchd 的重启是异步的，
//     kill 返回时旧进程可能还没死；只查「在不在跑」的话，「什么都没发生」和
//     「重启成功」长得一模一样
//   - 没在跑（含被 Stop 停住）时等价于 Start，语义与 systemctl restart 对齐：
//     用户在 agentd 崩着的时候敲 restart，要的是它起来
func (m *launchdManager) Restart() error {
	if _, err := m.ensureInstalled(); err != nil {
		return err
	}
	before := m.currentPid()
	if before == 0 {
		m.log.Info("重启时发现服务未在运行，改为启动", "label", LaunchdLabel)
		return m.Start()
	}
	m.log.Info("重启 launchd 服务", "label", LaunchdLabel, "pid_before", before)
	if out, kerr := m.run("launchctl", "kill", "SIGTERM", m.target()); kerr != nil {
		m.log.Error("发送 SIGTERM 失败", "label", LaunchdLabel,
			"cause", kerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("发送 SIGTERM 失败: %s（%w）", strings.TrimSpace(string(out)), kerr)
	}
	for i := 0; i < launchdVerifyAttempts; i++ {
		m.sleep(launchdVerifyInterval)
		if now := m.currentPid(); now != 0 && now != before {
			m.log.Info("launchd 服务已重启", "label", LaunchdLabel,
				"pid_before", before, "pid_after", now)
			return nil
		}
	}
	m.log.Error("已发 SIGTERM 但复核窗口内 pid 未换",
		"label", LaunchdLabel, "pid_before", before, "window", launchdVerifyWindow)
	return fmt.Errorf("已发 SIGTERM，但 %s 内 pid 仍是 %d（可能没被拉起来，检查日志）",
		launchdVerifyWindow, before)
}

n_service_launchdManager_Start.signature:
// Start 启动一个已安装的服务，并解除可能存在的停用状态。
//
// 返回：错误——plist 不在（ErrNotInstalled）、enable 失败、加载失败、
// 或复核窗口内没见它跑起来
//
// 注意：
//   - **enable 必须在 bootstrap 之前。** 被 launchctl disable 过的 target，
//     bootstrap 会直接拒（Service is disabled），而 Stop 正是靠 disable 才让
//     「停到显式 start」跨得过重启——这条路是 stop→start 的必经之路
//   - 用 bootstrap 而不是 kickstart：Stop 做过 bootout，job 已从 launchd
//     卸载，kickstart 找不到目标。已经加载着时 bootstrap 会报
//     "service already loaded"，那不是失败（目标状态本就是「加载着」），
//     降级为 kickstart 把它踢起来
//   - 不代为 Install
func (m *launchdManager) Start() error {
	path, err := m.ensureInstalled()
	if err != nil {
		return err
	}
	m.log.Info("启动 launchd 服务", "label", LaunchdLabel, "plist", path)
	if out, eerr := m.run("launchctl", "enable", m.target()); eerr != nil {
		m.log.Error("解除停用失败", "label", LaunchdLabel,
			"cause", eerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("解除停用失败: %s（%w）", strings.TrimSpace(string(out)), eerr)
	}
	if out, berr := m.run("launchctl", "bootstrap", m.domain(), path); berr != nil {
		bootstrapOutput := strings.TrimSpace(string(out))
		m.log.Debug("bootstrap 报错，改用 kickstart（已加载时属正常）",
			"output", bootstrapOutput)
		if kout, kerr := m.run("launchctl", "kickstart", m.target()); kerr != nil {
			kickstartOutput := strings.TrimSpace(string(kout))
			m.log.Error("启动 launchd 服务失败：先试 bootstrap 再试 kickstart，两个都失败",
				"label", LaunchdLabel,
				"bootstrap_cause", berr, "bootstrap_output", bootstrapOutput,
				"kickstart_cause", kerr, "kickstart_output", kickstartOutput)
			return fmt.Errorf("启动 launchd 服务失败：先试 bootstrap 再试 kickstart，两个都失败；bootstrap 原文: %s（%v）；kickstart 原文: %s（%w）",
				bootstrapOutput, berr, kickstartOutput, kerr)
		}
	}
	if !m.waitRunning() {
		m.log.Error("服务已触发但复核窗口内未见运行",
			"label", LaunchdLabel, "window", launchdVerifyWindow)
		return fmt.Errorf("服务已触发，但 %s 内未复核到运行（可能起来即退出）", launchdVerifyWindow)
	}
	m.log.Info("launchd 服务已启动", "label", LaunchdLabel)
	return nil
}

n_service_launchdManager_Status.signature:
// Status 查询单元的安装、运行与停用状态。
//
// 返回：
//   - Status：Installed 看 plist 在不在，Running 看 job 加载且不是
//     not running，Disabled 查 launchd 的停用清单
//   - 错误：只有取不到 plist 路径（主目录读不出来）才算查询失败；
//     「没装」「没跑」「停用了」都是正常答案，不是错误
//
// 注意：
//   - **Installed 的判据是 plist 存在，不是 launchctl print 能查到。**
//     Stop 会 bootout（把 job 从 launchd 卸载）但保留 plist；若按 print 判，
//     stop 之后 start 会被「没装」硬拒，「停到显式 start」当场自相矛盾
func (m *launchdManager) Status() (Status, error) {
	path, err := m.UnitPath()
	if err != nil {
		return Status{}, err
	}
	s := Status{}
	if _, statErr := m.stat(path); statErr == nil {
		s.Installed = true
	}
	if out, printErr := m.run("launchctl", "print", m.target()); printErr == nil {

		s.Installed = true
		s.Detail = firstLine(string(out))

		s.Running = !strings.Contains(string(out), "state = not running")
	}
	s.Disabled = m.isDisabled()
	m.log.Debug("launchd 服务状态", "label", LaunchdLabel,
		"installed", s.Installed, "running", s.Running, "disabled", s.Disabled)
	return s, nil
}

n_service_launchdManager_Stop.signature:
// Stop 停止服务并关掉自动拉起，直到显式 Start。
//
// 返回：错误——plist 不在（ErrNotInstalled）、disable 失败、
// 或复核窗口内它仍在跑
//
// 注意：
//   - **disable 在前、bootout 在后，顺序是承重的。** disable 成功而 bootout
//     失败，留下的是「还在跑但已停用」，重启后自己下去；反过来 bootout 成功
//     而 disable 失败，留下的是「停了但仍启用」，下次登录 launchd 自动把它
//     bootstrap 回来，用户的 stop 被无声撤销。选前一种失败形态
//   - **只 bootout 不 disable 是不够的**：plist 还躺在 ~/Library/LaunchAgents
//     里，RunAtLoad 会在下次登录时把它拉回来
func (m *launchdManager) Stop() error {
	path, err := m.ensureInstalled()
	if err != nil {
		return err
	}
	m.log.Info("停止并停用 launchd 服务", "label", LaunchdLabel, "plist", path)
	if out, derr := m.run("launchctl", "disable", m.target()); derr != nil {
		m.log.Error("停用 launchd 服务失败", "label", LaunchdLabel,
			"cause", derr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("停用失败: %s（%w）", strings.TrimSpace(string(out)), derr)
	}
	if out, berr := m.run("launchctl", "bootout", m.target()); berr != nil {

		m.log.Debug("bootout 报错（本来就没加载时属正常）", "output", strings.TrimSpace(string(out)))
	}
	if !m.waitStopped() {
		m.log.Error("已请求停止但复核窗口内仍在运行",
			"label", LaunchdLabel, "window", launchdVerifyWindow)
		return fmt.Errorf("已请求停止，但 %s 内它仍在运行", launchdVerifyWindow)
	}
	m.log.Info("launchd 服务已停止并停用", "label", LaunchdLabel)
	return nil
}

n_service_launchdManager_Uninstall.signature:
// Uninstall 卸载并删除 plist。本来就没装时返回 nil。
func (m *launchdManager) Uninstall() error {
	path, err := m.UnitPath()
	if err != nil {
		return err
	}
	m.log.Info("卸载 launchd 服务", "label", LaunchdLabel)
	if out, err := m.run("launchctl", "bootout", m.target()); err != nil {

		m.log.Debug("bootout 报错（未装时属正常）", "output", strings.TrimSpace(string(out)))
	}
	if err := m.remove(path); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("删除 plist %s: %w", path, err)
	}
	m.log.Info("launchd 服务已卸载", "label", LaunchdLabel)
	return nil
}

n_service_launchdManager_UnitPath.signature:
// UnitPath 返回 plist 的落点。
func (m *launchdManager) UnitPath() (string, error) {
	if m.plistDir == "" {
		return "", fmt.Errorf("取不到用户主目录，无法定位 LaunchAgents 目录")
	}
	return filepath.Join(m.plistDir, LaunchdLabel+".plist"), nil
}

n_service_launchdManager_currentPid.signature:
// currentPid 取当前实例的 pid，取不到（未加载 / 没在跑）返回 0。
//
// 它也是 start/stop 复核使用的轻量运行态探针：launchctl print 查不到 job，或
// 输出里没有 pid 行，这两种情况都返回 0；非零 pid 就代表当前有 agentd 实例在跑。
// 这正是轮询可以用 pid 代替完整 Status 的等价关系。
func (m *launchdManager) currentPid() int {
	out, err := m.run("launchctl", "print", m.target())
	if err != nil {
		return 0
	}
	return parsePrintPid(string(out))
}

n_service_launchdManager_domain.signature:
// domain 返回 launchctl 的目标域，形如 gui/501。
func (m *launchdManager) domain() string {
	return "gui/" + strconv.Itoa(os.Getuid())
}

n_service_launchdManager_ensureInstalled.signature:
// ensureInstalled 在做任何变更前确认 plist 在。
//
// 返回：plist 路径；不在时返回包装了 ErrNotInstalled 的错误
//
// 注意：三个生命周期方法共用它，且必须在发出任何 launchctl 变更命令之前调用
// ——「没装」的正确处置是去 install，不是让 start 悄悄替 install 干活
func (m *launchdManager) ensureInstalled() (string, error) {
	path, err := m.UnitPath()
	if err != nil {
		return "", err
	}
	if _, statErr := m.stat(path); statErr != nil {
		m.log.Error("单元未安装", "label", LaunchdLabel, "plist", path, "cause", statErr)
		return "", errNotInstalled(path)
	}
	return path, nil
}

n_service_launchdManager_isDisabled.signature:
// isDisabled 查 launchd 的停用覆写数据库，判断本 job 是否被显式停用。
//
// 返回：被 launchctl disable 过则 true；查不到、查询失败、从未出现在清单里
// 都按 false（未停用）处理
//
// 注意：
//   - 两种输出格式都要认。macOS 26 打的是 "<label>" => disabled/enabled，
//     更早的系统打的是 => true/false。只认一种，会在另一种系统上把「已停用」
//     读成「启用」，status 于是给出错误的处置建议
//   - 从未被 enable/disable 过的 label 根本不出现在这份清单里——不出现即未停用
func (m *launchdManager) isDisabled() bool {
	out, err := m.run("launchctl", "print-disabled", m.domain())
	if err != nil {
		m.log.Debug("查 launchd 停用清单失败，按未停用处理",
			"cause", err, "output", strings.TrimSpace(string(out)))
		return false
	}
	for _, line := range strings.Split(string(out), "\n") {
		if !strings.Contains(line, `"`+LaunchdLabel+`"`) {
			continue
		}
		i := strings.Index(line, "=>")
		if i < 0 {
			continue
		}
		v := strings.TrimSpace(line[i+2:])
		return v == "disabled" || v == "true"
	}
	return false
}

n_service_launchdManager_plistBody.signature:
// plistBody 渲染 plist 内容。
//
// 参数：
//   - spec: 要托管的 agentd 描述
//
// 返回：
//   - plist 全文
//
// 注意：
//   - KeepAlive=true 对应 systemd 的 Restart=always：**exit 0 也会被重新拉起**，
//     这正是自更新换版所依赖的（P1 实测确认，见 spec §7.1）
//   - launchd 对重生有约 10 秒节流，换版期间会有约 10 秒的服务空窗
func (m *launchdManager) plistBody(spec Spec) string {
	var b strings.Builder
	b.WriteString(`<?xml version="1.0" encoding="UTF-8"?>` + "\n")
	b.WriteString(`<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">` + "\n")
	b.WriteString("<plist version=\"1.0\">\n<dict>\n")
	b.WriteString("  <key>Label</key>\n  <string>" + LaunchdLabel + "</string>\n")
	b.WriteString("  <key>ProgramArguments</key>\n  <array>\n")
	b.WriteString("    <string>" + spec.BinPath + "</string>\n")
	b.WriteString("    <string>agentd</string>\n")
	if spec.ConfigPath != "" {
		b.WriteString("    <string>--config</string>\n")
		b.WriteString("    <string>" + spec.ConfigPath + "</string>\n")
	}
	b.WriteString("  </array>\n")
	b.WriteString("  <key>RunAtLoad</key>\n  <true/>\n")
	b.WriteString("  <key>KeepAlive</key>\n  <true/>\n")
	if spec.LogPath != "" {
		b.WriteString("  <key>StandardOutPath</key>\n  <string>" + spec.LogPath + "</string>\n")
		b.WriteString("  <key>StandardErrorPath</key>\n  <string>" + spec.LogPath + "</string>\n")
	}
	b.WriteString("</dict>\n</plist>\n")
	return b.String()
}

n_service_launchdManager_waitRunning.signature:
// waitRunning 轮询到服务真的在跑为止。超时返回 false。
//
// 这里不调用 Status，因为它还会查询 print-disabled，而 start 的 25 轮复核只
// 关心运行态。
func (m *launchdManager) waitRunning() bool {
	for i := 0; i < launchdVerifyAttempts; i++ {
		if m.currentPid() != 0 {
			return true
		}
		m.sleep(launchdVerifyInterval)
	}
	return false
}

n_service_launchdManager_waitStopped.signature:
// waitStopped 轮询到服务真的不在跑为止。超时返回 false。
//
// 这里不调用 Status，因为它还会查询 print-disabled，而 stop 的 25 轮复核只关
// 心运行态。
func (m *launchdManager) waitStopped() bool {
	for i := 0; i < launchdVerifyAttempts; i++ {
		if m.currentPid() == 0 {
			return true
		}
		m.sleep(launchdVerifyInterval)
	}
	return false
}

n_service_newLaunchd.signature:
// newLaunchd 构造生产用的 launchd manager。
func newLaunchd(log *slog.Logger) *launchdManager {
	m := &launchdManager{
		log:		log,
		homeDir:	os.UserHomeDir,
		mkdirAll:	os.MkdirAll,
		run: func(name string, args ...string) ([]byte, error) {

			return exec.Command(name, args...).CombinedOutput()
		},
		writeFile:	func(p string, b []byte, perm uint32) error { return os.WriteFile(p, b, os.FileMode(perm)) },
		remove:		os.Remove,
		stat:		os.Stat,
		sleep:		time.Sleep,
	}
	if h, err := m.homeDir(); err == nil {
		m.plistDir = filepath.Join(h, "Library", "LaunchAgents")
	}
	return m
}

n_service_newSystemd.signature:
// newSystemd 构造生产用的 systemd manager。
func newSystemd(log *slog.Logger) *systemdManager {
	name := ""
	if u, err := user.Current(); err == nil {
		name = u.Username
	}
	return &systemdManager{
		log:		log,
		unitDir:	"/etc/systemd/system",
		user:		name,
		run: func(n string, args ...string) ([]byte, error) {
			return exec.Command(n, args...).CombinedOutput()
		},
		writeFile:	func(p string, b []byte, perm uint32) error { return os.WriteFile(p, b, os.FileMode(perm)) },
		remove:		os.Remove,
		stat:		os.Stat,
	}
}

n_service_newWindows.signature:
// newWindows 构造生产用的 Windows manager。
func newWindows(log *slog.Logger) *windowsManager {
	return &windowsManager{
		log:		log,
		localAppData:	os.Getenv("LOCALAPPDATA"),
		currentUser: func() (string, error) {
			u, err := user.Current()
			if err != nil {
				return "", err
			}
			return u.Username, nil
		},
		mkdirAll:	os.MkdirAll,
		run: func(name string, args ...string) ([]byte, error) {
			c := exec.Command(name, args...)

			hideConsole(c)
			return c.CombinedOutput()
		},
		writeFile: func(path string, data []byte, perm uint32) error {
			return os.WriteFile(path, data, os.FileMode(perm))
		},
		remove:	os.Remove,
		sleep:	time.Sleep,
	}
}

n_service_parsePrintPid.signature:
// parsePrintPid 从 launchctl print 的输出里取当前实例的 pid。
//
// 返回：取不到（未加载、或那一刻没有进程）返回 0
//
// 注意：pid 是 Restart 唯一可信的复核判据——「还在跑」区分不了新旧实例
func parsePrintPid(out string) int {
	for _, line := range strings.Split(out, "\n") {
		line = strings.TrimSpace(line)
		if !strings.HasPrefix(line, "pid = ") {
			continue
		}
		n, err := strconv.Atoi(strings.TrimSpace(strings.TrimPrefix(line, "pid = ")))
		if err != nil {
			return 0
		}
		return n
	}
	return 0
}

n_service_sudoHint.signature:
// sudoHint 在 systemctl 的输出里认出权限不足，并把报文换成可执行的处置。
//
// 参数：
//   - action: 正在做的事，用于拼报文（如「停止」「启动」「重启」）
//   - output: systemctl 的原文
//
// 返回：面向用户的报文。权限不足时带上「请用 sudo 重跑」，否则原样带出原文
//
// 注意：B45 的教训——system unit 落在 /etc/systemd/system，所有变更类操作
// 都要 root；扁平抛一句 Access denied，用户不知道下一步该干什么
func sudoHint(action, output string) string {
	low := strings.ToLower(output)
	for _, sig := range []string{"access denied", "permission denied", "interactive authentication required"} {
		if strings.Contains(low, sig) {
			return fmt.Sprintf("%s systemd 服务需要 root 权限，请用 sudo 重跑：%s", action, output)
		}
	}
	return fmt.Sprintf("%s systemd 服务失败: %s", action, output)
}

n_service_systemdManager_Install.signature:
// Install 写 unit、reload、enable --now，并复核真的活着。
func (m *systemdManager) Install(spec Spec) error {
	path, err := m.UnitPath()
	if err != nil {
		return err
	}
	if m.user == "" {

		return fmt.Errorf("取不到当前用户名，无法生成 unit（User= 留空会让服务以 root 运行）")
	}
	m.log.Info("安装 systemd 服务", "unit", SystemdUnit, "path", path, "bin", spec.BinPath, "user", m.user)

	if err := m.writeFile(path, []byte(m.unitBody(spec)), 0o644); err != nil {

		if os.IsPermission(err) || strings.Contains(err.Error(), "permission denied") {
			return fmt.Errorf("写 %s 需要 root 权限，请用 sudo 重跑：sudo handoff service install（原因: %w）", path, err)
		}
		return fmt.Errorf("写 unit %s: %w", path, err)
	}

	if out, err := m.run("systemctl", "daemon-reload"); err != nil {
		m.rollback(path)
		return fmt.Errorf("systemctl daemon-reload 失败: %s（%w）", strings.TrimSpace(string(out)), err)
	}
	if out, err := m.run("systemctl", "enable", "--now", SystemdUnit); err != nil {
		m.rollback(path)
		m.log.Error("启用 systemd 服务失败，已回滚", "cause", err, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("启用 systemd 服务失败: %s（%w）", strings.TrimSpace(string(out)), err)
	}

	if out, err := m.run("systemctl", "is-active", SystemdUnit); err != nil {
		m.log.Error("服务已启用但复核不到活跃状态", "cause", err, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("服务已启用但未处于活跃状态（可能起来即退出，查 journalctl -u %s）: %w", SystemdUnit, err)
	}
	m.log.Info("systemd 服务安装完成", "unit", SystemdUnit)
	return nil
}

n_service_systemdManager_Restart.signature:
// Restart 就地重启，不重写 unit、不 daemon-reload。
//
// 返回：错误——unit 不在（ErrNotInstalled）、restart 失败、或复核不到 active
//
// 注意：
//   - systemctl restart 默认发 SIGTERM，配合 unit 里的 KillMode=process，
//     执行者不会被连坐（B36）
//   - 它是**同步**的：返回时新实例已经起来。所以复核一次 is-active 就够，
//     不像 launchd 那样要轮询等 KeepAlive 把它拉回来
//   - 单元当前没在跑（含被 Stop 停住）时，systemctl restart 会直接把它启起来
//     ——与 Manager.Restart 的约定一致，无需在这里特判
func (m *systemdManager) Restart() error {
	path, err := m.ensureInstalled()
	if err != nil {
		return err
	}
	m.log.Info("重启 systemd 服务", "unit", SystemdUnit, "path", path)
	if out, rerr := m.run("systemctl", "restart", SystemdUnit); rerr != nil {
		m.log.Error("重启 systemd 服务失败", "unit", SystemdUnit,
			"cause", rerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("%s（%w）", sudoHint("重启", strings.TrimSpace(string(out))), rerr)
	}
	if out, aerr := m.run("systemctl", "is-active", SystemdUnit); aerr != nil {
		m.log.Error("已重启但未 active", "unit", SystemdUnit,
			"cause", aerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("已重启但未处于活跃状态（可能起来即退出，查 journalctl -u %s）: %s（%w）",
			SystemdUnit, strings.TrimSpace(string(out)), aerr)
	}
	m.log.Info("systemd 服务已重启", "unit", SystemdUnit)
	return nil
}

n_service_systemdManager_Start.signature:
// Start 启动已安装的单元，并恢复开机自启。
//
// 返回：错误——unit 不在（ErrNotInstalled）、enable --now 失败、
// 或复核不到 active
//
// 注意：
//   - **用 enable --now 而不是裸 start。** Stop 用 disable 摘掉了开机自启，
//     只 start 能把它跑起来但下次开机又没了；「显式 start 之后恢复原状」
//     才是这里的目标
//   - 不重写 unit 文件、不 daemon-reload：那是 Install 的职责
//   - 不代为 Install
func (m *systemdManager) Start() error {
	path, err := m.ensureInstalled()
	if err != nil {
		return err
	}
	m.log.Info("启动 systemd 服务", "unit", SystemdUnit, "path", path)
	if out, serr := m.run("systemctl", "enable", "--now", SystemdUnit); serr != nil {
		m.log.Error("启动 systemd 服务失败", "unit", SystemdUnit,
			"cause", serr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("%s（%w）", sudoHint("启动", strings.TrimSpace(string(out))), serr)
	}

	if out, aerr := m.run("systemctl", "is-active", SystemdUnit); aerr != nil {
		m.log.Error("服务已触发但未 active", "unit", SystemdUnit,
			"cause", aerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("服务已触发但未处于活跃状态（可能起来即退出，查 journalctl -u %s）: %s（%w）",
			SystemdUnit, strings.TrimSpace(string(out)), aerr)
	}
	m.log.Info("systemd 服务已启动", "unit", SystemdUnit)
	return nil
}

n_service_systemdManager_Status.signature:
// Status 查询 unit 是否装了、是否活跃、是否被停用。
//
// 返回：
//   - Status：Installed 看 unit 文件在不在，Running 看 is-active，
//     Disabled 看 is-enabled
//   - 错误：恒为 nil。「没装」「没跑」「停用了」都是正常答案
//
// 注意：
//   - is-enabled 的输出是稳定的英文枚举（enabled/disabled/static/...），
//     不随 locale 变，可以按文本判。disabled 时它返回非 0，所以不看 err
func (m *systemdManager) Status() (Status, error) {
	s := Status{}
	path, _ := m.UnitPath()
	if _, statErr := m.stat(path); statErr == nil {
		s.Installed = true
	}
	out, err := m.run("systemctl", "is-active", SystemdUnit)
	s.Detail = firstLine(string(out))
	if err == nil {
		s.Installed = true
		s.Running = true
	}
	if eout, _ := m.run("systemctl", "is-enabled", SystemdUnit); strings.TrimSpace(firstLine(string(eout))) == "disabled" {
		s.Disabled = true
	}
	m.log.Debug("systemd 服务状态", "unit", SystemdUnit,
		"installed", s.Installed, "running", s.Running, "disabled", s.Disabled)
	return s, nil
}

n_service_systemdManager_Stop.signature:
// Stop 停止服务并关掉开机自启，直到显式 Start。
//
// 返回：错误——unit 不在（ErrNotInstalled）、disable --now 失败、
// 或复核到它仍然 active
//
// 注意：
//   - **用 disable --now 而不是裸 stop。** 只 stop 的话 unit 还是 enabled，
//     下次开机 systemd 照样把它拉起来，「停到显式 start」撑不过一次重启
//   - unit 里的 Restart=always 不会跟显式 stop 打架：systemd 的重启策略只对
//     「进程自己退出」生效，对 systemctl stop 不生效
func (m *systemdManager) Stop() error {
	path, err := m.ensureInstalled()
	if err != nil {
		return err
	}
	m.log.Info("停止并停用 systemd 服务", "unit", SystemdUnit, "path", path)
	if out, derr := m.run("systemctl", "disable", "--now", SystemdUnit); derr != nil {
		m.log.Error("停止 systemd 服务失败", "unit", SystemdUnit,
			"cause", derr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("%s（%w）", sudoHint("停止", strings.TrimSpace(string(out))), derr)
	}

	if out, aerr := m.run("systemctl", "is-active", SystemdUnit); aerr == nil {
		m.log.Error("已请求停止但仍处于活跃状态", "unit", SystemdUnit,
			"output", strings.TrimSpace(string(out)))
		return fmt.Errorf("已请求停止，但 unit 仍处于活跃状态: %s", strings.TrimSpace(string(out)))
	}
	m.log.Info("systemd 服务已停止并停用", "unit", SystemdUnit)
	return nil
}

n_service_systemdManager_Uninstall.signature:
// Uninstall 停用并删除 unit。本来就没装时返回 nil。
func (m *systemdManager) Uninstall() error {
	path, err := m.UnitPath()
	if err != nil {
		return err
	}
	m.log.Info("卸载 systemd 服务", "unit", SystemdUnit)
	if out, err := m.run("systemctl", "disable", "--now", SystemdUnit); err != nil {

		m.log.Debug("disable 报错（未装时属正常）", "output", strings.TrimSpace(string(out)))
	}
	if err := m.remove(path); err != nil && !os.IsNotExist(err) {
		if os.IsPermission(err) || strings.Contains(err.Error(), "permission denied") {
			return fmt.Errorf("删除 %s 需要 root 权限，请用 sudo 重跑（原因: %w）", path, err)
		}
		return fmt.Errorf("删除 unit %s: %w", path, err)
	}
	if _, err := m.run("systemctl", "daemon-reload"); err != nil {
		m.log.Warn("卸载后 daemon-reload 失败", "cause", err)
	}
	m.log.Info("systemd 服务已卸载", "unit", SystemdUnit)
	return nil
}

n_service_systemdManager_UnitPath.signature:
// UnitPath 返回 unit 文件落点。
func (m *systemdManager) UnitPath() (string, error) {
	return filepath.Join(m.unitDir, SystemdUnit), nil
}

n_service_systemdManager_ensureInstalled.signature:
// ensureInstalled 在做任何变更前确认 unit 文件在。
//
// 返回：unit 路径；不在时返回包装了 ErrNotInstalled 的错误
func (m *systemdManager) ensureInstalled() (string, error) {
	path, err := m.UnitPath()
	if err != nil {
		return "", err
	}
	if _, statErr := m.stat(path); statErr != nil {
		m.log.Error("单元未安装", "unit", SystemdUnit, "path", path, "cause", statErr)
		return "", errNotInstalled(path)
	}
	return path, nil
}

n_service_systemdManager_rollback.signature:
// rollback 删掉刚写的 unit 并 reload，避免留下一个装不上又卸不掉的残件。
func (m *systemdManager) rollback(path string) {
	if err := m.remove(path); err != nil && !os.IsNotExist(err) {
		m.log.Error("回滚删除 unit 失败", "path", path, "cause", err)
		return
	}
	if _, err := m.run("systemctl", "daemon-reload"); err != nil {
		m.log.Warn("回滚后 daemon-reload 失败", "cause", err)
	}
}

n_service_systemdManager_unitBody.signature:
// unitBody 渲染 unit 内容。
//
// 两条硬要求，改之前先读懂为什么：
//
//   - KillMode=process：执行者由 agentd 经 shim 以 setsid 拉起，setsid 脱离了
//     会话与进程组但**改不了 cgroup 归属**（cgroup 由 fork 继承）。systemd 默认的
//     KillMode=control-group 会在 stop/restart 时向整个 cgroup 发信号，执行者
//     一并被杀，正在跑的任务全部中断（B36）
//   - Restart=always：自更新换版靠「agentd 自己 exit 0 -> 管理器拉起新版」交接。
//     on-failure 在 exit 0 时**不重启**——换完版服务就此消失，而且没有任何信号
//     告诉任何人。这是 D9 的直接结论
//
// User 必须写字面用户名。写 %i 会被当成模板 unit 的实例名占位符，在非模板
// unit 里解析为空串，而 `User=` 空值会被 systemd 重置为 root——服务会以 root
// 静默跑起来，不报任何错。
func (m *systemdManager) unitBody(spec Spec) string {
	exec := spec.BinPath + " agentd"
	if spec.ConfigPath != "" {
		exec += " --config " + spec.ConfigPath
	}
	var b strings.Builder
	b.WriteString("# 由 handoff service install 生成，勿手改——重装会覆盖。\n")
	b.WriteString("[Unit]\n")
	b.WriteString("Description=handoff agentd (executor host)\n")
	b.WriteString("After=network-online.target\n")
	b.WriteString("Wants=network-online.target\n\n")
	b.WriteString("[Service]\n")
	b.WriteString("Type=simple\n")
	b.WriteString("User=" + m.user + "\n")
	b.WriteString("ExecStart=" + exec + "\n")

	b.WriteString("Restart=always\n")
	b.WriteString("RestartSec=3\n\n")
	b.WriteString("# KillMode=process 是硬要求：setsid 改不了 cgroup 归属，\n")
	b.WriteString("# 默认的 control-group 会在重启时把执行者一并杀掉（B36）。\n")
	b.WriteString("KillMode=process\n\n")
	b.WriteString("[Install]\n")
	b.WriteString("WantedBy=multi-user.target\n")
	return b.String()
}

n_service_taskIsRunning.signature:
// taskIsRunning 判断 schtasks 的详细输出是否表示任务正在运行。
//
// 参数：out 为 `schtasks /Query /V /FO LIST` 的原文
//
// 为什么是子串匹配而不是解析字段：字段名会随系统语言变化（英文
// `Last Result`、中文「上次结果」），按名字取值等于把判据绑死在一种语言上；
// Status 一列的**取值**同样会本地化（中文机器是「正在运行」）。而这两个数值
// 跨语言不变——它们既不是时间戳也不是路径，误命中其它字段可以忽略。
//
// **两个码都要认，只认 267009 是错的。** 2026-08-19 win-b37 实测（每 5 秒采样，
// 全程 Status: Running、进程一直活着）：
//
//	[10:34:57] Last Result: 267009
//	[10:35:02] Last Result: -2147020576   ← 分钟边界，此后永远是它
//
// 少认后者的代价不是「状态少报一档」：EnsureRunning 会据此判 agentd 没跑并调
// Install，而 Install 的 `schtasks /Create /F` 是删掉重建——任务与活着的 agentd
// 就此失联，每分钟的重复触发开始真的拉起新 agentd，撞 DataDir 锁退出，一分钟
// 一个控制台窗口，Install 自己的 5s 复核也必然失败。桌面薄壳每次启动踩一遍。
//
// 明确接受的局限：拒绝码证明的是「上一次触发时有实例在跑」，而不是此刻。单元
// 每分钟触发一次，所以这个证据最多陈旧 60 秒——agentd 刚死的那不到一分钟里会
// 判成还在跑，而那一分钟正是单元自己要把它拉回来的时间，判「在跑」并不算错。
// 任务被手工 Disable 时不再有触发，拒绝码会永久停在那里；此时判据会假阳性，
// 后果是薄壳报「无法连接 agentd」而不是去重建托管——比反过来安全。
func taskIsRunning(out string) bool {
	return strings.Contains(out, schedTaskRunning) ||
		strings.Contains(out, schedTaskAlreadyRunning)
}

n_service_toUTF16LE.signature:
// toUTF16LE 把字符串编码为带 BOM 的 UTF-16 LE 字节序列。
//
// schtasks /Create /XML 要求 UTF-16LE；喂 UTF-8 会报一个与编码无关的「文件无效」
// 错误，排查时几乎不可能从报错反推出编码问题。
func toUTF16LE(s string) []byte {
	codes := utf16.Encode([]rune(s))
	b := make([]byte, 0, 2+len(codes)*2)
	b = append(b, 0xFF, 0xFE)
	for _, c := range codes {
		b = append(b, byte(c), byte(c>>8))
	}
	return b
}

n_service_windowsManager_Install.signature:
// Install 写 XML 并建任务，最后复核任务真的注册上了。
//
// 次序与其它平台一致：先清旧 → 写盘 → 建任务 → 复核。建任务失败时回滚删 XML，
// 避免留下让人工误判安装状态的孤儿文件。
func (m *windowsManager) Install(spec Spec) error {
	path, err := m.UnitPath()
	if err != nil {
		return err
	}
	usr, err := m.currentUser()
	if err != nil {
		m.log.Error("取当前用户失败，无法确定计划任务的运行身份", "cause", err)
		return fmt.Errorf("取当前用户: %w", err)
	}
	m.log.Info("安装 Windows 计划任务", "task", WindowsTaskName, "xml", path,
		"bin", spec.BinPath, "user", usr)

	if out, derr := m.run("schtasks", "/Delete", "/TN", WindowsTaskName, "/F"); derr != nil {
		m.log.Debug("删除旧任务（未装时报错属正常）", "output", strings.TrimSpace(string(out)))
	}

	if err := m.mkdirAll(windowsPathDir(path), 0o755); err != nil {
		m.log.Error("创建 XML 目录失败", "dir", windowsPathDir(path), "cause", err)
		return fmt.Errorf("创建 %s: %w", windowsPathDir(path), err)
	}
	if err := m.writeFile(path, toUTF16LE(m.taskXML(spec, usr)), 0o644); err != nil {
		m.log.Error("写计划任务 XML 失败", "path", path, "cause", err)
		return fmt.Errorf("写 XML %s: %w", path, err)
	}

	if out, cerr := m.run("schtasks", "/Create", "/TN", WindowsTaskName, "/XML", path, "/F"); cerr != nil {
		if rmErr := m.remove(path); rmErr != nil {
			m.log.Error("回滚删除 XML 失败", "path", path, "cause", rmErr)
		}
		m.log.Error("建计划任务失败，已回滚", "cause", cerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("建计划任务失败: %s（%w）", strings.TrimSpace(string(out)), cerr)
	}

	if out, qerr := m.run("schtasks", "/Query", "/TN", WindowsTaskName); qerr != nil {
		m.log.Error("任务已建但复核失败", "cause", qerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("任务已建但复核不到（检查 %s）: %w", spec.LogPath, qerr)
	}

	if out, rerr := m.run("schtasks", "/Run", "/TN", WindowsTaskName); rerr != nil {
		m.log.Error("任务已建但启动失败", "cause", rerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("任务已建但启动失败: %s（%w）", strings.TrimSpace(string(out)), rerr)
	}

	return m.waitRunning("Windows 计划任务安装完成并已运行", spec.LogPath)
}

n_service_windowsManager_Restart.signature:
// Restart 就地重启计划任务，不改动任务定义。
//
// 返回：错误——任务不存在（ErrNotInstalled）、停不下来、起不来、
// 或复核窗口内没见进程存活
//
// 注意：
//   - 先 /End 并**复核真的停下来**，再 /Run。不复核就 /Run 的话，计划任务
//     服务可能因为「上一个实例还在」而忽略这次启动请求，于是「什么都没发生」
//     被报成「已重启」
//   - 被 Stop 停住时走 Start：/Run 对停用的任务会被拒，而用户敲 restart
//     要的是它起来（与 Manager.Restart 的约定一致）
func (m *windowsManager) Restart() error {
	if err := m.ensureInstalled(); err != nil {
		return err
	}
	st, serr := m.Status()
	if serr == nil && (st.Disabled || !st.Running) {
		m.log.Info("重启时发现任务已停用或未在运行，改为启动",
			"task", WindowsTaskName, "disabled", st.Disabled, "running", st.Running)
		return m.Start()
	}
	m.log.Info("重启 Windows 计划任务", "task", WindowsTaskName)
	if out, eerr := m.run("schtasks", "/End", "/TN", WindowsTaskName); eerr != nil {
		m.log.Error("停止计划任务失败", "task", WindowsTaskName,
			"cause", eerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("停止计划任务失败: %s（%w）", strings.TrimSpace(string(out)), eerr)
	}
	if err := m.waitStopped("重启中：旧实例已停止"); err != nil {
		return err
	}
	if out, rerr := m.run("schtasks", "/Run", "/TN", WindowsTaskName); rerr != nil {
		m.log.Error("重启中启动计划任务失败", "task", WindowsTaskName,
			"cause", rerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("重启中启动计划任务失败: %s（%w）", strings.TrimSpace(string(out)), rerr)
	}
	return m.waitRunning("Windows 计划任务已重启", "")
}

n_service_windowsManager_Start.signature:
// Start 启动已安装的计划任务，并解除可能存在的停用状态。
//
// 返回：错误——任务不存在（ErrNotInstalled）、/Change 或 /Run 失败、
// 或复核窗口内没见进程存活
//
// 注意：
//   - **/Change /Enable 必须在 /Run 之前**：被 /Change /Disable 停用过的任务，
//     /Run 会直接报「任务已禁用」
//   - 不写 XML、不 /Create、不 /Delete——这正是它存在的理由：Windows 的
//     Install 会先 /Delete /F 再重建，每次换版都会把任务定义恢复成默认值，
//     用户对任务定义的修改和任务历史一并消失
func (m *windowsManager) Start() error {
	if err := m.ensureInstalled(); err != nil {
		return err
	}
	m.log.Info("启动已安装的 Windows 计划任务（不重建定义）", "task", WindowsTaskName)
	if out, cerr := m.run("schtasks", "/Change", "/TN", WindowsTaskName, "/Enable"); cerr != nil {
		m.log.Error("解除任务停用失败", "task", WindowsTaskName,
			"cause", cerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("解除任务停用失败: %s（%w）", strings.TrimSpace(string(out)), cerr)
	}
	if out, rerr := m.run("schtasks", "/Run", "/TN", WindowsTaskName); rerr != nil {
		m.log.Error("启动计划任务失败", "task", WindowsTaskName,
			"cause", rerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("启动计划任务失败: %s（%w）", strings.TrimSpace(string(out)), rerr)
	}
	return m.waitRunning("Windows 计划任务已启动", "")
}

n_service_windowsManager_Status.signature:
// Status 查询任务是否注册、在跑或被停用。
//
// **Running 判据是 schtasks 的「上次结果」等于 SCHED_S_TASK_RUNNING(267009)**，
// 不是 PID、也不是 Status 列的文本。三条理由，都是 2026-08-18 真机实测得来的：
//
//   - **schtasks 根本不给 PID。** `/Query /V /FO CSV` 的 28 个字段里没有任何一列
//     是进程号（起草时以为有，那是事实错误）。按 PID 复核在这里不可能实现
//   - **列名与 Status 列的取值都会本地化。** 英文机器是 `Status: Running`，
//     中文机器是「正在运行」；按列名或按文本匹配都会在换一台机器时静默失效。
//     而 267009 是个数值常量，跨语言不变
//   - **进程侧也区分不开。** tasklist 不给命令行，而 agentd 与操作者正在敲的
//     handoff CLI 是同一个镜像名——按镜像名判定在 Status 被 CLI 调用时必然
//     假阳性（调用者自己就是一个 handoff.exe）
//
// 由此接受一个明确的局限：本判据信任 schtasks 的运行态记录。D8 记录过它会与
// 现实分叉，但那个分叉的根因是手搓托管套了 cmd.exe（schtasks 只跟踪外层）；
// 本实现的 Command 直接指向 handoff.exe，同日实测 schtasks 报 Running 时
// 进程确实在、agentd 的 HTTP 面也确实在应答。
func (m *windowsManager) Status() (Status, error) {
	out, err := m.run("schtasks", "/Query", "/TN", WindowsTaskName, "/V", "/FO", "LIST")
	if err != nil {
		m.log.Debug("查询计划任务未命中（未装时属正常）", "output", strings.TrimSpace(string(out)))
		return Status{}, nil
	}
	s := Status{Installed: true, Detail: firstLine(string(out))}
	s.Running = taskIsRunning(string(out))
	s.Disabled = m.isDisabled()
	m.log.Debug("计划任务状态", "task", WindowsTaskName,
		"installed", s.Installed, "running", s.Running, "disabled", s.Disabled)
	return s, nil
}

n_service_windowsManager_Stop.signature:
// Stop 停止计划任务并停用它，直到显式 Start。
//
// 返回：错误——任务不存在（ErrNotInstalled）、/Change /Disable 失败、
// 或复核窗口内它仍在跑
//
// 注意：
//   - **/Change /Disable 必须在 /End 之前，顺序承重。** 任务的 TimeTrigger
//     每分钟重复触发一次（等价于 systemd 的 Restart=always）；先 /End 的话
//     它会在 60 秒内被重新拉起，「停住」根本不成立。先掐触发源，再回收进程
//   - 用 /End 而不是按镜像名杀：本实现的任务动作进程直接就是 handoff.exe
//     （不套 cmd.exe），/End 精确命中；而 agentd 与操作者正在敲的 handoff CLI
//     同镜像名，按名字杀会连自己一起杀掉
//   - agentd 若是手工起的（不由本任务拉起），/End 杀不到它——那是诚实的结果：
//     stop 停的是托管，手工起的进程不归管理器处置
func (m *windowsManager) Stop() error {
	if err := m.ensureInstalled(); err != nil {
		return err
	}
	m.log.Info("停用并停止 Windows 计划任务", "task", WindowsTaskName)
	if out, cerr := m.run("schtasks", "/Change", "/TN", WindowsTaskName, "/Disable"); cerr != nil {
		m.log.Error("停用计划任务失败", "task", WindowsTaskName,
			"cause", cerr, "output", strings.TrimSpace(string(out)))
		return fmt.Errorf("停用计划任务失败: %s（%w）", strings.TrimSpace(string(out)), cerr)
	}
	if out, eerr := m.run("schtasks", "/End", "/TN", WindowsTaskName); eerr != nil {

		m.log.Debug("停止任务报错（本来就没在跑时属正常）",
			"output", strings.TrimSpace(string(out)))
	}
	return m.waitStopped("Windows 计划任务已停止并停用")
}

n_service_windowsManager_Uninstall.signature:
// Uninstall 删任务并删 XML。本来就没装时返回 nil。
//
// 不使用 schtasks /End：它只杀外层 cmd.exe，无法保证 agentd 孙进程退出。任务
// 删除先于进程回收，避免重复触发在一分钟内把已杀进程重新拉起。
func (m *windowsManager) Uninstall() error {
	path, err := m.UnitPath()
	if err != nil {
		return err
	}
	m.log.Info("卸载 Windows 计划任务", "task", WindowsTaskName)

	if out, eerr := m.run("schtasks", "/End", "/TN", WindowsTaskName); eerr != nil {
		m.log.Debug("停止任务报错（未装或本来就没在跑时属正常）",
			"output", strings.TrimSpace(string(out)))
	}
	if out, derr := m.run("schtasks", "/Delete", "/TN", WindowsTaskName, "/F"); derr != nil {
		m.log.Debug("删除任务报错（未装时属正常）", "output", strings.TrimSpace(string(out)))
	}
	if err := m.remove(path); err != nil && !os.IsNotExist(err) {
		m.log.Error("删除计划任务 XML 失败", "path", path, "cause", err)
		return fmt.Errorf("删除 XML %s: %w", path, err)
	}
	m.log.Info("Windows 计划任务已卸载", "task", WindowsTaskName)
	return nil
}

n_service_windowsManager_UnitPath.signature:
// UnitPath 返回 XML 的落点。
func (m *windowsManager) UnitPath() (string, error) {
	if m.localAppData == "" {
		if m.log != nil {
			m.log.Error("取不到 LOCALAPPDATA，无法定位计划任务 XML 落点", "task", WindowsTaskName)
		}
		return "", fmt.Errorf("取不到 %%LOCALAPPDATA%%，无法定位计划任务 XML 的落点")
	}
	return windowsPathJoin(m.localAppData, "handoff", WindowsTaskName+".xml"), nil
}

n_service_windowsManager_ensureInstalled.signature:
// ensureInstalled 在做任何变更前确认计划任务存在。
//
// 返回：任务不存在时返回包装了 ErrNotInstalled 的错误
//
// 注意：三个生命周期方法共用它，且必须在发出任何 schtasks 变更命令之前调用
func (m *windowsManager) ensureInstalled() error {
	if out, qerr := m.run("schtasks", "/Query", "/TN", WindowsTaskName); qerr != nil {
		m.log.Error("计划任务查询不到，单元未安装",
			"task", WindowsTaskName, "cause", qerr, "output", strings.TrimSpace(string(out)))
		return errNotInstalled(WindowsTaskName)
	}
	return nil
}

n_service_windowsManager_isDisabled.signature:
// isDisabled 从任务 XML 读 Settings/Enabled，判断任务是否被显式停用。
//
// 返回：显式为 false 才算停用；查不到、查询失败、标签缺省都按未停用处理
//
// 注意：
//   - **不看 /Query /V 的「Scheduled Task State」列**：那一列会本地化
//     （英文机器 Disabled、中文机器「已禁用」），按文本判会在换一台机器时
//     静默失效。XML 里的 <Enabled> 是 schema 标签名，不随 locale 变
//   - schtasks 的 /XML 输出走 Unicode，可能是 UTF-16LE。判之前滤掉 NUL 字节
//     ——这比为一处判据引一个真解码器便宜，且 UTF-8/UTF-16LE 都能命中
func (m *windowsManager) isDisabled() bool {
	out, err := m.run("schtasks", "/Query", "/TN", WindowsTaskName, "/XML", "ONE")
	if err != nil {
		m.log.Debug("查任务 XML 失败，按未停用处理",
			"task", WindowsTaskName, "output", strings.TrimSpace(string(out)))
		return false
	}
	plain := strings.ReplaceAll(string(out), "\x00", "")
	return strings.Contains(plain, "<Enabled>false</Enabled>")
}

n_service_windowsManager_taskXML.signature:
// taskXML 渲染 Task Scheduler 的任务定义。
//
// 参数：spec 是要托管的 agentd 描述；user 是运行身份。
// 返回：XML 全文（落盘前由 toUTF16LE 转码）。
// 注意：重复触发与 IgnoreNew 一起模拟 KeepAlive，电池设置避免任务静默不启动，
// ExecutionTimeLimit 为零避免长跑 agentd 被掐掉，Command 直接指向 handoff.exe
// 以确保 schtasks 能跟踪真正的 agentd。
//
// **触发器用 BootTrigger 而不是 LogonTrigger**（08-18 真机对照后改正）。
// 执行机是无人值守的服务器，平时没有任何交互登录会话——LogonTrigger 意味着
// 机器重启后 agentd 要等到有人 RDP 登录才会起来，而那可能永远不发生。
// win-b37 上手搓的那份托管用的正是 BootTrigger + S4U，已长期实证可行。
// S4U 拿到的是无网络凭据的令牌，对 agentd 够用（它只需本地资源与出站连接）。
func (m *windowsManager) taskXML(spec Spec, user string) string {
	args := "agentd"
	if spec.ConfigPath != "" {
		args += " --config " + spec.ConfigPath
	}
	var b strings.Builder
	b.WriteString(`<?xml version="1.0" encoding="UTF-16"?>` + "\n")
	b.WriteString(`<Task version="1.2" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">` + "\n")
	b.WriteString("  <RegistrationInfo>\n    <Description>handoff agentd</Description>\n  </RegistrationInfo>\n")

	b.WriteString("  <Triggers>\n    <BootTrigger>\n      <Enabled>true</Enabled>\n    </BootTrigger>\n")
	b.WriteString("    <TimeTrigger>\n")
	b.WriteString("      <Repetition>\n        <Interval>PT1M</Interval>\n")
	b.WriteString("        <StopAtDurationEnd>false</StopAtDurationEnd>\n      </Repetition>\n")
	b.WriteString("      <StartBoundary>2020-01-01T00:00:00</StartBoundary>\n")
	b.WriteString("      <Enabled>true</Enabled>\n    </TimeTrigger>\n  </Triggers>\n")
	b.WriteString("  <Principals>\n    <Principal id=\"Author\">\n")
	b.WriteString("      <UserId>" + esc(user) + "</UserId>\n")
	b.WriteString("      <LogonType>S4U</LogonType>\n      <RunLevel>HighestAvailable</RunLevel>\n")
	b.WriteString("    </Principal>\n  </Principals>\n")
	b.WriteString("  <Settings>\n")
	b.WriteString("    <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>\n")
	b.WriteString("    <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>\n")
	b.WriteString("    <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>\n")
	b.WriteString("    <StartWhenAvailable>true</StartWhenAvailable>\n")
	b.WriteString("    <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>\n")
	b.WriteString("    <Enabled>true</Enabled>\n")
	b.WriteString("  </Settings>\n")
	b.WriteString("  <Actions Context=\"Author\">\n    <Exec>\n")
	b.WriteString("      <Command>" + esc(spec.BinPath) + "</Command>\n")
	b.WriteString("      <Arguments>" + esc(args) + "</Arguments>\n")
	b.WriteString("    </Exec>\n  </Actions>\n</Task>\n")
	return b.String()
}

n_service_windowsManager_unitReferences.signature:
func (m *windowsManager) unitReferences(exePath string) (bool, string) {
	if strings.TrimSpace(exePath) == "" {
		return false, "拿不到本进程的可执行文件路径"
	}
	out, err := m.run("schtasks", "/Query", "/TN", WindowsTaskName, "/V", "/FO", "LIST")
	if err != nil {
		return false, fmt.Sprintf("计划任务 %s 未注册（handoff service install 可装）", WindowsTaskName)
	}

	if !strings.Contains(strings.ToLower(string(out)), strings.ToLower(exePath)) {
		return false, fmt.Sprintf("计划任务 %s 登记的不是本进程的二进制（本进程 %s）", WindowsTaskName, exePath)
	}
	return true, ""
}

n_service_windowsManager_waitRunning.signature:
// waitRunning 轮询到任务真的在跑为止，供 Install 与 Start 共用。
//
// 参数：
//   - okMsg: 复核通过时打的日志文案。由调用方给而不是写死——Install 与 Start
//     是两件不同的事，走查清单按这行文案区分它们，合并会让判据失去分辨力
//   - logPath: 复核不过时提示用户去看哪个日志
//
// 复核的是「进程真的存活」而不是「注册上了/触发了」：二进制路径错、端口被占、
// 配置读不出来都会让它起来即死，那种情况下报成功，操作者会去查一个不存在的服务。
func (m *windowsManager) waitRunning(okMsg, logPath string) error {
	var last Status
	for i := 0; i < installVerifyAttempts; i++ {
		m.sleep(installVerifyInterval)
		st, serr := m.Status()
		if serr == nil && st.Running {
			m.log.Info(okMsg, "task", WindowsTaskName, "probe", i+1)
			return nil
		}
		last = st
	}
	m.log.Error("任务已启动但复核窗口内未见进程存活",
		"task", WindowsTaskName, "window", installVerifyWindow,
		"installed", last.Installed, "detail", last.Detail)

	hint := ""
	if logPath != "" {
		hint = "（检查 " + logPath + "）"
	}
	return fmt.Errorf("任务已触发，但 %s 内未复核到 agentd 进程存活%s", installVerifyWindow, hint)
}

n_service_windowsManager_waitStopped.signature:
// waitStopped 轮询到任务真的不在跑为止，供 Stop 与 Restart 共用。
//
// 参数：
//   - okMsg: 复核通过时打的日志文案。由调用方给而不是写死——Stop 与 Restart
//     是两件不同的事，走查按这行文案区分它们，合并会让判据失去分辨力
//
// 返回：复核窗口内没停下来时返回错误
//
// 注意：轮询而不是查一次——/End 只是把停止请求交给计划任务服务，
// 进程退出还要一段时间；查一次会把「还没死透」当成「停不下来」
func (m *windowsManager) waitStopped(okMsg string) error {
	var last Status
	for i := 0; i < installVerifyAttempts; i++ {
		m.sleep(installVerifyInterval)
		st, serr := m.Status()
		if serr == nil && !st.Running {
			m.log.Info(okMsg, "task", WindowsTaskName, "probe", i+1)
			return nil
		}
		last = st
	}
	m.log.Error("已请求停止但复核窗口内进程仍在",
		"task", WindowsTaskName, "window", installVerifyWindow, "detail", last.Detail)
	return fmt.Errorf("已请求停止，但 %s 内任务仍在运行", installVerifyWindow)
}

n_service_windowsPathDir.signature:
// windowsPathDir 返回 Windows 路径的父目录，供全平台测试调用注入的 mkdirAll。
func windowsPathDir(path string) string {
	i := strings.LastIndexAny(path, `/\`)
	if i < 0 {
		return "."
	}
	if i == 0 {
		return path[:1]
	}
	return path[:i]
}

n_service_windowsPathJoin.signature:
// windowsPathJoin 在所有宿主平台上都使用 Windows 分隔符。
//
// windows.go 不带 build tag，macOS/Linux 上的单测也会构造 Windows 路径；使用
// 宿主机 filepath.Join 会在测试中生成混合分隔符，掩盖实际交给 schtasks 的路径。
func windowsPathJoin(parts ...string) string {
	if len(parts) == 0 {
		return ""
	}
	out := strings.TrimRight(parts[0], `\/`)
	for _, part := range parts[1:] {
		part = strings.Trim(part, `\/`)
		if part == "" {
			continue
		}
		if out == "" {
			out = part
		} else {
			out += `\` + part
		}
	}
	return out
}

n_sessdir_CheckSockPath.signature:
// CheckSockPath 在 bind 之前检查 socket 路径长度。
//
// 参数：root 是会话根目录；id 是会话 id。
// 返回：超过 MaxSockPath 时返回可读错误，否则 nil。
//
// 注意：DataDir 可以被配置到任意深的路径下，而 bind 对超长路径只会给一句
// "invalid argument"，所以必须在 bind 之前自己检查。
func CheckSockPath(root, id string) error {
	p := SockPath(root, id)
	if len(p) > MaxSockPath {
		return fmt.Errorf("会话 socket 路径过长（%d 字节，上限 %d）：%s；请把 DataDir 换到更短的路径下", len(p), MaxSockPath, p)
	}
	return nil
}

n_sessdir_Create.signature:
// Create 建出一个会话目录（0700）。已存在时不报错。
func Create(root, id string) error {
	if err := os.MkdirAll(Dir(root, id), 0o700); err != nil {
		return fmt.Errorf("创建会话目录 %s: %w", Dir(root, id), err)
	}
	return nil
}

n_sessdir_ReadMeta.signature:
// ReadMeta 读一个会话的元数据。
//
// 返回：解析失败或文件不存在时报错，调用方据此判 StateBroken。
func ReadMeta(root, id string) (Meta, error) {
	body, err := os.ReadFile(MetaPath(root, id))
	if err != nil {
		return Meta{}, fmt.Errorf("读会话元数据 %s: %w", MetaPath(root, id), err)
	}
	var m Meta
	if err := json.Unmarshal(body, &m); err != nil {
		return Meta{}, fmt.Errorf("解析会话元数据 %s: %w", MetaPath(root, id), err)
	}
	return m, nil
}

n_sessdir_Remove.signature:
// Remove 删掉一个会话目录。不存在时不报错（幂等）。
//
// 注意：调用方必须先确认该会话已死（Scan 报 StateDead）。删掉一个还活着的会话目录
// 不会杀死它的进程，只会让它变成谁也找不到的孤儿。
func Remove(root, id string) error {
	if err := os.RemoveAll(Dir(root, id)); err != nil {
		return fmt.Errorf("删除会话目录 %s: %w", Dir(root, id), err)
	}
	return nil
}

n_sessdir_Scan.signature:
// Scan 扫描根目录下的全部会话，逐个判活。
//
// 参数：root 是会话根目录；不存在时返回空结果而不报错（首次启动就是这样）。
// 返回：每个会话一条 Entry，含三态结论；只有 IO 故障才返回错误。
//
// 注意：本函数不删任何东西。StateDead 的目录由调用方决定何时清。
func Scan(root string) ([]Entry, error) {
	items, err := os.ReadDir(root)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, fmt.Errorf("读会话根目录 %s: %w", root, err)
	}
	out := make([]Entry, 0, len(items))
	for _, it := range items {
		if !it.IsDir() {
			continue
		}
		id := it.Name()
		held, err := prochost.IsLocked(LockPath(root, id))
		if err != nil {

			out = append(out, Entry{ID: id, State: StateBroken, Err: fmt.Errorf("试锁失败: %w", err)})
			continue
		}
		if !held {
			out = append(out, Entry{ID: id, State: StateDead})
			continue
		}
		m, err := ReadMeta(root, id)
		if err != nil {
			out = append(out, Entry{ID: id, State: StateBroken, Err: err})
			continue
		}
		out = append(out, Entry{ID: id, Meta: m, State: StateLive})
	}
	return out, nil
}

n_sessdir_WriteMeta.signature:
// WriteMeta 写入元数据（0600，整体覆盖）。
//
// 参数：root 是会话根目录；m 是元数据，m.ID 决定写到哪个会话目录下。
// 返回：编码或写入失败时报错。
//
// 注意：先写临时文件再 rename。agentd 可能在任何时刻读它；直接覆写会让读者有机会
// 读到半截 JSON，而那会被判成 StateBroken。
func WriteMeta(root string, m Meta) error {
	body, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return fmt.Errorf("编码会话元数据 %s: %w", m.ID, err)
	}
	tmp := MetaPath(root, m.ID) + ".tmp"
	if err := os.WriteFile(tmp, body, 0o600); err != nil {
		return fmt.Errorf("写会话元数据 %s: %w", tmp, err)
	}
	if err := os.Rename(tmp, MetaPath(root, m.ID)); err != nil {
		return fmt.Errorf("落定会话元数据 %s: %w", MetaPath(root, m.ID), err)
	}
	return nil
}

n_skill_InSync.signature:
// InSync 判断全部存在的落点是否都与 content 一致。
//
// missing 不算不一致：那家 agent 没装，本来就不该有落点。
func InSync(sites []Site) bool {
	for _, s := range sites {
		if s.State == StateStale {
			return false
		}
	}
	return true
}

n_skill_Install.signature:
// Install 把 content 装到本机。
//
// 参数：
//   - content: SKILL.md 的全文（生产由 go:embed 注入）
//   - home: 用户 home 目录（测试注入临时目录）
//   - providers: 各家 agent 的 Skills 能力提供方
//
// 返回：
//   - 每个落点的处置结果，首项为基准副本，随后按 providers 顺序追加
//   - err: 只有基准副本写失败才返回错误——那是这个功能的地基；
//     单个 agent 落点失败记进 Site.Note 继续，不因为一家没装成就全盘失败
func Install(content, home string, providers []executor.Skills) ([]Site, error) {
	base := BasePath(home)
	if err := os.MkdirAll(base, 0o755); err != nil {
		slog.Default().Error("创建基准副本目录失败", "path", base, "cause", err)
		return nil, fmt.Errorf("创建基准副本目录 %s: %w", base, err)
	}
	target := filepath.Join(base, fileName)
	if err := os.WriteFile(target, []byte(content), 0o644); err != nil {
		slog.Default().Error("写基准副本失败", "path", target, "cause", err)
		return nil, fmt.Errorf("写基准副本 %s: %w", target, err)
	}
	sites := []Site{{Path: target, State: StateInstalled}}
	slog.Default().Info("skill 基准副本已写入", "path", target)

	ctx := context.Background()
	for _, p := range providers {
		if p == nil {
			continue
		}
		got, err := p.Install(ctx, executor.SkillInstallReq{Home: home, Content: content})
		if err != nil {

			sites = append(sites, Site{Path: "", State: StateSkipped, Note: err.Error()})
			slog.Default().Warn("skill 提供方安装失败", "cause", err)
			continue
		}
		for _, s := range got {
			sites = append(sites, Site{Path: s.Path, State: s.State, Note: s.Note})
			if s.State == StateSkipped {
				slog.Default().Warn("skill 落点跳过", "path", s.Path, "reason", s.Note)
			} else {
				slog.Default().Info("skill 落点已写入", "path", s.Path, "state", s.State)
			}
		}
	}
	return sites, nil
}

n_skill_Status.signature:
// Status 报告每个落点的一致性。
//
// 参数：
//   - content: 当前二进制内嵌的 SKILL.md 全文，作为比对基准
//   - home: 用户 home 目录
//   - providers: 各家 agent 的 Skills 能力提供方
//
// 返回：
//   - 每个落点的状态，顺序与 Install 一致
//   - err: 恒为 nil
func Status(content, home string, providers []executor.Skills) ([]Site, error) {
	want := sha256.Sum256([]byte(content))
	check := func(p string) Site {
		b, err := os.ReadFile(p)
		switch {
		case errors.Is(err, os.ErrNotExist):
			return Site{Path: p, State: StateMissing}
		case err != nil:
			return Site{Path: p, State: StateMissing, Note: "读取失败: " + err.Error()}
		}
		got := sha256.Sum256(b)
		if got == want {
			return Site{Path: p, State: StateInSync}
		}
		return Site{Path: p, State: StateStale}
	}

	sites := []Site{check(filepath.Join(BasePath(home), fileName))}
	ctx := context.Background()
	for _, p := range providers {
		if p == nil {
			continue
		}
		got, err := p.Inspect(ctx, home)
		if err != nil {
			sites = append(sites, Site{Path: "", State: StateMissing, Note: err.Error()})
			continue
		}
		for _, s := range got {
			if s.State == StateMissing || s.State == StateSkipped {
				sites = append(sites, Site{Path: s.Path, State: s.State, Note: s.Note})
				continue
			}
			sites = append(sites, check(s.Path))
		}
	}
	return sites, nil
}

n_store_HashCredential.signature:
// HashCredential 计算凭据明文的 SHA-256 十六进制串。
//
// 参数：
//   - plain: 凭据明文（ticket 或 cookie 值）
//
// 返回：
//   - 64 字符的小写十六进制哈希
//
// 注意：
//   - 为什么不加盐、不用 bcrypt：输入是 256 位高熵随机串（不是人选的口令），
//     没有字典攻击面；而查表必须是 O(1) 精确匹配，加盐会退化成逐行比对
func HashCredential(plain string) string {
	sum := sha256.Sum256([]byte(plain))
	return hex.EncodeToString(sum[:])
}

n_store_Store_ActiveTasksByRepoPath.signature:
// ActiveTasksByRepoPath 返回仓库路径为 repoPath 的全部非终态任务。
//
// 参数：
//   - repoPath: 仓库绝对路径；空串返回空切片
//
// 注意：
//   - 与 ActiveTasksByWorkDir 的区别：那个按**工作目录**判定（managed worktree
//     各不相同），本方法按**仓库**判定——注销一条位置会影响这个项目下的所有
//     任务，包括从它长出来的 managed worktree
//   - 原属 repos.go（B62 迁移后 repos 表删除），项目注销的占用校验仍在用它
func (s *Store) ActiveTasksByRepoPath(repoPath string) ([]proto.Task, error) {
	if repoPath == "" {
		return nil, nil
	}
	placeholders := make([]string, len(proto.TerminalStates))
	args := []any{repoPath}
	for i, st := range proto.TerminalStates {
		placeholders[i] = "?"
		args = append(args, string(st))
	}
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT `+taskColumns+` FROM tasks
WHERE repo_path = ? AND state NOT IN (`+strings.Join(placeholders, ", ")+`)
ORDER BY created_at DESC`, args...)
	if err != nil {
		return nil, fmt.Errorf("查询仓库 %s 的活跃任务: %w", repoPath, err)
	}
	defer rows.Close()
	var tasks []proto.Task
	for rows.Next() {
		task, err := scanTaskRow(rows)
		if err != nil {
			return nil, fmt.Errorf("读取活跃任务行: %w", err)
		}
		tasks = append(tasks, task)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历活跃任务: %w", err)
	}
	return tasks, nil
}

n_store_Store_ActiveTasksByWorkDir.signature:
// ActiveTasksByWorkDir 返回工作目录为 workDir 的全部非终态任务。
//
// 参数：
//   - workDir: 工作目录绝对路径（原地模式即仓库路径）；空串返回空切片
//
// 返回：
//   - 非终态任务切片（可能为空），按创建时间倒序
//   - 查询失败返回错误（调用方按「查不出来就保守拒发」处置）
//
// 注意：
//   - 终态清单取自 proto.TerminalStates，避免与状态机定义漂移
//   - 空 workDir 直接返回空切片：不查是刻意的，managed 模式每任务一棵新树，
//     天然不冲突，不需要这个判据
//   - WHERE 里对空 work_dir 的兜底是给**旧库历史行**的：早期原地模式的
//     work_dir 存空串（proto.Task.Workdir() 的回退就是为它们写的），那些任务
//     同样占着仓库。新派发的任务 work_dir 一定是满的
func (s *Store) ActiveTasksByWorkDir(workDir string) ([]proto.Task, error) {
	if workDir == "" {
		return nil, nil
	}
	placeholders := make([]string, len(proto.TerminalStates))
	args := []any{workDir, workDir}
	for i, st := range proto.TerminalStates {
		placeholders[i] = "?"
		args = append(args, string(st))
	}
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT `+taskColumns+` FROM tasks
WHERE (work_dir = ? OR (work_dir = '' AND repo_path = ?))
  AND state NOT IN (`+strings.Join(placeholders, ", ")+`)
ORDER BY created_at DESC`, args...)
	if err != nil {
		return nil, fmt.Errorf("查询工作目录 %s 的活跃任务: %w", workDir, err)
	}
	defer rows.Close()
	var tasks []proto.Task
	for rows.Next() {
		task, err := scanTaskRow(rows)
		if err != nil {
			return nil, fmt.Errorf("读取活跃任务行: %w", err)
		}
		tasks = append(tasks, task)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历活跃任务: %w", err)
	}
	if len(tasks) > 0 {
		log().Info("工作目录上存在活跃任务", "workdir", workDir, "count", len(tasks))
	}
	return tasks, nil
}

n_store_Store_AnswerTicket.signature:
// AnswerTicket 回答指定工单。若答案已存在且相同则幂等返回 nil；若不同或工单已作废则返回 ErrTicketConflict。
func (s *Store) AnswerTicket(id, answer string) error {
	_, err := s.AnswerTicketApplied(id, answer)
	return err
}

n_store_Store_AnswerTicketApplied.signature:
// AnswerTicketApplied 回答指定工单，并返回本次是否真正写入新答案。
// applied=true：本次将答案从 NULL 更新为 answer；
// applied=false 且 err=nil：工单已有相同答案（幂等）；
// err 非 nil：工单不存在（ErrNotFound）或已有不同答案/已作废（ErrTicketConflict）。
func (s *Store) AnswerTicketApplied(id, answer string) (applied bool, err error) {
	res, err := s.db.ExecContext(context.Background(),
		"UPDATE tickets SET answer = ?, answered_at = ? WHERE id = ? AND answer IS NULL",
		answer, fmtTime(time.Now()), id)
	if err != nil {
		return false, fmt.Errorf("回答工单 %s: %w", id, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("读取工单影响行数: %w", err)
	}
	if n == 1 {
		s.touchTaskUpdatedAt(id)
		return true, nil
	}
	tk, gerr := s.GetTicket(id)
	if gerr != nil {
		return false, ErrNotFound
	}
	if tk.Answer == nil {
		return false, ErrNotFound
	}
	if *tk.Answer == VoidAnswer {
		return false, fmt.Errorf("%w: 工单已作废", ErrTicketConflict)
	}
	if *tk.Answer == answer {
		return false, nil
	}
	return false, fmt.Errorf("%w", ErrTicketConflict)
}

n_store_Store_AppendEvent.signature:
// AppendEvent 为任务追加一条事件，返回落库后带自增 seq 的完整事件。
//
// 参数：
//   - taskID: 所属任务 ID（与任务表无外键约束，任务不存在时也可追加）
//   - typ: 事件类型
//   - payload: 任意可 JSON 序列化的值，序列化后存入 payload 列
//
// 返回：
//   - 带全局自增 seq 的事件记录
//
// 注意：
//   - seq 由 AUTOINCREMENT 全局分配，跨任务单调递增，可作为全局时间轴排序依据
func (s *Store) AppendEvent(taskID string, typ proto.EventType, payload any) (proto.Event, error) {
	b, err := json.Marshal(payload)
	if err != nil {
		return proto.Event{}, fmt.Errorf("序列化事件 payload: %w", err)
	}
	now := fmtTime(time.Now())
	res, err := s.db.ExecContext(context.Background(),
		"INSERT INTO events (task_id, type, payload, created_at) VALUES (?, ?, ?, ?)",
		taskID, typ, string(b), now)
	if err != nil {
		return proto.Event{}, fmt.Errorf("写入事件: %w", err)
	}
	seq, err := res.LastInsertId()
	if err != nil {
		return proto.Event{}, fmt.Errorf("获取事件 seq: %w", err)
	}
	evt := proto.Event{Seq: seq, TaskID: taskID, Type: typ,
		Payload:	json.RawMessage(b), CreatedAt: parseTime(now)}

	s.fireEventHook(evt)
	s.signalEventDoorbell(evt.TaskID)
	return evt, nil
}

n_store_Store_AppendMirrorEvent.signature:
// AppendMirrorEvent 幂等追加一条远端事件副本。
//
// 参数：
//   - taskID: 所属任务 ID
//   - ev: 事件（Seq 为**远端库**的自增 seq，原值保留）
//
// 返回：
//   - inserted: true=本次真的插入了新行；false=该 (task_id, seq) 已存在
//     （重连补拉重复到达），本次为 no-op
//   - err: 数据库错误
//
// 注意：
//   - INSERT OR IGNORE 的幂等语义就是「重连补拉天然去重」：远端是权威，本机
//     不重编号，重连凭 seq 续拉即可
func (s *Store) AppendMirrorEvent(taskID string, ev proto.Event) (inserted bool, err error) {
	res, err := s.db.ExecContext(context.Background(), `
INSERT OR IGNORE INTO mirror_events (task_id, seq, type, payload, created_at)
VALUES (?, ?, ?, ?, ?)`,
		taskID, ev.Seq, string(ev.Type), string(ev.Payload), fmtTime(ev.CreatedAt))
	if err != nil {
		return false, fmt.Errorf("追加镜像事件 %s/%d: %w", taskID, ev.Seq, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("读取镜像事件影响行数: %w", err)
	}
	return n == 1, nil
}

n_store_Store_Close.signature:
// Close 关闭数据库连接池。
//
// 注意：
//   - 关闭后 Store 不可再使用；sql.DB.Close 幂等，重复调用返回 nil
func (s *Store) Close() error {
	return s.db.Close()
}

n_store_Store_ClosePreview.signature:
// ClosePreview conditionally closes a row and returns the full row plus whether
// this call performed the transition. The read/update is one transaction so
// only the winner may publish preview.closed; repeated close is an idempotent
// no-op with the already-closed row.
func (s *Store) ClosePreview(id string, at time.Time) (PreviewRecord, bool, error) {
	tx, err := s.db.BeginTx(context.Background(), nil)
	if err != nil {
		return PreviewRecord{}, false, fmt.Errorf("开始关闭预览会话 %s 事务: %w", id, err)
	}
	defer func() { _ = tx.Rollback() }()

	row := tx.QueryRowContext(context.Background(),
		`SELECT `+previewColumns+` FROM preview_sessions WHERE id = ?`, id)
	preview, err := scanPreviewRow(row)
	if errors.Is(err, sql.ErrNoRows) {
		return PreviewRecord{}, false, fmt.Errorf("预览会话 %s: %w", id, ErrNotFound)
	}
	if err != nil {
		return PreviewRecord{}, false, fmt.Errorf("读取待关闭预览会话 %s: %w", id, err)
	}
	if preview.ClosedAt != nil {
		if err := tx.Commit(); err != nil {
			return PreviewRecord{}, false, fmt.Errorf("提交重复关闭预览会话 %s: %w", id, err)
		}
		return preview, false, nil
	}
	closedAt := at.UTC()
	result, err := tx.ExecContext(context.Background(),
		`UPDATE preview_sessions SET closed_at = ? WHERE id = ? AND closed_at IS NULL`, fmtTime(closedAt), id)
	if err != nil {
		return PreviewRecord{}, false, fmt.Errorf("关闭预览会话 %s: %w", id, err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return PreviewRecord{}, false, fmt.Errorf("读取关闭预览会话 %s 影响行数: %w", id, err)
	}
	if affected != 1 {
		if err := tx.Commit(); err != nil {
			return PreviewRecord{}, false, fmt.Errorf("提交并发关闭预览会话 %s: %w", id, err)
		}
		return preview, false, nil
	}
	preview.ClosedAt = &closedAt
	if err := tx.Commit(); err != nil {
		return PreviewRecord{}, false, fmt.Errorf("提交关闭预览会话 %s: %w", id, err)
	}
	return preview, true, nil
}

n_store_Store_ConsumeAuthTicket.signature:
// ConsumeAuthTicket 原子认领一张未消费的 ticket，并返回它的设备名与过期时刻。
//
// 参数：
//   - hash: ticket 明文的 SHA-256
//   - now: 认领时刻，写入 consumed_at
//
// 返回：
//   - deviceName / expiresAt: 该 ticket 的登记信息
//   - ErrNotFound: 不存在或已被消费（对调用方是同一个结论：这张票不能用）
//
// 注意：
//   - 一次性**由 SQL 条件 UPDATE 的原子性保证**，不靠「先查后改」——后者在并发下
//     会让同一张 ticket 换出两个会话
//   - **过期不在这里判**：返回 expiresAt 交给调用方比较。原因是本表的时间以
//     RFC3339Nano 文本存储，Go 的格式化会裁掉尾部零，导致「整秒」与「带小数秒」
//     的两个时刻在 SQLite 里按字典序比较时次序反转（`.` 的码位小于 `Z`）。
//     把比较放到 Go 侧用 time.Time 做，才是无坑的
func (s *Store) ConsumeAuthTicket(hash string, now time.Time) (string, time.Time, error) {
	res, err := s.db.ExecContext(context.Background(), `
UPDATE auth_tickets SET consumed_at = ? WHERE id = ? AND consumed_at IS NULL`,
		fmtTime(now), hash)
	if err != nil {
		return "", time.Time{}, fmt.Errorf("消费 ticket: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return "", time.Time{}, fmt.Errorf("读取 ticket 影响行数: %w", err)
	}
	if n != 1 {
		return "", time.Time{}, ErrNotFound
	}
	var deviceName, expiresAt string
	if err := s.db.QueryRowContext(context.Background(),
		"SELECT device_name, expires_at FROM auth_tickets WHERE id = ?", hash).
		Scan(&deviceName, &expiresAt); err != nil {
		return "", time.Time{}, fmt.Errorf("读取 ticket 登记信息: %w", err)
	}
	return deviceName, parseTime(expiresAt), nil
}

n_store_Store_CountEvents.signature:
// CountEvents 统计任务在 (afterSeq, throughSeq] 区间内的事件条数。
//
// 参数：
//   - taskID: 任务 ID
//   - afterSeq: 区间下界（不含）
//   - throughSeq: 区间上界（含）
//
// 返回：
//   - 区间内事件条数
//   - 数据库错误
//
// 注意：
//   - 用途是 WS 重放截断后的缺口核对：seq 由 AUTOINCREMENT 全局分配，跨任务
//     交错，单任务的 seq **不连续**，因此无法靠「seq 是否逐格衔接」判断缺口，
//     只能按区间实际条数核对
func (s *Store) CountEvents(taskID string, afterSeq, throughSeq int64) (int, error) {
	var n int
	err := s.db.QueryRowContext(context.Background(),
		"SELECT COUNT(*) FROM events WHERE task_id = ? AND seq > ? AND seq <= ?",
		taskID, afterSeq, throughSeq).Scan(&n)
	if err != nil {
		return 0, fmt.Errorf("统计任务 %s 事件区间 (%d, %d]: %w", taskID, afterSeq, throughSeq, err)
	}
	return n, nil
}

n_store_Store_CreateAuthTicket.signature:
// CreateAuthTicket 落库一张一次性 ticket。
//
// 参数：
//   - hash: ticket 明文的 SHA-256（由调用方算好；本层不接触明文）
//   - deviceName: 签发时登记的设备名，纯展示
//   - createdAt / expiresAt: 签发与过期时刻
//
// 返回：
//   - 数据库错误；重复 hash 会因主键冲突报错（概率上不可能，视为真故障）
func (s *Store) CreateAuthTicket(hash, deviceName string, createdAt, expiresAt time.Time) error {
	if _, err := s.db.ExecContext(context.Background(), `
INSERT INTO auth_tickets (id, device_name, created_at, expires_at, consumed_at)
VALUES (?, ?, ?, ?, NULL)`,
		hash, deviceName, fmtTime(createdAt), fmtTime(expiresAt)); err != nil {
		return fmt.Errorf("写入 ticket: %w", err)
	}
	return nil
}

n_store_Store_CreateProjectLocation.signature:
// CreateProjectLocation 写入一条项目位置。
//
// 参数：
//   - loc: 位置条目；ProjectID/Name/Path/OriginURL 必须非空，CreatedAt 由调用方给定
//
// 返回：
//   - 错误：项目/名字/路径任一已存在时返回包装 ErrProjectDuplicate 的错误；其余为写库故障
func (s *Store) CreateProjectLocation(loc *proto.ProjectLocation) error {
	_, err := s.db.ExecContext(context.Background(),
		`INSERT INTO project_locations (project_id, name, path, origin_url, created_at)
VALUES (?, ?, ?, ?, ?)`,
		loc.ProjectID, loc.Name, loc.Path, loc.OriginURL, fmtTime(loc.CreatedAt))
	if err != nil {

		if strings.Contains(err.Error(), "UNIQUE constraint failed") ||
			strings.Contains(err.Error(), "PRIMARY KEY constraint failed") {
			return fmt.Errorf("%w: project_id=%s name=%s path=%s: %v",
				ErrProjectDuplicate, loc.ProjectID, loc.Name, loc.Path, err)
		}
		return fmt.Errorf("写入项目位置 %s: %w", loc.Name, err)
	}
	return nil
}

n_store_Store_CreateSession.signature:
// CreateSession 落库一个新会话。
//
// 参数：
//   - sess: 会话数据；ID 与 TokenHash 必须非空，RevokedAt 被忽略（新会话必未吊销）
//
// 返回：
//   - 数据库错误
func (s *Store) CreateSession(sess *Session) error {
	if _, err := s.db.ExecContext(context.Background(), `
INSERT INTO sessions (id, token_hash, device_name, created_at, expires_at, last_seen_at, revoked_at)
VALUES (?, ?, ?, ?, ?, ?, NULL)`,
		sess.ID, sess.TokenHash, sess.DeviceName,
		fmtTime(sess.CreatedAt), fmtTime(sess.ExpiresAt), fmtTime(sess.LastSeenAt)); err != nil {
		return fmt.Errorf("写入会话 %s: %w", sess.ID, err)
	}
	return nil
}

n_store_Store_CreateTask.signature:
// CreateTask 写入一个新任务。Carrier 与 HomeDir 同款只写入创建时的身份快照。
//
// 参数：
//   - t: 任务数据；ID 必须非空且唯一，重复 ID 返回底层主键冲突错误
//
// 注意：
//   - 状态迁移合法性由 UpdateTaskState 校验，此处仅原样入库，不含业务规则
func (s *Store) CreateTask(t *proto.Task) error {
	_, err := s.db.ExecContext(context.Background(), `
INSERT INTO tasks (id, target, repo_path, home_dir, carrier, squad, branch, plan_path, plan_summary, executor_session, state, created_at, updated_at,
  name, executor, model, work_dir, worktree_managed, base_commit, base_ahead, repo_dirty_count, repo_dirty_files, discipline_name, discipline_version)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		t.ID, t.Target, t.RepoPath, t.HomeDir, t.Carrier, t.Squad, t.Branch, t.PlanPath, t.PlanSummary,
		t.ExecutorSession, t.State, fmtTime(t.CreatedAt), fmtTime(t.UpdatedAt),
		t.Name, t.Executor, t.Model, t.WorkDir, boolToInt(t.WorktreeManaged),
		t.BaseCommit, t.BaseAhead, t.RepoDirtyCount, t.RepoDirtyFiles, t.DisciplineName,
		t.DisciplineVersion)
	if err != nil {
		return fmt.Errorf("写入任务 %s: %w", t.ID, err)
	}
	return nil
}

n_store_Store_CreateTicket.signature:
// CreateTicket 幂等创建工单：同 id 重复调用不报错，第二次起 created 为 false。
//
// 参数：
//   - tk: 工单数据；ID 必须非空
//
// 返回：
//   - created: true 表示本次为首次创建（id 此前不存在）
//   - err: 数据库错误
//
// 注意：
//   - 通过 INSERT OR IGNORE 实现幂等，与 upsert 不同：已存在时保留旧数据，不覆盖
//   - answer/answered_at 一律由 AnswerTicket 写入，入参中的值被忽略
func (s *Store) CreateTicket(tk *proto.Ticket) (bool, error) {
	res, err := s.db.ExecContext(context.Background(), `
INSERT OR IGNORE INTO tickets (id, task_id, kind, request, answer, created_at, answered_at, fingerprint)
VALUES (?, ?, ?, ?, NULL, ?, NULL, ?)`,
		tk.ID, tk.TaskID, tk.Kind, string(tk.Request), fmtTime(tk.CreatedAt), tk.Fingerprint)
	if err != nil {
		return false, fmt.Errorf("写入工单 %s: %w", tk.ID, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("读取工单影响行数: %w", err)
	}
	return n == 1, nil
}

n_store_Store_DeleteMirrorTask.signature:
// DeleteMirrorTask 删除一条镜像任务及其全部镜像事件。
//
// 返回：
//   - 被删除的事件条数（任务快照本身不存在时不报错，返回 0）
//
// 注意：
//   - 这是本包唯一的破坏性镜像操作，成功打 Info（task_id + 事件条数）
//   - 两个删放在一个事务里：镜像任务是复制品，删除必须原子，不能留
//     「快照没了、事件还在」的半截
func (s *Store) DeleteMirrorTask(taskID string) (int, error) {
	ctx := context.Background()
	tx, err := s.db.Begin()
	if err != nil {
		return 0, fmt.Errorf("开启删除镜像任务事务: %w", err)
	}
	defer tx.Rollback()

	res, err := tx.ExecContext(ctx, "DELETE FROM mirror_events WHERE task_id = ?", taskID)
	if err != nil {
		return 0, fmt.Errorf("删除镜像事件 %s: %w", taskID, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("读取镜像事件删除行数: %w", err)
	}
	if _, err := tx.ExecContext(ctx, "DELETE FROM mirror_tasks WHERE task_id = ?", taskID); err != nil {
		return 0, fmt.Errorf("删除镜像任务 %s: %w", taskID, err)
	}
	if err := tx.Commit(); err != nil {
		return 0, fmt.Errorf("提交删除镜像任务事务: %w", err)
	}
	log().Info("镜像任务已删除", "task_id", taskID, "events_removed", n)
	return int(n), nil
}

n_store_Store_DeleteProjectLocation.signature:
// DeleteProjectLocation 删除一条位置。
//
// 返回：
//   - 错误：位置不存在时返回 ErrNotFound（而非静默成功——调用方需要知道自己删错了名字）
//
// 注意：
//   - 只删登记，**不动磁盘上的仓库**
func (s *Store) DeleteProjectLocation(name string) error {
	res, err := s.db.ExecContext(context.Background(),
		`DELETE FROM project_locations WHERE name = ?`, name)
	if err != nil {
		return fmt.Errorf("删除项目位置 %s: %w", name, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("删除项目位置 %s 后取影响行数: %w", name, err)
	}
	if n == 0 {
		return fmt.Errorf("项目 %s: %w", name, ErrNotFound)
	}
	return nil
}

n_store_Store_DeleteWorkbenchBase.signature:
// DeleteWorkbenchBase 删除一行基准状态。行不存在时是空操作，不报错。
//
// 幂等的理由：前端在「一个目录的 tab 全关光了」时发删除，而它可能因为去抖
// 合并发两次。让第二次报错只会在控制台留下一条无意义的红。
func (s *Store) DeleteWorkbenchBase(key string) error {
	if _, err := s.db.ExecContext(context.Background(),
		`DELETE FROM workbench_bases WHERE base_key = ?`, key); err != nil {
		return fmt.Errorf("删除工作台基准行 %s: %w", key, err)
	}
	return nil
}

n_store_Store_DeleteWorkbenchSingleton.signature:
// DeleteWorkbenchSingleton 删除一个单例。不存在时是空操作，不报错（同 DeleteWorkbenchBase）。
func (s *Store) DeleteWorkbenchSingleton(key string) error {
	if _, err := s.db.ExecContext(context.Background(),
		`DELETE FROM workbench_singletons WHERE key = ?`, key); err != nil {
		return fmt.Errorf("删除工作台单例 %s: %w", key, err)
	}
	return nil
}

n_store_Store_EventsFrom.signature:
// EventsFrom 返回任务 taskID 在 seq 之后的事件，按 seq 升序，最多 limit 条。
//
// 语义（重要）：事件数超过 limit 时返回**最新**的 limit 条（截断掉最旧的），
// 保证读到的始终是「离 now 最近」的窗口——attach 的 recent_events 依赖
// 「最新窗口」，若返回最旧的 limit 条，>limit 的积压会让新事件（如 completed）
// 永远读不到，违反「不丢新事件」。
//
// 注意：**WS 重放不得使用本方法**——截断最旧会让客户端 cursor 越过缺口，缺口
// 永不补齐；WS 重放请用 EventsFromAsc（截断尾部、可续拉）。
//
// 参数：
//   - taskID: 任务 ID
//   - fromSeq: 起始 seq（不含），传 0 表示从头
//   - limit: 返回条数上限
//
// 注意：
//   - 借助 idx_events_task(task_id, seq) 索引加速按任务的时间线扫描
func (s *Store) EventsFrom(taskID string, fromSeq int64, limit int) ([]proto.Event, error) {

	rows, err := s.db.QueryContext(context.Background(), `
SELECT seq, task_id, type, payload, created_at FROM events
WHERE task_id = ? AND seq > ? ORDER BY seq DESC LIMIT ?`, taskID, fromSeq, limit)
	if err != nil {
		return nil, fmt.Errorf("查询事件: %w", err)
	}
	defer rows.Close()
	var events []proto.Event
	for rows.Next() {
		var (
			e		proto.Event
			payload		string
			createdAt	string
		)
		if err := rows.Scan(&e.Seq, &e.TaskID, &e.Type, &payload, &createdAt); err != nil {
			return nil, fmt.Errorf("读取事件行: %w", err)
		}
		e.Payload = json.RawMessage(payload)
		e.CreatedAt = parseTime(createdAt)
		events = append(events, e)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历事件: %w", err)
	}
	for i, j := 0, len(events)-1; i < j; i, j = i+1, j-1 {
		events[i], events[j] = events[j], events[i]
	}
	return events, nil
}

n_store_Store_EventsFromAsc.signature:
// EventsFromAsc 返回任务 taskID 在 fromSeq 之后的事件，按 seq 升序，最多 limit 条。
//
// 与 EventsFrom（最新窗口）语义相反（重要）：事件数超过 limit 时截断**窗口尾部**、
// 保留最旧的 limit 条——客户端 cursor 只前进到「确实收到」的最后一条，被截掉的
// 尾部缺口可凭更大 from_seq 重连续拉，缺口永远可补齐；EventsFrom 截最旧会让
// cursor 越过缺口，缺口永久丢失（见该方法的注意）。
//
// 用途：WS 重放（server.handleEvents）必须用本方法从头补起。
//
// 参数：
//   - taskID: 任务 ID
//   - fromSeq: 起始 seq（不含），传 0 表示从头
//   - limit: 返回条数上限
//
// 注意：
//   - 借助 idx_events_task(task_id, seq) 索引加速按任务的时间线扫描
func (s *Store) EventsFromAsc(taskID string, fromSeq int64, limit int) ([]proto.Event, error) {
	rows, err := s.db.QueryContext(context.Background(), `
SELECT seq, task_id, type, payload, created_at FROM events
WHERE task_id = ? AND seq > ? ORDER BY seq ASC LIMIT ?`, taskID, fromSeq, limit)
	if err != nil {
		return nil, fmt.Errorf("查询事件: %w", err)
	}
	defer rows.Close()
	var events []proto.Event
	for rows.Next() {
		var (
			e		proto.Event
			payload		string
			createdAt	string
		)
		if err := rows.Scan(&e.Seq, &e.TaskID, &e.Type, &payload, &createdAt); err != nil {
			return nil, fmt.Errorf("读取事件行: %w", err)
		}
		e.Payload = json.RawMessage(payload)
		e.CreatedAt = parseTime(createdAt)
		events = append(events, e)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历事件: %w", err)
	}
	return events, nil
}

n_store_Store_ExpirePreviews.signature:
// ExpirePreviews conditionally closes every idle row and returns only rows
// transitioned by this call. It uses the same transaction/conditional update
// rule as ClosePreview, preventing duplicate close events across sweepers.
func (s *Store) ExpirePreviews(now time.Time) ([]PreviewRecord, error) {
	now = now.UTC()
	tx, err := s.db.BeginTx(context.Background(), nil)
	if err != nil {
		return nil, fmt.Errorf("开始过期预览会话事务: %w", err)
	}
	defer func() { _ = tx.Rollback() }()
	rows, err := tx.QueryContext(context.Background(),
		`SELECT `+previewColumns+` FROM preview_sessions WHERE closed_at IS NULL`)
	if err != nil {
		return nil, fmt.Errorf("查询待过期预览会话: %w", err)
	}
	var candidates []PreviewRecord
	for rows.Next() {
		row, err := scanPreviewRow(rows)
		if err != nil {
			_ = rows.Close()
			return nil, fmt.Errorf("读取待过期预览会话: %w", err)
		}
		if previewExpired(row, now) {
			candidates = append(candidates, row)
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return nil, fmt.Errorf("遍历待过期预览会话: %w", err)
	}
	if err := rows.Close(); err != nil {
		return nil, fmt.Errorf("关闭待过期预览会话查询: %w", err)
	}
	expired := make([]PreviewRecord, 0, len(candidates))
	for _, candidate := range candidates {
		closedAt := now
		result, err := tx.ExecContext(context.Background(),
			`UPDATE preview_sessions SET closed_at = ? WHERE id = ? AND closed_at IS NULL`,
			fmtTime(closedAt), candidate.Session.ID)
		if err != nil {
			return nil, fmt.Errorf("过期预览会话 %s: %w", candidate.Session.ID, err)
		}
		affected, err := result.RowsAffected()
		if err != nil {
			return nil, fmt.Errorf("读取过期预览会话 %s 影响行数: %w", candidate.Session.ID, err)
		}
		if affected == 1 {
			candidate.ClosedAt = &closedAt
			expired = append(expired, candidate)
		}
	}
	if err := tx.Commit(); err != nil {
		return nil, fmt.Errorf("提交过期预览会话: %w", err)
	}
	return expired, nil
}

n_store_Store_FindReusableGrant.signature:
// FindReusableGrant 查同任务、同指纹、已被协调者批准且已送达的 gate 工单。
//
// 参数：
//   - taskID: 任务 id（复用严格限制在任务内，见 spec §3.4）
//   - fingerprint: 权限描述全文的 sha256；空串直接返回无匹配
//
// 返回：
//   - 命中时返回该工单；无匹配返回 (nil, nil)；查询出错返回错误
//
// 注意：
//   - answer 必须**严格等于** "allow"——gate 的翻译规则就是严格相等，
//     这里放宽（如 LIKE 'allow%'）会让 "allowed once, then never" 之类的
//     人工笔误变成一张长期通行证
//   - delivered_at 必须非空：应答落库但中继失败的工单不构成有效先例，
//     executor 侧那次请求根本没收到批准
func (s *Store) FindReusableGrant(taskID, fingerprint string) (*proto.Ticket, error) {
	if fingerprint == "" {
		return nil, nil
	}
	var id string
	err := s.db.QueryRowContext(context.Background(), `
SELECT id FROM tickets
WHERE task_id = ? AND fingerprint = ? AND kind = 'gate'
  AND answer = 'allow' AND delivered_at IS NOT NULL
ORDER BY created_at DESC LIMIT 1`, taskID, fingerprint).Scan(&id)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, fmt.Errorf("查询任务 %s 可复用裁决: %w", taskID, err)
	}
	return s.GetTicket(id)
}

n_store_Store_GetPreview.signature:
// GetPreview reads one complete owner preview row.
// ErrNotFound is returned when id does not exist; closed rows are still
// readable because close/expire need to return the complete event payload.
func (s *Store) GetPreview(id string) (PreviewRecord, error) {
	row := s.db.QueryRowContext(context.Background(),
		`SELECT `+previewColumns+` FROM preview_sessions WHERE id = ?`, id)
	preview, err := scanPreviewRow(row)
	if errors.Is(err, sql.ErrNoRows) {
		return PreviewRecord{}, fmt.Errorf("预览会话 %s: %w", id, ErrNotFound)
	}
	if err != nil {
		return PreviewRecord{}, fmt.Errorf("读取预览会话 %s: %w", id, err)
	}
	return preview, nil
}

n_store_Store_GetProjectLocationByName.signature:
// GetProjectLocationByName 按引用名查询单条位置。
