n_store_Store_GetTask.signature:
// GetTask 按 id 读取任务；不存在返回 ErrNotFound。
//
// 参数：
//   - id: 任务 ID
//
// 返回：
//   - 任务数据；不存在时返回 ErrNotFound
func (s *Store) GetTask(id string) (*proto.Task, error) {
	row := s.db.QueryRowContext(context.Background(),
		`SELECT `+taskColumns+` FROM tasks WHERE id = ?`, id)
	task, err := scanTaskRow(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("读取任务 %s: %w", id, err)
	}

	cum, err := s.TaskCumulative(id)
	if err != nil {
		return nil, err
	}
	task.Cumulative = cum

	tm, err := s.TaskTiming(id)
	if err != nil {
		return nil, err
	}
	task.Timing = tm
	return &task, nil
}

n_store_Store_GetTicket.signature:
// GetTicket 按 id 读取工单；不存在返回 ErrNotFound。
//
// 参数：
//   - id: 工单 ID
//
// 返回：
//   - 工单数据；不存在时返回 ErrNotFound
func (s *Store) GetTicket(id string) (*proto.Ticket, error) {
	var (
		tk		proto.Ticket
		request		string
		answer		sql.NullString
		answeredAt	sql.NullString
		deliveredAt	sql.NullString
		createdAt	string
		fingerprint	string
	)
	err := s.db.QueryRowContext(context.Background(), `
SELECT id, task_id, kind, request, answer, created_at, answered_at, delivered_at, fingerprint
FROM tickets WHERE id = ?`, id).
		Scan(&tk.ID, &tk.TaskID, &tk.Kind, &request, &answer, &createdAt, &answeredAt, &deliveredAt, &fingerprint)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("读取工单 %s: %w", id, err)
	}

	tk.Request = json.RawMessage(request)
	tk.CreatedAt = parseTime(createdAt)
	if answer.Valid {
		tk.Answer = &answer.String
	}
	if answeredAt.Valid {
		t := parseTime(answeredAt.String)
		tk.AnsweredAt = &t
	}
	if deliveredAt.Valid {
		t := parseTime(deliveredAt.String)
		tk.DeliveredAt = &t
	}
	tk.Fingerprint = fingerprint
	return &tk, nil
}

n_store_Store_InsertPreview.signature:
// InsertPreview persists a complete owner preview row.
// The operation is not an upsert: a duplicate session ID is returned as a
// database error so the owner cannot publish an event for an unknown row.
func (s *Store) InsertPreview(row PreviewRecord) error {
	viaJSON, err := json.Marshal(row.Session.Via)
	if err != nil {
		return fmt.Errorf("序列化预览会话 %s allowlist: %w", row.Session.ID, err)
	}
	var closed any
	if row.ClosedAt != nil {
		closed = fmtTime(*row.ClosedAt)
	}
	_, err = s.db.ExecContext(context.Background(), `
INSERT INTO preview_sessions
  (id, entry_url, via_json, cwd, origin_url, branch, created_at, ttl_seconds,
   source_kind, source_port, workspace_root, relative_path, last_active_at, closed_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		row.Session.ID, row.Session.EntryURL, string(viaJSON), row.Session.CWD,
		row.Session.OriginURL, row.Session.Branch, fmtTime(row.Session.CreatedAt),
		row.Session.TTLSeconds, row.Source.Kind, row.Source.Port, row.Source.WorkspaceRoot,
		row.Source.RelativePath, fmtTime(row.LastActiveAt), closed)
	if err != nil {
		return fmt.Errorf("写入预览会话 %s: %w", row.Session.ID, err)
	}
	return nil
}

n_store_Store_LatestEvent.signature:
// LatestEvent 返回任务最新一条事件（seq 最大）。
//
// 返回：
//   - 任务无任何事件时返回 ErrNotFound
//
// 注意：
//   - 看门狗（stalled 判定）与启动恢复用「最新事件时刻」判断任务是否卡住，
//     单条取最新即可，不必拉全量事件
func (s *Store) LatestEvent(taskID string) (*proto.Event, error) {
	var (
		e		proto.Event
		payload		string
		createdAt	string
	)
	err := s.db.QueryRowContext(context.Background(), `
SELECT seq, task_id, type, payload, created_at FROM events
WHERE task_id = ? ORDER BY seq DESC LIMIT 1`, taskID).
		Scan(&e.Seq, &e.TaskID, &e.Type, &payload, &createdAt)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("查询任务 %s 最新事件: %w", taskID, err)
	}
	e.Payload = json.RawMessage(payload)
	e.CreatedAt = parseTime(createdAt)
	return &e, nil
}

n_store_Store_ListActivePreviews.signature:
// ListActivePreviews returns active rows whose idle TTL has not elapsed.
// Time comparison is intentionally done with time.Time rather than SQLite
// text comparison because RFC3339Nano strings with and without fractional
// seconds do not have a reliable lexical ordering around the decimal point.
func (s *Store) ListActivePreviews(now time.Time) ([]PreviewRecord, error) {
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT `+previewColumns+` FROM preview_sessions WHERE closed_at IS NULL ORDER BY created_at DESC`)
	if err != nil {
		return nil, fmt.Errorf("查询活动预览会话: %w", err)
	}
	defer rows.Close()
	active := []PreviewRecord{}
	for rows.Next() {
		row, err := scanPreviewRow(rows)
		if err != nil {
			return nil, fmt.Errorf("读取活动预览会话: %w", err)
		}
		if previewExpired(row, now) {
			continue
		}
		active = append(active, row)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历活动预览会话: %w", err)
	}
	return active, nil
}

n_store_Store_ListMirrorTasks.signature:
// ListMirrorTasks 返回全部镜像任务快照，按快照时刻降序。
//
// 注意：
//   - 单行快照解析失败只 Warn 跳过（副本脏了不该让看板挂掉），不使整个列表失败
//   - 返回的切片可能为空，恒不为 nil
func (s *Store) ListMirrorTasks() ([]MirrorTask, error) {
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT task_id, target, snapshot, fetched_at FROM mirror_tasks ORDER BY fetched_at DESC`)
	if err != nil {
		return nil, fmt.Errorf("查询镜像任务列表: %w", err)
	}
	defer rows.Close()
	var out []MirrorTask
	for rows.Next() {
		var (
			taskID		string
			target		string
			snapshot	string
			fetchedAt	string
		)
		if err := rows.Scan(&taskID, &target, &snapshot, &fetchedAt); err != nil {
			return nil, fmt.Errorf("读取镜像任务行: %w", err)
		}
		var task proto.Task
		if err := json.Unmarshal([]byte(snapshot), &task); err != nil {

			log().Warn("镜像任务快照解析失败，跳过该行", "task_id", taskID, "cause", err)
			continue
		}
		out = append(out, MirrorTask{Task: task, Target: target, FetchedAt: parseTime(fetchedAt)})
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历镜像任务: %w", err)
	}
	if out == nil {
		out = []MirrorTask{}
	}
	return out, nil
}

n_store_Store_ListProjectLocations.signature:
// ListProjectLocations 返回本机全部项目位置，按名字字典序。
//
