n_store_Store_ListSessions.signature:
// ListSessions 列出全部会话（含已吊销与已过期），按创建时刻降序。
//
// 注意：已吊销的会话也返回——`handoff sessions` 要能看到「这台设备已经被吊销了」，
// 直接消失反而让人怀疑是不是漏看了
func (s *Store) ListSessions() ([]Session, error) {
	rows, err := s.db.QueryContext(context.Background(),
		"SELECT "+sessionColumns+" FROM sessions ORDER BY created_at DESC")
	if err != nil {
		return nil, fmt.Errorf("列出会话: %w", err)
	}
	defer rows.Close()
	out := make([]Session, 0, 8)
	for rows.Next() {
		sess, serr := scanSession(rows)
		if serr != nil {
			return nil, fmt.Errorf("扫描会话行: %w", serr)
		}
		out = append(out, *sess)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历会话: %w", err)
	}
	return out, nil
}

n_store_Store_ListTasks.signature:
// ListTasks 返回全部任务，按 created_at 降序（最新在前）。
//
// 注意：
//   - created_at 统一为 UTC RFC3339Nano 文本，字典序即时间序，可直接排序
//   - **不填充 Task.Cumulative 与 Task.Timing**。列表页不显示累计消耗或耗时，
//     为每一行做两次 SUM 是纯浪费；要拿聚合值请用 GetTask。这不是 bug，改之前先想清楚代价。
func (s *Store) ListTasks() ([]proto.Task, error) {
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT `+taskColumns+` FROM tasks ORDER BY created_at DESC`)
	if err != nil {
		return nil, fmt.Errorf("查询任务列表: %w", err)
	}
	defer rows.Close()
	var tasks []proto.Task
	for rows.Next() {
		task, err := scanTaskRow(rows)
		if err != nil {
			return nil, fmt.Errorf("读取任务行: %w", err)
		}
		tasks = append(tasks, task)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历任务列表: %w", err)
	}
	return tasks, nil
}

n_store_Store_ListWorkbench.signature:
// ListWorkbench 一次读出全部基准行与全部单例。
//
// 返回：
//   - bases: 按 updated_at 倒序（最近动过的在前）。恢复时顺序不重要，
//     但倒序让「淘汰谁」在读取结果里一眼可见，调试时省一次排序
//   - singles: 键为 WorkbenchKeySelected / WorkbenchKeyDock；不存在的键**不出现**
//   - 错误：查询失败
//
// 注意：两张表分两次查询，不在事务里。工作台状态没有跨表不变式——
// selected 指向一个已被淘汰的 base 是完全合法的（前端会退回未选中态）。
func (s *Store) ListWorkbench() ([]proto.WorkbenchBase, map[string]string, error) {
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT base_key, payload, updated_at FROM workbench_bases ORDER BY updated_at DESC`)
	if err != nil {
		return nil, nil, fmt.Errorf("查询工作台基准行: %w", err)
	}
	defer rows.Close()
	bases := []proto.WorkbenchBase{}
	for rows.Next() {
		var b proto.WorkbenchBase
		if err := rows.Scan(&b.BaseKey, &b.Payload, &b.UpdatedAt); err != nil {
			return nil, nil, fmt.Errorf("扫描工作台基准行: %w", err)
		}
		bases = append(bases, b)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("遍历工作台基准行: %w", err)
	}

	srows, err := s.db.QueryContext(context.Background(),
		`SELECT key, value FROM workbench_singletons`)
	if err != nil {
		return nil, nil, fmt.Errorf("查询工作台单例: %w", err)
	}
	defer srows.Close()
	singles := map[string]string{}
	for srows.Next() {
		var k, v string
		if err := srows.Scan(&k, &v); err != nil {
			return nil, nil, fmt.Errorf("扫描工作台单例: %w", err)
		}
		singles[k] = v
	}
	if err := srows.Err(); err != nil {
		return nil, nil, fmt.Errorf("遍历工作台单例: %w", err)
	}
	return bases, singles, nil
}

n_store_Store_MarkTicketDelivered.signature:
// MarkTicketDelivered 标记工单应答已送达 executor。
//
// 参数：
//   - id: 工单 ID
//
// 注意：
//   - 幂等：已标记的工单重复调用不报错（delivered_at IS NULL 条件不成立即无影响）
//   - 只有真正把应答交到 executor 手上（RespondPermission/Send 返回成功）之后
//     才可调用——这是 RecoverStuck 判断「该不该重投」的唯一依据
func (s *Store) MarkTicketDelivered(id string) error {
	if _, err := s.db.ExecContext(context.Background(),
		"UPDATE tickets SET delivered_at = ? WHERE id = ? AND delivered_at IS NULL",
		fmtTime(time.Now()), id); err != nil {
		return fmt.Errorf("标记工单 %s 已送达: %w", id, err)
	}
	return nil
}

n_store_Store_MirrorEventsFrom.signature:
// MirrorEventsFrom 返回任务 taskID 的镜像事件中 seq 大于 fromSeq 的条目，
// 按 seq 升序，最多 limit 条。
//
// 注意：fromSeq 是**开区间**（seq > fromSeq），与本机 EventsFromAsc 的语义一致；
// 远端 seq 原值保留，重连凭它续拉。
func (s *Store) MirrorEventsFrom(taskID string, fromSeq int64, limit int) ([]proto.Event, error) {
	rows, err := s.db.QueryContext(context.Background(), `
SELECT seq, task_id, type, payload, created_at FROM mirror_events
WHERE task_id = ? AND seq > ? ORDER BY seq ASC LIMIT ?`, taskID, fromSeq, limit)
	if err != nil {
		return nil, fmt.Errorf("查询镜像事件: %w", err)
	}
	defer rows.Close()
	var events []proto.Event
	for rows.Next() {
		var (
			e		proto.Event
			payload		string
			createdAt	string
		)
		if err := rows.Scan(&e.Seq, &e.TaskID, &e.Type, &payload, &createdAt); err != nil {
			return nil, fmt.Errorf("读取镜像事件行: %w", err)
		}
		e.Payload = json.RawMessage(payload)
		e.CreatedAt = parseTime(createdAt)
		events = append(events, e)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历镜像事件: %w", err)
	}
	return events, nil
}

n_store_Store_MirrorTaskTarget.signature:
// MirrorTaskTarget 返回任务所属机器（mirror_tasks 的路由索引查询）。
//
// 返回：
//   - ok=true: target 有效（该任务有镜像记录）
//   - ok=false: 任务没有镜像记录（从没发现过它），target 为空串
//   - err: 数据库错误
func (s *Store) MirrorTaskTarget(taskID string) (string, bool, error) {
	var target string
	err := s.db.QueryRowContext(context.Background(),
		"SELECT target FROM mirror_tasks WHERE task_id = ?", taskID).Scan(&target)
	if errors.Is(err, sql.ErrNoRows) {
		return "", false, nil
	}
	if err != nil {
		return "", false, fmt.Errorf("查询镜像任务路由 %s: %w", taskID, err)
	}
	return target, true, nil
}

n_store_Store_MirrorWatermark.signature:
// MirrorWatermark 返回某任务镜像事件的当前水位（远端 seq 已复制的最大值）。
//
// 返回：任务无任何镜像事件时为 0——「首次订阅从头拉」与「没镜像过」同义。
func (s *Store) MirrorWatermark(taskID string) (int64, error) {
	var wm int64
	err := s.db.QueryRowContext(context.Background(),
		"SELECT COALESCE(MAX(seq),0) FROM mirror_events WHERE task_id = ?", taskID).Scan(&wm)
	if err != nil {
		return 0, fmt.Errorf("查询镜像事件水位 %s: %w", taskID, err)
	}
	return wm, nil
}

n_store_Store_PendingTickets.signature:
// PendingTickets 返回任务下所有未回答工单（answer IS NULL），按 created_at 升序。
//
// 参数：
//   - taskID: 任务 ID
//
// 注意：
//   - 用于 agent 阻塞等待人工答复的场景；回答过的工单不会出现在结果中
func (s *Store) PendingTickets(taskID string) ([]proto.Ticket, error) {
	rows, err := s.db.QueryContext(context.Background(), `
SELECT id, task_id, kind, request, answer, created_at, answered_at, fingerprint FROM tickets
WHERE task_id = ? AND answer IS NULL ORDER BY created_at ASC`, taskID)
	if err != nil {
		return nil, fmt.Errorf("查询待办工单: %w", err)
	}
	defer rows.Close()
	var tickets []proto.Ticket
	for rows.Next() {
		var (
			tk		proto.Ticket
			request		string
			answer		sql.NullString
			answeredAt	sql.NullString
			createdAt	string
			fingerprint	string
		)
		if err := rows.Scan(&tk.ID, &tk.TaskID, &tk.Kind, &request, &answer, &createdAt, &answeredAt, &fingerprint); err != nil {
			return nil, fmt.Errorf("读取工单行: %w", err)
		}
		tk.Request = json.RawMessage(request)
		tk.CreatedAt = parseTime(createdAt)
		tk.Fingerprint = fingerprint
		if answer.Valid {
			tk.Answer = &answer.String
		}
		if answeredAt.Valid {
			t := parseTime(answeredAt.String)
			tk.AnsweredAt = &t
		}
		tickets = append(tickets, tk)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历待办工单: %w", err)
	}
	return tickets, nil
}

n_store_Store_PutWorkbenchBase.signature:
// PutWorkbenchBase 写入或覆盖一行基准状态，并就地把总行数裁到 WorkbenchBaseLimit。
//
// 参数：
//   - key: 基准目录的身份（工作树是 path 或 path@machine，见前端 workspaceBase）
//   - payload: 前端序列化好的 JSON 字符串，本层不解析
//   - now: 毫秒时间戳，由调用方给定
//
// 返回：错误为写库故障。
//
// 注意：淘汰做在写入路径而不是后台定时任务——省一个 goroutine，而且「刚写完
// 立刻裁」的时机最准（此刻的 updated_at 排序就是最终排序）。
func (s *Store) PutWorkbenchBase(key, payload string, now int64) error {
	if _, err := s.db.ExecContext(context.Background(),
		`INSERT INTO workbench_bases (base_key, payload, updated_at) VALUES (?, ?, ?)
     ON CONFLICT(base_key) DO UPDATE SET payload = excluded.payload, updated_at = excluded.updated_at`,
		key, payload, now); err != nil {
		return fmt.Errorf("写工作台基准行 %s: %w", key, err)
	}

	if _, err := s.db.ExecContext(context.Background(),
		`DELETE FROM workbench_bases WHERE base_key NOT IN (
       SELECT base_key FROM workbench_bases ORDER BY updated_at DESC LIMIT ?)`,
		WorkbenchBaseLimit); err != nil {
		return fmt.Errorf("裁剪工作台基准行至 %d: %w", WorkbenchBaseLimit, err)
	}
	return nil
}

n_store_Store_PutWorkbenchSingleton.signature:
// PutWorkbenchSingleton 写入或覆盖一个单例。
//
// 参数：key 必须是 WorkbenchKeySelected / WorkbenchKeyDock 之一（白名单在接口层校验）；
// value 是字符串，语义由前端定义；now 是毫秒时间戳。
//
// 返回：错误为写库故障。
func (s *Store) PutWorkbenchSingleton(key, value string, now int64) error {
	if _, err := s.db.ExecContext(context.Background(),
		`INSERT INTO workbench_singletons (key, value, updated_at) VALUES (?, ?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at`,
		key, value, now); err != nil {
		return fmt.Errorf("写工作台单例 %s: %w", key, err)
	}
	return nil
}

n_store_Store_RevokeSession.signature:
// RevokeSession 吊销一个尚未吊销的会话。
//
// 返回：
//   - ErrNotFound: 会话不存在**或**已被吊销（两者对调用方是同一个结论：这次吊销没改变什么）
func (s *Store) RevokeSession(id string, at time.Time) error {
	res, err := s.db.ExecContext(context.Background(),
		"UPDATE sessions SET revoked_at = ? WHERE id = ? AND revoked_at IS NULL",
		fmtTime(at), id)
	if err != nil {
		return fmt.Errorf("吊销会话 %s: %w", id, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("读取吊销影响行数: %w", err)
	}
	if n != 1 {
		return ErrNotFound
	}
	return nil
}

n_store_Store_SessionByID.signature:
// SessionByID 按会话 id 查会话；不存在返回 ErrNotFound。
func (s *Store) SessionByID(id string) (*Session, error) {
	row := s.db.QueryRowContext(context.Background(),
		"SELECT "+sessionColumns+" FROM sessions WHERE id = ?", id)
	sess, err := scanSession(row)
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("按 id 查询会话 %s: %w", id, err)
	}
	return sess, nil
}

n_store_Store_SessionByTokenHash.signature:
// SessionByTokenHash 按 cookie 哈希查会话；不存在返回 ErrNotFound。
//
// 注意：已过期或已吊销的会话**照样返回**——有效性由调用方判定，这样才能把
// 「不存在 / 已过期 / 已吊销」记成三种不同的鉴权失败原因
func (s *Store) SessionByTokenHash(hash string) (*Session, error) {
	row := s.db.QueryRowContext(context.Background(),
		"SELECT "+sessionColumns+" FROM sessions WHERE token_hash = ?", hash)
	sess, err := scanSession(row)
	if err == sql.ErrNoRows {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, fmt.Errorf("按哈希查询会话: %w", err)
	}
	return sess, nil
}

n_store_Store_SetEventHook.signature:
// SetEventHook 注册「事件落库后」的回调。传 nil 可取消。
//
// 调用时机：INSERT 成功、proto.Event 组装完成之后，AppendEvent 返回之前，
// **同步**调用。同步是刻意的——它保证「事件入库顺序 == 钩子观察顺序」，
// 派生出的帧流才能与事件流对齐。
//
// 边界（违反会死锁或自我递归）：
//   - **钩子内不得回调本 Store 的任何方法**。只允许做不回到数据库的动作，
//     比如往文件追加一行。
//   - 钩子不得长时间阻塞：它跑在 AppendEvent 的调用栈上，会拖慢事件落库。
//   - 钩子 panic 由本方法内部 recover：一个可见性副作用不该让已经成功的
//     事件落库变成失败。
func (s *Store) SetEventHook(fn func(proto.Event)) {
	s.eventHookMu.Lock()
	defer s.eventHookMu.Unlock()
	s.eventHook = fn
}

n_store_Store_SetTaskField.signature:
// SetTaskField 更新任务白名单内的单个字段（branch/executor_session/plan_summary/done_note）。
//
// 参数：
//   - id: 任务 ID
//   - field: 字段名，仅允许白名单四项
//   - value: 新值
//
// 注意：
//   - 白名单之外（如 id/state）返回错误；任务不存在时不报错（不影响其他行即返回 nil）
func (s *Store) SetTaskField(id, field, value string) error {
	if !allowedTaskFields[field] {
		return fmt.Errorf("字段 %s 不在可更新白名单", field)
	}
	if _, err := s.db.ExecContext(context.Background(),
		"UPDATE tasks SET "+field+" = ?, updated_at = ? WHERE id = ?",
		value, fmtTime(time.Now()), id); err != nil {
		return fmt.Errorf("更新任务 %s 字段 %s: %w", id, field, err)
	}
	return nil
}

n_store_Store_SetTaskUsage.signature:
// SetTaskUsage 一次性更新任务的实际模型名与 context 占用。
//
// 参数：
//   - id: 任务 ID
//   - model: 实际模型名；**空串表示本次不更新该列**（保留既有值）
//   - ctxTokens: 当前 context 占用；**0 表示不更新**
//   - ctxWindow: 上下文窗口上限；**nil 表示不更新**
//
// 为什么空值语义是「不更新」而不是「清空」：用量与模型名往往来自**不同的帧**
// （grok 的窗口在会话建立时到、占用在每次模型调用后到），若空值等于清空，
// 后到的那一帧会把先到的那一半抹掉。
//
// 注意：
//   - 三个参数全为空时是空操作，不打库
//   - 任务不存在时不报错（与 SetTaskField 一致，不影响其他行即返回 nil）
func (s *Store) SetTaskUsage(id, model string, ctxTokens int, ctxWindow *int) error {
	sets := make([]string, 0, 3)
	args := make([]any, 0, 5)
	if model != "" {
		sets = append(sets, "actual_model = ?")
		args = append(args, model)
	}
	if ctxTokens > 0 {
		sets = append(sets, "usage_context_tokens = ?")
		args = append(args, ctxTokens)
	}
	if ctxWindow != nil {
		sets = append(sets, "usage_context_window = ?")
		args = append(args, *ctxWindow)
	}
	if len(sets) == 0 {
		return nil
	}
	args = append(args, fmtTime(time.Now()), id)
	if _, err := s.db.ExecContext(context.Background(),
		"UPDATE tasks SET "+strings.Join(sets, ", ")+", updated_at = ? WHERE id = ?",
		args...); err != nil {
		return fmt.Errorf("更新任务 %s 用量: %w", id, err)
	}
	return nil
}

n_store_Store_SubscribeEventDoorbell.signature:
// SubscribeEventDoorbell subscribes to task-scoped persisted-event wakeups.
//
// 返回：
//   - 容量为 1 的通知 channel，以及可幂等调用的取消函数
//
// 注意：通知只表示“有新事件”，真实事件仍须从 EventsFromAsc 按 seq > fromSeq
// 读取；取消不会关闭共享 channel，以避免 signal 与 cancel 并发时发生 panic。
func (s *Store) SubscribeEventDoorbell(taskID string) (<-chan struct{}, func()) {
	events := make(chan struct{}, 1)
	s.eventDoorbellMu.Lock()
	if s.eventDoorbells == nil {
		s.eventDoorbells = make(map[string]map[chan struct{}]struct{})
	}
	if s.eventDoorbells[taskID] == nil {
		s.eventDoorbells[taskID] = make(map[chan struct{}]struct{})
	}
	s.eventDoorbells[taskID][events] = struct{}{}
	s.eventDoorbellMu.Unlock()

	var once sync.Once
	cancel := func() {
		once.Do(func() {
			s.eventDoorbellMu.Lock()
			listeners := s.eventDoorbells[taskID]
			delete(listeners, events)
			if len(listeners) == 0 {
				delete(s.eventDoorbells, taskID)
			}
			s.eventDoorbellMu.Unlock()
		})
	}
	return events, cancel
}

n_store_Store_TaskCumulative.signature:
// TaskCumulative 对该任务的全部账目求和，得到累计消耗。
//
// 返回：
//   - 没有任何账目行时返回 (nil, nil)。**不返回零值结构**——0 会被读成
//     「一共花了 0」，而真相是「还不知道」
//   - 花费状态按四条规则定（known=非 unknown 行的 ticks 之和，
//     missing=unknown 行的条数，est=是否含 estimated 行）：
//     missing==0 && !est → reported；missing==0 && est → estimated；
//     missing>0 && known>0 → partial（**下界**）；missing>0 && known==0 → unknown
//
// 注意：estimated 与 missing 同时成立时按 partial——漏账比不准要紧，
// 而 partial 的展示（下界）也已经隐含了「别当真」。
//
// **本方法读路径高频，成功不打日志**；只在调用方需要时报错（扫描/遍历出错
// 由调用方带上下文记录）。
func (s *Store) TaskCumulative(taskID string) (*proto.Cumulative, error) {
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT input, cached_input, output, cost_ticks, cost_state
   FROM task_usage_ledger WHERE task_id = ?`, taskID)
	if err != nil {
		return nil, fmt.Errorf("读任务 %s 消耗账本: %w", taskID, err)
	}
	defer rows.Close()

	var (
		c	proto.Cumulative
		known	int64
		missing	int
		est	bool
		n	int
	)
	for rows.Next() {
		var in, cached, out int
		var ticks int64
		var state string
		if err := rows.Scan(&in, &cached, &out, &ticks, &state); err != nil {
			return nil, fmt.Errorf("扫描任务 %s 的消耗行: %w", taskID, err)
		}
		n++
		c.InputTokens += in
		c.CachedTokens += cached
		c.OutputTokens += out
		switch proto.CostState(state) {
		case proto.CostUnknown:
			missing++
		case proto.CostEstimated:
			est = true
			known += ticks
		default:
			known += ticks
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历任务 %s 的消耗账本: %w", taskID, err)
	}
	if n == 0 {
		return nil, nil
	}
	c.TotalTokens = c.InputTokens + c.CachedTokens + c.OutputTokens
	c.Cost = &proto.Cost{Ticks: known}
	switch {
	case missing == 0 && !est:
		c.Cost.State = proto.CostReported
	case missing == 0:
		c.Cost.State = proto.CostEstimated
	case known > 0:
		c.Cost.State = proto.CostPartial
	default:
		c.Cost.State = proto.CostUnknown
	}
	return &c, nil
}

n_store_Store_TaskTiming.signature:
// TaskTiming 对该任务的全部耗时账目求和，得到三分法聚合。
//
// 参数：taskID —— 任务 ID
//
// 返回：
//   - 没有任何账目行时返回 (nil, nil)。**不返回零值结构**——0 会被读成
//     「一共没花时间」，而真相是「还不知道」（与 TaskCumulative 同款纪律）
//   - 取行/扫描出错时返回 (nil, err)。**出错绝不返回 (nil, nil)**：那与
//     「没有账目」形状相同，会把一次读库失败伪装成一个正常的空账本
//
// 注意：**本方法读路径高频，成功不打日志**（与 TaskCumulative 同款）。
func (s *Store) TaskTiming(taskID string) (*proto.TaskTiming, error) {
	rows, err := s.db.QueryContext(context.Background(),
		`SELECT kind, turn, dur_ms, offset_ms, label, detail
   FROM task_timing_ledger WHERE task_id = ?`, taskID)
	if err != nil {
		return nil, fmt.Errorf("读任务 %s 耗时账本: %w", taskID, err)
	}
	defer rows.Close()

	var acc []timingRow
	for rows.Next() {
		var r timingRow
		if err := rows.Scan(&r.Kind, &r.Turn, &r.DurMS, &r.OffsetMS, &r.Label, &r.Detail); err != nil {
			return nil, fmt.Errorf("扫描任务 %s 耗时账目: %w", taskID, err)
		}
		acc = append(acc, r)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历任务 %s 耗时账目: %w", taskID, err)
	}
	return aggregateTiming(acc), nil
}

n_store_Store_TicketHasEvent.signature:
// TicketHasEvent 判定某工单的通知事件（permission_request / question）是否已落库。
//
// 参数：
//   - taskID: 任务 ID（事件按任务分区存储）
//   - ticketID: 工单 ID，与事件 payload 里的 ticket_id 精确比对
//
// 返回：
//   - 是否已有对应通知事件
//   - 数据库错误
//
// 注意：
//   - 用途是「工单已创建但通知事件缺失」的自愈判定（崩溃恰好落在两次写之间）：
//     仅凭工单存在就认定为重放，会把协调者的唤醒事件永久吞掉
//   - payload 是 JSON 文本，这里取回后在 Go 侧精确解码比对，不用 LIKE 匹配
//     （ticket_id 含 `_` 等 LIKE 通配符，字符串匹配会误判）
//   - 单任务的问答类事件量级在几十条，全量扫描代价可忽略；且只在重放分支调用
func (s *Store) TicketHasEvent(taskID, ticketID string) (bool, error) {
	rows, err := s.db.QueryContext(context.Background(), `
SELECT payload FROM events WHERE task_id = ? AND type IN (?, ?)`,
		taskID, string(proto.EventTypePermissionRequest), string(proto.EventTypeQuestion))
	if err != nil {
		return false, fmt.Errorf("查询任务 %s 的问答事件: %w", taskID, err)
	}
	defer rows.Close()
	for rows.Next() {
		var payload string
		if err := rows.Scan(&payload); err != nil {
			return false, fmt.Errorf("扫描事件 payload: %w", err)
		}
		var p struct {
			TicketID string `json:"ticket_id"`
		}
		if json.Unmarshal([]byte(payload), &p) == nil && p.TicketID == ticketID {
			return true, nil
		}
	}
	if err := rows.Err(); err != nil {
		return false, fmt.Errorf("遍历任务 %s 的问答事件: %w", taskID, err)
	}
	return false, nil
}

n_store_Store_TouchPreview.signature:
// TouchPreview renews the idle clock only while the row remains open.
// It returns false for a missing or already-closed row and never changes wire
// fields such as CreatedAt or TTLSeconds.
func (s *Store) TouchPreview(id string, at time.Time) (bool, error) {
	result, err := s.db.ExecContext(context.Background(),
		`UPDATE preview_sessions SET last_active_at = ? WHERE id = ? AND closed_at IS NULL`,
		fmtTime(at.UTC()), id)
	if err != nil {
		return false, fmt.Errorf("续命预览会话 %s: %w", id, err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return false, fmt.Errorf("读取续命预览会话 %s 影响行数: %w", id, err)
	}
	return affected == 1, nil
}

n_store_Store_TouchSession.signature:
// TouchSession 写回会话的最后活跃时刻与过期时刻（滑动续期）。
//
// 注意：调用方负责节流——本方法每次调用都真写库
func (s *Store) TouchSession(id string, lastSeen, expiresAt time.Time) error {
	if _, err := s.db.ExecContext(context.Background(),
		"UPDATE sessions SET last_seen_at = ?, expires_at = ? WHERE id = ?",
		fmtTime(lastSeen), fmtTime(expiresAt), id); err != nil {
		return fmt.Errorf("更新会话 %s 活跃时刻: %w", id, err)
	}
	return nil
}

n_store_Store_UndeliveredAnswers.signature:
// UndeliveredAnswers 返回任务里「已应答但未送达 executor」的工单，按应答时间升序。
//
// 参数：
//   - taskID: 任务 ID
//
// 返回：
//   - 待重投的工单列表（可能为空）
//   - 数据库错误
//
// 注意：
//   - 作废工单（answer = VoidAnswer）不在其中：它们是「任务已终结，不会再被回答」
//     的墓碑，不是待送达的裁决
//   - 这是「协调者 reply 得到 502 之后」的可恢复面：列表非空即说明有裁决卡在半路
func (s *Store) UndeliveredAnswers(taskID string) ([]proto.Ticket, error) {
	rows, err := s.db.QueryContext(context.Background(), `
SELECT id, task_id, kind, request, answer, created_at, answered_at
FROM tickets
WHERE task_id = ? AND answer IS NOT NULL AND answer != ? AND delivered_at IS NULL
ORDER BY answered_at ASC`, taskID, VoidAnswer)
	if err != nil {
		return nil, fmt.Errorf("查询任务 %s 未送达应答: %w", taskID, err)
	}
	defer rows.Close()
	var out []proto.Ticket
	for rows.Next() {
		var (
			tk		proto.Ticket
			request		string
			answer		sql.NullString
			answeredAt	sql.NullString
			createdAt	string
		)
		if err := rows.Scan(&tk.ID, &tk.TaskID, &tk.Kind, &request, &answer, &createdAt, &answeredAt); err != nil {
			return nil, fmt.Errorf("扫描未送达应答: %w", err)
		}
		tk.Request = json.RawMessage(request)
		tk.CreatedAt = parseTime(createdAt)
		if answer.Valid {
			tk.Answer = &answer.String
		}
		if answeredAt.Valid {
			t := parseTime(answeredAt.String)
			tk.AnsweredAt = &t
		}
		out = append(out, tk)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("遍历任务 %s 未送达应答: %w", taskID, err)
	}
	return out, nil
}

n_store_Store_UpdatePreviewEntry.signature:
// UpdatePreviewEntry updates the owner-generated entry URL after restoring a
