n_store_Store_UpdateProjectLocation.signature:
// UpdateProjectLocation 改一条位置登记的引用名与/或路径。
//
// 参数：
//   - name: 当前引用名（定位用）
//   - newName: 新引用名；空串表示不改
//   - newPath: 新路径；空串表示不改
//
// 返回：更新后的记录；
//   - ErrNotFound：name 不存在
//   - ErrProjectDuplicate：新名字或新路径已被占用
func (s *Store) UpdateProjectLocation(name, newName, newPath string) (proto.ProjectLocation, error) {

	if newName == "" && newPath == "" {
		return s.GetProjectLocationByName(name)
	}
	var sets []string
	var args []any
	if newName != "" {
		sets = append(sets, "name = ?")
		args = append(args, newName)
	}
	if newPath != "" {
		sets = append(sets, "path = ?")
		args = append(args, newPath)
	}
	args = append(args, name)
	res, err := s.db.ExecContext(context.Background(),
		`UPDATE project_locations SET `+strings.Join(sets, ", ")+` WHERE name = ?`, args...)
	if err != nil {

		if strings.Contains(err.Error(), "UNIQUE constraint failed") ||
			strings.Contains(err.Error(), "PRIMARY KEY constraint failed") {
			return proto.ProjectLocation{}, fmt.Errorf("%w: name=%s newName=%s newPath=%s: %v",
				ErrProjectDuplicate, name, newName, newPath, err)
		}
		return proto.ProjectLocation{}, fmt.Errorf("更新项目位置 %s: %w", name, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return proto.ProjectLocation{}, fmt.Errorf("更新项目位置 %s 后取影响行数: %w", name, err)
	}
	if n == 0 {
		return proto.ProjectLocation{}, fmt.Errorf("项目 %s: %w", name, ErrNotFound)
	}
	if newName != "" {
		return s.GetProjectLocationByName(newName)
	}
	return s.GetProjectLocationByName(name)
}

n_store_Store_UpdateTaskState.signature:
// UpdateTaskState 将任务状态迁移到 st，迁移合法性由 proto.CanTransit 校验。
//
// 参数：
//   - id: 任务 ID；不存在返回 ErrNotFound
//   - st: 目标状态
//
// 返回：
//   - 非法迁移返回 ErrBadTransit；任务不存在返回 ErrNotFound
//
// 注意：
//   - 非法迁移是本包唯一打 Warn 日志的点：排障时可直接定位谁想从哪迁到哪被拒
//   - 写回采用 CAS（WHERE state = 读到的旧状态）：若并发写者先变更了状态，本方法返回
//     ErrBadTransit，调用方应用最新快照重试意图；不会静默覆盖并发迁移
func (s *Store) UpdateTaskState(id string, st proto.TaskState) error {
	cur, err := s.GetTask(id)
	if err != nil {
		return err
	}
	if !proto.CanTransit(cur.State, st) {
		log().Warn("非法状态迁移被拒绝", "task", id, "from", cur.State, "to", st)
		return ErrBadTransit
	}

	res, err := s.db.ExecContext(context.Background(),
		"UPDATE tasks SET state = ?, updated_at = ? WHERE id = ? AND state = ?",
		st, fmtTime(time.Now()), id, cur.State)
	if err != nil {
		return fmt.Errorf("更新任务 %s 状态: %w", id, err)
	}
	affected, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("读取更新任务 %s 状态影响行数: %w", id, err)
	}
	if affected == 0 {
		log().Warn("状态迁移被并发变更拒绝", "task", id, "from", cur.State, "to", st)
		return ErrBadTransit
	}
	return nil
}

n_store_Store_UpsertMirrorTask.signature:
// UpsertMirrorTask 覆盖式写入（或更新）一条任务快照。
//
// 参数：
//   - target: 任务所在机器的名字（本机 cfg.Targets 的键）
//   - task: 任务体 JSON，整体序列化进 snapshot 列
//   - fetchedAt: 本次快照的时刻（UI 据此显示数据新旧）
//
// 注意：
//   - upsert 语义：同 task_id 重复调用用新快照覆盖旧快照，不报错
func (s *Store) UpsertMirrorTask(target string, task proto.Task, fetchedAt time.Time) error {
	snap, err := json.Marshal(task)
	if err != nil {
		return fmt.Errorf("序列化镜像任务 %s: %w", task.ID, err)
	}
	_, err = s.db.ExecContext(context.Background(), `
INSERT INTO mirror_tasks (task_id, target, snapshot, fetched_at) VALUES (?, ?, ?, ?)
ON CONFLICT(task_id) DO UPDATE SET
  target = excluded.target, snapshot = excluded.snapshot, fetched_at = excluded.fetched_at`,
		task.ID, target, string(snap), fmtTime(fetchedAt))
	if err != nil {
		return fmt.Errorf("写入镜像任务 %s: %w", task.ID, err)
	}
	return nil
}

n_store_Store_UpsertSpend.signature:
// UpsertSpend 记一条消耗账目；同 (taskID, e.Key) **覆盖**既有行。
//
// 参数：
//   - taskID: 所属任务
//   - e: 账目。三个 token 分项的口径是归一化后的值——**输入不含缓存**、
//     **缓存输入 = 读缓存 + 写缓存**、**输出含 reasoning**。四家 executor 的
//     原始字段含义互不相同（codex/grok 的输入含缓存要减，claudecode/opencode
//     的要加；opencode 的 reasoning 与 output 平行要加，codex/grok 的是子集
//     不能加），归一化在各 adapter 的 spend.go 里完成，本方法不做换算。
//
// 注意：
//   - e.Key 为空时直接返回错误——没有键就没有幂等，宁可报错也不写一行永远
//     去不掉重的账
//   - 覆盖而非累加是刻意的，理由见 proto.SpendEntry 的注释
//   - **不打成功日志**：频率与 assistant 消息同级，会刷屏；错误由调用方
//     handleSpend 打（见 Task 2）
func (s *Store) UpsertSpend(taskID string, e proto.SpendEntry) error {
	if e.Key == "" {
		return fmt.Errorf("记任务 %s 的消耗：幂等键为空", taskID)
	}
	if _, err := s.db.ExecContext(context.Background(),
		`INSERT INTO task_usage_ledger
   (task_id, entry_key, input, cached_input, output, cost_ticks, cost_state, updated_at)
 VALUES (?, ?, ?, ?, ?, ?, ?, ?)
 ON CONFLICT(task_id, entry_key) DO UPDATE SET
   input = excluded.input, cached_input = excluded.cached_input,
   output = excluded.output, cost_ticks = excluded.cost_ticks,
   cost_state = excluded.cost_state, updated_at = excluded.updated_at`,
		taskID, e.Key, e.InputTokens, e.CachedTokens, e.OutputTokens,
		e.CostTicks, string(e.CostState), fmtTime(time.Now())); err != nil {
		return fmt.Errorf("记任务 %s 消耗 %s: %w", taskID, e.Key, err)
	}
	return nil
}

n_store_Store_UpsertTiming.signature:
// UpsertTiming 记一条耗时账目；同 (taskID, e.Key) **覆盖**既有行。
//
// 参数：
//   - taskID: 所属任务
//   - e: 账目。Detail 必须已由调用方截断（本方法不做截断——截断规则属于
//     采集侧的凭据边界，放在这里会让两处都以为对方管了）
//
// 注意：
//   - e.Key 为空时直接返回错误——没有键就没有幂等，与 UpsertSpend 同款
//   - 覆盖而非累加是刻意的：kind=turn 的条目随回合推进反复上报同一个键，
//     覆盖天然取到最终值
//   - **不打成功日志**：频率与 UpsertSpend 同级，会刷屏
func (s *Store) UpsertTiming(taskID string, e proto.TimingEntry) error {
	if e.Key == "" {
		return fmt.Errorf("记任务 %s 的耗时：幂等键为空", taskID)
	}
	if _, err := s.db.ExecContext(context.Background(),
		`INSERT INTO task_timing_ledger
   (task_id, entry_key, kind, turn, dur_ms, offset_ms, label, detail, updated_at)
 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
 ON CONFLICT(task_id, entry_key) DO UPDATE SET
   kind = excluded.kind, turn = excluded.turn, dur_ms = excluded.dur_ms,
   offset_ms = excluded.offset_ms, label = excluded.label,
   detail = excluded.detail, updated_at = excluded.updated_at`,
		taskID, e.Key, string(e.Kind), e.Turn, e.DurMS, e.OffsetMS,
		e.Label, e.Detail, fmtTime(time.Now())); err != nil {
		return fmt.Errorf("记任务 %s 耗时 %s: %w", taskID, e.Key, err)
	}
	return nil
}

n_store_Store_VoidPendingTickets.signature:
// VoidPendingTickets 把任务全部未回答工单作废（answer 置为 VoidAnswer）。
//
// 参数：
//   - taskID: 任务 ID
//
// 返回：
//   - 被作废的工单数（本次更新行数）
//
// 注意：
//   - 幂等：重复调用第二次起返回 0（已作废的工单不再更新）
//   - 不删除工单：request/answered_at 等审计痕迹保留，回答语义上视为已终结；
//     回答过的工单不受影响
//   - 由 agentd 启动恢复（RecoverOnStartup）在判定任务 dead 后调用；hub 侧等待
//     者随进程消亡不存在，无需清理
func (s *Store) VoidPendingTickets(taskID string) (int, error) {
	res, err := s.db.ExecContext(context.Background(),
		"UPDATE tickets SET answer = ?, answered_at = ? WHERE task_id = ? AND answer IS NULL",
		VoidAnswer, fmtTime(time.Now()), taskID)
	if err != nil {
		return 0, fmt.Errorf("作废任务 %s 挂起工单: %w", taskID, err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("读取作废工单影响行数: %w", err)
	}
	return int(n), nil
}

n_store_Store_fireEventHook.signature:
// fireEventHook 调用已注册的钩子，并把 panic 收在这里。
func (s *Store) fireEventHook(e proto.Event) {
	s.eventHookMu.RLock()
	fn := s.eventHook
	s.eventHookMu.RUnlock()
	if fn == nil {
		return
	}
	defer func() {
		if rec := recover(); rec != nil {

			log().Error("事件钩子 panic，已忽略", "seq", e.Seq, "type", e.Type, "panic", rec)
		}
	}()
	fn(e)
}

