n_store_addToolRow.signature:
// addToolRow 把一条工具账目累加进排行（工具名一格 + 命令首词下钻一层）。
func addToolRow(tools map[string]*bucketAcc, r timingRow) {
	label := r.Label
	if label == "" {
		label = unknownToolLabel
	}
	b := tools[label]
	if b == nil {
		b = &bucketAcc{subs: map[string]*bucketAcc{}}
		tools[label] = b
	}
	b.durMS += r.DurMS
	b.count++

	head := commandHead(r.Detail)
	if head == "" {
		return
	}
	s := b.subs[head]
	if s == nil {
		s = &bucketAcc{}
		b.subs[head] = s
	}
	s.durMS += r.DurMS
	s.count++
}

n_store_aggregateTiming.signature:
// aggregateTiming 把账目行聚合成三分法结果。
//
// **纯函数**：无 I/O、无时钟、结果不依赖 map 迭代顺序（次序由显式排序决定）。
//
// 参数：rows —— 同一个任务的全部账目行，顺序无关
// 返回：聚合结果；rows 为空返回 nil（不是零值结构，理由见 TaskTiming）
//
// 三条口径（契约 §2.1，改之前先读那一节）：
//   - TotalMS = Σ kind=turn。**turn 不是段**，是 other 的分母；加进三分会让
//     总时长被计两遍且不报错
//   - ToolSpanMS 分回合求区间并集再相加：OffsetMS 是回合内相对偏移，跨回合的
//     区间不可比，混在一起并集会把两个回合的 [0,500) 并成一个 500
//   - OtherMS = max(0, Total − API − ToolSpan)。取 max 是**防御不是语义**，
//     真出现负数说明采集有 bug，此时 Partial 必为真
//
// 关于 Partial 的窗口（2026-08-22 真机实测，别按直觉推）：它只在「回合已开始、
// 但本回合还没有任何一个模型段收口」那一小段时间里为真——回合开始就写了 turn
// 行，而首个 api 行要等第一次 ToolStart（或 EndTurn）才落。一旦第一次工具调用
// 发生，该回合就有了 api 行，partial 转 false 并一路保持。
//
// 所以**不要**把它读成「运行中就一定 Partial」：真机上一个跑了两分钟的任务，
// 绝大部分时间都是 partial=false 且三分法自洽。它真正标出的是「有回合缺段」，
// 常见来源是那个开头窗口、以及 executor 中途退出留下的半条账。
func aggregateTiming(rows []timingRow) *proto.TaskTiming {
	if len(rows) == 0 {
		return nil
	}

	turns := map[int]*turnAcc{}
	tools := map[string]*bucketAcc{}
	var out proto.TaskTiming

	for _, r := range rows {
		acc := turns[r.Turn]
		if acc == nil {
			acc = &turnAcc{}
			turns[r.Turn] = acc
		}
		switch proto.TimingKind(r.Kind) {
		case proto.TimingKindTurn:

			acc.turnMS, acc.hasTurn = r.DurMS, true
		case proto.TimingKindAPI:
			acc.apiMS += r.DurMS
			acc.hasAPI = true
		case proto.TimingKindTool:
			acc.spans = append(acc.spans, span{r.OffsetMS, r.OffsetMS + r.DurMS})
			out.ToolMS += r.DurMS
			addToolRow(tools, r)
		default:

			out.Partial = true
		}
	}

	for _, acc := range turns {
		out.TotalMS += acc.turnMS
		out.APIMS += acc.apiMS
		out.ToolSpanMS += unionMS(acc.spans)

		if !acc.hasTurn || !acc.hasAPI {
			out.Partial = true
		}
	}

	if residual := out.TotalMS - out.APIMS - out.ToolSpanMS; residual < 0 {
		out.OtherMS, out.Partial = 0, true
	} else {
		out.OtherMS = residual
	}

	out.Buckets = rankBuckets(tools)
	return &out
}

n_store_boolToInt.signature:
// boolToInt 将布尔转 0/1 整数以存入 SQLite 的 INTEGER 列。
// 回读时再由调用方按「非 0 即 true」还原（见 GetTask/ListTasks 的 Scan 处）。
func boolToInt(b bool) int {
	if b {
		return 1
	}
	return 0
}

n_store_commandHead.signature:
// commandHead 从 Detail 取「命令首词」，作为排行下钻层的标签。
// 返回 "" 表示这条 Detail 不适合下钻（调用方跳过，不建空格子）。
//
// 规则（P4=(b) 的落地 + 2026-08-22 真机补完）：
//  1. 以 { 或 [ 开头 → ""。那是入参 JSON（非 Bash 工具的 Detail 回落成
//     compactJSON），它的「首词」是 `{"path":` 之类，对「哪条命令慢」无价值
//  2. **先整体剥 shell 包装**（见 unwrapShell）。必须在按行切分之前做：包装里的
//     命令串自带换行时，先切行会把开引号和闭引号分到两行上
//  3. 逐行找第一行「像命令」的：跳过空行、# 注释行、纯环境赋值行、被截断出来
//     的碎片。跳过而不是就地返回 ""，是因为真机上见过 `# 说明` 起头、第二行
//     才是真命令的多行脚本
//  4. 取那一行的前两段（`go test ./...` → `go test`，把 go build/vet/test 分开），
//     再按 subLabelRunes 截断
func commandHead(detail string) string {
	s := strings.TrimSpace(detail)
	if s == "" || s[0] == '{' || s[0] == '[' {
		return ""
	}
	s = unwrapShell(s)
	for _, line := range strings.Split(s, "\n") {
		if h := headOfLine(line); h != "" {
			return h
		}
	}
	return ""
}

n_store_fmtTime.signature:
// fmtTime 将时间归一化为 UTC RFC3339Nano 文本存库。
// 统一 UTC 与固定格式，保证任意时区写入后回读一致，且文本字典序即时间序。
func fmtTime(t time.Time) string {
	return t.UTC().Format(time.RFC3339Nano)
}

n_store_headOfLine.signature:
// headOfLine 从一行里取命令首词；这一行不像命令时返回 ""，由 commandHead
// 接着看下一行。
func headOfLine(line string) string {
	s := strings.TrimSpace(line)
	if s == "" || strings.HasPrefix(s, "#") {
		return ""
	}
	fields := strings.Fields(s)

	for len(fields) > 0 && isEnvAssign(fields[0]) {
		fields = fields[1:]
	}
	if len(fields) == 0 || isElided(fields[0]) {
		return ""
	}
	head := fields[0]
	if len(fields) > 1 && !isElided(fields[1]) && !shellOps[fields[1]] {
		head += " " + fields[1]
	}
	if r := []rune(head); len(r) > subLabelRunes {
		return string(r[:subLabelRunes])
	}
	return head
}

n_store_isElided.signature:
// isElided 判断一段里是否含省略号——含就说明它是截断出来的碎片，不是命令词。
//
// 刻意**不**比对 executor.TruncationMarker 的字面值：为一个常量从 d_ledger
// 拉一条到 d_executor 的依赖边不值当，而「命令词里不会出现 …」这条判据比那个
// 具体标记更稳（标记改了它照样成立）。
func isElided(f string) bool {
	return strings.ContainsRune(f, '…')
}

n_store_isEnvAssign.signature:
// isEnvAssign 判断一段是不是 VAR=value 形式的环境赋值。
//
// 只认 [A-Za-z_][A-Za-z0-9_]*= 这一种形状：宽一点会把 `--flag=v` 这类真正的
// 命令参数误判成赋值，从而把命令首词吃掉一段。
func isEnvAssign(f string) bool {
	eq := strings.IndexByte(f, '=')
	if eq <= 0 {
		return false
	}
	for i, c := range f[:eq] {
		switch {
		case c >= 'A' && c <= 'Z', c >= 'a' && c <= 'z', c == '_':
		case i > 0 && c >= '0' && c <= '9':
		default:
			return false
		}
	}
	return true
}

n_store_isShellBin.signature:
// isShellBin 判断一段是不是 shell 可执行文件；按 basename 比对，认绝对路径。
func isShellBin(f string) bool {
	if i := strings.LastIndexAny(f, `/\`); i >= 0 {
		f = f[i+1:]
	}
	return shellBins[f]
}

n_store_isShellCmdFlag.signature:
// isShellCmdFlag 判断一段是不是「下一段就是命令串」的 shell 标志：
// 单横线短选项且含 c（-c / -lc / -lic / -ec 都算）。
func isShellCmdFlag(f string) bool {
	return len(f) >= 2 && f[0] == '-' && f[1] != '-' && strings.ContainsRune(f, 'c')
}

n_store_log.signature:
// log 是本包日志入口，运行时取 slog.Default()（与 config 包一致）。
// agentd 在 bootstrap 时 logx.Setup + slog.SetDefault(...)，本包日志即跟随统一格式与级别。
// 为什么不用包级 var 捕获：包级 var 在 package init 时求值，晚于其执行的 slog.SetDefault
// 不会生效；运行时求值才能保证「agentd 先 Setup 后 SetDefault」的接线真正接管本包日志。
func log() *slog.Logger	{ return slog.Default() }

n_store_migrateReposToProjectLocations.signature:
// migrateReposToProjectLocations 把旧 repos 表逐行迁入 project_locations，随后 DROP 掉它。
//
// 参数：
//   - db: 已打开的数据库句柄（Open 内部调用，此时新表已建好）
//
// 返回：
//   - 错误：查/写/DROP 失败时返回；旧表不存在时直接返回 nil（新库与二次调用都走这条）
//
// 注意：
//   - **必须整体走一个事务**：中途任一失败（写库报错、DROP 失败）都要把已插入的
//     行一并回滚。非事务化时，中途失败会留下「project_locations 里已有若干行 +
//     旧 repos 表还在」的中间态，下一次 Open 重跑迁移必然在第一批行的 project_id
//     主键冲突上硬失败，库从此打不开，只能人工手术——这就是本函数要防的死局
//   - 按 created_at 升序遍历，**同一个 project_id 保留最早的一条**：ADR-0008
//     只允许一个位置，多出来的（多半是同一仓库的 worktree 各登了一条）丢弃并
//     Warn 出 name/path/origin 三项完整信息，人照着 handoff project add --path 自己补
//   - 路径做 Abs+Clean：新表的 path UNIQUE 约束要靠绝对路径才有意义
//   - 迁移不探测文件系统：目录已被移走的行照样迁入，下一次派发在 EnsureRepoUsable
//     处报「路径不存在」，处置是 project rm 后重新 add（spec §14 风险一）
//   - 幂等靠 DROP：跑完旧表就没了，第二次调用直接返回
//   - 汇总 Info（migrated/skipped）在 Commit 成功之后才打：回滚过却报「已迁入」
//     是假日志
func migrateReposToProjectLocations(db *sql.DB) error {
	ctx := context.Background()
	var n int
	if err := db.QueryRowContext(ctx,
		`SELECT count(*) FROM sqlite_master WHERE type='table' AND name='repos'`).Scan(&n); err != nil {
		return fmt.Errorf("探查旧 repos 表: %w", err)
	}
	if n == 0 {
		return nil
	}
	rows, err := db.QueryContext(ctx,
		`SELECT name, path, origin_url, created_at FROM repos ORDER BY created_at ASC`)
	if err != nil {
		return fmt.Errorf("读旧 repos 表: %w", err)
	}
	type oldRepo struct{ name, path, origin, createdAt string }
	var olds []oldRepo
	for rows.Next() {
		var r oldRepo
		if err := rows.Scan(&r.name, &r.path, &r.origin, &r.createdAt); err != nil {
			rows.Close()
			return fmt.Errorf("读旧 repos 行: %w", err)
		}
		olds = append(olds, r)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return fmt.Errorf("遍历旧 repos 表: %w", err)
	}
	rows.Close()

	tx, err := db.Begin()
	if err != nil {
		return fmt.Errorf("开启迁移事务: %w", err)
	}
	defer tx.Rollback()

	seen := make(map[string]oldRepo, len(olds))
	migrated, skipped := 0, 0
	for _, r := range olds {
		pid := projectid.FromOrigin(r.origin)
		if pid == "" {
			log().Warn("迁移跳过：origin 算不出 project_id（人工处置：handoff project add）",
				"name", r.name, "path", r.path, "origin", r.origin)
			skipped++
			continue
		}
		if prev, dup := seen[pid]; dup {
			log().Warn("迁移跳过：同一项目已有更早的登记，本条丢弃（人工处置：handoff project add --path <该路径>）",
				"name", r.name, "path", r.path, "origin", r.origin,
				"kept_name", prev.name, "kept_path", prev.path)
			skipped++
			continue
		}
		abs, err := filepath.Abs(r.path)
		if err != nil {
			log().Warn("迁移跳过：路径无法绝对化",
				"name", r.name, "path", r.path, "origin", r.origin, "cause", err)
			skipped++
			continue
		}
		if _, err := tx.ExecContext(ctx,
			`INSERT INTO project_locations (project_id, name, path, origin_url, created_at)
VALUES (?, ?, ?, ?, ?)`,
			pid, r.name, filepath.Clean(abs), r.origin, r.createdAt); err != nil {
			return fmt.Errorf("迁移登记 %s 到 project_locations: %w", r.name, err)
		}
		seen[pid] = r
		migrated++
	}
	if _, err := tx.ExecContext(ctx, `DROP TABLE repos`); err != nil {
		return fmt.Errorf("迁移后删除旧 repos 表: %w", err)
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("提交迁移事务: %w", err)
	}
	log().Info("旧仓库登记已迁入项目位置表", "migrated", migrated, "skipped", skipped)
	return nil
}

n_store_nextField.signature:
// nextField 取 s 的第一个空白分隔段，返回该段与其后的剩余**原文**。
//
// 不能用 strings.Fields 再拼回去：引号内的空格会被吃掉，`-lc 'a  b'` 会变成
// `-lc 'a b'`，剥出来的命令与真实执行的那条不再是同一个字符串。
func nextField(s string) (string, string) {
	s = strings.TrimLeft(s, " \t")
	i := strings.IndexAny(s, " \t")
	if i < 0 {
		return s, ""
	}
	return s[:i], s[i:]
}

n_store_parseTime.signature:
// parseTime 解析库中存储的时间文本；格式由 fmtTime 保证，解析失败时返回零值。
func parseTime(s string) time.Time {
	t, _ := time.Parse(time.RFC3339Nano, s)
	return t
}

n_store_previewExpired.signature:
func previewExpired(row PreviewRecord, now time.Time) bool {
	return !row.LastActiveAt.Add(time.Duration(row.Session.TTLSeconds) * time.Second).After(now)
}

n_store_rankBuckets.signature:
// rankBuckets 把累加态排成降序排行并截断到 proto.TimingBucketCap。
//
// 排序键是 (DurMS 降序, Label 升序)。第二关键字不是美观，是**确定性**：
// Go 的 map 迭代顺序随机，只按 DurMS 排会让同耗时的两格在两次调用间换位，
// 于是契约夹具与断言会偶发翻红——而偶发红会被当噪音忽略，判据就此失效。
func rankBuckets(m map[string]*bucketAcc) []proto.TimingBucket {
	if len(m) == 0 {
		return nil
	}
	out := make([]proto.TimingBucket, 0, len(m))
	for label, acc := range m {
		out = append(out, proto.TimingBucket{
			Label:	label, DurMS: acc.durMS, Count: acc.count,
			Sub:	rankBuckets(acc.subs),
		})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].DurMS != out[j].DurMS {
			return out[i].DurMS > out[j].DurMS
		}
		return out[i].Label < out[j].Label
	})
	if len(out) > proto.TimingBucketCap {
		out = out[:proto.TimingBucketCap]
	}
	return out
}

n_store_scanPreviewRow.signature:
func scanPreviewRow(sc rowScanner) (PreviewRecord, error) {
	var (
		row		PreviewRecord
		viaJSON		string
		createdAt	string
		lastActive	string
		closedAt	sql.NullString
	)
	if err := sc.Scan(
		&row.Session.ID, &row.Session.EntryURL, &viaJSON, &row.Session.CWD,
		&row.Session.OriginURL, &row.Session.Branch, &createdAt, &row.Session.TTLSeconds,
		&row.Source.Kind, &row.Source.Port, &row.Source.WorkspaceRoot,
		&row.Source.RelativePath, &lastActive, &closedAt,
	); err != nil {
		return PreviewRecord{}, err
	}
	if viaJSON != "" {
		if err := json.Unmarshal([]byte(viaJSON), &row.Session.Via); err != nil {
			return PreviewRecord{}, fmt.Errorf("解析预览会话 %s allowlist: %w", row.Session.ID, err)
		}
	}
	row.Session.CreatedAt = parseTime(createdAt)
	row.LastActiveAt = parseTime(lastActive)
	if closedAt.Valid {
		closed := parseTime(closedAt.String)
		row.ClosedAt = &closed
	}
	return row, nil
}

n_store_scanProjectRow.signature:
// scanProjectRow 把一行 project_locations 记录读成 proto.ProjectLocation。
func scanProjectRow(sc rowScanner) (proto.ProjectLocation, error) {
	var (
		loc		proto.ProjectLocation
		createdAt	string
	)
	if err := sc.Scan(&loc.ProjectID, &loc.Name, &loc.Path, &loc.OriginURL, &createdAt); err != nil {
		return proto.ProjectLocation{}, err
	}
	loc.CreatedAt = parseTime(createdAt)
	return loc, nil
}

n_store_scanSession.signature:
// scanSession 按 sessionColumns 的列序把一行扫成 Session。
func scanSession(sc interface{ Scan(...any) error }) (*Session, error) {
	var (
		sess		Session
		created		string
		expires		string
		lastSeen	string
		revokedAt	sql.NullString
	)
	if err := sc.Scan(&sess.ID, &sess.TokenHash, &sess.DeviceName,
		&created, &expires, &lastSeen, &revokedAt); err != nil {
		return nil, err
	}
	sess.CreatedAt = parseTime(created)
	sess.ExpiresAt = parseTime(expires)
	sess.LastSeenAt = parseTime(lastSeen)
	if revokedAt.Valid {
		t := parseTime(revokedAt.String)
		sess.RevokedAt = &t
	}
	return &sess, nil
}

n_store_scanTaskRow.signature:
// scanTaskRow 按 taskColumns 的顺序把一行扫成 proto.Task（时间与 bool 就地还原）。
//
// 返回：扫描失败时原样返回错误（含 sql.ErrNoRows，由调用方翻译成 ErrNotFound）
func scanTaskRow(sc rowScanner) (proto.Task, error) {
	var (
		task		proto.Task
		createdAt	string
		updatedAt	string
		worktreeManaged	int
		ctxTokens	int
		ctxWindow	int
	)
	if err := sc.Scan(&task.ID, &task.Target, &task.RepoPath, &task.HomeDir, &task.Carrier, &task.Squad, &task.Branch, &task.PlanPath,
		&task.PlanSummary, &task.ExecutorSession, &task.State, &createdAt, &updatedAt,
		&task.Name, &task.Executor, &task.Model, &task.WorkDir, &worktreeManaged,
		&task.BaseCommit, &task.BaseAhead, &task.RepoDirtyCount, &task.RepoDirtyFiles,
		&task.DoneNote, &task.ActualModel, &ctxTokens, &ctxWindow, &task.DisciplineName,
		&task.DisciplineVersion); err != nil {
		return proto.Task{}, err
	}
	task.CreatedAt = parseTime(createdAt)
	task.UpdatedAt = parseTime(updatedAt)
	task.WorktreeManaged = worktreeManaged != 0

	if ctxTokens > 0 {
		task.Usage = &proto.Usage{ContextTokens: ctxTokens}
		if ctxWindow > 0 {
			w := ctxWindow
			task.Usage.ContextWindow = &w
		}
	}
	return task, nil
}

n_store_trimOuterQuote.signature:
// trimOuterQuote 去掉首尾成对的引号。
func trimOuterQuote(s string) string {
	if len(s) >= 2 && (s[0] == '\'' || s[0] == '"') && s[len(s)-1] == s[0] {
		return s[1 : len(s)-1]
	}
	return s
}

n_store_unionMS.signature:
// unionMS 求区间并集的总长度。
//
// 它存在的唯一理由是并发工具：一个回合里同时发出的多个工具调用，Σdur_ms 会
// 大于它们实际占用的墙钟。拿 Σdur_ms 当墙钟用，OtherMS 会被系统性地吃成 0，
// 而且不报错。
//
// 边界：end <= start 的区间（0ms 调用、时钟回拨、脏数据）跳过而不是当成负
// 长度——负长度会把并集算小，进而把 OtherMS 算大，是一个静默错误。
func unionMS(spans []span) int64 {
	valid := make([]span, 0, len(spans))
	for _, s := range spans {
		if s.end > s.start {
			valid = append(valid, s)
		}
	}
	if len(valid) == 0 {
		return 0
	}
	sort.Slice(valid, func(i, j int) bool { return valid[i].start < valid[j].start })
	var total int64
	cur := valid[0]
	for _, s := range valid[1:] {
		if s.start > cur.end {
			total += cur.end - cur.start
			cur = s
			continue
		}
		if s.end > cur.end {
			cur.end = s.end
		}
	}
	return total + cur.end - cur.start
}

n_store_unwrapShell.signature:
// unwrapShell 剥掉 `<shell> -c '<真命令>'` 这层包装，返回里面的真命令；
// 不是这个形状时**原样返回**。
//
// 只剥一层：嵌套包装（bash -lc 'sh -c "…"'）在真实 executor 上没见过，
// 为它加循环等于给一条不存在的路径写代码。
func unwrapShell(s string) string {
	bin, rest := nextField(s)
	if !isShellBin(bin) {
		return s
	}
	flag, rest2 := nextField(rest)
	if !isShellCmdFlag(flag) {
		return s
	}
	inner := trimOuterQuote(strings.TrimSpace(rest2))
	if inner == "" {
		return s
	}
	return inner
}

n_targetclient_New.signature:
// New 按 Target 形态选路，构造一个一次性的 agentd 客户端。
//
// 参数：
//   - name: target 名，只用于日志与错误文案（会原样显示给用户）
//   - t: target 配置；t.IsRelay() 为真走 relay 隧道，否则直连 t.Addr
//   - log: 日志器；nil 时用 slog.Default()
//
// 返回：
//   - client: 可直接链式 MarkForwarded()/NoRedirect()
//   - cleanup: **恒非 nil**，调用方 defer 它即可（直连形态是 no-op）
//   - err: ErrNoEndpoint（无端点）或 relay token 熵不足
//
// 注意：
//   - 不发任何网络请求；relay 隧道由 Dialer 首次用到时惰性建立
//   - 常驻场景不要用它——每次调用都会新建一条 relay 隧道，用 Pool
func New(name string, t config.Target, log *slog.Logger) (*client.Client, func(), error) {
	c, _, cleanup, err := newWithDialer(name, t, log)
	return c, cleanup, err
}

n_targetclient_NewLocal.signature:
// NewLocal 创建当前 agentd 的本机客户端。
//
// 本机没有 target 名，也没有 relay 隧道可加入池；因此它不写入 Pool.entries，
// 由调用方按本机服务生命周期持有。远端仍必须通过 Pool.For 取得并复用客户端。
func NewLocal(addr, token string) *client.Client {
	return client.New(addr, token)
}

n_targetclient_NewPool.signature:
// NewPool 构造复用池。
//
// 参数：
//   - conf: 取当前配置快照的函数；**每次 For/Names 都会现调**，池因此跟随活配置
//   - log: 日志器；nil 时用 slog.Default()
func NewPool(conf func() *config.Config, log *slog.Logger) *Pool {
	if log == nil {
		log = slog.Default()
	}
	return &Pool{
		conf:	conf, log: log, entries: make(map[string]*entry),
		warmTick:		warmTick,
		warmBackoffInitial:	warmBackoffInitial,
		warmBackoffMax:		warmBackoffMax,
	}
}

n_targetclient_Pool_Close.signature:
// Close 关掉池内全部客户端与隧道，之后 For 一律报错。
//
// 注意：relay.Dialer.Close 是终态（closed 标志阻止重连），所以池关了就不会
// 再复活——这符合进程退出语义，不要在运行期调它来「清一下缓存」。
func (p *Pool) Close() error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed {
		return nil
	}
	p.closed = true
	for name, e := range p.entries {
		e.cleanup()
		p.log.Debug("关闭 target 客户端", "target", name)
	}
	n := len(p.entries)
	p.entries = make(map[string]*entry)
	p.log.Info("target 客户端池已关闭", "closed", n)
	return nil
}

n_targetclient_Pool_DialContext.signature:
// DialContext opens a target-scoped raw upstream connection for preview proxy use.
// The pool owns the client/dialer lifetime; callers own and close the returned conn.
func (p *Pool) DialContext(ctx context.Context, targetName, network, addr string) (net.Conn, error) {
	if _, err := p.For(targetName); err != nil {
		p.log.Warn("预览 raw dial 取得 target 失败", "target", targetName, "addr", addr, "cause", err)
		return nil, err
	}
	p.mu.Lock()
	if p.closed {
		p.mu.Unlock()
		return nil, fmt.Errorf("target 客户端池已关闭")
	}
	e := p.entries[targetName]
	dial := e.dial
	p.mu.Unlock()
	if dial == nil {
		return nil, fmt.Errorf("target %s 未配置 raw dial", targetName)
	}
	p.log.Info("预览 raw dial 开始", "target", targetName, "network", network, "addr", addr)
	conn, err := dial(ctx, network, addr)
	if err != nil {
		p.log.Warn("预览 raw dial 失败", "target", targetName, "network", network, "addr", addr, "cause", err)
		return nil, err
	}
	p.log.Info("预览 raw dial 成功", "target", targetName, "network", network, "addr", addr)
	return conn, nil
}

n_targetclient_Pool_For.signature:
// For 取一台机器的客户端，必要时构造或重建。
//
// 参数：
//   - name: target 名，必须已在配置里登记
//
// 返回：
//   - client: **调用方不负责关闭**——隧道归池所有，进程退出时由 Close 统一关
//   - err: 机器未登记、池已关闭、或 New 的选路错误（ErrNoEndpoint / token 熵不足）
//
// 注意：不发任何网络请求。relay 隧道由 Dialer 惰性建立或由 Warm 预热。
func (p *Pool) For(name string) (*client.Client, error) {
	t, ok := p.conf().Targets[name]
	if !ok {

		p.drop(name)
		p.log.Warn("请求未登记机器的客户端", "target", name)
		return nil, fmt.Errorf("target %s 未在配置中登记", name)
	}

	p.mu.Lock()
	defer p.mu.Unlock()
	if p.closed {
		return nil, fmt.Errorf("target 客户端池已关闭")
	}
	if e, ok := p.entries[name]; ok {
		if e.target == t {
			return e.client, nil
		}

		p.log.Info("target 配置变更，重建客户端", "target", name)
		e.cleanup()
		delete(p.entries, name)
	}

	c, dialer, cleanup, err := newWithDialer(name, t, p.log)
	if err != nil {
		return nil, err
	}
	e := &entry{target: t, client: c, dialer: dialer, cleanup: cleanup}
	if dialer != nil {
		e.dial = dialer.RawDialContext
	} else {
		e.dial = directOwnerRawDial(c)
	}
	p.entries[name] = e
	p.log.Info("target 客户端已建立并入池", "target", name, "relay", t.IsRelay(), "pool_size", len(p.entries))
	return c, nil
}

n_targetclient_Pool_Names.signature:
// Names 返回当前配置里全部 target 名，已排序。
//
// 排序是为了让 UI 列表与日志顺序稳定：每次刷新都跳序会让人以为数据在变。
func (p *Pool) Names() []string {
	targets := p.conf().Targets
	names := make([]string, 0, len(targets))
	for name := range targets {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

n_targetclient_Pool_Warm.signature:
// Warm 跑预热循环，阻塞直到 ctx 取消。
//
// 参数：
//   - ctx: 生命周期；取消即返回
//
// 注意：
//   - 只对 relay 形态的 target 生效
//   - 单台失败按 1s→60s 指数退避，退避期内跳过该台，不影响其余
//   - 新增的机器由下一轮扫到；删除的机器自然不再出现在 Names() 里
//   - 预热成功只说明隧道，不能当成 agentd 可达（冻结 9）。
func (p *Pool) Warm(ctx context.Context) {
	p.log.Info("relay 隧道预热循环启动", "tick", p.warmTick.String())
	states := make(map[string]*warmState)
	t := time.NewTicker(p.warmTick)
	defer t.Stop()

	p.warmOnce(ctx, states)
	for {
		select {
		case <-ctx.Done():
			p.log.Info("relay 隧道预热循环退出", "reason", "上下文取消")
			return
		case <-t.C:
			p.warmOnce(ctx, states)
		}
	}
}

n_targetclient_Pool_drop.signature:
// drop 关掉并移出一条缓存条目；不存在时无副作用。
func (p *Pool) drop(name string) {
	p.mu.Lock()
	defer p.mu.Unlock()
	e, ok := p.entries[name]
	if !ok {
		return
	}
	e.cleanup()
	delete(p.entries, name)
	p.log.Info("target 已从池中移出", "target", name, "pool_size", len(p.entries))
}

n_targetclient_Pool_ensureTunnel.signature:
// ensureTunnel 对一台机器建隧道；测试可用 p.ensure 替换掉真实拨号。
func (p *Pool) ensureTunnel(ctx context.Context, name string) error {
	if p.ensure != nil {
		return p.ensure(ctx, name)
	}
	return p.realEnsure(ctx, name)
}

n_targetclient_Pool_realEnsure.signature:
// realEnsure 是生产实现：取出（必要时构造）该机器的 Dialer 并建隧道。
func (p *Pool) realEnsure(ctx context.Context, name string) error {
	if _, err := p.For(name); err != nil {
		return err
	}
	p.mu.Lock()
	e, ok := p.entries[name]
	p.mu.Unlock()
	if !ok || e.dialer == nil {

		return nil
	}
	return e.dialer.Ensure(ctx)
}

n_targetclient_Pool_size.signature:
// size 返回池内条目数，仅供测试断言。
func (p *Pool) size() int {
	p.mu.Lock()
	defer p.mu.Unlock()
	return len(p.entries)
}

n_targetclient_Pool_warmOnce.signature:
// warmOnce 跑一轮预热：对每台处于「可以重试」状态的 relay 机器建一次隧道。
func (p *Pool) warmOnce(ctx context.Context, states map[string]*warmState) {
	targets := p.conf().Targets
	now := time.Now()
	warmed, skipped, failed := 0, 0, 0

	for _, name := range p.Names() {
		t := targets[name]
		if !t.IsRelay() {
			continue
		}
		if st, ok := states[name]; ok && now.Before(st.nextAt) {
			skipped++
			continue
		}

		callCtx, cancel := context.WithTimeout(ctx, p.warmTick)
		err := p.ensureTunnel(callCtx, name)
		cancel()
		if err != nil {
			failed++
			st := states[name]
			if st == nil {
				st = &warmState{backoff: p.warmBackoffInitial}
				states[name] = st
			} else {
				st.backoff *= 2
				if st.backoff > p.warmBackoffMax {
					st.backoff = p.warmBackoffMax
				}
			}
			st.nextAt = now.Add(st.backoff)
			p.log.Warn("relay 隧道预热失败，等待后重试", "target", name, "node", t.Node,
				"backoff_ms", st.backoff.Milliseconds(), "cause", err)
			continue
		}
		warmed++
		if _, had := states[name]; had {

			delete(states, name)
			p.log.Info("relay 隧道预热恢复", "target", name, "node", t.Node)
		}
	}
	p.log.Debug("relay 隧道预热完成一轮", "warmed", warmed, "skipped", skipped, "failed", failed)
}

n_targetclient_directOwnerRawDial.signature:
// directOwnerRawDial asks the owner agentd to dial dest on the owner's host.
// Loopback spellings are normalized to 127.0.0.1 so owner static servers bound
// only to 127.0.0.1 are reachable. The coordinator never rewrites dest onto
// target.Addr's host — that was the Tailscale IP leak (B301).
func directOwnerRawDial(c *client.Client) func(context.Context, string, string) (net.Conn, error) {
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		host, port, err := net.SplitHostPort(addr)
		if err != nil {
			return nil, fmt.Errorf("preview raw dial 地址无端口 %q: %w", addr, err)
		}
		dest := addr
		if strings.EqualFold(host, "localhost") || isLoopbackHost(host) {
			dest = net.JoinHostPort("127.0.0.1", port)
		}
		return c.DialPreviewRaw(ctx, network, dest)
	}
}

n_targetclient_isLoopbackHost.signature:
func isLoopbackHost(host string) bool {
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

n_targetclient_newWithDialer.signature:
// newWithDialer 与 New 同源，额外把 relay Dialer 交给调用方（池要用它预热）。
// New 是它的薄壳：外部调用方不该拿到 Dialer，那是池的内部事务。
func newWithDialer(name string, t config.Target, log *slog.Logger) (*client.Client, *relay.Dialer, func(), error) {
	if log == nil {
		log = slog.Default()
	}
	noop := func() {}
	if t.IsRelay() {
		if err := relay.CheckTokenEntropy(t.Token); err != nil {
			log.Error("relay target 的 token 熵不足，拒绝构造", "target", name, "node", t.Node)
			return nil, nil, noop, fmt.Errorf("target %s: %w", name, err)
		}
		d := relay.NewDialer(t.Relay, t.Credential, t.Node, t.Token, "", log)
		log.Info("target 走 relay 传输", "target", name, "node", t.Node, "relay_url", t.Relay)
		return client.NewRelay(d, t.Token), d, func() { _ = d.Close() }, nil
	}
	if t.Addr == "" {
		log.Error("target 无端点，既没有 addr 也没有 relay", "target", name)
		return nil, nil, noop, fmt.Errorf("target %s: %w", name, ErrNoEndpoint)
	}
	log.Debug("target 走直连传输", "target", name, "addr", t.Addr)
	return client.New(t.Addr, t.Token), nil, noop, nil
}

