n_termseq_SummarizeIn.signature:
// SummarizeIn 分类终端模拟器送给应用的字节（用户按键 / 焦点 / 鼠标）。
func SummarizeIn(p []byte) []string {
	var out []string
	wheelUp, wheelDown := 0, 0
	flush := func() {
		if wheelUp > 0 {
			out = append(out, fmt.Sprintf("wheel-up×%d", wheelUp))
			wheelUp = 0
		}
		if wheelDown > 0 {
			out = append(out, fmt.Sprintf("wheel-down×%d", wheelDown))
			wheelDown = 0
		}
	}
	i := 0
	for i < len(p) {
		if p[i] != 0x1b {
			i++
			continue
		}
		if i+2 < len(p) && p[i+1] == '[' && p[i+2] == 'O' {
			flush()
			out = append(out, "focus-out")
			i += 3
			continue
		}
		if i+2 < len(p) && p[i+1] == '[' && p[i+2] == 'I' {
			flush()
			out = append(out, "focus-in")
			i += 3
			continue
		}
		if btn, n, ok := sgrMouse(p[i:]); ok {
			if btn == 64 {
				wheelUp++
			} else if btn == 65 {
				wheelDown++
			} else {
				flush()
				out = append(out, fmt.Sprintf("sgr-btn=%d", btn))
			}
			i += n
			continue
		}
		i++
	}
	flush()
	return out
}

n_termseq_SummarizeOut.signature:
// SummarizeOut 分类应用（TUI）写给模拟器的 DECSET/DECRST。
func SummarizeOut(p []byte) []string {
	var out []string
	i := 0
	for i < len(p) {
		if p[i] != 0x1b {
			i++
			continue
		}
		modes, hl, n, ok := decPrivate(p[i:])
		if !ok {
			i++
			continue
		}
		for _, m := range modes {
			if _, watch := watchedModes[m]; watch {
				out = append(out, strconv.Itoa(m)+string(hl))
			}
		}
		i += n
	}
	return out
}

n_termseq_decPrivate.signature:
func decPrivate(p []byte) (modes []int, hl byte, n int, ok bool) {

	if len(p) < 5 || p[0] != 0x1b || p[1] != '[' || p[2] != '?' {
		return nil, 0, 0, false
	}
	j := 3
	for j < len(p) {
		var v int
		v, j, ok = readInt(p, j)
		if !ok {
			return nil, 0, 0, false
		}
		modes = append(modes, v)
		if j >= len(p) {
			return nil, 0, 0, false
		}
		if p[j] == ';' {
			j++
			continue
		}
		if p[j] == 'h' || p[j] == 'l' {
			return modes, p[j], j + 1, true
		}
		return nil, 0, 0, false
	}
	return nil, 0, 0, false
}

n_termseq_readInt.signature:
func readInt(p []byte, i int) (int, int, bool) {
	if i >= len(p) || p[i] < '0' || p[i] > '9' {
		return 0, i, false
	}
	n := 0
	for i < len(p) && p[i] >= '0' && p[i] <= '9' {
		n = n*10 + int(p[i]-'0')
		i++
	}
	return n, i, true
}

n_termseq_sgrMouse.signature:
func sgrMouse(p []byte) (btn int, n int, ok bool) {

	if len(p) < 8 || p[0] != 0x1b || p[1] != '[' || p[2] != '<' {
		return 0, 0, false
	}
	j := 3
	btn, j, ok = readInt(p, j)
	if !ok || j >= len(p) || p[j] != ';' {
		return 0, 0, false
	}
	j++
	_, j, ok = readInt(p, j)
	if !ok || j >= len(p) || p[j] != ';' {
		return 0, 0, false
	}
	j++
	_, j, ok = readInt(p, j)
	if !ok || j >= len(p) || (p[j] != 'M' && p[j] != 'm') {
		return 0, 0, false
	}
	return btn, j + 1, true
}

n_testhttp_CloseIdleConnections.signature:
// CloseIdleConnections closes tracked idle transports and the standard default transport.
// It is intentionally separate from request cancellation.
func CloseIdleConnections() {
	if tr, ok := http.DefaultTransport.(*http.Transport); ok {
		tr.CloseIdleConnections()
	}
	configuredTransports.Lock()
	all := make([]*http.Transport, 0, len(configuredTransports.set))
	for tr := range configuredTransports.set {
		all = append(all, tr)
	}
	configuredTransports.Unlock()
	for _, tr := range all {
		tr.CloseIdleConnections()
	}
}

n_testhttp_ConfigureClient.signature:
// ConfigureClient replaces only a *http.Transport's dial hooks. A nil Transport is cloned
// from http.DefaultTransport so the process-global default is never mutated; a non-*http.Transport
// is intentionally left unchanged because it has no safe TCP hook.
func ConfigureClient(client *http.Client) {
	if client == nil {
		return
	}
	tr, ok := client.Transport.(*http.Transport)
	if client.Transport == nil {
		defaultTransport, defaultOK := http.DefaultTransport.(*http.Transport)
		if !defaultOK {
			return
		}
		tr = defaultTransport.Clone()
		client.Transport = tr
		ok = true
	}
	if !ok {
		return
	}
	if defaultTransport, defaultOK := http.DefaultTransport.(*http.Transport); defaultOK && tr == defaultTransport {
		tr = defaultTransport.Clone()
		client.Transport = tr
	}
	configuredTransports.Lock()
	if _, exists := configuredTransports.set[tr]; exists {
		configuredTransports.Unlock()
		return
	}
	configuredTransports.set[tr] = struct{}{}
	configuredTransports.Unlock()

	baseContext := tr.DialContext
	baseDial := tr.Dial
	if baseContext == nil {
		if baseDial != nil {
			baseContext = func(_ context.Context, network, addr string) (net.Conn, error) {
				return baseDial(network, addr)
			}
		} else {
			dialer := &net.Dialer{}
			baseContext = dialer.DialContext
		}
	}
	tr.Dial = nil
	tr.DialContext = RetryDialContext(DialContext(baseContext))
}

n_testhttp_NewServer.signature:
// NewServer starts a linger-enabled httptest server, configures the default client and
// registers cleanup that closes the server before tracked idle transports.
func NewServer(t testing.TB, handler http.Handler) *httptest.Server {
	t.Helper()
	oldDefault := http.DefaultClient.Transport
	ts := httptest.NewUnstartedServer(handler)
	ts.Listener = &lingerListener{Listener: ts.Listener}
	ts.Start()
	ConfigureClient(http.DefaultClient)
	ConfigureClient(ts.Client())
	t.Cleanup(func() {
		ts.Close()
		CloseIdleConnections()
		http.DefaultClient.Transport = oldDefault
	})
	return ts
}

n_testhttp_NewUnstartedServer.signature:
// NewUnstartedServer returns a linger-enabled server whose caller may replace Listener or
// modify Config before Start. The caller must call ConfigureClient(ts.Client()) after Start
// because httptest creates its client inside Start.
func NewUnstartedServer(t testing.TB, handler http.Handler) *httptest.Server {
	t.Helper()
	oldDefault := http.DefaultClient.Transport
	ts := httptest.NewUnstartedServer(handler)
	ts.Listener = &lingerListener{Listener: ts.Listener}
	ConfigureClient(http.DefaultClient)
	t.Cleanup(func() {
		ts.Close()
		CloseIdleConnections()
		http.DefaultClient.Transport = oldDefault
	})
	return ts
}

n_testhttp_RetryDialContext.signature:
// RetryDialContext retries only the two Darwin loopback address-allocation errors and
// only up to MaxDialAttempts. A successful loopback connection gets client-side linger.
func RetryDialContext(base DialContext) DialContext {
	if base == nil {
		dialer := &net.Dialer{}
		base = dialer.DialContext
	}
	return func(ctx context.Context, network, addr string) (net.Conn, error) {
		var last error
		for attempt := 0; attempt < MaxDialAttempts; attempt++ {
			conn, err := base(ctx, network, addr)
			if err == nil {
				return prepareClientConn(conn, addr)
			}
			last = err
			if !isLoopbackAddr(addr) || !retryableAddressError(err) || attempt+1 == MaxDialAttempts {
				return nil, err
			}
			timer := time.NewTimer(dialRetryDelay)
			select {
			case <-ctx.Done():
				if !timer.Stop() {
					<-timer.C
				}
				return nil, ctx.Err()
			case <-timer.C:
			}
		}
		return nil, last
	}
}

n_testhttp_isLoopbackAddr.signature:
func isLoopbackAddr(addr string) bool {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return false
	}
	host = strings.Trim(host, "[]")
	if strings.EqualFold(host, "localhost") {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

n_testhttp_lingerListener_Accept.signature:
func (l *lingerListener) Accept() (net.Conn, error) {
	conn, err := l.Listener.Accept()
	if err != nil {
		return nil, err
	}
	tcp, ok := conn.(*net.TCPConn)
	if !ok {
		_ = conn.Close()
		return nil, errors.New("testhttp: httptest listener returned non-TCP connection")
	}
	if err := setLinger(tcp); err != nil {
		_ = conn.Close()
		return nil, err
	}
	return tcp, nil
}

n_testhttp_prepareClientConn.signature:
func prepareClientConn(conn net.Conn, addr string) (net.Conn, error) {
	if !isLoopbackAddr(addr) {
		return conn, nil
	}
	tcp, ok := conn.(*net.TCPConn)
	if !ok {
		_ = conn.Close()
		return nil, errors.New("testhttp: loopback dial returned non-TCP connection")
	}
	if err := setLinger(tcp); err != nil {
		_ = conn.Close()
		return nil, err
	}
	return tcp, nil
}

n_testhttp_retryableAddressError.signature:
func retryableAddressError(err error) bool {
	return errors.Is(err, syscall.EADDRNOTAVAIL) || strings.Contains(err.Error(), "can't assign requested address")
}

n_testperm_DenyRead.signature:
// DenyRead 清除 path 的全部读 permission bits，并用一次真实读探针确认限制。
//
// 参数：t 是测试句柄；path 是已存在的普通文件。
// 返回：无；限制生效则返回给调用点继续执行，限制失效则恢复现场并 skip。
// 注意：目录不是本入口的目标；无关探针错误不会被转换成 skip。
func DenyRead(t testing.TB, path string) {
	t.Helper()
	info := targetInfo(t, path, "读")
	if info.IsDir() {
		slog.Default().Error("读权限前提目标类型不支持", "operation", "读", "path", path, "reason", "目标是目录而不是普通文件")
		t.Fatalf("读权限前提目标必须是文件，path=%q", path)
		return
	}
	restricted := info.Mode().Perm() &^ 0o444
	apply(t, path, info.Mode().Perm(), restricted, "读", func() error {
		f, err := os.Open(path)
		if err != nil {
			return err
		}
		return f.Close()
	})
}

n_testperm_DenyWrite.signature:
// DenyWrite 清除 path 的全部写 permission bits，并用一次真实写探针确认限制。
//
// 参数：t 是测试句柄；path 是已存在的目录或普通文件。
// 返回：无；限制生效则返回给调用点继续执行，限制失效则恢复现场并 skip。
// 注意：只有 errors.Is(err, fs.ErrPermission) 才算限制生效；其他探针错误会使测试失败。
func DenyWrite(t testing.TB, path string) {
	t.Helper()
	info := targetInfo(t, path, "写")
	restricted := info.Mode().Perm() &^ 0o222
	if info.IsDir() {
		apply(t, path, info.Mode().Perm(), restricted, "写", func() error {
			f, err := os.CreateTemp(path, ".handoff-permission-probe-*")
			if err != nil {
				return err
			}
			name := f.Name()
			closeErr := f.Close()
			removeErr := os.Remove(name)
			if closeErr != nil {
				return closeErr
			}
			return removeErr
		})
		return
	}
	apply(t, path, info.Mode().Perm(), restricted, "写", func() error {
		f, err := os.OpenFile(path, os.O_WRONLY, 0)
		if err != nil {
			return err
		}
		return f.Close()
	})
}

n_testperm_decideProbe.signature:
func decideProbe(operation, path string, probeErr error) probeDecision {
	if probeErr == nil {
		return probeDecision{
			action:	probeSkip,
			message: fmt.Sprintf("权限前提未成立：%s 探针成功，当前机器无法表达 path=%q 的限制；这不是禁用用例",
				operation, path),
		}
	}
	if errors.Is(probeErr, fs.ErrPermission) {
		return probeDecision{
			action:		probeContinue,
			message:	fmt.Sprintf("限制已生效：%s 探针被拒绝，path=%q", operation, path),
		}
	}
	return probeDecision{
		action:	probeFatal,
		message: fmt.Sprintf("权限探针出现无关错误：operation=%s path=%q err=%v",
			operation, path, probeErr),
	}
}

n_toolchain_CredRelPathFor.signature:
// CredRelPathFor 暴露既有凭据表的只读包装，供组装点注入 hostapi。表本身仍只
// 在本包维护，避免执行域复制 opencode/grok/codex 的相对路径或平台规则。
func CredRelPathFor(name string) (string, bool) {
	return credRelPathFor(name)
}

n_toolchain_Detect.signature:
// Detect 探测各家 executor 的状态。
//
// 返回：
//   - 固定项，顺序恒为 opencode / claude / grok / codex / agy
//
// 注意：
//   - 取不到 HOME 时，装了的执行者一律报 StateAuthUnknown。它既不是 StateMissing
//     （「凭证查不到」和「没装」是两件事，混为一谈会让用户去重装一个已经装好的
//     东西），也不是 StateNoCreds（那是一个「没登录」的断言，而此时凭证文件
//     根本没查过，下这个断言是在猜）
func Detect() []Result {
	home, homeErr := userHomeDir()
	out := make([]Result, 0, len(order))
	for _, name := range order {
		r := Result{Name: name}
		p, err := lookPath(name)
		if err != nil {
			r.State = StateMissing
			out = append(out, r)
			continue
		}
		r.Path = p
		if name == "claude" || name == "agy" {

			r.State = StateAuthUnknown
			out = append(out, r)
			continue
		}
		rel, ok := credRelPathFor(name)
		if !ok || homeErr != nil {

			r.State = StateAuthUnknown
			out = append(out, r)
			continue
		}
		if statFile(filepath.Join(home, rel)) == nil {
			r.State = StateReady
		} else {
			r.State = StateNoCreds
		}
		out = append(out, r)
	}
	return out
}

n_toolchain_FirstReady.signature:
// FirstReady 返回第一个就绪的 executor 名；一个都没有时返回空串。
//
// 供 init 挑 executor.default 的默认值用。**不把 StateAuthUnknown 算进来**，
// 理由同 Result.Ready。
func FirstReady(rs []Result) string {
	for _, r := range rs {
		if r.Ready() {
			return r.Name
		}
	}
	return ""
}

n_toolchain_Result_Ready.signature:
// Ready 表示「可以放心把它设成缺省执行者」。
//
// 注意：StateAuthUnknown 返回 **false**。它的语义是「不知道」，
// 把不知道当成就绪，就是替用户做了一个没有依据的判断。
func (r Result) Ready() bool	{ return r.State == StateReady }

n_toolchain_State_String.signature:
// String 返回给人看的中文短语（init 的表格直接打印它）。
func (s State) String() string {
	switch s {
	case StateMissing:
		return "没装"
	case StateNoCreds:
		return "已安装，未登录"
	case StateReady:
		return "就绪"
	case StateAuthUnknown:
		return "已安装，登录态未知"
	}
	return "未知"
}

n_toolchain_credRelPathFor.signature:
// credRelPathFor 返回某家 executor 在当前平台的凭证文件相对路径；
// 第二个返回值为 false 表示「本平台没有可靠的文件判据」。
//
// why 要按平台过滤：credRelPath 里 opencode 那条是 XDG 落点，Windows 上 opencode
// 不用它。拿一个在该平台不成立的路径去断言「未登录」，与拿 ~/.claude.json 断言
// claude 已就绪是同一种撒谎——后者正是 claude 被排除在表外的理由。
// 查不到判据时调用方会落到 StateAuthUnknown（「查不了」≠「没登录」）。
//
// grok 与 codex 不在此列：~/.grok、~/.codex 在 Windows 上同样成立。
func credRelPathFor(name string) (string, bool) {
	if goos == "windows" && name == "opencode" {
		return "", false
	}
	rel, ok := credRelPath[name]
	return rel, ok
}

n_turn_AppendRender.signature:
// AppendRender 把 delta 追加到 renderLogPath（不存在则创建，权限 0644）。
//
// 注意：调用方通常在高频文本增量路径上调用本函数，失败应只 Warn 不中断回合
// ——可见性是增强能力，不值得为它挂掉任务。
func AppendRender(renderLogPath, delta string) error {
	f, err := os.OpenFile(renderLogPath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("打开 %s: %w", renderLogPath, err)
	}
	defer f.Close()
	if _, err := f.WriteString(delta); err != nil {
		return fmt.Errorf("写 %s: %w", renderLogPath, err)
	}
	return nil
}

n_turn_ClampQuestion.signature:
// ClampQuestion 把兜底分类产出的整段回合文本收敛到 QuestionTextLimit，
// 超出时追加尾缀指明全文去处。
//
// 为什么**不能**复用 TruncateMarked：两者的「全文在哪」不同，尾缀因此必须不同。
//   - TruncateMarked 用于 permission 文本，全文在工单里（B6 契约：工单存全文、
//     事件截断），协调者 `handoff show` 就能拿到，`…（已截断）` 足够；
//   - 本函数用于 question 文本，全文**不在工单里**，只在任务目录的 render.log。
//     不指路 = 协调者拿到半截文本且不知道去哪找全文，证据链断掉。
//
// 这段尾缀是逐字从 opencode 现有实现搬来的，opencode 的
// regression_group_a_test.go 断言 `strings.Contains(ev.Text, "render.log")`，
// 改字面量即回归。
func ClampQuestion(text string) string {
	if len([]rune(text)) <= QuestionTextLimit {
		return text
	}
	return TruncateRunes(text, QuestionTextLimit) +
		"\n\n…（回合文本过长已截断，完整内容见任务目录 render.log）"
}

n_turn_DenyGuidanceText.signature:
// DenyGuidanceText 渲染「操作被拒 + 理由 + 别再重试」的正文。
//
// 参数：reason 为协调者给出的原因，调用方保证已 trim 且非空
// 返回：可直接下发给模型的正文
//
// 注意：末句「不要重复发起同一请求」不是客套——不给这句，模型被拒后最常见的
// 下一步就是原地再试一次同样的操作，白烧一个回合。
func DenyGuidanceText(reason string) string {
	return "你请求的操作已被协调者拒绝。原因：" + reason +
		"\n请据此调整做法后继续，不要重复发起同一请求。"
}

n_turn_FinalText.signature:
// FinalText 返回用于终态 Result 的正文窗口。
//
// 参数：text 是 adapter 收集到的完整回合正文。
// 返回：不超过 FinalTextLimit 个 rune 的正文尾部；短正文原样返回。
// 注意：这是传输边界的有界投影，不应替代 render.log 作为完整取证来源。
func FinalText(text string) string {
	return TailRunes(text, FinalTextLimit)
}

n_turn_FrameWriter_BeginTurn.signature:
// BeginTurn 开启新回合：turn 自增、part 计数归零，并写一条 turn_start 帧。
//
// reason 只应是 "dispatch"（Adapter.Start）或 "send"（Adapter.Send）。
// instructions 是 send 时的指令/应答原文（dispatch 传 ""）——写进帧供前端
// 渲染审核者气泡；日志里只记长度不记原文，避免把长指令刷进日志。
//
// 为什么 turn 自增与 turn_start 的写入必须在同一个临界区：SSE reader 是跨回合
// 长命的，上一回合的尾包可能正与 Send 并发。若先放锁再写 turn_start，并发帧
// 会带着新 turn 号排在 turn_start **之前**落盘，前端把正文画到回合分隔线上面。
func (w *FrameWriter) BeginTurn(reason, instructions string) error {
	if w == nil {
		return nil
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	w.turn++
	w.nextPart = 0
	w.log.Info("回合开始", "turn", w.turn, "reason", reason, "instructions_len", len(instructions))
	return w.appendLocked(proto.Frame{Type: proto.FrameTurnStart, Reason: reason, Instructions: instructions})
}

n_turn_FrameWriter_EventRef.signature:
// EventRef 写一条控制面事件的引用帧。
//
// 只存 seq 与类型名，不复制 payload：payload 的真相在 events 表，复制一份
// 就有了两份会漂移的真相。
func (w *FrameWriter) EventRef(refSeq int64, eventType string) error {
	if w == nil {
		return nil
	}
	return w.append(proto.Frame{Type: proto.FrameEvent, RefSeq: refSeq, Event: eventType})
}

n_turn_FrameWriter_NextPart.signature:
// NextPart 分配一个回合内唯一的 part 标识（p01、p02…）。
//
// 上游流自带 part / block / item 标识时**优先沿用上游的**，本方法只服务
// 那些没有标识的流——两个来源混用不会撞车，因为 p 前缀是本方法独有的。
func (w *FrameWriter) NextPart() string {
	if w == nil {
		return ""
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	w.nextPart++
	return fmt.Sprintf("p%02d", w.nextPart)
}

n_turn_FrameWriter_Reasoning.signature:
// Reasoning 写一条思维链增量帧。
//
// 注意：本方法只负责落盘。「思维链不能进回合正文」是 adapter 的判定，
// 不在这里——本包不认识回合正文。
func (w *FrameWriter) Reasoning(part, delta string) error {
	if w == nil || delta == "" {
		return nil
	}
	return w.append(proto.Frame{Type: proto.FrameReasoning, Part: part, Delta: delta})
}

n_turn_FrameWriter_Text.signature:
// Text 写一条模型正文增量帧。
func (w *FrameWriter) Text(part, delta string) error {
	if w == nil || delta == "" {
		return nil
	}
	return w.append(proto.Frame{Type: proto.FrameText, Part: part, Delta: delta})
}

n_turn_FrameWriter_ToolCall.signature:
// ToolCall 写一条工具调用帧；input 超长时头尾截断。
func (w *FrameWriter) ToolCall(part, tool, input string) error {
	if w == nil {
		return nil
	}
	out, truncated, orig := HeadTail(input, FrameFieldHead, FrameFieldTail)
	if truncated {
		w.log.Debug("工具入参已截断", "tool", tool, "bytes", orig)
	}
	return w.append(proto.Frame{
		Type:	proto.FrameToolCall, Part: part, Tool: tool,
		Input:	out, Truncated: truncated, Bytes: truncatedBytes(truncated, orig),
	})
}

n_turn_FrameWriter_ToolResult.signature:
// ToolResult 写一条工具结果帧；output 超长时头尾截断。
//
// 参数 dur 是本次工具调用的耗时（调用方从配对的 tool_call 时刻算出）。
// **dur < 0 表示「不知道」**，此时帧上不带 dur_ms。刻意不用 0 表达未知：
// 0ms 是一次真实可能的极快调用，用它当哨兵就再也分不清「没报」与「很快」。
//
// 为什么改签名而不是新增一个带耗时的变体：变体会让「忘记传耗时」成为一个
// 不报错的选项，而全仓调用方只有个位数——改签名的成本远低于让一半调用方
// 静默不报耗时（契约文档 §6.4 的拍板记录）。
func (w *FrameWriter) ToolResult(part, status, output string, dur time.Duration) error {
	if w == nil {
		return nil
	}
	out, truncated, orig := HeadTail(output, FrameFieldHead, FrameFieldTail)
	if truncated {
		w.log.Debug("工具输出已截断", "status", status, "bytes", orig)
	}
	return w.append(proto.Frame{
		Type:	proto.FrameToolResult, Part: part, Status: status,
		Output:	out, Truncated: truncated, Bytes: truncatedBytes(truncated, orig),
		DurMS:	durMS(dur),
	})
}

n_turn_FrameWriter_Turn.signature:
// Turn 返回当前回合号（还没开过回合时为 0）。
//
// 存在的唯一理由：段切分器（Segmenter）必须与帧共用同一个回合号。
// **不要在别处自建回合计数器**——FrameWriter 的 turn 在进程重启后从
// frames.jsonl 尾部恢复（见 resumeFrameState），自建的计数器会从 0 重来，
// 于是第二次运行的 "turn/1" 键会覆盖掉第一次运行的真数据，且账面无异常。
func (w *FrameWriter) Turn() int {
	if w == nil {
		return 0
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.turn
}

n_turn_FrameWriter_append.signature:
// append 分配 seq、编码成一行并追加进文件。
//
// 注意：seq 分配与写入必须在同一把锁内——分配完再放锁去写，两个 goroutine
// 就可能以 2、1 的顺序落盘，按 offset 续读的客户端会看到 seq 倒退。
func (w *FrameWriter) append(f proto.Frame) error {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.appendLocked(f)
}

n_turn_FrameWriter_appendLocked.signature:
// appendLocked 是 append 的锁内实现：调用方必须已持有 w.mu。
//
// 为什么拆出来：BeginTurn 要在同一临界区里「turn 自增 + 写 turn_start」，
// 需要复用这里的编码与落盘逻辑而又不重复加锁。
func (w *FrameWriter) appendLocked(f proto.Frame) error {
	w.seq++
	f.Seq = w.seq
	f.Turn = w.turn
	f.TS = time.Now()

	line, err := json.Marshal(f)
	if err != nil {
		return fmt.Errorf("编码帧 seq=%d: %w", f.Seq, err)
	}
	if len(line) > frameLineLimit {

		w.log.Warn("单帧超出行上限，仍照写但请排查字段体量",
			"seq", f.Seq, "type", f.Type, "line_bytes", len(line), "limit", frameLineLimit)
	}
	line = append(line, '\n')

	file, err := os.OpenFile(w.path, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		return fmt.Errorf("打开 %s: %w", w.path, err)
	}
	defer file.Close()
	if _, err := file.Write(line); err != nil {
		return fmt.Errorf("写 %s: %w", w.path, err)
	}
	return nil
}

n_turn_GitCommonDir.signature:
// GitCommonDir 返回 repoPath 所属仓库的共享 git 公共目录。
//
// 参数：repoPath 是主仓库或 linked worktree 的工作目录。
// 返回：绝对、Clean 的 common git directory；repoPath 非 git 仓库、git 不可用、
// 输出为空或路径绝对化失败时返回错误。此函数只读，不改变仓库配置。
func GitCommonDir(repoPath string) (string, error) {
	out, err := exec.Command("git", "-C", repoPath, "rev-parse", "--git-common-dir").Output()
	if err != nil {
		return "", fmt.Errorf("git rev-parse --git-common-dir: %w", err)
	}
	common := strings.TrimSpace(string(out))
	if common == "" {
		return "", fmt.Errorf("git rev-parse --git-common-dir returned empty path")
	}
	if !filepath.IsAbs(common) {
		common = filepath.Join(repoPath, common)
	}
	abs, err := filepath.Abs(common)
	if err != nil {
		return "", fmt.Errorf("absolute git-common-dir %q: %w", common, err)
	}
	return filepath.Clean(abs), nil
}

n_turn_GitDir.signature:
// GitDir 返回 repoPath 所属工作树的私有 git 目录。
//
// 参数：repoPath 是主仓库或 linked worktree 的工作目录。
// 返回：绝对、Clean 的 git directory；repoPath 非 git 仓库、git 不可用、输出为空
// 或路径绝对化失败时返回错误。此函数只读 git，不依赖工作树目录名，也不改变配置。
func GitDir(repoPath string) (string, error) {
	out, err := exec.Command("git", "-C", repoPath, "rev-parse", "--absolute-git-dir").Output()
	if err != nil {
		return "", fmt.Errorf("git rev-parse --absolute-git-dir: %w", err)
	}
	privateDir := strings.TrimSpace(string(out))
	if privateDir == "" {
		return "", fmt.Errorf("git rev-parse --absolute-git-dir returned empty path")
	}
	if !filepath.IsAbs(privateDir) {
		privateDir = filepath.Join(repoPath, privateDir)
	}
	abs, err := filepath.Abs(privateDir)
	if err != nil {
		return "", fmt.Errorf("absolute git-dir %q: %w", privateDir, err)
	}
	return filepath.Clean(abs), nil
}

n_turn_GitTurnStatus.signature:
// GitTurnStatus 返回工作区当前分支、HEAD commit，以及相对 startCommit 是否有新提交。
//
// 参数：
//   - repoPath: 任务工作目录（仓库或 worktree 路径）
//   - startCommit: 回合起点的 HEAD；空串表示起点未知，此时 hasNew 恒为 false
//
// 返回：分支名、HEAD hash、是否有新提交、错误
//
// 为什么需要它：模型可能不守收尾纪律（不输出 trailer）。此时唯一可信的是 git
// 实况——有新提交才可能是「干完了」，没有就该交协调者，绝不替模型宣布完成。
func GitTurnStatus(repoPath, startCommit string) (branch, commit string, hasNew bool, err error) {
	run := func(args ...string) (string, error) {
		out, err := exec.Command("git", append([]string{"-C", repoPath}, args...)...).Output()
		if err != nil {
			return "", fmt.Errorf("git %s: %w", strings.Join(args, " "), err)
		}
		return strings.TrimSpace(string(out)), nil
	}
	if branch, err = run("rev-parse", "--abbrev-ref", "HEAD"); err != nil {
		return "", "", false, err
	}
	if commit, err = run("rev-parse", "HEAD"); err != nil {
		return branch, "", false, err
	}

	return branch, commit, startCommit != "" && commit != "" && commit != startCommit, nil
}

n_turn_HeadTail.signature:
// HeadTail 把 s 压成「头 head 字节 + 截断标记 + 尾 tail 字节」。
//
// 参数：
//   - s:    原始字符串
//   - head: 头部保留的字节预算（按 rune 边界向内收缩，不会切出半个字符）
//   - tail: 尾部保留的字节预算（同上）
//
// 返回：
//   - out:       结果字符串；未截断时与 s 相同
//   - truncated: 是否确实发生了截断
//   - orig:      s 的原始字节数（无论是否截断都返回真实值）
//
// 注意：head+tail 已能覆盖整串时原样返回——否则会出现「截断后比原文还长」
// （多了一个标记）这种荒唐结果。
func HeadTail(s string, head, tail int) (out string, truncated bool, orig int64) {
	orig = int64(len(s))
	if len(s) <= head+tail {
		return s, false, orig
	}
	h := s[:sliceToRuneBoundary(s, head)]
	t := s[len(s)-tailToRuneBoundary(s, tail):]
	var b strings.Builder
	b.WriteString(h)
	b.WriteString(executor.TruncationMarker)
	b.WriteString(t)
	return b.String(), true, orig
}

n_turn_HeadTailRunes.signature:
// HeadTailRunes 按 **rune** 预算做头尾截断，中间以省略标记相连。
//
// 参数：head / tail 为头尾各保留的 rune 数；两者之和 >= 总长时原样返回。
// 返回：截断后的串（未截断时即原串）。
//
// 为什么不复用 HeadTail：那个函数的预算单位是**字节**（headtail.go:38），
// 用在中文命令上会从一个多字节字符中间切开，落进 SQLite 的就是半个字符。
// 帧字段用字节预算是对的（它防的是行长失控），Detail 用 rune 预算也是对的
// （它防的是凭据面扩大），两个单位服务两个目的，不该互相迁就。
func HeadTailRunes(s string, head, tail int) string {
	r := []rune(s)
	if head < 0 {
		head = 0
	}
	if tail < 0 {
		tail = 0
	}
	if len(r) <= head+tail {
		return s
	}
	return string(r[:head]) + executor.TruncationMarker + string(r[len(r)-tail:])
}

n_turn_NewFrameWriter.signature:
// NewFrameWriter 打开（或准备创建）taskDir 下的 frames.jsonl，并恢复 seq/turn。
//
// 参数：
//   - taskDir: 任务目录（agentd 在 DataDir/tasks/<id> 下创建）
//   - log:     日志入口，可为 nil（测试里常传 nil）
//
// 返回：可用的 FrameWriter；只有 taskDir 不可读时才返回错误。
//
// 注意：文件不存在是正常起点（seq=0, turn=0），不是错误。
func NewFrameWriter(taskDir string, log *slog.Logger) (*FrameWriter, error) {
	if log == nil {
		log = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	w := &FrameWriter{path: filepath.Join(taskDir, FramesFileName), log: log}
	seq, turn, err := resumeFrameState(w.path)
	if err != nil {
		return nil, fmt.Errorf("恢复帧状态 %s: %w", w.path, err)
	}
	w.seq, w.turn = seq, turn

	log.Info("帧写入器就绪", "path", w.path, "resume_seq", seq, "resume_turn", turn)
	return w, nil
}

n_turn_NewSegmenter.signature:
// NewSegmenter 创建段切分器。
//
// 参数：now 是时钟，传 nil 用 time.Now。
//
// 注意：**时钟必须能注入**。判据依赖真实时间的测试在 CI 负载下会偶发翻红，
// 而偶发红会被当噪音忽略，于是这条判据实际上失效了。
func NewSegmenter(now func() time.Time) *Segmenter {
	if now == nil {
		now = time.Now
	}
	return &Segmenter{now: now, open: map[string]*openTool{}}
}

n_turn_NoTrailerFailReason.signature:
// NoTrailerFailReason 构造「回合未输出协议 trailer」的失败原因文案。
//
// 参数：
//   - branch, commit: GitTurnStatus 查到的 git 实况
//   - text: 回合正文全文（本函数负责截尾）
//
// 返回：一条同时包含判定依据、git 实况、正文尾部的文案
//
// 注意：三者缺一，协调者就得回去翻日志——这条要求来自 spec §3.2，不是格式偏好。
func NoTrailerFailReason(branch, commit, text string) string {
	short := commit
	if len(short) > shortCommitLen {
		short = short[:shortCommitLen]
	}
	return fmt.Sprintf("回合结束但未输出协议 trailer；git 实况 %s@%s（相对回合起点有新提交）；回合末尾：%s",
		branch, short, TailRunes(text, noTrailerTailRunes))
}

n_turn_NoTrailerResult.signature:
// NoTrailerResult 构造「无 trailer 但 git 有新提交」时的回合结果。
//
// 参数：
//   - sessionID: executor 会话标识，供续接与归档
//   - branch, commit: GitTurnStatus 查到的 git 实况
//   - text: 回合正文全文
//
// 返回：OK=false 的结果，git 实况保留在结构化字段里
//
// 为什么是 OK=false 而不是 OK=true：模型没有宣布完成，handoff 不替它宣布。
// 翻转不给协调者增加任何一次操作——OK 与 !OK 都落到 waiting_review，
// 而 done 与 continue 在该状态下都合法。变的只是那条事件从「已完成，摘要如下」
// （邀请协调者不看 diff 就 done）变成「有新提交，但模型未按纪律宣布完成」
// （要求看一眼）。代价为零，收益是不再有假完成。
//
// 注意：Branch/CommitHash 必须继续填。翻转若把 git 实况降级成一段自由文本，
// 协调者与任何下游都无法再结构化地取用它。
func NoTrailerResult(sessionID, branch, commit, text string) *executor.Result {
	return &executor.Result{
		OK:		false,
		Branch:		branch,
		CommitHash:	commit,
		SessionID:	sessionID,
		FailReason:	NoTrailerFailReason(branch, commit, text),
		VoidReason:	executor.VoidReasonTurnDiscipline,
	}
}

n_turn_ParseTrailer.signature:
// ParseTrailer 从回合末文本宽容提取协议 JSON（ask/finish）。
//
// 提取分两级：
//   - 主路径：最后一个非空行，从该行第一个 { 起解码一个 JSON 值（容忍前缀
//     与后缀正文）
//   - 回退：主路径无果时，取最后一个「以 { 开头」的行按整行解码（旧规则）
//
// 返回：
//   - kind: "ask"（附 Question）| "finish"（附 Branch/Commit/Summary）| "none"
//   - t: 解析出的协议数据；kind 为 "none" 时为零值
//
// 注意：
//   - 放宽只作用于最后一个非空行：正文中间复述协议 JSON 不会被误当成结论
//   - 找不到或 JSON 损坏时返回 "none"，绝不 panic（模型输出不可信，防御在边界上做）
//   - 纯函数：不打日志，由调用方记录提取结果
func ParseTrailer(text string) (kind string, t Trailer) {

	text = verdictBlockPat.ReplaceAllString(text, "")
	lines := strings.Split(text, "\n")

	for i := len(lines) - 1; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		if line == "" {
			continue
		}
		if k, tr, ok := decodeProtocolJSON(line); ok {
			return k, tr
		}
		break
	}

	// 回退：现有规则原样保留——取最后一个「以 { 开头」的行。模型写完 trailer
	// 又追加了一整行正文时，末行没有 {，靠这条兜住。
	var last string
	for _, line := range lines {
		if strings.HasPrefix(strings.TrimSpace(line), "{") {
			last = line
		}
	}
	if last == "" {
		return "none", t
	}
	if k, tr, ok := decodeProtocolJSON(strings.TrimSpace(last)); ok {
		return k, tr
	}
	return "none", t
}

n_turn_RenderPrompt.signature:
// RenderPrompt 渲染带回合纪律的启动 prompt。
//
// 参数：
//   - taskID: 任务 ID，写入 prompt 标题行
//   - planContent: 实现计划全文（dispatch 侧已把 --prompt 附加指令拼在其后），
//     原样嵌入「实现计划」段，本函数不再二次拼接
//   - disciplineBlock: 按执行者裁出的执行纪律块；空串表示不注入，产物不含纪律块标记
//
// 返回：渲染后的 prompt 全文；模板执行失败时返回错误
func RenderPrompt(taskID, planContent, disciplineBlock string) (string, error) {
	var buf bytes.Buffer
	if err := promptTmpl.Execute(&buf, promptData{
		TaskID:	taskID, ProtocolRules: ProtocolRules,
		Discipline:	strings.TrimSpace(disciplineBlock), PlanContent: planContent,
	}); err != nil {
		return "", fmt.Errorf("渲染 prompt 模板: %w", err)
	}
	return buf.String(), nil
}

n_turn_Segmenter_BeginTurn.signature:
// BeginTurn 开启回合号为 turn 的新回合，并收尾上一个还开着的回合。
//
// 参数：turn 必须取自 FrameWriter.Turn()——**不要自建计数器**，理由见该方法注释。
// 返回：要上报的条目（上一回合的收尾条目 + 本回合的初始 turn 条目）。
func (s *Segmenter) BeginTurn(turn int) []proto.TimingEntry {
	if s == nil {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	out := s.closeTurnLocked()
	now := s.now()
	s.turn, s.turnStart, s.batches = turn, now, 0
	s.apiStart = now
	s.open = map[string]*openTool{}
	s.live = 0
	return append(out, s.turnEntryLocked(now))
}

n_turn_Segmenter_EndTurn.signature:
// EndTurn 收尾当前回合：关掉还开着的模型段，刷最后一条 turn 条目。
//
// 幂等：回合已收尾时返回 nil。调用点（adapter 的回合收尾入口）可能被重复触发。
//
// 注意：还开着的工具**不产条目**——没有结束时刻就没有耗时。它造成的缺口由
// 聚合层的 Partial 标出来，这正是 Partial 存在的理由。
func (s *Segmenter) EndTurn() []proto.TimingEntry {
	if s == nil {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.closeTurnLocked()
}

n_turn_Segmenter_PauseWaiting.signature:
// PauseWaiting pauses an open tool while waiting for an external person.
//
// Parameters: part is the existing tool-call pairing key. Returns a current
// turn marker on success, nil for a nil receiver, an unknown part, a closed
// turn, an empty part, or an already-paused tool. The waiting interval is
// subtracted when ToolEnd closes the tool; no new wire timing kind is emitted.
func (s *Segmenter) PauseWaiting(part string) []proto.TimingEntry {
	if s == nil || part == "" {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.turn == 0 {
		return nil
	}
	ot, ok := s.open[part]
	if !ok || ot.waiting {
		return nil
	}
	now := s.now()
	ot.waiting = true
	ot.waitingSince = now
	return []proto.TimingEntry{s.turnEntryLocked(now)}
}

n_turn_Segmenter_Resume.signature:
// Resume ends an external person's response window for an open tool.
//
// Parameters: part is the existing tool-call pairing key. Returns a current
// turn marker on success, nil for a nil receiver, an unknown part, a closed
// turn, an empty part, or a tool that is not paused. A clock moving backwards
// contributes no negative waiting duration.
func (s *Segmenter) Resume(part string) []proto.TimingEntry {
	if s == nil || part == "" {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.turn == 0 {
		return nil
	}
	ot, ok := s.open[part]
	if !ok || !ot.waiting {
		return nil
	}
	now := s.now()
	finishWaitingLocked(ot, now)
	return []proto.TimingEntry{s.turnEntryLocked(now)}
}

n_turn_Segmenter_ToolEnd.signature:
// ToolEnd 记一次工具调用的结束。
//
// 返回：
//   - dur: 本次调用耗时，直接交给 FrameWriter.ToolResult。**没配上 start 时
//     返回 -1（不知道），不是 0**——0ms 是一次真实可能的极快调用
//   - entries: 要上报的条目；没配上时为 nil（**不产 dur=0 的假条目**）
func (s *Segmenter) ToolEnd(part string) (time.Duration, []proto.TimingEntry) {
	if s == nil {
		return -1, nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	ot, ok := s.open[part]
	if !ok {
		return -1, nil
	}
	delete(s.open, part)
	s.live--
	now := s.now()
	finishWaitingLocked(ot, now)
	dur := now.Sub(ot.start) - ot.waitingMS
	if dur < 0 {
		dur = 0
	}
	out := []proto.TimingEntry{{
		Key:		fmt.Sprintf("tool/%d/%s", s.turn, part),
		Kind:		proto.TimingKindTool,
		Turn:		s.turn,
		DurMS:		dur.Milliseconds(),
		Label:		ot.tool,
		Detail:		ot.detail,
		OffsetMS:	ot.start.Sub(s.turnStart).Milliseconds(),
	}}

	if s.live == 0 {
		s.batches++
		s.apiStart = now
	}
	return dur, append(out, s.turnEntryLocked(now))
}

n_turn_Segmenter_ToolStart.signature:
// ToolStart 记一次工具调用的开始。
//
// 参数：part 是回合内唯一的调用标识（与 tool_call 帧的 Part 同值）；
// tool 是工具名（进 Label）；detail 是命令/入参摘要（进 Detail，本方法负责截断）。
// 返回：要上报的条目。本批工具的第一个 ToolStart 会顺带收掉当前模型段。
//
// 注意：同 part 重复 start 不重复计数——上游流重放时这条是唯一的防线。
func (s *Segmenter) ToolStart(part, tool, detail string) []proto.TimingEntry {
	if s == nil || part == "" {
		return nil
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.turn == 0 {
		return nil
	}
	now := s.now()
	var out []proto.TimingEntry
	if s.live == 0 {
		if e, ok := s.closeAPILocked(now); ok {
			out = append(out, e)
		}
	}
	if _, dup := s.open[part]; !dup {
		markerRunes := len([]rune(executor.TruncationMarker))
		contentRunes := DetailRunes - markerRunes
		headRunes := contentRunes / 2
		tailRunes := contentRunes - headRunes
		s.open[part] = &openTool{
			tool:	tool, detail: HeadTailRunes(detail, headRunes, tailRunes), start: now,
		}
		s.live++
	}
	return append(out, s.turnEntryLocked(now))
}

n_turn_Segmenter_closeAPILocked.signature:
// closeAPILocked 关掉当前模型段。没有开着的模型段时返回 (零值,false)。
// 调用方必须持锁。
func (s *Segmenter) closeAPILocked(now time.Time) (proto.TimingEntry, bool) {
	if s.apiStart.IsZero() {
		return proto.TimingEntry{}, false
	}
	e := proto.TimingEntry{
		Key:	fmt.Sprintf("api/%d/%d", s.turn, s.batches),
		Kind:	proto.TimingKindAPI,
		Turn:	s.turn,
		DurMS:	now.Sub(s.apiStart).Milliseconds(),
	}
	s.apiStart = time.Time{}
	return e, true
}

n_turn_Segmenter_closeTurnLocked.signature:
// closeTurnLocked 收尾当前回合。调用方必须持锁。
func (s *Segmenter) closeTurnLocked() []proto.TimingEntry {
	if s.turn == 0 {
		return nil
	}
	now := s.now()
	for _, ot := range s.open {
		finishWaitingLocked(ot, now)
	}
	var out []proto.TimingEntry
	if e, ok := s.closeAPILocked(now); ok {
		out = append(out, e)
	}
	out = append(out, s.turnEntryLocked(now))
	s.open = nil
	s.live = 0
	s.turn = 0
	return out
}

n_turn_Segmenter_turnEntryLocked.signature:
// turnEntryLocked 造一条当前回合的墙钟条目。调用方必须持锁。
//
// 每次段事件都刷一条（拍板 P3=(a)）：它按同键覆盖，重复上报无害，而代价是
// 「任务跑到一半时也读得到真实总时长」——审核者最想看耗时的时刻，恰恰是
// 「它怎么还没跑完」的那一刻。
func (s *Segmenter) turnEntryLocked(now time.Time) proto.TimingEntry {
	return proto.TimingEntry{
		Key:	fmt.Sprintf("turn/%d", s.turn),
		Kind:	proto.TimingKindTurn,
		Turn:	s.turn,
		DurMS:	now.Sub(s.turnStart).Milliseconds(),
	}
}

n_turn_TailRunes.signature:
// TailRunes 返回末尾 n 个 rune；不足 n 时原样返回。
func TailRunes(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[len(r)-n:])
}

n_turn_TruncateMarked.signature:
// TruncateMarked 按 rune 截断到 n，确实截断时追加 executor.TruncationMarker。
//
// 为什么必须带标记：上层据此 fail-closed——权限文本含标记说明裁决者看到的是
// 不完整命令，危险片段可能落在截断之外，黑名单与廉价模型都不可信。
func TruncateMarked(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n]) + executor.TruncationMarker
}

n_turn_TruncateRunes.signature:
// TruncateRunes 按 rune 截断到 n，不加任何标记。
func TruncateRunes(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n])
}

n_turn_WriterFor.signature:
// WriterFor 返回 taskDir 的**共享** FrameWriter（进程级按解析后路径去重）。
//
// 第一次为某个 taskDir 调用时构造并登记；之后同目录的所有调用（adapter 的
// r.frames 与事件钩子）拿到同一个实例，保证「一个目录一个 seq 分配者」。
//
// 参数：taskDir（任务目录）、log（日志入口，可为 nil）。返回与 NewFrameWriter
// 相同：可用的 writer；只有 taskDir 不可读时才返回错误。
//
// 注意：文件不存在是正常起点（seq=0, turn=0），不是错误。
func WriterFor(taskDir string, log *slog.Logger) (*FrameWriter, error) {
	key := filepath.Clean(taskDir)
	writerRegistryMu.Lock()
	defer writerRegistryMu.Unlock()
	if w, ok := writerRegistry[key]; ok {
		return w, nil
	}
	w, err := NewFrameWriter(taskDir, log)
	if err != nil {
		return nil, err
	}
	writerRegistry[key] = w
	return w, nil
}

n_turn_decodeProtocolJSON.signature:
// decodeProtocolJSON 从 line 中第一个 { 起解码一个 JSON 值，并按协议字段分类。
//
// 参数：line 为已 TrimSpace 的单行文本
//
// 返回：
//   - kind: "ask" | "finish"
//   - t: 解析出的协议数据
//   - ok: 是否解出了带协议字段的 JSON；false 时前两个返回值无意义
//
// 注意：
//   - 用 json.Decoder 而非 Unmarshal：Decode 读满第一个完整 JSON 值即停，
//     因此该值之后的正文（`{"ask":"q"} 好的`）不会让解析失败
//   - 宽容解码：不设 DisallowUnknownFields，模型多带字段时仍能提取已知字段
//   - 解出的 JSON 不含任何协议字段时返回 ok=false，由调用方继续往下判
func decodeProtocolJSON(line string) (kind string, t Trailer, ok bool) {
	i := strings.Index(line, "{")
	if i < 0 {
		return "", t, false
	}
	var payload struct {
		Question	string	`json:"ask"`
		Branch		string	`json:"branch"`
		Commit		string	`json:"commit"`
		Summary		string	`json:"summary"`
	}
	if err := json.NewDecoder(strings.NewReader(line[i:])).Decode(&payload); err != nil {
		return "", t, false
	}
	t = Trailer{Question: payload.Question, Branch: payload.Branch,
		Commit:	payload.Commit, Summary: payload.Summary}

	switch {
	case t.Question != "":
		return "ask", t, true
	case t.Branch != "" || t.Commit != "" || t.Summary != "":
		return "finish", t, true
	default:
		return "", Trailer{}, false
	}
}

n_turn_durMS.signature:
// durMS 把时长折算成帧上的毫秒数；负数（未知）折算成 0，即字段缺席。
func durMS(d time.Duration) int64 {
	if d < 0 {
		return 0
	}
	return d.Milliseconds()
}

n_turn_finishWaitingLocked.signature:
// finishWaitingLocked closes an active waiting window. Callers must hold mu.
// A backwards clock is treated as zero elapsed time so a delayed permission
// response cannot create a negative tool duration.
func finishWaitingLocked(ot *openTool, now time.Time) {
	if ot == nil || !ot.waiting {
		return
	}
	if elapsed := now.Sub(ot.waitingSince); elapsed > 0 {
		ot.waitingMS += elapsed
	}
	ot.waiting = false
	ot.waitingSince = time.Time{}
}

n_turn_resumeFrameState.signature:
// resumeFrameState 从已有的 frames.jsonl 末尾恢复 seq 与 turn。
//
// 返回 (0, 0, nil) 表示文件不存在或没有可解析的完整帧——都是正常起点。
//
// 为什么只回读尾部而不是整文件：帧文件可以很大（数千帧），而恢复只需要最后
// 一条。回读 framesResumeScan 字节，取其中最后一条能解析的完整行即可。
func resumeFrameState(path string) (seq int64, turn int, err error) {
	f, err := os.Open(path)
	if err != nil {
		if os.IsNotExist(err) {
			return 0, 0, nil
		}
		return 0, 0, err
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return 0, 0, err
	}
	start := fi.Size() - framesResumeScan
	if start < 0 {
		start = 0
	}
	if _, err := f.Seek(start, io.SeekStart); err != nil {
		return 0, 0, err
	}

	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64<<10), frameLineLimit*2)
	for sc.Scan() {
		var fr proto.Frame

		if json.Unmarshal(sc.Bytes(), &fr) != nil {
			continue
		}
		if fr.Seq > seq {
			seq, turn = fr.Seq, fr.Turn
		}
	}

	return seq, turn, nil
}

n_turn_sliceToRuneBoundary.signature:
// sliceToRuneBoundary 返回 <= n 的最大下标，且该下标是一个 rune 的起点。
//
// 为什么要向内收缩而不是直接切：切在 UTF-8 码点中间会产出 U+FFFD 替换字符，
// 前端渲染出来是一串乱码方块，而且 JSON 编码后还会把这个损坏悄悄固化下来。
func sliceToRuneBoundary(s string, n int) int {
	if n >= len(s) {
		return len(s)
	}
	for n > 0 && !utf8.RuneStart(s[n]) {
		n--
	}
	return n
}

n_turn_tailToRuneBoundary.signature:
// tailToRuneBoundary 返回 <= n 的最大尾部长度，且切点是一个 rune 的起点。
func tailToRuneBoundary(s string, n int) int {
	if n >= len(s) {
		return len(s)
	}
	for n > 0 && !utf8.RuneStart(s[len(s)-n]) {
		n--
	}
	return n
}

n_turn_truncatedBytes.signature:
// truncatedBytes 只在确实截断时返回原始长度，否则返回 0（让 omitempty 生效）。
//
// 为什么不无脑返回 orig：未截断的帧带一个 bytes 字段等于告诉前端「这里发生过
// 截断」，是误导。
func truncatedBytes(truncated bool, orig int64) int64 {
	if truncated {
		return orig
	}
	return 0
}

n_upgrade_Classify.signature:
// Classify 把探测结果收敛成单一结论。
//
// 参数：
//   - m: 一台机器的探测结果（调用方探测的产物）
//   - latest: 最新发布的 tag
//
// 返回：
//   - 该机器的唯一结论
//
// 优先级（顺序即判据，改动前先读完这段）：
//  1. 够不着 / 本机 agentd 没跑——探测本身没拿到东西，但两者含义不同：远端够不着
//     连版本都不知道；本机 agentd 没跑时二进制版本仍然已知，所以下一条还能生效
//  2. 远端过旧（未上报平台）——排在托管判定之前：连平台都不上报的对端，它的托管
//     状态同样不可信，报「非托管」会把人引去装一个救不了它的 service（B64 原症状）
//  3. 已是最新——排在托管判定之前：没事可做时不该催人装 service，也不该重下重换
//  4. 明确非托管 → 不知道是否托管 → 该升级
func Classify(m Machine, latest string) Verdict {
	if m.Err != nil && !m.Local {
		return VerdictUnreachable
	}
	if !m.Local && m.Platform == "" {
		return VerdictTooOld
	}
	if m.IsLatest(latest) {
		return VerdictLatest
	}

	if m.Err != nil {
		return VerdictAgentdDown
	}
	if m.Managed != nil && !*m.Managed {
		return VerdictUnmanaged
	}
	if m.Managed == nil {
		return VerdictManagedUnknown
	}
	return VerdictNeedsUpgrade
}

n_upgrade_Machine_IsLatest.signature:
// IsLatest 判断一台机器是否已是最新版本。
//
// 本机 agentd 未运行时只比二进制版本；运行时两者都要对齐（二进制已最新但
// agentd 还是旧进程 = 中间态，仍需要重启这一步）。远端只比较 agentd 版本。
func (m Machine) IsLatest(latest string) bool {
	if m.Local {
		if m.Agentd == "" {
			return m.Bin == latest
		}
		return m.Bin == latest && m.Agentd == latest
	}
	return m.Agentd == latest
}

n_upgrade_RemoteOne.signature:
// RemoteOne 把一台**远端**机器升到 rel，返回结构化结论。
//
// 注意：
//   - **只处理远端。** 本机路径（换文件后自己重启、skill 同步）留在 CLI，
//     两者的失败语义完全不同，合并会让本已复杂的分支表再翻一倍
//   - progress 可为 nil；非 nil 时按阶段回调一句人话，供 agentd 落进日志
func RemoteOne(ctx context.Context, log *slog.Logger, m Machine, peer Peer, f Fetcher,
	rel release.Release, o Options, progress func(string)) Result {
	if log == nil {
		log = slog.Default()
	}
	v := Classify(m, rel.Tag)
	log.Info("开始处理远端升级", "name", m.Name, "verdict", v.String(), "platform", m.Platform, "busy", m.Busy)

	switch v {
	case VerdictUnreachable:
		reason := "远端不可达"
		if m.Err != nil {
			reason = m.Err.Error()
		}
		log.Warn("机器够不着", "name", m.Name, "cause", m.Err)
		return Result{Verdict: v, Status: StatusFail, Reason: reason}
	case VerdictLatest:
		log.Info("跳过：已是最新", "name", m.Name)
		return Result{Verdict: v, Status: StatusSkip, Reason: "已是最新"}
	case VerdictTooOld:
		log.Info("跳过：对端未上报平台", "name", m.Name)
		return Result{Verdict: v, Status: StatusSkip,
			Reason:	"对端 agentd 过旧，未上报平台，需先手工升级到 ≥v0.1.1"}
	case VerdictUnmanaged:
		log.Info("跳过：agentd 非托管", "name", m.Name)
		return Result{Verdict: v, Status: StatusSkip,
			Reason:	"agentd 非托管启动，重启后不会被拉起",
			Remedy:	"先在该机器上 handoff service install"}
	case VerdictManagedUnknown:
		log.Info("跳过：对端未上报托管状态", "name", m.Name)
		return Result{Verdict: v, Status: StatusSkip,
			Reason:	"对端未上报托管状态，无法确认换版后能否被拉起"}
	case VerdictAgentdDown:

		return Result{Verdict: v, Status: StatusFail, Reason: "agentd 未运行"}
	}

	if m.Busy > 0 && !o.Force {
		log.Info("跳过：有活跃任务", "name", m.Name, "busy", m.Busy)
		return Result{
			Verdict:	v, Status: StatusSkip, Forcible: true,
			Reason:	fmt.Sprintf("%d 个活跃任务", m.Busy),
			Remedy:	fmt.Sprintf("handoff upgrade --now --target %s --force", m.Name),
		}
	}

	parts := strings.SplitN(m.Platform, "/", 2)
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		log.Warn("对端上报的平台格式非法", "name", m.Name, "platform", m.Platform)
		return Result{Verdict: v, Status: StatusFail,
			Reason:	fmt.Sprintf("对端上报的平台 %q 格式非法", m.Platform)}
	}

	usePull := !o.PreferPush && m.Pull != nil && *m.Pull
	log.Info("选择换版分发模式", "name", m.Name, "platform", m.Platform,
		"pull_capable", m.Pull != nil && *m.Pull, "force_push", o.PreferPush, "use_pull", usePull)
	say := func(message string) {
		if progress != nil {
			progress(message)
		}
	}

	var resp *proto.UpdateResp
	var err error
	if usePull {
		say("正在下发自拉换版请求")
		sum, sumErr := f.FetchChecksum(ctx, rel, parts[0], parts[1])
		if sumErr != nil {
			log.Error("取校验和失败", "name", m.Name, "cause", sumErr)
			return Result{Verdict: v, Status: StatusFail, Reason: sumErr.Error()}
		}
		log.Info("下发自拉换版请求", "name", m.Name, "tag", rel.Tag, "sha256", sum)
		resp, err = peer.PullUpdate(ctx, rel.Tag, sum, o.Force)
	} else {
		say("正在下载远端平台资产")
		log.Info("下载远端平台资产", "name", m.Name, "platform", m.Platform, "tag", rel.Tag)
		tgz, sum, fetchErr := f.FetchArchive(ctx, rel, parts[0], parts[1])
		if fetchErr != nil {
			log.Error("下载远端资产失败", "name", m.Name, "cause", fetchErr)
			return Result{Verdict: v, Status: StatusFail, Reason: fetchErr.Error()}
		}
		say("正在推送换版请求")
		log.Info("下载完成，推送换版请求", "name", m.Name, "tag", rel.Tag, "bytes", len(tgz))
		resp, err = peer.PushUpdate(ctx, rel.Tag, sum, tgz, o.Force)
	}

	if err != nil {
		var rej *client.UpdateRejected
		if errors.As(err, &rej) {
			log.Warn("换版被拒", "name", m.Name, "reason", rej.Reason, "detail", rej.Msg)
			result := Result{Verdict: v, Status: StatusSkip, Reason: rej.Msg}

			switch rej.Reason {
			case proto.UpdateReasonBusy:
				result.Forcible = true
				result.Remedy = fmt.Sprintf("handoff upgrade --now --target %s --force", m.Name)
			case proto.UpdateReasonUnmanaged:
				result.Remedy = "先在该机器上 handoff service install"
			case proto.UpdateReasonPullInProgress:

				result.Remedy = fmt.Sprintf("等它跑完，或 handoff status --target %s 看 pull_state", m.Name)
			}
			return result
		}
		log.Error("发起换版失败", "name", m.Name, "use_pull", usePull, "cause", err)
		return Result{Verdict: v, Status: StatusFail, Reason: err.Error()}
	}
	if resp == nil {
		err = errors.New("换版请求未返回响应")
		log.Error("发起换版失败", "name", m.Name, "cause", err)
		return Result{Verdict: v, Status: StatusFail, Reason: err.Error()}
	}

	waitTimeout := o.WaitPull
	if !usePull {
		waitTimeout = o.WaitPush
	}
	if waitTimeout <= 0 {
		if usePull {
			waitTimeout = defaultWaitPull
		} else {
			waitTimeout = defaultWaitPush
		}
	}
	waitInterval := o.WaitInterval
	if waitInterval <= 0 {
		waitInterval = defaultWaitInterval
	}
	say("正在等待新版本上线")
	log.Info("换版已受理，等待新版本上线", "name", m.Name,
		"version", resp.Version, "prev", resp.Prev, "accepted", resp.Accepted)
	if err := peer.WaitVersion(ctx, rel.Tag, waitTimeout, waitInterval, usePull); err != nil {

		log.Error("等待新版本上线失败", "name", m.Name, "use_pull", usePull, "cause", err)
		result := Result{Verdict: v, Status: StatusFail}
		if usePull {
			result.Reason = err.Error()
			result.Remedy = fmt.Sprintf("handoff status --target %s 看 pull_state 拿完整原因", m.Name)
		} else {
			result.Reason = fmt.Sprintf("已换版但新进程未在 %s 内上线", waitTimeout)
			result.Remedy = fmt.Sprintf("prev: %s  回滚：handoff upgrade --rollback", resp.Prev)
		}
		return result
	}
	log.Info("新版本已上线", "name", m.Name, "version", rel.Tag)
	return Result{Verdict: v, Status: StatusOK, From: m.Agentd, To: rel.Tag}
}

n_upgrade_Status_String.signature:
// String 让 Status 在日志与线格式里是可读的词，而不是 0/1/2。
// 真机实测过这个代价：一条 WARN 打出 status=2，读日志的人得回来翻常量顺序。
func (s Status) String() string {
	switch s {
	case StatusOK:
		return "ok"
	case StatusSkip:
		return "skip"
	case StatusFail:
		return "fail"
	default:
		return "unknown"
	}
}

n_webui_Embedded.signature:
// Embedded 报告当前二进制是否嵌入了真实的前端构建产物。
//
// 默认构建下恒为 false。调用方（如 agentd 启动日志）应据此告诉运维
// 「这份二进制有没有前端」——否则前端打不开时无从判断是构建问题还是运行问题。
func Embedded() bool	{ return false }

n_webui_FS.signature:
// FS 返回控制台静态资源的根文件系统。永不返回 nil。
//
// 默认构建下返回只含一页说明的 stub，见 stubIndex。
func FS() fs.FS	{ return stubFS }

n_wire_ReadFrame.signature:
// ReadFrame 读一个帧。
//
// 返回：kind 为 KindData 时 data 是载荷、ctrl 为 nil；kind 为 KindControl 时 ctrl
// 是解出的控制帧、data 为 nil。io.EOF 表示干净关闭，io.ErrUnexpectedEOF 表示半截帧。
// 未知帧类型会被完整读取后忽略，以便未来新增帧类型时旧端保持连接。
//
// 注意：调用方必须区分 io.EOF 与 io.ErrUnexpectedEOF：前者是订阅者走了，后者是对端
// 死了，在 agentd 侧一个该静默一个该记 Warn。
func ReadFrame(r io.Reader) (byte, []byte, *Control, error) {
	var head [5]byte
	if _, err := io.ReadFull(r, head[:]); err != nil {

		return 0, nil, nil, err
	}
	kind := head[0]
	n := binary.BigEndian.Uint32(head[1:])
	if n > MaxFrame {
		return 0, nil, nil, fmt.Errorf("帧长度 %d 超过上限 %d", n, MaxFrame)
	}
	body := make([]byte, n)
	if _, err := io.ReadFull(r, body); err != nil {
		if err == io.EOF {
			return 0, nil, nil, io.ErrUnexpectedEOF
		}
		return 0, nil, nil, err
	}
	switch kind {
	case KindData:
		return kind, body, nil, nil
	case KindControl:
		var c Control
		if err := json.Unmarshal(body, &c); err != nil {
			return 0, nil, nil, fmt.Errorf("解码控制帧: %w", err)
		}
		return kind, nil, &c, nil
	default:
		return kind, nil, nil, nil
	}
}

n_wire_WriteControl.signature:
// WriteControl 写一个控制帧。
//
// 参数：w 是目标；c 是控制内容，Type 可以是本包的 Ctrl* 常量，也可由未来版本扩展。
// 返回：JSON 编码失败或写失败时报错。
func WriteControl(w io.Writer, c Control) error {
	body, err := json.Marshal(c)
	if err != nil {
		return fmt.Errorf("编码控制帧 %s: %w", c.Type, err)
	}
	return writeFrame(w, KindControl, body)
}

n_wire_WriteData.signature:
// WriteData 写一个数据帧。
//
// 参数：w 是目标；p 是 PTY 原始字节。本函数在返回前用完 p，调用方之后可以复用它。
// 返回：写失败或长度超上限时报错。
func WriteData(w io.Writer, p []byte) error	{ return writeFrame(w, KindData, p) }

n_wire_writeFrame.signature:
// writeFrame 是两个写入口的共同实现。
func writeFrame(w io.Writer, kind byte, body []byte) error {
	if len(body) > MaxFrame {
		return fmt.Errorf("帧长度 %d 超过上限 %d", len(body), MaxFrame)
	}
	var head [5]byte
	head[0] = kind
	binary.BigEndian.PutUint32(head[1:], uint32(len(body)))

	buf := make([]byte, 0, len(head)+len(body))
	buf = append(buf, head[:]...)
	buf = append(buf, body...)
	if _, err := w.Write(buf); err != nil {
		return fmt.Errorf("写帧（类型 %d，%d 字节）: %w", kind, len(body), err)
	}
	return nil
}

n_workspace_BranchTip.signature:
// BranchTip 取分支当前尖端 sha。
//
// 参数：repo 为主仓库路径，branch 为分支名
//
// 返回：
//   - 成功时返回 40 位 sha 与 nil
//   - 取不到时返回空串与非 nil 错误（分支不存在、悬空引用、git 调用失败）
//
// 注意：失败不再塌缩成空串，也不在此处打日志——两件事都交给调用方。补偿侧的
// 决策必须能区分「尖端取不到」与「分支不是本次新建的」，旧签名让这两件事共用
// 空串，正是那道闸无法被单独测试的根因（见
// docs/superpowers/specs/2026-08-10-compensation-branch-decision-design.md §2）。
func BranchTip(ctx context.Context, repo, branch string) (string, error) {
	out, stderr, err := gitRun(ctx, repo, "rev-parse", "refs/heads/"+branch)
	if err != nil {
		return "", fmt.Errorf("git rev-parse refs/heads/%s: %s: %w", branch, strings.TrimSpace(stderr), err)
	}
	return strings.TrimSpace(out), nil
}

n_workspace_Branches.signature:
// Branches 列出仓库的本地分支名（refname:short，字母序）。
//
// 供审阅栏「改动」的基准分支下拉用：协调者从列表里选，不手填。
// 只列本地分支——diff 的 base 语义是本地 rev，远端跟踪分支由默认推导覆盖。
//
// 返回：分支名切片（可能为空，如空仓库）；git 失败返回错误（stderr 在 err 里）。
func Branches(repo string) ([]string, error) {
	out, _, err := gitRun(context.Background(), repo, "for-each-ref", "--format=%(refname:short)", "refs/heads")
	if err != nil {
		log().Error("列分支失败", "repo", repo, "cause", err)
		return nil, fmt.Errorf("git for-each-ref: %w", err)
	}
	var branches []string
	for _, line := range strings.Split(out, "\n") {
		if b := strings.TrimSpace(line); b != "" {
			branches = append(branches, b)
		}
	}
	log().Debug("列分支完成", "repo", repo, "count", len(branches))
	return branches, nil
}

n_workspace_BuildLocalTree.signature:
// BuildLocalTree 构建本机项目树。
//
// 返回：
//   - 项目树（Projects/Unowned 永不为 nil）
//   - 错误：只有「位置表都读不出来」才算错误；单个 location 探测失败是数据
//
// 注意：
//   - 同一 project_id 的多行会被合并到一个 ProjectNode 下。本机理论上不可能
//     出现（project_id 是主键），但代码按可能处理——真出现了就是库被手改过，
//     此时合并展示比崩掉强
func BuildLocalTree(ctx context.Context, locations ProjectLocationLister, managedRoot string, logger *slog.Logger) (proto.ProjectTreeResp, error) {
	start := time.Now()
	locs, err := locations.ListProjectLocations()
	if err != nil {
		logger.Error("项目树：查询位置表失败", "cause", err)
		return proto.ProjectTreeResp{}, err
	}

	resp := proto.ProjectTreeResp{Projects: []proto.ProjectNode{}, Unowned: []string{}}
	byID := map[string]int{}
	broken := 0
	for _, l := range locs {
		if l.ProjectID == "" {

			resp.Unowned = append(resp.Unowned, l.Name)
			continue
		}
		ws, probeErr := ProbeWorkspaces(ctx, l.Path, managedRoot)
		if probeErr != "" {
			broken++
		}
		node := proto.ProjectLocationNode{
			Machine:	"",
			Name:		l.Name,
			Path:		l.Path,
			Workspaces:	ws,
			ProbeError:	probeErr,
		}
		if i, ok := byID[l.ProjectID]; ok {
			resp.Projects[i].Locations = append(resp.Projects[i].Locations, node)
			continue
		}
		byID[l.ProjectID] = len(resp.Projects)
		resp.Projects = append(resp.Projects, proto.ProjectNode{
			ProjectID:	l.ProjectID,
			OriginURL:	l.OriginURL,
			Name:		l.Name,
			Locations:	[]proto.ProjectLocationNode{node},
		})
	}
	logger.Info("项目树构建完成", "projects", len(resp.Projects),
		"locations", len(locs), "broken", broken, "unowned", len(resp.Unowned),
		"elapsed_ms", time.Since(start).Milliseconds())
	return resp, nil
}

n_workspace_BundleRange.signature:
// BundleRange 在 repo 里生成 <have>..<branch> 的 git bundle，返回临时文件路径。
//
// 参数：
//   - ctx:    调用方上下文，透传给 git 子进程
//   - repo:   任务的**主仓库**路径（task.RepoPath，不是 Workdir()）——worktree 是
//     主仓的从属工作树，分支对象在主仓库里
//   - have:   协调者已有的基线提交；空串表示生成全量包
//   - branch: 任务分支名
//
// 返回：
//   - path: 生成的临时文件路径。**调用方负责 os.Remove**，本函数不回收
//   - err:  ErrHaveMissing（have 不存在）/ ErrBadBaseBranch（参数以 - 开头或
//     分支名为空）/ 其余为真故障。**不会因为「没有新提交」而失败**——见下
//
// 注意：
//   - 临时文件落 OS 临时目录，绝不落进 repo——那会让 dispatch 的干净工作区校验误报
//   - 不设体积上限：一个会拒绝合法全量包的上限，是把能用的路径改成坏的
//   - **区间为空时会自动放宽**（§5.2）：git 拒绝造空包，而调用方需要的不只是
//     对象、还有包里那个 ref——客户端的本地分支引用是 fetch 的副产品。放宽到
//     <branch>~1..<branch> 让包一定含 ref，客户端因此一行都不用改
func BundleRange(ctx context.Context, repo, have, branch string) (string, error) {

	if branch == "" || strings.HasPrefix(branch, "-") {
		log().Warn("bundle 分支名非法被拒绝", "repo", repo, "branch", branch)
		return "", fmt.Errorf("%w: %q", ErrBadBaseBranch, branch)
	}
	if strings.HasPrefix(have, "-") {
		log().Warn("bundle have 参数非法被拒绝", "repo", repo, "have", have)
		return "", fmt.Errorf("%w: %q", ErrBadBaseBranch, have)
	}
	log().Info("开始生成 bundle", "repo", repo, "branch", branch, "have", have)

	revRange := branch
	if have != "" {

		if _, _, err := gitProbe(ctx, repo, "cat-file", "-e", have+"^{commit}"); err != nil {
			log().Warn("bundle 的 have 提交在任务仓库中不存在", "repo", repo, "have", have)
			return "", fmt.Errorf("%w: %s", ErrHaveMissing, have)
		}
		revRange = have + ".." + branch
	}

	out, _, err := gitRun(ctx, repo, "rev-list", "--count", revRange)
	if err != nil {
		log().Error("bundle 统计提交数失败", "repo", repo, "range", revRange, "cause", err)
		return "", fmt.Errorf("git rev-list --count %s: %w", revRange, err)
	}
	if strings.TrimSpace(out) == "0" {
		revRange, err = widenEmptyRange(ctx, repo, branch)
		if err != nil {
			return "", err
		}
	}

	f, err := os.CreateTemp("", "handoff-bundle-*.bundle")
	if err != nil {
		log().Error("创建 bundle 临时文件失败", "repo", repo, "cause", err)
		return "", fmt.Errorf("创建 bundle 临时文件: %w", err)
	}
	path := f.Name()

	_ = f.Close()

	if _, stderr, err := gitRun(ctx, repo, "bundle", "create", path, revRange); err != nil {
		_ = os.Remove(path)
		log().Error("生成 bundle 失败", "repo", repo, "range", revRange,
			"stderr", truncateRunes(stderr, 500), "cause", err)
		return "", fmt.Errorf("git bundle create %s: %w", revRange, err)
	}
	fi, err := os.Stat(path)
	if err != nil {
		_ = os.Remove(path)
		log().Error("bundle 生成后无法读取", "repo", repo, "path", path, "cause", err)
		return "", fmt.Errorf("读取生成的 bundle: %w", err)
	}
	log().Info("bundle 生成完成", "repo", repo, "range", revRange, "bytes", fi.Size())
	return path, nil
}

n_workspace_ClassifyWorktree.signature:
// ClassifyWorktree 判定一个工作区当前所处的态。
//
// 参数：ctx 上层上下文，内部叠加 WorkspaceGitTimeout；entries 为 ListWorktrees 的产出；
// workdir 任务记录里的工作区路径。
// 返回：状态；脏清单（仅 dirty 时非空）；note（unknown / prunable 时的真因）。
//
// 注意：脏的判据含**未跟踪文件**，与 git worktree remove 自身的拒绝条件对齐。
func ClassifyWorktree(ctx context.Context, entries map[string]WorktreeEntry, workdir string) (proto.WorktreeState, []proto.DirtyFile, string) {
	e, ok := FindWorktree(entries, workdir)
	if !ok {
		log().Info("工作树判定：不在册，无残留", "workdir", workdir)
		return proto.WorktreeAbsent, nil, ""
	}
	if e.Prunable {
		log().Info("工作树判定：元数据残留", "workdir", workdir, "reason", e.PruneReason)
		return proto.WorktreePrunable, nil, e.PruneReason
	}
	sctx, cancel := context.WithTimeout(ctx, WorkspaceGitTimeout)
	defer cancel()
	out, stderr, err := gitRun(sctx, workdir, "status", "--porcelain")
	if err != nil {
		note := strings.TrimSpace(truncateRunes(stderr, 200))
		log().Warn("工作树判定：读不到 status，判不出",
			"workdir", workdir, "stderr", note, "cause", err)
		return proto.WorktreeUnknown, nil, note
	}
	files := parsePorcelainStatus(out)
	if len(files) == 0 {
		log().Info("工作树判定：干净，可回收", "workdir", workdir)
		return proto.WorktreeClean, nil, ""
	}
	log().Info("工作树判定：脏，默认拒绝回收", "workdir", workdir, "dirty", len(files))
	return proto.WorktreeDirty, files, ""
}

n_workspace_CloneRepo.signature:
// CloneRepo 在 parentDir 下克隆 originURL 到 dest。
//
// 参数：withProxy=true 走出网代理路径（gitRunNet），false 走本地直连（gitRun）。
// 返回：stderr 原文与错误；调用方据 stderr 组装用户可见文案。
//
// 注意：`--` 分隔符防止 URL/路径被 git 当成选项。
func CloneRepo(ctx context.Context, parentDir, originURL, dest string, withProxy bool) (string, error) {
	args := []string{"clone", "--", originURL, dest}
	var stderr string
	var err error
	if withProxy {
		_, stderr, err = gitRunNet(ctx, parentDir, args...)
	} else {
		_, stderr, err = gitRun(ctx, parentDir, args...)
	}
	return stderr, err
}

n_workspace_CopyEntry.signature:
// CopyEntry 复制工作树内一个条目（B107 文件树右键菜单），目录连同其内容一并
// 递归复制。副本名按「foo copy.go、foo copy 2.go …… 到 foo copy 99.go」的规则
// 取第一个未被占用的；目录整体当 base 不拆扩展名（`a.b` → `a.b copy`）。
// 命名细节与 99 上限的理由见 copyEntryName doc。
//
// 路径遏制与 CreateEntry/RenameEntry/DeleteEntry 同一红线：全部写操作经
// os.OpenRoot 的内核级 jail（理由见 1543 行注释），符号链接等特殊文件不复制、
// 只跳过并 Warn，绝不在递归途中落回绝对路径。
//
// 参数：
//   - repo: 工作树绝对路径（调用方必须已过白名单闸门，本函数不做白名单判定）
//   - rel: 待复制条目的相对路径（空串与 "." 都表示工作树根，按 ErrBadEntryName
//     拒绝——复制整棵工作树没有意义，落点必然撞已存在的副本名）
//
// 返回：
//   - proto.DirEntry: 复制后条目的信息（Name/IsDir/Size 取自磁盘实况）
//   - ErrBadEntryName: rel 是工作树根（空串 / "."）
//   - ErrPathEscape: rel 逃逸出工作树（含符号链接逃逸）
//   - ErrGitDirWrite: 目标是 .git 下的条目
//   - ErrEntryNotFound: rel 不存在
//   - ErrEntryExists: 副本名到 copy 99 已全部被占用
func CopyEntry(repo, rel string) (proto.DirEntry, error) {
	log().Info("复制工作树条目", "repo", repo, "path", rel)
	root, err := os.OpenRoot(repo)
	if err != nil {
		log().Warn("条目复制打开工作树失败", "repo", repo, "path", rel, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("打开工作树 %s: %w", repo, err)
	}
	defer root.Close()
	cleaned, err := cleanEntryRel(repo, rel)
	if err != nil {
		return proto.DirEntry{}, err
	}
	if cleaned == "" {
		log().Warn("条目复制目标是工作树根被拒绝", "repo", repo, "path", rel)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrBadEntryName, rel)
	}
	if isGitPath(cleaned) {
		log().Warn("条目复制命中 .git 被拒绝", "repo", repo, "path", cleaned)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrGitDirWrite, cleaned)
	}
	fi, err := root.Stat(cleaned)
	if err != nil {
		if rootErrIsEscape(err) {
			log().Warn("条目复制路径逃逸被拒绝", "repo", repo, "path", cleaned, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, cleaned)
		}
		if os.IsNotExist(err) {
			log().Warn("条目复制目标不存在", "repo", repo, "path", cleaned, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrEntryNotFound, cleaned)
		}
		log().Warn("条目复制检查目标失败", "repo", repo, "path", cleaned, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("检查条目 %s: %w", filepath.Join(repo, cleaned), err)
	}
	target, tried, err := copyEntryName(root, repo, cleaned, fi.IsDir())
	if err != nil {
		return proto.DirEntry{}, err
	}
	log().Info("条目复制选定副本名", "repo", repo, "path", cleaned, "target", target, "tried", tried)
	var entries, copied int64
	if fi.IsDir() {
		entries, copied, err = copyEntryDir(root, repo, cleaned, target)
	} else {
		entries = 1
		copied, err = copyEntryFile(root, repo, cleaned, target)
	}
	if err != nil {
		if rootErrIsEscape(err) {
			log().Warn("条目复制路径逃逸被拒绝", "repo", repo, "path", cleaned, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, cleaned)
		}
		log().Warn("条目复制执行失败", "repo", repo, "path", cleaned, "target", target, "cause", err)
		return proto.DirEntry{}, err
	}
	e, err := statEntry(root, repo, target)
	if err != nil {
		log().Warn("条目复制读取结果失败", "repo", repo, "path", target, "cause", err)
		return proto.DirEntry{}, err
	}
	log().Info("条目复制完成", "repo", repo, "path", cleaned, "target", target,
		"entries", entries, "bytes", copied)
	return e, nil
}

n_workspace_CreateEntry.signature:
// CreateEntry 在工作树内新建一个空文件或空目录（B107 文件树右键菜单）。
//
// 参数：
//   - repo: 工作树绝对路径（调用方必须已过白名单闸门，本函数不做白名单判定）
//   - parentRel: 目标所在父目录的相对路径；空串与 "." 都表示工作树根
//   - name: 新条目名（单层名，不得含 / 或 \）
//   - kind: "file" 或 "dir"
//
// 返回：
//   - proto.DirEntry: 新建条目的信息（Name/IsDir/Size 取自磁盘实况，非入参拼装）
//   - ErrBadEntryName: name 非法（空 / . / .. / 含分隔符），或 parentRel 不是目录
//   - ErrPathEscape: parentRel 逃逸出工作树（含符号链接逃逸）
//   - ErrGitDirWrite: 目标落在工作树根的 .git 下
//   - ErrEntryNotFound: parentRel 不存在
//   - ErrEntryExists: 目标已存在
func CreateEntry(repo, parentRel, name, kind string) (proto.DirEntry, error) {
	log().Info("新建工作树条目", "repo", repo, "parent", parentRel, "name", name, "kind", kind)
	root, err := os.OpenRoot(repo)
	if err != nil {
		log().Warn("新建条目打开工作树失败", "repo", repo, "path", parentRel, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("打开工作树 %s: %w", repo, err)
	}
	defer root.Close()
	parent, err := cleanEntryRel(repo, parentRel)
	if err != nil {
		return proto.DirEntry{}, err
	}
	if err := validateEntryName(repo, name); err != nil {
		return proto.DirEntry{}, err
	}
	if kind != "file" && kind != "dir" {
		log().Warn("新建条目未知类型被拒绝", "repo", repo, "kind", kind)
		return proto.DirEntry{}, fmt.Errorf("%w: 未知的条目类型 %q", ErrBadEntryName, kind)
	}
	target := filepath.Join(parent, name)
	if isGitPath(target) {
		log().Warn("新建条目命中 .git 被拒绝", "repo", repo, "path", target)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrGitDirWrite, target)
	}
	if parent != "" {
		pfi, err := root.Stat(parent)
		if err != nil {
			if rootErrIsEscape(err) {
				log().Warn("新建条目父目录逃逸被拒绝", "repo", repo, "path", parent, "cause", err)
				return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, parent)
			}
			if os.IsNotExist(err) {
				log().Warn("新建条目父目录不存在", "repo", repo, "path", parent, "cause", err)
				return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrEntryNotFound, parent)
			}
			log().Warn("新建条目父目录检查失败", "repo", repo, "path", parent, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("检查父目录 %s: %w", filepath.Join(repo, parent), err)
		}
		if !pfi.IsDir() {
			log().Warn("新建条目父目录不是目录", "repo", repo, "path", parent, "mode", pfi.Mode().String())
			return proto.DirEntry{}, fmt.Errorf("%w: 父目录 %q 不是目录", ErrBadEntryName, parent)
		}
	}
	if _, err := root.Stat(target); err == nil {
		log().Warn("新建条目目标已存在", "repo", repo, "path", target)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrEntryExists, target)
	} else if rootErrIsEscape(err) {
		log().Warn("新建条目路径逃逸被拒绝", "repo", repo, "path", target, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, target)
	}
	if kind == "dir" {
		if err := root.Mkdir(target, 0o755); err != nil {
			if rootErrIsEscape(err) {
				log().Warn("新建条目路径逃逸被拒绝", "repo", repo, "path", target, "cause", err)
				return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, target)
			}
			log().Warn("新建条目建目录失败", "repo", repo, "path", target, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("建目录 %s: %w", filepath.Join(repo, target), err)
		}
	} else {
		f, err := root.Create(target)
		if err != nil {
			if rootErrIsEscape(err) {
				log().Warn("新建条目路径逃逸被拒绝", "repo", repo, "path", target, "cause", err)
				return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, target)
			}
			log().Warn("新建条目建文件失败", "repo", repo, "path", target, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("建文件 %s: %w", filepath.Join(repo, target), err)
		}

		if err := f.Close(); err != nil {
			log().Warn("新建条目关闭文件失败", "repo", repo, "path", target, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("关闭文件 %s: %w", filepath.Join(repo, target), err)
		}
	}
	e, err := statEntry(root, repo, target)
	if err != nil {
		log().Warn("新建条目读取结果失败", "repo", repo, "path", target, "cause", err)
		return proto.DirEntry{}, err
	}
	log().Info("新建条目完成", "repo", repo, "path", target, "kind", kind)
	return e, nil
}

n_workspace_CreateManualWorktree.signature:
// CreateManualWorktree 在 worktreesDir/manual 下开一棵不属于任何任务的工作树。
//
// 参数：
//   - repo: 项目主仓路径（登记表里的 path）
//   - worktreesDir: <DataDir>/worktrees
//   - req: 建树请求，见 proto.CreateWorktreeReq
//
// 返回：
//   - 新工作树的 proto.Workspace，口径与项目树上那一条完全一致（含 head/created_at）
//   - 错误：请求类问题一律包 ErrBadWorktreeReq（调用方回 400）；git 执行失败原样返回
//
// 注意：
//   - 整个过程限时 WorkspaceGitTimeout（2 分钟）——pre-checkout hook 与凭证交互
//     提示都能把 git 挂死，不设上限会拖死一个 HTTP 连接
//   - 成功后会多跑一次 git worktree list 做回读，为的是让返回值与树上同源；
//     回读挑不到时退回手工组装并 Warn，**不因为回读失败就把成功报成失败**
func CreateManualWorktree(ctx context.Context, repo, worktreesDir string, req proto.CreateWorktreeReq) (proto.Workspace, error) {
	ctx, cancel := context.WithTimeout(ctx, WorkspaceGitTimeout)
	defer cancel()
	start := time.Now()
	log().Info("手工建树进入", "repo", repo, "mode", req.Mode, "branch", req.Branch,
		"base", req.Base, "worktrees_dir", worktreesDir, "timeout", WorkspaceGitTimeout)

	if req.Mode != "new_branch" && req.Mode != "existing_branch" {
		return proto.Workspace{}, rejectWorktree("mode 必须是 new_branch 或 existing_branch，收到 "+req.Mode, req)
	}
	if strings.TrimSpace(req.Branch) == "" {
		return proto.Workspace{}, rejectWorktree("branch 必填", req)
	}
	for _, v := range []struct{ what, val string }{{"branch", req.Branch}, {"base", req.Base}} {
		if strings.HasPrefix(v.val, "-") {
			return proto.Workspace{}, rejectWorktree(v.what+" 不允许以 - 开头（git 参数注入面）: "+v.val, req)
		}
	}

	if _, stderr, err := gitRun(ctx, repo, "check-ref-format", "--branch", req.Branch); err != nil {
		return proto.Workspace{}, rejectWorktree("分支名 "+req.Branch+" 不是合法的 git 分支名: "+strings.TrimSpace(stderr), req)
	}

	exists := ManualBranchExists(ctx, repo, req.Branch)
	base := req.Base
	switch req.Mode {
	case "new_branch":
		if exists {
			return proto.Workspace{}, rejectWorktree("分支 "+req.Branch+" 已存在，请换个名字或改用「检出已有分支」", req)
		}
		if base == "" {
			base = ResolveBaseBranch(repo)
			log().Info("建树基线由推导得出", "repo", repo, "base", base)
		}
		if base == "" {
			return proto.Workspace{}, rejectWorktree("推导不出基准分支，请显式指定基线", req)
		}
		if _, _, err := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", base); err != nil {
			return proto.Workspace{}, rejectWorktree("基线 "+base+" 在仓库里不存在", req)
		}
	case "existing_branch":
		if !exists {
			return proto.Workspace{}, rejectWorktree("分支 "+req.Branch+" 不存在", req)
		}
	}

	managedRoot := worktreesDir

	if req.Mode == "existing_branch" {
		existing, probeErr := ProbeWorkspaces(ctx, repo, managedRoot)
		if probeErr != "" {
			log().Warn("建树前探测已有工作树失败，占用检查降级为由 git 兜底", "repo", repo, "cause", probeErr)
		}
		for _, ws := range existing {
			if ws.Branch == req.Branch {
				return proto.Workspace{}, rejectWorktree("分支 "+req.Branch+" 已被工作树 "+ws.Path+" 检出，一个分支只能有一棵树", req)
			}
		}
	}

	root := ManualWorktreeRoot(worktreesDir)
	dir := filepath.Join(root, manualDirName(req.Branch))
	if _, err := os.Stat(dir); err == nil {
		return proto.Workspace{}, rejectWorktree("落点 "+dir+" 已存在，请换个分支名或先清理该目录", req)
	}
	if err := os.MkdirAll(root, 0o700); err != nil {
		log().Error("建树失败：创建落点根目录", "root", root, "cause", err)
		return proto.Workspace{}, fmt.Errorf("创建目录 %s: %w", root, err)
	}

	args := []string{"worktree", "add", dir, req.Branch}
	if req.Mode == "new_branch" {
		args = []string{"worktree", "add", "-b", req.Branch, dir, base}
	}
	if _, stderr, err := gitRun(ctx, repo, args...); err != nil {
		log().Error("建树失败：git worktree add", "repo", repo, "dir", dir,
			"branch", req.Branch, "stderr", truncateRunes(stderr, 500), "cause", err)

		if rmErr := os.Remove(dir); rmErr != nil && !os.IsNotExist(rmErr) {
			log().Warn("建树失败后清理落点未完成，保留现场待查", "dir", dir, "cause", rmErr)
		}
		return proto.Workspace{}, fmt.Errorf("git worktree add %s: %s: %w", dir, strings.TrimSpace(stderr), err)
	}

	ws := readBackWorktree(ctx, repo, managedRoot, dir, req.Branch)
	log().Info("手工建树完成", "repo", repo, "dir", ws.Path, "branch", ws.Branch,
		"managed", ws.Managed, "elapsed_ms", time.Since(start).Milliseconds())
	return ws, nil
}

n_workspace_DeleteBranch.signature:
// DeleteBranch 删除本地分支 refs/heads/<branch>（git branch -D）。
//
// 参数：ctx 控制本次 git 调用；repo 主仓库路径；branch 分支名。
// 返回：git stderr 原文（成功为空串）与错误；调用方需要逐字段还原迁移前的
// 日志/文案时按 CloneRepo 同款约定自取 stderr。
//
// 注意：只删分支，不删工作树；force 语义（-D）沿用原补偿路径：补偿只删本次
// 自建且自创建以来零提交的分支，调用方已先复核，故此处固定 -D。
func DeleteBranch(ctx context.Context, repo, branch string) (string, error) {
	if _, stderr, err := gitRun(ctx, repo, "branch", "-D", branch); err != nil {
		return stderr, fmt.Errorf("git branch -D %s: %s: %w", branch, strings.TrimSpace(stderr), err)
	}
	return "", nil
}

n_workspace_DeleteEntry.signature:
// DeleteEntry 删除工作树内一个条目（B107 文件树右键菜单），目录连同其内容一并删。
//
// 不做回收站：git 能救已跟踪文件（checkout / restore 一条命令），却救不了未跟踪
// 文件——新建即删除的落盘即永久，这正是「误删会弄丢东西」的全部理由，与凭据
// 强弱无关（控制台会话的权限本来就是主令牌等价，见 isGitPath 的 why）；这道闸
// 该挡的是「一次误操作就把数据/仓库弄坏」。
//
// 参数：
//   - repo: 工作树绝对路径（调用方必须已过白名单闸门，本函数不做白名单判定）
//   - rel: 待删除条目的相对路径
//
// 返回：
//   - ErrBadEntryName: rel 是工作树根（空串 / "."）
//   - ErrPathEscape: rel 逃逸出工作树（含符号链接逃逸）
//   - ErrGitDirWrite: 目标是 .git 下的条目
//   - ErrEntryNotFound: rel 不存在
func DeleteEntry(repo, rel string) error {
	log().Info("删除工作树条目", "repo", repo, "path", rel)
	root, err := os.OpenRoot(repo)
	if err != nil {
		log().Warn("删除条目打开工作树失败", "repo", repo, "path", rel, "cause", err)
		return fmt.Errorf("打开工作树 %s: %w", repo, err)
	}
	defer root.Close()
	cleaned, err := cleanEntryRel(repo, rel)
	if err != nil {
		return err
	}
	if cleaned == "" {
		log().Warn("删除工作树根本身被拒绝", "repo", repo, "path", rel)
		return fmt.Errorf("%w: %q", ErrBadEntryName, rel)
	}
	if isGitPath(cleaned) {
		log().Warn("删除条目命中 .git 被拒绝", "repo", repo, "path", cleaned)
		return fmt.Errorf("%w: %q", ErrGitDirWrite, cleaned)
	}
	fi, err := root.Stat(cleaned)
	if err != nil {
		if rootErrIsEscape(err) {
			log().Warn("删除条目路径逃逸被拒绝", "repo", repo, "path", cleaned, "cause", err)
			return fmt.Errorf("%w: %q", ErrPathEscape, cleaned)
		}
		if os.IsNotExist(err) {
			log().Warn("删除条目不存在", "repo", repo, "path", cleaned, "cause", err)
			return fmt.Errorf("%w: %q", ErrEntryNotFound, cleaned)
		}
		log().Warn("删除条目检查失败", "repo", repo, "path", cleaned, "cause", err)
		return fmt.Errorf("检查条目 %s: %w", filepath.Join(repo, cleaned), err)
	}
	kind := "file"
	if fi.IsDir() {
		kind = "dir"
		err = root.RemoveAll(cleaned)
	} else {
		err = root.Remove(cleaned)
	}
	if err != nil {
		if rootErrIsEscape(err) {
			log().Warn("删除条目路径逃逸被拒绝", "repo", repo, "path", cleaned, "cause", err)
			return fmt.Errorf("%w: %q", ErrPathEscape, cleaned)
		}
		log().Warn("删除条目执行失败", "repo", repo, "path", cleaned, "kind", kind, "cause", err)
		return fmt.Errorf("删除条目 %s: %w", filepath.Join(repo, cleaned), err)
	}
	log().Info("删除条目完成", "repo", repo, "path", cleaned, "kind", kind)
	return nil
}

n_workspace_Diff.signature:
// Diff 取任务分支相对基准分支的完整审阅素材：git diff <base>...HEAD 的差异
// + git log --oneline <base>..HEAD 的提交列表，按序拼接。
//
// 参数：
//   - repo: 任务仓库路径
//   - baseBranch: 基准分支（通常为派发前的分支，如 main/master）
//
// 返回：
//   - 拼接后的文本（diff 为空时只有提交列表，两边都空时为空串）
//   - err: git 失败返回错误（如 baseBranch 不存在，stderr 已并入日志）；
//     baseBranch 以 "-" 开头返回 ErrBadBaseBranch
func Diff(repo, baseBranch string) (string, error) {
	return DiffRange(repo, baseBranch, "HEAD")
}

n_workspace_DiffBaseFor.signature:
// DiffBaseFor 返回任务 diff 的缺省基准 rev：任务自己的 BaseCommit 优先，
// 为空才按仓库推导。
//
// 为什么优先任务基线（B65）：按仓库默认分支推导会把「默认分支与任务分支之间的
// 全部历史」也算进 diff——实测一个真实任务默认吐 26611 行而真实改动只有 3274 行，
// 审核者第一眼拿到的素材被淹掉。任务记录里本来就有它建在哪个提交上（B35 起）。
//
// BaseCommit 为空**不是缺字段**：proto 注释写明「空=切已存在分支（没有起点这回事）
// 或老任务」，所以退回推导链是正常分支，不是兜底。
//
// 返回空串表示两条路都取不到（非 git 仓库、既无 main 也无 master），
// 由调用方报 400 并提示显式指定 base。
func DiffBaseFor(task *proto.Task, repo string) string {
	if task != nil && task.BaseCommit != "" {
		return task.BaseCommit
	}
	return ResolveBaseBranch(repo)
}

n_workspace_DiffRange.signature:
// DiffRange 与 Diff 相同，但右端 rev 由调用方指定。
//
// 为什么需要指定右端：任务归档后 managed worktree 会被回收，此时只能回到主仓库
// 去看。**主仓库的 HEAD 不是任务分支**（多半是 main），拿 HEAD 当右端会把
// 「主线相对基线的全部历史」当成这个任务的改动——实测一个已归档任务因此吐出
// 1002 个文件，而它真实只改了几个。右端必须显式给任务分支。
//
// headRev 与 baseBranch 同一套校验：空串与 "-" 前缀一律拒绝（git 参数注入）。
func DiffRange(repo, baseBranch, headRev string) (string, error) {

	if baseBranch == "" || strings.HasPrefix(baseBranch, "-") {
		log().Warn("diff 基准分支非法（空或 - 前缀，疑似 git 参数注入）", "repo", repo, "base", baseBranch)
		return "", fmt.Errorf("%w: %q", ErrBadBaseBranch, baseBranch)
	}
	if headRev == "" || strings.HasPrefix(headRev, "-") {
		log().Warn("diff 右端 rev 非法（空或 - 前缀，疑似 git 参数注入）", "repo", repo, "head", headRev)
		return "", fmt.Errorf("%w: %q", ErrBadBaseBranch, headRev)
	}
	diffText, _, err := gitRun(context.Background(), repo, "diff", baseBranch+"..."+headRev)
	if err != nil {
		return "", fmt.Errorf("git diff %s...%s: %w", baseBranch, headRev, err)
	}
	logText, _, err := gitRun(context.Background(), repo, "log", "--oneline", baseBranch+".."+headRev)
	if err != nil {
		return "", fmt.Errorf("git log %s..%s: %w", baseBranch, headRev, err)
	}
	var parts []string
	if d := strings.TrimSpace(diffText); d != "" {
		parts = append(parts, d)
	}
	if l := strings.TrimSpace(logText); l != "" {
		parts = append(parts, l)
	}
	return strings.Join(parts, "\n\n"), nil
}

n_workspace_DirtyWorktreeError_Error.signature:
func (e *DirtyWorktreeError) Error() string {
