n_workspace_EnsureRepoUsable.signature:
// EnsureRepoUsable 校验 repo 确实是一个可用的 git 仓库。
//
// 参数：
//   - ctx: 控制本次 git 调用的生命周期
//   - repo: 任务仓库路径
//
// 返回：
//   - nil：是可用的 git 仓库
//   - ErrRepoUnusable：路径不存在 / 不是 git 仓库 / git 不在 PATH / 权限不足，
//     错误文本带 git stderr 原文（server 层据此给 400，见 writeDispatchError）
//
// 注意：
//   - 由 Dispatch 在 ResolveBaseline 之前调用。放在那里而不是建树前，是因为
//     ResolveBaseline 对非 git 仓库会误报成 ErrBaseCommitMissing（「落后于本地，
//     请先 push」），那是个比沉默更糟的答案
//   - 判据用 rev-parse --git-dir 而不是 grep worktree add 的错误串：前者是显式
//     判据，后者依赖 git 的文案不变
//   - ensureCleanWorktree 里原有的 ErrRepoUnusable 包装保留——它仍是 git status
//     因其他原因失败时的兜底
func EnsureRepoUsable(ctx context.Context, repo string) error {
	_, stderr, err := gitProbe(ctx, repo, "rev-parse", "--git-dir")
	if err != nil {
		log().Warn("dispatch 前置：任务仓库不可用，拒绝派发", "repo", repo,
			"stderr", truncateRunes(strings.TrimSpace(stderr), 300), "cause", err)
		return fmt.Errorf("%w: %s: %v", ErrRepoUnusable, strings.TrimSpace(stderr), err)
	}
	log().Info("dispatch 前置：仓库有效性校验通过", "repo", repo)
	return nil
}

n_workspace_FanoutProjectTree.signature:
// FanoutProjectTree 汇总本机与全部 target 的项目树。
//
// 返回值恒有效：单台失败记进 Machines 那一行，不影响其余机器与本机的数据。
// local 取本机那一棵树（gateway 侧闭包到 BuildLocalTree）。
func FanoutProjectTree(ctx context.Context, local func(context.Context) (proto.ProjectTreeResp, error),
	targets ProjectTreeSource, logger *slog.Logger) proto.ProjectTreeResp {
	out, err := local(ctx)
	if err != nil {

		out = proto.ProjectTreeResp{Projects: []proto.ProjectNode{}, Unowned: []string{}}
		out.Machines = []proto.MachineStatus{{Name: "", Ok: false,
			FetchedAt:	time.Now().UTC(), Error: err.Error()}}
	} else {
		out.Machines = []proto.MachineStatus{{Name: "", Ok: true, FetchedAt: time.Now().UTC()}}
	}

	names := targets.Names()

	fanCtx, cancel := context.WithTimeout(ctx, treeFanoutBudget)
	defer cancel()

	type result struct {
		status	proto.MachineStatus
		tree	*proto.ProjectTreeResp
	}
	results := make([]result, len(names))
	var wg sync.WaitGroup
	for i, name := range names {
		wg.Add(1)
		go func(i int, name string) {
			defer wg.Done()
			st := proto.MachineStatus{Name: name, FetchedAt: time.Now().UTC()}

			c, err := targets.For(name)
			if err != nil {
				logger.Warn("项目树扇出：取客户端失败", "machine", name, "cause", err)
				st.Error = err.Error()
				results[i] = result{status: st}
				return
			}
			tree, err := c.ProjectTree(fanCtx)
			if err != nil {
				logger.Warn("项目树扇出失败", "machine", name, "cause", err)
				st.Error = err.Error()
				results[i] = result{status: st}
				return
			}
			st.Ok = true
			results[i] = result{status: st, tree: tree}
		}(i, name)
	}
	wg.Wait()

	for _, r := range results {
		out.Machines = append(out.Machines, r.status)
		if r.tree == nil {
			continue
		}
		mergeTree(&out, r.status.Name, *r.tree)
	}
	logger.Info("项目树汇总完成", "machines", len(out.Machines),
		"projects", len(out.Projects))
	return out
}

n_workspace_FindWorktree.signature:
// FindWorktree 在条目表里按归一后的路径查找工作树。
//
// 参数：entries 为 parseWorktreeList 的产出（键为 git 原始路径）；workdir 任务记录里的路径。
// 返回：命中的条目与是否命中。
func FindWorktree(entries map[string]WorktreeEntry, workdir string) (WorktreeEntry, bool) {
	want := canonPath(workdir)
	for p, e := range entries {
		if canonPath(p) == want {
			return e, true
		}
	}
	return WorktreeEntry{}, false
}

