n_workspace_HasLedgerAttachField.signature:
// HasLedgerAttachField 报告结构体是否声明了挂卡字段（CardIDs 或 CardResults）。
// Ticket 0 用它锁住 PrepareReq / ManualReq / ManualTree 不得携带挂卡参数。
func HasLedgerAttachField(v any) bool {
	t := reflect.TypeOf(v)
	if t.Kind() == reflect.Pointer {
		t = t.Elem()
	}
	if t.Kind() != reflect.Struct {
		return false
	}
	if _, ok := t.FieldByName("CardIDs"); ok {
		return true
	}
	_, ok := t.FieldByName("CardResults")
	return ok
}

n_workspace_HeadBranch.signature:
// HeadBranch 读取目录当前分支名（git symbolic-ref --short -q HEAD）。
//
// 参数：ctx 控制本次 git 调用；dir 工作树路径。
// 返回：分支名；detached 或读取失败时返回空串（fail-open，绝不编造分支名）。
func HeadBranch(ctx context.Context, dir string) string {
	out, _, err := gitProbe(ctx, dir, "symbolic-ref", "--short", "-q", "HEAD")
	if err != nil {
		return ""
	}
	return strings.TrimSpace(out)
}

