n_workspace_ListDir.signature:
// ListDir 列举工作树内某个目录的**直接子项**，不递归。
//
// 与 ReadFile 共用同一套路径防护（安全红线，两道）：
//  1. filepath.Clean 归一化后，绝对路径或残留 .. 前缀一律拒绝（ErrPathEscape）
//  2. 实际打开经 os.OpenRoot（内核级 jail），符号链接逃逸由内核在单次系统调用
//     内拒绝，不留 TOCTOU 窗口
//
// 为什么不递归：一次递归列举一个大仓库要遍历几十万个 inode，而前端一次只画
// 一层。按需展开把成本摊到用户真正点开的那几层上。
//
// 排序：目录在前、各自按名称字典序。为什么由服务端排而不是前端排：前端会有
// 搜索过滤与虚拟滚动，排序稳定性交给一处比在多处各排一次可靠。
//
// 参数：
//   - repo: 工作树绝对路径（调用方必须已过白名单闸门，本函数不做白名单判定）
//   - rel: 相对工作树根的目录路径；"" 与 "." 都表示根
//
// 返回：
//   - 子项列表（**永不为 nil**）
//   - err: 逃逸返回 ErrPathEscape；目标不是目录返回 ErrPathNotDir；
//     目标不存在返回 *fs.PathError（含 %w 链，errors.Is(err, fs.ErrNotExist) 为真）
func ListDir(repo, rel string) ([]proto.DirEntry, error) {
	cleaned := filepath.Clean(rel)
	if rel == "" {
		cleaned = "."
	}
	if filepath.IsAbs(cleaned) || cleaned == ".." ||
		strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) {
		log().Warn("目录列举路径逃逸被拒绝", "repo", repo, "path", rel)
		return nil, fmt.Errorf("%w: %q", ErrPathEscape, rel)
	}
	root, err := os.OpenRoot(repo)
	if err != nil {
		return nil, fmt.Errorf("打开工作树 %s: %w", repo, err)
	}
	defer root.Close()

	f, err := root.OpenFile(cleaned, os.O_RDONLY|openNonBlock, 0)
	if err != nil {
		if rootErrIsEscape(err) {
			log().Warn("目录列举路径逃逸被拒绝", "repo", repo, "path", rel)
			return nil, fmt.Errorf("%w: %q", ErrPathEscape, rel)
		}
		return nil, fmt.Errorf("列举目录 %s: %w", filepath.Join(repo, cleaned), err)
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return nil, fmt.Errorf("列举目录 %s: %w", filepath.Join(repo, cleaned), err)
	}
	if !fi.IsDir() {
		log().Warn("目录列举目标不是目录", "repo", repo, "path", rel, "mode", fi.Mode().String())
		return nil, fmt.Errorf("%w: %q", ErrPathNotDir, rel)
	}
	des, err := f.ReadDir(-1)
	if err != nil {
		return nil, fmt.Errorf("列举目录 %s: %w", filepath.Join(repo, cleaned), err)
	}
	entries := make([]proto.DirEntry, 0, len(des))
	for _, de := range des {
		e := proto.DirEntry{Name: de.Name(), IsDir: de.IsDir()}
		if !de.IsDir() {

			if info, err := de.Info(); err == nil {
				e.Size = info.Size()
			} else {
				log().Debug("取子项大小失败，按 0 记", "repo", repo, "path", rel, "name", de.Name(), "cause", err)
			}
		}
		entries = append(entries, e)
	}
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].IsDir != entries[j].IsDir {
			return entries[i].IsDir
		}
		return entries[i].Name < entries[j].Name
	})
	log().Debug("目录列举完成", "repo", repo, "path", rel, "entries", len(entries))
	return entries, nil
}

n_workspace_ListWorktrees.signature:
// ListWorktrees 拉取一个仓库当前在册的全部工作树。
//
// 参数：ctx 上层上下文，内部叠加 WorkspaceGitTimeout；repo 仓库路径。
// 返回：条目表；仓库不可达或不是 git 仓库时返回错误（调用方据此报「判不出」）。
//
// 注意：这是**地面真相的唯一来源**——任务库里的 worktree_managed 只说明「当初建过」。
func ListWorktrees(ctx context.Context, repo string) (map[string]WorktreeEntry, error) {
	ctx, cancel := context.WithTimeout(ctx, WorkspaceGitTimeout)
	defer cancel()
	out, stderr, err := gitRun(ctx, repo, "worktree", "list", "--porcelain")
	if err != nil {
		log().Warn("拉工作树册失败，该仓库下的任务判不出",
			"repo", repo, "stderr", truncateRunes(stderr, 200), "cause", err)
		return nil, fmt.Errorf("git worktree list %s: %s: %w",
			repo, strings.TrimSpace(truncateRunes(stderr, 200)), err)
	}
	entries := parseWorktreeList(out)
	log().Info("工作树册已拉取", "repo", repo, "entries", len(entries))
	return entries, nil
}

n_workspace_LoadProjectIndex.signature:
// LoadProjectIndex 读一次位置表并构建索引；查表失败时返回空索引（全部未归属）。
//
// 为什么失败不向上抛：归属只是任务列表上的一个注解，位置表读不到时列表本身
// 仍然有效。为一个注解让 /api/tasks 500，是把附加信息变成了单点故障。
func LoadProjectIndex(source ProjectLocationLister, logger *slog.Logger) ProjectIndex {
	locs, err := source.ListProjectLocations()
	if err != nil {
		logger.Warn("读取位置表失败，任务归属本次全部显示未归属", "cause", err)
		return ProjectIndex{}
	}
	return NewProjectIndex(locs)
}

n_workspace_MainWorktreeRoot.signature:
// MainWorktreeRoot 返回 dir 所属 git 仓库的主工作树根目录。
//
// 参数：
//   - ctx: 控制 git 调用生命周期
//   - dir: 任意目录（主仓根/主仓子目录/linked worktree/worktree 子目录）
//
// 返回：
//   - 主工作树根目录的绝对路径（已 Clean）
//   - 错误：dir 不是 git 仓库（或 git 不可用）时返回包装 ErrRepoUnusable 的错误，
//     报文带 git 的 stderr 原文
//
// 注意：
//   - git rev-parse --git-common-dir 在**主仓内**返回相对路径（根目录 ".git"，
//     子目录 "../.git"），在 **linked worktree 内**返回指向主仓的绝对路径。
//     两种形态都要处理：相对时以 dir 为基准拼接，再取父目录
//   - 返回值一律绝对化：位置表的 path 列是绝对路径，UNIQUE 约束要靠它才有意义
func MainWorktreeRoot(ctx context.Context, dir string) (string, error) {
	out, stderr, err := gitRun(ctx, dir, "rev-parse", "--git-common-dir")
	if err != nil {
		log().Warn("主工作树归并失败：目录不是 git 仓库", "dir", dir,
			"stderr", truncateRunes(strings.TrimSpace(stderr), 300), "cause", err)
		return "", fmt.Errorf("%w: %s 不是 git 仓库: %s: %v",
			ErrRepoUnusable, dir, strings.TrimSpace(stderr), err)
	}
	common := strings.TrimSpace(out)
	if common == "" {
		log().Warn("主工作树归并失败：git 返回空的 common-dir", "dir", dir)
		return "", fmt.Errorf("%w: %s 的 git-common-dir 为空", ErrRepoUnusable, dir)
	}

	if !filepath.IsAbs(common) {
		common = filepath.Join(dir, common)
	}
	root, err := filepath.Abs(filepath.Dir(common))
	if err != nil {
		log().Error("主工作树归并失败：绝对化仓库根出错", "dir", dir, "common", common, "cause", err)
		return "", fmt.Errorf("%w: 绝对化 %s: %v", ErrRepoUnusable, common, err)
	}
	if root != dir {
		log().Info("主工作树归并", "from", dir, "root", root)
	}
	return filepath.Clean(root), nil
}

n_workspace_ManualBranchExists.signature:
// ManualBranchExists 判定本地分支是否存在。
//
// 判据是 rev-parse --verify --quiet refs/heads/<名> 有非空输出：--quiet 让
// 「不存在」走退出码而不是 stderr，与 PrepareWorkspace 的判法保持一致。
func ManualBranchExists(ctx context.Context, repo, branch string) bool {
	out, _, err := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", "refs/heads/"+branch)
	return err == nil && strings.TrimSpace(out) != ""
}

