n_workspace_MarkIgnored.signature:
// MarkIgnored 就地给 entries 打上 Ignored 标记。
//
// 参数：
//   - ctx: 上下文；内部再叠加 ignoreProbeTimeout 作为兜底上限
//   - root: 工作树绝对路径（调用方已过白名单闸门）
//   - rel: 这一层相对工作树根的路径；"" 或 "." 表示根
//   - entries: 待标注的条目（原地修改）
//
// 无返回值：所有失败路径都是「保持原样 + 日志」，调用方不需要为它写分支。
//
// 注意：走一次 git 子进程（每层一次，不是每条一次）。列举本身是按需展开的，
// 所以这笔开销只落在用户真正点开的那几层上。
func MarkIgnored(ctx context.Context, root, rel string, entries []proto.DirEntry) {
	if len(entries) == 0 {
		return
	}
	ctx, cancel := context.WithTimeout(ctx, ignoreProbeTimeout)
	defer cancel()

	// 相对仓库根的路径列表；-z 意味着输入输出都用 NUL 分隔，路径里的空格、
	// 换行、引号都不需要转义（文件名什么字符都可能有）
	var in bytes.Buffer
	paths := make([]string, len(entries))
	for i, e := range entries {
		p := e.Name
		if rel != "" && rel != "." {
			p = path.Join(rel, e.Name)
		}
		paths[i] = p
		in.WriteString(p)
		in.WriteByte(0)
	}

	cmd := exec.CommandContext(ctx, "git", "-C", root, "check-ignore", "-z", "--stdin")
	cmd.Stdin = &in
	var out, stderr bytes.Buffer
	cmd.Stdout = &out
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {

		if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() != 1 {
			log().Warn("ignore 探测失败，条目按未忽略返回",
				"root", root, "rel", rel, "cause", strings.TrimSpace(stderr.String()), "err", err)
			return
		}
		log().Debug("ignore 探测完成：本层无忽略项", "root", root, "rel", rel)
		return
	}

	ignored := map[string]bool{}
	for p := range strings.SplitSeq(out.String(), "\x00") {
		if p != "" {
			ignored[p] = true
		}
	}
	n := 0
	for i := range entries {
		if ignored[paths[i]] {
			entries[i].Ignored = true
			n++
		}
	}
	log().Debug("ignore 探测完成", "root", root, "rel", rel, "entries", len(entries), "ignored", n)
}

n_workspace_MayRecycle.signature:
// MayRecycle 决定一次触发能不能回收这棵树。
//
// 规则（全是 keep，除非下面某一条命中 recycle）：
//   - 非 managed（用户树/原地）永远 keep
//   - 手工树永远 keep
//   - waiting_review 永远 keep
//   - TriggerStop 永远 keep（取消留存现场）
//   - TriggerCompensate 且 managed：recycle（executor 尚未接管，无待验收现场）
//   - TriggerDone 或 TriggerExplicit，且终态 managed：recycle
func MayRecycle(in RecycleInput) Decision {
	if !in.Managed || in.Manual {
		return RetainKeep
	}
	if in.State == "waiting_review" {
		return RetainKeep
	}
	if in.Trigger == TriggerStop {
		return RetainKeep
	}
	if in.Trigger == TriggerCompensate {
		return RetainRecycle
	}
	if (in.Trigger == TriggerDone || in.Trigger == TriggerExplicit) && in.Terminal {
		return RetainRecycle
	}
	return RetainKeep
}

n_workspace_Mirror_Run.signature:
// Run 启动发现循环：先立刻跑一轮，然后按 mirrorDiscoveryTick 周期跑，
// ctx 取消时收掉全部订阅与门铃 goroutine。
//
// 注意：Run 内调 Stop 收尾，测试可直接调 Stop 而不用等 ctx 取消。
func (m *Mirror) Run(ctx context.Context) {
	m.log.Info("镜像启动", "tick", mirrorDiscoveryTick.String(), "targets", len(m.machineNames()))
	m.ensureSnapshotLoops(ctx)
	m.discoverOnce(ctx)
	ticker := time.NewTicker(mirrorDiscoveryTick)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			m.log.Info("镜像退出", "cause", ctx.Err())
			m.Stop()
			return
		case <-ticker.C:
			m.ensureSnapshotLoops(ctx)
			m.discoverOnce(ctx)
		}
	}
}

n_workspace_Mirror_Stop.signature:
// Stop 收掉全部订阅与门铃 goroutine，等它们全部退出才返回。
//
// 为什么必须 wg.Wait：镜像的 goroutine 会写本机库与 hub，直接返回等于把
// 「还在写库」的进程留给调用方去关库——竞态（同前 watchdog 的停机顺序纪律）。
func (m *Mirror) Stop() {
	m.mu.Lock()
	for _, cancel := range m.subs {
		cancel()
	}
	m.subs = map[string]context.CancelFunc{}
	m.mu.Unlock()
	m.wg.Wait()
}

n_workspace_Mirror_cancelSub.signature:
// cancelSub 取消一条订阅；返回 false 表示它本来就不在订阅表里。
func (m *Mirror) cancelSub(taskID string) bool {
	m.mu.Lock()
	cancel, ok := m.subs[taskID]
	if ok {
		delete(m.subs, taskID)
	}
	m.mu.Unlock()
	if ok {
		cancel()
	}
	return ok
}

n_workspace_Mirror_discoverOnce.signature:
// discoverOnce 跑一轮发现：对每台 target 拉任务列表，快照进 mirror_tasks，
// 活跃任务开订阅、终态任务收订阅。单台失败不影响其余。
func (m *Mirror) discoverOnce(ctx context.Context) {
	names := m.remoteMachineNames()

	fanCtx, cancel := context.WithTimeout(ctx, mirrorDiscoverBudget)
	defer cancel()

	type result struct {
		name	string
		views	[]proto.TaskView
		err	error
	}
	results := make([]result, len(names))
	var wg sync.WaitGroup
	for i, name := range names {
		wg.Add(1)
		go func(i int, name string) {
			defer wg.Done()
			c, err := m.pool.For(name)
			if err != nil {
				results[i] = result{name: name, err: err}
				return
			}
			views, err := c.ListTasks(fanCtx)
			results[i] = result{name: name, views: views, err: err}
		}(i, name)
	}
	wg.Wait()

	subscribed, dropped, unreachable := 0, 0, 0
	for _, r := range results {
		if r.err != nil {
			m.log.Warn("镜像发现失败", "machine", r.name, "cause", r.err)
			unreachable++
			continue
		}
		now := time.Now().UTC()
		for _, tv := range r.views {
			if err := m.st.UpsertMirrorTask(r.name, tv.Task, now); err != nil {
				m.log.Warn("镜像快照落库失败", "task", tv.Task.ID, "machine", r.name, "cause", err)
				continue
			}
			if tv.Task.State.IsTerminal() {

				if m.cancelSub(tv.Task.ID) {
					dropped++
				}
				continue
			}
			if !m.isSubscribed(tv.Task.ID) {
				subCtx, subCancel := context.WithCancel(ctx)
				m.registerSub(tv.Task.ID, subCancel)
				m.wg.Add(1)
				go m.subscribe(subCtx, r.name, tv.Task.ID)
				subscribed++
			}
		}
	}
	m.log.Info("镜像发现完成", "machines", len(results),
		"subscribed", subscribed, "dropped", dropped, "unreachable", unreachable)
}

n_workspace_Mirror_ensureSnapshotLoops.signature:
// ensureSnapshotLoops 为当前配置里尚未见过的机器启动快照门铃循环。
//
// 运行期新增 target 也必须有消费者：否则事件虽会落库，ringBell 却没有循环来
// 防抖刷新任务快照，新增机器的状态会停在首次发现的旧值。
func (m *Mirror) ensureSnapshotLoops(ctx context.Context) {
	for _, name := range m.remoteMachineNames() {
		m.mu.Lock()
		if _, ok := m.loops[name]; ok {
			m.mu.Unlock()
			continue
		}
		m.loops[name] = struct{}{}
		m.mu.Unlock()
		m.wg.Add(1)
		go m.runSnapshotLoop(ctx, name)
	}
}

n_workspace_Mirror_isSubscribed.signature:
// isSubscribed 报告该任务当前是否持有订阅。
func (m *Mirror) isSubscribed(taskID string) bool {
	m.mu.Lock()
	defer m.mu.Unlock()
	_, ok := m.subs[taskID]
	return ok
}

n_workspace_Mirror_onEvent.signature:
// onEvent 处理上游事件的每一帧：落库、去重、广播、敲门铃、识别终态。
//
// 返回 errMirrorDone 表示任务已终态；返回其他错误会中止本次连接（重连时凭
// 未推进的水位把失败事件重新拉回来）。
func (m *Mirror) onEvent(ctx context.Context, machine string, taskID string, ev proto.Event) error {
	inserted, err := m.st.AppendMirrorEvent(taskID, ev)
	if err != nil {
		m.log.Error("镜像事件落库失败", "task", taskID, "machine", machine, "seq", ev.Seq, "cause", err)

		return err
	}
	if !inserted {

		m.log.Debug("镜像事件重复，跳过广播", "task", taskID, "seq", ev.Seq)
		return nil
	}
	m.log.Debug("镜像事件入库并广播", "task", taskID, "machine", machine, "seq", ev.Seq, "type", ev.Type)
	m.hub.Publish(ev)
	m.ringBell(machine)
	if ev.Type == proto.EventTypeCompleted || ev.Type == proto.EventTypeFailed {
		return errMirrorDone
	}
	return nil
}

n_workspace_Mirror_refreshSnapshot.signature:
// refreshSnapshot 拉一次该 target 的任务列表并全部 upsert（事件即门铃的落点）。
func (m *Mirror) refreshSnapshot(ctx context.Context, machine string) {
	c, err := m.pool.For(machine)
	if err != nil {
		m.log.Warn("镜像快照刷新：取客户端失败", "machine", machine, "cause", err)
		return
	}
	tasks, err := c.ListTasks(ctx)
	if err != nil {
		m.log.Warn("镜像快照刷新失败", "machine", machine, "cause", err)
		return
	}
	now := time.Now().UTC()
	for _, tv := range tasks {
		if err := m.st.UpsertMirrorTask(machine, tv.Task, now); err != nil {
			m.log.Warn("镜像快照落库失败", "task", tv.Task.ID, "machine", machine, "cause", err)
		}
	}
	m.log.Debug("镜像快照刷新完成", "machine", machine, "tasks", len(tasks))
}

n_workspace_Mirror_registerSub.signature:
// registerSub 登记一条订阅（task_id → 取消函数）。
func (m *Mirror) registerSub(taskID string, cancel context.CancelFunc) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.subs[taskID] = cancel
}

n_workspace_Mirror_remoteMachineNames.signature:
// remoteMachineNames returns configured names that are eligible for discovery.
// The complete pool list remains available through machineNames for UI and
// health consumers; only task discovery excludes self-target aliases.
func (m *Mirror) remoteMachineNames() []string {
	names := m.machineNames()
	if m.isSelfTarget == nil {
		return names
	}
	out := make([]string, 0, len(names))
	for _, name := range names {
		if m.isSelfTarget(name) {
			m.log.Debug("跳过本机任务镜像", "machine", name)
			continue
		}
		out = append(out, name)
	}
	return out
}

n_workspace_Mirror_ringBell.signature:
// ringBell 敲响某 target 的门铃（非阻塞：已有待处理门铃时放弃，防抖会合并）。
func (m *Mirror) ringBell(machine string) {
	ch := m.ringOf(machine)
	select {
	case ch <- struct{}{}:
	default:
	}
}

n_workspace_Mirror_ringOf.signature:
// ringOf 取某 target 的门铃通道，没有就建一个（缓冲 1：一个待处理门铃足够，
// 防抖窗口会合并后续响铃）。
func (m *Mirror) ringOf(machine string) chan struct{} {
	m.mu.Lock()
	defer m.mu.Unlock()
	if ch := m.ring[machine]; ch != nil {
		return ch
	}
	ch := make(chan struct{}, 1)
	m.ring[machine] = ch
	return ch
}

n_workspace_Mirror_runSnapshotLoop.signature:
// runSnapshotLoop 消费某 target 的门铃：响铃后等一个防抖窗口，窗口内再次
// 响铃就重置计时，等事件潮过去刷一次快照。
func (m *Mirror) runSnapshotLoop(ctx context.Context, machine string) {
	defer m.wg.Done()
	for {
		select {
		case <-ctx.Done():
			return
		case <-m.ringOf(machine):
		}
		timer := time.NewTimer(snapshotDebounce)
		drained := false
		for !drained {
			select {
			case <-m.ringOf(machine):
				if !timer.Stop() {
					select {
					case <-timer.C:
					default:
					}
				}
				timer.Reset(snapshotDebounce)
			case <-timer.C:
				drained = true
			case <-ctx.Done():
				timer.Stop()
				return
			}
		}
		m.refreshSnapshot(ctx, machine)
	}
}

n_workspace_Mirror_subscribe.signature:
// subscribe 是一条任务的常驻上游订阅：从本机水位续拉事件，断线退避重连，
// 直到任务终态、上下文取消或 Stop。
func (m *Mirror) subscribe(ctx context.Context, machine string, taskID string) {
	defer m.wg.Done()
	defer m.unregisterSub(taskID)
	backoff := mirrorBackoffInitial
	attempt := 0
	for {

		fromSeq, err := m.st.MirrorWatermark(taskID)
		if err != nil {
			m.log.Warn("镜像订阅：读水位失败", "task", taskID, "machine", machine, "cause", err)
			return
		}
		m.log.Info("镜像订阅建立", "task", taskID, "machine", machine, "from_seq", fromSeq)
		c, err := m.pool.For(machine)
		if err != nil {
			m.log.Warn("镜像订阅：取客户端失败", "task", taskID, "machine", machine, "cause", err)
			return
		}
		err = c.StreamEventsOnce(ctx, taskID, fromSeq,
			func(ev proto.Event) error { return m.onEvent(ctx, machine, taskID, ev) })

		switch {
		case ctx.Err() != nil:
			m.log.Info("镜像订阅收掉", "task", taskID, "machine", machine, "reason", "stopped")
			return
		case errors.Is(err, errMirrorDone):

			m.log.Info("镜像订阅收掉", "task", taskID, "machine", machine, "reason", "terminal")
			return
		case err == nil:
			m.log.Warn("镜像订阅意外结束", "task", taskID, "machine", machine, "cause", "stream returned nil")
		default:
			m.log.Warn("镜像订阅断线，等待后重连", "task", taskID, "machine", machine,
				"attempt", attempt, "backoff_ms", backoff.Milliseconds(), "cause", err)
		}

		select {
		case <-ctx.Done():
			m.log.Info("镜像订阅收掉", "task", taskID, "machine", machine, "reason", "stopped")
			return
		case <-time.After(backoff):
		}
		backoff *= 2
		if backoff > mirrorBackoffMax {
			backoff = mirrorBackoffMax
		}
		attempt++
	}
}

n_workspace_Mirror_unregisterSub.signature:
// unregisterSub 摘除一条订阅登记（subscribe 退出时调用）。
func (m *Mirror) unregisterSub(taskID string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	delete(m.subs, taskID)
}

n_workspace_NewMirror.signature:
// NewMirror 创建镜像管理器。
//
// 参数：
//   - pool: target 客户端源（同时提供客户端与活的 target 清单）
//   - st: 本机存储（mirror_events / mirror_tasks 的落点）
//   - hub: 本机实时路由（镜像事件经它 Publish，让 /ws/events 订阅者立刻收到）
//   - isSelfTarget: 自机登记名判定；nil 表示不额外过滤名称
//   - log: 本镜像的日志入口
func NewMirror(pool RemoteTaskSource, st MirrorStore, hub EventPublisher,
	isSelfTarget func(name string) bool, log *slog.Logger) *Mirror {
	return &Mirror{
		pool:		pool,
		st:		st,
		hub:		hub,
		log:		log,
		isSelfTarget:	isSelfTarget,
		subs:		map[string]context.CancelFunc{},
		ring:		map[string]chan struct{}{},
		loops:		map[string]struct{}{},
	}
}

n_workspace_NewPreviewHub.signature:
// NewPreviewHub constructs an empty bounded preview event hub.
func NewPreviewHub(log *slog.Logger) *PreviewHub {
	if log == nil {
		log = slog.Default()
	}
	return &PreviewHub{subscribers: make(map[uint64]chan proto.PreviewEvent), log: log}
}

n_workspace_NewPreviewOwner.signature:
// NewPreviewOwner creates an owner using injected seams or production defaults.
// Static 不设缺省：生产实现（gateway 的静态 HTTP 服务）由组装点注入。
func NewPreviewOwner(st PreviewStore, hub *PreviewHub, deps PreviewOwnerDeps, log *slog.Logger) *PreviewOwner {
	if log == nil {
		log = slog.Default()
	}
	if hub == nil {
		hub = NewPreviewHub(log)
	}
	if deps.Now == nil {
		deps.Now = func() time.Time { return time.Now().UTC() }
	}
	if deps.NewID == nil {
		deps.NewID = uuid.NewString
	}
	if deps.Getwd == nil {
		deps.Getwd = os.Getwd
	}
	if deps.ProbePort == nil {
		deps.ProbePort = probePreviewPort
	}
	if deps.ResolveWorkspace == nil {
		deps.ResolveWorkspace = func(ctx context.Context, workspaceCWD string) (string, string, string, error) {
			getwd := deps.Getwd
			if workspaceCWD != "" {
				getwd = func() (string, error) { return workspaceCWD, nil }
			}
			return defaultPreviewWorkspaceResolver(ctx, getwd)
		}
	}
	if deps.ValidateVia == nil {
		deps.ValidateVia = ValidatePreviewViaSyntax
	}
	return &PreviewOwner{st: st, hub: hub, deps: deps, log: log, staticStops: make(map[string]func() error)}
}

n_workspace_NewProjectIndex.signature:
// NewProjectIndex 由位置表构建索引。
func NewProjectIndex(locs []proto.ProjectLocation) ProjectIndex {
	idx := make(ProjectIndex, len(locs))
	for _, l := range locs {
		if l.Path == "" {
			continue
		}
		idx[filepath.Clean(l.Path)] = l.ProjectID
	}
	return idx
}

n_workspace_NewResultRef.signature:
// NewResultRef 构造结果引用。commit 非空时必须通过 IsCommitSHA。
func NewResultRef(repo, branch, commit, path string) (ResultRef, error) {
	if commit != "" && !IsCommitSHA(commit) {
		return ResultRef{}, fmt.Errorf("结果 commit 必须是 40 位小写十六进制，实得 %q", commit)
	}
	return ResultRef{Repo: repo, Branch: branch, Commit: commit, Path: path}, nil
}

n_workspace_OriginURL.signature:
// OriginURL 读取仓库 origin 地址（git remote get-url origin）。
//
// 参数：ctx 控制本次 git 调用；repo 仓库路径。
// 返回：origin 地址；仓库不可用或没有 origin 时返回包装 ErrRepoUnusable 的错误。
//
// 注意：没有 origin 的仓库不能登记——project_id 由 origin 派生。
func OriginURL(ctx context.Context, repo string) (string, error) {
	out, stderr, err := gitRun(ctx, repo, "remote", "get-url", "origin")
	if err != nil {
		return "", fmt.Errorf("%w: 读取 %s 的 origin 失败: %s: %v",
			ErrRepoUnusable, repo, strings.TrimSpace(stderr), err)
	}
	url := strings.TrimSpace(out)
	if url == "" {
		return "", fmt.Errorf("%w: 仓库 %s 没有配置 origin remote", ErrRepoUnusable, repo)
	}
	return url, nil
}

n_workspace_PrepareBranch.signature:
// PrepareBranch 是 PrepareWorkspace 的过渡薄包装：保持一期「原地 + 自动分支」语义
// 与全部错误哨兵（ErrDirtyWorktree/ErrRepoUnusable），Dispatch 改走 PrepareWorkspace
// 后本函数仅剩测试与本包内部引用（Task 7 会清理调用点）。
//
// 参数：
//   - ctx: 控制整组 git 调用的生命周期，内部再叠加 WorkspaceGitTimeout 作为兜底上限
func PrepareBranch(ctx context.Context, repo, taskID string) (branch string, err error) {
	ws, err := PrepareWorkspace(ctx, WorkspaceReq{Repo: repo, TaskID: taskID})
	if err != nil {
		return "", err
	}
	return ws.Branch, nil
}

n_workspace_PrepareWorkspace.signature:
// PrepareWorkspace 按 WorkspaceReq 准备任务工作区，返回结果。
//
// 参数：
//   - ctx: 控制整组 git 调用的生命周期，内部再叠加 WorkspaceGitTimeout 作为兜底上限
//
// 3 分支模式 × 3 工作树模式的 9 种组合行为表（分支 B/新分支 N/自动 A × 新树 N/用户树 U/原地 I）：
//
//	      新树(NewWorktree)        用户树(Worktree)        原地(默认)
//	B   worktree add <p> <b>     校验归属+脏，checkout b   脏检查，checkout b
//	N   worktree add -b b <p> t  校验归属+脏，checkout -b  脏检查，checkout -b b [t]
//	A   worktree add -b h <p> [t] 校验归属+脏，checkout -b  脏检查，checkout -b h [t]
//
// 其中 b=指定分支、h=handoff/<id8>、t=Base（N 行与 A 行均有效，空=HEAD；B 行
// 切已存在分支，不接受 Base，见第 1 层校验）、p=WorktreesDir/<id8> 或用户路径。
// 校验规则：Branch 模式分支必须已存在；用户树模式必须归属本仓库（git-common-dir 比对
// + show-toplevel 必须等于入参）；所有以 "-" 开头的分支名/路径一律拒绝（git 参数注入面）。
//
// 为什么 NewWorktree 免脏检查：新 worktree 是从仓库新建的独立工作树，天然干净，
// 与主仓库的脏状态无关——这是 worktree 并行派发的价值：主仓有人手动改动也不阻塞
// 新任务开跑；只有原地/用户树模式（复用既有工作树）才需要脏检查防污染。
//
// 为什么用户树归属校验用 git-common-dir 比对：普通目录与 worktree 的差别就在
// 「共享同一仓库 git 目录」；git-common-dir 对 main 仓库返回其 .git、对 worktree
// 返回同一值，路径经 EvalSymlinks 归一后相等即归属成立——比「读 .git 文件内容」
// 更稳（.git 可能缺失、可能被链到别处）。校验失败按 ErrBadWorkspaceReq 拒发。
func PrepareWorkspace(ctx context.Context, req WorkspaceReq) (Workspace, error) {
	ctx, cancel := context.WithTimeout(ctx, WorkspaceGitTimeout)
	defer cancel()
	log().Info("工作区准备进入", "repo", req.Repo, "task", req.TaskID, "branch", req.Branch,
		"new_branch", req.NewBranch, "base", req.Base, "worktree", req.Worktree,
		"new_worktree", req.NewWorktree, "worktrees_dir", req.WorktreesDir,
		"timeout", WorkspaceGitTimeout)

	if req.Repo == "" || req.TaskID == "" {
		return Workspace{}, rejectWorkspace("repo 与 task_id 必填", req)
	}
	if req.Branch != "" && req.NewBranch != "" {
		return Workspace{}, rejectWorkspace("branch 与 new-branch 互斥", req)
	}
	if req.Worktree != "" && req.NewWorktree {
		return Workspace{}, rejectWorkspace("worktree 与 new-worktree 互斥", req)
	}

	if req.Base != "" && req.Branch != "" {
		return Workspace{}, rejectWorkspace("base 与 branch（已存在分支）互斥", req)
	}
	for _, name := range []struct{ what, v string }{
		{"branch", req.Branch}, {"new-branch", req.NewBranch}, {"base", req.Base}, {"worktree", req.Worktree},
	} {
		if strings.HasPrefix(name.v, "-") {
			return Workspace{}, rejectWorkspace(name.what+" 不允许以 - 开头（git 参数注入面）", req)
		}
	}

	branch := req.Branch
	if branch == "" {
		branch = req.NewBranch
	}
	if branch == "" {
		branch = TaskBranch(req.TaskID)
	}
	isExisting := req.Branch != ""
	if isExisting {

		if out, _, err := gitProbe(ctx, req.Repo, "rev-parse", "--verify", "--quiet", "refs/heads/"+req.Branch); err != nil || strings.TrimSpace(out) == "" {
			return Workspace{}, rejectWorkspace("分支 "+req.Branch+" 不存在", req)
		}
	}

	var ws Workspace

	switch {
	case req.NewWorktree:

		dirtyCount, dirtyFiles := repoDirtySnapshot(ctx, req.Repo)
		workDir := filepath.Join(req.WorktreesDir, ID8(req.TaskID))
		if err := os.MkdirAll(req.WorktreesDir, 0o700); err != nil {
			return Workspace{}, fmt.Errorf("创建 worktrees 目录 %s: %w", req.WorktreesDir, err)
		}
		var args []string
		if isExisting {
			args = []string{"worktree", "add", workDir, branch}
		} else {
			args = []string{"worktree", "add", "-b", branch, workDir}
			if req.Base != "" {
				args = append(args, req.Base)
			}
		}
		if _, stderr, err := gitRun(ctx, req.Repo, args...); err != nil {
			return Workspace{}, fmt.Errorf("git %v: %s: %w", args, strings.TrimSpace(stderr), err)
		}
		ws = Workspace{Branch: branch, WorkDir: workDir, Managed: true,
			RepoDirtyCount:	dirtyCount, RepoDirtyFiles: dirtyFiles}
		if !isExisting {
			ws.NewBranchTip = recordNewBranchTip(ctx, req.Repo, branch)
		}
	case req.Worktree != "":

		if !worktreeBelongsToRepo(ctx, req.Repo, req.Worktree) {
			return Workspace{}, rejectWorkspace("路径 "+req.Worktree+" 不是本仓库的 worktree", req)
		}
		if err := ensureCleanWorktree(ctx, req.Worktree); err != nil {
			return Workspace{}, err
		}
		prev := currentRef(ctx, req.Worktree)
		if err := checkoutInWorktree(ctx, req.Worktree, branch, req.Base, isExisting); err != nil {
			return Workspace{}, err
		}
		ws = Workspace{Branch: branch, WorkDir: req.Worktree, Managed: false, PrevRef: prev}
		if !isExisting {
			ws.NewBranchTip = recordNewBranchTip(ctx, req.Repo, branch)
		}
	default:

		if err := ensureCleanWorktree(ctx, req.Repo); err != nil {
			return Workspace{}, err
		}
		prev := currentRef(ctx, req.Repo)
		var args []string
		if isExisting {
			args = []string{"checkout", branch}
		} else {
			args = []string{"checkout", "-b", branch}
			if req.Base != "" {
				args = append(args, req.Base)
			}
		}
		if _, stderr, err := gitRun(ctx, req.Repo, args...); err != nil {
			return Workspace{}, fmt.Errorf("git %v: %s: %w", args, strings.TrimSpace(stderr), err)
		}
		ws = Workspace{Branch: branch, WorkDir: req.Repo, Managed: false, PrevRef: prev}
		if !isExisting {
			ws.NewBranchTip = recordNewBranchTip(ctx, req.Repo, branch)
		}
	}

	if verr := verifyBranchIdentity(ctx, ws.WorkDir, ws.Branch); verr != nil {
		log().Error("工作区分支身份核对失败，回滚并拒发", "task", req.TaskID,
			"want", ws.Branch, "workdir", ws.WorkDir, "managed", ws.Managed, "cause", verr)
		rollbackWorkspace(ctx, req.Repo, ws)
		return Workspace{}, verr
	}
	log().Info("工作区分支身份核对通过", "task", req.TaskID, "branch", ws.Branch)
	log().Info("工作区准备完成", "task", req.TaskID, "branch", ws.Branch, "workdir", ws.WorkDir, "managed", ws.Managed)

	if ctx.Err() != nil {
		log().Error("工作区准备超时", "task", req.TaskID, "timeout", WorkspaceGitTimeout, "cause", ctx.Err())
	}
	return ws, nil
}

n_workspace_PreviewHub_Close.signature:
// Close terminates every preview event stream and is safe to call repeatedly.
func (h *PreviewHub) Close() {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed {
		return
	}
	h.closed = true
	for id, ch := range h.subscribers {
		close(ch)
		delete(h.subscribers, id)
	}
}

n_workspace_PreviewHub_Publish.signature:
// Publish broadcasts one already-persisted event without waiting for consumers.
func (h *PreviewHub) Publish(event proto.PreviewEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for id, ch := range h.subscribers {
		select {
		case ch <- event:
		default:
			delete(h.subscribers, id)
			close(ch)
			h.log.Warn("预览 WS 订阅者过慢，已取消", "subscriber", id, "event", event.Type, "session", event.Session.ID)
		}
	}
}

n_workspace_PreviewHub_Subscribe.signature:
// Subscribe returns a bounded event stream and an idempotent cancellation function.
func (h *PreviewHub) Subscribe() (<-chan proto.PreviewEvent, func()) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.closed {
		ch := make(chan proto.PreviewEvent)
		close(ch)
		return ch, func() {}
	}
	h.nextID++
	id := h.nextID
	ch := make(chan proto.PreviewEvent, 16)
	h.subscribers[id] = ch
	return ch, func() { h.unsubscribe(id) }
}

n_workspace_PreviewHub_SubscriberCount.signature:
// SubscriberCount returns the current number of live subscribers. 测试用它等待
// 「WS 订阅者已连上」；不加锁拷贝，计数仅供观测。
func (h *PreviewHub) SubscriberCount() int {
	h.mu.Lock()
	defer h.mu.Unlock()
	return len(h.subscribers)
}

n_workspace_PreviewHub_unsubscribe.signature:
func (h *PreviewHub) unsubscribe(id uint64) {
	h.mu.Lock()
	defer h.mu.Unlock()
	ch, ok := h.subscribers[id]
	if !ok {
		return
	}
	delete(h.subscribers, id)
	close(ch)
}

n_workspace_PreviewInputError_Error.signature:
func (e *PreviewInputError) Error() string {
	return fmt.Sprintf("preview %s field=%s value=%q: %s", e.Operation, e.Field, e.Value, e.Reason)
}

n_workspace_PreviewOwner_Close.signature:
// Close conditionally closes one owner session and publishes its full closed event once.
func (o *PreviewOwner) Close(ctx context.Context, id string) (*proto.PreviewCloseResp, error) {
	_ = ctx
	o.mu.Lock()
	row, changed, err := o.st.ClosePreview(id, o.deps.Now().UTC())
	var stop func() error
	if err == nil && changed {
		stop = o.staticStops[id]
		delete(o.staticStops, id)
	}
	o.mu.Unlock()
	if err != nil {
		o.log.Warn("关闭预览会话失败", "operation", "close", "session", id, "cause", err)
		return nil, err
	}
	if !changed {
		return nil, fmt.Errorf("预览会话 %s: %w", id, ErrPreviewClosed)
	}
	if stop != nil {
		if err := stop(); err != nil {
			o.log.Warn("停止预览静态服务失败", "operation", "close", "session", id, "cause", err)
		}
	}
	o.hub.Publish(proto.PreviewEvent{Type: proto.PreviewEventClosed, Session: row.Session})
	o.log.Info("预览会话关闭成功", "operation", "close", "session", id)
	return &proto.PreviewCloseResp{OK: true}, nil
}

n_workspace_PreviewOwner_Create.signature:
// Create validates and persists one owner preview, publishing only after the row exists.
func (o *PreviewOwner) Create(ctx context.Context, req proto.PreviewOpenReq) (*proto.PreviewSession, error) {
	now := o.deps.Now().UTC()
	if (req.Port == 0) == (strings.TrimSpace(req.Path) == "") {
		return nil, &PreviewInputError{Operation: "create", Field: "port/path", Value: fmt.Sprintf("port=%d path=%q", req.Port, req.Path), Reason: "port 与 path 必须二选一"}
	}
	if req.Port != 0 && (req.Port < 1 || req.Port > 65535) {
		return nil, &PreviewInputError{Operation: "create", Field: "port", Value: fmt.Sprint(req.Port), Reason: "必须在 1..65535"}
	}
	if err := o.deps.ValidateVia(req.Via); err != nil {
		return nil, &PreviewInputError{Operation: "create", Field: "via", Value: strings.Join(req.Via, ","), Reason: err.Error()}
	}
	cwd := req.CWD
	var err error
	if cwd == "" {
		cwd, err = o.deps.Getwd()
		if err != nil {
			o.log.Error("创建预览无法取得工作目录", "operation", "create", "cause", err)
			return nil, fmt.Errorf("取得工作目录: %w", err)
		}
	} else {
		o.log.Info("创建预览使用请求工作目录", "operation", "create", "requested_cwd", cwd)
	}
	cwd, err = filepath.EvalSymlinks(cwd)
	if err != nil {
		o.log.Error("创建预览工作目录解析失败", "operation", "create", "cwd", cwd, "cause", err)
		return nil, fmt.Errorf("解析工作目录: %w", err)
	}

	session := proto.PreviewSession{ID: o.deps.NewID(), CWD: cwd, CreatedAt: now, TTLSeconds: PreviewTTLSeconds, Via: append([]string(nil), req.Via...)}
	if session.ID == "" {
		return nil, errors.New("生成预览会话 ID 为空")
	}
	row := PreviewRow{Session: session, LastActiveAt: now}
	var stop func() error
	if req.Port != 0 {
		if err := o.deps.ProbePort(ctx, req.Port); err != nil {
			o.log.Warn("预览端口未监听", "operation", "create", "port", req.Port, "cause", err)
			return nil, &PreviewInputError{Operation: "create", Field: "port", Value: fmt.Sprint(req.Port), Reason: "端口未监听: " + err.Error()}
		}
		root, origin, branch, err := o.deps.ResolveWorkspace(ctx, cwd)
		if err != nil {
			o.log.Warn("读取 port 预览工作区元数据失败", "operation", "create", "port", req.Port, "cwd", cwd, "cause", err)
			return nil, fmt.Errorf("解析 port 预览工作区: %w", err)
		}
		session.EntryURL = fmt.Sprintf("http://localhost:%d", req.Port)
		session.OriginURL, session.Branch = origin, branch
		if root == "" {
			root = cwd
		}
		row.Source = PreviewSource{Kind: "port", Port: req.Port, WorkspaceRoot: root}
	} else {
		root, origin, branch, err := o.deps.ResolveWorkspace(ctx, cwd)
		if err != nil {
			o.log.Warn("读取 path 预览工作区元数据失败", "operation", "create", "cwd", cwd, "path", req.Path, "cause", err)
			return nil, fmt.Errorf("解析预览工作区 path=%q: %w", req.Path, err)
		}
		rel, err := ValidatePreviewRelativePath(root, req.Path)
		if err != nil {
			o.log.Warn("预览 path 校验失败", "operation", "create", "cwd", cwd, "workspace", root, "path", req.Path, "cause", err)
			return nil, &PreviewInputError{Operation: "create", Field: "path", Value: req.Path, Reason: err.Error()}
		}
		entry, cleanup, err := o.deps.Static.Start(ctx, root, rel)
		if err != nil {
			o.log.Error("启动预览静态服务失败", "operation", "create", "path", req.Path, "cause", err)
			return nil, fmt.Errorf("启动预览静态服务: %w", err)
		}
		stop = cleanup
		session.EntryURL, session.OriginURL, session.Branch = entry, origin, branch
		row.Source = PreviewSource{Kind: "path", WorkspaceRoot: root, RelativePath: rel}
	}
	row.Session = session
	o.mu.Lock()
	err = o.st.InsertPreview(row)
	if err == nil && stop != nil {
		o.staticStops[session.ID] = stop
	}
	o.mu.Unlock()
	if err != nil {
		if stop != nil {
			_ = stop()
		}
		o.log.Error("预览会话持久化失败", "operation", "create", "session", session.ID, "cause", err)
		return nil, err
	}
	o.hub.Publish(proto.PreviewEvent{Type: proto.PreviewEventCreated, Session: session})
	o.log.Info("预览会话创建成功", "operation", "create", "session", session.ID, "entry_url", session.EntryURL)
	return &session, nil
}

n_workspace_PreviewOwner_Expire.signature:
// Expire closes idle sessions and publishes one complete event per transition.
func (o *PreviewOwner) Expire(ctx context.Context) error {
	_ = ctx
	rows, err := o.st.ExpirePreviews(o.deps.Now().UTC())
	if err != nil {
		return err
	}
	for _, row := range rows {
		o.stopStatic(row.Session.ID)
		o.hub.Publish(proto.PreviewEvent{Type: proto.PreviewEventClosed, Session: row.Session})
		o.log.Info("预览会话因 idle TTL 关闭", "operation", "expire", "session", row.Session.ID)
	}
	return nil
}

n_workspace_PreviewOwner_Get.signature:
// Get 返回一个会话的持久化行（含生命周期时间），供 gateway 侧判定会话是否
// 仍可打开。未登记时持久层的 not found 错误原样穿透。
func (o *PreviewOwner) Get(id string) (PreviewRow, error) {
	if o.st == nil {
		return PreviewRow{}, errors.New("preview owner 未配置")
	}
	return o.st.GetPreview(id)
}

n_workspace_PreviewOwner_List.signature:
// List returns active owner sessions; machine is intentionally absent.
func (o *PreviewOwner) List(ctx context.Context) (*proto.PreviewListResp, error) {
	_ = ctx
	rows, err := o.st.ListActivePreviews(o.deps.Now().UTC())
	if err != nil {
		o.log.Error("读取预览会话列表失败", "operation", "list", "cause", err)
		return nil, err
	}
	out := &proto.PreviewListResp{Sessions: make([]proto.PreviewSession, 0, len(rows))}
	for _, row := range rows {
		row.Session.Machine = ""
		out.Sessions = append(out.Sessions, row.Session)
	}
	o.log.Info("预览会话列表读取成功", "operation", "list", "count", len(out.Sessions))
	return out, nil
}

n_workspace_PreviewOwner_Restore.signature:
// Restore restarts path static servers for active persisted sessions and starts the TTL loop.
func (o *PreviewOwner) Restore(ctx context.Context) error {
	rows, err := o.st.ListActivePreviews(o.deps.Now().UTC())
	if err != nil {
		return err
	}
	for _, row := range rows {
		if row.Source.Kind != "path" {
			continue
		}
		entry, stop, err := o.deps.Static.Start(ctx, row.Source.WorkspaceRoot, row.Source.RelativePath)
		if err != nil {
			o.log.Error("恢复预览静态服务失败", "operation", "restore", "session", row.Session.ID, "cause", err)
			continue
		}
		o.mu.Lock()
		err = o.st.UpdatePreviewEntry(row.Session.ID, entry)
		if err == nil {
			o.staticStops[row.Session.ID] = stop
		}
		o.mu.Unlock()
		if err != nil {
			_ = stop()
			o.log.Error("恢复预览 entry_url 写入失败", "operation", "restore", "session", row.Session.ID, "cause", err)
			continue
		}
	}
	o.startExpiry(ctx)
	o.log.Info("预览 owner 恢复完成", "operation", "restore", "count", len(rows))
	return nil
}

n_workspace_PreviewOwner_Stop.signature:
// Stop cancels the TTL loop, closes the hub and reclaims owner static servers.
func (o *PreviewOwner) Stop(ctx context.Context) error {
	_ = ctx
	o.expireMu.Lock()
	if o.expireStop != nil {
		o.expireStop()
		o.expireStop = nil
	}
	o.expireMu.Unlock()
	o.expireWG.Wait()
	o.mu.Lock()
	stops := make([]func() error, 0, len(o.staticStops))
	for id, stop := range o.staticStops {
		stops = append(stops, stop)
		delete(o.staticStops, id)
	}
	o.mu.Unlock()
	for _, stop := range stops {
		if err := stop(); err != nil {
			o.log.Warn("停止预览静态服务失败", "operation", "stop", "cause", err)
		}
	}
	o.hub.Close()
	o.log.Info("预览 owner 已停止", "operation", "stop", "static_servers", len(stops))
	return nil
}

n_workspace_PreviewOwner_Touch.signature:
// Touch renews idle lifetime for an open session; it does not alter wire is-open state.
func (o *PreviewOwner) Touch(ctx context.Context, id string, at time.Time) error {
	_ = ctx
	return o.st.TouchPreview(id, at.UTC())
}

n_workspace_PreviewOwner_startExpiry.signature:
func (o *PreviewOwner) startExpiry(parent context.Context) {
	o.expireMu.Lock()
	defer o.expireMu.Unlock()
	if o.expireStop != nil {
		return
	}
	ctx, cancel := context.WithCancel(parent)
	o.expireStop = cancel
	o.expireWG.Add(1)
	go func() {
		defer o.expireWG.Done()
		ticker := time.NewTicker(time.Minute)
		defer ticker.Stop()
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				if err := o.Expire(ctx); err != nil {
					o.log.Error("预览 TTL 扫描失败", "operation", "expire", "cause", err)
				}
			}
		}
	}()
}

n_workspace_PreviewOwner_stopStatic.signature:
func (o *PreviewOwner) stopStatic(id string) {
	o.mu.Lock()
	stop := o.staticStops[id]
	delete(o.staticStops, id)
	o.mu.Unlock()
	if stop == nil {
		return
	}
	if err := stop(); err != nil {
		o.log.Warn("停止预览静态服务失败", "operation", "close", "session", id, "cause", err)
	}
}

n_workspace_ProbeCommit.signature:
// ProbeCommit 把 rev 解析成 40 位提交号（git rev-parse <rev>）。
//
// 参数：ctx 控制本次 git 调用；repo 仓库路径；rev 任意 rev。
// 返回：去空白的 rev-parse 输出与错误；调用方负责 IsCommitSHA 复核。
func ProbeCommit(ctx context.Context, repo, rev string) (string, error) {
	out, _, err := gitProbe(ctx, repo, "rev-parse", rev)
	if err != nil {
		return "", err
	}
	return strings.TrimSpace(out), nil
}

n_workspace_ProbeOriginURL.signature:
// ProbeOriginURL 探活仓库 origin 地址（预览元数据专用，fail-open）。
//
// 参数：ctx 控制本次 git 调用；repo 仓库路径。
// 返回：origin 地址与是否命中；没有 origin 或仓库不可用时返回 ("", false)，
// 走 gitProbe 口径（未命中记 Debug 不记 Error），与 TopLevel/HeadBranch 一致。
//
// 注意：登记路径必须用 OriginURL——那里「没有 origin」要拒绝登记，语义相反，
// 不得用本探针替代。
func ProbeOriginURL(ctx context.Context, repo string) (string, bool) {
	out, _, err := gitProbe(ctx, repo, "remote", "get-url", "origin")
	if err != nil {
		return "", false
	}
	val := strings.TrimSpace(out)
	if val == "" {
		return "", false
	}
	return val, true
}

n_workspace_ProbeWorkspaces.signature:
// ProbeWorkspaces 现场探测 dir 下的全部工作树。
//
// 参数：
//   - ctx: 上下文；内部再叠加 worktreeProbeTimeout 作为兜底上限
//   - dir: location 的路径（B62 保证它是主工作树根）
//   - managedRoot: agentd 自建 worktree 的根目录（<DataDir>/worktrees）；
//     空串表示「无法判定 managed」，此时全部按 false
//
// 返回：
//   - 工作树列表（**永不为 nil**，失败时是空切片）
//   - 探测失败的人话说明，空串=正常
//
// 注意：
//   - 失败不返回 error 而返回说明字符串，是刻意的：调用方要把它放进
//     ProjectLocationNode.ProbeError 展示，而不是让整棵树 500
func ProbeWorkspaces(ctx context.Context, dir, managedRoot string) ([]proto.Workspace, string) {
	ctx, cancel := context.WithTimeout(ctx, worktreeProbeTimeout)
	defer cancel()

	log().Debug("工作区探测开始", "dir", dir)
	out, stderr, err := gitRun(ctx, dir, "worktree", "list", "--porcelain")
	if err != nil {
		msg := strings.TrimSpace(stderr)
		if msg == "" {
			msg = err.Error()
		}

		log().Warn("工作区探测失败，降级为空列表", "dir", dir, "cause", msg)
		return []proto.Workspace{}, msg
	}
	ws := parseWorktreePorcelain(out, managedRoot)

	for i := range ws {
		ws[i].CreatedAt = workspaceCreatedAt(ws[i].Path, ws[i].IsMain)
	}
	log().Debug("工作区探测完成", "dir", dir, "worktrees", len(ws))
	return ws, ""
}

n_workspace_ProjectIndex_ProjectIDOf.signature:
// ProjectIDOf 返回该仓库路径所属的 project_id；未登记/已注销返回空串。
//
// 注意：空串是**正常结果**而非错误——「未归属」是项目树与看板要如实展示的一种状态。
func (idx ProjectIndex) ProjectIDOf(repoPath string) string {
	if repoPath == "" {
		return ""
	}
	return idx[filepath.Clean(repoPath)]
}

n_workspace_ProjectNameFromURL.signature:
// ProjectNameFromURL 从 git URL 末段派生缺省引用名（去掉 .git 后缀）。
//
// 例：git@github.com:Xsxdot/handoff.git → handoff
//
// why 分隔符集合里有反斜杠：origin 可以是 Windows 本地路径（`C:\work\x.git`）。
// git URL 的四种形态（https/ssh/scp 简写/file）都不含反斜杠，把它加进集合
// 对既有形态零影响，只有本地路径 origin 会走到这一支。
func ProjectNameFromURL(url string) string {
	s := strings.TrimRight(strings.TrimSpace(url), `/\`)
	s = strings.TrimSuffix(s, ".git")
	if i := strings.LastIndexAny(s, `/:\`); i >= 0 {
		s = s[i+1:]
	}
	return s
}

n_workspace_PruneWorktrees.signature:
// PruneWorktrees 清理丢失目录的 worktree 元数据（git worktree prune）。
//
// 参数：ctx 上层上下文，内部叠加 WorkspaceGitTimeout；repo 主仓库路径。
// 返回：失败时返回包装 stderr 原文的错误，成功 nil。
func PruneWorktrees(ctx context.Context, repo string) error {
	ctx, cancel := context.WithTimeout(ctx, WorkspaceGitTimeout)
	defer cancel()
	if _, stderr, err := gitRun(ctx, repo, "worktree", "prune"); err != nil {
		return fmt.Errorf("git worktree prune %s: %s: %w",
			repo, strings.TrimSpace(truncateRunes(stderr, 200)), err)
	}
	return nil
}

n_workspace_ReadFile.signature:
// ReadFile 读取任务仓库内相对路径文件的内容（审核者取上下文用）。
//
// 路径逃逸防御（安全红线，两道）：
//  1. filepath.Clean 归一化后，任何绝对路径或残留 .. 前缀的路径一律拒绝（ErrPathEscape）
//  2. 实际打开经 os.OpenRoot（内核级 jail）：路径中任何符号链接指向仓库外时，
//     打开直接失败。为什么不用 EvalSymlinks 前缀校验：那是「先校验、后打开」两步，
//     校验与打开之间有 TOCTOU 竞态窗口——恶意 executor 经 run 命令完全能在这个
//     窗口里把链接换成指向仓库外的版本；os.OpenRoot 的解析在单次打开内由内核完成，
//     无窗口。
//
// os.OpenRoot 的边界（stdlib 契约，Go 1.24+）：符号链接目标必须是相对路径
// （"Symbolic links must not be absolute"），故绝对目标链接一律拒绝（ErrPathEscape），
// 即使目标在仓库内也拒绝——保守语义，见 TestReadFileSymlinkEscape；
// 仓库根自身是符号链接时 OpenRoot 跟随之，读链接指向的真实仓库，正常可用。
//
// 大小上限：只读 maxRunOutput+1 字节（+1 仅用于判定是否超限），超限截断并 Warn——
// 与 RunCmd 的输出截断语义一致：返回开头、不整读内存，64MiB 大文件不会把 agentd 读挂。
// 截断而非拒绝：fetch 的用途是看文件开头（审阅上下文），1MiB 对源文件足够；
// 大文件多为生成物/数据文件，拒绝会让审核者误以为路径有误。
// 截断提示不再由本函数拼接，改由端点层按各自契约决定（handleTaskFile 拼、
// handleWorkspaceFile 不拼）——本函数返回的是保真的读，在线编辑那条线才敢把
// 内容原样存回磁盘。
//
// 非普通文件（目录/管道/设备等）一律拒绝：目录给 ErrPathIsDir（400 语义），
// 其余特殊文件 read 语义不可控（可能无限输出或永久阻塞），给 ErrNotRegularFile。
//
// 参数：
//   - repo: 任务仓库路径
//   - rel: 相对仓库根的路径（如 cmd/foo.go）
//
// 返回：
//   - proto.FileRead{Content, Size, Truncated, Binary, SHA256}，其中 SHA256 仅当
//     !Binary && !Truncated 时有值
//   - err: 路径逃逸（含符号链接逃逸）返回 ErrPathEscape；目录返回 ErrPathIsDir；
//     其他特殊文件返回 ErrNotRegularFile；文件不存在返回 *fs.PathError（含 %w 链）
func ReadFile(repo, rel string) (proto.FileRead, error) {
	cleaned := filepath.Clean(rel)
	if rel == "" || cleaned == "." || filepath.IsAbs(cleaned) ||
		cleaned == ".." || strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) {
		log().Warn("文件读取路径逃逸被拒绝", "repo", repo, "path", rel)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrPathEscape, rel)
	}
	root, err := os.OpenRoot(repo)
	if err != nil {
		return proto.FileRead{}, fmt.Errorf("打开任务仓库 %s: %w", repo, err)
	}
	defer root.Close()

	f, err := root.OpenFile(cleaned, os.O_RDONLY|openNonBlock, 0)
	if err != nil {
		if rootErrIsEscape(err) {

			log().Warn("文件读取路径逃逸被拒绝", "repo", repo, "path", rel)
			return proto.FileRead{}, fmt.Errorf("%w: %q", ErrPathEscape, rel)
		}
		return proto.FileRead{}, fmt.Errorf("读取文件 %s: %w", filepath.Join(repo, cleaned), err)
	}
	defer f.Close()
	fi, err := f.Stat()
	if err != nil {
		return proto.FileRead{}, fmt.Errorf("读取文件 %s: %w", filepath.Join(repo, cleaned), err)
	}
	if !fi.Mode().IsRegular() {
		log().Warn("文件读取目标不是普通文件", "repo", repo, "path", rel, "mode", fi.Mode().String())
		if fi.IsDir() {
			return proto.FileRead{}, fmt.Errorf("%w: %q", ErrPathIsDir, rel)
		}
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrNotRegularFile, rel)
	}

	b, err := io.ReadAll(io.LimitReader(f, int64(maxRunOutput)+1))
	if err != nil {
		return proto.FileRead{}, fmt.Errorf("读取文件 %s: %w", filepath.Join(repo, cleaned), err)
	}
	out := proto.FileRead{Size: fi.Size()}
	if len(b) > maxRunOutput {
		log().Warn("文件超过读取上限，内容已截断", "repo", repo, "path", rel,
			"size", fi.Size(), "limit", maxRunOutput)

		out.Truncated = true
		b = b[:maxRunOutput]
	}
	out.Content = string(b)
	out.Binary = isBinaryPrefix(b)

	if !out.Binary && !out.Truncated {
		sum := sha256.Sum256(b)
		out.SHA256 = hex.EncodeToString(sum[:])
	}
	return out, nil
}

n_workspace_RemoveManagedWorktree.signature:
// RemoveManagedWorktree 删除 agentd 管理的 worktree（git -C repo worktree remove workdir）。
//
// 参数：
//   - ctx: 控制整组 git 调用的生命周期，内部再叠加 WorkspaceGitTimeout 作为兜底上限
//   - repo: 主仓库路径
//   - workdir: 待删除的 worktree 路径（必须为 Managed=true 的工作区）
//
// 返回：error 非 nil 表示重试耗尽仍未删掉；调用方按现状只 Warn 不阻断。
//
// 注意：
//   - 只删工作树不删分支（spec：任务分支保留供审阅/回滚）
//   - workdir 带未提交改动时 git 拒绝删除（错误带 stderr 原文返回）；是否降级
//     由调用方（Done 归档）决定——本函数不做清理性降级
//   - 失败会重试若干次，见 removeWorktreeAttempts 的注释
func RemoveManagedWorktree(ctx context.Context, repo, workdir string) error {
	ctx, cancel := context.WithTimeout(ctx, WorkspaceGitTimeout)
	defer cancel()
	log().Info("删除 managed worktree", "repo", repo, "workdir", workdir,
		"timeout", WorkspaceGitTimeout, "attempts", removeWorktreeAttempts)
	var lastStderr string
	var lastErr error
	for i := 1; i <= removeWorktreeAttempts; i++ {
		stderr, err := worktreeRemoveFn(ctx, repo, workdir)
		if err == nil {
			log().Info("managed worktree 已删除", "repo", repo, "workdir", workdir, "attempt", i)
			return nil
		}
		lastStderr, lastErr = stderr, err
		if i < removeWorktreeAttempts {

			log().Warn("删除 managed worktree 失败，稍后重试", "repo", repo, "workdir", workdir,
				"attempt", i, "of", removeWorktreeAttempts,
				"stderr", truncateRunes(stderr, 300), "cause", err)
			select {
			case <-ctx.Done():
				log().Error("删除 managed worktree 被取消", "repo", repo, "workdir", workdir,
					"attempt", i, "cause", ctx.Err())
				return fmt.Errorf("git worktree remove %s: %w", workdir, ctx.Err())
			case <-time.After(removeWorktreeBackoff):
			}
		}
	}
	log().Error("删除 managed worktree 失败（重试耗尽）", "repo", repo, "workdir", workdir,
		"attempts", removeWorktreeAttempts, "stderr", truncateRunes(lastStderr, 300), "cause", lastErr)
	return fmt.Errorf("git worktree remove %s: %s: %w", workdir, strings.TrimSpace(lastStderr), lastErr)
}

n_workspace_RemoveWorktree.signature:
// RemoveWorktree 删除一棵在册 worktree（git worktree remove [--force]）。
//
// 参数：ctx 上层上下文，内部叠加 WorkspaceGitTimeout；repo 主仓库路径；
// workdir 待删工作树路径；force 为真时对脏树强删（丢弃未提交改动）。
// 返回：git stderr 原文（成功为空串）与错误；调用方需要逐字段还原迁移前的
// 日志/文案时按 CloneRepo 同款约定自取 stderr。
func RemoveWorktree(ctx context.Context, repo, workdir string, force bool) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, WorkspaceGitTimeout)
	defer cancel()
	args := []string{"worktree", "remove", workdir}
	if force {
		args = append(args, "--force")
	}
	if _, stderr, err := gitRun(ctx, repo, args...); err != nil {
		return stderr, fmt.Errorf("git worktree remove %s: %s: %w",
			workdir, strings.TrimSpace(truncateRunes(stderr, 200)), err)
	}
	return "", nil
}

n_workspace_RenameEntry.signature:
// RenameEntry 给工作树内一个条目改名（B107 文件树右键菜单）。
//
// 参数：
//   - repo: 工作树绝对路径（调用方必须已过白名单闸门，本函数不做白名单判定）
//   - rel: 待改名条目的相对路径
//   - newName: 新名字（单层名，不得含 / 或 \——本期不做跨目录移动）
//
// 返回：
//   - proto.DirEntry: 改名后条目的信息（Name/IsDir/Size 取自磁盘实况）
//   - ErrBadEntryName: newName 非法（空 / . / .. / 含分隔符），或 rel 是工作树根
//   - ErrPathEscape: rel 逃逸出工作树（含符号链接逃逸）
//   - ErrGitDirWrite: 目标是 .git 下的条目
//   - ErrEntryNotFound: rel 不存在
//   - ErrEntryExists: 新名字已存在
func RenameEntry(repo, rel, newName string) (proto.DirEntry, error) {
	log().Info("改名工作树条目", "repo", repo, "path", rel, "new_name", newName)
	root, err := os.OpenRoot(repo)
	if err != nil {
		log().Warn("条目改名打开工作树失败", "repo", repo, "path", rel, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("打开工作树 %s: %w", repo, err)
	}
	defer root.Close()
	cleaned, err := cleanEntryRel(repo, rel)
	if err != nil {
		return proto.DirEntry{}, err
	}
	if cleaned == "" {
		log().Warn("条目改名目标是工作树根被拒绝", "repo", repo, "path", rel)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrBadEntryName, rel)
	}
	if err := validateEntryName(repo, newName); err != nil {
		return proto.DirEntry{}, err
	}
	if isGitPath(cleaned) {
		log().Warn("条目改名命中 .git 被拒绝", "repo", repo, "path", cleaned)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrGitDirWrite, cleaned)
	}
	target := filepath.Join(filepath.Dir(cleaned), newName)
	if isGitPath(target) {
		log().Warn("条目改名命中 .git 被拒绝", "repo", repo, "target", target)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrGitDirWrite, target)
	}
	if _, err := root.Stat(cleaned); err != nil {
		if rootErrIsEscape(err) {
			log().Warn("条目改名路径逃逸被拒绝", "repo", repo, "path", cleaned, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, cleaned)
		}
		if os.IsNotExist(err) {
			log().Warn("条目改名目标不存在", "repo", repo, "path", cleaned, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrEntryNotFound, cleaned)
		}
		log().Warn("条目改名检查目标失败", "repo", repo, "path", cleaned, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("检查条目 %s: %w", filepath.Join(repo, cleaned), err)
	}
	if _, err := root.Stat(target); err == nil {
		log().Warn("条目改名撞名被拒绝", "repo", repo, "path", cleaned, "target", target)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrEntryExists, target)
	} else if rootErrIsEscape(err) {
		log().Warn("条目改名路径逃逸被拒绝", "repo", repo, "path", target, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, target)
	}
	if err := root.Rename(cleaned, target); err != nil {
		if rootErrIsEscape(err) {
			log().Warn("条目改名路径逃逸被拒绝", "repo", repo, "path", target, "cause", err)
			return proto.DirEntry{}, fmt.Errorf("%w: %q", ErrPathEscape, target)
		}
		log().Warn("条目改名执行失败", "repo", repo, "path", cleaned, "target", target, "cause", err)
		return proto.DirEntry{}, fmt.Errorf("改名 %s → %s: %w", filepath.Join(repo, cleaned), filepath.Join(repo, target), err)
	}
	e, err := statEntry(root, repo, target)
	if err != nil {
		log().Warn("条目改名读取结果失败", "repo", repo, "path", target, "cause", err)
		return proto.DirEntry{}, err
	}
	log().Info("条目改名完成", "repo", repo, "path", cleaned, "new_path", target)
	return e, nil
}

n_workspace_ResolveBaseBranch.signature:
// ResolveBaseBranch 确定 diff 的默认基准分支，优先级：
//  1. 仓库远端默认分支（refs/remotes/origin/HEAD 符号引用，如 origin/main）
//  2. 本地 main
//  3. 本地 master
//  4. 都没有 → 空串（由路由层报错，提示协调者显式 --base）
//
// 为什么需要这个推导链：任务仓库的分支名不可预知（main/master/dev 皆可能）。
//
// 注意（B65 更正）：「派发时并未记录基准分支名」这句原文已经过时——B35 起任务
// 记录里有 BaseCommit。缺省基准现在由 DiffBaseFor 决定，本函数只负责
// **没有任务基线时**的推导，不再是 diff 的唯一入口。
func ResolveBaseBranch(repo string) string {
	if out, _, err := gitRun(context.Background(), repo, "symbolic-ref", "--short", "refs/remotes/origin/HEAD"); err == nil && strings.TrimSpace(out) != "" {
		return strings.TrimSpace(out)
	}
	for _, cand := range []string{"main", "master"} {

		if _, _, err := gitProbe(context.Background(), repo, "rev-parse", "--verify", "--quiet", cand); err == nil {
			return cand
		}
	}
	log().Warn("无法确定基准分支，diff 需要显式 base", "repo", repo)
	return ""
}

n_workspace_ResolveBaseline.signature:
// ResolveBaseline 决议任务的基线：校验协调者本地基线在任务仓库中可用，并给出
// 新分支应当使用的起点与「任务仓库比它多出多少提交」。
//
// 参数：
//   - ctx: 上层上下文；fetch 阶段内部叠加 FetchTimeout
//   - repo: 任务仓库路径
//   - sha: 协调者本地 HEAD 的 40 位十六进制提交号；空=未提供（--no-sync-check
//     或调用方 cwd 不是 git 仓库），此时起点退回任务仓库当前 HEAD
//
// 返回：
//   - Baseline: Start=新分支起点；Ahead=任务仓库 HEAD 领先 Start 的提交数
//   - ErrBadWorkspaceReq: sha 格式非法（会拼进 git 参数，不校验等于开注入面）
//   - ErrBaseCommitMissing: fetch 后仍缺失，错误文本含 sha、fetch stderr 与动作提示
//
// 注意：
//   - 空 sha 也返回一个具体的 Start：让「这个任务建在哪个提交上」在任何路径下
//     都答得出来，包括 --no-sync-check 那条——今天那条路上基线是纯粹的空白
//   - 「命中才不 fetch」是刻意设计：常态下远程并不落后，cat-file 是纯本地对象库
//     查询（微秒级），只有真落后时才付网络代价
//   - fetch 与随后对象检查处于同一按仓库互斥内；锁竞争耗尽单独归因，其他失败
//     保留 ErrBaseCommitMissing。锁只覆盖 fetch 与目标对象读取，不覆盖整个 dispatch。
func ResolveBaseline(ctx context.Context, repo, sha string) (Baseline, error) {
	if sha == "" {
		head := headCommit(ctx, repo)
		log().Info("未提供基线提交，起点退回任务仓库 HEAD", "repo", repo, "start", head)
		return Baseline{Start: head}, nil
	}
	if !IsCommitSHA(sha) {
		log().Warn("基线提交格式非法，拒绝派发", "repo", repo, "base_commit", truncateRunes(sha, 80))
		return Baseline{}, fmt.Errorf("%w: 基线提交必须是 40 位十六进制，实得 %q", ErrBadWorkspaceReq, truncateRunes(sha, 80))
	}
	fetched := false
	if !hasCommit(ctx, repo, sha) {
		log().Info("基线提交缺失，补拉远端", "repo", repo, "base_commit", sha, "timeout", FetchTimeout)
		err := withRepoFetchLock(repo, func() error {
			if hasCommit(ctx, repo, sha) {
				return nil
			}
			fetched = true
			_, stderr, ferr := runFetchWithRetry(ctx, repo, "fetch", "--all", "--prune")
			if ferr != nil {
				if errors.Is(ferr, ErrFetchRefLockContention) {
					log().Error("基线补拉因远端 ref 锁竞争耗尽", "repo", repo, "base_commit", sha,
						"stderr", truncateRunes(strings.TrimSpace(stderr), 500), "cause", ferr)
					return ferr
				}
				log().Error("补拉远端失败", "repo", repo, "base_commit", sha,
					"stderr", truncateRunes(strings.TrimSpace(stderr), 500), "cause", ferr)
			}
			if !hasCommit(ctx, repo, sha) {
				log().Warn("基线提交补拉后仍缺失，拒绝派发", "repo", repo, "base_commit", sha,
					"fetch_stderr", truncateRunes(strings.TrimSpace(stderr), 300))
				return fmt.Errorf("%w: %s（任务仓库 %s 落后于本地；fetch 输出：%s）；请先在本地 git push，或用 --no-sync-check 跳过校验",
					ErrBaseCommitMissing, sha, repo, strings.TrimSpace(truncateRunes(stderr, 300)))
			}
			log().Info("补拉远端后基线提交已就位", "repo", repo, "base_commit", sha)
			return nil
		})
		if err != nil {
			return Baseline{}, err
		}
	}
	bl := Baseline{Start: sha, Ahead: countAhead(ctx, repo, sha), Fetched: fetched}
	log().Info("基线决议完成", "repo", repo, "start", bl.Start, "ahead", bl.Ahead, "fetched", bl.Fetched)
	return bl, nil
}

n_workspace_ResolveDefaultBaseBranch.signature:
// ResolveDefaultBaseBranch 读取项目仓库记录的远端默认分支名。
//
// 参数：repo 为已通过 EnsureRepoUsable 的项目仓库路径。
// 返回：origin/HEAD 指向的分支名；没有该符号引用或引用形态异常时返回
// ErrBadWorkspaceReq 包装错误。
//
// 注意：这里只负责得到分支名，不在这里 fetch。调用方随后把分支名交给
// ResolveDispatchBase 的 D2 路径；这样卡派发与显式 --base 共用同一套远端
// 补拉和 SHA 落库逻辑，同时普通 CLI 的空 Base 仍留在 ResolveBaseline 的
// HEAD 语义上。
func ResolveDefaultBaseBranch(ctx context.Context, repo string) (string, error) {
	out, stderr, err := gitRun(ctx, repo, "symbolic-ref", "--short", "refs/remotes/origin/HEAD")
	ref := strings.TrimSpace(out)
	if err != nil || ref == "" {
		log().Warn("无法解析项目默认分支：origin/HEAD 不存在", "repo", repo,
			"stderr", truncateRunes(strings.TrimSpace(stderr), 300), "cause", err)
		return "", fmt.Errorf("%w: 无法解析项目默认分支：origin/HEAD 未设置（仓库 %s；git 输出：%s）",
			ErrBadWorkspaceReq, repo, strings.TrimSpace(truncateRunes(stderr, 300)))
	}
	const prefix = "origin/"
	if !strings.HasPrefix(ref, prefix) || strings.TrimPrefix(ref, prefix) == "" {
		log().Warn("无法解析项目默认分支：origin/HEAD 形态异常", "repo", repo, "ref", ref)
		return "", fmt.Errorf("%w: 无法解析项目默认分支：origin/HEAD 指向异常引用 %q",
			ErrBadWorkspaceReq, ref)
	}
	branch := strings.TrimPrefix(ref, prefix)
	log().Info("项目默认分支已解析", "repo", repo, "ref", ref, "branch", branch)
	return branch, nil
}

n_workspace_ResolveDispatchBase.signature:
// ResolveDispatchBase 按 --base 的形态选择旧 commit-ish 解析或 D2 分支补拉。
// localBaseBranch 为真时进入工作分支路径：允许在同一锁内探测 origin 同名分支，
// 但不得进入普通基线的 ResolveBaseBranch D2 路径。
// 返回值 fetched 供 manager 日志标记是否真的走过 origin fetch。
func ResolveDispatchBase(ctx context.Context, repo, rev string, localBaseBranch bool) (resolved string, fetched bool, err error) {
	if localBaseBranch {
		return resolveLocalBaseBranch(ctx, repo, rev)
	}
	if !needsBaseBranchSync(ctx, repo, rev) {
		resolved, err = resolveCommit(ctx, repo, rev)
		return resolved, false, err
	}
	resolved, err = resolveRemoteBaseBranch(ctx, repo, baseBranchRemote(ctx, repo, rev), rev)
	return resolved, true, err
}

n_workspace_ResolveProject.signature:
// ResolveProject 把派发请求里的项目引用解析成本机的位置行。
//
// 参数：
//   - projectID: 调用方算出的 project_id（优先）
//   - projectName: 人可读引用（仅 --project <名字> 与 Web 控制台会用）
//   - entries: 本机全部位置行
//
// 返回：
//   - 命中的位置行（Path 即 executor 的工作仓库）
//   - 错误：ErrProjectNotRegistered（查不到）或 ErrBadDispatchRequest（两者都空），
//     均映射 400，且报文自带本机已登记清单
//
// 注意：
//   - projectID 与 projectName 同时给出时以 projectID 为准：它是身份，名字只是引用
//   - 本函数不判断路径是否真的存在，那是 EnsureRepoUsable 的职责
func ResolveProject(projectID, projectName string, entries []proto.ProjectLocation) (proto.ProjectLocation, error) {
	switch {
	case projectID != "":
		for _, e := range entries {
			if e.ProjectID == projectID {
				log().Info("项目解析：project_id 命中", "project_id", projectID,
					"name", e.Name, "path", e.Path)
				return e, nil
			}
		}
		log().Warn("项目解析被拒：project_id 查不到", "project_id", projectID,
			"registered", locationLines(entries))
		return proto.ProjectLocation{}, fmt.Errorf(
			"%w: project_id=%s；本机已登记的项目：%s（用 handoff project add 落地它）",
			ErrProjectNotRegistered, projectID, locationLines(entries))
	case projectName != "":
		for _, e := range entries {
			if e.Name == projectName {
				log().Info("项目解析：名字命中", "name", projectName, "path", e.Path)
				return e, nil
			}
		}
		log().Warn("项目解析被拒：名字查不到", "name", projectName,
			"registered", locationLines(entries))
		return proto.ProjectLocation{}, fmt.Errorf(
			"%w: %q；本机已登记的项目：%s（用 handoff project ls 查看）",
			ErrProjectNotRegistered, projectName, locationLines(entries))
	default:
		log().Warn("项目解析被拒：请求未指明项目")
		return proto.ProjectLocation{}, fmt.Errorf(
			"%w: 请求未指明项目（project_id 与 project_name 至少其一）", ErrBadDispatchRequest)
	}
}

n_workspace_ResolveRunShell.signature:
// ResolveRunShell 解析 run 命令要用的 shell。
//
// 参数：
//   - goos: 平台标识（生产路径传 runtime.GOOS）
//   - lookPath: PATH 查找函数（生产路径传 exec.LookPath）
//   - stat: 文件存在性判定（生产路径传 statFile）
//
// 返回：
//   - shell 的路径或名字，可直接交给 exec.CommandContext
//   - error: 只在 Windows 上找不到任何 sh 时返回，文案指出装什么能修
//
// 为什么找不到时**硬失败**而不是降级到 cmd 或 PowerShell：那会让协调者写的
// unix 风格命令（管道、$(…)、&&）以难以理解的方式半跑，排障成本远高于一条
// 明确的「请装 Git for Windows」。
func ResolveRunShell(goos string, lookPath func(string) (string, error), stat func(string) error) (string, error) {
	if goos != "windows" {
		return "sh", nil
	}
	if p, err := lookPath("sh"); err == nil && p != "" {
		slog.Default().Info("run 的 shell 解析自 PATH", "sh", p)
		return p, nil
	}
	cands := RunShellCandidates(goos)
	for _, c := range cands {
		if err := stat(c); err == nil {
			slog.Default().Info("run 的 shell 解析自已知安装目录", "sh", c)
			return c, nil
		}
	}
	slog.Default().Error("找不到 sh，run 命令无法执行", "candidates", cands)
	return "", fmt.Errorf("找不到 sh：请在本机安装完整的 Git for Windows"+
		"（MinGit 不带 sh），已查找 PATH 与 %v", cands)
}

n_workspace_RestoreWorktree.signature:
// RestoreWorktree 把非 managed 工作树切回原 ref（git checkout <ref>）。
//
// 参数：ctx 控制本次 git 调用；workdir 工作树路径；ref 原 ref（分支名或 sha）。
// 返回：git stderr 原文（成功为空串）与错误；调用方需要逐字段还原迁移前的
// 日志/文案时按 CloneRepo 同款约定自取 stderr。
func RestoreWorktree(ctx context.Context, workdir, ref string) (string, error) {
	if _, stderr, err := gitRun(ctx, workdir, "checkout", ref); err != nil {
		return stderr, fmt.Errorf("git -C %s checkout %s: %s: %w", workdir, ref, strings.TrimSpace(stderr), err)
	}
	return "", nil
}

n_workspace_RunCmd.signature:
// RunCmd 在任务仓库内执行一条审阅命令（sh -c），合并 stdout+stderr 有界回收 1MB。
//
// 这是协调者主动发起的只读审阅动作（跑测试/lint），不走审批门——
// 命令语义（跑什么、看什么）由协调者决定，agentd 只负责执行与回收。
//
// 参数：
//   - ctx: 上层上下文（HTTP 请求取消会终止命令）
//   - repo: 命令工作目录（任务仓库）
//   - cmdline: shell 命令原文（sh -c 执行）
//
// 返回：
//   - stdout: 合并后的输出（超过 1MB 截断）
//   - exitCode: 命令退出码；超时被杀时返回 124（与 time 命令的约定一致）
//   - err: 超时返回 context 相关错误；启动失败返回 exec 错误。
//     命令非零退出**不**返回错误——exitCode 已表达结果，路由层据此返回 200
func RunCmd(ctx context.Context, repo, cmdline string) (stdout string, exitCode int, err error) {
	if procHeadroom != nil {
		if err := procHeadroom("run"); err != nil {
			return "", -1, err
		}
	}
	ctx, cancel := context.WithTimeout(ctx, RunCmdTimeout)
	defer cancel()

	if _, statErr := os.Stat(repo); statErr != nil {
		log().Warn("run 被拒：工作目录不存在", "repo", repo,
			"cmd", truncateRunes(cmdline, 200), "cause", statErr)
		return "", -1, fmt.Errorf("%w（managed worktree 可能已被 done/stop 回收）: %s",
			ErrWorkdirGone, repo)
	}
	sh, serr := gitproc.RunShell()
	if serr != nil {
		log().Error("run 命令的 shell 解析失败", "repo", repo, "cause", serr)
		return "", -1, serr
	}
	cmd := exec.CommandContext(ctx, sh, "-c", cmdline)
	cmd.Dir = repo

	gitproc.SetProcGroup(cmd)

	out := runOutputBuffer{limit: maxRunOutput}
	cmd.Stdout = &out
	cmd.Stderr = &out
	log().Info("run 命令执行", "repo", repo, "cmd", truncateRunes(cmdline, 200))
	start := time.Now()
	if err := cmd.Start(); err != nil {
		if note := quotaNote(err); note != "" {
			log().Error("run 命令启动失败（进程配额）", "repo", repo,
				"cmd", truncateRunes(cmdline, 200), "note", note, "cause", err)
			return "", -1, fmt.Errorf("%s: %w", note, err)
		}
		log().Error("run 命令启动失败", "repo", repo, "cmd", truncateRunes(cmdline, 200),
			"cause", err)
		return "", -1, err
	}

	cmdDone := make(chan struct{})
	go func() {
		select {
		case <-ctx.Done():
			select {
			case <-cmdDone:

				return
			default:

				gitproc.KillProcGroup(cmd.Process.Pid)
			}
		case <-cmdDone:

			return
		}
	}()
	err = cmd.Wait()
	close(cmdDone)
	elapsed := time.Since(start)

	switch {
	case err != nil && ctx.Err() != nil:

		exitCode = 124
		log().Error("run 命令超时被终止", "repo", repo, "cmd", truncateRunes(cmdline, 200),
			"timeout", RunCmdTimeout, "elapsed_ms", elapsed.Milliseconds())
	case err != nil:
		if ee, ok := err.(*exec.ExitError); ok {

			exitCode = ee.ExitCode()
			err = nil
			log().Info("run 命令执行完成", "repo", repo, "cmd", truncateRunes(cmdline, 200),
				"exit_code", exitCode, "elapsed_ms", elapsed.Milliseconds())
		} else {
			exitCode = -1
			log().Error("run 命令运行异常", "repo", repo, "cmd", truncateRunes(cmdline, 200),
				"stderr", truncateRunes(out.buf.String(), 500), "cause", err)
		}
	default:
		log().Info("run 命令执行完成", "repo", repo, "cmd", truncateRunes(cmdline, 200),
			"exit_code", 0, "elapsed_ms", elapsed.Milliseconds())
	}
	if out.capped {
		log().Warn("run 输出超过上限已截断", "repo", repo, "cmd", truncateRunes(cmdline, 200),
			"output_bytes", out.total, "limit", maxRunOutput)
	}
	return out.buf.String(), exitCode, err
}

n_workspace_RunShell.signature:
// RunShell 是 RunCmd 的调用入口，把生产依赖接上。
func RunShell() (string, error) {
	return ResolveRunShell(runtime.GOOS, exec.LookPath, statFile)
}

n_workspace_RunShellCandidates.signature:
// RunShellCandidates 返回本平台上 sh 的已知安装位置（绝对路径，按优先级）。
//
// 参数：goos 取 runtime.GOOS；抽成参数是为了让 Windows 分支在 mac/linux 上测得到。
//
// 返回：非 Windows 恒为空——那些平台上 sh 一定在 PATH 上，不需要兜底。
//
// 为什么必须有兜底：Git for Windows 的默认安装只把 Git\cmd 加进 PATH，而 sh.exe
// 住在 Git\bin，**默认不在 PATH 上**（真机实测）。只靠 LookPath 会在绝大多数正常
// 安装的机器上失败。这与 internal/pathenv 的「已知安装目录兜底」是同一个模式。
func RunShellCandidates(goos string) []string {
	if goos != "windows" {
		return nil
	}
	var out []string
	for _, env := range []string{"ProgramFiles", "ProgramFiles(x86)", "LOCALAPPDATA"} {
		root := os.Getenv(env)
		if root == "" {
			continue
		}
		if env == "LOCALAPPDATA" {
			out = append(out, filepath.Join(root, "Programs", "Git", "bin", "sh.exe"))
			continue
		}
		out = append(out, filepath.Join(root, "Git", "bin", "sh.exe"))
	}

	out = append(out, `C:\Program Files\Git\bin\sh.exe`, `C:\Program Files (x86)\Git\bin\sh.exe`)
	return dedupStrings(out)
}

n_workspace_SameLocation.signature:
// SameLocation 比较两个路径是否指向同一位置。
//
// 为什么不能直接比字符串：git 在 linked worktree 里返回的 common-dir 是
// 主仓 .git 的**符号链接解析后**绝对路径（macOS 上 /var → /private/var），
// 而首次登记存进表的路径来自调用方目录（未解析符号链接）。两个都解析再比，
// 才能让「linked worktree 归并后幂等命中」在 macOS 上成立。
//
// 路径已不存在时（EvalSymlinks 失败）退回直接比较 Clean 后的串。
func SameLocation(a, b string) bool {
	if ra, errA := filepath.EvalSymlinks(a); errA == nil {
		if rb, errB := filepath.EvalSymlinks(b); errB == nil {
			return ra == rb
		}
	}
	return filepath.Clean(a) == filepath.Clean(b)
}

n_workspace_SearchInDir.signature:
// SearchInDir 在工作树某个目录内全文搜索关键词，返回命中的行
// （B107 文件树右键菜单「在文件夹内查找」）。
//
// 参数：
//   - ctx: 控制搜索生命周期；内部叠加 searchTimeout 作为兜底上限
//   - repo: 工作树绝对路径（调用方必须已过白名单闸门，本函数不做白名单判定）
//   - rel: 搜索范围（相对工作树根的目录）；"" 与 "." 都表示整棵工作树
//   - query: 关键词，空串直接报错
//   - limit: 命中数上限；<=0 取 searchDefaultLimit，>searchMaxLimit 收敛到它
//
// 返回：
//   - proto.SearchResult：Hits 的 Rel 含 scope 前缀、Line 从 1 起、Text 是匹配
//     行原文（超过 searchHitTextMax 截断）；Truncated=true 表示撞到命中数上限
//     或超时，此时 Hits 是已扫到的部分结论——必须把「只看到这些」与「总共就
//     这些」分开，用户才知道要收窄范围
//   - ErrPathEscape: rel 逃逸出工作树（含符号链接逃逸）
//
// 路径遏制与 ReadFile/ListDir 同一红线：遍历经 os.OpenRoot 的内核级 jail
// （root.FS() 做 fs.WalkDir），不落回 filepath.Join(repo, rel) 后的包级 os
// 调用（理由见本文件 1543 行注释）。
//
// 三条护栏（每条的为什么见对应常量/变量注释）：
//   - 命中数：达 limit 立即停止并标 Truncated
//   - 超时：searchTimeout 到点带已有结果返回，不把超时当错误
//   - 跳过生成物：searchSkipDirs 命中的目录任意层级即跳整棵子树
func SearchInDir(ctx context.Context, repo, rel, query string, limit int) (proto.SearchResult, error) {
	scope, err := cleanEntryRel(repo, rel)
	if err != nil {
		return proto.SearchResult{}, err
	}
	if query == "" {
		log().Warn("搜索空关键词被拒绝", "repo", repo, "scope", scope)
		return proto.SearchResult{}, fmt.Errorf("空关键词")
	}
	if limit <= 0 {
		limit = searchDefaultLimit
	} else if limit > searchMaxLimit {
		limit = searchMaxLimit
	}
	root, err := os.OpenRoot(repo)
	if err != nil {
		return proto.SearchResult{}, fmt.Errorf("打开工作树 %s: %w", repo, err)
	}
	defer root.Close()

	ctx, cancel := context.WithTimeout(ctx, searchTimeout)
	defer cancel()
	walkRoot := scope
	if walkRoot == "" {
		walkRoot = "."
	}
	log().Info("文件夹内搜索开始", "repo", repo, "scope", scope, "query", query,
		"limit", limit, "timeout", searchTimeout)

	res := proto.SearchResult{Hits: []proto.SearchHit{}}
	start := time.Now()
	scanned := 0
	werr := fs.WalkDir(root.FS(), walkRoot, func(p string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if d.IsDir() {
			if searchSkipDirs[d.Name()] {
				log().Debug("搜索跳过目录", "repo", repo, "dir", p)
				return fs.SkipDir
			}
			return nil
		}
		scanned++
		if scanned%100 == 0 && ctx.Err() != nil {
			return errSearchStop
		}
		if !d.Type().IsRegular() {
			return nil
		}
		f, err := root.Open(p)
		if err != nil {
			return err
		}
		defer f.Close()
		head := make([]byte, searchBinaryProbe)
		n, _ := io.ReadFull(f, head)
		if bytes.IndexByte(head[:n], 0) >= 0 {
			return nil
		}
		if _, err := f.Seek(0, io.SeekStart); err != nil {
			return err
		}
		sc := bufio.NewScanner(f)
		sc.Buffer(make([]byte, 0, 64*1024), searchMaxLine)
		line := 0
		for sc.Scan() {
			line++
			text := sc.Text()
			if !strings.Contains(text, query) {
				continue
			}
			res.Hits = append(res.Hits, proto.SearchHit{
				Rel:	filepath.ToSlash(p),
				Line:	line,
				Text:	truncateRunes(text, searchHitTextMax),
			})
			if len(res.Hits) >= limit {
				return errSearchStop
			}
		}
		if err := sc.Err(); err != nil {

			log().Debug("搜索跳过超长行文件", "repo", repo, "path", p, "cause", err)
		}
		return nil
	})
	if werr != nil && !errors.Is(werr, errSearchStop) {
		log().Error("搜索遍历失败", "repo", repo, "scope", scope, "cause", werr)
		return proto.SearchResult{}, fmt.Errorf("搜索遍历 %s: %w", filepath.Join(repo, scope), werr)
	}
	if errors.Is(werr, errSearchStop) {
		res.Truncated = true
		if ctx.Err() != nil {
			log().Warn("搜索超时，返回已扫到的部分结果", "repo", repo, "scope", scope,
				"query", query, "hits", len(res.Hits), "scanned", scanned, "timeout", searchTimeout)
		} else {
			log().Info("搜索命中数达上限，返回部分结果", "repo", repo, "scope", scope,
				"query", query, "hits", len(res.Hits), "scanned", scanned, "limit", limit)
		}
	}
	log().Info("搜索完成", "repo", repo, "scope", scope, "query", query,
		"hits", len(res.Hits), "scanned", scanned, "elapsed_ms", time.Since(start).Milliseconds())
	return res, nil
}

n_workspace_SetForkFailureNote.signature:
// SetForkFailureNote 绑定 fork 失败文案函数（prochost.ExplainForkFailure）。
// fn 为 nil 时恢复默认「无文案」。只在组装点调用一次。
func SetForkFailureNote(fn func(error) (string, bool)) {
	if fn == nil {
		forkFailureNote = func(error) (string, bool) { return "", false }
		return
	}
	forkFailureNote = fn
}

n_workspace_SetProcGroup.signature:
// SetProcGroup 让命令进程成为新进程组组长（pgid = pid）。
//
// 为什么需要：RunCmd 经 sh -c 执行，命令可能拉起孙进程（管道/后台子 shell）；
// CommandContext 超时只杀 sh 本身，孙进程会成孤儿继续占用资源。设为组组长后，
// 超时可按组一次性回收全部后代。
func SetProcGroup(cmd *exec.Cmd) {
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
}

n_workspace_SetProcHeadroom.signature:
// SetProcHeadroom 绑定 run 的进程余量判读函数（agentd.CheckProcHeadroom）。
// fn 为 nil 时恢复默认「不判余量」。只在组装点调用一次。
func SetProcHeadroom(fn func(op string) error)	{ procHeadroom = fn }

n_workspace_TaskBranch.signature:
// TaskBranch 由任务 ID 派生自动分支名 handoff/<id8>。
func TaskBranch(taskID string) string {
	return TaskBranchPrefix + ID8(taskID)
}

n_workspace_TaskDiffTarget.signature:
// TaskDiffTarget 决定一个任务的 diff 该在哪个仓库、以什么为右端。
//
// 两种形态：
//   - 任务的 work_dir 还在 → 就用它，右端 HEAD（跑着的任务要看实时进度，
//     这条路径与此前逐字一致，不改行为）
//   - work_dir 已被回收（`handoff done` 会删掉 managed worktree）→ 回到
//     repo_path，右端用**任务分支**
//
// 为什么必须用分支而不是 HEAD：主仓库的 HEAD 是主线。拿它当右端，diff 出来的是
// 「主线相对基线」的全部历史，与这个任务无关——实测一个已归档任务因此吐 1002 个
// 文件。宁可报错也不能给出一份看似正常的错素材。
//
// 分支为空（老任务没记）时不回退：回退了也没有合法右端，让原来的错误原样暴露，
// 比拿主线冒充任务改动诚实。
func TaskDiffTarget(task *proto.Task) (repo, headRev string) {
	workdir := task.Workdir()
	if task.Branch == "" || workdir == task.RepoPath {
		return workdir, "HEAD"
	}
	if _, err := os.Stat(workdir); err == nil {
		return workdir, "HEAD"
	}
	log().Info("任务 worktree 已不在，diff 回退到主仓库 + 任务分支",
		"work_dir", workdir, "repo", task.RepoPath, "branch", task.Branch)
	return task.RepoPath, task.Branch
}

n_workspace_TopLevel.signature:
// TopLevel 探活目录所属工作树的根（git rev-parse --show-toplevel）。
//
// 参数：ctx 控制本次 git 调用；dir 任意目录。
// 返回：根路径与是否命中；失败返回 ("", false)（fail-open，供预览元数据降级）。
func TopLevel(ctx context.Context, dir string) (string, bool) {
	out, _, err := gitProbe(ctx, dir, "rev-parse", "--show-toplevel")
	if err != nil {
		return "", false
	}
	val := strings.TrimSpace(out)
	if val == "" {
		return "", false
	}
	return val, true
}

n_workspace_TruncatedNotice.signature:
// TruncatedNotice 生成附在截断内容末尾的醒目提示（含真实文件大小与上限）。
func TruncatedNotice(size int64) string {
	return fmt.Sprintf("\n\n===== 内容已截断：文件共 %d 字节，以上仅为开头 %d 字节 =====\n",
		size, maxRunOutput)
}

n_workspace_ValidatePreviewRelativePath.signature:
// ValidatePreviewRelativePath 校验请求 path 是 workspace root 之内的非空相对
// 路径，返回可安全用于静态服务与持久化的 slash 形式（gateway 的静态服务在
// Start 前复用同一校验）。
func ValidatePreviewRelativePath(root, raw string) (string, error) {
	if strings.TrimSpace(raw) == "" || filepath.IsAbs(raw) {
		return "", errors.New("path 必须是非空 workspace-relative 路径")
	}
	clean := filepath.Clean(raw)
	if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+filepathSeparator) {
		return "", errors.New("path 不得逃出 workspace root")
	}
	rootReal, err := filepath.EvalSymlinks(root)
	if err != nil {
		return "", fmt.Errorf("workspace root 不可用: %w", err)
	}
	targetReal, err := filepath.EvalSymlinks(filepath.Join(rootReal, clean))
	if err != nil {
		return "", fmt.Errorf("path 不存在或无法解析: %w", err)
	}
	rel, err := filepath.Rel(rootReal, targetReal)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+filepathSeparator) {
		return "", errors.New("path realpath 逃出 workspace root")
	}
	return filepath.ToSlash(rel), nil
}

n_workspace_ValidatePreviewViaSyntax.signature:
// ValidatePreviewViaSyntax 校验 session 级网络 allowlist 的每一项（gateway 的
// proxy 面与 owner 的 Create 共用同一套语法规则）。
func ValidatePreviewViaSyntax(via []string) error {
	for _, raw := range via {
		value := strings.TrimSpace(raw)
		if value == "" {
			return errors.New("不允许空值")
		}
		if strings.ContainsAny(value, "*?[](){}|^$\\") {
			return errors.New("只接受单个 IP、CIDR 或域名，不接受 wildcard/regex/path")
		}
		if net.ParseIP(value) != nil {
			continue
		}
		if _, _, err := net.ParseCIDR(value); err == nil {
			continue
		}
		if strings.Contains(value, ":") || strings.ContainsAny(value, "#% ") {
			return errors.New("不接受 host:port 或 URL")
		}
		if !previewDomainPattern.MatchString(value) {
			return errors.New("域名格式非法")
		}
	}
	return nil
}

n_workspace_ValidateProjectName.signature:
// ValidateProjectName 校验引用名的合法性，返回包装 ErrBadDispatchRequest 的错误。
//
// 规则：
//   - 空名或纯空白 → 拒
//   - 名字含 / \ : → 拒：clone 落点是 repo_root/<名字>，这三个字符会让它跑到别处
//   - 名字为 . / .. 或含 .. 路径段 → 拒：会让落点逃出 repo_root
//
// 为什么必须入口拦：名字由 origin 末段派生或人工指定，没人保证它干净；
// 而它会被直接拼进文件系统路径。
func ValidateProjectName(name string) error {
	if strings.TrimSpace(name) == "" {
		return fmt.Errorf("%w: 项目名不能为空", ErrBadDispatchRequest)
	}
	if strings.ContainsAny(name, `/\:`) {
		return fmt.Errorf("%w: 项目名 %q 含路径特征字符（/ \\ :），会让克隆落点跑到 repo_root 之外",
			ErrBadDispatchRequest, name)
	}
	for _, seg := range strings.FieldsFunc(name, func(r rune) bool { return r == '/' || r == '\\' }) {
		if seg == "." || seg == ".." {
			return fmt.Errorf("%w: 项目名 %q 含 . 或 .. 路径段，会让克隆落点逃出 repo_root",
				ErrBadDispatchRequest, name)
		}
	}
	return nil
}

n_workspace_WriteFile.signature:
// WriteFile 用新内容原子替换工作树内一个已存在的文本文件，带基线哈希前置条件。
//
// 冲突保护的整个机制就是这个前置条件：调用方把它**读到那一版**的 sha256 带回来，
// 本函数比对磁盘现状，不一致就拒绝并把现状带回去。为什么不用 mtime：executor 在
// 工作树里频繁跑 git 操作，checkout/rebase 会动 mtime 但不动内容，用 mtime 会把
// 大量无害情况报成冲突。
//
// **已知窗口，如实记录**：第 6 步读哈希与第 9 步 rename 之间不是原子的。executor
// 恰好在这个窗口里写同一个文件，本函数检测不到，结果是它的改动被覆盖。加锁解决
// 不了——锁只挡得住 agentd 自己的并发写，executor 直接动文件系统，根本不经过这里。
// 窗口从「整个编辑时长」缩到「一次读 + 一次 rename」，是这条路能拿到的全部。
//
// 参数：
//   - repo: 工作树绝对路径（调用方必须已过白名单闸门，本函数不做白名单判定）
//   - rel: 相对工作树根的路径
//   - content: 新内容
//   - baseSHA256: 调用方读到那一版的 sha256 十六进制串；空串一律判为不匹配
//
// 返回：
//   - err == nil：res 是**新内容**的结论（SHA256 可直接当下一次的基线，Size 是新大小）
//   - errors.Is(err, ErrBaseMismatch)：res 是**磁盘现状**（含正文与现状哈希），
//     给调用方省一次往返
//   - 其余错误：res 是零值
//   - 错误取值：ErrPathEscape / ErrGitDirWrite / ErrSymlinkTarget / ErrPathIsDir /
//     ErrNotRegularFile / ErrBinaryFile / ErrFileTooLarge / ErrBaseMismatch /
//     fs.ErrNotExist（含 %w 链）
func WriteFile(repo, rel, content, baseSHA256 string) (proto.FileRead, error) {
	cleaned := filepath.Clean(rel)
	if rel == "" || cleaned == "." || filepath.IsAbs(cleaned) ||
		cleaned == ".." || strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) {
		log().Warn("文件写入路径逃逸被拒绝", "repo", repo, "path", rel)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrPathEscape, rel)
	}
	if isGitPath(cleaned) {
		log().Warn("文件写入命中 .git 被拒绝", "repo", repo, "path", rel)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrGitDirWrite, rel)
	}

	if len(content) > maxRunOutput {
		log().Warn("写入内容超过上限被拒绝", "repo", repo, "path", rel,
			"bytes", len(content), "limit", maxRunOutput)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrFileTooLarge, rel)
	}
	root, err := os.OpenRoot(repo)
	if err != nil {
		return proto.FileRead{}, fmt.Errorf("打开工作树 %s: %w", repo, err)
	}
	defer root.Close()

	fi, err := root.Lstat(cleaned)
	if err != nil {
		if rootErrIsEscape(err) {
			log().Warn("文件写入路径逃逸被拒绝", "repo", repo, "path", rel)
			return proto.FileRead{}, fmt.Errorf("%w: %q", ErrPathEscape, rel)
		}
		return proto.FileRead{}, fmt.Errorf("检查文件 %s: %w", filepath.Join(repo, cleaned), err)
	}
	switch {
	case fi.Mode()&fs.ModeSymlink != 0:
		log().Warn("文件写入目标是符号链接被拒绝", "repo", repo, "path", rel)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrSymlinkTarget, rel)
	case fi.IsDir():
		log().Warn("文件写入目标是目录被拒绝", "repo", repo, "path", rel)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrPathIsDir, rel)
	case !fi.Mode().IsRegular():
		log().Warn("文件写入目标不是普通文件被拒绝", "repo", repo, "path", rel,
			"mode", fi.Mode().String())
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrNotRegularFile, rel)
	}

	cur, err := ReadFile(repo, cleaned)
	if err != nil {
		return proto.FileRead{}, err
	}

	if cur.Binary {
		log().Warn("文件写入目标是二进制被拒绝", "repo", repo, "path", rel)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrBinaryFile, rel)
	}
	if cur.Truncated {
		log().Warn("文件写入目标超过读取上限被拒绝", "repo", repo, "path", rel, "size", cur.Size)
		return proto.FileRead{}, fmt.Errorf("%w: %q", ErrFileTooLarge, rel)
	}
	if cur.SHA256 != baseSHA256 {
		log().Warn("文件写入基线不匹配", "repo", repo, "path", rel,
			"base", shortHash(baseSHA256), "current", shortHash(cur.SHA256))
		return cur, fmt.Errorf("%w: %q", ErrBaseMismatch, rel)
	}

	log().Info("开始原子替换文件", "repo", repo, "path", rel, "bytes", len(content))
	if err := atomicReplace(root, cleaned, []byte(content), fi.Mode().Perm()); err != nil {
		log().Error("文件写入失败", "repo", repo, "path", rel, "cause", err)
		return proto.FileRead{}, err
	}
	sum := sha256.Sum256([]byte(content))
	res := proto.FileRead{
		Content:	content,
		Size:		int64(len(content)),
		SHA256:		hex.EncodeToString(sum[:]),
	}
	log().Info("文件写入完成", "repo", repo, "path", rel,
		"bytes", res.Size, "sha256", shortHash(res.SHA256))
	return res, nil
}

n_workspace_ambiguousRemoteBranchError.signature:
// ambiguousRemoteBranchError 统一 B76 的多远端拒发文案，避免补拉路径与旧解析路径
// 对同一个安全问题给出两种说法。
func ambiguousRemoteBranchError(rev string, cands []string) error {
	return fmt.Errorf("%w: 起点 %s 在多个远端同时存在（%s）；"+
		"请改用带远端前缀的全名（如 --base upstream/%s）或直接给 40 位 sha",
		ErrBadWorkspaceReq, rev, strings.Join(cands, "、"), rev)
}

n_workspace_atomicReplace.signature:
// atomicReplace 用同目录临时文件 + rename 原子替换目标文件。
//
// 为什么做原子替换（而不是像 orca 那样对用户文件裸 WriteFile）：executor 就在
// 同一个工作树里跑，裸覆盖有一个窗口能让它读到半截文件。orca 的编辑对象通常
// 没有一个高频读者在旁边，我们有。
//
// 为什么**不** fsync：工作树在 git 管着，掉电丢一次编辑不是灾难，而每次保存
// fsync 的代价在远程机上更明显。orca 只对自己的状态文件做 fsync——那些丢了
// 没有第二份，工作树文件不是。
//
// 参数：
//   - root: 已打开的工作树 Root（全程不出根）
//   - cleaned: 目标文件的相对路径
//   - data: 新内容
//   - perm: 目标文件原有的权限位（保留可执行位，丢了是静默故障）
func atomicReplace(root *os.Root, cleaned string, data []byte, perm fs.FileMode) error {
	tmp := filepath.Join(filepath.Dir(cleaned),
		fmt.Sprintf(".%s.%d.%d.tmp", filepath.Base(cleaned), os.Getpid(), time.Now().UnixNano()))
	f, err := root.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, perm)
	if err != nil {
		return fmt.Errorf("创建临时文件 %s: %w", tmp, err)
	}

	committed := false
	defer func() {
		if !committed {
			_ = f.Close()
			if err := root.Remove(tmp); err != nil {
				log().Warn("清理临时文件失败", "tmp", tmp, "cause", err)
			}
		}
	}()
	if _, err := f.Write(data); err != nil {
		return fmt.Errorf("写临时文件 %s: %w", tmp, err)
	}
	if err := f.Close(); err != nil {
		return fmt.Errorf("关闭临时文件 %s: %w", tmp, err)
	}
	if err := root.Rename(tmp, cleaned); err != nil {
		return fmt.Errorf("替换文件 %s: %w", cleaned, err)
	}
	committed = true
	return nil
}

n_workspace_baseBranchRemote.signature:
// baseBranchRemote 为 D2 选择真正持有分支的远端：本地分支优先看其配置的
// branch.<name>.remote；本地没有时看唯一远程跟踪 ref；都无法确定时才回退 origin。
func baseBranchRemote(ctx context.Context, repo, branch string) string {
	if refExists(ctx, repo, "refs/heads/"+branch) {
		if out, _, err := gitProbe(ctx, repo, "config", "--get", "branch."+branch+".remote"); err == nil {
			if remote := strings.TrimSpace(out); remote != "" {
				return remote
			}
		}
		return "origin"
	}
	if cands := remoteBranchCandidates(ctx, repo, branch); len(cands) == 1 {
		if remote := remoteFromBranchCandidate(cands[0], branch); remote != "" {
			return remote
		}
	}
	return "origin"
}

n_workspace_canonPath.signature:
// canonPath 把路径归一到可比较的形态（穿透符号链接；目录已失时解析父目录拼回叶子名）。
func canonPath(p string) string {
	p = filepath.Clean(p)
	if r, err := filepath.EvalSymlinks(p); err == nil {
		return filepath.Clean(r)
	}
	if r, err := filepath.EvalSymlinks(filepath.Dir(p)); err == nil {
		return filepath.Join(r, filepath.Base(p))
	}
	return p
}

n_workspace_checkoutInWorktree.signature:
// checkoutInWorktree 在用户自带 worktree 内切分支（已存在 → checkout；新建/自动
// → checkout -b [base]），供 Worktree 模式复用。ctx 控制本次 git 调用的生命周期。
func checkoutInWorktree(ctx context.Context, workDir, branch, base string, isExisting bool) error {
	var args []string
	if isExisting {
		args = []string{"checkout", branch}
	} else {
		args = []string{"checkout", "-b", branch}
		if base != "" {
			args = append(args, base)
		}
	}
	if _, stderr, err := gitRun(ctx, workDir, args...); err != nil {
		return fmt.Errorf("git -C %s %v: %s: %w", workDir, args, strings.TrimSpace(stderr), err)
	}
	return nil
}

n_workspace_cleanEntryRel.signature:
// cleanEntryRel 归一化条目操作的目标相对路径并做词汇层逃逸检查。
//
// 与 ReadFile/WriteFile/ListDir 相同的第 1 道红线（Clean 后绝对路径或残留 ..
// 前缀一律拒绝，ErrPathEscape）；"." 归一成 ""（表示工作树根）。
//
// 参数：
//   - repo: 工作树绝对路径（供日志定位）
//   - rel: 待归一化的相对路径
//
// 返回：
//   - 归一化后的相对路径（"." 归为空串）
//   - ErrPathEscape: rel 逃逸出工作树
func cleanEntryRel(repo, rel string) (string, error) {
	cleaned := filepath.Clean(rel)
	if filepath.IsAbs(cleaned) || cleaned == ".." ||
		strings.HasPrefix(cleaned, ".."+string(filepath.Separator)) {
		log().Warn("条目操作路径逃逸被拒绝", "repo", repo, "path", rel)
		return "", fmt.Errorf("%w: %q", ErrPathEscape, rel)
	}
	if cleaned == "." {
		return "", nil
	}
	return cleaned, nil
}

n_workspace_copyEntryDir.signature:
// copyEntryDir 把 root 内的一个目录连同全部内容递归复制到目标路径。
//
// 为什么整段都在 root.FS() 上走：os.Root 的 FS 是相对根目录的文件系统视图，
// WalkDir 产出的每条路径（含根目录本身）都以 "/" 为分隔符、可以原样喂回 root
// 的 Open/Mkdir/Stat——从 src 到 dst 的目标相对路径也只在相对路径之间拼（Rel +
// Join），中途不得落回绝对路径，一旦把哪一段换成 filepath.Join(rootPath, rel)
// 就绕过了内核级 jail，这条红线的理由见本文件 1543 行注释。
func copyEntryDir(root *os.Root, repo, src, dst string) (entries, bytes int64, err error) {
	if err := root.Mkdir(dst, 0o755); err != nil {
		if rootErrIsEscape(err) {
			return 0, 0, fmt.Errorf("%w: %q", ErrPathEscape, dst)
		}
		return 0, 0, fmt.Errorf("建副本目录 %s: %w", filepath.Join(repo, dst), err)
	}
	entries = 1
	counted := 0
	werr := fs.WalkDir(root.FS(), src, func(p string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		counted++
		if counted%200 == 0 {
			log().Debug("目录复制进度", "repo", repo, "path", src, "visited", counted)
		}
		if p == src {
			return nil
		}
		relPart, err := filepath.Rel(src, p)
		if err != nil {
			return err
		}
		target := filepath.Join(dst, relPart)
		if d.IsDir() {
			if err := root.Mkdir(target, 0o755); err != nil {
				if rootErrIsEscape(err) {
					return fmt.Errorf("%w: %q", ErrPathEscape, target)
				}
				return fmt.Errorf("建副本目录 %s: %w", filepath.Join(repo, target), err)
			}
			entries++
			return nil
		}
		if !d.Type().IsRegular() {

			log().Warn("目录复制跳过非普通文件", "repo", repo, "path", p, "mode", d.Type().String())
			return nil
		}
		n, err := copyEntryFile(root, repo, p, target)
		if err != nil {
			return err
		}
		entries++
		bytes += n
		return nil
	})
	if werr != nil {
		return 0, 0, fmt.Errorf("递归复制 %s: %w", filepath.Join(repo, src), werr)
	}
	return entries, bytes, nil
}

n_workspace_copyEntryFile.signature:
// copyEntryFile 把 root 内的一个普通文件复制到目标路径（同为 root 内相对路径）。
//
// 权限用源文件的 Stat().Mode() 经 root.Chmod 补上——root.Create 只带 0o666 &
// umask，源文件的可执行位等权限位会丢，丢了是静默故障（与 atomicReplace 的
// perm 语义同款）。
func copyEntryFile(root *os.Root, repo, src, dst string) (bytes int64, err error) {
	sfi, err := root.Stat(src)
	if err != nil {
		if rootErrIsEscape(err) {
			return 0, fmt.Errorf("%w: %q", ErrPathEscape, src)
		}
		return 0, fmt.Errorf("读取源文件 %s: %w", filepath.Join(repo, src), err)
	}
	srcF, err := root.Open(src)
	if err != nil {
		if rootErrIsEscape(err) {
			return 0, fmt.Errorf("%w: %q", ErrPathEscape, src)
		}
		return 0, fmt.Errorf("打开源文件 %s: %w", filepath.Join(repo, src), err)
	}
	defer srcF.Close()
	dstF, err := root.Create(dst)
	if err != nil {
		if rootErrIsEscape(err) {
			return 0, fmt.Errorf("%w: %q", ErrPathEscape, dst)
		}
		return 0, fmt.Errorf("创建副本 %s: %w", filepath.Join(repo, dst), err)
	}
	defer dstF.Close()
	n, err := io.Copy(dstF, srcF)
	if err != nil {
		return 0, fmt.Errorf("复制 %s → %s: %w", filepath.Join(repo, src), filepath.Join(repo, dst), err)
	}
	if err := root.Chmod(dst, sfi.Mode().Perm()); err != nil {
		return 0, fmt.Errorf("补副本权限 %s: %w", filepath.Join(repo, dst), err)
	}
	return n, nil
}

n_workspace_copyEntryName.signature:
// copyEntryName 为源条目挑一个未被占用的副本名（B107 文件树右键菜单）。
//
// 命名规则（spec §3.4）：文件用 filepath.Ext 把 base 与扩展名拆开，候选依次是
// `base copy<ext>`、`base copy 2<ext>` …… 到 `base copy 99<ext>`；目录不拆扩展名，
// 整体当 base（如 `a.b` 目录 → `a.b copy`，与 Mac Finder 同款，拆了会得到
// `a copy.b` 这种错误形态）。isDir 决定是否拆。
//
// 为什么封顶 99：候选名是给人读的（Mac 文件系统的复制命名同款），无限试探只会
// 在「全被占用」的场景白白做几十上百次 Stat，且名字本身会越来越难读。封顶后
// 全部占用按 ErrEntryExists 拒掉，明确告诉用户手动清一清。
//
// 返回：目标名（与 source 同目录）与试过的候选数；root.Stat 出现逃逸以外的
// 意外错误时直接透传。
func copyEntryName(root *os.Root, repo, source string, isDir bool) (string, int, error) {
	base := filepath.Base(source)
	nameBase, ext := base, ""
	if !isDir {
		ext = filepath.Ext(base)
		if len(base) == len(ext) {
			ext = ""
		}
		if ext != "" {
			nameBase = base[:len(base)-len(ext)]
		}
	}
	for i := 1; i <= 99; i++ {
		var name string
		if i == 1 {
			name = nameBase + " copy" + ext
		} else {
			name = nameBase + fmt.Sprintf(" copy %d", i) + ext
		}
		target := filepath.Join(filepath.Dir(source), name)
		if _, err := root.Stat(target); err != nil {
			if rootErrIsEscape(err) {
				log().Warn("条目复制命名探测逃逸被拒绝", "repo", repo, "path", source, "candidate", target, "cause", err)
				return "", i, fmt.Errorf("%w: %q", ErrPathEscape, target)
			}
			if os.IsNotExist(err) {
				return target, i, nil
			}
			log().Warn("条目复制命名探测失败", "repo", repo, "path", source, "candidate", target, "cause", err)
			return "", i, fmt.Errorf("探测副本名 %s: %w", filepath.Join(repo, target), err)
		}
	}
	log().Warn("条目复制候选名全部被占用", "repo", repo, "path", source)
	return "", 99, fmt.Errorf("%w: %q 的副本名到 copy 99 已全被占用", ErrEntryExists, source)
}

n_workspace_countAhead.signature:
// countAhead 数任务仓库 HEAD 上有、而 start 上没有的提交数。
//
// 数不出来时返回 0 并打 Warn：这是给人看的提示数字，不该因为数不出来就把
// 整次派发拒掉——起点本身已经校验过了，提示缺失不影响正确性。
func countAhead(ctx context.Context, repo, start string) int {
	out, _, err := gitRun(ctx, repo, "rev-list", "--count", start+"..HEAD")
	if err != nil {
		log().Warn("统计任务仓库领先提交数失败，按 0 处理", "repo", repo, "start", start, "cause", err)
		return 0
	}
	n, err := strconv.Atoi(strings.TrimSpace(out))
	if err != nil {
		log().Warn("领先提交数解析失败，按 0 处理", "repo", repo,
			"out", truncateRunes(out, 80), "cause", err)
		return 0
	}
	return n
}

n_workspace_currentRef.signature:
// currentRef 取工作树当前 HEAD 的**可复原引用**：正常在分支上时返回分支名，
// detached 时返回 commit sha。两种形态都能直接喂给 git checkout。
//
// 参数：dir 为工作树路径（原地模式即主仓库）
//
// 返回：引用字符串；取不到时返回空串
//
// 注意：
//   - 返回空串**不是错误**，调用方按「不知道该切回哪儿」处置。采集失败不该
//     挡住派发，但也绝不能拿一个猜测值去 checkout——乱切比不切更糟
func currentRef(ctx context.Context, dir string) string {

	if out, _, err := gitRun(ctx, dir, "symbolic-ref", "--short", "-q", "HEAD"); err == nil {
		if ref := strings.TrimSpace(out); ref != "" {
			return ref
		}
	}
	out, _, err := gitRun(ctx, dir, "rev-parse", "HEAD")
	if err != nil {
		log().Warn("采集原 ref 失败，补偿将无法复原工作树", "dir", dir, "cause", err)
		return ""
	}
	return strings.TrimSpace(out)
}

n_workspace_dedupStrings.signature:
// dedupStrings 按首次出现顺序去重。
func dedupStrings(in []string) []string {
	seen := make(map[string]bool, len(in))
	out := in[:0:0]
	for _, s := range in {
		if seen[s] {
			continue
		}
		seen[s] = true
		out = append(out, s)
	}
	return out
}

n_workspace_defaultPreviewWorkspaceResol.signature:
func defaultPreviewWorkspaceResolver(ctx context.Context, getwd func() (string, error)) (string, string, string, error) {
	workspaceRoot, err := getwd()
	if err != nil {
		return "", "", "", fmt.Errorf("取得工作目录: %w", err)
	}
	workspaceRoot, err = filepath.EvalSymlinks(workspaceRoot)
	if err != nil {
		return "", "", "", fmt.Errorf("解析工作目录: %w", err)
	}
	if root, ok := TopLevel(ctx, workspaceRoot); ok {
		if realRoot, realErr := filepath.EvalSymlinks(root); realErr == nil {
			workspaceRoot = realRoot
		} else {
			log().Warn("预览工作区根目录归一化失败，保留当前目录", "workspace", workspaceRoot, "git_root", root, "cause", realErr)
		}
	}

	var originURL string
	if u, ok := ProbeOriginURL(ctx, workspaceRoot); ok {
		originURL = u
	}
	branch := HeadBranch(ctx, workspaceRoot)
	log().Info("预览工作区元数据读取成功", "operation", "preview_workspace", "workspace", workspaceRoot, "origin_url", originURL, "branch", branch)
	return workspaceRoot, originURL, branch, nil
}

n_workspace_ensureCleanWorktree.signature:
// ensureCleanWorktree 校验工作区干净（status --porcelain 无任何输出）。
// 脏检测含未跟踪文件：未跟踪文件同样可能被执行器误 add 进任务提交，保守拒绝。
// git status 失败（仓库不存在/不是 git 仓库）与「脏」是两种可修复场景，
// 用 ErrRepoUnusable 区分（server 层据此给调用方可读的 400 而非扁平 500）。
// ctx 控制本次 git 调用的生命周期。
func ensureCleanWorktree(ctx context.Context, dir string) error {
	status, _, err := gitRun(ctx, dir, "status", "--porcelain")
	if err != nil {
		return fmt.Errorf("%w: git status: %v", ErrRepoUnusable, err)
	}
	if strings.TrimSpace(status) != "" {
		first := firstLine(status)
		log().Warn("工作区不干净，拒绝派发", "dir", dir, "status", truncateRunes(first, 200))
		return fmt.Errorf("%w: %s", ErrDirtyWorktree, first)
	}
	return nil
}

n_workspace_firstLine.signature:
// firstLine 取多行文本的第一行（日志摘要用）。
func firstLine(s string) string {
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		return s[:i]
	}
	return s
}

n_workspace_gitCapability_CreateManual.signature:
func (gitCapability) CreateManual(ctx context.Context, repo, worktreesDir string, req ManualReq) (ManualTree, error) {

	ws, err := CreateManualWorktree(ctx, repo, worktreesDir, proto.CreateWorktreeReq{
		Mode:	req.Mode, Branch: req.Branch, Base: req.Base,
	})
	if err != nil {
		return ManualTree{}, err
	}
	return ManualTree{Path: ws.Path, Branch: ws.Branch, Head: ws.Head, Managed: ws.Managed}, nil
}

n_workspace_gitCapability_DiffRange.signature:
func (gitCapability) DiffRange(ctx context.Context, repo, base, head string) (string, error) {
	if err := ctx.Err(); err != nil {
		return "", err
	}
	return DiffRange(repo, base, head)
}

n_workspace_gitCapability_EnsureRepoUsab.signature:
func (gitCapability) EnsureRepoUsable(ctx context.Context, repo string) error {
	return EnsureRepoUsable(ctx, repo)
}

n_workspace_gitCapability_Prepare.signature:
func (gitCapability) Prepare(ctx context.Context, req PrepareReq) (Prepared, error) {
	ws, err := PrepareWorkspace(ctx, WorkspaceReq{
		Repo:	req.Repo, TaskID: req.TaskID, Branch: req.Branch, NewBranch: req.NewBranch,
		Base:	req.Base, Worktree: req.Worktree, NewWorktree: req.NewWorktree, WorktreesDir: req.WorktreesDir,
	})
	if err != nil {
		return Prepared{}, err
	}
	return Prepared{
		Branch:	ws.Branch, WorkDir: ws.WorkDir, Managed: ws.Managed,
		NewBranchTip:	ws.NewBranchTip, PrevRef: ws.PrevRef,
		RepoDirtyCount:	ws.RepoDirtyCount, RepoDirtyFiles: ws.RepoDirtyFiles,
	}, nil
}

n_workspace_gitCapability_ReadFile.signature:
func (gitCapability) ReadFile(ctx context.Context, repo, rel string) (FileContent, error) {
	if err := ctx.Err(); err != nil {
		return FileContent{}, err
	}
	f, err := ReadFile(repo, rel)
	if err != nil {
		return FileContent{}, err
	}
	return FileContent{Content: f.Content, Size: f.Size, Truncated: f.Truncated, Binary: f.Binary, SHA256: f.SHA256}, nil
}

n_workspace_gitCapability_RecycleManaged.signature:
func (gitCapability) RecycleManaged(ctx context.Context, repo, workdir string) error {
	return RemoveManagedWorktree(ctx, repo, workdir)
}

n_workspace_gitCapability_ResolveBaselin.signature:
func (gitCapability) ResolveBaseline(ctx context.Context, repo, sha string) (Baseline, error) {
	return ResolveBaseline(ctx, repo, sha)
}

n_workspace_gitExec.signature:
// gitExec 是 gitRun / gitProbe 的公共体：执行 git -C repo <args...>，并在命令行层
// 强制使用本次调用的空 hooks 目录。这样即使仓库配置被执行者改写，agentd 自己的 git
// 也不会执行仓库 hooks；临时目录在单次调用结束后回收。
//
// quiet 只影响**失败时的日志级别**：false 记 Error（真故障），true 记 Debug
// （预期内的探测未命中）。返回值语义与 quiet 无关。
func gitExec(ctx context.Context, repo string, quiet bool, args ...string) (stdout, stderr string, err error) {
	log().Info("git 调用", "repo", repo, "args", args)
	start := time.Now()
	hooksPath, err := os.MkdirTemp("", "handoff-empty-hooks-")
	if err != nil {
		log().Error("创建 git hooks 隔离目录失败", "repo", repo, "args", args, "cause", err)
		return "", "", fmt.Errorf("创建 git hooks 隔离目录: %w", err)
	}
	log().Debug("git hooks 已隔离", "repo", repo, "args", args, "hooks_path", hooksPath)
	defer func() {
		if removeErr := os.RemoveAll(hooksPath); removeErr != nil {
			log().Warn("回收 git hooks 隔离目录失败", "repo", repo, "args", args,
				"hooks_path", hooksPath, "cause", removeErr)
		}
	}()

	cmdArgs := append([]string{"-C", repo, "-c", "core.hooksPath=" + hooksPath}, args...)
	cmd := exec.CommandContext(ctx, "git", cmdArgs...)
	var outBuf, errBuf bytes.Buffer
	cmd.Stdout = &outBuf
	cmd.Stderr = &errBuf
	err = cmd.Run()
	log().Info("git 调用完成", "repo", repo, "args", args,
		"elapsed_ms", time.Since(start).Milliseconds())
	if err != nil {
		if note := quotaNote(err); note != "" {
			log().Error("git 调用失败（进程配额）", "repo", repo, "args", args,
				"note", note, "cause", err)
			return outBuf.String(), errBuf.String(), fmt.Errorf("%s: %w", note, err)
		}
		if quiet {
			log().Debug("git 探测未命中（预期内）", "repo", repo, "args", args,
				"stderr", truncateRunes(errBuf.String(), 500), "cause", err)
		} else {
			log().Error("git 调用失败", "repo", repo, "args", args,
				"stderr", truncateRunes(errBuf.String(), 500), "cause", err)
		}
	}
	return outBuf.String(), errBuf.String(), err
}

n_workspace_gitNetArgs.signature:
// gitNetArgs 在 git 参数前插入代理参数。
//
// 代理参数必须排在子命令**之前**：git 的 -c 是全局选项，放到子命令后面
// git 会把它当成子命令的参数并直接报错。
func gitNetArgs(args ...string) []string {
	p := gitNet.Argv
	if len(p) == 0 {
		return args
	}
	return append(p, args...)
}

n_workspace_gitProbe.signature:
// gitProbe 与 gitRun 相同，但把**非零退出**当成预期内的探测结果而非故障：
// 失败记 Debug 不记 Error。返回值语义完全不变（调用方仍按 err != nil 判未命中）。
//
// 为什么需要它（B81）：探测型调用（rev-parse --verify --quiet、cat-file -e）的
// 非零退出是**正常分支**——远程执行机只 fetch 出 origin/<name>、从不建本地分支，
// 所以「本地同名分支不存在」是常态。经 gitRun 打成 ERROR 后，成功路径的日志里
// 躺着 ERROR，与真故障无法区分；按 level=ERROR 过滤日志会捞出正常路径。
//
// 边界：只用于「失败是预期内结果」的调用。会真正出事的 git 调用仍走 gitRun。
// 进程配额失败无论走哪个入口都仍是 Error。
func gitProbe(ctx context.Context, repo string, args ...string) (stdout, stderr string, err error) {
	return gitExec(ctx, repo, true, args...)
}

n_workspace_gitRun.signature:
// gitRun 执行 git -C repo <args...>，返回 stdout 与 stderr。
//
// 日志：调用前 Info（repo、args）、调用后 Info（耗时）；失败 Error 带 stderr
// 原文——git 报错原文是排障必需品，不能只留包装后的 error 文本。
//
// 用于**失败即故障**的调用（clone / fetch / worktree add / diff / log 等）。
// 失败是预期内结果的探测型调用请用 gitProbe。
func gitRun(ctx context.Context, repo string, args ...string) (stdout, stderr string, err error) {
	return gitExec(ctx, repo, false, args...)
}

n_workspace_gitRunNet.signature:
// gitRunNet 执行**会出网**的 git 操作（clone / fetch），自动带上代理参数。
//
// 参数与返回同 gitRun。
//
// 注意：
//   - 只有 clone 与 fetch 该用它。给本地操作用不会出错，但会让「哪些操作出网」
//     这个信息从代码里消失，下一个人就无从判断代理配错会影响哪些功能
//   - git 的 http.proxy 对 ssh:// 与 git@host:path 的 remote **无效**。
//     SSH remote 要走代理得配 ssh 的 ProxyCommand，那会动到用户的 ssh 配置面，
//     不在 handoff 职责内；README 给出改用 HTTPS remote（insteadOf）的解法
func gitRunNet(ctx context.Context, repo string, args ...string) (stdout, stderr string, err error) {
	if len(gitNet.Argv) > 0 {
		log().Info("git 出网操作将走代理", "repo", repo, "args", args,
			"proxy", gitNet.Redact)
	}
	return gitRun(ctx, repo, gitNetArgs(args...)...)
}

n_workspace_hasCommit.signature:
// hasCommit 判断 sha 是否已在 repo 的对象库中（^{commit} 保证它确实是提交对象，
// 而不是同名的 tree/blob）。
func hasCommit(ctx context.Context, repo, sha string) bool {
	_, _, err := gitProbe(ctx, repo, "cat-file", "-e", sha+"^{commit}")
	return err == nil
}

n_workspace_headCommit.signature:
// headCommit 取仓库当前 HEAD 的完整 sha。
//
// 返回空串只对应「仓库一个提交都没有」：仓库有效性已由 Dispatch 前置的
// EnsureRepoUsable 保证（B45），走到这里时路径一定是可用的 git 仓库。
// 空起点交给 git 默认行为，不是错误。
func headCommit(ctx context.Context, repo string) string {
	out, _, err := gitRun(ctx, repo, "rev-parse", "HEAD")
	if err != nil {
		log().Info("任务仓库没有 HEAD（空仓库或非 git 仓库），起点留空", "repo", repo)
		return ""
	}
	return strings.TrimSpace(out)
}

n_workspace_isAncestor.signature:
// isAncestor 检查 ancestor 是否为 descendant 的祖先。两边都不是祖先时由调用
// 方视为分叉；输入来自已成功读取的提交 ref，因此非零只代表不是祖先关系。
func isAncestor(ctx context.Context, repo, ancestor, descendant string) bool {
	_, _, err := gitProbe(ctx, repo, "merge-base", "--is-ancestor", ancestor, descendant)
	return err == nil
}

n_workspace_isBinaryPrefix.signature:
// isBinaryPrefix 判定一段内容的开头是否含 NUL 字节。
//
// 参数：
//   - b: 已读到的内容（可能已被 maxRunOutput 截断）
//
// 返回：前 min(len(b), 8192) 字节内出现 0x00 为真
func isBinaryPrefix(b []byte) bool {
	if len(b) > binaryProbeBytes {
		b = b[:binaryProbeBytes]
	}
	return bytes.IndexByte(b, 0) >= 0
}

n_workspace_isFetchRefLockFailure.signature:
// isFetchRefLockFailure 识别 git 在远端跟踪 ref 上的锁竞争；只对该类错误
// 重试，避免把认证、网络或真正缺失分支的失败延迟后再报。
func isFetchRefLockFailure(stderr string) bool {
	return strings.Contains(stderr, "cannot lock ref")
}

n_workspace_isGitPath.signature:
// isGitPath 判定一个已 Clean 的相对路径是否落在工作树根的 .git 下。
//
// 为什么要挡：`.git` 在 worktree 里是个几十字节的指针文件（内容 `gitdir: <路径>`），
// 改它能把整个工作树重指向别处；在主仓库里 `.git/config` 写进 core.pager /
// core.sshCommand / hooksPath，就是下一次任何 git 操作时的任意命令执行，改 HEAD、
// 删 index 也都能直接搞坏仓库。
//
// 这不是提权（控制台会话本来就与主令牌等价，见 spec §1.1），是「一次误操作就把
// 仓库弄坏」——正是那条参数校验闸门该挡的东西。
//
// 只挡工作树**根下**的 .git：嵌套子模块不在本期范围。前缀相同的 .gitignore /
// .gitattributes 不受影响。
//
// 参数：
//   - cleaned: 已经 filepath.Clean 过的相对路径
func isGitPath(cleaned string) bool {
	return cleaned == ".git" || strings.HasPrefix(cleaned, ".git"+string(filepath.Separator))
}

n_workspace_locationLines.signature:
// locationLines 把位置表压成「名字 → 路径」的一行串，供拒绝报文使用。
//
// 报文必须带得走「本机登记了什么」——远程派发时协调者读不到执行机的
// agentd.log，一句干巴巴的「未登记」等于让他去猜。
func locationLines(entries []proto.ProjectLocation) string {
	if len(entries) == 0 {
		return "（本机尚无任何项目）"
	}
	lines := make([]string, 0, len(entries))
	for _, e := range entries {
		lines = append(lines, e.Name+" → "+e.Path)
	}
	return strings.Join(lines, "; ")
}

n_workspace_manualDirName.signature:
// manualDirName 把分支名转成目录名：'/' 换 '-'，其余原样。
//
// 分支名此前已过 git check-ref-format，不含空格与控制字符，所以这一步只需处理
// 层级分隔符。副作用是 feat/x 与 feat-x 会撞同一个目录名——撞了直接拒（调用方
// 的落点存在性检查），不自动加后缀：自动改名会让人以为建在了他以为的位置。
func manualDirName(branch string) string {
	return strings.ReplaceAll(branch, "/", "-")
}

n_workspace_mergeTree.signature:
// mergeTree 把一台远程机器的单机树并进汇总结果。
//
// 合并键是 project_id——它是同一个纯函数从同一个 origin 算出的，跨机天然相等，
// **不需要任何协商**。同一项目在不同机器上的 location 因此排在一起。
func mergeTree(dst *proto.ProjectTreeResp, machine string, src proto.ProjectTreeResp) {
	idx := map[string]int{}
	for i, p := range dst.Projects {
		idx[p.ProjectID] = i
	}
	for _, p := range src.Projects {
		for i := range p.Locations {

			p.Locations[i].Machine = machine
		}
		if i, ok := idx[p.ProjectID]; ok {
			dst.Projects[i].Locations = append(dst.Projects[i].Locations, p.Locations...)
			continue
		}
		idx[p.ProjectID] = len(dst.Projects)
		dst.Projects = append(dst.Projects, p)
	}
	dst.Unowned = append(dst.Unowned, src.Unowned...)
}

n_workspace_needsBaseBranchSync.signature:
// needsBaseBranchSync 判定 req.Base 是否要走 D2 的远端补拉路径。
//
// 只有「普通分支名」才补拉：短 sha、tag、显式 ref、远端全名与其他可直接由
// resolveCommit 处理的 commit-ish 继续走老路。无本地 heads、但只有一棵远程跟踪
// 分支时仍然补拉；这是执行机镜像陈旧的核心场景。无本地 heads 且多棵远端同名时
// 刻意返回 false，让 resolveCommit 的 B76 歧义拒发继续生效，而不是静默挑 origin。
func needsBaseBranchSync(ctx context.Context, repo, rev string) bool {
	if strings.HasPrefix(rev, "refs/") || strings.HasPrefix(rev, "HEAD") || remoteQualifiedBase(ctx, repo, rev) {
		return false
	}
	localHead := refExists(ctx, repo, "refs/heads/"+rev)
	if localHead {
		return true
	}
	if commitishRe.MatchString(rev) {
		return false
	}
	if refExists(ctx, repo, "refs/tags/"+rev) {
		return false
	}
	cands := remoteBranchCandidates(ctx, repo, rev)
	if !localHead && len(cands) > 1 {
		return false
	}
	if localHead || len(cands) == 1 {
		return true
	}

	if _, _, err := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", rev+"^{commit}"); err == nil {
		return false
	}
	return true
}

n_workspace_parsePorcelainStatus.signature:
// parsePorcelainStatus 解析 git status --porcelain 的输出为脏文件清单。
//
// 参数：out 为 porcelain 原文，每行形如 "XY 路径"（XY 为两字符状态码）。
// 返回：脏条目清单；输出为空表示工作树干净。
//
// 注意：重命名行形如 "R  old -> new"，这里整段留在 Path 里不再拆。
func parsePorcelainStatus(out string) []proto.DirtyFile {
	var files []proto.DirtyFile
	for _, line := range strings.Split(out, "\n") {
		line = strings.TrimRight(line, "\r")
		if len(line) < 4 {
			continue
		}
		files = append(files, proto.DirtyFile{
			Status:	line[:2],
			Path:	strings.TrimSpace(line[3:]),
		})
	}
	return files
}

n_workspace_parseWorktreeList.signature:
// parseWorktreeList 解析 git worktree list --porcelain 的输出。
//
// 参数：out 为 porcelain 原文。记录之间以空行分隔，每条以 "worktree <路径>" 开头，
// 可选属性行含 HEAD / branch / bare / detached / locked / prunable。
//
// 返回：以 git 报的**原始**路径为键的条目表。路径归一交给 FindWorktree，
// 解析函数保持纯粹以便用固定文本测试。
func parseWorktreeList(out string) map[string]WorktreeEntry {
	entries := make(map[string]WorktreeEntry)
	var cur WorktreeEntry
	flush := func() {
		if cur.Path != "" {
			entries[cur.Path] = cur
		}
		cur = WorktreeEntry{}
	}
	for _, line := range strings.Split(out, "\n") {
		line = strings.TrimRight(line, "\r")
		switch {
		case line == "":
			flush()
		case strings.HasPrefix(line, "worktree "):
			flush()
			cur.Path = strings.TrimPrefix(line, "worktree ")
		case line == "prunable" || strings.HasPrefix(line, "prunable "):
			cur.Prunable = true
			cur.PruneReason = strings.TrimSpace(strings.TrimPrefix(line, "prunable"))
		}
	}
	flush()
	return entries
}

n_workspace_parseWorktreePorcelain.signature:
// parseWorktreePorcelain 解析 git worktree list --porcelain 的输出。
//
// 输出形态（每块之间空行分隔，第一块恒为主工作树）：
//
//	worktree /path
//	HEAD <40 位 sha>
//	branch refs/heads/main      ← detached 时这一行换成 detached
//
// 返回的切片永不为 nil。
func parseWorktreePorcelain(out, managedRoot string) []proto.Workspace {
	list := []proto.Workspace{}
	var cur *proto.Workspace
	flush := func() {
		if cur != nil {
			cur.IsMain = len(list) == 0
			cur.Managed = underRoot(cur.Path, managedRoot)
			list = append(list, *cur)
			cur = nil
		}
	}
	for _, line := range strings.Split(out, "\n") {
		line = strings.TrimSpace(line)
		switch {
		case line == "":
			flush()
		case strings.HasPrefix(line, "worktree "):
			flush()
			cur = &proto.Workspace{Path: strings.TrimPrefix(line, "worktree ")}
		case cur == nil:

		case strings.HasPrefix(line, "HEAD "):
			sha := strings.TrimPrefix(line, "HEAD ")
			if len(sha) > headShortLen {
				sha = sha[:headShortLen]
			}
			cur.Head = sha
		case strings.HasPrefix(line, "branch "):
			cur.Branch = strings.TrimPrefix(strings.TrimPrefix(line, "branch "), "refs/heads/")
		case line == "detached":

			cur.Branch = ""
		}
	}
	flush()
	return list
}

n_workspace_probePreviewPort.signature:
func probePreviewPort(ctx context.Context, port int) error {
	dialCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	conn, err := (&net.Dialer{}).DialContext(dialCtx, "tcp", fmt.Sprintf("127.0.0.1:%d", port))
	if err != nil {
		return err
	}
	return conn.Close()
}

n_workspace_quotaNote.signature:
// quotaNote 把一次进程创建失败翻译成归因文案；与配额无关时返回空串。
//
// 为什么包一层而不是四处直接调用注入的 forkFailureNote：归因文案要同时进日志
// 和进返回给协调者的 error，收在一处才不会两边写法漂移。
func quotaNote(err error) string {
	note, _ := forkFailureNote(err)
	return note
}

n_workspace_readBackWorktree.signature:
// readBackWorktree 回读刚建出来的树，返回与项目树同口径的 proto.Workspace。
//
// 路径比对走 canonPath：macOS 上 /var → /private/var 是实景，直接字符串比会
// 一个都对不上。挑不到时退回手工组装的最小值并 Warn——树已经建成了，不能因为
// 回读没赶上（并发被删、探测超时）就把一次成功报成失败。
func readBackWorktree(ctx context.Context, repo, managedRoot, dir, branch string) proto.Workspace {
	list, probeErr := ProbeWorkspaces(ctx, repo, managedRoot)
	if probeErr != "" {
		log().Warn("建树后回读探测失败，返回最小信息", "dir", dir, "cause", probeErr)
	}
	want := canonPath(dir)
	for _, ws := range list {
		if canonPath(ws.Path) == want {
			return ws
		}
	}
	log().Warn("建树后回读挑不到新树，返回最小信息", "dir", dir, "branch", branch)
	return proto.Workspace{Path: dir, Branch: branch, Managed: true}
}

n_workspace_recordNewBranchTip.signature:
// recordNewBranchTip 记录刚新建分支的尖端，作为补偿路径复核「自创建以来零提交」
// 的基线。PrepareWorkspace 的三条建分支路径（managed worktree / 用户树 / 原地）
// 共用它，避免同一段告警逻辑抄三遍。
//
// 参数：repo 为主仓库路径，branch 为刚新建的分支名
//
// 返回：取到则为 40 位 sha；取不到返回空串。
//
// 注意：取不到时返回空串是刻意的保守选择——没记到基线意味着补偿届时无从复核，
// 空串会让 decideBranchAction 判成 branchKeepNotOurs，即保留该分支不删。代价是
// 补偿时日志说不清「为什么不删」，所以失败必须在**这里**留下 WARN。
func recordNewBranchTip(ctx context.Context, repo, branch string) string {
	tip, err := BranchTip(ctx, repo, branch)
	if err != nil {
		log().Warn("新建分支后取尖端失败，补偿将保留该分支", "repo", repo, "branch", branch, "cause", err)
		return ""
	}
	return tip
}

n_workspace_refExists.signature:
// refExists 判断一个完整 ref 是否存在，不把正常的未命中写成 ERROR 日志。
func refExists(ctx context.Context, repo, ref string) bool {
	_, _, err := gitProbe(ctx, repo, "show-ref", "--verify", "--quiet", ref)
	return err == nil
}

n_workspace_rejectWorkspace.signature:
// rejectWorkspace 打参数拒绝日志并包装 ErrBadWorkspaceReq（哪个规则、哪个值）。
func rejectWorkspace(rule string, req WorkspaceReq) error {
	log().Warn("工作区参数非法，拒绝准备", "task", req.TaskID, "rule", rule, "req", req)
	return fmt.Errorf("%w: %s", ErrBadWorkspaceReq, rule)
}

n_workspace_rejectWorktree.signature:
// rejectWorktree 包一条拒绝理由，统一挂上 ErrBadWorktreeReq 并打 Warn。
func rejectWorktree(reason string, req proto.CreateWorktreeReq) error {
	log().Warn("建树被拒", "mode", req.Mode, "branch", req.Branch, "base", req.Base, "cause", reason)
	return fmt.Errorf("%w: %s", ErrBadWorktreeReq, reason)
}

n_workspace_remoteBranchCandidates.signature:
// remoteBranchCandidates 列出仓库里当前已知的同名远程跟踪分支。
// 查询失败按空列表处理：调用方仍会走原有的 commit-ish 解析并给出可操作错误。
func remoteBranchCandidates(ctx context.Context, repo, branch string) []string {
	matches, _, _ := gitRun(ctx, repo, "for-each-ref", "--format=%(refname)", "refs/remotes/*/"+branch)
	var cands []string
	for _, line := range strings.Split(matches, "\n") {
		if line = strings.TrimSpace(line); line != "" {
			cands = append(cands, line)
		}
	}
	return cands
}

n_workspace_remoteFromBranchCandidate.signature:
// remoteFromBranchCandidate 从 refs/remotes/<remote>/<branch> 中取出远端名。
// branch 可能包含斜杠，所以必须按完整 branch 后缀剥离，不能简单 strings.Split。
func remoteFromBranchCandidate(ref, branch string) string {
	const prefix = "refs/remotes/"
	suffix := "/" + branch
	if !strings.HasPrefix(ref, prefix) || !strings.HasSuffix(ref, suffix) {
		return ""
	}
	remote := strings.TrimSuffix(strings.TrimPrefix(ref, prefix), suffix)
	return remote
}

n_workspace_remoteQualifiedBase.signature:
// remoteQualifiedBase 判断 rev 是否已经明确指定了某个远端（如 origin/main）。
// 不能仅凭包含斜杠判断：feature/x 是合法的普通分支名，也必须走 D2 补拉。
func remoteQualifiedBase(ctx context.Context, repo, rev string) bool {

	if strings.HasPrefix(rev, "origin/") {
		return true
	}
	remotes, _, _ := gitRun(ctx, repo, "remote")
	for _, line := range strings.Split(remotes, "\n") {
		remote := strings.TrimSpace(line)
		if remote != "" && (rev == remote || strings.HasPrefix(rev, remote+"/")) {
			return true
		}
	}
	return false
}

n_workspace_repoDirtySnapshot.signature:
// repoDirtySnapshot 采集仓库未提交改动的快照（条数 + 文件名展示串）。
//
// 参数：
//   - ctx: 控制本次 git 调用的生命周期
//   - repo: 任务仓库路径（managed 模式下即主仓库）
//
// 返回：
//   - count: 未提交改动总数（含未跟踪文件）；干净或采集失败时为 0
//   - files: 逗号分隔的文件名串，最多 maxDirtyFilesListed 个，超出补「等 N 处」
//
// 注意：
//   - 采集失败不返回错误：这是诊断信息，不该挡住主流程（与 currentRef 同款约定），
//     失败只打 Warn 并返回零值
//   - 不区分已跟踪/未跟踪：B29 分它们是因为处置不同（拒发 vs 警告），这里两者
//     对新工作树同样不可见、处置完全一样，分了只是噪音
func repoDirtySnapshot(ctx context.Context, repo string) (count int, files string) {
	out, _, err := gitRun(ctx, repo, "status", "--porcelain")
	if err != nil {
		log().Warn("采集任务仓库脏快照失败，提示留空（不阻断派发）", "repo", repo, "cause", err)
		return 0, ""
	}
	var names []string
	for _, line := range strings.Split(strings.TrimRight(out, "\n"), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}

		name := strings.TrimSpace(line)
		if len(line) > 3 {
			name = strings.TrimSpace(line[3:])
		}
		if i := strings.LastIndex(name, " -> "); i >= 0 {
			name = name[i+4:]
		}
		names = append(names, name)
	}
	if len(names) == 0 {
		return 0, ""
	}
	shown := names
	if len(names) > maxDirtyFilesListed {
		shown = names[:maxDirtyFilesListed]
	}
	files = strings.Join(shown, ", ")
	if len(names) > len(shown) {
		files += fmt.Sprintf(" 等 %d 处", len(names))
	}

	log().Warn("任务仓库有未提交改动，新工作树不含它们",
		"repo", repo, "count", len(names), "files", strings.Join(names, ", "))
	return len(names), files
}

n_workspace_resolveCommit.signature:
// resolveCommit 把任意 commit-ish（分支名/tag/sha）解析成 40 位提交号。
//
// 参数：
//   - ctx: 控制本次 git 调用的生命周期
//   - repo: 任务仓库路径
//   - rev: 待解析的起点原文（用户的 --base 或决议出的基线）
//
// 返回：
//   - 40 位 sha；解析不出或歧义时返回包 ErrBadWorkspaceReq 的错误（server 映射 400）
//
// 为什么起点必须以 sha 形态交给 git（B76）：给分支名会触发 DWIM——base 只有
// origin/<name> 时，`worktree add -b X <dir> <base>` 会忽略显式的 -b、开出
// 名为 <base> 的分支，且退出码为 0。传 sha 让 DWIM 从原理上无从发生。
//
// 注意：^{commit} 的剥离是必需的：rev 可能是 annotated tag，裸解析给的是
// tag 对象而不是提交。rev-parse 本身不做「远程跟踪分支简写」的 DWIM，这里
// 手动补一次唯一匹配（与 git checkout 的 guess_remote 同语义），保证
// --base <只有远程跟踪 ref 的分支> 的用户语义不变；多个远端同时同名时视为
// 歧义拒发，错误文本列出全部候选 ref 并给出出路（用带远端前缀的全名或 sha）——
// 歧义不是「不存在」，把它降级成 git push 建议会把 fork 工作流的协调者引向
// 错误排查方向。
func resolveCommit(ctx context.Context, repo, rev string) (string, error) {
	out, stderr, err := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", rev+"^{commit}")
	sha := strings.TrimSpace(out)
	if err == nil && sha != "" {
		log().Info("起点已解析为提交号", "repo", repo, "base", rev, "sha", sha)
		return sha, nil
	}

	cands := remoteBranchCandidates(ctx, repo, rev)

	if len(cands) > 1 {
		log().Warn("起点解析歧义：多棵远端都有同名分支，拒绝派发",
			"repo", repo, "base", rev, "cands", cands)
		return "", ambiguousRemoteBranchError(rev, cands)
	}
	if len(cands) == 1 {
		if mout, _, e := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", cands[0]+"^{commit}"); e == nil && strings.TrimSpace(mout) != "" {
			sha = strings.TrimSpace(mout)
			log().Info("起点已解析为提交号（远程跟踪分支）", "repo", repo, "base", rev, "sha", sha, "ref", cands[0])
			return sha, nil
		}
	}
	log().Warn("起点解析失败，拒绝派发", "repo", repo, "base", rev,
		"stderr", strings.TrimSpace(truncateRunes(stderr, 300)))
	return "", fmt.Errorf("%w: 起点 %s 在任务仓库中不存在"+
		"（若它是你本地的分支，先 git push 再派发；或换一个起点）", ErrBadWorkspaceReq, rev)
}

n_workspace_resolveLocalBaseBranch.signature:
// resolveLocalBaseBranch 把工作分支名解析为本地 refs/heads 与 origin 同名跟踪
// ref 的快进并集。
//
// 参数：repo 为目标机登记的项目仓库；branch 为不带 refs/heads/ 前缀的本地分支名。
// 返回：可作为新分支起点的 SHA、是否成功探测 origin、错误。只有本地 ref 缺失
// 或两边分叉拒发；origin 缺失/不可达时保留本地尖端并成功返回。
//
// 注意：快进并集只能选择 origin 严格领先的尖端，不能移动本地工作分支 ref；
// origin 失败时回退本地。fetch 与远程 ref 读取及祖先比较共用同一仓库锁，不能
// 使用 FETCH_HEAD。
func resolveLocalBaseBranch(ctx context.Context, repo, branch string) (string, bool, error) {
	log().Info("解析本地工作分支", "repo", repo, "branch", branch, "ref", "refs/heads/"+branch)
	if branch == "" || strings.HasPrefix(branch, "-") || strings.HasPrefix(branch, "refs/") {
		log().Warn("本地工作分支名非法，拒绝派发", "repo", repo, "branch", branch)
		return "", false, fmt.Errorf("%w: local_base_branch 要求非空本地分支名 %q（只解析 refs/heads/<分支>）",
			ErrBadWorkspaceReq, branch)
	}
	ref := "refs/heads/" + branch
	if _, stderr, err := gitProbe(ctx, repo, "show-ref", "--verify", "--quiet", ref); err != nil {
		log().Warn("本地工作分支不存在，拒绝派发", "repo", repo, "branch", branch,
			"ref", ref, "stderr", truncateRunes(strings.TrimSpace(stderr), 300), "cause", err)
		return "", false, fmt.Errorf("%w: 工作分支只存在于创建它的那台机器，本地 %s 不存在；请先 push 到 origin（失败则 needs_human）。日常路径不使用 --base",
			ErrBadWorkspaceReq, ref)
	}
	out, stderr, err := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", ref+"^{commit}")
	resolved := strings.TrimSpace(out)
	if err != nil || resolved == "" {
		log().Warn("本地工作分支不存在，拒绝派发", "repo", repo, "branch", branch,
			"ref", ref, "stderr", truncateRunes(strings.TrimSpace(stderr), 300), "cause", err)
		return "", false, fmt.Errorf("%w: 工作分支只存在于创建它的那台机器，本地 %s 不存在；请先 push 到 origin（失败则 needs_human）。日常路径不使用 --base",
			ErrBadWorkspaceReq, ref)
	}
	localStart := resolved
	resolved = localStart
	fetched := false
	lockErr := withRepoFetchLock(repo, func() error {
		remoteRef := "refs/remotes/origin/" + branch
		_, fetchStderr, fetchErr := runFetchWithRetry(ctx, repo, "fetch", "origin", branch)
		if fetchErr != nil {
			log().Warn("origin 工作分支探测失败，保留本地尖端", "repo", repo, "branch", branch,
				"ref", remoteRef, "stderr", truncateRunes(strings.TrimSpace(fetchStderr), 500), "cause", fetchErr)
			return nil
		}
		out, readStderr, readErr := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", remoteRef+"^{commit}")
		originStart := strings.TrimSpace(out)
		if readErr != nil || originStart == "" {
			log().Warn("origin 工作分支跟踪 ref 不可读，保留本地尖端", "repo", repo, "branch", branch,
				"ref", remoteRef, "stderr", truncateRunes(strings.TrimSpace(readStderr), 300), "cause", readErr)
			return nil
		}
		fetched = true
		localAncestor := isAncestor(ctx, repo, localStart, originStart)
		originAncestor := isAncestor(ctx, repo, originStart, localStart)
		switch {
		case localAncestor && originAncestor:
			resolved = localStart
			log().Info("本地与 origin 工作分支相等，保留本地尖端", "repo", repo, "branch", branch,
				"start", resolved, "fetched", fetched)
		case localAncestor:
			resolved = originStart
			log().Info("origin 工作分支快进领先，使用 origin 尖端", "repo", repo, "branch", branch,
				"local_start", localStart, "origin_start", originStart, "fetched", fetched)
		case originAncestor:
			resolved = localStart
			log().Info("本地工作分支领先 origin，保留本地尖端", "repo", repo, "branch", branch,
				"local_start", localStart, "origin_start", originStart, "fetched", fetched)
		default:
			log().Warn("本地与 origin 工作分支已分叉，拒绝派发", "repo", repo, "branch", branch,
				"local_start", localStart, "origin_start", originStart)
			return fmt.Errorf("%w：本地=%s，origin=%s", ErrLocalBaseBranchDiverged, localStart, originStart)
		}
		return nil
	})
	if lockErr != nil {
		return "", fetched, lockErr
	}
	log().Info("本地工作分支解析完成", "repo", repo, "branch", branch, "ref", ref, "start", resolved,
		"fetched", fetched)
	return resolved, fetched, nil
}

n_workspace_resolveRemoteBaseBranch.signature:
// ResolveBaseBranch 把基线**分支名**解析成完整 sha，起点取指定远端上的那一份。
//
// 参数：repo 任务仓库路径；remote 持有该分支的远端名；branch 基线分支名。
// 返回：remote/<branch> 的完整 sha；分支在远端上不存在或 fetch 失败时报错。
//
// 与 ResolveBaseline（提交路径）唯一的、也是必须的不同：**无条件 fetch**。
// 提交路径是「本地没有才拉」，因为 commit sha 在本地要么有要么没有，是可靠
// 信号；而分支名在本地永远解析得到——那正是陈旧的那一份。拿「解析得到」当
// 「不用拉」的信号，会让「执行机镜像陈旧导致起点错」这个 bug 永远不触发
// 修复路径。无本地同名 heads 且发现多棵远端同名 ref 时，仍在 fetch 前拒发。
func resolveRemoteBaseBranch(ctx context.Context, repo, remote, branch string) (string, error) {
	localHead := refExists(ctx, repo, "refs/heads/"+branch)
	if !localHead {
		if cands := remoteBranchCandidates(ctx, repo, branch); len(cands) > 1 {
			log().Warn("基线分支解析歧义：补拉前发现多棵远端同名分支，拒绝派发",
				"repo", repo, "branch", branch, "cands", cands)
			return "", ambiguousRemoteBranchError(branch, cands)
		}
	}
	log().Info("解析基线分支，补拉远端", "repo", repo, "remote", remote, "branch", branch, "timeout", FetchTimeout)
	var sha string
	err := withRepoFetchLock(repo, func() error {
		_, fetchStderr, fetchErr := runFetchWithRetry(ctx, repo, "fetch", remote, branch)
		if fetchErr != nil {
			if errors.Is(fetchErr, ErrFetchRefLockContention) {
				log().Error("基线分支补拉因远端 ref 锁竞争耗尽", "repo", repo, "remote", remote,
					"branch", branch, "stderr", truncateRunes(strings.TrimSpace(fetchStderr), 500), "cause", fetchErr)
				return fetchErr
			}
			log().Error("基线分支补拉失败", "repo", repo, "remote", remote, "branch", branch,
				"stderr", truncateRunes(strings.TrimSpace(fetchStderr), 500), "cause", fetchErr)
			return fmt.Errorf("%w: 基线分支 %q 从远端 %q 补拉失败（fetch 输出：%s）",
				ErrBaseCommitMissing, branch, remote, strings.TrimSpace(truncateRunes(fetchStderr, 300)))
		}
		remoteRef := "refs/remotes/" + remote + "/" + branch
		out, readStderr, readErr := gitProbe(ctx, repo, "rev-parse", "--verify", "--quiet", remoteRef+"^{commit}")
		sha = strings.TrimSpace(out)
		if readErr != nil || sha == "" {
			log().Warn("基线分支目标远端 ref 读取失败", "repo", repo, "remote", remote,
				"branch", branch, "ref", remoteRef, "stderr", truncateRunes(strings.TrimSpace(readStderr), 300),
				"cause", readErr)
			return fmt.Errorf("%w: 基线分支 %q 在远端 %q 上不存在（目标 ref %s；fetch 输出：%s）",
				ErrBaseCommitMissing, branch, remote, remoteRef, strings.TrimSpace(truncateRunes(readStderr, 300)))
		}
		log().Info("基线分支解析完成", "repo", repo, "remote", remote, "branch", branch,
			"ref", remoteRef, "start", sha)
		return nil
	})
	if err != nil {
		return "", err
	}
	return sha, nil
}

n_workspace_rollbackWorkspace.signature:
// rollbackWorkspace 在 PrepareWorkspace 内部失败时回滚已建的工作区。
//
// 为什么不能交给 manager 的补偿 defer：那个 defer 用的是 PrepareWorkspace 的
// **返回值** ws，失败时它是零值，WorkDir 为空，compensateWorkspace 会直接返回。
// 所以 PrepareWorkspace 自己建的东西必须自己收。
func rollbackWorkspace(ctx context.Context, repo string, ws Workspace) {
	if ws.WorkDir == "" {
		return
	}
	if ws.Managed {
		if err := RemoveManagedWorktree(ctx, repo, ws.WorkDir); err != nil {
			log().Error("回滚 managed worktree 失败，需人工清理", "repo", repo,
				"workdir", ws.WorkDir, "cause", err)
			return
		}
		log().Info("已回滚 managed worktree", "repo", repo, "workdir", ws.WorkDir)
		return
	}
	if ws.PrevRef == "" {
		log().Warn("无 PrevRef 可复原，工作区停在当前 ref", "workdir", ws.WorkDir)
		return
	}
	if _, stderr, err := gitRun(ctx, ws.WorkDir, "checkout", ws.PrevRef); err != nil {
		log().Error("回滚切回原 ref 失败，需人工处理", "workdir", ws.WorkDir,
			"prev_ref", ws.PrevRef, "stderr", strings.TrimSpace(stderr), "cause", err)
		return
	}
	log().Info("已回滚至原 ref", "workdir", ws.WorkDir, "prev_ref", ws.PrevRef)
}

n_workspace_rootErrIsEscape.signature:
// rootErrIsEscape 判断 os.Root 返回的路径错误是否为「逃逸出根目录」。
//
// os.Root 对越界解析统一报内部私有错误（文本 "path escapes from parent"，见
// go/src/os/root.go 的 errPathEscapes），stdlib 未导出哨兵，无法 errors.Is，只能
// 按错误文本识别。该文本自 Go 1.24 引入 os.Root 以来未变，且 TestReadFileEscapeRejected
// 与 TestReadFileSymlinkEscape 全量断言「逃逸 → ErrPathEscape」——文本一旦变化，
// 测试立刻失败提示本函数需要同步。
func rootErrIsEscape(err error) bool {
	return err != nil && strings.Contains(err.Error(), "path escapes from parent")
}

n_workspace_runFetchWithRetry.signature:
// runFetchWithRetry 在一个 FetchTimeout 总截止时间内执行 fetch，最多重试两次
// ref 锁竞争。返回值保留最后一次 fetch 的原始 stdout/stderr，供缺失与锁竞争
// 两条错误分支给协调者定位。
func runFetchWithRetry(ctx context.Context, repo string, args ...string) (stdout, stderr string, err error) {
	fctx, cancel := context.WithTimeout(ctx, FetchTimeout)
	defer cancel()

	const maxAttempts = 3
	const retryDelay = 100 * time.Millisecond
	var lastErr error
	for attempt := 1; attempt <= maxAttempts; attempt++ {
		started := time.Now()
		log().Info("开始基线 fetch", "repo", repo, "args", args, "attempt", attempt, "of", maxAttempts)
		stdout, stderr, lastErr = runNetFetch(fctx, repo, args...)
		log().Info("基线 fetch 完成", "repo", repo, "args", args, "attempt", attempt,
			"elapsed_ms", time.Since(started).Milliseconds(), "stderr", truncateRunes(strings.TrimSpace(stderr), 500),
			"cause", lastErr)
		if lastErr == nil {
			return stdout, stderr, nil
		}
		if !isFetchRefLockFailure(stderr) || attempt == maxAttempts {
			break
		}
		select {
		case <-fctx.Done():
			lastErr = fctx.Err()
			attempt = maxAttempts
		case <-time.After(retryDelay):
		}
	}
	if isFetchRefLockFailure(stderr) {
		return stdout, stderr, fmt.Errorf("%w：fetch %v 重试耗尽（最后一次输出：%s）",
			ErrFetchRefLockContention, args, strings.TrimSpace(stderr))
	}
	return stdout, stderr, lastErr
}

n_workspace_runOutputBuffer_Write.signature:
func (b *runOutputBuffer) Write(p []byte) (int, error) {
	b.total += int64(len(p))
	if room := b.limit - b.buf.Len(); room > 0 {
		if len(p) > room {
			b.buf.Write(p[:room])
			b.capped = true
		} else {
			b.buf.Write(p)
		}
	} else {
		b.capped = true
	}

	return len(p), nil
}

n_workspace_shortHash.signature:
// shortHash 取哈希前 8 位供日志用。全量 64 位十六进制串在日志里既占地方又没人读，
// 而排障时要的只是「这两个是不是同一个」。
func shortHash(h string) string {
	if len(h) <= 8 {
		return h
	}
	return h[:8]
}

n_workspace_statEntry.signature:
// statEntry 从工作树现取一条目的 proto.DirEntry（Name/IsDir/Size 取自磁盘实况）。
//
// 为什么不凭入参拼：name 入参只保证「未逃逸」，磁盘实况才是建/改名后的事实
// 来源（如目录 size 恒 0，见 proto.DirEntry 的文档约定）。
func statEntry(root *os.Root, repo, target string) (proto.DirEntry, error) {
	fi, err := root.Stat(target)
	if err != nil {
		return proto.DirEntry{}, fmt.Errorf("读取条目 %s: %w", filepath.Join(repo, target), err)
	}
	e := proto.DirEntry{Name: fi.Name(), IsDir: fi.IsDir()}
	if !fi.IsDir() {
		e.Size = fi.Size()
	}
	return e, nil
}

n_workspace_statFile.signature:
// statFile 是 ResolveRunShell 的生产存在性判据。
func statFile(p string) error {
	_, err := os.Stat(p)
	return err
}

n_workspace_truncateRunes.signature:
// truncateRunes 将字符串截断为最多 n 个字符（按 rune 截断，避免切断多字节 UTF-8）。
// 与 agentd 侧同名助手各自保留一份（一行助手，不跨包导出）。
func truncateRunes(s string, n int) string {
	r := []rune(s)
	if len(r) <= n {
		return s
	}
	return string(r[:n])
}

n_workspace_underRoot.signature:
// underRoot 判断 path 是否落在 root 目录下（含 root 自身的子目录）。
//
// 为什么不用 strings.HasPrefix 裸比：/a/worktrees-old 会被 /a/worktrees 误判为
// 子目录。走 filepath.Rel 再看有没有 ".." 才是准的。
//
// 为什么先解析符号链接：git 的 porcelain 输出会解析路径里的符号链接
// （macOS 上 /var → /private/var 是实景），而 managedRoot 是配置里的原样路径，
// 两者不归一，真实机器上的 managed 判定会恒为 false。EvalSymlinks 对不存在的
// 路径失败（porcelain 测试里的虚构路径），此时退回词汇级比较。
func underRoot(path, root string) bool {
	if root == "" {
		return false
	}
	cleanPath := filepath.Clean(path)
	cleanRoot := filepath.Clean(root)
	if rp, err := filepath.EvalSymlinks(cleanPath); err == nil {
		cleanPath = rp
	}
	if rr, err := filepath.EvalSymlinks(cleanRoot); err == nil {
		cleanRoot = rr
	}
	rel, err := filepath.Rel(cleanRoot, cleanPath)
	if err != nil {
		return false
	}
	return rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator))
}

n_workspace_validateEntryName.signature:
// validateEntryName 校验新条目名：空、.、..、含 / 或 \、含 NUL 字节一律
// ErrBadEntryName（单层名，本期不做跨目录操作）。
func validateEntryName(repo, name string) error {
	if name == "" || name == "." || name == ".." || strings.ContainsAny(name, `/\`) ||
		strings.ContainsRune(name, 0) {
		log().Warn("条目名字不合法被拒绝", "repo", repo, "name", name)
		return fmt.Errorf("%w: %q", ErrBadEntryName, name)
	}
	return nil
}

n_workspace_verifyBranchIdentity.signature:
// verifyBranchIdentity 核对工作区实际所在分支是否就是决议出的分支。
//
// 参数：
//   - ctx: 控制本次 git 调用的生命周期
//   - workDir: 已建好的工作区目录
//   - want: 第 2 层决议出的分支名
//
// 返回：不符或读取失败时返回包 ErrBranchIdentityMismatch 的错误，文本同时
// 含请求分支与实到分支。
//
// 为什么需要这道核对：git 的退出码只说明「命令没报错」，不说明「它做了你要
// 的事」。B76 里 `worktree add -b X <dir> <base>` 在 base 只有远程跟踪 ref 时
// 被 DWIM 顶替成「检出 base」，丢掉 X 且退出码为 0——要的分支与实到分支从来
// 没被比对过，这是结构性空白，不是某一次 git 行为的补丁。
func verifyBranchIdentity(ctx context.Context, workDir, want string) error {
	out, stderr, err := gitRun(ctx, workDir, "branch", "--show-current")
	got := strings.TrimSpace(out)
	if err != nil {
		return fmt.Errorf("%w: 读取工作区 %s 的当前分支失败（请求分支 %s）: %s",
			ErrBranchIdentityMismatch, workDir, want, strings.TrimSpace(stderr))
	}
	if got != want {
		return fmt.Errorf("%w: 请求分支 %s，git 实际给出 %s（工作区 %s）",
			ErrBranchIdentityMismatch, want, got, workDir)
	}
	return nil
}

n_workspace_widenEmptyRange.signature:
// widenEmptyRange 在提交区间为空时给出一个**一定能造出包**的替代区间。
//
// 参数：repo 任务主仓库；branch 任务分支名
//
// 返回：可直接交给 git bundle create 的 rev 区间；分支 tip 是根提交时返回 branch
// 本身（全量包）。
//
// 为什么不能就此返回「无需生成」：客户端要的不只是对象，还有**包里那个 ref**。
// 本地分支引用是 `git fetch <分支>:<分支>` 的副产品，不是「有新提交」的副产品——
// ssh 老路无条件 fetch 所以 ref 总会建出来；bundle 路径若在这里短路，客户端就会
// 拿到一句「已是最新」而手上根本没有那个分支（B143 真机验收实测）。
//
// 为什么是放宽区间而不是「让客户端自己建 ref」：后者要新增一个协议头、一块客户端
// 逻辑，还要本设计自己发明一条「本地 ref 指向别处怎么办」的策略——而 git 的 fetch
// 语义本来就有答案（非快进即失败），ssh 老路一直照此行事。放宽区间让 fetch 该怎样
// 就怎样，代价只是多传一个提交的对象（几百字节），而客户端已有这些对象、fetch 是
// 无操作。
func widenEmptyRange(ctx context.Context, repo, branch string) (string, error) {

	if _, _, err := gitProbe(ctx, repo, "rev-parse", "--verify", branch+"~1"); err == nil {
		widened := branch + "~1.." + branch
		log().Info("bundle 区间为空，放宽一格以保证包内含 ref",
			"repo", repo, "branch", branch, "range", widened)
		return widened, nil
	}

	log().Info("bundle 区间为空且分支 tip 是根提交，退回全量包",
		"repo", repo, "branch", branch)
	return branch, nil
}

n_workspace_withRepoFetchLock.signature:
// withRepoFetchLock 串行化同一仓库的出网 fetch 及其紧随的目标 ref 读取。
//
// 参数：repo 为任务仓库路径；fn 必须把 fetch 和读取本次目标 ref 的完整序列
// 放在闭包中。锁键使用 filepath.Clean(repo)，不同仓库仍可并发；clone 不经过
// 此函数，因此不会被基线 fetch 拖住。
func withRepoFetchLock(repo string, fn func() error) error {
	key := filepath.Clean(repo)
	repoFetchLocksMu.Lock()
	lock := repoFetchLocks[key]
	if lock == nil {
		lock = &sync.Mutex{}
		repoFetchLocks[key] = lock
	}
	repoFetchLocksMu.Unlock()

	log().Debug("等待仓库 fetch 锁", "repo", repo, "lock_key", key)
	lock.Lock()
	defer lock.Unlock()
	log().Debug("取得仓库 fetch 锁", "repo", repo, "lock_key", key)
	if err := fn(); err != nil {
		log().Warn("仓库 fetch 锁内操作失败", "repo", repo, "lock_key", key, "cause", err)
		return err
	}
	log().Debug("释放仓库 fetch 锁", "repo", repo, "lock_key", key)
	return nil
}

n_workspace_workspaceCreatedAt.signature:
// workspaceCreatedAt 取一个工作树的创建时间；取不到返回零值。
//
// 参数：
//   - path: 工作树根的绝对路径
//   - isMain: 是否主工作树（决定去哪个文件上问）
//
// 返回：创建时间；取不到（含主工作树，见下）返回零值，**不返回 error**——
// 调用方要的是一个可展示的字段，不是一个能让整棵树 500 的错误。
//
// 链接工作树看 <公共目录>/worktrees/<名>/gitdir：git worktree add 写一次就不再动，
// 是唯一稳定的创建时间证据。刻意不 stat 工作树目录本身——它的 mtime 会随着往里
// 写代码变化，那是「最近动过」不是「什么时候建的」。
//
// **主工作树一律返回零值**，因为拿不到可信的创建时间：
//   - `.git` 目录的 mtime 不是创建时间，而是「最后一次在里面增删条目」的时间。
//     git 一直在干这事（FETCH_HEAD、新 ref、packed-refs、worktrees/ 下增删），
//     实测一个 08-07 建的仓库报出 08-18——差 11 天。
//   - 文件系统的 birthtime 才是准的，但 Go 标准库不给，要按平台走 syscall
//     （darwin 有 Birthtimespec，Linux 得 statx）。
//
// 零值在这里不是缺陷而是诚实：排序把主工作树**钉在第一位、不参与比较**
// （见 web 侧 sortWorkspaces），metricsOf 对它根本不会被调用，所以这个值
// 没有消费者。与其报一个自信的错值，不如如实说「不知道」。真需要时再上
// 平台相关的 birthtime，那时它有真实依据。
func workspaceCreatedAt(path string, isMain bool) time.Time {
	if isMain {
		return time.Time{}
	}
	dotGit := filepath.Join(path, ".git")
	fi, err := os.Stat(dotGit)
	if err != nil {

		log().Debug("取工作树创建时间失败，留零值", "path", path, "cause", err)
		return time.Time{}
	}

	if fi.IsDir() {

		log().Debug("工作树的 .git 是目录而非指针文件，无稳定创建时间可取，留零值", "path", path)
		return time.Time{}
	}
	data, err := os.ReadFile(dotGit)
	if err != nil {
		log().Debug("读工作树 .git 指针失败，留零值", "path", path, "cause", err)
		return time.Time{}
	}
	adminDir := strings.TrimSpace(strings.TrimPrefix(strings.TrimSpace(string(data)), "gitdir:"))
	if adminDir == "" {
		log().Debug("工作树 .git 指针为空，留零值", "path", path)
		return time.Time{}
	}
	gi, err := os.Stat(filepath.Join(adminDir, "gitdir"))
	if err != nil {
		log().Debug("取工作树管理目录时间失败，留零值", "path", path, "admin_dir", adminDir, "cause", err)
		return time.Time{}
	}
	return gi.ModTime()
}

n_workspace_worktreeBelongsToRepo.signature:
// worktreeBelongsToRepo 校验 worktree 路径是否属于主仓库 repo。
//
// 两道校验：
//  1. git-common-dir 比对：对 main 仓库与它的任一 worktree 返回同一 git 目录，
//     路径经 EvalSymlinks 归一后相等即归属成立——证明入参「在同一个仓库里」
//  2. show-toplevel 必须等于入参（经 EvalSymlinks 归一）：git-common-dir 会
//     向上查找，/repo/internal/sub 与主仓返回同一 git 目录，只有第二道才证明
//     「入参就是这棵工作树的根」——缺它，仓库子目录会被当成合法 worktree，
//     实际改的是主仓 HEAD、审阅面也被收窄到那个子目录
//
// 任一步失败（路径不是 git 仓库/不是本仓 worktree/不是工作树根）都返回 false
// （fail-closed）。ctx 控制本次 git 调用的生命周期。
func worktreeBelongsToRepo(ctx context.Context, repo, worktree string) bool {
	repoDir, _, err := gitRun(ctx, repo, "rev-parse", "--path-format=absolute", "--git-common-dir")
	if err != nil {
		return false
	}
	wtDir, _, err := gitRun(ctx, worktree, "rev-parse", "--path-format=absolute", "--git-common-dir")
	if err != nil {
		return false
	}
	rp, err1 := filepath.EvalSymlinks(strings.TrimSpace(repoDir))
	wp, err2 := filepath.EvalSymlinks(strings.TrimSpace(wtDir))
	if err1 != nil || err2 != nil {
		return false
	}
	if rp != wp {
		return false
	}

	top, _, err := gitRun(ctx, worktree, "rev-parse", "--show-toplevel")
	if err != nil {
		return false
	}
	tp, err3 := filepath.EvalSymlinks(strings.TrimSpace(top))
	ap, err4 := filepath.EvalSymlinks(worktree)
	if err3 != nil || err4 != nil {
		return false
	}
	if tp != ap {
		log().Warn("worktree 校验失败：路径不是工作树根（疑似传了仓库子目录）",
			"repo", repo, "worktree", worktree, "toplevel", tp)
		return false
	}
	return true
}
